INSERT INTO characters (char, data) VALUES ('祆', '{"9000": "6002.0", "Chữ Trung Quốc": "祆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 8 | nét | 礻 | thị | biểu nghĩa | thần linh, tín ngưỡng | 天 | thiên | biểu âm | trời, thiên đường | 祆 = 礻(Thị, biểu nghĩa: thần/tín ngưỡng) + 天 (Thiên, biểu âm: trời). Theo Wiktionary là chữ hội ý kết hợp hình thanh (ic + psc): thần linh (礻) của thiên đàng (天). Chữ chỉ đặc biệt thần Ahura Mazda của đạo Zoroaster (đạo thờ lửa).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiên\" (thần lửa): 礻 (thần) + 天 (trời) — vị thần trên thiên đàng của đạo Zoroaster, thờ phụng ánh sáng và lửa thiêng. | Gương Hán-Việt | tiên trong \"Tiên giáo\" (祆教) — đạo Zoroaster, đạo thờ lửa Ba Tư | Mở khoá kiến thức | Biết 祆 giúp đọc hiểu các văn bản về Phật giáo và tôn giáo ngoại lai du nhập Trung Hoa qua Con đường Tơ Lụa.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary: 祆 = 示/礻 (thần, tín ngưỡng) + 天 (trời). Chữ dùng riêng để chỉ thần Ormazd/Ahura Mazda của đạo Zoroaster (Bái Hỏa Giáo) du nhập vào Trung Hoa qua Con đường Tơ Lụa. Về sau mở rộng để chỉ thần của giáo phái Manichaean. Chữ tạo có mục đích phiên dịch văn hóa. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một tôn giáo thờ thần lửa thời xưa", "Hạng Tần Suất (Jun Da)": "6002.0", "Tần Suất % (Jun Da)": "99.9821223351", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 天", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻天", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "天", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "祆", "Unihan_Traditional (Chữ Phồn thể)": "祆", "Pinyin_Xie": "xiān", "Âm Hán Việt_Xie": "hiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường kết hợp với chữ giáo tạo thành tiên giáo để chỉ đạo thờ lửa cổ xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('伛', '{"9000": "6003.0", "Chữ Trung Quốc": "伛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 6 | nét | 伛 | ủ | tượng hình | người gù lưng, khom người | 伛 thuộc bộ 亻(nhân, người), là dạng giản thể của 傴. Wiktionary không cung cấp phân tích thành phần hình thanh cho chữ này, chỉ ghi nhận là chữ đồng nghĩa với dạng phồn thể 傴. Cấu trúc tự hình chưa rõ. Có đại triện và tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ủ\" (gù lưng): bộ 亻 (người) — người cong lưng, ủ rũ, khom xuống như không gánh nổi sức nặng cuộc đời. | Gương Hán-Việt | ủ trong \"ủ lũ\" (傴僂/伛偻) — gù lưng, còm cõi | Mở khoá kiến thức | Biết 伛 giúp đọc hiểu tổ hợp 傴僂 (ủ lũ) trong văn học cổ miêu tả người già yếu, gù lưng.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 伛 là dạng giản của 傴 (âm yǔ), Wiktionary ghi nhận nghĩa: gù lưng, khom người xuống. Bộ 亻 (người) cho thấy liên quan đến dáng người. Chữ có đại triện và tiểu triện nhưng Wiktionary không phân tích hình thanh/hội ý rõ ràng. Chưa có nguồn học thuật về tự nguyên cụ thể. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: ủ lũ 傴僂,伛偻)", "Hạng Tần Suất (Jun Da)": "6003.0", "Tần Suất % (Jun Da)": "99.9821502414", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 区", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻区", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "区", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "伛", "Unihan_Traditional (Chữ Phồn thể)": "傴", "Pinyin_Xie": "yǔ", "Âm Hán Việt_Xie": "ủ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này thường làm tính từ miêu tả tư thế lưng còng hoặc làm động từ chỉ hành động khom lưng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲥', '{"9000": "6004.0", "Chữ Trung Quốc": "鲥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 15 | nét | 鲥 | thì | tượng hình | cá cháy, loài cá di cư theo mùa | 鲥 thuộc bộ 魚 (ngư, cá), là dạng giản thể của 鰣. Wiktionary chỉ ghi {{Han etym}} không có phân tích thành phần. Chữ tạo để chỉ loài cá Ilisha elongata (cá cháy/shad), nổi tiếng là loài cá chỉ xuất hiện theo mùa nhất định.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thì\" (cá cháy): bộ 魚 (cá) + âm 時 (thời gian) — loài cá chỉ xuất hiện đúng theo mùa, như khách đến đúng giờ, không đến trước cũng không đến sau. | Gương Hán-Việt | thì trong \"thì ngư\" (鲥鱼) — cá cháy, loại cá quý hiếm theo mùa | Mở khoá kiến thức | Biết 鲥 giúp đọc hiểu văn chương ẩm thực cổ điển Trung Hoa và các bài thơ về món ăn cung đình.", "Tự nguyên_Xie": "鲥 (dạng giản của 鰣) chỉ loài cá cháy (Ilisha elongata/shad), nổi tiếng trong ẩm thực cung đình Trung Hoa xưa. Tên cá gắn với chữ 時 (thì/thời gian) vì loài này chỉ xuất hiện theo mùa di cư nhất định. Bộ 魚 biểu nghĩa cá. Wiktionary không cung cấp phân tích hội ý hay hình thanh cụ thể. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá cháy", "Hạng Tần Suất (Jun Da)": "6004.0", "Tần Suất % (Jun Da)": "99.9821781478", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 时", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼时", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "时", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲥", "Unihan_Traditional (Chữ Phồn thể)": "鰣", "Pinyin_Xie": "shí", "Âm Hán Việt_Xie": "thì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài cá xương nước lợ thường di cư. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('荦', '{"9000": "6005.0", "Chữ Trung Quốc": "荦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 荦 | lạc | tượng hình | trâu loang lổ nhiều màu; rõ ràng, hiển nhiên | 荦 là dạng giản của 犖. Wiktionary không phân tích thành phần hình thanh/hội ý rõ ràng. Chữ có tiểu triện và lục thư thông, có nghĩa gốc là con bò/trâu có lông loang lổ nhiều màu, nghĩa mở rộng là hiển nhiên, rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lạc\" (loang lổ): con trâu có bộ lông nhiều màu loang lổ, dễ nhận ra từ xa — từ đó mang nghĩa rõ ràng, hiển nhiên, nổi bật. | Gương Hán-Việt | lạc trong \"trác lạc\" (卓犖) — xuất sắc, nổi bật rõ ràng | Mở khoá kiến thức | Biết 荦 giúp đọc hiểu tổ hợp 犖犖 và 卓犖 trong văn học cổ điển Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 荦 (dạng giản của 犖, âm luò) theo Wiktionary có nghĩa: bò loang lổ nhiều màu; hiển nhiên; nổi bật. Từ ghép 犖犖 (lạc lạc) nghĩa là rõ ràng, hiển nhiên. Wiktionary không cung cấp phân tích hình thanh/hội ý cụ thể. Chữ có lịch sử dùng trong văn học cổ điển. Chưa có nguồn học thuật về tự nguyên. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trâu có nhiều sắc loang lổ; rành rọt, rõ ràng", "Hạng Tần Suất (Jun Da)": "6005.0", "Tần Suất % (Jun Da)": "99.9822060542", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "荦", "Unihan_Traditional (Chữ Phồn thể)": "犖", "Pinyin_Xie": "luò", "Âm Hán Việt_Xie": "lạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường dùng làm tính từ trong các từ ghép để chỉ sự rõ ràng, rành mạch. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('暾', '{"9000": "6006.0", "Chữ Trung Quốc": "暾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 16 | nét | 暾 | đôn | tượng hình | mặt trời mới mọc, ánh bình minh | 暾 thuộc bộ 日 (nhật, mặt trời). Wiktionary cung cấp phát âm và định nghĩa nhưng không phân tích thành phần hình thanh/hội ý. Chữ chỉ riêng hình ảnh mặt trời vừa mọc lên khỏi đường chân trời — khoảnh khắc bình minh đẹp nhất trong ngày.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đôn\" (bình minh): bộ 日 (mặt trời) — khoảnh khắc mặt trời đôn lên, vừa xuất hiện trên đường chân trời trong ánh sáng hồng rực ban mai. | Gương Hán-Việt | đôn trong \"triêu đôn\" (朝暾) — ánh sáng mặt trời buổi sáng sớm | Mở khoá kiến thức | Biết 暾 giúp đọc hiểu thơ văn cổ điển miêu tả cảnh bình minh và thiên nhiên buổi sáng.", "Tự nguyên_Xie": "暾 (âm tūn) theo Wiktionary: mặt trời mới mọc; bình minh; mặt trời vừa vượt qua đường chân trời. Từ ghép 朝暾 (triêu đôn) là ánh bình minh. Bộ 日 biểu nghĩa mặt trời. Wiktionary không phân tích thành phần hình thanh cụ thể. Chưa có nguồn học thuật về tự nguyên. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mặt trời mới mọc", "Hạng Tần Suất (Jun Da)": "6006.0", "Tần Suất % (Jun Da)": "99.9822339606", "GavinGrover_Once (Chiết tự trực tiếp)": "日 + 敦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰日敦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "暾", "Unihan_Traditional (Chữ Phồn thể)": "暾", "Pinyin_Xie": "tūn", "Âm Hán Việt_Xie": "thôn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ vầng thái dương lúc sáng sớm hoặc ánh nắng ban mai. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缌', '{"9000": "6007.0", "Chữ Trung Quốc": "缌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 12 | nét | 缌 | ti | tượng hình | vải gai mịn dùng trong tang lễ | 缌 là dạng giản của 緦, thuộc bộ 糸 (mịch, sợi/vải). Wiktionary mô tả là vải gai mịn dùng làm áo tang. Không có phân tích thành phần hình thanh/hội ý cụ thể trong Wiktionary. Có tiểu triện và lục thư thông.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ti\" (vải tang): bộ 糸 (sợi/vải) — loại vải gai mịn nhẹ nhất trong ngũ phục tang lễ cổ Trung Hoa, dùng khi để tang người thân xa. | Gương Hán-Việt | ti trong \"ti ma\" (緦麻) — loại vải tang nhẹ nhất trong hệ thống ngũ phục | Mở khoá kiến thức | Biết 缌 giúp đọc hiểu hệ thống tang phục (ngũ phục 五服) trong văn hóa và lễ nghi cổ Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 缌 (dạng giản của 緦, âm sī) theo Wiktionary: vải gai mịn thường dùng làm áo tang trong nghi lễ để tang Trung Hoa cổ đại. Tổ hợp 緦麻 (ti ma) chỉ loại vải tang nhẹ nhất trong ngũ phục (hệ thống tang phục theo mức độ thân thích). Bộ 糸 biểu nghĩa liên quan đến sợi/vải. Chưa có nguồn học thuật về tự nguyên. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vải gai mịn", "Hạng Tần Suất (Jun Da)": "6007.0", "Tần Suất % (Jun Da)": "99.982317163", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 思", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟思", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "思", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "缌", "Unihan_Traditional (Chữ Phồn thể)": "緦", "Pinyin_Xie": "sī", "Âm Hán Việt_Xie": "ti", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loại vải gai mịn thời xưa hoặc tang phục làm từ loại vải này. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('飏', '{"9000": "6008.0", "Chữ Trung Quốc": "飏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 風 | Số nét | 7 | nét | 飏 | dương | tượng hình | bay lên, gió tốc, tung lên | 飏 là dạng giản thể của 颺, theo Wiktionary đây là chữ giản hóa từ 颺 với 風 thay bằng 风, 昜 thay bằng 𠃓. Chữ gốc 颺 có bộ phong (gió) + phần âm. Có tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dương\" (bay trong gió): bộ 風 (gió) — như cánh cờ dương lên, tung bay trong gió, phiêu du tự tại. | Gương Hán-Việt | dương trong \"phi dương\" (飛飏) — bay lên, tung lên trong gió | Mở khoá kiến thức | Biết 飏 giúp đọc hiểu thơ văn cổ miêu tả cảnh gió thổi, vật bay lên, tự do phiêu bổng.", "Tự nguyên_Xie": "Tiểu triện | 飏 là dạng giản của 颺 (âm yáng). Theo Wiktionary: giản hóa bộ 風 thành 风. Chữ gốc 颺 chỉ việc gió thổi tung, bay lên, bay đi trong gió. Bộ 風 biểu nghĩa liên quan đến gió. Chữ có tiểu triện. Wiktionary không phân tích hình thanh/hội ý riêng cho 飏. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gió tốc lên, bay đi", "Hạng Tần Suất (Jun Da)": "6008.0", "Tần Suất % (Jun Da)": "99.9823445527", "GavinGrover_Once (Chiết tự trực tiếp)": "风 + 𠃓", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴风𠃓", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𠃓", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "风", "Unihan_Simplified (Chữ Giản thể)": "飏", "Unihan_Traditional (Chữ Phồn thể)": "颺", "Pinyin_Xie": "yáng", "Âm Hán Việt_Xie": "dương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động bay lượn hoặc bị gió thổi tung lên. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锞', '{"9000": "6009.0", "Chữ Trung Quốc": "锞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 13 | nét | 金 | kim | biểu nghĩa | vàng, kim loại | 果 | quả | biểu âm | quả, kết quả | 锞 = 金 (Kim, biểu nghĩa: vàng/kim loại) + 果 (Quả, biểu âm). Chữ hình thanh (psc): bộ 金 cho thấy liên quan đến kim loại quý, 果 cho âm kè/guǒ. Nghĩa là thoi vàng hoặc thoi bạc nhỏ, đơn vị tiền tệ cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khỏa\" (thoi vàng): 金 (vàng) + 果 (âm) — miếng vàng/bạc đúc thành hình thoi như trái cây, dùng làm tiền tệ cổ đại. | Gương Hán-Việt | khỏa trong \"kim khỏa\" — thoi vàng, miếng vàng đúc | Mở khoá kiến thức | Biết 锞 giúp đọc hiểu các văn bản về tiền tệ cổ Trung Hoa, đặc biệt trong văn học đời Minh-Thanh như Hồng Lâu Mộng.", "Tự nguyên_Xie": "Theo Wiktionary: 锞 (dạng giản của 錁) = 金 (vàng/kim loại, biểu nghĩa) + 果 (biểu âm). Chữ hình thanh chỉ thoi vàng hoặc thoi bạc nhỏ — đơn vị tiền tệ dạng thỏi trong lịch sử Trung Hoa. Tìm thấy trong từ điển Tập Vận thời Tống (1037 AD). Chữ có hai âm đọc: kè (thỏi vàng) và guǒ (hũ mỡ tra vào xe). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thoi vàng, thoi bạc; mỡ tra vào xe", "Hạng Tần Suất (Jun Da)": "6009.0", "Tần Suất % (Jun Da)": "99.9823719423", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 果", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅果", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "果", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锞", "Unihan_Traditional (Chữ Phồn thể)": "錁", "Pinyin_Xie": "kè", "Âm Hán Việt_Xie": "quả", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các thoi hoặc nén vàng bạc dùng làm tiền tệ thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('趵', '{"9000": "6010.0", "Chữ Trung Quốc": "趵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 10 | nét | 趵 | bác | tượng hình | giậm chân, nước phun lên | 趵 thuộc bộ 足 (túc, chân), Wiktionary cung cấp hai âm đọc: bào (nước suối phun lên) và bō (đá chân). Không có phân tích thành phần hình thanh/hội ý rõ ràng. Chữ nổi tiếng qua địa danh 趵突泉 (suối Báo Đột ở Tế Nam).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bác\" (phun vọt): bộ 足 (chân) — bước chân giậm mạnh khiến nước phun vọt lên, hình ảnh của suối 趵突泉 nổi tiếng ở Tế Nam phun nước không ngừng. | Gương Hán-Việt | bác trong \"bác đột tuyền\" (趵突泉) — suối nước phun nổi tiếng ở Tế Nam | Mở khoá kiến thức | Biết 趵 giúp nhận ra địa danh 趵突泉 và các từ chỉ nước phun trong văn học cổ điển và địa danh học Trung Quốc.", "Tự nguyên_Xie": "趵 (âm bào/bō) theo Wiktionary: âm bào nghĩa là nước ngầm phun lên, nhảy vọt (phương ngữ); âm bō nghĩa là đá/giậm chân (văn cổ). Bộ 足 biểu nghĩa liên quan đến chân hoặc chuyển động từ dưới lên. Chữ nổi tiếng qua 趵突泉 — suối nước nóng nổi tiếng ở Tế Nam, Sơn Đông. Chưa có nguồn học thuật về tự nguyên. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giậm chân", "Hạng Tần Suất (Jun Da)": "6010.0", "Tần Suất % (Jun Da)": "99.9823993319", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 勺", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊勺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "勺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "趵", "Unihan_Traditional (Chữ Phồn thể)": "趵", "Pinyin_Xie": "bào", "Âm Hán Việt_Xie": "báo, bác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Từ tượng thanh | 象声词 | Chữ này làm động từ chỉ hành động giậm chân hoặc dùng trong địa danh để tả tiếng nước phun. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('跖', '{"9000": "6011.0", "Chữ Trung Quốc": "跖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 12 | nét | 跖 | chích | tượng hình | lòng bàn chân | 跖 thuộc bộ 足 (túc, chân). Wiktionary cung cấp phát âm và định nghĩa (lòng bàn chân) nhưng không phân tích thành phần hình thanh/hội ý cụ thể. Có tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chích\" (lòng bàn chân): bộ 足 (chân) — phần tiếp đất của bàn chân, liên tưởng đến kẻ trộm Đạo Chích nhanh như gió, nhẹ bước không tiếng. | Gương Hán-Việt | chích trong \"đạo chích\" (盜跖) — tên kẻ trộm huyền thoại nổi tiếng trong văn học cổ | Mở khoá kiến thức | Biết 跖 giúp đọc hiểu tổ hợp 盜跖 và các văn bản y học cổ về giải phẫu bàn chân.", "Tự nguyên_Xie": "Tiểu triện | 跖 (âm zhí) theo Wiktionary: lòng bàn chân (sole of the foot). Bộ 足 biểu nghĩa liên quan đến chân. Wiktionary không phân tích phần âm. Chữ nổi tiếng trong tên kẻ trộm huyền thoại Đạo Chích (盜跖 Dào Zhí). Có tiểu triện. Chưa có nguồn học thuật về tự nguyên. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bàn chân", "Hạng Tần Suất (Jun Da)": "6011.0", "Tần Suất % (Jun Da)": "99.9824267215", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 石", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊石", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "石", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "跖", "Unihan_Traditional (Chữ Phồn thể)": "跖", "Pinyin_Xie": "zhí", "Âm Hán Việt_Xie": "chích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ gan bàn chân hoặc làm động từ chỉ hành động giậm chân lên đất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('跬', '{"9000": "6012.0", "Chữ Trung Quốc": "跬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 13 | nét | 足 | túc | biểu nghĩa | chân, bước chân | 圭 | quê | biểu âm | ngọc khuê | 跬 = 足 (Túc, biểu nghĩa: chân) + 圭 (Quê, biểu âm). Chữ hình thanh (psc): bộ 足 cho thấy liên quan đến bước chân, 圭 cho âm kuǐ. Nghĩa là nửa bước chân — một bước chân đơn (một chân dơ lên).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khoẻ\" (nửa bước): 足 (chân) + 圭 (âm) — một bước chân đơn. Câu Tuân Tử nhắc: không tích từng bước nhỏ, không đến được nghìn dặm. | Gương Hán-Việt | khoẻ trong \"khoẻ bộ\" (跬步) — từng bước nhỏ, bước ngắn | Mở khoá kiến thức | Biết 跬 giúp đọc câu kinh điển 跬步千里 (tích lũy từng bước nhỏ đi nghìn dặm) và văn học triết học cổ.", "Tự nguyên_Xie": "Theo Wiktionary: 跬 = 足 (chân, biểu nghĩa) + 圭 (biểu âm). Nghĩa là nửa bước (半步) — một chân bước lên. Hai bước 跬 mới thành một bộ (步). Câu trích dẫn kinh điển từ Tuân Tử: \"Cố bất tích khỏe bộ, vô dĩ chí thiên lý\" (không tích lũy từng bước nhỏ, không thể đi nghìn dặm). Có tiểu triện. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nửa bước chân, bước một chân; thời gian ngắn", "Hạng Tần Suất (Jun Da)": "6012.0", "Tần Suất % (Jun Da)": "99.9824541111", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 圭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊圭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "圭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "跬", "Unihan_Traditional (Chữ Phồn thể)": "跬", "Pinyin_Xie": "kuǐ", "Âm Hán Việt_Xie": "khuể", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Chữ này làm danh từ chỉ nửa bước chân hoặc làm lượng từ đo lường khoảng cách rất ngắn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('僬', '{"9000": "6013.0", "Chữ Trung Quốc": "僬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 14 | nét | 僬 | tiêu | tượng hình | người lùn, người thông minh nhanh nhẹn | 僬 thuộc bộ 亻 (nhân, người). Wiktionary cung cấp định nghĩa (thông minh, lanh lợi; người lùn thần thoại) nhưng không phân tích thành phần hình thanh cụ thể. Chữ xuất hiện chủ yếu trong tổ hợp 僬僥 chỉ loài người lùn trong thần thoại cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiêu\" (người lùn tinh khôn): bộ 亻 (người) — loài người tí hon trong thần thoại (僬僥) nổi tiếng vì sự thông minh và nhanh nhẹn bất ngờ. | Gương Hán-Việt | tiêu trong \"tiêu nghiêu\" (僬僥) — tên loài người lùn trong thần thoại cổ | Mở khoá kiến thức | Biết 僬 giúp đọc hiểu văn học thần thoại và địa lý thần kỳ (山海經) của Trung Hoa cổ đại.", "Tự nguyên_Xie": "僬 (âm jiāo) theo Wiktionary: thông minh, lanh lợi về tinh thần; xuất hiện trong 僬僥 chỉ loài người lùn thần thoại trong văn học cổ Trung Hoa. Bộ 亻 biểu nghĩa người. Wiktionary không phân tích hình thanh cụ thể. Chưa có nguồn học thuật về tự nguyên. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: tiêu nghiêu 僬僥,僬侥)", "Hạng Tần Suất (Jun Da)": "6013.0", "Tần Suất % (Jun Da)": "99.9824815007", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 焦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻焦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "焦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "僬", "Unihan_Traditional (Chữ Phồn thể)": "僬", "Pinyin_Xie": "jiāo", "Âm Hán Việt_Xie": "tiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này chủ yếu dùng làm danh từ trong từ ghép chỉ bộ tộc người lùn thời cổ hoặc làm tính từ chỉ sự lo nghĩ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('皲', '{"9000": "6014.0", "Chữ Trung Quốc": "皲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 皮 | Số nét | 11 | nét | 皲 | quân | tượng hình | da tay chân nứt nẻ vì lạnh | 皲 thuộc bộ 皮 (bì, da). Wiktionary xác nhận âm và nghĩa (nứt nẻ da) nhưng không phân tích thành phần hình thanh/hội ý. Chữ xuất hiện trong tổ hợp 皲裂 chỉ da nứt nẻ do thời tiết lạnh hanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quân\" (nứt nẻ): bộ 皮 (da) — da tay nứt toác như đất khô hạn, vào mùa đông hanh lạnh khi không được dưỡng ẩm. | Gương Hán-Việt | quân trong \"quân liệt\" (皲裂) — da nứt nẻ vì lạnh hoặc khô hanh | Mở khoá kiến thức | Biết 皲 giúp đọc hiểu văn học miêu tả lao động khổ cực trong mùa đông và các văn bản y học cổ về bệnh da.", "Tự nguyên_Xie": "皲 (dạng giản của 皸, âm jūn) theo Wiktionary: da bị nứt nẻ. Bộ 皮 biểu nghĩa liên quan đến da. Tổ hợp 皲裂 (quân liệt) chỉ da tay chân nứt vì thời tiết lạnh hanh. Wiktionary không phân tích thành phần cụ thể. Chưa có nguồn học thuật về tự nguyên. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chân tay nứt nẻ", "Hạng Tần Suất (Jun Da)": "6014.0", "Tần Suất % (Jun Da)": "99.9825088903", "GavinGrover_Once (Chiết tự trực tiếp)": "军 + 皮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰军皮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "军", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "皮", "Unihan_Simplified (Chữ Giản thể)": "皲", "Unihan_Traditional (Chữ Phồn thể)": "皸", "Pinyin_Xie": "jūn", "Âm Hán Việt_Xie": "quân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ chỉ hiện tượng da bị nứt nẻ hoặc làm danh từ chỉ vết nứt trên da. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('翥', '{"9000": "6015.0", "Chữ Trung Quốc": "翥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羽 | Số nét | 14 | nét | 者 | giả | biểu âm | kẻ, người | 羽 | vu | biểu nghĩa | cánh, lông vũ | 翥 = 者 (Giả, biểu âm) + 羽 (Vu, biểu nghĩa: cánh/lông). Chữ hình thanh (psc): bộ 羽 cho thấy liên quan đến cánh/bay, 者 cho âm zhù. Nghĩa là bay lên cao, vút lên.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chở\" (bay vút): 羽 (cánh) + 者 (âm) — cánh vũ vút lên cao, như phụng hoàng chở cánh trong thành ngữ cổ điển 鳳翥龍翔. | Gương Hán-Việt | chở trong \"phụng chở\" (鳳翥) — phụng hoàng vút lên cao | Mở khoá kiến thức | Biết 翥 giúp đọc hiểu thành ngữ cổ điển như 鸞翔鳳翥, 龍翔鳳翥 trong thư pháp và thơ văn Hán.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary: 翥 = 者 (biểu âm) + 羽 (cánh/lông, biểu nghĩa). Chữ hình thanh chỉ hành động bay lên cao — thường dùng trong tổ hợp như 鸞翔鳳翥 (loan tường phụng chở: loan bay phượng vút). Có tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bay lên", "Hạng Tần Suất (Jun Da)": "6015.0", "Tần Suất % (Jun Da)": "99.9825362799", "GavinGrover_Once (Chiết tự trực tiếp)": "者 + 羽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱者羽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "者", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羽", "Unihan_Simplified (Chữ Giản thể)": "翥", "Unihan_Traditional (Chữ Phồn thể)": "翥", "Pinyin_Xie": "zhù", "Âm Hán Việt_Xie": "chứ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ trong văn viết để tả cảnh chim muông tung cánh bay cao. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('祎', '{"9000": "6016.0", "Chữ Trung Quốc": "祎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 8 | nét | 示 | thị | biểu nghĩa | thần linh, lễ nghi | 韋 | vi | biểu âm | da thuộc | 祎 = 示 (Thị, biểu nghĩa: thần/lễ nghi) + 韋 (Vi, biểu âm). Chữ hình thanh (psc): bộ 示 liên quan đến thần linh và điều tốt đẹp thiêng liêng, 韋 cho âm yī. Nghĩa là tốt đẹp, xuất sắc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"y\" (tốt đẹp): 示 (thần/thiêng liêng) + 韋 (âm) — điều tốt đẹp được thần linh ban phước, xuất sắc hiếm có. Hay dùng đặt tên người. | Gương Hán-Việt | y trong \"y nhiên\" (祎然) — tốt đẹp, xuất sắc (ít dùng) | Mở khoá kiến thức | Biết 祎 giúp đọc hiểu tên người trong văn học cổ điển và lịch sử Trung Hoa (như Gia Cát Chiêm, tên thật Gia Cát Phẩm Huệ Tư).", "Tự nguyên_Xie": "Theo Wiktionary: 祎 (dạng giản của 禕) = 示 (thần/lễ nghi, biểu nghĩa) + 韋 (da thuộc, biểu âm). Nghĩa là tốt đẹp, xuất sắc, hiếm có. Thường dùng làm tên người, đặc biệt là tên phụ nữ trong văn hóa Trung Hoa. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tốt đẹp", "Hạng Tần Suất (Jun Da)": "6016.0", "Tần Suất % (Jun Da)": "99.9825636696", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 韦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻韦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "韦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "祎", "Unihan_Traditional (Chữ Phồn thể)": "禕", "Pinyin_Xie": "yī", "Âm Hán Việt_Xie": "y", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ trong văn cổ để ca ngợi vẻ đẹp hoặc dùng trong tên người. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('芴', '{"9000": "6017.0", "Chữ Trung Quốc": "芴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 7 | nét | 芴 | vật | tượng hình | cây huỳnh quang (fluorene), hoặc mơ hồ thoáng qua | 芴 thuộc bộ 艸 (thảo, cỏ/thực vật). Không có phân tích thành phần hình thanh/hội ý từ Wiktionary. Chữ có hai nghĩa: cổ văn là mơ hồ/bất ngờ; hiện đại là tên hợp chất hữu cơ fluorene. Có tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vật\" (mơ hồ/fluorene): bộ 艸 (thực vật) — chữ cổ nghĩa là bất ngờ, mơ hồ; nay dùng trong hoá học để ghi tên fluorene, hợp chất từ than đá. | Gương Hán-Việt | vật trong thuật ngữ hoá học — ít dùng trong văn học thông thường | Mở khoá kiến thức | Biết 芴 giúp đọc hiểu tên hợp chất hoá học hữu cơ và một số văn bản triết học cổ về sự mơ hồ vô định.", "Tự nguyên_Xie": "Tiểu triện | 芴 (âm wù) theo Wiktionary không có phân tích tự nguyên. Nghĩa cổ là mơ hồ (忽然/suddenly). Nghĩa hiện đại là fluorene (hợp chất hữu cơ thơm hai vòng). Bộ 艸 liên quan đến thực vật/chất hữu cơ. Chữ có tiểu triện. Chưa có nguồn học thuật về tự nguyên. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hợp chất hữu cơ Flu-ô-ren; Flu-ô-ren (Anh: fluorene)", "Hạng Tần Suất (Jun Da)": "6017.0", "Tần Suất % (Jun Da)": "99.9826727112", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 勿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹勿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "勿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "芴", "Unihan_Traditional (Chữ Phồn thể)": "芴", "Pinyin_Xie": "wù", "Âm Hán Việt_Xie": "vật, hốt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ một loại cây viễn chí hoặc hợp chất hóa học hữu cơ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('菰', '{"9000": "6018.0", "Chữ Trung Quốc": "菰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 艸 | tháo | biểu nghĩa | cỏ, thực vật | 孤 | cô | biểu âm | cô đơn, một mình | 菰 = 艸 (Tháo, biểu nghĩa: cỏ/thực vật) + 孤 (Cô, biểu âm). Chữ hình thanh (psc): bộ 艸 liên quan đến thực vật, 孤 cho âm gū. Nghĩa là rau cô (Zizania latifolia) — loài cây thủy sinh dùng làm thực phẩm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cô\" (rau cô): 艸 (cây) + 孤 (cô đơn, âm) — cây thủy sinh mọc riêng lẻ trong ao hồ, thân mềm dùng làm rau, hạt làm cơm. | Gương Hán-Việt | cô trong \"giao cô\" (茭菰) hoặc \"cô mễ\" (菰米) — gạo lúa cô | Mở khoá kiến thức | Biết 菰 giúp đọc hiểu văn học và ẩm thực cổ Trung Hoa về loài cây thủy sinh ăn được này.", "Tự nguyên_Xie": "Theo Wiktionary: 菰 = 艸 (cỏ/thực vật, biểu nghĩa) + 孤 (biểu âm). Chữ hình thanh chỉ cây rau cô hay lúa cô (Zizania latifolia/wild rice), loài thủy sinh cho hạt ăn được và thân non dùng làm rau. Cây này mọc một mình trong nước, gợi liên tưởng với 孤 (cô đơn). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rau cô, lúa cô; cây nấm", "Hạng Tần Suất (Jun Da)": "6018.0", "Tần Suất % (Jun Da)": "99.982699584", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 孤", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹孤", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "孤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "菰", "Unihan_Traditional (Chữ Phồn thể)": "菰", "Pinyin_Xie": "gū", "Âm Hán Việt_Xie": "cô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ cây niễng hoặc các loại nấm ăn được. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('眙', '{"9000": "6019.0", "Chữ Trung Quốc": "眙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 10 | nét | 眙 | y | tượng hình | trông thẳng, nhìn chằm chằm | 眙 thuộc bộ 目 (mục, mắt). Wiktionary chỉ ghi {{Han etym}} không có phân tích thành phần. Chữ chỉ hành động nhìn thẳng hoặc nhìn chằm chằm. Nổi tiếng qua địa danh 盱眙 (Hư Y) ở Giang Tô. Có tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"y\" (nhìn thẳng): bộ 目 (mắt) — mắt mở to nhìn thẳng không chớp, cố định vào một điểm, như trong địa danh 盱眙 (mắt mở trông về phía trước). | Gương Hán-Việt | y trong \"hư y\" (盱眙) — địa danh nổi tiếng ở Giang Tô | Mở khoá kiến thức | Biết 眙 giúp nhận ra địa danh 盱眙 trong lịch sử và văn học Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | 眙 (âm yí) theo Wiktionary: nhìn thẳng, trông chằm chằm. Bộ 目 biểu nghĩa mắt. Wiktionary không cung cấp phân tích hình thanh/hội ý. Chữ xuất hiện trong 盱眙 — địa danh nổi tiếng ở Giang Tô, Trung Quốc. Có tiểu triện. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trông thẳng", "Hạng Tần Suất (Jun Da)": "6019.0", "Tần Suất % (Jun Da)": "99.9827264569", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 台", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目台", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "台", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "眙", "Unihan_Traditional (Chữ Phồn thể)": "眙", "Pinyin_Xie": "yí", "Âm Hán Việt_Xie": "di", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ trong văn cổ để chỉ hành động nhìn chăm chú hoặc kinh ngạc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锓', '{"9000": "6020.0", "Chữ Trung Quốc": "锓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 12 | nét | 锓 | khẩm | tượng hình | khắc chạm, điêu khắc vào gỗ/đá | 锓 là dạng giản của 鋟, thuộc bộ 金 (kim, kim loại). Wiktionary mô tả là khắc/điêu khắc (văn cổ) và đầu nhọn (nghĩa cũ). Không có phân tích hình thanh/hội ý rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khẩm\" (khắc chạm): bộ 金 (kim loại) — dùng dụng cụ sắc bén bằng kim loại để khắc chữ hoặc hoa văn vào gỗ, đá, hay đồng. | Gương Hán-Việt | khẩm trong \"khẩm khắc\" (锓刻) — khắc chữ, khắc in bản gỗ | Mở khoá kiến thức | Biết 锓 giúp đọc hiểu văn bản về in ấn bằng bản gỗ (mộc bản) và nghề điêu khắc cổ đại Trung Hoa.", "Tự nguyên_Xie": "锓 (dạng giản của 鋟, âm qǐn) theo Wiktionary: (1) khắc, điêu khắc vào vật liệu; (2) nhọn, sắc bén (nghĩa cũ). Bộ 金 biểu nghĩa liên quan đến công cụ kim loại dùng để khắc. Wiktionary không phân tích thành phần hình thanh. Chưa có nguồn học thuật về tự nguyên. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khắc, chạm", "Hạng Tần Suất (Jun Da)": "6020.0", "Tần Suất % (Jun Da)": "99.9827533297", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "锓", "Unihan_Traditional (Chữ Phồn thể)": "鋟", "Pinyin_Xie": "qǐn", "Âm Hán Việt_Xie": "tẩm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ chỉ hành động khắc chữ hoặc in ấn bằng bản khắc gỗ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('訾', '{"9000": "6021.0", "Chữ Trung Quốc": "訾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 13 | nét | 訾 | tư | tượng hình | nói xấu, phê bình, chê bai | 訾 thuộc bộ 言 (ngôn, lời nói). Wiktionary cung cấp bốn âm đọc: zǐ (nói xấu/phê bình), zī (từ này), cí (chê bai/khuyết điểm), zū (tên thú vật). Không có phân tích thành phần hình thanh/hội ý rõ ràng. Có bạch thư, đại triện và tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tư\" (chê bai): bộ 言 (lời nói) — dùng lời nói để bới móc lỗi lầm người khác, chỉ trích, nói xấu sau lưng. | Gương Hán-Việt | tư trong \"tư nghị\" (訾議) — phê bình, chê bai; \"hủy tư\" (毀訾) — nói xấu phá hoại | Mở khoá kiến thức | Biết 訾 giúp đọc hiểu các văn bản luận lý và chính trị cổ điển khi nói về phê bình và ngôn từ.", "Tự nguyên_Xie": "Bạch thư | Đại triện | Tiểu triện | 訾 (âm zī/zǐ) theo Wiktionary là chữ đa âm đa nghĩa: nói xấu/phê bình (zǐ); từ này/đây (zī); khuyết điểm (cí); tên một loài thú (zū). Bộ 言 liên quan đến lời nói, phát ngôn. Chữ có lịch sử cổ với bạch thư, đại triện. Wiktionary không phân tích cụ thể tự nguyên. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nói xấu; bới móc", "Hạng Tần Suất (Jun Da)": "6021.0", "Tần Suất % (Jun Da)": "99.9827802025", "GavinGrover_Once (Chiết tự trực tiếp)": "此 + 言", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱此言", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "此", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "訾", "Unihan_Traditional (Chữ Phồn thể)": "訾", "Pinyin_Xie": "zī", "Âm Hán Việt_Xie": "tí, ti", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ chỉ việc gièm pha, chỉ trích hoặc làm danh từ chỉ lỗi lầm. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('莳', '{"9000": "6022.0", "Chữ Trung Quốc": "莳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 10 | nét | 艹 | tháo | biểu nghĩa | cỏ, thực vật | 時 | thì | biểu âm | thời gian, mùa vụ | 莳 = 艹 (Tháo, biểu nghĩa: cỏ/thực vật) + 時 (Thì, biểu âm). Chữ hình thanh (psc): bộ 艹 liên quan đến thực vật, 時 cho âm shí. Nghĩa là cấy trồng lại, trồng cây theo đúng thời vụ; cũng dùng cho cây thìa là (dill).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thì\" (cấy trồng): 艹 (cây) + 時 (thời vụ, âm) — đúng thời điểm trong năm để nhổ cây con lên rồi cấy trồng lại — như cấy lúa theo mùa. | Gương Hán-Việt | thì trong \"thì la\" (蒔蘿/莳萝) — cây thìa là (dill), gia vị quen thuộc | Mở khoá kiến thức | Biết 莳 giúp đọc hiểu tên cây thìa là (莳萝) trong ẩm thực và các văn bản nông nghiệp cổ điển.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary: 莳 (dạng giản của 蒔) = 艹 (cỏ/thực vật, biểu nghĩa) + 時 (biểu âm). Chữ hình thanh chỉ việc cấy lại cây con (trồng lại sau khi nhổ lên) — đặc biệt trong canh tác lúa. Cũng chỉ cây thìa là (Anethum graveolens/dill). Có tiểu triện và lục thư thông. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: thì la 蒔蘿,莳萝); trồng, trồng lại, cấy lại", "Hạng Tần Suất (Jun Da)": "6022.0", "Tần Suất % (Jun Da)": "99.9828070754", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 时", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹时", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "时", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "莳", "Unihan_Traditional (Chữ Phồn thể)": "蒔", "Pinyin_Xie": "shí", "Âm Hán Việt_Xie": "thì, thi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ chỉ việc cấy trồng hoặc làm danh từ trong tên cây thì là. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('菪', '{"9000": "6023.0", "Chữ Trung Quốc": "菪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 菪 | đãng | tượng hình | cây lang đãng (henbane), cây độc họ cà | 菪 thuộc bộ 艸 (thảo, cỏ/thực vật). Không có phân tích thành phần hình thanh/hội ý từ Wiktionary. Chữ xuất hiện chủ yếu trong tổ hợp 莨菪 (lang đãng) chỉ cây henbane — loài cây độc dùng trong dược liệu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đãng\" (cây độc): bộ 艸 (cây cỏ) — cây lang đãng (莨菪) có độc tính, dùng làm thuốc gây mê trong y học cổ đại Trung Hoa. | Gương Hán-Việt | đãng trong \"lang đãng\" (莨菪) — tên cây henbane trong y học cổ truyền | Mở khoá kiến thức | Biết 菪 giúp nhận ra 莨菪 trong văn bản y học cổ truyền Trung Hoa và bản thảo dược học.", "Tự nguyên_Xie": "菪 (âm dàng) không có phân tích tự nguyên trong Wiktionary. Chữ xuất hiện trong tổ hợp 莨菪 (Hyoscyamus niger/henbane) — cây thuộc họ cà có độc tính cao, dùng trong y học cổ đại như chất gây mê. Bộ 艸 biểu nghĩa thực vật. Chưa có nguồn học thuật. Chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: lang đãng 莨菪)", "Hạng Tần Suất (Jun Da)": "6023.0", "Tần Suất % (Jun Da)": "99.9828339482", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 宕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹宕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "菪", "Unihan_Traditional (Chữ Phồn thể)": "菪", "Pinyin_Xie": "dàng", "Âm Hán Việt_Xie": "đãng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ ghép để chỉ cây lang đãng trong y học cổ truyền. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('槠', '{"9000": "6024.0", "Chữ Trung Quốc": "槠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 14 | nét | 槠 | trữ | tượng hình | cây dẻ gai (Castanopsis/Quercus glauca) | 槠 là dạng giản của 櫧, thuộc bộ 木 (mộc, gỗ). Wiktionary mô tả là cây thuộc loài Quercus glauca hoặc chi Castanopsis, họ Sồi/Dẻ. Không có phân tích thành phần hình thanh/hội ý rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trữ\" (cây dẻ): bộ 木 (cây/gỗ) — loài cây họ Sồi xanh tốt quanh năm ở miền Nam Trung Quốc, gỗ cứng dùng làm đồ dùng bền chắc. | Gương Hán-Việt | trữ trong \"trữ mộc\" (槠木) — gỗ cây dẻ, vật liệu xây dựng và đồ gỗ | Mở khoá kiến thức | Biết 槠 giúp đọc hiểu văn học về thực vật và rừng núi miền Nam Trung Quốc.", "Tự nguyên_Xie": "槠 (dạng giản của 櫧, âm zhū) theo Wiktionary: loài cây thuộc Quercus glauca hoặc chi Castanopsis trong họ Fagaceae (Sồi/Dẻ). Bộ 木 biểu nghĩa cây/gỗ. Wiktionary không phân tích tự nguyên cụ thể. Chưa có nguồn học thuật. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây dó", "Hạng Tần Suất (Jun Da)": "6024.0", "Tần Suất % (Jun Da)": "99.982860821", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 诸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木诸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "诸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "槠", "Unihan_Traditional (Chữ Phồn thể)": "櫧", "Pinyin_Xie": "zhū", "Âm Hán Việt_Xie": "chư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ một loại cây thân gỗ thuộc họ sồi dẻ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('榍', '{"9000": "6025.0", "Chữ Trung Quốc": "榍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 14 | nét | 榍 | tiết | tượng hình | ngưỡng cửa, bậc cửa (doorsill); loài cây cổ | 榍 thuộc bộ 木 (mộc, gỗ). Wiktionary mô tả hai nghĩa cổ điển: ngưỡng cửa/bậc cửa (threshold) và một loài cây được mô tả trong văn bản cổ. Không có phân tích thành phần hình thanh/hội ý. Có tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiết\" (ngưỡng cửa): bộ 木 (gỗ) — thanh gỗ nằm ngang ở bậc cửa dưới, người qua lại phải bước qua — biên giới của trong và ngoài. | Gương Hán-Việt | tiết trong \"tiết thạch\" (榍石) — tên khoáng vật sphene trong địa chất học | Mở khoá kiến thức | Biết 榍 giúp đọc hiểu văn bản kiến trúc cổ điển và có thể gặp trong tên khoáng vật tiếng Trung (榍石 = sphene).", "Tự nguyên_Xie": "Tiểu triện | 榍 (âm xiè) theo Wiktionary: ngưỡng cửa, doorsill; bậc cửa dưới. Cũng chỉ một loài cây được ghi trong văn bản cổ. Bộ 木 biểu nghĩa liên quan đến gỗ/cây. Wiktionary không phân tích tự nguyên. Chữ có tiểu triện. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngạch cửa; bậu cửa; bậc cửa", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 屑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木屑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "屑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "榍", "Unihan_Traditional (Chữ Phồn thể)": "榍", "Pinyin_Xie": "xiè", "Âm Hán Việt_Xie": "tiết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ bộ phận khung gỗ ở chân cửa hoặc trong tên khoáng vật đá titan. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('俜', '{"9000": "6026.0", "Chữ Trung Quốc": "俜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 9 | nét | 亻 | nhân | biểu nghĩa | người | 甹 | biểu âm | phần biểu âm (甹) | 俜 = 亻 (Nhân, biểu nghĩa: người) + 甹 (biểu âm). Chữ hình thanh (psc): bộ 亻 cho thấy liên quan đến người, 甹 cho âm pīng. Nghĩa là cô đơn, thui thủi; nhờ cậy/gửi gắm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phình\" (cô đơn): 亻 (người) + 甹 (âm) — người đứng một mình trơ trọi, không ai bên cạnh, gửi gắm nỗi nhớ xa vắng. | Gương Hán-Việt | phình trong \"phình đinh\" (俜丁) — người cô đơn không nơi nương tựa | Mở khoá kiến thức | Biết 俜 giúp đọc hiểu thơ văn cổ miêu tả cảnh cô đơn, xa nhà, không người thân.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary: 俜 = 亻 (người, biểu nghĩa) + 甹 (biểu âm). Chữ hình thanh. Nghĩa là một mình, cô đơn (thui thủi); hoặc nhờ cậy/gửi thư/giao việc cho ai. Có tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thui thủi; trơ trọi", "Hạng Tần Suất (Jun Da)": "6026.0", "Tần Suất % (Jun Da)": "99.9829145667", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 甹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻甹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "俜", "Unihan_Traditional (Chữ Phồn thể)": "俜", "Pinyin_Xie": "pīng", "Âm Hán Việt_Xie": "binh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ miêu tả trạng thái cô đơn, lẻ loi trong văn cổ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('觚', '{"9000": "6027.0", "Chữ Trung Quốc": "觚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 角 | Số nét | 12 | nét | 觚 | cô | tượng hình | bình rượu đồng hình trụ cao; thẻ gỗ viết chữ | 觚 thuộc bộ 角 (giác, sừng/góc cạnh). Wiktionary mô tả là bình rượu đồng thời Thương-Chu hình trụ cao miệng loe, có gờ; cũng là thẻ gỗ dùng ghi chữ cổ đại. Không có phân tích thành phần hình thanh/hội ý rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cô\" (bình đồng): bộ 角 (sừng/góc) — bình rượu đồng thời Thương-Chu hình dáng thanh mảnh cao vút như sừng, miệng loe rộng. | Gương Hán-Việt | cô trong \"thao cô\" (操觚) — cầm thẻ gỗ, nghĩa là viết văn sáng tác | Mở khoá kiến thức | Biết 觚 giúp nhận ra 操觚 (sáng tác văn chương) và các tên đồ vật nghi lễ đồng thau trong lịch sử Thương-Chu.", "Tự nguyên_Xie": "Tiểu triện | 觚 (âm gū) theo Wiktionary: bình rượu đồng cao (bronze wine vessel) thời cổ Thương-Chu, thân mảnh, miệng rộng, đáy tròn, có gờ. Nghĩa phụ: gờ/góc cạnh; thẻ gỗ viết chữ (wooden writing slip). Bộ 角 liên quan đến hình dạng góc cạnh. Wiktionary không phân tích tự nguyên cụ thể. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phép tắc, luật lệ", "Hạng Tần Suất (Jun Da)": "6027.0", "Tần Suất % (Jun Da)": "99.9829414395", "GavinGrover_Once (Chiết tự trực tiếp)": "角 + 瓜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰角瓜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "瓜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "角", "Unihan_Simplified (Chữ Giản thể)": "觚", "Unihan_Traditional (Chữ Phồn thể)": "觚", "Pinyin_Xie": "gū", "Âm Hán Việt_Xie": "cô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loại chén uống rượu thời cổ hoặc ẩn dụ cho quy tắc, khuôn mẫu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('撄', '{"9000": "6028.0", "Chữ Trung Quốc": "撄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 14 | nét | 撄 | anh | tượng hình | chạm tới, vướng mắc, đối địch | 撄 là dạng giản của 攖, thuộc bộ 手/扌 (thủ, tay). Wiktionary cung cấp phát âm nhưng không có định nghĩa rõ ràng — chỉ ghi rfdef. Nghĩa gốc là chạm tới, vướng vào, xúc phạm hoặc đối kháng. Xuất hiện trong 撄寧 (anh ninh).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"anh\" (vướng mắc): bộ 扌 (tay) — tay chạm vào điều cấm kỵ, vướng víu vào rắc rối — như 攖寧 trong Trang Tử: bình tĩnh dù bị quấy nhiễu. | Gương Hán-Việt | anh trong \"anh ninh\" (攖寧/撄宁) — bình tĩnh dù bị quấy nhiễu (thuật ngữ Trang Tử) | Mở khoá kiến thức | Biết 撄 giúp đọc hiểu Trang Tử và triết học Đạo gia: 攖寧 là khái niệm quan trọng về sự bình thản trước va chạm.", "Tự nguyên_Xie": "撄 (dạng giản của 攖, âm yīng) theo Wiktionary không có định nghĩa đầy đủ. Nghĩa được biết qua từ điển: chạm tới, xúc phạm, làm phiền; vướng mắc vào. Tổ hợp 攖寧 trong Trang Tử chỉ trạng thái tâm hồn bình yên dù bị quấy nhiễu. Bộ 手 biểu nghĩa hành động tay. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chạm tới, đến gần; vướng, mắc", "Hạng Tần Suất (Jun Da)": "6028.0", "Tần Suất % (Jun Da)": "99.9829683123", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 婴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌婴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "婴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "撄", "Unihan_Traditional (Chữ Phồn thể)": "攖", "Pinyin_Xie": "yīng", "Âm Hán Việt_Xie": "anh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ trong văn viết để chỉ hành động chạm vào hoặc chọc giận. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嵫', '{"9000": "6029.0", "Chữ Trung Quốc": "嵫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 12 | nét | 嵫 | tư | tượng hình | tên núi (Yêm Tư 崦嵫) ở Cam Túc | 嵫 thuộc bộ 山 (sơn, núi). Wiktionary mô tả dùng trong 嵫釐 (núi cao chót vót) và 崦嵫 (tên núi ở Cam Túc, tượng trưng cho nơi mặt trời lặn). Không có phân tích thành phần hình thanh/hội ý rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tư\" (núi phương Tây): bộ 山 (núi) — núi Yêm Tư (崦嵫) trong thơ Khuất Nguyên, nơi mặt trời lặn xuống vào cuối ngày, biểu tượng cho sự tàn phai. | Gương Hán-Việt | tư trong \"yêm tư\" (崦嵫) — núi tượng trưng cho phương Tây, nơi mặt trời lặn | Mở khoá kiến thức | Biết 嵫 giúp đọc Ly Tao (Khuất Nguyên) và văn học cổ điển Trung Hoa về hình ảnh mặt trời lặn và thời gian trôi qua.", "Tự nguyên_Xie": "嵫 (âm zī) theo Wiktionary: xuất hiện trong 嵫釐 (núi cao chót vót, gian nan) và 崦嵫 (tên núi ở Cam Túc, Trung Quốc — trong văn học cổ tượng trưng cho nơi mặt trời đi xuống/lặn). Bộ 山 biểu nghĩa núi. Wiktionary không phân tích tự nguyên. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: yêm tư 崤嵫)", "Hạng Tần Suất (Jun Da)": "6029.0", "Tần Suất % (Jun Da)": "99.9829946684", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 兹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰山兹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "嵫", "Unihan_Traditional (Chữ Phồn thể)": "嵫", "Pinyin_Xie": "zī", "Âm Hán Việt_Xie": "tư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ riêng chỉ núi Yêm Tư, nơi mặt trời lặn theo thần thoại Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('桴', '{"9000": "6030.0", "Chữ Trung Quốc": "桴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 11 | nét | 桴 | phù | tượng hình | bè gỗ; dùi trống; đòn nóc nhà | 桴 thuộc bộ 木 (mộc, gỗ). Wiktionary chỉ ghi {{Han etym}} không có phân tích thành phần. Chữ có ba nghĩa chính: bè gỗ nổi trên nước; dùi trống; đòn nóc/xà ngang mái nhà. Có kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phù\" (bè gỗ): bộ 木 (gỗ) — ghép gỗ thành bè nổi, như Khổng Tử hứa sẽ \"cưỡi bè ra biển\" nếu thiên hạ không theo đạo của ông. | Gương Hán-Việt | phù trong \"phù hải\" (桴海) — đi biển trên bè; \"phù cổ\" (桴鼓) — dùi trống | Mở khoá kiến thức | Biết 桴 giúp đọc câu nổi tiếng trong Luận Ngữ và văn học âm nhạc cổ Trung Hoa về nhạc cụ gõ.", "Tự nguyên_Xie": "Kim văn | 桴 (âm fú) theo Wiktionary không có phân tích tự nguyên (chỉ {{Han etym}}). Bộ 木 biểu nghĩa liên quan đến gỗ. Nghĩa: bè nổi (raft), dùi trống, đòn nóc. Câu nổi tiếng từ Luận Ngữ: Khổng Tử nói \"Nếu đạo không được thực hành, ta sẽ lênh đênh trên biển bằng một chiếc bè\" (乘桴浮于海). Có kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái xà nhi; cái dùi trống", "Hạng Tần Suất (Jun Da)": "6030.0", "Tần Suất % (Jun Da)": "99.9830210244", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 孚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木孚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "孚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "桴", "Unihan_Traditional (Chữ Phồn thể)": "桴", "Pinyin_Xie": "fú", "Âm Hán Việt_Xie": "phù", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ cái bè gỗ hoặc dùi trống trong văn học cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('晡', '{"9000": "6031.0", "Chữ Trung Quốc": "晡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 11 | nét | 日 | nhật | biểu nghĩa | mặt trời, ngày | 甫 | phủ | biểu âm | mới, vừa mới | 晡 = 日 (Nhật, biểu nghĩa: mặt trời/thời gian) + 甫 (Phủ, biểu âm). Chữ hình thanh (psc): bộ 日 liên quan đến thời điểm trong ngày, 甫 cho âm bū. Nghĩa là giờ Thân (3-5 giờ chiều) — khoảng buổi chiều muộn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bô\" (giờ Thân): 日 (mặt trời) + 甫 (âm) — mặt trời đã nghiêng về tây lúc 3-5 chiều, giờ Thân trong lịch Trung Hoa — thời điểm ăn bữa chiều. | Gương Hán-Việt | bô trong \"nhật bô\" (日晡) — buổi chiều, khoảng giờ Thân | Mở khoá kiến thức | Biết 晡 giúp đọc hiểu hệ thống 12 giờ cổ Trung Hoa và văn học miêu tả cảnh vật buổi chiều tà.", "Tự nguyên_Xie": "Theo Wiktionary: 晡 = 日 (mặt trời/thời gian, biểu nghĩa) + 甫 (biểu âm). Chỉ giờ Thân trong hệ thống thập nhị chi thời gian cổ Trung Hoa, tương đương 3-5 giờ chiều. Cũng chỉ buổi chiều muộn/đầu tối. Phổ biến trong tiếng Mân Nam và Quảng Đông. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Buổi chiều", "Hạng Tần Suất (Jun Da)": "6031.0", "Tần Suất % (Jun Da)": "99.9830473804", "GavinGrover_Once (Chiết tự trực tiếp)": "日 + 甫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰日甫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "晡", "Unihan_Traditional (Chữ Phồn thể)": "晡", "Pinyin_Xie": "bū", "Âm Hán Việt_Xie": "bô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ mốc thời gian buổi chiều muộn trong tiếng Hán cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('爨', '{"9000": "6032.0", "Chữ Trung Quốc": "爨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 30 | nét | 𦥑 | biểu nghĩa | hai bàn tay | 鬲 | lịch | biểu nghĩa | nồi nấu | 冂 | biểu nghĩa | miệng bếp | 林 | lâm | biểu nghĩa | củi | 廾 | củng | biểu nghĩa | hai tay | 火 | hoả | biểu nghĩa | lửa | 爨 là chữ hội ý (ls=ic): tay người (𦥑/廾) đặt nồi (鬲) lên bếp (冂), thêm củi (林) vào lửa (火) — toàn bộ cảnh nấu ăn được khắc thành một chữ. Xuất hiện khá muộn, tìm thấy đầu tiên trên thẻ tre.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"soạn\" (nấu, bếp): chữ phức tạp nhất — 30 nét vẽ cả cảnh bếp núc: nồi + miệng bếp + củi + lửa + hai bàn tay. | Gương Hán-Việt | 炊爨 (xuy soạn) = nấu nướng | Mở khoá kiến thức | Biết 爨 mở khoá từ 炊爨 (bếp lửa, nấu ăn) và tên phong cách thư pháp 爨體 thịnh hành thế kỷ 3-4.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 爨 là chữ hội ý xuất hiện muộn, đầu tiên thấy trên thẻ tre. Kết hợp: hai tay (𦥑) nâng nồi nấu (鬲) đặt lên miệng bếp (冂), tay kia (廾) nhét củi (林) vào lửa (火) — mô tả trọn vẹn động tác nhóm bếp nấu ăn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nấu; cái bếp", "Hạng Tần Suất (Jun Da)": "6032.0", "Tần Suất % (Jun Da)": "99.9830737365", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "爨", "Unihan_Traditional (Chữ Phồn thể)": "爨", "Pinyin_Xie": "cuàn", "Âm Hán Việt_Xie": "thoán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ chỉ việc nấu nướng hoặc danh từ chỉ cái bếp lò thời xưa. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('悫', '{"9000": "6033.0", "Chữ Trung Quốc": "悫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 11 | nét | 悫 | xác | tượng hình | thành thật, ngay thẳng | 悫 là dạng giản thể / biến thể của 愨; cấu trúc chi tiết chưa được Wiktionary ghi nhận rõ. Chữ liên quan đến bộ 心 (tâm), chỉ phẩm chất nội tâm thành thật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xác\" (thành thật, xác thực): nhớ \"xác nhận\" — người xác thực luôn thành thật, không giả dối, đúng như nghĩa của 悫. | Gương Hán-Việt | 忠悫 (trung xác) = trung thành thành thật | Mở khoá kiến thức | Biết 悫 mở khoá từ cổ văn 忠愨 (trung xác) và 愨士 — người chính trực trong văn học cổ điển.", "Tự nguyên_Xie": "Wiktionary dùng dạng chuẩn 愨 cho chữ này; 悫 là dị thể. Nghĩa gốc: thành thật, cung kính, không giả dối — phẩm hạnh được văn ngôn cổ đại đề cao. Chưa có ghi chú cấu tạo chi tiết trong nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thành thực; thành thật; không giả dối; thật thà; xác; như \"xác (thành thực)\" \n\n§ Cũng như 愨.", "Hạng Tần Suất (Jun Da)": "6033.0", "Tần Suất % (Jun Da)": "99.9831000925", "GavinGrover_Once (Chiết tự trực tiếp)": "士 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱士", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "悫", "Unihan_Traditional (Chữ Phồn thể)": "愨", "Pinyin_Xie": "què", "Âm Hán Việt_Xie": "khác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Dùng làm tính từ miêu tả tính cách trung thực, chất phác của con người. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锇', '{"9000": "6034.0", "Chữ Trung Quốc": "锇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 12 | nét | 锇 | nga | tượng hình | nguyên tố osimi (Os) | 锇 là chữ tạo muộn để phiên âm tên nguyên tố hoá học osimi (Os). Bộ 金 (kim loại) chỉ nghĩa, phần biểu âm mang âm \"é\" gần với Os trong tiếng Anh/Latinh. Chưa có dữ liệu cấu tạo chi tiết trong nguồn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nga\" (osimi): bộ 金 (kim loại) + âm \"é\" — chữ chỉ kim loại nặng nhất trong bảng tuần hoàn. | Gương Hán-Việt | 锇元素 = nguyên tố osimi | Mở khoá kiến thức | Biết 锇 nhận diện ngay nguyên tố Os (osimi) trong văn bản hoá học Trung Quốc.", "Tự nguyên_Xie": "锇 là chữ tạo muộn, dùng để chuyển ngữ tên nguyên tố osimi (Os, số nguyên tử 76) sang chữ Hán. Không có ghi chép glyph-origin trong Wiktionary. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố osimi, Os", "Hạng Tần Suất (Jun Da)": "6034.0", "Tần Suất % (Jun Da)": "99.9831264486", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 我", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅我", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "我", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锇", "Unihan_Traditional (Chữ Phồn thể)": "鋨", "Pinyin_Xie": "é", "Âm Hán Việt_Xie": "nga", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này đóng vai trò làm danh từ chỉ nguyên tố hóa học trong các văn bản khoa học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锖', '{"9000": "6035.0", "Chữ Trung Quốc": "锖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 13 | nét | 金 | kim | biểu nghĩa | kim loại | 青 | thanh | biểu âm | xanh lam/xanh lục | 锖 = 金 (Kim, biểu nghĩa: kim loại) + 青 (Thanh, biểu âm); chữ hình thanh. Bộ 金 chỉ đây là chữ liên quan kim loại; 青 cho âm đọc gần với qiāng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thương\" (ánh kim loại): 金 (kim) + 青 (xanh thanh) — lớp xỉn xanh trên đồng/kim loại sau khi để lâu ngoài không khí. | Gương Hán-Việt | 錆色 (thương sắc) = màu xỉn kim loại | Mở khoá kiến thức | Biết 锖 nhận diện thuật ngữ 錆色 chỉ màu oxid hoá của kim loại trong văn bản kỹ thuật/nghệ thuật Trung Quốc.", "Tự nguyên_Xie": "Theo Wiktionary (dạng 錆), 锖 là chữ hình thanh: 金 (kim loại, biểu nghĩa) + 青 (biểu âm). Chỉ màu sắc xỉn, ánh xanh lam của bề mặt kim loại hay khoáng vật khi tiếp xúc không khí (patina/tarnish). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "màu của kim loại hoặc khoáng vật ánh vào không khí", "Hạng Tần Suất (Jun Da)": "6035.0", "Tần Suất % (Jun Da)": "99.9831528046", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 青", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅青", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "青", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锖", "Unihan_Traditional (Chữ Phồn thể)": "錆", "Pinyin_Xie": "qiāng", "Âm Hán Việt_Xie": "thương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ màu sắc biến đổi trên bề mặt khoáng vật hoặc kim loại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锘', '{"9000": "6036.0", "Chữ Trung Quốc": "锘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 13 | nét | 锘 | nặc | tượng hình | nguyên tố nobeli (No) | 锘 là chữ tạo muộn để phiên âm tên nguyên tố nobeli (No, số nguyên tử 102). Bộ 金 chỉ kim loại; phần còn lại biểu âm nuò gần với \"No-bel\". Chưa có ghi nhận cấu tạo chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nặc\" (nobeli): bộ 金 + âm nuò — nguyên tố nhân tạo mang tên Nobel, người sáng lập giải Nobel. | Gương Hán-Việt | 锘元素 = nguyên tố nobeli | Mở khoá kiến thức | Biết 锘 nhận diện ngay nguyên tố No (nobeli) trong bảng tuần hoàn tiếng Trung.", "Tự nguyên_Xie": "锘 là chữ tạo muộn, dùng để phiên âm tên nguyên tố phóng xạ nhân tạo nobeli (No). Không có ghi chép glyph-origin trong Wiktionary. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố nobeli, No", "Hạng Tần Suất (Jun Da)": "6036.0", "Tần Suất % (Jun Da)": "99.9831791607", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 若", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅若", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "若", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锘", "Unihan_Traditional (Chữ Phồn thể)": "鍩", "Pinyin_Xie": "nuò", "Âm Hán Việt_Xie": "nặc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này được dùng làm danh từ để biểu thị nguyên tố hóa học nhân tạo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蝾', '{"9000": "6037.0", "Chữ Trung Quốc": "蝾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 15 | nét | 蝾 | vinh | tượng hình | thành phần của từ 蝾螈 (kỳ giông) | 蝾 là dạng rút gọn của 蠑 (chỉ dùng trong từ 蝾螈/蠑螈 — kỳ giông, sa giông). Cấu trúc chi tiết không được Wiktionary ghi nhận đầy đủ cho dạng giản thể này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vinh\" (trong 蝾螈, kỳ giông): bộ 虫 (sâu bọ/động vật nhỏ) — con vật trơn nhớt sống được cả trên cạn lẫn dưới nước. | Gương Hán-Việt | 蝾螈 (vinh nguyên) = kỳ giông, sa giông | Mở khoá kiến thức | Biết 蝾 nhận diện 蝾螈 (kỳ giông) — loài lưỡng cư trong văn bản sinh học tiếng Trung.", "Tự nguyên_Xie": "Theo Wiktionary, 蝾 (dạng chuẩn 蠑) là từ rút gọn của 蠑螈 (kỳ giông, sa giông — salamander/newt). Không có ghi chú cấu tạo glyph chi tiết trong nguồn học thuật. Chưa có nguồn học thuật rõ ràng cho dạng giản thể 蝾. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: vinh nguyên 蠑螈,蝾螈)", "Hạng Tần Suất (Jun Da)": "6037.0", "Tần Suất % (Jun Da)": "99.9832055167", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 荣", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫荣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "荣", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蝾", "Unihan_Traditional (Chữ Phồn thể)": "蠑", "Pinyin_Xie": "róng", "Âm Hán Việt_Xie": "vinh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với chữ khác để tạo thành danh từ ghép chỉ loài động vật lưỡng cư. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('糌', '{"9000": "6038.0", "Chữ Trung Quốc": "糌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 15 | nét | 糌 | tán | tượng hình | thành phần của từ 糌粑 (tsampa — bánh lúa mạch Tây Tạng) | 糌 là chữ tạo muộn, dùng gần như độc quyền trong từ 糌粑 (tsampa). Bộ 米 (gạo/ngũ cốc) gợi tính chất thực phẩm. Không có ghi chú cấu tạo trong nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tán\" (tsampa): bộ 米 (gạo ngũ cốc) — bột lúa mạch rang của người Tây Tạng, ăn kèm trà bơ yak. | Gương Hán-Việt | 糌粑 (tán ba) = tsampa, bánh lúa mạch Tây Tạng | Mở khoá kiến thức | Biết 糌 nhận diện 糌粑 — món ăn truyền thống Tây Tạng trong văn bản văn hoá/ẩm thực.", "Tự nguyên_Xie": "糌 là chữ tạo muộn không có glyph-origin trong Wiktionary. Dùng chủ yếu trong từ 糌粑 (zānba) — tsampa, bánh làm từ lúa mạch rang xay của người Tây Tạng. Bộ 米 chỉ tính chất lương thực. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: ta ba 糌粑)", "Hạng Tần Suất (Jun Da)": "6038.0", "Tần Suất % (Jun Da)": "99.9832318727", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 昝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米昝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "糌", "Unihan_Traditional (Chữ Phồn thể)": "糌", "Pinyin_Xie": "zān", "Âm Hán Việt_Xie": "ta", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ trong cụm từ chỉ món ăn truyền thống của người Tạng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('柙', '{"9000": "6039.0", "Chữ Trung Quốc": "柙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 9 | nét | 柙 | hạp | tượng hình | cái cũi nhốt thú; bao đựng kiếm | 柙 là chữ không có ghi chú cấu tạo chi tiết trong Wiktionary. Bộ 木 (mộc) gợi vật làm bằng gỗ — cái cũi nhốt thú dữ hay bao gỗ đựng binh khí. Chưa xác định rõ hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hạp\" (cái cũi, hộp gỗ): bộ 木 (gỗ) — thanh gỗ kết thành cũi nhốt hổ báo, hoặc hộp đựng kiếm. | Gương Hán-Việt | 柙中虎 (hạp trung hổ) = hổ trong cũi | Mở khoá kiến thức | Biết 柙 đọc được điển tích cổ về thú dữ nhốt cũi và thuật ngữ vũ khí cổ.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary không có ghi chú glyph-origin chi tiết cho 柙. Chữ có bộ 木 (gỗ), nghĩa gốc là cái cũi gỗ nhốt thú dữ, hoặc bao kiếm. Hình tiểu triện còn lưu giữ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái cũi; bao đựng gươm", "Hạng Tần Suất (Jun Da)": "6039.0", "Tần Suất % (Jun Da)": "99.9832582288", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 甲", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木甲", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甲", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "柙", "Unihan_Traditional (Chữ Phồn thể)": "柙", "Pinyin_Xie": "xiá", "Âm Hán Việt_Xie": "hiệp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ làm tân ngữ sau động từ hoặc làm chủ ngữ trong câu cổ văn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('滹', '{"9000": "6040.0", "Chữ Trung Quốc": "滹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 14 | nét | 氵 | thuỷ | biểu nghĩa | nước | 虖 | biểu âm | 滹 = 氵 (Thuỷ, biểu nghĩa: nước) + 虖 (biểu âm, cho âm hū); chữ hình thanh. Dùng chủ yếu trong địa danh 滹沱河 (sông Hô Đà) ở tỉnh Hà Bắc, Trung Quốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hô\" (sông Hô Đà): 氵 (nước) + 虖 (âm hū) — con sông nổi tiếng ở Hà Bắc mang tên 滹沱. | Gương Hán-Việt | 滹沱河 (hô đà hà) = sông Hô Đà ở Hà Bắc | Mở khoá kiến thức | Biết 滹 đọc được địa danh 滹沱河 trong sử sách và địa lý Trung Quốc.", "Tự nguyên_Xie": "Lục thư thông | Theo Wiktionary, 滹 là chữ hình thanh: 氵 (nước, biểu nghĩa) + 虖 (biểu âm). Nghĩa duy nhất là tên một nhánh sông — 滹沱河 (Hô Đà Hà) ở tỉnh Hà Bắc. Cũng dùng làm họ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: hô đà 滹沱)", "Hạng Tần Suất (Jun Da)": "6040.0", "Tần Suất % (Jun Da)": "99.9832845848", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 虖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵虖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "虖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "滹", "Unihan_Traditional (Chữ Phồn thể)": "滹", "Pinyin_Xie": "hū", "Âm Hán Việt_Xie": "hô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ riêng trong địa danh hoặc tên gọi sông ngòi thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('睚', '{"9000": "6041.0", "Chữ Trung Quốc": "睚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 13 | nét | 目 | mục | biểu nghĩa | mắt | 厓 | nhai | biểu âm | 睚 = 目 (Mục, biểu nghĩa: mắt) + 厓 (Nhai, biểu âm); chữ hình thanh. Chỉ góc mắt hoặc cái nhìn ngang/sắc bén — dùng chủ yếu trong thành ngữ 睚眦必报.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhai\" (khoé mắt): 目 (mắt) + 厓 (âm nhai/yá) — khoé mắt nhíu lại trong cái nhìn tức giận, như trong 睚眦必报. | Gương Hán-Việt | 睚眦必报 (nhai tý tất báo) = thù vặt, nhỏ nhen | Mở khoá kiến thức | Biết 睚 đọc được thành ngữ 睚眦必报 — mô tả người thù dai, báo thù cả chuyện nhỏ nhặt.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 睚 là chữ hình thanh: 目 (mắt, biểu nghĩa) + 厓 (biểu âm). Nghĩa gốc là góc mắt (khoé mắt), cũng chỉ ánh mắt tức giận. Thường gặp trong thành ngữ 睚眦必报 (mới bị đôi mắt liếc cũng phải trả thù — người thù vặt). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vẹ mắt, góc mắt", "Hạng Tần Suất (Jun Da)": "6041.0", "Tần Suất % (Jun Da)": "99.9833109409", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 厓", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目厓", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "厓", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "睚", "Unihan_Traditional (Chữ Phồn thể)": "睚", "Pinyin_Xie": "yá", "Âm Hán Việt_Xie": "nhai", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ xuất hiện trong các thành ngữ cổ chỉ sự thù hằn hay cái nhìn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('莨', '{"9000": "6042.0", "Chữ Trung Quốc": "莨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 10 | nét | 莨 | lang | tượng hình | cây thảo dược 莨菪 (lang đãng) | 莨 không có ghi chú cấu tạo chi tiết trong Wiktionary. Bộ 艸 (thảo, cỏ cây) gợi đây là tên loại thực vật. Dùng chủ yếu trong từ 莨菪 (lang đãng — cây lỳ hoa).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lang\" (cây lang đãng): bộ 艸 (cây cỏ) — cây dược liệu/độc dược 莨菪, nhớ \"lang\" trong \"lang thang\" như cây dại. | Gương Hán-Việt | 莨菪 (lang đãng) = cây lỳ hoa, henbane | Mở khoá kiến thức | Biết 莨 nhận diện 莨菪 — tên thảo dược độc trong y học cổ truyền và dược lý học Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không có ghi chú glyph-origin chi tiết cho 莨. Chữ thuộc bộ 艸 (cỏ), chỉ cây 莨菪 (Scopolia japonica / henbane — cây lỳ hoa, có độc). Có hình tiểu triện còn lưu. Chưa có nguồn học thuật rõ ràng. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: lang đãng 莨菪)", "Hạng Tần Suất (Jun Da)": "6042.0", "Tần Suất % (Jun Da)": "99.9833631362", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 良", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹良", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "良", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "莨", "Unihan_Traditional (Chữ Phồn thể)": "莨", "Pinyin_Xie": "làng", "Âm Hán Việt_Xie": "lang, lương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong tên gọi các loại cây thảo dược hoặc thực vật học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('尻', '{"9000": "6043.0", "Chữ Trung Quốc": "尻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 尸 | Số nét | 5 | nét | 尸 | thi | biểu nghĩa | thân người | 九 | cửu | biểu âm | 尻 trong giáp cốt văn là chữ tượng hình — người có phần mông được đánh dấu. Đến triện thư phát triển thành chữ hình thanh: 尸 (Thi, biểu nghĩa: thân người) + 九 (Cửu, biểu âm).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khảo\" (xương cùng, mông): 尸 (thân người) + 九 (âm kāo) — phần cuối cột sống, xương cụt ở đáy lưng. | Gương Hán-Việt | 尻骨 (khảo cốt) = xương cụt, xương cùng | Mở khoá kiến thức | Biết 尻 đọc được thuật ngữ giải phẫu cổ như 尻骨 (xương cụt) trong y thư cổ điển.", "Tự nguyên_Xie": "Giáp cốt văn | Đại triện | Tiểu triện | Theo Wiktionary, trong giáp cốt văn 尻 là tượng hình (liushu=p): người có phần xương cụt/mông được làm nổi bật. Đến triện thư phát triển thành hình thanh: 尸 (thân người, biểu nghĩa) + 九 (biểu âm). Nghĩa gốc: xương cụt, mông. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xương cùng sau đít", "Hạng Tần Suất (Jun Da)": "6043.0", "Tần Suất % (Jun Da)": "99.9833889754", "GavinGrover_Once (Chiết tự trực tiếp)": "尸 + 九", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴尸九", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "九", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "尸", "Unihan_Simplified (Chữ Giản thể)": "尻", "Unihan_Traditional (Chữ Phồn thể)": "尻", "Pinyin_Xie": "kāo", "Âm Hán Việt_Xie": "khào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ bộ phận cơ thể người hoặc động vật trong y học cổ truyền. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('罨', '{"9000": "6044.0", "Chữ Trung Quốc": "罨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 网 | Số nét | 13 | nét | 罨 | yểm | tượng hình | lưới bắt cá; gạc chườm y tế | 罨 không có ghi chú cấu tạo chi tiết trong Wiktionary. Bộ 网/罒 (lưới) gợi công dụng: quăng lưới bắt cá, hoặc đắp gạc (chườm) trong y học. Chưa xác định rõ hội ý hay hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"yểm\" (lưới, chườm): bộ 罒 (lưới) — vừa là lưới ụp bắt cá, vừa là gạc ụp lên vết thương để chữa bệnh. | Gương Hán-Việt | 罨法 (yểm pháp) = phép chườm nóng/lạnh trong y học cổ | Mở khoá kiến thức | Biết 罨 đọc được thuật ngữ y học cổ 罨法 (phép chườm) trong y thư cổ điển.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không có ghi chú glyph-origin chi tiết cho 罨. Chữ thuộc bộ 网/罒 (lưới), có hai nghĩa: (1) lưới quăng bắt cá; (2) gạc/túi chườm trong y học cổ (罨法 — phép chườm). Có hình tiểu triện còn lưu. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quăng lưới bắt cá", "Hạng Tần Suất (Jun Da)": "6044.0", "Tần Suất % (Jun Da)": "99.9834148147", "GavinGrover_Once (Chiết tự trực tiếp)": "罒 + 奄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱罒奄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "罒", "Unihan_Simplified (Chữ Giản thể)": "罨", "Unihan_Traditional (Chữ Phồn thể)": "罨", "Pinyin_Xie": "yǎn", "Âm Hán Việt_Xie": "ấp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ hành động úp, đắp thuốc hoặc danh từ chỉ dụng cụ đánh bắt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锔', '{"9000": "6045.0", "Chữ Trung Quốc": "锔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 12 | nét | 金 | kim | biểu nghĩa | kim loại | 局 | cục | biểu âm | 锔 = 金 (Kim, biểu nghĩa: kim loại) + 局 (Cục, biểu âm); chữ hình thanh. Chỉ đinh kim loại dùng để gắn, vá đồ sứ/gốm bị vỡ — nghề thủ công truyền thống của Trung Quốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cúc\" (đinh vá gốm): 金 (kim loại) + 局 (cục, âm jū) — chiếc đinh cong kẹp mảnh sứ vỡ lại, nghề 锔瓷 độc đáo của Trung Quốc. | Gương Hán-Việt | 锔瓷 (cúc từ) = nghề vá đồ sứ bằng đinh kim loại | Mở khoá kiến thức | Biết 锔 nhận diện nghề thủ công 锔瓷 (vá gốm) và ký hiệu nguyên tố curium trong văn bản hoá học.", "Tự nguyên_Xie": "Theo Wiktionary (dạng 鋦), 锔 là chữ hình thanh: 金 (kim loại, biểu nghĩa) + 局 (biểu âm). Nghĩa chính: đinh hình chữ U bằng kim loại dùng để kẹp, vá đồ sứ bị nứt vỡ (nghề 锔瓷). Hiện nay cũng là ký hiệu cho nguyên tố curium (Cm). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đinh để vá đồ (bát đĩa) vỡ; gắn đồ vỡ", "Hạng Tần Suất (Jun Da)": "6045.0", "Tần Suất % (Jun Da)": "99.9834406539", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 局", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅局", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "局", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锔", "Unihan_Traditional (Chữ Phồn thể)": "鋦", "Pinyin_Xie": "jū", "Âm Hán Việt_Xie": "cư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Dùng làm động từ chỉ việc vá đồ gốm sứ hoặc danh từ chỉ cái ghim sắt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('筲', '{"9000": "6046.0", "Chữ Trung Quốc": "筲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 13 | nét | 筲 | sáo | tượng hình | cái rá vo gạo, giỏ tre nhỏ | 筲 không có ghi chú cấu tạo chi tiết trong Wiktionary. Bộ 竹 (trúc, tre) gợi đây là đồ dùng làm bằng tre — cái rá hoặc giỏ nhỏ. Dùng chủ yếu trong thành ngữ 斗筲 (dung lượng nhỏ, khả năng hạn chế).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sáo\" (cái rá, giỏ tre nhỏ): bộ 竹 (tre) — cái rá vo gạo hàng ngày, nhỏ bé hữu ích trong bếp. | Gương Hán-Việt | 斗筲 (đấu sáo) = tài năng nhỏ bé; 筲箕 (sáo ki) = cái rá | Mở khoá kiến thức | Biết 筲 đọc được thành ngữ 斗筲之才 (người tài cán nhỏ bé) và từ 筲箕 (cái rá vo gạo).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không có ghi chú glyph-origin chi tiết cho 筲. Chữ thuộc bộ 竹 (tre), chỉ cái rá vo gạo hoặc thùng nhỏ làm từ tre. Thường gặp trong thành ngữ 斗筲之才 (tài cán nhỏ bé như cái rá). Có hình tiểu triện còn lưu. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái rá vo gạo", "Hạng Tần Suất (Jun Da)": "6046.0", "Tần Suất % (Jun Da)": "99.9834664932", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 肖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮肖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "肖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "筲", "Unihan_Traditional (Chữ Phồn thể)": "䈰", "Pinyin_Xie": "shāo", "Âm Hán Việt_Xie": "sao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ dụng cụ đựng hoặc vo gạo thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('妣', '{"9000": "6047.0", "Chữ Trung Quốc": "妣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 7 | nét | 妣 | tỉ | tượng hình | mẹ đã qua đời | 妣 không có ghi chú cấu tạo chi tiết trong Wiktionary nhưng thuộc bộ 女 (nữ). Là tôn xưng kính cẩn cho người mẹ đã khuất, đối xứng với 考 (khảo — cha đã khuất). Giáp cốt văn và kim văn có hình dạng cổ còn lưu giữ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tỉ\" (mẹ đã khuất): bộ 女 (phụ nữ) — từ tôn xưng trang trọng nhất cho mẹ trong văn ngôn cổ, như \"tỉ đại nhân\" trên bia mộ. | Gương Hán-Việt | 考妣 (khảo tỉ) = cha mẹ đã khuất; 先妣 (tiên tỉ) = mẹ đã mất | Mở khoá kiến thức | Biết 妣 đọc được văn khắc bia mộ cổ, tế văn và sử sách khi nói về cha mẹ đã khuất.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Tiểu triện | Lục thư thông | Wiktionary không có ghi chú glyph-origin chi tiết cho 妣. Chữ thuộc bộ 女, là từ tôn xưng dùng trong văn ngôn để chỉ người mẹ đã mất. Cặp đôi truyền thống: 考妣 (khảo tỉ) = cha mẹ đã khuất. Có hình giáp cốt và kim văn còn lưu. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mẹ đã chết", "Hạng Tần Suất (Jun Da)": "6047.0", "Tần Suất % (Jun Da)": "99.9834923324", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 比", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女比", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "比", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "妣", "Unihan_Traditional (Chữ Phồn thể)": "妣", "Pinyin_Xie": "bǐ", "Âm Hán Việt_Xie": "tỷ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn cúng hoặc trên bia mộ để chỉ người mẹ đã khuất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('砘', '{"9000": "6048.0", "Chữ Trung Quốc": "砘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 9 | nét | 砘 | độn | tượng hình | nông cụ lèn đất | 砘 không có ghi chú cấu tạo chi tiết trong nguồn học thuật. Bộ 石 (thạch, đá) gợi đây là nông cụ làm từ đá hoặc đất dùng để lèn chặt mặt đất sau khi gieo hạt. Chưa xác định được rõ hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"độn\" (nông cụ lèn đất): bộ 石 (đá) — hòn đá hình trụ lăn trên ruộng để lèn chặt hạt giống vừa gieo. | Gương Hán-Việt | 砘车 (độn xa) = xe lăn lèn đất nông nghiệp | Mở khoá kiến thức | Biết 砘 nhận diện thuật ngữ nông nghiệp cổ 砘车 trong sách canh tác truyền thống.", "Tự nguyên_Xie": "砘 không có glyph-origin trong Wiktionary. Chữ thuộc bộ 石 (đá), chỉ loại nông cụ hình trụ tròn dùng để lèn chặt mặt đất sau khi gieo hạt (砘车 — xe lèn đất). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lèn đất; lèn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 屯", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石屯", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "屯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "砘", "Unihan_Traditional (Chữ Phồn thể)": "砘", "Pinyin_Xie": "dùn", "Âm Hán Việt_Xie": "đốn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Dùng làm động từ chỉ việc lèn đất hoặc danh từ chỉ cái trục lăn đất. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谳', '{"9000": "6049.0", "Chữ Trung Quốc": "谳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 15 | nét | 言 | ngôn | biểu nghĩa | lời nói, tuyên bố | 獻 | hiến | biểu âm | 谳 = 言 (Ngôn, biểu nghĩa: lời nói, tuyên bố) + 獻 (Hiến, biểu âm); chữ hình thanh. Chỉ hành động tuyên án, kết tội — lời phán xét chính thức của quan toà.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngãi\" (tuyên án): 言 (lời nói tuyên bố) + 獻 (âm yàn) — quan toà lên tiếng (言) để tuyên bố bản án. | Gương Hán-Việt | 定谳 (định ngãi) = kết án chính thức; 谳狱 (ngãi ngục) = xét xử vụ án | Mở khoá kiến thức | Biết 谳 đọc được thuật ngữ pháp luật cổ trong sử sách và văn bản tư pháp truyền thống Trung Quốc.", "Tự nguyên_Xie": "Theo Wiktionary (dạng 讞), 谳 là chữ hình thanh: 言 (lời nói, biểu nghĩa) + 獻 (biểu âm). Nghĩa: tuyên án, kết tội, ra phán quyết. Dùng trong văn ngôn pháp lý cổ: 定讞 (định luận tội), 讞獄 (xử vụ án). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nghị tội, luận tội, kết án", "Hạng Tần Suất (Jun Da)": "6049.0", "Tần Suất % (Jun Da)": "99.983544011", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 献", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠献", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "献", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "谳", "Unihan_Traditional (Chữ Phồn thể)": "讞", "Pinyin_Xie": "yàn", "Âm Hán Việt_Xie": "nghiện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ trong tư pháp thời cổ để chỉ việc thẩm án. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钽', '{"9000": "6050.0", "Chữ Trung Quốc": "钽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 10 | nét | 钽 | thản | tượng hình | nguyên tố tantan (Ta) | 钽 là chữ tạo muộn để phiên âm tên nguyên tố tantan (Ta, số nguyên tử 73). Bộ 金 (kim loại) chỉ tính chất kim loại; phần còn lại biểu âm tǎn. Không có ghi chú cấu tạo chi tiết trong nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thản\" (tantan): bộ 金 (kim loại) — kim loại cứng màu xanh xám, dùng trong tụ điện và dụng cụ y tế. | Gương Hán-Việt | 钽元素 = nguyên tố tantan | Mở khoá kiến thức | Biết 钽 nhận diện nguyên tố Ta (tantan) trong văn bản hoá học và kỹ thuật điện tử tiếng Trung.", "Tự nguyên_Xie": "钽 là chữ tạo muộn, dùng để phiên âm tên nguyên tố tantan (Ta). Không có glyph-origin trong Wiktionary. Tantan được đặt tên theo Tantalus trong thần thoại Hy Lạp. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố tantan, Ta", "Hạng Tần Suất (Jun Da)": "6050.0", "Tần Suất % (Jun Da)": "99.9835698502", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 旦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅旦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钽", "Unihan_Traditional (Chữ Phồn thể)": "鉭", "Pinyin_Xie": "tǎn", "Âm Hán Việt_Xie": "đán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong hóa học để chỉ nguyên tố kim loại tantan. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鈤', '{"9000": "6051.0", "Chữ Trung Quốc": "鈤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 12 | nét | 鈤 | nhật | tượng hình | tên cũ của nguyên tố radi (Ra) hoặc germani (Ge) | 鈤 là chữ tạo muộn, dạng phồn thể, từng dùng để đặt tên cho nguyên tố radi (Ra) hoặc germani (Ge) trong hệ thống ký hiệu hoá học Trung Quốc cũ. Bộ 金 chỉ kim loại; phần 日 (nhật) biểu âm rì. Không có ghi chú học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhật\" (tên cũ radi/germani): bộ 金 (kim loại) + 日 (nhật, âm rì) — chữ hoá học tạo muộn, nay ít dùng. | Gương Hán-Việt | 鈤 — tên cũ của nguyên tố radi hoặc germani trong hoá học Hán tự | Mở khoá kiến thức | Biết 鈤 nhận diện ký hiệu hoá học cổ trong tài liệu khoa học Trung Quốc đầu thế kỷ 20.", "Tự nguyên_Xie": "鈤 là chữ tạo muộn, không có glyph-origin trong Wiktionary. Từng là tên cũ trong hệ thống hoá học Hán tự cho nguyên tố radi (Ra) hoặc germani (Ge) — nay các ký hiệu này đã thay đổi. Bộ 金 chỉ kim loại. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tên gọi cũ của nguyên tố radi, Ra; tên gọi cũ của nguyên tố germani, Ge", "Hạng Tần Suất (Jun Da)": "6051.0", "Tần Suất % (Jun Da)": "99.9835956895", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 日", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金日", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "日", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鈤", "Unihan_Traditional (Chữ Phồn thể)": "鈤", "Pinyin_Xie": "rì", "Âm Hán Việt_Xie": "nhật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong hóa học cổ để chỉ nguyên tố radi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鄹', '{"9000": "6052.0", "Chữ Trung Quốc": "鄹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 16 | nét | 鄹 | trâu | tượng hình | tên ấp Trâu (nơi sinh Khổng Tử) | 鄹 không có ghi chú cấu tạo chi tiết trong Wiktionary. Bộ 邑 (ấp, vùng đất) cho thấy đây là địa danh. Là tên ấp Trâu thuộc huyện Khúc Phụ nước Lỗ — nơi sinh của Khổng Tử.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trâu\" (ấp Trâu): bộ 邑 (ấp, đất) — địa danh lịch sử gắn với cha của Khổng Tử, nhớ Trâu Ấp = quê nhà nhà Khổng. | Gương Hán-Việt | 鄹邑 (trâu ấp) = ấp Trâu, quê cha Khổng Tử | Mở khoá kiến thức | Biết 鄹 đọc được địa danh cổ trong sử sách Xuân Thu và các ghi chép về Khổng Tử.", "Tự nguyên_Xie": "Lục thư thông | Wiktionary chỉ ghi nhận 鄹 là địa danh (rfdef). Chữ thuộc bộ 邑 (ấp), chỉ ấp Trâu (鄹邑) ở huyện Khúc Phụ, nước Lỗ thời Xuân Thu — nơi cha của Khổng Tử từng làm quan. Chưa có nguồn học thuật ghi chú cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Ấp Châu ở huyện Khúc Phụ của nước Lỗ thời xưa (nay thuộc tỉnh Sơn Đông của Trung Quốc)", "Hạng Tần Suất (Jun Da)": "6052.0", "Tần Suất % (Jun Da)": "99.9836726905", "GavinGrover_Once (Chiết tự trực tiếp)": "聚 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰聚阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "聚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "鄹", "Unihan_Traditional (Chữ Phồn thể)": "鄹", "Pinyin_Xie": "zōu", "Âm Hán Việt_Xie": "châu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ riêng chỉ địa danh cổ hoặc họ của người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('菡', '{"9000": "6053.0", "Chữ Trung Quốc": "菡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 函 | hàm | biểu âm | 菡 = 艹 (Thảo, biểu nghĩa: thực vật) + 函 (Hàm, biểu âm); chữ hình thanh. Dùng độc quyền trong từ 菡萏 (hạm đạm) — nụ hoa sen chưa nở.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hạm\" (nụ sen trong 菡萏): 艹 (thực vật) + 函 (hàm, âm hàn) — nụ sen phong kín như chiếc hộp (函) chứa vẻ đẹp bên trong. | Gương Hán-Việt | 菡萏 (hạm đạm) = nụ hoa sen; hoa sen trong thơ ca cổ | Mở khoá kiến thức | Biết 菡 đọc được từ 菡萏 trong thơ ca và văn chương cổ điển Trung Quốc về hoa sen.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 菡 là chữ hình thanh: 艸/艹 (cỏ/thực vật, biểu nghĩa) + 函 (biểu âm). Chỉ dùng trong từ 菡萏 — nụ hoa sen (lotus bud). Từ 菡萏 xuất hiện trong thơ ca cổ điển Trung Quốc để chỉ sen chưa nở, biểu tượng của vẻ đẹp thuần khiết. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: hạm đạm 菡萏)", "Hạng Tần Suất (Jun Da)": "6053.0", "Tần Suất % (Jun Da)": "99.9836980129", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "菡", "Unihan_Traditional (Chữ Phồn thể)": "菡", "Pinyin_Xie": "hàn", "Âm Hán Việt_Xie": "hạm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với chữ đạm để tạo thành từ ghép chỉ hoa sen. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('崦', '{"9000": "6054.0", "Chữ Trung Quốc": "崦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 11 | nét | 崦 | yêm | tượng hình | tên núi huyền thoại 崦嵫, nơi mặt trời lặn | 崦 không có ghi chú cấu tạo chi tiết trong Wiktionary. Bộ 山 (sơn, núi) gợi đây là tên địa danh núi. Dùng chủ yếu trong từ 崦嵫 — núi huyền thoại ở phương Tây nơi mặt trời lặn xuống.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"yêm\" (núi Yêm Tư, nơi mặt trời lặn): bộ 山 (núi) — ngọn núi huyền thoại ở tây phương, nơi ánh mặt trời tắt mỗi tối. | Gương Hán-Việt | 崦嵫 (yêm tư) = núi huyền thoại nơi mặt trời lặn; 日薄崦嵫 = mặt trời gần lặn (tuổi già) | Mở khoá kiến thức | Biết 崦 đọc được thành ngữ 日薄崦嵫 (mặt trời gần lặn — ẩn dụ tuổi già) trong thơ văn cổ điển.", "Tự nguyên_Xie": "Wiktionary không có ghi chú glyph-origin chi tiết cho 崦. Chữ thuộc bộ 山 (núi), dùng chủ yếu trong từ 崦嵫 — ngọn núi huyền thoại ở vùng Cam Túc, theo truyền thuyết là nơi mặt trời lặn vào mỗi đêm. Cũng có nghĩa thứ cấp: núi nói chung (cổ ngữ). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: yêm tư 崤嵫)", "Hạng Tần Suất (Jun Da)": "6054.0", "Tần Suất % (Jun Da)": "99.9837233354", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 奄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰山奄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "崦", "Unihan_Traditional (Chữ Phồn thể)": "崦", "Pinyin_Xie": "yān", "Âm Hán Việt_Xie": "yêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với chữ tư để chỉ ngọn núi huyền thoại trong văn học cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('狺', '{"9000": "6055.0", "Chữ Trung Quốc": "狺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 10 | nét | 犬 | khuyển | biểu nghĩa | chó | 言 | ngôn | biểu âm | 狺 = 犬 (Khuyển, biểu nghĩa: chó) + 言 (Ngôn, biểu âm); chữ hình thanh. Chỉ tiếng chó gầm gừ, sủa hung hăng. Có thể ban đầu viết là 㹞 (犬+斤).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngân\" (tiếng chó gầm): 犬 (chó) + 言 (lời nói, âm yín) — chó \"lên tiếng\" (言) gầm gừ hung dữ. | Gương Hán-Việt | 狺狺 (ngân ngân) = tiếng chó sủa liên tiếp dữ dội | Mở khoá kiến thức | Biết 狺 nhận diện từ láy 狺狺 mô tả tiếng chó hung hăng trong văn thơ cổ điển.", "Tự nguyên_Xie": "Theo Wiktionary, 狺 là chữ hình thanh: 犬 (chó, biểu nghĩa) + 言 (biểu âm). Có thể ban đầu viết 㹞 với 斤 làm biểu âm. Nghĩa: tiếng chó sủa dữ, gầm gừ. Dùng trong từ láy 狺狺 — tiếng chó sủa liên tiếp. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng chó gầm gừ", "Hạng Tần Suất (Jun Da)": "6055.0", "Tần Suất % (Jun Da)": "99.9837486579", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 言", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭言", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "言", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "狺", "Unihan_Traditional (Chữ Phồn thể)": "狺", "Pinyin_Xie": "yín", "Âm Hán Việt_Xie": "ngân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường dùng làm động từ mô tả tiếng chó sủa gầm gừ hoặc xuất hiện trong từ ghép. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('杌', '{"9000": "6056.0", "Chữ Trung Quốc": "杌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 7 | nét | 杌 | ngột | tượng hình | gốc cây cụt; ghế đẩu vuông | 杌 không có ghi chú cấu tạo chi tiết trong Wiktionary. Bộ 木 (mộc, gỗ/cây) cho thấy liên quan đến gỗ/cây. Có hai nghĩa chính: (1) gốc cây cụt (cây vô cành lá); (2) chiếc ghế đẩu nhỏ vuông làm bằng gỗ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngột\" (gốc cây cụt, ghế đẩu): bộ 木 (gỗ) — gốc cây cụt trơ trọi, hoặc chiếc ghế đẩu gỗ vuông không có lưng tựa. | Gương Hán-Việt | 杌隉 (ngột niết) = không ổn định, bất an; 杌子 (ngột tử) = ghế đẩu | Mở khoá kiến thức | Biết 杌 đọc được từ 杌隉 (bất ổn) trong sử sách và từ ghép 杌凳/杌子 (ghế đẩu) trong văn xuôi.", "Tự nguyên_Xie": "Wiktionary không có ghi chú glyph-origin chi tiết cho 杌. Chữ thuộc bộ 木 (gỗ), có nghĩa gốc cây cụt — cây không có cành hoặc cây chết trơ gốc. Nghĩa phái sinh: ghế đẩu vuông (杌子/杌凳). Dùng trong từ 杌隉 (ngột niết — không ổn định, dao động). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: ngột niết 杌隉)", "Hạng Tần Suất (Jun Da)": "6056.0", "Tần Suất % (Jun Da)": "99.9837739803", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 兀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木兀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "杌", "Unihan_Traditional (Chữ Phồn thể)": "杌", "Pinyin_Xie": "wù", "Âm Hán Việt_Xie": "ngột", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ loại ghế đôn gỗ nhỏ hoặc làm tính từ chỉ sự bất an. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('秭', '{"9000": "6057.0", "Chữ Trung Quốc": "秭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 9 | nét | 禾 | hoà | biểu nghĩa | lúa, ngũ cốc | 𠂔 | biểu âm | 秭 = 禾 (Hoà, biểu nghĩa) + 𠂔 (biểu âm, không có âm đọc Hán-Việt chuẩn); chữ hình thanh. Dùng làm từ số học Hán cổ chỉ số rất lớn (10⁹ đến 10²⁴ tuỳ hệ đếm), và là tên đất Tỉ Quy (Zigui) ở Hồ Bắc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tỉ\" (tỉ tỉ, số lớn): bộ 禾 (lúa) + biểu âm — số đơn vị lớn trong toán học cổ, và là quê hương của Khuất Nguyên (Tỉ Quy). | Gương Hán-Việt | 秭歸 (tỉ quy) = huyện Tỉ Quy, quê Khuất Nguyên; một tỉ (10⁹) | Mở khoá kiến thức | Biết 秭 đọc được đơn vị số học cổ Trung Quốc và địa danh 秭歸 trong thơ lịch sử.", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | Theo Wiktionary, 秭 là chữ hình thanh: 禾 (lúa, biểu nghĩa) + 𠂔 (biểu âm). Dùng làm số học: chỉ các đơn vị rất lớn (10⁹, 10¹², hoặc 10²⁴ tuỳ hệ đếm cổ điển). Cũng là tên địa danh 秭歸 (Zigui, Hồ Bắc) — nơi sinh nhà thơ Khuất Nguyên. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một tỉ; tỉ; Tỉ Quy (tên đất, ở tỉnh Hồ Bắc, Trung Quốc)", "Hạng Tần Suất (Jun Da)": "6057.0", "Tần Suất % (Jun Da)": "99.9837993028", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "秭", "Unihan_Traditional (Chữ Phồn thể)": "秭", "Pinyin_Xie": "zǐ", "Âm Hán Việt_Xie": "tỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Số từ | 数词 | Dùng làm số từ biểu thị một lượng số cực kỳ lớn trong toán học cổ Trung Hoa. | Số từ | 数词 | Chỉ số lượng hoặc thứ tự. Hầu như không đứng thẳng trước danh từ mà phải chèn lượng từ ở giữa: 两个人.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('舯', '{"9000": "6058.0", "Chữ Trung Quốc": "舯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 舟 | Số nét | 10 | nét | 舯 | trung | tượng hình | điểm giữa thuyền (midship) | 舯 không có ghi chú cấu tạo chi tiết trong nguồn học thuật. Bộ 舟 (chu, thuyền) gợi đây là thuật ngữ hàng hải. Chỉ điểm giữa thuyền — cả về chiều dài lẫn chiều cao.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trung\" (điểm giữa thuyền): bộ 舟 (thuyền) — vị trí trung tâm của con tàu, quan trọng nhất trong điều hướng. | Gương Hán-Việt | 舯部 (trung bộ) = phần giữa tàu; midship section | Mở khoá kiến thức | Biết 舯 đọc được thuật ngữ đóng tàu và hàng hải trong tài liệu kỹ thuật tiếng Trung.", "Tự nguyên_Xie": "舯 không có glyph-origin trong Wiktionary. Chữ thuộc bộ 舟 (thuyền), là thuật ngữ hàng hải chỉ vị trí giữa tàu thuyền — midship trong tiếng Anh. Chưa có nguồn học thuật ghi chú cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "điểm giữa chiều cao thuyền; giữa thuyền (độ dài thuyền)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "舟 + 中", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舟中", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "中", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舟", "Unihan_Simplified (Chữ Giản thể)": "舯", "Unihan_Traditional (Chữ Phồn thể)": "舯", "Pinyin_Xie": "zhōng", "Âm Hán Việt_Xie": "trung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Từ chỉ phương vị | 方位词 | Thường dùng làm danh từ hoặc từ chỉ phương vị để xác định vị trí ở giữa thân tàu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Từ chỉ phương vị | 方位词 | Chỉ vị trí và đứng SAU danh từ — 桌子上, 家里 — chứ không đứng trước như ''trên bàn'', ''trong nhà''. Thường đi cùng 在.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('豇', '{"9000": "6059.0", "Chữ Trung Quốc": "豇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 豆 | Số nét | 10 | nét | 豆 | đậu | biểu nghĩa | đậu, đỗ | 工 | công | biểu âm | 豇 = 豆 (Đậu, biểu nghĩa: đậu/đỗ) + 工 (Công, biểu âm, cho âm jiāng); chữ hình thanh. Chỉ loại đậu đũa (豇豆 — cowpea/yardlong bean) — loại rau phổ biến trong ẩm thực Trung Quốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giang\" (đậu đũa): 豆 (đậu) + 工 (công, âm gōng/jiāng) — hạt đậu dài như cái công cụ (工), tức đậu đũa dài. | Gương Hán-Việt | 豇豆 (giang đậu) = đậu đũa, đậu bắp dài | Mở khoá kiến thức | Biết 豇 nhận diện 豇豆 (đậu đũa) trên thực đơn và trong tài liệu nông nghiệp tiếng Trung.", "Tự nguyên_Xie": "Theo Wiktionary, 豇 là chữ hình thanh: 豆 (đậu, biểu nghĩa) + 工 (biểu âm). Chỉ dùng trong từ 豇豆 — đậu đũa (cowpea, Vigna unguiculata). Từ gốc không dùng độc lập. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giống đậu lang lổ", "Hạng Tần Suất (Jun Da)": "6059.0", "Tần Suất % (Jun Da)": "99.9838499478", "GavinGrover_Once (Chiết tự trực tiếp)": "豆 + 工", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰豆工", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "工", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "豆", "Unihan_Simplified (Chữ Giản thể)": "豇", "Unihan_Traditional (Chữ Phồn thể)": "豇", "Pinyin_Xie": "jiāng", "Âm Hán Việt_Xie": "giang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ các loại cây thuộc họ đậu, phổ biến nhất là đậu đũa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲵', '{"9000": "6060.0", "Chữ Trung Quốc": "鲵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 16 | nét | 魚 | ngư | biểu nghĩa | cá (rộng nghĩa: động vật thuỷ sinh) | 兒 | nhi | biểu âm | 鲵 = 魚 (Ngư, biểu nghĩa: cá/động vật thuỷ sinh) + 兒 (Nhi, biểu âm, cho âm ní); chữ hình thanh. Chỉ con cá giống hoặc con kỳ giông khổng lồ (大鲵 — giant salamander).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nghê\" (kỳ giông thuỷ sinh): 魚 (cá/thuỷ sinh) + 兒 (nhi, âm ní) — sinh vật dưới nước trông như cá con (兒) nhưng thực ra là loài lưỡng cư. | Gương Hán-Việt | 大鲵 (đại nghê) = kỳ giông khổng lồ Trung Quốc | Mở khoá kiến thức | Biết 鲵 nhận diện 大鲵 — kỳ giông khổng lồ Trung Quốc, loài lưỡng cư bảo tồn cấp quốc gia.", "Tự nguyên_Xie": "Theo Wiktionary, 鲵 là chữ hình thanh: 魚 (cá, biểu nghĩa) + 兒 (biểu âm). Nghĩa: con cá nhỏ (kỳ giông thủy) hoặc cụ thể là 大鲵 (kỳ giông khổng lồ Trung Quốc — Chinese giant salamander, loài lưỡng cư lớn nhất thế giới). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá kình, cá voi", "Hạng Tần Suất (Jun Da)": "6060.0", "Tần Suất % (Jun Da)": "99.9838752702", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 兒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼兒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲵", "Unihan_Traditional (Chữ Phồn thể)": "鯢", "Pinyin_Xie": "ní", "Âm Hán Việt_Xie": "nghê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ loài kỳ giông nước ngọt hoặc loài cá voi nhỏ thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蘧', '{"9000": "6061.0", "Chữ Trung Quốc": "蘧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 19 | nét | 蘧 | cừ | tượng hình | cây 蘧麥 (dianthus); cảm giác vui mừng bất ngờ | 蘧 không có ghi chú cấu tạo chi tiết trong Wiktionary. Bộ 艸 (thảo, cỏ/thực vật) cho thấy liên quan thực vật. Dùng trong: 蘧麥 (cừ mạch — cây cẩm chướng), 蘧然 (giật mình vui mừng), 蘧蒢 (người bướng bỉnh trong từ cổ), và là họ tên người.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cừ\" (tên cây, niềm vui bất ngờ): bộ 艸 (cỏ cây) — nhớ Cừ Viên (蘧瑗), hiền thần nước Vệ nổi tiếng biết nhận sai và sửa lỗi. | Gương Hán-Việt | 蘧然 (cừ nhiên) = giật mình vui mừng; 蘧瑗知非 (cừ viên tri phi) = biết lỗi của mình | Mở khoá kiến thức | Biết 蘧 đọc được điển tích 蘧瑗知非 (Cừ Viên biết lỗi mình) — điển cố về sự tự soi bản thân trong văn học cổ.", "Tự nguyên_Xie": "Wiktionary không có ghi chú glyph-origin chi tiết cho 蘧. Chữ thuộc bộ 艸 (cỏ). Có nhiều nghĩa: (1) 蘧麥 — tên cây (dianthus); (2) 蘧然 — vui mừng bất ngờ (cảm giác giật mình dễ chịu); (3) họ tên cổ nổi tiếng (Cừ Viên — hiền tài nước Vệ thời Xuân Thu). Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: cử mạch 蘧麥)", "Hạng Tần Suất (Jun Da)": "6061.0", "Tần Suất % (Jun Da)": "99.9839005927", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 遽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹遽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "遽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蘧", "Unihan_Traditional (Chữ Phồn thể)": "蘧", "Pinyin_Xie": "qú", "Âm Hán Việt_Xie": "cừ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ họ người hoặc tính từ chỉ trạng thái kinh ngạc trong văn ngôn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('阚', '{"9000": "6062.0", "Chữ Trung Quốc": "阚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 14 | nét | 阚 | hám | tượng hình | tiếng gầm thét (hổ); liếc nhìn; họ Hám | 阚 không có ghi chú cấu tạo chi tiết trong Wiktionary. Bộ 门/門 (môn, cửa) có thể gợi ý nhìn qua cửa. Có nghĩa: nhìn xuống từ trên cao, tiếng gầm thét, hoặc dùng làm họ người.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hám\" (nhìn xuống từ cao, gầm thét): bộ 门 (cửa) — nhìn qua cửa xuống bên dưới, hoặc tiếng gầm thét như hổ. | Gương Hán-Việt | 阚姓 (họ Hám) = họ Hám trong danh sách họ Trung Quốc | Mở khoá kiến thức | Biết 阚 nhận diện họ người (阚) trong danh sách họ Trung Quốc và trong sử sách.", "Tự nguyên_Xie": "Wiktionary không có ghi chú glyph-origin chi tiết cho 阚. Chữ thuộc bộ 门 (cửa), có nghĩa: (1) nhìn xuống từ trên cao (khảm ngó); (2) tiếng gầm thét như hổ (dùng trong tên người); (3) họ Hám (阚). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dòm ngó", "Hạng Tần Suất (Jun Da)": "6062.0", "Tần Suất % (Jun Da)": "99.9839259152", "GavinGrover_Once (Chiết tự trực tiếp)": "门 + 敢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴门敢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "门", "Unihan_Simplified (Chữ Giản thể)": "阚", "Unihan_Traditional (Chữ Phồn thể)": "闞", "Pinyin_Xie": "hǎn", "Âm Hán Việt_Xie": "hám, giảm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Dùng làm động từ chỉ tiếng hổ gầm hoặc hành động dòm ngó, và làm danh từ chỉ họ người. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('悝', '{"9000": "6063.0", "Chữ Trung Quốc": "悝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 10 | nét | 悝 | lý | tượng hình | buồn rầu, ưu sầu; tên người (Lý Khôi) | 悝 không có ghi chú cấu tạo chi tiết trong Wiktionary. Bộ 心/忄 (tâm, lòng) cho thấy đây là chữ chỉ trạng thái tinh thần. Nghĩa: ưu sầu, buồn bã. Nổi tiếng là tên Lý Khôi (李悝) — nhà cải cách pháp luật thời Chiến Quốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lý\" (ưu sầu): bộ 忄 (tâm) — lòng buồn rầu, nhớ nhân vật lịch sử Lý Khôi (李悝) — nhà lập pháp đầu tiên Trung Quốc. | Gương Hán-Việt | 李悝 (Lý Khôi) = nhà cải cách pháp luật thời Chiến Quốc | Mở khoá kiến thức | Biết 悝 nhận diện tên Lý Khôi trong sử học và pháp chế Trung Quốc cổ đại.", "Tự nguyên_Xie": "Wiktionary không có ghi chú glyph-origin chi tiết cho 悝. Chữ thuộc bộ 心/忄 (tâm), nghĩa ưu sầu. Nổi tiếng nhất qua tên Lý Khôi (李悝) — học trò của Tử Hạ, nhà cải cách pháp luật nước Ngụy, soạn bộ Pháp Kinh đầu tiên. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên người); cười nhạo, cười chê", "Hạng Tần Suất (Jun Da)": "6063.0", "Tần Suất % (Jun Da)": "99.9839512376", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 里", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄里", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "里", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "悝", "Unihan_Traditional (Chữ Phồn thể)": "悝", "Pinyin_Xie": "kuī", "Âm Hán Việt_Xie": "lí, khôi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm động từ chỉ sự trêu chọc hoặc tính từ chỉ nỗi buồn rầu trong văn cổ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铌', '{"9000": "6064.0", "Chữ Trung Quốc": "铌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 10 | nét | 金 | kim | biểu nghĩa | kim loại | 尼 | ni | biểu âm | 铌 = 金 (Kim, biểu nghĩa: kim loại) + 尼 (Ni, biểu âm); chữ hình thanh. Chỉ nguyên tố niobi (Nb, số nguyên tử 41) — kim loại chuyển tiếp dùng trong hợp kim thép.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nỉ\" (niobi): 金 (kim loại) + 尼 (ni, âm ní) — kim loại mang tên Niobe, dùng tăng cường thép cho ngành hàng không. | Gương Hán-Việt | 铌元素 = nguyên tố niobi (Nb) | Mở khoá kiến thức | Biết 铌 nhận diện nguyên tố Nb (niobi) trong văn bản kỹ thuật và hoá học tiếng Trung.", "Tự nguyên_Xie": "铌 là chữ hình thanh: 金 (kim loại, biểu nghĩa) + 尼 (biểu âm, cho âm ní). Tên nguyên tố niobi (Nb), đặt tên theo Niobe trong thần thoại Hy Lạp. Chữ được tạo để phiên âm tên nguyên tố vào hệ thống Hán tự. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố niobi, Nb", "Hạng Tần Suất (Jun Da)": "6064.0", "Tần Suất % (Jun Da)": "99.9839765601", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 尼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅尼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铌", "Unihan_Traditional (Chữ Phồn thể)": "鈮", "Pinyin_Xie": "ní", "Âm Hán Việt_Xie": "ni", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong hóa học để chỉ nguyên tố kim loại niobi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缑', '{"9000": "6065.0", "Chữ Trung Quốc": "缑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 12 | nét | 缑 | câu | tượng hình | dây quấn cán kiếm; họ tên người | 缑 không có ghi chú cấu tạo chi tiết trong Wiktionary. Bộ 糸/纟 (mịch, sợi) gợi đây là vật làm từ sợi/dây. Nghĩa: dây da hoặc dây vải quấn quanh cán kiếm để tăng độ bám. Cũng dùng làm họ người và địa danh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"câu\" (dây quấn cán kiếm): bộ 纟 (sợi dây) — sợi dây da/vải quấn quanh cán kiếm để không trơn trượt khi chiến đấu. | Gương Hán-Việt | 缑氏 (câu thị) = tên đất cổ; dây quấn cán kiếm | Mở khoá kiến thức | Biết 缑 đọc được địa danh cổ 緱氏 và thuật ngữ vũ khí cổ trong sử sách Trung Quốc.", "Tự nguyên_Xie": "Wiktionary không có ghi chú glyph-origin chi tiết cho 缑. Chữ thuộc bộ 糸 (sợi), chỉ dây quấn cán kiếm (sword-grip wrapping). Cũng là họ người và tên đất (緱氏 — địa danh cổ). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dây quấn ở chuôi dao hay chuôi kiếm; họ Câu", "Hạng Tần Suất (Jun Da)": "6065.0", "Tần Suất % (Jun Da)": "99.9840266883", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 侯", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟侯", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "侯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "缑", "Unihan_Traditional (Chữ Phồn thể)": "緱", "Pinyin_Xie": "gōu", "Âm Hán Việt_Xie": "câu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ phần dây thừng quấn quanh chuôi kiếm hoặc làm họ của người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瑗', '{"9000": "6066.0", "Chữ Trung Quốc": "瑗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 13 | nét | 瑗 | viên | tượng hình | vòng ngọc lớn có lỗ rộng ở giữa | 瑗 không có ghi chú cấu tạo chi tiết trong Wiktionary. Bộ 玉/王 (ngọc) gợi đây là đồ vật bằng ngọc. Chỉ loại vòng ngọc hình khuyên với lỗ ở giữa rất lớn — phân biệt với 璧 (bích — vòng ngọc lỗ nhỏ). Cũng là tên người (Cừ Viên — 蘧瑗).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"viên\" (vòng ngọc lỗ lớn): bộ 玉 (ngọc) — vòng ngọc với lỗ thật lớn ở giữa, như vòng tròn (圆/viên) của đá quý. | Gương Hán-Việt | 瑗玉 (viên ngọc) = vòng ngọc lỗ lớn; 蘧瑗 (Cừ Viên) = tên hiền thần | Mở khoá kiến thức | Biết 瑗 đọc được tên ngọc khí cổ trong văn bản lễ chế và tên nhân vật 蘧瑗 trong sử học.", "Tự nguyên_Xie": "Wiktionary mô tả 瑗 là vòng ngọc (jade annulus) với lỗ lớn ở giữa. Chữ thuộc bộ 玉 (ngọc), không có ghi chú glyph-origin chi tiết. Phân biệt với 璧 (lỗ nhỏ). Dùng trong từ 蘧瑗知非 và làm tên người. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngọc viện", "Hạng Tần Suất (Jun Da)": "6066.0", "Tần Suất % (Jun Da)": "99.984051494", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 爰", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王爰", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "爰", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "瑗", "Unihan_Traditional (Chữ Phồn thể)": "瑗", "Pinyin_Xie": "yuàn", "Âm Hán Việt_Xie": "viện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng làm danh từ trong văn ngôn để chỉ một loại ngọc quý hoặc dùng trong tên người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('椹', '{"9000": "6067.0", "Chữ Trung Quốc": "椹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 13 | nét | 木 | mộc | biểu nghĩa | gỗ, cây | 甚 | thậm | biểu âm | 椹 = 木 (Mộc, biểu nghĩa: gỗ/cây) + 甚 (Thậm, biểu âm); chữ hình thanh. Có hai nghĩa: (1) quả dâu tằm chín (桑椹 — mulberry fruit); (2) thớt chặt/đe gỗ (dùng trong rèn và chặt thịt).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thẩm\" (quả dâu tằm / đe gỗ): 木 (cây) + 甚 (thậm, âm shèn) — cây dâu cho quả ngọt, hoặc khúc gỗ làm đế chặt thịt. | Gương Hán-Việt | 桑椹 (tang thẩm) = quả dâu tằm | Mở khoá kiến thức | Biết 椹 nhận diện 桑椹 (quả dâu tằm) trong văn bản ẩm thực và y học cổ truyền.", "Tự nguyên_Xie": "Theo Wiktionary, 椹 là chữ hình thanh: 木 (gỗ/cây, biểu nghĩa) + 甚 (biểu âm). Có hai nghĩa chính: (1) quả dâu tằm (桑椹 — sang thẩm, mulberry fruit); (2) đe/thớt chặt bằng gỗ. Cách đọc shèn (quả dâu), zhēn (thớt chặt). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quả dâu; trái dâu", "Hạng Tần Suất (Jun Da)": "6067.0", "Tần Suất % (Jun Da)": "99.9840762996", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 甚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木甚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "椹", "Unihan_Traditional (Chữ Phồn thể)": "椹", "Pinyin_Xie": "shèn", "Âm Hán Việt_Xie": "thẩm, châm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ quả của cây dâu tằm hoặc cái thớt gỗ dùng để kê chặt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('旰', '{"9000": "6068.0", "Chữ Trung Quốc": "旰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 7 | nét | 旰 | cán | tượng hình | chữ chỉ chiều tà, mặt trời đứng bóng muộn | 旰 là chữ độc thể, cấu trúc nội bộ chưa được Wiktionary giải mã; chưa rõ hình thanh hay hội ý. Chỉ thấy dạng tiểu triện lưu hanziyuan.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cán\": mặt trời 日 đã về chiều — ngày làm việc vất vả đến tận 旰 (cán) mới nghỉ. | Gương Hán-Việt | cán trong 宵旰 (tiêu cán — thức khuya dậy sớm, chỉ vua chăm chính sự) | Mở khoá kiến thức | Biết 旰 mở khoá thành ngữ 宵旰憂勤 (tiêu cán ưu cần — cần mẫn từ sáng đến tối).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary chỉ ghi {{Han etym}} mà không cung cấp phân tích cụ thể cho 旰. Dựa vào ý nghĩa ''chiều tà, hoàng hôn'' và bộ 日 (nhật, mặt trời), có thể suy đoán chữ liên quan đến thời điểm cuối ngày; chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chiều, hoàng hôn", "Hạng Tần Suất (Jun Da)": "6068.0", "Tần Suất % (Jun Da)": "99.9841011053", "GavinGrover_Once (Chiết tự trực tiếp)": "日 + 干", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰日干", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "干", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "旰", "Unihan_Traditional (Chữ Phồn thể)": "旰", "Pinyin_Xie": "gàn", "Âm Hán Việt_Xie": "cán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ chỉ thời gian trong ngày đã muộn hoặc trời đã về chiều tối. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('魆', '{"9000": "6069.0", "Chữ Trung Quốc": "魆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鬼 | Số nét | 14 | nét | 魆 | húc | tượng hình | tối om; đen tối hoàn toàn | 魆 là chữ hiếm, không có dữ liệu Wiktionary về cấu trúc. Bộ thủ 鬼 (quỷ) gợi liên tưởng đến bóng tối huyền bí, song phân tích chính thức còn thiếu; chưa rõ hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"húc\": bóng 鬼 ma phủ kín — trời 魆 húc tối om không thấy gì. | Gương Hán-Việt | húc trong 黑魆魆 (hắc húc húc — đen tối om om) | Mở khoá kiến thức | Biết 魆 mở khoá cụm 黑魆魆 miêu tả bóng tối dày đặc.", "Tự nguyên_Xie": "Wiktionary không có mục từ cho 魆. Bộ 鬼 (quỷ — ma quỷ, bóng tối) cho thấy chữ liên quan đến tối tăm, âm u; song không có nguồn học thuật xác nhận cấu trúc thêm. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tối om om; tối đen", "Hạng Tần Suất (Jun Da)": "6069.0", "Tần Suất % (Jun Da)": "99.984125911", "GavinGrover_Once (Chiết tự trực tiếp)": "鬼 + 戉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴鬼戉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "戉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鬼", "Unihan_Simplified (Chữ Giản thể)": "魆", "Unihan_Traditional (Chữ Phồn thể)": "魆", "Pinyin_Xie": "xū", "Âm Hán Việt_Xie": "huất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ để mô tả trạng thái tối đen như mực hoặc sự xuất hiện đột ngột. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蓍', '{"9000": "6070.0", "Chữ Trung Quốc": "蓍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 13 | nét | 蓍 | thi | tượng hình | cỏ thi dùng để bói | 蓍 không có phân tích hội ý hay hình thanh rõ ràng từ Wiktionary. Bộ thủ 艸 (thảo) xác nhận đây là loài thực vật; cấu trúc nội bộ chưa được giải mã chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thi\": cỏ 艸 dùng để gieo quẻ bói — 蓍 thi là cây thiêng của thầy bói xưa. | Gương Hán-Việt | thi trong 蓍龜 (thi quy — cỏ thi và mai rùa dùng bói) | Mở khoá kiến thức | Biết 蓍 mở khoá 蓍龜 (thi quy) — hai vật dụng bói toán cổ điển.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary ghi {{Han etym}} nhưng không cung cấp phân tích hội ý hay hình thanh. 蓍 là tên loài cỏ thi (Achillea millefolium), thuộc bộ 艸. Thường dùng cùng 龟 (quy — rùa) trong bói toán truyền thống. Chưa có nguồn học thuật xác nhận cấu trúc thêm. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỏ thi (lá nhỏ dài, có kẽ, hoa trắng hoặc đỏ phớt, gần giống hoa cúc, thường dùng để bói)", "Hạng Tần Suất (Jun Da)": "6070.0", "Tần Suất % (Jun Da)": "99.9841507167", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 耆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹耆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "耆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蓍", "Unihan_Traditional (Chữ Phồn thể)": "蓍", "Pinyin_Xie": "shī", "Âm Hán Việt_Xie": "thi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loại cỏ thân thảo thời cổ đại chuyên dùng trong nghi thức bói toán. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蕹', '{"9000": "6071.0", "Chữ Trung Quốc": "蕹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 16 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 雍 | ủng | biểu âm | hoà hợp, yên tĩnh (cho âm) | 蕹 là chữ hình thanh: 艹 (thảo) biểu nghĩa chỉ thực vật, 雍 (ủng) biểu âm cho âm đọc gốc. Chữ hình thanh điển hình trong nhóm tên cây cỏ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ủng\": rau 艹 mềm hoà hợp 雍 trong nước — 蕹 ủng chính là rau muống quen thuộc. | Gương Hán-Việt | ủng trong 蕹菜 (ủng thái — rau muống) | Mở khoá kiến thức | Biết 蕹 mở khoá 蕹菜 (ủng thái) — rau muống, món ăn phổ biến ở Đông Nam Á.", "Tự nguyên_Xie": "Theo Wiktionary, 蕹 = 艹 (thảo — cỏ, biểu nghĩa) + 雍 (ủng, biểu âm). Đây là chữ hình thanh chỉ loài cây rau muống (Ipomoea aquatica) — thực vật thuỷ sinh thân mềm, lá xanh. Bộ thảo xác nhận đây là thực vật, 雍 cho biết âm đọc gốc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rau muống", "Hạng Tần Suất (Jun Da)": "6071.0", "Tần Suất % (Jun Da)": "99.9841750056", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 雍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹雍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "雍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蕹", "Unihan_Traditional (Chữ Phồn thể)": "蕹", "Pinyin_Xie": "wèng", "Âm Hán Việt_Xie": "ung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ trong tổ hợp từ để chỉ cây rau muống. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('岜', '{"9000": "6072.0", "Chữ Trung Quốc": "岜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 7 | nét | 岜 | ba | tượng hình | núi đá; vách đá cao | 岜 là chữ mượn từ tiếng Tráng (Zhuang), không phải chữ Hán thuần tuý. Không phân tích theo hội ý hay hình thanh; đây là phiên âm chữ địa phương bā/bya nghĩa là đồi núi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ba\": chữ mượn tiếng Tráng — 岜 ba là núi đá cao vùng Tây Nam Trung Quốc. | Gương Hán-Việt | ba trong địa danh 岜沙 (Ba Sa — làng của người Miêu ở Quý Châu) | Mở khoá kiến thức | Biết 岜 giúp đọc địa danh vùng Quảng Tây và Quý Châu có chữ này.", "Tự nguyên_Xie": "Theo Wiktionary, 岜 là chữ mượn từ tiếng Tráng (Zhuang): từ ''bya'' nghĩa là đồi, núi. Đây không phải chữ Hán tạo theo lục thư truyền thống mà là chữ phương ngữ được tạo để ghi âm tiếng địa phương vùng Quảng Tây, Trung Quốc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "núi đá; thạch sơn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 巴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱山巴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "岜", "Unihan_Traditional (Chữ Phồn thể)": "岜", "Pinyin_Xie": "bā", "Âm Hán Việt_Xie": "ba", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ xuất hiện trong các địa danh ở vùng có nhiều núi đá vôi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钐', '{"9000": "6073.0", "Chữ Trung Quốc": "钐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 8 | nét | 钐 | sam | tượng hình | cái liềm lớn; nguyên tố samarium | 钐 (dạng phồn thể 釤) không có phân tích hội ý hay hình thanh từ Wiktionary. Bộ 金 (kim) xác nhận liên quan đến kim loại hay công cụ bằng kim loại, song cấu trúc nội bộ chưa được giải mã chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sam\": lưỡi kim 金 loại cắt tới tấp — 钐 sam là cái liềm lớn vung mạnh. | Gương Hán-Việt | sam trong 钐镰 (sam liêm — liềm lớn) hoặc tên nguyên tố samarium | Mở khoá kiến thức | Biết 钐 giúp nhận biết ký hiệu nguyên tố samarium (钐, Sm) trong hoá học Trung Quốc.", "Tự nguyên_Xie": "Wiktionary chỉ ghi {{Han etym}} cho 釤 (dạng gốc của 钐) mà không cung cấp phân tích chi tiết. Bộ 金 (kim — kim loại) cho thấy chữ chỉ công cụ hoặc chất liệu kim loại. Nghĩa hiện đại bao gồm cái liềm lớn và tên nguyên tố samarium (Sm). Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái liềm to; vung liềm cắt tới tấp", "Hạng Tần Suất (Jun Da)": "6073.0", "Tần Suất % (Jun Da)": "99.9842235834", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 彡", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅彡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "彡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钐", "Unihan_Traditional (Chữ Phồn thể)": "釤", "Pinyin_Xie": "shān", "Âm Hán Việt_Xie": "sán, sam", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Dùng làm danh từ chỉ loại liềm lớn hoặc làm động từ chỉ hành động vung liềm cắt cỏ nhanh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锬', '{"9000": "6074.0", "Chữ Trung Quốc": "锬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 13 | nét | 锬 | đàm | tượng hình | mâu dài; vũ khí cổ | 锬 (dạng phồn thể 錟) không có phân tích hội ý hay hình thanh từ Wiktionary. Bộ 金 (kim) xác nhận đây là vật bằng kim loại; cấu trúc nội bộ chưa được Wiktionary giải mã.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đàm\": thanh kim 金 loại dài nhọn — 锬 đàm là ngọn giáo sắc bén thời cổ. | Gương Hán-Việt | đàm trong văn ngữ cổ chỉ loại giáo dài | Mở khoá kiến thức | Biết 锬 giúp đọc văn học cổ Trung Quốc mô tả vũ khí chiến trường.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không có phân tích nguồn gốc tự dạng cho 錟/锬. Theo định nghĩa, chữ có hai cách đọc chính: tán (nghĩa: sắc bén) và xiān (nghĩa: loại vũ khí cổ, giáo dài). Bộ 金 (kim) xác nhận vật liệu kim loại. Chưa có nguồn học thuật xác nhận cấu trúc thêm. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái mâu; cái giáo; Ghi chú: 另见xiān", "Hạng Tần Suất (Jun Da)": "6074.0", "Tần Suất % (Jun Da)": "99.9842478723", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 炎", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅炎", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "炎", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锬", "Unihan_Traditional (Chữ Phồn thể)": "錟", "Pinyin_Xie": "tán", "Âm Hán Việt_Xie": "đàm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong văn ngôn để chỉ một loại binh khí cổ có mũi nhọn dài. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镪', '{"9000": "6075.0", "Chữ Trung Quốc": "镪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 17 | nét | 镪 | cường | tượng hình | xâu tiền; axit mạnh | 镪 (dạng phồn thể 鏹) không có phân tích hội ý hay hình thanh từ Wiktionary. Bộ 金 (kim) gợi liên quan đến tiền bạc hoặc kim loại; cấu trúc nội bộ chưa được giải mã chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cường\": tiền kim 金 loại mạnh mạnh — 镪 cường còn chỉ cường thuỷ, axit ăn mòn kim loại. | Gương Hán-Việt | cường trong 镪水 (cường thuỷ — axit mạnh, nước cường toan) | Mở khoá kiến thức | Biết 镪 mở khoá 镪水 (cường thuỷ) — thuật ngữ hoá học chỉ axit mạnh.", "Tự nguyên_Xie": "Wiktionary không phân tích cấu trúc tự dạng cho 鏹/镪. Nghĩa cổ là xâu tiền, đồng tiền, bạc; nghĩa hiện đại trong 镪水 (cường thuỷ) là axit mạnh (axit sulfuric hoặc nitric đặc). Bộ 金 (kim) xác nhận liên quan đến kim loại hoặc tiền. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quan tiền", "Hạng Tần Suất (Jun Da)": "6075.0", "Tần Suất % (Jun Da)": "99.9842721612", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 强", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅强", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "强", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镪", "Unihan_Traditional (Chữ Phồn thể)": "鏹", "Pinyin_Xie": "qiāng", "Âm Hán Việt_Xie": "cường, cưỡng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ tiền tài, thỏi bạc hoặc dây dùng để xâu tiền thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('绡', '{"9000": "6076.0", "Chữ Trung Quốc": "绡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 10 | nét | 绡 | tiêu | tượng hình | lụa sống, tơ dệt thô | 绡 (dạng phồn thể 綃) không có phân tích hội ý hay hình thanh rõ ràng từ Wiktionary dù bộ 糸 (mịch) xác nhận liên quan đến tơ lụa. Cấu trúc nội bộ chưa được giải mã chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiêu\": sợi tơ 糸 mỏng như sương — 绡 tiêu là lụa sống trong suốt óng ánh. | Gương Hán-Việt | tiêu trong 生绡 (sinh tiêu — lụa sống) và 红绡 (hồng tiêu — lụa đỏ) | Mở khoá kiến thức | Biết 绡 mở khoá nhóm từ tên lụa cổ trong thơ Đường: 生绡, 红绡, 冰绡.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không phân tích cấu trúc tự dạng cho 綃/绡 ngoài việc liệt kê phát âm và nghĩa. 绡 chỉ lụa sống — vải dệt từ tơ thô chưa qua xử lý, mỏng và trong. Bộ 糸 (mịch — sợi, tơ) xác nhận đây là tên loại vải. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lụa sống, lụa dệt bằng tơ sống; cái xà treo cánh buồm", "Hạng Tần Suất (Jun Da)": "6076.0", "Tần Suất % (Jun Da)": "99.9842964501", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 肖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟肖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "肖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "绡", "Unihan_Traditional (Chữ Phồn thể)": "綃", "Pinyin_Xie": "xiāo", "Âm Hán Việt_Xie": "tiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ loại lụa tơ tằm mỏng nhẹ hoặc trang phục may từ loại lụa này. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('檎', '{"9000": "6077.0", "Chữ Trung Quốc": "檎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 16 | nét | 木 | mộc | biểu nghĩa | cây, gỗ | 禽 | cầm | biểu âm | cầm thú, chim (cho âm) | 檎 là chữ hình thanh: 木 (mộc) biểu nghĩa chỉ cây ăn quả, 禽 (cầm) biểu âm cho âm đọc gốc. Tên loài cây táo nhỏ màu đỏ (林檎).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cầm\": cây 木 có quả như chim 禽 đậu chùm — 檎 cầm là cây táo nhỏ đỏ mọng. | Gương Hán-Việt | cầm trong 林檎 (lâm cầm — táo dại, cây táo nhỏ đỏ) | Mở khoá kiến thức | Biết 檎 mở khoá 林檎 (lâm cầm) — tên Hán-Nhật cho táo nhỏ, còn dùng trong tiếng Nhật.", "Tự nguyên_Xie": "Theo Wiktionary, 檎 = 木 (mộc — cây, biểu nghĩa) + 禽 (cầm, biểu âm). Đây là chữ hình thanh chỉ cây 林檎 (lâm cầm) — một loài táo nhỏ màu đỏ (Malus asiatica). Bộ 木 xác nhận đây là cây ăn quả; 禽 cho âm đọc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây làm cầm (một thứ cây ăn quả)", "Hạng Tần Suất (Jun Da)": "6077.0", "Tần Suất % (Jun Da)": "99.984320739", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 禽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木禽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "禽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "檎", "Unihan_Traditional (Chữ Phồn thể)": "檎", "Pinyin_Xie": "qín", "Âm Hán Việt_Xie": "cầm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong tên gọi của một loại cây ăn quả thuộc họ hoa hồng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('茕', '{"9000": "6078.0", "Chữ Trung Quốc": "茕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 8 | nét | 茕 | quỳnh | tượng hình | côi cút, không nơi nương tựa | 茕 là dạng giản thể của 煢. Wiktionary ghi {{Han simp|煢|f=𤇾|t=𫇦}}, nghĩa là 茕 được giản lược thành phần lửa (𤇾). Cấu trúc nguyên bản của 煢 liên quan đến lửa đơn độc, gợi hình ảnh cô đơn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quỳnh\": ngọn lửa đơn độc bùng cháy — 茕 quỳnh là người côi cút không chỗ nương thân. | Gương Hán-Việt | quỳnh trong 茕茕 (quỳnh quỳnh — côi cút trơ trọi) và 茕茕孑立 (cô đơn một mình) | Mở khoá kiến thức | Biết 茕 mở khoá 茕茕孑立 (quỳnh quỳnh kiệt lập) — thành ngữ cổ điển diễn tả cô đơn tuyệt đối.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 茕 là dạng giản thể của 煢. Chữ gốc 煢 có thành phần lửa 𤇾 gợi hình ảnh ngọn lửa đơn độc. Nghĩa là côi cút, không có người thân nương tựa. Thường dùng trong văn ngữ cổ: 茕茕孑立 (quỳnh quỳnh kiệt lập — đơn độc một mình trơ trọi). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "côi cút, không nơi nương tựa", "Hạng Tần Suất (Jun Da)": "6078.0", "Tần Suất % (Jun Da)": "99.9843693168", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "茕", "Unihan_Traditional (Chữ Phồn thể)": "煢", "Pinyin_Xie": "qióng", "Âm Hán Việt_Xie": "quỳnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường làm tính từ bổ nghĩa cho danh từ hoặc đứng trong thành ngữ để tả cảnh cô độc. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('荈', '{"9000": "6079.0", "Chữ Trung Quốc": "荈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 荈 | suyễn | tượng hình | trà già, lá trà thu hái muộn | 荈 không có phân tích hội ý hay hình thanh từ Wiktionary. Bộ 艸 (thảo) xác nhận đây là thực vật; cấu trúc nội bộ chưa được giải mã chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"suyễn\": cỏ 艸 già thu hái muộn — 荈 suyễn là trà thô lá già, vị đắng đậm. | Gương Hán-Việt | suyễn trong văn cổ chỉ trà thô, lá trà hái vào cuối mùa | Mở khoá kiến thức | Biết 荈 giúp đọc văn học cổ Trung Quốc về trà đạo, phân biệt các tên gọi trà theo mùa hái.", "Tự nguyên_Xie": "Wiktionary ghi phát âm và nghĩa nhưng không phân tích cấu trúc tự dạng cho 荈. Nghĩa là lá trà thu hái muộn (trà già), trà thô. Bộ 艸 (thảo) xác nhận đây là tên loại thực vật. Từ đồng nghĩa với 茶 (trà). Chưa có nguồn học thuật xác nhận cấu trúc thêm. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trà già; lá trà già", "Hạng Tần Suất (Jun Da)": "6079.0", "Tần Suất % (Jun Da)": "99.9844664724", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 舛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹舛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "舛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "荈", "Unihan_Traditional (Chữ Phồn thể)": "荈", "Pinyin_Xie": "chuǎn", "Âm Hán Việt_Xie": "xuyễn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại trà và thường xuất hiện trong các văn bản cổ về trà đạo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('侉', '{"9000": "6080.0", "Chữ Trung Quốc": "侉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 8 | nét | 侉 | khoả | tượng hình | nói giọng địa phương; khoa trương | 侉 không có phân tích hội ý hay hình thanh rõ ràng từ Wiktionary. Bộ 亻 (nhân) xác nhận liên quan đến con người; cấu trúc nội bộ chưa được giải mã chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khoả\": người 亻 nói giọng lơ lớ — 侉 khoả là kẻ phát âm địa phương nặng, khác chuẩn. | Gương Hán-Việt | khoả trong 侉子 (khoả tử — người nói giọng địa phương) (phương ngữ Bắc) | Mở khoá kiến thức | Biết 侉 giúp hiểu từ khẩu ngữ Bắc Kinh mô tả giọng địa phương hoặc cách nói cường điệu.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary chỉ ghi {{Han etym}} mà không cung cấp phân tích cụ thể cho 侉. Bộ 亻 (nhân — người) cho thấy liên quan đến hành vi con người. Nghĩa là nói giọng địa phương, phát âm không chuẩn; hoặc to lớn vụng về. Chưa có nguồn học thuật xác nhận cấu trúc thêm. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khoa trương, phóng đại", "Hạng Tần Suất (Jun Da)": "6080.0", "Tần Suất % (Jun Da)": "99.9844902445", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 夸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻夸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "侉", "Unihan_Traditional (Chữ Phồn thể)": "侉", "Pinyin_Xie": "kuǎ", "Âm Hán Việt_Xie": "khoa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ thường dùng để miêu tả giọng nói đặc trưng của một vùng miền. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('渫', '{"9000": "6081.0", "Chữ Trung Quốc": "渫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 12 | nét | 氵 | thuỷ | biểu nghĩa | nước | 枼 | biểu âm | thành phần biểu âm | 渫 là chữ hình thanh: 氵 (thuỷ — nước) biểu nghĩa, 枼 biểu âm. Nghĩa gốc liên quan đến việc múc, tát, thông nước.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiết\": nước 氵 thoát ra sạch sẽ — 渫 tiết là tát nước, nạo vét giếng sạch bùn. | Gương Hán-Việt | tiết trong 井渫不食 (tỉnh tiết bất thực — giếng sạch mà không ai dùng, ẩn dụ tài năng bị bỏ phí) | Mở khoá kiến thức | Biết 渫 mở khoá thành ngữ 井渫不食 (giếng sạch không ai uống) — ẩn dụ nhân tài không được trọng dụng.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 渫 = 氵 (thuỷ — nước, biểu nghĩa) + 枼 (biểu âm). Có hai cách đọc: xiè (dọn sạch, tát nước, thông thoát) và dié (trong cụm 浹渫 — ướt đẫm). Nghĩa chính là nạo vét, thoát nước, loại bỏ; cũng dùng trong địa danh (渫水 — sông Tiết ở Hồ Nam). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trừ bỏ; sơ tán, phân tán; ngưng lại, dơ bẩn", "Hạng Tần Suất (Jun Da)": "6081.0", "Tần Suất % (Jun Da)": "99.9845140167", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 枼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵枼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "枼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "渫", "Unihan_Traditional (Chữ Phồn thể)": "渫", "Pinyin_Xie": "xiè", "Âm Hán Việt_Xie": "tiết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động dọn dẹp, khơi thông dòng chảy hoặc loại bỏ chất bẩn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('辂', '{"9000": "6082.0", "Chữ Trung Quốc": "辂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 10 | nét | 辂 | lộ | tượng hình | xe lớn, xe kéo của thiên tử | 辂 (dạng phồn thể 輅) không có phân tích hội ý hay hình thanh từ Wiktionary. Bộ 車 (xa — xe) xác nhận đây là loại xe; cấu trúc nội bộ chưa được giải mã chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lộ\": xe 車 sang trọng to lớn — 辂 lộ là xe thiên tử, thứ xe oai nghi bậc nhất. | Gương Hán-Việt | lộ trong 大輅 (đại lộ — xe lớn nhất của thiên tử), 玉輅 (ngọc lộ — xe ngọc) | Mở khoá kiến thức | Biết 辂 mở khoá 大輅 (xe thiên tử) và 玉輅 trong nghi lễ triều đình Trung Quốc cổ.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Wiktionary không phân tích cấu trúc tự dạng cho 輅/辂 ngoài việc liệt kê phát âm và ghi ''rfdef'' (chưa định nghĩa đầy đủ). Bộ 車 (xa — xe) xác nhận đây là tên loại xe. Nghĩa là xe kéo lớn, thường chỉ xe của thiên tử hoặc quan lại cấp cao. Kim văn và tiểu triện đã ghi nhận chữ này. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "kéo xe; cái xe to", "Hạng Tần Suất (Jun Da)": "6082.0", "Tần Suất % (Jun Da)": "99.9845377888", "GavinGrover_Once (Chiết tự trực tiếp)": "车 + 各", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰车各", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "各", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "车", "Unihan_Simplified (Chữ Giản thể)": "辂", "Unihan_Traditional (Chữ Phồn thể)": "輅", "Pinyin_Xie": "lù", "Âm Hán Việt_Xie": "lộ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loại xe lớn dùng cho vua chúa thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('欷', '{"9000": "6083.0", "Chữ Trung Quốc": "欷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 欠 | Số nét | 11 | nét | 欷 | hi | tượng hình | khóc nức nở, thút thít | 欷 không có phân tích hội ý hay hình thanh rõ ràng từ Wiktionary. Bộ 欠 (khiếm — há miệng, thở) xác nhận liên quan đến tiếng phát ra từ miệng; cấu trúc nội bộ chưa được giải mã chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hi\": miệng 欠 há khóc thút thít — 欷 hi là tiếng nức nở khi buồn, không cầm được nước mắt. | Gương Hán-Việt | hi trong 欷歔 (hi hu — tiếng khóc nức nở, thở dài đau lòng) | Mở khoá kiến thức | Biết 欷 mở khoá cụm 欷歔 (歔欷) — từ văn học cổ miêu tả tiếng khóc nức nở thê lương.", "Tự nguyên_Xie": "Wiktionary ghi phát âm và định nghĩa ''rfdef'' (chưa đầy đủ). Bộ 欠 (khiếm — há miệng, thở) xác nhận liên quan đến âm thanh hay hành động liên quan đến hơi thở. Nghĩa là khóc nức nở, thở dài thút thít. Thường dùng trong cụm 欷歔 (hi hu — tiếng khóc nức nở). Chưa có nguồn học thuật xác nhận cấu trúc thêm. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khóc nức nở; khóc thút thít", "Hạng Tần Suất (Jun Da)": "6083.0", "Tần Suất % (Jun Da)": "99.9845615609", "GavinGrover_Once (Chiết tự trực tiếp)": "希 + 欠", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰希欠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "希", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "欠", "Unihan_Simplified (Chữ Giản thể)": "欷", "Unihan_Traditional (Chữ Phồn thể)": "欷", "Pinyin_Xie": "xī", "Âm Hán Việt_Xie": "hi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ miêu tả trạng thái khóc nghẹn ngào hoặc thở dài trong văn thơ cổ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('轾', '{"9000": "6084.0", "Chữ Trung Quốc": "轾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 10 | nét | 轾 | trị | tượng hình | xe thấp phía sau; cái thấp hơn | 轾 (dạng phồn thể 輊) không có phân tích hội ý hay hình thanh từ Wiktionary. Bộ 車 (xa — xe) xác nhận liên quan đến xe cộ; cấu trúc nội bộ chưa được giải mã chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trị\": xe 車 chúc thấp phần đuôi — 轾 trị là cái thấp hèn, thua kém trong so sánh. | Gương Hán-Việt | trị trong 軒輊 (hiên trị — cao và thấp, hơn kém nhau) | Mở khoá kiến thức | Biết 轾 mở khoá thành ngữ 不分軒輊 (bất phân hiên trị — không phân biệt hơn kém) hay dùng trong văn phong trang trọng.", "Tự nguyên_Xie": "Wiktionary chỉ ghi {{Han etym}} mà không cung cấp phân tích cho 輊/轾. Nghĩa là phần thấp phía sau của xe; ẩn dụ cho cái thua kém. Thường dùng trong cặp đối lập với 軒 (hiên) trong thành ngữ 軒輊 (hiên trị — cao thấp, hơn kém). Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xe có mái che", "Hạng Tần Suất (Jun Da)": "6084.0", "Tần Suất % (Jun Da)": "99.984585333", "GavinGrover_Once (Chiết tự trực tiếp)": "车 + 至", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰车至", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "至", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "车", "Unihan_Simplified (Chữ Giản thể)": "轾", "Unihan_Traditional (Chữ Phồn thể)": "輊", "Pinyin_Xie": "zhì", "Âm Hán Việt_Xie": "chí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ bộ phận xe hoặc làm tính từ trong từ ghép để so sánh cao thấp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('麴', '{"9000": "6085.0", "Chữ Trung Quốc": "麴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 麥 | Số nét | 19 | nét | 麥 | mạch | biểu nghĩa | lúa mì, ngũ cốc | 匊 | cúc | biểu âm | thành phần biểu âm | 麴 là chữ hình thanh: 麥 (mạch — lúa mì) biểu nghĩa xác nhận nguồn gốc từ ngũ cốc, 匊 biểu âm. Chữ chỉ men rượu làm từ lúa mì lên men.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khúc\": lúa mì 麥 ủ lên men — 麴 khúc là men rượu, nền tảng của nghề nấu rượu Đông Á. | Gương Hán-Việt | khúc trong 酒麴 (tửu khúc — men rượu) và họ 麴 (Khúc — tên họ lịch sử) | Mở khoá kiến thức | Biết 麴 mở khoá 酒麴 (men rượu), 麴義 (Khúc Nghĩa — tướng thời Tam Quốc) và văn hoá ủ rượu truyền thống.", "Tự nguyên_Xie": "Theo Wiktionary, 麴 = 麥 (mạch — lúa mì, biểu nghĩa) + 匊 (cúc, biểu âm). Nghĩa là nấm men rượu (koji/leaven) làm từ lúa mì hoặc gạo. Đây là thành phần thiết yếu để ủ rượu và làm tương ở Đông Á. Còn là họ người (Khúc). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "men rượu", "Hạng Tần Suất (Jun Da)": "6085.0", "Tần Suất % (Jun Da)": "99.9846091051", "GavinGrover_Once (Chiết tự trực tiếp)": "麥 + 匊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰麥匊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "麥", "Unihan_Simplified (Chữ Giản thể)": "麴", "Unihan_Traditional (Chữ Phồn thể)": "麴", "Pinyin_Xie": "qū", "Âm Hán Việt_Xie": "khúc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ chất men dùng trong quá trình ủ rượu hoặc chế biến thực phẩm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('戢', '{"9000": "6086.0", "Chữ Trung Quốc": "戢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 戈 | Số nét | 12 | nét | 戢 | tập | tượng hình | cất giấu vũ khí; thu liễm, dừng lại | 戢 không có phân tích hội ý hay hình thanh rõ ràng từ Wiktionary. Bộ 戈 (qua — mác, vũ khí) xác nhận liên quan đến vũ khí; cấu trúc nội bộ chưa được giải mã chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tập\": vũ khí 戈 được thu lại cất — 戢 tập là dẹp binh đao, ngừng chiến. | Gương Hán-Việt | tập trong 戢兵 (tập binh — cất vũ khí, dừng chiến) và 戢翼 (tập dực — thu cánh lại) | Mở khoá kiến thức | Biết 戢 mở khoá 干戈載戢 (can qua tái tập — vũ khí được cất đi, thái bình trở lại) trong thơ cổ.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi phát âm và trích dẫn Kinh Thi nhưng không phân tích cấu trúc tự dạng. Bộ 戈 (qua — vũ khí) xác nhận liên quan đến vũ khí. Nghĩa gốc là cất vũ khí vào bao; mở rộng thành: thu lại cánh, dừng lại, chấm dứt. Chưa có nguồn học thuật xác nhận cấu trúc thêm. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cất giấu", "Hạng Tần Suất (Jun Da)": "6086.0", "Tần Suất % (Jun Da)": "99.9846328772", "GavinGrover_Once (Chiết tự trực tiếp)": "咠 + 戈", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰咠戈", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "咠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "戈", "Unihan_Simplified (Chữ Giản thể)": "戢", "Unihan_Traditional (Chữ Phồn thể)": "戢", "Pinyin_Xie": "jí", "Âm Hán Việt_Xie": "tập", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường làm động từ trong văn ngôn để chỉ việc thu hồi binh khí hoặc kiềm chế bản thân. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('趼', '{"9000": "6087.0", "Chữ Trung Quốc": "趼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 11 | nét | 趼 | kiển | tượng hình | chai tay chân; da dày lên do cọ xát | 趼 không có phân tích hội ý hay hình thanh rõ ràng từ Wiktionary. Bộ 足 (túc — chân) xác nhận liên quan đến chân hoặc đi lại; cấu trúc nội bộ chưa được giải mã chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiển\": bàn chân 足 cọ xát thành chai — 趼 kiển là chỗ da dày cứng ở lòng bàn chân. | Gương Hán-Việt | kiển trong 趼子 (kiển tử — chai chân tay) và 老鼠趼 (lão thử kiển — loại chai cụ thể) | Mở khoá kiến thức | Biết 趼 giúp đọc văn y học cổ truyền và văn học hiện thực mô tả người lao động tay chân.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi phát âm và nghĩa (callus) nhưng không phân tích cấu trúc tự dạng. Bộ 足 (túc — chân) xác nhận liên quan đến bàn chân. Nghĩa là chai da ở chân tay do cọ xát, tương đương với 茧 (kiển — kén tằm, chai tay). Chưa có nguồn học thuật xác nhận cấu trúc thêm. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "móng chân ngay và phẳng của giống thú; chai (phần da dày lên)", "Hạng Tần Suất (Jun Da)": "6087.0", "Tần Suất % (Jun Da)": "99.9846566494", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 开", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊开", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "开", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "趼", "Unihan_Traditional (Chữ Phồn thể)": "趼", "Pinyin_Xie": "jiǎn", "Âm Hán Việt_Xie": "kiển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ phần da bị chai cứng do lao động hoặc đi bộ nhiều. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('芈', '{"9000": "6088.0", "Chữ Trung Quốc": "芈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羊 | Số nét | 7 | nét | 芈 | mị | tượng hình | con dê cái kêu be be; họ Mị | 芈 (dạng phồn thể 羋) là chữ hội ý: hình 羊 (dương — con dê) với dấu gạch ngang chỉ tiếng kêu be be. Wiktionary phân loại là liushu=i (hội ý). Miêu tả con vật phát âm thanh đặc trưng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mị\": con dê 羊 kêu be be — 芈 mị là tiếng dê, cũng là họ danh gia quyền quý nước Tần. | Gương Hán-Việt | mị trong họ 芈 (Mị) — dòng họ hoàng tộc nước Sở thời Chiến Quốc | Mở khoá kiến thức | Biết 芈 giúp đọc lịch sử Chiến Quốc — họ Mị là quốc tính của nước Sở, nổi tiếng qua phim 芈月传.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 羋 là chữ hội ý: hình dê 羊 cộng dấu gạch chỉ tiếng kêu. Đây là chữ tượng thanh-hội ý, mô tả trực tiếp tiếng kêu be be của dê. Họ Mị (芈) nổi tiếng trong lịch sử qua Tuyên Thái Hậu nước Tần (Mị Bát Tử). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "be be (tiếng dê kêu); họ Mễ", "Hạng Tần Suất (Jun Da)": "6088.0", "Tần Suất % (Jun Da)": "99.9847036768", "GavinGrover_Once (Chiết tự trực tiếp)": "卝 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴卝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "芈", "Unihan_Traditional (Chữ Phồn thể)": "羋", "Pinyin_Xie": "mǐ", "Âm Hán Việt_Xie": "mị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Từ tượng thanh | 象声词 | Chữ này chủ yếu dùng làm danh từ chỉ họ người hoặc từ mô phỏng tiếng kêu của loài dê. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('苈', '{"9000": "6089.0", "Chữ Trung Quốc": "苈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 7 | nét | 苈 | lịch | tượng hình | loại cây thuốc (đình lịch) | 苈 (dạng phồn thể 藶) không có phân tích hội ý hay hình thanh từ Wiktionary. Bộ 艸 (thảo) xác nhận đây là tên thực vật; cấu trúc nội bộ chưa được giải mã chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lịch\": cỏ 艸 thuốc nhỏ trong đình 葶lịch — 苈 lịch luôn đi với 葶 kết hợp tên thuốc quý. | Gương Hán-Việt | lịch trong 葶苈 (đình lịch — tên cây thuốc Đông y) | Mở khoá kiến thức | Biết 苈 mở khoá 葶苈 (đình lịch) — vị thuốc Đông y trị phù nề, ho hen.", "Tự nguyên_Xie": "Wiktionary ghi ''rfdef'' cho 藶 (dạng gốc của 苈) và không có phân tích tự dạng. Bộ 艸 (thảo) xác nhận đây là tên cây. 苈 chỉ một mình không đủ nghĩa, thường dùng trong cụm 葶苈 (đình lịch — Descurainia sophia hoặc Lepidium apetalum), loại cây thuốc trong y học cổ truyền. Chưa có nguồn học thuật xác nhận cấu trúc thêm. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: đình lịch 葶藶,葶苈)", "Hạng Tần Suất (Jun Da)": "6089.0", "Tần Suất % (Jun Da)": "99.9847269321", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 历", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹历", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "历", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "苈", "Unihan_Traditional (Chữ Phồn thể)": "藶", "Pinyin_Xie": "lì", "Âm Hán Việt_Xie": "lịch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này là danh từ thường xuất hiện trong tên vị thuốc đông y đình lịch tử. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缍', '{"9000": "6090.0", "Chữ Trung Quốc": "缍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 11 | nét | 缍 | đoả | tượng hình | con nai; cái thoi dệt (đánh thoi) | 缍 là dạng giản thể của 綞. Wiktionary ghi {{Han simp|綞|f=糹|t=纟}} — phần 糹 (sợi) được đơn giản hoá thành 纟. Bộ 糸/纟 xác nhận liên quan đến sợi dệt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đoả\": sợi 纟 đánh thoi — 缍 đoả là con thoi dệt lướt qua lướt lại trên khung vải. | Gương Hán-Việt | đoả trong 綞缍 (đoả — con thoi dệt vải) | Mở khoá kiến thức | Biết 缍 giúp đọc văn học cổ Trung Quốc về nghề dệt và thủ công mỹ nghệ.", "Tự nguyên_Xie": "Theo Wiktionary, 缍 là dạng giản thể của 綞, với phần 糹 (mịch) được thay bằng 纟. Chữ gốc 綞 chỉ con thoi (shuttle) trong dệt vải, hoặc dây buộc. Bộ 糸 gợi liên quan đến sợi và dệt. Chưa có phân tích nguồn gốc sâu hơn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con nai", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 垂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟垂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "垂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "缍", "Unihan_Traditional (Chữ Phồn thể)": "缍", "Pinyin_Xie": "duǒ", "Âm Hán Việt_Xie": "đoả", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Chữ này làm danh từ chỉ quả cân hoặc cuộn sợi, đôi khi dùng làm lượng từ cho bó sợi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('歃', '{"9000": "6091.0", "Chữ Trung Quốc": "歃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 欠 | Số nét | 13 | nét | 臿 | trở | biểu âm | cuốc đất (cho âm) | 欠 | khiếm | biểu nghĩa | há miệng, nuốt | 歃 là chữ hình thanh: 欠 (khiếm — há miệng) biểu nghĩa gợi hành động nuốt, uống, 臿 biểu âm. Nghĩa là uống máu hoặc nhấp chất lỏng trong nghi lễ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sáp\": miệng 欠 há ra uống — 歃 sáp là nhấp máu thề bồi, kết minh ước. | Gương Hán-Việt | sáp trong 歃血 (sáp huyết — uống máu thề) và 歃血為盟 (sáp huyết vi minh — uống máu kết minh ước) | Mở khoá kiến thức | Biết 歃 mở khoá 歃血為盟 — nghi lễ kết minh trang trọng nhất trong lịch sử Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 歃 = 臿 (biểu âm) + 欠 (khiếm — há miệng, biểu nghĩa). Nghĩa gốc là uống, nhấp; đặc biệt trong nghi lễ uống máu thề (歃血為盟 — shà xuè wéi méng). Bộ 欠 gợi hành động há miệng, nuốt. Tiểu triện ghi nhận dạng này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "uống, nuốt", "Hạng Tần Suất (Jun Da)": "6091.0", "Tần Suất % (Jun Da)": "99.9847734428", "GavinGrover_Once (Chiết tự trực tiếp)": "臿 + 欠", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰臿欠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "臿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "欠", "Unihan_Simplified (Chữ Giản thể)": "歃", "Unihan_Traditional (Chữ Phồn thể)": "歃", "Pinyin_Xie": "shà", "Âm Hán Việt_Xie": "sáp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường đi kèm với từ chỉ máu trong nghi thức kết nghĩa ngày xưa. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('燠', '{"9000": "6092.0", "Chữ Trung Quốc": "燠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 16 | nét | 燠 | úc | tượng hình | ấm áp, nóng nực | 燠 không có phân tích hội ý hay hình thanh rõ ràng từ Wiktionary. Bộ 火 (hoả — lửa) xác nhận liên quan đến nhiệt độ; cấu trúc nội bộ chưa được giải mã chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"úc\": lửa 火 hừng hực toả hơi nóng — 燠 úc là cái oi ả, ấm nóng ngột ngạt. | Gương Hán-Việt | úc trong 燠热 (úc nhiệt — nóng nực, oi ả) và 燠暖 (úc noãn — ấm áp) | Mở khoá kiến thức | Biết 燠 giúp đọc thơ ca cổ miêu tả thời tiết ấm nóng và ngôn ngữ lịch sự hỏi thăm sức khoẻ.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary chỉ ghi {{Han etym}} mà không cung cấp phân tích cho 燠. Bộ 火 (hoả — lửa) xác nhận liên quan đến nhiệt. Nghĩa là ấm áp, nóng nực. Tiểu triện và lục thư thông đều ghi nhận dạng chữ này. Chưa có nguồn học thuật xác nhận cấu trúc thêm. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ấm áp", "Hạng Tần Suất (Jun Da)": "6092.0", "Tần Suất % (Jun Da)": "99.9847966981", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 奥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火奥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "燠", "Unihan_Traditional (Chữ Phồn thể)": "燠", "Pinyin_Xie": "yù", "Âm Hán Việt_Xie": "úc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ miêu tả thời tiết nóng bức hoặc cảm giác ấm áp. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('耜', '{"9000": "6093.0", "Chữ Trung Quốc": "耜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 耒 | Số nét | 11 | nét | 耒 | lồi | biểu nghĩa | cày, nông cụ | 㠯 | biểu âm | thành phần biểu âm | 耜 là chữ hình thanh: 耒 (lồi — cày) biểu nghĩa xác nhận đây là nông cụ, 㠯 biểu âm. Chữ chỉ lưỡi cày gắn vào thân cày.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tự\": cày 耒 gắn lưỡi bén — 耜 tự là lưỡi cày xới đất tơi xốp cho mùa vụ. | Gương Hán-Việt | tự trong 耒耜 (lồi tự — bộ cày) và 良耜 (lương tự — cày tốt, tên bài trong Kinh Thi) | Mở khoá kiến thức | Biết 耜 mở khoá 耒耜 — thuật ngữ nông nghiệp cổ và Kinh Thi 《良耜》 ca ngợi mùa thu hoạch.", "Tự nguyên_Xie": "Lục thư thông | Theo Wiktionary, 耜 = 耒 (lồi — cày, biểu nghĩa) + 㠯 (biểu âm). Nghĩa là lưỡi cày (plowshare) — phần sắt hoặc gỗ bén gắn vào đầu cày để bới đất. Thường đi cùng 耒 trong cụm 耒耜 (lồi tự — bộ cày hoàn chỉnh). Lục thư thông ghi nhận dạng này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lưỡi cày", "Hạng Tần Suất (Jun Da)": "6093.0", "Tần Suất % (Jun Da)": "99.9848199535", "GavinGrover_Once (Chiết tự trực tiếp)": "耒 + 㠯", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰耒㠯", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㠯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "耒", "Unihan_Simplified (Chữ Giản thể)": "耜", "Unihan_Traditional (Chữ Phồn thể)": "耜", "Pinyin_Xie": "sì", "Âm Hán Việt_Xie": "cử", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại công cụ sản xuất nông nghiệp thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('顸', '{"9000": "6094.0", "Chữ Trung Quốc": "顸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 干 | Số nét | 9 | nét | 顸 | hàm | tượng hình | mặt to bẹt; ngu ngốc, lờ khờ | 顸 là dạng giản thể của 頇. Wiktionary ghi {{Han simp|頇|f=頁|t=页}} — phần 頁 (đầu) được giản lược thành 页. Nghĩa là mặt to phẳng bẹt; ẩn dụ cho người ngu ngốc, chậm chạp.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hàm\": mặt đầu 页 to bẹt bệt — 顸 hàm là kẻ to đầu mà ngu, điển hình quan liêu hủ bại. | Gương Hán-Việt | hàm trong 颟顸 (man hàm — to lớn mà ngu) và 顢頇 (phồn thể) | Mở khoá kiến thức | Biết 顸 mở khoá 颟顸 — từ văn học cổ chỉ tính quan liêu vô trách nhiệm, còn dùng trong văn xuôi hiện đại.", "Tự nguyên_Xie": "Theo Wiktionary, 顸 là dạng giản thể của 頇, với 頁 (đầu) được thay bằng 页. Chữ gốc 頇 chỉ khuôn mặt to bẹt; ẩn dụ cho tính ngu ngốc. Thường dùng trong cụm 颟顸 (man hàm — to lớn mà ngu ngốc, vô trách nhiệm) — từ mô tả tính cách quan liêu hủ bại. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: man han 顢頇,颟顸)", "Hạng Tần Suất (Jun Da)": "6094.0", "Tần Suất % (Jun Da)": "99.9848432088", "GavinGrover_Once (Chiết tự trực tiếp)": "干 + 页", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰干页", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "页", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "干", "Unihan_Simplified (Chữ Giản thể)": "顸", "Unihan_Traditional (Chữ Phồn thể)": "頇", "Pinyin_Xie": "hān", "Âm Hán Việt_Xie": "han", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ thường dùng trong từ ghép để chỉ sự thô kệch hoặc khờ khạo. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蚵', '{"9000": "6095.0", "Chữ Trung Quốc": "蚵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 11 | nét | 蚵 | hà | tượng hình | con hà (hàu, sò); loài thân mềm biển | 蚵 không có phân tích hội ý hay hình thanh từ Wiktionary. Bộ 虫 (trùng) xác nhận đây là sinh vật; nghĩa phổ biến là con hàu (oyster) hoặc con hà bám vào đá, tàu thuyền.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hà\": loài 虫 sống bám biển — 蚵 hà là con hàu mặn mòi dưới đá biển. | Gương Hán-Việt | hà trong 蚵仔 (hà tử — con hàu nhỏ, tiếng Mân Nam) và 蚵仔煎 (hà tử tiên — bánh hàu, món ăn Đài Loan) | Mở khoá kiến thức | Biết 蚵 mở khoá 蚵仔煎 (bánh hàu chiên Đài Loan) và ẩm thực Mân Nam-Đài Loan.", "Tự nguyên_Xie": "Wiktionary chỉ ghi {{Han etym}} mà không cung cấp phân tích cho 蚵. Bộ 虫 (trùng — côn trùng, sinh vật nhỏ) xác nhận đây là tên sinh vật. Nghĩa phổ biến là con hàu (oyster) hoặc sinh vật thân mềm bám vào đá. Trong tiếng Mân Nam (Hokkien), 蚵仔 (hé zǐ) là tên gọi phổ biến cho hàu. Chưa có nguồn học thuật xác nhận cấu trúc thêm. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: hà long 蚵蠪)", "Hạng Tần Suất (Jun Da)": "6095.0", "Tần Suất % (Jun Da)": "99.9848664641", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 可", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫可", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "可", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蚵", "Unihan_Traditional (Chữ Phồn thể)": "蚵", "Pinyin_Xie": "hé", "Âm Hán Việt_Xie": "hà", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài nhuyễn thể hai mảnh vỏ, phổ biến trong khẩu ngữ miền Nam Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('哓', '{"9000": "6096.0", "Chữ Trung Quốc": "哓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 9 | nét | 哓 | kiêu | tượng hình | sợ hãi, lo lắng; lải nhải | 哓 là dạng giản thể của 嘵. Wiktionary ghi {{Han simp|嘵|f=堯|t=尧}} — phần 堯 được giản thành 尧. Bộ 口 (khẩu — miệng) gợi liên quan đến tiếng kêu hoặc lời nói.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiêu\": miệng 口 kêu loạn lên — 哓 kiêu là tiếng la hét sợ hãi, lải nhải không ngừng. | Gương Hán-Việt | kiêu trong 哓哓 (kiêu kiêu — tiếng kêu lo lắng, lải nhải) | Mở khoá kiến thức | Biết 哓 giúp đọc thơ ca cổ miêu tả tiếng kêu sợ hãi và những người nói nhiều không ngừng.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 哓 là dạng giản thể của 嘵, với 堯 được đơn giản hoá thành 尧. Bộ 口 (khẩu — miệng) xác nhận liên quan đến âm thanh phát ra. Nghĩa là kêu sợ, kêu la lo lắng; hoặc nói lải nhải, không dứt. Tiểu triện ghi nhận dạng chữ gốc. Chưa có nguồn học thuật phân tích cấu trúc sâu hơn. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sợ hãi; lải nhải", "Hạng Tần Suất (Jun Da)": "6096.0", "Tần Suất % (Jun Da)": "99.9848897194", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 尧", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口尧", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尧", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "哓", "Unihan_Traditional (Chữ Phồn thể)": "嘵", "Pinyin_Xie": "xiāo", "Âm Hán Việt_Xie": "hiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ biểu thị hành động kêu khóc hoặc tranh luận không ngừng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('澌', '{"9000": "6097.0", "Chữ Trung Quốc": "澌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 15 | nét | 氵 | thuỷ | biểu nghĩa | nước | 斯 | tư | biểu âm | đây, này (cho âm) | 澌 là chữ hình thanh: 氵 (thuỷ — nước) biểu nghĩa, 斯 (tư) biểu âm. Nghĩa là nước cạn dần đến hết; ẩn dụ cho sự tiêu diệt hoàn toàn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tư\": nước 氵 rút dần cạn kiệt — 澌 tư là cạn hết, tiêu tan, không còn gì. | Gương Hán-Việt | tư trong 澌滅 (tư diệt — tiêu diệt hoàn toàn, không còn dấu vết) | Mở khoá kiến thức | Biết 澌 mở khoá 澌滅 — từ văn học chỉ sự diệt vong hoàn toàn không thể khôi phục.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 澌 = 氵 (thuỷ — nước, biểu nghĩa) + 斯 (tư, biểu âm). Nghĩa gốc là nước cạn khô kiệt; mở rộng thành: hết sạch, tiêu diệt hoàn toàn. Tiểu triện ghi nhận cấu trúc này. 澌滅 (tư diệt — tiêu diệt hoàn toàn) là từ hay dùng nhất. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hết sạch", "Hạng Tần Suất (Jun Da)": "6097.0", "Tần Suất % (Jun Da)": "99.9849129748", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 斯", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵斯", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "斯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "澌", "Unihan_Traditional (Chữ Phồn thể)": "澌", "Pinyin_Xie": "sī", "Âm Hán Việt_Xie": "ti, tê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường làm động từ trong văn ngôn để chỉ sự cạn kiệt hoặc tiêu tan hoàn toàn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('郜', '{"9000": "6098.0", "Chữ Trung Quốc": "郜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 9 | nét | 郜 | cáo | tượng hình | tên nước chư hầu thời Chu; họ Cáo | 郜 không có phân tích hội ý hay hình thanh từ Wiktionary. Bộ 邑 (ấp — địa danh, khu dân cư) xác nhận đây là tên địa phương hoặc quốc gia; cấu trúc nội bộ chưa được giải mã chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cáo\": đất ấp 邑 phong cho hoàng tử — 郜 cáo là tên nước chư hầu thời Chu, sau thành họ người. | Gương Hán-Việt | cáo trong họ 郜 (Cáo) — dòng họ xuất phát từ nước Cáo thời Chu | Mở khoá kiến thức | Biết 郜 giúp đọc chính sử và phả hệ Trung Quốc liên quan đến phong tước thời Tây Chu.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | Wiktionary ghi phát âm và định nghĩa nhưng không phân tích cấu trúc tự dạng. Bộ 邑 (ấp — thành ấp, địa danh) xác nhận đây là địa danh. Nghĩa là nước Cáo — một chư hầu nhỏ thời Chu, đất được phong cho con cả của Văn Vương. Kim văn, tiểu triện và lục thư thông đều ghi nhận chữ này. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên đất); họ Cáo", "Hạng Tần Suất (Jun Da)": "6098.0", "Tần Suất % (Jun Da)": "99.9849362301", "GavinGrover_Once (Chiết tự trực tiếp)": "告 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰告阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "告", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "郜", "Unihan_Traditional (Chữ Phồn thể)": "郜", "Pinyin_Xie": "gào", "Âm Hán Việt_Xie": "cáo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ riêng để chỉ họ người hoặc tên một nước thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('徼', '{"9000": "6099.0", "Chữ Trung Quốc": "徼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 彳 | Số nét | 16 | nét | 徼 | kiếu | tượng hình | biên cương, đường tuần tra; cầu may | 徼 không có phân tích hội ý hay hình thanh từ Wiktionary. Bộ 彳 (sách — bước đi) xác nhận liên quan đến đường đi hoặc hành trình; cấu trúc nội bộ chưa được giải mã chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiếu\": bước đi 彳 dọc biên giới — 徼 kiếu là tuần tra biên cương, hoặc cầu may phước. | Gương Hán-Việt | kiếu trong 徼幸 (kiếu hạnh — cầu may, mong được phước nhờ may rủi) và 徼外 (kiếu ngoại — ngoài biên cương) | Mở khoá kiến thức | Biết 徼 mở khoá 徼幸 (cầu may) và 疆徼 (cương kiếu — đường biên giới) trong văn học cổ.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary ghi nhiều cách đọc (jiǎo, jiào, jiāo, yāo) và nhiều nghĩa nhưng không phân tích cấu trúc tự dạng. Bộ 彳 (sách — bước đi) xác nhận liên quan đến tuần tra, đường biên. Nghĩa chính: biên cương, kiểm tra tuần tra; nghĩa phụ: cầu xin, may mắn. Tiểu triện và lục thư thông ghi nhận chữ này. Chưa có nguồn học thuật xác nhận cấu trúc thêm. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cầu may", "Hạng Tần Suất (Jun Da)": "6099.0", "Tần Suất % (Jun Da)": "99.9849594854", "GavinGrover_Once (Chiết tự trực tiếp)": "彳 + 敫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰彳敫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "彳", "Unihan_Simplified (Chữ Giản thể)": "徼", "Unihan_Traditional (Chữ Phồn thể)": "徼", "Pinyin_Xie": "jiǎo", "Âm Hán Việt_Xie": "kiêu, kiếu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thể hiện hành động cầu xin hoặc mong đợi sự may mắn ngoài ý muốn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('籀', '{"9000": "6100.0", "Chữ Trung Quốc": "籀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 19 | nét | 籀 | trứu | tượng hình | lối chữ đại triện (Chu văn); đọc sách, giải nghĩa | 籀 không có dữ liệu Wiktionary về cấu trúc. Bộ 竹 (trúc) gợi liên quan đến thẻ tre, sách vở. Nghĩa chỉ thể chữ đại triện (籀文) được truyền là do Sử Trứu đời Chu tạo ra.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trứu\": sách tre 竹 của Sử quan đời Chu — 籀 trứu là lối chữ đại triện cổ kính bậc nhất. | Gương Hán-Việt | trứu trong 籀文 (trứu văn — thể chữ đại triện) và 太史籀 (Thái Sử Trứu — người tạo chữ) | Mở khoá kiến thức | Biết 籀 mở khoá 籀文 (đại triện) — hệ thống chữ Hán cổ đứng giữa kim văn và tiểu triện trong lịch sử thư pháp.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không có mục từ cho 籀. Bộ 竹 (trúc — tre, thẻ tre) gợi liên quan đến viết lách và thư tịch. Nghĩa là: (1) thể chữ đại triện gọi là 籀文 (trứu văn) — hệ chữ Chu cổ được cho là do Sử Trứu (太史籀) đời Chu Tuyên Vương biên soạn; (2) đọc sách, giải thích nghĩa kinh văn. Tiểu triện còn lưu hình dạng. Chưa có nguồn học thuật xác nhận cấu trúc thêm. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lối chữ trứu (chữ đại triện); diễn giải kinh sách", "Hạng Tần Suất (Jun Da)": "6100.0", "Tần Suất % (Jun Da)": "99.9849827408", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 㨨", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮㨨", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㨨", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "籀", "Unihan_Traditional (Chữ Phồn thể)": "籀", "Pinyin_Xie": "zhòu", "Âm Hán Việt_Xie": "trứu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ với nghĩa đọc sách hoặc làm danh từ chỉ một thể chữ cổ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('陬', '{"9000": "6101.0", "Chữ Trung Quốc": "陬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 10 | nét | 陬 | trâu | tượng hình | góc, xó; nơi hẻo lánh | 陬 không có phân tích hội ý hay hình thanh từ Wiktionary. Bộ 阜 (phụ — gò đồi, địa hình) xác nhận liên quan đến địa lý hoặc vị trí; cấu trúc nội bộ chưa được giải mã chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trâu\": gò 阜 hẻo lánh một góc — 陬 trâu là nơi khuất nẻo tận cùng xó xỉnh. | Gương Hán-Việt | trâu trong 荒陬 (hoang trâu — nơi hoang vắng) và 陬月 (trâu nguyệt — tháng Giêng cổ) | Mở khoá kiến thức | Biết 陬 mở khoá 孟陬 (tháng Giêng âm lịch) và 荒陬 trong thơ ca cổ về vùng xa xôi hẻo lánh.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi phát âm và định nghĩa nhưng không phân tích cấu trúc tự dạng. Bộ 阜 (phụ — đồi gò, địa hình cao) xác nhận liên quan đến địa lý. Nghĩa là góc, xó, nơi hẻo lánh. Thường dùng trong 荒陬 (hoang trâu — nơi hoang vắng xa xôi) và 孟陬 (mạnh trâu — tháng đầu tiên). Tiểu triện ghi nhận chữ này. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "góc, xó", "Hạng Tần Suất (Jun Da)": "6101.0", "Tần Suất % (Jun Da)": "99.9850054793", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + 取", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝取", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "取", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "陬", "Unihan_Traditional (Chữ Phồn thể)": "陬", "Pinyin_Xie": "zōu", "Âm Hán Việt_Xie": "tưu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các góc khuất, nơi hẻo lánh hoặc vùng biên giới. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蕤', '{"9000": "6102.0", "Chữ Trung Quốc": "蕤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 15 | nét | 蕤 | nhuy | tượng hình | hoa rủ xuống; mềm mại, lung lay | 蕤 không có phân tích hội ý hay hình thanh rõ ràng từ Wiktionary. Bộ 艸 (thảo) xác nhận liên quan đến thực vật; cấu trúc nội bộ chưa được giải mã chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhuy\": cỏ 艸 hoa rủ mềm mại — 蕤 nhuy là cành hoa buông xuống, tươi tốt lung linh. | Gương Hán-Việt | nhuy trong 葳蕤 (uy nhuy — hoa lá tươi tốt) và 蕤賓 (nhuy tân — luật âm nhạc tháng 5) | Mở khoá kiến thức | Biết 蕤 mở khoá 葳蕤 (tươi tốt rậm rạp) trong thơ cổ và 蕤賓 trong âm nhạc truyền thống Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi phát âm và nghĩa nhưng không phân tích cấu trúc tự dạng. Bộ 艸 (thảo — cỏ cây) xác nhận đây là tên thực vật hoặc mô tả đặc tính thực vật. Nghĩa là: cành hoa rủ xuống; mềm mại lay động; cũng là tên luật âm nhạc cổ (蕤賓 — nhuy tân). Thường dùng trong cụm 葳蕤 (uy nhuy — hoa lá rủ đẹp, rậm rạp tốt tươi). | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hoa nở rủ xuống", "Hạng Tần Suất (Jun Da)": "6102.0", "Tần Suất % (Jun Da)": "99.9850282179", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 甤", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹甤", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蕤", "Unihan_Traditional (Chữ Phồn thể)": "蕤", "Pinyin_Xie": "ruí", "Âm Hán Việt_Xie": "nhuy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ tua trang trí hoặc làm tính từ mô tả hoa lá rủ xuống sum suê. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('叻', '{"9000": "6103.0", "Chữ Trung Quốc": "叻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 5 | nét | 口 | khẩu | biểu nghĩa | miệng, khẩu ngữ | 力 | lực | biểu âm | sức mạnh | 叻 = 口 (Khẩu, biểu nghĩa: miệng/khẩu ngữ) + 力 (Lực, biểu âm); chữ hình thanh. Bộ 口 cho nghĩa liên quan đến lời nói/địa danh, bộ 力 cho âm gần lè/lặc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sựt\": miệng (口) dùng hết sức (力) gọi tên đất lạ — nhớ 叻埠 là Singapore ngày xưa. | Gương Hán-Việt | sựt — ít dùng độc lập trong tiếng Việt Hán-Việt hiện đại | Mở khoá kiến thức | Biết 叻 mở khoá địa danh lịch sử Đông Nam Á trong văn bản Hán cổ.", "Tự nguyên_Xie": "Chữ hình thanh: 口 (khẩu) biểu nghĩa liên quan đến khẩu ngữ, 力 (lực) biểu âm. Dùng phiên âm địa danh tiếng Mã Lai, nổi bật nhất là 叻埠 (Lặc Phụ, tức Singapore/Singapur trong tiếng Quảng Đông). Chữ tạo muộn để phiên âm, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật cổ điển. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: lặc phụ 叻埠)", "Hạng Tần Suất (Jun Da)": "6103.0", "Tần Suất % (Jun Da)": "99.9850509564", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 力", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口力", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "力", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "叻", "Unihan_Traditional (Chữ Phồn thể)": "叻", "Pinyin_Xie": "lè", "Âm Hán Việt_Xie": "lặc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ trong các từ ghép phiên âm địa danh nước ngoài như Singapore. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('猞', '{"9000": "6104.0", "Chữ Trung Quốc": "猞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 11 | nét | 犭 | biểu nghĩa | thú bốn chân (biến thể bộ 犬) | 舍 | xá | biểu âm | nhà, bỏ lại | 猞 = 犭(biểu nghĩa: thú bốn chân) + 舍 (Xá, biểu âm); chữ hình thanh. Bộ 犭 cho nghĩa là loài thú, bộ 舍 cho âm shē.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt tương ứng âm \"xá\": con thú (犭) trú ẩn như cái nhà (舍) trong rừng — đó là linh miêu 猞猁. | Gương Hán-Việt | 猞 — không có từ Hán-Việt độc lập, chỉ dùng trong 猞猁 | Mở khoá kiến thức | Biết 猞 mở khoá tên loài linh miêu (猞猁) trong văn bản động vật học Hán ngữ.", "Tự nguyên_Xie": "Chữ hình thanh: 犭(犬, khuyển) biểu nghĩa chỉ thú vật, 舍 (xá) biểu âm. 猞 chỉ dùng trong từ 猞猁 (shēlì), tên loài mèo rừng (linh miêu/lynx). Chữ tạo muộn để đặt tên loài vật, chưa thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: xá lợi 猞猁)", "Hạng Tần Suất (Jun Da)": "6104.0", "Tần Suất % (Jun Da)": "99.985073695", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 舍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭舍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "舍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "猞", "Unihan_Traditional (Chữ Phồn thể)": "猞", "Pinyin_Xie": "shē", "Âm Hán Việt_Xie": "xá", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ và hầu như chỉ xuất hiện trong từ ghép để chỉ loài linh miêu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('洇', '{"9000": "6105.0", "Chữ Trung Quốc": "洇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 9 | nét | 洇 | tượng hình | nước thấm vào/loang ra — chữ độc lập, chưa tách được thành phần rõ ràng | 洇 có bộ 氵(thủy) bên trái và 因 bên phải theo hình thức thị giác, nhưng nguồn gốc chưa được Wiktionary ghi chép cụ thể ({{Han etym}}). Có thể là hình thanh với 氵 biểu nghĩa (nước) và 因 biểu âm yīn, nhưng không có xác nhận học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhân\": bộ nước (氵) + nhân (因) — nước thấm \"vì\" (因) mực trên giấy mà nhòe ra, đó là 洇. | Gương Hán-Việt | 洇 — không có từ Hán-Việt phổ biến | Mở khoá kiến thức | Biết 洇 giúp đọc văn bản về kỹ thuật in ấn, hội họa mực nước khi mực bị nhoè.", "Tự nguyên_Xie": "Tiểu triện | Nguồn gốc chữ 洇 chưa được ghi chép đầy đủ trong Wiktionary. Về hình thức, chữ gồm bộ 氵(thủy) và 因, gợi ý hình thanh với nghĩa liên quan đến nước thấm/loang. Có dạng tiểu triện. Chưa có nguồn học thuật xác nhận cấu trúc chính thức. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thấm; nhoè", "Hạng Tần Suất (Jun Da)": "6105.0", "Tần Suất % (Jun Da)": "99.9850964335", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 因", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵因", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "因", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "洇", "Unihan_Traditional (Chữ Phồn thể)": "洇", "Pinyin_Xie": "yīn", "Âm Hán Việt_Xie": "nhân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hiện tượng chất lỏng thấm qua giấy hoặc vải gây loang màu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锎', '{"9000": "6106.0", "Chữ Trung Quốc": "锎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 12 | nét | 锎 | tượng hình | nguyên tố californium — chữ tạo mới, tự thân | 锎 có bộ 钅(kim) biểu nghĩa (kim loại) và 开 biểu âm theo hình thức thị giác, nhưng không có ghi chép Wiktionary chính thức. Chữ được tạo ra để phiên dịch tên nguyên tố californium (Cf) sang chữ Hán hiện đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khai\": bộ kim (钅) + âm kāi — kim loại phóng xạ californium được \"khai\" phá tại California. | Gương Hán-Việt | 锎 — không có từ Hán-Việt, chỉ dùng trong hóa học | Mở khoá kiến thức | Biết 锎 mở khoá hệ thống tên nguyên tố hóa học trong chữ Hán hiện đại.", "Tự nguyên_Xie": "锎 là chữ Hán hiện đại được đặt ra để ký hiệu nguyên tố californium (Cf, số hiệu 98). Không có nguồn gốc cổ điển. Chữ tạo muộn theo quy ước đặt tên nguyên tố hóa học bằng chữ Hán: bộ 钅(kim) chỉ kim loại, âm đọc kāi gần với phần đầu \"ca-\" của californium. Chưa có nguồn học thuật cổ điển. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố californi, Cf", "Hạng Tần Suất (Jun Da)": "6106.0", "Tần Suất % (Jun Da)": "99.985119172", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 𫕲", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅𫕲", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𫕲", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锎", "Unihan_Traditional (Chữ Phồn thể)": "鐦", "Pinyin_Xie": "kāi", "Âm Hán Việt_Xie": "khai", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chuyên ngành hóa học để chỉ nguyên tố phóng xạ Californi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('舳', '{"9000": "6107.0", "Chữ Trung Quốc": "舳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 舟 | Số nét | 11 | nét | 舳 | tượng hình | đuôi/lái thuyền — chữ độc lập chưa xác định thành phần rõ ràng | 舳 có bộ 舟 (chu, thuyền) biểu nghĩa và 由 biểu âm theo hình thức thị giác. Nguồn Wiktionary ghi {{Han etym}}, chưa có phân tích cấu trúc chính thức. Chữ liên quan đến thuyền bè cổ đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trục\": bộ thuyền (舟) + âm zhú — con thuyền có \"do\" (由) đuôi lái mà điều hướng được. | Gương Hán-Việt | 舳 — không có từ Hán-Việt độc lập phổ biến | Mở khoá kiến thức | Biết 舳 mở khoá từ 舳艫 — cụm chỉ đội thuyền lớn trong sử liệu cổ Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | Nguồn gốc chính thức của 舳 chưa được Wiktionary ghi chép đầy đủ. Về hình thức, chữ gồm bộ 舟 (chu, thuyền) và phần 由, gợi ý hình thanh. Nghĩa chính là đuôi thuyền, phần lái. Dùng trong cụm 舳艫 (zhúlú) chỉ đội thuyền/đầu và đuôi thuyền. Có dạng tiểu triện. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đuôi thuyền", "Hạng Tần Suất (Jun Da)": "6107.0", "Tần Suất % (Jun Da)": "99.9851419106", "GavinGrover_Once (Chiết tự trực tiếp)": "舟 + 由", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舟由", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "由", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舟", "Unihan_Simplified (Chữ Giản thể)": "舳", "Unihan_Traditional (Chữ Phồn thể)": "舳", "Pinyin_Xie": "zhú", "Âm Hán Việt_Xie": "trục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ phần đuôi của con thuyền hoặc bánh lái tàu bè. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缋', '{"9000": "6108.0", "Chữ Trung Quốc": "缋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 12 | nét | 缋 | tượng hình | lụa thêu, tranh vẽ — chữ chưa tách được thành phần rõ ràng | 缋 có bộ 糸 (mịch, tơ lụa) biểu nghĩa và 贵 hoặc phần khác biểu âm theo hình thức thị giác. Nguồn Wiktionary chỉ ghi {{Han etym}}, không có phân tích cấu trúc. Là biến thể giản của 繢.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hội\": bộ tơ (糸) gợi nghĩa thêu lụa — 缋 là những mảnh lụa thêu còn lại sau khi hoàn thành tác phẩm. | Gương Hán-Việt | 缋 — không có từ Hán-Việt độc lập phổ biến | Mở khoá kiến thức | Biết 缋 mở khoá từ vựng về thêu thùa và hội họa trong cổ văn Hán ngữ.", "Tự nguyên_Xie": "缋 là dạng giản thể (hoặc dị thể) của 繢 (huì). Nguồn gốc chưa được Wiktionary ghi chép đầy đủ. Chữ có bộ 糸 (tơ lụa) biểu nghĩa, liên quan đến thêu thùa và vẽ tranh. Nghĩa gốc: phần lụa thêu thừa; sau là dị thể của 繪 (vẽ, phác thảo). Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lụa thêu, tua lụa", "Hạng Tần Suất (Jun Da)": "6108.0", "Tần Suất % (Jun Da)": "99.9851646491", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 贵", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟贵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "贵", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "缋", "Unihan_Traditional (Chữ Phồn thể)": "繢", "Pinyin_Xie": "huì", "Âm Hán Việt_Xie": "hội", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ việc vẽ, thêu hoặc làm danh từ chỉ các dải lụa màu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镗', '{"9000": "6109.0", "Chữ Trung Quốc": "镗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 16 | nét | 镗 | tượng hình | tiếng trống/chiêng, dụng cụ khoan — chưa tách được thành phần rõ ràng | 镗 có bộ 钅(kim) biểu nghĩa (kim loại) và 堂 biểu âm theo hình thức thị giác. Nguồn Wiktionary chỉ ghi {{Han etym}}, không có phân tích cấu trúc. Phồn thể là 鏜.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đường\": bộ kim (钅) + âm tāng — tiếng kim loại (钅) vang lên \"thùng thùng\" (tāng) như trống đồng. | Gương Hán-Việt | 镗 — không có từ Hán-Việt độc lập phổ biến | Mở khoá kiến thức | Biết 镗 mở khoá từ vựng cơ khí (khoan khoét) và nhạc khí cổ đại trong tiếng Hán.", "Tự nguyên_Xie": "Tiểu triện | 镗 (phồn thể 鏜) có nguồn gốc chưa được Wiktionary ghi chép đầy đủ. Có dạng tiểu triện. Bộ 钅(kim) gợi liên quan đến kim loại — nghĩa bao gồm tiếng trống/chiêng vang, chiêng nhỏ, và trong kỹ thuật hiện đại là động tác khoan/khoét lỗ kim loại. Chưa có nguồn học thuật xác nhận cấu trúc chính thức. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng trống thùng thùng; cái chiêng nhỏ", "Hạng Tần Suất (Jun Da)": "6109.0", "Tần Suất % (Jun Da)": "99.9851873877", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 堂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅堂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "堂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镗", "Unihan_Traditional (Chữ Phồn thể)": "鏜", "Pinyin_Xie": "tāng", "Âm Hán Việt_Xie": "thang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Từ tượng thanh | 象声词 | Thường dùng làm danh từ chỉ một loại nhạc khí gõ hoặc từ tượng thanh mô phỏng tiếng chuông trống vang rền. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('褙', '{"9000": "6110.0", "Chữ Trung Quốc": "褙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 14 | nét | 褙 | tượng hình | lót vải/giấy, đóng bìa — chưa tách được thành phần rõ ràng | 褙 có bộ 衤(y, quần áo/vải) biểu nghĩa và 背 biểu âm theo hình thức thị giác. Nguồn Wiktionary ghi {{Han etym|偝}}, tham chiếu dạng cổ 偝. Nghĩa là dán lót vải hoặc giấy vào mặt sau.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bội\": bộ vải (衤) + lưng (背) — dán vải vào \"lưng\" tờ tranh để gia cố, đó là kỹ thuật 褙. | Gương Hán-Việt | 褙 — không có từ Hán-Việt độc lập phổ biến | Mở khoá kiến thức | Biết 褙 mở khoá từ vựng nghề đóng sách và bảo tồn thư pháp truyền thống Trung Hoa.", "Tự nguyên_Xie": "褙 liên quan đến dạng cổ 偝, theo Wiktionary. Có bộ 衤(y, vải/quần áo) biểu nghĩa, 背 (bèi, lưng) biểu âm. Nghĩa gốc: lót vải/giấy vào mặt sau (lưng) của vật; nay dùng trong nghề đóng bìa sách, ép tranh thư pháp. Có dạng tiểu triện. Chưa có nguồn học thuật xác nhận đầy đủ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "áo lót ngực", "Hạng Tần Suất (Jun Da)": "6110.0", "Tần Suất % (Jun Da)": "99.9852101262", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 背", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤背", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "背", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "褙", "Unihan_Traditional (Chữ Phồn thể)": "褙", "Pinyin_Xie": "bèi", "Âm Hán Việt_Xie": "bối", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ trong việc bồi giấy, vải hoặc làm danh từ chỉ lớp lót áo. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('耋', '{"9000": "6111.0", "Chữ Trung Quốc": "耋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 老 | Số nét | 12 | nét | 耋 | tượng hình | người già tám mươi tuổi — chữ độc lập, chưa tách được thành phần rõ ràng | 耋 có bộ 老 (lão, già) ở trên và 至 ở dưới theo hình thức thị giác. Nguồn Wiktionary chỉ ghi {{Han etym}}, không có phân tích cấu trúc. Nghĩa: người già từ 70-80 tuổi. Có dạng tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điệt\": bộ lão (老) trên đỉnh — người đã đến (至) tuổi già cực kỳ, đó là bậc 耋 tám mươi. | Gương Hán-Việt | 耋 — không có từ Hán-Việt độc lập phổ biến | Mở khoá kiến thức | Biết 耋 mở khoá cụm 耄耋 — từ trang trọng chỉ tuổi thọ cao trong văn chương cổ điển.", "Tự nguyên_Xie": "Tiểu triện | 耋 có nguồn gốc chưa được Wiktionary ghi chép đầy đủ. Về hình thức, chữ liên quan đến bộ 老 (lão, già). Nghĩa: người rất cao tuổi (70-80 tuổi), thường dùng trong cụm 耄耋 (màodié) chỉ tuổi già 80-90. Có dạng tiểu triện. Chưa có nguồn học thuật xác nhận cấu trúc chính thức. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "già 80 tuổi", "Hạng Tần Suất (Jun Da)": "6111.0", "Tần Suất % (Jun Da)": "99.9852328648", "GavinGrover_Once (Chiết tự trực tiếp)": "老 + 至", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱老至", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "至", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "老", "Unihan_Simplified (Chữ Giản thể)": "耋", "Unihan_Traditional (Chữ Phồn thể)": "耋", "Pinyin_Xie": "dié", "Âm Hán Việt_Xie": "điệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ người già thượng thọ hoặc tính từ chỉ sự già nua. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('聬', '{"9000": "6112.0", "Chữ Trung Quốc": "聬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 耳 | Số nét | 16 | nét | 耳 | nhĩ | biểu nghĩa | tai | 翁 | ông | biểu âm | ông già, phụ âm tiếng ong | 聬 = 耳 (Nhĩ, biểu nghĩa: tai) + 翁 (Ông, biểu âm); chữ hình thanh. Bộ 耳 cho nghĩa liên quan đến tai/nghe, bộ 翁 cho âm wēng gần với wěng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ông\": tai (耳) nghe tiếng \"ông ông\" (翁) — đó là âm vo ve của gió hay tiếng ong, chính là 聬. | Gương Hán-Việt | 聬 — không có từ Hán-Việt phổ biến | Mở khoá kiến thức | Biết 聬 mở khoá từ vựng mô tả âm thanh vo ve, ù tai trong thơ văn cổ điển.", "Tự nguyên_Xie": "Chữ hình thanh: 耳 (nhĩ) biểu nghĩa chỉ tai/thính giác, 翁 (ông) biểu âm. 聬 mô tả tiếng vo ve (như tiếng ong, tiếng gió) vang trong tai. Theo Wiktionary: {{Han compound|耳|翁|c1=s|c2=p|ls=psc|t1=ear}}. Chữ ít dùng, chủ yếu trong văn học mô tả âm thanh. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "聁", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "耳 + 翁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰耳翁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "翁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "耳", "Unihan_Simplified (Chữ Giản thể)": "聬", "Unihan_Traditional (Chữ Phồn thể)": "聬", "Pinyin_Xie": "wěng", "Âm Hán Việt_Xie": "ung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ miêu tả trạng thái tai bị ù hoặc tiếng động trầm đục khó nghe. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鳡', '{"9000": "6113.0", "Chữ Trung Quốc": "鳡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 21 | nét | 鳡 | tượng hình | cá ngão/cá vược lớn — chưa tách được thành phần rõ ràng | 鳡 có bộ 鱼 (ngư, cá) biểu nghĩa và 敢 biểu âm theo hình thức thị giác. Nguồn Wiktionary chỉ ghi {{Han etym}}, không có phân tích cấu trúc. Phồn thể là 鱤.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cảm\": bộ cá (鱼) + âm gǎn — loài cá dám (敢) đương đầu với mọi thứ vì nó rất lớn và hung dữ. | Gương Hán-Việt | 鳡 — không có từ Hán-Việt độc lập phổ biến | Mở khoá kiến thức | Biết 鳡 mở khoá từ vựng về loài cá nước ngọt lớn trong ngư nghiệp và văn học Trung Hoa.", "Tự nguyên_Xie": "鳡 (phồn thể 鱤) có nguồn gốc chưa được Wiktionary ghi chép đầy đủ. Bộ 鱼 (ngư) biểu nghĩa chỉ loài cá; 敢 biểu âm gǎn. Là tên loài cá freshwater lớn trong sông hồ Trung Hoa (yellowcheek carp), nổi tiếng hung dữ và to lớn. Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá măng", "Hạng Tần Suất (Jun Da)": "6113.0", "Tần Suất % (Jun Da)": "99.9852783419", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 感", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼感", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "感", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鳡", "Unihan_Traditional (Chữ Phồn thể)": "鱤", "Pinyin_Xie": "gǎn", "Âm Hán Việt_Xie": "cảm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ đứng độc lập hoặc kết hợp để chỉ loài cá măng lớn chuyên ăn thịt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲌', '{"9000": "6114.0", "Chữ Trung Quốc": "鲌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 13 | nét | 鲌 | tượng hình | cá trắng đuôi đỏ (Culter) — chưa tách được thành phần rõ ràng | 鲌 có bộ 鱼 (ngư, cá) biểu nghĩa và 白 (bạch, trắng) biểu âm theo hình thức thị giác. Nguồn Wiktionary chỉ ghi {{Han etym}}, không có phân tích cấu trúc chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bạch\": bộ cá (鱼) + trắng (白) — loài cá trắng bạc ánh như bạc đó là 鲌. | Gương Hán-Việt | 鲌 — không có từ Hán-Việt độc lập phổ biến | Mở khoá kiến thức | Biết 鲌 mở khoá tên loài cá nước ngọt trong ngư học và ẩm thực Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | 鲌 có nguồn gốc chưa được Wiktionary ghi chép đầy đủ. Bộ 鱼 (ngư) biểu nghĩa chỉ loài cá; 白 (bạch) biểu âm bó. Là tên chi cá Culter — cá trắng nước ngọt có đuôi đỏ, phổ biến trong sông hồ Trung Hoa. Có dạng tiểu triện. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá thiều bạc", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 白", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼白", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "白", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲌", "Unihan_Traditional (Chữ Phồn thể)": "鲌", "Pinyin_Xie": "bà", "Âm Hán Việt_Xie": "bạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ một họ cá nước ngọt có vảy màu trắng bạc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鰽', '{"9000": "6115.0", "Chữ Trung Quốc": "鰽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 22 | nét | 鰽 | tượng hình | một loài cá — chữ phồn thể, chưa tách được thành phần rõ ràng | 鰽 có bộ 魚 (ngư, cá) biểu nghĩa và phần còn lại biểu âm qiú theo hình thức thị giác. Không có nguồn gốc chính thức trong Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cầu\": bộ cá (魚) — loài cá đặc biệt trong hệ thống phân loại ngư học cổ đại. | Gương Hán-Việt | 鰽 — không có từ Hán-Việt độc lập phổ biến | Mở khoá kiến thức | Biết 鰽 giúp đọc từ điển ngư học cổ và văn bản phân loại sinh vật cổ đại Trung Hoa.", "Tự nguyên_Xie": "鰽 là chữ phồn thể chỉ một loài cá, không có ghi chép nguồn gốc trong Wiktionary. Bộ 魚 (ngư) biểu nghĩa chỉ loài cá. Chữ ít được nghiên cứu, xuất hiện trong từ điển cá chuyên ngành. Chưa có nguồn học thuật xác nhận cấu trúc chính thức. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá trích", "Hạng Tần Suất (Jun Da)": "6115.0", "Tần Suất % (Jun Da)": "99.985323819", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 曹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚曹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鰽", "Unihan_Traditional (Chữ Phồn thể)": "鰽", "Pinyin_Xie": "qiú", "Âm Hán Việt_Xie": "cừu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong tên gọi các loài cá biển nhỏ thuộc họ cá trích. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('袴', '{"9000": "6116.0", "Chữ Trung Quốc": "袴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 11 | nét | 衤 | biểu nghĩa | vải, quần áo (biến thể bộ 衣) | 夸 | khoa | biểu âm | khoe khoang, phóng đại | 袴 = 衤(Y, biểu nghĩa: vải/quần áo) + 夸 (Khoa, biểu âm); chữ hình thanh. Bộ 衤 cho nghĩa quần áo, bộ 夸 cho âm kù.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khố\": vải (衤) khoa trương (夸) dài rộng che đôi chân — đó là chiếc khố 袴, quần cổ đại. | Gương Hán-Việt | khố — 袴子 (quần), 短袴 (quần ngắn) | Mở khoá kiến thức | Biết 袴 (khố) mở khoá từ vựng trang phục cổ đại và dị thể 褲/裤 (quần hiện đại).", "Tự nguyên_Xie": "Theo Wiktionary: {{Han compound|衣|alt1=衤|t1=cloth|夸|ls=psc|c1=s|c2=p}} — một loại quần áo. 袴 là quần rộng/quần ống (không đáy trong tiếng Hán cổ). Dị thể của 褲 (quần). Chữ hình thanh: 衤biểu nghĩa (vải), 夸 biểu âm kù. Ít dùng hơn dạng phổ biến 裤/褲. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái khố; cái quần đùi", "Hạng Tần Suất (Jun Da)": "2086.0", "Tần Suất % (Jun Da)": "97.4379229686", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 夸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤夸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "裤", "Unihan_Traditional (Chữ Phồn thể)": "袴", "Pinyin_Xie": "kù", "Âm Hán Việt_Xie": "khố", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ chỉ trang phục mặc ở phần dưới cơ thể như quần hoặc khố. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('巯', '{"9000": "6117.0", "Chữ Trung Quốc": "巯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 工 | Số nét | 12 | nét | 巯 | tượng hình | nhóm thiol (-SH) trong hóa học — chữ tạo mới | 巯 có bộ 工 biểu nghĩa theo hình thức thị giác và phần còn lại biểu âm qiú. Chữ được tạo ra để ký hiệu nhóm thiol/mercapto (-SH) trong hóa học hữu cơ. Không có nguồn gốc cổ điển.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cầu\": nhìn vào 巯 — chữ tạo ra riêng cho hóa học, đại diện nhóm -SH (thiol) trong phân tử hữu cơ. | Gương Hán-Việt | 巯 — chỉ dùng trong hóa học, không có từ Hán-Việt độc lập | Mở khoá kiến thức | Biết 巯 mở khoá từ vựng hóa học hữu cơ Hán ngữ: 巯基 (nhóm thiol), 巯醇.", "Tự nguyên_Xie": "巯 là chữ Hán hiện đại được đặt ra để ký hiệu nhóm thiol/mercapto (-SH) trong hóa học hữu cơ. Không có nguồn gốc cổ điển, không có phân tích cấu trúc trong Wiktionary. Chữ tạo muộn theo quy ước thuật ngữ hóa học Hán ngữ. Chưa có nguồn học thuật cổ điển. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Sun-phua hy-đrô", "Hạng Tần Suất (Jun Da)": "6117.0", "Tần Suất % (Jun Da)": "99.9854819552", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 㐬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰㐬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "巯", "Unihan_Traditional (Chữ Phồn thể)": "巰", "Pinyin_Xie": "qiú", "Âm Hán Việt_Xie": "khưu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ trong thuật ngữ hóa học để chỉ nhóm chức chứa lưu huỳnh và hydro. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('吖', '{"9000": "6118.0", "Chữ Trung Quốc": "吖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 6 | nét | 口 | khẩu | biểu nghĩa | miệng, khẩu ngữ | 丫 | nha | biểu âm | chẽ đôi, nhánh | 吖 = 口 (Khẩu, biểu nghĩa: miệng) + 丫 (Nha, biểu âm); chữ hình thanh. Bộ 口 cho nghĩa liên quan đến âm thanh/lời nói, bộ 丫 cho âm yā.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nha\": miệng (口) tạo âm \"ya\" từ cái nhánh chẽ đôi (丫) — 吖 là âm cảm thán hoặc phiên âm. | Gương Hán-Việt | 吖 — không có từ Hán-Việt độc lập; dùng trong phiên âm và tiếng Quảng Đông | Mở khoá kiến thức | Biết 吖 giúp đọc văn bản tiếng Quảng Đông và phiên âm nước ngoài bằng chữ Hán.", "Tự nguyên_Xie": "Theo Wiktionary: {{Han compound|口|丫|ls=psc|c1=s|c2=p|t1=mouth|no_och2=y}}. 吖 dùng để phiên âm tiếng nước ngoài hoặc trong tiếng Quảng Đông làm trợ từ ngữ khí. Chữ hình thanh: 口 biểu nghĩa (miệng/âm thanh), 丫 biểu âm yā. Chữ tạo muộn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(dùng phiên âm tiếng nước ngoài, chủ yếu dùng trong hoá học); a; ôi; úi chà", "Hạng Tần Suất (Jun Da)": "6118.0", "Tần Suất % (Jun Da)": "99.985504177", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 丫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口丫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "吖", "Unihan_Traditional (Chữ Phồn thể)": "吖", "Pinyin_Xie": "yā", "Âm Hán Việt_Xie": "a", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Trợ từ | 助词 | Thán từ | 叹词 | Danh từ | 名词 | Chữ này thường dùng làm trợ từ ngữ khí ở cuối câu hoặc dùng để phiên âm các hợp chất hóa học. | Trợ từ | 助词 | Không mang nghĩa riêng, gắn vào câu để đánh dấu ngữ pháp hoặc ngữ khí: 的 / 地 / 得 (kết cấu), 了 / 着 / 过 (thể), 吗 / 呢 / 吧 (nghi vấn, ngữ khí). | Thán từ | 叹词 | Bộc lộ cảm xúc hoặc dùng để gọi đáp: 啊, 哦, 喂. Đứng tách riêng ở đầu câu, không làm thành phần câu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('猁', '{"9000": "6119.0", "Chữ Trung Quốc": "猁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 10 | nét | 犭 | biểu nghĩa | thú bốn chân (biến thể bộ 犬) | 利 | lợi | biểu âm | lợi ích, bén nhọn | 猁 = 犭(biểu nghĩa: thú bốn chân) + 利 (Lợi, biểu âm); chữ hình thanh. Bộ 犭 cho nghĩa loài thú, bộ 利 cho âm lì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lợi\": thú (犭) linh lợi (利) như dao bén — đó là linh miêu 猞猁, mèo rừng nhanh nhẹn. | Gương Hán-Việt | 猁 — không có từ Hán-Việt độc lập, chỉ dùng trong 猞猁 | Mở khoá kiến thức | Biết 猁 mở khoá tên đầy đủ linh miêu 猞猁 trong văn bản động vật học.", "Tự nguyên_Xie": "Theo Wiktionary: {{Han compound|犬|利|alt1=犭|ls=psc|c1=s|c2=p|t1=dog|no_och2=1}}. 猁 chỉ dùng trong từ 猞猁 (shēlì), tên loài linh miêu (lynx). Chữ hình thanh: 犭biểu nghĩa (thú), 利 biểu âm lì. Chữ tạo muộn để đặt tên loài vật. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: xá lợi 猞猁)", "Hạng Tần Suất (Jun Da)": "6119.0", "Tần Suất % (Jun Da)": "99.9855263987", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 利", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭利", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "利", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "猁", "Unihan_Traditional (Chữ Phồn thể)": "猁", "Pinyin_Xie": "lì", "Âm Hán Việt_Xie": "lợi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này hầu như chỉ xuất hiện trong từ ghép để chỉ loài linh miêu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('桷', '{"9000": "6120.0", "Chữ Trung Quốc": "桷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 11 | nét | 桷 | dác | tượng hình | rui nhà vuông — chữ độc lập, không tách được thành phần rõ ràng từ nguồn | 桷 có bộ 木 (mộc, gỗ/cây) biểu nghĩa và 角 biểu âm theo hình thức thị giác. Nguồn Wiktionary chỉ ghi {{Han etym}}, không có phân tích cấu trúc chính thức. Có dạng tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dác\": gỗ (木) có góc cạnh (角) vuông vức — đó là rui nhà vuông 桷, đòn tay kẻ góc. | Gương Hán-Việt | dác — không có từ Hán-Việt phổ biến | Mở khoá kiến thức | Biết 桷 mở khoá từ vựng kiến trúc cổ đại Trung Hoa trong văn bản kinh điển.", "Tự nguyên_Xie": "Tiểu triện | 桷 có nguồn gốc chưa được Wiktionary ghi chép đầy đủ. Về hình thức, chữ gồm bộ 木 (mộc, gỗ) và 角 biểu âm, gợi ý hình thanh. Nghĩa: rui nhà vuông (đòn tay/rafters có hình vuông, khác với 椽 là rui tròn). Dùng trong kiến trúc cổ đại Trung Hoa. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rui nhà, xà nhà (hình vuông); cái vồ; cột to", "Hạng Tần Suất (Jun Da)": "6120.0", "Tần Suất % (Jun Da)": "99.9855486205", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 角", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木角", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "角", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "桷", "Unihan_Traditional (Chữ Phồn thể)": "桷", "Pinyin_Xie": "jué", "Âm Hán Việt_Xie": "giác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các thanh gỗ làm rui hoặc xà ngang trong kiến trúc nhà cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('砼', '{"9000": "6121.0", "Chữ Trung Quốc": "砼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 10 | nét | 砼 | tượng hình | bê tông (concrete) — chữ tạo mới của kỹ sư Trung Quốc | 砼 là chữ tạo mới hiện đại, được thiết kế có chủ đích: 石 (thạch, đá) + 人 (nhân, người) + 工 (công, công việc) — đá người làm ra, tức bê tông nhân tạo. Không có nguồn gốc cổ điển.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đồng\": đá (石) + người (人) + công (工) — \"đá do con người công phu tạo ra\" chính là bê tông 砼. | Gương Hán-Việt | 砼 — không có từ Hán-Việt, chỉ dùng trong kỹ thuật xây dựng | Mở khoá kiến thức | Biết 砼 mở khoá từ vựng kỹ thuật xây dựng Hán ngữ: 混凝土/砼, 钢筋砼 (bê tông cốt thép).", "Tự nguyên_Xie": "砼 là chữ Hán hiện đại do kỹ sư Trung Quốc Hoàng Xiliang (黄锡麟) đặt ra vào năm 1953 để ký hiệu bê tông (concrete). Cấu trúc chủ đích: 石 (đá) + 人 (người) + 工 (công việc) = đá do con người tạo ra. Không có nguồn gốc cổ điển, chưa thấy trong giáp cốt/kim văn. Chữ tạo muộn, được tiêu chuẩn hóa trong ngành xây dựng Trung Quốc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bê-tông", "Hạng Tần Suất (Jun Da)": "6121.0", "Tần Suất % (Jun Da)": "99.9855708423", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 仝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石仝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "仝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "砼", "Unihan_Traditional (Chữ Phồn thể)": "砼", "Pinyin_Xie": "tóng", "Âm Hán Việt_Xie": "đồng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này là danh từ chuyên ngành xây dựng, viết tắt thay thế cho từ bê tông. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锾', '{"9000": "6122.0", "Chữ Trung Quốc": "锾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 14 | nét | 锾 | tượng hình | đơn vị trọng lượng/tiền tệ cổ đại — chưa tách được thành phần rõ ràng | 锾 có bộ 钅(kim) biểu nghĩa (kim loại/tiền) và 爰 biểu âm huán theo hình thức thị giác. Nguồn Wiktionary chỉ ghi {{Han etym}}, không có phân tích cấu trúc. Có dạng tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoàn\": bộ kim (钅) + âm huán — lượng kim loại hoán đổi được, đơn vị tiền tệ/phạt cổ đại 锾. | Gương Hán-Việt | 锾 — không có từ Hán-Việt độc lập phổ biến | Mở khoá kiến thức | Biết 锾 mở khoá đơn vị đo lường cổ đại trong luật pháp và thương mại Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | 锾 có nguồn gốc chưa được Wiktionary ghi chép đầy đủ. Bộ 钅(kim) gợi liên quan đến kim loại/tiền tệ. Nghĩa: đơn vị trọng lượng hoặc tiền phạt cổ đại (6 lạng). Có dạng tiểu triện. Chưa có nguồn học thuật xác nhận cấu trúc chính thức. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hoàn (đơn vị đo khối lượng, bằng 6 lạng); tiền", "Hạng Tần Suất (Jun Da)": "6122.0", "Tần Suất % (Jun Da)": "99.985593064", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 爰", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅爰", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "爰", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锾", "Unihan_Traditional (Chữ Phồn thể)": "鍰", "Pinyin_Xie": "huán", "Âm Hán Việt_Xie": "hoàn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Chữ này dùng làm danh từ chỉ tiền tệ thời cổ hoặc làm lượng từ đo khối lượng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('颟', '{"9000": "6123.0", "Chữ Trung Quốc": "颟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 頁 | Số nét | 16 | nét | 㒼 | biểu âm | mặt đầy đặn | 頁 | biểu nghĩa | đầu, trang | 颟 = 㒼 (biểu âm, âm mān) + 頁 (biểu nghĩa: đầu/mặt); chữ hình thanh. Bộ 頁 cho nghĩa liên quan đến đầu/mặt, bộ 㒼 cho âm mān.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"man\": mặt (頁) ngây ngô đầy đặn (㒼) — 颟顸 là người ngớ ngẩn không hiểu đời. | Gương Hán-Việt | 颟 — không có từ Hán-Việt độc lập | Mở khoá kiến thức | Biết 颟 mở khoá từ 颟顸 — tính từ văn học mô tả người lơ mơ, ngây ngốc.", "Tự nguyên_Xie": "Theo Wiktionary: {{Han compound|㒼|頁|ls=psc|c1=p|c2=s|t2=leaf}}. Chữ hình thanh: 頁 biểu nghĩa (đầu/mặt), 㒼 biểu âm mān. Chỉ dùng trong từ 颟顸 (mānhān) — mô tả người ngây ngô, lơ mơ, không hiểu chuyện. Chữ ít dùng độc lập. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: man han 顢頇,颟顸)", "Hạng Tần Suất (Jun Da)": "6123.0", "Tần Suất % (Jun Da)": "99.9856152858", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 页", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰页", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "颟", "Unihan_Traditional (Chữ Phồn thể)": "顢", "Pinyin_Xie": "mān", "Âm Hán Việt_Xie": "man", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường kết hợp để tạo thành tính từ mô tả thái độ làm việc tắc trách, hồ đồ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('跽', '{"9000": "6124.0", "Chữ Trung Quốc": "跽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 14 | nét | 跽 | tượng hình | quỳ gối — chưa tách được thành phần rõ ràng | 跽 có bộ 足 (túc, chân) biểu nghĩa và 忌 biểu âm jì theo hình thức thị giác. Nguồn Wiktionary ghi {{Han etym}}, không có phân tích cấu trúc. Có dạng tiểu triận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kị\": bộ chân (足) + âm jì — hai chân cúi quỳ xuống, đó là tư thế 跽 quỳ gối kính cẩn. | Gương Hán-Việt | 跽 — không có từ Hán-Việt độc lập phổ biến | Mở khoá kiến thức | Biết 跽 mở khoá từ vựng lễ nghi cổ đại và tư thế thân thể trong văn học Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | 跽 có nguồn gốc chưa được Wiktionary ghi chép đầy đủ. Bộ 足 (túc, chân) gợi nghĩa liên quan đến tư thế chân/gối. Nghĩa: quỳ gối, ngồi quỳ. Có dạng tiểu triện. Dùng trong văn học cổ mô tả tư thế lễ nghi quỳ gối trước bề trên. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quỳ gối; quỳ", "Hạng Tần Suất (Jun Da)": "6124.0", "Tần Suất % (Jun Da)": "99.9856375075", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 忌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊忌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "忌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "跽", "Unihan_Traditional (Chữ Phồn thể)": "跽", "Pinyin_Xie": "jì", "Âm Hán Việt_Xie": "kị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ tư thế quỳ thẳng lưng trong nghi lễ thời cổ đại. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('悛', '{"9000": "6125.0", "Chữ Trung Quốc": "悛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 10 | nét | 悛 | thoăn | tượng hình | hối lỗi, sửa mình — chữ độc lập, chưa tách được thành phần rõ ràng | 悛 có bộ 忄(tâm, trái tim/tâm hồn) biểu nghĩa và 夋 biểu âm quān theo hình thức thị giác. Nguồn Wiktionary chỉ ghi {{Han etym}}, không có phân tích cấu trúc. Có dạng tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thoăn\": tâm (忄) thoăn thoắt quay đầu sửa lỗi — 悛 là biết hối cải, không ngoan cố. | Gương Hán-Việt | thoăn — 悛改 (thoăn cải = hối cải, sửa chữa) | Mở khoá kiến thức | Biết 悛 mở khoá từ 不悛 (bất thoăn = ngoan cố không hối cải) trong văn học đạo đức cổ.", "Tự nguyên_Xie": "Tiểu triện | 悛 có nguồn gốc chưa được Wiktionary ghi chép đầy đủ. Bộ 忄(tâm) gợi nghĩa liên quan đến tâm hồn/cảm xúc. Nghĩa: hối lỗi, thay đổi tâm tính, cải tà quy chính. Dùng trong từ hóa thạch 悛改 và cụm phủ định 不悛 (không chịu hối cải). Có dạng tiểu triện. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hối cải; hối lỗi", "Hạng Tần Suất (Jun Da)": "6125.0", "Tần Suất % (Jun Da)": "99.9856597293", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 夋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄夋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "悛", "Unihan_Traditional (Chữ Phồn thể)": "悛", "Pinyin_Xie": "quān", "Âm Hán Việt_Xie": "thuân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thể hiện sự ăn năn, tự sửa chữa khuyết điểm của bản thân. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('桕', '{"9000": "6126.0", "Chữ Trung Quốc": "桕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 10 | nét | 桕 | tượng hình | cây ô cữu (tallow tree) — chưa tách được thành phần rõ ràng | 桕 có bộ 木 (mộc, gỗ/cây) biểu nghĩa và 臼 biểu âm jiù theo hình thức thị giác. Nguồn Wiktionary chỉ ghi {{Han etym}}, không có phân tích cấu trúc chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cữu\": bộ cây (木) + cối (臼) — cây 桕 có hạt ép ra sáp như giã cối, dùng làm nến cổ đại. | Gương Hán-Việt | 桕 — không có từ Hán-Việt độc lập phổ biến | Mở khoá kiến thức | Biết 桕 mở khoá tên cây ô cữu (乌桕) — cây lấy sáp truyền thống và cây cảnh mùa thu nổi tiếng.", "Tự nguyên_Xie": "桕 có nguồn gốc chưa được Wiktionary ghi chép đầy đủ. Bộ 木 (mộc) biểu nghĩa chỉ cây. Nghĩa: cây ô cữu (Sapium sebiferum/Triadica sebifera) — cây lấy sáp dùng làm nến trong lịch sử Trung Quốc. Tên đầy đủ 乌桕. Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây bồ hòn (tên khoa học: sapium sebiferum)", "Hạng Tần Suất (Jun Da)": "6126.0", "Tần Suất % (Jun Da)": "99.9856819511", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 臼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木臼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "臼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "桕", "Unihan_Traditional (Chữ Phồn thể)": "桕", "Pinyin_Xie": "jiù", "Âm Hán Việt_Xie": "cữu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại cây lấy dầu hoặc làm nguyên liệu sản xuất sáp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('艨', '{"9000": "6127.0", "Chữ Trung Quốc": "艨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 舟 | Số nét | 19 | nét | 艨 | tượng hình | thuyền chiến bọc da cổ đại — chưa tách được thành phần rõ ràng | 艨 có bộ 舟 (chu, thuyền) biểu nghĩa và 蒙 biểu âm méng theo hình thức thị giác. Nguồn Wiktionary chỉ ghi {{Han etym}}, không có phân tích cấu trúc chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mông\": bộ thuyền (舟) + mông lung (蒙) — thuyền chiến bọc kín mịt mù đó là 艨 trong 艨艟. | Gương Hán-Việt | 艨 — không có từ Hán-Việt độc lập phổ biến | Mở khoá kiến thức | Biết 艨 mở khoá từ 艨艟 — tên thuyền chiến tốc độ cao trong sử liệu thủy chiến Trung Hoa.", "Tự nguyên_Xie": "艨 có nguồn gốc chưa được Wiktionary ghi chép đầy đủ. Bộ 舟 (chu, thuyền) gợi nghĩa liên quan đến thuyền bè. Nghĩa: thuyền chiến bọc da (trong 艨艟 méngchōng — loại thuyền chiến tốc độ cao thời cổ đại). Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: mông đồng 艨艟)", "Hạng Tần Suất (Jun Da)": "6127.0", "Tần Suất % (Jun Da)": "99.9857041728", "GavinGrover_Once (Chiết tự trực tiếp)": "舟 + 蒙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舟蒙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "蒙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舟", "Unihan_Simplified (Chữ Giản thể)": "艨", "Unihan_Traditional (Chữ Phồn thể)": "艨", "Pinyin_Xie": "méng", "Âm Hán Việt_Xie": "mông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường đi kèm với chữ đồng để tạo thành danh từ chỉ loại thuyền chiến lớn thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('颡', '{"9000": "6128.0", "Chữ Trung Quốc": "颡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 頁 | Số nét | 16 | nét | 桑 | tang | biểu âm | cây dâu tằm | 頁 | biểu nghĩa | đầu, trang | 颡 = 桑 (Tang, biểu âm) + 頁 (biểu nghĩa: đầu/mặt); chữ hình thanh. Bộ 頁 cho nghĩa liên quan đến đầu/trán, bộ 桑 cho âm sǎng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tang\": đầu (頁) mang âm tang (桑) — trán 颡 là phần đỉnh đầu phía trước. | Gương Hán-Việt | 颡 — không có từ Hán-Việt độc lập phổ biến | Mở khoá kiến thức | Biết 颡 mở khoá từ vựng giải phẫu đầu mặt trong y học cổ truyền và thơ ca Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary: {{Han compound|桑|頁|ls=psc|c1=p|c2=s|t2=head}}. Chữ hình thanh: 頁 biểu nghĩa (đầu), 桑 biểu âm sǎng. Nghĩa: trán, vầng trán. Có dạng tiểu triện. Chữ ít dùng, chủ yếu trong thơ văn cổ điển và y học cổ truyền. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trán (trên đầu)", "Hạng Tần Suất (Jun Da)": "6128.0", "Tần Suất % (Jun Da)": "99.9857263946", "GavinGrover_Once (Chiết tự trực tiếp)": "桑 + 页", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰桑页", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "桑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "页", "Unihan_Simplified (Chữ Giản thể)": "颡", "Unihan_Traditional (Chữ Phồn thể)": "顙", "Pinyin_Xie": "sǎng", "Âm Hán Việt_Xie": "tảng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bộ phận trán trên đầu, thường dùng trong văn viết cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('髹', '{"9000": "6129.0", "Chữ Trung Quốc": "髹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 髟 | Số nét | 16 | nét | 髹 | tượng hình | sơn mài đen, quét sơn mài — chưa tách được thành phần rõ ràng | 髹 có bộ 髟 (tiêu, tóc/lông dài) biểu nghĩa theo một cách đọc, hoặc có thể bộ 彡 (tóc/vẽ) liên quan. Nguồn không có trong Wiktionary. Có dạng tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hưu\": bộ tóc (髟) dài mềm + âm xiū — 髹 là động tác quét sơn mài mượt mà như vuốt tóc. | Gương Hán-Việt | 髹 — không có từ Hán-Việt độc lập phổ biến | Mở khoá kiến thức | Biết 髹 mở khoá từ vựng nghề sơn mài (漆器) trong mỹ thuật thủ công truyền thống Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | 髹 không có ghi chép nguồn gốc trong Wiktionary. Có dạng tiểu triện. Nghĩa: quét sơn mài (lacquer) màu đỏ nâu/đen; cũng là màu sơn mài đó. Dùng trong nghề thủ công sơn mài truyền thống Trung Hoa. Chưa có nguồn học thuật xác nhận cấu trúc chính thức. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sơn; quét sơn", "Hạng Tần Suất (Jun Da)": "6129.0", "Tần Suất % (Jun Da)": "99.9857486163", "GavinGrover_Once (Chiết tự trực tiếp)": "髟 + 休", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱髟休", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "休", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "髟", "Unihan_Simplified (Chữ Giản thể)": "髹", "Unihan_Traditional (Chữ Phồn thể)": "髹", "Pinyin_Xie": "xiū", "Âm Hán Việt_Xie": "hưu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ hành động quét sơn lên các vật dụng mỹ nghệ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('桫', '{"9000": "6130.0", "Chữ Trung Quốc": "桫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 11 | nét | 桫 | tượng hình | dương xỉ cổ thụ (tree fern) — chưa tách được thành phần rõ ràng | 桫 có bộ 木 (mộc, gỗ/cây) biểu nghĩa và 沙 biểu âm suō theo hình thức thị giác. Nguồn Wiktionary chỉ ghi {{Han etym}}, không có phân tích cấu trúc chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sa\": bộ cây (木) + âm suō — cây 桫欏 dương xỉ cổ thụ như \"sa\" mạc thời khủng long. | Gương Hán-Việt | 桫 — không có từ Hán-Việt độc lập phổ biến | Mở khoá kiến thức | Biết 桫 mở khoá tên 桫欏 — cây dương xỉ cổ thụ quý hiếm, \"hóa thạch sống\" từ kỷ Jura.", "Tự nguyên_Xie": "桫 có nguồn gốc chưa được Wiktionary ghi chép đầy đủ. Bộ 木 (mộc) biểu nghĩa chỉ cây. Nghĩa: viết tắt của 桫欏 (suōluó) — cây dương xỉ cổ thụ (tree fern), hóa thạch sống từ kỷ Jura. Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: sa la 桫欏,桫椤)", "Hạng Tần Suất (Jun Da)": "6130.0", "Tần Suất % (Jun Da)": "99.9857708381", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 沙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木沙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "沙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "桫", "Unihan_Traditional (Chữ Phồn thể)": "桫", "Pinyin_Xie": "suō", "Âm Hán Việt_Xie": "sa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, hầu như chỉ dùng trong tên gọi loài cây dương xỉ cổ đại sa la. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('葸', '{"9000": "6131.0", "Chữ Trung Quốc": "葸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 艹 | biểu nghĩa | cỏ cây (biến thể bộ 艸) | 思 | tư | biểu âm | suy nghĩ, nhớ nhung | 葸 = 艹(Thảo, biểu nghĩa: cỏ/cây) + 思 (Tư, biểu âm); chữ hình thanh. Bộ 艹 gợi cỏ héo rũ, bộ 思 cho âm xǐ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tơi\": cỏ (艹) nghĩ lo (思) mà rũ xuống — 葸 là sự nhút nhát rụt rè như cỏ yếu héo. | Gương Hán-Việt | tơi — 葸葸 (rụt rè), 葸怯 (nhút nhát) | Mở khoá kiến thức | Biết 葸 mở khoá từ vựng mô tả tính cách nhút nhát, rụt rè trong văn học cổ điển.", "Tự nguyên_Xie": "Theo Wiktionary: {{Han compound|艸|alt1=艹|思|ls=psc|c1=s|t1=grass|c2=p}}. Chữ hình thanh: 艹 biểu nghĩa (cỏ héo rũ), 思 biểu âm xǐ. Nghĩa: nhút nhát, sợ hãi, do dự không dám. Dùng trong từ 葸葸 (xǐxǐ, rụt rè) và 葸怯 (nhút nhát). Chữ ít dùng. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sợ sệt; sợ hãi", "Hạng Tần Suất (Jun Da)": "6131.0", "Tần Suất % (Jun Da)": "99.9859036519", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 思", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹思", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "思", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "葸", "Unihan_Traditional (Chữ Phồn thể)": "葸", "Pinyin_Xie": "xǐ", "Âm Hán Việt_Xie": "tỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ miêu tả dáng vẻ e sợ, rụt rè, thường dùng trong văn ngôn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('屣', '{"9000": "6132.0", "Chữ Trung Quốc": "屣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 尸 | Số nét | 14 | nét | 屣 | tượng hình | dép cỏ, giày rơm — chữ độc lập, chưa tách được thành phần rõ ràng | 屣 có bộ 尸 (thi, thân thể/vật có hình dáng) hoặc 履 liên quan, cùng với phần còn lại. Nguồn Wiktionary chỉ ghi {{Han etym}}, không có phân tích cấu trúc. Nghĩa: dép cỏ/giày nhẹ dễ trượt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tỉ\": 屣 là đôi dép cỏ rẻ tiền — nhắc đến 屣 là nhớ câu \"như ném dép cũ\" khi coi khinh điều gì. | Gương Hán-Việt | 屣 — không có từ Hán-Việt độc lập phổ biến | Mở khoá kiến thức | Biết 屣 mở khoá thành ngữ cổ điển 弃之如敝屣 (bỏ như dép rách) trong văn học Trung Hoa.", "Tự nguyên_Xie": "屣 có nguồn gốc chưa được Wiktionary ghi chép đầy đủ. Nghĩa: dép cỏ, giày rơm nhẹ (literary). Dùng trong thành ngữ 如弃敝屣 (như ném dép cũ — coi nhẹ), hoặc 倒屣迎 (đón khách quý nhanh đến mức đi dép ngược). Có dạng tiểu triện. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giày; hài; dép", "Hạng Tần Suất (Jun Da)": "6132.0", "Tần Suất % (Jun Da)": "99.9859253569", "GavinGrover_Once (Chiết tự trực tiếp)": "尸 + 徙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴尸徙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "徙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "尸", "Unihan_Simplified (Chữ Giản thể)": "屣", "Unihan_Traditional (Chữ Phồn thể)": "屣", "Pinyin_Xie": "xǐ", "Âm Hán Việt_Xie": "tỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ giày dép, thường xuất hiện trong các thành ngữ cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('獒', '{"9000": "6133.0", "Chữ Trung Quốc": "獒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 14 | nét | 獒 | ngao | tượng hình | chó ngao lớn, dữ; chữ tượng hình hình con chó to | 獒 là chữ tượng hình, mô tả một con chó lớn và dữ (mastiff). Cấu trúc nội tại chưa được phân tích rõ ràng trong nguồn học thuật; chưa có nguồn Wiktionary về liên kết hình-thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngao\": hình ảnh con chó ngao (獒) Tây Tạng khổng lồ, dữ tợn — vừa nhìn chữ vừa nghĩ đến tiếng gầm gừ \"ngao ngao\" của nó. | Gương Hán-Việt | ngao trong 藏獒 (Tạng Ngao – chó ngao Tây Tạng) | Mở khoá kiến thức | Biết 獒 (ngao) mở khoá các từ chỉ giống chó lớn trong văn học cổ Trung Hoa như 藏獒, 獒犬.", "Tự nguyên_Xie": "Tiểu triện | 獒 (ngao) xuất hiện trong tiểu triện, chỉ loại chó ngao to lớn, hung dữ. Không có phân tích hình-thanh hay hội ý rõ ràng trong nguồn Wiktionary. Chữ này dùng phổ biến trong hai từ: 獒犬 (chó ngao) và 藏獒 (chó ngao Tây Tạng). chưa có nguồn học thuật phân tích chi tiết cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chó ngao", "Hạng Tần Suất (Jun Da)": "6133.0", "Tần Suất % (Jun Da)": "99.9859470618", "GavinGrover_Once (Chiết tự trực tiếp)": "敖 + 犬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱敖犬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犬", "Unihan_Simplified (Chữ Giản thể)": "獒", "Unihan_Traditional (Chữ Phồn thể)": "獒", "Pinyin_Xie": "áo", "Âm Hán Việt_Xie": "ngao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ giống chó săn to khỏe, hung dữ vùng Tây Tạng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瘌', '{"9000": "6134.0", "Chữ Trung Quốc": "瘌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 14 | nét | 疒 | nạch | biểu nghĩa | bộ bệnh tật | 剌 | lạt | biểu âm | 瘌 là chữ hình thanh: bộ 疒 (nạch, biểu nghĩa: bệnh tật) kết hợp với 剌 (lạt, biểu âm). Chữ chỉ các bệnh da như ghẻ lở, hói đầu. Wiktionary chỉ ghi {{Han etym}} mà không phân tích chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không rõ (âm đọc là lả/lạt): bộ 疒 (bệnh) + 剌 (lạt/sắc) — da bị \"lạt\" bởi bệnh ghẻ lở, rụng tóc trông \"lả\" người. | Gương Hán-Việt | lả trong 瘌痢 (ghẻ lở đầu, hói) | Mở khoá kiến thức | Biết 瘌 giúp hiểu các từ y học cổ chỉ bệnh ngoài da trong văn bản cổ điển Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | 瘌 (lạt/lả) là chữ chỉ bệnh ngoài da nghiêm trọng, bao gồm ghẻ lở và hói đầu do bệnh. Bộ 疒 xác định đây là bệnh tật; thành phần 剌 đóng vai trò biểu âm. Hình tiểu triện còn lưu giữ. chưa có nguồn học thuật phân tích chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ghẻ lở; hói đầu", "Hạng Tần Suất (Jun Da)": "6134.0", "Tần Suất % (Jun Da)": "99.9859687668", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 剌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒剌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "剌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "瘌", "Unihan_Traditional (Chữ Phồn thể)": "瘌", "Pinyin_Xie": "là", "Âm Hán Việt_Xie": "lạt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ miêu tả tình trạng da đầu bị ghẻ lở gây rụng tóc. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('佴', '{"9000": "6135.0", "Chữ Trung Quốc": "佴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 8 | nét | 亻 | nhân | biểu nghĩa | người | 耳 | nhĩ | biểu âm | tai | 佴 là chữ hình thanh: bộ 亻 (nhân, biểu nghĩa: người) kết hợp với 耳 (nhĩ, biểu âm). Chữ có hai âm đọc: èr (thứ hai, phụ tá) và nài (họ, trợ lý). Tiểu triện và lục thư thông đều lưu giữ dạng chữ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không rõ phổ biến (âm nại/nhị): 亻(người) + 耳(tai) — người luôn để tai nghe theo, đứng thứ hai, làm \"nhị\" (phụ tá) cho chủ. | Gương Hán-Việt | nhị trong nghĩa thứ hai, phụ tá | Mở khoá kiến thức | Biết 佴 giúp hiểu các chức vụ phụ tá thứ hai trong văn bản hành chính cổ Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 佴 (nhị/nại) là chữ hình thanh, gồm 亻 (người) là thành phần biểu nghĩa và 耳 biểu âm. Có hai nghĩa chính: (1) âm èr: đặt để, xếp sau; (2) âm nài: người phụ tá, trợ lý, cũng là họ. Dạng tiểu triện và lục thư thông còn lưu lại. chưa có nguồn học thuật phân tích chi tiết cấu tạo nguyên thủy. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đặt để, dừng lại", "Hạng Tần Suất (Jun Da)": "6135.0", "Tần Suất % (Jun Da)": "99.9859904718", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 耳", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻耳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "耳", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "佴", "Unihan_Traditional (Chữ Phồn thể)": "佴", "Pinyin_Xie": "èr", "Âm Hán Việt_Xie": "nhị, nại", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường dùng làm động từ chỉ sự đặt để hoặc làm danh từ chỉ người phụ tá. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锫', '{"9000": "6136.0", "Chữ Trung Quốc": "锫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 13 | nét | 钅 | kim | biểu nghĩa | kim loại | 咅 | bôi | biểu âm | 锫 là chữ hình thanh hiện đại: bộ 钅 (kim, biểu nghĩa: kim loại) kết hợp với thành phần biểu âm. Đây là chữ tạo muộn để phiên âm tên nguyên tố hóa học berkelium (Bk, số 97). Không có dạng giáp cốt hay kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không có phổ biến (âm bồi/péi): 钅(kim loại) — chữ tạo muộn cho nguyên tố berkelium (Bk), kim loại phóng xạ được \"bồi đắp\" thêm vào bảng tuần hoàn. | Gương Hán-Việt | bồi trong 锫 (berkelium – nguyên tố 97) | Mở khoá kiến thức | Biết 锫 giúp nhận ra quy tắc đặt tên nguyên tố hóa học trong chữ Hán: bộ 钅 + âm phiên.", "Tự nguyên_Xie": "锫 là chữ tạo muộn trong thế kỷ 20 để phiên âm tên nguyên tố hóa học berkelium (Bk, nguyên tử số 97), được đặt tên theo thành phố Berkeley, California. Bộ 钅 xác nhận đây là kim loại; phần còn lại biểu âm péi. Chưa có dạng chữ cổ. chưa có nguồn học thuật phân tích chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố berkeli, Bk", "Hạng Tần Suất (Jun Da)": "6136.0", "Tần Suất % (Jun Da)": "99.9860121768", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 咅", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅咅", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "咅", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锫", "Unihan_Traditional (Chữ Phồn thể)": "錇", "Pinyin_Xie": "péi", "Âm Hán Việt_Xie": "bồi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ nguyên tố hóa học Berkeli trong bảng tuần hoàn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('隰', '{"9000": "6137.0", "Chữ Trung Quốc": "隰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 16 | nét | 阜 | phụ | biểu nghĩa | gò đất, đất cao | 㬎 | biểu âm | 隰 là chữ hình thanh: bộ 阜 (phụ, biểu nghĩa: đất, địa hình) kết hợp với 㬎 (biểu âm). Nghĩa gốc là vùng đất trũng, ẩm thấp — ngược với 阜 (đất cao). Dạng tiểu triện và lục thư thông còn lưu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thấp\": bộ 阜 (đất) + 㬎 (biểu âm) — vùng đất \"thấp\" trũng, ẩm ướt, nơi cây cỏ um tùm như mô tả trong Kinh Thi. | Gương Hán-Việt | thấp trong 隰地 (vùng đất trũng), cùng âm với 湿 (ẩm) | Mở khoá kiến thức | Biết 隰 (thấp) giúp đọc hiểu các bài thơ trong Kinh Thi mô tả địa hình đồng quê cổ Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 隰 (thấp/tập) là chữ hình thanh, gồm bộ 阜 (đất, địa hình) biểu nghĩa và 㬎 biểu âm. Nghĩa gốc là vùng đất thấp, ẩm ướt, hoặc ruộng mới khai khẩn. Kinh Thi có câu: 隰有萇楚，猗儺其枝 (Ở vùng đất trũng có cây carambola, cành lá mềm mại). Ngoài ra còn có nghĩa là im lặng không nói (phương ngữ Mân Nam). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chỗ đất trũng; ruộng mới vỡ", "Hạng Tần Suất (Jun Da)": "6137.0", "Tần Suất % (Jun Da)": "99.9860338817", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + 㬎", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝㬎", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㬎", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "隰", "Unihan_Traditional (Chữ Phồn thể)": "隰", "Pinyin_Xie": "xí", "Âm Hán Việt_Xie": "thấp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ vùng đất trũng ẩm ướt hoặc đầm lầy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('醌', '{"9000": "6138.0", "Chữ Trung Quốc": "醌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 15 | nét | 酉 | dậu | biểu nghĩa | bộ rượu, hóa chất | 昆 | côn | biểu âm | 醌 là chữ hình thanh hiện đại: bộ 酉 (dậu, biểu nghĩa: rượu/hóa chất) kết hợp với thành phần biểu âm kūn. Đây là chữ tạo muộn để phiên âm thuật ngữ hóa học quinone. Không có dạng giáp cốt hay kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến (âm côn/kūn): 酉(hóa chất) — chữ tạo muộn cho quinone, hợp chất vòng thơm quan trọng trong sinh hóa (như vitamin K, coenzyme Q). | Gương Hán-Việt | côn trong 醌 (quinone – hợp chất hóa học) | Mở khoá kiến thức | Biết 醌 giúp đọc hiểu tài liệu hóa học và sinh hóa tiếng Trung về các hợp chất quinone.", "Tự nguyên_Xie": "醌 là chữ tạo muộn trong thế kỷ 19-20 để phiên âm thuật ngữ hóa học quinone (quinon), một hợp chất hữu cơ quan trọng trong hóa học. Bộ 酉 xác nhận đây là hợp chất hóa học; phần còn lại biểu âm kūn. Chưa có dạng chữ cổ. chưa có nguồn học thuật phân tích chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quinon (hoá học)", "Hạng Tần Suất (Jun Da)": "6138.0", "Tần Suất % (Jun Da)": "99.9860555867", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 昆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉昆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "醌", "Unihan_Traditional (Chữ Phồn thể)": "醌", "Pinyin_Xie": "kūn", "Âm Hán Việt_Xie": "côn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ dùng trong thuật ngữ hóa học để chỉ hợp chất quinon. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鰕', '{"9000": "6139.0", "Chữ Trung Quốc": "鰕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 20 | nét | 魚 | ngư | biểu nghĩa | cá | 叚 | giả | biểu âm | 鰕 là chữ hình thanh: bộ 魚 (ngư, biểu nghĩa: cá/thủy sinh) kết hợp với thành phần biểu âm. Vốn chỉ loài kỳ nhông khổng lồ (giant salamander) và con bống (goby); sau dùng thay cho 蝦 (tôm). Wiktionary ghi nhận cả ba nghĩa này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến (âm hà/xiā): 魚(cá) — chữ cổ trong Sơn Hải Kinh chỉ sinh vật nước lớn; ngày nay thường thấy thay cho 蝦 (tôm), cùng đọc xiā. | Gương Hán-Việt | hà trong 鰕魚 (cá bống), 鰕虎魚 (cá bống hổ) | Mở khoá kiến thức | Biết 鰕 giúp đọc hiểu văn bản cổ Trung Hoa như Sơn Hải Kinh và phân biệt với 蝦 (tôm) hiện đại.", "Tự nguyên_Xie": "鰕 (hà) là chữ cổ, xuất hiện trong Sơn Hải Kinh với nghĩa loài kỳ nhông khổng lồ sống trên đồi (hình dáng như con báo). Sau đó chỉ con bống (goby), và cũng dùng thay thế cho 蝦 (tôm, tôm hùm). Bộ 魚 biểu nghĩa thủy sinh. Chưa có phân tích học thuật rõ hơn về cấu tạo. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con tôm", "Hạng Tần Suất (Jun Da)": "6139.0", "Tần Suất % (Jun Da)": "99.9861207016", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 叚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚叚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "叚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鰕", "Unihan_Traditional (Chữ Phồn thể)": "鰕", "Pinyin_Xie": "xiā", "Âm Hán Việt_Xie": "hà", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ con tôm, thường dùng trong văn tự cổ hoặc tên gọi sinh học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('岽', '{"9000": "6140.0", "Chữ Trung Quốc": "岽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 8 | nét | 山 | sơn | biểu nghĩa | núi | 东 | đông | biểu âm | 岽 là chữ hình thanh: bộ 山 (sơn, biểu nghĩa: núi) kết hợp với 东 (đông, biểu âm). Đây là chữ mượn từ tiếng Choang (壮语 ndoeng = rừng), dùng trong địa danh ở Quảng Tây. Wiktionary ghi nhận đây là vay mượn từ tiếng Choang.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến (âm đông/dōng): 山(núi) + 东(đông/biểu âm) — địa danh núi rừng phía Đông Quảng Tây, vay mượn từ tiếng Choang \"ndoeng\" (rừng). | Gương Hán-Việt | đông trong địa danh Quảng Tây | Mở khoá kiến thức | Biết 岽 giúp nhận ra địa danh thuộc khu tự trị dân tộc Choang, tỉnh Quảng Tây trong bản đồ Trung Quốc.", "Tự nguyên_Xie": "岽 là chữ tạo để phiên âm từ tiếng Choang (Zhuang: ndoeng, nghĩa là rừng). Dạng đầy đủ là 崬, đơn giản hóa thành 岽. Chữ xuất hiện chủ yếu trong địa danh ở khu tự trị dân tộc Choang, tỉnh Quảng Tây, Trung Quốc. Không có dạng giáp cốt hay kim văn vì đây là chữ tạo muộn. chưa có nguồn học thuật phân tích chi tiết hơn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên núi nay thuộc khu tự trị dân tộc Choang, tỉnh Quảng Tây)", "Hạng Tần Suất (Jun Da)": "6140.0", "Tần Suất % (Jun Da)": "99.9861418898", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 东", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱山东", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "东", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "岽", "Unihan_Traditional (Chữ Phồn thể)": "崬", "Pinyin_Xie": "dōng", "Âm Hán Việt_Xie": "đông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ riêng dùng trong địa danh, cụ thể là tên một ngọn núi ở Quảng Tây. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('昃', '{"9000": "6141.0", "Chữ Trung Quốc": "昃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 8 | nét | 昃 | trắc | tượng hình | hình mặt trời lúc xế chiều, nghiêng về phía tây | 昃 là chữ tượng hình hoặc hội ý: hình vẽ mặt trời đang nghiêng (xế) xuống phía tây vào buổi chiều. Giáp cốt văn có rất nhiều dạng (13 biến thể), kim văn và tiểu triện đều lưu giữ, cho thấy chữ đã tồn tại từ thời Thương. Wiktionary chỉ ghi {{Han etym}} mà không phân tích chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến (âm trắc/zè): hình mặt trời đang \"trắc\" (nghiêng) về phía tây lúc xế chiều — giáp cốt văn vẽ rõ mặt trời xiên góc, không còn thẳng đứng trên đỉnh đầu. | Gương Hán-Việt | trắc trong 昃食 (ăn lúc xế chiều), văn học cổ điển Trung Hoa | Mở khoá kiến thức | Biết 昃 giúp đọc hiểu văn thơ cổ điển Trung Hoa miêu tả thời gian trong ngày, đặc biệt là buổi chiều tà.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Tiểu triện | Lục thư thông | 昃 (trắc/zè) xuất hiện từ thời giáp cốt văn (Thương triều) với nhiều biến thể hình vẽ mặt trời lúc xế chiều. Kim văn, tiểu triện và lục thư thông đều lưu giữ dạng chữ. Nghĩa chính là buổi chiều, mặt trời lúc quá trưa (qua đỉnh, đang xế). Không có phân tích cấu tạo học thuật rõ ràng trong Wiktionary; chưa có nguồn học thuật phân tích chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xế, mặt trời lúc quá trưa", "Hạng Tần Suất (Jun Da)": "6141.0", "Tần Suất % (Jun Da)": "99.986163078", "GavinGrover_Once (Chiết tự trực tiếp)": "日 + 仄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱日仄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "仄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "昃", "Unihan_Traditional (Chữ Phồn thể)": "昃", "Pinyin_Xie": "zè", "Âm Hán Việt_Xie": "trắc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ việc mặt trời ngả về tây sau buổi trưa hoặc làm danh từ chỉ buổi chiều tà. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('螓', '{"9000": "6142.0", "Chữ Trung Quốc": "螓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 16 | nét | 虫 | trùng | biểu nghĩa | sâu bọ, côn trùng | 秦 | tần | biểu âm | 螓 là chữ hình thanh: bộ 虫 (trùng, biểu nghĩa: côn trùng) kết hợp với 秦 (tần, biểu âm). Chữ chỉ loài ve sầu nhỏ đầu vuông, cũng chỉ ruồi nhà trong một số tài liệu cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến (âm tần/qín): 虫(trùng) + 秦(biểu âm) — con ve sầu \"tần\" đầu vuông, tiếng kêu mùa hè; vẻ đẹp đầu trán rộng gợi tả trong thành ngữ 螓首蛾眉. | Gương Hán-Việt | tần trong 螓首蛾眉 (tần thủ nga mi – đầu vuông lông mày ngài, vẻ đẹp phụ nữ) | Mở khoá kiến thức | Biết 螓 giúp hiểu thành ngữ thẩm mỹ cổ Trung Hoa: 螓首蛾眉 trong Kinh Thi mô tả vẻ đẹp người phụ nữ.", "Tự nguyên_Xie": "螓 (tần/qín) là chữ hình thanh, gồm 虫 (côn trùng) biểu nghĩa và 秦 biểu âm. Wiktionary: \"a small cicada with a square head\" và \"housefly\" (nghĩa cổ). Chữ xuất hiện trong thành ngữ 螓首蛾眉 (đầu vuông lông mày ngài) để ca ngợi vẻ đẹp người phụ nữ trong Kinh Thi. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con cồ cộ", "Hạng Tần Suất (Jun Da)": "6142.0", "Tần Suất % (Jun Da)": "99.9861842662", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 秦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫秦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "秦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "螓", "Unihan_Traditional (Chữ Phồn thể)": "螓", "Pinyin_Xie": "qín", "Âm Hán Việt_Xie": "tần", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài ve sầu nhỏ có đầu rộng và vuông. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('垧', '{"9000": "6143.0", "Chữ Trung Quốc": "垧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 9 | nét | 土 | thổ | biểu nghĩa | đất | 向 | hướng | biểu âm | 垧 là chữ hình thanh: bộ 土 (thổ, biểu nghĩa: đất) kết hợp với 向 (hướng, biểu âm). Chữ chỉ đơn vị đo diện tích đất đai ở Trung Quốc (thưởng/shǎng). Không có dạng chữ cổ vì đây là chữ tạo muộn. chưa có nguồn học thuật phân tích chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến (âm thưởng/shǎng): 土(đất) — đơn vị đo đất ruộng vùng Đông Bắc Trung Quốc, to \"thưởng\" hơn mẫu thường. | Gương Hán-Việt | thưởng trong đơn vị đo đất đai ở phương Bắc Trung Quốc | Mở khoá kiến thức | Biết 垧 giúp đọc hiểu tài liệu lịch sử và địa lý nông nghiệp vùng Đông Bắc Trung Quốc.", "Tự nguyên_Xie": "垧 (thưởng) là chữ tạo muộn, chỉ đơn vị đo diện tích đất ở Trung Quốc. Giá trị của một 垧 thay đổi theo vùng miền, thường bằng 3 đến 10 mẫu (亩). Bộ 土 biểu nghĩa đất đai, phần còn lại biểu âm shǎng. Không có nguồn Wiktionary phân tích chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thưởng (đơn vị đo diện tích đất đai, Trung Quốc)", "Hạng Tần Suất (Jun Da)": "6143.0", "Tần Suất % (Jun Da)": "99.9862054544", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 向", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土向", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "向", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "垧", "Unihan_Traditional (Chữ Phồn thể)": "垧", "Pinyin_Xie": "shǎng", "Âm Hán Việt_Xie": "thưởng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Lượng từ | 量词 | Chữ này làm lượng từ tương đương với một héc-ta đất ở vùng Đông Bắc Trung Quốc. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('廨', '{"9000": "6144.0", "Chữ Trung Quốc": "廨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 广 | Số nét | 16 | nét | 广 | quảng | biểu nghĩa | mái nhà, tòa nhà | 解 | giải | biểu âm | 廨 là chữ hình thanh: bộ 广 (quảng, biểu nghĩa: tòa nhà, mái che) kết hợp với 解 (giải, biểu âm). Chữ chỉ công sở, dinh quan, nơi các quan lại làm việc. Không có dạng chữ cổ vì đây là chữ tạo muộn. chưa có nguồn học thuật phân tích chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến (âm giải/xiè): 广(tòa nhà) + 解(biểu âm) — tòa nhà để \"giải\" quyết công việc nhà nước, tức là công sở, dinh quan. | Gương Hán-Việt | giải trong 公廨 (công giải – công sở, dinh quan) | Mở khoá kiến thức | Biết 廨 giúp đọc hiểu văn bản hành chính cổ Trung Hoa về các cơ quan nhà nước và dinh thự quan lại.", "Tự nguyên_Xie": "廨 (giải/xiè) là chữ hình thanh chỉ công sở, dinh quan của triều đình phong kiến. Bộ 广 biểu nghĩa tòa nhà; phần 解 biểu âm xiè. Không có nguồn Wiktionary phân tích chi tiết về cấu tạo. chưa có nguồn học thuật phân tích chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sở công, dinh quan", "Hạng Tần Suất (Jun Da)": "6144.0", "Tần Suất % (Jun Da)": "99.9862266426", "GavinGrover_Once (Chiết tự trực tiếp)": "广 + 解", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴广解", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "解", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "广", "Unihan_Simplified (Chữ Giản thể)": "廨", "Unihan_Traditional (Chữ Phồn thể)": "廨", "Pinyin_Xie": "xiè", "Âm Hán Việt_Xie": "giải", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ nơi làm việc của quan lại thời phong kiến. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('骺', '{"9000": "6145.0", "Chữ Trung Quốc": "骺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 骨 | Số nét | 15 | nét | 骨 | cốt | biểu nghĩa | xương | 侯 | hầu | biểu âm | 骺 là chữ hình thanh: bộ 骨 (cốt, biểu nghĩa: xương) kết hợp với 侯 (hầu, biểu âm). Chữ chỉ đầu mút của xương dài (epiphysis) trong giải phẫu học và y học. Không có dạng chữ cổ. chưa có nguồn học thuật phân tích chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến (âm hầu/hóu): 骨(xương) + 侯(biểu âm) — phần \"hầu\" (đầu nhô ra) của xương dài, tức là epiphysis trong y học. | Gương Hán-Việt | hầu trong 骨骺 (cốt hầu – đầu mút xương, epiphysis) | Mở khoá kiến thức | Biết 骺 giúp đọc hiểu tài liệu y học và giải phẫu tiếng Trung về cấu trúc xương.", "Tự nguyên_Xie": "骺 (hầu/hóu) là chữ hình thanh chuyên dùng trong y học và giải phẫu học, chỉ phần đầu mút của xương dài (epiphysis). Bộ 骨 biểu nghĩa xương; 侯 biểu âm hóu. Chưa có dạng chữ cổ và không có nguồn Wiktionary phân tích chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mấu trên não, đầu xương", "Hạng Tần Suất (Jun Da)": "6145.0", "Tần Suất % (Jun Da)": "99.9862478308", "GavinGrover_Once (Chiết tự trực tiếp)": "骨 + 后", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰骨后", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "后", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "骨", "Unihan_Simplified (Chữ Giản thể)": "骺", "Unihan_Traditional (Chữ Phồn thể)": "骺", "Pinyin_Xie": "hóu", "Âm Hán Việt_Xie": "hầu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ phần đầu xương hoặc sụn khớp trong giải phẫu học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('黥', '{"9000": "6146.0", "Chữ Trung Quốc": "黥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 黑 | Số nét | 20 | nét | 黑 | hắc | biểu nghĩa | đen; thích chữ vào mặt như hình phạt | 京 | kinh | biểu âm | 黥 là chữ hình thanh: bộ 黑 (hắc, biểu nghĩa: đen, thích mực vào mặt như hình phạt) kết hợp với 京 (kinh, biểu âm). Wiktionary ghi rõ: \"to brand one''s face\" — thích chữ vào mặt tội nhân bằng mực đen.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến (âm kình/qíng): 黑(mực đen) + 京(biểu âm) — hình phạt \"kình\" thích chữ bằng mực đen vào mặt tội nhân, một trong Ngũ Hình thời cổ. | Gương Hán-Việt | kình trong 黥刑 (kình hình – hình phạt thích chữ vào mặt), 黥布 (Kình Bố – tên nhân vật lịch sử) | Mở khoá kiến thức | Biết 黥 giúp hiểu hệ thống Ngũ Hình trong luật pháp cổ Trung Hoa và đọc hiểu tên nhân vật lịch sử Kình Bố (黥布) thời Sở Hán tranh hùng.", "Tự nguyên_Xie": "Tiểu triện | 黥 (kình/qíng) là chữ hình thanh, gồm 黑 (đen; thích vào mặt như hình phạt) biểu nghĩa và 京 biểu âm. Đây là một trong Ngũ Hình (五刑) của Trung Hoa cổ đại: dùng kim châm và mực đen thích chữ lên trán hoặc mặt tội nhân. Hình phạt này xuất hiện nhiều trong lịch sử Hán đến Đường. Tiểu triện còn lưu dạng chữ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thích vào, khắc vào", "Hạng Tần Suất (Jun Da)": "6146.0", "Tần Suất % (Jun Da)": "99.986269019", "GavinGrover_Once (Chiết tự trực tiếp)": "黑 + 京", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰黑京", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "京", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "黑", "Unihan_Simplified (Chữ Giản thể)": "黥", "Unihan_Traditional (Chữ Phồn thể)": "黥", "Pinyin_Xie": "qíng", "Âm Hán Việt_Xie": "kình", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ chỉ hình phạt xăm chữ vào mặt thời phong kiến hoặc danh từ chỉ vết xăm đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('豳', '{"9000": "6147.0", "Chữ Trung Quốc": "豳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 豕 | Số nét | 17 | nét | 豳 | bân | tượng hình | địa danh cổ nước Chu, hình ảnh liên quan đến heo/đất | 豳 là chữ có bộ 豕 (thỉ – lợn), cấu tạo phức tạp. Wiktionary chỉ ghi {{Han etym}} mà không phân tích chi tiết. Đây là địa danh cổ chỉ nước Bân (Bīn) thời nhà Chu, nơi Hậu Tắc khai lập nghiệp. Tiểu triện còn lưu dạng chữ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bân\": địa danh cổ nước Bân thời Chu — đọc bài Bân Phong (豳風) trong Kinh Thi là đọc về cuộc sống nông thôn nơi tổ tiên họ Cơ (nhà Chu) khai nghiệp. | Gương Hán-Việt | bân trong 豳風 (Bân Phong – phần Kinh Thi về vùng Bân) | Mở khoá kiến thức | Biết 豳 giúp đọc hiểu Kinh Thi, đặc biệt phần Bân Phong (豳風) mô tả cuộc sống nông thôn và lịch sử nhà Chu.", "Tự nguyên_Xie": "Tiểu triện | 豳 (bân/bīn) là tên địa danh cổ, chỉ vùng đất Bân – nơi tổ tiên nhà Chu (Hậu Tắc) sinh sống và khai nghiệp. Bài thơ 豳風 (Bân Phong) trong Kinh Thi mô tả cuộc sống nông thôn tại vùng đất này. Cấu tạo có bộ 豕 (lợn), tiểu triện còn lưu; chưa có phân tích học thuật chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước Bân", "Hạng Tần Suất (Jun Da)": "6147.0", "Tần Suất % (Jun Da)": "99.9862902072", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 豩", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴山豩", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "豩", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "豳", "Unihan_Traditional (Chữ Phồn thể)": "豳", "Pinyin_Xie": "bīn", "Âm Hán Việt_Xie": "bân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ riêng chỉ địa danh cổ hoặc nước Bân thời nhà Chu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('荑', '{"9000": "6148.0", "Chữ Trung Quốc": "荑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 荑 | di | tượng hình | chồi non của cỏ, mầm non | 荑 là chữ chưa được phân tích cấu trúc rõ ràng trong Wiktionary. Bộ 艸 (cỏ) xác nhận liên quan đến thực vật; phần còn lại chưa được phân tích. Wiktionary chỉ ghi {{Han etym}} không có chi tiết. Bạch thư, đại triện và tiểu triện còn lưu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"di\": chữ có bộ cỏ — 柔荑 (mầm non mềm mại) trong Kinh Thi ví đôi tay người đẹp như những mầm cỏ non mềm mại vươn ra mùa xuân. | Gương Hán-Việt | di trong 柔荑 (nhu di – mầm non mềm mại), 荑手 (tay mềm như mầm non) | Mở khoá kiến thức | Biết 荑 giúp hiểu hình ảnh thơ cổ điển Trung Hoa về vẻ đẹp của người phụ nữ qua Kinh Thi.", "Tự nguyên_Xie": "Bạch thư | Đại triện | Tiểu triện | 荑 (di/tí) xuất hiện từ thời bạch thư, có hai âm đọc: tí (chỉ chồi non, mầm cỏ) và yí (cắt cỏ dại). Chữ xuất hiện trong Kinh Thi với hình ảnh 柔荑 (nhu di) — đôi tay mềm như mầm non — ca ngợi vẻ đẹp ngón tay người phụ nữ. Bạch thư, đại triện và tiểu triện đều còn lưu dạng chữ. chưa có nguồn học thuật phân tích chi tiết cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cắt cỏ; cỏ di", "Hạng Tần Suất (Jun Da)": "6148.0", "Tần Suất % (Jun Da)": "99.9864168195", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 夷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹夷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "荑", "Unihan_Traditional (Chữ Phồn thể)": "荑", "Pinyin_Xie": "tí", "Âm Hán Việt_Xie": "di, đề", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ chồi non của cỏ tranh hoặc động từ chỉ việc làm cỏ, dọn cỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('莶', '{"9000": "6149.0", "Chữ Trung Quốc": "莶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 10 | nét | 艸 | tháo | biểu nghĩa | cỏ, thực vật | 僉 | thiêm | biểu âm | 莶 là chữ hình thanh: bộ 艸 (tháo, biểu nghĩa: cỏ) kết hợp với 僉 (thiêm, biểu âm). Chữ chỉ cây hy hiêm (豨薟/豨莶), một loại cây thuốc trong y học cổ truyền. Tiểu triện còn lưu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến (âm hiêm/xiān): 艸(cỏ) + 僉(biểu âm) — cây hy hiêm (豨莶) trong y học cổ truyền, vị thuốc \"thiêm\" (có vị đắng) chữa phong thấp. | Gương Hán-Việt | hiêm trong 豨莶 (hy hiêm – tên cây thuốc) | Mở khoá kiến thức | Biết 莶 giúp đọc hiểu tài liệu y học cổ truyền Trung Hoa về các cây thuốc trong các bài thuốc trị phong thấp.", "Tự nguyên_Xie": "Tiểu triện | 莶 (hiêm/xiān) là chữ hình thanh, gồm 艸 (cỏ) biểu nghĩa và 僉 biểu âm. Wiktionary dẫn dạng đầy đủ là 薟, cùng cấu tạo. Chữ thường dùng trong từ 豨莶 (hy hiêm) — loại cây thuốc dùng trong y học cổ truyền Trung Hoa để chữa phong thấp và tê liệt. Tiểu triện còn lưu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: hy hiêm 豨薟,豨莶)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 佥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹佥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "佥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "莶", "Unihan_Traditional (Chữ Phồn thể)": "莶", "Pinyin_Xie": "xiān", "Âm Hán Việt_Xie": "hiêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ và hầu như chỉ xuất hiện trong tên vị thuốc hy thiêm thảo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蓊', '{"9000": "6150.0", "Chữ Trung Quốc": "蓊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 13 | nét | 艹 | tháo | biểu nghĩa | cỏ, thực vật | 翁 | ông | biểu âm | 蓊 là chữ hình thanh: bộ 艹 (tháo, biểu nghĩa: cỏ/cây) kết hợp với 翁 (ông, biểu âm). Chữ chỉ cây cối rậm rạp, um tùm. Wiktionary ghi rõ: \"lush; luxuriant; flourishing\" — tươi tốt, phồn thịnh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến (âm ông/wěng): 艹(cỏ) + 翁(ông) — khu rừng \"ông\" già um tùm, cây cối rậm rạp như mái tóc bạc trắng của cụ ông dày dặn che khuất bầu trời. | Gương Hán-Việt | ông trong 蓊鬱 (ông uất – cây cối rậm rạp, tươi tốt) | Mở khoá kiến thức | Biết 蓊 giúp đọc hiểu văn thơ cổ điển Trung Hoa mô tả cảnh rừng cây um tùm, rậm rạp.", "Tự nguyên_Xie": "蓊 (ông/wěng) là chữ hình thanh, gồm 艹 (cỏ/cây) biểu nghĩa và 翁 biểu âm. Wiktionary mô tả: \"of vegetation: lush, luxuriant, flourishing\" — cây cối rậm rạp, um tùm, xanh tươi. Dùng nhiều trong thành ngữ 蓊鬱 (ông uất) và 蓊蓊鬱鬱 mô tả rừng cây dày đặc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "um tùm", "Hạng Tần Suất (Jun Da)": "6150.0", "Tần Suất % (Jun Da)": "99.9864581623", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 翁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹翁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "翁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蓊", "Unihan_Traditional (Chữ Phồn thể)": "蓊", "Pinyin_Xie": "wěng", "Âm Hán Việt_Xie": "ống", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ miêu tả trạng thái cây cối mọc rậm rạp, xanh tốt. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('揎', '{"9000": "6151.0", "Chữ Trung Quốc": "揎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 12 | nét | 手 | thủ | biểu nghĩa | tay | 宣 | tuyên | biểu âm | 揎 là chữ hình thanh: bộ 手 (thủ, biểu nghĩa: tay) kết hợp với 宣 (tuyên, biểu âm). Wiktionary ghi rõ: \"to roll up the sleeves\" — xắn tay áo lên. Nghĩa mở rộng: đấm, đánh bằng nắm đấm trần.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến (âm tuyên/xuān): 手(tay) + 宣(biểu âm) — \"tuyên\" xắn tay áo lên, lộ cánh tay trần sẵn sàng chiến đấu — động tác quen thuộc của dũng sĩ trong tiểu thuyết cổ. | Gương Hán-Việt | tuyên trong 揎拳 (tuyên quyền – vén tay đấm) | Mở khoá kiến thức | Biết 揎 giúp hiểu thành ngữ và mô tả hành động vật lý trong văn học võ hiệp Trung Hoa cổ điển.", "Tự nguyên_Xie": "揎 (tuyên/xuān) là chữ hình thanh, gồm 手 (tay) biểu nghĩa và 宣 biểu âm. Nghĩa gốc: xắn tay áo lên, lộ cánh tay. Từ đó mở rộng sang đấm bằng nắm đấm trần và đẩy/xô. Xuất hiện nhiều trong thành ngữ chỉ hành động hăng hái, chiến đấu như 揎拳捋袖 (vén tay sẵn sàng đánh). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xắn tay áo", "Hạng Tần Suất (Jun Da)": "6151.0", "Tần Suất % (Jun Da)": "99.9864788337", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 宣", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌宣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宣", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "揎", "Unihan_Traditional (Chữ Phồn thể)": "揎", "Pinyin_Xie": "xuān", "Âm Hán Việt_Xie": "tuyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ chỉ hành động xắn tay áo lên để chuẩn bị làm việc hoặc đánh nhau. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('娈', '{"9000": "6152.0", "Chữ Trung Quốc": "娈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 9 | nét | 娈 | loan | tượng hình | người con gái tươi đẹp, dễ thương; chưa phân tích được chi tiết từ nguồn Wiktionary | 娈 là dạng giản thể của 孌. Dạng phồn thể 孌 chưa được Wiktionary phân tích cấu tạo chi tiết (chỉ ghi phát âm và nghĩa). Kim văn (3 biến thể), tiểu triện và lục thư thông đều còn lưu dạng chữ 孌.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến (âm loan/luán): chữ có bộ nữ (女) — vẻ đẹp \"loan\" (uyển chuyển như loan phượng), dùng trong thơ cổ miêu tả nét đẹp thanh tú. | Gương Hán-Việt | loan trong 婉娈 (uyển loan – vẻ đẹp dịu dàng), văn thơ cổ điển Trung Hoa | Mở khoá kiến thức | Biết 娈 giúp hiểu ngôn ngữ thơ cổ điển Trung Hoa về vẻ đẹp người phụ nữ trong Kinh Thi và Sở Từ.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | 娈 (loan/luán) là dạng giản thể của 孌. Kim văn của dạng phồn thể 孌 còn lưu 3 biến thể, cùng tiểu triện và lục thư thông. Wiktionary ghi nghĩa: (văn học) xinh đẹp, dễ thương; (văn học) ngoan ngoãn, dễ bảo. Kinh Thi có câu: 猗嗟孌兮，清揚婉兮 (xinh đẹp thay, ánh mắt sáng khuôn mặt duyên dáng). chưa có nguồn học thuật phân tích chi tiết cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tươi tắn", "Hạng Tần Suất (Jun Da)": "6152.0", "Tần Suất % (Jun Da)": "99.9864995051", "GavinGrover_Once (Chiết tự trực tiếp)": "亦 + 女", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱亦女", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "娈", "Unihan_Traditional (Chữ Phồn thể)": "孌", "Pinyin_Xie": "luán", "Âm Hán Việt_Xie": "luyến", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ đứng trước danh từ để miêu tả vẻ đẹp thanh tú của con người. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嫜', '{"9000": "6153.0", "Chữ Trung Quốc": "嫜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 14 | nét | 女 | nữ | biểu nghĩa | phụ nữ, quan hệ gia đình qua hôn nhân | 章 | chương | biểu âm | 嫜 là chữ hình thanh: bộ 女 (nữ, biểu nghĩa: phụ nữ, quan hệ gia đình) kết hợp với 章 (chương, biểu âm). Chữ chỉ cha mẹ chồng (cụ thể là bố chồng theo Wiktionary: \"the father and mother of a woman''s husband\"). Wiktionary chỉ ghi {{Han etym}} mà không phân tích chi tiết cấu tạo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến (âm chương/zhāng): 女(nữ) + 章(chương) — người phụ nữ nhìn \"chương\" (chương sách uy nghiêm) kính cẩn gọi là bố chồng mình. | Gương Hán-Việt | chương trong 姑嫜 (cô chương – mẹ chồng bố chồng) | Mở khoá kiến thức | Biết 嫜 giúp đọc hiểu các bài thơ cổ điển mô tả quan hệ gia đình bên chồng và lễ nghi dâu con.", "Tự nguyên_Xie": "嫜 (chương/zhāng) là chữ hình thanh, gồm bộ 女 (phụ nữ/quan hệ hôn nhân) biểu nghĩa và 章 biểu âm. Wiktionary ghi: \"the father and mother of a woman''s husband\" — cha mẹ chồng. Trong dùng thực tế cổ đại, 嫜 thường chỉ bố chồng, còn 姑 chỉ mẹ chồng; 姑嫜 là cụm chỉ cả hai. chưa có nguồn học thuật phân tích chi tiết cấu tạo. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bố chồng", "Hạng Tần Suất (Jun Da)": "6153.0", "Tần Suất % (Jun Da)": "99.9865201765", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 章", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女章", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "章", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "嫜", "Unihan_Traditional (Chữ Phồn thể)": "嫜", "Pinyin_Xie": "zhāng", "Âm Hán Việt_Xie": "chương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ người, thường dùng trong văn viết cổ hoặc kết hợp thành từ ghép chỉ bố mẹ chồng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('毽', '{"9000": "6154.0", "Chữ Trung Quốc": "毽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 毛 | Số nét | 12 | nét | 毛 | mao | biểu nghĩa | lông vũ, lông | 建 | kiến | biểu âm | 毽 là chữ hình thanh: bộ 毛 (mao, biểu nghĩa: lông vũ) kết hợp với 建 (kiến, biểu âm). Wiktionary ghi: \"feather\" (lông vũ) là thành phần biểu nghĩa. Chữ chỉ quả cầu lông (shuttlecock), trò chơi đá cầu truyền thống Trung Hoa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến (âm kiện/jiàn): 毛(lông) + 建(biểu âm) — quả cầu \"kiện\" được \"kiến\" (dựng đứng) bằng lông gà — trò đá cầu đã có hàng ngàn năm ở cả Trung Hoa lẫn Việt Nam. | Gương Hán-Việt | kiện trong 毽球 (kiện cầu – quả cầu lông), 踢毽 (đá cầu) | Mở khoá kiến thức | Biết 毽 giúp đọc hiểu tài liệu về trò chơi dân gian và văn hóa thể thao truyền thống Trung Hoa.", "Tự nguyên_Xie": "毽 (kiện/jiàn) là chữ hình thanh, gồm 毛 (lông vũ) biểu nghĩa và 建 biểu âm. Chữ chỉ quả cầu lông (毽球/踢毽) — đồ vật làm từ lông gà gắn trên đồng tiền xu, được đá bằng chân. Trò chơi đá cầu (踢毽) là trò chơi dân gian lâu đời ở Trung Hoa và Việt Nam. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "721.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mao (201) Kiến (720)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mao (số 201 - lông) ở bên trái chữ Kiến (số 720 - thiết lập/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Kiến chỉ âm, bộ Mao (lông vũ) chỉ ý. Kiện là quả cầu đá (có gắn mảng lông để đá).", "Nghĩa Tiếng Việt_Xie": "quả cầu", "Hạng Tần Suất (Jun Da)": "6154.0", "Tần Suất % (Jun Da)": "99.986540848", "GavinGrover_Once (Chiết tự trực tiếp)": "毛 + 建", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴毛建", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "建", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "毛", "Unihan_Simplified (Chữ Giản thể)": "毽", "Unihan_Traditional (Chữ Phồn thể)": "毽", "Pinyin_Xie": "jiàn", "Âm Hán Việt_Xie": "kiện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ vật, thường làm tân ngữ cho động từ đá. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('砑', '{"9000": "6155.0", "Chữ Trung Quốc": "砑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 9 | nét | 砑 | nha | tượng hình | đá mài; chưa phân tích được chi tiết từ nguồn Wiktionary | 砑 có bộ 石 (thạch, đá) kết hợp với thành phần biểu âm. Wiktionary chỉ ghi {{Han etym}} không phân tích cấu tạo chi tiết. Chữ chỉ hành động mài, đánh bóng bằng đá; dùng con lăn đá để là phẳng vải lụa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến (âm nha/yà): 石(đá) — dùng đá \"nha\" (nghiến, mài) để đánh bóng vải lụa hoặc bề mặt — kỹ thuật hoàn thiện vải truyền thống. | Gương Hán-Việt | nha trong 砑光 (nha quang – đánh bóng), 砑綾 (nha lăng – vải lụa đánh bóng) | Mở khoá kiến thức | Biết 砑 giúp đọc hiểu tài liệu về kỹ thuật dệt may truyền thống và in ấn cổ đại Trung Hoa.", "Tự nguyên_Xie": "砑 (nha/yà) là chữ hình thanh, bộ 石 (đá) biểu nghĩa, phần còn lại biểu âm. Nghĩa: nghiền, mài, đánh bóng bằng đá; dùng con lăn đá để cán phẳng vải lụa (砑光 — đánh bóng bề mặt). Wiktionary xác nhận nghĩa \"to crush; to grind; to polish\". chưa có nguồn học thuật phân tích chi tiết hơn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đá mài", "Hạng Tần Suất (Jun Da)": "6155.0", "Tần Suất % (Jun Da)": "99.9865615194", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 牙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石牙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "牙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "砑", "Unihan_Traditional (Chữ Phồn thể)": "砑", "Pinyin_Xie": "yà", "Âm Hán Việt_Xie": "nhạ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thể hiện hành động dùng đá lăn hoặc ép cho giấy, vải phẳng bóng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('碶', '{"9000": "6156.0", "Chữ Trung Quốc": "碶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 14 | nét | 石 | thạch | biểu nghĩa | đá | 契 | khế | biểu âm | 碶 là chữ hình thanh: bộ 石 (thạch, biểu nghĩa: đá) kết hợp với thành phần biểu âm. Chữ chỉ cống nước, cửa cống bằng đá (flood-gate, water-gate). Không có dạng chữ cổ. chưa có nguồn học thuật phân tích chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến (âm khế/qì): 石(đá) — cống đá \"khế\" chắn nước, điều tiết thủy lợi ở vùng đồng bằng châu thổ — phổ biến trong địa danh vùng Chiết Giang. | Gương Hán-Việt | khế trong 大碶 (Đại Khế – địa danh vùng Chiết Giang) | Mở khoá kiến thức | Biết 碶 giúp nhận ra địa danh liên quan đến công trình thủy lợi cổ đại ở vùng Chiết Giang, Trung Quốc.", "Tự nguyên_Xie": "碶 (khế/qì) là chữ hình thanh chỉ cống nước, cửa cống điều tiết nước bằng đá. Bộ 石 biểu nghĩa đá; phần còn lại biểu âm qì. Chữ tồn tại trong địa danh như 大碶頭 (Đại Khế Đầu) ở Chiết Giang, Trung Quốc. Không có nguồn Wiktionary phân tích chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: đại khế đầu 大碶頭,大碶头)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 契", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石契", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "契", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "碶", "Unihan_Traditional (Chữ Phồn thể)": "碶", "Pinyin_Xie": "qì", "Âm Hán Việt_Xie": "khế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ công trình thủy lợi, chủ yếu xuất hiện trong các địa danh vùng Chiết Giang. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('剀', '{"9000": "6157.0", "Chữ Trung Quốc": "剀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 刀 | Số nét | 8 | nét | 豈 | khải | biểu âm | 刂 | đao | biểu nghĩa | dao, cắt | 剀 là chữ hình thanh: bộ 刂 (đao, biểu nghĩa: dao, cắt) kết hợp với 豈 (khải, biểu âm). Wiktionary xác nhận cấu tạo: 豈 (biểu âm) + 刀/刂 (dao, biểu nghĩa). Nghĩa gốc: mài sắc dao; sau mở rộng sang nghĩa hợp lý, thích đáng, thấu đáo. Bạch thư, đại triện và tiểu triện còn lưu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến (âm khải/kǎi): 刂(dao) + 豈(biểu âm) — mài dao cho \"khải\" (sắc bén, thấu đáo) — nghĩa mở rộng: lời nói thấu đáo, phân tích hợp lý, không hời hợt. | Gương Hán-Việt | khải trong 剀切 (khải thiết – thích đáng, chính xác), văn bản hành chính cổ | Mở khoá kiến thức | Biết 剀 giúp đọc hiểu văn bản hành chính và học thuật cổ Trung Hoa trong đó 剀切 là lời khen về tính thấu đáo.", "Tự nguyên_Xie": "Bạch thư | Đại triện | Tiểu triện | 剀 (khải/kǎi) là chữ hình thanh, gồm 刂 (dao) biểu nghĩa và 豈 biểu âm. Wiktionary xác nhận cấu tạo qua dạng đầy đủ 剴. Nghĩa gốc: mài sắc; sau mở rộng sang thấu đáo, hợp lý, cẩn thận. Dùng trong từ 剀切 (thích đáng, xác đáng). Bạch thư, đại triện và tiểu triện đều còn lưu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hợp lý, thích đáng, vừa", "Hạng Tần Suất (Jun Da)": "6157.0", "Tần Suất % (Jun Da)": "99.9866028622", "GavinGrover_Once (Chiết tự trực tiếp)": "岂 + 刂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰岂刂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "岂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "刂", "Unihan_Simplified (Chữ Giản thể)": "剀", "Unihan_Traditional (Chữ Phồn thể)": "剴", "Pinyin_Xie": "kǎi", "Âm Hán Việt_Xie": "khải", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ bổ nghĩa cho danh từ hoặc động từ để chỉ sự thấu đáo, thích đáng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('薷', '{"9000": "6158.0", "Chữ Trung Quốc": "薷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 17 | nét | 艹 | tháo | biểu nghĩa | cỏ, thực vật | 需 | nhu | biểu âm | 薷 là chữ hình thanh: bộ 艹 (tháo, biểu nghĩa: cỏ/thực vật) kết hợp với 需 (nhu, biểu âm). Chữ chỉ cây hương nhu (Elsholtzia), một loại cây thuốc thơm. Wiktionary xác nhận cấu tạo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nho\": 艹(cỏ) + 需(nhu, biểu âm) — cây hương nho (香薷) có mùi thơm \"nhu\" mượt, dùng giải nhiệt mùa hè trong y học cổ truyền. | Gương Hán-Việt | nho trong 香薷 (hương nho – cây hương nhu) | Mở khoá kiến thức | Biết 薷 (nho) mở khoá từ 香薷 (hương nhu) — cây thuốc thơm phổ biến trong y học cổ truyền Trung Hoa và Việt Nam.", "Tự nguyên_Xie": "薷 (nho/rú) là chữ hình thanh, gồm 艹 (cỏ/cây) biểu nghĩa và 需 biểu âm. Wiktionary xác nhận: \"Elsholtzia\" — cây hương nhu (香薷), một loại cây thảo mộc có mùi thơm, dùng trong y học cổ truyền và nấu ăn. Dùng phổ biến nhất trong từ 香薷 (hương nhu). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: hương nhu 香薷)", "Hạng Tần Suất (Jun Da)": "6158.0", "Tần Suất % (Jun Da)": "99.9866235336", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 需", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹需", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "需", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "薷", "Unihan_Traditional (Chữ Phồn thể)": "薷", "Pinyin_Xie": "rú", "Âm Hán Việt_Xie": "nhu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, hầu như chỉ dùng trong từ ghép để chỉ tên một loại thảo dược. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('怃', '{"9000": "6159.0", "Chữ Trung Quốc": "怃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 7 | nét | 忄 | tâm | biểu nghĩa | tâm trạng, cảm xúc | 无 | vô | biểu âm | 怃 là chữ hình thanh: bộ 忄 (tâm, biểu nghĩa: tâm trạng) kết hợp với 无 (vô, biểu âm). Dạng giản thể của 憮. Chữ chỉ tâm trạng thất vọng, buồn bã, thẫn thờ. Wiktionary xác nhận dạng đầy đủ là 憮. Tiểu triện còn lưu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến (âm vô/wǔ): 忄(tâm) + 无(vô) — tâm trạng \"vô\" (trống rỗng, mất mát) — cảm giác thất vọng, thẫn thờ như không còn gì nữa. | Gương Hán-Việt | vũ trong 怃然 (vũ nhiên – thẫn thờ, thất vọng) | Mở khoá kiến thức | Biết 怃 giúp đọc hiểu văn thơ cổ điển Trung Hoa mô tả tâm trạng buồn bã, thất vọng, ngơ ngẩn.", "Tự nguyên_Xie": "Tiểu triện | 怃 (vô/wǔ) là dạng giản thể của 憮. Tiểu triện lưu dạng 憮. Wiktionary ghi dạng phồn thể 憮 với nghĩa thẫn thờ, thất vọng. Dùng phổ biến trong từ 憮然/怃然 (ngơ ngẩn, thẫn thờ; thất vọng) và 眉憮 (nét mày buồn). chưa có nguồn học thuật phân tích chi tiết cấu tạo. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thất vọng", "Hạng Tần Suất (Jun Da)": "6159.0", "Tần Suất % (Jun Da)": "99.986644205", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 无", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄无", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "无", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "怃", "Unihan_Traditional (Chữ Phồn thể)": "憮", "Pinyin_Xie": "wǔ", "Âm Hán Việt_Xie": "hủ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này thường làm tính từ biểu thị trạng thái thất vọng hoặc làm động từ chỉ sự vỗ về. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('怿', '{"9000": "6160.0", "Chữ Trung Quốc": "怿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 8 | nét | 忄 | tâm | biểu nghĩa | tâm trạng, cảm xúc | 𠬤 | biểu âm | 怿 là dạng giản thể của 懌. Wiktionary ghi: 怿 là dạng giản thể của 懌 với 睪 rút gọn thành 𠬤. Bộ 忄 (tâm) biểu nghĩa tâm trạng vui vẻ. Tiểu triện còn lưu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến (âm dịch/yì): 忄(tâm) + 𠬤(biểu âm) — tâm trạng \"dịch\" (chuyển hóa, đổi thay) sang trạng thái vui mừng, phấn khởi. | Gương Hán-Việt | dịch trong 怿色 (dịch sắc – sắc mặt vui mừng), văn thơ cổ điển Trung Hoa | Mở khoá kiến thức | Biết 怿 giúp đọc hiểu văn thơ cổ điển Trung Hoa mô tả tâm trạng vui mừng, phấn khởi.", "Tự nguyên_Xie": "Tiểu triện | 怿 (dịch/yì) là dạng giản thể của 懌. Wiktionary xác nhận: 怿 = 懌 giản thể, với 睪 được rút gọn. Nghĩa: vui mừng, hài lòng, thích thú. Tiểu triện của dạng gốc còn lưu. chưa có nguồn học thuật phân tích chi tiết cấu tạo nguyên thủy. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vui lòng", "Hạng Tần Suất (Jun Da)": "6160.0", "Tần Suất % (Jun Da)": "99.9866648764", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "怿", "Unihan_Traditional (Chữ Phồn thể)": "懌", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "dịch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này làm tính từ chỉ tâm trạng vui sướng hoặc làm động từ biểu thị sự vui lòng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('骐', '{"9000": "6161.0", "Chữ Trung Quốc": "骐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 11 | nét | 骐 | kỳ | tượng hình | ngựa ô màu xanh lam đen, ngựa tốt | 骐 có bộ 马 (mã, ngựa) kết hợp với thành phần biểu âm. Dạng giản thể của 騏. Wiktionary ghi dạng phồn thể 騏 chỉ ngựa màu lam đen, ngựa tốt. Bạch thư và đại triện còn lưu dạng 騏.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kỳ\": bộ 马(mã, ngựa) — ngựa \"kỳ\" màu xanh lam đen, ngựa quý báu; 騏驥 (kỳ kị) là từ chỉ nhân tài xuất sắc trong thành ngữ Trung Hoa. | Gương Hán-Việt | kỳ trong 騏驥 (kỳ kị – ngựa quý, ví nhân tài) | Mở khoá kiến thức | Biết 骐 (kỳ) giúp hiểu thành ngữ 騏驥一毛 (kỳ kị nhất mao – ngựa kỳ một sợi lông, tài năng nhỏ trong số lớn) và các hình ảnh ẩn dụ về nhân tài.", "Tự nguyên_Xie": "Bạch thư | Đại triện | 骐 (kỳ/qí) là dạng giản thể của 騏. Wiktionary xác nhận: 騏 là ngựa màu lam đen (dark-blue piebald horse) và ngựa tốt, ngựa xuất sắc. Xuất hiện trong Mặc Tử và Trang Tử: 騏驥一日而馳千里 (ngựa kỳ kị một ngày chạy nghìn dặm). Bạch thư và đại triện của 騏 còn lưu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngựa ô", "Hạng Tần Suất (Jun Da)": "6161.0", "Tần Suất % (Jun Da)": "99.9866855478", "GavinGrover_Once (Chiết tự trực tiếp)": "马 + 其", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰马其", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "其", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "马", "Unihan_Simplified (Chữ Giản thể)": "骐", "Unihan_Traditional (Chữ Phồn thể)": "騏", "Pinyin_Xie": "qí", "Âm Hán Việt_Xie": "kì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài ngựa tốt, thường dùng trong văn học cổ hoặc tên riêng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('腧', '{"9000": "6162.0", "Chữ Trung Quốc": "腧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 13 | nét | 月 | nguyệt | biểu nghĩa | bộ nhục (thịt, cơ thể) | 俞 | du | biểu âm | 腧 là chữ hình thanh: bộ 月/肉 (nhục, biểu nghĩa: thân thể, cơ thể) kết hợp với 俞 (du, biểu âm). Chữ chỉ huyệt vị trong châm cứu, điểm đặc biệt trên cơ thể để châm kim. Wiktionary xác nhận nghĩa \"acupoint\".", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến (âm du/shù): 月(thân thể) + 俞(biểu âm) — huyệt \"du\" trên cơ thể, nơi châm kim trong châm cứu để điều tiết khí huyết theo y học cổ truyền. | Gương Hán-Việt | du trong 腧穴 (du huyệt – huyệt vị châm cứu) | Mở khoá kiến thức | Biết 腧 giúp đọc hiểu tài liệu y học cổ truyền Trung Hoa về châm cứu và huyệt vị cơ thể.", "Tự nguyên_Xie": "腧 (du/shù) là chữ hình thanh, gồm 月/肉 (thân thể) biểu nghĩa và 俞 biểu âm. Wiktionary ghi: \"acupoint\" — huyệt vị trong châm cứu. Dùng trong từ 腧穴 (du huyệt). Hai âm đọc: shù (chính) và yú (biến thể). chưa có nguồn học thuật phân tích chi tiết cấu tạo. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "huyệt; đường huyệt; Ghi chú: ''''俞''''另见yú", "Hạng Tần Suất (Jun Da)": "6162.0", "Tần Suất % (Jun Da)": "99.9867062192", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 俞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月俞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "俞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "腧", "Unihan_Traditional (Chữ Phồn thể)": "腧", "Pinyin_Xie": "shù", "Âm Hán Việt_Xie": "thú", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các vị trí huyệt vị trên cơ thể trong y học cổ truyền. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('霈', '{"9000": "6163.0", "Chữ Trung Quốc": "霈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 雨 | Số nét | 15 | nét | 雨 | vũ | biểu nghĩa | mưa | 沛 | phái | biểu âm | 霈 là chữ hình thanh: bộ 雨 (vũ, biểu nghĩa: mưa) kết hợp với thành phần biểu âm pèi. Chữ chỉ mưa to, mưa rào; theo nghĩa bóng chỉ ân huệ của vua ban xuống. Wiktionary xác nhận các nghĩa này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"pháy\": 雨(mưa) + thành phần biểu âm — cơn mưa \"pháy\" (rào lớn), như ân huệ từ trời cao đổ xuống — hình ảnh mưa ân trạch trong văn học cung đình cổ. | Gương Hán-Việt | pháy trong 霶霈 (phanh pháy – mưa rào to), 甘霈 (cam pháy – mưa đúng lúc như ân huệ) | Mở khoá kiến thức | Biết 霈 giúp đọc hiểu thơ văn cung đình và văn học cổ điển Trung Hoa về mưa ân huệ của vua ban.", "Tự nguyên_Xie": "霈 (pháy/pèi) là chữ hình thanh, gồm 雨 (mưa) biểu nghĩa và thành phần biểu âm pèi. Wiktionary ghi: (1) mưa to, mưa đúng lúc; (2) mưa hoặc tuyết to, dữ dội; (3) (nghĩa bóng) ân huệ của hoàng đế ban xuống. Cũng có nghĩa: tự mãn, kiêu ngạo (chưa xác minh). Dùng trong từ 霶霈 (mưa rào lớn). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mưa rào; ân trạch", "Hạng Tần Suất (Jun Da)": "6163.0", "Tần Suất % (Jun Da)": "99.9867268906", "GavinGrover_Once (Chiết tự trực tiếp)": "雨 + 沛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱雨沛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "沛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "雨", "Unihan_Simplified (Chữ Giản thể)": "霈", "Unihan_Traditional (Chữ Phồn thể)": "霈", "Pinyin_Xie": "pèi", "Âm Hán Việt_Xie": "bái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ trận mưa lớn hoặc làm tính từ miêu tả dáng vẻ mưa rơi tầm tã. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蝻', '{"9000": "6164.0", "Chữ Trung Quốc": "蝻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 15 | nét | 虫 | trùng | biểu nghĩa | côn trùng | 南 | nam | biểu âm | 蝻 là chữ hình thanh: bộ 虫 (trùng, biểu nghĩa: côn trùng) kết hợp với 南 (nam, biểu âm). Chữ chỉ châu chấu non, ấu trùng châu chấu (immature locusts). Không có dạng chữ cổ. chưa có nguồn học thuật phân tích chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến (âm nam/nǎn): 虫(trùng) + 南(nam) — châu chấu non \"nam\" chưa mọc cánh, thành đàn cắn phá mùa màng — nỗi kinh hoàng của nông dân xưa. | Gương Hán-Việt | nam trong 蝗蝻 (hoàng nam – châu chấu trưởng thành và ấu trùng) | Mở khoá kiến thức | Biết 蝻 giúp đọc hiểu tài liệu nông nghiệp và lịch sử Trung Hoa về nạn châu chấu phá hoại mùa màng.", "Tự nguyên_Xie": "蝻 (nam/nǎn) là chữ hình thanh, gồm 虫 (côn trùng) biểu nghĩa và 南 biểu âm. Chữ chỉ châu chấu non — ấu trùng châu chấu chưa mọc cánh, giai đoạn trước khi trở thành châu chấu trưởng thành. Tên khoa học liên quan: Locusta migratoria (ấu trùng). Không có nguồn Wiktionary phân tích chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con châu chấu non", "Hạng Tần Suất (Jun Da)": "6164.0", "Tần Suất % (Jun Da)": "99.986747562", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 南", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫南", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "南", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蝻", "Unihan_Traditional (Chữ Phồn thể)": "蝻", "Pinyin_Xie": "nǎn", "Âm Hán Việt_Xie": "nam", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, thường dùng trong văn viết hoặc kết hợp thành từ ghép chỉ côn trùng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('墼', '{"9000": "6165.0", "Chữ Trung Quốc": "墼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 16 | nét | 墼 | kích | tượng hình | gạch mộc chưa nung | 墼 là chữ độc lập, không phân tách được thành phần rõ ràng trong CHISE; chưa có nguồn gốc cấu tạo học thuật xác nhận. Bộ thủ 土 (thổ) gợi vật liệu đất.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kích\": khối đất (土) nén chặt thành viên gạch mộc—kích thước vuông vức. | Gương Hán-Việt | kích trong \"thổ kích\" (gạch đất) | Mở khoá kiến thức | Biết 墼 mở khoá: 土墼 (gạch đất), 炭墼 (than bánh).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 墼 nghĩa là gạch mộc (mud brick, adobe)—loại gạch làm từ đất sét chưa qua nung. Cấu trúc chữ không được phân tích rõ ràng. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gạch mộc", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "𣪠 + 土", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱𣪠土", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𣪠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "墼", "Unihan_Traditional (Chữ Phồn thể)": "墼", "Pinyin_Xie": "jī", "Âm Hán Việt_Xie": "kích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loại gạch đất sét chưa nung, thường dùng trong xây dựng cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('坩', '{"9000": "6166.0", "Chữ Trung Quốc": "坩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 8 | nét | 土 | thổ | biểu nghĩa | đất | 甘 | cam | biểu âm | 坩 = 土 (Thổ, biểu nghĩa: đất) + 甘 (Cam, biểu âm); chữ hình thanh. Phần 土 gợi vật liệu đất nung; 甘 cho âm gān.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cam\": đất (土) nặn thành lọ ngọt ngào (甘)—chiếc bình đất nung xinh xắn. | Gương Hán-Việt | cam trong \"cam lộ\" (ngọt ngào) — mượn âm cho lọ đất | Mở khoá kiến thức | Biết 坩 mở khoá: 坩堝 (nồi/chén nung, crucible trong thí nghiệm).", "Tự nguyên_Xie": "Theo Wiktionary, 坩 là chữ hình thanh: 土 (thổ, biểu nghĩa: đất) kết hợp với 甘 (cam, biểu âm). Chữ chỉ đồ vật làm bằng đất—nồi, lọ, chum đất nung; dùng phổ biến nhất trong 坩堝 (nồi đất nung dùng trong luyện kim). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đồ bằng đất (như nồi, chum, lọ,...)", "Hạng Tần Suất (Jun Da)": "6166.0", "Tần Suất % (Jun Da)": "99.9868292141", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 甘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土甘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "坩", "Unihan_Traditional (Chữ Phồn thể)": "坩", "Pinyin_Xie": "gān", "Âm Hán Việt_Xie": "kham", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, thường xuất hiện trong các từ ghép chỉ dụng cụ thí nghiệm hoặc đồ đất nung. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('甏', '{"9000": "6167.0", "Chữ Trung Quốc": "甏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 瓦 | Số nét | 16 | nét | 彭 | bành | biểu âm | 瓦 | ngoã | biểu nghĩa | đồ gốm nung | 甏 = 彭 (Bành, biểu âm) + 瓦 (Ngoã, biểu nghĩa: đồ gốm nung); chữ hình thanh. Phần 瓦 gợi vật liệu gốm; 彭 cho âm bèng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bành\": chiếc vò gốm (瓦) phình to (彭) như cái bụng—đựng rượu làng quê. | Gương Hán-Việt | bành trong \"bành trướng\" (phình ra, lớn ra) | Mở khoá kiến thức | Biết 甏 mở khoá từ phương ngữ chỉ đồ đựng gốm: 酱甏 (vò tương).", "Tự nguyên_Xie": "Theo Wiktionary, 甏 là chữ hình thanh: 彭 (bành, biểu âm) kết hợp với 瓦 (ngoã, biểu nghĩa: đồ gốm nung). Chữ chỉ loại vò, bình gốm lớn dùng đựng rượu, tương, mắm trong phương ngữ Trung Quốc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái vò lớn", "Hạng Tần Suất (Jun Da)": "6167.0", "Tần Suất % (Jun Da)": "99.9868493687", "GavinGrover_Once (Chiết tự trực tiếp)": "彭 + 瓦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱彭瓦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "彭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "瓦", "Unihan_Simplified (Chữ Giản thể)": "甏", "Unihan_Traditional (Chữ Phồn thể)": "甏", "Pinyin_Xie": "bèng", "Âm Hán Việt_Xie": "bạng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loại bình chứa bằng đất nung có miệng nhỏ bụng to. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鹇', '{"9000": "6168.0", "Chữ Trung Quốc": "鹇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 12 | nét | 鹇 | nhàn | tượng hình | chim trĩ bạc, Lophura nycthemera | 鹇 là chữ chỉ tên loài chim; không có phân tích cấu tạo học thuật trong nguồn anchor. Bộ thủ 鳥 (điểu) gợi đây là tên chim.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhàn\": con chim lông trắng bạc (鳥) ung dung nhàn hạ—gà lôi bạc thảnh thơi trong rừng. | Gương Hán-Việt | nhàn trong \"nhàn hạ\" (thư thái)—hình ảnh chim lôi thư nhàn | Mở khoá kiến thức | Biết 鹇 mở khoá: 白鹇 (bạch nhàn—gà lôi bạc, loài chim quý).", "Tự nguyên_Xie": "Chữ 鹇 chỉ con gà lôi bạc (silver pheasant). Không có phân tích glyph origin từ Wiktionary. chưa có nguồn học thuật về cấu tạo chữ này. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con gà lôi", "Hạng Tần Suất (Jun Da)": "6168.0", "Tần Suất % (Jun Da)": "99.9868695233", "GavinGrover_Once (Chiết tự trực tiếp)": "闲 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴闲鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "闲", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鹇", "Unihan_Traditional (Chữ Phồn thể)": "鷳", "Pinyin_Xie": "xián", "Âm Hán Việt_Xie": "nhàn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài chim thuộc họ trĩ, thường dùng trong tên riêng loài vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鹣', '{"9000": "6169.0", "Chữ Trung Quốc": "鹣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 15 | nét | 鹣 | kiêm | tượng hình | chim thần thoại một mắt một cánh | 鹣 là tên chim trong thần thoại Trung Quốc; không có phân tích cấu tạo rõ ràng trong anchor. Bộ 鳥 (điểu) xác nhận đây là tên chim.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiêm\": chim (鳥) chỉ có một cánh — kiêm (cùng nhau) mới bay được, ví tình yêu đôi lứa. | Gương Hán-Việt | kiêm trong \"kiêm ái\" (yêu tất cả), \"kiêm nhiệm\" | Mở khoá kiến thức | Biết 鹣 mở khoá: 鶼鰈情深 (tình nghĩa vợ chồng sâu đậm như chim 鶼 và cá 鰈).", "Tự nguyên_Xie": "Theo Wiktionary, 鹣 (truyền thống: 鶼) chỉ con chim thần thoại chỉ có một mắt và một cánh — hai con phải sánh đôi mới bay được. Dùng trong thành ngữ 鶼鰈情深 để chỉ tình nghĩa vợ chồng sâu đậm. chưa có phân tích glyph origin học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: kiêm kiêm 鶼鶼,鹣鹣)", "Hạng Tần Suất (Jun Da)": "6169.0", "Tần Suất % (Jun Da)": "99.9868896779", "GavinGrover_Once (Chiết tự trực tiếp)": "兼 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰兼鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鹣", "Unihan_Traditional (Chữ Phồn thể)": "鶼", "Pinyin_Xie": "jiān", "Âm Hán Việt_Xie": "kiêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, thường dùng trong văn học cổ để ví von tình nghĩa vợ chồng gắn bó. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('舴', '{"9000": "6170.0", "Chữ Trung Quốc": "舴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 舟 | Số nét | 11 | nét | 舴 | trách | tượng hình | thuyền nhỏ | 舴 chỉ dùng trong từ ghép 舴艋 (thuyền nhỏ); không có phân tích cấu tạo trong anchor. Bộ 舟 (chu) xác nhận liên quan đến thuyền bè.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trách\": chiếc thuyền (舟) nhỏ bé — trách (trơn nhỏ) lướt sóng. | Gương Hán-Việt | trách trong \"trách nhiệm\" — mượn âm, không liên nghĩa | Mở khoá kiến thức | Biết 舴 mở khoá: 舴艋 (thuyền nhỏ trong thơ cổ điển).", "Tự nguyên_Xie": "Theo Wiktionary, 舴 chỉ xuất hiện trong từ 舴艋 nghĩa là thuyền nhỏ. Không có phân tích glyph origin. chưa có nguồn học thuật về cấu tạo chữ này. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: trách mãnh 舴艋)", "Hạng Tần Suất (Jun Da)": "6170.0", "Tần Suất % (Jun Da)": "99.9869098325", "GavinGrover_Once (Chiết tự trực tiếp)": "舟 + 乍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舟乍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舟", "Unihan_Simplified (Chữ Giản thể)": "舴", "Unihan_Traditional (Chữ Phồn thể)": "舴", "Pinyin_Xie": "zé", "Âm Hán Việt_Xie": "trách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, hầu như chỉ dùng trong từ ghép để chỉ loại thuyền nhỏ đi sông. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲭', '{"9000": "6171.0", "Chữ Trung Quốc": "鲭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 16 | nét | 鲭 | thanh | tượng hình | cá thu, cá nấu lẫn thịt | 鲭 (truyền thống: 鯖) là tên loài cá; không có phân tích cấu tạo chi tiết trong anchor ngoài bộ 魚 (ngư). Bộ 魚 xác nhận đây là tên cá.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thanh\": cá (魚) màu xanh (青) lóng lánh — cá thu xanh bóng ngoài biển. | Gương Hán-Việt | thanh trong \"thanh lịch\", \"xanh\" — cá mang màu xanh biển | Mở khoá kiến thức | Biết 鲭 mở khoá từ vựng hải sản: 鲭鱼 (cá thu), 鲭罐头 (cá thu đóng hộp).", "Tự nguyên_Xie": "Theo Wiktionary, 鯖 là tên cá thu (mackerel). Wiktionary chỉ ghi {{Han etym}} không có phân tích cụ thể. chưa có nguồn học thuật về glyph origin. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá nấu lẫn với thịt; cá đối", "Hạng Tần Suất (Jun Da)": "6171.0", "Tần Suất % (Jun Da)": "99.9869299872", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 青", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼青", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "青", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲭", "Unihan_Traditional (Chữ Phồn thể)": "鯖", "Pinyin_Xie": "qīng", "Âm Hán Việt_Xie": "chinh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loài cá thuộc họ cá thu hoặc món ăn chế biến từ cá. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('傺', '{"9000": "6172.0", "Chữ Trung Quốc": "傺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 13 | nét | 傺 | sái | tượng hình | cản trở, dừng lại | 傺 là chữ độc lập; không có phân tích cấu tạo trong anchor. Bộ 人/亻 (nhân) gợi liên quan đến hành vi của người.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sái\": người (亻) bị chặn đứng lại — sái bước, không tiến được. | Gương Hán-Việt | sái trong \"sái quấy\" (sai trái) | Mở khoá kiến thức | Biết 傺 mở khoá: 侘傺 (thất ý, lạc lõng — từ cổ trong thơ Sở Từ).", "Tự nguyên_Xie": "Theo Wiktionary, 傺 có nghĩa: ở lại, dừng lại; cản trở; giữ lại. Xuất hiện trong 侘傺 (thất ý, buồn bã). Không có phân tích glyph origin. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cản trở, ngăn cản", "Hạng Tần Suất (Jun Da)": "6172.0", "Tần Suất % (Jun Da)": "99.9869501418", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 祭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻祭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "祭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "傺", "Unihan_Traditional (Chữ Phồn thể)": "傺", "Pinyin_Xie": "chì", "Âm Hán Việt_Xie": "sế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ biểu thị sự ngưng trệ, không đạt được ý nguyện trong văn ngôn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('枘', '{"9000": "6173.0", "Chữ Trung Quốc": "枘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 8 | nét | 枘 | nhuế | tượng hình | chuôi, cán dụng cụ; mộng tenon | 枘 là chữ độc lập; không có phân tích cấu tạo trong anchor. Bộ 木 (mộc) xác nhận liên quan đến đồ gỗ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhuế\": thanh gỗ (木) nhọn nhỉnh — phần mộng tenon tra vào lỗ mộng. | Gương Hán-Việt | nhuế trong nghĩa \"nhọn, nhuệ\" | Mở khoá kiến thức | Biết 枘 mở khoá: 枘鑿 (mộng và lỗ mộng — ví hai thứ không khớp nhau).", "Tự nguyên_Xie": "Theo Wiktionary, 枘 chỉ chuôi, cán dụng cụ; đặc biệt là phần mộng (tenon) trong nghề mộc. Dùng trong thành ngữ 枘鑿不入 (mộng không vừa lỗ — ví sự không tương thích). Không có glyph origin. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khớp mộng, vào mộng (nghề mộc)", "Hạng Tần Suất (Jun Da)": "6173.0", "Tần Suất % (Jun Da)": "99.9869702964", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 内", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木内", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "内", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "枘", "Unihan_Traditional (Chữ Phồn thể)": "枘", "Pinyin_Xie": "ruì", "Âm Hán Việt_Xie": "nhuế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ phần đầu gỗ nhô ra để lắp vào lỗ mộng trong nghề mộc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('秕', '{"9000": "6174.0", "Chữ Trung Quốc": "秕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 9 | nét | 禾 | hòa | biểu nghĩa | lúa | 比 | tỷ | biểu âm | 秕 = 禾 (Hòa, biểu nghĩa: lúa) + 比 (Tỷ, biểu âm); chữ hình thanh. Phần 禾 gợi hạt lúa; 比 cho âm bǐ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bỉ\": lúa (禾) so sánh (比) thì thấy lép — hạt lép không bằng hạt chắc. | Gương Hán-Việt | bỉ trong \"bỉ ổi\" (xấu xa), \"khinh bỉ\" | Mở khoá kiến thức | Biết 秕 mở khoá: 秕糠 (trấu lép — ví điều vô dụng), 糠秕 (kẻ tầm thường).", "Tự nguyên_Xie": "Theo Wiktionary, 秕 là chữ hình thanh: 禾 (hòa, biểu nghĩa: lúa) kết hợp với 比 (tỷ, biểu âm). Chữ chỉ hạt lúa lép, hạt không có nhân đầy — trấu vỏ không có gạo bên trong. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hạt lúa lép; làm nhơ bẩn", "Hạng Tần Suất (Jun Da)": "6174.0", "Tần Suất % (Jun Da)": "99.986990451", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 比", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾比", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "比", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "秕", "Unihan_Traditional (Chữ Phồn thể)": "秕", "Pinyin_Xie": "bǐ", "Âm Hán Việt_Xie": "bỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ hạt lép hoặc làm tính từ trong từ ghép chỉ sự tồi tệ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('糨', '{"9000": "6175.0", "Chữ Trung Quốc": "糨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 18 | nét | 米 | mễ | biểu nghĩa | gạo | 強 | cường | biểu âm | 糨 = 米 (Mễ, biểu nghĩa: gạo) + 強 (Cường, biểu âm); chữ hình thanh. Phần 米 gợi chất bột gạo; 強 cho âm jiàng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cường\": gạo (米) nấu đặc cứng (強) — hồ tinh bột sệt như keo dán. | Gương Hán-Việt | cường trong \"cường tráng\" (mạnh mẽ) — hồ cứng chắc | Mở khoá kiến thức | Biết 糨 mở khoá: 糨糊 (hồ dán, paste), 糨水 (nước hồ tinh bột).", "Tự nguyên_Xie": "Theo Wiktionary, 糨 là chữ hình thanh: 米 (mễ, biểu nghĩa: gạo) kết hợp với 強 (cường, biểu âm). Chữ chỉ hồ tinh bột đặc quánh—dùng để hồ vải, dán giấy; đồng nghĩa 漿 trong một số ngữ cảnh. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đặc quánh", "Hạng Tần Suất (Jun Da)": "6175.0", "Tần Suất % (Jun Da)": "99.9870106056", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 强", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米强", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "强", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "糨", "Unihan_Traditional (Chữ Phồn thể)": "糨", "Pinyin_Xie": "jiàng", "Âm Hán Việt_Xie": "cưỡng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm danh từ chỉ hồ tinh bột hoặc tính từ miêu tả trạng thái đặc quánh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('忉', '{"9000": "6176.0", "Chữ Trung Quốc": "忉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 5 | nét | 忄 | biểu nghĩa | trái tim, cảm xúc | 刀 | đao | biểu âm | 忉 = 忄(biểu nghĩa: tâm, tim) + 刀 (Đao, biểu âm); chữ hình thanh. Phần 忄 gợi cảm xúc nội tâm; 刀 cho âm dāo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đau\": lòng (忄) bị dao (刀) cứa — đau đáu không yên. | Gương Hán-Việt | đau trong \"đau đớn\", \"đau khổ\" | Mở khoá kiến thức | Biết 忉 mở khoá: 忉忉 (lo lắng, đau đáu — từ cổ trong thơ).", "Tự nguyên_Xie": "Theo Wiktionary, 忉 là chữ hình thanh: 忄(tâm, biểu nghĩa: tim/cảm xúc) kết hợp với 刀 (đao, biểu âm). Chữ chỉ trạng thái đau đáu, lo lắng, bận tâm — như lưỡi dao cắt vào lòng. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đau đáu", "Hạng Tần Suất (Jun Da)": "6176.0", "Tần Suất % (Jun Da)": "99.9870307603", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 刀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄刀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "刀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "忉", "Unihan_Traditional (Chữ Phồn thể)": "忉", "Pinyin_Xie": "dāo", "Âm Hán Việt_Xie": "đao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ trong từ láy để biểu thị tâm trạng lo lắng, buồn phiền. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('磲', '{"9000": "6177.0", "Chữ Trung Quốc": "磲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 16 | nét | 磲 | cừ | tượng hình | trai khổng lồ Tridacna | 磲 chỉ dùng trong từ ghép 硨磲 (trai khổng lồ, một trong bảy báu vật Phật giáo); không có phân tích cấu tạo trong anchor. Bộ 石 (thạch) gợi chất liệu cứng như đá.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cừ\": đá (石) quý trắng tinh — vỏ trai 硨磲 sáng như ngọc. | Gương Hán-Việt | cừ trong \"xa cừ\" (vỏ trai ngọc quý) | Mở khoá kiến thức | Biết 磲 mở khoá: 硨磲 (trai khổng lồ, vật liệu đồ trang sức quý).", "Tự nguyên_Xie": "Theo Wiktionary, 磲 chỉ xuất hiện trong 硨磲 — tên của con trai khổng lồ Tridacna gigas, một trong thất bảo Phật giáo. Không có glyph origin chi tiết. chưa có nguồn học thuật về cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: xa cừ 硨磲)", "Hạng Tần Suất (Jun Da)": "6177.0", "Tần Suất % (Jun Da)": "99.9870509149", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 渠", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石渠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "渠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "磲", "Unihan_Traditional (Chữ Phồn thể)": "磲", "Pinyin_Xie": "qú", "Âm Hán Việt_Xie": "cừ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ trong từ ghép để chỉ loài sò tai tượng hoặc ngọc xà cừ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('侑', '{"9000": "6178.0", "Chữ Trung Quốc": "侑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 8 | nét | 侑 | hựu | tượng hình | mời ăn thêm, hỗ trợ | 侑 là chữ độc lập; không có phân tích cấu tạo chi tiết trong anchor. Bộ 亻(nhân) gợi hành động của người — mời mọc, giúp đỡ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hựu\": người (亻) mời thêm bát cơm — hựu thêm, thêm nữa đi. | Gương Hán-Việt | hựu trong \"hựu\" (lại, nữa) — mời thêm | Mở khoá kiến thức | Biết 侑 mở khoá: 侑食 (đệm nhạc khi ăn), 侑觴 (mời uống rượu).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 侑 có nghĩa: mời (ai đó) ăn hoặc uống thêm; giúp đỡ; đáp lại ân nghĩa. Không có phân tích glyph origin. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mời ăn thêm", "Hạng Tần Suất (Jun Da)": "6178.0", "Tần Suất % (Jun Da)": "99.9871310166", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 有", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻有", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "有", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "侑", "Unihan_Traditional (Chữ Phồn thể)": "侑", "Pinyin_Xie": "yòu", "Âm Hán Việt_Xie": "hựu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong văn cổ chỉ việc mời khách ăn uống hoặc dùng âm nhạc để trợ hứng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('萁', '{"9000": "6179.0", "Chữ Trung Quốc": "萁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 萁 | kỳ | tượng hình | thân cây đậu | 萁 là chữ độc lập; không có phân tích cấu tạo chi tiết trong anchor. Bộ 艸/艹 (thảo) xác nhận liên quan đến cây cỏ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kỳ\": cọng cây (艹) kỳ lạ — cọng đậu cháy để nấu hạt đậu, anh em hại nhau. | Gương Hán-Việt | kỳ trong \"kỳ lạ\", \"kỳ diệu\" | Mở khoá kiến thức | Biết 萁 mở khoá: 煮豆燃萁 (thành ngữ: anh em hại nhau), 豆萁 (cọng cây đậu).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 萁 chỉ thân/cọng cây đậu — phần thân khô dùng làm củi. Nổi tiếng qua bài thơ của Tào Thực: 煮豆燃萁 (nấu đậu đốt cọng đậu — ví anh em hại nhau). Không có glyph origin. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thân cây đậu", "Hạng Tần Suất (Jun Da)": "6179.0", "Tần Suất % (Jun Da)": "99.9871506544", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 其", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹其", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "其", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "萁", "Unihan_Traditional (Chữ Phồn thể)": "萁", "Pinyin_Xie": "qí", "Âm Hán Việt_Xie": "ki", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ thân cây đậu sau khi đã thu hoạch hạt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('葳', '{"9000": "6180.0", "Chữ Trung Quốc": "葳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 葳 | uy | tượng hình | sum suê, um tùm, rậm rạp | 葳 là chữ độc lập; không có phân tích cấu tạo chi tiết trong anchor. Bộ 艹 (thảo) xác nhận liên quan đến cây cỏ sum suê.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uy\": cây cỏ (艹) uy nghi sum suê — rừng cây rậm rạp đầy uy lực. | Gương Hán-Việt | uy trong \"uy nghi\" (oai vệ), \"uy quyền\" | Mở khoá kiến thức | Biết 葳 mở khoá: 葳蕤 (sum suê, rậm rạp — từ văn học cổ), 紫葳 (cây điên điển đỏ).", "Tự nguyên_Xie": "Theo Wiktionary, 葳 chỉ dùng trong từ 葳蕤 (uy nhuế) — tả cây cỏ xanh tốt sum suê, cành lá rủ xuống. Không có glyph origin. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sum suê, um tùm", "Hạng Tần Suất (Jun Da)": "6180.0", "Tần Suất % (Jun Da)": "99.9871702922", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 威", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹威", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "威", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "葳", "Unihan_Traditional (Chữ Phồn thể)": "葳", "Pinyin_Xie": "wēi", "Âm Hán Việt_Xie": "uy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ trong từ láy để tả cây cối phát triển xanh tốt. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('呙', '{"9000": "6181.0", "Chữ Trung Quốc": "呙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 7 | nét | 呙 | oa | tượng hình | miệng; tiếng kêu | 呙 là chữ giản thể mới; không có phân tích cấu tạo học thuật. Bộ 口 (khẩu) xác nhận liên quan đến miệng, tiếng nói.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"oa\": miệng (口) mở to — tiếng kêu oa oa. | Gương Hán-Việt | oa trong \"oa oa\" (tiếng trẻ con khóc) | Mở khoá kiến thức | Biết 呙 mở khoá: 呙国 (nước Oa — địa danh cổ), dùng làm họ 呙.", "Tự nguyên_Xie": "Theo anchor, 呙 là chữ Hán giản thể (Simplified Chinese), không có glyph origin truyền thống. Bộ 口 (khẩu) gợi nghĩa miệng/tiếng. chưa có nguồn học thuật về cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "họ Oa; oà; như \"khóc oà\" (vhn) oa; như \"khóc oa oa\" (btcn) ùa; như \"ùa vào\" (btcn) ua; như \"lá ngả màu ua úa\" (gdhn) uả; như \"ủa trời tối (tiếng ỡ ngỡ)\" (gdhn)", "Hạng Tần Suất (Jun Da)": "6181.0", "Tần Suất % (Jun Da)": "99.9871899301", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 内", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱口内", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "内", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "呙", "Unihan_Traditional (Chữ Phồn thể)": "咼", "Pinyin_Xie": "guō", "Âm Hán Việt_Xie": "oa, qua, quai, oai", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ chỉ trạng thái méo lệch hoặc làm họ người. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鹋', '{"9000": "6182.0", "Chữ Trung Quốc": "鹋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 13 | nét | 鹋 | miêu | tượng hình | chim đà điểu Úc (emu) | 鹋 là tên loài chim; không có phân tích cấu tạo trong anchor. Bộ 鳥 (điểu) xác nhận tên chim. Chỉ dùng trong 鸸鹋 (đà điểu Úc).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"miêu\": chim (鳥) trông như mèo (描) nhìn xa — con emu lông xù nhìn từ xa như mèo khổng lồ. | Gương Hán-Việt | miêu trong \"miêu tả\" (mô tả), \"miêu\" (mèo) | Mở khoá kiến thức | Biết 鹋 mở khoá: 鸸鹋 (con emu — đà điểu Úc không biết bay).", "Tự nguyên_Xie": "Chữ 鹋 không có glyph origin trong Wiktionary. Là thành phần trong 鸸鹋 — tên chữ Hán của con emu (đà điểu Úc). chưa có nguồn học thuật về cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: nhi miêu 鴯鶓,鸸鹋)", "Hạng Tần Suất (Jun Da)": "6182.0", "Tần Suất % (Jun Da)": "99.9872095679", "GavinGrover_Once (Chiết tự trực tiếp)": "苗 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰苗鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "苗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鹋", "Unihan_Traditional (Chữ Phồn thể)": "鶓", "Pinyin_Xie": "miáo", "Âm Hán Việt_Xie": "miêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp thành từ ghép để chỉ loài đà điểu Emu của nước Úc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('貘', '{"9000": "6183.0", "Chữ Trung Quốc": "貘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 豸 | Số nét | 17 | nét | 豸 | trại | biểu nghĩa | thú dữ | 莫 | mạc | biểu âm | 貘 = 豸 (Trại, biểu nghĩa: thú dữ) + 莫 (Mạc, biểu âm); chữ hình thanh. Phần 豸 gợi đây là loài thú; 莫 cho âm mò.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mạc\": thú (豸) mờ ảo (莫) không ai biết — con mô huyền bí ăn cả sắt thép. | Gương Hán-Việt | mạc trong \"mạc mạc\" (mờ mịt), \"sa mạc\" | Mở khoá kiến thức | Biết 貘 mở khoá: 貘皮 (da thú mô), 夢貘 (mô ăn ác mộng — trong văn hóa Nhật Bản).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Theo Wiktionary, 貘 là chữ hình thanh: 豸 (trại, biểu nghĩa: thú dữ không chân sau) kết hợp với 莫 (mạc, biểu âm). Chữ chỉ con mô — sinh vật trong truyền ngụ ngôn Trung Quốc ăn sắt đồng, hoặc con tapir trong thực tế. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con mô (trong truyện ngụ ngôn Trung Quốc, hơi giống gấu, ăn đồng và sắt)", "Hạng Tần Suất (Jun Da)": "6183.0", "Tần Suất % (Jun Da)": "99.9872292058", "GavinGrover_Once (Chiết tự trực tiếp)": "豸 + 莫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰豸莫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "莫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "豸", "Unihan_Simplified (Chữ Giản thể)": "貘", "Unihan_Traditional (Chữ Phồn thể)": "貘", "Pinyin_Xie": "mò", "Âm Hán Việt_Xie": "mạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài động vật huyền thoại hoặc con heo vòi trong thực tế. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('葶', '{"9000": "6184.0", "Chữ Trung Quốc": "葶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 葶 | đình | tượng hình | cây đình lịch (Draba) | 葶 là chữ độc lập; không có phân tích cấu tạo trong anchor. Bộ 艹 (thảo) xác nhận tên cây cỏ; chỉ dùng trong 葶藶.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đình\": cây (艹) đứng thẳng như cái đình — cây đình lịch mọc thẳng đứng. | Gương Hán-Việt | đình trong \"đình chỉ\" (dừng lại), \"đình đài\" | Mở khoá kiến thức | Biết 葶 mở khoá: 葶藶 (đình lịch — cây dược liệu trong Đông y).", "Tự nguyên_Xie": "Theo Wiktionary, 葶 chỉ dùng trong 葶藶 (đình lịch) — tên một loại cây dược liệu (Draba nemorosa). Không có glyph origin. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: đình lịch 葶藶,葶苈)", "Hạng Tần Suất (Jun Da)": "6184.0", "Tần Suất % (Jun Da)": "99.9872488436", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 亭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹亭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "葶", "Unihan_Traditional (Chữ Phồn thể)": "葶", "Pinyin_Xie": "tíng", "Âm Hán Việt_Xie": "đình", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu làm danh từ khi kết hợp thành từ ghép chỉ tên cây thuốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('枨', '{"9000": "6185.0", "Chữ Trung Quốc": "枨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 8 | nét | 枨 | trành | tượng hình | bậc cửa, thanh chắn cửa | 枨 là chữ độc lập (dị thể của 棖); không có phân tích cấu tạo chi tiết trong anchor. Bộ 木 (mộc) xác nhận vật liệu gỗ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trành\": thanh gỗ (木) chắn ngang — cái trành cửa giữ không cho cửa mở quá. | Gương Hán-Việt | trành trong \"trành cửa\" (thanh chặn cửa) | Mở khoá kiến thức | Biết 枨 mở khoá ngữ vựng nghề mộc: 门枨 (thanh chắn cửa), 枨橘 (cam quýt — dị nghĩa cổ).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary (usedForm: 棖), 枨 nghĩa là bậc cửa, thanh chắn cửa (doorstop, doorjamb); cũng có nghĩa dùng vật gì đó chống đỡ. Không có phân tích glyph origin. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái bậc cửa", "Hạng Tần Suất (Jun Da)": "6185.0", "Tần Suất % (Jun Da)": "99.9872684814", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 长", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木长", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "长", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "枨", "Unihan_Traditional (Chữ Phồn thể)": "棖", "Pinyin_Xie": "chéng", "Âm Hán Việt_Xie": "trành", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ bộ phận của cửa hoặc làm động từ với nghĩa chạm, chạm vào. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('棹', '{"9000": "6186.0", "Chữ Trung Quốc": "棹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 12 | nét | 木 | mộc | biểu nghĩa | gỗ | 卓 | trác | biểu âm | 棹 = 木 (Mộc, biểu nghĩa: gỗ) + 卓 (Trác, biểu âm); chữ hình thanh. Phần 木 gợi vật dụng gỗ dùng trên sông nước; 卓 cho âm zhào.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chèo\": gỗ (木) vươn cao (卓) trên mặt nước — cây chèo thuyền. | Gương Hán-Việt | chèo trong \"chèo thuyền\", \"bơi chèo\" | Mở khoá kiến thức | Biết 棹 mở khoá: 棹歌 (hát khi chèo thuyền), 孤棹 (mái chèo đơn độc — trong thơ cổ).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 棹 là chữ hình thanh: 木 (mộc, biểu nghĩa: gỗ) kết hợp với 卓 (trác, biểu âm). Chữ chỉ mái chèo — vật bằng gỗ dùng để chèo thuyền. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mái chèo", "Hạng Tần Suất (Jun Da)": "6186.0", "Tần Suất % (Jun Da)": "99.9872881193", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 卓", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木卓", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卓", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "棹", "Unihan_Traditional (Chữ Phồn thể)": "棹", "Pinyin_Xie": "zhào", "Âm Hán Việt_Xie": "trạo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ mái chèo hoặc làm động từ chỉ hành động chèo thuyền. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('纛', '{"9000": "6187.0", "Chữ Trung Quốc": "纛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 25 | nét | 毒 | độc | biểu âm | 縣 | huyện | biểu nghĩa | treo lên | 纛 = 毒 (Độc, biểu âm) + 縣 (Huyện, biểu nghĩa: treo lên); chữ hình thanh. Phần 縣 gợi vật được treo — lá cờ; 毒 cho âm dào. Wiktionary cũng gợi ý có thể là hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"độc\": lá cờ (縣 — treo) mạnh mẽ đầy độc lực (毒) — cờ tiết mao oai nghiêm. | Gương Hán-Việt | độc trong \"độc lập\", \"trung độc\" | Mở khoá kiến thức | Biết 纛 mở khoá: 纛旗 (cờ tiết mao lớn), 大纛 (đại kỳ — cờ lớn nhất của quân đội).", "Tự nguyên_Xie": "Theo Wiktionary, 纛 là chữ hình thanh: 縣 (huyện, biểu nghĩa: treo lên) kết hợp với 毒 (độc, biểu âm). Chỉ lá cờ tiết mao lớn — loại cờ dùng trong quân đội và lễ nghi hoàng gia. Wiktionary lưu ý có thể cũng là hội ý. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cờ tiết mao; cái cờ cái", "Hạng Tần Suất (Jun Da)": "6187.0", "Tần Suất % (Jun Da)": "99.9873077571", "GavinGrover_Once (Chiết tự trực tiếp)": "龶 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱龶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "纛", "Unihan_Traditional (Chữ Phồn thể)": "纛", "Pinyin_Xie": "dào", "Âm Hán Việt_Xie": "đạo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loại cờ lệnh lớn của quân đội thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嶷', '{"9000": "6188.0", "Chữ Trung Quốc": "嶷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 17 | nét | 嶷 | nghị | tượng hình | núi cao hiểm trở; trẻ thông minh | 嶷 là chữ độc lập; không có phân tích cấu tạo trong anchor. Bộ 山 (sơn) xác nhận liên quan đến núi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nghị\": núi (山) cao vững chắc — nghị lực như ngọn núi Cửu Nghi. | Gương Hán-Việt | nghị trong \"nghị lực\" (ý chí), \"nghị luận\" | Mở khoá kiến thức | Biết 嶷 mở khoá: 九嶷山 (Cửu Nghi Sơn — địa danh nổi tiếng), 岐嶷 (trẻ thông minh từ nhỏ).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 嶷 có hai âm: yí — dùng trong 九嶷山 (núi Cửu Nghi ở Hồ Nam); nì — nghĩa núi cao hiểm trở, hoặc trẻ nhỏ thông minh. Không có glyph origin. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên núi ở Hà Nam)", "Hạng Tần Suất (Jun Da)": "6188.0", "Tần Suất % (Jun Da)": "99.9873857916", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 疑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱山疑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "疑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "嶷", "Unihan_Traditional (Chữ Phồn thể)": "嶷", "Pinyin_Xie": "yí", "Âm Hán Việt_Xie": "nghi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ chỉ sự cao lớn, thông tuệ hoặc làm danh từ riêng chỉ tên núi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('妁', '{"9000": "6189.0", "Chữ Trung Quốc": "妁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 6 | nét | 妁 | chước | tượng hình | mai mối phía nhà gái | 妁 là chữ độc lập; không có phân tích cấu tạo chi tiết trong anchor. Bộ 女 (nữ) xác nhận liên quan đến phụ nữ — người mai mối phía nhà gái.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chước\": người phụ nữ (女) khéo léo sắp xếp (chước tính) — bà mai mối phía nhà gái. | Gương Hán-Việt | chước trong \"chước lượng\" (cân nhắc tính toán) | Mở khoá kiến thức | Biết 妁 mở khoá: 媒妁 (mai mối), 媒妁之言 (lời mai mối — hôn nhân qua trung gian).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 妁 chỉ người mai mối phía nhà gái; cũng là họ người. Thường ghép thành 媒妁 (mai mối). Không có glyph origin. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "làm mối", "Hạng Tần Suất (Jun Da)": "6189.0", "Tần Suất % (Jun Da)": "99.9874049127", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 勺", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女勺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "勺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "妁", "Unihan_Traditional (Chữ Phồn thể)": "妁", "Pinyin_Xie": "shuò", "Âm Hán Việt_Xie": "chước", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ người mai mối, thường đi kèm trong từ ghép môi chước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('杩', '{"9000": "6190.0", "Chữ Trung Quốc": "杩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 7 | nét | 木 | mộc | biểu nghĩa | gỗ, cây | 馬 | mã | biểu âm | 杩 = 木 (Mộc, biểu nghĩa: gỗ) + 馬 (Mã, biểu âm); chữ hình thanh. Phần 木 gợi vật liệu gỗ; 馬 cho âm mà.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mã\": gỗ (木) ngựa (馬) — tấm ván gỗ đứng đầu giường như con ngựa chắn gió. | Gương Hán-Việt | mã trong \"mã tốc\" (nhanh như ngựa), \"mã đầu\" (bến cảng) | Mở khoá kiến thức | Biết 杩 mở khoá: 床杩 (bậu đầu giường), dùng trong kiến trúc truyền thống.", "Tự nguyên_Xie": "Theo Wiktionary (usedForm: 榪), 杩 là chữ hình thanh: 木 (mộc, biểu nghĩa: gỗ) kết hợp với 馬 (mã, biểu âm). Chữ chỉ bậu đầu giường — thanh gỗ đỡ đầu giường. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bậu cửa; ngưỡng cửa; mớ; như \"từng mớ; một mớ\" (vhn)", "Hạng Tần Suất (Jun Da)": "6190.0", "Tần Suất % (Jun Da)": "99.9874240337", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 马", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木马", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "马", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "杩", "Unihan_Traditional (Chữ Phồn thể)": "榪", "Pinyin_Xie": "mà", "Âm Hán Việt_Xie": "mạt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Chữ này làm danh từ chỉ thanh chắn gỗ hoặc làm lượng từ chỉ mớ, bó. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鹛', '{"9000": "6191.0", "Chữ Trung Quốc": "鹛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 14 | nét | 鹛 | mi | tượng hình | chim hoạ mi, babbler | 鹛 (truyền thống: 鶥) là tên chim; không có phân tích cấu tạo chi tiết trong anchor. Bộ 鳥 (điểu) xác nhận tên chim.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mi\": chim (鳥) lông mịn như nhung — hoạ mi hót hay nhất trong rừng. | Gương Hán-Việt | mi trong \"hoạ mi\" (chim hót hay), \"mi nhân\" (người đẹp) | Mở khoá kiến thức | Biết 鹛 mở khoá: 画眉鸟 (chim hoạ mi), 相思鸟 (chim uyên ương cùng họ).", "Tự nguyên_Xie": "Theo Wiktionary (usedForm: 鶥), 鹛 chỉ các loài chim babbler. Không có glyph origin. chưa có nguồn học thuật về cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chim hoạ mi; hoạ mi; mi; như \"chim hoạ mi\" (gdhn)", "Hạng Tần Suất (Jun Da)": "6191.0", "Tần Suất % (Jun Da)": "99.9874431548", "GavinGrover_Once (Chiết tự trực tiếp)": "眉 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰眉鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "眉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鹛", "Unihan_Traditional (Chữ Phồn thể)": "鶥", "Pinyin_Xie": "méi", "Âm Hán Việt_Xie": "mi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài chim họa mi, thường dùng trong các từ ghép chỉ tên chim. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('羝', '{"9000": "6192.0", "Chữ Trung Quốc": "羝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羊 | Số nét | 11 | nét | 羊 | dương | biểu nghĩa | dê, cừu | 氐 | đê | biểu âm | 羝 = 羊 (Dương, biểu nghĩa: dê/cừu) + 氐 (Đê, biểu âm); chữ hình thanh. Phần 羊 gợi loài dê; 氐 cho âm dī.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dê\": con dê (羊) đực thấp bé (氐) — con dê đực húc đầu. | Gương Hán-Việt | dê trong \"con dê\" (山羊), \"dê đực\" | Mở khoá kiến thức | Biết 羝 mở khoá: 羝羊 (dê đực), 羝羊觸藩 (dê đực húc hàng rào — thành ngữ: tiến thoái lưỡng nan).", "Tự nguyên_Xie": "Kim văn | Theo Wiktionary, 羝 là chữ hình thanh: 羊 (dương, biểu nghĩa: dê/cừu) kết hợp với 氐 (đê, biểu âm). Chữ chỉ con dê đực — con đực của loài dê/cừu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con dê đực", "Hạng Tần Suất (Jun Da)": "6192.0", "Tần Suất % (Jun Da)": "99.9874622758", "GavinGrover_Once (Chiết tự trực tiếp)": "羊 + 氐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰羊氐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "氐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羊", "Unihan_Simplified (Chữ Giản thể)": "羝", "Unihan_Traditional (Chữ Phồn thể)": "羝", "Pinyin_Xie": "dī", "Âm Hán Việt_Xie": "đê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu làm danh từ chỉ con dê đực trong văn ngôn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('骖', '{"9000": "6193.0", "Chữ Trung Quốc": "骖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 11 | nét | 骖 | tham | tượng hình | ngựa bên sườn xe tam mã | 骖 (truyền thống: 驂) là chữ độc lập; không có phân tích cấu tạo trong anchor. Bộ 馬 (mã) xác nhận liên quan đến ngựa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tham\": ngựa (馬) bên sườn — con ngựa thứ ba đứng ngoài cùng trong xe tam mã. | Gương Hán-Việt | tham trong \"tham gia\" (cùng tham dự) | Mở khoá kiến thức | Biết 骖 mở khoá: 骖乘 (cùng ngồi xe), 骖靳 (dây buộc ngựa phụ).", "Tự nguyên_Xie": "Bạch thư | Tiểu triện | Theo Wiktionary (usedForm: 驂), 骖 chỉ hai con ngựa bên ngoài của đội xe tam mã (ba ngựa kéo xe); mở rộng ra chỉ ngựa nói chung. Không có glyph origin. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xe 3 ngựa", "Hạng Tần Suất (Jun Da)": "6193.0", "Tần Suất % (Jun Da)": "99.9874813969", "GavinGrover_Once (Chiết tự trực tiếp)": "马 + 参", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰马参", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "参", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "马", "Unihan_Simplified (Chữ Giản thể)": "骖", "Unihan_Traditional (Chữ Phồn thể)": "驂", "Pinyin_Xie": "cān", "Âm Hán Việt_Xie": "tham", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ con ngựa phụ bên cạnh xe hoặc động từ chỉ việc đi kèm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('祧', '{"9000": "6194.0", "Chữ Trung Quốc": "祧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 10 | nét | 祧 | thiêu | tượng hình | nhà thờ tổ xa đời | 祧 là chữ độc lập; không có phân tích cấu tạo trong anchor. Bộ 示 (thị) xác nhận liên quan đến lễ nghi, thờ cúng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiêu\": bàn thờ (示) xa xôi — nhà thiêu (kho) lưu giữ bài vị tổ đời xa. | Gương Hán-Việt | thiêu trong \"thiêu hủy\" — mượn âm, không liên nghĩa | Mở khoá kiến thức | Biết 祧 mở khoá: 宗祧 (tông pháp thờ cúng tổ tiên), 不祧 (không thể dời bài vị — chỉ vị tổ đặc biệt).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 祧 nghĩa là nhà thờ tổ nơi cất giữ bài vị tổ tiên xa đời; động từ: chuyển bài vị vào kho lưu trữ; kế thừa. Không có glyph origin. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhà thờ để thần chủ đã lâu đời", "Hạng Tần Suất (Jun Da)": "6194.0", "Tần Suất % (Jun Da)": "99.9875005179", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 兆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻兆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "祧", "Unihan_Traditional (Chữ Phồn thể)": "祧", "Pinyin_Xie": "tiāo", "Âm Hán Việt_Xie": "thiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Dùng làm danh từ chỉ miếu thờ tổ tiên đời xa hoặc động từ chỉ việc di dời bài vị. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('淠', '{"9000": "6195.0", "Chữ Trung Quốc": "淠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 11 | nét | 淠 | bí | tượng hình | sông Phì (Anhui); thuyền đi; cỏ nước sum suê | 淠 là chữ độc lập; không có phân tích cấu tạo trong anchor. Bộ 水/氵 (thủy) xác nhận liên quan đến nước, sông ngòi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bí\": dòng nước (氵) ngập tràn như bí bách — sông Phì nước chảy mạnh. | Gương Hán-Việt | bí trong \"bí ẩn\" (ẩn khuất), \"bí quyết\" | Mở khoá kiến thức | Biết 淠 mở khoá: 淠河 (sông Phì — địa danh An Huy).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Theo Wiktionary, 淠 chủ yếu chỉ sông Phì (淠河) ở tỉnh An Huy. Không có glyph origin. chưa có nguồn học thuật về cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thuyền đi; chìm ngập", "Hạng Tần Suất (Jun Da)": "6195.0", "Tần Suất % (Jun Da)": "99.98753876", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 畀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵畀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "畀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "淠", "Unihan_Traditional (Chữ Phồn thể)": "淠", "Pinyin_Xie": "pì", "Âm Hán Việt_Xie": "bí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ miêu tả trạng thái nước chảy mạnh hoặc động từ chỉ thuyền di chuyển. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('畎', '{"9000": "6196.0", "Chữ Trung Quốc": "畎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 田 | Số nét | 9 | nét | 畎 | khuyển | tượng hình | rãnh thoát nước giữa ruộng | 畎 là chữ độc lập; không có phân tích cấu tạo chi tiết trong anchor. Bộ 田 (điền) xác nhận liên quan đến ruộng đồng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khuyển\": ruộng (田) có rãnh nhỏ — như chú chó (犬) chạy dọc bờ ruộng theo kênh thoát nước. | Gương Hán-Việt | khuyển trong \"khuyển mã\" (chó ngựa — tự khiêm), \"trung khuyển\" | Mở khoá kiến thức | Biết 畎 mở khoá: 畎畝 (ruộng đồng, thôn quê), 畎夷 (tên bộ tộc cổ), 溝畎 (mương rãnh).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 畎 chỉ rãnh thoát nước nhỏ giữa các thửa ruộng; cũng nghĩa cánh đồng (cổ). Không có glyph origin. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1417.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Điền (097) Khuyển (058)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Điền (số 097 - ruộng/ 田 /chỉ ý) ở bên trái bộ Khuyển (số 058 - con chó/ 犬 /chỉ âm). Nơi có chó (người dân dẫn chó) ra cánh đồng để làm ruộng, bảo vệ mùa màng, săn bắt thú. Giải thích sự chuyển ý: Đây là chữ Hình thanh. Bộ Khuyển chỉ âm, bộ Điền chỉ ý. Quyển vốn là cái rãnh nước chạy dọc giữa các luống khoai ruộng lúa. Mở rộng là nơi đồng ruộng (quyển mẫu).", "Nghĩa Tiếng Việt_Xie": "khơi thông", "Hạng Tần Suất (Jun Da)": "6196.0", "Tần Suất % (Jun Da)": "99.9875578811", "GavinGrover_Once (Chiết tự trực tiếp)": "田 + 犬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰田犬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "犬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "田", "Unihan_Simplified (Chữ Giản thể)": "畎", "Unihan_Traditional (Chữ Phồn thể)": "畎", "Pinyin_Xie": "quǎn", "Âm Hán Việt_Xie": "quyến", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Làm danh từ chỉ rãnh nước nhỏ ở ruộng hoặc động từ chỉ việc đào rãnh khơi thông. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('箨', '{"9000": "6197.0", "Chữ Trung Quốc": "箨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 14 | nét | 箨 | thác | tượng hình | mo nang, cật tre bao quanh thân | 箨 là dạng giản thể của 籜. Không có cấu trúc hội ý hay hình thanh rõ ràng trong dạng giản thể; chữ gốc 籜 mang bộ 竹 (trúc). Đây là chữ dùng để chỉ bẹ tre, mo nang bao quanh thân tre.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thác\": bẹ tre (箨) bao quanh thân tre như tấm áo choàng — khi tre lớn, tấm áo tự \"thác\" (rơi) ra. | Gương Hán-Việt | thác — ít dùng độc lập, chủ yếu trong văn bản Hán cổ chỉ bẹ tre | Mở khoá kiến thức | Biết 箨 giúp nhận ra các từ chỉ bộ phận cây tre trong thực vật học và thơ cổ.", "Tự nguyên_Xie": "Lục thư thông | 箨 là dạng giản thể của 籜, được đơn giản hóa từ 擇→择. Chữ gốc 籜 gồm bộ 竹 (trúc) biểu nghĩa và phần biểu âm. Chữ dùng để chỉ bẹ tre — lớp vỏ bọc bên ngoài thân và đốt tre khi còn non, sau tự rụng. Chữ tạo muộn, chưa thấy rõ trong giáp cốt. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cật tre, mo nang", "Hạng Tần Suất (Jun Da)": "6197.0", "Tần Suất % (Jun Da)": "99.9875770021", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 择", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮择", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "择", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "箨", "Unihan_Traditional (Chữ Phồn thể)": "籜", "Pinyin_Xie": "tuò", "Âm Hán Việt_Xie": "thác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ lớp vỏ bọc ngoài của măng hoặc tre non. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鳐', '{"9000": "6198.0", "Chữ Trung Quốc": "鳐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 18 | nét | 鳐 | dao | tượng hình | loài cá đuối, cá đáy | 鳐 là dạng giản thể của 鰩, gốc gồm bộ 魚 (ngư, cá) biểu nghĩa và phần biểu âm. Chữ dùng để chỉ loài cá đuối hay cá đáy.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dao\": cá đuối (鳐) bơi như chiếc dao dẹt lướt qua đáy biển. | Gương Hán-Việt | dao — ít dùng trong tiếng Việt hiện đại, xuất hiện trong từ điển Hán-Việt cổ | Mở khoá kiến thức | Biết 鳐 giúp nhận ra các từ chỉ loài cá biển trong sinh vật học và văn học cổ.", "Tự nguyên_Xie": "Tiểu triện | 鳐 là dạng giản thể của 鰩. Chữ gốc 鰩 có bộ 魚 (cá) biểu nghĩa, chỉ loài cá đuối (ray/skate) — loài cá dẹt sống ở đáy biển. Wiktionary chỉ ghi {{Han etym}} không có giải thích chi tiết về cấu tạo. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá chuồn, cá bo (thứ cá hay chúi dưới bùn)", "Hạng Tần Suất (Jun Da)": "6198.0", "Tần Suất % (Jun Da)": "99.9875961232", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "鳐", "Unihan_Traditional (Chữ Phồn thể)": "鰩", "Pinyin_Xie": "yáo", "Âm Hán Việt_Xie": "diêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ các loài cá đuối hoặc cá chuồn trong sinh học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('剡', '{"9000": "6199.0", "Chữ Trung Quốc": "剡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 刀 | Số nét | 10 | nét | 炎 | viêm | biểu âm | lửa nóng | 刂 | biểu nghĩa | dao, lưỡi cắt | 剡 = 炎 (Viêm, biểu âm: lửa cháy) + 刂 (đao, biểu nghĩa: dao, lưỡi cắt). Đây là chữ hình thanh: bộ 刂 cho biết nghĩa liên quan đến lưỡi dao sắc, 炎 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chiêm\": 剡 (chiêm) = lửa (炎 biểu âm) + dao (刂) — lưỡi dao nóng như lửa, sắc bén cắt gọt. | Gương Hán-Việt | chiêm — ít dùng độc lập; trong địa danh ''Chiêm Khê'' (剡溪, Chiết Giang) | Mở khoá kiến thức | Biết 剡 giúp đọc địa danh cổ Chiết Giang và các từ chỉ sự sắc bén trong văn bản Hán cổ.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 剡 là chữ hình thanh: 炎 biểu âm + 刀/刂 (dao) biểu nghĩa. Tiểu triện đã được ghi nhận. Nghĩa gốc là ''sắc bén, nhọn'' — lưỡi dao cắt gọt. Chữ này còn là địa danh (huyện Chiêm, Chiết Giang) và là gốc của tên sông Chiêm (剡溪). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sắc, nhọn", "Hạng Tần Suất (Jun Da)": "6199.0", "Tần Suất % (Jun Da)": "99.9876715738", "GavinGrover_Once (Chiết tự trực tiếp)": "炎 + 刂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰炎刂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "炎", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "刂", "Unihan_Simplified (Chữ Giản thể)": "剡", "Unihan_Traditional (Chữ Phồn thể)": "剡", "Pinyin_Xie": "shàn", "Âm Hán Việt_Xie": "diệm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ miêu tả vật sắc nhọn hoặc động từ chỉ hành động gọt nhọn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('吲', '{"9000": "6200.0", "Chữ Trung Quốc": "吲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 7 | nét | 吲 | dặn | tượng hình | mỉm cười, tên gọi trong hóa học (indole) | 吲 không có phân tích etymology rõ ràng trong anchor. Chữ này gồm bộ 口 (khẩu, miệng) và phần còn lại. Dùng chủ yếu trong thuật ngữ hóa học tiếng Trung hiện đại (吲哚 = indole).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dặn\": 吲 (dặn) có bộ miệng (口) — miệng dặn dò, nhắc nhở; trong hóa học là gốc indole. | Gương Hán-Việt | dặn — ít dùng độc lập; chủ yếu trong 吲哚 (indole, thuật ngữ hóa học) | Mở khoá kiến thức | Biết 吲 giúp nhận ra thuật ngữ hóa học 吲哚 (indole) trong tài liệu sinh hóa tiếng Trung.", "Tự nguyên_Xie": "吲 không có nguồn Wiktionary rõ ràng. Chữ gồm bộ 口 (miệng) và phần biểu âm, nghĩa Hán-Việt là ''dặn'' (mỉm cười). Tuy nhiên trong tiếng Trung hiện đại, 吲 chủ yếu dùng phiên âm thuật ngữ hóa học: 吲哚 (indole). Chưa có nguồn học thuật xác nhận cấu tạo gốc. Chữ tạo muộn, chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mỉm cười", "Hạng Tần Suất (Jun Da)": "6200.0", "Tần Suất % (Jun Da)": "99.9876901781", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 引", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口引", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "引", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "吲", "Unihan_Traditional (Chữ Phồn thể)": "吲", "Pinyin_Xie": "yǐn", "Âm Hán Việt_Xie": "sẩn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường làm động từ trong văn ngôn để chỉ hành động cười nhẹ hoặc mỉm cười. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嫫', '{"9000": "6201.0", "Chữ Trung Quốc": "嫫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 13 | nét | 女 | nữ | biểu nghĩa | người phụ nữ | 莫 | mạc | biểu âm | không, chớ | 嫫 = 女 (Nữ, biểu nghĩa: người phụ nữ) + 莫 (Mạc, biểu âm). Đây là chữ hình thanh: bộ 女 cho biết nghĩa liên quan đến phụ nữ, 莫 cho âm gần với 嫫.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mụ\": 嫫 (mụ) = nữ (女) + Mạc (莫 biểu âm) — người phụ nữ xấu xí (嫫母) trong thần thoại, nhưng đức hạnh được khen ngợi. | Gương Hán-Việt | mụ — ít dùng; chủ yếu trong 嫫母 (Mụ Mẫu, nhân vật thần thoại) | Mở khoá kiến thức | Biết 嫫 giúp đọc văn bản thần thoại cổ Trung Quốc về thời Hoàng Đế.", "Tự nguyên_Xie": "Theo Wiktionary, 嫫 là chữ hình thanh: 女 (phụ nữ) biểu nghĩa + 莫 biểu âm. Chữ chủ yếu dùng trong 嫫母 — tên của người phụ nữ xấu xí nổi tiếng thời Hoàng Đế trong thần thoại Trung Quốc.嫫母 được truyền là vợ của Hoàng Đế, người phụ nữ tuy xấu nhưng đức hạnh cao. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đàn bà xấu", "Hạng Tần Suất (Jun Da)": "6201.0", "Tần Suất % (Jun Da)": "99.9877087824", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 莫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女莫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "莫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "嫫", "Unihan_Traditional (Chữ Phồn thể)": "嫫", "Pinyin_Xie": "mó", "Âm Hán Việt_Xie": "mô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này là danh từ thường dùng trong tên riêng Mụ Mẫu, người vợ thứ tư có dung mạo xấu xí của Hoàng Đế. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('戽', '{"9000": "6202.0", "Chữ Trung Quốc": "戽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 戶 | Số nét | 8 | nét | 戽 | hộ | tượng hình | gáo múc nước, dụng cụ tát nước | 戽 không có phân tích hội ý hay hình thanh rõ ràng trong anchor; Wiktionary chỉ ghi rfdef (cần định nghĩa). Chữ chỉ dụng cụ múc nước (gáo, gầu tát nước) dùng trong nông nghiệp cổ truyền.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hộ\": 戽 (hộ) — cái gáo hộ trực múc nước cho ruộng lúa, công cụ quen thuộc của nhà nông. | Gương Hán-Việt | hộ — ít dùng độc lập; trong 戽斗 (gầu tát nước) | Mở khoá kiến thức | Biết 戽 giúp đọc văn bản nông nghiệp cổ và hiểu thuật ngữ thủy lợi truyền thống.", "Tự nguyên_Xie": "Wiktionary ghi 戽 với {{Han etym}} nhưng không có giải thích cấu tạo chi tiết. Chữ chỉ dụng cụ tát nước thủ công (bucket/bailing scoop) dùng để tưới ruộng. Compounds gồm 戽斗 (gầu tát nước), 戽水 (múc nước), 水戽. Chưa có nguồn học thuật xác nhận cấu tạo gốc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gáo múc nước", "Hạng Tần Suất (Jun Da)": "6202.0", "Tần Suất % (Jun Da)": "99.9877273866", "GavinGrover_Once (Chiết tự trực tiếp)": "户 + 斗", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴户斗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "斗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "户", "Unihan_Simplified (Chữ Giản thể)": "戽", "Unihan_Traditional (Chữ Phồn thể)": "戽", "Pinyin_Xie": "hù", "Âm Hán Việt_Xie": "hố", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này vừa làm danh từ chỉ cái gáo múc nước, vừa làm động từ chỉ hành động tát nước vào ruộng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('糗', '{"9000": "6203.0", "Chữ Trung Quốc": "糗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 16 | nét | 米 | mễ | biểu nghĩa | gạo, ngũ cốc | 臭 | xú | biểu âm | mùi hôi | 糗 = 米 (Mễ, biểu nghĩa: gạo, lương thực) + 臭 (Xú, biểu âm: mùi). Đây là chữ hình thanh: bộ 米 cho biết nghĩa liên quan đến lương thực khô, 臭 cho âm gần với 糗.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xúc\": 糗 (xúc) = gạo (米) + mùi (臭 biểu âm) — lương khô có mùi thơm đặc trưng, thức ăn khô mang theo đường. | Gương Hán-Việt | xúc — ít dùng độc lập; trong văn cổ chỉ lương thực khô dùng cho quân lính hành quân | Mở khoá kiến thức | Biết 糗 giúp đọc văn bản lịch sử về lương thực quân đội và hiểu tiếng lóng hiện đại về sự xấu hổ.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 糗 là chữ hình thanh: 米 (gạo) biểu nghĩa + 臭 biểu âm. Hình bigseal và tiểu triện đã được ghi nhận. Nghĩa gốc là lương thực khô nấu chín — gạo hoặc lúa mì rang/nấu chín rồi phơi khô để mang đi đường. Trong tiếng Trung hiện đại, 糗 còn có nghĩa thứ hai là ''xấu hổ, mất mặt'' (tiếng lóng). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lương khô", "Hạng Tần Suất (Jun Da)": "6203.0", "Tần Suất % (Jun Da)": "99.9877459909", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 臭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米臭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "臭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "糗", "Unihan_Traditional (Chữ Phồn thể)": "糗", "Pinyin_Xie": "qiǔ", "Âm Hán Việt_Xie": "khứu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ lương khô hoặc làm tính từ trong khẩu ngữ để chỉ sự lúng túng, xấu hổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鸮', '{"9000": "6204.0", "Chữ Trung Quốc": "鸮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 10 | nét | 鸮 | hiêu | tượng hình | con cú, chim cú mèo | 鸮 là dạng giản thể của 鴞, gốc gồm bộ 鳥 (điểu, chim) biểu nghĩa. Chữ chỉ loài chim cú mèo (owl) — loài chim săn mồi về đêm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hiêu\": 鸮 (hiêu) — chim cú mèo kêu ''hiêu hiêu'' trong đêm tối, điềm không lành trong văn hóa dân gian. | Gương Hán-Việt | hiêu — trong 鸱鸮 (si hiêu, chim cú); ít dùng độc lập trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 鸮 giúp đọc thơ cổ và văn học dân gian Trung Quốc về điềm báo và chim cú.", "Tự nguyên_Xie": "Tiểu triện | 鸮 là dạng giản thể của 鴞 (giản thể hóa từ 鳥→鸟). Tiểu triện đã được ghi nhận. Chữ chỉ loài cú mèo — loài chim ăn thịt về đêm có đặc trưng đôi mắt lớn. Trong văn học cổ Trung Quốc, cú mèo (鸱鸮) bị coi là điềm gở. Hanziyuan có ảnh tiểu triện. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con vọ", "Hạng Tần Suất (Jun Da)": "6204.0", "Tần Suất % (Jun Da)": "99.9877645952", "GavinGrover_Once (Chiết tự trực tiếp)": "号 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰号鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "号", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鸮", "Unihan_Traditional (Chữ Phồn thể)": "鴞", "Pinyin_Xie": "xiāo", "Âm Hán Việt_Xie": "hào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ để chỉ các loài chim thuộc họ cú mèo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蕰', '{"9000": "6205.0", "Chữ Trung Quốc": "蕰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 15 | nét | 蕰 | uẩn | tượng hình | cỏ thủy sinh, tảo nước | 蕰 là biến thể cổ của 薀 (dạng thay thế của 蘊). Không có phân tích hình thanh/hội ý rõ ràng. Chữ dùng để chỉ cỏ mọc trong nước (waterweed) và nghĩa phái sinh là tích tụ, chứa đựng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uẩn\": 蕰 (uẩn) — cỏ tảo chứa đựng (uẩn) dưỡng chất nuôi cá; liên hệ với ''uẩn khúc'' (điều ẩn chứa bên trong). | Gương Hán-Việt | uẩn — trong ''uẩn tàng'' (ẩn chứa), liên quan đến 蘊 (uẩn, chứa đựng, tích tụ) | Mở khoá kiến thức | Biết 蕰 giúp nhận ra họ chữ 蘊/薀/蕰 chỉ sự tích tụ, chứa đựng trong văn bản cổ.", "Tự nguyên_Xie": "Theo Wiktionary, 蕰 là biến thể cổ của 薀, chính là dạng thay thế của 蘊 (tích tụ, chứa). Nghĩa gốc là cỏ thủy sinh (waterweed) — loại cỏ mọc dưới nước dùng nuôi cá. Phái sinh thêm nghĩa ''tích tụ, chứa đựng'' (như 蘊藏). Chưa có nguồn học thuật chi tiết về cấu tạo gốc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỏ ôn (cỏ mọc trong nước, để nuôi cá); rong kim ngư (một loại cỏ mọc lâu năm ở nước)", "Hạng Tần Suất (Jun Da)": "6205.0", "Tần Suất % (Jun Da)": "99.9877831994", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 温", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹温", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "温", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蕰", "Unihan_Traditional (Chữ Phồn thể)": "薀", "Pinyin_Xie": "wēn", "Âm Hán Việt_Xie": "ôn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ một loại cỏ nước hoặc làm động từ với nghĩa tích tụ, chứa đựng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('坼', '{"9000": "6206.0", "Chữ Trung Quốc": "坼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 8 | nét | 土 | thổ | biểu nghĩa | đất | 斥 | xích | biểu âm | xua đuổi, trách mắng | 坼 = 土 (Thổ, biểu nghĩa: đất) + 斥 (Xích, biểu âm). Đây là chữ hình thanh: bộ 土 cho biết nghĩa liên quan đến đất nứt vỡ, 斥 cho âm. Hình thức gốc là 𡍩.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sách\": 坼 (sách) = đất (土) + xích (斥 biểu âm) — đất bị xua đẩy, tách rời, nứt ra như khi trời hạn hán. | Gương Hán-Việt | sách — ít dùng độc lập; trong văn bản cổ chỉ đất nứt, vật vỡ nứt | Mở khoá kiến thức | Biết 坼 giúp đọc văn học cổ và thơ Đường miêu tả cảnh hạn hán, thiên nhiên khắc nghiệt.", "Tự nguyên_Xie": "Theo Wiktionary, 坼 là chữ hình thanh: 土 (đất) biểu nghĩa + 斥 biểu âm. Hình thức gốc là 𡍩. Nghĩa gốc là đất nứt nẻ — như mặt đất khô nứt ra trong hạn hán, hoặc vỏ cây nứt theo năm tháng. Chưa có nguồn học thuật chi tiết hơn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nứt ra", "Hạng Tần Suất (Jun Da)": "6206.0", "Tần Suất % (Jun Da)": "99.9878018037", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 斥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土斥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "斥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "坼", "Unihan_Traditional (Chữ Phồn thể)": "坼", "Pinyin_Xie": "chè", "Âm Hán Việt_Xie": "sách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hiện tượng đất đai hoặc đồ vật bị nứt ra do khô hanh. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('璺', '{"9000": "6207.0", "Chữ Trung Quốc": "璺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 20 | nét | 璺 | vấn | tượng hình | vết nứt trên đồ ngọc | 璺 không có phân tích hình thanh/hội ý rõ ràng trong anchor. Wiktionary chỉ ghi phiên âm và định nghĩa. Chữ chỉ vết nứt, kẽ nứt nhỏ trên đồ gốm, ngọc, hoặc đồ vật cứng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vấn\": 璺 (vấn) — vết nứt trên ngọc, như câu hỏi (vấn) không có lời giải — vết nứt nhỏ nhưng khó lành. | Gương Hán-Việt | vấn — ít dùng; trong tục ngữ và văn bản cổ chỉ vết nứt đồ vật | Mở khoá kiến thức | Biết 璺 giúp đọc tục ngữ cổ và văn học miêu tả sự không hoàn hảo, vết nứt.", "Tự nguyên_Xie": "Theo Wiktionary, 璺 (wèn) chỉ vết nứt nhỏ trên ngọc, gốm hoặc đồ cứng. Câu tục ngữ nổi tiếng: ''沿着鸡蛋上的缝儿找璺'' (tìm vết nứt theo kẽ trứng — tìm cớ gây sự). Không có giải thích chi tiết về cấu tạo gốc trong nguồn anchor. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vết nứt của viên ngọc", "Hạng Tần Suất (Jun Da)": "6207.0", "Tần Suất % (Jun Da)": "99.9878204079", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 玉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱玉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "璺", "Unihan_Traditional (Chữ Phồn thể)": "璺", "Pinyin_Xie": "wèn", "Âm Hán Việt_Xie": "vấn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ vết rạn nứt trên bề mặt đồ gốm, sứ hoặc ngọc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('栊', '{"9000": "6208.0", "Chữ Trung Quốc": "栊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 9 | nét | 栊 | lung | tượng hình | cửa sổ lưới, lồng nhốt vật | 栊 là dạng giản thể của 櫳, gốc gồm bộ 木 (mộc, gỗ) biểu nghĩa. Chữ chỉ cái lồng bằng gỗ, cửa sổ có thanh gỗ, hoặc nhà ở (nghĩa văn học).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lung\": 栊 (lung) = gỗ làm lồng — cái lồng (lung) bằng gỗ nhốt chim, hoặc cửa sổ gỗ như lồng nhốt ánh sáng. | Gương Hán-Việt | lung — trong ''lung linh'' (ánh sáng xuyên qua khe) liên hệ; ít dùng độc lập trong tiếng Việt | Mở khoá kiến thức | Biết 栊 giúp đọc thơ Đường miêu tả kiến trúc cổ và cảnh cửa sổ lưới.", "Tự nguyên_Xie": "Tiểu triện | 栊 là dạng giản thể của 櫳. Chữ gốc 櫳 có bộ 木 (gỗ) biểu nghĩa. Theo Wiktionary, nghĩa là: (1) lồng/cũi nuôi vật; (2) cửa sổ lưới/thanh gỗ; (3) nhà ở (nghĩa văn học). Tiểu triện đã được ghi nhận qua hanziyuan. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cửa sổ; cái lồng, cái cũi", "Hạng Tần Suất (Jun Da)": "6208.0", "Tần Suất % (Jun Da)": "99.9878390122", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 龙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木龙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "龙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "栊", "Unihan_Traditional (Chữ Phồn thể)": "櫳", "Pinyin_Xie": "lóng", "Âm Hán Việt_Xie": "long", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loại lồng chim, cũi nhốt thú hoặc khung song cửa sổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镝', '{"9000": "6209.0", "Chữ Trung Quốc": "镝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 16 | nét | 镝 | địch | tượng hình | mũi tên sắt; nguyên tố dysprosium | 镝 là dạng giản thể của 鏑, gốc gồm bộ 金 (kim, kim loại) biểu nghĩa. Chữ chỉ đầu mũi tên bịt sắt trong vũ khí cổ, và được dùng trong hóa học hiện đại để phiên âm nguyên tố dysprosium (Dy).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"địch\": 镝 (địch) — mũi tên địch (kẻ thù) bịt sắt bay vút; trong hóa học là kim loại đất hiếm dysprosium. | Gương Hán-Việt | địch — ít dùng độc lập; trong 矢镝 (mũi tên), và hóa học 镝 (Dy) | Mở khoá kiến thức | Biết 镝 giúp đọc văn bản lịch sử về vũ khí cổ và tài liệu hóa học về kim loại đất hiếm.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 镝 là dạng giản thể của 鏑. Chữ gốc 鏑 có bộ 金 (kim loại) biểu nghĩa. Tiểu triện và lục thư thông đã được ghi nhận. Nghĩa gốc là đầu mũi tên bịt kim loại. Trong hóa học hiện đại, 镝 (địch) là ký hiệu phiên âm của nguyên tố Dysprosium (Dy, số nguyên tử 66). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mũi tên bịt sắt; nguyên tố điprosi, Dy", "Hạng Tần Suất (Jun Da)": "6209.0", "Tần Suất % (Jun Da)": "99.9878576165", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 啇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅啇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "啇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镝", "Unihan_Traditional (Chữ Phồn thể)": "鏑", "Pinyin_Xie": "dī", "Âm Hán Việt_Xie": "đích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ mũi tên nhọn bằng sắt thời cổ hoặc nguyên tố hóa học Dysprosium. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('疔', '{"9000": "6210.0", "Chữ Trung Quốc": "疔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 7 | nét | 疒 | biểu nghĩa | bệnh tật | 丁 | đinh | biểu âm | đinh, can thiên can | 疔 = 疒 (bộ bệnh, biểu nghĩa: bệnh tật) + 丁 (Đinh, biểu âm). Đây là chữ hình thanh: bộ 疒 cho biết nghĩa liên quan đến bệnh da, 丁 cho âm đọc là dīng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đinh\": 疔 (đinh) = bệnh (疒) + đinh (丁 biểu âm) — nhọt đầu đinh, nhọn như cái đinh, đau nhức. | Gương Hán-Việt | đinh — trong ''đinh nhọt'' (nhọt đầu đinh), y học cổ truyền | Mở khoá kiến thức | Biết 疔 giúp đọc tài liệu y học Đông y về bệnh ngoài da và nhận ra các chữ bệnh trong bộ 疒.", "Tự nguyên_Xie": "Theo Wiktionary, 疔 là chữ hình thanh: 疒 (bệnh) biểu nghĩa + 丁 biểu âm. Nghĩa gốc là nhọt đầu đinh — loại mụn nhọt nhỏ, cứng, đầu nhọn như đinh sắt, thường gặp trên da mặt hoặc tay. Trong y học Đông phương, đây là loại ung thư da nguy hiểm nếu không điều trị. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhọt, mụn", "Hạng Tần Suất (Jun Da)": "6210.0", "Tần Suất % (Jun Da)": "99.9878762207", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 丁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒丁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "疔", "Unihan_Traditional (Chữ Phồn thể)": "疔", "Pinyin_Xie": "dīng", "Âm Hán Việt_Xie": "đinh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loại mụn nhọt sưng đau trên da. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瘰', '{"9000": "6211.0", "Chữ Trung Quốc": "瘰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 16 | nét | 瘰 | lỗi | tượng hình | bệnh nổi hạch cổ, lao hạch | 瘰 không có phân tích hình thanh/hội ý rõ ràng trong anchor; Wiktionary chỉ ghi rfdef (cần định nghĩa). Bộ 疒 biểu nghĩa bệnh tật. Chữ thường đi kèm 癧 thành 瘰癧 — chỉ bệnh lao hạch cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lỗi\": 瘰 (lỗi) — bệnh 瘰癧 là hạch lỗi lồi lên ở cổ, như những cục đá nhỏ nằm dưới da. | Gương Hán-Việt | lỗi — trong 瘰癧 (lỗi lịch, bệnh lao hạch) | Mở khoá kiến thức | Biết 瘰 giúp đọc tài liệu y học Đông y về bệnh lao hạch và các bệnh tuyến bạch huyết.", "Tự nguyên_Xie": "Theo Wiktionary, 瘰 (luǒ) có bộ 疒 (bệnh) và được dùng chủ yếu trong 瘰癧 (lao hạch, scrofula) — bệnh nổi nhiều hạch nhỏ ở cổ do lao. Wiktionary ghi rfdef (cần định nghĩa chi tiết hơn). Không có giải thích cấu tạo gốc. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: lỗi lịch 瘰癧,瘰疬)", "Hạng Tần Suất (Jun Da)": "6211.0", "Tần Suất % (Jun Da)": "99.987894825", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 累", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒累", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "累", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "瘰", "Unihan_Traditional (Chữ Phồn thể)": "瘰", "Pinyin_Xie": "luǒ", "Âm Hán Việt_Xie": "lỗi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, thường kết hợp thành từ ghép lỗi lịch để chỉ bệnh lao hạch ở cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谮', '{"9000": "6212.0", "Chữ Trung Quốc": "谮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 14 | nét | 谮 | tấm | tượng hình | vu cáo, nói gièm pha | 谮 là dạng giản thể của 譖, gốc gồm bộ 言 (ngôn, lời nói) biểu nghĩa. Chữ chỉ hành động vu cáo, nói gièm pha người khác với người có quyền.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tấm\": 谮 (tấm) = lời nói (言) dùng để vu cáo — những lời tấm tức, gièm pha người khác lên bề trên. | Gương Hán-Việt | tấm — ít dùng độc lập; trong văn bản Hán cổ chỉ sự vu cáo, gièm pha | Mở khoá kiến thức | Biết 谮 giúp đọc văn bản lịch sử và thơ cổ về gian thần vu cáo trung thần.", "Tự nguyên_Xie": "Tiểu triện | 谮 là dạng giản thể của 譖. Chữ gốc 譖 có bộ 言 (lời nói) biểu nghĩa. Tiểu triện đã được ghi nhận. Nghĩa gốc là vu cáo, nói xấu người khác trước bề trên — dùng lời nói để hại người. Chữ này chuyên dùng trong văn bản chính trị và văn học cổ miêu tả sự gian trá. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cáo mách, vu vạ; nói gièm pha", "Hạng Tần Suất (Jun Da)": "6212.0", "Tần Suất % (Jun Da)": "99.9879134293", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 朁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠朁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "朁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "谮", "Unihan_Traditional (Chữ Phồn thể)": "譖", "Pinyin_Xie": "zèn", "Âm Hán Việt_Xie": "trấm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường đứng trước danh từ chỉ người để biểu thị hành vi vu khống. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('辋', '{"9000": "6213.0", "Chữ Trung Quốc": "辋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 12 | nét | 辋 | võng | tượng hình | vành bánh xe, nan hoa | 辋 là dạng giản thể của 輞, gốc gồm bộ 車 (xa, xe) biểu nghĩa. Chữ chỉ vành ngoài của bánh xe — phần gỗ hoặc kim loại bao quanh bánh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"võng\": 辋 (võng) = xe (车) + vành — vành (võng) ngoài bánh xe như tấm võng bao quanh, giữ chặt các nan hoa. | Gương Hán-Việt | võng — ít dùng độc lập; trong 轮辋 (vành bánh xe) | Mở khoá kiến thức | Biết 辋 giúp đọc tài liệu kỹ thuật về xe cộ và văn bản lịch sử về giao thông cổ.", "Tự nguyên_Xie": "辋 là dạng giản thể của 輞 (giản thể hóa từ 車→车). Nghĩa gốc là vành bánh xe (wheel rim) — phần khung ngoài bao quanh bánh xe gỗ cổ đại. Trong tiếng Trung hiện đại, 轮辋 là vành bánh xe (wheel rim). Chưa có giải thích chi tiết cấu tạo gốc. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái vành bánh xe", "Hạng Tần Suất (Jun Da)": "6213.0", "Tần Suất % (Jun Da)": "99.9879320335", "GavinGrover_Once (Chiết tự trực tiếp)": "车 + 罔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰车罔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "罔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "车", "Unihan_Simplified (Chữ Giản thể)": "辋", "Unihan_Traditional (Chữ Phồn thể)": "輞", "Pinyin_Xie": "wǎng", "Âm Hán Việt_Xie": "võng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường dùng trong văn học cổ hoặc kết hợp thành từ ghép để chỉ bộ phận của bánh xe. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('碥', '{"9000": "6214.0", "Chữ Trung Quốc": "碥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 14 | nét | 碥 | biển | tượng hình | mỏm đá nhô ra bờ nước, đá núi nghiêng | 碥 không có nguồn etymology trong anchor. Bộ 石 (thạch, đá) biểu nghĩa rõ ràng. Chữ chỉ mỏm đá nhô ra ở bờ sông hoặc núi nghiêng ra mặt nước. Chữ tạo muộn, chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"biển\": 碥 (biển) = đá (石) + mỏm nhô — mỏm đá (biển) nhô ra mặt nước như tảng đá chắn gió. | Gương Hán-Việt | biển — ít dùng; trong địa danh và văn bản địa lý cổ chỉ mỏm đá nhô | Mở khoá kiến thức | Biết 碥 giúp đọc tên địa danh và văn bản địa lý cổ Trung Quốc.", "Tự nguyên_Xie": "碥 không có nguồn Wiktionary hay anchor etymology. Bộ 石 (đá) biểu nghĩa, chỉ loại đá/mỏm đá nghiêng nhô ra bờ nước. Chữ dùng trong địa danh và miêu tả địa hình hiểm trở. Chưa có nguồn học thuật xác nhận cấu tạo gốc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mỏm đá; đá núi nghiêng ra bờ nước", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 扁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石扁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "扁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "碥", "Unihan_Traditional (Chữ Phồn thể)": "碥", "Pinyin_Xie": "biǎn", "Âm Hán Việt_Xie": "biển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường dùng làm địa danh hoặc chỉ các khối đá dốc bên bờ sông. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('豂', '{"9000": "6215.0", "Chữ Trung Quốc": "豂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 谷 | Số nét | 18 | nét | 豂 | liêu | tượng hình | hang trống rỗng, rỗng không | 豂 không có phân tích hình thanh/hội ý rõ ràng trong anchor. Wiktionary ghi nghĩa là hang trống rỗng, trống không. Chữ dùng rất ít trong văn bản cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"liêu\": 豂 (liêu) — hang động liêu tịch, trống vắng như bầu trời xa tít. | Gương Hán-Việt | liêu — ít dùng; trong ''liêu vắng'', ''hư liêu'' (trống không, vắng lặng) về nghĩa | Mở khoá kiến thức | Biết 豂 giúp đọc từ điển cổ và văn bản Hán xưa về địa hình hang động.", "Tự nguyên_Xie": "Theo Wiktionary, 豂 (liáo) có nghĩa: hang trống rỗng (empty cave), rỗng không, sâu xa. Không có giải thích chi tiết về cấu tạo gốc. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "豱", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "谷 + 翏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰谷翏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "翏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "谷", "Unihan_Simplified (Chữ Giản thể)": "豂", "Unihan_Traditional (Chữ Phồn thể)": "豂", "Pinyin_Xie": "liáo", "Âm Hán Việt_Xie": "liêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này chủ yếu dùng làm danh từ chỉ hang sâu hoặc tính từ mô tả sự trống rỗng trong văn ngôn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('黒', '{"9000": "6216.0", "Chữ Trung Quốc": "黒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 黑 | Số nét | 11 | nét | 黒 | hắc | tượng hình | màu đen (biến thể Nhật Bản của 黑) | 黒 là dạng biến thể shinjitai (chữ cải cách Nhật Bản) của 黑, thay hai chấm bằng một nét. Về cấu trúc gốc, 黑 = 囪 (lỗ ống khói) + 灬 (lửa) — chỉ vết muội đen từ ống khói.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hắc\": 黒 (hắc) = lỗ ống khói (囪) trên lửa (灬) — khói đen từ lửa tạo ra màu hắc (đen) bám trên tường. | Gương Hán-Việt | hắc — trong ''hắc ám'' (tối đen), ''hắc bạch'' (đen trắng), ''ô hắc'' (đen bóng) | Mở khoá kiến thức | Biết 黒 giúp đọc văn bản Nhật-Trung và nhận ra biến thể shinjitai trong tài liệu song ngữ.", "Tự nguyên_Xie": "Lụa Mã Vương Đôi | Đại triện | Theo Wiktionary, 黒 là biến thể shinjitai của 黑 (đen). Hình thức 黑 có bộ 囪 (lỗ ống khói) trên 灬 (lửa) — muội đen từ ống khói. Lụa Mã Vương Đôi và bigseal đã được ghi nhận. Biến thể Nhật Bản 黒 thay thế hai chấm dưới bằng một nét ngang, tương tự như 母 thành 毋 trong shinjitai. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Biến thể tiếng Nhật của 黑", "Hạng Tần Suất (Jun Da)": "6216.0", "Tần Suất % (Jun Da)": "99.9880250549", "GavinGrover_Once (Chiết tự trực tiếp)": "里 + 灬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱里灬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "灬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "里", "Unihan_Simplified (Chữ Giản thể)": "黒", "Unihan_Traditional (Chữ Phồn thể)": "黒", "Pinyin_Xie": "hēi", "Âm Hán Việt_Xie": "hắc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Động từ | 动词 | Chữ này làm tính từ thường đứng trước danh từ để tu từ hoặc làm động từ mang nghĩa bôi đen. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('劂', '{"9000": "6217.0", "Chữ Trung Quốc": "劂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 刀 | Số nét | 14 | nét | 劂 | khoét | tượng hình | dụng cụ khắc, đục khoét | 劂 không có phân tích hình thanh/hội ý rõ ràng trong anchor; chủ yếu dùng trong từ ghép 剞劂 (dụng cụ khắc chạm). Bộ 刀/刂 biểu nghĩa lưỡi cắt/đục.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khoét\": 劂 (khoét) — dụng cụ khoét đục vào gỗ, đá để tạo hình chạm khắc. | Gương Hán-Việt | khoét — trong 剞劂 (cơ khoét, dụng cụ khắc); ít dùng độc lập | Mở khoá kiến thức | Biết 劂 giúp đọc văn bản nghề thủ công, khắc gỗ và in ấn cổ đại Trung Quốc.", "Tự nguyên_Xie": "Theo Wiktionary, 劂 (jué) dùng trong 剞劂 — chỉ dụng cụ khắc chạm, đục gỗ. Không có giải thích chi tiết về cấu tạo gốc. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: kỷ quyết 剞劂)", "Hạng Tần Suất (Jun Da)": "6217.0", "Tần Suất % (Jun Da)": "99.9880431423", "GavinGrover_Once (Chiết tự trực tiếp)": "厥 + 刂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰厥刂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "厥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "刂", "Unihan_Simplified (Chữ Giản thể)": "劂", "Unihan_Traditional (Chữ Phồn thể)": "劂", "Pinyin_Xie": "jué", "Âm Hán Việt_Xie": "quyết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ dụng cụ khắc gỗ hoặc làm động từ trong từ ghép chỉ việc khắc in sách vở. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('潋', '{"9000": "6218.0", "Chữ Trung Quốc": "潋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 14 | nét | 潋 | liễm | tượng hình | nước trào mênh mông, sóng vỗ | 潋 là dạng giản thể của 瀲, gốc gồm bộ 氵 (thuỷ, nước) biểu nghĩa. Chữ chỉ cảnh nước dâng tràn, sóng lăn tăn. Thường dùng trong 瀲灩/潋滟 miêu tả ánh sáng lấp lánh trên mặt nước.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"liễm\": 潋 (liễm) = nước (氵) + âm Liễm — mặt nước liễm lịm ánh sáng, sóng vỗ liên miên như bài thơ Tây Hồ của Tô Đông Pha. | Gương Hán-Việt | liễm — trong 瀲灩 (liễm diễm, sóng ánh sáng lấp lánh) trong thơ Đường-Tống | Mở khoá kiến thức | Biết 潋 giúp đọc thơ cổ Trung Quốc, đặc biệt thơ Tô Đông Pha về cảnh hồ.", "Tự nguyên_Xie": "潋 là dạng giản thể của 瀲. Chữ gốc 瀲 có bộ 氵 (nước) biểu nghĩa. Nghĩa là nước đầy tràn, sóng gợn lăn tăn. Trong thơ cổ có câu nổi tiếng của Tô Đông Pha: ''水光瀲灩晴方好'' (ánh nước lấp lánh đẹp khi trời quang). Chưa có giải thích cấu tạo gốc chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước trào mênh mông; ước chảy sóng vỗ", "Hạng Tần Suất (Jun Da)": "6218.0", "Tần Suất % (Jun Da)": "99.9880612298", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 敛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵敛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "潋", "Unihan_Traditional (Chữ Phồn thể)": "瀲", "Pinyin_Xie": "liàn", "Âm Hán Việt_Xie": "liễm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này làm tính từ thường dùng trong văn thơ để tả cảnh sóng nước lấp lánh hoặc đầy tràn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('孓', '{"9000": "6219.0", "Chữ Trung Quốc": "孓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 子 | Số nét | 3 | nét | 孓 | quyết | tượng hình | thiếu cánh tay trái; ấu trùng muỗi | 孓 có liên quan đến 子, biến thể thiếu một nét — chỉ sự thiếu sót, không đầy đủ. Chữ dùng trong 孑孓 chỉ ấu trùng muỗi (lăng quăng).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quyết\": 孓 (quyết) — chữ con (子) bị quyết mất một nét, như con lăng quăng thiếu tay chân đầy đủ. | Gương Hán-Việt | quyết — trong 孑孓 (kiết quyết, lăng quăng/ấu trùng muỗi) | Mở khoá kiến thức | Biết 孓 giúp nhận ra 孑孓 (lăng quăng) trong sách sinh học và phòng chống sốt xuất huyết.", "Tự nguyên_Xie": "Theo Wiktionary, 孓 (jué) có gốc từ 子. Nghĩa cổ: thiếu cánh tay trái (missing left arm). Nghĩa hiện đại: dùng trong 孑孓 (lằng quằng, ấu trùng muỗi). Có một số cách đọc âm và nghĩa phái sinh. Chưa có giải thích cấu tạo chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: kiết củng 孑孒,孑孓)", "Hạng Tần Suất (Jun Da)": "6219.0", "Tần Suất % (Jun Da)": "99.9880793173", "GavinGrover_Once (Chiết tự trực tiếp)": "了 + ㇏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "Ký hiệu: lock", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "了㇏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㇏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "了", "Unihan_Simplified (Chữ Giản thể)": "孓", "Unihan_Traditional (Chữ Phồn thể)": "孓", "Pinyin_Xie": "jué", "Âm Hán Việt_Xie": "quyết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ thường đi đôi với chữ kiết để chỉ sự cô đơn hoặc làm danh từ chỉ ấu trùng của muỗi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('螋', '{"9000": "6220.0", "Chữ Trung Quốc": "螋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 15 | nét | 螋 | sưu | tượng hình | con cầu cái, rết nước (một loại côn trùng) | 螋 không có phân tích hình thanh/hội ý rõ ràng trong anchor; bộ 虫 (trùng, côn trùng) biểu nghĩa. Chữ chủ yếu dùng trong 蠼螋 — chỉ con cầu cái (earwig).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sưu\": 螋 (sưu) = côn trùng (虫) + âm sưu — con cầu cái (蠼螋) sục sạo (sưu) khắp nơi trong bóng tối. | Gương Hán-Việt | sưu — trong 蠼螋 (quắc sưu, con cầu cái/earwig) | Mở khoá kiến thức | Biết 螋 giúp nhận ra 蠼螋 (cầu cái/earwig) trong tài liệu sinh học về côn trùng.", "Tự nguyên_Xie": "Theo Wiktionary, 螋 (sōu) dùng trong 蠼螋 (earwig — côn trùng có càng đuôi). Bộ 虫 biểu nghĩa côn trùng. Không có giải thích chi tiết về cấu tạo gốc. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: quắc sưu 蠼螋)", "Hạng Tần Suất (Jun Da)": "6220.0", "Tần Suất % (Jun Da)": "99.9880974048", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 叟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫叟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "叟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "螋", "Unihan_Traditional (Chữ Phồn thể)": "螋", "Pinyin_Xie": "sōu", "Âm Hán Việt_Xie": "sưu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ và hầu như chỉ xuất hiện trong từ ghép song âm tiết để chỉ một loại côn trùng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲳', '{"9000": "6221.0", "Chữ Trung Quốc": "鲳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 16 | nét | 鲳 | xương | tượng hình | cá xương, cá chim (một loài cá biển) | 鲳 là dạng giản thể của 鯧, gốc gồm bộ 魚 (ngư, cá) biểu nghĩa. Chữ chỉ loài cá chim (pomfret/butterfish) — cá biển dẹt, thịt trắng ngon.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xương\": 鲳 (xương) = cá (鱼) + âm xương — cá xương (鲳鱼) còn gọi là cá chim, thịt ít xương mà lại ngon. | Gương Hán-Việt | xương — trong 鲳鱼 (cá xương/cá chim, pomfret); ít dùng độc lập | Mở khoá kiến thức | Biết 鲳 giúp đọc thực đơn và tài liệu ẩm thực biển Trung Quốc.", "Tự nguyên_Xie": "鲳 là dạng giản thể của 鯧. Chữ gốc 鯧 có bộ 魚 (cá) biểu nghĩa. Nghĩa là cá chim (pomfret) — loài cá biển dẹt, có thịt trắng ngon, phổ biến trong ẩm thực Trung Quốc và Việt Nam. Không có giải thích chi tiết về cấu tạo gốc. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con cá xương", "Hạng Tần Suất (Jun Da)": "6221.0", "Tần Suất % (Jun Da)": "99.9881154923", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 昌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼昌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲳", "Unihan_Traditional (Chữ Phồn thể)": "鯧", "Pinyin_Xie": "chāng", "Âm Hán Việt_Xie": "xương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ đứng độc lập hoặc kết hợp với các từ chỉ màu sắc để gọi tên các loài cá chim cụ thể. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铙', '{"9000": "6222.0", "Chữ Trung Quốc": "铙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 11 | nét | 铙 | nao | tượng hình | cái chiêng lớn, não bạt | 铙 là dạng giản thể của 鐃, gốc gồm bộ 金 (kim, kim loại) biểu nghĩa. Chữ chỉ loại nhạc cụ gõ bằng đồng — chiêng lớn hoặc não bạt dùng trong quân đội và lễ nhạc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nao\": 铙 (nao) = kim loại (金) + âm nao — tiếng nao nao của chiêng đồng vang lên, hiệu lệnh thu quân. | Gương Hán-Việt | nao — trong 铙钹 (nao bát, não bạt) nhạc cụ; ''nao nao'' trong cụm từ liên quan âm thanh | Mở khoá kiến thức | Biết 铙 giúp đọc văn bản lịch sử quân sự và nhạc lý cổ đại Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | 铙 là dạng giản thể của 鐃 (giản thể hóa từ 堯→尧). Chữ gốc 鐃 có bộ 金 (kim loại) biểu nghĩa. Tiểu triện đã được ghi nhận. Nghĩa gốc là nhạc cụ gõ đồng — loại chuông/chiêng nhỏ dùng để báo hiệu trong quân đội (''鸣金收兵'' = gõ chiêng thu quân). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái nao bạt to", "Hạng Tần Suất (Jun Da)": "6222.0", "Tần Suất % (Jun Da)": "99.9881335797", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 尧", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅尧", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尧", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铙", "Unihan_Traditional (Chữ Phồn thể)": "鐃", "Pinyin_Xie": "náo", "Âm Hán Việt_Xie": "nao, nạo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại nhạc cụ gõ cổ đại bằng đồng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('塄', '{"9000": "6223.0", "Chữ Trung Quốc": "塄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 12 | nét | 塄 | lăng | tượng hình | bờ đất mé ruộng, gờ đất | 塄 không có nguồn etymology trong anchor. Bộ 土 (thổ, đất) biểu nghĩa rõ ràng. Chữ chỉ gờ đất, bờ đất nhỏ ở mé ruộng hoặc sườn đồi. Chữ tạo muộn, chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lăng\": 塄 (lăng) = đất (土) + âm lăng — bờ đất lăng cao ở mé ruộng, ranh giới giữa các thửa ruộng bậc thang. | Gương Hán-Việt | lăng — ít dùng; trong địa danh và văn bản nông nghiệp miền Bắc Trung Quốc | Mở khoá kiến thức | Biết 塄 giúp đọc tài liệu nông nghiệp và địa lý ruộng bậc thang Bắc Trung Quốc.", "Tự nguyên_Xie": "塄 không có nguồn Wiktionary hay anchor etymology. Bộ 土 (đất) biểu nghĩa. Chữ chỉ bờ đất, gờ đất nhỏ ở mé thửa ruộng hoặc sườn núi — loại địa hình phổ biến trong nông nghiệp ruộng bậc thang ở miền Bắc Trung Quốc. Chưa có nguồn học thuật xác nhận cấu tạo gốc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gò đất ở mé ruộng", "Hạng Tần Suất (Jun Da)": "6223.0", "Tần Suất % (Jun Da)": "99.9881516672", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "塄", "Unihan_Traditional (Chữ Phồn thể)": "塄", "Pinyin_Xie": "léng", "Âm Hán Việt_Xie": "lăng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bờ đất hoặc gò đất dốc ở rìa ruộng bậc thang. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('萆', '{"9000": "6224.0", "Chữ Trung Quốc": "萆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 萆 | bí | tượng hình | cây ti giải, áo tơi; tên gọi nhiều loài thực vật | 萆 không có phân tích hình thanh/hội ý rõ ràng trong anchor; gốc gồm bộ 艹 (thảo, cỏ cây) biểu nghĩa. Chữ dùng để gọi một số loài thực vật, đặc biệt là ti giải (một vị thuốc Đông y) và áo tơi bằng cỏ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bí\": 萆 (bí) = cỏ (艹) + âm bí — cây bí (萆), tên gọi cây ti giải trong Đông y, cũng có nghĩa áo tơi cỏ che mưa. | Gương Hán-Việt | bí — trong 萆薢 (bí giải, vị thuốc Đông y); ít dùng độc lập | Mở khoá kiến thức | Biết 萆 giúp đọc tài liệu Đông y và sách bản thảo cổ điển về dược liệu.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Theo Wiktionary, 萆 (bì) dùng để gọi tên nhiều loại cây: cây ti giải (vị thuốc Đông y), áo tơi cỏ (straw raincoat), hoặc là biến thể của 蔽 (che giấu). Hình kim văn và tiểu triện đã được ghi nhận. Anchor ghi ''dùng trong tên một số cây''. Chưa có nguồn học thuật chi tiết. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tằm thầu dầu Như''蓖''; ti giải (vị thuốc Đông y)", "Hạng Tần Suất (Jun Da)": "6224.0", "Tần Suất % (Jun Da)": "99.9881697547", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 卑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹卑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "萆", "Unihan_Traditional (Chữ Phồn thể)": "萆", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "tì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ dùng trong tên gọi các loại thảo dược hoặc vị thuốc cổ truyền. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('碲', '{"9000": "6225.0", "Chữ Trung Quốc": "碲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 14 | nét | 石 | thạch | biểu nghĩa | đá, khoáng chất | 帝 | đế | biểu âm | vua, hoàng đế | 碲 = 石 (Thạch, biểu nghĩa: đá, khoáng chất) + 帝 (Đế, biểu âm). Đây là chữ hình thanh: bộ 石 cho biết nghĩa là khoáng chất/kim loại, 帝 cho âm đọc. Chữ hiện đại phiên âm nguyên tố tellurium (Te).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đế\": 碲 (đế) = đá (石) + đế (帝 biểu âm) — nguyên tố tellurium, ''vua'' (đế) của nhóm chalcogen trong bảng tuần hoàn. | Gương Hán-Việt | đế — trong 碲 (nguyên tố Te); ít dùng độc lập ngoài hóa học | Mở khoá kiến thức | Biết 碲 giúp đọc tài liệu hóa học tiếng Trung về nguyên tố đất hiếm và bán dẫn.", "Tự nguyên_Xie": "Theo Wiktionary, 碲 là chữ hình thanh: 石 (đá, khoáng) biểu nghĩa + 帝 biểu âm. Chữ được tạo ra để phiên âm nguyên tố Tellurium (Te, số nguyên tử 52) trong bảng tuần hoàn tiếng Trung. Không có hình thức cổ trong anchor; chữ thuần kỹ thuật hiện đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố telu, Te", "Hạng Tần Suất (Jun Da)": "6225.0", "Tần Suất % (Jun Da)": "99.9881878422", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 帝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石帝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "帝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "碲", "Unihan_Traditional (Chữ Phồn thể)": "碲", "Pinyin_Xie": "dì", "Âm Hán Việt_Xie": "đế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ nguyên tố hóa học phi kim telu trong bảng tuần hoàn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('粋', '{"9000": "6226.0", "Chữ Trung Quốc": "粋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 10 | nét | 粋 | túy | tượng hình | thuần túy, tinh khiết (biến thể Nhật của 粹) | 粋 là dạng shinjitai (biến thể cải cách Nhật Bản) của 粹, đơn giản hóa phần 卒→卆. Bộ 米 (mễ, gạo) liên quan đến tinh lọc/tinh khiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"túy\": 粋 (túy) = gạo (米) tinh lọc — tinh túy nhất, thuần khiết nhất; trong tiếng Nhật là ''iki'' — phong cách thanh lịch, tinh tế. | Gương Hán-Việt | túy — trong ''tinh túy'' (精粹), ''thuần túy'' (純粹); biến thể Nhật 粋 nghĩa phong cách | Mở khoá kiến thức | Biết 粋 giúp đọc văn bản Nhật-Trung về thẩm mỹ và văn hóa Edo.", "Tự nguyên_Xie": "粋 là dạng shinjitai Nhật Bản của 粹 (tinh túy, tinh khiết). Chữ gốc 粹 có bộ 米 (gạo) biểu nghĩa — gạo tinh lọc, thuần khiết. Wiktionary ghi đây là dạng giản hóa Nhật thay 卒 bằng 卆. Chữ dùng nhiều hơn trong tiếng Nhật (粋 = iki, phong cách thanh lịch Edo) hơn là tiếng Trung. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "粋", "Hạng Tần Suất (Jun Da)": "6226.0", "Tần Suất % (Jun Da)": "99.9882059297", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 卆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米卆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "粋", "Unihan_Traditional (Chữ Phồn thể)": "粋", "Pinyin_Xie": "cuì", "Âm Hán Việt_Xie": "túy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ phần tinh hoa hoặc làm tính từ chỉ sự thuần khiết, không pha tạp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('纻', '{"9000": "6227.0", "Chữ Trung Quốc": "纻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 7 | nét | 纻 | trữ | tượng hình | cây gai, sợi gai lanh | 纻 là dạng giản thể của 紵 (giản thể hóa từ 宁→㝉). Bộ 糸/纟 (ti, sợi) biểu nghĩa chỉ vải/sợi. Chữ gốc 紵 chỉ cây gai (ramie) và vải gai làm từ sợi gai.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trữ\": 纻 (trữ) = sợi (纟) + âm trữ — sợi gai trữ sẵn để dệt vải, như người ta trữ thức ăn cho mùa đông. | Gương Hán-Việt | trữ — trong 纻布 (vải gai), 纻麻 (gai lanh); ít dùng độc lập trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 纻 giúp đọc tài liệu dệt may cổ và sách bản thảo về cây gai lanh.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 纻 là dạng giản thể của 紵. Tiểu triện và lục thư thông đã được ghi nhận. Bộ 糸 (sợi) biểu nghĩa. Nghĩa gốc là sợi gai lanh (ramie fiber) — loại sợi dệt tự nhiên từ cây gai, nổi tiếng về độ bền và độ thoáng. Vải gai 纻布 là một trong những loại vải cổ truyền Trung Quốc. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sợi gai", "Hạng Tần Suất (Jun Da)": "6227.0", "Tần Suất % (Jun Da)": "99.9882240171", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 㝉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟㝉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㝉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "纻", "Unihan_Traditional (Chữ Phồn thể)": "紵", "Pinyin_Xie": "zhù", "Âm Hán Việt_Xie": "trữ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ cây gai hoặc sợi gai dùng làm nguyên liệu dệt may. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('沭', '{"9000": "6228.0", "Chữ Trung Quốc": "沭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 8 | nét | 氵 | biểu nghĩa | nước | 朮 | biểu âm | phần biểu âm | 沭 = 氵 (thủy, biểu nghĩa: nước) + 朮 (biểu âm). Đây là chữ hình thanh: bộ 氵 cho biết nghĩa liên quan đến sông nước, 朮 cho âm. Chữ chủ yếu dùng trong địa danh sông Thuật (沭河) ở Sơn Đông-Giang Tô.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thuật\": 沭 (thuật) = nước (氵) + âm thuật — sông Thuật (沭河) chảy qua đất Thuật, tên địa danh lịch sử vùng Sơn Đông-Giang Tô. | Gương Hán-Việt | thuật — trong 沭河 (sông Thuật), 沭阳 (Thuật Dương); địa danh Trung Quốc | Mở khoá kiến thức | Biết 沭 giúp đọc địa danh lịch sử và tài liệu địa lý vùng Sơn Đông-Giang Tô.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 沭 là chữ hình thanh: 氵 (nước) biểu nghĩa + 朮 biểu âm. Tiểu triện đã được ghi nhận. Chữ chủ yếu là tên riêng sông Thuật (沭河) — con sông ở vùng Sơn Đông và Giang Tô. Tên địa danh quan trọng: 沭阳 (Thuật Dương, huyện ở Giang Tô). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Thuật", "Hạng Tần Suất (Jun Da)": "6228.0", "Tần Suất % (Jun Da)": "99.9882421046", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 术", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵术", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "术", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "沭", "Unihan_Traditional (Chữ Phồn thể)": "沭", "Pinyin_Xie": "shù", "Âm Hán Việt_Xie": "thuật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ riêng dùng để chỉ con sông Thuật chảy qua tỉnh Sơn Đông và Giang Tô. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('祏', '{"9000": "6229.0", "Chữ Trung Quốc": "祏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 9 | nét | 祏 | thạch | tượng hình | hộp đá đựng bài vị tổ tông trong tông miếu | 祏 không có phân tích hình thanh/hội ý rõ ràng trong anchor; bộ 示 (thị, thờ cúng) biểu nghĩa. Chữ chỉ hộp đá hoặc bài vị đá đặt trong tông miếu để thờ tổ tiên.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thạch\": 祏 (thạch) = thờ cúng (示) + âm thạch — hộp đá (thạch) đựng bài vị tổ tông trong tông miếu, nơi thờ phụng thiêng liêng. | Gương Hán-Việt | thạch — ít dùng; trong văn bản lễ chế và tông miếu học cổ đại | Mở khoá kiến thức | Biết 祏 giúp đọc văn bản lễ nghi tông miếu và nghiên cứu tôn giáo/phong tục thờ tổ tiên Trung Quốc.", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | Theo Wiktionary, 祏 (shí) chỉ hộp đá đặt trong tông miếu để cất giữ bài vị tổ tiên — tương đương bài vị thần chủ. Hình giáp cốt và tiểu triện đã được ghi nhận. Bộ 示 (thờ cúng) biểu nghĩa. Chữ dùng trong văn bản lễ chế và nghi lễ tôn miếu cổ đại. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hộp đá đựng bài vị tổ tông trong tông miếu; bài vị tổ tông trong tông miếu", "Hạng Tần Suất (Jun Da)": "6229.0", "Tần Suất % (Jun Da)": "99.9882601921", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 石", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻石", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "石", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "祏", "Unihan_Traditional (Chữ Phồn thể)": "祏", "Pinyin_Xie": "shí", "Âm Hán Việt_Xie": "thạch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ chiếc hộp bằng đá dùng để cất giữ bài vị trong tông miếu thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鱲', '{"9000": "6230.0", "Chữ Trung Quốc": "鱲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 26 | nét | 鱲 | liệt | tượng hình | một loài cá; dùng trong địa danh | 鱲 không có phân tích hình thanh/hội ý rõ ràng trong anchor; bộ 魚 (ngư, cá) biểu nghĩa. Chữ chỉ một loài cá và được dùng trong địa danh nổi tiếng 赤鱲角 (Chek Lap Kok, Hong Kong).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"liệt\": 鱲 (liệt) = cá (魚) + âm liệt — cá liệt (鱲), tên địa danh 赤鱲角 nơi có sân bay Hong Kong. | Gương Hán-Việt | liệt — ít dùng độc lập; trong 赤鱲角 (địa danh Hong Kong) | Mở khoá kiến thức | Biết 鱲 giúp đọc địa danh Hong Kong và tài liệu địa lý Quảng Đông.", "Tự nguyên_Xie": "Theo Wiktionary, 鱲 (liè) chỉ một loài cá và được dùng trong địa danh. Chữ nổi tiếng qua 赤鱲角 (Chek Lap Kok) — tên của đảo/bán đảo ở Hong Kong, nơi có sân bay Hong Kong International Airport. Bộ 魚 biểu nghĩa cá. Không có giải thích chi tiết về cấu tạo gốc. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Lý", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 巤", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚巤", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "𫚭", "Unihan_Traditional (Chữ Phồn thể)": "鱲", "Pinyin_Xie": "liè", "Âm Hán Việt_Xie": "liệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ dùng trong tên gọi của một số loài cá xương. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鄩', '{"9000": "6231.0", "Chữ Trung Quốc": "鄩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 14 | nét | 鄩 | tầm | tượng hình | tên đất cổ | 鄩 là địa danh/họ người, cấu trúc không rõ từ dữ liệu hiện có; xử lý là độc thể mang nghĩa tượng hình về tên đất.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt ''tầm'': bộ Ấp (邑) bên phải cho thấy đây là tên đất — vùng đất mang họ Tầm lưu lại trong sử sách Xuân Thu. | Gương Hán-Việt | ''tầm'' trong họ Tầm (ít dùng trong tiếng Việt hiện đại) | Mở khoá kiến thức | 鄩 là chữ chuyên dùng cho địa danh/họ người; ít gặp ngoài văn bản cổ điển.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không cung cấp thông tin nguồn gốc hình chữ cho 鄩. Đây là chữ chuyên dùng ghi địa danh (tên huyện ở Sơn Đông) và họ người thời Xuân Thu. Bộ 邑 (ấp, thành) thường gặp trong các địa danh Trung Quốc cổ. Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên đất thời Xuân Thu, Trung Quốc, nay thuộc Hà Nam); (tên nước cổ, nay thuộc tỉnh Sơn Đông, Trung Quốc); họ Tầm", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "尋 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰尋阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "𬩽", "Unihan_Traditional (Chữ Phồn thể)": "鄩", "Pinyin_Xie": "xún", "Âm Hán Việt_Xie": "tầm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ riêng chỉ địa danh thời cổ hoặc họ của người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('怍', '{"9000": "6232.0", "Chữ Trung Quốc": "怍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 8 | nét | 怍 | tạc | tượng hình | hổ thẹn | 怍 không có dữ liệu cấu trúc rõ ràng trong nguồn hiện có. Bộ 心 (tâm, trái tim) ngầm trong chữ gợi nghĩa cảm xúc hổ thẹn. Xử lý là độc thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt ''tạc'': chữ nhỏ mà nặng — người quân tử sợ nhất là ''tạc'' (hổ thẹn với người), ngang với sợ thẹn với trời. | Gương Hán-Việt | ''tạc'' trong ''hổ tạc'', ''thẹn thùng'' (văn cổ) | Mở khoá kiến thức | Biết 怍 mở khoá: 愧怍 (hổ thẹn), 慚怍 (xấu hổ); chủ yếu dùng trong văn học cổ điển.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không cung cấp phân tích hình chữ chi tiết cho 怍, chỉ ghi nhận âm cổ. Chữ mang nghĩa ''hổ thẹn, xấu hổ'', dùng chủ yếu trong văn ngôn. Câu nổi tiếng nhất trong Mạnh Tử: ''Ngưỡng bất quý ư thiên, phủ bất tạc ư nhân'' (Ngẩng mặt không thẹn trời, cúi đầu không thẹn người). Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tủi thẹn", "Hạng Tần Suất (Jun Da)": "6232.0", "Tần Suất % (Jun Da)": "99.9884405501", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 乍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄乍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "怍", "Unihan_Traditional (Chữ Phồn thể)": "怍", "Pinyin_Xie": "zuò", "Âm Hán Việt_Xie": "tạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ miêu tả trạng thái tâm lý hổ thẹn hoặc làm động từ trong văn ngôn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('糍', '{"9000": "6233.0", "Chữ Trung Quốc": "糍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 15 | nét | 糍 | tì | tượng hình | bánh nếp | 糍 không có dữ liệu cấu trúc rõ trong nguồn. Bộ 米 (mễ, gạo) là dấu hiệu loại thực phẩm từ gạo. Xử lý là độc thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt ''tì'': bộ Mễ (米) gợi gạo — bánh nếp (糍粑) làm từ gạo nếp giã dẻo, dính như keo. | Gương Hán-Việt | ''tì'' trong bánh tì (ít dùng trong tiếng Việt); tương đương bánh nếp | Mở khoá kiến thức | Biết 糍 mở khoá: 糍粑 (bánh nếp giã), 麻糍 (bánh nếp mè), 糯米糍 (bánh nếp nhân dừa).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không cung cấp phân tích hình chữ chi tiết cho 糍. Chữ chỉ loại bánh làm từ gạo nếp giã nhuyễn (glutinous rice cake), phổ biến trong ẩm thực miền Nam Trung Quốc. Từ phổ biến nhất là 糍粑 (bánh nếp kiểu Tứ Xuyên/Quý Châu). Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: từ ba 糍粑)", "Hạng Tần Suất (Jun Da)": "6233.0", "Tần Suất % (Jun Da)": "99.9884581208", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 兹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米兹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "糍", "Unihan_Traditional (Chữ Phồn thể)": "糍", "Pinyin_Xie": "cí", "Âm Hán Việt_Xie": "từ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp thành từ ghép để chỉ các loại bánh nếp giã nhuyễn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鸻', '{"9000": "6234.0", "Chữ Trung Quốc": "鸻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 11 | nét | 行 | hàng | biểu âm | 鳥 | điểu | biểu nghĩa | chim | 鸻 = 行 (Hàng, biểu âm) + 鳥 (Điểu, biểu nghĩa: chim); chữ hình thanh. Chữ chỉ loài chim choi choi (plover) sống ở bãi biển và đồng lầy.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không rõ — bộ Điểu (鳥) và bộ Hàng (行) gợi con chim đi từng hàng dọc bãi biển — đúng tập tính chim choi choi. | Gương Hán-Việt | ''hành'' trong tên khoa học; ít dùng trong tiếng Việt | Mở khoá kiến thức | 鸻 chủ yếu dùng trong điểu học và tên gọi loài vật; từ liên quan: 燕鴴 (chim nhàn plover).", "Tự nguyên_Xie": "Theo Wiktionary (dạng 鴴), 鸻 là chữ hình thanh: 鳥 (điểu, chim) biểu nghĩa, 行 biểu âm. Chữ chỉ chim choi choi (plover) thuộc họ Charadriinae, loài chim di cư thường thấy ở ven biển. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chim choi choi", "Hạng Tần Suất (Jun Da)": "6234.0", "Tần Suất % (Jun Da)": "99.9884756915", "GavinGrover_Once (Chiết tự trực tiếp)": "行 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰行鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鸟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "行", "Unihan_Simplified (Chữ Giản thể)": "鸻", "Unihan_Traditional (Chữ Phồn thể)": "鴴", "Pinyin_Xie": "héng", "Âm Hán Việt_Xie": "hằng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong sinh học để chỉ họ chim choi choi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('仵', '{"9000": "6235.0", "Chữ Trung Quốc": "仵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 6 | nét | 仵 | ngỗ | tượng hình | đối lập, tương tự | 仵 không có dữ liệu cấu trúc trong nguồn. Bộ 亻(nhân, người) gợi liên quan đến người. Xử lý là độc thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt ''ngỗ'': bộ Nhân (亻) — người đứng đối diện người, hai bên tương đương nhau; 仵作 là người đứng đối diện với tử thi để khám xét. | Gương Hán-Việt | ''ngỗ'' ít dùng trong tiếng Việt hiện đại; gặp trong văn bản pháp lý cổ | Mở khoá kiến thức | Biết 仵 mở khoá: 仵作 (ngọc tác, nhân viên pháp y cổ đại Trung Quốc).", "Tự nguyên_Xie": "Wiktionary không cung cấp phân tích hình chữ cho 仵. Chữ có nghĩa ''tương đồng, đối nhau'', đặc biệt dùng trong từ 仵作 chỉ nhân viên khám nghiệm tử thi thời cổ Trung Quốc (tương đương pháp y ngày nay). Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đối lập", "Hạng Tần Suất (Jun Da)": "6235.0", "Tần Suất % (Jun Da)": "99.9884932622", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 午", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻午", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "午", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "仵", "Unihan_Traditional (Chữ Phồn thể)": "仵", "Pinyin_Xie": "wǔ", "Âm Hán Việt_Xie": "ngỗ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng trong từ ghép chỉ người khám nghiệm tử thi thời xưa hoặc biểu thị sự chống đối. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('柰', '{"9000": "6236.0", "Chữ Trung Quốc": "柰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 9 | nét | 柰 | nại | tượng hình | cây táo dại trên bàn thờ | 柰 là tượng hình: cây (木) đặt trên bàn thờ (示), chỉ nghi lễ đốt gỗ tế thần hoặc cây táo dại. Wiktionary xếp là tượng hình (pictograph), không có lsCodes rõ ràng. Hai chữ 奈 và 祟 được phái sinh từ 柰.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt ''nại'': cây (木) trên bàn thờ (示) — gỗ cây nại từng dùng trong nghi lễ cổ đại, hai chữ cháu 奈 và 祟 đều mang dáng dấp này. | Gương Hán-Việt | ''nại'' trong cây nại (ít dùng tiếng Việt hiện đại) | Mở khoá kiến thức | Biết 柰 giúp hiểu nguồn gốc của 奈 (nại hà — biết làm sao) và 祟 (tà khí).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 柰 là tượng hình: cây (木) đặt trên bàn thờ (示), chỉ lễ đốt gỗ hiến thần hoặc cây táo dại trong nghi lễ. Hai chữ 奈 (biết làm sao) và 祟 (ma quỷ gây hại) đều xuất phát từ 柰 qua biến thể hình dạng. Nghĩa hiện đại chủ yếu là ''cây nại'' (crab-apple). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây nại", "Hạng Tần Suất (Jun Da)": "6236.0", "Tần Suất % (Jun Da)": "99.9885108329", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 示", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱木示", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "示", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "柰", "Unihan_Traditional (Chữ Phồn thể)": "柰", "Pinyin_Xie": "nài", "Âm Hán Việt_Xie": "nại", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Dùng làm danh từ chỉ một loại cây ăn quả hoặc làm động từ biểu thị sự đối phó, xoay xở. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('棼', '{"9000": "6237.0", "Chữ Trung Quốc": "棼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 12 | nét | 棼 | phần | tượng hình | xà nhà rối loạn | 棼 không có dữ liệu cấu trúc rõ ràng trong nguồn. Bộ 木 (mộc, gỗ) gợi liên quan gỗ/xà nhà. Xử lý là độc thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt ''phần'': gỗ (木) của mái nhà rối loạn — 治絲益棼, càng cố gỡ càng thêm rối như xà nhà chồng chéo. | Gương Hán-Việt | ''phần'' trong nghĩa rối loạn (văn cổ) | Mở khoá kiến thức | Biết 棼 mở khoá thành ngữ: 治絲益棼 (càng gỡ càng rối, ý cưỡng cầu làm hỏng thêm).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không cung cấp phân tích hình chữ chi tiết cho 棼. Chữ có hai nghĩa: (1) xà ngang ngắn trong mái nhà, (2) rối loạn, lộn xộn. Thành ngữ nổi tiếng 治絲益棼 (càng gỡ càng rối) dùng nghĩa thứ hai. Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái xà ngắn; rối bung; vải gai, vải bông; rậm rạp", "Hạng Tần Suất (Jun Da)": "6237.0", "Tần Suất % (Jun Da)": "99.9885284036", "GavinGrover_Once (Chiết tự trực tiếp)": "林 + 分", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱林分", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "分", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "林", "Unihan_Simplified (Chữ Giản thể)": "棼", "Unihan_Traditional (Chữ Phồn thể)": "棼", "Pinyin_Xie": "fén", "Âm Hán Việt_Xie": "phần", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ miêu tả trạng thái rối ren, hỗn loạn hoặc danh từ chỉ kết cấu gỗ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('氇', '{"9000": "6238.0", "Chữ Trung Quốc": "氇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 毛 | Số nét | 16 | nét | 毛 | mao | biểu nghĩa | lông, sợi | 魯 | lỗ | biểu âm | 氇 = 毛 (Mao, biểu nghĩa: lông/sợi) + 魯 (Lỗ, biểu âm); chữ hình thanh. Chữ chỉ loại vải dạ thô dày từ Tây Tạng (phổ lỗ 氆氌/氆氇).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt ''lỗ'': bộ Mao (毛) gợi lông cừu — vải dạ Tibet (氆氌) dày nặng như lông cừu vùng cao nguyên. | Gương Hán-Việt | ''lỗ'' ít dùng trong tiếng Việt; gặp trong từ vựng dệt may dân tộc | Mở khoá kiến thức | 氇 chỉ dùng trong từ 氆氌 (phổ lỗ) — vải dạ Tây Tạng.", "Tự nguyên_Xie": "Theo Wiktionary (dạng 氌), 氇 là chữ hình thanh: 毛 (mao, lông) biểu nghĩa chất liệu sợi, 魯 biểu âm. Chữ chỉ dùng trong từ 氆氌 (phổ lỗ) — loại vải dạ thô dày dệt từ lông cừu ở Tây Tạng và các vùng miền núi Trung Á. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: phổ lỗ 氆氌,氆氇)", "Hạng Tần Suất (Jun Da)": "6238.0", "Tần Suất % (Jun Da)": "99.9885459743", "GavinGrover_Once (Chiết tự trực tiếp)": "毛 + 鲁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴毛鲁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鲁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "毛", "Unihan_Simplified (Chữ Giản thể)": "氇", "Unihan_Traditional (Chữ Phồn thể)": "氌", "Pinyin_Xie": "lu", "Âm Hán Việt_Xie": "lỗ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường chỉ dùng trong từ ghép để chỉ loại vải len dệt thủ công của Tây Tạng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('氆', '{"9000": "6239.0", "Chữ Trung Quốc": "氆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 毛 | Số nét | 16 | nét | 氆 | phổ | tượng hình | vải dạ Tây Tạng | 氆 không có dữ liệu cấu trúc từ nguồn. Bộ 毛 (mao) ẩn trong chữ gợi chất liệu sợi lông. Xử lý là độc thể. Wiktionary không có mục cho 氆.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt ''phổ'': chữ tạo muộn, ghép cùng 氌/氇 để ghi âm tên vải dạ Tibet — nhớ qua cặp từ 氆氌 như một từ không thể tách. | Gương Hán-Việt | ''phổ'' ít dùng độc lập; gặp trong 氆氌 (phổ lỗ) | Mở khoá kiến thức | 氆 luôn đi kèm 氌 hoặc 氇 trong từ 氆氌/氆氇 (vải dạ Tây Tạng).", "Tự nguyên_Xie": "Wiktionary không có mục cho 氆. Chữ chỉ dùng trong từ 氆氌 (phổ lỗ) — loại vải dạ thô Tây Tạng. Đây là chữ tạo muộn để phiên âm từ địa phương Tây Tạng. Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: phổ lỗ 氆氌,氆氇)", "Hạng Tần Suất (Jun Da)": "6239.0", "Tần Suất % (Jun Da)": "99.988563545", "GavinGrover_Once (Chiết tự trực tiếp)": "毛 + 普", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴毛普", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "普", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "毛", "Unihan_Simplified (Chữ Giản thể)": "氆", "Unihan_Traditional (Chữ Phồn thể)": "氆", "Pinyin_Xie": "pǔ", "Âm Hán Việt_Xie": "phổ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng trong từ ghép để chỉ một loại vải nỉ dệt bằng len. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('烀', '{"9000": "6240.0", "Chữ Trung Quốc": "烀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 9 | nét | 火 | hoả | biểu nghĩa | lửa | 乎 | hồ | biểu âm | 烀 = 火 (Hoả, biểu nghĩa: lửa/nhiệt) + 乎 (Hồ, biểu âm); chữ hình thanh. Chỉ phương pháp nấu ít nước/hơi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt ''hô'': lửa (火) nhỏ kêu ''hô hô'' — nấu liu riu để thịt chín mềm từ từ mà không khô. | Gương Hán-Việt | ''hô'' ít dùng độc lập trong tiếng Việt; tương đương ''hầm/rim'' trong ẩm thực | Mở khoá kiến thức | Biết 烀 giúp đọc thực đơn ẩm thực Trung Quốc: 烀肉 (thịt hầm hơi), 烀饼 (bánh hấp).", "Tự nguyên_Xie": "Theo Wiktionary, 烀 là chữ hình thanh: 火 (hoả, lửa) biểu nghĩa phương pháp dùng nhiệt, 乎 biểu âm. Nghĩa là nấu bằng hơi nước ít lửa (simmer/steam), đặc trưng trong ẩm thực Đông Bắc Trung Quốc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "luộc (ít nước)", "Hạng Tần Suất (Jun Da)": "6240.0", "Tần Suất % (Jun Da)": "99.9885811157", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 乎", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火乎", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乎", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "烀", "Unihan_Traditional (Chữ Phồn thể)": "烀", "Pinyin_Xie": "hū", "Âm Hán Việt_Xie": "hô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ thực phẩm để biểu thị cách nấu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镔', '{"9000": "6241.0", "Chữ Trung Quốc": "镔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 15 | nét | 镔 | tân | tượng hình | thép tốt đã luyện | 镔 không có dữ liệu cấu trúc rõ ràng. Bộ 金 (kim, kim loại) gợi chất liệu sắt/thép cao cấp. Xử lý là độc thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt ''tân'': bộ Kim (金) gợi kim loại quý — thép tân là thép đã qua luyện, sáng như tuyết (雪花鑌鐵 — thép hoa tuyết). | Gương Hán-Việt | ''tân'' trong ''tân thiết'' (thép tinh luyện, văn cổ) | Mở khoá kiến thức | Biết 镔 giúp đọc văn học kiếm hiệp: 镔铁 (thép tinh luyện), 雪花镔铁 (thép hoa tuyết — loại thép huyền thoại).", "Tự nguyên_Xie": "Wiktionary (dạng 鑌) không cung cấp phân tích hình chữ chi tiết. Chữ có nghĩa là thép rèn cao cấp (wrought iron/high-quality iron), gặp trong cụm 鑌鐵 (tân thiết — thép tinh luyện). Đây là chất liệu được trân trọng trong văn học và vũ khí học cổ Trung Hoa. Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thép già, thép đã luyện", "Hạng Tần Suất (Jun Da)": "6241.0", "Tần Suất % (Jun Da)": "99.9885986864", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 宾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅宾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镔", "Unihan_Traditional (Chữ Phồn thể)": "鑌", "Pinyin_Xie": "bīn", "Âm Hán Việt_Xie": "tấn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm định ngữ đứng trước danh từ để chỉ các loại vũ khí sắc bén. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('珉', '{"9000": "6242.0", "Chữ Trung Quốc": "珉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 9 | nét | 珉 | dân | tượng hình | đá giống ngọc | 珉 không có dữ liệu cấu trúc rõ ràng. Bộ 王/玉 (ngọc) ẩn trong chữ gợi đá giống ngọc. Xử lý là độc thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt ''dân'': bộ Ngọc (玉) — đá dân (珉) trông giống ngọc quý nhưng không phải ngọc thật, như người thường trông giống người tài. | Gương Hán-Việt | ''dân'' trong nghĩa đá giống ngọc (văn cổ) | Mở khoá kiến thức | 珉 chủ yếu gặp trong văn học cổ và kim thạch học (nghiên cứu đá quý).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không cung cấp phân tích hình chữ chi tiết cho 珉. Chữ có nghĩa là đá giống ngọc nhưng không phải ngọc thật (jade-like stone). Thường dùng để phân biệt với ngọc thật trong văn học cổ, ví dụ hình ảnh người thường (dân) và người quý tộc. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(một thứ đá đẹp như ngọc)", "Hạng Tần Suất (Jun Da)": "6242.0", "Tần Suất % (Jun Da)": "99.9886162571", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 民", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王民", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "民", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "珉", "Unihan_Traditional (Chữ Phồn thể)": "珉", "Pinyin_Xie": "mín", "Âm Hán Việt_Xie": "mân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn cổ hoặc dùng trong tên người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鞬', '{"9000": "6243.0", "Chữ Trung Quốc": "鞬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 革 | Số nét | 17 | nét | 革 | cách | biểu nghĩa | da thuộc | 建 | kiến | biểu âm | 鞬 = 革 (Cách, biểu nghĩa: da thuộc) + 建 (Kiến, biểu âm); chữ hình thanh. Chỉ túi da đựng cung tên trên lưng ngựa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt ''kiên'': da (革) làm túi vững (建) — túi da kị binh đựng cung tên, vững chắc trên lưng ngựa. | Gương Hán-Việt | ''kiên'' trong túi kiên (đựng cung tên, văn cổ) | Mở khoá kiến thức | 鞬 chủ yếu gặp trong văn học lịch sử và thư tịch cổ về binh khí.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 鞬 là chữ hình thanh: 革 (cách, da thuộc) biểu nghĩa vật dụng bằng da, 建 biểu âm. Nghĩa là túi da đựng cung tên khi cưỡi ngựa (quiver on horseback), hoặc kho dự trữ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "túi đựng cung tên", "Hạng Tần Suất (Jun Da)": "6243.0", "Tần Suất % (Jun Da)": "99.9886338277", "GavinGrover_Once (Chiết tự trực tiếp)": "革 + 建", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰革建", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "建", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "革", "Unihan_Simplified (Chữ Giản thể)": "鞬", "Unihan_Traditional (Chữ Phồn thể)": "鞬", "Pinyin_Xie": "jiān", "Âm Hán Việt_Xie": "kiện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ vật dụng đựng vũ khí treo trên mình ngựa thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('囝', '{"9000": "6244.0", "Chữ Trung Quốc": "囝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 囗 | Số nét | 6 | nét | 囗 | vi | biểu nghĩa | vây quanh, bao bọc | 子 | tử | biểu nghĩa | đứa trẻ, con | 囝 = 囗 (Vi, bao bọc) + 子 (Tử, đứa trẻ); chữ hội ý. Đứa trẻ (子) được bao bọc trong vòng tay (囗) — hình ảnh đứa con nhỏ được ôm ấp. So sánh với 囡 (chữ tương tự gốc Mân Việt).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không rõ âm chuẩn — hội ý: khung ô vuông (囗) ôm lấy đứa trẻ (子) — đứa con được bao bọc trong vòng tay cha mẹ. | Gương Hán-Việt | ''kiến'' ít dùng trong tiếng Việt; từ phương ngữ Mân Nam | Mở khoá kiến thức | 囝 chủ yếu dùng trong thơ Đường (bài 囝 của Cố Huống) và phương ngữ Phúc Kiến/Đài Loan.", "Tự nguyên_Xie": "Theo Wiktionary, 囝 là chữ hội ý: 囗 (vi, bao bọc) kết hợp 子 (tử, đứa trẻ). Đứa con nằm trong vòng bọc — hình ảnh em bé. So sánh với 囡 có cùng cấu trúc tương tự. Chữ này đặc biệt dùng trong phương ngữ Mân Nam (Phúc Kiến) để chỉ đứa con trai. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đứa con", "Hạng Tần Suất (Jun Da)": "6244.0", "Tần Suất % (Jun Da)": "99.9887211644", "GavinGrover_Once (Chiết tự trực tiếp)": "囗 + 子", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Bao quanh toàn bộ)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴囗子", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "子", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "囗", "Unihan_Simplified (Chữ Giản thể)": "囝", "Unihan_Traditional (Chữ Phồn thể)": "囝", "Pinyin_Xie": "jiǎn", "Âm Hán Việt_Xie": "kiển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng trong khẩu ngữ hoặc phương ngôn miền Nam Trung Quốc để gọi con cái. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('犴', '{"9000": "6245.0", "Chữ Trung Quốc": "犴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 6 | nét | 犬 | khuyển | biểu nghĩa | chó | 干 | can | biểu âm | 犴 = 犬 (Khuyển, biểu nghĩa: chó) + 干 (Can, biểu âm); chữ hình thanh. Chỉ loài chó rừng hoặc nhà tù nhỏ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt ''hãn'': chó (犬) trông coi (干) — chó canh gác nhà giam, nên 犴 có nghĩa cả ''chó rừng'' lẫn ''ngục tù''. | Gương Hán-Việt | ''hãn'' trong ''hãn ngục'' (nhà giam nhỏ, văn cổ) | Mở khoá kiến thức | Biết 犴 giúp đọc văn học lịch sử: 犴狴 (ngục tù), 犴獄 (nhà giam).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 犴 là chữ hình thanh: 犬 (khuyển, chó) biểu nghĩa loài thú hoang, 干 biểu âm. Nghĩa kép: (1) con chó rừng (wild dog), (2) nhà giam nhỏ — vì ngày xưa dùng chó canh ngục. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhà ngục, nhà lao; con chó rừng", "Hạng Tần Suất (Jun Da)": "6245.0", "Tần Suất % (Jun Da)": "99.9887382183", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 干", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭干", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "干", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "犴", "Unihan_Traditional (Chữ Phồn thể)": "犴", "Pinyin_Xie": "àn", "Âm Hán Việt_Xie": "ngạn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn học cổ để chỉ ngục thất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镠', '{"9000": "6246.0", "Chữ Trung Quốc": "镠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 16 | nét | 金 | kim | biểu nghĩa | vàng, kim loại | 翏 | biểu âm | 镠 = 金 (Kim, biểu nghĩa: vàng) + 翏 (biểu âm, không có Hán-Việt phổ biến); chữ hình thanh. Chỉ vàng tinh khiết cao cấp.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt ''lưu'': vàng (金) chảy như dòng nước (翏 gợi âm liú) — vàng ròng tinh khiết chảy qua khuôn như dòng ánh sáng. | Gương Hán-Việt | ''lưu'' trong ''vàng lưu'' (vàng ròng, văn cổ) | Mở khoá kiến thức | 镠 chủ yếu gặp trong văn học cổ điển và kim thạch học: 黄镠 (vàng ròng).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | Theo Wiktionary (dạng 鏐), 镠 là chữ hình thanh: 金 (kim, vàng) biểu nghĩa chất liệu quý, 翏 biểu âm. Nghĩa là vàng ròng độ tinh khiết cao. Kim văn có nhiều ảnh từ hanziyuan.net. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vàng tốt", "Hạng Tần Suất (Jun Da)": "6246.0", "Tần Suất % (Jun Da)": "99.9887552723", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 翏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅翏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "翏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镠", "Unihan_Traditional (Chữ Phồn thể)": "鏐", "Pinyin_Xie": "liú", "Âm Hán Việt_Xie": "lưu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn cổ để chỉ loại vàng có độ tinh khiết cao. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('觇', '{"9000": "6247.0", "Chữ Trung Quốc": "觇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 見 | Số nét | 9 | nét | 觇 | chiêm | tượng hình | dòm ngó, dò xét | 觇 không có dữ liệu cấu trúc rõ ràng. Bộ 見 (kiến, nhìn) gợi hành động quan sát. Xử lý là độc thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt ''chiêm'': bộ Kiến (見) — nhìn lén như trinh sát — 觇 là nhìn mà không để người kia biết. | Gương Hán-Việt | ''chiêm'' trong ''chiêm ngưỡng'', ''chiêm bái'' (dùng nghĩa ngưỡng nhìn) | Mở khoá kiến thức | Biết 觇 giúp đọc văn cổ: 覘兵 (do thám quân), 覘國 (dò tình hình quốc gia), 窺覘 (dòm ngó).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Wiktionary (dạng 覘) không cung cấp phân tích hình chữ chi tiết. Chữ có nghĩa ''dòm ngó, do thám, quan sát lén''. Hình dáng gợi kết hợp của bộ thị/nhìn với yếu tố khác. Đại triện và tiểu triện từ wikimedia. Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dò xét, dòm", "Hạng Tần Suất (Jun Da)": "6247.0", "Tần Suất % (Jun Da)": "99.9887723262", "GavinGrover_Once (Chiết tự trực tiếp)": "占 + 见", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰占见", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "占", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "见", "Unihan_Simplified (Chữ Giản thể)": "觇", "Unihan_Traditional (Chữ Phồn thể)": "覘", "Pinyin_Xie": "chān", "Âm Hán Việt_Xie": "chiêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ trong văn viết cổ hoặc kết hợp thành từ ghép như chiêm vọng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钆', '{"9000": "6248.0", "Chữ Trung Quốc": "钆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 6 | nét | 钆 | ga | tượng hình | nguyên tố gadolinium | 钆 là chữ tạo hiện đại để phiên dịch tên nguyên tố gadolinium (Gd) sang Hán tự. Bộ 金 (kim) biểu nghĩa kim loại; phần còn lại biểu âm. Wiktionary không có mục. Chữ tạo muộn, không có hình chữ cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt ''ga'': bộ Kim (金) + phần biểu âm — nguyên tố gadolinium, ký hiệu Gd, số 64, dùng trong MRI và vật liệu từ tính. | Gương Hán-Việt | ''ga'' trong ''gadolinium'' — thuật ngữ khoa học hiện đại | Mở khoá kiến thức | 钆 chủ yếu dùng trong hóa học và bảng tuần hoàn tiếng Trung.", "Tự nguyên_Xie": "钆 là chữ Hán hiện đại được tạo ra để dịch tên nguyên tố gadolinium (Gd, số nguyên tử 64) — nguyên tố đất hiếm được phát hiện năm 1880. Chữ tạo muộn, không có giáp cốt văn hay kim văn. Chưa có nguồn học thuật xác nhận cấu trúc. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố gađolini, Gd", "Hạng Tần Suất (Jun Da)": "6248.0", "Tần Suất % (Jun Da)": "99.9887893801", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 乚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅乚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钆", "Unihan_Traditional (Chữ Phồn thể)": "釓", "Pinyin_Xie": "gá", "Âm Hán Việt_Xie": "ca", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ nguyên tố hóa học, thường xuất hiện trong các tài liệu khoa học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蚺', '{"9000": "6249.0", "Chữ Trung Quốc": "蚺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 11 | nét | 蚺 | nhiễm | tượng hình | con trăn | 蚺 không có dữ liệu cấu trúc rõ ràng. Bộ 虫 (trùng, côn trùng/loài bò sát) là dấu hiệu loài bò sát. Xử lý là độc thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt ''nhiễm'': bộ Trùng (虫) gợi bò sát — con trăn (蚺) dài thõng như sợi chỉ nhuộm (nhiễm) qua bụi rậm. | Gương Hán-Việt | ''nhiễm'' ít dùng độc lập; gặp trong 蚺蛇 (trăn con) | Mở khoá kiến thức | Biết 蚺 giúp đọc văn bản sinh học: 蚺蛇 (trăn), 水蚺 (trăn nước/anaconda).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không cung cấp phân tích hình chữ chi tiết cho 蚺, chỉ ghi nhận âm cổ. Chữ chỉ loài trăn lớn (boa constrictor). Tiểu triện từ hanziyuan.net có ảnh. Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con trăn", "Hạng Tần Suất (Jun Da)": "6249.0", "Tần Suất % (Jun Da)": "99.988806434", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 冉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫冉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蚺", "Unihan_Traditional (Chữ Phồn thể)": "蚺", "Pinyin_Xie": "rán", "Âm Hán Việt_Xie": "nhiêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ động vật, thường kết hợp thành từ ghép như nhiễm xà. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4":