INSERT INTO characters (char, data) VALUES ('蝓', '{"9000": "6250.0", "Chữ Trung Quốc": "蝓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 15 | nét | 蝓 | du | tượng hình | ốc sên | 蝓 không có dữ liệu cấu trúc rõ ràng. Bộ 虫 (trùng) gợi loài thân mềm/bò sát nhỏ. Xử lý là độc thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt ''du'': bộ Trùng (虫) — con sên (蛞蝓) bò chậm như du hành, để lại vết nhớt trên đường đi. | Gương Hán-Việt | ''du'' ít dùng độc lập; gặp trong 蛞蝓 (khoát du — con sên) | Mở khoá kiến thức | Biết 蝓 giúp nhận ra từ 蛞蝓 (con sên không vỏ) trong văn bản sinh học hoặc ẩm thực.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không cung cấp phân tích hình chữ cho 蝓. Chữ chủ yếu dùng trong từ 蛞蝓 (khoát du — con sên không vỏ). Tiểu triện từ wikimedia. Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: khoát du 蛞蝓)", "Hạng Tần Suất (Jun Da)": "6250.0", "Tần Suất % (Jun Da)": "99.9888234879", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 俞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫俞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "俞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蝓", "Unihan_Traditional (Chữ Phồn thể)": "蝓", "Pinyin_Xie": "yú", "Âm Hán Việt_Xie": "du", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường không đứng một mình mà kết hợp thành từ ghép như khoát du để chỉ con sên. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('趑', '{"9000": "6251.0", "Chữ Trung Quốc": "趑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 走 | Số nét | 13 | nét | 趑 | tư | tượng hình | bước chân do dự, không tiến được | 趑 không có dữ liệu cấu trúc rõ ràng. Bộ 走 (tẩu, đi) gợi hành động di chuyển khó khăn. Xử lý là độc thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt ''tư'': bộ Tẩu (走) — chân muốn đi (走) mà cứ dừng lại tư lự — 趑趄 là bước chân lưỡng lự không tiến. | Gương Hán-Việt | ''tư'' trong nghĩa do dự (văn cổ) | Mở khoá kiến thức | 趑 chỉ dùng trong từ 趑趄 (lưỡng lự, do dự không bước được).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Wiktionary không cung cấp phân tích hình chữ chi tiết cho 趑. Chữ chỉ dùng trong từ 趑趄 (tư thư) — nghĩa là đi chân không bước được, do dự không tiến, hoặc đi lảo đảo khó khăn. Đại triện và tiểu triện từ wikimedia. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: tư thư 趑趄,趦趄)", "Hạng Tần Suất (Jun Da)": "6251.0", "Tần Suất % (Jun Da)": "99.9888405418", "GavinGrover_Once (Chiết tự trực tiếp)": "走 + 次", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴走次", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "次", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "走", "Unihan_Simplified (Chữ Giản thể)": "趑", "Unihan_Traditional (Chữ Phồn thể)": "趑", "Pinyin_Xie": "zī", "Âm Hán Việt_Xie": "tư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường kết hợp với chữ thư thành từ láy tư thư để làm vị ngữ hoặc trạng ngữ trong câu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('貔', '{"9000": "6252.0", "Chữ Trung Quốc": "貔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 豸 | Số nét | 17 | nét | 豸 | trãi | biểu nghĩa | thú hoang | 𣬉 | biểu âm | 貔 = 豸 (Trãi, biểu nghĩa: thú hoang) + 𣬉 (biểu âm, không có Hán-Việt phổ biến); chữ hình thanh. Chỉ loài thú huyền thoại giống hổ-báo, thường đi cặp 貔貅.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt ''tỳ'': bộ Trãi (豸) của thú hung dữ — 貔貅 (tỳ hưu) là linh thú ăn vào mà không nhả ra, biểu tượng giữ tài lộc. | Gương Hán-Việt | ''tỳ'' trong ''tỳ hưu'' (貔貅 — linh vật phong thủy) | Mở khoá kiến thức | Biết 貔 mở khoá: 貔貅 (tỳ hưu — linh vật hút tài lộc), 貔虎 (mãnh thú).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 貔 là chữ hình thanh: 豸 (trãi, thú hoang) biểu nghĩa, 𣬉 biểu âm. Chỉ loài thú huyền thoại (fox, leopard, panther) trong văn học cổ. Từ nổi tiếng nhất: 貔貅 (tỳ hưu) — con vật linh thiêng trong văn hóa Trung Hoa, biểu trưng tài lộc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con tì (loài thú nói trong sách cổ)", "Hạng Tần Suất (Jun Da)": "6252.0", "Tần Suất % (Jun Da)": "99.9888575957", "GavinGrover_Once (Chiết tự trực tiếp)": "豸 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰豸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "貔", "Unihan_Traditional (Chữ Phồn thể)": "貔", "Pinyin_Xie": "pí", "Âm Hán Việt_Xie": "tì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ, thường kết hợp thành từ ghép tì hưu để chỉ con vật cát tường. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('躞', '{"9000": "6253.0", "Chữ Trung Quốc": "躞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 24 | nét | 躞 | tiết | tượng hình | đi lững thững | 躞 không có dữ liệu cấu trúc rõ ràng. Bộ 足 (túc, chân) gợi hành động đi lại. Xử lý là độc thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt ''tiết'': bộ Túc (足) gặp chữ phức tạp — bước đi (蹀躞) nhỏ nhắn uyển chuyển như điệu múa, tiết tấu đẹp. | Gương Hán-Việt | ''tiết'' trong nghĩa bước chân uyển chuyển (văn cổ) | Mở khoá kiến thức | Biết 躞 giúp đọc văn học cổ điển: 蹀躞 (đi uyển chuyển), 金題玉躞 (trang trí sang trọng).", "Tự nguyên_Xie": "Wiktionary không cung cấp phân tích hình chữ chi tiết cho 躞. Chữ có hai nghĩa: (1) đi với dáng điệu uyển chuyển/nhỏ nhắn (mincing gait), (2) vật trang trí trên dây buộc cuộn sách. Gặp trong từ 蹀躞 (đi uyển chuyển) và 金題玉躞 (trang trí vàng ngọc). Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái trục xe; đi lững thững", "Hạng Tần Suất (Jun Da)": "6253.0", "Tần Suất % (Jun Da)": "99.9888746496", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 燮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊燮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "燮", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "躞", "Unihan_Traditional (Chữ Phồn thể)": "躞", "Pinyin_Xie": "xiè", "Âm Hán Việt_Xie": "tiệp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ trong từ láy điệp âm tiết điệp để tả dáng đi lững thững. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('氽', '{"9000": "6254.0", "Chữ Trung Quốc": "氽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 6 | nét | 氽 | thốn | tượng hình | nổi trên mặt nước | 氽 không có dữ liệu cấu trúc từ nguồn, Wiktionary cũng không có mục. Hình chữ trông như người (人) trên nước (水) — gợi hình ảnh nổi trên mặt nước. Xử lý là độc thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt ''thốn'': người (人) ngồi trên nước (水) — hình ảnh tự nhiên của việc nổi bềnh hoặc thả mình vào chảo dầu. | Gương Hán-Việt | ''thốn'' ít dùng; tương đương ''nổi'', ''chiên'' trong ẩm thực | Mở khoá kiến thức | Biết 氽 giúp đọc công thức nấu ăn: 氽水 (chần sơ qua nước sôi), 油氽 (chiên ngập dầu).", "Tự nguyên_Xie": "Wiktionary không có mục cho 氽. Chữ có thể là hội ý hình tượng: người (人) trên nước (水), chỉ hành động nổi trên mặt nước hoặc chiên ngập dầu (deep fry). Đây là chữ tạo muộn/dân gian, không có hình cổ. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trôi; trôi nổi; bập bềnh; lênh đênh; rán; chiên", "Hạng Tần Suất (Jun Da)": "6254.0", "Tần Suất % (Jun Da)": "99.9888917035", "GavinGrover_Once (Chiết tự trực tiếp)": "人 + 水", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱人水", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "水", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "人", "Unihan_Simplified (Chữ Giản thể)": "氽", "Unihan_Traditional (Chữ Phồn thể)": "氽", "Pinyin_Xie": "tǔn", "Âm Hán Việt_Xie": "thộn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ chỉ hành động nổi trên nước hoặc phương pháp nấu ăn chiên ngập dầu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('绂', '{"9000": "6255.0", "Chữ Trung Quốc": "绂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 8 | nét | 绂 | phất | tượng hình | dây thao buộc ấn tín | 绂 không có dữ liệu cấu trúc rõ ràng. Bộ 糸 (mịch, sợi/lụa) gợi vật dụng bằng chỉ sợi. Xử lý là độc thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt ''phất'': bộ Mịch (糸) gợi sợi lụa — dải lụa buộc ấn quan (印紱) — quan nào cũng cần dây thao này để treo ấn tín. | Gương Hán-Việt | ''phất'' trong ''ấn phất'' (dây buộc ấn tín, văn cổ) | Mở khoá kiến thức | Biết 绂 giúp đọc văn học lịch sử: 印紱 (ấn tín và dây thao), 朱紱 (dây thao đỏ của quan cao cấp).", "Tự nguyên_Xie": "Wiktionary (dạng 紱) không cung cấp phân tích hình chữ chi tiết. Chữ có nghĩa là dải lụa/dây thao buộc ấn tín quan lại (silk ribbon for official seal). Cũng là dạng khác của 韍 (tế phục). Chữ gắn với văn hóa quan lại phong kiến Trung Hoa. Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dây thao đeo ấn", "Hạng Tần Suất (Jun Da)": "6255.0", "Tần Suất % (Jun Da)": "99.9889087574", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 犮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟犮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "犮", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "绂", "Unihan_Traditional (Chữ Phồn thể)": "紱", "Pinyin_Xie": "fú", "Âm Hán Việt_Xie": "phất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ trang phục quan lại thời xưa, thường xuất hiện trong văn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('栲', '{"9000": "6256.0", "Chữ Trung Quốc": "栲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 10 | nét | 栲 | khảo | tượng hình | cây khảo/đước | 栲 không có dữ liệu cấu trúc rõ ràng. Bộ 木 (mộc, cây) gợi loài thực vật. Xử lý là độc thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt ''khảo'': bộ Mộc (木) gợi cây — cây khảo (栲) vỏ dùng thuộc da, từ 栲膠 (keo vỏ cây) còn gặp trong công nghiệp thuộc da. | Gương Hán-Việt | ''khảo'' trong ''cây khảo'', ''khảo giao'' (keo vỏ cây) | Mở khoá kiến thức | Biết 栲 giúp đọc văn bản lâm nghiệp và thủ công truyền thống: 栲膠 (keo vỏ cây), 栲栳 (giỏ tre).", "Tự nguyên_Xie": "Lục thư thông | Wiktionary không cung cấp phân tích hình chữ cho 栲. Chữ chỉ loài cây đước (mangrove) hoặc cây họ sồi Đông Á. Chỉ có ảnh từ lục thư thông (thời Minh muộn). Chưa có nguồn học thuật xác nhận cấu trúc. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây khảo", "Hạng Tần Suất (Jun Da)": "6256.0", "Tần Suất % (Jun Da)": "99.9889258113", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 考", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木考", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "考", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "栲", "Unihan_Traditional (Chữ Phồn thể)": "栲", "Pinyin_Xie": "kǎo", "Âm Hán Việt_Xie": "khảo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ thực vật, thường đứng trước các từ chỉ bộ phận như vỏ cây khảo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鹎', '{"9000": "6257.0", "Chữ Trung Quốc": "鹎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 13 | nét | 鹎 | bề | tượng hình | chim bulbul | 鹎 không có dữ liệu cấu trúc rõ ràng. Bộ 鳥 (điểu, chim) gợi loài chim. Xử lý là độc thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt ''bề'': bộ Điểu (鳥) — chim bulbul bề ngoài nhỏ bé nhưng tiếng hót trong trẻo, nổi tiếng ở Nam Á. | Gương Hán-Việt | ''bề'' ít dùng trong tiếng Việt; tương đương ''chim tu ti'' | Mở khoá kiến thức | 鹎 chủ yếu dùng trong điểu học: 白头鹎 (chim đầu trắng), 红耳鹎 (chim tai đỏ).", "Tự nguyên_Xie": "Wiktionary (dạng 鵯) không cung cấp phân tích hình chữ chi tiết. Chữ chỉ loài chim bulbul — loài chim nhỏ có tiếng hót hay, phổ biến ở châu Á nhiệt đới. Chữ tạo muộn để ghi tên loài chim. Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chim tu ti (mieroscelis amaurotis)", "Hạng Tần Suất (Jun Da)": "6257.0", "Tần Suất % (Jun Da)": "99.9889428653", "GavinGrover_Once (Chiết tự trực tiếp)": "卑 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰卑鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鹎", "Unihan_Traditional (Chữ Phồn thể)": "鵯", "Pinyin_Xie": "bēi", "Âm Hán Việt_Xie": "bi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ loài chim, thường kết hợp thành từ ghép chỉ phân loại chim. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('襻', '{"9000": "6258.0", "Chữ Trung Quốc": "襻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 24 | nét | 衣 | y | biểu nghĩa | quần áo | 攀 | phan | biểu âm | 襻 = 衣 (Y, biểu nghĩa: quần áo) + 攀 (Phan, biểu âm); chữ hình thanh. Chỉ vòng khuyết (button loop) trên quần áo để cài cúc hoặc dây buộc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt ''phan'': áo (衣) có dải leo bám (攀) — vòng khuyết áo dài leo qua cúc để giữ nếp, như dây leo bám vào cành. | Gương Hán-Việt | ''phan'' ít dùng trong tiếng Việt; tương đương ''khuyết áo'' | Mở khoá kiến thức | Biết 襻 giúp đọc văn học cổ điển và thuật ngữ may mặc truyền thống: 纽襻 (khuyết cúc), 扣襻 (vòng khuyết).", "Tự nguyên_Xie": "Đại triện | Theo Wiktionary, 襻 là chữ hình thanh: 衣 (y, quần áo) biểu nghĩa vật phụ kiện may mặc, 攀 biểu âm. Nghĩa là vòng khuyết cài cúc (button loop) hoặc dải buộc trên quần áo. Là bộ phận may mặc truyền thống Trung Hoa. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái khuyết áo, dải áo", "Hạng Tần Suất (Jun Da)": "6258.0", "Tần Suất % (Jun Da)": "99.9889599192", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 攀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤攀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "攀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "襻", "Unihan_Traditional (Chữ Phồn thể)": "襻", "Pinyin_Xie": "pàn", "Âm Hán Việt_Xie": "phán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ bộ phận của trang phục hoặc đồ vật, làm tân ngữ hoặc chủ ngữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蓚', '{"9000": "6259.0", "Chữ Trung Quốc": "蓚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 蓚 | điêu | tượng hình | cây có acid oxalic | 蓚 không có dữ liệu cấu trúc từ nguồn và Wiktionary không có mục. Bộ 艸 (thảo, cỏ/cây) gợi loài thực vật. Xử lý là độc thể. Chữ tạo muộn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt ''điêu'': bộ Thảo (艸) gợi cây — chứa axit chua (蓚酸 = acid oxalic), như cây rau me chua. | Gương Hán-Việt | ''điêu'' ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | 蓚 chủ yếu gặp trong hóa học thực vật: 蓚酸 (acid oxalic).", "Tự nguyên_Xie": "Wiktionary không có mục cho 蓚. Chữ gặp trong từ 蓚酸 (acid oxalic) hoặc chỉ loại cây có chứa oxalate. Chữ tạo muộn, không có hình cổ. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Côn trùng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "蓚", "Unihan_Traditional (Chữ Phồn thể)": "蓚", "Pinyin_Xie": "tiáo", "Âm Hán Việt_Xie": "điều", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu làm danh từ để chỉ một loài cỏ hoặc loài sâu trong thư tịch cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('祓', '{"9000": "6260.0", "Chữ Trung Quốc": "祓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 9 | nét | 示 | thị | biểu nghĩa | thần linh, tế lễ | 祓 thuộc bộ 示 (thị — thần linh, tế lễ), chỉ nghi thức tẩy uế. Cấu trúc ls-code chưa xác định; dựa bộ thủ 示 suy đây là chữ liên quan đến tế tự, chưa rõ phần biểu âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phất\": bộ 示 (thần linh) gợi hình ảnh thầy tế vẩy nước — 祓 là trừ tà, rẩy sạch điều xui rủi. | Gương Hán-Việt | phất trong \"tế phất\" (nghi lễ thanh tẩy) | Mở khoá kiến thức | Biết 祓 mở khoá từ vựng nghi lễ cổ: 祓除 (phất trừ — loại bỏ tà uế), 祓禊 (phất khể — lễ thanh tẩy mùa xuân).", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | 祓 xuất hiện trong giáp cốt văn và tiểu triện. Wiktionary ghi nhận nghĩa: trừ tà (expel evil spirits), thực hiện lễ trừ uế (exorcism ceremony), thanh tẩy (cleanse/purify). Bộ 示 chỉ thần linh, nghi lễ. Cấu tạo chi tiết chưa được học thuật xác nhận đầy đủ. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trừ khử đi", "Hạng Tần Suất (Jun Da)": "6260.0", "Tần Suất % (Jun Da)": "99.9890110809", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 犮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻犮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "犮", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "祓", "Unihan_Traditional (Chữ Phồn thể)": "祓", "Pinyin_Xie": "fú", "Âm Hán Việt_Xie": "phất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong các nghi lễ cúng bái để tẩy trần hoặc trừ bỏ tai ương. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('郿', '{"9000": "6261.0", "Chữ Trung Quốc": "郿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 11 | nét | 眉 | mi | biểu âm | lông mày — cho âm méi | 阝 | ấp | biểu nghĩa | vùng đất, địa danh | 郿 = 眉 (Mi, biểu âm: cho âm méi) + 阝/邑 (Ấp, biểu nghĩa: vùng đất, địa danh); chữ hình thanh (psc). Dạng kết hợp điển hình của địa danh: bộ 阝 chỉ \"vùng\", 眉 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mi\": bộ 阝 (ấp — vùng đất) + 眉 (lông mày — cho âm) — tên huyện Mi, vùng đất mang tên \"Lông Mày\" ở Thiểm Tây. | Gương Hán-Việt | mi trong \"Mi huyện\" (huyện Mi, Thiểm Tây) | Mở khoá kiến thức | Biết 郿 nhận diện địa danh cổ Trung Quốc: 郿坞 (Mi Ô — căn cứ địa Đổng Trác thời Tam Quốc).", "Tự nguyên_Xie": "Tiểu triện | 郿 là chữ hình thanh: 眉 (biểu âm, âm méi) + 邑/阝 (biểu nghĩa, vùng đất). Chỉ địa danh — huyện Mi, nay thuộc tỉnh Thiểm Tây, Trung Quốc. Dạng tiểu triện ghi nhận trong Wiktionary. Không có nghĩa ngoài địa danh. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "huyện Mi (ở tỉnh Thiểm Tây, Trung Quốc)", "Hạng Tần Suất (Jun Da)": "6261.0", "Tần Suất % (Jun Da)": "99.9890617258", "GavinGrover_Once (Chiết tự trực tiếp)": "眉 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰眉阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "眉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "郿", "Unihan_Traditional (Chữ Phồn thể)": "郿", "Pinyin_Xie": "méi", "Âm Hán Việt_Xie": "mi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ riêng chỉ địa danh cổ hoặc tên huyện ở Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('骝', '{"9000": "6262.0", "Chữ Trung Quốc": "骝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 13 | nét | 骝 | lưu | tượng hình | ngựa hồng có bờm đen — loại ngựa quý | 骝 thuộc bộ 馬 (ngựa), tự dạng không rõ ls-code. Chữ chuyên chỉ loại ngựa hồng bờm đen (驊騮). Cấu trúc thành phần chi tiết chưa được xác định; dựa hình dáng suy là hình thanh với bộ 馬 biểu nghĩa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lưu\": bộ 馬 (ngựa) — 骝 là con ngựa \"lưu loát\" sắc hồng bờm đen, loại tuấn mã quý hiếm trong thơ ca cổ. | Gương Hán-Việt | lưu trong \"lưu mã\" (ngựa chạy nhanh) | Mở khoá kiến thức | Biết 骝 nhận diện từ điển/thơ văn cổ: 驊騮 (hoa lưu — danh mã thần thoại Trung Hoa).", "Tự nguyên_Xie": "Tiểu triện | 骝 (giản thể của 騮) thuộc bộ 馬. Wiktionary ghi nhận chỉ dùng trong từ 驊騮 — tên một loại ngựa quý huyền thoại thời cổ Trung Quốc, màu hồng với bờm đen. Tiểu triện ghi nhận. Không có nghĩa độc lập ngoài tổ hợp này. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con ngựa", "Hạng Tần Suất (Jun Da)": "6262.0", "Tần Suất % (Jun Da)": "99.989078263", "GavinGrover_Once (Chiết tự trực tiếp)": "马 + 留", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰马留", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "留", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "马", "Unihan_Simplified (Chữ Giản thể)": "骝", "Unihan_Traditional (Chữ Phồn thể)": "騮", "Pinyin_Xie": "liú", "Âm Hán Việt_Xie": "lưu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ loại ngựa có sắc lông đỏ tía pha đen. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('檫', '{"9000": "6263.0", "Chữ Trung Quốc": "檫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 18 | nét | 檫 | sát | tượng hình | cây gỗ sát (sassafras) — loài cây gỗ quý | 檫 thuộc bộ 木 (cây/gỗ), ls-code không xác định, không có dữ liệu Wiktionary. Dựa bộ thủ 木 suy đây là tên cây. Cấu trúc chi tiết chưa được học thuật xác nhận; chữ tạo muộn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sát\": bộ 木 (cây) — 檫 là cây gỗ \"sát\" — gỗ sassafras dùng \"sát\" bề mặt đồ nội thất cho bóng đẹp. | Gương Hán-Việt | sát trong \"sát mộc\" (loài cây gỗ) | Mở khoá kiến thức | Biết 檫 nhận diện tên cây trong thực vật học Trung Quốc: 檫木 (sát mộc — cây sassafras Trung Hoa).", "Tự nguyên_Xie": "檫 thuộc bộ 木 (gỗ). Không có dữ liệu Wiktionary glyph-origin cho chữ này. Chỉ dữ liệu nghĩa: cây gỗ sát (sassafras chinensis), loài cây gỗ quý dùng trong đóng đồ nội thất. Chưa có nguồn học thuật xác nhận cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây gỗ sát", "Hạng Tần Suất (Jun Da)": "6263.0", "Tần Suất % (Jun Da)": "99.9890948001", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 察", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木察", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "察", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "檫", "Unihan_Traditional (Chữ Phồn thể)": "檫", "Pinyin_Xie": "chá", "Âm Hán Việt_Xie": "sát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ một loài cây thân gỗ thuộc họ Long não. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('砟', '{"9000": "6264.0", "Chữ Trung Quốc": "砟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 10 | nét | 砟 | trá | tượng hình | sỏi đá vụn, dăm đá | 砟 thuộc bộ 石 (đá), ls-code không xác định. Wiktionary chỉ ghi {{Han etym}} không có chi tiết. Dựa bộ 石 suy đây là danh từ chỉ loại đá/sỏi. Chữ tạo muộn, chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trá\": bộ 石 (đá) — 砟 là những viên đá \"vụn trá\" — dăm sỏi trên đường ray xe lửa. | Gương Hán-Việt | trá trong \"trá thạch\" (đá vụn) | Mở khoá kiến thức | Biết 砟 nhận diện từ kỹ thuật đường sắt: 道砟 (đạo trá — đá dăm ballast trên đường ray).", "Tự nguyên_Xie": "砟 thuộc bộ 石 (đá). Wiktionary không cung cấp glyphOrigin chi tiết. Nghĩa: sỏi, dăm đá, sạn đường. Chưa có nguồn học thuật xác nhận cấu tạo cụ thể. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sỏi; sạn", "Hạng Tần Suất (Jun Da)": "6264.0", "Tần Suất % (Jun Da)": "99.9891113372", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 乍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石乍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "砟", "Unihan_Traditional (Chữ Phồn thể)": "砟", "Pinyin_Xie": "zhǎ", "Âm Hán Việt_Xie": "tra", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ để chỉ các mảnh đá vụn hoặc than đá nhỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蝰', '{"9000": "6265.0", "Chữ Trung Quốc": "蝰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 15 | nét | 蝰 | khôi | tượng hình | rắn viper — loài rắn độc | 蝰 thuộc bộ 虫 (sâu bọ, côn trùng, loài vật nhỏ), ls-code không xác định. Wiktionary chỉ ghi {{Han etym}} không có chi tiết cấu tạo. Dựa bộ 虫 suy là tên loài bò sát/động vật. Chữ tạo muộn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khôi\": bộ 虫 (loài vật) — 蝰 là con rắn \"khôi\" viper, loài rắn độc nguy hiểm có hình đầu tam giác đặc trưng. | Gương Hán-Việt | khôi trong \"khôi xà\" (rắn viper) | Mở khoá kiến thức | Biết 蝰 nhận diện tên loài rắn độc trong văn bản sinh học: 蝰蛇 (khôi xà — viper), 蝰科 (họ rắn viper).", "Tự nguyên_Xie": "蝰 thuộc bộ 虫. Wiktionary ghi nhận nghĩa: 蝰蛇 (rắn viper — loài rắn độc họ Viperidae). Không có glyphOrigin chi tiết. Cấu tạo chưa được học thuật xác nhận. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rắn vipe (một loại rắn độc)", "Hạng Tần Suất (Jun Da)": "6265.0", "Tần Suất % (Jun Da)": "99.9891278743", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 奎", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫奎", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奎", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蝰", "Unihan_Traditional (Chữ Phồn thể)": "蝰", "Pinyin_Xie": "kuí", "Âm Hán Việt_Xie": "khuê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong các từ ghép để chỉ loài rắn độc thuộc họ rắn lục. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('猱', '{"9000": "6266.0", "Chữ Trung Quốc": "猱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 12 | nét | 猱 | nao | tượng hình | con vượn — loài linh trưởng leo trèo giỏi | 猱 thuộc bộ 犬/犭 (chó/thú), ls-code không xác định. Wiktionary chỉ có thông tin phát âm và định nghĩa, không có glyphOrigin. Dựa bộ 犭 suy là tên loài thú. Chữ tạo muộn, chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nao\": bộ 犭 (thú) — 猱 là con vượn \"nao núng\" trên cành — leo trèo nhanh thoăn thoắt không chịu đứng yên. | Gương Hán-Việt | nao trong \"nao viên\" (vượn leo trèo) | Mở khoá kiến thức | Biết 猱 đọc hiểu thơ văn cổ: 猱升木 (nao thăng mộc — vượn leo cây, ẩn dụ người lanh lợi), 攀猱 (phan nao — leo trèo như vượn).", "Tự nguyên_Xie": "猱 thuộc bộ 犭 (thú vật). Wiktionary ghi: macaque (khỉ đuôi dài), với dị thể 夒, 獿, 獶. Nghĩa trong cổ văn: loài vượn leo trèo cực giỏi, thường dùng ẩn dụ cho sự lanh lẹ. Không có glyphOrigin chi tiết. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một loài vượn", "Hạng Tần Suất (Jun Da)": "6266.0", "Tần Suất % (Jun Da)": "99.9891444115", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 柔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭柔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "柔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "猱", "Unihan_Traditional (Chữ Phồn thể)": "猱", "Pinyin_Xie": "náo", "Âm Hán Việt_Xie": "nhu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ một loài vượn cổ hoặc loài khỉ leo trèo giỏi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缵', '{"9000": "6267.0", "Chữ Trung Quốc": "缵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 19 | nét | 缵 | toản | tượng hình | nối, kế thừa — bộ 糸 chỉ sợi nối tiếp | 缵 thuộc bộ 糸 (sợi tơ), ls-code không xác định. Wiktionary chỉ có thông tin phát âm và định nghĩa. Dựa bộ 糸 suy là chữ liên quan đến nối tiếp. Chỉ thấy tiểu triện, chữ tạo muộn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"toản\": bộ 糸 (sợi tơ) — 缵 là \"toản\" lại các sợi đứt — kế tục, nối nghiệp tổ tiên. | Gương Hán-Việt | toản trong \"toản nghiệp\" (kế thừa sự nghiệp) | Mở khoá kiến thức | Biết 缵 đọc văn ngôn: 缵承 (toản thừa — kế thừa), 缵业 (toản nghiệp — nối tiếp sự nghiệp).", "Tự nguyên_Xie": "Tiểu triện | 缵 thuộc bộ 糸 (sợi tơ). Wiktionary ghi nghĩa: kế thừa (inherit), tiếp nối (succeed/continue/carry on). Tiểu triện ghi nhận. Hình ảnh sợi tơ nối tiếp gợi nghĩa \"kế thừa\". Cấu tạo chi tiết chưa xác nhận. Chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nối, nối theo làm", "Hạng Tần Suất (Jun Da)": "6267.0", "Tần Suất % (Jun Da)": "99.9891609486", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 赞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟赞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "赞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "缵", "Unihan_Traditional (Chữ Phồn thể)": "纘", "Pinyin_Xie": "zuǎn", "Âm Hán Việt_Xie": "toản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong văn viết cổ để chỉ việc kế thừa chí hướng hoặc sự nghiệp của tổ tiên. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('沔', '{"9000": "6268.0", "Chữ Trung Quốc": "沔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 7 | nét | 氵 | thuỷ | biểu nghĩa | nước | 丏 | biểu âm | phần cho âm miǎn | 沔 = 氵 (Thuỷ, biểu nghĩa: nước) + 丏 (biểu âm, cho âm miǎn); chữ hình thanh (psc). Bộ 氵 chỉ đây là chữ liên quan đến nước, sông. Dùng chủ yếu làm địa danh sông Miện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"miền\": bộ 氵 (nước) — 沔 là con sông \"miền\" chảy qua đất Hán Trung — sông Miện, nơi Gia Cát Lượng xuất quân. | Gương Hán-Việt | miền trong \"Miện Dương\" (thành phố Miện Dương, Tứ Xuyên) | Mở khoá kiến thức | Biết 沔 nhận diện địa danh lịch sử: 沔水 (Miện Thuỷ — sông Miện), 沔陽 (Miện Dương — địa danh lịch sử Hồ Bắc).", "Tự nguyên_Xie": "Tiểu triện | Lưu thư thông | 沔 là chữ hình thanh: 氵/水 (nước, biểu nghĩa) + 丏 (biểu âm). Wiktionary xác nhận cấu trúc psc. Nghĩa: tên sông Miện (Mian River) ở Thiểm Tây/Hồ Bắc; cũng có nghĩa cổ là nước tràn đầy. Tiểu triện và Lưu thư thông ghi nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Miện", "Hạng Tần Suất (Jun Da)": "6268.0", "Tần Suất % (Jun Da)": "99.9891774857", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 丏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵丏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "沔", "Unihan_Traditional (Chữ Phồn thể)": "沔", "Pinyin_Xie": "miǎn", "Âm Hán Việt_Xie": "miện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này thường dùng làm danh từ riêng chỉ tên sông hoặc làm tính từ mô tả dòng nước chảy tràn đầy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('彖', '{"9000": "6269.0", "Chữ Trung Quốc": "彖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 彐 | Số nét | 9 | nét | 彖 | đoán | tượng hình | lời giải quẻ Kinh Dịch — hình tượng con lợn rừng chạy | 彖 là chữ độc thể hoặc tượng hình, dưới bộ 彐 (đầu lợn). Không có ls-code. Wiktionary không cung cấp cấu tạo chi tiết. Trong Kinh Dịch, 彖 chỉ lời giải thích toàn quẻ (彖辭).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đoán\": 彖 là lời \"đoán\" giải quẻ trong Kinh Dịch — thầy bói nhìn quẻ rồi phán — 彖辭 là lời phán đoán của Văn Vương. | Gương Hán-Việt | đoán trong \"Đoán từ\" (lời giải quẻ Dịch) | Mở khoá kiến thức | Biết 彖 đọc hiểu Kinh Dịch: 彖辭 (đoán từ — lời giải quẻ), 彖傳 (đoán truyện — thiên giải thích quẻ trong Thập Dực).", "Tự nguyên_Xie": "Kim văn | Bạch thư | Đại triện | Tiểu triện | 彖 xuất hiện trong kim văn, bạch thư, đại triện và tiểu triện. Wiktionary không cung cấp glyphOrigin chi tiết. Nghĩa chính: lời 彖 trong Kinh Dịch — lời giải thích tổng quát ý nghĩa một quẻ. Một số học giả cho rằng chữ mô tả con lợn rừng chạy nhanh (ý nghĩa \"quyết đoán\"). Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1574.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Ký (058) Thỉ (216)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Ký (số 058 - đầu con lợn/ 彑) ở trên chữ Thỉ (số 216 - con lợn/ 豕). Nhìn con lợn cắm đầu chạy ta có thể đoán được hướng đi của nó. Giải thích sự chuyển ý: Đây là chữ Hội ý. Thoán vốn là con lợn cắm đầu chạy. Từ đó dùng để biểu ý cho sự phán xét, phán đoán. Trong Kinh Dịch, thoán dùng để gọi những lời bình luận, diễn giải ý nghĩa của các quẻ (thoán từ).", "Nghĩa Tiếng Việt_Xie": "lời giải thích các quẻ trong kinh Dịch", "Hạng Tần Suất (Jun Da)": "6269.0", "Tần Suất % (Jun Da)": "99.9891940228", "GavinGrover_Once (Chiết tự trực tiếp)": "彑 + 𧰨", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱彑𧰨", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𧰨", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "彑", "Unihan_Simplified (Chữ Giản thể)": "彖", "Unihan_Traditional (Chữ Phồn thể)": "彖", "Pinyin_Xie": "tuàn", "Âm Hán Việt_Xie": "thoán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn học cổ để chỉ lời thoán giải thích ý nghĩa của các quẻ Dịch. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('黻', '{"9000": "6270.0", "Chữ Trung Quốc": "黻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 黹 | Số nét | 17 | nét | 黻 | phất | tượng hình | hoa văn thêu đen xanh trên lễ phục hoàng gia | 黻 thuộc bộ 黹 (thêu thùa), ls-code không xác định. Wiktionary không cung cấp cấu tạo chi tiết. Chỉ có giáp cốt văn và tiểu triện. Chữ chuyên chỉ hoa văn thêu hình \"亞\" ngược màu đen-xanh trên lễ phục vua chúa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phất\": bộ 黹 (thêu) — 黻 là hoa văn \"phất phơ\" đen-xanh trên áo vua — biểu tượng uy quyền thêu tỉ mỉ trên long bào. | Gương Hán-Việt | phất trong \"phất chương\" (hoa văn lễ phục) | Mở khoá kiến thức | Biết 黻 đọc hiểu lễ chế cổ đại: 黼黻 (phủ phất — hoa văn lễ phục), 十二章紋 (thập nhị chương — 12 biểu tượng trên long bào).", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | 黻 thuộc bộ 黹 (thêu thùa). Xuất hiện trong giáp cốt văn và tiểu triện. Wiktionary ghi: hoa văn thêu hình trang trí màu đen và xanh lam trên lễ phục cổ đại, trông giống hai chữ \"弓\" đối nhau. Một trong \"thập nhị chương\" (十二章紋) — 12 biểu tượng trên long bào hoàng đế. Chưa có nguồn học thuật đầy đủ về cấu tạo. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "áo lễ phục", "Hạng Tần Suất (Jun Da)": "6270.0", "Tần Suất % (Jun Da)": "99.98921056", "GavinGrover_Once (Chiết tự trực tiếp)": "黹 + 犮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰黹犮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "犮", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "黹", "Unihan_Simplified (Chữ Giản thể)": "黻", "Unihan_Traditional (Chữ Phồn thể)": "黻", "Pinyin_Xie": "fú", "Âm Hán Việt_Xie": "phất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ loại lễ phục cổ hoặc hoa văn trang trí trên trang phục của vua quan ngày xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('眢', '{"9000": "6271.0", "Chữ Trung Quốc": "眢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 10 | nét | 眢 | oan | tượng hình | con ngươi lõm vào, mắt trũng sâu | 眢 thuộc bộ 目 (mắt), ls-code không xác định. Không có dữ liệu Wiktionary glyphOrigin. Dựa bộ 目 suy liên quan đến mắt. Giáp cốt văn và tiểu triện ghi nhận. Chữ tạo muộn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"oan\": bộ 目 (mắt) — 眢 là đôi mắt \"oan\" trũng sâu — mắt người ốm lõm hẳn vào hốc, buồn bã như mang nỗi oan. | Gương Hán-Việt | oan trong \"oan nhãn\" (mắt trũng) | Mở khoá kiến thức | Biết 眢 đọc thơ văn miêu tả ngoại hình cổ: 眢目 (oan mục — mắt trũng sâu), dùng tả người ốm yếu, già nua.", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | 眢 thuộc bộ 目 (mắt). Xuất hiện trong giáp cốt văn và tiểu triện. Không có Wiktionary glyphOrigin. Nghĩa: con ngươi lõm sâu vào, mắt trũng (mô tả mắt người ốm/già). Chưa có nguồn học thuật xác nhận đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con ngươi lõm vào", "Hạng Tần Suất (Jun Da)": "6271.0", "Tần Suất % (Jun Da)": "99.9892270971", "GavinGrover_Once (Chiết tự trực tiếp)": "夗 + 目", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱夗目", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "眢", "Unihan_Traditional (Chữ Phồn thể)": "眢", "Pinyin_Xie": "yuān", "Âm Hán Việt_Xie": "oan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ bổ nghĩa cho danh từ như mắt hoặc giếng để chỉ trạng thái khô cạn, lõm sâu. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鮠', '{"9000": "6272.0", "Chữ Trung Quốc": "鮠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 17 | nét | 鮠 | ngỗi | tượng hình | cá ngạnh (cá da trơn không vảy) | 鮠 thuộc bộ 魚 (cá), ls-code không xác định. Wiktionary chỉ có thông tin phát âm và định nghĩa, không có glyphOrigin. Dựa bộ 魚 suy là tên loài cá. Chữ tạo muộn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngỗi\": bộ 魚 (cá) — 鮠 là con cá \"ngỗi ngược\" — cá da trơn không vảy bơi ngược dòng như ngỗi nước. | Gương Hán-Việt | ngỗi trong \"ngỗi ngư\" (cá ngạnh) | Mở khoá kiến thức | Biết 鮠 nhận diện tên cá trong văn bản sinh học/ẩm thực: 鮠魚 (ngỗi ngư — cá ngạnh), một loại cá nước ngọt quý ở Trung Quốc.", "Tự nguyên_Xie": "鮠 thuộc bộ 魚 (cá). Wiktionary ghi nhận: bagrid catfish, naked catfish, longtail catfish — các loài cá da trơn không vảy họ cá ngạnh (Bagridae). Không có glyphOrigin chi tiết. Chưa có nguồn học thuật xác nhận cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá ngạnh", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 危", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚危", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "危", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "𬶏", "Unihan_Traditional (Chữ Phồn thể)": "鮠", "Pinyin_Xie": "wéi", "Âm Hán Việt_Xie": "nguy, ngôi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong tên gọi các loài cá nước ngọt thuộc họ cá da trơn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('茛', '{"9000": "6273.0", "Chữ Trung Quốc": "茛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 茛 | cấn | tượng hình | cây mao cấn (buttercup/Ranunculus) | 茛 thuộc bộ 艸/艹 (cỏ, cây cỏ), ls-code không xác định. Wiktionary không cung cấp glyphOrigin chi tiết. Dựa bộ 艹 suy là tên thực vật. Chữ tạo muộn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cấn\": bộ 艹 (cỏ) — 茛 là cây \"cấn\" — mao cấn, hoa vàng nhỏ mọc ven suối, trông đẹp nhưng độc. | Gương Hán-Việt | cấn trong \"mao cấn\" (cây mao cấn, Ranunculus) | Mở khoá kiến thức | Biết 茛 nhận diện tên thực vật: 毛茛 (mao cấn — cây mao cấn/buttercup, họ Ranunculaceae).", "Tự nguyên_Xie": "茛 thuộc bộ 艹 (cỏ). Wiktionary ghi: dùng trong từ 毛茛 (mao cấn — Ranunculus/buttercup); cũng là dị danh của 鉤吻 (cây độc câu vẫn). Không có glyphOrigin chi tiết. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mao cấn (vị thuốc đông y)", "Hạng Tần Suất (Jun Da)": "6273.0", "Tần Suất % (Jun Da)": "99.9893423402", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 艮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹艮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "艮", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "茛", "Unihan_Traditional (Chữ Phồn thể)": "茛", "Pinyin_Xie": "gèn", "Âm Hán Việt_Xie": "cấn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong y học cổ truyền để chỉ một loại thảo dược có độc tính nhẹ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蕈', '{"9000": "6274.0", "Chữ Trung Quốc": "蕈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 15 | nét | 蕈 | tầm | tượng hình | cây nấm, nấm mọc trên cây | 蕈 thuộc bộ 艸/艹 (cỏ, thực vật), ls-code không xác định. Wiktionary chỉ có thông tin phát âm. Dựa bộ 艹 suy là tên thực vật/nấm. Đại triện và tiểu triện ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tầm\": bộ 艹 (thực vật) — 蕈 là nấm \"tầm thường\" mọc trên thân cây mục — cẩn thận vì nhiều loài nấm rất độc. | Gương Hán-Việt | tầm trong \"tầm thực\" (nấm ăn) | Mở khoá kiến thức | Biết 蕈 nhận diện tên nấm trong y học/sinh thái: 靈蕈 (linh tầm — nấm linh chi), 毒蕈 (độc tầm — nấm độc).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 蕈 thuộc bộ 艹. Wiktionary ghi nghĩa: nấm (mushroom), đặc biệt nấm mọc trên gỗ/cây mục. Đại triện và tiểu triện ghi nhận. Không có glyphOrigin chi tiết về cấu tạo. Chưa có nguồn học thuật xác nhận đầy đủ. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây nấm; vi khuẩn", "Hạng Tần Suất (Jun Da)": "6274.0", "Tần Suất % (Jun Da)": "99.9893583605", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "蕈", "Unihan_Traditional (Chữ Phồn thể)": "蕈", "Pinyin_Xie": "xùn", "Âm Hán Việt_Xie": "khuẩn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ các loại nấm mọc trên gỗ mục hoặc mặt đất ẩm ướt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('骀', '{"9000": "6275.0", "Chữ Trung Quốc": "骀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 8 | nét | 骀 | đãi | tượng hình | ngựa hèn, ngựa xấu | 骀 thuộc bộ 馬 (ngựa), ls-code không xác định. Wiktionary không cung cấp glyphOrigin chi tiết. Dựa bộ 馬 suy là tên chỉ loại ngựa. Tiểu triện và Lưu thư thông ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đãi\": bộ 馬 (ngựa) — 骀 là con ngựa \"đãi\" — ngựa cùn, già yếu, bị ruồng bỏ — đối lập với 驊騮 tuấn mã. | Gương Hán-Việt | đãi trong \"đãi mã\" (ngựa hèn) | Mở khoá kiến thức | Biết 骀 đọc văn ngôn: 駑骀 (nô đãi — ngựa cùn hèn), dùng ẩn dụ người kém tài.", "Tự nguyên_Xie": "Tiểu triện | Lưu thư thông | 骀 thuộc bộ 馬. Wiktionary ghi nhận nghĩa: ngựa già nua, gầy yếu, ngựa hèn kém. Tiểu triện và Lưu thư thông ghi nhận. Không có glyphOrigin chi tiết. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngựa hèn, ngựa xấu", "Hạng Tần Suất (Jun Da)": "6275.0", "Tần Suất % (Jun Da)": "99.9893743808", "GavinGrover_Once (Chiết tự trực tiếp)": "马 + 台", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰马台", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "台", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "马", "Unihan_Simplified (Chữ Giản thể)": "骀", "Unihan_Traditional (Chữ Phồn thể)": "駘", "Pinyin_Xie": "dài", "Âm Hán Việt_Xie": "đãi, đài", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này thường làm tính từ bổ nghĩa cho danh từ để chỉ sự chậm chạp hoặc kém cỏi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('樨', '{"9000": "6276.0", "Chữ Trung Quốc": "樨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 16 | nét | 樨 | tê | tượng hình | cây quế mộc tê (Osmanthus) | 樨 thuộc bộ 木 (cây/gỗ), ls-code không xác định. Không có dữ liệu Wiktionary. Dựa bộ 木 suy là tên cây. Chữ tạo muộn, chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tê\": bộ 木 (cây) — 樨 là cây \"tê\" — mộc tê, cây hoa quế vàng thơm ngào ngạt trong thu về. | Gương Hán-Việt | tê trong \"mộc tê\" (cây hoa quế Osmanthus) | Mở khoá kiến thức | Biết 樨 nhận diện tên cây: 木樨 (mộc tê — hoa quế vàng/Osmanthus), 木樨肉 (món ăn trứng hoa quế nổi tiếng).", "Tự nguyên_Xie": "樨 thuộc bộ 木. Không có Wiktionary glyphOrigin. Nghĩa: cây quế hoa vàng (木樨 — Osmanthus fragrans), loài cây hoa thơm nổi tiếng trong văn hóa Trung Hoa. Chưa có nguồn học thuật xác nhận cấu tạo. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây quế", "Hạng Tần Suất (Jun Da)": "6276.0", "Tần Suất % (Jun Da)": "99.9893904012", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 犀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木犀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "犀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "樨", "Unihan_Traditional (Chữ Phồn thể)": "樨", "Pinyin_Xie": "xī", "Âm Hán Việt_Xie": "tê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong các từ ghép chỉ thực vật như mộc tê. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('昝', '{"9000": "6277.0", "Chữ Trung Quốc": "昝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 9 | nét | 昝 | tảm | tượng hình | họ Tảm (họ người Trung Quốc hiếm) | 昝 thuộc bộ 日 (mặt trời, ngày tháng), ls-code không xác định. Wiktionary ghi đây là dạng rút gọn/hư hoá từ 朁. Không có cấu trúc chi tiết. Chữ hư hoá.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tảm\": bộ 日 (mặt trời) phía trên — 昝 là họ \"Tảm\" — một trong những họ hiếm nhất Trung Quốc, như ánh sáng mặt trời hiếm gặp giữa đám đông. | Gương Hán-Việt | tảm trong \"họ Tảm\" (姓昝) | Mở khoá kiến thức | Biết 昝 nhận diện họ người hiếm trong văn bản hành chính Trung Quốc: 昝氏 (họ Tảm).", "Tự nguyên_Xie": "昝 là dạng rút gọn (corrupted form) của 朁. Wiktionary xác nhận điều này. Chủ yếu dùng như một họ người hiếm ở Trung Quốc. Không có glyphOrigin riêng biệt. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "họ Tảm", "Hạng Tần Suất (Jun Da)": "6277.0", "Tần Suất % (Jun Da)": "99.9894064215", "GavinGrover_Once (Chiết tự trực tiếp)": "处 + 日", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱处日", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "处", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "昝", "Unihan_Traditional (Chữ Phồn thể)": "昝", "Pinyin_Xie": "zǎn", "Âm Hán Việt_Xie": "tảm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Đại từ | 代词 | Chủ yếu dùng làm danh từ riêng chỉ họ người hoặc làm đại từ nhân xưng trong cổ ngữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Đại từ | 代词 | Thay cho người hoặc vật đã nhắc tới (我, 这, 谁). Dùng đúng ở vị trí của danh từ. Chỉ người thì thêm 们 để thành số nhiều: 我们.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('餂', '{"9000": "6278.0", "Chữ Trung Quốc": "餂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 14 | nét | 餂 | thiêm | tượng hình | liếm, lấy thức ăn bằng miệng | 餂 thuộc bộ 食 (ăn/thức ăn), ls-code không xác định. Wiktionary chỉ ghi {{Han etym}} không có chi tiết. Dựa bộ 食 suy là động từ liên quan đến ăn uống. Chữ tạo muộn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiêm\": bộ 食 (ăn) — 餂 là \"thiêm\" — liếm thức ăn nhẹ nhàng, lấy đi một ít, như người đang lén liếm thìa. | Gương Hán-Việt | thiêm trong \"thiêm thực\" (lấy thức ăn) | Mở khoá kiến thức | Biết 餂 đọc hiểu văn ngôn miêu tả hành động ăn uống.", "Tự nguyên_Xie": "餂 thuộc bộ 食 (ăn uống). Wiktionary không cung cấp glyphOrigin chi tiết. Nghĩa cổ: dùng miệng lấy thức ăn, liếm, hoặc lấy thứ gì đó một cách lén lút. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lấy; dùng", "Hạng Tần Suất (Jun Da)": "6278.0", "Tần Suất % (Jun Da)": "99.9894224419", "GavinGrover_Once (Chiết tự trực tiếp)": "飠 + 舌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰飠舌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "飠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舌", "Unihan_Simplified (Chữ Giản thể)": "餂", "Unihan_Traditional (Chữ Phồn thể)": "餂", "Pinyin_Xie": "tiǎn", "Âm Hán Việt_Xie": "thiểm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ thể hiện hành vi dụ dỗ hoặc lừa gạt để đoạt lấy thứ gì. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镎', '{"9000": "6279.0", "Chữ Trung Quốc": "镎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 15 | nét | 镎 | nã | tượng hình | nguyên tố neptuni (Np, số 93) | 镎 thuộc bộ 金 (kim loại), ls-code không xác định. Không có dữ liệu Wiktionary. Đây là chữ tạo hiện đại để phiên âm tên nguyên tố neptunium (Np). Bộ 金 chỉ kim loại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nã\": bộ 金 (kim loại) — 镎 là nguyên tố kim loại \"nã\" — neptuni, kim loại phóng xạ đặt tên theo hành tinh Neptune. | Gương Hán-Việt | nã trong \"nã nguyên tố\" (nguyên tố neptuni) | Mở khoá kiến thức | Biết 镎 nhận diện trong bảng tuần hoàn tiếng Trung: 镎 (nã) = Np = Neptunium, số nguyên tử 93.", "Tự nguyên_Xie": "镎 là chữ tạo hiện đại thuộc bộ 金 (kim loại). Không có Wiktionary glyphOrigin. Đây là chữ phiên tự (transliteration character) cho nguyên tố neptunium (Np, số nguyên tử 93) — kim loại phóng xạ. Không có nguồn học thuật về cấu tạo cổ điển. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố neptuni, Np", "Hạng Tần Suất (Jun Da)": "6279.0", "Tần Suất % (Jun Da)": "99.9894384622", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 拿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅拿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "拿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镎", "Unihan_Traditional (Chữ Phồn thể)": "鎿", "Pinyin_Xie": "ná", "Âm Hán Việt_Xie": "nã", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chuyên ngành hóa học để chỉ nguyên tố kim loại phóng xạ Neptuni. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('酡', '{"9000": "6280.0", "Chữ Trung Quốc": "酡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 12 | nét | 酉 | dậu | biểu nghĩa | rượu, hũ rượu | 它 | tha | biểu âm | phần cho âm tuó | 酡 = 酉 (Dậu, biểu nghĩa: rượu/hũ rượu) + 它 (Tha, biểu âm); chữ hình thanh (psc). Bộ 酉 chỉ liên quan đến rượu — mặt đỏ sau khi uống rượu. Wiktionary xác nhận cấu trúc psc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đà\": bộ 酉 (rượu) + 它 (tha — cho âm) — uống rượu mặt đỏ \"đà\" — 酡 là gương mặt ửng đỏ sau chén rượu. | Gương Hán-Việt | đà trong \"đà nhan\" (mặt đỏ vì rượu) | Mở khoá kiến thức | Biết 酡 đọc miêu tả ngoại hình trong thơ văn: 酡顏 (đà nhan — mặt đỏ vì rượu), 酡紅 (đà hồng — hồng như mặt người say).", "Tự nguyên_Xie": "酡 là chữ hình thanh: 酉 (hũ rượu — biểu nghĩa) + 它 (biểu âm). Wiktionary xác nhận cấu trúc. Nghĩa: mặt đỏ hồng do uống rượu (flushed from drinking). Tiểu triện ghi nhận. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "say rượu đỏ mặt", "Hạng Tần Suất (Jun Da)": "6280.0", "Tần Suất % (Jun Da)": "99.9894544825", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 它", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉它", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "它", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "酡", "Unihan_Traditional (Chữ Phồn thể)": "酡", "Pinyin_Xie": "tuó", "Âm Hán Việt_Xie": "đà", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ miêu tả sắc mặt đỏ hồng do uống rượu hoặc do ngượng ngùng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鳜', '{"9000": "6281.0", "Chữ Trung Quốc": "鳜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 20 | nét | 魚 | ngư | biểu nghĩa | cá | 厥 | quyết | biểu âm | phần cho âm guì | 鳜 = 魚 (Ngư, biểu nghĩa: cá) + 厥 (Quyết, biểu âm); chữ hình thanh (psc). Bộ 魚 chỉ đây là tên cá, 厥 cho âm. Tiểu triện ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quyết\": bộ 魚 (cá) + 厥 (quyết — cho âm) — cá quyết — 鳜魚 là cá mandarin nổi danh trong thơ \"斜風細雨不須歸\" — cá câu đẹp nhất mùa thu. | Gương Hán-Việt | quyết trong \"quyết ngư\" (cá mandarin) | Mở khoá kiến thức | Biết 鳜 đọc hiểu thơ cổ: 鳜魚 (quyết ngư — cá mandarin/cá quế), nổi tiếng trong bài từ \"漁歌子\" của Trương Chí Hòa.", "Tự nguyên_Xie": "Tiểu triện | 鳜 là chữ hình thanh: 魚 (cá — biểu nghĩa) + 厥 (biểu âm). Wiktionary xác nhận cấu trúc psc. Nghĩa: cá mandarin (Siniperca), một loại cá nước ngọt quý, thịt ngon — loài cá nổi tiếng trong thơ \"Thu Phố Ca\" của Trương Chí Hòa. Tiểu triện ghi nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con cá rô", "Hạng Tần Suất (Jun Da)": "6281.0", "Tần Suất % (Jun Da)": "99.9894705029", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 厥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼厥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "厥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鳜", "Unihan_Traditional (Chữ Phồn thể)": "鱖", "Pinyin_Xie": "guì", "Âm Hán Việt_Xie": "quyết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ một loài cá nước ngọt có thịt thơm ngon. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('觋', '{"9000": "6282.0", "Chữ Trung Quốc": "觋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 見 | Số nét | 11 | nét | 巫 | vu | biểu nghĩa | thầy cúng, pháp sư | 見 | kiến | biểu nghĩa | nhìn thấy | 觋 = 巫 (Vu, biểu nghĩa: thầy cúng) + 見 (Kiến, biểu nghĩa: nhìn thấy); chữ hội ý (ic). Thầy cúng nam (觋) là người \"nhìn thấy\" (thần linh, ma quỷ). Phân biệt với 巫 chỉ thầy cúng nữ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hích\": 巫 (thầy vu) + 見 (nhìn thấy) — thầy cúng nam \"hích\" mắt nhìn thấy được thần linh — 觋 là pháp sư nam. | Gương Hán-Việt | hích trong \"vu hích\" (thầy cúng nam) | Mở khoá kiến thức | Biết 觋 đọc văn ngôn về tôn giáo cổ: 巫觋 (vu hích — thầy cúng chung, nam và nữ), 觋者 (hích giả — thầy pháp nam).", "Tự nguyên_Xie": "Tiểu triện | Lưu thư thông | 觋 là chữ hội ý (ic): 巫 (thầy cúng — biểu nghĩa) + 見 (nhìn thấy — biểu nghĩa). Wiktionary xác nhận cấu trúc ic. Nghĩa: thầy cúng nam (male shaman/sorcerer), người có khả năng giao tiếp với thần linh. Tiểu triện và Lưu thư thông ghi nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thầy cúng", "Hạng Tần Suất (Jun Da)": "6282.0", "Tần Suất % (Jun Da)": "99.9894865232", "GavinGrover_Once (Chiết tự trực tiếp)": "巫 + 见", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰巫见", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "见", "Unihan_Simplified (Chữ Giản thể)": "觋", "Unihan_Traditional (Chữ Phồn thể)": "覡", "Pinyin_Xie": "xí", "Âm Hán Việt_Xie": "hích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ người đàn ông làm nghề cúng bái, bói toán thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('礅', '{"9000": "6283.0", "Chữ Trung Quốc": "礅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 17 | nét | 礅 | đôn | tượng hình | tảng đá lớn dày, bệ đá | 礅 thuộc bộ 石 (đá), ls-code không xác định. Không có dữ liệu Wiktionary. Dựa bộ 石 suy là vật thể bằng đá lớn. Chữ tạo muộn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đôn\": bộ 石 (đá) — 礅 là tảng đá \"đôn\" — chắc nịch, to đùng như cái đôn đá ngồi trước cổng nhà cổ. | Gương Hán-Việt | đôn trong \"thạch đôn\" (bệ đá, ghế đá) | Mở khoá kiến thức | Biết 礅 nhận diện đồ nội thất/kiến trúc cổ: 石礅 (thạch đôn — bệ đá), 門礅 (môn đôn — đá kê cột cổng).", "Tự nguyên_Xie": "礅 thuộc bộ 石. Không có Wiktionary glyphOrigin. Nghĩa: tảng đá lớn và dày, bệ đá (stone block/stump). Thường dùng để chỉ bậc đá, bệ đá, hoặc ghế đá. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khối đá lớn và dày", "Hạng Tần Suất (Jun Da)": "6283.0", "Tần Suất % (Jun Da)": "99.9895025436", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 敦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石敦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "礅", "Unihan_Traditional (Chữ Phồn thể)": "礅", "Pinyin_Xie": "dūn", "Âm Hán Việt_Xie": "đôn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ khối đá dày dùng làm bệ đỡ hoặc ghế ngồi ngoài trời. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('垆', '{"9000": "6284.0", "Chữ Trung Quốc": "垆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 8 | nét | 垆 | lò | tượng hình | đất thó đen; bệ đặt vò rượu | 垆 thuộc bộ 土 (đất), ls-code không xác định. Wiktionary chỉ ghi {{Han etym}} và định nghĩa. Dựa bộ 土 suy là chữ liên quan đến đất hoặc vật bằng đất. Tiểu triện ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lò\": bộ 土 (đất) — 垆 là \"lò\" đất — bệ đất kê vò rượu trong quán, hình ảnh Văn Quân \"đương lò\" bán rượu cùng Tư Mã Tương Như. | Gương Hán-Việt | lò trong \"đương lò\" (bán rượu tại quán) | Mở khoá kiến thức | Biết 垆 đọc hiểu điển cố: 當壚 (đương lò — bán rượu; điển cố Văn Quân — Tư Mã Tương Như), 壚邸 (lò đê — quán rượu).", "Tự nguyên_Xie": "Tiểu triện | 垆 thuộc bộ 土. Wiktionary ghi nhận nhưng không có glyphOrigin chi tiết. Nghĩa: loại đất thó đen; bệ đất/gạch đặt vò rượu trong quán rượu cổ đại; cũng nghĩa là quán rượu (當壚 — tiếp khách tại quán rượu). Tiểu triện ghi nhận. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đất thó đen; bệ đặt vò rượu (trong quán rượu đời xưa); đắp đất đặt vò rượu; quán rượu; cái lò", "Hạng Tần Suất (Jun Da)": "6284.0", "Tần Suất % (Jun Da)": "99.9895185639", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 卢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土卢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "垆", "Unihan_Traditional (Chữ Phồn thể)": "壚", "Pinyin_Xie": "lú", "Âm Hán Việt_Xie": "lư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ loại đất thó màu đen hoặc bệ đất đặt bình rượu trong quán xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('坻', '{"9000": "6285.0", "Chữ Trung Quốc": "坻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 8 | nét | 坻 | chỉ | tượng hình | cồn đất nhỏ giữa lòng sông, bãi bồi | 坻 thuộc bộ 土 (đất), ls-code không xác định. Wiktionary chỉ ghi {{Han etym}}. Dựa bộ 土 suy là địa hình đất nhỏ. Tiểu triện và Lưu thư thông ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chỉ\": bộ 土 (đất) — 坻 là mảnh đất \"chỉ\" nhỏ nổi lên giữa dòng sông — bãi giữa lòng sông, như đảo nhỏ bồi cát. | Gương Hán-Việt | chỉ trong \"sa chỉ\" (bãi cát giữa sông) | Mở khoá kiến thức | Biết 坻 đọc thơ Kinh Thi: 宛在水中坻 (uyển tại thuỷ trung chỉ — như ở cồn giữa nước), câu thơ nổi tiếng trong bài 蒹葭 (Kiêm Già).", "Tự nguyên_Xie": "Tiểu triện | Lưu thư thông | 坻 thuộc bộ 土. Wiktionary không cung cấp glyphOrigin chi tiết. Nghĩa: cồn đất nhỏ giữa lòng sông, bãi bồi, bãi soi — phần đất nổi lên giữa sông nước. Tiểu triện và Lưu thư thông ghi nhận. Chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cồn; bãi bồi; bãi soi; bãi giữa lòng sông", "Hạng Tần Suất (Jun Da)": "6285.0", "Tần Suất % (Jun Da)": "99.9895345842", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 氐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土氐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "氐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "坻", "Unihan_Traditional (Chữ Phồn thể)": "坻", "Pinyin_Xie": "chí", "Âm Hán Việt_Xie": "để, trì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ dải đất nổi lên giữa sông hoặc ven biển. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('荇', '{"9000": "6286.0", "Chữ Trung Quốc": "荇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 艸 | tháu | biểu nghĩa | cỏ, thực vật | 行 | hàng | biểu âm | phần cho âm xìng | 荇 = 艸/艹 (Tháu, biểu nghĩa: cỏ/thực vật) + 行 (Hàng, biểu âm); chữ hình thanh (psc). Bộ 艹 chỉ đây là tên cây thủy sinh. Wiktionary xác nhận cấu trúc psc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hành\": bộ 艹 (cỏ) + 行 (đi — cho âm) — rau hạnh \"hành\" trên mặt nước — 荇菜 nổi tiếng trong Kinh Thi \"參差荇菜，左右流之\". | Gương Hán-Việt | hành trong \"hành thái\" (rau hạnh, Nymphoides) | Mở khoá kiến thức | Biết 荇 đọc Kinh Thi: 荇菜 (hành thái — rau hạnh), trong bài Quan Thư nổi tiếng nhất Kinh Thi.", "Tự nguyên_Xie": "Tiểu triện | Lưu thư thông | 荇 là chữ hình thanh: 艹 (cỏ — biểu nghĩa) + 行 (biểu âm). Wiktionary xác nhận cấu trúc psc. Nghĩa: rau hạnh (Nymphoides peltatum), cây thủy sinh có hoa vàng nhỏ mọc trên mặt nước. Nổi tiếng trong bài thơ đầu Kinh Thi \"關雎\" (Quan Thư). Tiểu triện và Lưu thư thông ghi nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rau hạnh (một thứ rau mọc dưới nước, tên khoa học: nymphoides peltatum)", "Hạng Tần Suất (Jun Da)": "6286.0", "Tần Suất % (Jun Da)": "99.9895506046", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 行", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹行", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "行", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "荇", "Unihan_Traditional (Chữ Phồn thể)": "荇", "Pinyin_Xie": "xìng", "Âm Hán Việt_Xie": "hạnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loài cây thủy sinh có lá nổi trên mặt nước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('扃', '{"9000": "6287.0", "Chữ Trung Quốc": "扃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 戶 | Số nét | 9 | nét | 扃 | quýnh | tượng hình | then cửa, chốt cửa | 扃 thuộc bộ 戶 (cửa), ls-code không xác định. Wiktionary chỉ có thông tin phát âm và định nghĩa cơ bản. Dựa bộ 戶 suy liên quan đến cửa. Đại triện và tiểu triện ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quýnh\": bộ 戶 (cửa) — 扃 là then \"quýnh\" khóa cửa — gài then lại là đóng chặt cửa, không ai vào được. | Gương Hán-Việt | quýnh trong \"quýnh hộ\" (đóng cửa, khóa cửa) | Mở khoá kiến thức | Biết 扃 đọc văn ngôn miêu tả cảnh đóng cửa: 扃鑰 (quýnh thược — then và chìa khóa), 扃戶 (quýnh hộ — đóng cửa).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 扃 thuộc bộ 戶 (cửa). Wiktionary ghi nhận nghĩa: then cửa (doorlatch), chốt (bolt/clasp), cũng là động từ đóng cửa (to close/latch). Đại triện và tiểu triện ghi nhận. Không có glyphOrigin chi tiết. Chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đóng (cửa); then, chốt", "Hạng Tần Suất (Jun Da)": "6287.0", "Tần Suất % (Jun Da)": "99.9895666249", "GavinGrover_Once (Chiết tự trực tiếp)": "户 + 冋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴户冋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "户", "Unihan_Simplified (Chữ Giản thể)": "扃", "Unihan_Traditional (Chữ Phồn thể)": "扃", "Pinyin_Xie": "jiōng", "Âm Hán Việt_Xie": "quynh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ cái then cửa hoặc động từ chỉ hành động cài then, đóng cửa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('磻', '{"9000": "6288.0", "Chữ Trung Quốc": "磻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 17 | nét | 磻 | bàn | tượng hình | địa danh Bàn Khê (nơi Khương Thái Công câu cá) | 磻 thuộc bộ 石 (đá), ls-code không xác định. Wiktionary chỉ có thông tin phát âm (bō/pán). Dựa bộ 石 suy liên quan đến địa hình đá. Tiểu triện và Lưu thư thông ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bàn\": bộ 石 (đá) — 磻 là đá \"bàn\" — 磻溪 là suối Bàn Khê, nơi Khương Tử Nha ngồi câu trên đá chờ minh quân. | Gương Hán-Việt | bàn trong \"Bàn Khê\" (điển cố câu cá chờ thời) | Mở khoá kiến thức | Biết 磻 đọc hiểu điển cố: 磻溪 (Bàn Khê — nơi Khương Tử Nha câu cá, biểu tượng ẩn cư chờ thời được dùng).", "Tự nguyên_Xie": "Tiểu triện | Lưu thư thông | 磻 thuộc bộ 石. Wiktionary ghi nhận nhưng không có glyphOrigin. Nghĩa chính: dùng trong địa danh 磻溪 (Bàn Khê) — con suối nơi Khương Thái Công (Khương Tử Nha) câu cá chờ thời trước khi được Chu Văn Vương trọng dụng. Tiểu triện và Lưu thư thông ghi nhận. Chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên đất)", "Hạng Tần Suất (Jun Da)": "6288.0", "Tần Suất % (Jun Da)": "99.9895826453", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 番", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石番", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "番", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "磻", "Unihan_Traditional (Chữ Phồn thể)": "磻", "Pinyin_Xie": "pán", "Âm Hán Việt_Xie": "bàn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ riêng trong địa danh cổ như sông Bàn Khê. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('郗', '{"9000": "6289.0", "Chữ Trung Quốc": "郗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 9 | nét | 希 | hy | biểu âm | phần cho âm chī/xī | 邑 | ấp | biểu nghĩa | vùng đất, địa danh | 郗 = 希 (Hy, biểu âm) + 邑/阝 (Ấp, biểu nghĩa: vùng đất); chữ hình thanh (psc). Dạng kết hợp điển hình địa danh: bộ 阝 chỉ vùng đất, 希 cho âm. Tiểu triện và Lưu thư thông ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hí\": 阝 (ấp — vùng đất) + 希 (hy — cho âm) — ấp đất \"Hí\" thời nhà Chu; họ Hí nổi tiếng với thư pháp gia Vương Hi Chi. | Gương Hán-Việt | hí trong \"họ Hí\" (姓郗) | Mở khoá kiến thức | Biết 郗 nhận diện họ người trong lịch sử: 郗鑒 (Hí Giám — quan thần thời Đông Tấn), 郗超 (Hí Siêu — con trai Hí Giám).", "Tự nguyên_Xie": "Tiểu triện | Lưu thư thông | 郗 là chữ hình thanh: 希 (biểu âm) + 邑/阝 (vùng đất — biểu nghĩa). Wiktionary xác nhận cấu trúc psc. Nghĩa: tên ấp thời nhà Chu (nay thuộc Thẩm Dương, Hà Nam); cũng là họ người (họ Si/Hí). Tiểu triện và Lưu thư thông ghi nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tên một ấp đời nhà Chu (nay thuộc thành phố Thấm Dương, tỉnh Hà Nam của Trung Quốc); họ Si", "Hạng Tần Suất (Jun Da)": "6289.0", "Tần Suất % (Jun Da)": "99.9895986656", "GavinGrover_Once (Chiết tự trực tiếp)": "希 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰希阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "希", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "郗", "Unihan_Traditional (Chữ Phồn thể)": "郗", "Pinyin_Xie": "xī", "Âm Hán Việt_Xie": "hy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ riêng chỉ họ người hoặc địa danh thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('阇', '{"9000": "6290.0", "Chữ Trung Quốc": "阇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 11 | nét | 門 | môn | biểu nghĩa | cổng, cửa | 者 | giả | biểu âm | phần cho âm dū | 阇 = 門 (Môn, biểu nghĩa: cổng/cửa) + 者 (Giả, biểu âm); chữ hình thanh (psc). Bộ 門 chỉ liên quan đến cổng tường thành. Wiktionary xác nhận cấu trúc psc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đồ\": bộ 門 (cổng) + 者 (giả — cho âm) — cổng \"đồ\" — 阇 là cổng tháp trên tường thành; cũng gặp trong thuật ngữ Phật giáo. | Gương Hán-Việt | đồ trong \"nhân đồ\" (cổng tháp tường thành) | Mở khoá kiến thức | Biết 阇 đọc thuật ngữ cổ và Phật giáo: 闉闍 (nhân đồ — cổng tháp), 阇梨 (đồ lê — âm dịch acarya, thầy trong Phật giáo).", "Tự nguyên_Xie": "Tiểu triện | 阇 là chữ hình thanh: 門 (cổng — biểu nghĩa) + 者 (biểu âm). Wiktionary xác nhận cấu trúc psc. Nghĩa: dùng trong 闉闍 (nhân đồ) — cổng tháp trên tường thành cổ đại; cũng phiên âm từ Sanskrit \"stūpa\" (tháp Phật). Tiểu triện ghi nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: nhân đồ 闉闍)", "Hạng Tần Suất (Jun Da)": "6290.0", "Tần Suất % (Jun Da)": "99.9896146859", "GavinGrover_Once (Chiết tự trực tiếp)": "门 + 者", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴门者", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "者", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "门", "Unihan_Simplified (Chữ Giản thể)": "阇", "Unihan_Traditional (Chữ Phồn thể)": "闍", "Pinyin_Xie": "dū", "Âm Hán Việt_Xie": "đồ, xà", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong các từ ghép cổ chỉ kiến trúc thành quách. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('腈', '{"9000": "6291.0", "Chữ Trung Quốc": "腈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 12 | nét | 腈 | tinh | tượng hình | hợp chất nitrile, nhóm -CN trong hóa học hữu cơ | 腈 thuộc bộ 肉/⺼ (thịt), ls-code không xác định. Không có Wiktionary. Đây là chữ tạo hiện đại dùng trong hóa học hữu cơ để chỉ hợp chất nitrile. Chữ tạo muộn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tinh\": bộ ⺼ (cơ thể/hợp chất) — 腈 là hợp chất \"tinh\" — nitrile, nhóm -CN, chất \"tinh\" khiết trong hóa học hữu cơ hiện đại. | Gương Hán-Việt | tinh trong \"tinh hóa chất\" (hợp chất nitrile) | Mở khoá kiến thức | Biết 腈 nhận diện thuật ngữ hóa học: 丙烯腈 (acrylonitrile), 丁腈 (butadiene nitrile — cao su NBR).", "Tự nguyên_Xie": "腈 thuộc bộ ⺼/肉. Không có Wiktionary glyphOrigin. Đây là chữ tạo hiện đại dùng trong hóa học: chỉ hợp chất nitrile (nhóm -CN). Ví dụ nổi tiếng: 丙烯腈 (acrylonitrile), 丁腈橡膠 (cao su nitrile). Không có nguồn học thuật cổ điển. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(hợp chất hữu cơ)", "Hạng Tần Suất (Jun Da)": "6291.0", "Tần Suất % (Jun Da)": "99.9896307063", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 青", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月青", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "青", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "腈", "Unihan_Traditional (Chữ Phồn thể)": "腈", "Pinyin_Xie": "jīng", "Âm Hán Việt_Xie": "thanh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong thuật ngữ hóa học để chỉ nhóm hợp chất nitrin. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铈', '{"9000": "6292.0", "Chữ Trung Quốc": "铈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 10 | nét | 金 | kim | biểu nghĩa | kim loại | 市 | thị | biểu âm | phần cho âm shì | 铈 = 金/钅 (Kim, biểu nghĩa: kim loại) + 市 (Thị, biểu âm); chữ hình thanh (psc). Wiktionary xác nhận cấu trúc psc. Đây là chữ tạo hiện đại để chỉ nguyên tố ceri (Ce).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thị\": bộ 金 (kim loại) + 市 (thị — cho âm) — kim loại \"thị\" — 铈 là ceri, kim loại đất hiếm dùng trong đèn thắp sáng và chất xúc tác. | Gương Hán-Việt | thị trong \"thị nguyên tố\" (nguyên tố ceri) | Mở khoá kiến thức | Biết 铈 nhận diện bảng tuần hoàn tiếng Trung: 铈 (thị) = Ce = Cerium, số nguyên tử 58.", "Tự nguyên_Xie": "铈 là chữ hình thanh hiện đại: 金/钅 (kim loại — biểu nghĩa) + 市 (biểu âm, tr2=shì). Wiktionary xác nhận cấu trúc psc. Chỉ nguyên tố ceri (Ce, số nguyên tử 58) — kim loại đất hiếm. Không có nguồn học thuật cổ điển. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố ceri, Ce", "Hạng Tần Suất (Jun Da)": "6292.0", "Tần Suất % (Jun Da)": "99.9896467266", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 市", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅市", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "市", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铈", "Unihan_Traditional (Chữ Phồn thể)": "鈰", "Pinyin_Xie": "shì", "Âm Hán Việt_Xie": "thị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong hóa học để chỉ nguyên tố kim loại đất hiếm Ceri. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('顟', '{"9000": "6293.0", "Chữ Trung Quốc": "顟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 頁 | Số nét | 20 | nét | 顟 | lão | tượng hình | chữ ít dùng, nghĩa chưa rõ | 顟 là chữ ít tài liệu, cấu tạo chưa được phân tích rõ ràng trong nguồn học thuật. Có thể liên quan bộ 頁 (đầu), nhưng chưa xác định được phương thức tạo chữ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lão\": chữ cổ hiếm gặp, ngoại hình có phần giống 頁 (đầu người) — tạm nhớ như \"đầu lão\" để phân biệt. | Gương Hán-Việt | (hiếm dùng trong tiếng Việt Hán-Việt) | Mở khoá kiến thức | 顟 là chữ cổ hiếm, không mở khoá từ vựng phổ biến nào.", "Tự nguyên_Xie": "Wiktionary chưa có phân tích từ nguyên rõ cho 顟. Chữ này hầu như không xuất hiện trong văn bản hiện đại. Một số tài liệu ghi âm là liáo hoặc piāo. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "顟", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "翏 + 頁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰翏頁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "翏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "頁", "Unihan_Simplified (Chữ Giản thể)": "顟", "Unihan_Traditional (Chữ Phồn thể)": "顟", "Pinyin_Xie": "láo", "Âm Hán Việt_Xie": "lão", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ trong văn ngôn để tả hành động nhìn chăm chú hoặc trợn mắt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('衖', '{"9000": "6294.0", "Chữ Trung Quốc": "衖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 行 | Số nét | 12 | nét | 行 | hành | biểu nghĩa | đi lại, đường sá | 共 | cộng | biểu âm | chung, cùng nhau | 衖 = 行 (Hành, biểu nghĩa: đường đi) + 共 (Cộng, biểu âm); chữ hình thanh — bộ 行 chỉ đường sá, 共 cho âm xiàng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hạng\": Đường (行) mọi người Cùng (共) đi → cái NGÕ (衖) trong làng. | Gương Hán-Việt | hạng ngõ (ngõ nhỏ), lý hạng (làng xóm ngõ ngách) | Mở khoá kiến thức | Biết 衖 mở khoá khái niệm: ngõ hẻm trong văn học Trung Hoa cổ điển.", "Tự nguyên_Xie": "Theo Wiktionary, 衖 là chữ hình thanh: 行 (đường đi, lối đi) biểu nghĩa, 共 biểu âm. Nghĩa là ngõ nhỏ, hẻm trong làng — con đường nhỏ mọi người cùng (共) đi qua. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đường đi trong làng", "Hạng Tần Suất (Jun Da)": "6294.0", "Tần Suất % (Jun Da)": "99.9897423319", "GavinGrover_Once (Chiết tự trực tiếp)": "行 + 共", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴行共", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "共", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "行", "Unihan_Simplified (Chữ Giản thể)": "衖", "Unihan_Traditional (Chữ Phồn thể)": "衖", "Pinyin_Xie": "xiàng", "Âm Hán Việt_Xie": "hạng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ lối đi nhỏ hoặc ngõ hẻm trong làng xóm, đô thị. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('珙', '{"9000": "6295.0", "Chữ Trung Quốc": "珙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 10 | nét | 珙 | củng | tượng hình | loại đá quý; tên địa danh | 珙 là chữ ít dữ liệu cấu tạo rõ ràng. Dựa vào dạng thị giác, có bộ 王/玉 (ngọc) bên trái — có thể là chữ hình thanh với bộ ngọc biểu nghĩa và 共 biểu âm, nhưng chưa xác nhận được từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"củng\": nhớ 珙 như tên huyện Củng ở Tứ Xuyên — vùng đất có loại ngọc đặc biệt. | Gương Hán-Việt | (hiếm dùng trong tiếng Việt Hán-Việt phổ thông) | Mở khoá kiến thức | 珙 chủ yếu dùng trong địa danh 珙縣 (huyện Củng, Tứ Xuyên).", "Tự nguyên_Xie": "Wiktionary chưa có phân tích từ nguyên chi tiết cho 珙. Chữ này chủ yếu dùng làm tên địa danh (huyện Củng, tỉnh Tứ Xuyên) hoặc chỉ một loại đá quý trong văn học cổ. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(một loại ngọc); huyện Củng (ở tỉnh Tứ Xuyên của Trung Quốc)", "Hạng Tần Suất (Jun Da)": "6295.0", "Tần Suất % (Jun Da)": "99.9897578354", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 共", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王共", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "共", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "珙", "Unihan_Traditional (Chữ Phồn thể)": "珙", "Pinyin_Xie": "gǒng", "Âm Hán Việt_Xie": "củng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong tên gọi các loại ngọc cổ hoặc dùng làm địa danh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('襞', '{"9000": "6296.0", "Chữ Trung Quốc": "襞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 19 | nét | 衣 | y | biểu nghĩa | áo, vải, quần áo | 辟 | tích | biểu âm | mở ra, tránh | 襞 = 衣 (Y, biểu nghĩa: áo, vải) + 辟 (Tích, biểu âm); chữ hình thanh — bộ 衣 chỉ liên quan vải áo, 辟 cho âm bì. Theo Kanjigen, cũng có thể hiểu là hội ý: 辟 nghĩa là mở ra, các nếp gấp áo được tạo ra bằng cách kéo căng vải.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bích\": Áo (衣) bị kéo/mở (辟) ra kết hợp thành các NẾP GẤP (襞) xếp nếp. | Gương Hán-Việt | (hiếm trong Hán-Việt thông dụng) | Mở khoá kiến thức | Biết 襞 mở khoá từ vựng ngành may: nếp gấp, nếp ly trên quần áo.", "Tự nguyên_Xie": "Theo Wiktionary, 襞 là chữ hình thanh: 衣 (áo, vải) biểu nghĩa, 辟 biểu âm. Theo Kanjigen còn có cách đọc hội ý: 辟 mang nghĩa mở/kéo căng, nếp gấp trên áo được tạo ra khi kéo căng sợi vải ra. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gấp áo", "Hạng Tần Suất (Jun Da)": "6296.0", "Tần Suất % (Jun Da)": "99.989773339", "GavinGrover_Once (Chiết tự trực tiếp)": "辟 + 衣", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱辟衣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "辟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衣", "Unihan_Simplified (Chữ Giản thể)": "襞", "Unihan_Traditional (Chữ Phồn thể)": "襞", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "bích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Dùng làm danh từ chỉ nếp gấp quần áo hoặc động từ chỉ hành động xếp nếp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('劁', '{"9000": "6297.0", "Chữ Trung Quốc": "劁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 刀 | Số nét | 14 | nét | 焦 | tiêu | biểu âm | khô cháy, thiêu đốt | 刂 | đao | biểu nghĩa | dao (biến thể của 刀) | 劁 = 焦 (Tiêu, biểu âm) + 刂 (Đao, biểu nghĩa: dao); chữ hình thanh — bộ 刂/刀 chỉ dụng cụ cắt, 焦 cho âm qiāo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiêu\": Dao (刂) đốt (焦) → dùng dao để THIẾN (劁) gia súc. | Gương Hán-Việt | (hiếm trong Hán-Việt thông dụng) | Mở khoá kiến thức | Biết 劁 mở khoá từ vựng chăn nuôi truyền thống: thiến, thiến heo.", "Tự nguyên_Xie": "Theo Wiktionary, 劁 là chữ hình thanh: 刀/刂 (dao) biểu nghĩa, 焦 biểu âm. Nghĩa gốc là thiến gia súc bằng dao — phương pháp chăn nuôi truyền thống. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thiến", "Hạng Tần Suất (Jun Da)": "6297.0", "Tần Suất % (Jun Da)": "99.9897888425", "GavinGrover_Once (Chiết tự trực tiếp)": "焦 + 刂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰焦刂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "焦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "刂", "Unihan_Simplified (Chữ Giản thể)": "劁", "Unihan_Traditional (Chữ Phồn thể)": "劁", "Pinyin_Xie": "qiāo", "Âm Hán Việt_Xie": "thiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ gia súc để biểu thị việc thiến hoạn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('隈', '{"9000": "6298.0", "Chữ Trung Quốc": "隈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 11 | nét | 隈 | ổi | tượng hình | khúc cong của sông hoặc núi | 隈 là chữ có cấu tạo chưa được phân tích rõ trong nguồn học thuật. Nhìn hình thức, có thể liên quan bộ 阜 (đất cao, núi) và một thành phần biểu âm, nhưng cấu trúc chính xác chưa xác định.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ổi\": nhớ 隈 như cái VỊ TRÍ ẨN NÁU trong khúc cong của sông núi. | Gương Hán-Việt | (hiếm trong Hán-Việt thông dụng) | Mở khoá kiến thức | Biết 隈 mở khoá từ vựng địa lý cổ điển: khúc cong địa hình.", "Tự nguyên_Xie": "Wiktionary chưa có phân tích từ nguyên rõ cho 隈. Nghĩa là khúc uốn của sông hay núi — nơi địa hình tạo thành góc cong lõm vào. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khúc cong của sông hay núi", "Hạng Tần Suất (Jun Da)": "6298.0", "Tần Suất % (Jun Da)": "99.9898043461", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + 畏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝畏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "畏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "隈", "Unihan_Traditional (Chữ Phồn thể)": "隈", "Pinyin_Xie": "wēi", "Âm Hán Việt_Xie": "ôi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ nơi uốn cong của địa hình hoặc góc khuất trong không gian. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('胬', '{"9000": "6299.0", "Chữ Trung Quốc": "胬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 11 | nét | 奴 | nô | biểu âm | nô lệ, người phục vụ | 肉 | nhục | biểu nghĩa | thịt, mô cơ thể | 胬 = 奴 (Nô, biểu âm) + 肉 (Nhục, biểu nghĩa: thịt, mô); chữ hình thanh — bộ 肉 chỉ mô thịt trên cơ thể, 奴 cho âm nǔ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nỗ\": Thịt (肉) thừa mọc ra như người Nô lệ (奴) — cái MỘNG THỊT (胬) trong mắt. | Gương Hán-Việt | (hiếm trong Hán-Việt thông dụng) | Mở khoá kiến thức | Biết 胬 mở khoá thuật ngữ y học mắt: 胬肉攀睛 (mộng thịt che giác mạc).", "Tự nguyên_Xie": "Theo Wiktionary, 胬 là chữ hình thanh: 肉 (thịt, mô) biểu nghĩa, 奴 biểu âm. Nghĩa chuyên biệt là mộng thịt ở mắt (胬肉) — mô thịt mọc lan lên bề mặt nhãn cầu, một bệnh về mắt. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "màng thịt, mộng thịt (ở mắt)", "Hạng Tần Suất (Jun Da)": "6299.0", "Tần Suất % (Jun Da)": "99.9898198496", "GavinGrover_Once (Chiết tự trực tiếp)": "奴 + 肉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱奴肉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "肉", "Unihan_Simplified (Chữ Giản thể)": "胬", "Unihan_Traditional (Chữ Phồn thể)": "胬", "Pinyin_Xie": "nǔ", "Âm Hán Việt_Xie": "nỗ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong y học cổ truyền để chỉ chứng mộng thịt ở mắt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('纮', '{"9000": "6300.0", "Chữ Trung Quốc": "纮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 7 | nét | 纮 | hoành | tượng hình | dây buộc quai nón, dây tơ | 纮 là chữ có cấu tạo không rõ ràng trong nguồn hiện có. Nhìn hình thức, có thể liên quan bộ 糸 (sợi tơ) và một thành phần biểu âm, nhưng chưa xác nhận được từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoành\": sợi Dây (纮) kéo ngang — dây quai nón NGANG TRỜI, rộng lớn bát ngát. | Gương Hán-Việt | bát hoành (tám phương trời, rộng khắp) | Mở khoá kiến thức | Biết 纮 mở khoá: 八紘一宇 (tám dây nối một mái nhà, khẩu hiệu Nhật Bản thời chiến — tám phương trời một nhà).", "Tự nguyên_Xie": "Wiktionary không có phân tích từ nguyên chi tiết cho 纮. Nghĩa chính là dây buộc quai nón, hoặc theo nghĩa mở rộng là rộng lớn, mênh mông (như dây trải ra khắp nơi). chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tua quai mũ", "Hạng Tần Suất (Jun Da)": "6300.0", "Tần Suất % (Jun Da)": "99.9898353532", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 厷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟厷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "厷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "纮", "Unihan_Traditional (Chữ Phồn thể)": "紘", "Pinyin_Xie": "hóng", "Âm Hán Việt_Xie": "hoành", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ dây quai mũ thời cổ hoặc dây buộc nói chung. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('翙', '{"9000": "6301.0", "Chữ Trung Quốc": "翙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羽 | Số nét | 12 | nét | 翙 | hội | tượng hình | tiếng vỗ cánh chim | 翙 là chữ không có phân tích cấu tạo rõ ràng trong nguồn học thuật. Có thể liên quan bộ 羽 (lông, cánh), nhưng không xác nhận được cấu trúc hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hội\": âm Hội — nghe như tiếng HUỀ HUỀ của cánh chim vỗ khi bay lên. | Gương Hán-Việt | (hiếm trong Hán-Việt thông dụng) | Mở khoá kiến thức | 翙 là chữ cổ mô phỏng âm thanh, chủ yếu dùng trong thơ văn cổ.", "Tự nguyên_Xie": "Wiktionary chưa có phân tích từ nguyên chi tiết cho 翙. Nghĩa là tiếng vỗ cánh chim, tiếng phập phồng của đôi cánh khi bay — dùng trong văn học cổ điển mô tả cảnh chim bay. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ghềnh, vênh, vểnh", "Hạng Tần Suất (Jun Da)": "6301.0", "Tần Suất % (Jun Da)": "99.9898508567", "GavinGrover_Once (Chiết tự trực tiếp)": "岁 + 羽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰岁羽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "岁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羽", "Unihan_Simplified (Chữ Giản thể)": "翙", "Unihan_Traditional (Chữ Phồn thể)": "翽", "Pinyin_Xie": "huì", "Âm Hán Việt_Xie": "hối", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Tính từ | 形容词 | Thường dùng làm từ tượng thanh mô tả âm thanh vỗ cánh hoặc tính từ tả vẻ bay lượn. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('茀', '{"9000": "6302.0", "Chữ Trung Quốc": "茀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 8 | nét | 茀 | phất | tượng hình | cỏ mọc um tùm; che phủ; phúc lành | 茀 là chữ có bộ 艸/草 (cỏ) trên đầu, nhưng cấu tạo phần còn lại không rõ ràng từ nguồn Wiktionary. Nhiều khả năng là hình thanh với bộ 艸 biểu nghĩa, nhưng chưa xác nhận được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phất\": Cỏ (艸) mọc PHẤT PHỚI um tùm che lấp cả lối đi — rồi mở rộng sang che chắn và PHÚ PHẬT (phúc lành). | Gương Hán-Việt | phất phới (cỏ mọc tươi tốt) | Mở khoá kiến thức | Biết 茀 mở khoá nghĩa cổ: đường bị cỏ lấp, vật che phủ, phúc lành trong văn học.", "Tự nguyên_Xie": "Wiktionary không có phân tích từ nguyên rõ ràng cho 茀. Chữ có bộ 艸 (cỏ), nghĩa chính là cỏ mọc um tùm, đường bị cỏ lấp; nghĩa phái sinh là che phủ, mái che; và nghĩa văn học là phúc lành, may mắn. chưa có nguồn học thuật xác nhận cấu trúc đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỏ tốt um; che, mái che, mui xe; phúc, sự may mắn", "Hạng Tần Suất (Jun Da)": "6302.0", "Tần Suất % (Jun Da)": "99.9898663603", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 弗", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹弗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "弗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "茀", "Unihan_Traditional (Chữ Phồn thể)": "茀", "Pinyin_Xie": "fú", "Âm Hán Việt_Xie": "phất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Dùng làm tính từ tả cỏ mọc um tùm hoặc danh từ chỉ cái mui che xe thời cổ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('荜', '{"9000": "6303.0", "Chữ Trung Quốc": "荜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 荜 | tất | tượng hình | cây tiêu dài; hàng rào tre | 荜 là chữ có bộ 艸 (cỏ, thực vật) trên đầu, nhưng cấu tạo phần còn lại không rõ ràng trong nguồn học thuật. Nhiều khả năng là hình thanh với bộ 艸 biểu nghĩa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tất\": bộ Cỏ (艸) + — nhớ 荜茇 là cây TIÊU DÀI, vị thuốc Đông y quen thuộc. | Gương Hán-Việt | (hiếm trong Hán-Việt thông dụng) | Mở khoá kiến thức | Biết 荜 mở khoá: 荜茇 (tiêu dài, vị thuốc), 荜路蓝缕 (nghèo khổ gian khó — thành ngữ).", "Tự nguyên_Xie": "Wiktionary ghi 荜 là dạng khác của 篳 (hàng rào tre, nứa) hoặc chỉ loại cây tiêu dài (荜茇, piper longum). Không có phân tích từ nguyên chi tiết. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây tiêu dài", "Hạng Tần Suất (Jun Da)": "6303.0", "Tần Suất % (Jun Da)": "99.9898818638", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 毕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹毕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "毕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "荜", "Unihan_Traditional (Chữ Phồn thể)": "蓽", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "tất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong tên gọi các loại cây thảo mộc hoặc hàng rào thưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('溱', '{"9000": "6304.0", "Chữ Trung Quốc": "溱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 13 | nét | 水 | thủy | biểu nghĩa | nước | 秦 | tần | biểu âm | triều Tần; họ Tần | 溱 = 水 (Thủy, biểu nghĩa: nước) + 秦 (Tần, biểu âm); chữ hình thanh — bộ 水 chỉ sông nước, 秦 cho âm qín.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trăn\": Nước (水) chảy vùng Tần (秦) — sông TRĂN (溱) trong Kinh Thi. | Gương Hán-Việt | (hiếm trong Hán-Việt thông dụng) | Mở khoá kiến thức | Biết 溱 mở khoá: 溱洧 (tên hai con sông trong Kinh Thi, biểu tượng tình yêu thời cổ đại).", "Tự nguyên_Xie": "Theo Wiktionary, 溱 là chữ hình thanh: 水 (nước) biểu nghĩa, 秦 biểu âm. Nguyên nghĩa là tên một con sông ở tỉnh Hà Nam, Trung Quốc — dòng sông Trăn được nhắc đến trong Kinh Thi. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Trăn", "Hạng Tần Suất (Jun Da)": "6304.0", "Tần Suất % (Jun Da)": "99.9898973674", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 秦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵秦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "秦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "溱", "Unihan_Traditional (Chữ Phồn thể)": "溱", "Pinyin_Xie": "qín", "Âm Hán Việt_Xie": "trăn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ riêng chỉ tên sông hoặc tính từ chỉ sự đông đúc, nhiều nước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('酤', '{"9000": "6305.0", "Chữ Trung Quốc": "酤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 12 | nét | 酉 | dậu | biểu nghĩa | rượu, bình rượu | 古 | cổ | biểu âm | xưa, cổ đại | 酤 = 酉 (Dậu, biểu nghĩa: rượu, bình rượu) + 古 (Cổ, biểu âm); chữ hình thanh — bộ 酉 chỉ rượu, 古 cho âm gū.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cổ\": Rượu (酉) bán kiểu Cổ (古) xưa — BUÔN RƯỢU (酤) ngoài chợ làng. | Gương Hán-Việt | (hiếm trong Hán-Việt thông dụng) | Mở khoá kiến thức | Biết 酤 mở khoá: 沽酒 / 酤酒 (mua rượu, bán rượu — từ văn học cổ điển).", "Tự nguyên_Xie": "Theo Wiktionary, 酤 là chữ hình thanh: 酉 (rượu) biểu nghĩa, 古 biểu âm. Nghĩa gốc là mua bán rượu, đặc biệt là rượu mua về hoặc rượu để qua một đêm. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bán rượu; rượu mua; rượu để cách đêm", "Hạng Tần Suất (Jun Da)": "6305.0", "Tần Suất % (Jun Da)": "99.989912871", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 古", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉古", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "古", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "酤", "Unihan_Traditional (Chữ Phồn thể)": "酤", "Pinyin_Xie": "gū", "Âm Hán Việt_Xie": "cô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Dùng làm động từ chỉ việc mua bán rượu hoặc danh từ chỉ loại rượu cất nhanh. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鱇', '{"9000": "6306.0", "Chữ Trung Quốc": "鱇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 22 | nét | 鱇 | khang | tượng hình | cá cóc, cá câu (anglerfish); bộ 魚 liên quan cá | 鱇 là chữ không có phân tích cấu tạo rõ ràng trong nguồn học thuật. Có bộ 魚 (cá) là thành phần gợi nghĩa, nhưng cấu trúc đầy đủ chưa xác định được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khang\": nhớ 鱇 = CÁ (魚) tên khang — cá cóc, loài cá săn mồi bằng mồi giả. | Gương Hán-Việt | (hiếm trong Hán-Việt thông dụng) | Mở khoá kiến thức | Biết 鱇 mở khoá: 鮟鱇 (cá cóc — anglerfish, loài cá nổi tiếng có đèn câu mồi).", "Tự nguyên_Xie": "Wiktionary không có phân tích từ nguyên cho 鱇. Chữ liên quan đến cá, cụ thể là cá cóc hay cá câu (anglerfish). chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chim cút", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 康", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚康", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "康", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "𩾌", "Unihan_Traditional (Chữ Phồn thể)": "鱇", "Pinyin_Xie": "kāng", "Âm Hán Việt_Xie": "khang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ ghép để chỉ loài cá an-cơ trong sinh học đại dương. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('圯', '{"9000": "6307.0", "Chữ Trung Quốc": "圯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 6 | nét | 土 | thổ | biểu nghĩa | đất, bùn | 巳 | tị | biểu âm | chi Tị (con rắn), giờ Tị | 圯 = 土 (Thổ, biểu nghĩa: đất) + 巳 (Tị, biểu âm); chữ hình thanh — bộ 土 chỉ công trình bằng đất (cầu đắp bằng đất), 巳 cho âm yí.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đài\": Đất (土) đắp thành cái CẦU (圯) — nhớ điển tích Trương Lương nhận sách trên cầu 圯. | Gương Hán-Việt | (hiếm trong Hán-Việt thông dụng) | Mở khoá kiến thức | Biết 圯 mở khoá: 圯橋 (cầu đất — điển tích Trương Lương học binh thư), 圯上老人 (ông già trên cầu đất).", "Tự nguyên_Xie": "Theo Wiktionary, 圯 là chữ hình thanh: 土 (đất) biểu nghĩa, 巳 biểu âm. Nghĩa là cây cầu nhỏ (đặc biệt là cầu đắp đất). Nổi tiếng qua điển tích Trương Lương nhận binh thư từ người già trên cầu 圯 (Hán thư). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái cầu", "Hạng Tần Suất (Jun Da)": "6307.0", "Tần Suất % (Jun Da)": "99.9900053755", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 巳", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土巳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巳", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "圯", "Unihan_Traditional (Chữ Phồn thể)": "圯", "Pinyin_Xie": "yí", "Âm Hán Việt_Xie": "di", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn ngôn để chỉ cây cầu, xuất hiện trong điển tích lịch sử. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('柽', '{"9000": "6308.0", "Chữ Trung Quốc": "柽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 9 | nét | 木 | mộc | biểu nghĩa | cây cối, gỗ | 聖 | thánh | biểu âm | thánh nhân, linh thiêng | 柽 = 木 (Mộc, biểu nghĩa: cây) + 聖 (Thánh, biểu âm); chữ hình thanh — bộ 木 chỉ thực vật, cây cối, 聖 cho âm chēng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thính\": Cây (木) Thánh (聖) — cây LIỄU ĐỎ (柽) xuất hiện trong Kinh Thi như biểu tượng thiêng liêng. | Gương Hán-Việt | (hiếm trong Hán-Việt thông dụng) | Mở khoá kiến thức | Biết 柽 mở khoá: 柽柳 (cây liễu đỏ, tamarisk), xuất hiện trong Kinh Thi và văn học cổ Trung Quốc.", "Tự nguyên_Xie": "Theo Wiktionary, 柽 là chữ hình thanh: 木 (cây) biểu nghĩa, 聖 biểu âm. Nghĩa là cây liễu đỏ hoặc cây tamarisk — một loài cây thấp mọc ở vùng khô hạn, nổi tiếng trong Kinh Thi. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây sanh (như cây liễu)", "Hạng Tần Suất (Jun Da)": "6308.0", "Tần Suất % (Jun Da)": "99.9900203623", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 圣", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木圣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "圣", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "柽", "Unihan_Traditional (Chữ Phồn thể)": "檉", "Pinyin_Xie": "chēng", "Âm Hán Việt_Xie": "sanh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ một loại cây thân gỗ nhỏ lá kim giống cây liễu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瞀', '{"9000": "6309.0", "Chữ Trung Quốc": "瞀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 14 | nét | 敄 | mậu | biểu âm | cố gắng, nỗ lực (chữ cổ) | 目 | mục | biểu nghĩa | mắt, nhìn | 瞀 = 敄 (Mậu, biểu âm) + 目 (Mục, biểu nghĩa: mắt); chữ hình thanh — bộ 目 chỉ thị giác, mắt nhìn, 敄 cho âm mào.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mậu\": Mắt (目) Mậu (敄) — mắt MỜ (瞀), nhìn không rõ, u mê mờ mịt. | Gương Hán-Việt | (hiếm trong Hán-Việt thông dụng) | Mở khoá kiến thức | Biết 瞀 mở khoá: 瞀亂 (mờ tối hỗn loạn), 昏瞀 (mê man, u mê — văn học cổ).", "Tự nguyên_Xie": "Theo Wiktionary, 瞀 là chữ hình thanh: 目 (mắt) biểu nghĩa, 敄 biểu âm. Nghĩa là nhìn gần không rõ, thị lực kém; mờ mịt, u mê; hoặc nhìn xuống (nhìn lom lom). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lờ mờ, mù mịt", "Hạng Tần Suất (Jun Da)": "6309.0", "Tần Suất % (Jun Da)": "99.990035349", "GavinGrover_Once (Chiết tự trực tiếp)": "敄 + 目", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱敄目", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "瞀", "Unihan_Traditional (Chữ Phồn thể)": "瞀", "Pinyin_Xie": "mào", "Âm Hán Việt_Xie": "mậu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ đứng trước danh từ hoặc làm vị ngữ để miêu tả trạng thái thị lực kém hoặc đầu óc mê muội. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铖', '{"9000": "6310.0", "Chữ Trung Quốc": "铖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 11 | nét | 铖 | thành | tượng hình | chữ dùng làm tên người | 铖 là chữ dùng chủ yếu làm tên người. Nhìn hình thức có thể chứa bộ 金/钅 (kim loại) và thành phần biểu âm, nhưng không có dữ liệu từ nguyên từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thành\": nhớ 铖 như tên người — có bộ Kim (钅) trong tên. | Gương Hán-Việt | (hiếm trong Hán-Việt thông dụng) | Mở khoá kiến thức | 铖 chủ yếu dùng làm tên người, không có từ ghép phổ thông.", "Tự nguyên_Xie": "Wiktionary không có phân tích từ nguyên cho 铖. Chữ này gần như chỉ dùng làm tên người (nhân danh). Có thể liên quan bộ 金/钅 (kim loại). chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Thành (dùng làm tên người)", "Hạng Tần Suất (Jun Da)": "6310.0", "Tần Suất % (Jun Da)": "99.9900503358", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 成", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅成", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "成", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铖", "Unihan_Traditional (Chữ Phồn thể)": "鋮", "Pinyin_Xie": "chéng", "Âm Hán Việt_Xie": "thành", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ riêng trong tên người hoặc chỉ một loại rìu chiến cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('粞', '{"9000": "6311.0", "Chữ Trung Quốc": "粞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 12 | nét | 粞 | tê | tượng hình | hạt gạo tấm, gạo xay vỡ | 粞 là chữ không có phân tích cấu tạo rõ ràng trong nguồn học thuật. Có thể chứa bộ 米 (gạo) và thành phần biểu âm, nhưng chưa xác nhận được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tê\": nhớ 粞 = hạt TẤM (gạo vụn) — gạo (米) xay không đều ra hạt nhỏ vỡ. | Gương Hán-Việt | (hiếm trong Hán-Việt thông dụng) | Mở khoá kiến thức | Biết 粞 mở khoá từ vựng nông nghiệp: hạt tấm, phế phẩm xay gạo.", "Tự nguyên_Xie": "Wiktionary không có phân tích từ nguyên chi tiết cho 粞. Nghĩa là hạt tấm — gạo xay vỡ thành mảnh nhỏ, phế phẩm của xay xát. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hạt tấm gạo", "Hạng Tần Suất (Jun Da)": "6311.0", "Tần Suất % (Jun Da)": "99.9900653226", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 西", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米西", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "西", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "粞", "Unihan_Traditional (Chữ Phồn thể)": "粞", "Pinyin_Xie": "xī", "Âm Hán Việt_Xie": "tê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ phần hạt gạo bị nát vụn ra trong quá trình xay xát. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('撙', '{"9000": "6312.0", "Chữ Trung Quốc": "撙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 15 | nét | 手 | thủ | biểu nghĩa | tay | 尊 | tôn | biểu âm | tôn trọng, bình rượu | 撙 = 手 (Thủ, biểu nghĩa: tay) + 尊 (Tôn, biểu âm); chữ hình thanh — bộ 手 chỉ hành động bằng tay, 尊 cho âm zǔn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tôn\": Tay (手) giữ Tôn (尊) trọng — TIẾT KIỆM (撙), điều tiết từng chút một. | Gương Hán-Việt | tiết tôn (tiết kiệm), tôn tiết | Mở khoá kiến thức | Biết 撙 mở khoá: 撙節 (tiết kiệm, giảm chi phí — từ kinh tế cổ điển).", "Tự nguyên_Xie": "Theo Wiktionary, 撙 là chữ hình thanh: 手 (tay) biểu nghĩa, 尊 biểu âm. Nghĩa là giảm bớt, tiết kiệm; điều chỉnh, tuân thủ — hành động dùng tay để kiểm soát, điều tiết. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chỉnh, sửa", "Hạng Tần Suất (Jun Da)": "6312.0", "Tần Suất % (Jun Da)": "99.9900803093", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 尊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌尊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "撙", "Unihan_Traditional (Chữ Phồn thể)": "撙", "Pinyin_Xie": "zǔn", "Âm Hán Việt_Xie": "tỗn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ kết hợp với các từ khác để chỉ việc tiết giảm chi tiêu hoặc kiềm chế bản thân. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铊', '{"9000": "6313.0", "Chữ Trung Quốc": "铊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 10 | nét | 铊 | tha | tượng hình | nguyên tố tali (Tl), kim loại nặng | 铊 là chữ Hán hiện đại dùng để phiên âm nguyên tố hóa học Thallium (Tl). Có bộ 钅/金 (kim loại) chỉ nghĩa, nhưng cấu tạo đầy đủ không có phân tích từ nguyên cổ học.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tha\": Kim loại (钅) mang tên Tha — TALI (铊), nguyên tố số 81, cực độc. | Gương Hán-Việt | (hiếm trong Hán-Việt thông dụng) | Mở khoá kiến thức | Biết 铊 mở khoá thuật ngữ hóa học: 铊中毒 (ngộ độc tali), tên nguyên tố Tl trong hóa học Trung Quốc.", "Tự nguyên_Xie": "Wiktionary không có phân tích từ nguyên cổ học cho 铊. Đây là chữ dùng để phiên dịch tên nguyên tố Thallium (Tl) sang tiếng Trung — một kim loại nặng độc, phát hiện năm 1861. chưa có nguồn học thuật từ nguyên. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố tali, Tl", "Hạng Tần Suất (Jun Da)": "6313.0", "Tần Suất % (Jun Da)": "99.9900952961", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 它", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅它", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "它", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铊", "Unihan_Traditional (Chữ Phồn thể)": "鉈", "Pinyin_Xie": "tā", "Âm Hán Việt_Xie": "tha", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong hóa học để chỉ nguyên tố kim loại tali hoặc quả cân của cân tiểu ly. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('圹', '{"9000": "6314.0", "Chữ Trung Quốc": "圹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 6 | nét | 土 | thổ | biểu nghĩa | đất, bùn đất | 廣 | quảng | biểu âm | rộng lớn, quảng đại | 圹 = 土 (Thổ, biểu nghĩa: đất) + 廣 (Quảng, biểu âm); chữ hình thanh — bộ 土 chỉ hố đất (huyệt mộ), 廣 cho âm kuàng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khoáng\": Đất (土) rộng (廣) — hố HUYỆT (圹) đào trong đất rộng để chôn người. | Gương Hán-Việt | khoáng dã (đồng hoang rộng lớn), quang khoáng | Mở khoá kiến thức | Biết 圹 mở khoá: 壙穴 (huyệt mộ), 曠野/圹野 (đồng hoang).", "Tự nguyên_Xie": "Theo Wiktionary, 圹 là chữ hình thanh: 土 (đất) biểu nghĩa, 廣 biểu âm. Nghĩa là huyệt mộ — hố đất đào để chôn người; nghĩa mở rộng là đồng hoang, vùng đất trống rộng lớn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái huyệt chôn người chết", "Hạng Tần Suất (Jun Da)": "6314.0", "Tần Suất % (Jun Da)": "99.9901102829", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 广", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土广", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "广", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "圹", "Unihan_Traditional (Chữ Phồn thể)": "壙", "Pinyin_Xie": "kuàng", "Âm Hán Việt_Xie": "khoáng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn cổ để chỉ huyệt mộ chôn cất người chết hoặc bãi đất trống. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('菝', '{"9000": "6315.0", "Chữ Trung Quốc": "菝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 菝 | bạt | tượng hình | cây phục linh; kim cang (smilax china) | 菝 là chữ có bộ 艸 (cỏ, thực vật) trên đầu, nhưng cấu tạo phần còn lại không rõ ràng trong nguồn học thuật. Nhiều khả năng là hình thanh với bộ 艸 biểu nghĩa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bạt\": bộ Cỏ (艸) tên BẠT — 菝葜 là cây KIM CANG leo có gai trong rừng. | Gương Hán-Việt | (hiếm trong Hán-Việt thông dụng) | Mở khoá kiến thức | Biết 菝 mở khoá: 菝葜 (kim cang — smilax china, vị thuốc Đông y trị phong thấp).", "Tự nguyên_Xie": "Wiktionary không có phân tích từ nguyên chi tiết cho 菝. Chữ này chủ yếu xuất hiện trong từ 菝葜 (kim cang, cây smilax china) — một loài thực vật leo có gai, dùng trong Đông y. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(một loại thực vật)", "Hạng Tần Suất (Jun Da)": "6315.0", "Tần Suất % (Jun Da)": "99.9901252696", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 拔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹拔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "拔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "菝", "Unihan_Traditional (Chữ Phồn thể)": "菝", "Pinyin_Xie": "bá", "Âm Hán Việt_Xie": "tế, phất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng làm danh từ trong tên gọi các loại cây như bạt kiều. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('岙', '{"9000": "6316.0", "Chữ Trung Quốc": "岙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 7 | nét | 岙 | áo | tượng hình | thung lũng; tên địa danh vùng ven biển | 岙 là chữ giản thể (hoặc phương ngôn tự) chỉ dùng làm tên địa danh ở vùng Chiết Giang, Phúc Kiến. Không có phân tích cấu tạo từ nguồn học thuật chuẩn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"áo\": chữ địa danh ÁO — vùng đất AO làng (thung lũng nhỏ ven biển Chiết Giang). | Gương Hán-Việt | (hiếm trong Hán-Việt thông dụng) | Mở khoá kiến thức | Biết 岙 mở khoá: tên nhiều địa danh đảo Chiết Giang như 东沙岙, các địa danh kết thúc bằng -岙 ở vùng biển Đông Trung Quốc.", "Tự nguyên_Xie": "Wiktionary không có phân tích từ nguyên cho 岙. Chữ này là chữ phương ngôn (方言字) chủ yếu dùng làm tên đất ở vùng ven biển Chiết Giang và Phúc Kiến (ví dụ: 舟山群島 có nhiều địa danh kết thúc bằng 岙). Nghĩa gốc là thung lũng nhỏ ven biển, vũng nước hay đảo nhỏ. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thung lũng; Áo (thường dùng làm tên đất, ở vùng Chiết Giang, Phúc Kiến, Trung Quốc)", "Hạng Tần Suất (Jun Da)": "6316.0", "Tần Suất % (Jun Da)": "99.9901552432", "GavinGrover_Once (Chiết tự trực tiếp)": "夭 + 山", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱夭山", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "岙", "Unihan_Traditional (Chữ Phồn thể)": "嶴", "Pinyin_Xie": "ào", "Âm Hán Việt_Xie": "áo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ địa hình thung lũng hoặc dùng trong địa danh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('漶', '{"9000": "6317.0", "Chữ Trung Quốc": "漶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 14 | nét | 漶 | hoán | tượng hình | mờ, không rõ ràng (của chữ viết, hình ảnh) | 漶 là chữ có bộ 水/氵 (nước) bên trái, gợi ý liên quan đến ẩm ướt, thấm nước làm mờ. Cấu tạo đầy đủ không rõ ràng trong nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoán\": Nước (氵) thấm vào — chữ viết bị NHÒE (漶) không đọc được. | Gương Hán-Việt | (hiếm trong Hán-Việt thông dụng) | Mở khoá kiến thức | Biết 漶 mở khoá: 漫漶 (mờ nhạt, nhòe không đọc được — nói về văn bản cổ bị hư hại).", "Tự nguyên_Xie": "Wiktionary không có phân tích từ nguyên chi tiết cho 漶. Nghĩa chủ yếu là chữ viết hoặc hình ảnh bị mờ đi, không đọc được — thường do nước thấm, thời gian bào mòn. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "không rõ ràng", "Hạng Tần Suất (Jun Da)": "6317.0", "Tần Suất % (Jun Da)": "99.99017023", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 患", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵患", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "患", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "漶", "Unihan_Traditional (Chữ Phồn thể)": "漶", "Pinyin_Xie": "huàn", "Âm Hán Việt_Xie": "hoán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ thường kết hợp với mạn để chỉ nét chữ hoặc vết tích bị mờ nhòe. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缏', '{"9000": "6318.0", "Chữ Trung Quốc": "缏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 12 | nét | 缏 | biện | tượng hình | dây bện, tết bím | 缏 là chữ có bộ 糸/纟 (sợi tơ, dây) biểu nghĩa. Cấu tạo đầy đủ không rõ ràng trong nguồn học thuật hiện có.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"biện\": Sợi Tơ (纟) BIỆN (bện) lại — dây THẮT BỆN (缏), đường viền tết bím. | Gương Hán-Việt | biện phát (tóc bím, đuôi sam) | Mở khoá kiến thức | Biết 缏 mở khoá: 缏子 (dây bện, bím tóc), các từ liên quan đan bện sợi.", "Tự nguyên_Xie": "Wiktionary không có phân tích từ nguyên chi tiết cho 缏. Nghĩa là tết bện, làm dây bện; hoặc đường viền vải, diềm áo. Liên quan bộ 糸/纟 (sợi tơ). chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dây bện", "Hạng Tần Suất (Jun Da)": "6318.0", "Tần Suất % (Jun Da)": "99.9901852167", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 便", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟便", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "便", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "缏", "Unihan_Traditional (Chữ Phồn thể)": "緶", "Pinyin_Xie": "biàn", "Âm Hán Việt_Xie": "biền", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ dây bện hoặc làm động từ chỉ hành động tết tóc, viền áo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('貊', '{"9000": "6319.0", "Chữ Trung Quốc": "貊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 豸 | Số nét | 13 | nét | 貊 | mạch | tượng hình | tên bộ lạc miền Bắc Trung Quốc cổ đại | 貊 là chữ không có phân tích cấu tạo rõ ràng trong nguồn học thuật. Có thể liên quan bộ 豸 (thú dữ) hoặc một bộ khác, nhưng chưa xác nhận được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mạch\": nhớ 貊 = tên bộ lạc MẠCH — người Đông Bắc Trung Quốc cổ đại, tổ tiên người Triều Tiên. | Gương Hán-Việt | (hiếm trong Hán-Việt thông dụng) | Mở khoá kiến thức | Biết 貊 mở khoá: 濊貊 (người Tầm Mạch — dân tộc cổ vùng Mãn Châu, tổ tiên Cao Câu Ly).", "Tự nguyên_Xie": "Wiktionary ghi 貊 là tên một bộ lạc cổ đại ở đông bắc Trung Quốc, cùng nhóm với người Mạch (貊)/Tầm (尋). Đây là chủng tộc xuất hiện trong sử sách Trung Quốc và Hàn Quốc cổ đại — tổ tiên của người Cao Ly / Triều Tiên. chưa có nguồn học thuật từ nguyên rõ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một bộ lạc ở miền Bắc Trung Quốc", "Hạng Tần Suất (Jun Da)": "6319.0", "Tần Suất % (Jun Da)": "99.9902002035", "GavinGrover_Once (Chiết tự trực tiếp)": "豸 + 百", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰豸百", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "百", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "豸", "Unihan_Simplified (Chữ Giản thể)": "貊", "Unihan_Traditional (Chữ Phồn thể)": "貊", "Pinyin_Xie": "mò", "Âm Hán Việt_Xie": "mạch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ riêng chỉ một bộ tộc hoặc vùng đất phía bắc thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('粫', '{"9000": "6320.0", "Chữ Trung Quốc": "粫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 12 | nét | 粫 | nhĩ | tượng hình | (chữ nghĩa không rõ) | 粫 là chữ rất hiếm gặp, không có dữ liệu từ nguyên trong nguồn học thuật. Có thể liên quan bộ 米 (gạo, ngũ cốc) dựa trên hình thức chữ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhĩ\": nhớ 粫 như chữ hiếm có bộ Gạo (米) — không phổ biến trong tiếng Trung hiện đại. | Gương Hán-Việt | (hiếm trong Hán-Việt thông dụng) | Mở khoá kiến thức | 粫 là chữ cực kỳ hiếm, không mở khoá từ vựng phổ biến nào.", "Tự nguyên_Xie": "Wiktionary không có phân tích cho 粫. Chữ này cực kỳ hiếm, nghĩa không rõ ràng ngay cả trong từ điển Trung Quốc. Có thể liên quan gạo (bộ 米). chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Tiểu", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 而", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米而", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "而", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "粫", "Unihan_Traditional (Chữ Phồn thể)": "粫", "Pinyin_Xie": "ér", "Âm Hán Việt_Xie": "nhĩ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này chủ yếu dùng làm tính từ để miêu tả tính chất nhỏ bé của sự vật. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('徂', '{"9000": "6321.0", "Chữ Trung Quốc": "徂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 彳 | Số nét | 8 | nét | 徂 | tò | tượng hình | đi, tiến đến; chết (cổ văn) | 徂 là chữ không có phân tích cấu tạo rõ ràng trong nguồn học thuật. Có thể liên quan bộ 彳 (bước đi) dựa trên hình thức chữ, gợi ý hành động đi lại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tò\": bộ Bước đi (彳) — đi tới, TỚI NƠI (徂), và trong nghĩa cổ: đi hẳn, qua đời. | Gương Hán-Việt | (hiếm trong Hán-Việt thông dụng) | Mở khoá kiến thức | Biết 徂 mở khoá: 徂歲 (năm qua đi), 徂落 (rụng, tàn — văn học cổ), các thi từ Đường Tống.", "Tự nguyên_Xie": "Wiktionary không có phân tích từ nguyên chi tiết cho 徂. Nghĩa chính là đi, tiến về phía trước; nghĩa cổ còn chỉ cái chết, qua đời. Dùng trong văn học cổ điển Trung Quốc. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đi, đến, kịp; chết, mất", "Hạng Tần Suất (Jun Da)": "6321.0", "Tần Suất % (Jun Da)": "99.990230177", "GavinGrover_Once (Chiết tự trực tiếp)": "彳 + 且", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰彳且", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "且", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "彳", "Unihan_Simplified (Chữ Giản thể)": "徂", "Unihan_Traditional (Chữ Phồn thể)": "徂", "Pinyin_Xie": "cú", "Âm Hán Việt_Xie": "tồ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ sự di chuyển, thời gian trôi qua hoặc người đã khuất. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('洎', '{"9000": "6322.0", "Chữ Trung Quốc": "洎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 9 | nét | 洎 | kế | tượng hình | kịp đến lúc; canh thịt; ngâm ướt | 洎 là chữ có bộ 水/氵 (nước) biểu nghĩa. Cấu tạo đầy đủ không rõ ràng trong nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kế\": Nước (氵) đến kịp — KỊP (洎) đến lúc, cho đến khi (dùng trong văn học cổ). | Gương Hán-Việt | (hiếm trong Hán-Việt thông dụng) | Mở khoá kiến thức | Biết 洎 mở khoá: 洎乎 (cho đến khi, đến lúc — liên từ cổ văn).", "Tự nguyên_Xie": "Wiktionary không có phân tích từ nguyên chi tiết cho 洎. Nghĩa là: kịp đến thời điểm nào đó (đến lúc, cho đến khi); canh thịt; ngâm vào nước. Có bộ 水 liên quan đến nước hoặc chất lỏng. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "kịp thời", "Hạng Tần Suất (Jun Da)": "6322.0", "Tần Suất % (Jun Da)": "99.9902451638", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 自", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵自", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "自", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "洎", "Unihan_Traditional (Chữ Phồn thể)": "洎", "Pinyin_Xie": "jì", "Âm Hán Việt_Xie": "kịp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Giới từ | 介词 | Động từ | 动词 | Chữ này thường làm giới từ chỉ mốc thời gian hoặc làm động từ chỉ sự đạt đến. | Giới từ | 介词 | Ghép với danh từ hoặc đại từ thành cụm chỉ nơi chốn, thời gian, đối tượng: 在家, 跟他. Cụm giới từ đứng TRƯỚC động từ — 我在家吃饭 — ngược với trật tự tiếng Việt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('礌', '{"9000": "6323.0", "Chữ Trung Quốc": "礌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 18 | nét | 礌 | lỗi | tượng hình | tảng đá lớn; lăn đá từ trên cao xuống | 礌 là chữ có bộ 石 (đá) biểu nghĩa. Cấu tạo đầy đủ không rõ ràng trong nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lỗi\": Đá (石) to LĂNG LỖI — tảng ĐÁ LỚN (礌) thủ thành, lăn từ trên cao xuống. | Gương Hán-Việt | (hiếm trong Hán-Việt thông dụng) | Mở khoá kiến thức | Biết 礌 mở khoá: 礌石 (đá lăn thủ thành), thuật ngữ chiến thuật thủ thành trong lịch sử quân sự cổ Trung Hoa.", "Tự nguyên_Xie": "Wiktionary không có phân tích từ nguyên chi tiết cho 礌. Nghĩa là tảng đá lớn, hoặc động từ: lăn đá từ trên cao xuống tấn công kẻ địch (kỹ thuật thủ thành cổ đại). Bộ 石 chỉ liên quan đến đá. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lăn đá từ trên cao xuống; tảng đá lớn", "Hạng Tần Suất (Jun Da)": "6323.0", "Tần Suất % (Jun Da)": "99.9902601506", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 雷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石雷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "雷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "礌", "Unihan_Traditional (Chữ Phồn thể)": "礌", "Pinyin_Xie": "léi", "Âm Hán Việt_Xie": "lôi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ đá tảng hoặc làm động từ chỉ hành động lăn đá để tấn công. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('邠', '{"9000": "6324.0", "Chữ Trung Quốc": "邠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 6 | nét | 分 | phân | biểu âm | chia | 邑 | ấp | biểu nghĩa | thành ấp | 邠 = 分 (Phân, biểu âm) + 邑 (Ấp, biểu nghĩa: thành ấp, địa danh). Chữ hình thanh: bộ 邑 (阝bên phải) chỉ địa danh, phần 分 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bân\": bộ ấp (邑) ghi tên đất — Bân Châu, vùng đất cổ thời nhà Chu ở Thiểm Tây. | Gương Hán-Việt | \"bân\" ít dùng trong tiếng Việt hiện đại; chủ yếu xuất hiện trong địa danh lịch sử Trung Quốc. | Mở khoá kiến thức | Biết 邠 giúp đọc địa danh lịch sử: 邠州 (Bân Châu — tên huyện thời Hán).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary: 邠 là chữ hình thanh gồm 分 (biểu âm) và 邑 (biểu nghĩa: thành ấp). 邠 là tên cổ của một vùng đất ở tỉnh Thiểm Tây, nay cũng viết là 豳 hoặc 彬. Chữ có âm Trung cổ mc=y, oc=y. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước Bân", "Hạng Tần Suất (Jun Da)": "6324.0", "Tần Suất % (Jun Da)": "99.9903495544", "GavinGrover_Once (Chiết tự trực tiếp)": "分 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰分阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "分", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "邠", "Unihan_Traditional (Chữ Phồn thể)": "邠", "Pinyin_Xie": "bīn", "Âm Hán Việt_Xie": "bân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ riêng chỉ địa danh cổ hoặc họ của người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('邽', '{"9000": "6325.0", "Chữ Trung Quốc": "邽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 8 | nét | 邽 | khuê | tượng hình | tên đất cổ, Hạ Khuê / Thượng Khuê ở Thiểm Tây | 邽 là chữ tạo muộn, không có phân tích cấu trúc rõ ràng từ CHISE. Dạng tiểu triện được ghi lại bởi hanziyuan. Chưa có nguồn học thuật xác định hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khuê\": tên đất Khuê — Hạ Khuê (下邽) và Thượng Khuê (上邽) là hai huyện cổ tại vùng Quan Trung. | Gương Hán-Việt | \"khuê\" trong tiếng Việt còn có nghĩa phòng khuê (phòng riêng của phụ nữ), nhưng đây là chữ khác (閨). | Mở khoá kiến thức | Biết 邽 giúp đọc địa danh lịch sử: 下邽, 上邽 trong sử sách Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary chỉ ghi nhận 邽 là địa danh (tên huyện thời Hán), âm guī. Không có phân tích cấu trúc chi tiết. Chữ gắn với địa danh 下邽 (Hạ Khuê) và 上邽 (Thượng Khuê) tại Thiểm Tây. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên đất, xem: hạ khuê 下邽, thượng khuê 上邽); họ Khuê", "Hạng Tần Suất (Jun Da)": "6325.0", "Tần Suất % (Jun Da)": "99.9903640244", "GavinGrover_Once (Chiết tự trực tiếp)": "圭 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰圭阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "圭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "邽", "Unihan_Traditional (Chữ Phồn thể)": "邽", "Pinyin_Xie": "guī", "Âm Hán Việt_Xie": "khuê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ riêng trong địa danh cổ hoặc làm họ người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('溽', '{"9000": "6326.0", "Chữ Trung Quốc": "溽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 13 | nét | 溽 | nhục | tượng hình | ẩm ướt, oi nồng — hơi nóng ẩm bốc lên | 溽 không có phân tích cấu trúc trong dữ liệu CHISE. Nhìn dạng chữ thấy bộ 水 (氵, biểu nghĩa: nước/ẩm) bên trái và phần bên phải cho âm. Nhiều khả năng là chữ hình thanh nhưng chưa có xác nhận học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhục\": hình ảnh mùa hè oi bức — không khí ẩm ướt nồng nặc như hơi nước bốc lên. | Gương Hán-Việt | \"nhục\" đọc gần với \"nhục\" (肉, thịt) nhưng đây là chữ khác nghĩa; 溽 ít dùng trong tiếng Việt. | Mở khoá kiến thức | Biết 溽 giúp đọc: 溽暑 (nhục thử — cái nóng ẩm của mùa hè).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không cung cấp phân tích cấu trúc cho 溽. Chữ mang nghĩa ẩm ướt, oi nồng (moist, muggy) — điển hình dùng trong 溽暑 (nhiệt độ ẩm ướt mùa hè). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hơi nắng bốc lên; ướt; nồng đặc (đồ ăn ngon)", "Hạng Tần Suất (Jun Da)": "6326.0", "Tần Suất % (Jun Da)": "99.9903784944", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 辱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵辱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "辱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "溽", "Unihan_Traditional (Chữ Phồn thể)": "溽", "Pinyin_Xie": "rù", "Âm Hán Việt_Xie": "nhục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường làm tính từ bổ nghĩa cho danh từ để tả thời tiết ẩm ướt, oi bức. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('棰', '{"9000": "6327.0", "Chữ Trung Quốc": "棰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 12 | nét | 木 | mộc | biểu nghĩa | cây, gỗ | 垂 | thuỳ | biểu âm | rủ xuống | 棰 = 木 (Mộc, biểu nghĩa: gỗ) + 垂 (Thuỳ, biểu âm). Chữ hình thanh: bộ 木 chỉ đồ vật bằng gỗ; 垂 cho âm. Nghĩa: gậy ngắn, roi đánh bằng gỗ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chuỳ\": gỗ (木) + rủ xuống (垂) — hình ảnh cây gậy gỗ phạt tội rủ xuống đánh. | Gương Hán-Việt | \"chuỳ\" trong tiếng Việt: cái chuỳ (dùi cui), búa chuỳ; 棰 đặc chỉ roi gậy phạt trong pháp hình cổ. | Mở khoá kiến thức | Biết 棰 giúp đọc: 棰楚 (chuỳ sở — đánh gậy, hình phạt roi).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary: 棰 là chữ hình thanh gồm 木 (biểu nghĩa: gỗ) và 垂 (biểu âm). Chữ chỉ gậy ngắn hoặc roi gỗ dùng để đánh phạt. Xuất hiện trong dạng tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gậy ngắn; đánh bằng gậy", "Hạng Tần Suất (Jun Da)": "6327.0", "Tần Suất % (Jun Da)": "99.9903929643", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 垂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木垂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "垂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "棰", "Unihan_Traditional (Chữ Phồn thể)": "棰", "Pinyin_Xie": "chuí", "Âm Hán Việt_Xie": "chùy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này có thể làm danh từ chỉ cây gậy ngắn hoặc làm động từ chỉ hành động đánh bằng gậy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('舭', '{"9000": "6328.0", "Chữ Trung Quốc": "舭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 舟 | Số nét | 10 | nét | 舭 | bỉ | tượng hình | phần uốn khúc giữa mạn và đáy thuyền (bilge) | 舭 không có dữ liệu nguồn gốc từ Wiktionary. Nhìn dạng chữ thấy bộ 舟 (thuyền) và phần còn lại. Nhiều khả năng hình thanh nhưng chưa xác nhận được. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bỉ\": bộ 舟 (thuyền) — phần bỉ là chỗ uốn cong ở đáy thuyền nơi nước tích tụ. | Gương Hán-Việt | \"bỉ\" trong tiếng Việt dùng trong thuật ngữ hàng hải; ít phổ biến trong văn viết thường nhật. | Mở khoá kiến thức | Biết 舭 giúp đọc thuật ngữ đóng thuyền: phần 舭 là bilge — khoang dưới đáy tàu.", "Tự nguyên_Xie": "Không có dữ liệu nguồn gốc từ Wiktionary cho chữ 舭. Chữ ghi thuật ngữ hàng hải: phần uốn cong giữa mạn thuyền và đáy thuyền (bilge tiếng Anh). Đây là từ vay mượn khái niệm kỹ thuật. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chỗ uốn lượn (phần uốn khúc giữa mạn thuyền và đáy thuyền); Ghi chú: (英bilge)", "Hạng Tần Suất (Jun Da)": "6328.0", "Tần Suất % (Jun Da)": "99.9904074343", "GavinGrover_Once (Chiết tự trực tiếp)": "舟 + 比", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舟比", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "比", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舟", "Unihan_Simplified (Chữ Giản thể)": "舭", "Unihan_Traditional (Chữ Phồn thể)": "舭", "Pinyin_Xie": "bǐ", "Âm Hán Việt_Xie": "tỳ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ trong thuật ngữ hàng hải để chỉ phần chuyển tiếp giữa mạn và đáy tàu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('艋', '{"9000": "6329.0", "Chữ Trung Quốc": "艋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 舟 | Số nét | 14 | nét | 艋 | mành | tượng hình | thuyền nhỏ — dùng trong từ ghép 舴艋 hoặc 艋舺 | 艋 không có phân tích cấu trúc CHISE rõ ràng. Nhìn dạng chữ thấy bộ 舟 (thuyền) và phần âm. Chữ chủ yếu dùng trong từ ghép 舴艋 (thuyền nhỏ) và địa danh 艋舺 (Mạnh Giáp — tên phố cổ Đài Bắc). Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mành\": con thuyền mành nhỏ — 舴艋 là loại thuyền nhỏ và nhẹ trên sông. | Gương Hán-Việt | \"mành\" trong tiếng Việt: thuyền mành — loại thuyền buồm nhỏ của Đông Nam Á và miền Nam Trung Quốc. | Mở khoá kiến thức | Biết 艋 giúp đọc: 舴艋 (trách mành — thuyền nhỏ), 艋舺 (Mạnh Giáp — tên địa danh Đài Loan).", "Tự nguyên_Xie": "Wiktionary xác nhận 艋 dùng trong 舴艋 (thuyền nhỏ) và địa danh 艋舺 (Mạnh Giáp). Không có phân tích nguồn gốc chi tiết từ học thuật. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: trách mãnh 舴艋)", "Hạng Tần Suất (Jun Da)": "6329.0", "Tần Suất % (Jun Da)": "99.9904219043", "GavinGrover_Once (Chiết tự trực tiếp)": "舟 + 孟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舟孟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "孟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舟", "Unihan_Simplified (Chữ Giản thể)": "艋", "Unihan_Traditional (Chữ Phồn thể)": "艋", "Pinyin_Xie": "měng", "Âm Hán Việt_Xie": "mãnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường kết hợp thành từ ghép để chỉ các loại thuyền nhỏ, xuồng ba lá. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('聱', '{"9000": "6330.0", "Chữ Trung Quốc": "聱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 耳 | Số nét | 16 | nét | 聱 | ngao | tượng hình | trúc trắc, khó nghe, lủng củng — dùng trong 聱牙 | 聱 không có phân tích cấu trúc CHISE rõ ràng. Nhìn dạng chữ thấy bộ 耳 (nhĩ, tai) ở dưới, gợi liên quan đến âm thanh, nghe. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngao\": bộ tai (耳) phía dưới — âm thanh trúc trắc lủng củng khó lọt vào tai. | Gương Hán-Việt | \"ngao\" ít dùng độc lập trong tiếng Việt; chủ yếu trong Hán văn. | Mở khoá kiến thức | Biết 聱 giúp đọc: 聱牙 (ngao nha — trúc trắc khó đọc), 佶屈聱牙 (văn phong khúc khuỷu).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không cung cấp phân tích cấu trúc cho 聱. Chữ mang nghĩa trúc trắc, khó nghe (佶屈聱牙 — văn phong khó đọc). Bộ 耳 (tai) có thể gợi ý liên quan đến âm thanh khó nghe. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trúc trắc, chủng chẳng khó nghe, lủng củng", "Hạng Tần Suất (Jun Da)": "6330.0", "Tần Suất % (Jun Da)": "99.9904508443", "GavinGrover_Once (Chiết tự trực tiếp)": "敖 + 耳", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱敖耳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "耳", "Unihan_Simplified (Chữ Giản thể)": "聱", "Unihan_Traditional (Chữ Phồn thể)": "聱", "Pinyin_Xie": "áo", "Âm Hán Việt_Xie": "ngao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường làm tính từ miêu tả văn chương hoặc lời nói khúc khuỷu, không trôi chảy. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('尢', '{"9000": "6331.0", "Chữ Trung Quốc": "尢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 尢 | Số nét | 3 | nét | 尢 | uông | tượng hình | người có chân cong yếu — hình tượng hình gốc | 尢 là chữ tượng hình độc lập: hình người (大) nhưng một chân bị cong hoặc khuỵu — biểu thị sự yếu đuối, khiếm khuyết. So sánh với 大 (người chân thẳng). Đây là bộ thủ Khang Hy số 43.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uông\": chữ 大 (người) nhưng một chân cong xuống — hình ảnh người yếu đuối khập khiễng. | Gương Hán-Việt | \"uông\" ít dùng trong tiếng Việt hiện đại; 尢 chủ yếu là bộ thủ để tra từ điển. | Mở khoá kiến thức | Biết 尢 giúp tra bộ thủ số 43: các chữ thuộc bộ 尢 như 尤 (đặc biệt), 就 (đến), 尴尬 (lúng túng).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Theo Wiktionary: 尢 là chữ tượng hình (liushu=i), hình người có chân cong (khác với 大 — người chân thẳng). Có thể là hình ảnh người đang nhảy hoặc người yếu chân. Các nét bút hơi khác với 大. Xuất hiện trong kim văn và tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1104.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hình ảnh một người bị thọt chân, què quặt (chân bên phải bị gập lại). Giải thích sự chuyển ý: Đây là chữ Tượng hình. Uông là người bị thọt chân, tàn tật.", "Nghĩa Tiếng Việt_Xie": "kiễng chân; yếu đuối", "Hạng Tần Suất (Jun Da)": "6331.0", "Tần Suất % (Jun Da)": "99.9904653143", "GavinGrover_Once (Chiết tự trực tiếp)": "𠂇 + 乚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴𠂇乚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𠂇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "乚", "Unihan_Simplified (Chữ Giản thể)": "尢", "Unihan_Traditional (Chữ Phồn thể)": "尢", "Pinyin_Xie": "yóu", "Âm Hán Việt_Xie": "ngột, uông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này thường làm tính từ chỉ người có dị tật ở chân hoặc dùng làm bộ thủ trong chữ Hán. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('藚', '{"9000": "6332.0", "Chữ Trung Quốc": "藚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 18 | nét | 藚 | súc | tượng hình | cây trạch tả (Alisma orientale) — thực vật nước dùng làm thuốc | 藚 không có phân tích cấu trúc CHISE rõ ràng. Nhìn dạng chữ thấy bộ 艸 (tháu, cỏ) — gợi ý thực vật. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"súc\": bộ cỏ (艸) — cây trạch tả mọc ở nước, dùng làm vị thuốc thanh nhiệt. | Gương Hán-Việt | \"súc\" ít gặp trong tiếng Việt thường nhật; xuất hiện trong y học cổ truyền. | Mở khoá kiến thức | Biết 藚 giúp đọc: 澤瀉 (trạch tả) — tên khác của cây này trong y học cổ truyền.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary xác nhận 藚 là tên cây Trạch Tả (Alisma orientale), cũng gọi là 澤瀉. Không có phân tích nguồn gốc cấu trúc chi tiết. Chữ tạo muộn, chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Alisma plantago", "Hạng Tần Suất (Jun Da)": "6332.0", "Tần Suất % (Jun Da)": "99.9904797842", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 賣", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹賣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "賣", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "藚", "Unihan_Traditional (Chữ Phồn thể)": "藚", "Pinyin_Xie": "xù", "Âm Hán Việt_Xie": "tục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài cỏ nước dùng làm thuốc trong Đông y. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('佾', '{"9000": "6333.0", "Chữ Trung Quốc": "佾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 8 | nét | 佾 | dật | tượng hình | hàng vũ công trong lễ tế thiên tử | 佾 không có phân tích cấu trúc CHISE rõ ràng. Nhìn dạng chữ thấy bộ 人 (亻, nhân) — gợi ý liên quan đến người, vũ công. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dật\": bộ 人 (亻) — hàng người vũ công trong lễ tế; tám người một hàng là một dật. | Gương Hán-Việt | \"dật\" trong tiếng Việt có nghĩa phóng túng/vượt qua (佚), nhưng đây là chữ khác; 佾 đặc chỉ hàng múa lễ. | Mở khoá kiến thức | Biết 佾 giúp đọc Luận Ngữ: 八佾 (bát dật — tám hàng vũ công của thiên tử).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary xác nhận 佾 chỉ hàng vũ công trong lễ tế hiến tế thời phong kiến Trung Quốc: mỗi hàng tám người được gọi là một 佾, thiên tử được dùng tám hàng (八佾, 64 người). Chữ này nổi tiếng qua Luận Ngữ: ''Ba Thị dùng tám hàng vũ công (八佾) trong sân — điều không thể chịu được!''. Chưa có nguồn học thuật về cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hàng dật (trong lễ định vua Thiên tử được bắt sáu mươi tư người múa bài bông, mỗi hàng tám người gọi là múa bát dật)", "Hạng Tần Suất (Jun Da)": "6333.0", "Tần Suất % (Jun Da)": "99.9904942542", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 䏌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻䏌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "䏌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "佾", "Unihan_Traditional (Chữ Phồn thể)": "佾", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "dật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Thường dùng làm danh từ chỉ hàng múa hoặc lượng từ đếm số hàng múa trong tế lễ cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蕻', '{"9000": "6334.0", "Chữ Trung Quốc": "蕻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 16 | nét | 蕻 | hồng | tượng hình | cải xanh (choy sum), rau xanh tươi tốt | 蕻 không có phân tích cấu trúc CHISE rõ ràng. Nhìn dạng chữ thấy bộ 艸 (tháu, cỏ) gợi thực vật. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hồng\": bộ cỏ (艸) — cây rau xanh tươi hồng, đặc biệt cải muối 雪裡蕻 (tuyết lý hồng). | Gương Hán-Việt | \"hồng\" trong tiếng Việt thường gặp nghĩa màu đỏ hồng, nhưng ở đây 蕻 chỉ loài rau. | Mở khoá kiến thức | Biết 蕻 giúp đọc: 雪裡蕻 (tuyết lý hồng — cải muối tuyết, món ăn phổ biến).", "Tự nguyên_Xie": "Wiktionary xác nhận 蕻 chỉ loài rau 雪裡蕻 (cải muối tuyết) và choy sum (Brassica rapa var. parachinensis). Cũng có nghĩa tươi tốt, xanh mướt. Chữ tạo muộn, không thấy trong giáp cốt hay kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tươi tốt", "Hạng Tần Suất (Jun Da)": "6334.0", "Tần Suất % (Jun Da)": "99.9905087242", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "蕻", "Unihan_Traditional (Chữ Phồn thể)": "蕻", "Pinyin_Xie": "hóng", "Âm Hán Việt_Xie": "hống", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ một loại rau cải hoặc tính từ tả cây cối tươi tốt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('狁', '{"9000": "6335.0", "Chữ Trung Quốc": "狁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 7 | nét | 狁 | duẫn | tượng hình | tên tộc du mục phương Bắc thời cổ — Hiểm Duẫn (玁狁) | 狁 không có phân tích cấu trúc CHISE rõ ràng. Nhìn dạng chữ thấy bộ 犬 (khuyển, chó) — gợi ý tên tộc dân du mục bị coi là man di. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"duẫn\": bộ khuyển (犬) — tên tộc 玁狁 (Hiểm Duẫn), dân du mục phương Bắc thời nhà Chu. | Gương Hán-Việt | \"duẫn\" ít gặp trong tiếng Việt; chỉ xuất hiện trong lịch sử học. | Mở khoá kiến thức | Biết 狁 giúp đọc: 玁狁 (Hiểm Duẫn) trong Kinh Thi và sử ký Trung Quốc.", "Tự nguyên_Xie": "Wiktionary xác nhận 狁 chỉ dùng trong 玁狁 — tên một tộc du mục phương Bắc thời Chu (được đồng nhất với người Scythia hoặc Hung Nô sơ kỳ). Chữ không có phân tích cấu trúc chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước Duẫn", "Hạng Tần Suất (Jun Da)": "6335.0", "Tần Suất % (Jun Da)": "99.9905231942", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 允", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭允", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "允", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "狁", "Unihan_Traditional (Chữ Phồn thể)": "狁", "Pinyin_Xie": "yǔn", "Âm Hán Việt_Xie": "duẫn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ riêng trong tên bộ tộc Hiểm Duẫn thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('绁', '{"9000": "6336.0", "Chữ Trung Quốc": "绁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 8 | nét | 糸 | biểu nghĩa | sợi tơ, dây | 世 | thế | biểu âm | đời | 绁 = 糸 (biểu nghĩa: sợi tơ, dây) + 世 (Thế, biểu âm). Chữ hình thanh: bộ 糸 gợi vật bằng sợi/dây; 世 cho âm. Chữ gốc là 紲 (truyền thống).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiết\": bộ sợi tơ (糸) + thế (世) — sợi dây cương buộc ngựa qua từng đời. | Gương Hán-Việt | \"tiết\" trong tiếng Việt thường gặp trong 節 (tiết — khớp, tiết mục); 绁 là chữ hiếm chỉ dây buộc. | Mở khoá kiến thức | Biết 绁 giúp hiểu từ cổ: 紲馬 (tiết mã — dây buộc ngựa), 束縛 cùng nhóm nghĩa.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary: chữ gốc là 紲 — hình thanh gồm 糸 (sợi tơ, dây — biểu nghĩa) và 世 (biểu âm). 绁/紲 chỉ dây cương ngựa hoặc dây trói buộc. Dạng giản thể 绁 dùng 纟thay cho 糸. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cương ngựa", "Hạng Tần Suất (Jun Da)": "6336.0", "Tần Suất % (Jun Da)": "99.9905376642", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 世", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟世", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "世", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "绁", "Unihan_Traditional (Chữ Phồn thể)": "紲", "Pinyin_Xie": "xiè", "Âm Hán Việt_Xie": "tiết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Dùng làm danh từ chỉ dây buộc hoặc động từ với nghĩa trói buộc, xiềng xích. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('牾', '{"9000": "6337.0", "Chữ Trung Quốc": "牾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 牛 | Số nét | 11 | nét | 牛 | ngưu | biểu nghĩa | trâu bò | 吾 | ngô | biểu âm | tôi (đại từ) | 牾 = 牛 (Ngưu, biểu nghĩa: trâu bò) + 吾 (Ngô, biểu âm). Chữ hình thanh: bộ 牛 gợi sức đẩy húc của trâu; 吾 cho âm. Nghĩa: húc chống lại, xung đột.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngỗ\": trâu (牛) + tôi (吾) — hình ảnh trâu húc ngược lại, ý nghĩa ngỗ ngược, chống đối. | Gương Hán-Việt | \"ngỗ\" trong tiếng Việt: ngỗ ngược, ngỗ nghịch — thái độ chống đối bất tuân. | Mở khoá kiến thức | Biết 牾 giúp hiểu: 牾 gợi ý chống đối, tương phùng, cùng nhóm với 忤逆 (ngỗ nghịch).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary: 牾 là chữ hình thanh gồm 牛 (biểu nghĩa: trâu bò) và 吾 (biểu âm). Chữ ghi hành động húc, chống đối — gắn với hình ảnh trâu húc đầu vào nhau. Xuất hiện trong tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tương phùng; gặp gỡ; gặp nhau; làm trái; trái", "Hạng Tần Suất (Jun Da)": "6337.0", "Tần Suất % (Jun Da)": "99.9905521342", "GavinGrover_Once (Chiết tự trực tiếp)": "牛 + 吾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰牛吾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "牛", "Unihan_Simplified (Chữ Giản thể)": "牾", "Unihan_Traditional (Chữ Phồn thể)": "牾", "Pinyin_Xie": "wǔ", "Âm Hán Việt_Xie": "ngộ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ chỉ sự xung đột, bất đồng hoặc kết hợp thành từ ghép chỉ sự mâu thuẫn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('慝', '{"9000": "6338.0", "Chữ Trung Quốc": "慝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 14 | nét | 慝 | thắc | tượng hình | ác ngầm, xấu xa trong tâm — chưa có nguồn học thuật | 慝 không có phân tích cấu trúc CHISE rõ ràng; Wiktionary chỉ ghi {{Han etym}} không có chi tiết. Nhìn dạng chữ thấy bộ 心 (tâm) — gợi ý liên quan đến nội tâm xấu. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thắc\": bộ tâm (心) ẩn trong chữ — cái ác thắc mắc ẩn giấu trong lòng. | Gương Hán-Việt | \"thắc\" trong tiếng Việt: thắc mắc (lo ngại), nhưng 慝 đặc chỉ điều ác ngầm ẩn. | Mở khoá kiến thức | Biết 慝 giúp đọc văn cổ về đạo đức: 邪慝 (tà thắc — điều ác tà), 陰慝 (âm thắc — điều xấu ẩn).", "Tự nguyên_Xie": "Wiktionary không cung cấp phân tích cấu trúc cho 慝. Chữ mang nghĩa ác ngầm, tâm địa xấu xa, không ngay thẳng. Có thể thấy bộ 心 (tâm) trong cấu trúc. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ác ngầm, không ngay thẳng; gièm pha; đồn nhảm; âm khí", "Hạng Tần Suất (Jun Da)": "6338.0", "Tần Suất % (Jun Da)": "99.9905666042", "GavinGrover_Once (Chiết tự trực tiếp)": "匿 + 心", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱匿心", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "心", "Unihan_Simplified (Chữ Giản thể)": "慝", "Unihan_Traditional (Chữ Phồn thể)": "慝", "Pinyin_Xie": "tè", "Âm Hán Việt_Xie": "thắc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Dùng làm danh từ chỉ ý nghĩ xấu xa hoặc tính từ chỉ sự gian tà, không ngay thẳng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蜱', '{"9000": "6339.0", "Chữ Trung Quốc": "蜱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 14 | nét | 蜱 | bì | tượng hình | ve (tick) — loài ký sinh trùng hút máu | 蜱 không có phân tích cấu trúc CHISE rõ ràng. Nhìn dạng chữ thấy bộ 虫 (trùng, côn trùng) — gợi ý loài động vật nhỏ. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bì\": bộ trùng (虫) — con bì ve nhỏ bám vào da hút máu. | Gương Hán-Việt | \"bì\" trong tiếng Việt thường gặp nghĩa da (皮 bì), nhưng 蜱 đặc chỉ con ve ký sinh. | Mở khoá kiến thức | Biết 蜱 giúp đọc thuật ngữ y tế và sinh học: 蜱蟲 (bì trùng — con ve), 蜱蛸 (nhện).", "Tự nguyên_Xie": "Wiktionary xác nhận 蜱 chỉ con ve (tick, Acari) — loài ký sinh trùng hút máu. Tên đồng nghĩa 壁蝨. Không có phân tích cấu trúc chi tiết. Chữ tạo muộn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một loài nhện", "Hạng Tần Suất (Jun Da)": "6339.0", "Tần Suất % (Jun Da)": "99.9905810741", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 卑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫卑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蜱", "Unihan_Traditional (Chữ Phồn thể)": "蜱", "Pinyin_Xie": "pí", "Âm Hán Việt_Xie": "tỳ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ các loài côn trùng ký sinh hút máu như ve, bét. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鬘', '{"9000": "6340.0", "Chữ Trung Quốc": "鬘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 髟 | Số nét | 21 | nét | 鬘 | man | tượng hình | tóc đẹp mượt mà, hoa trang trí tóc (trong nghệ thuật Phật giáo) | 鬘 không có phân tích cấu trúc CHISE rõ ràng. Nhìn dạng chữ thấy bộ 髟 (biêu — tóc dài) gợi ý liên quan đến tóc. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"man\": bộ tóc dài (髟) — mái tóc mượt mà đẹp như vòng hoa man. | Gương Hán-Việt | \"man\" trong tiếng Việt thường gặp nghĩa man rợ/man di, nhưng 鬘 đặc chỉ tóc đẹp. | Mở khoá kiến thức | Biết 鬘 giúp đọc: 華鬘 (hoa man — vòng hoa trang trí trong Phật giáo).", "Tự nguyên_Xie": "Wiktionary không cung cấp phân tích cấu trúc chi tiết cho 鬘. Chữ ghi hình ảnh tóc đẹp mượt hoặc vòng hoa đội đầu (華鬘 — vòng hoa Phật giáo). Bộ 髟 gợi tóc dài. Chữ tạo muộn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tóc mượt", "Hạng Tần Suất (Jun Da)": "6340.0", "Tần Suất % (Jun Da)": "99.9905955441", "GavinGrover_Once (Chiết tự trực tiếp)": "髟 + 曼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱髟曼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "髟", "Unihan_Simplified (Chữ Giản thể)": "鬘", "Unihan_Traditional (Chữ Phồn thể)": "鬘", "Pinyin_Xie": "mán", "Âm Hán Việt_Xie": "man", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn thơ cổ để chỉ mái tóc đẹp của phụ nữ hoặc vòng hoa đội đầu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('埚', '{"9000": "6341.0", "Chữ Trung Quốc": "埚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 10 | nét | 埚 | qua | tượng hình | nồi nấu chảy kim loại (crucible) — dạng giản thể của 堝 | 埚 là dạng giản thể của 堝 (堝 = thổ + 呙). Không có phân tích cấu trúc riêng — tra theo 堝. Bộ 土 (thổ, đất) gợi ý đồ vật bằng đất nung.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"qua\": bộ đất (土) — nồi đất nung chịu lửa để nấu chảy kim loại. | Gương Hán-Việt | \"qua\" trong tiếng Việt thường gặp nghĩa đi qua hoặc dưa (南瓜); 埚 đặc chỉ nồi nấu kim loại. | Mở khoá kiến thức | Biết 埚 giúp đọc thuật ngữ luyện kim: 坩埚 (cam qua — nồi nung, crucible).", "Tự nguyên_Xie": "Wiktionary xác nhận 埚 là dạng giản thể của 堝, tra theo 堝. 堝 là nồi nấu chảy kim loại (crucible) làm bằng đất nung chịu nhiệt độ cao. Chữ tạo muộn, chưa thấy trong giáp cốt hay kim văn. Chưa có nguồn học thuật riêng. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nồi nấu kim loại", "Hạng Tần Suất (Jun Da)": "6341.0", "Tần Suất % (Jun Da)": "99.9906673773", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 呙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土呙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "呙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "埚", "Unihan_Traditional (Chữ Phồn thể)": "堝", "Pinyin_Xie": "guō", "Âm Hán Việt_Xie": "qua", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ đứng sau các từ chỉ chất liệu để tạo thành tên loại nồi nấu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('堙', '{"9000": "6342.0", "Chữ Trung Quốc": "堙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 12 | nét | 堙 | nhân | tượng hình | lấp đất, chôn vùi, ụ đất đắp cao | 堙 không có phân tích cấu trúc CHISE rõ ràng. Nhìn dạng chữ thấy bộ 土 (thổ, đất) — gợi ý liên quan đến đất đai. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhân\": bộ đất (土) — lấp đất nhân lên, chôn vùi hoặc đắp cao. | Gương Hán-Việt | \"nhân\" trong tiếng Việt thường gặp nghĩa người (人) hoặc nhân quả; 堙 là chữ chuyên ngành ít dùng. | Mở khoá kiến thức | Biết 堙 giúp đọc văn cổ về công trình đất đai: 堙塞 (nhân tắc — bít lấp, ngăn chặn).", "Tự nguyên_Xie": "Wiktionary chỉ ghi phát âm và không có phân tích cấu trúc cho 堙. Chữ mang nghĩa lấp đất, chôn vùi, hoặc ụ đất đắp cao. Bộ 土 (đất) rõ ràng gợi ý liên quan đến công việc đất đai, đắp đê. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lấp, chôn; ụ đất", "Hạng Tần Suất (Jun Da)": "6342.0", "Tần Suất % (Jun Da)": "99.9906813305", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 垔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土垔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "垔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "堙", "Unihan_Traditional (Chữ Phồn thể)": "堙", "Pinyin_Xie": "yīn", "Âm Hán Việt_Xie": "nhân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường đi kèm với các từ chỉ đất đá hoặc sự che lấp, cản trở. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('菥', '{"9000": "6343.0", "Chữ Trung Quốc": "菥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 菥 | tích | tượng hình | tên cây thuốc trong 菥蓂 — toàn thân dùng thanh nhiệt giải độc | 菥 không có phân tích cấu trúc CHISE rõ ràng. Nhìn dạng chữ thấy bộ 艸 (tháu, cỏ) — gợi ý thực vật. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tích\": bộ cỏ (艸) — cây tích mãnh (菥蓂) là thảo dược thanh nhiệt. | Gương Hán-Việt | \"tích\" trong tiếng Việt thường gặp nghĩa xưa cũ (tích cũ); 菥 là chữ thảo dược hiếm. | Mở khoá kiến thức | Biết 菥 giúp đọc tên thảo dược: 菥蓂 (tích mãnh — tên cây trong Đông y).", "Tự nguyên_Xie": "Wiktionary xác nhận 菥 chỉ dùng trong 菥蓂 — tên một loài cây thuốc, toàn thân có tác dụng thanh nhiệt giải độc. Không có phân tích cấu trúc chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(một loại thực vật, toàn thân dùng làm thuốc, có tác dụng thanh nhiệt giải độc.)", "Hạng Tần Suất (Jun Da)": "6343.0", "Tần Suất % (Jun Da)": "99.9906952837", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 析", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹析", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "析", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "菥", "Unihan_Traditional (Chữ Phồn thể)": "菥", "Pinyin_Xie": "xī", "Âm Hán Việt_Xie": "tích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ trong tên gọi thảo dược tích minh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('萏', '{"9000": "6344.0", "Chữ Trung Quốc": "萏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 萏 | đạm | tượng hình | hoa sen — dùng trong 菡萏 (nụ sen) | 萏 không có phân tích cấu trúc CHISE rõ ràng. Nhìn dạng chữ thấy bộ 艸 (tháu, cỏ) — gợi ý thực vật. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đạm\": bộ cỏ (艸) — nụ sen đạm nhạt thanh khiết chưa nở trong 菡萏. | Gương Hán-Việt | \"đạm\" trong tiếng Việt thường gặp nghĩa đạm nhạt, đạm bạc; 萏 là chữ thơ văn chỉ hoa sen. | Mở khoá kiến thức | Biết 萏 giúp đọc thơ cổ: 菡萏 (hàm đạm — nụ sen, hoa sen chưa nở đầy đủ).", "Tự nguyên_Xie": "Lục thư thông | Wiktionary xác nhận 萏 chỉ dùng trong 菡萏 — tên chữ Hán chỉ hoa sen (đặc biệt là nụ sen chưa nở). Không có phân tích cấu trúc chi tiết. Chữ tạo muộn, thấy trong lục thư thông. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: hạm đạm 菡萏)", "Hạng Tần Suất (Jun Da)": "6344.0", "Tần Suất % (Jun Da)": "99.9907092368", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 臽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹臽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "臽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "萏", "Unihan_Traditional (Chữ Phồn thể)": "萏", "Pinyin_Xie": "dàn", "Âm Hán Việt_Xie": "đạm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường kết hợp với hạm thành từ ghép hạm đạm để chỉ hoa sen. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('玟', '{"9000": "6345.0", "Chữ Trung Quốc": "玟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 8 | nét | 玟 | văn | tượng hình | đường vân trên ngọc — đá đẹp như ngọc | 玟 không có phân tích cấu trúc CHISE rõ ràng. Nhìn dạng chữ thấy bộ 玉/王 (ngọc) — gợi ý liên quan đến ngọc đá quý. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"văn\": bộ ngọc (王/玉) — đường vân văn hoa trên viên ngọc quý. | Gương Hán-Việt | \"văn\" trong tiếng Việt: văn chương, vân vẻ; 玟 đặc chỉ vân trên đá ngọc. | Mở khoá kiến thức | Biết 玟 giúp đọc văn học: tên người (Bảo Văn 玟), hoặc từ chỉ đá quý có vân đẹp.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary ghi 玟 có hai đọc: một là 珉 (mǐn, loại đá giống ngọc), hai là wén (vân trên ngọc). Không có phân tích cấu trúc chi tiết. Chữ tạo muộn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(một thứ đá đẹp như ngọc)", "Hạng Tần Suất (Jun Da)": "6345.0", "Tần Suất % (Jun Da)": "99.99072319", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 文", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王文", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "文", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "玟", "Unihan_Traditional (Chữ Phồn thể)": "玟", "Pinyin_Xie": "wén", "Âm Hán Việt_Xie": "văn, mân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loại đá quý hoặc dùng trong tên người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('椟', '{"9000": "6346.0", "Chữ Trung Quốc": "椟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 12 | nét | 椟 | độc | tượng hình | tủ, hộp đựng đồ — dạng giản thể của 櫝 | 椟 là dạng giản thể của 櫝 (giản: 賣→卖). Không có phân tích cấu trúc riêng. Bộ 木 (mộc, gỗ) gợi ý đồ vật bằng gỗ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"độc\": bộ gỗ (木) — chiếc hộp gỗ đẹp đựng ngọc châu — gợi thành ngữ 買櫝還珠. | Gương Hán-Việt | \"độc\" trong tiếng Việt thường gặp nghĩa độc hại, nhưng 椟 đặc chỉ hộp gỗ đựng đồ quý. | Mở khoá kiến thức | Biết 椟 giúp hiểu thành ngữ: 買櫝還珠 (mãi độc hoàn châu — chuộng hình thức bỏ nội dung).", "Tự nguyên_Xie": "Bạch thư | Tiểu triện | Wiktionary xác nhận 椟 là dạng giản thể của 櫝, tra theo 櫝. Chữ gốc 櫝 chỉ tủ, hộp đựng đồ bằng gỗ. Nổi tiếng qua thành ngữ 買櫝還珠 (mua hộp trả ngọc — chỉ người nhầm giá trị). Xuất hiện trong bạch thư và tiểu triện. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái tủ", "Hạng Tần Suất (Jun Da)": "6346.0", "Tần Suất % (Jun Da)": "99.9907371432", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 卖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木卖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "椟", "Unihan_Traditional (Chữ Phồn thể)": "櫝", "Pinyin_Xie": "dú", "Âm Hán Việt_Xie": "độc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ đồ dùng để đựng, thường xuất hiện trong các thành ngữ cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铗', '{"9000": "6347.0", "Chữ Trung Quốc": "铗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 11 | nét | 铗 | giáp | tượng hình | cán kiếm; kẹp kim loại — dạng giản thể của 鋏 | 铗 là dạng giản thể của 鋏 (金+夾). Không có phân tích cấu trúc riêng cho 铗. Bộ 金 (kim loại) gợi ý đồ vật kim loại. Chữ gốc 鋏 = 金 (kim) + 夾 (kẹp).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giáp\": bộ kim loại (金) — cán kiếm giáp dài; tiếng kiếm kêu gọi chủ nhân về. | Gương Hán-Việt | \"giáp\" trong tiếng Việt: giáp trụ (áo giáp), giáp mặt; 铗/鋏 đặc chỉ cán kiếm. | Mở khoá kiến thức | Biết 铗 giúp đọc Chiến Quốc Sách: 長鋏歸來乎 (trường giáp quy lai hồ — trường kiếm hãy về cùng ta).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary xác nhận 铗 là dạng giản thể của 鋏, tra theo 鋏. Chữ 鋏 chỉ cán kiếm dài hoặc kẹp kim loại. Nổi tiếng qua trích dẫn Chiến Quốc Sách: ''Trường kiếm (長鋏), hãy về cùng ta! Ở đây không có cá!'' — hình ảnh người tài chưa được dùng. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái kìm gắp; thanh gươm", "Hạng Tần Suất (Jun Da)": "6347.0", "Tần Suất % (Jun Da)": "99.9907510964", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 夹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅夹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铗", "Unihan_Traditional (Chữ Phồn thể)": "鋏", "Pinyin_Xie": "jiá", "Âm Hán Việt_Xie": "kiệp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ công cụ gắp hoặc vũ khí trong văn học cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('颙', '{"9000": "6348.0", "Chữ Trung Quốc": "颙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 頁 | Số nét | 15 | nét | 颙 | ngung | tượng hình | nghiêm trang, to lớn; ngẩng đầu trông đợi — dạng giản thể của 顒 | 颙 là dạng giản thể của 顒 (元+頁). Không có phân tích cấu trúc riêng. Bộ 頁 (trang/đầu) gợi ý liên quan đến đầu, dáng vẻ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngung\": bộ đầu (頁) — dáng ngẩng đầu nghiêm trang, ngưỡng vọng. | Gương Hán-Việt | \"ngung\" ít dùng trong tiếng Việt; chủ yếu trong văn ngôn và thơ cổ. | Mở khoá kiến thức | Biết 颙 giúp đọc văn cổ: 顒望 (ngung vọng — mong đợi, ngóng trông).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary xác nhận 颙 là dạng giản thể của 顒, tra theo 顒. Chữ mang nghĩa nghiêm trang, to lớn, hoặc ngẩng đầu trông đợi (顒望). Không có phân tích cấu trúc chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nghiêm chỉnh", "Hạng Tần Suất (Jun Da)": "6348.0", "Tần Suất % (Jun Da)": "99.9907650496", "GavinGrover_Once (Chiết tự trực tiếp)": "禺 + 页", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禺页", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "禺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "页", "Unihan_Simplified (Chữ Giản thể)": "颙", "Unihan_Traditional (Chữ Phồn thể)": "顒", "Pinyin_Xie": "yóng", "Âm Hán Việt_Xie": "ngung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này làm tính từ miêu tả dáng vẻ tôn kính hoặc động từ thể hiện sự mong mỏi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('踬', '{"9000": "6349.0", "Chữ Trung Quốc": "踬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 15 | nét | 踬 | trật | tượng hình | vấp ngã, thất bại — dạng giản thể của 躓 | 踬 là dạng giản thể của 躓 (足+質). Không có phân tích cấu trúc riêng. Bộ 足 (túc, chân) gợi ý liên quan đến đi lại, vấp ngã.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trật\": bộ chân (足) — bước chân vấp trật, ngã xuống, thất bại. | Gương Hán-Việt | \"trật\" trong tiếng Việt: trật bánh, lỡ trật; 踬/躓 đặc chỉ vấp ngã trên đường đời. | Mở khoá kiến thức | Biết 踬 giúp đọc: 跋前躓後 (bạt tiền trật hậu — tiến thoái đều khó), 顛躓 (điên trật — ngã lộn).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary xác nhận 踬 là dạng giản thể của 躓, tra theo 躓. Chữ gốc 躓 = 足 (chân) + 質 (biểu âm). Nghĩa: vấp ngã, vấp váp, thất bại trên đường đời. Xuất hiện trong tiểu triện. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vấp ngã; té ngã; lộn nhào; thất bại; vấp váp", "Hạng Tần Suất (Jun Da)": "6349.0", "Tần Suất % (Jun Da)": "99.9907790028", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 质", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊质", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "质", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "踬", "Unihan_Traditional (Chữ Phồn thể)": "躓", "Pinyin_Xie": "zhì", "Âm Hán Việt_Xie": "chí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động vấp ngã hoặc nghĩa bóng là gặp thất bại trong cuộc sống. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('筚', '{"9000": "6350.0", "Chữ Trung Quốc": "筚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 12 | nét | 筚 | tất | tượng hình | hàng rào tre, liếp tre — dạng giản thể của 篳 | 筚 là dạng giản thể của 篳 (竹+畢). Không có phân tích cấu trúc riêng. Bộ 竹 (trúc, tre) gợi ý đồ vật bằng tre.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tất\": bộ tre (竹) — rào tre tất bạch tất lộ — hình ảnh người lập nghiệp gian khổ. | Gương Hán-Việt | \"tất\" trong tiếng Việt: tất cả, tất nhiên; 筚 đặc chỉ hàng rào tre trong văn ngôn. | Mở khoá kiến thức | Biết 筚 giúp hiểu thành ngữ: 篳路藍縷 (tất lộ lam lũ — gian khổ khởi nghiệp).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary xác nhận 筚 là dạng giản thể của 篳, tra theo 篳. Chữ gốc 篳 chỉ hàng rào tre hoặc liếp tre. Nổi tiếng qua 篳路藍縷 (tất lộ lam lũ — vừa dùng xe tre vừa mặc áo rách — nói về gian khổ lập nghiệp). Xuất hiện trong tiểu triện. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nan tre", "Hạng Tần Suất (Jun Da)": "6350.0", "Tần Suất % (Jun Da)": "99.990792956", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 毕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮毕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "毕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "筚", "Unihan_Traditional (Chữ Phồn thể)": "篳", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "tất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ vật liệu tre nứa, thường dùng trong các từ ghép chỉ sự nghèo khó, giản dị. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('矻', '{"9000": "6351.0", "Chữ Trung Quốc": "矻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 8 | nét | 矻 | ngật | tượng hình | siêng năng cần cù, làm việc không ngừng — dùng trong 矻矻 | 矻 không có phân tích cấu trúc CHISE rõ ràng. Nhìn dạng chữ thấy bộ 石 (thạch, đá) — gợi ý sự cứng chắc, kiên trì. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngật\": bộ đá (石) — cứng như đá, không ngừng làm việc, ngật ngật siêng cần. | Gương Hán-Việt | \"ngật\" trong tiếng Việt: ít gặp riêng lẻ; 矻 chủ yếu trong văn ngôn. | Mở khoá kiến thức | Biết 矻 giúp đọc: 矻矻 (ngật ngật — siêng năng, chăm chỉ không ngừng), 孜孜矻矻 (cần cù bền bỉ).", "Tự nguyên_Xie": "Wiktionary xác nhận 矻 chỉ dùng trong 矻矻 — trạng từ chỉ sự siêng năng, chăm chỉ không ngừng. Không có phân tích cấu trúc chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: ngột ngột 矻矻)", "Hạng Tần Suất (Jun Da)": "6351.0", "Tần Suất % (Jun Da)": "99.9908069092", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 乞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石乞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "矻", "Unihan_Traditional (Chữ Phồn thể)": "矻", "Pinyin_Xie": "kū", "Âm Hán Việt_Xie": "khốt, ngột", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường dùng lặp lại thành ngật ngật để làm tính từ miêu tả trạng thái làm việc chăm chỉ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('搠', '{"9000": "6352.0", "Chữ Trung Quốc": "搠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 13 | nét | 搠 | sóc | tượng hình | đâm, xọc, đẩy mạnh — không có nguồn học thuật | 搠 không có dữ liệu nguồn gốc từ Wiktionary. Nhìn dạng chữ thấy bộ 手 (thủ, tay) — gợi ý hành động tay. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sóc\": bộ tay (扌) — hành động đâm sóc thẳng vào, đẩy mạnh một cái. | Gương Hán-Việt | \"sóc\" trong tiếng Việt: con sóc (sóc chuột), nhưng 搠 đặc chỉ hành động đâm. | Mở khoá kiến thức | Biết 搠 giúp đọc văn cổ chiến trận: hành động đâm thẳng bằng vũ khí.", "Tự nguyên_Xie": "Không có dữ liệu nguồn gốc từ Wiktionary cho chữ 搠. Chữ mang nghĩa đâm, xọc, đẩy mạnh (thrust, stab). Bộ 手 (扌, tay) rõ ràng gợi ý hành động tay. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đâm; gài, gắn, xen thêm; cầm, nắm", "Hạng Tần Suất (Jun Da)": "6352.0", "Tần Suất % (Jun Da)": "99.9908208624", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 朔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌朔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "朔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "搠", "Unihan_Traditional (Chữ Phồn thể)": "搠", "Pinyin_Xie": "shuò", "Âm Hán Việt_Xie": "sóc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường làm động từ biểu thị hành động đâm, chọc hoặc cắm vật gì đó vào. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('圉', '{"9000": "6353.0", "Chữ Trung Quốc": "圉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 囗 | Số nét | 11 | nét | 圉 | ngữ | tượng hình | nhà tù; người giữ ngựa — tượng hình từ giáp cốt văn | 圉 là chữ tượng hình: hình ảnh cái khung vây (囗) chứa một công cụ hạn chế tay (㚔) — biểu thị nhà tù. Trong nhiều giáp cốt văn còn thấy dạng gồm 囗+執, có thêm hình người quỳ bị trói buộc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngữ\": khung vây (囗) + người bị xiềng — ngục tù, nơi giam giữ người vi phạm. | Gương Hán-Việt | \"ngữ\" trong tiếng Việt thường gặp nghĩa ngôn ngữ (語); 圉 là chữ lịch sử chỉ nhà tù và người giữ ngựa. | Mở khoá kiến thức | Biết 圉 giúp đọc: 囹圄 (linh ngữ — nhà tù, ngục thất), 圉人 (người giữ ngựa).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Theo Wiktionary: 圉 là chữ tượng hình (liushu=p). Hình ảnh: khung vây (囗) chứa công cụ hạn chế tay (㚔) — nhà tù. Nhiều giáp cốt văn còn rõ hơn: 囗+執, thêm người quỳ bị trói. Chữ mở rộng nghĩa sang: người giữ ngựa, biên cương. Xuất hiện từ giáp cốt văn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tên bồi ngựa", "Hạng Tần Suất (Jun Da)": "6353.0", "Tần Suất % (Jun Da)": "99.9908348156", "GavinGrover_Once (Chiết tự trực tiếp)": "囗 + 幸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Bao quanh toàn bộ)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴囗幸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "幸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "囗", "Unihan_Simplified (Chữ Giản thể)": "圉", "Unihan_Traditional (Chữ Phồn thể)": "圉", "Pinyin_Xie": "yǔ", "Âm Hán Việt_Xie": "ngữ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ người chăn ngựa hoặc nơi nuôi ngựa, đôi khi làm động từ chỉ việc canh giữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('浍', '{"9000": "6354.0", "Chữ Trung Quốc": "浍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 9 | nét | 浍 | hội | tượng hình | ngòi nước, rãnh dẫn nước đồng ruộng | 浍 là chữ đơn thể, không phân tích được thành các thành phần rõ ràng trong hệ thống IDS. Chữ chỉ một con rãnh nhỏ dẫn nước ra đồng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hội\": dòng nước nhỏ hội tụ — hãy hình dung những con rãnh đồng gặp nhau tại một điểm. | Gương Hán-Việt | hội tụ — chữ 浍 gợi ý nghĩa tụ hợp nguồn nước nhỏ | Mở khoá kiến thức | Biết 浍 giúp nhận dạng các chữ liên quan đến hệ thống thủy lợi cổ đại Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | 浍 (dạng phồn thể 澮) có hai âm đọc: kuài chỉ mương rãnh đồng ruộng, Huì là tên riêng của sông Huihe chảy qua Hà Nam và An Huy. Chữ dùng trong thành ngữ 涓澮 (dòng chảy nhỏ). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái ngòi nhỏ, cái rãnh", "Hạng Tần Suất (Jun Da)": "6354.0", "Tần Suất % (Jun Da)": "99.9908487688", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 会", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵会", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "会", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "浍", "Unihan_Traditional (Chữ Phồn thể)": "澮", "Pinyin_Xie": "huì", "Âm Hán Việt_Xie": "quái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ các rãnh nước nhỏ dẫn nước ngoài đồng ruộng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蛸', '{"9000": "6355.0", "Chữ Trung Quốc": "蛸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 13 | nét | 虫 | trùng | biểu nghĩa | sâu bọ, côn trùng | 肖 | tiêu | biểu âm | giống, nhỏ | 蛸 = 虫 (Trùng, biểu nghĩa: côn trùng) + 肖 (Tiêu, biểu âm); chữ hình thanh. Bộ 虫 chỉ loại sinh vật, 肖 cho âm xiāo/shāo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiêu\" (từ bộ 肖): con trùng 虫 nhỏ bé tiêu điều — nhện chân dài đứng im như bóng. | Gương Hán-Việt | tiêu sao (蠨蛸) — tên gọi nhện chân dài trong văn cổ | Mở khoá kiến thức | Biết 蛸 giúp đọc các tên thuốc Đông y: 螵蛸 (hải phiêu tiêu) là vị thuốc từ trứng bọ ngựa.", "Tự nguyên_Xie": "Tiểu triện | 蛸 là chữ hình thanh: 虫 cho nghĩa (loài vật nhỏ), 肖 cho âm. Có ba âm đọc: xiāo dùng trong 螵蛸 (kén trứng bọ ngựa — vị thuốc Đông y), shāo dùng trong 蠨蛸 (nhện chân dài, họ Tetragnathidae), và shāo/xiāo chỉ bạch tuộc/mực. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: tiêu sao 蠨蛸,蟏蛸)", "Hạng Tần Suất (Jun Da)": "6355.0", "Tần Suất % (Jun Da)": "99.9908766752", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 肖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫肖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "肖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蛸", "Unihan_Traditional (Chữ Phồn thể)": "蛸", "Pinyin_Xie": "shāo", "Âm Hán Việt_Xie": "tiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ xuất hiện trong các từ ghép chỉ loài côn trùng hoặc vị thuốc đông y. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鮊', '{"9000": "6356.0", "Chữ Trung Quốc": "鮊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 16 | nét | 鮊 | bá | tượng hình | cá bạch điều, họ cá trắng sống ở sông Trung Quốc | 鮊 là chữ đơn thể chỉ tên một loài cá. Không phân tích được thành phần IDS rõ ràng trong cơ sở dữ liệu, chỉ thấy trong tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bá\": loài cá 鮊 trắng bạc vùng sông Trung Quốc — bá chiếm vùng nước như một tên bá chủ. | Gương Hán-Việt | bá ngư — từ cổ chỉ loài cá vùng nước ngọt | Mở khoá kiến thức | Biết 鮊 giúp nhận dạng tên cá trong văn bản ngư nghiệp và điển tích cổ Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | 鮊 (có thể đọc bó hoặc bà) là tên chỉ cá thuộc chi Culter (cá bạch điều, topmouth culter) và cá thu (Spanish mackerel). Chữ chỉ có dạng tiểu triện, không thấy trong giáp cốt hay kim văn, có thể là chữ tạo muộn. | Theo Wiktionary · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "銊", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 白", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚白", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "白", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鮊", "Unihan_Traditional (Chữ Phồn thể)": "鮊", "Pinyin_Xie": "bà", "Âm Hán Việt_Xie": "bá", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ dùng trong tên gọi của các loài cá nước ngọt cụ thể. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('芘', '{"9000": "6357.0", "Chữ Trung Quốc": "芘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 7 | nét | 芘 | bí | tượng hình | loài cây thuộc họ thực vật, có thể là cây cẩm quỳ hoặc cây tương tự | 芘 là chữ đơn thể thuộc bộ 艸 (cỏ), không phân tích thành các thành phần IDS trong dữ liệu. Chữ chỉ tên thực vật cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bí\": cỏ 艸 che bí — như tán lá cây bí che phủ mặt đất, đó là nghĩa che chở (庇) liên hệ đến âm bì. | Gương Hán-Việt | bí thảo — tên gọi cổ một loại cây trong thảo học Trung Quốc | Mở khoá kiến thức | Biết 芘 giúp đọc các bản thảo dược cổ Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | 芘 có hai âm: pí dùng trong 芘芣 (tên cây thực vật cổ, có thể là cây mã đề 車前草); bì là dạng thay thế của 庇 (che chở). Chữ chủ yếu xuất hiện trong văn bản thực vật cổ Trung Quốc. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cẩm quỳ; cây hoa quỳ tím", "Hạng Tần Suất (Jun Da)": "6357.0", "Tần Suất % (Jun Da)": "99.9909459244", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 比", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹比", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "比", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "芘", "Unihan_Traditional (Chữ Phồn thể)": "芘", "Pinyin_Xie": "pí", "Âm Hán Việt_Xie": "tỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ thực vật hoặc động từ với nghĩa che chở trong văn ngôn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('萜', '{"9000": "6358.0", "Chữ Trung Quốc": "萜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 萜 | thiếp | tượng hình | terpene — nhóm hợp chất hữu cơ trong hóa học | 萜 là chữ tạo muộn dùng trong hóa học hiện đại để phiên âm thuật ngữ \"terpene\" (tiếng Anh). Không có nguồn giáp cốt hay kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiếp\": cỏ 艸 thuần terpene — chữ tạo mới cho ngành hóa học, bộ 艸 chỉ nguồn gốc thực vật của phần lớn terpene. | Gương Hán-Việt | thiếp — chữ chuyên dùng trong hóa học hữu cơ | Mở khoá kiến thức | Biết 萜 giúp đọc các tài liệu hóa học hữu cơ về terpene và các hợp chất thiên nhiên.", "Tự nguyên_Xie": "萜 là chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chữ được tạo ra trong thời hiện đại để phiên dịch thuật ngữ hóa học \"terpene\" (C5H8) — nhóm hợp chất hydrocacbon đơn vị isoprene. Chưa có nguồn học thuật về cấu trúc glyph. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tecpen, đipenten (hoá học)", "Hạng Tần Suất (Jun Da)": "6358.0", "Tần Suất % (Jun Da)": "99.9909593609", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 帖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹帖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "帖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "萜", "Unihan_Traditional (Chữ Phồn thể)": "萜", "Pinyin_Xie": "tiē", "Âm Hán Việt_Xie": "thiếp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chuyên ngành hóa học để chỉ nhóm hợp chất tecpen. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鄗', '{"9000": "6359.0", "Chữ Trung Quốc": "鄗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 12 | nét | 鄗 | hạo | tượng hình | tên huyện cổ ở Hà Bắc (nay là Bách Hương), cũng là dạng thay thế của 鎬 (kinh đô nhà Chu) | 鄗 là chữ chỉ địa danh, thuộc bộ 邑 (ấp/đô thị). Không phân tích được thành phần IDS rõ ràng trong dữ liệu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt (không có âm chuẩn): tên đất 鄗 — huyện Hạo ở Hà Bắc, dấu tích kinh đô Hạo Kinh nhà Chu. | Gương Hán-Việt | Hạo Kinh — kinh đô tây của nhà Chu, địa danh lịch sử quan trọng | Mở khoá kiến thức | Biết 鄗 giúp đọc lịch sử địa lý cổ đại Trung Quốc và địa danh nhà Chu.", "Tự nguyên_Xie": "Tiểu triện | 鄗 là địa danh chỉ huyện Hạo ở tỉnh Hà Bắc, nay là huyện Bách Hương (柏鄉). Chữ cũng là dạng thay thế của 鎬 (Hạo — kinh đô của nhà Chu tây ở Thiểm Tây). Dạng tiểu triện còn lưu lại. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Hạo (tên huyện cổ, nay là huyện Bách Hương, tỉnh Hà Bắc, Trung Quốc.)", "Hạng Tần Suất (Jun Da)": "6359.0", "Tần Suất % (Jun Da)": "99.9909727973", "GavinGrover_Once (Chiết tự trực tiếp)": "高 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰高阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "阝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "高", "Unihan_Simplified (Chữ Giản thể)": "鄗", "Unihan_Traditional (Chữ Phồn thể)": "鄗", "Pinyin_Xie": "hào", "Âm Hán Việt_Xie": "hạo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ riêng chỉ địa danh cổ trong lịch sử Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('惝', '{"9000": "6360.0", "Chữ Trung Quốc": "惝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 11 | nét | 惝 | sượng | tượng hình | tâm trạng lo âu, chán nản, thất vọng | 惝 là chữ thuộc bộ 心 (tâm, lòng), nhưng không có phân tích IDS rõ ràng trong dữ liệu. Không có nguồn Wiktionary glyph-origin. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sượng\": lòng 心 cảm thấy sượng sùng — trạng thái khó chịu, không thoải mái trong lòng. | Gương Hán-Việt | sượng sùng — cảm giác ngại ngùng, xấu hổ hay bất an trong tiếng Việt | Mở khoá kiến thức | Biết 惝 giúp đọc văn học cổ Trung Quốc mô tả trạng thái tâm lý mơ hồ, hoang mang.", "Tự nguyên_Xie": "惝 không có nguồn Wiktionary glyph-origin. Thuộc bộ 心 (tâm), chỉ trạng thái tâm lý: lo âu, chán nản, hoảng hốt. Thường xuất hiện trong cặp 惝恍 (mơ màng, không rõ ràng) hoặc 惝怳 (hoảng hốt). Chưa có nguồn học thuật về cấu trúc glyph. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngã lòng", "Hạng Tần Suất (Jun Da)": "6360.0", "Tần Suất % (Jun Da)": "99.9909862337", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 尚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄尚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "惝", "Unihan_Traditional (Chữ Phồn thể)": "惝", "Pinyin_Xie": "chǎng", "Âm Hán Việt_Xie": "thảng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ miêu tả trạng thái tinh thần buồn bã hoặc ngơ ngác. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('毵', '{"9000": "6361.0", "Chữ Trung Quốc": "毵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 毛 | Số nét | 12 | nét | 毵 | sam | tượng hình | lông dài, lông xù xì, bộ lông rối bời | 毵 thuộc bộ 毛 (lông, tóc), chỉ bộ lông dài và không gọn gàng. Không có phân tích IDS chi tiết trong dữ liệu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sam\": bộ lông 毛 xù sam sao — lông vũ dài và rối bời như cây cỏ mọc hoang. | Gương Hán-Việt | sam — từ ít dùng, xuất hiện trong miêu tả lông thú/chim trong văn học cổ | Mở khoá kiến thức | Biết 毵 giúp đọc mô tả ngoại hình chim thú trong thơ văn cổ điển Trung Quốc.", "Tự nguyên_Xie": "毵 (dạng thay thế 毿) là chữ chỉ lông vũ dài, bộ lông rối bời, xù xì. Wiktionary ghi nhận âm sān, có thể liên quan đến bộ 毛 (lông). Dùng trong 毿毿 (lông xù xì) và 㲯毿. Không có nguồn glyph-origin học thuật chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lông dài", "Hạng Tần Suất (Jun Da)": "6361.0", "Tần Suất % (Jun Da)": "99.9909996701", "GavinGrover_Once (Chiết tự trực tiếp)": "参 + 毛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰参毛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "参", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "毛", "Unihan_Simplified (Chữ Giản thể)": "毵", "Unihan_Traditional (Chữ Phồn thể)": "毿", "Pinyin_Xie": "sān", "Âm Hán Việt_Xie": "tam", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ miêu tả trạng thái lông chim hoặc tóc người dài và rủ xuống. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲽', '{"9000": "6362.0", "Chữ Trung Quốc": "鲽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 17 | nét | 魚 | ngư | biểu nghĩa | cá | 枼 | diệp | biểu âm | lá mỏng, tấm phẳng | 鲽 = 魚 (Ngư, biểu nghĩa: cá) + 枼 (Diệp, biểu âm); chữ hình thanh. Bộ 魚 chỉ loài cá, 枼 cho âm và gợi hình dạng dẹt như lá.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điệp\": cá 魚 dẹt như lá 枼 — cá bơn dẹp lép nằm trên đáy biển như tờ lá mỏng. | Gương Hán-Việt | điệp ngư — cá bơn, cá dẹt trong văn học hải sản Trung Quốc | Mở khoá kiến thức | Biết 鲽 giúp đọc các bản thực đơn hải sản và tài liệu ngư nghiệp Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 鲽 (phồn thể 鰈) là chữ hình thanh: 魚 (cá) cho nghĩa, 枼 (tấm dẹt như lá) cho âm. Chỉ cá dẹt họ bơn (flatfish/flounder/sole). Hình ảnh \"lá\" của 枼 phù hợp với thân hình dẹt đặc trưng của họ cá này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá điệp, cá bơn", "Hạng Tần Suất (Jun Da)": "6362.0", "Tần Suất % (Jun Da)": "99.9910131065", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 枼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼枼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "枼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲽", "Unihan_Traditional (Chữ Phồn thể)": "鰈", "Pinyin_Xie": "dié", "Âm Hán Việt_Xie": "điệp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loại cá thân bẹt sống ở đáy biển. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('酞', '{"9000": "6363.0", "Chữ Trung Quốc": "酞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 11 | nét | 酉 | dậu | biểu nghĩa | bình rượu, gốc hóa học | 太 | thái | biểu âm | lớn, quá mức | 酞 = 酉 (Dậu, biểu nghĩa: gốc hóa học/dung dịch) + 太 (Thái, biểu âm); chữ hình thanh dùng trong hóa học hiện đại để phiên âm \"phthalein\".", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thái\" (từ 太): dung dịch 酉 thái quá — phenolphthalein đổi màu hồng thái quá khi kiềm. | Gương Hán-Việt | thái — chữ chuyên dùng trong hóa học hữu cơ | Mở khoá kiến thức | Biết 酞 giúp đọc tài liệu hóa học hữu cơ về phthalein và các chỉ thị màu.", "Tự nguyên_Xie": "酞 là chữ hình thanh: 酉 (bình rượu, dùng làm bộ hóa học) cho nghĩa, 太 cho âm tài. Chữ được tạo ra trong thời hiện đại để dịch thuật ngữ hóa học \"phthalein\" — nhóm hợp chất tạo màu được dùng làm chỉ thị pH. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phtalêin (hoá học)", "Hạng Tần Suất (Jun Da)": "6363.0", "Tần Suất % (Jun Da)": "99.9910265429", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 太", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉太", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "太", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "酞", "Unihan_Traditional (Chữ Phồn thể)": "酞", "Pinyin_Xie": "tài", "Âm Hán Việt_Xie": "thái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong hóa học để chỉ nhóm hợp chất hữu cơ phthalin. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('哚', '{"9000": "6364.0", "Chữ Trung Quốc": "哚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 9 | nét | 哚 | đoá | tượng hình | indole — hợp chất hữu cơ vòng thơm trong hóa học | 哚 là chữ tạo muộn dùng trong hóa học để phiên âm tiếng Anh \"indole\". Thuộc bộ 口, không phân tích IDS được từ dữ liệu. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đoá\": miệng 口 nói đoá — indole có mùi hoa jasmine ở nồng độ thấp, nồng độ cao thì hôi. | Gương Hán-Việt | đoá — chữ chuyên dùng trong hóa học hữu cơ | Mở khoá kiến thức | Biết 哚 giúp đọc tài liệu hóa học hữu cơ về indole và các dẫn xuất.", "Tự nguyên_Xie": "哚 là chữ tạo muộn trong hóa học hiện đại, dùng để phiên âm \"indole\" (indol — vòng thơm N-heterocyclic, C8H7N). Không có nguồn Wiktionary glyph-origin. Chưa có nguồn học thuật về lịch sử chữ này. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "In-đô (indole)", "Hạng Tần Suất (Jun Da)": "6364.0", "Tần Suất % (Jun Da)": "99.9910534157", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 朵", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口朵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "朵", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "哚", "Unihan_Traditional (Chữ Phồn thể)": "哚", "Pinyin_Xie": "duǒ", "Âm Hán Việt_Xie": "đóa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong hóa học, chủ yếu xuất hiện trong từ ghép chỉ hợp chất hữu cơ dị vòng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('溷', '{"9000": "6365.0", "Chữ Trung Quốc": "溷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 13 | nét | 溷 | hỗn | tượng hình | chuồng xí, nhà tiêu; dơ bẩn, rối loạn | 溷 thuộc bộ 水 (nước) nhưng không có phân tích IDS rõ ràng trong dữ liệu. Chữ chỉ nơi dơ bẩn, chuồng xí.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hỗn\": nước 水 dơ hỗn loạn — chuồng xí hỗn độn, nơi mọi thứ lẫn lộn dơ bẩn. | Gương Hán-Việt | hỗn loạn, hỗn tạp — chữ 溷 cổ đại gợi ý sự lộn xộn bùn lầy | Mở khoá kiến thức | Biết 溷 giúp đọc thơ văn cổ Trung Quốc dùng hình ảnh chuồng xí và số phận con người.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 溷 có nghĩa là chuồng lợn, nhà vệ sinh, bùn lầy, hỗn loạn. Thuộc bộ 水 (nước), gợi ý môi trường ẩm ướt dơ bẩn. Thành ngữ 飄茵落溷 (rơi lên nệm êm hay rơi xuống cống rãnh — tùy số phận) là câu dùng 溷 nổi tiếng nhất. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chuồng xí, nhà tiêu; rối loạn; chuồng nhốt thú", "Hạng Tần Suất (Jun Da)": "6365.0", "Tần Suất % (Jun Da)": "99.9910668522", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 圂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵圂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "圂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "溷", "Unihan_Traditional (Chữ Phồn thể)": "溷", "Pinyin_Xie": "hùn", "Âm Hán Việt_Xie": "hỗn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm tính từ chỉ sự bẩn thỉu, đục ngầu hoặc danh từ chỉ nhà vệ sinh trong văn ngôn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缞', '{"9000": "6366.0", "Chữ Trung Quốc": "缞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 13 | nét | 缞 | thôi | tượng hình | áo sô gai mặc khi chịu tang, phần trước ngực | 缞 thuộc bộ 糸 (tơ, vải), chỉ loại áo tang làm từ vải thô. Không có phân tích IDS chi tiết từ dữ liệu và không có nguồn Wiktionary glyph-origin.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thôi\": vải 糸 thô ráp thôi thúc nỗi đau — áo tang sô gai mặc để bày tỏ thương tiếc. | Gương Hán-Việt | thôi — trong tang lễ cổ Trung Quốc, 缞 là loại tang phục quan trọng | Mở khoá kiến thức | Biết 缞 giúp đọc các điển tịch lễ nghi tang chế Trung Quốc cổ đại.", "Tự nguyên_Xie": "Tiểu triện | 缞 không có nguồn Wiktionary glyph-origin. Thuộc bộ 糸 (tơ/vải), chỉ loại áo tang thô nhám (sackcloth) mặc để kẻ nhà có tang. Trong lễ nhạc tang chế cổ Trung Quốc, cấp độ và thời hạn tang phục tương ứng với mức độ quan hệ huyết thống. Chưa có nguồn học thuật về glyph. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "áo sô, áo tang", "Hạng Tần Suất (Jun Da)": "6366.0", "Tần Suất % (Jun Da)": "99.9910802886", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 衰", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟衰", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "衰", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "缞", "Unihan_Traditional (Chữ Phồn thể)": "縗", "Pinyin_Xie": "cuī", "Âm Hán Việt_Xie": "thôi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ trang phục tang lễ bằng vải sô thô thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('踰', '{"9000": "6367.0", "Chữ Trung Quốc": "踰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 16 | nét | 足 | túc | biểu nghĩa | chân, bàn chân | 俞 | du | biểu âm | vượt, thuận | 踰 = 足 (Túc, biểu nghĩa: chân) + 俞 (Du, biểu âm); chữ hình thanh. Chân bước qua — hành động vượt qua ranh giới.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"du\": chân 足 du lịch vượt ranh — dùng đôi chân vượt qua giới hạn, như du mục không biên cương. | Gương Hán-Việt | du — ít gặp trong từ Hán-Việt hiện đại, nhưng xuất hiện trong 踰矩 (vượt khỏi khuôn phép) | Mở khoá kiến thức | Biết 踰 giúp đọc văn học và luật pháp cổ Trung Quốc về vượt giới hạn, vi phạm quy tắc.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 踰 là chữ hình thanh: 足 (chân) cho nghĩa, 俞 cho âm. Nghĩa gốc là bước qua, vượt qua (ranh giới, hàng rào, giới hạn). Mở rộng sang vượt quá, lớn hơn, vượt ngưỡng. Có dạng tiểu triện và Lục thư thông. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "qua", "Hạng Tần Suất (Jun Da)": "2605.0", "Tần Suất % (Jun Da)": "98.6739846405", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 俞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊俞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "俞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "逾", "Unihan_Traditional (Chữ Phồn thể)": "踰", "Pinyin_Xie": "yú", "Âm Hán Việt_Xie": "du", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ chỉ hành động vượt qua giới hạn, ranh giới hoặc thời gian. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('搦', '{"9000": "6368.0", "Chữ Trung Quốc": "搦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 13 | nét | 搦 | nặc | tượng hình | nắm bắt, bóp chặt, xoa bóp | 搦 thuộc bộ 手 (tay), chỉ hành động dùng tay nắm bắt. Dữ liệu Wiktionary chỉ ghi {{Han etym}} mà không có phân tích chi tiết hơn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nặc\": tay 手 nặc nặc bắt giữ — hình ảnh bàn tay nắm chặt không thả ra. | Gương Hán-Việt | nặc — ít gặp trong từ Hán-Việt hiện đại, chủ yếu trong văn bản cổ | Mở khoá kiến thức | Biết 搦 giúp đọc văn bản võ thuật và pháp luật cổ Trung Quốc về bắt giữ tội phạm.", "Tự nguyên_Xie": "Tiểu triện | 搦 thuộc bộ 手 (tay), chỉ hành động nắm, bắt giữ, bóp chặt. Wiktionary chỉ ghi nhận nguồn gốc Han etymological mà không cung cấp phân tích chi tiết cấu trúc chữ. Có dạng tiểu triện. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bắt giữ; quắp, cầm; xoa bóp", "Hạng Tần Suất (Jun Da)": "6368.0", "Tần Suất % (Jun Da)": "99.9911071614", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 弱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌弱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "弱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "搦", "Unihan_Traditional (Chữ Phồn thể)": "搦", "Pinyin_Xie": "nuò", "Âm Hán Việt_Xie": "nạch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ chỉ hành động cầm nắm chặt bằng tay hoặc khiêu khích. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('帻', '{"9000": "6369.0", "Chữ Trung Quốc": "帻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 巾 | Số nét | 11 | nét | 帻 | trách | tượng hình | khăn vén tóc, mũ lưỡi trai nhỏ đội đầu | 帻 thuộc bộ 巾 (vải, khăn), chỉ loại khăn đầu hay mũ nhỏ dùng để vén tóc. Không có phân tích IDS chi tiết trong dữ liệu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trách\": vải 巾 cuốn trách nhiệm trên đầu — khăn đội đầu trong xã hội cổ đại phản ánh địa vị xã hội. | Gương Hán-Việt | trách — xuất hiện trong miêu tả trang phục trong thơ văn Đường, Tống | Mở khoá kiến thức | Biết 帻 giúp đọc mô tả trang phục trong thơ văn cổ Trung Quốc và truyện lịch sử.", "Tự nguyên_Xie": "Tiểu triện | 帻 (phồn thể 幘) thuộc bộ 巾 (vải, khăn), chỉ loại khăn đầu hoặc mũ lưỡi trai nhỏ dùng để vén tóc. Trong thơ văn cổ xuất hiện nhiều kiểu: 岸幘 (mũ đội ngả sau — phong thái tự do), 綠幘 (khăn xanh — người hèn mọn). Dạng tiểu triện còn lưu lại. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái khăn vén tóc", "Hạng Tần Suất (Jun Da)": "6369.0", "Tần Suất % (Jun Da)": "99.9911205978", "GavinGrover_Once (Chiết tự trực tiếp)": "巾 + 责", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰巾责", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "责", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "巾", "Unihan_Simplified (Chữ Giản thể)": "帻", "Unihan_Traditional (Chữ Phồn thể)": "幘", "Pinyin_Xie": "zé", "Âm Hán Việt_Xie": "trách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ loại khăn hoặc mũ quấn đầu của nam giới thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铦', '{"9000": "6370.0", "Chữ Trung Quốc": "铦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 11 | nét | 金 | kim | biểu nghĩa | kim loại | 甜 | điềm | biểu âm | ngọt | 铦 = 金 (Kim, biểu nghĩa: kim loại) + 甜 (Điềm, biểu âm); chữ hình thanh. Vũ khí hay nông cụ sắc bén bằng kim loại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiêm\": kim 金 sắc tiêm nhọn — vũ khí sắc bén như mũi kim đâm xuyên. | Gương Hán-Việt | tiêm — xuất hiện trong miêu tả vũ khí và nông cụ sắc bén | Mở khoá kiến thức | Biết 铦 giúp đọc tài liệu vũ khí và nông cụ cổ đại Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | 铦 (phồn thể 銛) là chữ hình thanh: 金 (kim loại) cho nghĩa, 甜 rút gọn cho âm. Nghĩa là sắc bén, cũng chỉ loại cuốc hay vũ khí bằng kim loại sắc bén. Có dạng tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vũ khí sắc bén; cái xiên cá", "Hạng Tần Suất (Jun Da)": "6370.0", "Tần Suất % (Jun Da)": "99.9911340342", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 舌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅舌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "舌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铦", "Unihan_Traditional (Chữ Phồn thể)": "銛", "Pinyin_Xie": "xiān", "Âm Hán Việt_Xie": "tiêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ để miêu tả vũ khí sắc bén hoặc danh từ chỉ nông cụ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲴', '{"9000": "6371.0", "Chữ Trung Quốc": "鲴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 16 | nét | 鲴 | cố | tượng hình | cá vảy trắng bạc, cá shovel-jaw carp sông Đài Loan | 鲴 (phồn thể 鯝) thuộc bộ 魚 (cá), chỉ loài cá trắng. Không có phân tích IDS chi tiết trong dữ liệu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cố\": cá 魚 bạc trắng cố thủ — cá trắng bám chặt đáy sông như kẻ cố thủ không chịu rời. | Gương Hán-Việt | cố ngư — cá trắng sông nước ngọt Trung Quốc | Mở khoá kiến thức | Biết 鲴 giúp đọc tài liệu ngư nghiệp và điển tích cổ Trung Quốc về các loài cá nước ngọt.", "Tự nguyên_Xie": "鲴 (phồn thể 鯝) là tên cá vảy trắng bạc, đặc biệt là Taiwan shovel-jaw carp (Onychostoma barbatulum). Nghĩa cổ điển là lòng cá. Wiktionary ghi nhận có nguồn gốc Han etymological nhưng không có glyph-origin chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá trắng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 固", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼固", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "固", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲴", "Unihan_Traditional (Chữ Phồn thể)": "鲴", "Pinyin_Xie": "gù", "Âm Hán Việt_Xie": "ngư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ để chỉ một loài cá nước ngọt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('髫', '{"9000": "6372.0", "Chữ Trung Quốc": "髫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 髟 | Số nét | 15 | nét | 髫 | điêu | tượng hình | tóc trái đào, tóc rủ xuống trước mặt của trẻ em | 髫 thuộc bộ 髟 (tóc rũ dài), chỉ kiểu tóc truyền thống của trẻ em thời cổ đại — tóc buộc rủ xuống hai bên hay trước trán. Không có phân tích IDS chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điêu\": tóc 髟 điêu khắc tuổi thơ — 垂髫 là hình ảnh con trẻ tóc rủ ngây thơ trong thơ cổ. | Gương Hán-Việt | điêu — xuất hiện trong cụm 垂髫 chỉ tuổi thơ trong thơ văn Đào Uyên Minh và cổ điển Trung Quốc | Mở khoá kiến thức | Biết 髫 giúp đọc thơ Đào Uyên Minh và văn học cổ Trung Quốc mô tả tuổi thơ.", "Tự nguyên_Xie": "Tiểu triện | 髫 thuộc bộ 髟 (tóc dài), chỉ kiểu tóc trái đào của trẻ em trong xã hội Trung Quốc cổ đại. 垂髫 là thành ngữ chỉ tuổi thơ (thời còn để tóc rủ). Dạng tiểu triện còn lưu lại. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tóc trái đào", "Hạng Tần Suất (Jun Da)": "6372.0", "Tần Suất % (Jun Da)": "99.9911609071", "GavinGrover_Once (Chiết tự trực tiếp)": "髟 + 召", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱髟召", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "召", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "髟", "Unihan_Simplified (Chữ Giản thể)": "髫", "Unihan_Traditional (Chữ Phồn thể)": "髫", "Pinyin_Xie": "tiáo", "Âm Hán Việt_Xie": "thiều", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, thường dùng trong văn cổ để chỉ trẻ thơ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('醡', '{"9000": "6373.0", "Chữ Trung Quốc": "醡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 17 | nét | 醡 | trà | tượng hình | máy ép rượu, dụng cụ ép nho/hoa quả để lấy nước | 醡 thuộc bộ 酉 (bình rượu, liên quan đến lên men), chỉ dụng cụ ép rượu. Không có phân tích IDS chi tiết trong dữ liệu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trà\": rượu 酉 ép trà lấy nước — máy ép rượu hoạt động bằng cách nén chặt nho lấy dịch. | Gương Hán-Việt | trà — ít gặp trong từ Hán-Việt hiện đại, xuất hiện trong từ điển cổ học | Mở khoá kiến thức | Biết 醡 giúp đọc tài liệu về kỹ thuật làm rượu và ẩm thực cổ đại Trung Quốc.", "Tự nguyên_Xie": "醡 thuộc bộ 酉 (bình rượu), chỉ máy ép rượu hoặc hành động ép rượu. Wiktionary dẫn nguồn 窄 làm tham chiếu gốc, gợi ý liên hệ với ý nghĩa \"hẹp, nén chặt\". Không có nguồn glyph-origin học thuật chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đồ ép rượu; ép rượu", "Hạng Tần Suất (Jun Da)": "6373.0", "Tần Suất % (Jun Da)": "99.991254962", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 窄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉窄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "窄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "醡", "Unihan_Traditional (Chữ Phồn thể)": "醡", "Pinyin_Xie": "zhà", "Âm Hán Việt_Xie": "trá", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ máy ép hoặc làm động từ chỉ hành động ép nước, ép rượu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('儇', '{"9000": "6374.0", "Chữ Trung Quốc": "儇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 15 | nét | 儇 | huyên | tượng hình | thông minh và khinh bạc, nhanh nhẹn nhưng không đứng đắn | 儇 thuộc bộ 人 (người), chỉ tính cách con người. Không có phân tích IDS chi tiết trong dữ liệu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huyên\": người 人 huyên láo thông minh — thông minh nhưng huyên thuyên, khôn lanh nhưng thiếu trầm tĩnh. | Gương Hán-Việt | huyên — xuất hiện trong miêu tả tính cách trong văn học cổ Trung Quốc | Mở khoá kiến thức | Biết 儇 giúp đọc mô tả tính cách phức tạp trong văn học cổ điển Trung Quốc.", "Tự nguyên_Xie": "儇 thuộc bộ 人 (người), chỉ người thông minh nhưng khinh bạc, nhanh nhẹn nhưng không nghiêm túc. Trong các phương ngữ Ôn Châu, Ninh Ba, 儇 còn có nghĩa là trẻ em ngoan ngoãn, nghe lời. Wiktionary ghi nhận có nguồn gốc Han etymological. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thông minh và khinh bạc; gian nịnh", "Hạng Tần Suất (Jun Da)": "6374.0", "Tần Suất % (Jun Da)": "99.9912678816", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 睘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻睘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "睘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "儇", "Unihan_Traditional (Chữ Phồn thể)": "儇", "Pinyin_Xie": "xuān", "Âm Hán Việt_Xie": "huyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ đứng trước danh từ hoặc sau phó từ chỉ mức độ để miêu tả tính cách. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('狴', '{"9000": "6375.0", "Chữ Trung Quốc": "狴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 10 | nét | 犬 | khuyển | biểu nghĩa | chó, chó dữ | 坒 | bĩ | biểu âm | so sánh, kề sát | 狴 = 犬 (Khuyển, biểu nghĩa: chó) + 坒 (Bĩ, biểu âm); chữ hình thanh. Loài thú dữ huyền thoại hình dạng giống hổ/chó.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tì\": thú 犬 dữ tì tì — con thú huyền thoại đứng canh cửa ngục, uy dữ không nhân nhượng. | Gương Hán-Việt | tì — trong văn hóa rồng Trung Quốc, 狴犴 là biểu tượng công lý và nhà giam | Mở khoá kiến thức | Biết 狴 giúp đọc thần thoại và văn hóa dân gian về chín con rồng Trung Quốc.", "Tự nguyên_Xie": "Lục thư thông | 狴 là chữ hình thanh: 犬 (chó) cho nghĩa, 坒 cho âm. Chỉ loài thú huyền thoại Trung Quốc (tương truyền là con thứ tám của rồng), hình dạng như hổ, ưa tranh tụng, nên hình được vẽ trên cửa nhà ngục. Mở rộng nghĩa sang nhà ngục (狴牢, 狴犴). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(một giống thú)", "Hạng Tần Suất (Jun Da)": "6375.0", "Tần Suất % (Jun Da)": "99.9912808012", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 坒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭坒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "坒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "狴", "Unihan_Traditional (Chữ Phồn thể)": "狴", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "bệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, thường kết hợp thành từ ghép bệ ngạn để chỉ nhà giam. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('迮', '{"9000": "6376.0", "Chữ Trung Quốc": "迮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 8 | nét | 迮 | trách | tượng hình | ép buộc, hẹp hòi; họ Trách | 迮 thuộc bộ 辵 (đi lại), chỉ sự chật hẹp, bị ép buộc. Không có phân tích IDS chi tiết trong dữ liệu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trách\": đường 辵 trách nhiệm hẹp — con đường hẹp ép buộc phải đi thẳng, không có lối thoát. | Gương Hán-Việt | trách — họ người và từ cổ chỉ sự hẹp hòi trong văn học cổ đại | Mở khoá kiến thức | Biết 迮 giúp đọc văn bản cổ Trung Quốc mô tả địa thế hẹp hay tâm lý bức bách.", "Tự nguyên_Xie": "Tiểu triện | 迮 thuộc bộ 辵 (đi lại), chỉ trạng thái hẹp hòi, bị ép buộc, vội vã. Có các nghĩa: ép buộc, hẹp, vội vàng. Cũng là họ 迮. Dạng tiểu triện còn lưu lại. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hẹp; hẹp hòi; họ Trách", "Hạng Tần Suất (Jun Da)": "6376.0", "Tần Suất % (Jun Da)": "99.9912937208", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 乍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶乍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "迮", "Unihan_Traditional (Chữ Phồn thể)": "迮", "Pinyin_Xie": "zé", "Âm Hán Việt_Xie": "trách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này làm tính từ để miêu tả không gian chật hẹp hoặc trạng thái vội vàng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('趱', '{"9000": "6377.0", "Chữ Trung Quốc": "趱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 走 | Số nét | 23 | nét | 趱 | toản | tượng hình | chạy nhanh, vội vàng, thúc giục | 趱 (phồn thể 趲) thuộc bộ 走 (đi, chạy), chỉ hành động chạy nhanh hoặc thúc giục người khác tiến bước. Không có phân tích IDS chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"toản\": chân 走 chạy toản loạn — toản (vội) chạy cho nhanh, không để trễ mà mắc họa. | Gương Hán-Việt | toản — ít gặp trong Hán-Việt hiện đại, xuất hiện trong tiểu thuyết cổ điển như Thủy Hử | Mở khoá kiến thức | Biết 趱 giúp đọc tiểu thuyết cổ điển Trung Quốc như Thủy Hử, Tam Quốc mô tả cảnh hành quân.", "Tự nguyên_Xie": "趱 (phồn thể 趲) thuộc bộ 走 (chạy), chỉ hành động chạy nhanh hay thúc giục tiến lên. Wiktionary ghi nhận có nguồn gốc Han etymological. Chủ yếu xuất hiện trong văn học cổ và tiểu thuyết cổ điển. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chạy", "Hạng Tần Suất (Jun Da)": "6377.0", "Tần Suất % (Jun Da)": "99.9913195601", "GavinGrover_Once (Chiết tự trực tiếp)": "走 + 赞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴走赞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "赞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "走", "Unihan_Simplified (Chữ Giản thể)": "趱", "Unihan_Traditional (Chữ Phồn thể)": "趲", "Pinyin_Xie": "zǎn", "Âm Hán Việt_Xie": "toản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước động từ chỉ sự di chuyển để biểu thị việc đi nhanh hơn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('椠', '{"9000": "6378.0", "Chữ Trung Quốc": "椠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 12 | nét | 椠 | thiểm | tượng hình | bản gỗ để viết, bản khắc in sách, lá thư | 椠 (phồn thể 槧) thuộc bộ 木 (gỗ), chỉ tấm gỗ dùng để viết hoặc khắc chữ trước khi có giấy. Không có phân tích IDS chi tiết trong dữ liệu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiểm\": gỗ 木 thiểm mỏng để viết — trước khi có giấy, người Trung Quốc dùng tấm gỗ mỏng như giấy thiểm để ghi chép. | Gương Hán-Việt | thiểm — xuất hiện trong nghiên cứu sách cổ và lịch sử xuất bản Trung Quốc | Mở khoá kiến thức | Biết 椠 giúp đọc tài liệu nghiên cứu văn bản học và lịch sử xuất bản cổ Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 椠 (phồn thể 槧) thuộc bộ 木 (gỗ), chỉ loại bảng gỗ mỏng dùng làm vật liệu viết chữ thời cổ đại, sau mở rộng sang bản in, bản ấn hành sách và thư từ. Có dạng tiểu triện và Lục thư thông. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bản gỗ để viết; bản in (hay bản dịch) sách; thư từ", "Hạng Tần Suất (Jun Da)": "6378.0", "Tần Suất % (Jun Da)": "99.9913324797", "GavinGrover_Once (Chiết tự trực tiếp)": "斩 + 木", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱斩木", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "斩", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "椠", "Unihan_Traditional (Chữ Phồn thể)": "槧", "Pinyin_Xie": "qiàn", "Âm Hán Việt_Xie": "thiễm, tạm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn viết cổ để chỉ sách vở hoặc thư từ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('赟', '{"9000": "6379.0", "Chữ Trung Quốc": "赟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 16 | nét | 赟 | vân | tượng hình | tốt đẹp, dễ thương, đáng yêu; tên người | 赟 (giản thể, phồn thể là 贇) thuộc bộ 貝 (vật quý giá), chỉ phẩm chất tốt đẹp. Không có phân tích IDS chi tiết. Wiktionary ghi nhận là giản thể của 贇.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vân\": của quý 貝 vân mây đẹp — tên đẹp như mây bay, thường dùng đặt tên con gái. | Gương Hán-Việt | vân — phổ biến trong tên người, ít gặp trong từ ghép thông thường | Mở khoá kiến thức | Biết 赟 giúp nhận dạng tên người Trung Quốc hiện đại sử dụng chữ chỉ vẻ đẹp và phẩm chất tốt.", "Tự nguyên_Xie": "赟 là dạng giản thể của 贇, thuộc bộ 貝 (của cải, vật quý). Chỉ phẩm chất tốt đẹp, dễ thương. Chủ yếu dùng làm tên người, đặc biệt phổ biến trong tên người Trung Quốc hiện đại. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tốt đẹp", "Hạng Tần Suất (Jun Da)": "6379.0", "Tần Suất % (Jun Da)": "99.9913453993", "GavinGrover_Once (Chiết tự trực tiếp)": "斌 + 贝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱斌贝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "斌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "贝", "Unihan_Simplified (Chữ Giản thể)": "赟", "Unihan_Traditional (Chữ Phồn thể)": "贇", "Pinyin_Xie": "yūn", "Âm Hán Việt_Xie": "uân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chủ yếu dùng làm tính từ trong văn cổ hoặc làm danh từ riêng đặt tên người. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('陔', '{"9000": "6380.0", "Chữ Trung Quốc": "陔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 8 | nét | 陔 | cai | tượng hình | bậc thềm, đê, bậc nhà; răn dạy | 陔 thuộc bộ 阜 (gò đất, đê), chỉ bậc thềm, bậc đất hay đê điều. Không có phân tích IDS chi tiết trong dữ liệu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cai\": đê 阝 cai bậc thềm — bậc đất đắp cao từng cấp như người cai quản trật tự. | Gương Hán-Việt | cai — xuất hiện trong điển tích hiếu thảo và thiên văn học cổ Trung Quốc | Mở khoá kiến thức | Biết 陔 giúp đọc thơ ca cổ điển Trung Quốc về hiếu đạo và thiên văn học cổ đại.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 陔 thuộc bộ 阜 (gò đất), chỉ bậc thềm, bậc đất. Cũng có nghĩa là răn bảo (源自蘭陔 — lan cai, bài thơ của Mao Thi biểu thị hiếu thảo). 九陔 là tên gọi chín tầng trời. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thềm nhà, bậc lên; răn bảo", "Hạng Tần Suất (Jun Da)": "6380.0", "Tần Suất % (Jun Da)": "99.991358319", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + 亥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝亥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "陔", "Unihan_Traditional (Chữ Phồn thể)": "陔", "Pinyin_Xie": "gāi", "Âm Hán Việt_Xie": "cai", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ các bậc thềm hoặc ranh giới phân chia trong kiến trúc cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('坌', '{"9000": "6381.0", "Chữ Trung Quốc": "坌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 7 | nét | 分 | phân | biểu âm | chia, phân | 土 | thổ | biểu nghĩa | đất | 坌 = 分 (Phân, biểu âm) + 土 (Thổ, biểu nghĩa: đất); chữ hình thanh. Bụi đất, đất tung lên.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phần\": đất 土 phân bụi — bụi đất tung bay, tụ họp hay tan tán như số phận. | Gương Hán-Việt | phần — ít gặp trong từ Hán-Việt hiện đại, xuất hiện trong phương ngữ và văn bản nông nghiệp | Mở khoá kiến thức | Biết 坌 giúp đọc văn bản canh tác đất và phương ngữ miền Nam Trung Quốc.", "Tự nguyên_Xie": "坌 là chữ hình thanh: 土 (đất) cho nghĩa, 分 cho âm. Nghĩa gốc là bụi đất, đất bốc lên. Mở rộng sang: tụ họp, đào bới, ngu ngốc vụng về (phương ngữ). Cũng là dạng cổ của 笨 (ngu). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hợp, nhóm; bụi", "Hạng Tần Suất (Jun Da)": "6381.0", "Tần Suất % (Jun Da)": "99.9913712386", "GavinGrover_Once (Chiết tự trực tiếp)": "分 + 土", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱分土", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "分", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "坌", "Unihan_Traditional (Chữ Phồn thể)": "坌", "Pinyin_Xie": "bèn", "Âm Hán Việt_Xie": "bộn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Có thể làm danh từ chỉ bụi đất hoặc động từ chỉ hành động tụ tập, đào bới. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('悃', '{"9000": "6382.0", "Chữ Trung Quốc": "悃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 10 | nét | 悃 | khổn | tượng hình | chữ hình thanh gốc, biểu thị lòng thành thật | 悃 không có cấu trúc IDS rõ ràng trong dữ liệu; dựa vào hình thức chữ, đây là chữ hình thanh thuộc bộ 心 (tâm), biểu thị cảm xúc chân thành. chưa có nguồn học thuật xác nhận cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khổn\": bộ 心 (tâm) — lòng thành thật không che giấu, dâng trọn tâm ý. | Gương Hán-Việt | khổn — ít dùng trong tiếng Việt hiện đại; gặp trong văn cổ qua từ như \"trung khổn\" (lòng trung thành chân thật) | Mở khoá kiến thức | Biết 悃 mở khoá các từ cổ văn chỉ lòng thành: 悃誠, 忠悃, 悃愊.", "Tự nguyên_Xie": "Tiểu triện | 悃 thuộc bộ 心 (tâm, trái tim), mang nghĩa thành thật, trung thành. Wiktionary không cung cấp phân tích cấu trúc hình thanh/hội ý cụ thể cho chữ này; chỉ ghi nhận đây là tính từ văn học chỉ sự chân thành. chưa có nguồn học thuật xác nhận cụ thể. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thành thật", "Hạng Tần Suất (Jun Da)": "6382.0", "Tần Suất % (Jun Da)": "99.9913841582", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 困", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄困", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "困", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "悃", "Unihan_Traditional (Chữ Phồn thể)": "悃", "Pinyin_Xie": "kǔn", "Âm Hán Việt_Xie": "khổn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ tấm lòng chân thành hoặc tính từ bổ nghĩa cho tâm ý. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('塍', '{"9000": "6383.0", "Chữ Trung Quốc": "塍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 13 | nét | 朕 | trẫm | biểu âm | ta (ngôi xưng của vua) | 土 | thổ | biểu nghĩa | đất | 塍 = 朕 (Trẫm, biểu âm) + 土 (Thổ, biểu nghĩa: đất); chữ hình thanh. Phần 朕 cho âm đọc gần chéng; phần 土 chỉ đây là vật thể làm từ đất — bờ ruộng, bờ đê.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thặng\": bờ đất (土) phân chia ruộng, mang âm của 朕 — hình dung vị vua (朕) đứng trên bờ ruộng (土) kiểm tra mùa màng. | Gương Hán-Việt | thặng — ít dùng trong tiếng Việt hiện đại; xuất hiện trong thơ văn cổ chỉ bờ ruộng | Mở khoá kiến thức | Biết 塍 mở khoá các từ điền viên cổ: 田塍 (bờ ruộng), 塍上 (trên bờ ruộng).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | 塍 là chữ hình thanh: 土 (thổ, đất) biểu nghĩa, 朕 (trẫm) biểu âm. Theo Wiktionary, chữ chỉ con đường nổi giữa các thửa ruộng, bờ đê phân chia ruộng lúa. Kim văn và tiểu triện đã xác nhận cấu trúc này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thửa ruộng cấy lúa", "Hạng Tần Suất (Jun Da)": "6383.0", "Tần Suất % (Jun Da)": "99.9913970779", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "塍", "Unihan_Traditional (Chữ Phồn thể)": "堘", "Pinyin_Xie": "chéng", "Âm Hán Việt_Xie": "thăng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ ranh giới đất đai hoặc lối đi giữa các thửa ruộng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('疬', '{"9000": "6384.0", "Chữ Trung Quốc": "疬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 9 | nét | 疒 | nạch | biểu nghĩa | bệnh tật | 歷 | lịch | biểu âm | trải qua | 疬 = 疒 (biểu nghĩa: bệnh) + 歷 (Lịch, biểu âm); chữ hình thanh. Dạng đầy đủ là 癧 (truyền thống). Phần 疒 chỉ đây là loại bệnh; phần 歷 cho âm lì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lịch\": bộ 疒 (bệnh) cộng âm Lịch (歷) — hình dung bệnh \"trải qua\" (歷) thời gian dài mới phát, nổi u cục ở cổ. | Gương Hán-Việt | lịch — xuất hiện trong y học cổ truyền: \"loa lịch\" (瘰疬) chỉ chứng lao hạch | Mở khoá kiến thức | Biết 疬 mở khoá thuật ngữ y học cổ: 瘰疬 (loa lịch, bệnh lao hạch).", "Tự nguyên_Xie": "疬 là dạng giản thể của 癧, chữ hình thanh: 疒 (nạch, bệnh) biểu nghĩa, 歷 (lịch) biểu âm. Theo Wiktionary, chữ chỉ căn bệnh lao hạch (scrofula) — sưng hạch bạch huyết vùng cổ. Thường dùng trong cụm 瘰疬 (loa lịch). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: lỗi lịch 瘰癧,瘰疬)", "Hạng Tần Suất (Jun Da)": "6384.0", "Tần Suất % (Jun Da)": "99.9914099975", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 历", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒历", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "历", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "疬", "Unihan_Traditional (Chữ Phồn thể)": "癧", "Pinyin_Xie": "lì", "Âm Hán Việt_Xie": "lịch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong y học cổ truyền, kết hợp thành từ ghép chỉ bệnh lao hạch ở cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('麈', '{"9000": "6385.0", "Chữ Trung Quốc": "麈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鹿 | Số nét | 16 | nét | 麈 | chủ | tượng hình | loài nai lớn, từ đó đuôi được dùng làm phất trần | 麈 là chữ độc lập thuộc bộ 鹿 (lộc, hươu nai). Wiktionary không cung cấp phân tích hội ý hay hình thanh cụ thể; chữ chỉ một loài nai đặc biệt mà đuôi được giới trí thức thời cổ dùng làm phất trần khi đàm đạo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chủ\": loài nai chủ chốt (主) của bộ 鹿 — đuôi nó được dùng làm phất trần của các học giả Nguỵ Tấn. | Gương Hán-Việt | chủ — ít dùng trong tiếng Việt hiện đại; gặp trong văn học cổ điển qua hình ảnh \"phất trần麈尾\" | Mở khoá kiến thức | Biết 麈 mở khoá hình ảnh văn hoá: 麈尾 (chủ vĩ — phất trần), 揮麈 (huy chủ — vẫy phất trần khi đàm đạo).", "Tự nguyên_Xie": "Tiểu triện | 麈 thuộc bộ 鹿 (lộc, hươu nai), chỉ một loài nai lớn. Theo Wiktionary, tiểu triện có hình. Đuôi con麈 (zhǔ wěi — phất trần làm từ đuôi麈) là vật dụng phổ biến của văn nhân thời Nguỵ Tấn khi thảo luận triết học (thanh đàm). chưa có nguồn học thuật xác nhận cấu trúc chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một loài thú giống con nai", "Hạng Tần Suất (Jun Da)": "6385.0", "Tần Suất % (Jun Da)": "99.9914229171", "GavinGrover_Once (Chiết tự trực tiếp)": "鹿 + 主", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴鹿主", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "主", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鹿", "Unihan_Simplified (Chữ Giản thể)": "麈", "Unihan_Traditional (Chữ Phồn thể)": "麈", "Pinyin_Xie": "zhǔ", "Âm Hán Việt_Xie": "chủ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ loài thú giống nai hoặc cái phất trần làm bằng đuôi của nó. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('絜', '{"9000": "6386.0", "Chữ Trung Quốc": "絜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 12 | nét | 㓞 | khiết | biểu âm | khắc | 糸 | mịch | biểu nghĩa | sợi tơ, dây | 絜 = 㓞 (biểu âm, cho âm jié) + 糸 (Mịch, biểu nghĩa: sợi tơ); chữ hình thanh. Dây sợi 糸 biểu thị đây là thứ dùng để đo lường hoặc kéo thẳng; 㓞 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khiết\": sợi tơ 糸 căng thẳng như chuẩn mực — chữ Khiết gợi sự tinh khiết, thẳng thắn không vẩn đục. | Gương Hán-Việt | khiết — tiếng Việt dùng qua \"khiết bạch\" (trong trắng), \"thanh khiết\" (tinh khiết) | Mở khoá kiến thức | Biết 絜 mở khoá từ cổ văn về sự tinh khiết và đo lường: 絜矩 (phép đo lường công bằng), 絜齋 (ăn chay giữ thân trong sạch).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 絜 là chữ hình thanh: 糸 (mịch, sợi tơ) biểu nghĩa, 㓞 biểu âm. Theo Wiktionary, nghĩa gốc là dây để đo, sau mở rộng sang sạch sẽ (trong sáng như dây thẳng), đo lường, quy chế. Tiểu triện và Lục thư thông đã có dạng chữ này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sạch sẽ", "Hạng Tần Suất (Jun Da)": "6386.0", "Tần Suất % (Jun Da)": "99.9914358367", "GavinGrover_Once (Chiết tự trực tiếp)": "㓞 + 糸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱㓞糸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㓞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糸", "Unihan_Simplified (Chữ Giản thể)": "絜", "Unihan_Traditional (Chữ Phồn thể)": "絜", "Pinyin_Xie": "jié", "Âm Hán Việt_Xie": "kiết, hiệt, khiết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ chỉ sự trong sạch hoặc động từ chỉ việc đo đạc, so sánh. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('脩', '{"9000": "6387.0", "Chữ Trung Quốc": "脩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 10 | nét | 攸 | du | biểu âm | 肉 | nhục | biểu nghĩa | thịt | 脩 = 攸 (Du, biểu âm) + 肉 (Nhục, biểu nghĩa: thịt); chữ hình thanh. Bộ 肉 chỉ đây là thức ăn liên quan đến thịt; 攸 cho âm đọc xiū.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tu\": thịt (肉) khô phơi nắng — ngày xưa học trò mang 束脩 (thịt khô) đến nhà thầy như học phí đầu tiên. | Gương Hán-Việt | tu — tiếng Việt dùng qua \"tu dưỡng\", \"tu sửa\" (thường viết bằng 修 giản thể) | Mở khoá kiến thức | Biết 脩 mở khoá từ cổ về học phí và tu dưỡng: 束脩 (thịt khô làm học phí), 脩金 (tiền thưởng thầy), 脩飾 (trang sức, tu chỉnh).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 脩 là chữ hình thanh: 肉 (nhục, thịt) biểu nghĩa, 攸 biểu âm. Theo Wiktionary, nghĩa gốc là thịt khô (sấy, phơi) — loại thực phẩm học trò mang đến biếu thầy giáo như tiền học phí thời cổ. Từ đó mở rộng nghĩa thành \"lương thưởng thầy giáo\", rồi dùng thay 修 với nghĩa tu dưỡng, sửa chữa. Tiểu triện và nhiều dạng Lục thư thông đã xác nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Sửa chữa", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 𡕙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰𡕙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "脩", "Unihan_Traditional (Chữ Phồn thể)": "脩", "Pinyin_Xie": "xiū", "Âm Hán Việt_Xie": "tu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ thịt khô làm quà tặng thầy học hoặc động từ đồng nghĩa với tu sửa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('赒', '{"9000": "6388.0", "Chữ Trung Quốc": "赒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 12 | nét | 赒 | chu | tượng hình | giản thể của 賙 — bộ 貝 (tiền) + 周 (chu cấp) | 赒 là giản thể của 賙. Dạng đầy đủ 賙 gồm 貝 (buổi, tiền của) biểu nghĩa và 周 (chu) biểu âm — chữ hình thanh chỉ việc chu cấp, trợ giúp bằng tiền. chưa có dữ liệu IDS chi tiết cho dạng giản thể này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chu\": bộ 貝 (tiền) kết hợp với 周 (chu cấp) — người giàu lòng chu đáo trao tiền giúp đỡ kẻ nghèo. | Gương Hán-Việt | chu — tiếng Việt dùng qua \"chu cấp\" (cung cấp đầy đủ), \"chu toàn\" (đầy đủ trọn vẹn) | Mở khoá kiến thức | Biết 赒 mở khoá từ từ thiện cổ văn: 赒恤 (chu cấp và cứu trợ), 赒濟 (chu cấp giúp đỡ).", "Tự nguyên_Xie": "赒 là giản thể của 賙, theo Wiktionary. Chữ đầy đủ 賙 là hình thanh: 貝 (tiền của) biểu nghĩa, 周 (chu, xung quanh, đầy đủ) biểu âm — gợi ý chu cấp tiền bạc cho người cần. chưa có nguồn học thuật xác nhận thêm cấu trúc dạng giản thể. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chu cấp, giúp", "Hạng Tần Suất (Jun Da)": "6388.0", "Tần Suất % (Jun Da)": "99.991461676", "GavinGrover_Once (Chiết tự trực tiếp)": "贝 + 周", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰贝周", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "周", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "贝", "Unihan_Simplified (Chữ Giản thể)": "赒", "Unihan_Traditional (Chữ Phồn thể)": "賙", "Pinyin_Xie": "zhōu", "Âm Hán Việt_Xie": "chu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường làm động từ đứng trước danh từ chỉ đối tượng được giúp đỡ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('埒', '{"9000": "6389.0", "Chữ Trung Quốc": "埒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 10 | nét | 土 | thổ | biểu nghĩa | đất | 寽 | quát | biểu âm | 埒 = 土 (Thổ, biểu nghĩa: đất) + 寽 (Quát, biểu âm); chữ hình thanh. Bộ 土 chỉ đây là công trình đất; 寽 cho âm đọc liè.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lệt\": tường đất (土) thấp bao quanh — hình dung bờ rào đất gọn nhỏ phân ranh giới kho thóc. | Gương Hán-Việt | lệt — ít dùng trong tiếng Việt; gặp trong điển cố cổ văn qua cụm \"phú lệt thiên tử\" (giàu ngang thiên tử) | Mở khoá kiến thức | Biết 埒 mở khoá từ cổ về ranh giới và sự tương đương: 富埒天子 (giàu ngang thiên tử), 馬埒 (khu vực huấn luyện ngựa).", "Tự nguyên_Xie": "Tiểu triện | 埒 là chữ hình thanh: 土 (thổ, đất) biểu nghĩa, 寽 biểu âm. Theo Wiktionary, nghĩa cổ là tường thấp bao quanh kho, bờ ruộng nổi, hay đường nhỏ trong núi. Tiểu triện xác nhận dạng này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tường xây quanh kho", "Hạng Tần Suất (Jun Da)": "6389.0", "Tần Suất % (Jun Da)": "99.9914745956", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 寽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土寽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "寽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "埒", "Unihan_Traditional (Chữ Phồn thể)": "埒", "Pinyin_Xie": "liè", "Âm Hán Việt_Xie": "liệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ bờ tường đất hoặc làm động từ với nghĩa so sánh ngang bằng nhau. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镡', '{"9000": "6390.0", "Chữ Trung Quốc": "镡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 17 | nét | 镡 | tầm | tượng hình | bộ kim khí, thanh gươm ngắn hoặc phần bảo vệ chuôi kiếm | 镡 là giản thể của 鐔. Wiktionary không cung cấp cấu trúc IDS; đây là chữ liên quan đến vũ khí thuộc bộ 金 (kim). Chữ gốc 鐔 có thể gồm 金 biểu nghĩa và phần biểu âm, nhưng chưa có phân tích chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tầm\": bộ 金 (kim loại) — hình dung phần kim loại nằm giữa chuôi và lưỡi kiếm, bảo vệ bàn tay chiến sĩ. | Gương Hán-Việt | tầm — ít dùng trong tiếng Việt; xuất hiện trong văn học võ hiệp qua các mô tả vũ khí cổ | Mở khoá kiến thức | Biết 镡 mở khoá từ vũ khí cổ: 星鐔 (ngôi sao trên bảo vệ chuôi kiếm), 鱗鋏星鐔 (hình tả kiếm quý).", "Tự nguyên_Xie": "Đại triện | 镡 là giản thể của 鐔, thuộc bộ 金 (kim, kim loại). Theo Wiktionary, nghĩa là phần bảo vệ (guard) của chuôi kiếm, hoặc thanh dao ngắn. Đại triện có ảnh. Chưa có phân tích hội ý hay hình thanh rõ ràng; chưa có nguồn học thuật xác nhận chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một thứ binh khí giống thanh gươm nhưng nhỏ hơn; phần nhô ra hai bên giữa chuôi gươm và lưỡi gươm", "Hạng Tần Suất (Jun Da)": "6390.0", "Tần Suất % (Jun Da)": "99.9914875153", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "镡", "Unihan_Traditional (Chữ Phồn thể)": "鐔", "Pinyin_Xie": "chán", "Âm Hán Việt_Xie": "tầm, thiền, đàm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này đóng vai trò là danh từ chỉ bộ phận của thanh kiếm hoặc loại binh khí cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镨', '{"9000": "6391.0", "Chữ Trung Quốc": "镨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 17 | nét | 金 | kim | biểu nghĩa | kim loại | 普 | phổ | biểu âm | phổ thông, rộng khắp | 镨 = 金 (Kim, biểu nghĩa: kim loại) + 普 (Phổ, biểu âm); chữ hình thanh. Bộ 金 chỉ đây là nguyên tố kim loại; 普 cho âm pǔ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phổ\": kim loại (金) mang âm Phổ — nguyên tố praseodymium phổ biến trong kỹ thuật từ tính và luyện kim hiện đại. | Gương Hán-Việt | phổ — dùng trong hoá học: \"nguyên tố praseodymium\" thường ghi là 镨 (Pr) | Mở khoá kiến thức | Biết 镨 mở khoá hệ thống đặt tên nguyên tố Hán tự: nguyên tố kim loại = bộ 金 + âm phiên.", "Tự nguyên_Xie": "镨 là giản thể của 鐠, chữ hình thanh: 金 (kim, kim loại) biểu nghĩa, 普 (phổ) biểu âm. Đây là chữ được đặt để phiên âm tên nguyên tố hóa học praseodymium (Pr, số nguyên tử 59) — kim loại đất hiếm. Cấu trúc theo mẫu đặt tên nguyên tố hóa học của Trung Quốc: bộ 金 + âm gần. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố prazeodi, Pr", "Hạng Tần Suất (Jun Da)": "6391.0", "Tần Suất % (Jun Da)": "99.9915004349", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 普", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅普", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "普", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镨", "Unihan_Traditional (Chữ Phồn thể)": "鐠", "Pinyin_Xie": "pǔ", "Âm Hán Việt_Xie": "phổ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này là danh từ chuyên ngành hóa học, thường đứng độc lập hoặc trong tên hợp chất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('骎', '{"9000": "6392.0", "Chữ Trung Quốc": "骎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 10 | nét | 骎 | khâm | tượng hình | ngựa chạy vùn vụt, thuộc bộ 馬 | 骎 là giản thể của 駸. Wiktionary không cung cấp phân tích IDS; thuộc bộ 馬 (mã, ngựa). Chữ gốc 駸 có thể gồm 馬 biểu nghĩa và phần biểu âm, nhưng chưa có dữ liệu cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khâm\": bộ 馬 (ngựa) — hình dung đàn ngựa phi nhanh như tên bắn, chân gõ khâm khâm trên mặt đất. | Gương Hán-Việt | khâm — ít dùng trong tiếng Việt hiện đại; xuất hiện trong thơ cổ qua hình ảnh ngựa phi | Mở khoá kiến thức | Biết 骎 mở khoá từ thơ cổ mô tả tốc độ: 駸駸 (ngựa phi nhanh, thời gian trôi vùn vụt).", "Tự nguyên_Xie": "Tiểu triện | 骎 là giản thể của 駸, thuộc bộ 馬 (mã, ngựa). Theo Wiktionary, chữ thường dùng trong dạng điệp 駸駸, mô tả ngựa chạy nhanh hoặc sự phát triển nhanh chóng của thời gian. Tiểu triện có ảnh. chưa có nguồn học thuật xác nhận cấu trúc chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chạy xăm xăm, vùn vụt", "Hạng Tần Suất (Jun Da)": "6392.0", "Tần Suất % (Jun Da)": "99.9915133545", "GavinGrover_Once (Chiết tự trực tiếp)": "马 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰马", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "骎", "Unihan_Traditional (Chữ Phồn thể)": "駸", "Pinyin_Xie": "qīn", "Âm Hán Việt_Xie": "xâm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Phó từ | 副词 | Chữ này làm tính từ miêu tả tốc độ chạy của ngựa hoặc làm phó từ bổ nghĩa cho động từ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('骙', '{"9000": "6393.0", "Chữ Trung Quốc": "骙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 12 | nét | 骙 | quỳ | tượng hình | ngựa hăng hái mạnh mẽ, thuộc bộ 馬 | 骙 là giản thể của 騤. Wiktionary chỉ ghi {{Han etym}} mà không cung cấp phân tích IDS; thuộc bộ 馬 (mã, ngựa), chỉ sức mạnh và tinh thần của ngựa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quỳ\": bộ 馬 (ngựa) — ngựa Quỳ hùng mạnh, chân bước vững như núi, vó gõ đất đầy khí thế. | Gương Hán-Việt | quỳ — ít dùng trong tiếng Việt; xuất hiện trong thơ Kinh Thi mô tả đàn ngựa của vua | Mở khoá kiến thức | Biết 骙 mở khoá thơ Kinh Thi: 四牡骙骙 (bốn ngựa đực hăng hái mạnh khoẻ).", "Tự nguyên_Xie": "Tiểu triện | 骙 là giản thể của 騤, thuộc bộ 馬 (mã, ngựa). Theo Wiktionary, chữ mô tả ngựa có tinh thần hăng hái, mạnh khoẻ. Tiểu triện có ảnh. chưa có nguồn học thuật xác nhận cấu trúc chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hăng hái, khoẻ mạnh", "Hạng Tần Suất (Jun Da)": "6393.0", "Tần Suất % (Jun Da)": "99.9915262741", "GavinGrover_Once (Chiết tự trực tiếp)": "马 + 癸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰马癸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "癸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "马", "Unihan_Simplified (Chữ Giản thể)": "骙", "Unihan_Traditional (Chữ Phồn thể)": "騤", "Pinyin_Xie": "kuí", "Âm Hán Việt_Xie": "quỳ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ miêu tả trạng thái khỏe khoắn, dũng mãnh của loài ngựa. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鼩', '{"9000": "6394.0", "Chữ Trung Quốc": "鼩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鼠 | Số nét | 18 | nét | 鼠 | thử | biểu nghĩa | chuột | 句 | câu | biểu âm | câu, cong | 鼩 = 鼠 (Thử, biểu nghĩa: chuột) + 句 (Câu, biểu âm); chữ hình thanh. Bộ 鼠 chỉ đây là loài gặm nhấm; 句 cho âm đọc qú.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cú\": chuột (鼠) nhỏ bằng ngón tay, thân cong như dấu câu (句) — hình ảnh con chuột chù tí hon cuộn tròn trong lá. | Gương Hán-Việt | cú — ít dùng trong tiếng Việt; loài động vật này gọi là \"chuột chù\" hay \"chuột xạ\" | Mở khoá kiến thức | Biết 鼩 mở khoá tên loài động vật: 鼩鼱 (chuột chù nhỏ), 樹鼩 (chuột chù cây).", "Tự nguyên_Xie": "Tiểu triện | 鼩 là chữ hình thanh: 鼠 (thử, chuột) biểu nghĩa, 句 (câu) biểu âm. Theo Wiktionary, chữ chỉ loài chuột chù (shrew) — động vật ăn sâu bọ nhỏ có mõm nhọn. Tiểu triện xác nhận dạng này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chuột xạ (da rất quý)", "Hạng Tần Suất (Jun Da)": "6394.0", "Tần Suất % (Jun Da)": "99.9915521134", "GavinGrover_Once (Chiết tự trực tiếp)": "鼠 + 句", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鼠句", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "句", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鼠", "Unihan_Simplified (Chữ Giản thể)": "鼩", "Unihan_Traditional (Chữ Phồn thể)": "鼩", "Pinyin_Xie": "qú", "Âm Hán Việt_Xie": "cù", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, thường kết hợp với chữ khác để chỉ loài chuột chù. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('雰', '{"9000": "6395.0", "Chữ Trung Quốc": "雰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 雨 | Số nét | 12 | nét | 雨 | vũ | biểu nghĩa | mưa | 分 | phân | biểu âm | chia nhỏ, tản ra | 雰 = 雨 (Vũ, biểu nghĩa: mưa/thời tiết) + 分 (Phân, biểu âm); chữ hình thanh. Bộ 雨 chỉ đây là hiện tượng khí quyển; 分 cho âm đọc fēn và gợi ý sương mù tản rộng khắp.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phân\": hơi nước (雨) phân tán (分) khắp không trung — sương mù bao phủ mờ ảo. | Gương Hán-Việt | phân — tiếng Việt dùng qua \"khí phân\" (không khí), \"vân phân\" (mây sương); từ hiện đại \"không khí\" dùng 空氣 | Mở khoá kiến thức | Biết 雰 mở khoá từ thơ văn cổ về thời tiết: 雰圍 (bầu không khí, atmosphere), 雰雰 (sương mù dày đặc).", "Tự nguyên_Xie": "Tiểu triện | 雰 là chữ hình thanh: 雨 (vũ, mưa) biểu nghĩa, 分 (phân, chia nhỏ) biểu âm. Theo Wiktionary, chữ chỉ khí quyển, sương mù, khói mù. Tiểu triện xác nhận cấu trúc này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khí sương mù", "Hạng Tần Suất (Jun Da)": "6395.0", "Tần Suất % (Jun Da)": "99.991565033", "GavinGrover_Once (Chiết tự trực tiếp)": "雨 + 分", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱雨分", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "分", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "雨", "Unihan_Simplified (Chữ Giản thể)": "雰", "Unihan_Traditional (Chữ Phồn thể)": "雰", "Pinyin_Xie": "fēn", "Âm Hán Việt_Xie": "phân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ hiện tượng thời tiết khí quyển hoặc kết hợp tạo từ chỉ bầu không khí. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('藴', '{"9000": "6396.0", "Chữ Trung Quốc": "藴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 18 | nét | 艸 | tháu | biểu nghĩa | cỏ, thực vật | 縕 | uẩn | biểu âm | bông lót áo, ẩn chứa | 藴 = 艸 (Tháu, biểu nghĩa: thực vật) + 縕 (Uẩn, biểu âm); chữ hình thanh. Dạng truyền thống là 蘊. Bộ 艸 gợi sự tích tụ như cây cỏ chồng chất; 縕 cho âm đọc yùn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uẩn\": cỏ (艸) chồng chất tầng tầng — bên dưới ẩn chứa sức sống, như người tích luỹ học vấn bên trong. | Gương Hán-Việt | uẩn — tiếng Việt dùng qua \"hàm uẩn\" (ẩn chứa ý sâu), \"uẩn khúc\" (điều uẩn khuất) | Mở khoá kiến thức | Biết 藴 mở khoá từ về tiềm năng ẩn chứa: 蘊藏 (tàng trữ ẩn chứa), 底蘊 (nội hàm sâu xa), 蘊含 (ẩn chứa).", "Tự nguyên_Xie": "藴 là dạng variant của 蘊 (truyền thống), chữ hình thanh: 艸 (tháu, cỏ) biểu nghĩa, 縕 biểu âm. Theo Wiktionary, nghĩa là tích luỹ, ẩn chứa, chứa đựng. Hình ảnh cỏ chồng chất (艸) gợi sự tích tụ ẩn ý. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Vân", "Hạng Tần Suất (Jun Da)": "6396.0", "Tần Suất % (Jun Da)": "99.9915908723", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 緼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹緼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "緼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "藴", "Unihan_Traditional (Chữ Phồn thể)": "藴", "Pinyin_Xie": "yùn", "Âm Hán Việt_Xie": "uẩn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ sự tích tụ, ẩn chứa bên trong hoặc làm danh từ chỉ sự súc tích. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鳑', '{"9000": "6397.0", "Chữ Trung Quốc": "鳑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 18 | nét | 鳑 | bàng | tượng hình | cá bàng bì nhỏ, thuộc họ cá chép | 鳑 là giản thể của 鰟. Không có dữ liệu IDS hay Wiktionary anchor; thuộc bộ 魚 (ngư, cá). Thường dùng trong cụm 鳑鲏 (bàng bì) chỉ một loài cá chép nhỏ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bàng\": bộ 魚 (cá) — con cá bàng bì nhỏ xinh, bơi bàng bạc trong ao hồ. | Gương Hán-Việt | bàng — ít dùng trong tiếng Việt; tên cá này thường gọi là \"cá bàng bì\" theo phiên âm | Mở khoá kiến thức | Biết 鳑 mở khoá tên cá nước ngọt: 鳑鲏 (cá bàng bì, bitterling).", "Tự nguyên_Xie": "鳑 là giản thể của 鰟, thuộc bộ 魚 (ngư, cá). Không có dữ liệu Wiktionary anchor cho chữ này. Chữ thường dùng trong cụm 鳑鲏 (bàng bì) chỉ loài cá nhỏ họ cá chép. chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: báng bì 鰟鮍,鳑鲏)", "Hạng Tần Suất (Jun Da)": "6397.0", "Tần Suất % (Jun Da)": "99.9916296312", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 旁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼旁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鳑", "Unihan_Traditional (Chữ Phồn thể)": "鰟", "Pinyin_Xie": "páng", "Âm Hán Việt_Xie": "bàng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ trong tên gọi các loài cá nước ngọt nhỏ như bàng bì. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('豨', '{"9000": "6398.0", "Chữ Trung Quốc": "豨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 豕 | Số nét | 14 | nét | 豕 | thỉ | biểu nghĩa | lợn | 希 | hy | biểu âm | hi vọng, hiếm | 豨 = 豕 (Thỉ, biểu nghĩa: lợn) + 希 (Hy, biểu âm); chữ hình thanh. Bộ 豕 chỉ đây là loài lợn/heo; 希 cho âm đọc xī. Chữ dùng trong văn học cổ để chỉ lợn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hê\": lợn (豕) bình thường nhưng hiếm gặp (希) trong văn viết — chữ Hê cổ kính chỉ con heo mà sách cổ mới dùng. | Gương Hán-Việt | hê — ít dùng trong tiếng Việt hiện đại; gặp trong văn học cổ qua \"hê tiển\" (豨苋, cây cỏ lợn) | Mở khoá kiến thức | Biết 豨 mở khoá từ cổ về vật nuôi: 豨苋 (cỏ lợn, một loại thảo dược).", "Tự nguyên_Xie": "Tiểu triện | 豨 là chữ hình thanh: 豕 (thỉ, lợn) biểu nghĩa, 希 (hy) biểu âm. Theo Wiktionary, đây là từ cổ văn chỉ lợn/heo, thường thấy trong tên người như \"Bành Việt Đồ Hề\" (彭越屠豨) — Bành Việt mổ heo. Tiểu triện xác nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lợn (nói trong sách cổ)", "Hạng Tần Suất (Jun Da)": "6398.0", "Tần Suất % (Jun Da)": "99.991642034", "GavinGrover_Once (Chiết tự trực tiếp)": "豕 + 希", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰豕希", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "希", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "豕", "Unihan_Simplified (Chữ Giản thể)": "豨", "Unihan_Traditional (Chữ Phồn thể)": "豨", "Pinyin_Xie": "xī", "Âm Hán Việt_Xie": "hi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này là danh từ dùng trong văn ngôn cổ để chỉ loài lợn hoặc heo rừng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('琚', '{"9000": "6399.0", "Chữ Trung Quốc": "琚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 12 | nét | 𤣩 | ngọc | biểu nghĩa | ngọc thạch | 居 | cư | biểu âm | ở, cư trú | 琚 = 𤣩 (bộ Ngọc, biểu nghĩa: ngọc thạch) + 居 (Cư, biểu âm); chữ hình thanh. Bộ ngọc 𤣩 chỉ đây là đồ trang sức ngọc; 居 cho âm đọc jū.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cư\": ngọc (玉) cư trú (居) tại thắt lưng — những viên ngọc quý đeo thắt lưng của quý tộc xưa, leng keng khi bước đi. | Gương Hán-Việt | cư — ít dùng trong tiếng Việt; gặp qua \"Vân Hà\" (瓊琚) trong thơ Kinh Thi | Mở khoá kiến thức | Biết 琚 mở khoá hình ảnh thơ cổ: 瓊琚 (ngọc quý đeo thắt lưng), 玉佩瓊琚 (chuỗi ngọc thắt lưng).", "Tự nguyên_Xie": "Tiểu triện | 琚 là chữ hình thanh: bộ 玉/𤣩 (ngọc) biểu nghĩa, 居 (cư) biểu âm. Theo Wiktionary, chữ chỉ ngọc hoặc đá quý đeo ở thắt lưng như vật trang sức. Tiểu triện xác nhận. Chữ xuất hiện trong thơ cổ qua hình ảnh \"Vân Hà Tặng Ngọc\" (瓊琚). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngọc cư", "Hạng Tần Suất (Jun Da)": "6399.0", "Tần Suất % (Jun Da)": "99.9916544369", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 居", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王居", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "居", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "琚", "Unihan_Traditional (Chữ Phồn thể)": "琚", "Pinyin_Xie": "jū", "Âm Hán Việt_Xie": "cư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại ngọc quý đeo bên mình thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('觫', '{"9000": "6400.0", "Chữ Trung Quốc": "觫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 角 | Số nét | 14 | nét | 觫 | túc | tượng hình | run rẩy sợ hãi, thuộc bộ 角 | 觫 không có dữ liệu IDS hay Wiktionary anchor. Thuộc bộ 角 (giác, sừng). Nghĩa là run rẩy vì sợ hãi, thường dùng trong cụm 觳觫 (hộc túc — run sợ, cụm từ Mạnh Tử).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"túc\": bộ 角 (sừng) — hình dung con bò run rẩy (觳觫), đôi sừng cũng run theo khi bị dắt đến nơi giết mổ. | Gương Hán-Việt | túc — ít dùng trong tiếng Việt; gặp trong dịch Mạnh Tử qua \"觳觫\" (hộc túc) | Mở khoá kiến thức | Biết 觫 mở khoá điển cố Mạnh Tử: 觳觫 (hộc túc — run sợ van xin, hình ảnh con bò nhân từ).", "Tự nguyên_Xie": "觫 thuộc bộ 角 (giác, sừng). Không có dữ liệu Wiktionary anchor. Chữ thường dùng trong cụm 觳觫 từ Mạnh Tử, mô tả con bò run sợ khi bị dắt đi giết. chưa có nguồn học thuật xác nhận cấu trúc chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sừng mới nhú", "Hạng Tần Suất (Jun Da)": "6400.0", "Tần Suất % (Jun Da)": "99.9916668397", "GavinGrover_Once (Chiết tự trực tiếp)": "角 + 束", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰角束", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "束", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "角", "Unihan_Simplified (Chữ Giản thể)": "觫", "Unihan_Traditional (Chữ Phồn thể)": "觫", "Pinyin_Xie": "sù", "Âm Hán Việt_Xie": "tốc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này thường kết hợp thành từ ghép như cốt túc để mô tả trạng thái run sợ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲦', '{"9000": "6401.0", "Chữ Trung Quốc": "鲦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 15 | nét | 魚 | ngư | biểu nghĩa | cá | 條 | điều | biểu âm | sợi, dài và mỏng | 鲦 = 魚 (Ngư, biểu nghĩa: cá) + 條 (Điều, biểu âm); chữ hình thanh. Dạng đầy đủ là 鰷. Bộ 魚 chỉ đây là loài cá; 條 cho âm tiáo và gợi thân hình dẹt mỏng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điều\": cá (魚) mình mỏng như sợi dây (條) — cá vền trắng bạc bơi thành dòng (điều) trong suối. | Gương Hán-Việt | điều — ít dùng trong tiếng Việt; loài cá này gọi là \"cá vền\" hay \"cá mương\" | Mở khoá kiến thức | Biết 鲦 mở khoá từ tự nhiên học: 白鲦 (cá vền trắng), 鲦鱼 (cá mương, minnow).", "Tự nguyên_Xie": "鲦 là giản thể của 鰷, chữ hình thanh: 魚 (ngư, cá) biểu nghĩa, 條 (điều, sợi dài mỏng) biểu âm. Theo Wiktionary, chữ chỉ cá vền — loài cá nước ngọt thân dẹt, màu trắng bạc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá vền (mình trắng, dẹt)", "Hạng Tần Suất (Jun Da)": "6401.0", "Tần Suất % (Jun Da)": "99.9916792425", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 条", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼条", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "条", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲦", "Unihan_Traditional (Chữ Phồn thể)": "鰷", "Pinyin_Xie": "tiáo", "Âm Hán Việt_Xie": "điều", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ để chỉ một loại cá nước ngọt nhỏ có thân dài và dẹt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('刳', '{"9000": "6402.0", "Chữ Trung Quốc": "刳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 刀 | Số nét | 8 | nét | 刳 | khoa | tượng hình | mổ, khoét, bộ 刀 | 刳 là chữ thuộc bộ 刀 (đao, dao), nhưng Wiktionary không cung cấp phân tích IDS chi tiết. Tiểu triện có ảnh. Nghĩa là mổ, khoét rỗng, rạch ra.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khoa\": dao (刀) khoét rỗng thân cây — người cổ đại khoa (刳) gỗ làm thuyền độc mộc. | Gương Hán-Việt | khoa — ít dùng trong tiếng Việt; gặp trong dịch Trang Tử qua 刳木為舟 | Mở khoá kiến thức | Biết 刳 mở khoá điển cố Trang Tử: 刳木為舟 (khoét gỗ làm thuyền), 刳腹 (mổ bụng).", "Tự nguyên_Xie": "Tiểu triện | 刳 thuộc bộ 刀 (đao, dao). Theo Wiktionary, nghĩa là cắt hở, khoét rỗng, mổ bụng. Chữ dùng trong văn học cổ và Trang Tử: 刳木為舟 (khoét gỗ làm thuyền). Tiểu triện có ảnh. chưa có nguồn học thuật xác nhận cấu trúc chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mổ", "Hạng Tần Suất (Jun Da)": "6402.0", "Tần Suất % (Jun Da)": "99.9916916454", "GavinGrover_Once (Chiết tự trực tiếp)": "夸 + 刂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰夸刂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "刂", "Unihan_Simplified (Chữ Giản thể)": "刳", "Unihan_Traditional (Chữ Phồn thể)": "刳", "Pinyin_Xie": "kū", "Âm Hán Việt_Xie": "khô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thể hiện hành động mổ, khoét hoặc làm rỗng một vật thể. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('拶', '{"9000": "6403.0", "Chữ Trung Quốc": "拶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 9 | nét | ⺘ | thủ | biểu nghĩa | tay | 𡿪 | biểu âm | 拶 = ⺘ (bộ Thủ, biểu nghĩa: tay) + 𡿪 (biểu âm); chữ hình thanh. Bộ tay ⺘ chỉ đây là hành động dùng tay ép, bóp; phần còn lại cho âm đọc zā.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tạp\": tay (⺘) ép mạnh — hình cụ拶子 kẹp chặt ngón tay của kẻ tình nghi để tra khảo thời cổ. | Gương Hán-Việt | tạp — ít dùng trong tiếng Việt; gặp trong sử học qua mô tả hình phạt cổ đại Trung Hoa | Mở khoá kiến thức | Biết 拶 mở khoá từ lịch sử hình phạt: 拶子 (hình cụ ép ngón tay), 拶指 (tra tấn ngón tay).", "Tự nguyên_Xie": "拶 là chữ hình thanh: ⺘/手 (thủ, tay) biểu nghĩa, 𡿪 biểu âm. Theo Wiktionary, nghĩa là ép buộc, dồn ép; cũng chỉ hình cụ tra tấn cổ đại dùng để ép ngón tay (拶子). Có hai cách đọc: zā (ép) và zǎn (hình cụ ép ngón). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bức bách, đè nén", "Hạng Tần Suất (Jun Da)": "6403.0", "Tần Suất % (Jun Da)": "99.9917040482", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 𡿪", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌𡿪", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𡿪", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "拶", "Unihan_Traditional (Chữ Phồn thể)": "拶", "Pinyin_Xie": "zā", "Âm Hán Việt_Xie": "tạt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động tra tấn bằng cách kẹp ngón tay hoặc dồn ép. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('掊', '{"9000": "6404.0", "Chữ Trung Quốc": "掊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 11 | nét | 掊 | bầu | tượng hình | bẻ gãy, kéo lấy — thuộc bộ 手 | 掊 là chữ thuộc bộ 手 (thủ, tay). Wiktionary không cung cấp phân tích IDS; nghĩa gốc là bẻ mở, đập vỡ. Tiểu triện có ảnh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bầu\": tay (手) đập bầu rỗng — điển cố Trang Tử: bầu bí to nhưng vô dụng thì đập bỏ (掊之). | Gương Hán-Việt | bầu — ít dùng trong tiếng Việt; gặp trong dịch Trang Tử qua điển cố bầu rỗng | Mở khoá kiến thức | Biết 掊 mở khoá điển cố Trang Tử: 掊之 (đập vỡ), 掊克 (vơ vét bóc lột).", "Tự nguyên_Xie": "Tiểu triện | 掊 thuộc bộ 手 (thủ, tay). Theo Wiktionary, nghĩa là bẻ mở, đập vỡ. Dẫn chứng từ Trang Tử: 非不呺然大也，吾為其無用而掊之 (Không phải không rỗng lớn, ta vì nó vô dụng mà đập vỡ). Tiểu triện có ảnh. chưa có nguồn học thuật xác nhận cấu trúc chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "kéo lấy; cầm, nắm; đánh; bửa ra", "Hạng Tần Suất (Jun Da)": "6404.0", "Tần Suất % (Jun Da)": "99.9917164511", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 咅", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌咅", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "咅", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "掊", "Unihan_Traditional (Chữ Phồn thể)": "掊", "Pinyin_Xie": "póu", "Âm Hán Việt_Xie": "bồi, phẩu, bẫu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động vơ vét của cải hoặc đào bới, đánh đập. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('泐', '{"9000": "6405.0", "Chữ Trung Quốc": "泐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 7 | nét | 泐 | lặc | tượng hình | đá nứt ra; viết — thuộc bộ 水 | 泐 là chữ thuộc bộ 水/氵 (thuỷ, nước). Không có dữ liệu Wiktionary anchor hay IDS. Nghĩa là đá bị nứt nẻ (do nước), và cũng dùng với nghĩa viết (văn ngữ trang trọng: 泐此 — viết thư này). Tiểu triện có ảnh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lặc\": nước (水) lặc lẽo chảy theo thớ đá — theo thời gian nước khắc vào đá thành vân, thành chữ. | Gương Hán-Việt | lặc — ít dùng trong tiếng Việt; gặp trong văn thư cổ trang trọng qua \"泐此\" (viết thư này) | Mở khoá kiến thức | Biết 泐 mở khoá từ văn thư cổ: 泐此奉聞 (viết thư này kính thông báo), 石泐 (đá nứt nẻ).", "Tự nguyên_Xie": "Tiểu triện | 泐 thuộc bộ 水/氵 (thuỷ, nước). Không có dữ liệu Wiktionary anchor. Nghĩa gốc: đá bị nứt nẻ do tác động của nước (vân đá, thớ đá). Nghĩa mở rộng: viết thư (文言); cũng chỉ thớ gỗ/đá. chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đá nứt nẻ ra; viết", "Hạng Tần Suất (Jun Da)": "6405.0", "Tần Suất % (Jun Da)": "99.9917288539", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 阞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵阞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "阞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "泐", "Unihan_Traditional (Chữ Phồn thể)": "泐", "Pinyin_Xie": "lè", "Âm Hán Việt_Xie": "lặc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ việc khắc chữ lên đá hoặc viết thư trong văn phong cổ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瘗', '{"9000": "6406.0", "Chữ Trung Quốc": "瘗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 14 | nét | 㾜 | ế | biểu âm | 土 | thổ | biểu nghĩa | đất | 瘗 = 㾜 (biểu âm) + 土 (Thổ, biểu nghĩa: đất); chữ hình thanh. Dạng truyền thống là 瘞. Bộ 土 chỉ đây liên quan đến chôn cất vào đất; 㾜 cho âm đọc yì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ế\": đất (土) che phủ giấu kín — hành động chôn vùi dưới đất, từ mai táng đến giấu của. | Gương Hán-Việt | ế — ít dùng trong tiếng Việt; gặp trong văn học và sử học qua \"瘗埋\" (chôn cất), \"瘗玉\" (chôn ngọc tế lễ) | Mở khoá kiến thức | Biết 瘗 mở khoá từ tang lễ cổ: 瘗埋 (chôn cất), 瘗玉 (chôn ngọc tế thần đất), 瘗鶴銘 (bia mộ hạc nổi tiếng).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 瘗 (dạng chính 瘞) là chữ hình thanh: 土 (thổ, đất) biểu nghĩa, 㾜 biểu âm. Theo Wiktionary, nghĩa là chôn cất, vùi giấu xuống đất. Tiểu triện và Lục thư thông xác nhận dạng này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chôn giấu", "Hạng Tần Suất (Jun Da)": "6406.0", "Tần Suất % (Jun Da)": "99.9917412568", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "瘗", "Unihan_Traditional (Chữ Phồn thể)": "瘞", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "ế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động chôn cất người chết hoặc chôn giấu đồ vật. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('雩', '{"9000": "6407.0", "Chữ Trung Quốc": "雩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 雨 | Số nét | 11 | nét | 雨 | vũ | biểu nghĩa | mưa | 于 | vu | biểu âm | 雩 = 雨 (Vũ, biểu nghĩa: mưa) + 于 (Vu, biểu âm); chữ hình thanh. Bộ 雨 chỉ đây liên quan đến mưa; 于 cho âm đọc yú. Chữ chỉ nghi lễ tế cầu mưa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vu\": mưa (雨) cầu khấn bằng nghi lễ Vu — thầy cúng vũ (vu) múa dưới bầu trời nắng hạn, cầu thần mưa (雨) xuống. | Gương Hán-Việt | vu — tiếng Việt dùng qua \"tế vu\" (tế cầu mưa), \"vu chúc\" (thầy cúng chúc tụng) | Mở khoá kiến thức | Biết 雩 mở khoá nghi lễ cổ đại: 雩祭 (tế cầu mưa), 舞雩 (múa cầu mưa — điển cố Luận Ngữ).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Đại triện | Tiểu triện | 雩 là chữ hình thanh: 雨 (vũ, mưa) biểu nghĩa, 于 (vu) biểu âm. Theo Wiktionary, chữ chỉ lễ cầu mưa — nghi lễ tôn giáo quan trọng của nông nghiệp cổ đại. Giáp cốt văn, kim văn, đại triện và tiểu triện đều có ảnh — chữ có lịch sử lâu đời. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tế đảo vũ, tế cầu mưa", "Hạng Tần Suất (Jun Da)": "6407.0", "Tần Suất % (Jun Da)": "99.9917536596", "GavinGrover_Once (Chiết tự trực tiếp)": "雨 + 亏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱雨亏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "雨", "Unihan_Simplified (Chữ Giản thể)": "雩", "Unihan_Traditional (Chữ Phồn thể)": "雩", "Pinyin_Xie": "yú", "Âm Hán Việt_Xie": "vu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ nghi lễ cầu mưa hoặc làm động từ chỉ việc thực hiện nghi lễ đó. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('麿', '{"9000": "6408.0", "Chữ Trung Quốc": "麿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 麻 | Số nét | 17 | nét | 麿 | ma | tượng hình | chữ Nhật mượn vào tiếng Trung; đại từ nhân xưng cổ Nhật | 麿 là chữ Kokuji (quốc tự Nhật Bản), mượn vào tiếng Trung. Không có phân tích IDS truyền thống. Wiktionary ghi rõ đây là chữ vay từ tiếng Nhật (obor|ja), không có nguồn gốc Hán tự thuần tuý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ma\": bộ 麻 (gai dầu) ở trên, bên dưới hình dáng cổ kính — chữ Nhật Ma-ro (麿) dùng trong tên quý tộc cổ Nhật như \"Hikaru Genji麿\". | Gương Hán-Việt | ma — ít dùng trong tiếng Việt; dùng khi phiên âm hoặc dịch tên tiếng Nhật | Mở khoá kiến thức | Biết 麿 mở khoá ngữ cảnh tên Nhật cổ: dùng trong tên quý tộc thời Heian như 光源氏麿.", "Tự nguyên_Xie": "麿 là chữ Kokuji (国字) — chữ Nhật Bản tự tạo, sau đó mượn vào tiếng Trung. Theo Wiktionary, nguồn gốc từ tiếng Nhật maro (まろ), đại từ nhân xưng cổ kính hoặc hậu tố gắn với tên người/vật nuôi. Trong tiếng Trung hiện đại chủ yếu dùng trong tên Nhật. Thuộc bộ 麻 (ma, gai dầu). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(Kokuji tiếng Nhật) Tôi, tôi (cổ xưa); pr. maro; hậu tố gắn liền với tên của một người hoặc vật nuôi", "Hạng Tần Suất (Jun Da)": "6408.0", "Tần Suất % (Jun Da)": "99.9917660624", "GavinGrover_Once (Chiết tự trực tiếp)": "麻 + 吕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴麻吕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "麻", "Unihan_Simplified (Chữ Giản thể)": "麿", "Unihan_Traditional (Chữ Phồn thể)": "麿", "Pinyin_Xie": "mo", "Âm Hán Việt_Xie": "mi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Đại từ | 代词 | Danh từ | 名词 | Chữ này chủ yếu dùng làm đại từ nhân xưng ngôi thứ nhất hoặc hậu tố đặt sau tên riêng trong tiếng Nhật cổ. | Đại từ | 代词 | Thay cho người hoặc vật đã nhắc tới (我, 这, 谁). Dùng đúng ở vị trí của danh từ. Chỉ người thì thêm 们 để thành số nhiều: 我们. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('檗', '{"9000": "6409.0", "Chữ Trung Quốc": "檗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 17 | nét | 辟 | tích | biểu âm | 木 | mộc | biểu nghĩa | cây | 檗 = 辟 (Tích, biểu âm) + 木 (Mộc, biểu nghĩa: cây); chữ hình thanh. Bộ 木 chỉ đây là loài cây; 辟 cho âm đọc bò.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bách\": cây (木) vỏ vàng sáng như mở (辟) ra — cây hoàng bá Bách vỏ vàng đắng, dùng làm thuốc Đông y trị nhiệt. | Gương Hán-Việt | bách — tiếng Việt dùng qua \"hoàng bách\" (黃檗) trong Đông y | Mở khoá kiến thức | Biết 檗 mở khoá từ dược thảo: 黃檗 (hoàng bá — Phellodendron, vị thuốc Đông y), 蘗 (mầm cây).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 檗 là chữ hình thanh: 木 (mộc, cây) biểu nghĩa, 辟 (tích) biểu âm. Theo Wiktionary, chữ dùng trong cụm 黃檗 (hoàng bá) — một loại cây dược liệu quan trọng trong Đông y, vỏ vàng dùng làm thuốc thanh nhiệt. Đại triện và tiểu triện đều có ảnh. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây hoàng bá", "Hạng Tần Suất (Jun Da)": "6409.0", "Tần Suất % (Jun Da)": "99.9917784653", "GavinGrover_Once (Chiết tự trực tiếp)": "辟 + 木", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱辟木", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "辟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "檗", "Unihan_Traditional (Chữ Phồn thể)": "檗", "Pinyin_Xie": "bò", "Âm Hán Việt_Xie": "nghiệt, bách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại cây thân gỗ dùng vỏ làm thuốc nhuộm hoặc vị thuốc đông y. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鼂', '{"9000": "6410.0", "Chữ Trung Quốc": "鼂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 黽 | Số nét | 18 | nét | 鼂 | trào | tượng hình | loài rùa biển; họ Trào — thuộc bộ 黽 | 鼂 là chữ thuộc bộ 黽 (mạnh, loài ếch/rùa). Wiktionary ghi \"Bất định, có thể là hội ý\" nhưng không phân tích cụ thể. Chữ dùng chỉ loài rùa biển và là họ tên người.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trào\": bộ 黽 (rùa/ếch) — họ Trào với hình ảnh con rùa biển to lớn, ẩn mình dưới đáy đại dương. | Gương Hán-Việt | trào — ít dùng trong tiếng Việt; gặp trong sử học qua \"Trào Thố\" (鼂錯) — nhân vật lịch sử Hán đại | Mở khoá kiến thức | Biết 鼂 mở khoá họ tên cổ: 鼂錯 (Trào Thố — quan đại thần nhà Hán nổi tiếng).", "Tự nguyên_Xie": "鼂 thuộc bộ 黽 (mạnh, ếch/rùa lớn). Theo Wiktionary, nguồn gốc không chắc chắn, có thể là hội ý. Nghĩa là loài rùa biển và họ tên người (họ Trào). chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "họ Trào", "Hạng Tần Suất (Jun Da)": "6410.0", "Tần Suất % (Jun Da)": "99.9917908681", "GavinGrover_Once (Chiết tự trực tiếp)": "日 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱日", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "鼂", "Unihan_Traditional (Chữ Phồn thể)": "鼂", "Pinyin_Xie": "cháo", "Âm Hán Việt_Xie": "trào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ riêng chỉ họ người hoặc danh từ chỉ loài ba ba lớn thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('褔', '{"9000": "6411.0", "Chữ Trung Quốc": "褔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 14 | nét | 衤 | y | biểu nghĩa | quần áo | 畐 | phúc | biểu âm | đầy đủ | 褔 = 衤 (Y, biểu nghĩa: quần áo) + 畐 (Phúc, biểu âm); chữ hình thanh. Bộ 衤 chỉ đây liên quan đến quần áo; 畐 cho âm đọc fù. Nghĩa là quần áo lót nhiều lớp hoặc đầy.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phúc\": áo (衤) nhiều lớp đầy đặn (畐) — người mặc áo dày lớp là người có phúc, áo đầy ắp gợi sự sung túc. | Gương Hán-Việt | phúc — tiếng Việt dùng qua \"phúc lợi\", \"may mắn\" (qua 福 phổ biến hơn); 褔 là chữ ít gặp hơn | Mở khoá kiến thức | Biết 褔 mở khoá từ về quần áo cổ: 褔衣 (áo nhiều lớp), phân biệt với 福 (phúc may mắn có bộ 示).", "Tự nguyên_Xie": "褔 là chữ hình thanh: 衣/衤 (y, quần áo) biểu nghĩa, 畐 (phúc, đầy) biểu âm. Theo Wiktionary, nghĩa là quần áo có nhiều lớp, phức tạp (complex, double). Tiểu triện có thể xác nhận. chưa có nguồn học thuật xác nhận chi tiết hơn về nghĩa mở rộng. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bộ phân loại cho các mặt hàng quần áo (cũ); đầy lên", "Hạng Tần Suất (Jun Da)": "6411.0", "Tần Suất % (Jun Da)": "99.9918280767", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 畐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤畐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "畐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "褔", "Unihan_Traditional (Chữ Phồn thể)": "褔", "Pinyin_Xie": "fù", "Âm Hán Việt_Xie": "phúc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Lượng từ | 量词 | Động từ | 动词 | Chữ này dùng làm lượng từ cho trang phục cổ hoặc làm động từ với nghĩa làm cho đầy đặn. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铟', '{"9000": "6412.0", "Chữ Trung Quốc": "铟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 11 | nét | 铟 | in | tượng hình | nguyên tố indi (In), bộ 金 | 铟 là chữ hiện đại chỉ nguyên tố indium (In). Không có dữ liệu Wiktionary anchor hay IDS. Thuộc bộ 金 (kim, kim loại) theo mẫu đặt tên nguyên tố kim loại trong tiếng Trung.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"in\": bộ 金 (kim loại) — nguyên tố In (indium) dùng \"in\" màn hình cảm ứng điện thoại hiện đại. | Gương Hán-Việt | in — dùng trong hoá học: \"nguyên tố indium\" viết là 铟 (In) | Mở khoá kiến thức | Biết 铟 mở khoá hệ thống tên nguyên tố kim loại: 铟 (In), 铊 (Tl), 铋 (Bi) — đều bộ 金.", "Tự nguyên_Xie": "铟 là chữ hiện đại đặt để phiên âm tên nguyên tố indium (In, số nguyên tử 49) — kim loại mềm dùng trong màn hình cảm ứng. Cấu trúc theo mẫu: bộ 金 + phần biểu âm gần yīn. chưa có nguồn học thuật xác nhận cấu trúc chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố indi, In", "Hạng Tần Suất (Jun Da)": "6412.0", "Tần Suất % (Jun Da)": "99.9918404795", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 因", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅因", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "因", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铟", "Unihan_Traditional (Chữ Phồn thể)": "銦", "Pinyin_Xie": "yīn", "Âm Hán Việt_Xie": "nhân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ nguyên tố kim loại Indi trong hóa học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲏', '{"9000": "6413.0", "Chữ Trung Quốc": "鲏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 13 | nét | 鲏 | bì | tượng hình | loài cá nhỏ (cá bã trầu) | 鲏 là chữ độc thể, bộ 魚 (ngư). Chữ dùng chủ yếu trong tên ghép 鳑鲏 (báng bì) chỉ một loài cá chép nhỏ. Không đủ dữ liệu để xác định rõ hình thanh hay hội ý; chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bì\": bộ 魚 (cá) + hình dạng con cá nhỏ — liên tưởng con cá bã trầu bé nhỏ bơi trong ao. | Gương Hán-Việt | \"bì\" trong 鳑鲏 (báng bì — loài cá chép nhỏ) | Mở khoá kiến thức | Biết 鲏 mở khoá từ chuyên ngành thủy sinh: 鳑鲏 (cá bã trầu), 鳑鲏魚.", "Tự nguyên_Xie": "Tiểu triện | Chữ 鲏 chỉ dùng trong từ ghép 鳑鲏 (báng bì), tên một loài cá chép nhỏ. Không tìm thấy nguồn phân tích cấu tạo chữ này trong Wiktionary. Dạng cổ 鮍 có ấn triện (tiểu triện). Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: báng bì 鰟鮍,鳑鲏)", "Hạng Tần Suất (Jun Da)": "6413.0", "Tần Suất % (Jun Da)": "99.9918900909", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 皮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼皮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "皮", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲏", "Unihan_Traditional (Chữ Phồn thể)": "鮍", "Pinyin_Xie": "pí", "Âm Hán Việt_Xie": "bì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, thường xuất hiện trong từ ghép để chỉ một loài cá nước ngọt nhỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蒗', '{"9000": "6414.0", "Chữ Trung Quốc": "蒗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 13 | nét | 蒗 | lãng | tượng hình | tên một loại cỏ; địa danh | 蒗 là chữ độc thể, bộ 艸 (thảo). Không có dữ liệu phân tích cấu tạo từ Wiktionary. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lãng\": bộ 艸 (cỏ) gợi cây cỏ — âm \"lãng\" như \"lãng mạn\", hình dung một bãi cỏ hoang vu nơi địa danh xa xôi. | Gương Hán-Việt | \"lãng\" trong địa danh Nín Lãng (宁蒗 — huyện ở Vân Nam) | Mở khoá kiến thức | Biết 蒗 giúp nhận ra địa danh 宁蒗彝族自治县 (huyện dân tộc Di Nín Lãng, Vân Nam).", "Tự nguyên_Xie": "Chữ 蒗 theo Wiktionary chỉ một loài thảo dược cổ (nay hiếm dùng), và là địa danh (huyện Nín Lãng, Vân Nam). Không có phân tích cấu tạo chữ. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên đất)", "Hạng Tần Suất (Jun Da)": "6414.0", "Tần Suất % (Jun Da)": "99.9919024937", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 浪", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹浪", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "浪", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蒗", "Unihan_Traditional (Chữ Phồn thể)": "蒗", "Pinyin_Xie": "làng", "Âm Hán Việt_Xie": "lạng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ riêng, chủ yếu dùng trong các tên đất đai hoặc địa danh của Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('魟', '{"9000": "6415.0", "Chữ Trung Quốc": "魟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 14 | nét | 魟 | hồng | tượng hình | cá đuối gai độc (stingray) | 魟 là chữ độc thể, bộ 魚 (ngư). Không có dữ liệu Wiktionary về cấu trúc nội bộ. Chưa có nguồn học thuật xác nhận loại chữ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hồng\": bộ 魚 (cá) — hình dung con cá đuối màu đỏ hồng bơi dưới đáy biển. | Gương Hán-Việt | \"hồng\" trong 魟魚 (hồng ngư — cá đuối) | Mở khoá kiến thức | Biết 魟 mở khoá từ thủy hải sản: 魟魚 (cá đuối), 長魟 (cá đuối dài).", "Tự nguyên_Xie": "Chữ 魟 chỉ cá đuối (ray/stingray), âm hóng (hóng) hoặc gōnɡ. Wiktionary không có phân tích cấu tạo. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá đuối gai độc", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 工", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚工", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "工", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "𫚉", "Unihan_Traditional (Chữ Phồn thể)": "魟", "Pinyin_Xie": "hóng", "Âm Hán Việt_Xie": "hồng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài cá đuối có gai độc ở đuôi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('遹', '{"9000": "6416.0", "Chữ Trung Quốc": "遹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 15 | nét | 遹 | duật | tượng hình | noi theo; tuân theo; cong queo | 遹 là chữ độc thể, bộ 辵 (sước — chỉ đi lại). Wiktionary không cung cấp phân tích cấu tạo nội bộ. Ảnh kim văn và đại triện cho thấy chữ có lịch sử lâu đời. Chưa xác định hình thanh hay hội ý từ nguồn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"duật\": bộ 辵 (đi lại) — hình dung người \"duật\" theo con đường cong queo, vừa đi vừa noi theo dấu người trước. | Gương Hán-Việt | \"duật\" trong 遹追 (duật truy — noi theo, truy tìm dấu vết tổ tiên) | Mở khoá kiến thức | Biết 遹 giúp đọc văn ngôn cổ điển: 遹追 (noi gương), 遹皇 (noi theo đường lớn).", "Tự nguyên_Xie": "Kim văn | Đại triện | Chữ 遹 (duật) theo Wiktionary mang nghĩa: đi lạc lối, lệch lạc (nghĩa cổ); tuân theo, noi theo, tuân thủ (nghĩa cổ điển). Có hình trong kim văn và đại triện. Bộ 辵 gợi ý liên quan đến việc đi lại. Không có phân tích cấu tạo chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "noi theo, nối theo; cong queo", "Hạng Tần Suất (Jun Da)": "6416.0", "Tần Suất % (Jun Da)": "99.9919267826", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 矞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶矞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "矞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "遹", "Unihan_Traditional (Chữ Phồn thể)": "遹", "Pinyin_Xie": "yù", "Âm Hán Việt_Xie": "duật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường dùng làm động từ trong văn ngôn với nghĩa tuân theo hoặc làm tính từ chỉ sự quanh co. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('攴', '{"9000": "6417.0", "Chữ Trung Quốc": "攴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 攴 | Số nét | 4 | nét | 攴 | phộc | tượng hình | tay cầm vật đánh — động tác gõ nhẹ | 攴 là chữ tượng hình: mô tả bàn tay (又) cầm một dụng cụ (sau biến dạng thành 卜) để đánh nhẹ. Wiktionary xác nhận đây là chữ tượng hình (liushu p). Phần công cụ sau bị âm hóa thành bộ 卜, nhưng không liên quan ý nghĩa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phộc\": hình ảnh bàn tay (又) cầm roi \"phộc\" vào — động tác gõ nhẹ, thúc giục. | Gương Hán-Việt | \"phộc\" dùng trong từ Hán-Việt cổ chỉ bộ thủ 攴 (phộc bộ); xưa dùng như 扑. | Mở khoá kiến thức | Biết 攴 giúp nhận ra bộ thủ này trong nhiều chữ: 政 (chính), 教 (giáo), 数 (số), 放 (phóng), 改 (cải), 收 (thu).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Tiểu triện | Theo Wiktionary: 攴 là chữ tượng hình vẽ bàn tay (又, hữu) cầm một dụng cụ — có thể là vũ khí hoặc roi — với nghĩa \"đánh nhẹ\". Phần công cụ về sau biến dạng thành thành phần biểu âm 卜. Chữ tương tự nhưng không liên quan: 支, 父. Trong giáp cốt văn, kim văn và tiểu triện đều có hình ảnh rõ ràng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "588.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Bốc (041) Hựu (018)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Bốc (số 041 - bói) ở trên chữ Hựu (số 018 - lại). Giải thích sự chuyển ý: Đây là chữ Hội ý. Trước khi làm việc gì phải bói toán đắn đo suy nghĩ kỹ. Phộc là hành động đánh khẽ, đánh nhẹ để răn đe.", "Nghĩa Tiếng Việt_Xie": "phộc; như \"phộc (bộ thủ)\" \n (Động) Đánh khẽ.\n§ Xưa dùng như phốc 扑.", "Hạng Tần Suất (Jun Da)": "6417.0", "Tần Suất % (Jun Da)": "99.9919386687", "GavinGrover_Once (Chiết tự trực tiếp)": "⺊ + 又", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺊又", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "又", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺊", "Unihan_Simplified (Chữ Giản thể)": "攴", "Unihan_Traditional (Chữ Phồn thể)": "攴", "Pinyin_Xie": "pū", "Âm Hán Việt_Xie": "phộc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chủ yếu dùng làm động từ chỉ hành động gõ nhẹ hoặc làm bộ thủ trong cấu tạo chữ Hán. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蝥', '{"9000": "6418.0", "Chữ Trung Quốc": "蝥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 15 | nét | 敄 | biểu âm | 虫 | trùng | biểu nghĩa | côn trùng | 蝥 = 敄 (biểu âm) + 虫 (Trùng, biểu nghĩa: côn trùng). Chữ hình thanh. Bộ 虫 cho biết liên quan đến loài côn trùng/sâu bọ; 敄 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mao\": bộ 虫 (côn trùng) + âm 敄 — hình dung con bọ \"mao\" (斑蝥) đốm hoa cánh cứng dùng trong thuốc độc. | Gương Hán-Việt | \"mao\" trong 斑蝥 (ban mao — loài bọ cánh cứng độc) | Mở khoá kiến thức | Biết 蝥 mở khoá từ y học cổ truyền: 斑蝥 (bọ cánh cứng ban mao), 蝥弧 (tên chiến kỳ cổ).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary: 蝥 là chữ hình thanh gồm 敄 (biểu âm) và 虫 (biểu nghĩa: côn trùng). Chữ dùng trong 斑蝥 (ban mao) — loài bọ cánh cứng có độc dùng trong y học cổ truyền, tương tự cantharides. Cũng dùng trong 蝥弧 (mao hồ). Chỉ có ảnh tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con xén tóc", "Hạng Tần Suất (Jun Da)": "6418.0", "Tần Suất % (Jun Da)": "99.9919505547", "GavinGrover_Once (Chiết tự trực tiếp)": "敄 + 虫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱敄虫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蝥", "Unihan_Traditional (Chữ Phồn thể)": "蝥", "Pinyin_Xie": "máo", "Âm Hán Việt_Xie": "mâu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ các loại côn trùng gây hại cho mùa màng như sâu ăn lá. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('茆', '{"9000": "6419.0", "Chữ Trung Quốc": "茆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 8 | nét | 茆 | mão | tượng hình | rau lữu (Brasenia schreberi); cỏ tranh; họ Mao | 茆 là chữ độc thể, bộ 艸 (thảo). Wiktionary không có phân tích cấu tạo nội bộ. Chưa xác định hình thanh hay hội ý. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mão\": bộ 艸 (cỏ) — hình dung bụi cỏ tranh \"mão\" mọc ven ao nước, gần với rau lữu. | Gương Hán-Việt | \"mão\" trong 茆茨 (mão từ — nhà lợp cỏ tranh); đồng âm với 茅. | Mở khoá kiến thức | Biết 茆 giúp đọc địa danh và văn học cổ: 白茆 (Bạch Mão), 茆店 (quán cỏ tranh).", "Tự nguyên_Xie": "Chữ 茆 (mão) theo Wiktionary chỉ hai thứ: (1) cây rau lữu nước (water shield, Brasenia schreberi), đồng nghĩa với 蒓; (2) biến thể của 茅 (cỏ tranh). Cũng là họ người. Không có phân tích cấu tạo. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rau lữu (tên khoa học: brasenia schreberi); cỏ lợp nhà; họ Mao", "Hạng Tần Suất (Jun Da)": "6419.0", "Tần Suất % (Jun Da)": "99.9919624408", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 卯", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹卯", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "茆", "Unihan_Traditional (Chữ Phồn thể)": "茆", "Pinyin_Xie": "máo", "Âm Hán Việt_Xie": "mao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ một loại rau nước hoặc cỏ tranh dùng để lợp mái nhà. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蓁', '{"9000": "6420.0", "Chữ Trung Quốc": "蓁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 13 | nét | 蓁 | trăn | tượng hình | cây cối xanh um; bụi rậm gai góc | 蓁 là chữ độc thể, bộ 艸 (thảo). Wiktionary không cung cấp phân tích cấu tạo nội bộ. Có ảnh tiểu triện và lục thư thông. Chưa có nguồn học thuật xác nhận cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trăn\": bộ 艸 (cỏ cây) — hình dung bụi cây \"trăn trở\" um tùm, rậm rạp không lối vào. | Gương Hán-Việt | \"trăn\" trong 蓁蓁 (trăn trăn — um tùm, rậm rạp) dùng trong thơ Kinh Thi. | Mở khoá kiến thức | Biết 蓁 giúp đọc văn học cổ điển: 蓁蓁 (cây cối xanh mướt), 蓁荒 (hoang vu um tùm).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ 蓁 (trăn) theo Wiktionary mang nghĩa: (văn học) cây cối xanh tốt, um tùm; bụi rậm, cây dại; biến thể của 榛 (cây phỉ). Có hình tiểu triện và lục thư thông từ hanziyuan. Không có phân tích cấu tạo. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây cối xanh um tùm; rậm rạp, gai góc, bụi rậm", "Hạng Tần Suất (Jun Da)": "6420.0", "Tần Suất % (Jun Da)": "99.9919743269", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 秦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹秦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "秦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蓁", "Unihan_Traditional (Chữ Phồn thể)": "蓁", "Pinyin_Xie": "zhēn", "Âm Hán Việt_Xie": "trăn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ miêu tả cảnh cây cối phát triển xanh tốt, rậm rạp. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嚆', '{"9000": "6421.0", "Chữ Trung Quốc": "嚆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 16 | nét | 口 | khẩu | biểu nghĩa | miệng, tiếng kêu | 蒿 | hao | biểu âm | 嚆 = 口 (Khẩu, biểu nghĩa: miệng, tiếng kêu) + 蒿 (Hao, biểu âm). Chữ hình thanh. Bộ 口 cho biết liên quan đến âm thanh; 蒿 cung cấp âm đọc hāo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hao\": miệng (口) + cỏ hao (蒿) — hình dung tiếng \"hao hao\" của mũi tên phát âm rít qua không khí, báo hiệu mở đầu trận chiến. | Gương Hán-Việt | \"hao\" trong 嚆矢 (hao thỉ — mũi tên rú, ẩn dụ khởi đầu của việc gì) | Mở khoá kiến thức | Biết 嚆 giúp hiểu thành ngữ văn ngôn: 嚆矢 (mũi tên khai chiến, ẩn dụ tiên phong).", "Tự nguyên_Xie": "Theo Wiktionary: 嚆 là chữ hình thanh gồm 口 (biểu nghĩa: miệng) và 蒿 (biểu âm). Chữ chỉ tiếng kêu vang, tiếng ồn, hay tên gọi \"mũi tên có âm thanh\" (嚆矢 — mũi tên phát tiếng rú khi bay). Không có ảnh cổ tự. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng động", "Hạng Tần Suất (Jun Da)": "6421.0", "Tần Suất % (Jun Da)": "99.9919862129", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 蒿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口蒿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "蒿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嚆", "Unihan_Traditional (Chữ Phồn thể)": "嚆", "Pinyin_Xie": "hāo", "Âm Hán Việt_Xie": "hao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ trong từ ghép như hao thỉ để chỉ âm thanh vang lên mở đầu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('忮', '{"9000": "6422.0", "Chữ Trung Quốc": "忮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 7 | nét | 心 | tâm | biểu nghĩa | tâm trí, cảm xúc | 支 | chi | biểu âm | 忮 = 心 (Tâm, biểu nghĩa: tâm trí, tình cảm) + 支 (Chi, biểu âm). Chữ hình thanh. Bộ 心 cho biết liên quan đến tâm lý; 支 cung cấp âm đọc zhì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kị\": tâm (心) + chi (支) — hình dung trái tim \"kị\" người khác, ganh ghét như cái gai (chi) đâm vào lòng. | Gương Hán-Việt | \"kị\" trong 不忮不求 (bất kị bất cầu — không ganh ghét, không ham muốn) | Mở khoá kiến thức | Biết 忮 giúp hiểu thành ngữ cổ điển: 不忮不求 (phẩm hạnh không ganh ghét không tham cầu).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary: 忮 là chữ hình thanh gồm 心 (biểu nghĩa: tâm) và 支 (biểu âm). Chữ mang nghĩa: cố chấp, bướng bỉnh; ghen ghét, thù hằn. Có ảnh tiểu triện. Thành ngữ nổi tiếng: 不忮不求 (bất kị bất cầu — không ganh ghét không tham cầu). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ghen ghét; ganh ghét", "Hạng Tần Suất (Jun Da)": "6422.0", "Tần Suất % (Jun Da)": "99.991998099", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 支", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄支", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "支", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "忮", "Unihan_Traditional (Chữ Phồn thể)": "忮", "Pinyin_Xie": "zhì", "Âm Hán Việt_Xie": "kĩ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ miêu tả tính cách ghen ghét, đố kị hoặc ngang bướng của con người. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('篌', '{"9000": "6423.0", "Chữ Trung Quốc": "篌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 15 | nét | 篌 | hầu | tượng hình | đàn không hầu (loại đàn hạc cổ) | 篌 là chữ độc thể, bộ 竹 (trúc). Wiktionary không có phân tích cấu tạo nội bộ. Chữ dùng chủ yếu trong từ ghép 箜篌. Chưa có nguồn học thuật xác nhận cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hầu\": bộ 竹 (tre) — hình dung cây đàn \"không hầu\" làm từ tre, tiếng nhạc vang lên như tiếng \"hầu hầu\". | Gương Hán-Việt | \"hầu\" trong 箜篌 (không hầu — loại đàn hạc cổ) | Mở khoá kiến thức | Biết 篌 giúp nhận ra 箜篌 — nhạc cụ dây cổ Trung Hoa nổi tiếng trong thơ Đường.", "Tự nguyên_Xie": "Chữ 篌 (hầu) theo Wiktionary chỉ một loại tre; chủ yếu dùng trong 箜篌 — tên loại đàn hạc cổ của Trung Quốc có nguồn gốc từ Tây Vực. Không có phân tích cấu tạo. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: không hầu 箜篌)", "Hạng Tần Suất (Jun Da)": "6423.0", "Tần Suất % (Jun Da)": "99.992009985", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 侯", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮侯", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "侯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "篌", "Unihan_Traditional (Chữ Phồn thể)": "篌", "Pinyin_Xie": "hóu", "Âm Hán Việt_Xie": "hầu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ và hầu như chỉ xuất hiện trong danh từ ghép khống hầu để chỉ một loại nhạc cụ cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('菧', '{"9000": "6424.0", "Chữ Trung Quốc": "菧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 菧 | đê | tượng hình | tên cây thảo dược cổ | 菧 là chữ độc thể, bộ 艸 (thảo). Không có dữ liệu Wiktionary về cấu tạo. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đê\": bộ 艸 (cỏ cây) — hình dung loài cây thảo \"đê thấp\" mọc sát mặt đất. | Gương Hán-Việt | \"đê\" trong từ cổ chỉ loại cây thảo dược hiếm gặp trong văn bản cổ điển. | Mở khoá kiến thức | Biết 菧 giúp nhận ra bộ 艸 trong các chữ thực vật và tra từ điển Hán cổ.", "Tự nguyên_Xie": "Chữ 菧 (đê) không có nguồn Wiktionary. Bộ 艸 cho thấy liên quan đến thực vật. Nghĩa cụ thể không rõ ràng từ nguồn học thuật. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "stibene", "Hạng Tần Suất (Jun Da)": "6424.0", "Tần Suất % (Jun Da)": "99.9920218711", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 底", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹底", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "底", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "菧", "Unihan_Traditional (Chữ Phồn thể)": "菧", "Pinyin_Xie": "dǐ", "Âm Hán Việt_Xie": "để", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong thuật ngữ hóa học để chỉ hợp chất hữu cơ stibene. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('卺', '{"9000": "6425.0", "Chữ Trung Quốc": "卺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 卩 | Số nét | 8 | nét | 卺 | cẩn | tượng hình | chén rượu hôn lễ làm từ quả bầu khô | 卺 là chữ độc thể, bộ 卩 (tiết). Wiktionary ghi dạng cổ là 巹. Không có phân tích cấu tạo nội bộ. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cẩn\": chén bầu hôn lễ — \"cẩn\" như \"hợp cẩn\" (合卺), đôi tân hôn uống rượu từ chén bầu chia đôi. | Gương Hán-Việt | \"cẩn\" trong 合卺 (hợp cẩn — lễ uống rượu hôn phối); 行卺 (hành cẩn — thực hiện lễ hợp cẩn) | Mở khoá kiến thức | Biết 卺 mở khoá từ lễ nghi cổ đại: 合卺 (hợp cẩn — lễ uống rượu cưới), 行卺礼 (lễ hợp cẩn).", "Tự nguyên_Xie": "Chữ 卺 (cẩn), dạng cổ 巹, theo Wiktionary chỉ cái muôi/chén làm từ quả bầu khô (dried gourd) dùng trong hôn lễ cổ đại Trung Quốc. Đôi tân hôn uống rượu chung từ hai nửa quả bầu này trong lễ hợp cẩn (合卺). Không có phân tích cấu tạo chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chén uống rượu làm từ quả bầu", "Hạng Tần Suất (Jun Da)": "6425.0", "Tần Suất % (Jun Da)": "99.9920337571", "GavinGrover_Once (Chiết tự trực tiếp)": "丞 + 㔾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱丞㔾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㔾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "丞", "Unihan_Simplified (Chữ Giản thể)": "卺", "Unihan_Traditional (Chữ Phồn thể)": "巹", "Pinyin_Xie": "jǐn", "Âm Hán Việt_Xie": "cẩn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ chiếc chén gỗ hoặc quả bầu cắt đôi dùng trong nghi lễ hợp cẩn ngày cưới. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('郫', '{"9000": "6426.0", "Chữ Trung Quốc": "郫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 10 | nét | 郫 | bì | tượng hình | địa danh (huyện Bì, Tứ Xuyên) | 郫 là chữ địa danh, bộ 邑 (ấp — chỉ đô thị, địa danh). Wiktionary không cung cấp phân tích cấu tạo nội bộ. Có ảnh tiểu triện. Chưa có nguồn học thuật xác nhận cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bì\": bộ 邑 (ấp — địa danh) — nhớ huyện \"Bì\" ở Tứ Xuyên nơi sản xuất đậu tương ớt nổi tiếng. | Gương Hán-Việt | \"bì\" trong 郫縣 (bì huyện — huyện Bì, Tứ Xuyên); 郫都 (Bì Đô — quận hiện nay) | Mở khoá kiến thức | Biết 郫 giúp nhận ra địa danh 郫县 và thương hiệu 郫县豆瓣 (tương đậu ớt nổi tiếng).", "Tự nguyên_Xie": "Tiểu triện | Chữ 郫 (bì) là địa danh, chỉ huyện Bì (郫縣, nay là quận Bì Đô 郫都) thuộc Thành Đô, Tứ Xuyên. Nổi tiếng với đậu tương ớt 郫县豆瓣 (bì huyện đậu bạn). Có ảnh tiểu triện từ hanziyuan. Không có phân tích cấu tạo. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên đất)", "Hạng Tần Suất (Jun Da)": "6426.0", "Tần Suất % (Jun Da)": "99.9920456432", "GavinGrover_Once (Chiết tự trực tiếp)": "卑 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰卑阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "郫", "Unihan_Traditional (Chữ Phồn thể)": "郫", "Pinyin_Xie": "pí", "Âm Hán Việt_Xie": "bì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ riêng chỉ địa danh cổ, hiện nay thường thấy trong tên loại tương ớt nổi tiếng của vùng Tứ Xuyên. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('篠', '{"9000": "6427.0", "Chữ Trung Quốc": "篠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 16 | nét | 竹 | trúc | biểu nghĩa | tre | 條 | điều | biểu âm | 篠 = 竹 (Trúc, biểu nghĩa: tre) + 條 (Điều, biểu âm). Chữ hình thanh. Bộ 竹 cho biết liên quan đến tre; 條 cung cấp âm đọc xiǎo. Chỉ có ảnh lục thư thông, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiểu\": trúc (竹) + điều (條, âm) — hình dung cây \"tiểu trúc\" mảnh dẻ, thân nhỏ xinh uốn lượn. | Gương Hán-Việt | \"tiểu\" trong 篠竹 (tiểu trúc — tre mảnh); đồng âm với 小 (nhỏ). | Mở khoá kiến thức | Biết 篠 giúp đọc văn học cổ điển về thiên nhiên: 叢篠 (bụi tre nhỏ), 篠寢 (lều tre nhỏ).", "Tự nguyên_Xie": "Lục thư thông | Theo Wiktionary: 篠 là chữ hình thanh gồm 竹 (biểu nghĩa: tre) và 條 (biểu âm). Nghĩa: tre mảnh, tre nhỏ (văn học). Chỉ có ảnh lục thư thông (Ming dynasty compilation), chưa thấy trong giáp cốt hay kim văn — chữ tạo muộn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Tiểu", "Hạng Tần Suất (Jun Da)": "6427.0", "Tần Suất % (Jun Da)": "99.9920575293", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 條", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮條", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "條", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "篠", "Unihan_Traditional (Chữ Phồn thể)": "篠", "Pinyin_Xie": "xiǎo", "Âm Hán Việt_Xie": "tiểu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại tre nhỏ hoặc dùng trong tên người và địa danh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('犰', '{"9000": "6428.0", "Chữ Trung Quốc": "犰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 5 | nét | 犰 | cầu | tượng hình | con tatu (armadillo) | 犰 là chữ độc thể, bộ 犬 (khuyển). Không có nguồn Wiktionary về cấu tạo. Chữ dùng chủ yếu trong tên ghép 犰狳 (cầu du — con tatu). Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cầu\": bộ 犬 (thú) — con thú \"cầu\" (犰狳) có vỏ giáp như cái cầu vồng, thu mình thành quả bóng khi gặp nguy hiểm. | Gương Hán-Việt | \"cầu\" trong 犰狳 (cầu du — con tatu) | Mở khoá kiến thức | Biết 犰 giúp nhận ra tên động vật 犰狳 (tatu/armadillo) trong tài liệu sinh học.", "Tự nguyên_Xie": "Chữ 犰 không có nguồn Wiktionary. Bộ 犬 (chó) cho thấy liên quan đến loài thú. Chủ yếu dùng trong 犰狳 (cầu du) — con tatu (armadillo), một loài thú có vỏ giáp. Chưa có nguồn học thuật xác nhận cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con tatu", "Hạng Tần Suất (Jun Da)": "6428.0", "Tần Suất % (Jun Da)": "99.9921283288", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 九", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭九", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "九", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "犰", "Unihan_Traditional (Chữ Phồn thể)": "犰", "Pinyin_Xie": "qiú", "Âm Hán Việt_Xie": "cừu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ khi kết hợp với chữ du để chỉ con tatu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('狳', '{"9000": "6429.0", "Chữ Trung Quốc": "狳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 10 | nét | 狳 | du | tượng hình | con tatu (armadillo) — dùng trong 犰狳 | 狳 là chữ độc thể, bộ 犬 (khuyển). Wiktionary ghi chủ yếu dùng trong 犰狳. Không có phân tích cấu tạo nội bộ. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"du\": bộ 犬 (thú) — con thú \"du\" (犰狳) lang thang (du lịch) với bộ giáp trên lưng. | Gương Hán-Việt | \"du\" trong 犰狳 (cầu du — con tatu) | Mở khoá kiến thức | Biết 狳 giúp nhận ra 犰狳 (tatu) trong sách sinh học và thơ văn hiện đại.", "Tự nguyên_Xie": "Chữ 狳 (du) theo Wiktionary dùng trong 犰狳 (cầu du — con tatu). Có nghĩa cổ: một loại thú trong thần thoại Trung Quốc. Bộ 犬 liên quan đến thú vật. Không có phân tích cấu tạo chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con ta-tu (động vật)", "Hạng Tần Suất (Jun Da)": "6429.0", "Tần Suất % (Jun Da)": "99.9921396981", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 余", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭余", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "余", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "狳", "Unihan_Traditional (Chữ Phồn thể)": "狳", "Pinyin_Xie": "yú", "Âm Hán Việt_Xie": "trư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ khi kết hợp với chữ cầu để chỉ con tatu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('陠', '{"9000": "6430.0", "Chữ Trung Quốc": "陠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 9 | nét | 陠 | phô | tượng hình | (nghĩa chưa rõ — chữ hiếm) | 陠 là chữ độc thể, bộ 阜 (phụ — đồi, địa hình). Wiktionary chỉ có phát âm, không có định nghĩa cụ thể (rfdef). Không có phân tích cấu tạo. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phô\": bộ 阜 (đồi cao) — hình dung mảnh đất \"phô\" bày trước mặt, có địa hình gồ ghề. | Gương Hán-Việt | \"phô\" trong từ cổ và văn bản hiếm liên quan đến địa hình. | Mở khoá kiến thức | Biết 陠 giúp nhận ra bộ 阜 trong các chữ địa hình: 陵 (lăng), 陡 (đốc), 阶 (giai).", "Tự nguyên_Xie": "Chữ 陠 (phô) theo Wiktionary chỉ có ghi chú phát âm, không có định nghĩa rõ ràng. Bộ 阜 (đồi, địa hình cao) gợi ý có thể liên quan đến địa hình. Chữ cực hiếm. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "陠", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + 甫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝甫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "陠", "Unihan_Traditional (Chữ Phồn thể)": "陠", "Pinyin_Xie": "pū", "Âm Hán Việt_Xie": "phô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ riêng chỉ địa danh cổ hoặc bờ đất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蹁', '{"9000": "6431.0", "Chữ Trung Quốc": "蹁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 16 | nét | 蹁 | biền | tượng hình | đi khập khiễng | 蹁 là chữ độc thể, bộ 足 (túc). Wiktionary không cung cấp phân tích cấu tạo nội bộ. Có ảnh tiểu triện. Chưa có nguồn học thuật xác nhận cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"biền\": bộ 足 (chân) — dáng chân \"biền\" đi không đều, khập khiễng mà lại có vẻ uyển chuyển như vũ điệu. | Gương Hán-Việt | \"biền\" trong 蹁躚 (biền tiên — dáng đi uyển chuyển, nhảy múa) | Mở khoá kiến thức | Biết 蹁 giúp hiểu từ thơ văn cổ: 蹁躚 (dáng bay lượn nhẹ nhàng, uyển chuyển).", "Tự nguyên_Xie": "Tiểu triện | Chữ 蹁 (biền) theo Wiktionary nghĩa là đi khập khiễng (walk with a limp). Dùng trong 蹁躚 — dáng đi uyển chuyển, nhảy múa. Bộ 足 liên quan đến chân, dáng đi. Có ảnh tiểu triện từ hanziyuan. Không có phân tích cấu tạo. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khập khiễng", "Hạng Tần Suất (Jun Da)": "6431.0", "Tần Suất % (Jun Da)": "99.9921624366", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 扁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊扁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "扁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "蹁", "Unihan_Traditional (Chữ Phồn thể)": "蹁", "Pinyin_Xie": "pián", "Âm Hán Việt_Xie": "biên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Làm động từ chỉ dáng đi khập khiễng hoặc kết hợp tạo từ láy chỉ dáng múa uyển chuyển. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蓐', '{"9000": "6432.0", "Chữ Trung Quốc": "蓐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 13 | nét | 蓐 | náu | tượng hình | đệm cỏ, chiếu cỏ; cỏ dại mọc um tùm | 蓐 là chữ độc thể, bộ 艸 (thảo). Wiktionary không có định nghĩa rõ ràng (rfdef) nhưng các từ ghép cho thấy nghĩa: đệm cỏ, giường đẻ (臨蓐), vết lở (蓐瘡). Có ảnh tiểu triện và lục thư thông. Chưa có nguồn học thuật xác nhận cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"náu\": bộ 艸 (cỏ) — tấm đệm cỏ \"náu\" thân người nằm nghỉ — gợi cảnh sản phụ nằm trên đệm cỏ. | Gương Hán-Việt | \"náu\" trong 臨蓐 (lâm náu — lúc sắp sinh), 床蓐 (sàng náu — đệm giường) | Mở khoá kiến thức | Biết 蓐 giúp đọc văn ngôn y học và hôn tục cổ: 臨蓐 (sắp sinh), 蓐母 (bà đỡ), 坐蓐 (ngồi đẻ).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ 蓐 (náu) theo từ ghép trong Wiktionary: 床蓐 (đệm giường), 臨蓐 (lúc sắp sinh — nằm trên đệm cỏ), 蓐母 (bà đỡ), 蓐收 (thần thu hoạch). Bộ 艸 liên quan đến cỏ cây. Có ảnh tiểu triện và lục thư thông. Chưa có phân tích cấu tạo chi tiết. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỏ dại mọc um tùm; cái đệm cỏ", "Hạng Tần Suất (Jun Da)": "6432.0", "Tần Suất % (Jun Da)": "99.9921738059", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 辱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹辱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "辱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蓐", "Unihan_Traditional (Chữ Phồn thể)": "蓐", "Pinyin_Xie": "rù", "Âm Hán Việt_Xie": "nhục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ tấm đệm lót hoặc liên quan đến thời kỳ sinh đẻ của phụ nữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('菃', '{"9000": "6433.0", "Chữ Trung Quốc": "菃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 10 | nét | 菃 | cù | tượng hình | tên cây thảo (dùng trong địa danh) | 菃 là chữ độc thể, bộ 艸 (thảo). Wiktionary chỉ ghi dùng trong địa danh (zh-used2 n). Không có phân tích cấu tạo. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cù\": bộ 艸 (cỏ cây) — cây cỏ \"cù\" mọc ở địa danh xa xôi, hiếm gặp. | Gương Hán-Việt | \"cù\" trong từ địa danh hiếm, văn bản cổ có bộ 艸. | Mở khoá kiến thức | Biết 菃 giúp nhận ra bộ 艸 trong các chữ thực vật hiếm và địa danh cổ.", "Tự nguyên_Xie": "Chữ 菃 (cù) theo Wiktionary chỉ dùng trong địa danh (zh-used2|n). Bộ 艸 gợi liên quan đến thực vật. Nghĩa cụ thể không rõ ràng từ nguồn học thuật. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "胃", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 洰", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹洰", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "洰", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "菃", "Unihan_Traditional (Chữ Phồn thể)": "菃", "Pinyin_Xie": "qú", "Âm Hán Việt_Xie": "cù", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn ngôn để chỉ dạ dày của muông thú. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('埝', '{"9000": "6434.0", "Chữ Trung Quốc": "埝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 11 | nét | 埝 | niệm | tượng hình | bờ đất giữ nước; bờ ruộng | 埝 là chữ độc thể, bộ 土 (thổ). Wiktionary xác nhận nghĩa là bờ đất giữ nước, bờ ruộng. Không có phân tích cấu tạo nội bộ. Chưa có nguồn học thuật xác nhận cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"niệm\": thổ (土, đất) — bờ đất \"niệm niệm\" bao quanh ruộng, giống hình ảnh người \"niệm\" giữ nước lại. | Gương Hán-Việt | \"niệm\" trong 子埝 (tử niệm — bờ ruộng nhỏ); đồng âm 念 (niệm — nhớ). | Mở khoá kiến thức | Biết 埝 giúp đọc từ vựng nông nghiệp và thủy lợi: 子埝 (bờ nhỏ), 民埝 (đê dân), 圩埝 (bờ đê).", "Tự nguyên_Xie": "Chữ 埝 (niệm) theo Wiktionary chỉ bờ đất giữ nước, đê bao quanh ruộng lúa. Tương tự 圩 (vu). Bộ 土 (đất) liên quan đến địa hình, đất. Từ ghép: 子埝 (bờ nhỏ), 民埝 (đê dân làm). Không có phân tích cấu tạo. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: vu niệm 圩埝)", "Hạng Tần Suất (Jun Da)": "6434.0", "Tần Suất % (Jun Da)": "99.9922079137", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 念", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土念", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "念", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "埝", "Unihan_Traditional (Chữ Phồn thể)": "埝", "Pinyin_Xie": "niàn", "Âm Hán Việt_Xie": "niệm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ bờ đất đắp cao quanh ruộng hoặc đê nhỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蕞', '{"9000": "6435.0", "Chữ Trung Quốc": "蕞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 15 | nét | 蕞 | toái | tượng hình | nhỏ bé, tí xíu | 蕞 là chữ độc thể, bộ 艸 (thảo). Wiktionary chỉ ghi dùng trong 蕞爾 (toái nhĩ — nhỏ bé). Không có phân tích cấu tạo. Chưa có nguồn học thuật xác nhận cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"toái\": bộ 艸 (cỏ nhỏ) — cọng cỏ \"toái\" tí hon, \"蕞爾\" nhỏ xíu như ngón tay. | Gương Hán-Việt | \"toái\" trong 蕞爾 (toái nhĩ — nhỏ bé, tí hon) | Mở khoá kiến thức | Biết 蕞 giúp hiểu thành ngữ văn học cổ: 蕞爾小國 (nước nhỏ tí hon).", "Tự nguyên_Xie": "Chữ 蕞 (toái) theo Wiktionary chỉ dùng trong 蕞爾 — tính từ chỉ sự nhỏ bé, tí hon. Bộ 艸 liên quan đến thực vật, có thể gợi hình ảnh cây cỏ nhỏ tí. Không có phân tích cấu tạo. Chưa có nguồn học thuật. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhỏ bé", "Hạng Tần Suất (Jun Da)": "6435.0", "Tần Suất % (Jun Da)": "99.992219283", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 最", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹最", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "最", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蕞", "Unihan_Traditional (Chữ Phồn thể)": "蕞", "Pinyin_Xie": "zuì", "Âm Hán Việt_Xie": "tụi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ đứng trước danh từ để miêu tả quy mô nhỏ bé. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('喈', '{"9000": "6436.0", "Chữ Trung Quốc": "喈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 12 | nét | 喈 | giai | tượng hình | âm thanh hòa điệu; tiếng nhạc; tiếng chim hót | 喈 là chữ độc thể, bộ 口 (khẩu). Wiktionary chỉ có Han etym mà không có phân tích cụ thể. Có ảnh tiểu triện và lục thư thông. Chưa có nguồn học thuật xác nhận cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giai\": bộ 口 (miệng) — tiếng \"giai giai\" hòa điệu, như tiếng chim hót vui tươi buổi sáng. | Gương Hán-Việt | \"giai\" trong 喈喈 (giai giai — tiếng chim hót hòa điệu); đồng âm 皆 (giai — đều). | Mở khoá kiến thức | Biết 喈 giúp đọc thơ văn miêu tả thiên nhiên: 喈喈鸡鸣 (tiếng gà gáy rộn ràng).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ 喈 (giai) chỉ âm thanh hòa điệu, tiếng nhạc, tiếng chim hót vui. Bộ 口 liên quan đến âm thanh, miệng. Có ảnh tiểu triện và lục thư thông từ hanziyuan. Không có phân tích cấu tạo chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xập xình (âm thanh)", "Hạng Tần Suất (Jun Da)": "6436.0", "Tần Suất % (Jun Da)": "99.9922306523", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 皆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口皆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "皆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "喈", "Unihan_Traditional (Chữ Phồn thể)": "喈", "Pinyin_Xie": "jiē", "Âm Hán Việt_Xie": "dê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Từ tượng thanh | 象声词 | Thường dùng làm tính từ miêu tả tiếng chim hót hoặc tiếng nhạc êm dịu. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('戋', '{"9000": "6437.0", "Chữ Trung Quốc": "戋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 戈 | Số nét | 5 | nét | 戋 | tiên | tượng hình | nhỏ bé, ít ỏi — dạng giản thể của 戔 | 戋 là chữ độc thể, bộ 戈 (qua). Wiktionary ghi đây là giản thể của 戔. Dạng cổ 戔 gồm hai cây kích (戈) chồng lên nhau, gợi ý vật nhỏ bé do chia cắt. Có ảnh giáp cốt văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiên\": hai cây kích (戈+戈) chồng nhau — vật bị \"tiêm\" cắt nhỏ, ít ỏi tầm thường. | Gương Hán-Việt | \"tiên\" là bộ thủ trong 钱 (tiền — tiền bạc), 浅 (thiển — nông cạn), 贱 (tiện — rẻ tiền) | Mở khoá kiến thức | Biết 戋 mở khoá hàng chục chữ có bộ thủ này: 钱 (tiền), 浅 (nông), 贱 (hèn), 残 (tàn), 践 (tiễn).", "Tự nguyên_Xie": "Giáp cốt văn | Chữ 戋 là giản thể của 戔. Dạng cổ 戔 gồm hai bộ 戈 (qua — giáo, kích) chồng nhau, biểu thị vật bị chia cắt thành nhỏ bé. Có ảnh giáp cốt văn. Trong tiếng Trung hiện đại, 戋 dùng làm bộ phận trong nhiều chữ như 钱 (tiền), 浅 (thiển), 贱 (tiện). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhỏ nhặt", "Hạng Tần Suất (Jun Da)": "6437.0", "Tần Suất % (Jun Da)": "99.9922420216", "GavinGrover_Once (Chiết tự trực tiếp)": "㇂ + 二 + ㇒ + 丶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "Ký hiệu: built", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "㇂二㇒丶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㇂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "二", "Unihan_Simplified (Chữ Giản thể)": "戋", "Unihan_Traditional (Chữ Phồn thể)": "戔", "Pinyin_Xie": "jiān", "Âm Hán Việt_Xie": "tiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ bổ nghĩa cho danh từ hoặc xuất hiện dưới dạng từ láy. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('赙', '{"9000": "6438.0", "Chữ Trung Quốc": "赙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 14 | nét | 赙 | phú | tượng hình | tiền viếng tang; tặng tiền cho người chết | 赙 là chữ độc thể, bộ 貝 (bối). Wiktionary ghi đây là giản thể của 賻. Bộ 貝 gợi liên quan đến tiền tệ. Có ảnh tiểu triện và lục thư thông.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phú\": bối (貝, tiền) — tiền \"phú\" viếng tang, trao cho gia đình như nghĩa cử thương xót. | Gương Hán-Việt | \"phú\" trong 賻儀 (phú nghi — tiền phúng điếu), 賻贈 (phú tặng — tặng tiền viếng tang) | Mở khoá kiến thức | Biết 赙/賻 giúp đọc văn bản lễ nghi tang tế: 賻儀 (tiền phúng điếu), 送赙 (gửi tiền viếng).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ 赙 (phú) là giản thể của 賻 — nghĩa tiền viếng tang, tiền phúng điếu tặng cho gia đình người mất để giúp chịu phí mai táng. Bộ 貝 (vỏ sò, tiền tệ) biểu nghĩa. Có ảnh tiểu triện và lục thư thông. Không có phân tích cấu tạo chi tiết. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tặng tiền cho người chết", "Hạng Tần Suất (Jun Da)": "6438.0", "Tần Suất % (Jun Da)": "99.9922533908", "GavinGrover_Once (Chiết tự trực tiếp)": "贝 + 尃", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰贝尃", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "贝", "Unihan_Simplified (Chữ Giản thể)": "赙", "Unihan_Traditional (Chữ Phồn thể)": "賻", "Pinyin_Xie": "fù", "Âm Hán Việt_Xie": "phụ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ mang tân ngữ chỉ tiền bạc hoặc làm danh từ chỉ đồ phúng điếu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('磉', '{"9000": "6439.0", "Chữ Trung Quốc": "磉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 15 | nét | 磉 | tảng | tượng hình | đá tảng kê chân cột | 磉 là chữ độc thể, bộ 石 (thạch). Wiktionary không có định nghĩa rõ ràng (rfdef) nhưng từ ghép 磉墩 cho thấy nghĩa: đá kê chân cột. Không có phân tích cấu tạo. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tảng\": bộ 石 (đá) — \"tảng\" đá kê dưới chân cột, chịu đựng cả công trình phía trên. | Gương Hán-Việt | \"tảng\" trong 磉墩 (tảng đôn — đá tảng kê cột), đồng nghĩa với 柱础 (trụ sở — bệ cột) | Mở khoá kiến thức | Biết 磉 giúp đọc từ vựng kiến trúc truyền thống: 磉墩 (bệ đá cột), 柱磉 (đá kê cột).", "Tự nguyên_Xie": "Chữ 磉 (tảng) theo từ ghép 磉墩: đá tảng kê chân cột, bệ đá nền cột. Bộ 石 (thạch) biểu thị vật liệu là đá. Không có phân tích cấu tạo. Chưa có nguồn học thuật xác nhận cụ thể. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đá tảng", "Hạng Tần Suất (Jun Da)": "6439.0", "Tần Suất % (Jun Da)": "99.9922647601", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 桑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石桑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "桑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "磉", "Unihan_Traditional (Chữ Phồn thể)": "磉", "Pinyin_Xie": "sǎng", "Âm Hán Việt_Xie": "tảng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ bệ đá kê dưới chân cột gỗ trong kiến trúc cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('郤', '{"9000": "6440.0", "Chữ Trung Quốc": "郤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 9 | nét | 𧮫 | khích | biểu âm | 邑 | ấp | biểu nghĩa | đô thị, đất phong | 郤 = 𧮫 (biểu âm) + 邑 (Ấp, biểu nghĩa: đô thị, đất phong). Chữ hình thanh. Bộ 邑 cho biết liên quan đến địa danh; 𧮫 cung cấp âm đọc xì. Có ảnh đại triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khích\": ấp (邑, đất phong) + 𧮫 (âm) — kẽ hở giữa các đất phong, \"khích\" như kẽ hở trong áo giáp. | Gương Hán-Việt | \"khích\" trong 郤克 (Khích Khắc — danh tướng thời Xuân Thu), họ Khích cổ đại | Mở khoá kiến thức | Biết 郤 giúp đọc sử ký Trung Quốc: họ Khích (郤氏) nước Tấn, 郤克 (Khích Khắc).", "Tự nguyên_Xie": "Đại triện | Theo Wiktionary: 郤 là chữ hình thanh gồm 𧮫 (biểu âm) và 邑 (biểu nghĩa: đô thị). Nghĩa: kẽ hở, chỗ xương thịt tiếp giáp nhau; họ người; địa danh cổ. Có ảnh đại triện. Họ Khích (郤) nổi tiếng thời Xuân Thu trong sử Trung Quốc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên đất); chỗ xương thịt giáp nhau", "Hạng Tần Suất (Jun Da)": "6440.0", "Tần Suất % (Jun Da)": "99.9922761294", "GavinGrover_Once (Chiết tự trực tiếp)": "谷 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰谷阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "阝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "谷", "Unihan_Simplified (Chữ Giản thể)": "郤", "Unihan_Traditional (Chữ Phồn thể)": "郤", "Pinyin_Xie": "xì", "Âm Hán Việt_Xie": "khích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ vết nứt vật lý hoặc sự bất hòa trong quan hệ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('聍', '{"9000": "6441.0", "Chữ Trung Quốc": "聍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 耳 | Số nét | 11 | nét | 聍 | ninh | tượng hình | ráy tai (earwax) | 聍 là chữ độc thể, bộ 耳 (nhĩ). Không có nguồn Wiktionary về cấu tạo. Chủ yếu dùng trong từ ghép 耵聍 (chỉ ráy tai). Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ninh\": bộ 耳 (tai) — ráy tai \"ninh ninh\" bám trong lỗ tai như vật \"ninh cố\". | Gương Hán-Việt | \"ninh\" trong 耵聍 (đinh ninh — ráy tai) | Mở khoá kiến thức | Biết 聍 giúp nhận ra 耵聍 trong từ vựng y học tai mũi họng.", "Tự nguyên_Xie": "Chữ 聍 (ninh) không có nguồn Wiktionary. Bộ 耳 (tai) cho thấy liên quan đến tai. Chủ yếu dùng trong 耵聍 (đinh ninh) — ráy tai. Không có phân tích cấu tạo. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: đinh ninh 耵聹,耵聍)", "Hạng Tần Suất (Jun Da)": "6441.0", "Tần Suất % (Jun Da)": "99.9922874987", "GavinGrover_Once (Chiết tự trực tiếp)": "耳 + 宁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰耳宁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "耳", "Unihan_Simplified (Chữ Giản thể)": "聍", "Unihan_Traditional (Chữ Phồn thể)": "聹", "Pinyin_Xie": "níng", "Âm Hán Việt_Xie": "ninh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với chữ đinh để tạo thành danh từ ghép chỉ ráy tai. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铷', '{"9000": "6442.0", "Chữ Trung Quốc": "铷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 11 | nét | 铷 | như | tượng hình | nguyên tố rubidi (Rb), số nguyên tử 37 | 铷 là chữ độc thể, bộ 金 (kim). Không có nguồn Wiktionary. Bộ 金 biểu thị kim loại; âm đọc rú gần với âm Latin \"Rubidium\". Chữ tạo muộn (kim loại này được phát hiện năm 1861).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"như\": bộ 金 (kim loại) — kim loại \"như\" (Rubidium) — nhớ: Rb + kim (金) = nguyên tố nhóm 1 có màu bạc sáng. | Gương Hán-Việt | \"như\" là tên Hán-Việt của nguyên tố Rubidium trong hóa học | Mở khoá kiến thức | Biết 铷 giúp nhận ra nguyên tố Rubidium (Rb) trong tài liệu hóa học tiếng Trung.", "Tự nguyên_Xie": "Chữ 铷 (như) là tên phiên âm Hán hóa của nguyên tố hóa học Rubidium (Rb, số 37). Bộ 金 biểu nghĩa kim loại; phần còn lại phiên âm. Tạo muộn theo hệ thống phiên âm nguyên tố hóa học của Trung Quốc. Không có nguồn Wiktionary. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố rubidi, Rb", "Hạng Tần Suất (Jun Da)": "6442.0", "Tần Suất % (Jun Da)": "99.9922988679", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 如", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅如", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "如", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铷", "Unihan_Traditional (Chữ Phồn thể)": "銣", "Pinyin_Xie": "rú", "Âm Hán Việt_Xie": "như", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ đứng độc lập trong các tài liệu khoa học hóa học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('硏', '{"9000": "6443.0", "Chữ Trung Quốc": "硏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 11 | nét | 硏 | nghiên | tượng hình | mài nghiền; dị thể của 研 | 硏 là dị thể của 研, bộ 石 (thạch). Không có nguồn Wiktionary riêng. Bộ 石 biểu thị liên quan đến đá, mài nghiền. Chưa có nguồn học thuật xác nhận cấu trúc riêng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nghiên\": bộ 石 (đá) — cái \"nghiên\" mài mực làm từ đá, \"nghiên cứu\" như mài đi mài lại cho đến khi hiểu thấu. | Gương Hán-Việt | \"nghiên\" trong 研究 (nghiên cứu), 研磨 (nghiên ma — mài nghiền) | Mở khoá kiến thức | Biết 硏/研 mở khoá từ vựng học thuật: 研究 (nghiên cứu), 研讨 (hội thảo), 研磨 (mài nghiền).", "Tự nguyên_Xie": "Chữ 硏 (nghiên) là dị thể của 研 — mài nghiền. Bộ 石 (đá) biểu nghĩa. Không có nguồn Wiktionary riêng cho 硏. Nghĩa: mài nghiền; nghiên cứu. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nghiên; như \"nghiên cứu\" \n\n§ Cũng như 研.", "Hạng Tần Suất (Jun Da)": "6443.0", "Tần Suất % (Jun Da)": "99.9923102372", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "硏", "Unihan_Traditional (Chữ Phồn thể)": "硏", "Pinyin_Xie": "yán", "Âm Hán Việt_Xie": "nghiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ để chỉ hoạt động tìm hiểu sâu sắc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('腘', '{"9000": "6444.0", "Chữ Trung Quốc": "腘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 12 | nét | 腘 | quắc | tượng hình | khoeo chân; hõm sau đầu gối (popliteal fossa) | 腘 là chữ độc thể, bộ 肉 (nhục — thịt). Wiktionary ghi dạng cổ là 膕. Nghĩa: hố khoeo (popliteal fossa) — vùng lõm sau đầu gối. Không có phân tích cấu tạo. Chưa có nguồn học thuật xác nhận cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quắc\": bộ 肉 (thịt, thân thể) — \"quắc\" chân gập lại tạo hõm khoeo sau đầu gối. | Gương Hán-Việt | \"quắc\" trong 腘窩 (quắc oa — hố khoeo sau đầu gối) | Mở khoá kiến thức | Biết 腘 giúp đọc từ vựng giải phẫu y học: 腘窩 (hố khoeo), 腘動脈 (động mạch khoeo), 膝關節 (khớp gối).", "Tự nguyên_Xie": "Chữ 腘 (quắc), dạng cổ 膕, theo Wiktionary chỉ hố khoeo (knee pit, popliteal fossa) — vùng lõm ở mặt sau đầu gối. Bộ 肉 (thịt) liên quan đến thân thể. Từ ghép 膕窩 (hố khoeo). Không có phân tích cấu tạo chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhượng chân; khoeo chân; quắc; như \"quắc (lỗ lõm sau đầu gối)\" (gdhn)", "Hạng Tần Suất (Jun Da)": "6444.0", "Tần Suất % (Jun Da)": "99.9923216065", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 国", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月国", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "国", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "腘", "Unihan_Traditional (Chữ Phồn thể)": "膕", "Pinyin_Xie": "guó", "Âm Hán Việt_Xie": "quắc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ bộ phận cơ thể người hoặc động vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鮟', '{"9000": "6445.0", "Chữ Trung Quốc": "鮟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 17 | nét | 魚 | ngư | biểu nghĩa | cá | 安 | an | biểu âm | 鮟 = 魚 (Ngư, biểu nghĩa: cá) + 安 (An, biểu âm). Chữ hình thanh: bộ 魚 chỉ loại cá, 安 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"áng\": bộ 魚 (ngư, cá) + 安 (an, yên tĩnh) — con cá 鮟鱇 yên lặng ẩn dưới đáy biển sâu, dùng đèn sinh học dụ mồi. | Gương Hán-Việt | áng trong \"鮟鱇\" (áng hàng — anglerfish, cá nhám đèn lồng) | Mở khoá kiến thức | Biết 鮟 mở khoá tổ hợp 鮟鱇 (cá anglerfish) — loài cá kỳ lạ dùng đèn sinh học ở đầu để dụ mồi ở đáy biển.", "Tự nguyên_Xie": "Chữ hình thanh gồm 魚 (cá) biểu nghĩa và 安 (an) biểu âm. 鮟 thường xuất hiện trong tổ hợp 鮟鱇 (cá nhám đèn lồng, anglerfish). Chưa có nguồn học thuật chuyên sâu về glyph origin ngoài cấu trúc hình thanh cơ bản theo Wiktionary. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鮟", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 安", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚安", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "安", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "𩽾", "Unihan_Traditional (Chữ Phồn thể)": "鮟", "Pinyin_Xie": "àn", "Âm Hán Việt_Xie": "áng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu làm danh từ trong tên gọi loài cá áng sống ở biển sâu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鳈', '{"9000": "6446.0", "Chữ Trung Quốc": "鳈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 17 | nét | 鳈 | tuyền | tượng hình | tên loài cá nước ngọt thân dài màu nâu | 鳈 là chữ chuyên dụng chỉ tên loài cá. Cấu trúc nội bộ không tách được rõ ràng theo dữ liệu hiện có; khả năng có bộ 魚 biểu nghĩa nhưng chưa xác nhận. Chữ xuất hiện trong từ điển cổ để chỉ cá tuyền (cá nước ngọt).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuyền\": 鳈 (tuyền) — loài cá nước ngọt thân dài; liên tưởng âm tuyền với \"泉\" (suối nguồn) — nơi cá tuyền sinh sống. | Gương Hán-Việt | tuyền trong \"tuyền ngư\" (cá tuyền, cá nước ngọt) | Mở khoá kiến thức | Biết 鳈 (tuyền) xuất hiện trong từ điển sinh học cổ điển Trung Quốc khi mô tả các loài cá nước ngọt.", "Tự nguyên_Xie": "Không có glyph origin từ Wiktionary cho 鳈. Dựa vào cấu trúc, khả năng là chữ hình thanh với bộ 魚 biểu nghĩa (cá) và phần biểu âm, nhưng chưa có nguồn học thuật xác nhận. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá tuyền (giống cá dài khoảng 5-6 tấc, màu nâu sẫm, có vân, miệng nhỏ); tuyền; như \"tuyền ngư (cá nước ngọt)\"", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 泉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼泉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "泉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鳈", "Unihan_Traditional (Chữ Phồn thể)": "鳈", "Pinyin_Xie": "quán", "Âm Hán Việt_Xie": "toàn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ dùng trong tên gọi của một loài cá nước ngọt nhỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('秾', '{"9000": "6447.0", "Chữ Trung Quốc": "秾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 11 | nét | 秾 | nùng | tượng hình | hoa cỏ rậm rạp, tươi tốt | 秾 có bộ 禾 (lúa, cây trồng) gợi ý thực vật. Glyph origin trong Wiktionary chỉ ghi {{Han etym}} không có mô tả cụ thể. Cấu trúc đầy đủ chưa tách được rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nùng\": 秾 (nùng) — hoa cỏ rậm rạp um tùm, như chữ 濃 (nồng, đậm đặc) nhưng dành riêng cho thực vật tươi tốt. | Gương Hán-Việt | nùng trong thơ cổ tả cảnh hoa cỏ tươi tốt rậm rạp | Mở khoá kiến thức | Biết 秾 (nùng) xuất hiện trong thơ cổ điển Trung Quốc tả cảnh hoa cỏ phong phú, đặc biệt trong Kinh Thi và thơ Đường.", "Tự nguyên_Xie": "Wiktionary không cung cấp mô tả glyph origin cụ thể cho 秾. Bộ 禾 (lúa) gợi liên quan đến thực vật; âm nóng gần với 農/濃. Đây có thể là chữ hình thanh chỉ sự um tùm của hoa cỏ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hoa cỏ rậm rạp", "Hạng Tần Suất (Jun Da)": "6447.0", "Tần Suất % (Jun Da)": "99.9924120439", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 农", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾农", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "农", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "秾", "Unihan_Traditional (Chữ Phồn thể)": "穠", "Pinyin_Xie": "nóng", "Âm Hán Việt_Xie": "nùng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ bổ nghĩa cho danh từ để tả cảnh hoa cỏ sum suê, tươi tốt. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('邗', '{"9000": "6448.0", "Chữ Trung Quốc": "邗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 5 | nét | 邗 | hàn | tượng hình | địa danh cổ, thành Hàn thuộc nước Ngô | 邗 là địa danh, có bộ 邑 (ấp) ở bên phải theo quy ước chữ Hán chỉ địa danh hành chính. Glyph origin không được mô tả chi tiết trong nguồn hiện có.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hàn\": 邗 (hàn) — tên thành cổ nước Ngô, nhớ qua 邗溝 (kênh Hàn Câu) lịch sử đào từ 486 TCN nối hai con sông lớn. | Gương Hán-Việt | hàn trong \"邗溝\" (Hàn Câu — kênh đào lịch sử), \"邗江\" (Hàn Giang — địa danh Giang Tô) | Mở khoá kiến thức | Biết 邗 (hàn) giúp đọc hiểu sử liệu về nước Ngô thời Xuân Thu Chiến Quốc và địa lý Giang Tô cổ đại.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | 邗 là địa danh ghi trong sử cổ: một thành cũ thuộc nước Ngô thời Xuân Thu, nay ở Hoài An, Giang Tô. Wiktionary chỉ ghi {{Han etym}} không mô tả cụ thể. Kênh đào 邗溝 nối sông Hoài và Trường Giang được đào từ 486 TCN là di tích lịch sử quan trọng gắn với địa danh này. Chưa có nguồn học thuật. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên sông)", "Hạng Tần Suất (Jun Da)": "6448.0", "Tần Suất % (Jun Da)": "99.9924228964", "GavinGrover_Once (Chiết tự trực tiếp)": "干 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰干阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "阝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "干", "Unihan_Simplified (Chữ Giản thể)": "邗", "Unihan_Traditional (Chữ Phồn thể)": "邗", "Pinyin_Xie": "hán", "Âm Hán Việt_Xie": "hàn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ riêng chỉ địa danh cổ hoặc tên con kênh đào thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('矧', '{"9000": "6449.0", "Chữ Trung Quốc": "矧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 矢 | Số nét | 9 | nét | 矧 | thẩn | tượng hình | huống chi, vả lại; chân răng | 矧 có bộ 矢 (mũi tên) làm thành tố, phần còn lại có thể biểu âm nhưng glyph origin không được Wiktionary mô tả chi tiết. Chữ dùng trong văn ngôn với nghĩa \"huống chi\".", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thẩn\": 矧 (thẩn) nghĩa là \"huống chi\" trong văn ngôn — như mũi tên 矢 chỉ thẳng vào điều hiển nhiên hơn, \"huống chi là...\" | Gương Hán-Việt | thẩn trong cổ văn: \"矧乃\" (thẩn nãi — huống chi là) | Mở khoá kiến thức | Biết 矧 (thẩn) giúp đọc hiểu cổ văn Trung Quốc, đặc biệt văn nghị luận thời Đường Tống dùng 矧 làm liên từ tăng cường.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không cung cấp mô tả glyph origin chi tiết cho 矧 (chỉ ghi {{Han etym}}). Chữ này dùng trong văn ngôn cổ điển với nghĩa \"huống chi\", \"vả lại\" — một phó từ so sánh tăng tiến. Cũng có nghĩa là chân răng (nướu răng). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ví bằng, huống chi; chân răng; cũng", "Hạng Tần Suất (Jun Da)": "6449.0", "Tần Suất % (Jun Da)": "99.9924446013", "GavinGrover_Once (Chiết tự trực tiếp)": "矢 + 引", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰矢引", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "引", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "矢", "Unihan_Simplified (Chữ Giản thể)": "矧", "Unihan_Traditional (Chữ Phồn thể)": "矧", "Pinyin_Xie": "shěn", "Âm Hán Việt_Xie": "thẩn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Liên từ | 连词 | Danh từ | 名词 | Thường làm liên từ ở đầu vế câu thứ hai để biểu thị ý nghĩa tăng tiến, huống hồ. | Liên từ | 连词 | Nối từ, cụm từ hoặc mệnh đề: 和, 但是, 因为…所以…. Lưu ý 和 chỉ nối danh từ, không nối hai câu như ''và'' tiếng Việt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('舁', '{"9000": "6450.0", "Chữ Trung Quốc": "舁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 臼 | Số nét | 9 | nét | 臼 | cối | biểu nghĩa | đôi bàn tay (trên) | 廾 | trấp | biểu nghĩa | đôi bàn tay (dưới) | 舁 = 臼 (ban đầu là 𦥑 — đôi tay phía trên) + 廾 (Trấp — đôi tay phía dưới). Chữ hội ý: bốn bàn tay cùng khiêng — hành động hợp sức nâng vật nặng. Lưu ý: thành tố trên trong dạng gốc là 𦥑 (hai bàn tay), không phải cối xay; hình dạng hiện tại trông giống cối là nhầm lẫn hình dạng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dư\": 舁 (dư) — bốn bàn tay 臼+廾 cùng khiêng một vật, hình ảnh bốn người khiêng kiệu hoặc cáng thương. | Gương Hán-Việt | dư trong \"肩舁\" (kiên dư — khiêng vai), \"舁人\" (dư nhân — người khiêng kiệu) | Mở khoá kiến thức | Biết 舁 (dư) giúp đọc hiểu cổ văn về nghi lễ và từ điển cổ: 肩舁 (khiêng vai), 轎舁 (khiêng kiệu), 舁夫 (người khiêng).", "Tự nguyên_Xie": "Tiểu triện | Chữ hội ý gồm hai bộ tay: 𦥑 (hai bàn tay trên, nay viết thành 臼) và 廾 (hai bàn tay dưới). Bốn bàn tay cùng khiêng — động tác nâng vai, khiêng kiệu. Wiktionary lưu ý thành tố trên trong dạng gốc là 𦥑 (hai tay), không phải cối xay; hình dạng hiện tại dễ gây nhầm lẫn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khiêng, công kênh", "Hạng Tần Suất (Jun Da)": "6450.0", "Tần Suất % (Jun Da)": "99.9924554538", "GavinGrover_Once (Chiết tự trực tiếp)": "臼 + 艹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱臼艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "艹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "臼", "Unihan_Simplified (Chữ Giản thể)": "舁", "Unihan_Traditional (Chữ Phồn thể)": "舁", "Pinyin_Xie": "yú", "Âm Hán Việt_Xie": "dư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ để chỉ hành động cùng nhau khiêng hoặc nâng vật nặng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('貅', '{"9000": "6451.0", "Chữ Trung Quốc": "貅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 豸 | Số nét | 13 | nét | 豸 | trại | biểu nghĩa | thú có đốm | 休 | hưu | biểu âm | 貅 = 豸 (Trại, biểu nghĩa: thú dữ có đốm) + 休 (Hưu, biểu âm). Chữ hình thanh: bộ 豸 chỉ loài thú dữ, 休 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hươu\": 貅 (hươu) — thú dữ 豸 với âm 休 (hưu) — một nửa của 貔貅 (tỳ hưu), con linh vật hút tài lộc trong văn hóa Hoa. | Gương Hán-Việt | hươu trong \"貔貅\" (tỳ hưu — linh vật hút tài lộc) | Mở khoá kiến thức | Biết 貅 (hươu) mở khoá: 貔貅 (tỳ hưu — con linh vật trong tín ngưỡng Hoa: hút tiền vào không thả ra, dùng làm tượng phong thủy).", "Tự nguyên_Xie": "Chữ hình thanh: 豸 (thú dữ có đốm) biểu nghĩa, 休 (hưu) biểu âm. 貅 chỉ một loài vật huyền thoại giống hổ, dũng mãnh, thường xuất hiện trong cụm 貔貅 (tỳ hưu) — con vật linh thiêng được dùng như bùa hộ mệnh trong văn hóa Trung Hoa, tượng trưng cho tài lộc và may mắn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một loài vật giống như hổ; dũng sĩ", "Hạng Tần Suất (Jun Da)": "6451.0", "Tần Suất % (Jun Da)": "99.9924663063", "GavinGrover_Once (Chiết tự trực tiếp)": "豸 + 休", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰豸休", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "休", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "豸", "Unihan_Simplified (Chữ Giản thể)": "貅", "Unihan_Traditional (Chữ Phồn thể)": "貅", "Pinyin_Xie": "xiū", "Âm Hán Việt_Xie": "hưu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng trong các từ ghép chỉ loài vật huyền thoại hoặc người dũng mãnh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('骢', '{"9000": "6452.0", "Chữ Trung Quốc": "骢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 14 | nét | 骢 | thông | tượng hình | ngựa trắng xám | 骢 là dạng giản thể của 驄, có bộ 馬 (ngựa) biểu nghĩa. Glyph origin: đơn giản hóa từ 驄 (馬→马). Chữ chỉ màu lông ngựa trắng xám (xanh xám).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thông\": 骢 (thông) — con ngựa 馬 màu xanh xám, như màu sương thông thoáng buổi sáng sớm. Nhớ: ngựa 驄 (骢) xanh xám như sương mù. | Gương Hán-Việt | thông trong \"青骢\" (thanh thông — ngựa xanh xám), \"骢馬\" (thông mã — ngựa xám xanh) | Mở khoá kiến thức | Biết 骢 (thông) xuất hiện trong thơ cổ điển Trung Quốc tả ngựa chiến màu xanh xám quý phái.", "Tự nguyên_Xie": "Tiểu triện | 骢 là dạng giản thể của 驄. Wiktionary ghi: {{Han simp|驄|f=馬|t=马}} — đơn giản hóa bộ 馬 thành 马. 驄 là chữ hình thanh: 馬 (ngựa) biểu nghĩa, phần còn lại biểu âm. Ý nghĩa: ngựa có lông màu trắng xám (xanh xám). Chưa có nguồn học thuật cho glyph origin cổ. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngựa trắng xám", "Hạng Tần Suất (Jun Da)": "6452.0", "Tần Suất % (Jun Da)": "99.9924880113", "GavinGrover_Once (Chiết tự trực tiếp)": "马 + 悤", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰马悤", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "悤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "马", "Unihan_Simplified (Chữ Giản thể)": "骢", "Unihan_Traditional (Chữ Phồn thể)": "驄", "Pinyin_Xie": "cōng", "Âm Hán Việt_Xie": "thông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ loại ngựa có màu lông đặc trưng trong văn chương cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('阼', '{"9000": "6453.0", "Chữ Trung Quốc": "阼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 7 | nét | 阼 | tộ | tượng hình | bậc thang phía đông dẫn lên sảnh đường | 阼 có bộ 阜 (gò đất, bậc thang) biểu nghĩa. Glyph origin trong Wiktionary chỉ ghi {{Han etym}} không mô tả cụ thể. Chữ chỉ bậc thang phía đông dẫn lên đại sảnh, nơi dành cho hoàng đế/chủ nhà.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tộ\": 阼 (tộ) — bậc thang phía Đông 阜 nơi chủ nhà bước lên ngênh tiếp khách. Nhớ: \"登阼\" (đăng tộ) là lên ngôi hoàng đế — bước lên bậc thang thiêng liêng đó. | Gương Hán-Việt | tộ trong \"đăng tộ\" (lên ngôi), \"踐阼\" (tiễn tộ — bước lên ngôi, kế vị) | Mở khoá kiến thức | Biết 阼 (tộ) giúp đọc sử liệu Trung Quốc cổ về lễ nghi triều đình: 登阼 (đăng tộ — lên ngôi), 踐阼 (tiễn tộ — kế vị).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 阼 là chữ cổ chỉ bậc thang phía đông dẫn lên sảnh đường (dành cho chủ nhà hoặc hoàng đế trong nghi lễ). Bộ 阜 (gò, bậc thang) biểu nghĩa. Wiktionary không mô tả glyph origin chi tiết. Từ nghĩa cụ thể (bậc thang), chữ mở rộng sang nghĩa bóng là \"ngai vàng\" (登阼 — lên ngôi). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phía bên chủ (khi tiếp khách)", "Hạng Tần Suất (Jun Da)": "6453.0", "Tần Suất % (Jun Da)": "99.9924988638", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + 乍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝乍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "阼", "Unihan_Traditional (Chữ Phồn thể)": "阼", "Pinyin_Xie": "zuò", "Âm Hán Việt_Xie": "tộ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường xuất hiện trong các văn bản cổ để chỉ vị trí chủ nhà hoặc ngôi vị hoàng đế. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('垸', '{"9000": "6454.0", "Chữ Trung Quốc": "垸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 10 | nét | 土 | thổ | biểu nghĩa | đất | 完 | hoàn | biểu âm | 垸 = 土 (Thổ, biểu nghĩa: đất) + 完 (Hoàn, biểu âm). Chữ hình thanh: bộ 土 chỉ công trình đất, 完 cho âm đọc. Ý nghĩa: bờ đê, đập đất.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoàn\": 垸 (hoàn) — đất 土 hoàn thiện 完 thành bờ đê ngăn nước. Nhớ: bờ đê phải hoàn chỉnh mới ngăn được lũ. | Gương Hán-Việt | hoàn trong \"圩垸\" (vu hoàn — hệ thống đê đập đồng bằng) | Mở khoá kiến thức | Biết 垸 (hoàn) giúp đọc hiểu văn bản về thủy lợi và địa lý vùng đồng bằng hồ Động Đình, Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 土 (đất) biểu nghĩa, 完 (hoàn) biểu âm. 垸 chỉ bờ đê đất dùng để ngăn nước ở đồng bằng châu thổ, đặc biệt phổ biến ở vùng hồ Động Đình (Hồ Nam) nơi có hệ thống đê đập phức tạp gọi là 圩垸 (wéiyuàn). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bờ đê", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 完", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土完", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "完", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "垸", "Unihan_Traditional (Chữ Phồn thể)": "垸", "Pinyin_Xie": "yuàn", "Âm Hán Việt_Xie": "viện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Dùng để chỉ bờ đê bao quanh hoặc hành động đắp đất ngăn nước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('墁', '{"9000": "6455.0", "Chữ Trung Quốc": "墁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 14 | nét | 墁 | mạn | tượng hình | quét vôi, trát tường, lát gạch | 墁 có bộ 土 (đất, vật liệu xây dựng) biểu nghĩa. Glyph origin trong Wiktionary chỉ ghi {{Han etym}} không mô tả cụ thể; chữ là dạng thay thế của 鏝 (bay xây dựng). Cấu trúc đầy đủ chưa tách được rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mạn\": 墁 (mạn) — dùng bay đất 土 quét trơn, trát tường, lát gạch — lớp \"mạn\" phẳng phiu trên bề mặt tường. | Gương Hán-Việt | mạn trong \"圬墁\" (ô mạn — thợ hồ, thợ trát vôi) | Mở khoá kiến thức | Biết 墁 (mạn) xuất hiện trong từ điển xây dựng cổ và cổ văn tả công việc thợ hồ, trát tường vôi.", "Tự nguyên_Xie": "墁 là dạng thay thế (alt form) của 鏝 (bay xây dựng, dụng cụ trát tường). Wiktionary không mô tả glyph origin chi tiết (chỉ ghi {{Han etym}}). Bộ 土 (đất) liên quan đến vật liệu xây dựng. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quét vôi", "Hạng Tần Suất (Jun Da)": "6455.0", "Tần Suất % (Jun Da)": "99.9925205687", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 曼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土曼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "墁", "Unihan_Traditional (Chữ Phồn thể)": "墁", "Pinyin_Xie": "màn", "Âm Hán Việt_Xie": "mạn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng để chỉ hành động trát vôi hoặc lát gạch trên bề mặt tường, sàn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('攮', '{"9000": "6456.0", "Chữ Trung Quốc": "攮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 25 | nét | 攮 | nện | tượng hình | đâm bằng dao; đẩy mạnh | 攮 có bộ 手/扌 (tay) biểu nghĩa. Cấu trúc đầy đủ không tách được rõ ràng theo dữ liệu hiện có; glyph origin không có trong Wiktionary. Chữ chỉ hành động đâm hoặc đẩy mạnh bằng tay.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nện\": 攮 (nện) — tay 手 nện mạnh, đâm một cái — hình ảnh đẩy mạnh hoặc đâm nhát dao dứt khoát. | Gương Hán-Việt | nện trong \"攮了一刀\" (nện một nhát dao — đâm một cái) | Mở khoá kiến thức | Biết 攮 (nện) xuất hiện trong văn học và phương ngữ Bắc Kinh, chỉ hành động đâm hoặc xô đẩy mạnh.", "Tự nguyên_Xie": "Không có glyph origin từ Wiktionary cho 攮. Bộ 手 (tay) biểu nghĩa; phần còn lại có thể biểu âm. Chữ này dùng trong văn nói/văn học hiện đại với nghĩa đâm dao hoặc đẩy mạnh (phương ngữ Bắc Kinh). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đâm bằng dao; đẩy mạnh", "Hạng Tần Suất (Jun Da)": "6456.0", "Tần Suất % (Jun Da)": "99.9925314212", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 囊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌囊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "囊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "攮", "Unihan_Traditional (Chữ Phồn thể)": "攮", "Pinyin_Xie": "nǎng", "Âm Hán Việt_Xie": "nãng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng để mô tả hành động đâm bằng vật nhọn hoặc đẩy mạnh vật gì đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('柝', '{"9000": "6457.0", "Chữ Trung Quốc": "柝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 9 | nét | 木 | mộc | biểu nghĩa | cây, gỗ | 斥 | xích | biểu âm | 柝 = 木 (Mộc, biểu nghĩa: cây gỗ) + 斥 (Xích, biểu âm). Chữ hình thanh: bộ 木 chỉ vật bằng gỗ, 斥 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thác\": 柝 (thác) — cái mõ gỗ 木 dùng để gõ báo giờ canh đêm. Nhớ: tiếng mõ \"thác thác\" trong đêm khuya báo canh. | Gương Hán-Việt | thác trong \"擊柝\" (kích thác — gõ mõ canh), \"金柝\" (kim thác — mõ gõ canh) | Mở khoá kiến thức | Biết 柝 (thác) giúp đọc thơ cổ điển về canh đêm: 金柝 (kim thác — tiếng mõ canh), 擊柝 (gõ mõ tuần tra).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 木 (gỗ) biểu nghĩa, 斥 biểu âm. 柝 chỉ cái mõ gỗ (watchman''s rattle) dùng để gõ ban đêm khi tuần tra canh gác. Dạng gốc viết là 𣔳. Dụng cụ này phổ biến trong hệ thống canh đêm truyền thống Trung Quốc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mõ canh (gõ cầm canh ban đêm)", "Hạng Tần Suất (Jun Da)": "6457.0", "Tần Suất % (Jun Da)": "99.9925422737", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 斥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木斥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "斥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "柝", "Unihan_Traditional (Chữ Phồn thể)": "柝", "Pinyin_Xie": "tuò", "Âm Hán Việt_Xie": "thác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chỉ cái mõ dùng để báo canh đêm hoặc hành động gõ mõ canh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('梃', '{"9000": "6458.0", "Chữ Trung Quốc": "梃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 10 | nét | 梃 | đĩnh | tượng hình | cái gậy, cái côn gỗ; thẳng | 梃 có bộ 木 (cây gỗ) biểu nghĩa. Glyph origin trong Wiktionary chỉ ghi {{Han etym}} không mô tả cụ thể. Chữ chỉ gậy gỗ, côn gỗ hoặc vật thẳng bằng gỗ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đĩnh\": 梃 (đĩnh) — cái gậy gỗ 木 thẳng đĩnh (thẳng đứng). Nhớ: \"đĩnh\" trong tiếng Việt cũng có nghĩa thẳng, ngay ngắn. | Gương Hán-Việt | đĩnh trong \"梃杖\" (đĩnh trượng — gậy gỗ), \"梃擊\" (đĩnh kích — đánh bằng gậy) | Mở khoá kiến thức | Biết 梃 (đĩnh) giúp đọc hiểu cổ văn về vũ khí nguyên thủy và Mạnh Tử: 梃擊 (đánh bằng gậy) xuất hiện trong câu nổi tiếng \"以梃與刃\" (dùng gậy hay dùng dao).", "Tự nguyên_Xie": "Tiểu triện | Lưu thư thông (Minh) | 梃 có bộ 木 (gỗ) biểu nghĩa. Wiktionary không mô tả glyph origin chi tiết (chỉ ghi {{Han etym}}). Chữ chỉ cái gậy hoặc côn bằng gỗ; cũng là lượng từ chỉ cây/cán (梃槍 — một cây giáo). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái gậy, cái côn", "Hạng Tần Suất (Jun Da)": "6458.0", "Tần Suất % (Jun Da)": "99.9925531262", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 廷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木廷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "廷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "梃", "Unihan_Traditional (Chữ Phồn thể)": "梃", "Pinyin_Xie": "tǐng", "Âm Hán Việt_Xie": "đĩnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ các loại gậy gỗ hoặc côn dùng để đánh đập. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('眚', '{"9000": "6459.0", "Chữ Trung Quốc": "眚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 10 | nét | 生 | sinh | biểu âm | 目 | mục | biểu nghĩa | mắt | 眚 = 生 (Sinh, biểu âm) + 目 (Mục, biểu nghĩa: mắt). Chữ hình thanh: bộ 目 chỉ liên quan đến mắt, 生 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sinh\": 眚 (sinh) — mắt 目 bị màng che từ khi \"sinh\" ra 生 — tật bẩm sinh của mắt, cũng là lỗi lầm (vì không nhìn thấy rõ). | Gương Hán-Việt | sinh trong \"眚災\" (sinh tai — tai họa, lỗi lầm gây ra thảm họa) | Mở khoá kiến thức | Biết 眚 (sinh) giúp đọc cổ văn và Kinh Thư: 眚災 (lỗi lầm/tai họa), 日月之眚 (nhật thực nguyệt thực — trời đất bị \"che mắt\").", "Tự nguyên_Xie": "Giáp cốt | Tiểu triện | Chữ hình thanh: 生 biểu âm, 目 (mắt) biểu nghĩa. 眚 chỉ bệnh mắt có màng (đục thủy tinh thể), sau mở rộng sang nghĩa lỗi lầm, tai họa. Từ giáp cốt văn đã thấy hình dạng mắt có vật che phủ. Sự phát triển ngữ nghĩa: mắt bị che → tầm nhìn hạn chế → lỗi lầm do thiếu nhìn xa. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mắt có màng", "Hạng Tần Suất (Jun Da)": "6459.0", "Tần Suất % (Jun Da)": "99.9925639787", "GavinGrover_Once (Chiết tự trực tiếp)": "生 + 目", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱生目", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "目", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "生", "Unihan_Simplified (Chữ Giản thể)": "眚", "Unihan_Traditional (Chữ Phồn thể)": "眚", "Pinyin_Xie": "shěng", "Âm Hán Việt_Xie": "sảnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng để chỉ bệnh về mắt hoặc các tai họa, lỗi lầm trong văn phong cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('箜', '{"9000": "6460.0", "Chữ Trung Quốc": "箜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 14 | nét | 箜 | không | tượng hình | nhạc cụ dây cổ đại (không hầu) | 箜 có bộ 竹 (tre, nhạc cụ tre/dây) biểu nghĩa. Glyph origin trong Wiktionary chỉ ghi {{Han etym}} không mô tả cụ thể. Chữ chỉ xuất hiện trong tổ hợp 箜篌 (không hầu — đàn hạc Trung Hoa).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"không\": 箜 (không) — mãi chỉ xuất hiện trong 箜篌 (không hầu), cây đàn hạc cổ đại, tiếng đàn vang vọng \"không\" khắp nơi như tiếng gió. | Gương Hán-Việt | không trong \"箜篌\" (không hầu — đàn hạc Trung Hoa cổ) | Mở khoá kiến thức | Biết 箜 (không) mở khoá: 箜篌 (không hầu — nhạc cụ dây cổ đại Trung Quốc, xuất hiện nhiều trong thơ Đường như Lý Hà).", "Tự nguyên_Xie": "箜 chỉ xuất hiện trong tổ hợp 箜篌 (không hầu), tên một nhạc cụ dây cổ đại của Trung Quốc, nguồn gốc từ vùng Tây Vực (Trung Á), du nhập vào Trung Hoa khoảng thế kỷ 2 TCN. Wiktionary không mô tả glyph origin chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: không hầu 箜篌)", "Hạng Tần Suất (Jun Da)": "6460.0", "Tần Suất % (Jun Da)": "99.9925748312", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 空", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮空", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "空", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "箜", "Unihan_Traditional (Chữ Phồn thể)": "箜", "Pinyin_Xie": "kōng", "Âm Hán Việt_Xie": "không", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chỉ xuất hiện trong từ ghép không hầu để chỉ một loại nhạc cụ dây cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('簏', '{"9000": "6461.0", "Chữ Trung Quốc": "簏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 17 | nét | 竹 | trúc | biểu nghĩa | tre | 鹿 | lộc | biểu âm | 簏 = 竹 (Trúc, biểu nghĩa: tre) + 鹿 (Lộc, biểu âm). Chữ hình thanh: bộ 竹 chỉ đồ vật bằng tre, 鹿 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lộc\": 簏 (lộc) — cái sọt tre 竹 cao như con hươu 鹿 vươn cổ. Nhớ: sọt tre cao chứa đồ vật. | Gương Hán-Việt | lộc trong \"竹簏\" (trúc lộc — sọt tre), \"書簏\" (thư lộc — hộp sách) | Mở khoá kiến thức | Biết 簏 (lộc) giúp đọc cổ văn về đồ dùng gia đình bằng tre: 書簏 (hộp đựng sách), 竹簏 (sọt tre).", "Tự nguyên_Xie": "Tiểu triện | Lưu thư thông (Minh) | Chữ hình thanh: 竹 (tre) biểu nghĩa, 鹿 (lộc) biểu âm. 簏 chỉ cái sọt cao hoặc hộp tre dùng để đựng đồ. Đồ vật bằng tre phổ biến trong cuộc sống Trung Quốc cổ đại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái sọt cao, cái bễ tre", "Hạng Tần Suất (Jun Da)": "6461.0", "Tần Suất % (Jun Da)": "99.9925856837", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 鹿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮鹿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鹿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "簏", "Unihan_Traditional (Chữ Phồn thể)": "簏", "Pinyin_Xie": "lù", "Âm Hán Việt_Xie": "lộc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ vật dụng đan bằng tre nứa để đựng đồ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('綮', '{"9000": "6462.0", "Chữ Trung Quốc": "綮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 14 | nét | 糸 | biểu âm | sợi tơ | 綮 = 𢼄 (biểu âm) + 糸 (tơ, biểu nghĩa/âm). Theo Wiktionary, đây là chữ hình thanh: 𢼄 (c1=p) và 糸 (c2=s). Chữ chỉ giao điểm giữa gân và xương (肯綮 — khẳng khính) hoặc cờ thêu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khải\": 綮 (khải) — xuất hiện chủ yếu trong thành ngữ 肯綮 (khẳng khải — điểm cốt lõi, chỗ trúng tim đen). Bộ 糸 gợi sợi kết nối gân xương. | Gương Hán-Việt | khải trong \"肯綮\" (khẳng khải — nơi gân xương giao nhau, điểm quan trọng nhất) | Mở khoá kiến thức | Biết 綮 (khải) mở khoá thành ngữ 切中肯綮 (thiết trúng khẳng khải — nói trúng vào điểm mấu chốt, chạm đúng vào tim đen vấn đề).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 𢼄 biểu âm, 糸 biểu nghĩa (tơ/vải). Nghĩa gốc là cờ thêu hoặc giao điểm gân-xương (肯綮 — chỗ kết nối quan trọng). Wiktionary ghi là dạng thay thế của 棨. Âm đọc qǐ hoặc qìng. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: khẳng khính 肯綮)", "Hạng Tần Suất (Jun Da)": "6462.0", "Tần Suất % (Jun Da)": "99.9925965362", "GavinGrover_Once (Chiết tự trực tiếp)": "𢼄 + 糸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱𢼄糸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𢼄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糸", "Unihan_Simplified (Chữ Giản thể)": "綮", "Unihan_Traditional (Chữ Phồn thể)": "綮", "Pinyin_Xie": "qǐ", "Âm Hán Việt_Xie": "khể, khính", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng làm danh từ trong văn ngôn để chỉ điểm mấu chốt hoặc khớp nối quan trọng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲩', '{"9000": "6463.0", "Chữ Trung Quốc": "鲩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 15 | nét | 鲩 | hoản | tượng hình | cá trắm cỏ, cá trắm trắng | 鲩 là chữ chuyên dụng tên loài cá. Cấu trúc có bộ 魚/鱼 (cá) biểu nghĩa. Glyph origin trong Wiktionary chỉ ghi {{Han etym}} không mô tả chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoản\": 鲩 (hoản) — cá trắm cỏ (草魚), một trong bốn loài cá nuôi lớn nhất Trung Quốc. Nhớ: \"hoản\" âm gần \"hoàn\" — cá cuộn tròn trong ao. | Gương Hán-Việt | hoản trong \"草鲩\" (thảo hoản — cá trắm cỏ) | Mở khoá kiến thức | Biết 鲩 (hoản) giúp đọc thực đơn và văn bản về nuôi trồng thủy sản Trung Quốc: 鲩魚 (hoản ngư — cá trắm cỏ).", "Tự nguyên_Xie": "Tiểu triện | 鲩 là tên gọi cá trắm cỏ (grass carp, Ctenopharyngodon idella), một trong \"tứ đại gia ngư\" (bốn loài cá nước ngọt quan trọng nhất Trung Quốc). Wiktionary không mô tả glyph origin chi tiết. Chữ này phổ biến trong ngành nuôi trồng thủy sản. Chưa có nguồn học thuật về glyph origin. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá trắm trắng, cá trắm cỏ", "Hạng Tần Suất (Jun Da)": "6463.0", "Tần Suất % (Jun Da)": "99.9926073886", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 完", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼完", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "完", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲩", "Unihan_Traditional (Chữ Phồn thể)": "鯇", "Pinyin_Xie": "huàn", "Âm Hán Việt_Xie": "cán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ để chỉ loài cá trắm cỏ trong các ngữ cảnh ẩm thực hoặc sinh học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('茇', '{"9000": "6464.0", "Chữ Trung Quốc": "茇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 8 | nét | 茇 | bạt | tượng hình | rễ cỏ; lều tranh; đóng trại trong cỏ | 茇 có bộ 艸/艹 (cỏ) biểu nghĩa. Glyph origin trong Wiktionary chỉ ghi {{Han etym}} không mô tả cụ thể. Chữ chỉ rễ cỏ, lều tranh, hoặc hành động đóng trại trong bụi cỏ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bạt\": 茇 (bạt) — bộ 艸 gợi cỏ, chữ gợi hình ảnh đóng trại dưới bụi cỏ. Nhớ: \"bạt\" trong \"cắm trại\" — đóng lều trong cỏ. | Gương Hán-Việt | bạt trong \"蓽茇\" (bạch hạt — gia vị cay), \"茇舍\" (bạt xá — lều tranh dã chiến) | Mở khoá kiến thức | Biết 茇 (bạt) giúp đọc cổ văn về dã chiến và thực vật: 茇舍 (lều tranh), 蓽茇 (tiêu lốt — gia vị từ Ấn Độ).", "Tự nguyên_Xie": "茇 có bộ 艸 (cỏ) biểu nghĩa. Wiktionary không mô tả glyph origin chi tiết. Nghĩa gốc bao gồm: rễ cỏ, lều tranh, hành động đóng trại ngoài bụi cỏ (茇舍 — lều tranh dã chiến). Cũng dùng trong 蓽茇 (bạch hạt — một loại gia vị cay từ Ấn Độ). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái lều tranh; rễ cỏ", "Hạng Tần Suất (Jun Da)": "6464.0", "Tần Suất % (Jun Da)": "99.9926290936", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 犮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹犮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "犮", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "茇", "Unihan_Traditional (Chữ Phồn thể)": "茇", "Pinyin_Xie": "bá", "Âm Hán Việt_Xie": "bạt, bái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ trong văn học cổ để chỉ rễ cỏ hoặc túp lều tranh tạm bợ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('摅', '{"9000": "6465.0", "Chữ Trung Quốc": "摅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 13 | nét | 扌 | biểu nghĩa | tay | 慮 | lự | biểu âm | 摅 = 扌 (tay/手, biểu nghĩa) + 慮 (Lự, biểu âm). Chữ hình thanh: bộ 扌 chỉ hành động bằng tay, 慮 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thư\": 摅 (thư) — tay 扌 mở rộng lo toan 慮 để giãi bày tâm tư. Nhớ: \"thư hoài\" (giãi bày nỗi lòng). | Gương Hán-Việt | thư trong \"摅懷\" (thư hoài — giãi bày tâm tư), \"摅情\" (thư tình — bày tỏ cảm xúc) | Mở khoá kiến thức | Biết 摅 (thư) mở khoá: 摅懷 (thư hoài — giãi bày nỗi lòng), 摅情 (bày tỏ cảm xúc) — dùng trong thơ cổ.", "Tự nguyên_Xie": "Chữ hình thanh: 手 (扌, tay) biểu nghĩa, 慮 biểu âm. 摅 có nghĩa là bày tỏ, giãi bày cảm xúc, suy nghĩ; hoặc vọt lên (như cá vọt). Âm shū liên quan đến 疏 (sơ, thưa, thông), gợi ý mở thông ra ngoài. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giãi bày, giãi tỏ; vọt lên", "Hạng Tần Suất (Jun Da)": "6465.0", "Tần Suất % (Jun Da)": "99.9926399461", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 虑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌虑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "虑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "摅", "Unihan_Traditional (Chữ Phồn thể)": "攄", "Pinyin_Xie": "shū", "Âm Hán Việt_Xie": "sư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thể hiện hành động bày tỏ tình cảm hoặc ý kiến, thường dùng trong văn viết. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('顐', '{"9000": "6466.0", "Chữ Trung Quốc": "顐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 頁 | Số nét | 18 | nét | 顐 | hỗn | tượng hình | trơ trọi, trần trụi; biến thể của 諢 (lời bông đùa) | 顐 có bộ 頁 (đầu) biểu nghĩa. Glyph origin trong Wiktionary chỉ ghi {{Han etym}} không mô tả cụ thể. Chữ là dạng cổ của 諢 (bông đùa, hề hước) hoặc mang nghĩa trần trụi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hỗn\": 顐 (hỗn) — đầu 頁 trơ trọi, trần trụi; hoặc là lời bông đùa hỗn hào. Âm hỗn liên hệ biến thể của 諢 (bông đùa). | Gương Hán-Việt | hỗn trong dạng cổ: biến thể của 諢 (hỗn — bông đùa, lời hề) | Mở khoá kiến thức | Biết 顐 (hỗn) là chữ cổ hiếm, biến thể của 諢 (bông đùa). Xuất hiện trong từ điển cổ.", "Tự nguyên_Xie": "顐 là dạng thay thế của 諢 (bông đùa, lời hề) hoặc mang nghĩa trần trụi/trơ trọi. Bộ 頁 (đầu người) biểu nghĩa. Wiktionary ghi: alt form of 諢 và \"bare\". Âm đọc hún/hùn. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鐐", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "軍 + 頁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰軍頁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "軍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "頁", "Unihan_Simplified (Chữ Giản thể)": "顐", "Unihan_Traditional (Chữ Phồn thể)": "顐", "Pinyin_Xie": "wèn", "Âm Hán Việt_Xie": "hỗn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này làm động từ chỉ hành vi đùa cợt hoặc làm tính từ chỉ tính chất khôi hài, bông đùa. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蜾', '{"9000": "6467.0", "Chữ Trung Quốc": "蜾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 14 | nét | 蜾 | quả | tượng hình | ong đất đơn độc (potter wasp) | 蜾 có bộ 虫 (côn trùng) biểu nghĩa. Glyph origin trong Wiktionary chỉ ghi {{Han etym}} không mô tả cụ thể. Chữ chỉ xuất hiện trong 蜾蠃 (quả lõa — ong đất đơn độc, potter wasp).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quả\": 蜾 (quả) — loài côn trùng 虫 trong 蜾蠃 (ong đất đơn độc). Nhớ qua tích Kinh Thi: ong 蜾蠃 mang sâu về làm thức ăn cho con, từ đó \"螟蛉\" thành từ chỉ con nuôi. | Gương Hán-Việt | quả trong \"蜾蠃\" (quả lõa — ong đất đơn độc) | Mở khoá kiến thức | Biết 蜾 (quả) mở khoá điển cố 蜾蠃/螟蛉 từ Kinh Thi: ong đất mang sâu nuôi con → \"螟蛉之子\" = con nuôi.", "Tự nguyên_Xie": "Tiểu triện | 蜾 chỉ xuất hiện trong tổ hợp 蜾蠃 (quả lõa, potter wasp — loài ong đơn độc làm tổ bằng đất). Wiktionary không mô tả glyph origin chi tiết. Trong văn học cổ điển Trung Quốc, 蜾蠃 nổi tiếng qua thành ngữ \"螟蛉有子，蜾蠃負之\" (ong đất mang con sâu về nuôi) từ Kinh Thi, sau dùng nghĩa bóng cho con nuôi. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: quả loả 蜾蠃)", "Hạng Tần Suất (Jun Da)": "6467.0", "Tần Suất % (Jun Da)": "99.9926616511", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 果", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫果", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "果", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蜾", "Unihan_Traditional (Chữ Phồn thể)": "蜾", "Pinyin_Xie": "guǒ", "Âm Hán Việt_Xie": "quả", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, hầu như chỉ xuất hiện trong từ ghép quả khỏa để chỉ con tò vò. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('龂', '{"9000": "6468.0", "Chữ Trung Quốc": "龂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 齒 | Số nét | 12 | nét | 龂 | ngân | tượng hình | nướu răng; tranh cãi | 龂 là dạng giản thể của 齗, có bộ 齒/齿 (răng) biểu nghĩa. Glyph origin: {{Han simp|齗|f=齒|t=齿}} — đơn giản hóa bộ 齒 thành 齿.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngân\": 龂 (ngân) — bộ 齿 (răng) liên quan đến miệng và nướu. Nhớ: nướu răng 龂 là \"ngân\" — như tiếng nhai hay tranh cãi \"ngân nga\". | Gương Hán-Việt | ngân trong \"龂龂\" (ngân ngân — tranh cãi gay gắt) | Mở khoá kiến thức | Biết 龂 (ngân) giúp đọc từ ngữ y học cổ về nha khoa và cổ văn tả tranh luận: 龂龂然 (tranh cãi gay gắt).", "Tự nguyên_Xie": "Tiểu triện | Lưu thư thông (Minh) | 龂 là dạng giản thể của 齗. Wiktionary ghi: {{Han simp|齗|f=齒|t=齿}}. Bộ 齒 (răng) biểu nghĩa; chữ chỉ nướu răng (lợi) hoặc hành động tranh cãi, cãi nhau (龂龂 — tranh cãi gay gắt). Đây là chữ tạo muộn do đơn giản hóa, chưa thấy trong giáp cốt/kim văn dạng này. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lợi, chân răng", "Hạng Tần Suất (Jun Da)": "6468.0", "Tần Suất % (Jun Da)": "99.9926725036", "GavinGrover_Once (Chiết tự trực tiếp)": "齿 + 斤", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰齿斤", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "斤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "齿", "Unihan_Simplified (Chữ Giản thể)": "龂", "Unihan_Traditional (Chữ Phồn thể)": "齗", "Pinyin_Xie": "yín", "Âm Hán Việt_Xie": "ngân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ phần nướu răng hoặc làm động từ chỉ việc tranh cãi, cự cãi nhau. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('讉', '{"9000": "6470.0", "Chữ Trung Quốc": "讉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 22 | nét | 讉 | di | tượng hình | chữ không xác định nghĩa rõ | 讉 có bộ 言 (lời nói) biểu nghĩa. Glyph origin trong Wiktionary chỉ ghi {{Han etym}} không mô tả cụ thể. Chữ được ghi là \"rfdef\" (cần định nghĩa) trong Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"di\": 讉 (di) — bộ 言 (lời nói) gợi liên quan đến ngôn ngữ. Chữ hiếm, nghĩa chưa rõ ràng trong từ điển hiện đại. | Gương Hán-Việt | di trong văn liệu cổ (nghĩa chưa xác định rõ) | Mở khoá kiến thức | Biết 讉 (di) là chữ hiếm, bộ 言, nghĩa chưa được xác định đầy đủ trong từ điển học thuật hiện đại.", "Tự nguyên_Xie": "讉 có bộ 言 (lời nói) biểu nghĩa. Wiktionary ghi {{Han etym}} và {{rfdef|zh}} — nghĩa chưa được xác định đầy đủ. Âm đọc là yí. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "艉", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 遺", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言遺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "遺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "讉", "Unihan_Traditional (Chữ Phồn thể)": "讉", "Pinyin_Xie": "yí", "Âm Hán Việt_Xie": "di", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ để chỉ việc để lại hoặc truyền lại cái gì đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鎯', '{"9000": "6471.0", "Chữ Trung Quốc": "鎯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 16 | nét | 鎯 | lang | tượng hình | búa lớn | 鎯 có bộ 金 (kim loại) biểu nghĩa. Không có glyph origin từ Wiktionary. Chữ chỉ dụng cụ búa lớn (鎯頭 — búa tạ).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lang\": 鎯 (lang) — kim loại 金 nặng như búa tạ 鎯頭. Nhớ: âm \"lang\" gợi tiếng búa đập \"làng làng\" vang xa. | Gương Hán-Việt | lang trong \"鎯頭\" (lang đầu — búa tạ) | Mở khoá kiến thức | Biết 鎯 (lang) mở khoá: 鎯頭 (búa tạ, búa lớn) — dụng cụ đập sắt trong rèn đúc kim loại.", "Tự nguyên_Xie": "Không có glyph origin từ Wiktionary cho 鎯. Bộ 金 (kim loại) biểu nghĩa; phần còn lại có thể biểu âm. 鎯 xuất hiện trong 鎯頭 (búa tạ, búa lớn bằng kim loại). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鎯", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 郎", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金郎", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "郎", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "𨱍", "Unihan_Traditional (Chữ Phồn thể)": "鎯", "Pinyin_Xie": "láng", "Âm Hán Việt_Xie": "lang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong danh từ ghép để chỉ các loại dụng cụ kim loại như búa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('脒', '{"9000": "6472.0", "Chữ Trung Quốc": "脒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 10 | nét | 脒 | mễ | tượng hình | amidine (hóa học); bộ phận hữu cơ | 脒 có bộ 肉/月 (thịt/cơ thể) biểu nghĩa. Không có glyph origin từ Wiktionary. Chữ là thuật ngữ hóa học hiện đại chỉ nhóm amidine (-C(=NH)-NH₂).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mễ\": 脒 (mễ) — bộ 肉 gợi chất hữu cơ sinh học; 脒 là amidine trong hóa học. Nhớ: \"mễ\" âm gần \"mi\" trong \"amino\" (axit amin). | Gương Hán-Việt | mễ trong \"脒基\" (mễ cơ — nhóm amidino trong hóa học) | Mở khoá kiến thức | Biết 脒 (mễ) xuất hiện trong thuật ngữ hóa học và dược phẩm: amidine là nhóm chức quan trọng trong nhiều loại thuốc kháng khuẩn.", "Tự nguyên_Xie": "Không có glyph origin từ Wiktionary cho 脒. Bộ 肉 (thịt/cơ thể) biểu nghĩa, phù hợp với chất hữu cơ sinh học. 脒 là thuật ngữ hóa học hiện đại chỉ amidine (nhóm chức trong hóa học hữu cơ). Chưa có nguồn học thuật về glyph origin. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "amidin (hoá học)", "Hạng Tần Suất (Jun Da)": "6472.0", "Tần Suất % (Jun Da)": "99.9927474374", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 米", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月米", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "米", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "脒", "Unihan_Traditional (Chữ Phồn thể)": "脒", "Pinyin_Xie": "mǐ", "Âm Hán Việt_Xie": "mễ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong thuật ngữ hóa học để chỉ nhóm hợp chất chứa nitơ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('箬', '{"9000": "6473.0", "Chữ Trung Quốc": "箬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 14 | nét | 竹 | trúc | biểu nghĩa | tre | 若 | nhược | biểu âm | 箬 = 竹 (Trúc, biểu nghĩa: tre) + 若 (Nhược, biểu âm). Chữ hình thanh: bộ 竹 chỉ loại cây/lá tre, 若 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhược\": 箬 (nhược) — lá tre 竹 rộng nhược 若 như bàn tay, dùng gói bánh chưng Trung Hoa (粽子). | Gương Hán-Việt | nhược trong \"箬葉\" (nhược diệp — lá tre rộng), \"箬笠\" (nhược lạp — nón lá tre) | Mở khoá kiến thức | Biết 箬 (nhược) giúp đọc văn học ẩm thực và dân gian Trung Quốc: 箬葉 (lá gói 粽子), 箬笠 (nón lá che mưa).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Chữ hình thanh: 竹 (tre) biểu nghĩa, 若 biểu âm. 箬 chỉ một loại tre lá rộng (Phyllostachys bambusoides), lá của nó được dùng gói bánh truyền thống Trung Quốc như 粽子 (bánh chưng/tét kiểu Trung). Lá 箬 còn dùng làm nón lá, giày đi mưa trong văn hóa dân gian. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1199.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Trúc (108) Nhược (1198)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Trúc (số 108 - tre trúc/chỉ ý) ở trên chữ Nhược (số 1198 - giả sử/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Nhược chỉ âm, bộ Trúc chỉ ý. Nhược là tên một giống tre trúc, có lá to dùng để lợp nhà, đan nón.", "Nghĩa Tiếng Việt_Xie": "cây tre", "Hạng Tần Suất (Jun Da)": "6473.0", "Tần Suất % (Jun Da)": "99.9927577731", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 若", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮若", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "若", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "箬", "Unihan_Traditional (Chữ Phồn thể)": "箬", "Pinyin_Xie": "ruò", "Âm Hán Việt_Xie": "nhược", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng trước các danh từ khác để chỉ các vật làm từ lá tre. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲻', '{"9000": "6474.0", "Chữ Trung Quốc": "鲻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 16 | nét | 鲻 | tư | tượng hình | cá đối (flathead mullet) | 鲻 có bộ 鱼 (cá) biểu nghĩa. Glyph origin trong Wiktionary chỉ ghi {{Han etym}} không mô tả cụ thể. Chữ chỉ loài cá đối (Mugil cephalus).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tư\": 鲻 (tư) — cá 鱼 tư (đối) — loài cá đối sống ở vùng nước lợ ven biển, thịt ngon, nuôi trồng phổ biến. | Gương Hán-Việt | tư trong \"鲻魚\" (tư ngư — cá đối) | Mở khoá kiến thức | Biết 鲻 (tư) giúp đọc văn bản thủy sản Trung Quốc: 鲻魚 (cá đối, flathead mullet) là loài cá quan trọng trong nuôi trồng và đánh bắt.", "Tự nguyên_Xie": "鲻 là tên loài cá đối (flathead mullet, Mugil cephalus). Wiktionary không mô tả glyph origin chi tiết. Bộ 鱼 (cá) biểu nghĩa. Cá đối là loài cá biển và nước lợ phổ biến ở vùng nhiệt đới và cận nhiệt đới, có giá trị thực phẩm cao. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá đối", "Hạng Tần Suất (Jun Da)": "6474.0", "Tần Suất % (Jun Da)": "99.9927681088", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 甾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼甾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲻", "Unihan_Traditional (Chữ Phồn thể)": "鯔", "Pinyin_Xie": "zī", "Âm Hán Việt_Xie": "tri", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ đứng độc lập hoặc kết hợp thành cụm từ chỉ loài cá đối. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('埸', '{"9000": "6475.0", "Chữ Trung Quốc": "埸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 11 | nét | 埸 | dịch | tượng hình | bờ ranh giới ruộng; biên cương | 埸 có bộ 土 (đất) biểu nghĩa. Glyph origin trong Wiktionary chỉ ghi {{Han etym}} không mô tả cụ thể. Chữ chỉ bờ ranh giới giữa các thửa ruộng, hoặc biên giới/biên cương.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dịch\": 埸 (dịch) — đất 土 tại vùng biên dịch, bờ ranh giới ruộng đồng. Nhớ: \"dịch\" âm gần \"địa dịch\" — vùng đất biên giới. | Gương Hán-Việt | dịch trong \"疆埸\" (cương dịch — biên cương, biên giới lãnh thổ) | Mở khoá kiến thức | Biết 埸 (dịch) giúp đọc cổ văn về địa giới và nông nghiệp: 疆埸 (cương dịch — biên cương), bờ ruộng ranh giới.", "Tự nguyên_Xie": "埸 có bộ 土 (đất) biểu nghĩa. Wiktionary không cung cấp glyph origin chi tiết (ghi {{Han etym}} và {{rfdef|zh}}). Chữ chỉ đường ranh giới trên đồng ruộng hoặc biên cương lãnh thổ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bờ ruộng", "Hạng Tần Suất (Jun Da)": "6475.0", "Tần Suất % (Jun Da)": "99.9927784445", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 易", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土易", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "易", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "埸", "Unihan_Traditional (Chữ Phồn thể)": "埸", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "dịch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ ranh giới hoặc bờ ruộng trong văn ngôn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('颃', '{"9000": "6476.0", "Chữ Trung Quốc": "颃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 頁 | Số nét | 10 | nét | 颃 | hàng | tượng hình | chim bay thấp xuống | 颃 là chữ độc thể, cấu trúc nội bộ chưa được phân tích đầy đủ. Dạng cổ 頏 có bộ 頁 (trang) nhưng quan hệ hình thành học chưa rõ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hàng\": hình ảnh chim lao thấp — đầu 頁 cúi xuống như đầu chim sà thấp. | Gương Hán-Việt | hàng trong 頡頏 — tương đương, ngang nhau | Mở khoá kiến thức | Biết 颃 mở khoá thành ngữ 頡頏 chỉ sự ngang tài ngang sức.", "Tự nguyên_Xie": "Tiểu triện | 颃 (dạng cổ 頏) ghi âm háng, chỉ động tác chim bay thấp hoặc lao xuống. Thường gặp trong thành ngữ 頡頏 — chim bay lên rồi lao xuống — ám chỉ sự tương đương, không ai kém ai. Chưa có phân tích hình thành học học thuật rõ ràng; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bay thấp xuống", "Hạng Tần Suất (Jun Da)": "6476.0", "Tần Suất % (Jun Da)": "99.9927887802", "GavinGrover_Once (Chiết tự trực tiếp)": "亢 + 页", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亢页", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "页", "Unihan_Simplified (Chữ Giản thể)": "颃", "Unihan_Traditional (Chữ Phồn thể)": "頏", "Pinyin_Xie": "háng", "Âm Hán Việt_Xie": "hàng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ trong từ ghép để tả dáng bay lên bay xuống của chim. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蒹', '{"9000": "6477.0", "Chữ Trung Quốc": "蒹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 13 | nét | 蒹 | kiêm | tượng hình | cây sậy non chưa kết hạt | 蒹 là chữ độc thể, cấu trúc hình thành học chưa được phân tích. Bộ 艸 gợi ý thực vật nhưng thành phần nội bộ không rõ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiêm\": sậy non kiêm nhường, chưa kết hạt — liên tưởng bài thơ 蒹葭 trong Kinh Thi. | Gương Hán-Việt | kiêm trong 蒹葭 (kiêm già) — bãi lau sậy cổ thi | Mở khoá kiến thức | Biết 蒹 mở khoá câu thơ cổ 蒹葭蒼蒼 nổi tiếng trong Kinh Thi.", "Tự nguyên_Xie": "蒹 đọc jiān, chỉ cây sậy non (Phragmites communis) chưa kết hạt — phân biệt với 葭 là sậy non mới mọc. Cặp 蒹葭 nổi tiếng trong Kinh Thi: 蒹葭蒼蒼，白露為霜 — bãi lau sậy xanh mướt buổi sớm sương. Chưa có phân tích hình thành học học thuật rõ ràng; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỏ kiêm", "Hạng Tần Suất (Jun Da)": "6477.0", "Tần Suất % (Jun Da)": "99.9927991159", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 兼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹兼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蒹", "Unihan_Traditional (Chữ Phồn thể)": "蒹", "Pinyin_Xie": "jiān", "Âm Hán Việt_Xie": "kiêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ xuất hiện trong văn thơ cổ để chỉ loài cỏ lau bên sông. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瞍', '{"9000": "6478.0", "Chữ Trung Quốc": "瞍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 14 | nét | 目 | mục | biểu nghĩa | mắt | 叟 | tẩu | biểu âm | ông lão (cho âm sǒu) | 瞍 = 目 (Mục, biểu nghĩa: mắt) + 叟 (Tẩu, biểu âm); chữ hình thanh. Mắt 目 chỉ phạm trù thị giác; 叟 cho âm gần sǒu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tẩu\": ông lão (叟) mà mắt (目) không thấy — 瞍 là người mù, nhạc sư mù thời cổ. | Gương Hán-Việt | tẩu trong 矇瞍 — người mù hoàn toàn | Mở khoá kiến thức | Biết 瞍 mở khoá từ cổ văn 矇瞍 chỉ người khiếm thị trong thư tịch Chu.", "Tự nguyên_Xie": "Tiểu triện | 瞍 là chữ hình thanh: 目 (mắt) biểu nghĩa, 叟 (ông lão) biểu âm. Nghĩa gốc là người mù — mắt không có con ngươi. Trong văn cổ chỉ nhạc sư mù thời Chu. Wiktionary xác nhận cấu trúc psc rõ ràng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mắt không có con ngươi", "Hạng Tần Suất (Jun Da)": "6478.0", "Tần Suất % (Jun Da)": "99.9928094516", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 叟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目叟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "叟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "瞍", "Unihan_Traditional (Chữ Phồn thể)": "瞍", "Pinyin_Xie": "sǒu", "Âm Hán Việt_Xie": "tẩu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ bổ nghĩa cho mắt hoặc danh từ chỉ người mù trong văn cổ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铫', '{"9000": "6479.0", "Chữ Trung Quốc": "铫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 11 | nét | 铫 | diêu | tượng hình | nồi nhỏ có quai và vòi; mác dài | 铫 (dạng phồn thể 銚) cấu trúc nội bộ chưa được phân tích đầy đủ. Bộ 金 gợi ý vật bằng kim loại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"diêu\": kim loại (金) đúc thành ấm nhỏ — 铫 là dụng cụ đun nước tay cầm. | Gương Hán-Việt | diêu trong 銚子 — ấm đun nước nhỏ | Mở khoá kiến thức | Biết 铫 mở khoá từ cổ 銚子 (ấm đun nước) và dụng cụ cổ truyền.", "Tự nguyên_Xie": "Tiểu triện | 铫 (dạng cổ 銚) có nhiều âm: yáo (cuốc lớn, họ), diào (nồi nhỏ có quai và vòi đun nước), tiáo (giáo dài). Âm diào thông dụng nhất, chỉ ấm đất nung hoặc kim loại nhỏ cầm tay. Nguồn gốc hình thành học chưa được phân tích rõ; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái mác (vũ khí)", "Hạng Tần Suất (Jun Da)": "6479.0", "Tần Suất % (Jun Da)": "99.9928197873", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 兆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅兆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铫", "Unihan_Traditional (Chữ Phồn thể)": "銚", "Pinyin_Xie": "diào", "Âm Hán Việt_Xie": "diêu, điệu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ các loại dụng cụ kim loại như nồi nhỏ có tay cầm hoặc vũ khí cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蒐', '{"9000": "6480.0", "Chữ Trung Quốc": "蒐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 艸 | tháu | biểu nghĩa | cỏ, thực vật | 鬼 | quỷ | biểu nghĩa | quỷ, linh hồn | 蒐 = 艸 (Tháu, cỏ) + 鬼 (Quỷ); chữ hội ý. Cỏ có màu đỏ như máu quỷ — gốc là cây thiên thảo cho màu đỏ, rồi mở rộng nghĩa thành tìm kiếm, thu thập.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sưu\": quỷ (鬼) ẩn trong cỏ (艸) — phải sưu tầm mới thấy; 蒐 nghĩa là thu thập, tìm kiếm. | Gương Hán-Việt | sưu trong 蒐集 (sưu tập), 蒐索 (sưu tìm) | Mở khoá kiến thức | Biết 蒐 mở khoá các từ 蒐集, 蒐證 trong văn viết trang trọng.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | 蒐 là chữ hội ý: 艸 (cỏ) + 鬼 (quỷ). Gốc nghĩa là cây thiên thảo (茜草, Rubia cordifolia) — cỏ có rễ đỏ dùng nhuộm. Từ đó mở rộng: săn bắn mùa xuân, rồi thu thập, tìm kiếm. Chữ 搜 là biến thể thông dụng trong hiện đại. Wiktionary xác nhận cấu trúc hội ý. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Tìm kiếm", "Hạng Tần Suất (Jun Da)": "6480.0", "Tần Suất % (Jun Da)": "99.992830123", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 鬼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹鬼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鬼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蒐", "Unihan_Traditional (Chữ Phồn thể)": "蒐", "Pinyin_Xie": "sōu", "Âm Hán Việt_Xie": "sưu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ đối tượng cần tìm kiếm hoặc thu thập. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蹻', '{"9000": "6481.0", "Chữ Trung Quốc": "蹻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 19 | nét | 蹻 | kều | tượng hình | nhón chân, giơ chân; đi cà kheo | 蹻 cấu trúc nội bộ chưa được phân tích đầy đủ. Bộ 足 gợi ý liên quan đến chân.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kều\": chân (足) kều lên cao — 蹻 là nhón gót, đứng trên đầu ngón chân. | Gương Hán-Việt | kều trong ngữ cảnh nhón chân, đứng cao | Mở khoá kiến thức | Biết 蹻 mở khoá hình ảnh cổ văn về người đi cà kheo và động tác nhón chân.", "Tự nguyên_Xie": "Tiểu triện | 蹻 đọc juē/qiāo/jué, chỉ động tác nhón gót chân, giơ chân lên, hoặc đi cà kheo. Cũng có nghĩa dũng cảm trong cổ văn. Bộ 足 liên quan đến chân. Chưa có phân tích hình thành học học thuật rõ ràng; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giơ; nhấc; kiễng chân; nhón chân; đi cà kheo", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 喬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊喬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "喬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "蹻", "Unihan_Traditional (Chữ Phồn thể)": "蹻", "Pinyin_Xie": "juē", "Âm Hán Việt_Xie": "cược", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ chỉ động tác của chân hoặc tính từ miêu tả sự nhanh nhẹn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('幞', '{"9000": "6482.0", "Chữ Trung Quốc": "幞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 巾 | Số nét | 15 | nét | 幞 | phốc | tượng hình | khăn bịt đầu, mũ vải | 幞 cấu trúc nội bộ không có trong dữ liệu (glyphOrigin null). Bộ 巾 gợi ý vải, khăn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phốc\": khăn 巾 phốc đầu — 幞 là chiếc khăn mũ quan lại thời Đường. | Gương Hán-Việt | phốc trong 幞頭 — khăn mũ quan lại thời Đường | Mở khoá kiến thức | Biết 幞 mở khoá từ lịch sử 幞頭 — mũ quan trọng trong phục sức thời Tùy Đường.", "Tự nguyên_Xie": "Tiểu triện | 幞 đọc fú, chỉ loại khăn bịt đầu hoặc mũ vải thời Tùy-Đường (幞頭) — tiền thân của mũ quan lại. Bộ 巾 liên quan đến vải khăn. Chưa có nguồn học thuật về cấu trúc hình thành; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái khăn bịt đầu", "Hạng Tần Suất (Jun Da)": "6482.0", "Tần Suất % (Jun Da)": "99.9928507944", "GavinGrover_Once (Chiết tự trực tiếp)": "巾 + 菐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰巾菐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "菐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "巾", "Unihan_Simplified (Chữ Giản thể)": "幞", "Unihan_Traditional (Chữ Phồn thể)": "幞", "Pinyin_Xie": "fú", "Âm Hán Việt_Xie": "phốc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ để chỉ loại khăn quấn đầu của nam giới thời phong kiến. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('阯', '{"9000": "6483.0", "Chữ Trung Quốc": "阯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 6 | nét | 阯 | chỉ | tượng hình | nền đất, nền móng | 阯 cấu trúc nội bộ không rõ. Bộ 阜 gợi ý đất, gò địa hình.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chỉ\": gò đất 阜 chỉ ra nơi chốn — 阯 là nền móng, địa chỉ. | Gương Hán-Việt | chỉ trong 地阯 — địa điểm, địa chỉ | Mở khoá kiến thức | Biết 阯 tương đương 址 hiện đại trong văn bản trang trọng và địa danh cổ.", "Tự nguyên_Xie": "Tiểu triện | 阯 đọc zhǐ, là biến thể cổ của 址 (nền đất, địa chỉ). Bộ 阜 liên quan đến đất, gò đất. Nghĩa gốc là nền móng, vị trí đất. Hiện nay 址 là dạng thông dụng; 阯 xuất hiện trong địa danh tại Hồng Kông và văn bản trang trọng. Chưa có nguồn học thuật; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nền đất; (xem: địa chỉ 地址)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + 止", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝止", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "止", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "阯", "Unihan_Traditional (Chữ Phồn thể)": "阯", "Pinyin_Xie": "zhǐ", "Âm Hán Việt_Xie": "chỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng làm danh từ trong các từ ghép chỉ vị trí hoặc nền móng như địa chỉ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6":