INSERT INTO characters (char, data) VALUES ('觏', '{"9000": "6484.0", "Chữ Trung Quốc": "觏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 見 | Số nét | 14 | nét | 觏 | cấu | tượng hình | tình cờ gặp gỡ, không hẹn mà gặp | 觏 (dạng phồn thể 覯) cấu trúc nội bộ không rõ trong dữ liệu. Bộ 見 gợi ý liên quan đến cái nhìn, gặp mặt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cấu\": mắt 見 chợt thấy — 觏 là bất ngờ gặp mặt, không hẹn trước. | Gương Hán-Việt | cấu trong 亦既覯止 (Kinh Thi) — đã tình cờ gặp gỡ | Mở khoá kiến thức | Biết 觏 mở khoá ngôn ngữ thơ ca Kinh Thi về gặp gỡ tình cờ.", "Tự nguyên_Xie": "Tiểu triện | 觏 (dạng cổ 覯) đọc gòu, nghĩa là tình cờ gặp gỡ, không hẹn mà gặp. Bộ 見 chỉ hành động nhìn, gặp mặt. Xuất hiện trong Kinh Thi: 亦既覯止 (lại đã gặp gỡ). Chưa có phân tích hình thành học rõ ràng; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "không hẹn mà gặp", "Hạng Tần Suất (Jun Da)": "6484.0", "Tần Suất % (Jun Da)": "99.9928714659", "GavinGrover_Once (Chiết tự trực tiếp)": "冓 + 见", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰冓见", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冓", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "见", "Unihan_Simplified (Chữ Giản thể)": "觏", "Unihan_Traditional (Chữ Phồn thể)": "覯", "Pinyin_Xie": "gòu", "Âm Hán Việt_Xie": "cấu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường xuất hiện trong văn viết cổ với nghĩa là tình cờ gặp mặt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('媵', '{"9000": "6485.0", "Chữ Trung Quốc": "媵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 13 | nét | 朕 | trẫm | biểu âm | ta (ngôi vua) — cho âm | 女 | nữ | biểu nghĩa | người phụ nữ | 媵 = 朕 (Trẫm, biểu âm) + 女 (Nữ, biểu nghĩa: người phụ nữ); chữ hình thanh. 朕 cho âm gần yìng; 女 chỉ phạm trù phụ nữ hầu cận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dựng\": người phụ nữ (女) hầu theo dựng cô dâu — 媵 là tì thiếp đi kèm lễ cưới. | Gương Hán-Việt | dựng trong 媵妾 — tì thiếp đi kèm cô dâu | Mở khoá kiến thức | Biết 媵 mở khoá chế độ hôn nhân cổ 媵制 — tập tục cho người hầu theo cô dâu.", "Tự nguyên_Xie": "Lục thư thông | 媵 là chữ hình thanh: 女 biểu nghĩa, 朕 biểu âm. Nghĩa gốc là người hầu gái đi theo cô dâu về nhà chồng — tập tục hôn nhân thời cổ (媵制). Cũng nghĩa là tiễn đưa, hộ tống. Wiktionary xác nhận cấu trúc psc rõ ràng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "người hầu đi theo các phu nhân khi mới xuất giá; đính thêm tặng vật phụ khi tặng quà", "Hạng Tần Suất (Jun Da)": "6485.0", "Tần Suất % (Jun Da)": "99.9928818016", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "媵", "Unihan_Traditional (Chữ Phồn thể)": "媵", "Pinyin_Xie": "yìng", "Âm Hán Việt_Xie": "dắng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ người thiếp theo hầu hoặc làm động từ với nghĩa đưa tiễn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钬', '{"9000": "6486.0", "Chữ Trung Quốc": "钬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 9 | nét | 金 | kim | biểu nghĩa | kim loại | 火 | hoả | biểu âm | lửa (cho âm huǒ) | 钬 = 金 (Kim, biểu nghĩa: kim loại) + 火 (Hoả, biểu âm); chữ hình thanh. Đây là chữ tạo muộn để phiên âm tên nguyên tố holmium (Ho).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoả kim\": kim loại (金) nóng như lửa (火) — 钬 là holmium, nguyên tố đất hiếm. | Gương Hán-Việt | hoả trong ngữ cảnh bảng tuần hoàn, nguyên tố holmium | Mở khoá kiến thức | Biết 钬 mở khoá tên các nguyên tố đất hiếm viết bằng chữ Hán.", "Tự nguyên_Xie": "钬 là chữ tạo muộn (hiện đại) để ghi tên nguyên tố holmium (Ho, số hiệu 67). Theo công thức tạo chữ khoa học: 金 (kim loại) biểu nghĩa, 火 (huǒ) biểu âm gần huǒ/huo. Dạng phồn thể 鈥. Wiktionary xác nhận cấu trúc psc rõ ràng. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố honmi, Ho", "Hạng Tần Suất (Jun Da)": "6486.0", "Tần Suất % (Jun Da)": "99.9928921373", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 火", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅火", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "火", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钬", "Unihan_Traditional (Chữ Phồn thể)": "鈥", "Pinyin_Xie": "huǒ", "Âm Hán Việt_Xie": "hỏa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chuyên ngành hóa học để chỉ nguyên tố Holmium. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('襦', '{"9000": "6487.0", "Chữ Trung Quốc": "襦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 19 | nét | 襦 | nhu | tượng hình | áo cánh ngắn, áo lót | 襦 cấu trúc nội bộ chưa được phân tích đầy đủ trong dữ liệu. Bộ 衣 gợi ý trang phục, quần áo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhu\": áo 衣 mềm nhu (nhu) — 襦 là áo cánh ngắn nhẹ nhàng, mềm mại của phụ nữ cổ. | Gương Hán-Việt | nhu trong 襦裙 (nhu quần) — áo cánh ngắn và váy | Mở khoá kiến thức | Biết 襦 mở khoá trang phục cổ 襦裙 — bộ đồ nữ phổ biến thời Hán Đường.", "Tự nguyên_Xie": "Tiểu triện | 襦 đọc rú, chỉ loại áo cánh ngắn (ru) — trang phục của phụ nữ thời cổ, mặc trong hoặc ngoài. Bộ 衣 liên quan đến trang phục. Nổi tiếng qua 襦裙 (áo cánh ngắn + váy) — bộ trang phục nữ truyền thống. Chưa có phân tích hình thành học rõ; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "áo cánh, áo lót", "Hạng Tần Suất (Jun Da)": "6487.0", "Tần Suất % (Jun Da)": "99.992902473", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 需", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤需", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "需", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "襦", "Unihan_Traditional (Chữ Phồn thể)": "襦", "Pinyin_Xie": "rú", "Âm Hán Việt_Xie": "nhu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loại áo ngắn mặc bên trong thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('簋', '{"9000": "6488.0", "Chữ Trung Quốc": "簋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 17 | nét | 簋 | quỹ | tượng hình | bình đựng xôi, đồ thờ bằng đồng | 簋 là chữ độc thể, cấu trúc hình thành học chưa được phân tích rõ. Bộ 竹 gợi ý liên quan đến tre hoặc vật đựng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quỹ\": chiếc quỹ đựng xôi dâng thần — 簋 là đồ thờ đồng hình tròn thời Chu. | Gương Hán-Việt | quỹ trong 簠簋 (phủ quỹ) — cặp đồ lễ cúng tế | Mở khoá kiến thức | Biết 簋 mở khoá kiến thức về đồ đồng nghi lễ thời Chu và văn hoá tế tự cổ Trung Hoa.", "Tự nguyên_Xie": "簋 đọc guǐ, là loại đồ đựng thức ăn (thường là xôi) dùng trong các nghi lễ cúng tế thời cổ — có thân tròn, hai hoặc bốn quai, đế hoặc chân đứng, đôi khi có nắp. Thường làm bằng đồng thau hoặc gốm. Trong nghi lễ Chu thường đi cùng 鼎 (đỉnh). Chưa có phân tích hình thành học học thuật rõ ràng; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bình đựng xôi", "Hạng Tần Suất (Jun Da)": "6488.0", "Tần Suất % (Jun Da)": "99.9929128087", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "簋", "Unihan_Traditional (Chữ Phồn thể)": "簋", "Pinyin_Xie": "guǐ", "Âm Hán Việt_Xie": "quỹ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại đồ tế khí bằng tre hoặc đồng để đựng lương thực. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('翮', '{"9000": "6489.0", "Chữ Trung Quốc": "翮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羽 | Số nét | 16 | nét | 鬲 | lịch | biểu âm | vạc ba chân (cho âm hé) | 羽 | vũ | biểu nghĩa | lông vũ, cánh chim | 翮 = 鬲 (Lịch, biểu âm) + 羽 (Vũ, biểu nghĩa: lông vũ, cánh); chữ hình thanh. 羽 chỉ phạm trù lông chim; 鬲 cho âm gần hé.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hách\": lông vũ (羽) cứng như hách — 翮 là ống lông chim, phần cứng của chiếc lông. | Gương Hán-Việt | hách trong ngữ cảnh thơ ca cổ về cánh chim, ống lông | Mở khoá kiến thức | Biết 翮 mở khoá từ vựng thơ ca cổ về lông vũ, cánh chim và sự tự do bay bổng.", "Tự nguyên_Xie": "Tiểu triện | 翮 là chữ hình thanh: 羽 (lông vũ) biểu nghĩa, 鬲 biểu âm. Nghĩa gốc là ống lông chim — phần cứng giữa chiếc lông. Mở rộng chỉ cánh chim, chim chóc, nhạc cụ hơi. Wiktionary xác nhận cấu trúc psc rõ ràng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lông cánh chim", "Hạng Tần Suất (Jun Da)": "6489.0", "Tần Suất % (Jun Da)": "99.9929231444", "GavinGrover_Once (Chiết tự trực tiếp)": "鬲 + 羽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鬲羽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "羽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鬲", "Unihan_Simplified (Chữ Giản thể)": "翮", "Unihan_Traditional (Chữ Phồn thể)": "翮", "Pinyin_Xie": "hé", "Âm Hán Việt_Xie": "cách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ phần ống cứng của lông chim hoặc dùng để chỉ cánh chim nói chung. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蹯', '{"9000": "6490.0", "Chữ Trung Quốc": "蹯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 19 | nét | 蹯 | phàn | tượng hình | bàn chân thú, chân gấu | 蹯 cấu trúc nội bộ chưa được phân tích đầy đủ. Bộ 足 gợi ý liên quan đến chân.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phàn\": bàn chân (足) thú phàn ăn — 蹯 là chân thú, chân gấu quý giá trong ẩm thực cổ. | Gương Hán-Việt | phàn trong 熊蹯 — chân gấu, món ăn quý thời cổ | Mở khoá kiến thức | Biết 蹯 mở khoá từ vựng ẩm thực cổ điển và hình ảnh chân thú trong văn học Trung Hoa.", "Tự nguyên_Xie": "蹯 đọc fán, chỉ bàn chân của thú vật — đặc biệt chân gấu (熊蹯) vốn là món ăn quý thời cổ. Bộ 足 liên quan đến chân. Ghi lại trong nhiều tác phẩm cổ điển. Chưa có phân tích hình thành học học thuật rõ ràng; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chân loài thú", "Hạng Tần Suất (Jun Da)": "6490.0", "Tần Suất % (Jun Da)": "99.9929334801", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 番", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊番", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "番", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "蹯", "Unihan_Traditional (Chữ Phồn thể)": "蹯", "Pinyin_Xie": "fán", "Âm Hán Việt_Xie": "phiền", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường dùng để chỉ bàn chân của các loài dã thú như gấu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('艖', '{"9000": "6491.0", "Chữ Trung Quốc": "艖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 舟 | Số nét | 15 | nét | 艖 | soa | tượng hình | thuyền nhỏ, bè | 艖 cấu trúc nội bộ chưa được phân tích đầy đủ. Bộ 舟 gợi ý phương tiện đường thuỷ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"soa\": con thuyền (舟) soa nhỏ — 艖 là thuyền nhỏ lướt sông. | Gương Hán-Việt | soa trong ngữ cảnh thơ ca cổ về thuyền bè nhỏ | Mở khoá kiến thức | Biết 艖 mở khoá từ vựng thơ ca cổ về thuyền nhỏ, du thuyền trên sông.", "Tự nguyên_Xie": "艖 đọc chā, chỉ loại thuyền nhỏ hoặc bè. Bộ 舟 liên quan đến thuyền, phương tiện đường thuỷ. Chưa có phân tích hình thành học học thuật rõ ràng; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thuyền con; thuyền nhỏ", "Hạng Tần Suất (Jun Da)": "6491.0", "Tần Suất % (Jun Da)": "99.9929438158", "GavinGrover_Once (Chiết tự trực tiếp)": "舟 + 差", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舟差", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "差", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舟", "Unihan_Simplified (Chữ Giản thể)": "艖", "Unihan_Traditional (Chữ Phồn thể)": "艖", "Pinyin_Xie": "chā", "Âm Hán Việt_Xie": "xoa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ dùng trong văn thơ cổ để chỉ những con thuyền nhỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲿', '{"9000": "6492.0", "Chữ Trung Quốc": "鲿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 17 | nét | 鲿 | trường | tượng hình | cá trê vàng, cá nheo | 鲿 cấu trúc nội bộ chưa được phân tích đầy đủ. Bộ 魚 gợi ý loài cá.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trường\": cá (魚) dài trường — 鲿 là cá trê vàng, thân dài sống dưới đáy nước. | Gương Hán-Việt | trường trong 黃鱨魚 — cá trê vàng | Mở khoá kiến thức | Biết 鲿 mở khoá từ vựng thuỷ sản và tên khoa học cá nước ngọt Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | 鲿 (dạng cổ 鱨) đọc cháng, chỉ cá trê vàng (Tachysurus fulvidraco/sinensis) — loài cá nước ngọt phổ biến ở Trung Quốc. Cũng dùng cho họ cá trê (Bagridae). Bộ 魚 chỉ loài cá. Chưa có phân tích hình thành học rõ ràng; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá măng", "Hạng Tần Suất (Jun Da)": "6492.0", "Tần Suất % (Jun Da)": "99.9929954943", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 尝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼尝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲿", "Unihan_Traditional (Chữ Phồn thể)": "鱨", "Pinyin_Xie": "cháng", "Âm Hán Việt_Xie": "thường", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ một loài cá nước ngọt trong các tài liệu sinh học hoặc tên gọi địa phương. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蹠', '{"9000": "6493.0", "Chữ Trung Quốc": "蹠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 18 | nét | 蹠 | chích | tượng hình | lòng bàn chân; đạp lên | 蹠 cấu trúc nội bộ chưa được phân tích đầy đủ. Bộ 足 gợi ý liên quan đến chân. Wiktionary ghi nhận 蹠 là biến thể của 跖.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chích\": bàn chân (足) chích xuống đất — 蹠 là lòng bàn chân, bước đạp. | Gương Hán-Việt | chích trong 蹠骨 (chích cốt) — xương bàn chân | Mở khoá kiến thức | Biết 蹠 mở khoá từ giải phẫu 蹠骨 (xương bàn chân) và tên cướp Chí Tẩu trong Trang Tử.", "Tự nguyên_Xie": "Tiểu triện | 蹠 đọc zhí/zhè, là biến thể/đồng nghĩa của 跖 — chỉ lòng bàn chân hoặc hành động đạp chân lên. Cũng liên quan đến tên người (Chí Tẩu — tên tướng cướp trong Trang Tử). Bộ 足 liên quan đến chân. Chưa có nguồn học thuật; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây trồng", "Hạng Tần Suất (Jun Da)": "6493.0", "Tần Suất % (Jun Da)": "99.9930151321", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 庶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊庶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "庶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "蹠", "Unihan_Traditional (Chữ Phồn thể)": "蹠", "Pinyin_Xie": "zhí", "Âm Hán Việt_Xie": "chích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ trong y học để chỉ lòng bàn chân hoặc làm động từ mang nghĩa giẫm, đạp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('攉', '{"9000": "6494.0", "Chữ Trung Quốc": "攉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 19 | nét | 攉 | hoắc | tượng hình | xúc bằng xẻng, hốt; vẫy tay gọi | 攉 cấu trúc nội bộ chưa được phân tích đầy đủ. Bộ 手 (扌) gợi ý hành động tay.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoắc\": tay (扌) vung hoắc một cái — 攉 là hốt xúc hoặc vẫy gọi. | Gương Hán-Việt | hoắc trong ngữ cảnh lao động, hốt than hốt đất | Mở khoá kiến thức | Biết 攉 mở khoá từ vựng lao động thủ công về hốt xúc bằng xẻng.", "Tự nguyên_Xie": "攉 đọc huō, chỉ hành động hốt, xúc bằng xẻng hoặc vẫy tay gọi. Bộ 手 liên quan đến hành động tay. Chưa có phân tích hình thành học học thuật rõ ràng; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xúc bằng xẻng, hốt", "Hạng Tần Suất (Jun Da)": "6494.0", "Tần Suất % (Jun Da)": "99.993024951", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 霍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌霍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "霍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "攉", "Unihan_Traditional (Chữ Phồn thể)": "攉", "Pinyin_Xie": "huō", "Âm Hán Việt_Xie": "hoắc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ chỉ hành động xúc đất cát bằng xẻng hoặc quăng ném đồ vật. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('禊', '{"9000": "6495.0", "Chữ Trung Quốc": "禊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 13 | nét | 禊 | khế | tượng hình | lễ tẩy trừ ô uế theo mùa | 禊 cấu trúc nội bộ chưa được phân tích đầy đủ. Bộ 示 gợi ý lễ nghi, tế tự.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khế\": lễ 示 khế ước với thần — 禊 là nghi lễ tẩy trừ ô uế bên sông mùa xuân. | Gương Hán-Việt | khế trong 修禊 — lễ tẩy trần nổi tiếng trong Lan Đình Tự | Mở khoá kiến thức | Biết 禊 mở khoá 修禊 trong Lan Đình Tự (Vương Hy Chi) — nghi lễ văn hoá nổi tiếng.", "Tự nguyên_Xie": "禊 đọc xì, chỉ nghi lễ thanh tẩy diễn ra vào mùa xuân và mùa thu — người ta tắm gội ở sông suối để trừ tà khí, cầu phúc. Nổi tiếng qua 修禊 (sửa lễ tẩy trần) trong bài tựa Lan Đình (Vương Hy Chi). Bộ 示 liên quan đến lễ nghi thiêng liêng. Chưa có phân tích hình thành học rõ; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trừ ma quỷ", "Hạng Tần Suất (Jun Da)": "6495.0", "Tần Suất % (Jun Da)": "99.99303477", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 契", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻契", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "契", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "禊", "Unihan_Traditional (Chữ Phồn thể)": "禊", "Pinyin_Xie": "xì", "Âm Hán Việt_Xie": "hễ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chủ yếu dùng làm danh từ chỉ nghi lễ cúng tế tẩy trần thời cổ đại vào mùa xuân và mùa thu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('箐', '{"9000": "6496.0", "Chữ Trung Quốc": "箐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 14 | nét | 箐 | thanh | tượng hình | rừng tre trong núi; cung nỏ bằng tre | 箐 cấu trúc nội bộ chưa được phân tích đầy đủ. Bộ 竹 gợi ý liên quan đến tre.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thanh\": tre (竹) xanh thanh trong rừng núi — 箐 là thung lũng rừng tre. | Gương Hán-Việt | thanh trong 箐谷 — thung lũng rừng tre | Mở khoá kiến thức | Biết 箐 mở khoá địa danh vùng Vân Nam và từ vựng địa lý rừng núi.", "Tự nguyên_Xie": "箐 có hai âm: jīng (đọc cổ) và qìng/qiàn — chỉ thung lũng có rừng tre, hoặc rừng tre lớn trên núi. Bộ 竹 liên quan đến tre. Chủ yếu dùng trong địa danh ở Vân Nam. Chưa có phân tích hình thành học rõ; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rừng tre già trong núi; cung nỏ làm bằng tre", "Hạng Tần Suất (Jun Da)": "6496.0", "Tần Suất % (Jun Da)": "99.9930445889", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 青", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮青", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "青", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "箐", "Unihan_Traditional (Chữ Phồn thể)": "箐", "Pinyin_Xie": "qìng", "Âm Hán Việt_Xie": "tinh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ các thung lũng có rừng tre rậm rạp ở vùng núi phía Tây Nam Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镟', '{"9000": "6497.0", "Chữ Trung Quốc": "镟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 16 | nét | 镟 | toàn | tượng hình | máy tiện; con lăn | 镟 (dạng phồn thể 鏇) cấu trúc nội bộ chưa được phân tích đầy đủ. Bộ 金 gợi ý dụng cụ kim loại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"toàn\": kim loại (金) quay toàn vòng — 镟 là máy tiện, quay tròn để tạo hình. | Gương Hán-Việt | toàn trong 镟床 (toàn sàng) — máy tiện | Mở khoá kiến thức | Biết 镟 mở khoá từ vựng kỹ thuật 镟床 (máy tiện) trong thủ công nghiệp.", "Tự nguyên_Xie": "Tiểu triện | 镟 (dạng cổ 鏇) đọc xuàn, chỉ máy tiện — dụng cụ quay tròn để tiện đồ vật hình tròn bằng kim loại. Bộ 金 liên quan đến kim loại. Chưa có phân tích hình thành học rõ; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "máy tiện để tiện các đồ hình tròn; con lăn", "Hạng Tần Suất (Jun Da)": "6497.0", "Tần Suất % (Jun Da)": "99.9930544078", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 旋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅旋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镟", "Unihan_Traditional (Chữ Phồn thể)": "鏇", "Pinyin_Xie": "xuàn", "Âm Hán Việt_Xie": "tuyền", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ chỉ việc tiện gỗ, kim loại hoặc làm danh từ chỉ dụng cụ tiện, khay đựng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('癍', '{"9000": "6498.0", "Chữ Trung Quốc": "癍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 17 | nét | 癍 | ban | tượng hình | nốt ban, vết bệnh trên da | 癍 cấu trúc nội bộ không có trong dữ liệu (glyphOrigin null). Bộ 疒 gợi ý bệnh tật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ban\": bệnh (疒) nổi ban đỏ — 癍 là nốt ban, vết bệnh trên da. | Gương Hán-Việt | ban trong 癍疹 — nốt ban, vết bệnh trên da | Mở khoá kiến thức | Biết 癍 mở khoá từ y học cổ về bệnh ban và các vết nổi trên da.", "Tự nguyên_Xie": "癍 đọc bān, chỉ nốt ban hoặc vết bệnh xuất hiện trên da — thường dùng trong y học. Bộ 疒 liên quan đến bệnh. Chưa có nguồn học thuật về cấu trúc hình thành; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bị bệnh ban", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 斑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒斑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "斑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "癍", "Unihan_Traditional (Chữ Phồn thể)": "癍", "Pinyin_Xie": "bān", "Âm Hán Việt_Xie": "ban", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong y học để chỉ các vết sẹo, đốm màu hoặc nốt ban xuất hiện trên da. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('霪', '{"9000": "6499.0", "Chữ Trung Quốc": "霪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 雨 | Số nét | 19 | nét | 霪 | dầm | tượng hình | mưa dầm, mưa dài ngày | 霪 cấu trúc nội bộ chưa được phân tích đầy đủ. Bộ 雨 gợi ý liên quan đến mưa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dầm\": mưa (雨) dầm dề kéo dài — 霪 là mưa dầm, mưa ngày này qua ngày khác. | Gương Hán-Việt | dầm trong 霪雨 (dầm vũ) — mưa dầm kéo dài | Mở khoá kiến thức | Biết 霪 mở khoá từ thơ ca cổ về mưa dầm và thiên tai lũ lụt.", "Tự nguyên_Xie": "霪 đọc yín, chỉ mưa kéo dài liên tục — mưa dầm, mưa lũ. Bộ 雨 liên quan đến mưa. Xuất hiện trong 霪雨 (mưa dầm), 霪霖 (mưa liên miên). Chưa có phân tích hình thành học rõ; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mưa dầm", "Hạng Tần Suất (Jun Da)": "6499.0", "Tần Suất % (Jun Da)": "99.9930740456", "GavinGrover_Once (Chiết tự trực tiếp)": "雨 + 淫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱雨淫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "淫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "雨", "Unihan_Simplified (Chữ Giản thể)": "霪", "Unihan_Traditional (Chữ Phồn thể)": "霪", "Pinyin_Xie": "yín", "Âm Hán Việt_Xie": "dâm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ bổ nghĩa cho danh từ chỉ thời tiết mưa kéo dài nhiều ngày không dứt. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('袪', '{"9000": "6500.0", "Chữ Trung Quốc": "袪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 10 | nét | 袪 | khư | tượng hình | tay áo, cổ tay áo | 袪 cấu trúc nội bộ chưa được phân tích đầy đủ. Bộ 衣 gợi ý trang phục.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khư\": vạt áo 衣 khư khư giơ lên — 袪 là tay áo, và cũng nghĩa xua đi. | Gương Hán-Việt | khư trong 袪除 (khư trừ) — trừ khử, xua đuổi | Mở khoá kiến thức | Biết 袪 mở khoá nghĩa xua đuổi trong y học cổ 袪邪 và từ vựng trang phục cổ.", "Tự nguyên_Xie": "Tiểu triện | 袪 đọc qū, chỉ phần tay áo hoặc cổ tay áo. Bộ 衣 liên quan đến quần áo. Hiện nay 袪 còn dùng với nghĩa trừ khử, xua đuổi (袪除, 袪邪). Chưa có phân tích hình thành học rõ; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tay áo", "Hạng Tần Suất (Jun Da)": "6500.0", "Tần Suất % (Jun Da)": "99.9930838645", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 去", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤去", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "去", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "袪", "Unihan_Traditional (Chữ Phồn thể)": "袪", "Pinyin_Xie": "qū", "Âm Hán Việt_Xie": "khư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ phần ống tay áo rộng thời cổ hoặc làm động từ với nghĩa xua đuổi tà ma. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('劓', '{"9000": "6501.0", "Chữ Trung Quốc": "劓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 刀 | Số nét | 16 | nét | 鼻 | tỵ | biểu nghĩa | mũi | 刂 | đao | biểu nghĩa | dao | 劓 = 鼻 (Tỵ, biểu nghĩa: mũi) + 刂 (Đao, biểu nghĩa: dao); chữ hội ý. Dao cắt mũi — hình ảnh trực quan của hình phạt cắt mũi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nghị\": dao (刂) cắt mũi (鼻) — 劓 là hình phạt nghị tội bằng cách cắt mũi thời cổ. | Gương Hán-Việt | nghị trong hình phạt 劓刑 (nghị hình) — cắt mũi | Mở khoá kiến thức | Biết 劓 mở khoá ngũ hình cổ đại Trung Hoa và lịch sử pháp luật hình sự thời Tiên Tần.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | 劓 là chữ hội ý: 鼻 (mũi) + 刀/刂 (dao) — dao cắt mũi. Là một trong ngũ hình thời cổ đại Trung Hoa (cắt mũi). Wiktionary xác nhận cấu trúc hội ý rõ ràng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hình phạt cắt mũi", "Hạng Tần Suất (Jun Da)": "6501.0", "Tần Suất % (Jun Da)": "99.9930936835", "GavinGrover_Once (Chiết tự trực tiếp)": "鼻 + 刂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鼻刂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "刂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鼻", "Unihan_Simplified (Chữ Giản thể)": "劓", "Unihan_Traditional (Chữ Phồn thể)": "劓", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "tị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm động từ chỉ hành động cắt mũi hoặc danh từ chỉ hình phạt này trong cổ văn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('殂', '{"9000": "6502.0", "Chữ Trung Quốc": "殂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 歹 | Số nét | 9 | nét | 歹 | tồi | biểu nghĩa | xương tàn, chết chóc | 且 | thả | biểu âm | vả lại (cho âm cú) | 殂 = 歹 (Tồi, biểu nghĩa: chết chóc, xương tàn) + 且 (Thả, biểu âm); chữ hình thanh. Bộ 歹 chỉ phạm trù tử vong; 且 cho âm gần cú.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tồ\": xương tàn 歹 của người qua đời — 殂 là mất, qua đời (văn viết trang trọng). | Gương Hán-Việt | tồ trong 崩殂 (băng tồ) — vua qua đời | Mở khoá kiến thức | Biết 殂 mở khoá từ cổ văn 崩殂 — cách diễn đạt trang trọng khi vua hoặc quan lớn mất.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 殂 là chữ hình thanh: 歹 (chết chóc) biểu nghĩa, 且 biểu âm. Nghĩa là qua đời, mất. Dùng trong văn viết trang trọng hoặc văn chương. Wiktionary xác nhận cấu trúc psc rõ ràng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phách, vía", "Hạng Tần Suất (Jun Da)": "6502.0", "Tần Suất % (Jun Da)": "99.9931035024", "GavinGrover_Once (Chiết tự trực tiếp)": "歹 + 且", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰歹且", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "且", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "歹", "Unihan_Simplified (Chữ Giản thể)": "殂", "Unihan_Traditional (Chữ Phồn thể)": "殂", "Pinyin_Xie": "cú", "Âm Hán Việt_Xie": "tồ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong văn viết cổ để chỉ việc vua chúa hoặc người có địa vị qua đời. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('脞', '{"9000": "6503.0", "Chữ Trung Quốc": "脞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 11 | nét | 脞 | tỏa | tượng hình | thịt băm nhỏ; tủn mủn, vụn vặt | 脞 cấu trúc nội bộ chưa được phân tích đầy đủ. Bộ 肉 (月) gợi ý liên quan đến thịt, thân thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tỏa\": thịt (肉) tỏa nhỏ vụn — 脞 là thịt băm, việc vặt vãnh. | Gương Hán-Việt | tỏa trong 叢脞 (tùng tỏa) — vụn vặt, nhiều chuyện linh tinh | Mở khoá kiến thức | Biết 脞 mở khoá từ vựng ẩm thực 肉脞麵 và tính từ văn học 叢脞 chỉ sự tủn mủn.", "Tự nguyên_Xie": "脞 đọc cuǒ, chỉ thịt băm nhỏ, tủn mủn. Bộ 肉 liên quan đến thịt. Mở rộng nghĩa thành việc vặt, sự vụn vặt. Xuất hiện trong 肉脞麵 (bún thịt băm). Chưa có phân tích hình thành học rõ; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhỏ nhặn, tủn mủn", "Hạng Tần Suất (Jun Da)": "6503.0", "Tần Suất % (Jun Da)": "99.9931133213", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 坐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月坐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "坐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "脞", "Unihan_Traditional (Chữ Phồn thể)": "脞", "Pinyin_Xie": "cuǒ", "Âm Hán Việt_Xie": "thoả", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ bổ nghĩa cho danh từ hoặc kết hợp thành từ ghép để chỉ sự vụn vặt. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('霨', '{"9000": "6504.0", "Chữ Trung Quốc": "霨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 雨 | Số nét | 19 | nét | 霨 | vị | tượng hình | mây hiện lên, mây vần vũ | 霨 cấu trúc nội bộ không có trong dữ liệu (glyphOrigin null). Bộ 雨 gợi ý liên quan đến thời tiết, mây mưa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vị\": mây (雨) vị trí hiện lên — 霨 là mây vần vũ xuất hiện trên bầu trời. | Gương Hán-Việt | vị trong ngữ cảnh thơ ca về mây vần vũ | Mở khoá kiến thức | Biết 霨 mở khoá từ vựng thơ ca về cảnh mây trời và thiên nhiên huyền ảo.", "Tự nguyên_Xie": "霨 đọc wèi, chỉ mây hiện lên, vần vũ. Bộ 雨 liên quan đến thời tiết. Từ hiếm, chủ yếu xuất hiện trong thơ ca hoặc văn học cổ. Chưa có nguồn học thuật; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mây hiện lên", "Hạng Tần Suất (Jun Da)": "6504.0", "Tần Suất % (Jun Da)": "99.9931231402", "GavinGrover_Once (Chiết tự trực tiếp)": "雨 + 尉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱雨尉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "雨", "Unihan_Simplified (Chữ Giản thể)": "霨", "Unihan_Traditional (Chữ Phồn thể)": "霨", "Pinyin_Xie": "wèi", "Âm Hán Việt_Xie": "uý", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường dùng làm động từ hoặc tính từ trong văn thơ cổ để tả cảnh mây khói tụ lại dày đặc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('饾', '{"9000": "6505.0", "Chữ Trung Quốc": "饾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 10 | nét | 饾 | đậu | tượng hình | thức ăn bày cho đẹp; đống xếp chồng | 饾 (dạng phồn thể 餖) cấu trúc nội bộ chưa được phân tích đầy đủ. Bộ 食 gợi ý liên quan đến thức ăn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đậu\": thức ăn (食) đậu chồng lên nhau cho đẹp — 饾 là bày biện, xếp đặt hình thức. | Gương Hán-Việt | đậu trong 飣餖 — thức ăn bày trưng, chắp vá | Mở khoá kiến thức | Biết 饾 mở khoá từ 飣餖 chỉ sự bày biện hình thức hoặc văn chương chắp vá.", "Tự nguyên_Xie": "饾 (dạng cổ 餖) đọc dòu, dùng trong cụm 飣餖 — thức ăn bày ra để trưng bày, trông đẹp nhưng không ăn. Mở rộng nghĩa thành sự chắp vá, gộp lại lôn xôn. Bộ 食 liên quan đến thức ăn. Chưa có phân tích hình thành học rõ; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mâm ngũ quả", "Hạng Tần Suất (Jun Da)": "6505.0", "Tần Suất % (Jun Da)": "99.9931329591", "GavinGrover_Once (Chiết tự trực tiếp)": "饣 + 豆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰饣豆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "豆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "饣", "Unihan_Simplified (Chữ Giản thể)": "饾", "Unihan_Traditional (Chữ Phồn thể)": "餖", "Pinyin_Xie": "dòu", "Âm Hán Việt_Xie": "đậu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong văn cổ với nghĩa bày biện thức ăn hoặc sắp đặt đồ vật. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('耵', '{"9000": "6506.0", "Chữ Trung Quốc": "耵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 耳 | Số nét | 8 | nét | 耳 | nhĩ | biểu nghĩa | tai | 丁 | đinh | biểu âm | đinh (cho âm dīng) | 耵 = 耳 (Nhĩ, biểu nghĩa: tai) + 丁 (Đinh, biểu âm); chữ hình thanh. Tai 耳 chỉ phạm trù thính giác/tai; 丁 cho âm dīng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đinh\": tai (耳) có đinh bịt — 耵 trong 耵聹 là ráy tai, chất bịt ống tai. | Gương Hán-Việt | đinh trong 耵聹 (đinh ninh) — ráy tai | Mở khoá kiến thức | Biết 耵 mở khoá từ y học 耵聹 (ráy tai) trong giải phẫu tai mũi họng.", "Tự nguyên_Xie": "耵 là chữ hình thanh: 耳 (tai) biểu nghĩa, 丁 biểu âm. Dùng trong 耵聹 (耵聍) — ráy tai (cerumen). Wiktionary xác nhận cấu trúc psc rõ ràng. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: đinh ninh 耵聹,耵聍)", "Hạng Tần Suất (Jun Da)": "6506.0", "Tần Suất % (Jun Da)": "99.993142778", "GavinGrover_Once (Chiết tự trực tiếp)": "耳 + 丁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰耳丁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "耳", "Unihan_Simplified (Chữ Giản thể)": "耵", "Unihan_Traditional (Chữ Phồn thể)": "耵", "Pinyin_Xie": "dīng", "Âm Hán Việt_Xie": "đinh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường không đứng một mình mà kết hợp với chữ ninh để tạo thành danh từ chỉ ráy tai. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('泺', '{"9000": "6507.0", "Chữ Trung Quốc": "泺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 8 | nét | 泺 | lạc | tượng hình | sông Lạc ở Sơn Đông | 泺 là dạng giản hoá của 濼 (thay 樂 bằng 乐). Bộ 水 (氵) gợi ý sông nước.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lạc\": nước (氵) sông Lạc — 泺 là tên sông Lạc ở Sơn Đông. | Gương Hán-Việt | lạc trong 泺水 — sông Lạc | Mở khoá kiến thức | Biết 泺 mở khoá địa danh sông Lạc ở Sơn Đông và dạng giản thể của tên địa lý.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Tiểu triện | 泺 là dạng giản thể của 濼 — tên sông Lạc (Luo) ở tỉnh Sơn Đông. Wiktionary ghi nhận: 泺 = giản hoá 濼 (thay 樂 → 乐). Bộ 氵 chỉ sông, nước. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Lạc", "Hạng Tần Suất (Jun Da)": "6507.0", "Tần Suất % (Jun Da)": "99.993152597", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 乐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵乐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "泺", "Unihan_Traditional (Chữ Phồn thể)": "濼", "Pinyin_Xie": "luò", "Âm Hán Việt_Xie": "lạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ riêng để chỉ tên sông hoặc tên địa danh cổ ở Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('埤', '{"9000": "6508.0", "Chữ Trung Quốc": "埤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 11 | nét | 土 | thổ | biểu nghĩa | đất | 卑 | ti | biểu âm | thấp, hèn (cho âm pí) | 埤 = 土 (Thổ, biểu nghĩa: đất) + 卑 (Ti, biểu âm); chữ hình thanh. Đất 土 chỉ địa hình, đất đai; 卑 cho âm gần pí.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ti\": đất (土) thấp ti — 埤 là tường thấp bổ sung, hồ chứa nước. | Gương Hán-Việt | ti trong 埤益 (ti ích) — bổ ích, tăng thêm | Mở khoá kiến thức | Biết 埤 mở khoá địa danh Đài Loan (埤頭) và nghĩa bổ sung trong cổ văn.", "Tự nguyên_Xie": "Tiểu triện | 埤 là chữ hình thanh: 土 (đất) biểu nghĩa, 卑 biểu âm. Nghĩa là tường thấp, bức tường bổ sung; cũng nghĩa thêm vào, tăng thêm; hồ chứa nước tưới tiêu. Wiktionary xác nhận cấu trúc psc rõ ràng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phụ thêm, tăng thêm", "Hạng Tần Suất (Jun Da)": "6508.0", "Tần Suất % (Jun Da)": "99.9931624159", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 卑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土卑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "埤", "Unihan_Traditional (Chữ Phồn thể)": "埤", "Pinyin_Xie": "pí", "Âm Hán Việt_Xie": "bì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ chỉ sự thêm vào hoặc tính từ chỉ tính chất thấp bé, phụ trợ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('碁', '{"9000": "6509.0", "Chữ Trung Quốc": "碁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 13 | nét | 石 | thạch | biểu nghĩa | đá | 其 | kỳ | biểu âm | đó, kỳ (cho âm qí) | 碁 = 石 (Thạch, biểu nghĩa: đá) + 其 (Kỳ, biểu âm); chữ hình thanh. Đá 石 chỉ quân cờ bằng đá; 其 cho âm gần qí.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cờ\": đá (石) kỳ diệu — 碁 là quân cờ đá, cờ vây. | Gương Hán-Việt | cờ trong 碁盤 (cờ bàn) — bàn cờ vây | Mở khoá kiến thức | Biết 碁 mở khoá từ vựng cờ vây và văn hoá trò chơi trí tuệ Đông Á.", "Tự nguyên_Xie": "碁 là chữ hình thanh: 石 (đá) biểu nghĩa, 其 biểu âm. Chỉ cờ vây (围棋) hoặc bất kỳ trò chơi tương tự cờ. Quân cờ vây làm bằng đá. Wiktionary xác nhận cấu trúc psc rõ ràng. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cờ (chơi)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "其 + 石", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱其石", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "其", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "碁", "Unihan_Traditional (Chữ Phồn thể)": "碁", "Pinyin_Xie": "qí", "Âm Hán Việt_Xie": "kì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ các loại cờ hoặc quân cờ trong văn viết. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲐', '{"9000": "6510.0", "Chữ Trung Quốc": "鲐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 13 | nét | 鲐 | thai | tượng hình | cá thu; cá nóc; người già | 鲐 (dạng cổ 鮐) cấu trúc nội bộ chưa được phân tích đầy đủ. Bộ 魚 gợi ý loài cá.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thai\": cá (魚) thai chứng — 鲐 là cá thu và cũng ví người già lưng còng như lưng cá. | Gương Hán-Việt | thai trong 鮐背 — lưng cá thu, ám chỉ người già | Mở khoá kiến thức | Biết 鲐 mở khoá thành ngữ 黃髮鮐背 chỉ người cao tuổi trường thọ.", "Tự nguyên_Xie": "Tiểu triện | 鲐 (dạng cổ 鮐) có hai âm: tái (cá thu, người già có da nhăn như lưng cá nóc) và yí (cá nóc, pufferfish). Âm tái phổ biến hơn. Thú vị: 鮐背 (lưng cá thu) là hình ảnh ví người già có da nhăn — dùng trong 黃髮鮐背 chỉ người sống lâu. Bộ 魚 chỉ loài cá. Chưa có phân tích hình thành học rõ; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá thu", "Hạng Tần Suất (Jun Da)": "6510.0", "Tần Suất % (Jun Da)": "99.9931820537", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 台", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼台", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "台", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲐", "Unihan_Traditional (Chữ Phồn thể)": "鮐", "Pinyin_Xie": "tái", "Âm Hán Việt_Xie": "thai", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ một loài cá biển hoặc dùng ẩn dụ chỉ người già tóc đốm mồi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鷟', '{"9000": "6511.0", "Chữ Trung Quốc": "鷟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 22 | nét | 鷟 | sạt | tượng hình | tên chim thần kỳ nhạc trạc 鸑鷟 | 鷟 là chữ độc thể, dùng để chỉ loài chim thần thoại nhạc trạc (鸑鷟). Bộ 鳥 (điểu) gợi lên loài chim, nhưng cấu trúc nội bộ chưa có phân tích hình thanh rõ ràng trong nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sạt\": hình ảnh con chim thần (bộ 鳥) với âm thanh sạt sạt — nhớ đây là tên chim phụng hoàng huyền bí trong điển cố Trung Hoa. | Gương Hán-Việt | nhạc trạc 鸑鷟 — tên chim thần thoại trong thơ cổ | Mở khoá kiến thức | Biết 鷟 giúp đọc hiểu điển cố nhạc trạc (鸑鷟) — loài chim thần xuất hiện trong Thi Kinh và văn chương cổ điển.", "Tự nguyên_Xie": "Tiểu triện | Chữ 鷟 chỉ xuất hiện trong tiểu triện; Wiktionary ghi nhận đây là chữ viết tắt của 鸑鷟, tên loài chim thần thoại. Chưa có phân tích glyph cổ xưa cụ thể ngoài tiểu triện. chưa có nguồn học thuật chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: nhạc trạc 鸑鷟)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "族 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱族鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "族", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "𬸦", "Unihan_Traditional (Chữ Phồn thể)": "鷟", "Pinyin_Xie": "zhuó", "Âm Hán Việt_Xie": "trạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với chữ nhạc để làm danh từ chỉ một loài chim thần thoại giống phượng hoàng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('膬', '{"9000": "6512.0", "Chữ Trung Quốc": "膬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 16 | nét | 膬 | thôi | tượng hình | dạng cổ của 脆 (giòn) | 膬 là dạng cổ của chữ 脆 (giòn, dễ vỡ). Bộ 肉 (nhục) gợi nghĩa liên quan đến thịt, thức ăn. Cấu trúc nội bộ chưa được phân tích hình thanh chi tiết trong nguồn học thuật hiện có.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thôi\": chữ cổ của 脆 — nhớ bộ 肉 (thịt) kết hợp với ý giòn tan, dễ vỡ như thịt tươi. | Gương Hán-Việt | 脆 (thôi/túy) — giòn, dễ vỡ, được dùng trong 甘膬 (ngọt giòn) | Mở khoá kiến thức | Biết 膬 giúp hiểu từ cổ 甘膬 và mối liên hệ giữa dạng chữ cổ với 脆 trong văn bản cổ điển.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 膬 là dạng thay thế của 脆 (giòn, dễ vỡ). Bộ 肉 (nhục) chỉ liên quan đến thịt hoặc mô. Chưa có phân tích glyph cổ rõ ràng hơn. chưa có nguồn học thuật chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Tin tưởng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 毳", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月毳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "毳", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "膬", "Unihan_Traditional (Chữ Phồn thể)": "膬", "Pinyin_Xie": "cuì", "Âm Hán Việt_Xie": "thôi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ để miêu tả tính chất giòn, dễ vỡ của thức ăn hoặc đồ vật. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('粯', '{"9000": "6513.0", "Chữ Trung Quốc": "粯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 13 | nét | 粯 | hiến | tượng hình | gạo xay vỡ, tấm gạo | 粯 có bộ 米 (mễ — gạo) làm ý phù và phần còn lại có thể là âm phù, nhưng lsCodes trống, chưa xác định cấu trúc hình thanh chính thức. Chữ mang nghĩa tấm gạo, gạo nát.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hiến\": bộ 米 (gạo) kết hợp với âm — nhớ 粯 là tấm gạo, gạo vỡ vụn, thường dùng nấu cháo mịn. | Gương Hán-Việt | 粯 (hiến) — gạo xay thô, tấm gạo, ít gặp trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 粯 giúp đọc hiểu văn bản nông nghiệp cổ về các loại sản phẩm từ gạo lúa.", "Tự nguyên_Xie": "Wiktionary ghi 粯 với phát âm xiàn nhưng thiếu định nghĩa chi tiết (rfdef). Bộ 米 (gạo) gợi nghĩa liên quan lúa gạo. Chưa có phân tích glyph cổ chi tiết. chưa có nguồn học thuật chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tấm; gạo nát", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 見", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米見", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "見", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "粯", "Unihan_Traditional (Chữ Phồn thể)": "粯", "Pinyin_Xie": "xiàn", "Âm Hán Việt_Xie": "hiến", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ để chỉ gạo nát hoặc tấm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('陴', '{"9000": "6514.0", "Chữ Trung Quốc": "陴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 10 | nét | 陴 | tỳ | tượng hình | bức tường thấp trên mặt thành | 陴 có bộ 阜 (phụ — gò đất, tường lũy) làm ý phù. Phần còn lại có thể là âm phù (pí), tuy lsCodes trống. Chữ chỉ bức tường thấp (lan can) xây trên đỉnh tường thành để che chắn cho người canh gác.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tỳ\": bộ 阜 (tường, gò) kết hợp với âm phù — 陴 là bức tường thấp trên đỉnh thành, người lính ẩn sau để canh gác. | Gương Hán-Việt | 陴 (tỳ) — ít gặp trong tiếng Việt hiện đại; xuất hiện trong 登陴 (lên tường thành canh gác) | Mở khoá kiến thức | Biết 陴 giúp đọc hiểu văn bản chiến tranh cổ điển khi miêu tả phòng thủ thành trì.", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | Wiktionary ghi 陴 nghĩa là parapet (bức tường thấp trên mặt thành). Bộ 阜 (gò đất, tường lũy) là ý phù. Không có phân tích glyph cổ chi tiết hơn trong nguồn học thuật hiện có. Giáp cốt văn và tiểu triện có hình chữ này tại hanziyuan. chưa có nguồn học thuật chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bức tường thấp trên mặt thành", "Hạng Tần Suất (Jun Da)": "6514.0", "Tần Suất % (Jun Da)": "99.9932600883", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + 卑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝卑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "陴", "Unihan_Traditional (Chữ Phồn thể)": "陴", "Pinyin_Xie": "pí", "Âm Hán Việt_Xie": "bài", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ bức tường thấp có lỗ châu mai trên thành lũy cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('橼', '{"9000": "6515.0", "Chữ Trung Quốc": "橼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 16 | nét | 橼 | duyên | tượng hình | cây citrus, chanh vàng | 橼 có bộ 木 (mộc — cây) làm ý phù, gợi đây là tên một loại cây. Phần còn lại có thể là âm phù (yuán), tuy lsCodes trống. Chữ dùng chủ yếu trong tên ghép 枸橼 (cẩu duyên — cây chanh vàng, citron).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"duyên\": bộ 木 (cây) + âm duyên — 橼 là tên cây chanh vàng (枸橼), loại citrus có vỏ dày đặc biệt trong y học cổ truyền. | Gương Hán-Việt | 橼 (duyên) — chỉ gặp trong 枸橼 (cẩu duyên), ít dùng độc lập | Mở khoá kiến thức | Biết 橼 giúp đọc tên dược liệu cổ: 枸橼 (citron), 香橼 (hương duyên — citrus medica) trong đông y.", "Tự nguyên_Xie": "Wiktionary dùng dạng phồn thể 櫞, ghi là không có định nghĩa chi tiết (rfdef). Chữ xuất hiện chủ yếu trong hợp từ 枸橼 (枸櫞) là tên cây citron (chanh vàng). Bộ 木 chỉ đây là tên cây. chưa có nguồn học thuật chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: cẩu duyên 枸櫞,枸橼)", "Hạng Tần Suất (Jun Da)": "6515.0", "Tần Suất % (Jun Da)": "99.9932693904", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 缘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木缘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "缘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "橼", "Unihan_Traditional (Chữ Phồn thể)": "櫞", "Pinyin_Xie": "yuán", "Âm Hán Việt_Xie": "duyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong từ ghép để chỉ một loại cây thuộc chi Cam chanh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('驩', '{"9000": "6516.0", "Chữ Trung Quốc": "驩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 27 | nét | 馬 | mã | biểu nghĩa | ngựa | 雚 | quán | biểu âm | âm phù | 驩 là chữ hình thanh (psc): 馬 (mã — ngựa, biểu nghĩa) + 雚 (quán, biểu âm). Chữ chỉ ngựa lành, ngựa thuần thục; cũng dùng nghĩa vui mừng (thông với 歡).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoan\": 馬 (ngựa) + 雚 (âm hoan) — 驩 là ngựa vui, ngựa lành; âm ''hoan'' gần với 歡 (vui mừng), giúp nhớ cả hai nghĩa. | Gương Hán-Việt | 驩 (hoan) — ít dùng độc lập; liên hệ với 歡 (hoan) trong 歡迎 (hoan nghênh), 歡樂 (hoan lạc) | Mở khoá kiến thức | Biết 驩 giúp nhận ra mối liên hệ giữa 馬 (ngựa tốt) và 歡 (vui), thấy trong tên người và văn học cổ.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary: 驩 = 馬 (ngựa, biểu nghĩa) + 雚 (biểu âm), chữ hình thanh. Bộ 馬 chỉ loài ngựa. 雚 cho âm. Chữ mang nghĩa ''ngựa thuần'' và chuyển nghĩa sang ''vui mừng'' (thông với 歡/欢). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngựa ngoan, ngựa lành", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "馬 + 雚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰馬雚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "雚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "驩", "Unihan_Traditional (Chữ Phồn thể)": "驩", "Pinyin_Xie": "huān", "Âm Hán Việt_Xie": "hoan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ ngựa tốt hoặc tính từ biểu thị sự vui mừng trong văn ngôn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('唣', '{"9000": "6517.0", "Chữ Trung Quốc": "唣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 10 | nét | 唣 | táo | tượng hình | cãi nhau, nói huyên náo | 唣 có bộ 口 (khẩu — miệng) làm ý phù, gợi nghĩa liên quan đến lời nói, tiếng ồn ào. Cấu trúc nội bộ chưa được phân tích chính thức; không có Wiktionary anchor. Chữ mang nghĩa cãi nhau, nói chuyện huyên náo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"táo\": bộ 口 (miệng) kết hợp với âm táo — 唣 là tiếng cãi nhau, huyên náo; âm ''táo'' gợi 躁 (táo — nóng vội, bốc đồng) — miệng nóng vội là cãi nhau. | Gương Hán-Việt | 唣 (táo) — ít gặp trong tiếng Việt hiện đại; liên hệ với 躁 (táo nộ — nóng giận) | Mở khoá kiến thức | Biết 唣 giúp nhận ra nghĩa cãi cọ, ồn ào trong một số phương ngữ và văn bản thông tục Trung Hoa.", "Tự nguyên_Xie": "Không có nguồn Wiktionary cho 唣. Bộ 口 (miệng) gợi liên quan đến lời nói hoặc tiếng động. Chữ mang nghĩa cãi nhau, huyên náo. chưa có nguồn học thuật chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cãi nhau", "Hạng Tần Suất (Jun Da)": "6517.0", "Tần Suất % (Jun Da)": "99.9932879947", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 皂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口皂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "皂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "唣", "Unihan_Traditional (Chữ Phồn thể)": "唕", "Pinyin_Xie": "zào", "Âm Hán Việt_Xie": "tạo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường kết hợp thành từ ghép để làm tính từ chỉ sự phiền toái hoặc ồn ào. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蜩', '{"9000": "6518.0", "Chữ Trung Quốc": "蜩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 14 | nét | 蜩 | điêu | tượng hình | con ve sầu | 蜩 có bộ 虫 (trùng — côn trùng) làm ý phù. Phần còn lại có thể là âm phù (tiáo), tuy lsCodes trống. Chữ cổ chỉ con ve sầu (cicada), xuất hiện trong Trang Tử và Kinh Thi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điêu\": bộ 虫 (sâu/côn trùng) + âm điêu — 蜩 là ve sầu, nổi tiếng trong Trang Tử: 蜩與學鳩 (ve sầu và chim cánh cụt cùng cười chim bằng bay cao). | Gương Hán-Việt | 蜩 (điêu) — ít dùng hiện đại; gặp trong văn học cổ, nhất là Trang Tử 莊子 | Mở khoá kiến thức | Biết 蜩 giúp đọc hiểu Trang Tử và thơ ca cổ điển Trung Hoa khi nhắc đến mùa hè và tiếng ve.", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | Lục thư thông | Wiktionary ghi 蜩 nghĩa là cicada (ve sầu), được đánh dấu là cổ ngữ (archaic). Giáp cốt văn và tiểu triện có hình chữ này. Bộ 虫 (côn trùng) là ý phù. Chữ nổi tiếng qua câu Trang Tử: 蜩與學鳩笑之 (Ve sầu và chim cánh cụt cười nó). chưa có nguồn học thuật phân tích glyph chi tiết hơn. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con ve sầu", "Hạng Tần Suất (Jun Da)": "6518.0", "Tần Suất % (Jun Da)": "99.9932972968", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 周", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫周", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "周", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蜩", "Unihan_Traditional (Chữ Phồn thể)": "蜩", "Pinyin_Xie": "tiáo", "Âm Hán Việt_Xie": "điêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ con ve sầu trong văn học cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('埯', '{"9000": "6519.0", "Chữ Trung Quốc": "埯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 11 | nét | 埯 | ám | tượng hình | lỗ nhỏ để tra hạt giống | 埯 có bộ 土 (thổ — đất) làm ý phù, gợi nghĩa liên quan đến đất đai, canh tác. Phần còn lại có thể là âm phù (ǎn), tuy lsCodes trống. Chữ mang nghĩa chuyên biệt: lỗ nhỏ để tra hạt giống và đơn vị đếm khóm/cụm cây.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ám\": bộ 土 (đất) + âm ám — 埯 là lỗ nhỏ trong đất để tra hạt; nhớ như người nông dân đào lỗ âm thầm gieo hạt. | Gương Hán-Việt | 埯 (ám) — ít dùng trong tiếng Việt; liên hệ với hoạt động nông nghiệp truyền thống | Mở khoá kiến thức | Biết 埯 giúp đọc văn bản nông nghiệp cổ và phương ngữ Quảng Đông khi miêu tả cách gieo trồng theo lỗ.", "Tự nguyên_Xie": "Wiktionary ghi 埯 có nghĩa: lỗ để tra hạt, hành động tra hạt vào lỗ, và danh từ đơn vị đếm cây trồng bằng cách tra hạt. Bộ 土 (đất) là ý phù. Không có phân tích glyph cổ chi tiết hơn. chưa có nguồn học thuật chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đào lỗ để tra hạt; lỗ để tra hạt; khóm, cụm", "Hạng Tần Suất (Jun Da)": "6519.0", "Tần Suất % (Jun Da)": "99.9933065989", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 奄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土奄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "埯", "Unihan_Traditional (Chữ Phồn thể)": "埯", "Pinyin_Xie": "ǎn", "Âm Hán Việt_Xie": "am", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Lượng từ | 量词 | Thường dùng làm động từ chỉ việc đào hố gieo hạt hoặc làm lượng từ cho khóm cây. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蓥', '{"9000": "6520.0", "Chữ Trung Quốc": "蓥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 13 | nét | 金 | kim | biểu âm | âm phù (kim loại) | 蓥 là chữ hình thanh (psc): 𤇾 (biểu âm theo Wiktionary dạng 鎣) + 金 (kim — kim loại, biểu nghĩa). Nghĩa gốc là mài bóng, đánh bóng kim loại. Dạng thảo 蓥 thêm bộ 艸 bên trên, nhưng nghĩa vẫn là đánh bóng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huỳnh\": 金 (kim loại) + âm huỳnh — 蓥 là mài bóng kim loại cho sáng; nhớ: 金 sáng bóng như ánh 光 — dùng trong tên địa danh 華蓥 nổi tiếng ở Tứ Xuyên. | Gương Hán-Việt | 蓥 (huỳnh) — gặp chủ yếu trong địa danh 華蓥山 (Huà Yíng Shān — núi Hoa Huỳnh ở Tứ Xuyên) | Mở khoá kiến thức | Biết 蓥 giúp đọc địa danh 華蓥 và hiểu nghĩa mài bóng trong văn bản cổ về thủ công nghiệp.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Wiktionary (dạng 鎣): 𤇾 (biểu âm) + 金 (kim loại, biểu nghĩa), chữ hình thanh. Nghĩa: mài bóng, đánh bóng kim loại. Chữ 蓥 là biến thể có thêm bộ 艸. Kim văn và tiểu triện đã có dạng chữ này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mài cho sáng bóng", "Hạng Tần Suất (Jun Da)": "6520.0", "Tần Suất % (Jun Da)": "99.9933159011", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "蓥", "Unihan_Traditional (Chữ Phồn thể)": "鎣", "Pinyin_Xie": "yíng", "Âm Hán Việt_Xie": "oánh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chủ yếu dùng làm động từ chỉ việc mài giũa vũ khí hoặc đồ kim loại cho sáng bóng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('袝', '{"9000": "6521.0", "Chữ Trung Quốc": "袝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 10 | nét | 袝 | phụ | tượng hình | hành lễ hợp thờ (phụ tế) | 袝 có bộ 衣 (y — áo, lễ phục) làm ý phù. Phần còn lại có thể là âm phù (fù), tuy lsCodes trống. Chữ mang nghĩa nghi lễ: hợp thờ thần vị mới vào miếu tổ tiên sau tang lễ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phụ\": bộ 衣 (lễ phục) + âm phụ — 袝 là nghi lễ phụ tế, đặt bài vị người mới mất vào miếu tổ tiên; nhớ ''phụ'' như ''phụ vào'' — ghép vào miếu thờ. | Gương Hán-Việt | 袝 (phụ) — từ lễ nghi cổ, ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 袝 giúp đọc văn bản lễ nghi và văn chương Nho giáo về việc thờ cúng tổ tiên.", "Tự nguyên_Xie": "Wiktionary ghi 袝 với phát âm fù nhưng không có định nghĩa chi tiết (rfdef). Bộ 衣 (lễ phục, áo) gợi liên quan đến nghi lễ. Theo ngữ cảnh cổ điển, 袝 là nghi thức đặt bài vị người mới mất vào miếu thờ cùng tổ tiên. chưa có nguồn học thuật chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Nhân dân tệ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 付", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤付", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "付", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "袝", "Unihan_Traditional (Chữ Phồn thể)": "袝", "Pinyin_Xie": "fù", "Âm Hán Việt_Xie": "phụ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường dùng làm động từ trong văn cúng tế cổ để chỉ việc cúng hợp tế. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谞', '{"9000": "6522.0", "Chữ Trung Quốc": "谞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 11 | nét | 谞 | tư | tượng hình | mưu trí, sự khôn ngoan | 谞 (phồn thể: 諝) có bộ 言 (ngôn — lời nói) làm ý phù. Phần còn lại có thể là âm phù (xū), tuy lsCodes trống. Chữ mang nghĩa: sự khôn ngoan, mưu mẹo, tri thức sâu xa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tư\": bộ 言 (lời nói) + âm tư — 谞 là lời nói khôn ngoan, mưu trí; nhớ: lời 言 của người tư duy sâu sắc. | Gương Hán-Việt | 谞 (tư) — ít dùng độc lập; gặp trong 才諝 (tài tư — tài năng trí tuệ), 智諝 (trí tư — trí khôn) | Mở khoá kiến thức | Biết 谞 giúp đọc văn bản cổ điển khi ca ngợi mưu lược và tài trí của người quân tử.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary (dạng 諝) ghi nghĩa là khôn ngoan, mưu mẹo, nhưng không có phân tích glyph chi tiết. Bộ 言 (lời nói) gợi nghĩa liên quan đến lời nói thông minh, mưu lược. Xuất hiện trong thành ngữ 謀無遺諝 (mưu lược không sót điểm nào). chưa có nguồn học thuật chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khôn ngoan; mưu mẹo", "Hạng Tần Suất (Jun Da)": "6522.0", "Tần Suất % (Jun Da)": "99.9933345053", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 胥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠胥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "胥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "谞", "Unihan_Traditional (Chữ Phồn thể)": "諝", "Pinyin_Xie": "xū", "Âm Hán Việt_Xie": "tư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này thường dùng làm danh từ để chỉ tài năng hoặc mưu lược trong văn ngôn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('馘', '{"9000": "6523.0", "Chữ Trung Quốc": "馘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 首 | Số nét | 17 | nét | 首 | thủ | biểu nghĩa | đầu người | 或 | hoặc | biểu âm | âm phù | 馘 là chữ hình thanh (psc): 首 (thủ — đầu người, biểu nghĩa) + 或 (hoặc, biểu âm). Nghĩa gốc: cắt tai trái của kẻ thù đã chết để làm chiến công. Sau chỉ việc chém đầu quân thù.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quắc\": 首 (đầu) + 或 (âm hoặc/quắc) — 馘 là chặt tai kẻ thù làm chiến tích; âm ''quắc'' gợi hành động dứt khoát trong chiến trận. | Gương Hán-Việt | 馘 (quắc) — ít dùng hiện đại; xuất hiện trong văn học chiến tranh cổ đại | Mở khoá kiến thức | Biết 馘 giúp hiểu tục lệ kiểm tính chiến công trong quân sự thời Thương, Chu và văn học sử thi cổ đại.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary: 馘 = 首 (đầu, biểu nghĩa) + 或 (biểu âm), chữ hình thanh. Chữ này phần lớn thay thế cho 聝 trong văn bản kinh điển cổ. Nghĩa: cắt tai trái kẻ thù đã giết để làm bằng chứng chiến công — tục lệ trong chiến tranh thời cổ Trung Hoa. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tai đã cắt ra", "Hạng Tần Suất (Jun Da)": "6523.0", "Tần Suất % (Jun Da)": "99.9933438075", "GavinGrover_Once (Chiết tự trực tiếp)": "首 + 或", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰首或", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "或", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "首", "Unihan_Simplified (Chữ Giản thể)": "馘", "Unihan_Traditional (Chữ Phồn thể)": "馘", "Pinyin_Xie": "guó", "Âm Hán Việt_Xie": "quắc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này dùng làm động từ trong văn cổ để chỉ hành động cắt tai quân địch làm chiến tích. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谫', '{"9000": "6524.0", "Chữ Trung Quốc": "谫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 13 | nét | 谫 | tiễn | tượng hình | nông cạn, hẹp hòi về học thức | 谫 (phồn thể: 譾) có bộ 言 (ngôn — lời nói) làm ý phù. Phần còn lại có thể là âm phù (jiǎn), tuy lsCodes trống. Chữ mang nghĩa: nông cạn, hẹp hòi, thiếu sâu sắc về học thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiễn\": bộ 言 (lời nói) + âm tiễn — 谫 là lời nói nông cạn, học thức hẹp hòi; nhớ: 言 mà tiễn cụt = nói chuyện thiếu chiều sâu. | Gương Hán-Việt | 谫 (tiễn) — ít dùng hiện đại; gặp trong 譾陋 (tiễn lậu — nông cạn hèn kém), tự mô tả khiêm tốn | Mở khoá kiến thức | Biết 谫 giúp đọc các lời tự khiêm trong thư từ cổ đại khi tác giả tự nhận ''học thức nông cạn''.", "Tự nguyên_Xie": "Wiktionary (dạng 譾) ghi nghĩa: nông nổi, hẹp hòi (shallow, superficial) — từ văn học (literary). Bộ 言 (lời nói) gợi nghĩa lời lẽ nông cạn. Không có phân tích glyph cổ chi tiết hơn. chưa có nguồn học thuật chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nông nổi; hẹp hòi", "Hạng Tần Suất (Jun Da)": "6524.0", "Tần Suất % (Jun Da)": "99.9933531096", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 剪", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠剪", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "剪", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "谫", "Unihan_Traditional (Chữ Phồn thể)": "謭", "Pinyin_Xie": "jiǎn", "Âm Hán Việt_Xie": "tiễn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ thường kết hợp với các từ chỉ tài năng hoặc tri thức để tự khiêm. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('輶', '{"9000": "6525.0", "Chữ Trung Quốc": "輶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 16 | nét | 輶 | du | tượng hình | xe nhẹ, tầm thường | 輶 có bộ 車 (xa — xe) làm ý phù, gợi nghĩa liên quan đến phương tiện. Phần còn lại có thể là âm phù (yóu), tuy lsCodes trống. Chữ mang nghĩa: xe nhẹ, xe nhanh và chuyển nghĩa sang ''nhẹ, tầm thường''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"du\": bộ 車 (xe) + âm du — 輶 là xe nhẹ, nhỏ; nhớ ''du'' như ''du lịch'' nhẹ nhàng, không cồng kềnh. | Gương Hán-Việt | 輶 (du) — ít dùng hiện đại; gặp trong 輶軒 (du hiên — xe nhẹ của quan sứ giả) | Mở khoá kiến thức | Biết 輶 giúp đọc văn bản lịch sử về phương tiện đi lại và quan chế thời cổ đại Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary ghi 輶 có hai nghĩa: xe nhẹ (light carriage — lịch sử) và nhẹ, tầm thường (literary). Bộ 車 (xe) là ý phù. Không có phân tích glyph cổ chi tiết hơn. Tiểu triện và lục thư thông đã có dạng chữ này. chưa có nguồn học thuật chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái xe nhẹ; nhẹ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "車 + 酋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰車酋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "酋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "車", "Unihan_Simplified (Chữ Giản thể)": "𬨎", "Unihan_Traditional (Chữ Phồn thể)": "輶", "Pinyin_Xie": "yóu", "Âm Hán Việt_Xie": "du", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này dùng làm danh từ chỉ loại xe nhẹ thời xưa hoặc làm tính từ chỉ sự nhẹ nhàng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('廑', '{"9000": "6526.0", "Chữ Trung Quốc": "廑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 广 | Số nét | 14 | nét | 廑 | cần | tượng hình | cái nhà nhỏ, hẹp; chỉ có, vừa đủ | 廑 có bộ 广 (nghiễm — mái nhà, công trình) làm ý phù. Phần còn lại có thể là âm phù (jǐn), tuy lsCodes trống. Chữ mang hai nghĩa: một ngôi nhà nhỏ/lều và ''chỉ có'' (phó từ hạn định).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cần\": bộ 广 (mái nhà) + âm cần — 廑 là lều nhỏ cần cù; nhớ: căn nhà cần (廑) — nhỏ bé, vừa đủ sống. | Gương Hán-Việt | 廑 (cần) — ít dùng hiện đại; gặp trong văn bản cổ chỉ sự khiêm tốn về nơi ở | Mở khoá kiến thức | Biết 廑 giúp đọc văn bản cổ về nhà ở khiêm nhường và dùng nghĩa ''chỉ có, vừa đủ'' trong thư từ Nho gia.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary ghi 廑 với phát âm jǐn/qín nhưng không có định nghĩa chi tiết (rfdef). Bộ 广 (mái nhà) gợi nghĩa nơi trú ngụ nhỏ. Tiểu triện và lục thư thông có dạng chữ này. chưa có nguồn học thuật chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái nhà nhỏ; chỉ có", "Hạng Tần Suất (Jun Da)": "6526.0", "Tần Suất % (Jun Da)": "99.9933717139", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "廑", "Unihan_Traditional (Chữ Phồn thể)": "廑", "Pinyin_Xie": "jǐn", "Âm Hán Việt_Xie": "cần", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Phó từ | 副词 | Tính từ | 形容词 | Chữ này thường dùng làm phó từ với nghĩa là chỉ hoặc vừa vặn trong văn viết cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瘐', '{"9000": "6527.0", "Chữ Trung Quốc": "瘐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 13 | nét | 瘐 | dũ | tượng hình | chết trong tù vì đói rét, đối xử tàn nhẫn | 瘐 có bộ 疒 (nạch — bệnh, ốm đau) làm ý phù, gợi nghĩa liên quan đến bệnh tật hoặc khốn khổ thể xác. Không có Wiktionary anchor. Chữ mang nghĩa: chết trong tù vì đói rét, hoặc đối xử tàn nhẫn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dũ\": bộ 疒 (bệnh, khổ sở) + âm dũ — 瘐 là chết lịm trong tù đói rét; nhớ ''dũ'' như kiệt sức héo tàn dần. | Gương Hán-Việt | 瘐 (dũ) — ít dùng trong tiếng Việt hiện đại; xuất hiện trong văn bản hình luật cổ đại | Mở khoá kiến thức | Biết 瘐 giúp đọc văn bản pháp luật và lịch sử hình phạt thời cổ Trung Hoa.", "Tự nguyên_Xie": "Không có nguồn Wiktionary cho 瘐. Bộ 疒 (bệnh) là ý phù, gợi khổ sở về thể xác. Nghĩa ''chết trong tù vì đói rét'' gắn với bối cảnh hình phạt tàn nhẫn thời cổ. chưa có nguồn học thuật chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "héo chết, đói chết", "Hạng Tần Suất (Jun Da)": "6527.0", "Tần Suất % (Jun Da)": "99.993381016", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 臾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒臾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "臾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "瘐", "Unihan_Traditional (Chữ Phồn thể)": "瘐", "Pinyin_Xie": "yǔ", "Âm Hán Việt_Xie": "dũ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này dùng làm động từ để chỉ việc tù nhân bị bệnh hoặc đói rét mà chết trong tù. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('躐', '{"9000": "6528.0", "Chữ Trung Quốc": "躐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 22 | nét | 躐 | láp | tượng hình | xéo lên, giẫm lên, vượt qua | 躐 có bộ 足 (túc — chân) làm ý phù, gợi nghĩa liên quan đến bước chân, di chuyển. Phần còn lại chưa được phân tích rõ ràng (lsCodes trống). Wiktionary chỉ ghi {{Han etym}} mà không cung cấp phân tích chi tiết. Chữ mang nghĩa bước vượt qua, giẫm lên trên.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"láp\": bộ 足 (chân) kết hợp với âm láp — 躐 là giẫm lên, xéo qua; ''láp'' gợi tiếng bước chân nặng nề đạp lên vật gì. | Gương Hán-Việt | 躐 (láp) — ít dùng trong tiếng Việt hiện đại; gặp trong 躐等 (láp đẳng — vượt cấp, bỏ qua thứ tự) | Mở khoá kiến thức | Biết 躐 giúp đọc văn bản lễ nghi và giáo dục cổ đại: 躐等 là thuật ngữ Nho học cảnh báo việc vượt cấp không đúng thứ tự.", "Tự nguyên_Xie": "Wiktionary chỉ ghi {{Han etym}} mà không có phân tích cụ thể. Bộ 足 (chân) là ý phù. Nghĩa ''xéo lên, vượt qua'' gắn với hành động dùng chân bước qua hoặc giẫm lên. chưa có nguồn học thuật chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xéo, giẫm lên; vượt qua; cầm, giữ", "Hạng Tần Suất (Jun Da)": "6528.0", "Tần Suất % (Jun Da)": "99.9933903181", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 巤", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊巤", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "躐", "Unihan_Traditional (Chữ Phồn thể)": "躐", "Pinyin_Xie": "liè", "Âm Hán Việt_Xie": "liệp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này dùng làm động từ để chỉ hành động vượt cấp hoặc giẫm đạp lên quy tắc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('黟', '{"9000": "6529.0", "Chữ Trung Quốc": "黟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 黑 | Số nét | 18 | nét | 黟 | y | tượng hình | gỗ đen, đen bóng | 黟 có bộ 黑 (hắc — đen) làm ý phù, gợi màu tối đậm. Phần còn lại có thể là âm phù (yī), tuy lsCodes trống. Chữ mang nghĩa gỗ đen bóng, đen tuyền — cũng dùng làm địa danh (huyện Hắc Châu, An Huy).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"y\": bộ 黑 (đen) + âm y — 黟 là đen bóng như gỗ mun; nhớ địa danh 黟縣 (huyện Y) ở An Huy, nơi có làng cổ Hongcun nổi tiếng. | Gương Hán-Việt | 黟 (y) — chủ yếu gặp trong 黟縣 (Y huyện), tên huyện ở An Huy, Trung Quốc | Mở khoá kiến thức | Biết 黟 giúp nhận ra địa danh 黟縣 trong An Huy — nơi nổi tiếng với kiến trúc Huy Phái và làng cổ di sản UNESCO.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 黟 với phát âm yī nhưng thiếu định nghĩa chi tiết (rfdef). Bộ 黑 (đen) là ý phù. Nghĩa gỗ đen bóng hoặc màu đen sáng. Tiểu triện có dạng chữ này. chưa có nguồn học thuật chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gỗ đen", "Hạng Tần Suất (Jun Da)": "6529.0", "Tần Suất % (Jun Da)": "99.9933996203", "GavinGrover_Once (Chiết tự trực tiếp)": "黑 + 多", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰黑多", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "多", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "黑", "Unihan_Simplified (Chữ Giản thể)": "黟", "Unihan_Traditional (Chữ Phồn thể)": "黟", "Pinyin_Xie": "yī", "Âm Hán Việt_Xie": "y", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này dùng làm tính từ để tả sắc đen của gỗ hoặc đá. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('膯', '{"9000": "6530.0", "Chữ Trung Quốc": "膯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 16 | nét | 膯 | đằng | tượng hình | không rõ nghĩa | 膯 có bộ 肉 (nhục — thịt) làm ý phù. Phần còn lại có thể là âm phù (tēng), tuy lsCodes trống. Wiktionary ghi thiếu định nghĩa (rfdef). Nghĩa trong các từ điển ghi là ''误'' (sai) gợi ý đây có thể là dạng chữ nhầm hoặc ít được ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đằng\": bộ 肉 (thịt) + âm đằng — 膯 là chữ hiếm, ít xác nhận nghĩa rõ ràng; nhớ bộ 肉 nếu gặp trong văn bản cổ. | Gương Hán-Việt | 膯 (đằng) — cực kỳ hiếm, không dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 膯 giúp nhận ra đây là chữ hiếm có bộ 肉; tránh nhầm với các chữ thông dụng cùng âm.", "Tự nguyên_Xie": "Wiktionary ghi 膯 với phát âm tēng nhưng thiếu định nghĩa chi tiết (rfdef). Bộ 肉 (thịt) là ý phù. Dữ liệu MongoDB ghi nghĩa là ''误'' (nhầm lẫn), gợi ý chữ này hiếm và ít được xác nhận. chưa có nguồn học thuật chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "误", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 登", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月登", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "登", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "膯", "Unihan_Traditional (Chữ Phồn thể)": "膯", "Pinyin_Xie": "tēng", "Âm Hán Việt_Xie": "đằng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này dùng làm động từ trong văn cổ để chỉ hành động trợn mắt nhìn hoặc trạng thái nhầm lẫn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('藭', '{"9000": "6531.0", "Chữ Trung Quốc": "藭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 18 | nét | 藭 | cùng | tượng hình | cây khung cùng, loại thảo dược | 藭 có bộ 艸 (thảo — cỏ/thực vật) làm ý phù, gợi đây là tên thực vật. Phần còn lại có thể là âm phù (qióng), tuy lsCodes trống. Chữ dùng chủ yếu trong tên dược liệu 芎藭 (khung cùng — Ligusticum chuanxiong).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cùng\": bộ 艸 (cỏ) + âm cùng — 藭 là tên cây dược liệu trong 芎藭 (khung cùng); nhớ: cây cỏ (艸) tên ''cùng'' — một vị thuốc Đông y. | Gương Hán-Việt | 藭 (cùng) — chỉ dùng trong dược danh 芎藭 (khung cùng), ít độc lập | Mở khoá kiến thức | Biết 藭 giúp đọc toa thuốc và văn bản Đông y khi nhắc đến 芎藭 (Ligusticum) — vị thuốc trị đau đầu, huyết hư.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 藭 với phát âm qióng nhưng thiếu định nghĩa chi tiết (rfdef). Bộ 艸 (cỏ) gợi đây là tên thực vật. Chữ xuất hiện trong dược danh 芎藭 — loại thảo dược nổi tiếng trong đông y Trung Hoa. chưa có nguồn học thuật chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: khung cùng 芎藭)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 窮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹窮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "窮", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "䓖", "Unihan_Traditional (Chữ Phồn thể)": "藭", "Pinyin_Xie": "qióng", "Âm Hán Việt_Xie": "cùng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này hầu như chỉ dùng làm danh từ trong tên vị thuốc đông y khung cùng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('禆', '{"9000": "6532.0", "Chữ Trung Quốc": "禆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 12 | nét | 禆 | tỳ | tượng hình | phụ tế, thứ thần; áo tế lễ | 禆 có bộ 示 (thị — thần linh, lễ tế) làm ý phù, gợi nghĩa liên quan đến nghi lễ tôn giáo. Phần còn lại có thể là âm phù (bēi/pí), tuy lsCodes trống và không có Wiktionary anchor. Chữ mang nghĩa thứ thần (phụ thần), áo tế lễ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tỳ\": bộ 示 (thần linh, lễ tế) + âm tỳ — 禆 là thứ thần, vị thần phụ trong hệ thống tế tự; nhớ: 示 (tế lễ) thứ yếu = thần phụ. | Gương Hán-Việt | 禆 (tỳ) — ít dùng trong tiếng Việt hiện đại; xuất hiện trong văn bản tế tự và chức quan cổ đại | Mở khoá kiến thức | Biết 禆 giúp đọc văn bản lễ nghi và hành chính cổ đại Trung Hoa liên quan đến tế tự và quan chức phụ.", "Tự nguyên_Xie": "Không có nguồn Wiktionary cho 禆. Bộ 示 (lễ tế, thần linh) là ý phù. Nghĩa ''phụ tế, thứ thần'' gợi đây là chức vị hoặc lễ tế phụ bên cạnh nghi lễ chính. chưa có nguồn học thuật chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "禆", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 卑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻卑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "禆", "Unihan_Traditional (Chữ Phồn thể)": "禆", "Pinyin_Xie": "bēi", "Âm Hán Việt_Xie": "tỳ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này thường dùng làm động từ với nghĩa giúp đỡ, bổ trợ hoặc tính từ chỉ sự nhỏ bé, phụ trợ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('稓', '{"9000": "6533.0", "Chữ Trung Quốc": "稓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 13 | nét | 稓 | tộc | tượng hình | chữ hiếm không rõ nghĩa | 稓 có bộ 禾 (hòa — lúa) làm ý phù, gợi liên quan đến lúa gạo, ngũ cốc. Phần còn lại có thể là âm phù (zuó), tuy không có Wiktionary anchor và lsCodes trống. Nghĩa chưa được xác định rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tộc\": bộ 禾 (lúa) kết hợp với âm tộc — 稓 là chữ hiếm liên quan ngũ cốc; nhớ bộ 禾 nếu gặp trong văn bản nông nghiệp cổ đại. | Gương Hán-Việt | 稓 (tộc) — cực kỳ hiếm, không dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 稓 giúp nhận ra bộ 禾 trong các chữ liên quan lúa gạo và nông nghiệp cổ đại.", "Tự nguyên_Xie": "Không có nguồn Wiktionary cho 稓. Bộ 禾 (lúa, ngũ cốc) là ý phù. Nghĩa chưa được ghi nhận đầy đủ trong từ điển học thuật hiện đại. chưa có nguồn học thuật chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "稓", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 昔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾昔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "稓", "Unihan_Traditional (Chữ Phồn thể)": "稓", "Pinyin_Xie": "zuó", "Âm Hán Việt_Xie": "tộc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này là từ cổ, dùng làm danh từ chỉ lúa cấy dày hoặc động từ chỉ việc gặt lúa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('縠', '{"9000": "6534.0", "Chữ Trung Quốc": "縠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 16 | nét | 縠 | hộc | tượng hình | vải sa trun, lụa mỏng nhăn | 縠 có bộ 糸 (mịch — tơ sợi) làm ý phù, gợi đây là tên loại vải dệt. Phần còn lại có thể là âm phù (hú), tuy lsCodes trống. Chữ mang nghĩa: loại vải sa hoặc lụa nhăn nhỏ (crepe).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hộc\": bộ 糸 (tơ sợi) + âm hộc — 縠 là vải sa trun, loại lụa mỏng có bề mặt nhăn nhỏ; nhớ: tơ (糸) dệt nhăn như ''hộc''. | Gương Hán-Việt | 縠 (hộc) — ít dùng trong tiếng Việt hiện đại; xuất hiện trong văn bản thời trang và dệt may cổ đại | Mở khoá kiến thức | Biết 縠 giúp đọc văn bản thủ công nghiệp và thời trang cổ đại khi mô tả các loại vải dệt quý.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary ghi 縠 với phát âm hú nhưng thiếu định nghĩa chi tiết (rfdef). Bộ 糸 (tơ) gợi đây là loại vải dệt từ tơ. Tiểu triện và lục thư thông có dạng chữ này. chưa có nguồn học thuật chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vải sa trun", "Hạng Tần Suất (Jun Da)": "6534.0", "Tần Suất % (Jun Da)": "99.9935200312", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "縠", "Unihan_Traditional (Chữ Phồn thể)": "縠", "Pinyin_Xie": "hú", "Âm Hán Việt_Xie": "hộc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại vải tơ lụa mỏng và nhăn thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('揠', '{"9000": "6535.0", "Chữ Trung Quốc": "揠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 12 | nét | 手 | thủ | biểu nghĩa | tay | 匽 | yến | biểu âm | âm phù | 揠 là chữ hình thanh (psc): 手 (thủ — tay, biểu nghĩa) + 匽 (yến, biểu âm). Tay nhổ vật gì lên — hình ảnh trực tiếp của động tác nhổ, kéo lên.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"yển\": 手 (tay) + 匽 (âm yển/yà) — 揠 là nhổ lên bằng tay; nhớ thành ngữ 揠苗助長: nhổ mầm lên cho nhanh lớn — kết quả là cây chết. | Gương Hán-Việt | 揠 (yển) — chủ yếu gặp trong thành ngữ 揠苗助長 (yển miêu trợ trưởng — nóng vội phản tác dụng) | Mở khoá kiến thức | Biết 揠 giúp hiểu và dùng thành ngữ 揠苗助長 — phê phán thái độ nóng vội muốn đẩy nhanh kết quả.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary: 揠 = 手 (tay, biểu nghĩa) + 匽 (biểu âm), chữ hình thanh. Nghĩa: nhổ lên, kéo lên, đề bạt. Nổi tiếng qua thành ngữ 揠苗助長 (nhổ mầm giúp lớn — nóng vội phản tác dụng). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhổ lên", "Hạng Tần Suất (Jun Da)": "6535.0", "Tần Suất % (Jun Da)": "99.9935288165", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 匽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌匽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "揠", "Unihan_Traditional (Chữ Phồn thể)": "揠", "Pinyin_Xie": "yà", "Âm Hán Việt_Xie": "yết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động nhổ cây cối lên, thường gặp trong thành ngữ yển miêu trợ trưởng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('绐', '{"9000": "6536.0", "Chữ Trung Quốc": "绐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 8 | nét | 绐 | đãi | tượng hình | lừa dối, lừa lọc | 绐 (phồn thể: 紿) có bộ 糸 (mịch — tơ sợi) làm ý phù. Phần còn lại có thể là âm phù (dài), tuy lsCodes trống. Bộ 糸 có thể gợi ''dây trói'' hay ''mạng lưới'' để bẫy người. Chữ mang nghĩa: lừa dối, đánh lừa, gian lận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đãi\": bộ 糸 (tơ, mạng lưới) + âm đãi — 绐 là lừa đảo như mạng tơ giăng bẫy; nhớ: ''đãi'' như đãi ngộ nhưng thực ra là bẫy. | Gương Hán-Việt | 绐 (đãi) — ít dùng trong tiếng Việt hiện đại; xuất hiện trong 欺紿 (lừa dối), 受紿 (bị lừa) | Mở khoá kiến thức | Biết 绐 giúp đọc văn học cổ khi miêu tả hành vi gian dối, phản trắc.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary (dạng 紿): nghĩa là lừa dối (to cheat, to deceive), từ văn học cổ. Bộ 糸 (tơ sợi) là ý phù. Tiểu triện và lục thư thông có dạng chữ này. chưa có nguồn học thuật phân tích glyph chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lừa dối", "Hạng Tần Suất (Jun Da)": "6536.0", "Tần Suất % (Jun Da)": "99.9935376019", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 台", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟台", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "台", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "绐", "Unihan_Traditional (Chữ Phồn thể)": "紿", "Pinyin_Xie": "dài", "Âm Hán Việt_Xie": "đãi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành vi lừa gạt, dối trá trong văn ngôn cổ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鸰', '{"9000": "6537.0", "Chữ Trung Quốc": "鸰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 10 | nét | 鸰 | linh | tượng hình | chim tích linh, loại chim nhỏ | 鸰 (phồn thể: 鴒) có bộ 鳥 (điểu — chim) làm ý phù. Phần còn lại có thể là âm phù (líng), tuy lsCodes trống. Chữ chủ yếu dùng trong tên chim 鶺鴒/鹡鸰 (tích linh — loài chim wagtail).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"linh\": bộ 鳥 (chim) + âm linh — 鸰 là chim tích linh; nhớ thành ngữ 鶺鴒在原: chim tích linh trên đồng — biểu tượng tình anh em trong Kinh Thi. | Gương Hán-Việt | 鸰 (linh) — chủ yếu gặp trong 鶺鴒/鹡鸰 (tích linh) và thành ngữ 鴒原 | Mở khoá kiến thức | Biết 鸰 giúp hiểu điển cố 鴒原 — biểu tượng tình anh em tương trợ trong thơ ca cổ điển Trung Hoa.", "Tự nguyên_Xie": "Wiktionary (dạng 鴒): nghĩa là loài chim thuộc họ Motacilla (lark/wagtail). Bộ 鳥 (chim) là ý phù. Chữ nổi tiếng qua thành ngữ 鶺鴒在原 (tích linh tại nguyên) trong Kinh Thi, ý nói anh em tương trợ nhau. chưa có nguồn học thuật phân tích glyph chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: tích linh 鶺鴒,鹡鸰)", "Hạng Tần Suất (Jun Da)": "6537.0", "Tần Suất % (Jun Da)": "99.9935463872", "GavinGrover_Once (Chiết tự trực tiếp)": "令 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰令鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "令", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鸰", "Unihan_Traditional (Chữ Phồn thể)": "鴒", "Pinyin_Xie": "líng", "Âm Hán Việt_Xie": "linh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường xuất hiện trong các từ ghép để chỉ tên một loài chim nhỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('搛', '{"9000": "6538.0", "Chữ Trung Quốc": "搛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 13 | nét | 搛 | gom | tượng hình | gắp thức ăn bằng đũa | 搛 có bộ 手 (thủ — tay) làm ý phù, gợi hành động của tay. Phần còn lại có thể là âm phù (jiān), tuy lsCodes trống và Wiktionary chỉ ghi {{Han etym}} mà không có phân tích chi tiết. Chữ mang nghĩa: gắp thức ăn bằng đũa hoặc ngón tay.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"gom\": bộ 手 (tay) + âm gom — 搛 là gắp thức ăn; nhớ: tay (手) ''gom'' thức ăn vào đũa, như ''gắp'' trong tiếng Việt. | Gương Hán-Việt | 搛 (gom) — ít dùng trong tiếng Việt hiện đại; nghĩa gắp đũa rất cụ thể và chuyên biệt | Mở khoá kiến thức | Biết 搛 giúp đọc văn bản ẩm thực và phong tục ăn uống Trung Hoa cổ đại khi miêu tả cách dùng đũa.", "Tự nguyên_Xie": "Wiktionary chỉ ghi {{Han etym}} không có phân tích cụ thể. Bộ 手 (tay) là ý phù, gợi hành động cầm nắm. Nghĩa gắp thức ăn bằng đũa là nghĩa chính. chưa có nguồn học thuật chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gắp thức ăn", "Hạng Tần Suất (Jun Da)": "6538.0", "Tần Suất % (Jun Da)": "99.9935551726", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 兼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌兼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "搛", "Unihan_Traditional (Chữ Phồn thể)": "搛", "Pinyin_Xie": "jiān", "Âm Hán Việt_Xie": "kiêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ vị ngữ trong câu để diễn tả hành động gắp thức ăn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('黹', '{"9000": "6539.0", "Chữ Trung Quốc": "黹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 黹 | Số nét | 12 | nét | 黹 | chỉ | tượng hình | hình trang trí thêu trên vải, biểu tượng hình mây | 黹 là chữ tượng hình độc thể, không phân tích thành bộ phận nhỏ hơn. Theo Wiktionary, nó có thể mô tả hoa văn trang trí dạng mây dùng trên đồ đồng và áo vải. Chữ tượng hình, tự thân là bộ thủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chỉ\": hình mây uốn lượn trên tấm vải thêu — 黹 là bộ thủ của nghề kim chỉ, may vá, thêu thùa. | Gương Hán-Việt | kim chỉ (針黹 — nghề thêu thùa, may vá) | Mở khoá kiến thức | Biết 黹 mở khoá: 針黹 (châm chỉ — nghề thêu), 黼黻 (phủ phất — hoa văn lễ phục cổ).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Tiểu triện | Theo Wiktionary, 黹 là chữ tượng hình (象形), có thể biểu thị một loại hoa văn trang trí giống hình mây dùng trên đồ đồng và trang phục. Không liên quan đến 敝 dù hình dạng tương tự. Chữ dùng làm bộ thủ cho các chữ liên quan đến thêu thùa. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "may áo", "Hạng Tần Suất (Jun Da)": "6539.0", "Tần Suất % (Jun Da)": "99.9935639579", "GavinGrover_Once (Chiết tự trực tiếp)": "业 + 㡀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱业㡀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㡀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "业", "Unihan_Simplified (Chữ Giản thể)": "黹", "Unihan_Traditional (Chữ Phồn thể)": "黹", "Pinyin_Xie": "zhǐ", "Âm Hán Việt_Xie": "chỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Dùng làm danh từ chỉ công việc may vá hoặc động từ chỉ hành động khâu thêu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('恧', '{"9000": "6540.0", "Chữ Trung Quốc": "恧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 10 | nét | 而 | nhi | biểu âm | và, mà (cho âm) | 心 | tâm | biểu nghĩa | tâm hồn, trái tim | 恧 = 而 (Nhi, biểu âm) + 心 (Tâm, biểu nghĩa: tâm hồn). Chữ hình thanh — 心 cho nghĩa cảm xúc bên trong, 而 cho âm đọc gần với nǜ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nục\" (dạng cổ): 心 (tâm) chứa nỗi xấu hổ — khi lòng (心) tự trách mình mà (而) không nói được, đó là 恧. | Gương Hán-Việt | tàm nục (慚恧 — xấu hổ, hổ thẹn trong văn ngôn) | Mở khoá kiến thức | Biết 恧 mở khoá nhóm chữ văn ngôn chỉ sự hổ thẹn: 慚恧, 愧恧 — dùng trong thơ văn cổ.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 恧 là chữ hình thanh (形聲): 心 biểu nghĩa (tâm hồn, cảm xúc), 而 biểu âm. Chữ cổ dùng để chỉ trạng thái xấu hổ, bẽ mặt. Hiện rất ít dùng, chủ yếu xuất hiện trong văn ngôn cổ điển. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hổ thẹn", "Hạng Tần Suất (Jun Da)": "6540.0", "Tần Suất % (Jun Da)": "99.9935727433", "GavinGrover_Once (Chiết tự trực tiếp)": "而 + 心", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱而心", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "心", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "而", "Unihan_Simplified (Chữ Giản thể)": "恧", "Unihan_Traditional (Chữ Phồn thể)": "恧", "Pinyin_Xie": "nǜ", "Âm Hán Việt_Xie": "nục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng trong văn viết cổ để biểu thị trạng thái tâm lý xấu hổ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('粎', '{"9000": "6541.0", "Chữ Trung Quốc": "粎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 10 | nét | 米 | mễ | biểu âm | gạo (cho âm mǐ → chǐ) | 尺 | xích | biểu nghĩa | thước đo, đơn vị đo lường | 粎 = 米 (Mễ, biểu âm) + 尺 (Xích, biểu nghĩa: đơn vị đo). Chữ hình thanh — 尺 cho nghĩa đo lường, 米 cho âm (mǐ → chǐ). Đây là chữ tạo muộn để phiên âm \"mét\" (metre) trong tiếng Trung hiện đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mễ\" (dạng biến): 尺 (xích — thước đo) + 米 (mễ — gạo/mét) → chữ đặc biệt phiên âm đơn vị \"mét\" trong đo lường. | Gương Hán-Việt | mét (粎 — biến thể chữ 米 dùng cho đơn vị đo lường) | Mở khoá kiến thức | Biết 粎 giúp nhận ra các chữ ghép đơn vị đo lường tiếng Trung hiện đại dựa trên 米 và 尺.", "Tự nguyên_Xie": "Theo Wiktionary, 粎 là chữ hình thanh tạo muộn, dùng như dạng thay thế của 米 (mét). Cấu trúc: 米 biểu âm (mǐ gần với chǐ), 尺 biểu nghĩa (đơn vị đo lường). Chữ tạo muộn để biểu thị đơn vị đo lường mét, chưa thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "玎", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 尺", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米尺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "粎", "Unihan_Traditional (Chữ Phồn thể)": "粎", "Pinyin_Xie": "chǐ", "Âm Hán Việt_Xie": "mễ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Lượng từ | 量词 | Dùng làm lượng từ đo lường chiều dài trong một số tài liệu kỹ thuật cũ. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('柒', '{"9000": "6542.0", "Chữ Trung Quốc": "柒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 9 | nét | 柒 | thất | tượng hình | số bảy dạng viết chính thức, phòng chống sửa chữa trong văn bản tài chính | 柒 là dạng chữ chính thức (大写) của số 七 (bảy), dùng trong văn bản tài chính, pháp lý để tránh giả mạo. Cấu trúc gốc liên quan đến 七 (thất) và bộ 木 (mộc), nhưng chức năng chính là ký tự số học chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thất\": số 七 (bảy) mặc áo gỗ (木) — 柒 là bản \"trang trọng\" của 七 dùng trong hợp đồng, hóa đơn để không ai sửa thành số khác. | Gương Hán-Việt | thất (柒 — bảy trong văn bản tài chính, pháp lý) | Mở khoá kiến thức | Biết 柒 giúp đọc hiểu văn bản tài chính Trung Quốc: 壹貳參肆伍陸柒捌玖拾 (1-10 dạng chính thức).", "Tự nguyên_Xie": "Theo nguồn Wiktionary chỉ ghi {{Han etym}} mà không có giải thích chi tiết. 柒 là dạng chính thức (财务大写) của 七 (bảy), tương tự như 壹贰叁肆伍陆柒捌玖拾. Chữ tạo muộn phục vụ mục đích hành chính, chưa có ghi chép giáp cốt rõ ràng riêng biệt. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "7, bảy (như: 七, dùng viết trong văn tự)", "Hạng Tần Suất (Jun Da)": "6542.0", "Tần Suất % (Jun Da)": "99.993590314", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 木", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱木", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "柒", "Unihan_Traditional (Chữ Phồn thể)": "柒", "Pinyin_Xie": "qī", "Âm Hán Việt_Xie": "thất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Số từ | 数词 | Dùng làm số từ trong các văn bản tài chính để tránh việc tẩy xóa và gian lận. | Số từ | 数词 | Chỉ số lượng hoặc thứ tự. Hầu như không đứng thẳng trước danh từ mà phải chèn lượng từ ở giữa: 两个人.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('裒', '{"9000": "6543.0", "Chữ Trung Quốc": "裒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 12 | nét | 裒 | bâu | tượng hình | tụ tập, thu gom; áo rộng tay | 裒 là chữ độc thể, không có cấu trúc hình thanh rõ ràng trong dữ liệu hiện có. Nghĩa gốc là tụ lại, gom lại, hoặc chỉ kiểu áo rộng tay cổ. Chữ tự thân mang nghĩa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bâu\": hình ảnh vạt áo rộng (裒) dùng để gom nhặt, thu góp — như người vén vạt áo hứng lấy tất cả. | Gương Hán-Việt | bâu tập (裒集 — thu thập, biên soạn trong văn ngôn) | Mở khoá kiến thức | Biết 裒 mở khoá: 裒集 (bâu tập — thu thập), 裒多益寡 (san sẻ từ nhiều bù cho ít — thành ngữ cổ).", "Tự nguyên_Xie": "Lục thư thông | Không có glyph origin chi tiết từ Wiktionary cho 裒. Dựa vào cấu trúc chữ, 裒 có liên quan đến áo vải (bộ 衣 biến thể) và ý nghĩa tụ họp, thu thập. Chưa có nguồn học thuật chi tiết cho chữ này. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tụ lại", "Hạng Tần Suất (Jun Da)": "6543.0", "Tần Suất % (Jun Da)": "99.9935990993", "GavinGrover_Once (Chiết tự trực tiếp)": "衣 + 臼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴衣臼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "臼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衣", "Unihan_Simplified (Chữ Giản thể)": "裒", "Unihan_Traditional (Chữ Phồn thể)": "裒", "Pinyin_Xie": "póu", "Âm Hán Việt_Xie": "bầu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong văn ngôn để chỉ việc thu gom hoặc bớt chỗ thừa bù chỗ thiếu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('栳', '{"9000": "6544.0", "Chữ Trung Quốc": "栳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 10 | nét | 栳 | lão | tượng hình | chiếc giỏ đan tròn bằng liễu gai hoặc tre | 栳 là chữ độc thể. Theo Wiktionary, chữ chỉ dùng trong từ 栲栳 (cái giỏ đáy tròn làm từ liễu gai hoặc nan tre). Cấu trúc có thể liên quan bộ 木 (mộc — gỗ/cây) nhưng không có phân tích hình thanh rõ ràng trong dữ liệu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lão\": cái giỏ (栳) của người già (lão) — 栳 là chiếc giỏ tròn đan bằng liễu gai, hình ảnh quen thuộc ở nông thôn Trung Hoa xưa. | Gương Hán-Việt | lão (栳 — dùng trong 栲栳, chỉ đồ vật thủ công) | Mở khoá kiến thức | Biết 栳 giúp nhận ra 栲栳 (cái giỏ tròn đan liễu) — từ chỉ dụng cụ thủ công trong văn học dân gian Trung Quốc.", "Tự nguyên_Xie": "Theo Wiktionary, 栳 chỉ xuất hiện trong từ 栲栳, chỉ một loại dụng cụ đựng đáy tròn làm từ liễu hoặc nan tre. Chữ tạo muộn, chưa có ghi chép giáp cốt hay kim văn riêng biệt cho chữ này. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái giỏ", "Hạng Tần Suất (Jun Da)": "6544.0", "Tần Suất % (Jun Da)": "99.9936078847", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 老", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木老", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "老", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "栳", "Unihan_Traditional (Chữ Phồn thể)": "栳", "Pinyin_Xie": "lǎo", "Âm Hán Việt_Xie": "lão", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường đi kèm với chữ khảo để tạo thành từ ghép chỉ cái giỏ tre đựng đồ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钸', '{"9000": "6545.0", "Chữ Trung Quốc": "钸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 10 | nét | 金 | kim | biểu nghĩa | kim loại | 布 | bố | biểu âm | vải, bố (cho âm bù) | 钸 = 金 (Kim, biểu nghĩa: kim loại) + 布 (Bố, biểu âm: cho âm bù). Chữ hình thanh — 金 xác định loại vật liệu (kim loại), 布 cho âm đọc. Đây là chữ dùng để phiên âm tên nguyên tố hóa học Plutonium (Pu).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bố\" (biến thể kim loại): 金 (kim — kim loại) + 布 (bố — vải, âm Bù) → 钸 là ký hiệu phiên âm nguyên tố Plutonium, kim loại phóng xạ nặng nhất. | Gương Hán-Việt | bố (钸 — tên nguyên tố Plutonium trong hóa học Trung Quốc) | Mở khoá kiến thức | Biết 钸 giúp nhận ra hệ thống phiên âm nguyên tố hóa học tiếng Trung: các chữ bộ 金 + âm phiên.", "Tự nguyên_Xie": "Theo Wiktionary, 钸 là chữ hình thanh: 金 (kim — kim loại) biểu nghĩa, 布 (bố) biểu âm. Chữ tạo hiện đại để phiên âm tên nguyên tố Plutonium (Pu, nguyên tử số 94) trong bảng tuần hoàn tiếng Trung. Chưa thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tấm kim loại", "Hạng Tần Suất (Jun Da)": "6545.0", "Tần Suất % (Jun Da)": "99.99361667", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 布", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅布", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "布", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钸", "Unihan_Traditional (Chữ Phồn thể)": "鈽", "Pinyin_Xie": "bù", "Âm Hán Việt_Xie": "bố", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chuyên ngành hóa học để chỉ nguyên tố phóng xạ Plutonium. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('饸', '{"9000": "6546.0", "Chữ Trung Quốc": "饸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 9 | nét | 饸 | hạp | tượng hình | phần trong từ ghép 饸饹, chỉ loại mì sợi ép | 饸 là chữ chỉ dùng trong từ 饸饹 (hé le) — một loại mì sợi ép từ bột mì hoặc kiều mạch đặc trưng ở miền Bắc Trung Quốc. Không có cấu trúc hình thanh được ghi nhận riêng lẻ trong dữ liệu hiện có.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hạp\": 饸饹 là mì ép — chữ 饸 luôn đi đôi với 饹, như hai nửa sợi mì không thể tách rời. | Gương Hán-Việt | hạp lạc (饸饹 — loại mì sợi ép đặc sản miền Bắc Trung Quốc) | Mở khoá kiến thức | Biết 饸 giúp nhận ra từ 饸饹 trong thực đơn và văn hóa ẩm thực Thiểm Tây, Sơn Tây.", "Tự nguyên_Xie": "Theo Wiktionary, 饸 chỉ xuất hiện trong từ 饸饹 (餄餎). Chữ tạo muộn phục vụ từ vựng ẩm thực dân gian miền Bắc Trung Quốc. Chưa có nguồn học thuật chi tiết về cấu trúc từ nguyên. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: hợp lạc 餄餄,饸饹)", "Hạng Tần Suất (Jun Da)": "6546.0", "Tần Suất % (Jun Da)": "99.9936254554", "GavinGrover_Once (Chiết tự trực tiếp)": "饣 + 合", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰饣合", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "合", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "饣", "Unihan_Simplified (Chữ Giản thể)": "饸", "Unihan_Traditional (Chữ Phồn thể)": "餄", "Pinyin_Xie": "hé", "Âm Hán Việt_Xie": "hợp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với chữ lạc để chỉ món mì truyền thống ở miền bắc Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('譞', '{"9000": "6547.0", "Chữ Trung Quốc": "譞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 20 | nét | 言 | ngôn | biểu nghĩa | lời nói | 睘 | biểu âm | (cho âm xuān) | 譞 = 言 (Ngôn, biểu nghĩa: lời nói) + 睘 (biểu âm, không có Hán-Việt phổ biến). Chữ hình thanh — 言 xác định nghĩa liên quan đến ngôn ngữ/trí tuệ, 睘 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huyên\": 言 (ngôn — lời) + 睘 (âm xuān) → người nói lời thông minh, sáng suốt — 譞 là chữ cổ khen tài biện luận. | Gương Hán-Việt | huyên (譞 — thông minh, sáng suốt trong văn ngôn cổ) | Mở khoá kiến thức | Biết 譞 mở khoá nhóm chữ 言-bộ chỉ phẩm chất ngôn ngữ và trí tuệ trong văn ngôn cổ điển.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 譞 là chữ hình thanh (形聲): 言 (ngôn — lời nói) biểu nghĩa, 睘 biểu âm. Nghĩa cổ là thông minh, sáng suốt. Chữ hiếm dùng, chủ yếu xuất hiện trong văn ngôn. Có ghi nhận trong tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "螞", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 睘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言睘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "睘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "𫍽", "Unihan_Traditional (Chữ Phồn thể)": "譞", "Pinyin_Xie": "xuān", "Âm Hán Việt_Xie": "huyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ trong văn cổ để miêu tả sự thông minh hoặc hoạt ngôn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铕', '{"9000": "6548.0", "Chữ Trung Quốc": "铕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 11 | nét | 铕 | âu | tượng hình | nguyên tố Europium, ký hiệu Eu | 铕 là chữ tạo hiện đại để phiên âm tên nguyên tố Europium (Eu, số nguyên tử 63). Bộ 金 (kim loại) kết hợp phần biểu âm cho âm yǒu. Chữ tạo muộn phục vụ hóa danh pháp, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"âu\": 铕 là kim loại (金) mang tên châu Âu (Eu-rope) — Europium, nguyên tố đất hiếm dùng trong màn hình và đèn huỳnh quang. | Gương Hán-Việt | âu (铕 — tên nguyên tố Europium trong hóa học) | Mở khoá kiến thức | Biết 铕 giúp nhận ra hệ thống đặt tên nguyên tố đất hiếm tiếng Trung, toàn bộ dùng bộ 金.", "Tự nguyên_Xie": "铕 là chữ hình thanh tạo hiện đại: bộ 金 (kim — kim loại) biểu nghĩa, phần còn lại biểu âm. Dùng để phiên âm tên nguyên tố Europium (Eu) trong bảng tuần hoàn tiếng Trung. Chưa có nguồn gốc học thuật cổ điển. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố Europi, Eu", "Hạng Tần Suất (Jun Da)": "6548.0", "Tần Suất % (Jun Da)": "99.9936518114", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 有", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅有", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "有", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铕", "Unihan_Traditional (Chữ Phồn thể)": "銪", "Pinyin_Xie": "yǒu", "Âm Hán Việt_Xie": "hữu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ nguyên tố kim loại đất hiếm Europi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('絷', '{"9000": "6549.0", "Chữ Trung Quốc": "絷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 12 | nét | 執 | chấp | biểu âm | nắm giữ (cho âm zhí) | 糸 | mịch | biểu nghĩa | sợi tơ, dây buộc | 絷 = 執 (Chấp, biểu âm: cho âm zhí) + 糸 (Mịch, biểu nghĩa: sợi dây, dây thừng). Chữ hình thanh — 糸 xác định nghĩa liên quan đến dây buộc/trói, 執 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chấp\": 糸 (dây tơ) + 執 (chấp — nắm giữ) → dây tơ nắm chặt — 絷 là trói buộc, giam cầm. | Gương Hán-Việt | chấp phược (絷縛 — trói buộc trong văn ngôn cổ) | Mở khoá kiến thức | Biết 絷 mở khoá nhóm chữ văn ngôn chỉ sự giam cầm, trói buộc: 絷縛, 絷馬 (buộc ngựa).", "Tự nguyên_Xie": "Theo Wiktionary, 絷 là chữ hình thanh (形聲): 糸 (mịch — sợi tơ, dây) biểu nghĩa, 執 (chấp) biểu âm. Nghĩa gốc là trói buộc, giam cầm bằng dây. Dùng trong văn ngôn cổ để chỉ việc bắt giữ, xiềng xích. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "buộc, trói, cùm lại", "Hạng Tần Suất (Jun Da)": "6549.0", "Tần Suất % (Jun Da)": "99.9936605968", "GavinGrover_Once (Chiết tự trực tiếp)": "执 + 糸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱执糸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "执", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糸", "Unihan_Simplified (Chữ Giản thể)": "絷", "Unihan_Traditional (Chữ Phồn thể)": "縶", "Pinyin_Xie": "zhí", "Âm Hán Việt_Xie": "trập", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong văn ngôn để chỉ hành động trói buộc hoặc giam giữ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蒨', '{"9000": "6550.0", "Chữ Trung Quốc": "蒨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 13 | nét | 蒨 | thiến | tượng hình | cây cỏ xanh tươi tốt; cây điều đỏ (madder) | 蒨 là chữ độc thể, không có phân tích hình thanh rõ trong dữ liệu. Theo Wiktionary, chữ dùng như dạng thay thế của 茜 (cây điều, màu đỏ sẫm) và có nghĩa độc lập là xanh tốt, um tùm. Bộ 艹 (thảo) gợi liên hệ đến cây cỏ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiến\": 蒨 gợi màu xanh rực rỡ của đồng cỏ — như cánh đồng tràn đầy cỏ xanh mướt (艹 — thảo) sau mưa. | Gương Hán-Việt | thiến (蒨 — xanh tươi tốt, um tùm trong thơ văn cổ) | Mở khoá kiến thức | Biết 蒨 giúp đọc hiểu thơ văn cổ miêu tả thiên nhiên tươi tốt: 蒨蒨 (um tùm), 蔥蒨 (xanh mướt).", "Tự nguyên_Xie": "Theo Wiktionary, 蒨 là dạng thay thế của 茜 (màu đỏ madder) và có nghĩa văn học là cây cỏ um tùm, xanh tươi. Xuất hiện trong văn học cổ qua các từ như 妍蒨, 蒨蒨, 峭蒨. Chưa có phân tích từ nguyên chi tiết trong dữ liệu hiện có. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tươi tốt; màu đỏ", "Hạng Tần Suất (Jun Da)": "6550.0", "Tần Suất % (Jun Da)": "99.9936693821", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 倩", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹倩", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "倩", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蒨", "Unihan_Traditional (Chữ Phồn thể)": "蒨", "Pinyin_Xie": "qiàn", "Âm Hán Việt_Xie": "thiến", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ miêu tả cây cối xanh tươi hoặc màu sắc đỏ thắm. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蓣', '{"9000": "6551.0", "Chữ Trung Quốc": "蓣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 13 | nét | 蓣 | dự | tượng hình | củ khoai mài (yam), chỉ dùng trong từ 薯蕷 | 蓣 là chữ chỉ xuất hiện trong từ 薯蕷 (shǔyù — củ khoai mài). Bộ 艹 (thảo) gợi liên hệ đến thực vật. Không có phân tích hình thanh chi tiết trong dữ liệu hiện có.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dự\": 蓣 là nửa sau của 薯蕷 — tên khoa học của củ khoai mài, loại củ bổ dưỡng quen thuộc trong Đông y. | Gương Hán-Việt | thự dự (薯蕷 — củ khoai mài, hoài sơn trong Đông y) | Mở khoá kiến thức | Biết 蓣 giúp nhận ra tên vị thuốc Đông y: 山藥/薯蕷 (hoài sơn — củ mài) dùng bổ tỳ thận.", "Tự nguyên_Xie": "Theo Wiktionary, 蓣 chỉ dùng trong từ 薯蕷 (củ khoai mài, yam). Chữ tạo để đặt tên thực vật, thuộc nhóm chữ nông nghiệp/bản thảo. Chưa có phân tích từ nguyên chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: thự dự 薯蕷,薯蕷)", "Hạng Tần Suất (Jun Da)": "6551.0", "Tần Suất % (Jun Da)": "99.9936781674", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 预", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹预", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "预", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蓣", "Unihan_Traditional (Chữ Phồn thể)": "蕷", "Pinyin_Xie": "yù", "Âm Hán Việt_Xie": "dự", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong các từ ghép chỉ các loại củ thuộc họ củ mài. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('迻', '{"9000": "6552.0", "Chữ Trung Quốc": "迻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 9 | nét | 迻 | đi | tượng hình | di chuyển, dịch chuyển (dạng cổ của 移) | 迻 là dị thể cổ của 移 (di chuyển). Theo Wiktionary, chữ này chỉ đơn thuần là biến thể chữ viết của 移, không có cấu trúc riêng biệt được phân tích. Có bộ 辶 (sước — di chuyển).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đi\": 迻 là dạng cổ của chữ 移 (di) — bộ 辶 (sước) gợi hành trình di chuyển, và âm Hán-Việt \"đi\" như lời nhắc nhớ động tác bước chân. | Gương Hán-Việt | đi (迻 — di chuyển, dạng cổ của 移 trong văn ngôn) | Mở khoá kiến thức | Biết 迻 giúp đọc các bản thảo cổ dùng dị thể chữ, nhận ra 迻 = 移 khi gặp trong văn bản trước thế kỷ 20.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 迻 là dạng dị thể của 移 (di chuyển, chuyển dịch). Có chữ tiểu triện. Nghĩa và cách dùng đồng nhất với 移 trong văn bản cổ. Chữ tạo muộn hơn so với 移. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "di chuyển", "Hạng Tần Suất (Jun Da)": "6552.0", "Tần Suất % (Jun Da)": "99.9936869528", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 多", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶多", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "多", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "迻", "Unihan_Traditional (Chữ Phồn thể)": "迻", "Pinyin_Xie": "yí", "Âm Hán Việt_Xie": "di", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ trong văn cổ chỉ sự dịch chuyển vị trí hoặc thay đổi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('釆', '{"9000": "6553.0", "Chữ Trung Quốc": "釆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 釆 | Số nét | 7 | nét | 釆 | biện | tượng hình | móng vuốt thú vật xòe ra; bộ thủ liên quan đến phân biệt | 釆 là chữ tượng hình độc thể. Theo Wiktionary, có hai giải thích: (1) hình móng/bàn chân thú với các ngón xòe ra, liên quan đến chữ 蹯; (2) hình cái cày gỗ (力) và hạt giống, gợi ý nghĩa gieo trồng, lan rộng, liên quan đến 播. Chữ dùng làm bộ thủ Khang Hy số 165.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"biện\": 釆 là dấu chân thú xòe ra — mỗi ngón một hướng, như việc phân biệt (biện) các sự vật riêng biệt. | Gương Hán-Việt | biện biệt (釆 — phân biệt, là bộ thủ Khang Hy số 165) | Mở khoá kiến thức | Biết 釆 giúp nhận ra bộ thủ trong từ điển Khang Hy và một số chữ cổ liên quan đến phân biệt, gieo trồng.", "Tự nguyên_Xie": "Kim văn | Đại triện | Tiểu triện | Theo Wiktionary, 釆 là chữ tượng hình (象形). Theo Thuyết Văn Giải Tự, đây là hình bàn chân thú với các ngón xòe ra, liên quan đến 蹯 (bàn chân thú). Theo Zhang Shichao, là hình cái cày và hạt giống, gợi ý gieo trồng và lan rộng, liên quan đến 播. Có chữ kim văn, đại triện và tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "918.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Phiệt (004) Mễ (453)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Nét phẩy (số 004) ở trên bộ Mễ (số 453 - hạt gạo). Là hình vết chân của thú hoang dã. Tùy từng loại thú mà để lại dấu vết khác nhau, qua đó phân biệt được chúng. Giải thích sự chuyển ý: Đây là chữ Hội ý. Biện là phân biệt.", "Nghĩa Tiếng Việt_Xie": "phân biệt", "Hạng Tần Suất (Jun Da)": "6553.0", "Tần Suất % (Jun Da)": "99.9936957381", "GavinGrover_Once (Chiết tự trực tiếp)": "㇒ + 米", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱㇒米", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㇒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "釆", "Unihan_Traditional (Chữ Phồn thể)": "釆", "Pinyin_Xie": "biàn", "Âm Hán Việt_Xie": "biện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ cổ chỉ hành động phân biệt hoặc nhận biết sự vật. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲕', '{"9000": "6554.0", "Chữ Trung Quốc": "鲕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 14 | nét | 鲕 | nhi | tượng hình | trứng cá, cá con mới nở | 鲕 là chữ độc thể trong dữ liệu hiện có. Bộ 鱼 (ngư — cá) gợi liên hệ đến nghĩa liên quan đến cá. Nghĩa gốc là trứng cá (roe) hoặc cá con. Không có phân tích hình thanh chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhi\": 鲕 là \"con nhi\" của cá — trứng cá và cá bột mới nở, nhỏ bé như trẻ sơ sinh (nhi) trong lòng nước. | Gương Hán-Việt | nhi (鲕 — trứng cá, cá bột trong văn ngôn ngư nghiệp) | Mở khoá kiến thức | Biết 鲕 giúp đọc hiểu văn ngôn về ngư nghiệp và bản thảo sinh học cổ Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 鲕 nghĩa là trứng cá hoặc cá bột (cá con mới nở). Có chữ tiểu triện. Xuất hiện trong từ 鯤鮞 (cá con nhỏ). Chưa có phân tích từ nguyên chi tiết trong dữ liệu hiện có. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá giống; một loại cá có thịt ngon", "Hạng Tần Suất (Jun Da)": "6554.0", "Tần Suất % (Jun Da)": "99.9937045235", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 而", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼而", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "而", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲕", "Unihan_Traditional (Chữ Phồn thể)": "鮞", "Pinyin_Xie": "ér", "Âm Hán Việt_Xie": "nhi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ trứng cá hoặc các loại cá nhỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鍏', '{"9000": "6555.0", "Chữ Trung Quốc": "鍏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 17 | nét | 釒 | kim | biểu nghĩa | kim loại (biến thể bộ 金 khi đứng bên trái) | 韋 | vi | biểu âm | da thuộc (cho âm wéi) | 鍏 = 釒 (Kim, biểu nghĩa: kim loại) + 韋 (Vi, biểu âm: cho âm wéi). Chữ hình thanh — 釒 xác định đây là dụng cụ kim loại, 韋 cho âm đọc. Nghĩa là cái cuốc, cái xẻng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vi\": 釒 (kim loại) + 韋 (vi — da thuộc) → cán da bọc lưỡi sắt — 鍏 là cái thuổng, công cụ đào đất bằng kim loại của người xưa. | Gương Hán-Việt | vi (鍏 — cuốc, xẻng trong từ điển cổ) | Mở khoá kiến thức | Biết 鍏 giúp nhận ra nhóm nông cụ kim loại trong từ điển cổ điển và văn bản nông nghiệp xưa.", "Tự nguyên_Xie": "Theo Wiktionary, 鍏 là chữ hình thanh (形聲): 釒 (kim — kim loại) biểu nghĩa, 韋 (vi) biểu âm. Nghĩa là cuốc, xẻng. Chữ hiếm dùng trong tiếng Trung hiện đại, chủ yếu gặp trong từ điển cổ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thuổng", "Hạng Tần Suất (Jun Da)": "6555.0", "Tần Suất % (Jun Da)": "99.9937220942", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 韋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金韋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "韋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鍏", "Unihan_Traditional (Chữ Phồn thể)": "鍏", "Pinyin_Xie": "wéi", "Âm Hán Việt_Xie": "vi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loại nông cụ đào đất thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鷉', '{"9000": "6556.0", "Chữ Trung Quốc": "鷉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 21 | nét | 鷉 | đề | tượng hình | chim le le, chim mòng biển nhỏ (grebe) | 鷉 là chữ chỉ dùng trong từ 鸊鷉 (pì tī — chim le le, một loài chim nước). Không có phân tích hình thanh chi tiết trong dữ liệu. Bộ 鸟/鳥 (điểu — chim) ngầm chứa trong cấu trúc chữ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đề\": 鷉 là nửa tên của chim lặn (鸊鷉) — loài chim nước tài bơi lặn, âm Hán-Việt \"đề\" gợi tiếng chim kêu đề đề trên mặt hồ. | Gương Hán-Việt | đề (鷉 — trong 鸊鷉, tên loài chim lặn le le) | Mở khoá kiến thức | Biết 鷉 giúp nhận ra tên loài chim trong cổ văn điểu học: 鸊鷉 (chim le le, grebe) xuất hiện trong thơ ca và bản thảo tự nhiên học.", "Tự nguyên_Xie": "Theo Wiktionary, 鷉 chỉ dùng trong từ 鸊鷉 (chim le le, grebe). Có chữ giáp cốt văn (etym từ 鷈). Chữ hiếm, chủ yếu gặp trong văn bản điểu học và từ điển cổ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "như chữ 鷈", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "虒 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虒鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "虒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鷉", "Unihan_Traditional (Chữ Phồn thể)": "鷉", "Pinyin_Xie": "tī", "Âm Hán Việt_Xie": "đề", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong từ ghép để chỉ loài chim lặn nước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('郄', '{"9000": "6557.0", "Chữ Trung Quốc": "郄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 8 | nét | 郄 | khích | tượng hình | họ người; tên đất; kẽ hở giữa xương và thịt | 郄 là dị thể của 郤, cũng là biến thể của 卻. Bộ 阝(邑) gợi địa danh hoặc tên họ. Chữ có nhiều âm đọc: xì (họ), què (biến thể 卻), qiè (họ người). Không có phân tích hình thanh chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khích\": bộ 阝 (ấp — làng xóm) + phần gốc → 郄 là tên đất, họ người cổ, và còn nghĩa \"kẽ hở\" như khoảng cách giữa xương và thịt. | Gương Hán-Việt | khích (郄 — kẽ hở, tên đất/họ trong văn ngôn cổ) | Mở khoá kiến thức | Biết 郄 giúp đọc hiểu tên họ và địa danh cổ trong văn học lịch sử Trung Quốc.", "Tự nguyên_Xie": "Theo Wiktionary, 郄 là dị thể của 郤, đồng thời là biến thể của 卻. Âm xì: dùng như 郤 (tên đất, họ người, hoặc kẽ hở giữa xương thịt). Âm qiè: họ người. Âm què: dùng như 卻. Chữ phức tạp với nhiều cách đọc trong văn ngôn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên đất); chỗ xương thịt giáp nhau", "Hạng Tần Suất (Jun Da)": "6557.0", "Tần Suất % (Jun Da)": "99.9937391481", "GavinGrover_Once (Chiết tự trực tiếp)": "𠫤 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰𠫤阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𠫤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "郄", "Unihan_Traditional (Chữ Phồn thể)": "郄", "Pinyin_Xie": "qiè", "Âm Hán Việt_Xie": "khích, tức, khước", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ khe hở giữa xương thịt hoặc dùng làm họ người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('埘', '{"9000": "6558.0", "Chữ Trung Quốc": "埘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 10 | nét | 埘 | thì | tượng hình | chuồng gà khoét vào tường đất | 埘 là chữ độc thể liên quan đến đất (bộ 土 — thổ). Nghĩa gốc là chuồng gà làm bằng cách khoét lỗ vào tường đất. Có chữ tiểu triện. Xuất hiện trong Kinh Thi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thì\": 土 (thổ — đất) tạo ra chiếc tổ khoét sâu — 埘 là chuồng gà kiểu cổ, khoét thẳng vào vách đất làng quê. | Gương Hán-Việt | thì (塒/埘 — chuồng gà khoét tường, xuất hiện trong Kinh Thi) | Mở khoá kiến thức | Biết 埘 giúp đọc hiểu Kinh Thi và văn học nông thôn cổ Trung Quốc miêu tả đời sống chăn nuôi.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 埘 nghĩa là chuồng gà, đặc biệt là loại chuồng khoét vào tường đất. Trích dẫn từ Kinh Thi: \"雞棲于塒\" (gà đậu trong 塒 — chuồng khoét tường). Có chữ tiểu triện. Chữ nông thôn cổ, nay hiếm dùng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chuồng gà", "Hạng Tần Suất (Jun Da)": "6558.0", "Tần Suất % (Jun Da)": "99.9937474167", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 时", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土时", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "时", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "埘", "Unihan_Traditional (Chữ Phồn thể)": "塒", "Pinyin_Xie": "shí", "Âm Hán Việt_Xie": "thì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ loại chuồng gà được khoét sâu vào tường đất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('薤', '{"9000": "6559.0", "Chữ Trung Quốc": "薤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 16 | nét | 薤 | giới | tượng hình | củ kiệu (Allium chinense), loại hành kiệu | 薤 là chữ độc thể, bộ 艹 (thảo) gợi liên hệ đến thực vật. Nghĩa là cây hành kiệu (củ kiệu), một loại cây họ hành tỏi. Có chữ liushutong. Xuất hiện trong các bài thơ cổ nổi tiếng như 薤露 (Hành lộ ca).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giới\": 薤露 — giọt sương (露) trên lá kiệu (薤) sáng sớm tan biến — hình ảnh thơ ca cổ ví von cuộc đời ngắn ngủi. | Gương Hán-Việt | giới (薤 — củ kiệu, trong bài ca 薤露 nổi tiếng) | Mở khoá kiến thức | Biết 薤 giúp đọc hiểu bài 薤露歌 — một trong những ca khúc tang lễ cổ nhất Trung Quốc còn lưu truyền.", "Tự nguyên_Xie": "Lục thư thông | Theo Wiktionary, 薤 là tên thực vật chỉ cây Allium chinense (củ kiệu). Có chữ liushutong (tạo muộn). Nổi tiếng qua bài ca 薤露 (Hành lộ — ca khúc tang lễ cổ so sánh đời người với giọt sương trên lá kiệu). Chưa có nguồn học thuật chi tiết về từ nguyên. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "củ kiệu", "Hạng Tần Suất (Jun Da)": "6559.0", "Tần Suất % (Jun Da)": "99.9937556852", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "薤", "Unihan_Traditional (Chữ Phồn thể)": "薤", "Pinyin_Xie": "xiè", "Âm Hán Việt_Xie": "giới", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ cây kiệu hoặc củ kiệu trong ẩm thực. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲞', '{"9000": "6560.0", "Chữ Trung Quốc": "鲞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 14 | nét | 鲞 | tưởng | tượng hình | cá phơi khô, cá muối | 鲞 là chữ độc thể. Bộ 鱼 (ngư — cá) trong cấu trúc gợi liên hệ đến hải sản. Nghĩa gốc là cá phơi khô hoặc thực phẩm muối sấy khô, phổ biến trong ẩm thực miền Đông Trung Quốc (Chiết Giang, Phúc Kiến).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tưởng\": 鲞 là cá (鱼) được phơi nắng đến khi khô giòn — \"tưởng\" nhớ mùi cá khô đặc trưng của vùng biển Chiết Giang. | Gương Hán-Việt | tưởng (鲞 — cá phơi khô, đặc sản ẩm thực miền Đông Trung Quốc) | Mở khoá kiến thức | Biết 鲞 giúp nhận ra tên món ăn đặc sản Chiết Giang: 白鯗 (cá tráp khô), 鯗魚 trong văn học ẩm thực Trung Quốc.", "Tự nguyên_Xie": "Theo Wiktionary, 鲞 nghĩa là cá phơi khô (sun-dried fish), từ đó mở rộng sang các thực phẩm muối sấy khô khác. Có chữ cổ từ văn bản Trung Đường. Chữ phương ngữ, phổ biến ở Ôn Châu và Ninh Ba (Chiết Giang). Chưa có nguồn học thuật chi tiết về từ nguyên hình chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá phơi khô", "Hạng Tần Suất (Jun Da)": "6560.0", "Tần Suất % (Jun Da)": "99.9937639538", "GavinGrover_Once (Chiết tự trực tiếp)": "龹 + 鱼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱龹鱼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "龹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲞", "Unihan_Traditional (Chữ Phồn thể)": "鯗", "Pinyin_Xie": "xiǎng", "Âm Hán Việt_Xie": "tưởng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau tên loại cá để chỉ món cá khô tương ứng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鼯', '{"9000": "6561.0", "Chữ Trung Quốc": "鼯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鼠 | Số nét | 20 | nét | 鼯 | ngô | tượng hình | con sóc bay (flying squirrel) | 鼯 là chữ độc thể. Bộ 鼠 (thử — chuột) trong cấu trúc gợi liên hệ đến loài gặm nhấm. 鼯 chỉ con sóc bay, một loài động vật có màng da nối tay chân giúp lướt gió. Chữ tạo từ bộ thú vật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngô\": 鼯 là con chuột (鼠) biết bay — sóc bay trải màng da như chiếc áo ngô (ngô — áo ngoài) lướt qua các tán cây. | Gương Hán-Việt | ngô (鼯 — sóc bay trong văn ngôn tự nhiên học cổ) | Mở khoá kiến thức | Biết 鼯 giúp đọc thành ngữ cổ: 鼯鼠五技 (sóc bay năm tài — biết nhiều nhưng không tinh) — ví người học vắng tay đủ thứ mà không chuyên.", "Tự nguyên_Xie": "Theo Wiktionary, nguồn chỉ ghi {{Han etym}} mà không có giải thích chi tiết. 鼯 nghĩa là sóc bay (flying squirrel), có bộ 鼠 (thử — chuột) biểu nghĩa. Chữ tạo muộn. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con sóc bay", "Hạng Tần Suất (Jun Da)": "6561.0", "Tần Suất % (Jun Da)": "99.9937722223", "GavinGrover_Once (Chiết tự trực tiếp)": "鼠 + 吾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鼠吾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鼠", "Unihan_Simplified (Chữ Giản thể)": "鼯", "Unihan_Traditional (Chữ Phồn thể)": "鼯", "Pinyin_Xie": "wú", "Âm Hán Việt_Xie": "ngô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với các chữ khác tạo thành danh từ chỉ loài sóc bay. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('坭', '{"9000": "6562.0", "Chữ Trung Quốc": "坭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 8 | nét | 坭 | nơi | tượng hình | bùn đất, đất nhão | 坭 là dị thể của 泥 (bùn) hoặc chữ độc thể. Bộ 土 (thổ — đất) gợi liên hệ đến đất sét, bùn nhão. Không có phân tích từ nguyên chi tiết trong dữ liệu. Theo nguồn, 坭 nghĩa là bùn, đất nhão.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nơi\": 坭 là đất (土) nhão ướt — \"nơi\" đất bùn lầy, như ruộng lúa sau mưa, dưới bàn chân là bùn nhão. | Gương Hán-Việt | nơi (坭 — bùn đất, đất nhão trong phương ngữ Nam Trung Quốc) | Mở khoá kiến thức | Biết 坭 giúp nhận ra chữ trong địa danh và từ vựng phương ngữ Quảng Đông liên quan đến đất sét và đồ gốm.", "Tự nguyên_Xie": "Theo Wiktionary, không có giải thích chi tiết. 坭 nghĩa là bùn đất, đất nhão (mud, mire), dùng để trét tường hoặc chỉ đất lầy. Bộ 土 biểu nghĩa liên quan đến đất. Chữ tạo muộn, chưa có ghi chép giáp cốt/kim văn rõ ràng. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bùn đất", "Hạng Tần Suất (Jun Da)": "6562.0", "Tần Suất % (Jun Da)": "99.9937804909", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 尼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土尼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "坭", "Unihan_Traditional (Chữ Phồn thể)": "坭", "Pinyin_Xie": "ní", "Âm Hán Việt_Xie": "nê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong địa danh hoặc kết hợp chỉ chất liệu đất sét. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蔌', '{"9000": "6563.0", "Chữ Trung Quốc": "蔌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 14 | nét | 蔌 | tốc | tượng hình | rau cỏ; âm thanh gió thổi hoặc vật rơi | 蔌 là chữ độc thể, bộ 艹 (thảo) gợi liên hệ đến thực vật. Nghĩa chính là rau cỏ (văn ngôn), ngoài ra còn dùng trong từ láy 蔌蔌 chỉ tiếng gió thổi hoặc tiếng lá rơi. Cũng là họ người.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tốc\": 蔌 là rau cỏ (艹) rào rào — 蔌蔌 là tiếng gió thổi qua đám cỏ, như cỏ cây rơi tốc xuống trong gió. | Gương Hán-Việt | tốc (蔌 — rau cỏ văn ngôn; 蔌蔌 trong thơ miêu tả thiên nhiên) | Mở khoá kiến thức | Biết 蔌 giúp đọc hiểu thơ văn cổ miêu tả thiên nhiên: 山肴野蔌 (sơn hào dã tốc — thức ăn rừng núi dân dã).", "Tự nguyên_Xie": "Theo Wiktionary, 蔌 có các nghĩa: (văn ngôn) rau cỏ; dùng trong 蔌蔌 chỉ âm thanh (gió thổi, vật rơi); và là họ người. Có chữ cổ. Chưa có phân tích từ nguyên chi tiết trong dữ liệu. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rau cỏ; thô sơ; rơi lả tả; gió thổi nhanh và mạnh; nước chảy", "Hạng Tần Suất (Jun Da)": "6563.0", "Tần Suất % (Jun Da)": "99.9937887595", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 欶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹欶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "欶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蔌", "Unihan_Traditional (Chữ Phồn thể)": "蔌", "Pinyin_Xie": "sù", "Âm Hán Việt_Xie": "tốc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ rau cỏ hoặc làm tính từ mô tả vẻ đạm bạc của món ăn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缳', '{"9000": "6564.0", "Chữ Trung Quốc": "缳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 16 | nét | 缳 | hoàn | tượng hình | thòng lọng, vòng thắt cổ; giản thể của 繯 | 缳 là giản thể của 繯. Bộ 纟(糸 — mịch, sợi tơ) gợi liên hệ đến dây thừng, thòng lọng. Nghĩa là dây thòng lọng, vòng thắt hoặc hành động treo cổ. Chữ có chữ đại triện và tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoàn\": 缳 là sợi dây (纟) cuộn thành vòng (hoàn) — hình ảnh chiếc thòng lọng, dây buộc nguy hiểm. | Gương Hán-Việt | hoàn (缳 — thòng lọng, hành quyết bằng treo cổ trong văn ngôn pháp luật cổ) | Mở khoá kiến thức | Biết 缳 giúp đọc các văn bản pháp luật và lịch sử hình phạt cổ Trung Quốc: 就缳 (chịu án treo cổ).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 缳 là giản thể của 繯 (thòng lọng, vòng thắt). Bộ 纟(糸) biểu nghĩa (dây sợi), phần còn lại biểu âm. Nghĩa: vòng, thòng lọng, treo cổ. Có chữ đại triện và tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "buộc thòng lọng, thắt cổ", "Hạng Tần Suất (Jun Da)": "6564.0", "Tần Suất % (Jun Da)": "99.993797028", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 睘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟睘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "睘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "缳", "Unihan_Traditional (Chữ Phồn thể)": "繯", "Pinyin_Xie": "huán", "Âm Hán Việt_Xie": "hoán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ chỉ hành động treo cổ hoặc danh từ chỉ nút thòng lọng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('筸', '{"9000": "6565.0", "Chữ Trung Quốc": "筸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 13 | nét | 竹 | trúc | biểu nghĩa | tre, trúc | 旱 | hạn | biểu âm | hạn hán (cho âm gān) | 筸 = 竹 (Trúc, biểu nghĩa: tre) + 旱 (Hạn, biểu âm: cho âm gān). Chữ hình thanh — 竹 xác định liên hệ đến tre/trúc, 旱 cho âm đọc. Nghĩa là tên đất ở Hà Nam (Trung Quốc cổ).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"can\": 竹 (trúc — tre) + 旱 (hạn — khô hạn) → vùng đất tre khô — 筸 là tên địa danh cổ ở Hà Nam, nơi có nhiều tre trúc. | Gương Hán-Việt | can (筸 — địa danh cổ ở Hà Nam, Trung Quốc) | Mở khoá kiến thức | Biết 筸 giúp nhận ra địa danh trong văn bản địa lý và lịch sử Hà Nam cổ đại.", "Tự nguyên_Xie": "Theo Wiktionary, 筸 là chữ hình thanh: 竹 (trúc — tre) biểu nghĩa, 旱 (hạn) biểu âm. Dùng làm địa danh ở Hà Nam. Chữ hiếm, chủ yếu gặp trong địa lý và từ điển cổ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên đất)", "Hạng Tần Suất (Jun Da)": "6565.0", "Tần Suất % (Jun Da)": "99.9938135652", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 旱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮旱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "筸", "Unihan_Traditional (Chữ Phồn thể)": "筸", "Pinyin_Xie": "gān", "Âm Hán Việt_Xie": "can", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong địa danh cổ hoặc chỉ loại tre nhỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('夼', '{"9000": "6566.0", "Chữ Trung Quốc": "夼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 大 | Số nét | 6 | nét | 夼 | khoảng | tượng hình | vùng đất trũng thấp (dùng trong địa danh Sơn Đông) | 夼 là chữ độc thể, không có phân tích hình thanh rõ trong dữ liệu. Nghĩa là vùng đất trũng, lòng chảo (depression), dùng chủ yếu trong địa danh ở Sơn Đông, Trung Quốc. Không có dữ liệu ảnh từ nguyên.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khoảng\": 夼 là khoảng đất trũng — địa hình lõm xuống giữa núi đồi ở Sơn Đông, nơi nước tụ lại. | Gương Hán-Việt | khoảng (夼 — vùng đất trũng trong địa danh Sơn Đông) | Mở khoá kiến thức | Biết 夼 giúp nhận ra tên làng xã ở Sơn Đông khi đọc bản đồ hoặc văn bản địa phương Trung Quốc.", "Tự nguyên_Xie": "Không có glyphOrigin chi tiết từ Wiktionary cho 夼. Chữ dùng để chỉ vùng đất thấp trũng, lòng chảo địa hình, chủ yếu dùng trong địa danh tỉnh Sơn Đông. Chữ tạo muộn phục vụ mục đích địa lý địa phương. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nơi đất trũng", "Hạng Tần Suất (Jun Da)": "6566.0", "Tần Suất % (Jun Da)": "99.9938301023", "GavinGrover_Once (Chiết tự trực tiếp)": "大 + 川", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱大川", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "川", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "大", "Unihan_Simplified (Chữ Giản thể)": "夼", "Unihan_Traditional (Chữ Phồn thể)": "夼", "Pinyin_Xie": "kuǎng", "Âm Hán Việt_Xie": "khoảng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ xuất hiện trong địa danh ở vùng Sơn Đông, Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('椐', '{"9000": "6567.0", "Chữ Trung Quốc": "椐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 12 | nét | 椐 | cư | tượng hình | cây cư (Zelkova serrata — cây du Nhật) | 椐 là chữ độc thể, bộ 木 (mộc — gỗ/cây) gợi liên hệ đến thực vật gỗ. Nghĩa là cây linh thọ (Zelkova serrata — cây du Nhật), một loại cây gỗ quý. Có chữ tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cư\": 椐 là cây gỗ (木) đứng thẳng trang nghiêm — cây du Nhật (cư) mọc thẳng và rắn chắc, biểu tượng của sự vững chãi. | Gương Hán-Việt | cư (椐 — cây linh thọ, Zelkova serrata trong bản thảo thực vật cổ) | Mở khoá kiến thức | Biết 椐 giúp nhận ra tên cây gỗ quý trong văn bản bản thảo học và lâm nghiệp cổ Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 椐 là tên cây Zelkova serrata (cây du Nhật, linh thọ). Bộ 木 biểu nghĩa (cây/gỗ). Có chữ tiểu triện. Xuất hiện trong từ ghép 椐椐 (đứng thẳng, trang nghiêm). Chưa có nguồn học thuật chi tiết về cấu trúc từ nguyên. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây cư, cây linh thọ", "Hạng Tần Suất (Jun Da)": "6567.0", "Tần Suất % (Jun Da)": "99.9938383708", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 居", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木居", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "居", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "椐", "Unihan_Traditional (Chữ Phồn thể)": "椐", "Pinyin_Xie": "jū", "Âm Hán Việt_Xie": "cư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ một loại cây thân gỗ cổ thụ có gai dùng làm gậy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('轹', '{"9000": "6568.0", "Chữ Trung Quốc": "轹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 9 | nét | 車 | xa | biểu nghĩa | xe, cỗ xe | 樂 | lạc | biểu âm | vui vẻ (cho âm lì) | 轹 = 車 (Xa, biểu nghĩa: xe) + 樂 (Lạc, biểu âm: cho âm lì). Chữ hình thanh — 車 xác định nghĩa liên quan đến xe cộ, 樂 cho âm đọc. Nghĩa là cán xe chạy qua, nghiến qua, hoặc bắt nạt, chèn ép.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lịch\": 車 (xa — bánh xe) + 樂 (lạc — vui) → bánh xe vô tư nghiền qua — 轹 là cán qua không thương tiếc, hình ảnh sức mạnh bắt nạt kẻ yếu. | Gương Hán-Việt | lịch (軋轢/轹 — chèn ép, nghiến qua trong văn ngôn cổ) | Mở khoá kiến thức | Biết 轹 mở khoá từ 軋轢 (lịch — xung đột, chèn ép) dùng trong văn học và báo chí chữ Hán.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 轹 là chữ hình thanh: 車 (xa — xe) biểu nghĩa, 樂 (lạc) biểu âm. Nghĩa: cán xe chạy qua (run over), kẻ phá hoại, hoặc bắt nạt người. Có chữ tiểu triện. Các từ ghép gồm 凌轢, 軋轢 (chèn ép, xung đột). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nghiền, nghiến qua", "Hạng Tần Suất (Jun Da)": "6568.0", "Tần Suất % (Jun Da)": "99.9938466394", "GavinGrover_Once (Chiết tự trực tiếp)": "车 + 乐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰车乐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "车", "Unihan_Simplified (Chữ Giản thể)": "轹", "Unihan_Traditional (Chữ Phồn thể)": "轢", "Pinyin_Xie": "lì", "Âm Hán Việt_Xie": "lịch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ chỉ hành động bánh xe lăn qua hoặc chà đạp, áp bức. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('脬', '{"9000": "6569.0", "Chữ Trung Quốc": "脬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 11 | nét | 脬 | bào | tượng hình | bàng quang, bong bóng đái | 脬 là chữ độc thể, bộ 月/肉 (nhục — thịt/cơ thể) trong cấu trúc gợi liên hệ đến nội tạng. Nghĩa là bàng quang (bladder), bong bóng. Có chữ tiểu triện. Các từ ghép như 尿脬 (bàng quang), 卵脬 (tinh hoàn trong phương ngữ).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bào\": 脬 là túi thịt (月/肉) chứa nước tiểu — bàng quang (bào), cái túi mềm bên trong cơ thể người. | Gương Hán-Việt | bào (脬 — bàng quang, bong bóng đái trong y học cổ và phương ngữ) | Mở khoá kiến thức | Biết 脬 giúp đọc các văn bản y học Đông y và phương ngữ Mân Nam liên quan đến nội tạng và giải phẫu.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 脬 nghĩa là bàng quang (bladder). Có chữ tiểu triện. Dùng trong các từ phương ngữ như 尿脬 (bàng quang), 卵脬. Chưa có phân tích từ nguyên cấu trúc chi tiết trong dữ liệu. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bong bóng; bóng đái", "Hạng Tần Suất (Jun Da)": "6569.0", "Tần Suất % (Jun Da)": "99.993854908", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 孚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月孚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "孚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "脬", "Unihan_Traditional (Chữ Phồn thể)": "脬", "Pinyin_Xie": "pāo", "Âm Hán Việt_Xie": "phao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Thường dùng làm danh từ chỉ bàng quang hoặc lượng từ cho nước tiểu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('眍', '{"9000": "6570.0", "Chữ Trung Quốc": "眍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 9 | nét | 眍 | khấu | tượng hình | mắt lõm xuống, hố mắt trũng sâu | 眍 là chữ độc thể, bộ 目 (mục — mắt) trong cấu trúc gợi liên hệ đến mắt. Nghĩa là mắt lõm sâu vào hốc mắt. Từ ghép như 眍瞜 miêu tả mắt trũng sâu do gầy yếu hoặc bệnh tật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khấu\": 眍 là đôi mắt (目) khấu vào sâu — hốc mắt lõm xuống như cái hố, dấu hiệu của người gầy yếu hoặc bệnh nặng. | Gương Hán-Việt | khấu (眍 — mắt lõm sâu, hốc mắt trũng trong miêu tả ngoại hình) | Mở khoá kiến thức | Biết 眍 giúp đọc miêu tả ngoại hình chi tiết trong tiểu thuyết và văn xuôi Trung Quốc hiện đại.", "Tự nguyên_Xie": "Theo Wiktionary, 眍 nghĩa là mắt trũng sâu (sunken-eyed). Dùng trong từ 眍瞜 và 窩瞘眼. Có chữ cổ trong từ điển. Chưa có phân tích từ nguyên chi tiết trong dữ liệu. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mắt lõm xuống", "Hạng Tần Suất (Jun Da)": "6570.0", "Tần Suất % (Jun Da)": "99.9938631765", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 区", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目区", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "区", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "眍", "Unihan_Traditional (Chữ Phồn thể)": "瞘", "Pinyin_Xie": "kōu", "Âm Hán Việt_Xie": "khu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ miêu tả đặc điểm hốc mắt bị trũng sâu. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('饹', '{"9000": "6571.0", "Chữ Trung Quốc": "饹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 9 | nét | 饹 | lạc | tượng hình | phần trong từ ghép 饸饹, chỉ loại mì sợi ép | 饹 là chữ chỉ dùng trong từ 饸饹 (hé le) — một loại mì sợi ép từ bột mì hoặc kiều mạch đặc trưng miền Bắc Trung Quốc. Không có cấu trúc hình thanh riêng lẻ trong dữ liệu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lạc\": 饹 luôn đi sau 饸 trong từ 饸饹 — như sợi mì cuối cùng không thể thiếu, \"lạc\" lại thành cặp không tách rời. | Gương Hán-Việt | lạc (饹 — nửa sau của 饸饹, mì sợi ép miền Bắc) | Mở khoá kiến thức | Biết 饹 giúp nhận ra từ 饸饹 trong thực đơn và văn hóa ẩm thực Bắc Trung Quốc (Thiểm Tây, Sơn Tây, Hà Bắc).", "Tự nguyên_Xie": "Không có glyphOrigin chi tiết từ Wiktionary cho 饹. Chữ chỉ xuất hiện trong từ 饸饹 (餄餎). Tạo muộn phục vụ từ vựng ẩm thực dân gian. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: hợp lạc 餄餎,饸饹)", "Hạng Tần Suất (Jun Da)": "6571.0", "Tần Suất % (Jun Da)": "99.9938714451", "GavinGrover_Once (Chiết tự trực tiếp)": "饣 + 各", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰饣各", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "各", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "饣", "Unihan_Simplified (Chữ Giản thể)": "饹", "Unihan_Traditional (Chữ Phồn thể)": "餎", "Pinyin_Xie": "le", "Âm Hán Việt_Xie": "lạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp thành từ ghép để chỉ một loại mì sợi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瘥', '{"9000": "6572.0", "Chữ Trung Quốc": "瘥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 14 | nét | 疒 | nạch | biểu nghĩa | bệnh tật (bộ thủ bệnh) | 差 | sai | biểu âm | sai khác (cho âm chài/cuō) | 瘥 = 疒 (Nạch, biểu nghĩa: bệnh tật) + 差 (Sai, biểu âm: cho âm chài). Chữ hình thanh — 疒 xác định nghĩa liên quan đến bệnh, 差 cho âm đọc. Nghĩa là bị ốm; cũng có nghĩa khỏi bệnh (dịch bệnh, đại dịch).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sai\": 疒 (bệnh) + 差 (sai — lệch) → cơ thể \"lệch\" vì bệnh — 瘥 vừa có nghĩa mắc bệnh vừa có nghĩa khỏi bệnh (trở về \"đúng\" trạng thái). | Gương Hán-Việt | sai (瘥 — ốm bệnh; khỏi bệnh trong y văn Đông y cổ điển) | Mở khoá kiến thức | Biết 瘥 giúp đọc y văn Đông y cổ: 病瘥 (bệnh khỏi), 大瘥 (đại dịch qua đi).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 瘥 là chữ hình thanh: 疒 (nạch — bệnh tật) biểu nghĩa, 差 (sai) biểu âm. Nghĩa kép: (1) bị ốm, mắc bệnh; (2) hết bệnh, khỏi (Đông y). Có chữ tiểu triện. Xuất hiện trong văn ngôn y học cổ điển. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bị ốm", "Hạng Tần Suất (Jun Da)": "6572.0", "Tần Suất % (Jun Da)": "99.9938797137", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 差", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒差", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "差", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "瘥", "Unihan_Traditional (Chữ Phồn thể)": "瘥", "Pinyin_Xie": "chài", "Âm Hán Việt_Xie": "sái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ sự hồi phục sau khi bị ốm. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瘵', '{"9000": "6573.0", "Chữ Trung Quốc": "瘵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 16 | nét | 瘵 | trái | tượng hình | bệnh nặng, bệnh lao; bệnh mãn tính tiêu hao | 瘵 là chữ độc thể trong dữ liệu hiện có. Bộ 疒 (nạch — bệnh tật) gợi liên hệ đến bệnh nặng. Nghĩa là bệnh tiêu hao (wasting disease), bệnh lao hoặc bệnh mãn tính nặng. Có chữ tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trái\": bộ 疒 (bệnh) mang \"trái\" khoắng — 瘵 là bệnh lao tiêu hao dần, như trái cây héo rũ từng ngày. | Gương Hán-Việt | trái (瘵 — bệnh lao, bệnh tiêu hao trong văn ngôn y học cổ) | Mở khoá kiến thức | Biết 瘵 giúp đọc y văn và văn học cổ điển Trung Quốc mô tả bệnh nặng mãn tính: 凋瘵 (điêu trái — tiêu điều bệnh tật).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 瘵 nghĩa là bệnh tiêu hao, bệnh nặng (wasting disease), đặc biệt là lao bệnh. Xuất hiện trong văn học cổ điển cao cấp (trích dẫn Tang Dynasty). Có chữ tiểu triện. Chữ văn ngôn, hiếm dùng trong tiếng Trung hiện đại. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bệnh tật", "Hạng Tần Suất (Jun Da)": "6573.0", "Tần Suất % (Jun Da)": "99.9938879822", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 祭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒祭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "祭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "瘵", "Unihan_Traditional (Chữ Phồn thể)": "瘵", "Pinyin_Xie": "zhài", "Âm Hán Việt_Xie": "sái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ bệnh lao hoặc tình trạng suy nhược. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('邴', '{"9000": "6574.0", "Chữ Trung Quốc": "邴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 7 | nét | 邴 | bỉnh | tượng hình | địa danh cổ, tên đất thuộc nước Tống | 邴 là chữ chỉ địa danh cổ. Cấu trúc không rõ ràng trong nguồn CHISE; chữ liên quan đến bộ 邑 (ấp, vùng đất). Chưa xác định rõ hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bỉnh\": Tên đất cổ xưa vùng Sơn Đông — 邴 mang dấu ấn lịch sử nước Tống. Chưa có nguồn học thuật rõ ràng về cấu tạo. | Gương Hán-Việt | bỉnh — ít dùng trong tiếng Việt hiện đại, chủ yếu xuất hiện trong tên riêng | Mở khoá kiến thức | Biết 邴 giúp nhận diện địa danh cổ Trung Quốc và họ tên người Hoa gốc lịch sử.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 邴 là tên một thành ấp thuộc nước Tống thời cổ đại (nay thuộc Sơn Đông). Cũng mang nghĩa vui mừng (dùng trong 邴邴). Chưa có phân tích cấu trúc chi tiết trong học thuật. Có hình tiểu triện. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vui mừng; huyện Bỉnh (nay thuộc tỉnh Sơn Đông của Trung Quốc)", "Hạng Tần Suất (Jun Da)": "6574.0", "Tần Suất % (Jun Da)": "99.9939127879", "GavinGrover_Once (Chiết tự trực tiếp)": "丙 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰丙阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "邴", "Unihan_Traditional (Chữ Phồn thể)": "邴", "Pinyin_Xie": "bǐng", "Âm Hán Việt_Xie": "bỉnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm họ người hoặc tính từ chỉ sự vui mừng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鉁', '{"9000": "6575.0", "Chữ Trung Quốc": "鉁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 13 | nét | 鉁 | tượng hình | chữ thuộc bộ kim, phát âm zhēn | 鉁 thuộc bộ 金 (kim loại). Không có dữ liệu cấu trúc chi tiết từ CHISE. Chưa xác định được hình thanh hay hội ý. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chan\": Chữ bộ Kim (金), đọc zhēn — liên tưởng với 針 (cây kim) hay 珍 (quý báu) cùng âm. Chưa có nguồn học thuật. | Gương Hán-Việt | ít dùng trong tiếng Việt | Mở khoá kiến thức | Chữ hiếm, ít xuất hiện ngoài văn bản cổ hoặc tên riêng.", "Tự nguyên_Xie": "Không có dữ liệu nguồn gốc từ Wiktionary cho 鉁. Chữ thuộc bộ 金 (kim loại), phát âm zhēn — gợi liên hệ với các chữ cùng âm như 針 (kim châm), 珍 (quý giá). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鉁", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 㐱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金㐱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㐱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鉁", "Unihan_Traditional (Chữ Phồn thể)": "鉁", "Pinyin_Xie": "zhēn", "Âm Hán Việt_Xie": "chan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ đồ vật quý giá hoặc tính từ quý báu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鞮', '{"9000": "6576.0", "Chữ Trung Quốc": "鞮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 革 | Số nét | 18 | nét | 革 | cách | biểu nghĩa | da thuộc | 是 | thị | biểu âm | là, đúng | 鞮 = 革 (Cách, biểu nghĩa: da thuộc, liên quan đến giày dép) + 是 (Thị, biểu âm); chữ hình thanh. Phần 革 gợi nghĩa đồ da, phần 是 cho biết âm đọc dī.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"de\": Da thuộc (革) làm ra đôi giày — 鞮 là chiếc giày da quý tộc thời cổ xưa. Hình thanh: 革 nghĩa + 是 âm. | Gương Hán-Việt | ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 鞮 giúp đọc văn bản lịch sử về trang phục và phong tục cổ Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 鞮 là chữ hình thanh: 革 (biểu nghĩa, da thuộc) kết hợp với 是 (biểu âm). Nghĩa gốc là giày da, đặc biệt chỉ loại giày cổ xưa. Cũng dùng để chỉ các nhóm dân tộc phía bắc và tây Trung Quốc thời cổ. Có hình tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giày da; giày đơn; thông dịch, phiên dịch", "Hạng Tần Suất (Jun Da)": "6576.0", "Tần Suất % (Jun Da)": "99.993929325", "GavinGrover_Once (Chiết tự trực tiếp)": "革 + 是", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰革是", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "是", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "革", "Unihan_Simplified (Chữ Giản thể)": "鞮", "Unihan_Traditional (Chữ Phồn thể)": "鞮", "Pinyin_Xie": "dī", "Âm Hán Việt_Xie": "đê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ loại giày da thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('舄', '{"9000": "6577.0", "Chữ Trung Quốc": "舄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 臼 | Số nét | 12 | nét | 舄 | tích | tượng hình | loài chim; giày hai lần đế | 舄 là chữ tượng hình, phác thảo hình ảnh một loài chim (biến thể bảo thủ hơn là 舃). Theo thời gian mang thêm nghĩa giày với đế kép dùng trong nghi lễ. Chưa xác định được hội ý hay hình thanh từ cấu trúc hiện tại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tích\": Chim hỷ thước biến thành đôi giày nghi lễ có đế đôi — 舄 vừa là chim, vừa là hài cổ trang. | Gương Hán-Việt | tích — ít dùng trong tiếng Việt, xuất hiện trong văn học cổ | Mở khoá kiến thức | Biết 舄 giúp đọc thơ và văn cổ điển Trung Hoa về trang phục nghi lễ hoàng cung.", "Tự nguyên_Xie": "Theo Wiktionary, 舄 xuất phát từ hình tượng một loài chim (liushu: tượng hình). Nghĩa phái sinh là loại giày có thêm đế gỗ bên dưới dùng trong nghi lễ cung đình. Phát âm 1: xì (giày); phát âm 2: què (chim hỷ thước — dị thể của 鵲). Chưa thấy trong giáp cốt văn hay kim văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "611.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Cữu (610) Bao (020) Hỏa (118)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Cữu (số 610) mà phần dưới thay bằng bộ Bao (số 020) và 4 chấm Hỏa (số 118). Giải thích sự chuyển ý: Đây là chữ Hội ý. Ngụ ý ở xứ lạnh, đôi giày luôn bao bọc giữ ấm đôi chân. Tích là đôi giày có 2 lớp đế dày.", "Nghĩa Tiếng Việt_Xie": "giày 2 lần đế", "Hạng Tần Suất (Jun Da)": "6577.0", "Tần Suất % (Jun Da)": "99.9939375936", "GavinGrover_Once (Chiết tự trực tiếp)": "臼 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱臼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "舄", "Unihan_Traditional (Chữ Phồn thể)": "舄", "Pinyin_Xie": "xì", "Âm Hán Việt_Xie": "tích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ loại giày nghi lễ thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('麄', '{"9000": "6578.0", "Chữ Trung Quốc": "麄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鹿 | Số nét | 15 | nét | 麄 | thô | tượng hình | thô ráp, lớn; dị thể của 粗 | 麄 là dị thể cổ của 粗 (thô). Cấu trúc gồm bộ 鹿 (lộc, hươu). Không có phân tích cấu trúc rõ ràng trong nguồn; chữ tạo muộn, không thấy trong giáp cốt hay kim văn. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thô\": Con hươu (鹿) to lớn, thô ráp — 麄 là dạng cổ của chữ 粗 (thô). Chưa có nguồn học thuật. | Gương Hán-Việt | thô — xuất hiện trong văn bản cổ thay cho 粗 | Mở khoá kiến thức | Biết 麄 giúp nhận diện dị thể cổ của 粗 trong văn bản Hán cổ điển.", "Tự nguyên_Xie": "Không có dữ liệu nguồn gốc từ Wiktionary cho 麄. Đây là dị thể cổ của 粗 (thô ráp), thuộc bộ 鹿. Chữ tạo muộn, chưa thấy trong giáp cốt văn hay kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "to lớn; sơ lược; gạo giã chưa kỹ", "Hạng Tần Suất (Jun Da)": "6578.0", "Tần Suất % (Jun Da)": "99.9939458621", "GavinGrover_Once (Chiết tự trực tiếp)": "分 + 鹿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱分鹿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "分", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鹿", "Unihan_Simplified (Chữ Giản thể)": "麄", "Unihan_Traditional (Chữ Phồn thể)": "麄", "Pinyin_Xie": "cū", "Âm Hán Việt_Xie": "thô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ miêu tả tính chất thô sơ, chưa qua chế biến. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('翛', '{"9000": "6579.0", "Chữ Trung Quốc": "翛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羽 | Số nét | 12 | nét | 翛 | tiêu | tượng hình | lông vũ rối; vội vàng, phóng khoáng | 翛 thuộc bộ 羽 (lông vũ). Không có dữ liệu cấu trúc chi tiết trong nguồn CHISE. Chữ xuất hiện chủ yếu trong 翛翛 (tiêu tiêu, chỉ vẻ lông rối hoặc phóng khoáng tự do) và 翛然 (tiêu nhiên, thư thái). Chưa xác định hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiêu\": Lông chim (羽) bay lả trong gió — 翛翛 gợi cảnh phóng khoáng, 翛然 là trạng thái thư thái tự tại. Chưa có nguồn học thuật. | Gương Hán-Việt | tiêu — xuất hiện trong thơ cổ điển (翛然, 翛翛) | Mở khoá kiến thức | Biết 翛 giúp đọc thơ Đường Tống miêu tả cảnh vật phóng khoáng, tự tại.", "Tự nguyên_Xie": "Theo Wiktionary, 翛 chủ yếu dùng trong các từ ghép 翛翛 và 翛然. Phát âm 1: xiāo (lông rối, phóng khoáng); phát âm 2: shū/shù (dị thể cổ của 倏, vội vàng). Không có phân tích cấu tạo chi tiết. Chưa có nguồn học thuật rõ ràng. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vội vàng, gấp; (xem: tiêu tiêu 翛翛)", "Hạng Tần Suất (Jun Da)": "6579.0", "Tần Suất % (Jun Da)": "99.9939541307", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "翛", "Unihan_Traditional (Chữ Phồn thể)": "翛", "Pinyin_Xie": "xiāo", "Âm Hán Việt_Xie": "tiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Phó từ | 副词 | Chữ này thường dùng làm tính từ hoặc phó từ trong văn học cổ để tả dáng vẻ tự tại. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('覩', '{"9000": "6580.0", "Chữ Trung Quốc": "覩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 見 | Số nét | 15 | nét | 覩 | đổ | tượng hình | nhìn thấy; dị thể của 睹 | 覩 là dị thể của 睹 (đổ, nhìn thấy), thuộc bộ 見 (kiến, nhìn thấy). Không có phân tích cấu tạo riêng; Wiktionary chỉ đơn giản liệt kê 覩 là biến thể cổ của 睹.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đổ\": Mắt nhìn (見) — 覩 là dạng cổ của 睹, đều mang nghĩa trông thấy, chứng kiến. | Gương Hán-Việt | đổ — xuất hiện trong thành ngữ cổ như 有目共覩 (ai cũng thấy rõ) | Mở khoá kiến thức | Biết 覩 giúp đọc thành ngữ cổ điển liên quan đến thị giác và nhận thức.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 覩 là dị thể cổ của 睹 (nhìn thấy). Thuộc bộ 見, liên quan đến thị giác. Có hình tiểu triện. Chưa có phân tích nguồn gốc độc lập. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trông thấy", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "者 + 見", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰者見", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "者", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "見", "Unihan_Simplified (Chữ Giản thể)": "覩", "Unihan_Traditional (Chữ Phồn thể)": "覩", "Pinyin_Xie": "dǔ", "Âm Hán Việt_Xie": "đổ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường làm động từ đứng trước tân ngữ để chỉ việc nhìn thấy rõ ràng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('纩', '{"9000": "6581.0", "Chữ Trung Quốc": "纩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 6 | nét | 纩 | khoáng | tượng hình | sợi bông; lụa; dạng giản thể của 纊 | 纩 là dạng giản thể của 纊 (khoáng), thuộc bộ 纟(糸, tơ sợi). Dạng phồn thể 纊 = 糸 (biểu nghĩa, tơ sợi) + 廣 (biểu âm). Chữ hình thanh trong dạng gốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khoáng\": Sợi tơ (糸) quý như khoáng sản — 纩/纊 chỉ bông lụa mịn dùng trong nghi lễ tang ma cổ đại. Chưa có nguồn học thuật riêng cho dạng giản thể. | Gương Hán-Việt | khoáng — ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 纩 giúp đọc văn bản cổ về trang phục và nghi lễ sử dụng tơ lụa.", "Tự nguyên_Xie": "Theo Wiktionary, 纩 là dạng giản thể của 纊. Dạng phồn thể 纊 = 糸 (tơ sợi, biểu nghĩa) + 廣 (biểu âm) — chữ hình thanh chỉ sợi bông mịn, lụa. Phần 纟gợi nghĩa liên quan đến sợi dệt. Chưa có dữ liệu tiểu triện hay giáp cốt. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sợi bông", "Hạng Tần Suất (Jun Da)": "6581.0", "Tần Suất % (Jun Da)": "99.9939706678", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 广", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟广", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "广", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "纩", "Unihan_Traditional (Chữ Phồn thể)": "纊", "Pinyin_Xie": "kuàng", "Âm Hán Việt_Xie": "khoáng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ tơ bông thô dùng để lót áo ấm ngày xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('唛', '{"9000": "6582.0", "Chữ Trung Quốc": "唛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 10 | nét | 口 | khẩu | biểu nghĩa | miệng, lời nói thông tục | 麥 | mạch | biểu âm | lúa mạch | 唛 = 口 (Khẩu, biểu nghĩa: lời nói thông tục, phiên âm) + 麥 (Mạch, biểu âm); chữ hình thanh. Đây là chữ phiên âm tiếng Quảng Đông cho từ \"mark\" (nhãn hiệu). Phần 口 chỉ đây là chữ phiên âm, phần 麥 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mac\": Miệng (口) đọc \"麥\" (mạch) âm Quảng Đông mak6 → mark tiếng Anh — 唛 là nhãn hiệu hàng hoá phiên âm từ \"mark\". | Gương Hán-Việt | ít dùng trong tiếng Việt; gặp trong thương mại Hoa Nam và Hồng Kông | Mở khoá kiến thức | Biết 唛 giúp đọc tài liệu thương mại Hoa Nam, nhãn hiệu hàng xuất khẩu.", "Tự nguyên_Xie": "Theo Wiktionary (dạng chuẩn 嘜), 唛 là chữ hình thanh: 口 (biểu nghĩa, phiên âm) + 麥 (biểu âm). Chữ được tạo để ghi âm từ tiếng Anh \"mark\" qua tiếng Quảng Đông mak6. Là ví dụ điển hình về chữ Hán hiện đại tạo cho nhu cầu phiên âm ngoại lai. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhãn hiệu, mark hàng hoá", "Hạng Tần Suất (Jun Da)": "6582.0", "Tần Suất % (Jun Da)": "99.993987205", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 麦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口麦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "麦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "唛", "Unihan_Traditional (Chữ Phồn thể)": "嘜", "Pinyin_Xie": "mà", "Âm Hán Việt_Xie": "mạ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng làm danh từ trong thương mại để chỉ nhãn mác trên bao bì. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('袓', '{"9000": "6583.0", "Chữ Trung Quốc": "袓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 10 | nét | 袓 | tượng hình | chữ bộ 衣 ít dùng, phát âm jù | 袓 thuộc bộ 衣 (y phục). Không có dữ liệu cấu trúc chi tiết trong CHISE hay Wiktionary — chỉ có {{Han etym}} rỗng. Chưa xác định hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cu\": Bộ Y (衣) gợi liên quan đến y phục — 袓 là chữ hiếm thuộc nhóm trang phục. Chưa có nguồn học thuật. | Gương Hán-Việt | ít dùng trong tiếng Việt | Mở khoá kiến thức | Chữ hiếm, ít xuất hiện ngoài từ điển chuyên sâu.", "Tự nguyên_Xie": "Không có dữ liệu nguồn gốc từ Wiktionary cho 袓. Chữ thuộc bộ 衣 (y phục), phát âm jù. Chưa có nguồn học thuật rõ ràng. Có thể là dị thể hoặc chữ hiếm ít tư liệu. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "袓", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 且", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤且", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "且", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "袓", "Unihan_Traditional (Chữ Phồn thể)": "袓", "Pinyin_Xie": "jù", "Âm Hán Việt_Xie": "cu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này thường dùng làm tính từ trong văn ngôn để tả vẻ đẹp của trang phục. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('祂', '{"9000": "6584.0", "Chữ Trung Quốc": "祂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 7 | nét | 示 | thị | biểu nghĩa | thần linh, tế lễ | 也 | dã | biểu âm | cũng, là | 祂 = 示 (Thị, biểu nghĩa: thần linh, tôn giáo) + 也 (Dã, biểu âm); chữ hình thanh. Phần 示 gợi nghĩa tôn giáo/thần thánh, phần 也 cho biết âm đọc tā — phiên âm đại từ ngôi ba số ít giới tính trung tính, dùng riêng để chỉ Thiên Chúa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ta\": Bộ Thị (示, thần linh) + Dã (也, âm tā) = 祂 — đại từ thiêng liêng dành cho Đức Chúa Trời, khác 他 (người thường), 她 (phụ nữ), 它 (vật). | Gương Hán-Việt | ít dùng trong tiếng Việt; gặp trong bản dịch Kinh Thánh tiếng Trung | Mở khoá kiến thức | Biết 祂 giúp đọc Kinh Thánh và văn bản tôn giáo dịch sang tiếng Hoa hiện đại.", "Tự nguyên_Xie": "Theo Wiktionary, 祂 là chữ hình thanh: 示 (biểu nghĩa, tôn giáo) + 也 (biểu âm). Đây là chữ Hán hiện đại, tạo ra để có đại từ ngôi ba dành riêng cho Thiên Chúa/Allah trong Kinh Thánh và Kinh Quran bản dịch tiếng Trung. Không phải chữ cổ điển. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng xưng Ngài trong Kinh Thánh", "Hạng Tần Suất (Jun Da)": "6584.0", "Tần Suất % (Jun Da)": "99.9940037421", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 也", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻也", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "也", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "祂", "Unihan_Traditional (Chữ Phồn thể)": "祂", "Pinyin_Xie": "tā", "Âm Hán Việt_Xie": "tha", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Đại từ | 代词 | Chữ này làm đại từ nhân xưng ngôi thứ ba số ít để chỉ Thượng đế hoặc thần thánh. | Đại từ | 代词 | Thay cho người hoặc vật đã nhắc tới (我, 这, 谁). Dùng đúng ở vị trí của danh từ. Chỉ người thì thêm 们 để thành số nhiều: 我们.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('螵', '{"9000": "6585.0", "Chữ Trung Quốc": "螵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 17 | nét | 螵 | phiêu | tượng hình | nhộng, kén; chỉ trong 螵蛸 (trứng bọ ngựa) | 螵 thuộc bộ 虫 (côn trùng). Không có dữ liệu cấu trúc chi tiết trong CHISE. Chữ chủ yếu dùng trong 螵蛸 (phiêu tiêu, chỉ trứng/nhộng bọ ngựa). Chữ tạo muộn, chỉ có hình lục thư thông.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phiêu\": Côn trùng (虫) bay lơ lửng — 螵蛸 là túi trứng bọ ngựa, một vị thuốc trong đông y. Chữ tạo muộn. | Gương Hán-Việt | phiêu — xuất hiện trong đông y (螵蛸/phiêu tiêu) | Mở khoá kiến thức | Biết 螵 giúp đọc sách thuốc đông y về côn trùng học.", "Tự nguyên_Xie": "Lục thư thông | Không có dữ liệu nguồn gốc từ Wiktionary cho 螵. Chữ thuộc bộ 虫, dùng chủ yếu trong 螵蛸 — tên gọi trứng bọ ngựa (một vị thuốc đông y). Chữ tạo muộn, chưa thấy giáp cốt hay kim văn, chỉ có hình lục thư thông. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: phiêu sao 螵蛸)", "Hạng Tần Suất (Jun Da)": "6585.0", "Tần Suất % (Jun Da)": "99.994061622", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 票", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫票", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "票", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "螵", "Unihan_Traditional (Chữ Phồn thể)": "螵", "Pinyin_Xie": "piāo", "Âm Hán Việt_Xie": "phiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này hầu như chỉ xuất hiện trong từ ghép danh từ phiêu sao để chỉ tổ bọ ngựa dùng làm thuốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鸊', '{"9000": "6586.0", "Chữ Trung Quốc": "鸊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 24 | nét | 鸊 | tích | tượng hình | chim le le nước (Podiceps); chim bói cá | 鸊 thuộc bộ 鳥 (điểu, chim). Không có dữ liệu cấu trúc chi tiết trong CHISE hay Wiktionary. Chữ chỉ một loài chim nước (chim le le/grebe). Chữ tạo muộn, không thấy trong giáp cốt hay kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tích\": Chim (鳥) nước dẹp mình lặn xuống — 鸊 là chim le le, loài chim nước có khả năng lặn giỏi. Chưa có nguồn học thuật. | Gương Hán-Việt | tích — ít dùng trong tiếng Việt | Mở khoá kiến thức | Biết 鸊 giúp nhận diện tên loài chim trong văn bản sinh học tiếng Trung.", "Tự nguyên_Xie": "Không có dữ liệu nguồn gốc từ Wiktionary cho 鸊. Chữ thuộc bộ 鳥, chỉ loài chim le le nước (Podiceps ruficolus). Chữ tạo muộn, chưa có nguồn học thuật. Chỉ có bộ thủ và tên loài. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá bống tượng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "𡰪 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰𡰪", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "鸊", "Unihan_Traditional (Chữ Phồn thể)": "鸊", "Pinyin_Xie": "pì", "Âm Hán Việt_Xie": "bich", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng trong từ ghép bích đề để chỉ một loài chim chuyên lặn bắt cá. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鮡', '{"9000": "6587.0", "Chữ Trung Quốc": "鮡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 17 | nét | 鮡 | triệu | tượng hình | cá không vảy đầu dẹp sống ở suối (họ Sisoridae) | 鮡 thuộc bộ 魚 (ngư, cá). Không có dữ liệu cấu trúc chi tiết trong CHISE. Chữ chỉ họ cá Sisoridae (cá trê Á Đông, không vảy, đầu dẹp, sống ở suối đá). Có hình tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"triệu\": Cá (魚) sống dưới suối đá — 鮡 là loài cá da trơn không vảy thuộc họ Sisoridae, quen nước chảy xiết. Chưa có nguồn học thuật chi tiết. | Gương Hán-Việt | triệu — ít dùng trong tiếng Việt | Mở khoá kiến thức | Biết 鮡 giúp đọc tài liệu sinh vật học thuỷ sản tiếng Trung.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 鮡 chỉ họ cá Sisoridae — nhóm cá da trơn châu Á sống ở suối đá miền núi. Phát âm zhào. Chưa có phân tích cấu tạo chi tiết trong nguồn. Có hình tiểu triện. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(một loại cá, không vảy, phần đầu dẹp, sống ở suối)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 兆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚兆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鮡", "Unihan_Traditional (Chữ Phồn thể)": "鮡", "Pinyin_Xie": "zhào", "Âm Hán Việt_Xie": "triệu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này đóng vai trò là danh từ chỉ một loài cá nước ngọt nhỏ sống ở khe suối. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('禛', '{"9000": "6588.0", "Chữ Trung Quốc": "禛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 14 | nét | 禛 | trinh | tượng hình | được phúc nhờ thành tâm; bộ 示 | 禛 thuộc bộ 示 (thị, thần linh, tế lễ). Không có dữ liệu cấu trúc chi tiết trong CHISE. Chữ mang nghĩa được phúc lành nhờ lòng thành kính. Có hình tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trinh\": Bộ Thị (示, thần linh) — 禛 là người đủ thành tâm để nhận phúc lành từ trời. Nổi tiếng là tên vua Ung Chính (胤禛) triều Thanh. | Gương Hán-Việt | trinh — ít dùng trong tiếng Việt, chủ yếu trong tên người Hoa | Mở khoá kiến thức | Biết 禛 giúp nhận ra tên vua Ung Chính (胤禛) và các tên Hán cổ mang bộ 示.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 禛 mang nghĩa nhận phúc lành nhờ lòng thành tâm. Thuộc bộ 示. Có hình tiểu triện. Chữ nổi tiếng vì là tên vua Ung Chính triều Thanh (胤禛). Chưa có phân tích cấu tạo chi tiết. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "được phúc nhờ có lòng thành", "Hạng Tần Suất (Jun Da)": "6588.0", "Tần Suất % (Jun Da)": "99.9940859109", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 真", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻真", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "真", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "禛", "Unihan_Traditional (Chữ Phồn thể)": "禛", "Pinyin_Xie": "zhēn", "Âm Hán Việt_Xie": "chân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này thường dùng làm danh từ chỉ điềm lành hoặc tính từ trong tên người thể hiện sự chân thành. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('袆', '{"9000": "6589.0", "Chữ Trung Quốc": "袆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 9 | nét | 衣 | y | biểu nghĩa | áo, y phục | 韋 | vi | biểu âm | da thuộc mềm | 袆 = 衣 (Y, biểu nghĩa: y phục) + 韋 (Vi, biểu âm); chữ hình thanh. Phần 衣 chỉ đây là loại áo lễ phục, phần 韋 cho biết âm đọc huī. Chữ có từ giáp cốt văn — là áo lễ của hoàng hậu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huy\": Áo (衣) đẹp như da thuộc quý (韋) — 袆 là áo lễ dành riêng cho hoàng hậu, biểu tượng uy nghi cung đình. Có hình giáp cốt văn. | Gương Hán-Việt | huy — ít dùng trong tiếng Việt, xuất hiện trong sử sách về cung đình Trung Hoa | Mở khoá kiến thức | Biết 袆 giúp đọc sử liệu về trang phục nghi lễ hoàng tộc Trung Hoa cổ đại.", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | Theo Wiktionary (dạng chuẩn 褘), 袆 là chữ hình thanh: 衣 (biểu nghĩa, y phục) kết hợp với 韋 (biểu âm). Chỉ loại áo lễ của hoàng hậu, thêu hình đuôi phượng. Có hình giáp cốt văn và tiểu triện — chứng tỏ chữ rất cổ, liên quan trang phục cung đình từ thời sớm. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đẹp; áo tế của hoàng hậu", "Hạng Tần Suất (Jun Da)": "6589.0", "Tần Suất % (Jun Da)": "99.9940936627", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 韦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤韦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "韦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "袆", "Unihan_Traditional (Chữ Phồn thể)": "褘", "Pinyin_Xie": "huī", "Âm Hán Việt_Xie": "huy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ trang phục tế lễ của hoàng hậu hoặc tính từ chỉ sự tốt đẹp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('謴', '{"9000": "6590.0", "Chữ Trung Quốc": "謴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 18 | nét | 言 | ngôn | biểu nghĩa | lời nói, ngôn ngữ | 貫 | quan | biểu âm | xuyên suốt, tiền đồng | 謴 = 言 (Ngôn, biểu nghĩa: lời nói) + 貫 (Quan, biểu âm); chữ hình thanh. Phần 言 chỉ đây là hoạt động lời nói, phần 貫 cho biết âm đọc gùn. Nghĩa: đùa giỡn, trêu chọc bằng lời.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cun\": Lời nói (言) xuyên thấu (貫) như mũi tên — 謴 là trêu chọc, đùa cợt bằng ngôn từ sắc sảo. Hình thanh: 言 nghĩa + 貫 âm. | Gương Hán-Việt | ít dùng trong tiếng Việt | Mở khoá kiến thức | Biết 謴 giúp đọc văn cổ miêu tả những cuộc đối đáp dí dỏm, bỡn cợt bằng lời.", "Tự nguyên_Xie": "Theo Wiktionary, 謴 là chữ hình thanh: 言 (biểu nghĩa, lời nói) kết hợp với 貫 (biểu âm). Nghĩa cổ là đùa giỡn, trêu cợt bằng lời. Có hình tiểu triện trong nguồn hanziyuan. Chữ cổ, ít dùng trong văn bản hiện đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thắng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 貫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言貫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "貫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "謴", "Unihan_Traditional (Chữ Phồn thể)": "謴", "Pinyin_Xie": "gùn", "Âm Hán Việt_Xie": "cun", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này là động từ cổ dùng để chỉ hành vi đùa cợt hoặc lừa gạt người khác. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('邾', '{"9000": "6591.0", "Chữ Trung Quốc": "邾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 8 | nét | 朱 | chu | biểu âm | màu đỏ son | 邑 | ấp | biểu nghĩa | vùng đất, khu dân cư | 邾 = 朱 (Chu, biểu âm) + 邑 (Ấp, biểu nghĩa: vùng đất, khu dân cư); chữ hình thanh. Phần 邑 chỉ đây là địa danh, phần 朱 cho biết âm đọc zhū. Là tên nước chư hầu thời Xuân Thu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"châu\": Đất ấp (邑) mang màu son chu (朱) — 邾 là tên nước Chu chư hầu thời Xuân Thu, sau đổi thành Trâu (鄒) — quê hương của Mạnh Tử. | Gương Hán-Việt | châu trong địa danh cổ Trung Hoa, ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 邾 giúp đọc sử sách về các nước chư hầu thời Xuân Thu Chiến Quốc.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | Theo Wiktionary, 邾 là chữ hình thanh: 朱 (biểu âm) kết hợp với 邑 (biểu nghĩa, vùng đất). Chỉ tên nước Chu (邾, sau đổi thành Trâu 鄒) — nước chư hầu thời Xuân Thu, nay thuộc tỉnh Sơn Đông. Có hình kim văn và tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Chu", "Hạng Tần Suất (Jun Da)": "6591.0", "Tần Suất % (Jun Da)": "99.9941091662", "GavinGrover_Once (Chiết tự trực tiếp)": "朱 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰朱阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "朱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "邾", "Unihan_Traditional (Chữ Phồn thể)": "邾", "Pinyin_Xie": "zhū", "Âm Hán Việt_Xie": "chu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này là danh từ riêng chỉ một nước chư hầu cổ ở Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鮣', '{"9000": "6592.0", "Chữ Trung Quốc": "鮣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 16 | nét | 魚 | ngư | biểu nghĩa | cá | 印 | an | biểu âm | ấn, in | 鮣 = 魚 (Ngư, biểu nghĩa: cá) + 印 (An/Ấn, biểu âm); chữ hình thanh. Phần 魚 chỉ đây là loài cá, phần 印 cho biết âm đọc yìn. Là cá remora (cá hút đĩa).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ấn\": Cá (魚) in (印) đĩa hút lên lưng cá lớn — 鮣 là cá remora, bám vào cá mập để đi xa. Hình thanh: 魚 nghĩa + 印 âm. | Gương Hán-Việt | ấn — ít dùng trong tiếng Việt | Mở khoá kiến thức | Biết 鮣 giúp đọc tài liệu sinh học biển tiếng Trung về loài cá cộng sinh.", "Tự nguyên_Xie": "Theo Wiktionary, 鮣 là chữ hình thanh: 魚 (biểu nghĩa, cá) kết hợp với 印 (biểu âm). Chỉ loài cá remora (suckerfish) — cá có đĩa hút trên đầu, bám vào cá lớn hơn để di chuyển. Phát âm yìn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鮮", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 印", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚印", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "印", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "䲟", "Unihan_Traditional (Chữ Phồn thể)": "鮣", "Pinyin_Xie": "yìn", "Âm Hán Việt_Xie": "an", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài cá có giác bám chuyên đi theo tàu thuyền hoặc cá lớn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('酲', '{"9000": "6593.0", "Chữ Trung Quốc": "酲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 14 | nét | 酲 | xành | tượng hình | cơn say rượu, trạng thái nghiện rượu | 酲 thuộc bộ 酉 (dậu, rượu). Không có dữ liệu cấu trúc chi tiết trong CHISE. Chữ chỉ trạng thái say sưa, cơn ngây rượu. Có hình tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xành\": Bộ Dậu (酉, rượu) — 酲 là cơn say ngây ngất sau khi uống, trạng thái mờ nhạt không tỉnh táo. Nổi tiếng trong 憂心如酲. | Gương Hán-Việt | xành — ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 酲 giúp đọc thơ cổ và thành ngữ về trạng thái say rượu.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 酲 mang nghĩa trạng thái say rượu, ngây ngất. Thuộc bộ 酉 liên quan đến rượu. Có hình tiểu triện. Gặp trong thành ngữ 憂心如酲 (lo âu như kẻ ngây rượu). Chưa có phân tích cấu tạo chi tiết. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nghiện rượu, cơn say", "Hạng Tần Suất (Jun Da)": "6593.0", "Tần Suất % (Jun Da)": "99.9941246698", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 呈", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉呈", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "呈", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "酲", "Unihan_Traditional (Chữ Phồn thể)": "酲", "Pinyin_Xie": "chéng", "Âm Hán Việt_Xie": "trình", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ trạng thái mệt mỏi sau khi tỉnh rượu hoặc tính từ chỉ sự say sưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('龁', '{"9000": "6594.0", "Chữ Trung Quốc": "龁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 齒 | Số nét | 11 | nét | 龁 | ngật | tượng hình | cắn, gặm; dạng giản thể của 齕 | 龁 là dạng giản thể của 齕 (ngật, cắn), thuộc bộ 齿 (răng). Dạng phồn thể 齕 = 齒 (biểu nghĩa, răng) + cấu phần biểu âm. Nghĩa là dùng răng cắn, gặm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngật\": Răng (齒) cắn gặm — 龁 là hành động nhai gặm, dùng răng nghiền. Hình ảnh ngựa gặm cỏ (齕草). | Gương Hán-Việt | ngật — ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 龁 giúp đọc văn học cổ Trung Hoa miêu tả ngựa và động vật ăn cỏ.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 龁 là dạng giản thể của 齕. Dạng phồn thể 齕 thuộc bộ 齒 (răng), chỉ hành động cắn, gặm. Có hình đại triện và tiểu triện. Chữ cổ điển, thường dùng trong văn học miêu tả ngựa gặm cỏ. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cắn", "Hạng Tần Suất (Jun Da)": "6594.0", "Tần Suất % (Jun Da)": "99.9941324216", "GavinGrover_Once (Chiết tự trực tiếp)": "齿 + 乞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰齿乞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "齿", "Unihan_Simplified (Chữ Giản thể)": "龁", "Unihan_Traditional (Chữ Phồn thể)": "齕", "Pinyin_Xie": "hé", "Âm Hán Việt_Xie": "hột", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động cắn hoặc gặm thức ăn của động vật. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('汔', '{"9000": "6595.0", "Chữ Trung Quốc": "汔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 6 | nét | 汔 | ngật | tượng hình | gần, hầu như; nước cạn | 汔 thuộc bộ 水 (thuỷ, nước). Không có dữ liệu cấu trúc chi tiết trong CHISE (chỉ có {{Han etym}} rỗng). Chữ mang nghĩa hầu như, gần như; nước cạn kiệt. Có hình tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngật\": Nước (水) gần cạn — 汔 là hầu như, gần đến mức nước sắp hết. Xuất hiện trong Kinh Thi cổ đại. | Gương Hán-Việt | ngật — ít dùng trong tiếng Việt | Mở khoá kiến thức | Biết 汔 giúp đọc Kinh Thi và thơ văn cổ điển Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 汔 có nghĩa là gần, hầu như; nước cạn. Thuộc bộ 水. Có hình tiểu triện. Gặp trong thơ cổ Kinh Thi (汔可小息, gần có thể nghỉ một chút). Chưa có phân tích cấu tạo chi tiết. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gần, gần như, hầu như; nước cạn; tận, hết; đến, cuối cùng, sau cùng", "Hạng Tần Suất (Jun Da)": "6595.0", "Tần Suất % (Jun Da)": "99.9941401734", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 乞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵乞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "汔", "Unihan_Traditional (Chữ Phồn thể)": "汔", "Pinyin_Xie": "qì", "Âm Hán Việt_Xie": "ngật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Tính từ | 形容词 | Chữ này thường làm phó từ đứng trước động từ để biểu thị trạng thái gần đạt được. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('眄', '{"9000": "6596.0", "Chữ Trung Quốc": "眄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 9 | nét | 眄 | miện | tượng hình | nhìn nghiêng, liếc mắt | 眄 thuộc bộ 目 (mục, mắt). Không có dữ liệu cấu trúc chi tiết trong CHISE. Chữ mang nghĩa nhìn nghiêng, liếc mắt. Chưa xác định hình thanh hay hội ý từ nguồn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"miện\": Mắt (目) lướt nghiêng — 眄 là liếc nhìn, ánh mắt thoáng qua nghiêng ngó. Xuất hiện nhiều trong thơ tình cổ điển. | Gương Hán-Việt | miện — ít dùng trong tiếng Việt, xuất hiện trong văn học cổ | Mở khoá kiến thức | Biết 眄 giúp đọc thơ cổ điển Trung Hoa miêu tả ánh mắt và tình cảm qua ánh nhìn.", "Tự nguyên_Xie": "Theo Wiktionary, 眄 có nghĩa là nhìn nghiêng, liếc nhìn từ một bên. Thuộc bộ 目. Dùng phổ biến trong thơ cổ điển. Không có phân tích cấu tạo chi tiết trong nguồn. Gặp trong 眄睞 (liếc nhìn), 恩眄 (ân tình trong ánh mắt). | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trông, liếc", "Hạng Tần Suất (Jun Da)": "6596.0", "Tần Suất % (Jun Da)": "99.9941479251", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 丏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目丏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "眄", "Unihan_Traditional (Chữ Phồn thể)": "眄", "Pinyin_Xie": "miǎn", "Âm Hán Việt_Xie": "miện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường làm động từ chỉ hành động liếc mắt hoặc nhìn nghiêng trong văn ngôn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('眊', '{"9000": "6597.0", "Chữ Trung Quốc": "眊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 9 | nét | 眊 | mạo | tượng hình | mờ mắt, mù quáng; lú lẫn | 眊 thuộc bộ 目 (mục, mắt). Không có dữ liệu cấu trúc chi tiết trong CHISE. Chữ mang nghĩa mắt mờ, thị lực kém, lú lẫn. Có hình tiểu triện và lục thư thông.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mạo\": Mắt (目) mờ dần như màn che — 眊 là thị lực lờ mờ, mê muội, hình ảnh tuổi già mắt kém. Cũng là dị thể của 耄 (người rất già). | Gương Hán-Việt | mạo — ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 眊 giúp đọc văn cổ miêu tả tuổi già, thị lực kém và sự lú lẫn.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 眊 có nghĩa là mờ mắt, không nhìn rõ; lú lẫn, mơ hồ. Thuộc bộ 目. Cũng là dị thể cổ của 旄 (cờ đuôi ngựa) và 耄 (tuổi trên 80). Có hình tiểu triện. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mờ, nhập nhèm", "Hạng Tần Suất (Jun Da)": "6597.0", "Tần Suất % (Jun Da)": "99.9941556769", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 毛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目毛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "毛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "眊", "Unihan_Traditional (Chữ Phồn thể)": "眊", "Pinyin_Xie": "mào", "Âm Hán Việt_Xie": "mạo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ mô tả trạng thái mắt mờ của người già hoặc tinh thần suy nhược. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鬲', '{"9000": "6598.0", "Chữ Trung Quốc": "鬲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鬲 | Số nét | 10 | nét | 鬲 | lịch | tượng hình | đỉnh ba chân rỗng; loại nồi cổ đại | 鬲 là chữ tượng hình, phác thảo hình dáng chiếc đỉnh (nồi nấu) ba chân rỗng thời cổ đại. Có thể nhận ra phần thân và ba chân từ hình giáp cốt văn và kim văn. Chữ cũng là bộ thủ 193 trong Khang Hy tự điển.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lịch\": Ba chân rỗng (鬲) đỡ thân nồi — 鬲 là chiếc đỉnh nấu cổ đại ba chân rỗng, hình tượng hoá đồ dùng sinh hoạt từ thời đồ đồng. | Gương Hán-Việt | lịch — ít dùng trong tiếng Việt, chủ yếu trong khảo cổ học | Mở khoá kiến thức | Biết 鬲 giúp đọc sách khảo cổ và lịch sử đồ gốm/đồng Trung Hoa cổ đại.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Theo Wiktionary, 鬲 là chữ tượng hình mô tả chiếc đỉnh ba chân rỗng (li) — dụng cụ nấu ăn và tế lễ thời cổ. Có hai cách đọc chính: lì (đỉnh nấu ăn, dùng trong tang lễ) và gé (dị thể của 隔/膈). Có hình giáp cốt văn và kim văn — một trong những chữ cổ nhất. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1475.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hình ảnh cái nồi, cái đỉnh ba chân để nấu thức ăn thời cổ đại. Giải thích sự chuyển ý: Đây là chữ Tượng hình. Lịch là dụng cụ để nấu ăn hầm chín thức ăn thời xưa có 3 chân rỗng. Đây là bộ thủ thứ 193 trong 214 bộ thủ Khang Hy.", "Nghĩa Tiếng Việt_Xie": "một đồ để đựng giống cái đỉnh", "Hạng Tần Suất (Jun Da)": "6598.0", "Tần Suất % (Jun Da)": "99.9941634287", "GavinGrover_Once (Chiết tự trực tiếp)": "𠮛 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱𠮛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "鬲", "Unihan_Traditional (Chữ Phồn thể)": "鬲", "Pinyin_Xie": "gé", "Âm Hán Việt_Xie": "cách, lịch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loại dụng cụ nấu ăn bằng đất nung thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('阨', '{"9000": "6599.0", "Chữ Trung Quốc": "阨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 6 | nét | 阨 | ách | tượng hình | gặp nạn, chỗ hiểm trở; bộ 阜 | 阨 thuộc bộ 阜 (phụ, đất cao, đê). Không có dữ liệu cấu trúc chi tiết từ CHISE. Chữ mang nghĩa gặp hoạn nạn, đường hiểm trở, chỗ tắc nghẽn. Chưa có nguồn học thuật rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ách\": Đất cao (阜) chắn đường — 阨 là chỗ hiểm yếu, ải đường khó qua. Liên quan đến 厄 (khốn ách, nạn). Chưa có nguồn học thuật. | Gương Hán-Việt | ách trong ách tắc, khó ách — ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 阨 giúp đọc văn cổ và binh thư về địa hình hiểm yếu.", "Tự nguyên_Xie": "Không có dữ liệu nguồn gốc từ Wiktionary cho 阨. Chữ thuộc bộ 阜 (đất cao), mang nghĩa chỗ hiểm trở, khó khăn, nguy cấp. Có liên quan đến các chữ 厄, 隘. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "làm ô uế; gặp nạn; đi qua", "Hạng Tần Suất (Jun Da)": "6599.0", "Tần Suất % (Jun Da)": "99.9941711805", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + 厄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝厄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "厄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "阨", "Unihan_Traditional (Chữ Phồn thể)": "阨", "Pinyin_Xie": "è", "Âm Hán Việt_Xie": "ách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Danh từ | 名词 | Thường làm tính từ chỉ sự hiểm trở hoặc động từ chỉ sự cản trở, khốn đốn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('靸', '{"9000": "6600.0", "Chữ Trung Quốc": "靸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 革 | Số nét | 12 | nét | 靸 | táp | tượng hình | kéo lê giày; dép đế phẳng; giày trẻ em | 靸 thuộc bộ 革 (cách, da thuộc). Không có dữ liệu cấu trúc chi tiết từ CHISE (chỉ {{Han etym}} rỗng). Chữ liên quan đến dép, giày đế phẳng và cách đi lê thê. Có hình tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"táp\": Da (革) kéo lê trên đất — 靸 là đôi dép đế mỏng kéo lê, hoặc đi dép chân bước lướt. Có hình tiểu triện. | Gương Hán-Việt | táp — ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 靸 giúp đọc văn học cổ Trung Hoa miêu tả cách đi đứng và trang phục đôi chân.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 靸 mang nghĩa giày trẻ em đế mỏng, hoặc cách đi lê bước chân kéo giày. Thuộc bộ 革 (da thuộc). Có hình tiểu triện. Chưa có phân tích cấu tạo chi tiết. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lê, kéo lê; giày, dép", "Hạng Tần Suất (Jun Da)": "6600.0", "Tần Suất % (Jun Da)": "99.9941789322", "GavinGrover_Once (Chiết tự trực tiếp)": "革 + 及", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰革及", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "及", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "革", "Unihan_Simplified (Chữ Giản thể)": "靸", "Unihan_Traditional (Chữ Phồn thể)": "靸", "Pinyin_Xie": "sǎ", "Âm Hán Việt_Xie": "táp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm động từ chỉ hành động đi giày lê gót hoặc danh từ chỉ loại giày dép nhẹ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('酺', '{"9000": "6601.0", "Chữ Trung Quốc": "酺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 14 | nét | 酺 | bồ | tượng hình | tụ tập uống rượu; tiệc rượu chung | 酺 thuộc bộ 酉 (dậu, rượu). Không có dữ liệu cấu trúc chi tiết từ CHISE. Chữ mang nghĩa tụ tập cùng uống rượu, tiệc rượu chung. Có hình tiểu triện và lục thư thông.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bồ\": Bộ Dậu (酉, rượu) — 酺 là bữa tiệc rượu chung, khi nhiều người cùng tụ tập vui uống. Hình ảnh lễ hội mùa màng cổ đại. | Gương Hán-Việt | bồ — ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 酺 giúp đọc văn học cổ Trung Hoa về lễ hội và tiệc tùng dân gian.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 酺 có nghĩa là cùng nhau uống rượu, uống nhiều. Thuộc bộ 酉. Có hình tiểu triện và lục thư thông. Chưa có phân tích cấu tạo chi tiết trong nguồn. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tụ tập uống rượu", "Hạng Tần Suất (Jun Da)": "6601.0", "Tần Suất % (Jun Da)": "99.9942021876", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 甫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉甫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "酺", "Unihan_Traditional (Chữ Phồn thể)": "酺", "Pinyin_Xie": "pú", "Âm Hán Việt_Xie": "bô, bồ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ việc vua ban phép cho dân chúng tụ tập uống rượu vui chơi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('狃', '{"9000": "6602.0", "Chữ Trung Quốc": "狃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 7 | nét | 犬 | khuyển | biểu nghĩa | chó, thú vật | 丑 | sửu | biểu âm | móng vuốt thú, can chi Sửu | 狃 = 犬 (Khuyển, biểu nghĩa: chó, thú) + 丑 (Sửu, biểu âm: móng vuốt); chữ hình thanh kiêm hội ý. Phần 犬 gợi hành vi bản năng như thú vật, phần 丑 (móng vuốt thú) cho biết âm và gợi thói quen theo dấu chân cũ — con thú quen theo vết cũ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nữu\": Chó (犬) cứ theo dấu móng cũ (丑) — 狃 là thói quen nhờn, cứ lặp lại hành vi cũ như thú vật đi theo vết mòn. | Gương Hán-Việt | nữu trong quen nhờn, lờn mặt — ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 狃 giúp đọc văn học cổ miêu tả thói quen xấu, lờn mặt, bám víu vào lề cũ.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 狃 là chữ hình thanh kiêm hội ý: 犬 (chó, biểu nghĩa) + 丑 (móng vuốt thú, biểu âm và biểu ý) — gợi hình ảnh dấu chân thú vật. Nghĩa là quen thuộc, quen làm, cũng mang nghĩa tham muốn, bám víu vào thói cũ. Có hình tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhờn, quen", "Hạng Tần Suất (Jun Da)": "6602.0", "Tần Suất % (Jun Da)": "99.9942099394", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 丑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭丑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "狃", "Unihan_Traditional (Chữ Phồn thể)": "狃", "Pinyin_Xie": "niǔ", "Âm Hán Việt_Xie": "nữu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ chỉ sự quen nhờn hoặc tính từ chỉ thói quen xấu khó bỏ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('轺', '{"9000": "6603.0", "Chữ Trung Quốc": "轺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 9 | nét | 轺 | diêu | tượng hình | xe ngựa nhỏ nhẹ; dạng giản thể của 軺 | 轺 là dạng giản thể của 軺 (diêu), thuộc bộ 車 (xa, xe cộ). Dạng phồn thể 軺 = 車 (biểu nghĩa) + phần biểu âm. Chỉ loại xe ngựa nhỏ, nhẹ dùng để di chuyển nhanh. Có hình tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"diêu\": Xe (車) nhỏ nhẹ như cánh diều — 轺 là loại xe ngựa nhẹ, nhanh nhẹn dùng cho sứ thần và quan lại. Có hình tiểu triện. | Gương Hán-Việt | diêu — ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 轺 giúp đọc sử liệu và văn học cổ Trung Hoa về phương tiện di chuyển của quan lại.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 軺 chỉ loại xe ngựa nhỏ nhẹ dùng để đi lại nhanh. Thuộc bộ 車. Có hình tiểu triện. 轺 là dạng giản thể hiện đại. Gặp trong 軺車 (xe nhẹ) và văn học cổ miêu tả sứ thần đi xe. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xe ngựa", "Hạng Tần Suất (Jun Da)": "6603.0", "Tần Suất % (Jun Da)": "99.9942176911", "GavinGrover_Once (Chiết tự trực tiếp)": "车 + 召", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰车召", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "召", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "车", "Unihan_Simplified (Chữ Giản thể)": "轺", "Unihan_Traditional (Chữ Phồn thể)": "軺", "Pinyin_Xie": "yáo", "Âm Hán Việt_Xie": "diêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ loại xe nhỏ nhẹ do một ngựa kéo thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('霅', '{"9000": "6604.0", "Chữ Trung Quốc": "霅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 雨 | Số nét | 15 | nét | 霅 | chap | tượng hình | chữ độc thể, tự thân là ký hiệu âm thanh sấm chớp | 霅 là chữ độc thể không phân tích được thành các thành phần rõ ràng trong dữ liệu hiện có. Chưa có nguồn học thuật xác nhận cấu trúc bộ thủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chap\": hình ảnh ánh chớp *chớp* qua bầu trời tối — âm \"chap\" bắt chước tiếng nổ ngắn gọn của sấm sét. | Gương Hán-Việt | chap — âm Hán-Việt hiếm dùng trong văn ngữ cổ | Mở khoá kiến thức | Biết 霅 mở khoá các từ cổ điển mô tả tiếng sấm chớp, ánh chớp giữa cơn mưa", "Tự nguyên_Xie": "霅 mang âm Hán-Việt *chap*, phản ánh âm Middle Chinese cổ đại liên quan đến ánh chớp và tiếng sấm. Nguồn gốc tự hình chưa được tài liệu học thuật xác nhận đầy đủ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bỗng, chợt, thình lình; nhanh chóng", "Hạng Tần Suất (Jun Da)": "6604.0", "Tần Suất % (Jun Da)": "99.9942254429", "GavinGrover_Once (Chiết tự trực tiếp)": "雨 + 言", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱雨言", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "言", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "雨", "Unihan_Simplified (Chữ Giản thể)": "霅", "Unihan_Traditional (Chữ Phồn thể)": "霅", "Pinyin_Xie": "zhà", "Âm Hán Việt_Xie": "tráp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Từ tượng thanh | 象声词 | Thường làm tính từ mô tả sự xuất hiện đột ngột hoặc từ mô phỏng âm thanh mưa gió. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鬂', '{"9000": "6605.0", "Chữ Trung Quốc": "鬂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 髟 | Số nét | 17 | nét | 鬂 | bấn | tượng hình | tóc mai hai bên thái dương; tục tự của 鬢, bộ 髟 | 鬂 thuộc bộ 髟 (biêu, tóc dài), không có cấu trúc phân tích liushu trong Wiktionary. Là tục tự của 鬢 (bấn), chỉ tóc mai mọc bên thái dương.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bấn\": bộ 髟 (tóc dài) ôm lấy 髟 — tóc mai \"bấn\" sát hai bên thái dương, mái tóc rủ bên tai. | Gương Hán-Việt | Chữ 鬂 (bấn) xuất hiện trong văn cổ chỉ tóc mai, biến thể của 鬢. | Mở khoá kiến thức | Biết 鬂 (bấn) mở khoá nhóm bộ 髟 chỉ các loại tóc: 髦 (mao), 髯 (nhiêm), 髻 (kế).", "Tự nguyên_Xie": "Chữ 鬂 thuộc bộ 髟 (biêu, chỉ tóc). Wiktionary không có glyph-origin cho chính chữ này; đây là tục tự của 鬢 (bấn). Không có nguồn học thuật phân tích lịch sử tạo tự riêng cho 鬂. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bấn; như \"bấn bíu\" bẩn; như \"bẩn thỉu\" mấn; như \"mấn (tóc mai; tóc bên mái tai)\" \nTục dùng như chữ tấn; mấn 鬢.", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "髟 + 兵", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱髟兵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兵", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "髟", "Unihan_Simplified (Chữ Giản thể)": "鬂", "Unihan_Traditional (Chữ Phồn thể)": "鬂", "Pinyin_Xie": "bìn", "Âm Hán Việt_Xie": "tấn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ phần tóc ở hai bên tai của con người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鼷', '{"9000": "6606.0", "Chữ Trung Quốc": "鼷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鼠 | Số nét | 23 | nét | 鼷 | he | tượng hình | chữ độc thể chỉ loài chuột nhỏ | 鼷 là chữ độc thể, bộ thủ gốc là 鼠 (thử, chuột). Cấu trúc hình thanh hoặc hội ý cụ thể chưa được tài liệu học thuật xác nhận đầy đủ. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"he\": con chuột *he* nhỏ xíu cứ len lén chui vào hang — âm \"he\" nghe như tiếng chuột rúc nhỏ. | Gương Hán-Việt | he — xuất hiện trong 鼷鼠 (he thử: chuột nhỏ) | Mở khoá kiến thức | Biết 鼷 mở khoá tên gọi cổ điển cho các loài gặm nhấm nhỏ trong văn ngữ cổ Hán", "Tự nguyên_Xie": "鼷 mang âm Middle Chinese *hɛj*, tương ứng âm Hán-Việt *he*. Chữ thuộc nhóm danh từ chỉ loài gặm nhấm nhỏ trong cổ văn. Wiktionary ghi nhận âm Quảng Đông *hai4*, phản ánh cùng gốc âm cổ. Chưa có nguồn học thuật đầy đủ về tự hình. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chuột nhắt", "Hạng Tần Suất (Jun Da)": "6606.0", "Tần Suất % (Jun Da)": "99.9942409465", "GavinGrover_Once (Chiết tự trực tiếp)": "鼠 + 奚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鼠奚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鼠", "Unihan_Simplified (Chữ Giản thể)": "鼷", "Unihan_Traditional (Chữ Phồn thể)": "鼷", "Pinyin_Xie": "xī", "Âm Hán Việt_Xie": "hề", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài chuột nhỏ, thường xuất hiện trong từ ghép hề thử. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蠃', '{"9000": "6607.0", "Chữ Trung Quốc": "蠃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 19 | nét | 蠃 | la | tượng hình | chữ độc thể chỉ loài sâu bọ cuộn tròn trong vỏ | 蠃 là chữ có bộ 虫 (trùng) nhưng cấu trúc hình thanh hoặc hội ý cụ thể chưa được dữ liệu học thuật xác nhận. Chưa có nguồn học thuật về tự hình.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"la\": con ốc *la* vác cái vỏ to tướng trên lưng đi chậm chạp — âm \"la\" ngắn gọn như tiếng kêu của nó. | Gương Hán-Việt | la — xuất hiện trong văn cổ chỉ loài ốc sên hoặc nhộng tằm | Mở khoá kiến thức | Biết 蠃 mở khoá cách đọc cổ điển của các chữ chỉ côn trùng và nhộng trong cổ văn", "Tự nguyên_Xie": "蠃 mang âm Hán-Việt *la*, phản ánh âm Middle Chinese cổ đại. Chữ dùng trong cổ văn để chỉ loài ốc sên (con la) hoặc nhộng tằm. Nguồn gốc tự hình chưa được tài liệu học thuật xác nhận đầy đủ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con tò vò (một loại ong sống ký sinh)", "Hạng Tần Suất (Jun Da)": "6607.0", "Tần Suất % (Jun Da)": "99.9942486982", "GavinGrover_Once (Chiết tự trực tiếp)": "𣎆 + 虫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴𣎆虫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𣎆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蠃", "Unihan_Traditional (Chữ Phồn thể)": "蠃", "Pinyin_Xie": "luǒ", "Âm Hán Việt_Xie": "loả", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài tò vò, thường dùng trong từ ghép quả la. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('埴', '{"9000": "6608.0", "Chữ Trung Quốc": "埴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 11 | nét | 土 | thổ | biểu nghĩa | đất | 直 | trực | biểu âm | thẳng (cho âm) | 埴 = 土 (Thổ, biểu nghĩa: đất) + 直 (Trực, biểu âm); chữ hình thanh. Thổ cho nghĩa (đất), Trực cho âm gốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thuc\": đất sét *thục* nhào kỹ — người thợ gốm *trực tiếp* (Trực) dùng *đất* (Thổ) nắn thành bình. | Gương Hán-Việt | thuc — xuất hiện trong 埴土 (thục thổ: đất sét mịn) | Mở khoá kiến thức | Biết 埴 mở khoá thuật ngữ cổ về đất sét và nghề gốm trong cổ văn Hán", "Tự nguyên_Xie": "埴 mang âm Middle Chinese *d͡ʑɨk*, tương ứng âm Hán-Việt *thục*. Chữ hình thanh gồm 土 (đất) làm phần biểu nghĩa và 直 làm phần biểu âm. Dùng trong cổ văn chỉ loại đất sét mịn dùng làm gốm. Wiktionary ghi nhận âm Quảng Đông *zik6*. Chưa có nguồn học thuật đầy đủ về tự hình qua Wiktionary. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đất thó, đất sét", "Hạng Tần Suất (Jun Da)": "6608.0", "Tần Suất % (Jun Da)": "99.99425645", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 直", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土直", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "直", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "埴", "Unihan_Traditional (Chữ Phồn thể)": "埴", "Pinyin_Xie": "zhí", "Âm Hán Việt_Xie": "thực", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loại đất sét mịn dùng để nặn đồ gốm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鴥', '{"9000": "6609.0", "Chữ Trung Quốc": "鴥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 16 | nét | 鴥 | uat | tượng hình | chữ độc thể chỉ hành động chim bay nhanh, lao xuống | 鴥 là chữ có bộ 鳥 (điểu, chim) nhưng cấu trúc hình thanh hoặc hội ý cụ thể chưa được dữ liệu học thuật xác nhận rõ ràng. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uat\": chim *vút* lao xuống — âm \"uat\" ngắn gọn như tiếng gió khi cánh chim xé không khí. | Gương Hán-Việt | uat — xuất hiện trong thơ cổ mô tả chim bay vụt nhanh | Mở khoá kiến thức | Biết 鴥 mở khoá cách đọc cổ điển mô tả chim bay nhanh trong Kinh Thi", "Tự nguyên_Xie": "鴥 mang âm Middle Chinese *wɨt*, tương ứng âm Hán-Việt *uat*. Âm Quảng Đông *wat6/jyut6*, Mân Nam *u̍t* theo Wiktionary. Chữ dùng trong Kinh Thi mô tả chim bay vụt lao xuống nhanh. Nguồn gốc tự hình chưa được tài liệu học thuật xác nhận đầy đủ. Chưa có nguồn học thuật. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vun vút (chim bay rất nhanh)", "Hạng Tần Suất (Jun Da)": "6609.0", "Tần Suất % (Jun Da)": "99.9942642018", "GavinGrover_Once (Chiết tự trực tiếp)": "鳥 + 穴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鳥穴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "穴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鴥", "Unihan_Traditional (Chữ Phồn thể)": "鴥", "Pinyin_Xie": "yù", "Âm Hán Việt_Xie": "duật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Phó từ | 副词 | Chữ này làm tính từ hoặc phó từ mô tả trạng thái chim bay nhanh vút qua. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('髆', '{"9000": "6610.0", "Chữ Trung Quốc": "髆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 骨 | Số nét | 19 | nét | 骨 | cốt | biểu nghĩa | xương | 尃 | phô | biểu âm | phân tán, trải rộng (cho âm) | 髆 = 骨 (Cốt, biểu nghĩa: xương) + 尃 (Phô, biểu âm); chữ hình thanh. Cốt cho nghĩa (xương cơ thể), Phô cho âm gốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bac\": *xương* (Cốt) bả vai rộng *bác* ra — hình ảnh người vác nặng, vai bè rộng như tấm gỗ phẳng. | Gương Hán-Việt | bac — xuất hiện trong 髆骨 (bác cốt: xương bả vai) | Mở khoá kiến thức | Biết 髆 mở khoá thuật ngữ giải phẫu cổ về xương bả vai và vai trong y học cổ truyền Hán", "Tự nguyên_Xie": "髆 là chữ hình thanh gồm 骨 (cốt, xương) làm phần biểu nghĩa và 尃 làm phần biểu âm, theo Wiktionary. Âm Hán-Việt *bác* phản ánh Middle Chinese cổ đại. Chữ dùng trong y học cổ truyền chỉ xương bả vai (scapula). Chưa có nguồn học thuật đầy đủ về tự hình qua Wiktionary. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vai", "Hạng Tần Suất (Jun Da)": "6610.0", "Tần Suất % (Jun Da)": "99.9942797053", "GavinGrover_Once (Chiết tự trực tiếp)": "骨 + 尃", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰骨尃", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "骨", "Unihan_Simplified (Chữ Giản thể)": "髆", "Unihan_Traditional (Chữ Phồn thể)": "髆", "Pinyin_Xie": "bó", "Âm Hán Việt_Xie": "bác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bộ phận xương bả vai của người hoặc động vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('膮', '{"9000": "6611.0", "Chữ Trung Quốc": "膮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 16 | nét | 肉 | nhục | biểu nghĩa | thịt | 堯 | nghiêu | biểu âm | cao ngất, tên vua (cho âm) | 膮 = 肉 (Nhục, biểu nghĩa: thịt) + 堯 (Nghiêu, biểu âm); chữ hình thanh. Nhục cho nghĩa (món thịt), Nghiêu cho âm gốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hieu\": nồi canh *thịt* (Nhục) bốc hơi *hiêu* lên cao như núi Nghiêu — mùi thơm lan xa. | Gương Hán-Việt | hieu — xuất hiện trong văn cổ chỉ món canh thịt | Mở khoá kiến thức | Biết 膮 mở khoá thuật ngữ ẩm thực cổ điển về các món canh thịt trong lễ nghi Hán", "Tự nguyên_Xie": "膮 là chữ hình thanh gồm 肉 (nhục, thịt) làm phần biểu nghĩa và 堯 làm phần biểu âm, theo Wiktionary. Âm Hán-Việt *hiêu* phản ánh Middle Chinese *xɨaw*. Âm Quảng Đông *hiu1*. Chữ chỉ món canh thịt (meat broth) trong văn ngữ cổ điển. Chưa có nguồn học thuật đầy đủ về tự hình qua Wiktionary. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhau; như \"chôn nhau cắt rốn\" (gdhn) rau; như \"nơi chôn rau (nhau) cắt rốn\" (gdhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 堯", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月堯", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "堯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "膮", "Unihan_Traditional (Chữ Phồn thể)": "膮", "Pinyin_Xie": "xiāo", "Âm Hán Việt_Xie": "hiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ nhau thai hoặc món canh thịt hầm thơm ngon thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铪', '{"9000": "6612.0", "Chữ Trung Quốc": "铪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 11 | nét | 铪 | cap | tượng hình | chữ độc thể chỉ nguyên tố kim loại hafnium | 铪 là chữ hình thanh có bộ 钅/金 (kim, kim loại) làm phần biểu nghĩa. Phần biểu âm chưa được xác nhận rõ trong dữ liệu hiện có. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cap\": kim loại *cáp* — bộ 金 cho biết đây là kim loại, âm *cáp* phiên âm từ tiếng Latin hafnium. | Gương Hán-Việt | cap — âm Hán-Việt của nguyên tố hafnium trong danh pháp hóa học | Mở khoá kiến thức | Biết 铪 mở khoá tên gọi Hán-Việt của nguyên tố hafnium (Hf, số nguyên tử 72) trong hóa học", "Tự nguyên_Xie": "铪 là chữ tạo muộn (cận đại), dùng để phiên âm tên nguyên tố hafnium (Hf). Bộ 钅 (kim) cho biết đây là kim loại. Âm Hán-Việt *cáp* phản ánh phiên âm tên khoa học Latinh. Chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật về tự hình cổ. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố hafini, Hf", "Hạng Tần Suất (Jun Da)": "6612.0", "Tần Suất % (Jun Da)": "99.9943107125", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 合", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅合", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "合", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铪", "Unihan_Traditional (Chữ Phồn thể)": "鉿", "Pinyin_Xie": "hā", "Âm Hán Việt_Xie": "cáp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ nguyên tố kim loại hafini trong hóa học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('簳', '{"9000": "6613.0", "Chữ Trung Quốc": "簳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 19 | nét | 竹 | trúc | biểu nghĩa | tre, trúc | 幹 | can | biểu âm | thân cây, cán (cho âm) | 簳 = 竹 (Trúc, biểu nghĩa: tre) + 幹 (Can, biểu âm); chữ hình thanh. Trúc cho nghĩa (vật liệu tre), Cán cho âm gốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"can\": *tre* (Trúc) thẳng *cán* — loại trúc thẳng tắp như cái cán (幹) dùng làm cán tên, cán giáo. | Gương Hán-Việt | can — xuất hiện trong 簳竹 (can trúc: tre thẳng dùng làm cán) | Mở khoá kiến thức | Biết 簳 mở khoá thuật ngữ cổ về các loại tre thẳng dùng làm cán tên hoặc đồ vật", "Tự nguyên_Xie": "簳 là chữ hình thanh gồm 竹 (trúc, tre) làm phần biểu nghĩa và 幹 làm phần biểu âm, theo Wiktionary. Âm Hán-Việt *can* phản ánh Middle Chinese cổ đại. Chữ chỉ loại tre thẳng, cứng dùng làm cán mũi tên hoặc đồ thủ công. Chưa có nguồn học thuật đầy đủ về tự hình qua Wiktionary. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "簳", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 幹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮幹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "幹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "簳", "Unihan_Traditional (Chữ Phồn thể)": "簳", "Pinyin_Xie": "gǎn", "Âm Hán Việt_Xie": "can", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại tre nhỏ, thẳng và cứng chuyên dùng làm mũi tên. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('訉', '{"9000": "6614.0", "Chữ Trung Quốc": "訉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 10 | nét | 訉 | hung | tượng hình | chữ độc thể, chưa xác nhận được cấu trúc thành phần | 訉 có thể có bộ 言 (ngôn, lời nói) nhưng cấu trúc hình thanh hoặc hội ý cụ thể chưa được dữ liệu học thuật xác nhận. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hung\": chữ *hung* cổ tối tăm trong văn chương — như bóng đêm phủ lên những trang sách xưa, chỉ học giả mới biết đọc. | Gương Hán-Việt | hung — âm Hán-Việt hiếm gặp trong văn ngữ cổ | Mở khoá kiến thức | Biết 訉 mở khoá cách đọc chữ cổ hiếm trong văn bản cổ điển Hán", "Tự nguyên_Xie": "訉 là chữ hiếm, nguồn gốc tự hình chưa được tài liệu học thuật xác nhận đầy đủ. Âm Hán-Việt *hung* được suy luận từ cấu trúc và vị trí trong hệ thống âm Sino-Vietnamese. Chưa có nguồn học thuật. Chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "艉", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 凡", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言凡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "凡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "訉", "Unihan_Traditional (Chữ Phồn thể)": "訉", "Pinyin_Xie": "fān", "Âm Hán Việt_Xie": "hung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này là một động từ cổ ít dùng, chủ yếu xuất hiện trong các văn bản cổ với nghĩa lừa gạt hoặc nói dối. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲉', '{"9000": "6615.0", "Chữ Trung Quốc": "鲉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 13 | nét | 魚 | ngư | biểu nghĩa | cá | 由 | do | biểu âm | từ, bởi vì (cho âm) | 鲉 = 魚 (Ngư, biểu nghĩa: cá) + 由 (Do, biểu âm); chữ hình thanh. Ngư cho nghĩa (loài cá), Do cho âm gốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"do\": *cá* (Ngư) mù làn *do* đâu mà có gai độc — *do* 由 chính là vì bản năng tự vệ của nó. | Gương Hán-Việt | do — xuất hiện trong 鲉鱼 (do ngư: cá mù làn/scorpionfish) | Mở khoá kiến thức | Biết 鲉 mở khoá tên gọi Hán-Việt của họ cá mù làn (Scorpaenidae) trong ngư học", "Tự nguyên_Xie": "鲉 là chữ hình thanh gồm 魚 (ngư, cá) làm phần biểu nghĩa và 由 làm phần biểu âm, theo Wiktionary. Âm Hán-Việt *do* phản ánh Middle Chinese cổ đại. Chữ chỉ cá mù làn (scorpionfish), loài có gai độc. Chưa có nguồn học thuật đầy đủ về tự hình qua Wiktionary. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một loài cá giống như con lươn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 由", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼由", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "由", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲉", "Unihan_Traditional (Chữ Phồn thể)": "鲉", "Pinyin_Xie": "yóu", "Âm Hán Việt_Xie": "du", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này đóng vai trò là danh từ dùng để gọi tên một họ cá biển trong ngành ngữ loại học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蕿', '{"9000": "6616.0", "Chữ Trung Quốc": "蕿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 16 | nét | 蕿 | tuyen | tượng hình | chữ độc thể chỉ loài thực vật, chưa xác nhận cấu trúc | 蕿 có bộ 艹 (thảo, cỏ cây) nhưng cấu trúc hình thanh hoặc hội ý cụ thể chưa được dữ liệu học thuật xác nhận. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuyen\": loài *cỏ* (艹) *tuyên* — hình ảnh bông hoa nhỏ tuyên truyền hương thơm giữa đồng cỏ. | Gương Hán-Việt | tuyen — âm Hán-Việt hiếm gặp trong thực vật học cổ điển | Mở khoá kiến thức | Biết 蕿 mở khoá cách đọc tên loài thực vật hiếm trong văn ngữ cổ Hán", "Tự nguyên_Xie": "蕿 là chữ hiếm chỉ một loài thực vật trong cổ văn Hán. Nguồn gốc tự hình chưa được tài liệu học thuật xác nhận đầy đủ. Âm Hán-Việt *tuyên* suy luận từ hệ thống âm Sino-Vietnamese. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "聿", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 煖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹煖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "煖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蕿", "Unihan_Traditional (Chữ Phồn thể)": "蕿", "Pinyin_Xie": "xuān", "Âm Hán Việt_Xie": "tuyen", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này là danh từ chỉ một loài cỏ hoa màu vàng trong văn học cổ, thường dùng để tượng trưng cho người mẹ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('袊', '{"9000": "6617.0", "Chữ Trung Quốc": "袊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 10 | nét | 袊 | cung | tượng hình | chữ độc thể liên quan trang phục, cấu trúc chưa xác nhận | 袊 có bộ 衤 (y, áo) nhưng cấu trúc hình thanh hoặc hội ý cụ thể chưa được dữ liệu học thuật xác nhận. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cung\": chiếc áo *cung* đình — bộ 衤 cho biết đây là trang phục, âm *cung* gợi sự trang trọng nơi cung điện. | Gương Hán-Việt | cung — âm Hán-Việt hiếm trong văn ngữ cổ liên quan trang phục | Mở khoá kiến thức | Biết 袊 mở khoá cách đọc chữ cổ liên quan đến trang phục truyền thống Hán", "Tự nguyên_Xie": "袊 là chữ hiếm liên quan đến trang phục trong cổ văn Hán. Nguồn gốc tự hình chưa được tài liệu học thuật xác nhận đầy đủ. Âm Hán-Việt *cung* suy luận từ hệ thống âm Sino-Vietnamese. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cổ áo; váy", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 令", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤令", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "令", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "袊", "Unihan_Traditional (Chữ Phồn thể)": "袊", "Pinyin_Xie": "lǐng", "Âm Hán Việt_Xie": "lãnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bộ phận cổ áo hoặc trang phục của người xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('汆', '{"9000": "6618.0", "Chữ Trung Quốc": "汆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 6 | nét | 入 | nhập | biểu nghĩa | vào, nhúng vào | 水 | thủy | biểu nghĩa | nước | 汆 là hội ý: 入 (Nhập, đi vào) + 水 (Thủy, nước) — ý nghĩa là nhúng/thả vào nước sôi. Chữ hội ý, tạo muộn, dùng trong ẩm thực.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuan\": *nhúng* (入) vào *nước* (水) — hình ảnh trực quan: người đầu bếp thả thịt vào nồi nước sôi chần nhanh. | Gương Hán-Việt | tuan — xuất hiện trong 汆汤 (trần thang: chần qua nước sôi) trong ẩm thực Trung Hoa | Mở khoá kiến thức | Biết 汆 mở khoá kỹ thuật chần nhanh trong ẩm thực Trung Hoa — nền tảng của nhiều món lẩu và canh", "Tự nguyên_Xie": "汆 là chữ hội ý hiện đại, theo Wiktionary: 入 (nhập, đi vào) + 水 (thủy, nước). Hình ảnh: thứ gì đó đi vào trong nước — động tác chần/trụng. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Âm Hán-Việt *toản* phản ánh cách đọc Sino-Vietnamese. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xốii đi, nước cuốn đi", "Hạng Tần Suất (Jun Da)": "6618.0", "Tần Suất % (Jun Da)": "99.9943944316", "GavinGrover_Once (Chiết tự trực tiếp)": "入 + 水", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱入水", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "水", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "入", "Unihan_Simplified (Chữ Giản thể)": "汆", "Unihan_Traditional (Chữ Phồn thể)": "汆", "Pinyin_Xie": "cuān", "Âm Hán Việt_Xie": "thộn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ phương pháp nấu ăn bằng cách nhúng nhanh thực phẩm vào nước sôi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('仝', '{"9000": "6619.0", "Chữ Trung Quốc": "仝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 5 | nét | 人 | nhân | biểu nghĩa | người | 工 | công | biểu nghĩa | công việc, nghề | 仝 = 人 (Nhân, người) + 工 (Công, công việc); chữ hội ý theo Wiktionary {{Han compound|人|工}}. Mô tả người và công việc cùng nhau — cùng nhau, đồng. Biến thể cổ của chữ 同 (đồng, cùng nhau).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đồng\": 人 (người) + 工 (công việc) — nhiều người \"đồng\" lòng cùng làm một công việc, hợp sức chung tay. | Gương Hán-Việt | \"Đồng\" trong tiếng Việt: đồng nghĩa (仝義), đồng lòng — từ 仝 (biến thể của 同). | Mở khoá kiến thức | Biết 仝 (đồng) giúp nhận ra chữ 同 và các từ đồng căn: đồng nghĩa, đồng lòng, đồng bào, tương đồng.", "Tự nguyên_Xie": "Tiểu triện | Chữ 仝 là chữ hội ý: 人 (nhân, người) + 工 (công, nghề/công việc). Wiktionary xác nhận: {{Han compound|人|工}}. Có hình tiểu triện (nguồn hanziyuan). Đây là biến thể cổ của 同 (đồng), nghĩa: cùng nhau, như nhau. Thường dùng như chữ 同 trong văn bản cổ. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cùng nhau", "Hạng Tần Suất (Jun Da)": "69.0", "Tần Suất % (Jun Da)": "35.3317159543", "GavinGrover_Once (Chiết tự trực tiếp)": "人 + 工", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱人工", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "工", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "人", "Unihan_Simplified (Chữ Giản thể)": "同", "Unihan_Traditional (Chữ Phồn thể)": "仝", "Pinyin_Xie": "tóng", "Âm Hán Việt_Xie": "đồng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Phó từ | 副词 | Chữ này thường dùng như tính từ hoặc phó từ trong văn bản hành chính cổ để chỉ sự đồng lòng, cùng chung. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('趽', '{"9000": "6620.0", "Chữ Trung Quốc": "趽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 11 | nét | 趽 | phuong | tượng hình | chữ độc thể liên quan chuyển động chân, cấu trúc chưa xác nhận | 趽 có bộ 走 (tẩu, chạy/đi) nhưng cấu trúc hình thanh hoặc hội ý cụ thể chưa được dữ liệu học thuật xác nhận. Wiktionary ghi nhận ba âm khác nhau (fàng/páng/fāng), cho thấy chữ có nhiều cách đọc. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phuong\": bước chân *phương* xa — bộ 走 (tẩu) gợi hình ảnh đi đứng, âm *phương* gợi hướng đi mơ hồ. | Gương Hán-Việt | phuong — âm Hán-Việt hiếm gặp trong văn ngữ cổ | Mở khoá kiến thức | Biết 趽 mở khoá cách đọc chữ cổ liên quan dáng đi hoặc cử chỉ chân", "Tự nguyên_Xie": "趽 mang nhiều âm khác nhau: fàng/páng/fāng theo Wiktionary, tương ứng âm Hán-Việt *phương*. Chữ liên quan đến dáng đi hoặc cử chỉ chân trong cổ văn. Nguồn gốc tự hình chưa được tài liệu học thuật xác nhận đầy đủ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "载", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 方", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊方", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "方", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "趽", "Unihan_Traditional (Chữ Phồn thể)": "趽", "Pinyin_Xie": "fàng", "Âm Hán Việt_Xie": "phuong", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này làm động từ hoặc tính từ mô tả dáng đi không vững, đi lệch một bên chân. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('堍', '{"9000": "6621.0", "Chữ Trung Quốc": "堍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 11 | nét | 堍 | tho | tượng hình | chữ độc thể chỉ chân cầu/bục đất, cấu trúc chưa xác nhận đầy đủ | 堍 có bộ 土 (thổ, đất) nhưng cấu trúc hình thanh hoặc hội ý cụ thể chưa được dữ liệu học thuật xác nhận. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tho\": khối *đất* (Thổ) dưới chân cầu — *thố* là nền móng, cơ sở giữ cho cầu đứng vững. | Gương Hán-Việt | tho — xuất hiện trong 桥堍 (kiều thố: chân cầu, móng cầu) | Mở khoá kiến thức | Biết 堍 mở khoá thuật ngữ kiến trúc cổ về chân cầu và móng cầu trong văn học Hán", "Tự nguyên_Xie": "堍 là chữ chỉ phần đất ở hai đầu cầu (chân cầu, bờ cầu). Âm Hán-Việt *thố* phản ánh Middle Chinese cổ đại. Nguồn gốc tự hình chưa được tài liệu học thuật xác nhận đầy đủ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dốc cầu; mố cầu", "Hạng Tần Suất (Jun Da)": "6621.0", "Tần Suất % (Jun Da)": "99.9944233716", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 兔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土兔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "堍", "Unihan_Traditional (Chữ Phồn thể)": "堍", "Pinyin_Xie": "tù", "Âm Hán Việt_Xie": "thố", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng làm danh từ để chỉ phần đất hoặc mố đất ở hai đầu cầu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('揸', '{"9000": "6622.0", "Chữ Trung Quốc": "揸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 12 | nét | 揸 | tra | tượng hình | chữ độc thể chỉ động tác nắm bằng tay, cấu trúc chưa xác nhận | 揸 có bộ 手/扌 (thủ, tay) nhưng cấu trúc hình thanh hoặc hội ý cụ thể chưa được dữ liệu học thuật xác nhận. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tra\": *tay* (扌) *tra* vào — động tác cầm nắm dứt khoát, như tra tay vào túi lấy đồ. | Gương Hán-Việt | tra — âm Hán-Việt của từ nắm tay/bốc lấy trong phương ngữ Quảng Đông | Mở khoá kiến thức | Biết 揸 mở khoá cách diễn đạt động tác nắm, bốc, cầm trong tiếng Quảng Đông và văn ngữ cổ", "Tự nguyên_Xie": "揸 là chữ chỉ động tác nắm, bốc lấy bằng tay. Phổ biến trong phương ngữ Quảng Đông. Âm Hán-Việt *tra* phản ánh Middle Chinese cổ đại. Nguồn gốc tự hình chưa được tài liệu học thuật xác nhận đầy đủ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nặn, nhúm lấy", "Hạng Tần Suất (Jun Da)": "6622.0", "Tần Suất % (Jun Da)": "99.9944306066", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 查", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌查", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "查", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "揸", "Unihan_Traditional (Chữ Phồn thể)": "揸", "Pinyin_Xie": "zhā", "Âm Hán Việt_Xie": "tra", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ biểu thị hành động dùng tay nắm hoặc bóp chặt vật gì đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('忭', '{"9000": "6623.0", "Chữ Trung Quốc": "忭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 7 | nét | 忭 | bien | tượng hình | chữ độc thể chỉ cảm xúc vui mừng | 忭 có bộ 忄/心 (tâm, lòng/cảm xúc) nhưng cấu trúc hình thanh hoặc hội ý cụ thể chưa được dữ liệu học thuật xác nhận rõ ràng. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bien\": *lòng* (心) vui *biện* — khi nội tâm tràn đầy niềm vui, lời chúc mừng tự nhiên tuôn ra. | Gương Hán-Việt | bien — xuất hiện trong 忭賀 (biện hạ: vui mừng chúc mừng), 歡忭 (hoan biện: hân hoan vui mừng) | Mở khoá kiến thức | Biết 忭 mở khoá cách diễn đạt cảm xúc vui mừng hân hoan trong văn ngữ cổ điển Hán", "Tự nguyên_Xie": "忭 mang âm Middle Chinese *bjian*, tương ứng âm Hán-Việt *biện*. Âm Quảng Đông *bin6* theo Wiktionary. Chữ dùng trong cổ văn chỉ trạng thái vui mừng, hân hoan (delighted, glad, joyful). Nguồn gốc tự hình chưa được tài liệu học thuật xác nhận đầy đủ. Chưa có nguồn học thuật. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vui thích", "Hạng Tần Suất (Jun Da)": "6623.0", "Tần Suất % (Jun Da)": "99.9944378416", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 卞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄卞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "忭", "Unihan_Traditional (Chữ Phồn thể)": "忭", "Pinyin_Xie": "biàn", "Âm Hán Việt_Xie": "biện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này thường làm tính từ biểu thị trạng thái vui mừng hoặc làm động từ trong văn viết cổ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('銧', '{"9000": "6624.0", "Chữ Trung Quốc": "銧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 14 | nét | 銧 | quang | tượng hình | chữ độc thể liên quan kim loại, cấu trúc chưa xác nhận | 銧 có bộ 金/钅 (kim, kim loại) nhưng cấu trúc hình thanh hoặc hội ý cụ thể chưa được dữ liệu học thuật xác nhận. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quang\": kim loại *quang* sáng — bộ 金 cho biết chất liệu kim loại, ánh *quang* phản chiếu như gương. | Gương Hán-Việt | quang — âm Hán-Việt hiếm trong lĩnh vực kim loại và khoáng sản cổ điển | Mở khoá kiến thức | Biết 銧 mở khoá cách đọc chữ cổ liên quan đến kim loại trong văn ngữ Hán", "Tự nguyên_Xie": "銧 là chữ hiếm liên quan đến kim loại trong cổ văn Hán. Âm Hán-Việt *quang* suy luận từ hệ thống âm Sino-Vietnamese. Nguồn gốc tự hình chưa được tài liệu học thuật xác nhận đầy đủ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tên gọi cũ của nguyên tố rađi, Ra", "Hạng Tần Suất (Jun Da)": "6624.0", "Tần Suất % (Jun Da)": "99.9944450766", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 光", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金光", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "光", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "銧", "Unihan_Traditional (Chữ Phồn thể)": "銧", "Pinyin_Xie": "guāng", "Âm Hán Việt_Xie": "quang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này là danh từ hóa học cổ dùng để chỉ nguyên tố phóng xạ ra-đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('妤', '{"9000": "6625.0", "Chữ Trung Quốc": "妤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 7 | nét | 女 | nữ | biểu nghĩa | phụ nữ | 予 | dư | biểu âm | ban cho, tôi (cho âm) | 妤 = 女 (Nữ, biểu nghĩa: phụ nữ) + 予 (Dư, biểu âm); chữ hình thanh. Nữ cho nghĩa (phụ nữ trong cung), Dư cho âm gốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"du\": *phụ nữ* (Nữ) được *ban* (Dư/予) danh hiệu — Tiệp Dư là phi tần được hoàng đế ban tước vị trong cung Hán. | Gương Hán-Việt | du — xuất hiện trong 婕妤 (tiệp dư: danh hiệu phi tần trong hoàng cung) | Mở khoá kiến thức | Biết 妤 mở khoá danh hiệu 婕妤 — phi tần cấp cao trong cung đình Hán triều", "Tự nguyên_Xie": "妤 là chữ hình thanh gồm 女 (nữ, phụ nữ) làm phần biểu nghĩa và 予 làm phần biểu âm, theo Wiktionary. Âm Hán-Việt *dư* phản ánh Middle Chinese *jɨo*. Âm Quảng Đông *jyu4*, Mân Nam *û/îr*. Chữ chỉ dùng trong 婕妤 — một danh hiệu phi tần trong cung đình nhà Hán. Chưa có nguồn học thuật đầy đủ về tự hình qua Wiktionary. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: tiệp dư 婕妤)", "Hạng Tần Suất (Jun Da)": "6625.0", "Tần Suất % (Jun Da)": "99.9944523116", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 予", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女予", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "予", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "妤", "Unihan_Traditional (Chữ Phồn thể)": "妤", "Pinyin_Xie": "yú", "Âm Hán Việt_Xie": "dư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này thường dùng làm tính từ chỉ vẻ đẹp của phụ nữ hoặc kết hợp thành danh từ chỉ chức quan phi tần. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('頫', '{"9000": "6626.0", "Chữ Trung Quốc": "頫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 頁 | Số nét | 15 | nét | 兆 | triệu | biểu âm | triệu, điềm báo (cho âm) | 頁 | hiệt | biểu nghĩa | đầu, mặt người | 頫 = 兆 (Triệu, biểu âm) + 頁 (Hiệt, biểu nghĩa: đầu/mặt người); chữ hình thanh. Hiệt cho nghĩa (động tác của đầu), Triệu cho âm gốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phu\": *đầu* (Hiệt/頁) *phủ* xuống — hình ảnh người cúi đầu khiêm nhường, đối lập với ngẩng (仰) lên nhìn trời. | Gương Hán-Việt | phu — xuất hiện trong 頫仰 (phủ ngưỡng: cúi và ngửa) trong văn ngữ cổ | Mở khoá kiến thức | Biết 頫 mở khoá cặp từ cổ điển 頫仰 diễn tả cúi đầu và ngẩng đầu trong triết học và thơ ca Hán", "Tự nguyên_Xie": "頫 là chữ hình thanh gồm 兆 làm phần biểu âm và 頁 (hiệt, đầu) làm phần biểu nghĩa, theo Wiktionary. Âm Hán-Việt *phủ* phản ánh Middle Chinese cổ đại. Chữ chỉ động tác cúi đầu, nhìn xuống, cúi người. Đối nghĩa với 仰 (ngưỡng: ngẩng đầu nhìn lên). Chưa có nguồn học thuật đầy đủ về tự hình qua Wiktionary. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cúi xuống", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "兆 + 頁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰兆頁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "頁", "Unihan_Simplified (Chữ Giản thể)": "𫖯", "Unihan_Traditional (Chữ Phồn thể)": "頫", "Pinyin_Xie": "fǔ", "Âm Hán Việt_Xie": "phu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động cúi đầu xuống, dùng tương đương với chữ phủ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('讟', '{"9000": "6627.0", "Chữ Trung Quốc": "讟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 29 | nét | 誩 | cạnh | biểu nghĩa | tranh luận, lời cãi cọ | 𧶠 | biểu âm | thành phần biểu âm (hình phức) | 讟 = 誩 (Cạnh, biểu nghĩa: lời tranh luận) + 𧶠 (biểu âm); chữ hình thanh. Phần Cạnh cho nghĩa (lời oán thán, phỉ báng), phần kia cho âm gốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"doc\": lời *tranh cãi* (Cạnh/誩) *độc* ác — khi người ta oán hận tột cùng, lời nói trở nên như chất độc. | Gương Hán-Việt | doc — xuất hiện trong văn cổ chỉ oán thán, phỉ báng | Mở khoá kiến thức | Biết 讟 mở khoá cách diễn đạt sự oán trách và phỉ báng trong cổ văn Hán", "Tự nguyên_Xie": "讟 là chữ hình thanh gồm 誩 làm phần biểu nghĩa và 𧶠 làm phần biểu âm, theo Wiktionary. Âm Hán-Việt *độc* phản ánh Middle Chinese *dʑuwk*. Âm Quảng Đông *duk6*, Mân Nam *tho̍k*. Chữ dùng trong cổ văn chỉ sự oán trách, phỉ báng, khiếu kiện. Chưa có nguồn học thuật đầy đủ về tự hình qua Wiktionary. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phỉ báng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "誩 + 賣", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴誩賣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "賣", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "誩", "Unihan_Simplified (Chữ Giản thể)": "𮙋", "Unihan_Traditional (Chữ Phồn thể)": "讟", "Pinyin_Xie": "dú", "Âm Hán Việt_Xie": "độc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này chủ yếu làm động từ thể hiện sự oán trách hoặc phỉ báng trong văn ngôn cổ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('龠', '{"9000": "6628.0", "Chữ Trung Quốc": "龠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 龠 | Số nét | 17 | nét | 品 | phẩm | biểu nghĩa | ba cái miệng — nhiều lỗ thổi | 侖 | luân | biểu nghĩa | thứ tự, mạch lạc — ống sắp hàng | 龠 là hội ý: 品 (Phẩm: ba miệng — nhiều lỗ thổi) + 侖 (Luân: thứ tự — ống xếp hàng ngăn nắp). Chữ hội ý tượng hình: sáo trúc nhiều ống như tiêu/sáo Pan với hai miệng thổi trên đỉnh. Wiktionary mô tả: nhạc cụ sáo trúc kiểu Pan flute trong đó 吅 biểu thị đỉnh tròn của ống trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"yuoc\": sáo Pan *ước* hẹn — nhiều ống trúc (品/ba miệng) xếp *luân* phiên thứ tự, cùng tấu lên giai điệu cổ xưa. | Gương Hán-Việt | yuoc — xuất hiện trong 龠量 (ước lượng: đơn vị đo lường cổ) và 吹龠 (xuy ước: thổi sáo trúc) | Mở khoá kiến thức | Biết 龠 mở khoá kiến thức về nhạc cụ thổi Trung Hoa cổ đại và đơn vị đo lường trong cổ văn", "Tự nguyên_Xie": "龠 là chữ tượng hình/hội ý, theo Wiktionary: hình ảnh cây sáo trúc Pan (Pan flute) với hai miệng (吅) biểu thị đỉnh tròn của ống trúc. Trong kim văn, 亼 (miệng lật ngược của 口) được thêm vào trên cùng để chỉ miệng đang thổi nhạc cụ. Shuowen giải thích theo hội ý. Âm Hán-Việt *ược* phản ánh Middle Chinese cổ đại. Chưa có nguồn học thuật đầy đủ về tự hình qua Wiktionary. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một thứ nhạc khí như sáo, có 3 lỗ", "Hạng Tần Suất (Jun Da)": "6628.0", "Tần Suất % (Jun Da)": "99.9944812515", "GavinGrover_Once (Chiết tự trực tiếp)": "亼 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱亼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "龠", "Unihan_Traditional (Chữ Phồn thể)": "龠", "Pinyin_Xie": "yuè", "Âm Hán Việt_Xie": "thược", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Chữ này làm danh từ chỉ nhạc khí cổ hoặc làm lượng từ đo dung tích thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('垤', '{"9000": "6629.0", "Chữ Trung Quốc": "垤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 9 | nét | 垤 | diet | tượng hình | chữ độc thể chỉ gò đất nhỏ, cấu trúc chưa xác nhận đầy đủ | 垤 có bộ 土 (thổ, đất) nhưng cấu trúc hình thanh hoặc hội ý cụ thể chưa được dữ liệu học thuật xác nhận. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"diet\": gò *đất* (Thổ) nhỏ *điệt* — hình ảnh gò đất nhỏ nổi lên giữa đồng bằng, như nốt ruồi trên mặt đất. | Gương Hán-Việt | diet — xuất hiện trong văn cổ chỉ gò đất nhỏ, đống đất nhỏ | Mở khoá kiến thức | Biết 垤 mở khoá thuật ngữ địa hình cổ về các gò đất nhỏ và mô đất trong thơ cổ Hán", "Tự nguyên_Xie": "垤 mang âm Middle Chinese *dɛt*, tương ứng âm Hán-Việt *điệt*. Âm Quảng Đông *dit6*, Khách Gia *te* theo Wiktionary. Chữ dùng trong cổ văn và thơ ca chỉ gò đất nhỏ, mô đất (mound, small hill). Wiktionary trích thơ cổ: ký岈然窪然，若垤若穴. Chưa có nguồn học thuật đầy đủ về tự hình qua Wiktionary. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đống đất nhỏ; đống đất do kiến đùn", "Hạng Tần Suất (Jun Da)": "6629.0", "Tần Suất % (Jun Da)": "99.9944884865", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 至", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土至", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "至", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "垤", "Unihan_Traditional (Chữ Phồn thể)": "垤", "Pinyin_Xie": "dié", "Âm Hán Việt_Xie": "điệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ để chỉ các gò đất nhỏ hoặc ụ đất do loài kiến đắp lên. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('擐', '{"9000": "6630.0", "Chữ Trung Quốc": "擐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 16 | nét | 手 | thủ | biểu nghĩa | tay | 睘 | hoàn | biểu âm | tròn, cong (cho âm) | 擐 = 手 (Thủ, biểu nghĩa: tay) + 睘 (Hoàn, biểu âm); chữ hình thanh. Thủ cho nghĩa (động tác tay mặc giáp), Hoàn cho âm gốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoan\": *tay* (Thủ) *hoàn* tất việc mặc giáp — chiến binh dùng tay luồn qua từng vòng giáp, sẵn sàng ra trận. | Gương Hán-Việt | hoan — xuất hiện trong 擐甲執兵 (hoàn giáp chấp binh: mặc giáp cầm vũ khí) | Mở khoá kiến thức | Biết 擐 mở khoá thành ngữ cổ điển về chiến binh mặc áo giáp trong cổ văn quân sự Hán", "Tự nguyên_Xie": "擐 là chữ hình thanh gồm 手 (thủ, tay) làm phần biểu nghĩa và 睘 làm phần biểu âm, theo Wiktionary. Âm Hán-Việt *hoàn* phản ánh Middle Chinese cổ đại. Chữ dùng trong cổ văn quân sự chỉ động tác mặc áo giáp (to put on armor). Chưa có nguồn học thuật đầy đủ về tự hình qua Wiktionary. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mặc vào người, đeo vào người", "Hạng Tần Suất (Jun Da)": "6630.0", "Tần Suất % (Jun Da)": "99.9944957215", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 睘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌睘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "睘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "擐", "Unihan_Traditional (Chữ Phồn thể)": "擐", "Pinyin_Xie": "huàn", "Âm Hán Việt_Xie": "hoàn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động mặc hoặc xỏ quần áo, đặc biệt là mặc giáp trụ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('噍', '{"9000": "6631.0", "Chữ Trung Quốc": "噍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 15 | nét | 噍 | tieu | tượng hình | chữ độc thể chỉ hành động nhai, loài có thể nhai, cấu trúc chưa xác nhận | 噍 có bộ 口 (khẩu, miệng) nhưng cấu trúc hình thanh hoặc hội ý cụ thể chưa được dữ liệu học thuật xác nhận. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tieu\": *miệng* (口) *tiều* tụy nhai không nổi — 無噍類 là câu cổ văn: không còn một sinh vật nào còn miệng để nhai. | Gương Hán-Việt | tieu — xuất hiện trong 噍類 (tiều loại: loài còn sống, loài có thể nhai), 無噍類 (vô tiều loại: không còn sống sót) | Mở khoá kiến thức | Biết 噍 mở khoá thành ngữ cổ 無噍類 — không còn một mống sống sót trong cổ văn Hán", "Tự nguyên_Xie": "噍 mang âm Hán-Việt *tiều*, phản ánh Middle Chinese cổ đại. Chữ dùng trong cổ văn chỉ động tác nhai, hoặc (theo mở rộng nghĩa) loài có sự sống có thể nhai thức ăn. Thành ngữ 無噍類 (vô tiều loại: không còn một loài có thể nhai = không còn sống sót) rất phổ biến. Nguồn gốc tự hình chưa được tài liệu học thuật xác nhận đầy đủ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cắn, nhai, nhấm", "Hạng Tần Suất (Jun Da)": "6631.0", "Tần Suất % (Jun Da)": "99.9945029565", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 焦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口焦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "焦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "噍", "Unihan_Traditional (Chữ Phồn thể)": "噍", "Pinyin_Xie": "jiào", "Âm Hán Việt_Xie": "tiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động nhai hoặc cắn nuốt thức ăn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('洫', '{"9000": "6632.0", "Chữ Trung Quốc": "洫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 9 | nét | 洫 | huc | tượng hình | chữ độc thể chỉ mương rãnh thoát nước, cấu trúc chưa xác nhận | 洫 có bộ 水/氵 (thủy, nước) nhưng cấu trúc hình thanh hoặc hội ý cụ thể chưa được dữ liệu học thuật xác nhận. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huc\": *nước* (Thủy) chảy qua mương *hức* — mương thoát nước nhỏ dẫn nước đi khắp ruộng, âm *hức* gợi tiếng nước chảy rì rào. | Gương Hán-Việt | huc — xuất hiện trong 溝洫 (câu hức: hệ thống mương rãnh thoát nước trong nông nghiệp cổ) | Mở khoá kiến thức | Biết 洫 mở khoá thuật ngữ thủy lợi cổ về hệ thống mương rãnh thoát nước trong canh tác Hán cổ", "Tự nguyên_Xie": "洫 mang âm Hán-Việt *hức*, phản ánh Middle Chinese cổ đại. Chữ dùng trong hệ thống thủy lợi cổ điển chỉ loại mương nhỏ (rộng 4 xích theo Chu Lễ) dẫn nước qua ruộng. Trong hệ thống đồng điền cổ: đây là mương cấp 3 trong chuỗi thủy lợi. Nguồn gốc tự hình chưa được tài liệu học thuật xác nhận đầy đủ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rãnh, hào, mương; kè, bờ ngăn nước; thành trì; lạm", "Hạng Tần Suất (Jun Da)": "6632.0", "Tần Suất % (Jun Da)": "99.9945101915", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 血", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵血", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "血", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "洫", "Unihan_Traditional (Chữ Phồn thể)": "洫", "Pinyin_Xie": "xù", "Âm Hán Việt_Xie": "hức", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ mương rãnh hoặc động từ chỉ việc đào rãnh thoát nước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('滏', '{"9000": "6633.0", "Chữ Trung Quốc": "滏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 13 | nét | 滏 | phu | tượng hình | chữ độc thể chỉ tên sông cổ, cấu trúc chưa xác nhận | 滏 có bộ 水/氵 (thủy, nước) nhưng cấu trúc hình thanh hoặc hội ý cụ thể chưa được dữ liệu học thuật xác nhận. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phu\": *nước* (Thủy) sông *phủ* — 滏陽河 là con sông lịch sử chảy qua Hà Bắc, âm *phủ* gợi hình ảnh dòng nước trôi nhẹ nhàng. | Gương Hán-Việt | phu — xuất hiện trong 滏水 (Phủ Thủy: tên sông cổ ở Hà Bắc, Trung Quốc) | Mở khoá kiến thức | Biết 滏 mở khoá địa danh cổ liên quan đến sông Phủ (滏水/滏陽河) và địa lý lịch sử Hà Bắc", "Tự nguyên_Xie": "滏 mang âm Hán-Việt *phủ*, phản ánh Middle Chinese cổ đại. Chữ chủ yếu dùng trong địa danh: 滏水 (sông Phủ) hay 滏陽河 ở tỉnh Hà Bắc, Trung Quốc. Đây là chữ chuyên dùng cho địa danh, không có nghĩa độc lập rộng rãi. Nguồn gốc tự hình chưa được tài liệu học thuật xác nhận đầy đủ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Phũ (Hà Bắc, Trung Quốc)", "Hạng Tần Suất (Jun Da)": "6633.0", "Tần Suất % (Jun Da)": "99.9945174265", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 釜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵釜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "釜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "滏", "Unihan_Traditional (Chữ Phồn thể)": "滏", "Pinyin_Xie": "fǔ", "Âm Hán Việt_Xie": "phũ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ riêng trong địa danh như sông Phủ Dương. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('璁', '{"9000": "6634.0", "Chữ Trung Quốc": "璁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 15 | nét | 玉 | ngọc | biểu nghĩa | đá quý | 悤 | thông | biểu âm | 璁 = 玉 (Ngọc, biểu nghĩa: đá quý) + 悤 (Thông, biểu âm); chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không có âm chuẩn: viên ngọc (玉) sáng bóng — 璁 là đá giống ngọc bích, được người xưa trân trọng. | Gương Hán-Việt | 璁 không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 璁 giúp nhận diện chữ chỉ đá quý trong văn chương Hán Nôm cổ điển.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 玉 biểu nghĩa loại khoáng vật quý, 悤 biểu âm (âm cōng). 璁 chỉ loại đá giống ngọc bích màu xanh. Dạng tiểu triện đã có. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một thứ đá giống như ngọc bích", "Hạng Tần Suất (Jun Da)": "6634.0", "Tần Suất % (Jun Da)": "99.9945246615", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 悤", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王悤", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "悤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "璁", "Unihan_Traditional (Chữ Phồn thể)": "璁", "Pinyin_Xie": "cōng", "Âm Hán Việt_Xie": "thông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loại đá quý hoặc dùng trong tên người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('癃', '{"9000": "6635.0", "Chữ Trung Quốc": "癃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 16 | nét | 癃 | lung | tượng hình | bệnh suy nhược, bí tiểu tiện | 癃 thuộc bộ 疒 (bệnh tật). Wiktionary không cung cấp cấu trúc hội ý hay hình thanh rõ ràng. Chưa có nguồn học thuật xác nhận cấu trúc nội bộ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lung\": người bệnh (疒) lưng còng — 癃 chỉ trạng thái suy nhược, đi lại khó khăn hoặc bí tiểu tiện. | Gương Hán-Việt | \"lung\" xuất hiện trong y văn cổ \"lung bệnh\" (suy nhược, gù lưng). | Mở khoá kiến thức | Biết 癃 giúp đọc y văn cổ Trung Hoa mô tả bệnh tiểu tiện bí hoặc suy nhược thể chất.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary không phân tích cấu trúc cho 癃. Chữ thuộc bộ 疒 (bệnh), mang nghĩa suy nhược thể chất hoặc bí tiểu. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bị gù lưng", "Hạng Tần Suất (Jun Da)": "6635.0", "Tần Suất % (Jun Da)": "99.9945318965", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 隆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒隆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "隆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "癃", "Unihan_Traditional (Chữ Phồn thể)": "癃", "Pinyin_Xie": "lóng", "Âm Hán Việt_Xie": "lung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ chỉ trạng thái suy yếu, gù lưng hoặc danh từ chỉ chứng bí tiểu. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('邡', '{"9000": "6636.0", "Chữ Trung Quốc": "邡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 6 | nét | 邡 | phương | tượng hình | tên địa danh ở Tứ Xuyên | 邡 dùng làm tên địa danh (什邡). Wiktionary không cung cấp phân tích cấu trúc hội ý hay hình thanh. Bộ 邑 thường biểu thị địa danh trong chữ Hán.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phương\": 邡 là địa danh — ấp đất phương (方) ở Tứ Xuyên, tức huyện 什邡 (Thập Phương). | Gương Hán-Việt | \"phương\" trong địa danh 什邡 (Thập Phương, Tứ Xuyên). | Mở khoá kiến thức | Biết 邡 giúp nhận ra địa danh cổ vùng Tứ Xuyên trong văn bản lịch sử Trung Quốc.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | 邡 xuất hiện trong kim văn và tiểu triện, chủ yếu trong địa danh 什邡 (Thập Phương) ở Tứ Xuyên. Wiktionary ghi hai âm: fāng (địa danh) và fàng (thay thế cho 訪). Chưa có nguồn học thuật về cấu trúc nội bộ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên đất)", "Hạng Tần Suất (Jun Da)": "6636.0", "Tần Suất % (Jun Da)": "99.9945391315", "GavinGrover_Once (Chiết tự trực tiếp)": "方 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰方阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "阝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "方", "Unihan_Simplified (Chữ Giản thể)": "邡", "Unihan_Traditional (Chữ Phồn thể)": "邡", "Pinyin_Xie": "fāng", "Âm Hán Việt_Xie": "phương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ riêng trong địa danh như huyện Thập Phương ở Tứ Xuyên. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('絁', '{"9000": "6637.0", "Chữ Trung Quốc": "絁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 11 | nét | 絁 | si | tượng hình | vải tơ thô sợi to | 絁 thuộc bộ 糸 (tơ, sợi). Wiktionary không cung cấp phân tích cấu trúc hình thanh/hội ý. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"si\": tơ (糸) thô ráp — 絁 là lụa hạng thấp, sợi to, không mịn như tơ hảo hạng. | Gương Hán-Việt | \"si\" hiếm trong tiếng Việt hiện đại; xuất hiện trong văn bản cổ về hàng dệt. | Mở khoá kiến thức | Biết 絁 giúp đọc tài liệu lịch sử về thương mại tơ lụa và hàng dệt thời cổ đại.", "Tự nguyên_Xie": "絁 là loại vải lụa thô, sợi to, không tinh tế. Thuộc bộ 糸. Wiktionary ghi nhận chỉ nghĩa (coarse silk) mà không phân tích cấu trúc. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một loại vải tơ to sợi", "Hạng Tần Suất (Jun Da)": "6637.0", "Tần Suất % (Jun Da)": "99.9945463665", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 㐌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹㐌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㐌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "絁", "Unihan_Traditional (Chữ Phồn thể)": "絁", "Pinyin_Xie": "shī", "Âm Hán Việt_Xie": "thi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loại vải dệt bằng tơ sợi thô thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蒽', '{"9000": "6638.0", "Chữ Trung Quốc": "蒽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 13 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 恩 | ân | biểu âm | âm đọc gần ēn | 蒽 = 艹 (Thảo, biểu nghĩa: thực vật) + 恩 (Ân, biểu âm); chữ hình thanh. Bộ 艹 gợi chất hữu cơ từ thực vật/than, 恩 cung cấp âm ēn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không có âm chuẩn: cỏ (艹) mang ân (恩) — 蒽 là anthracene, hợp chất hữu cơ có bộ thảo mộc. | Gương Hán-Việt | 蒽 không có từ Hán-Việt thông dụng; chỉ dùng trong thuật ngữ hóa học. | Mở khoá kiến thức | Biết 蒽 giúp đọc tài liệu hóa học hữu cơ tiếng Hán về hợp chất thơm.", "Tự nguyên_Xie": "Chữ hình thanh: 艹 biểu nghĩa, 恩 biểu âm. 蒽 là tên Hán của anthracene (antraxen), hợp chất thơm polycyclic trong than đá. Chữ được tạo ra để phiên dịch thuật ngữ hóa học hiện đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "antraxen (hoá học)", "Hạng Tần Suất (Jun Da)": "6638.0", "Tần Suất % (Jun Da)": "99.9945680714", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 恩", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹恩", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "恩", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蒽", "Unihan_Traditional (Chữ Phồn thể)": "蒽", "Pinyin_Xie": "ēn", "Âm Hán Việt_Xie": "ân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong hóa học hữu cơ để chỉ hợp chất anthracene. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('膫', '{"9000": "6639.0", "Chữ Trung Quốc": "膫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 16 | nét | 肉 | nhục | biểu nghĩa | thịt, thân thể | 尞 | liêu | biểu âm | âm đọc gần liáo | 膫 = 肉 (Nhục, biểu nghĩa: thịt/cơ thể) + 尞 (Liêu, biểu âm); chữ hình thanh. Bộ 肉 cho biết liên quan đến cơ thể, 尞 cung cấp âm liáo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không có âm chuẩn: thịt (肉) bao quanh lâu dài (尞) — 膫 là màng mỡ bao phủ ruột bên trong cơ thể. | Gương Hán-Việt | 膫 không có từ Hán-Việt thông dụng; dùng trong y văn và ẩm thực Triều Châu. | Mở khoá kiến thức | Biết 膫 giúp đọc y văn cổ về nội tạng và tài liệu ẩm thực miền Nam Trung Quốc.", "Tự nguyên_Xie": "Chữ hình thanh: 肉 biểu nghĩa, 尞 biểu âm. 膫 chỉ lớp mỡ bao phủ ruột (omentum); trong tiếng Triều Châu còn chỉ mỡ lợn (lard). Wiktionary xác nhận cấu trúc này. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cơ quan sinh dục; bộ phận sinh dục (giống đực)", "Hạng Tần Suất (Jun Da)": "6639.0", "Tần Suất % (Jun Da)": "99.9945825414", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 尞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月尞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "膫", "Unihan_Traditional (Chữ Phồn thể)": "膫", "Pinyin_Xie": "liáo", "Âm Hán Việt_Xie": "liêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ phần mỡ quanh ruột hoặc bộ phận sinh dục của động vật đực. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('臅', '{"9000": "6640.0", "Chữ Trung Quốc": "臅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 17 | nét | 臅 | súc | tượng hình | chữ hiếm, nghĩa chưa xác định | 臅 thuộc bộ 肉 (thịt). Wiktionary không cung cấp phân tích cấu trúc hay giải thích nghĩa cụ thể. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"súc\": chữ bộ nhục (肉) — 臅 là chữ hiếm trong y văn cổ, nghĩa chính xác chưa xác định. | Gương Hán-Việt | 臅 không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 臅 giúp nhận diện các chữ hiếm trong từ điển chữ Hán toàn thư.", "Tự nguyên_Xie": "Wiktionary chỉ ghi âm đọc chù/zuk, không giải thích cấu trúc hay nghĩa (rfdef). Chưa có nguồn học thuật xác nhận ý nghĩa chính xác của 臅. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "卅", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 蜀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月蜀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "蜀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "臅", "Unihan_Traditional (Chữ Phồn thể)": "臅", "Pinyin_Xie": "chù", "Âm Hán Việt_Xie": "súc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong cổ văn để chỉ phần thịt ở ngực hoặc sườn động vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('茖', '{"9000": "6641.0", "Chữ Trung Quốc": "茖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 茖 | các | tượng hình | loài hành dại (Allium victorialis) | 茖 thuộc bộ 艹 (cỏ/thực vật). Wiktionary không cung cấp phân tích cấu trúc hình thanh/hội ý. Chữ chỉ dùng trong từ ghép 茖葱 (một loài hành dại).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"các\": cỏ (艹) tên \"các\" — 茖 là loại hành dại mọc ở núi cao, dùng trong y học cổ truyền. | Gương Hán-Việt | \"các\" ít dùng trong tiếng Việt hiện đại; xuất hiện trong tên dược liệu cổ. | Mở khoá kiến thức | Biết 茖 giúp nhận diện tên dược liệu và thực vật trong y văn Đông y cổ.", "Tự nguyên_Xie": "Bạch thư | Đại triện | Tiểu triện | 茖 xuất hiện trong bạch thư, đại triện và tiểu triện. Wiktionary ghi chỉ dùng trong 茖葱 (Allium victorialis, loài hành dại vùng núi). Chưa có nguồn học thuật về cấu trúc nội bộ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "các thông (vị thuốc Đông y)", "Hạng Tần Suất (Jun Da)": "6641.0", "Tần Suất % (Jun Da)": "99.9945970114", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 各", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹各", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "各", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "茖", "Unihan_Traditional (Chữ Phồn thể)": "茖", "Pinyin_Xie": "gé", "Âm Hán Việt_Xie": "lạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng làm danh từ để chỉ một loại tỏi hoang dã hoặc thảo dược trong Đông y. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('詾', '{"9000": "6642.0", "Chữ Trung Quốc": "詾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 13 | nét | 詾 | hung | tượng hình | nói rầm rầm, ồn ào | 詾 thuộc bộ 言 (lời nói). Wiktionary không cung cấp phân tích cấu trúc hội ý hay hình thanh. Chữ là dạng khác của 訩.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hung\": lời (言) ồn ào hung hãn — 詾 là tiếng ồn rầm rầm, hỗn loạn. | Gương Hán-Việt | \"hung\" ít dùng trong tiếng Việt; gần với \"hung\" trong hung hăng, hỗn loạn. | Mở khoá kiến thức | Biết 詾 giúp nhận diện chữ cổ mô tả âm thanh hỗn loạn trong văn học cổ điển.", "Tự nguyên_Xie": "Wiktionary ghi 詾 là dạng thay thế (alt form) của 訩 (ồn ào, hỗn loạn). Bộ 言 liên quan đến tiếng nói. Chưa có nguồn học thuật về cấu trúc nội bộ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nói rầm rầm", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 匈", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言匈", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匈", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "詾", "Unihan_Traditional (Chữ Phồn thể)": "詾", "Pinyin_Xie": "xiōng", "Âm Hán Việt_Xie": "hung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này thường làm động từ chỉ hành vi tranh cãi hoặc làm tính từ mô tả sự ồn ào. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('贆', '{"9000": "6643.0", "Chữ Trung Quốc": "贆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 19 | nét | 贆 | tiêu | tượng hình | chữ hiếm bộ bối, nghĩa chưa rõ | 贆 thuộc bộ 貝 (tiền, của cải). Wiktionary không cung cấp phân tích cấu trúc hay giải thích nghĩa cụ thể. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiêu\": của cải (貝) — 贆 là chữ hiếm bộ bối, nghĩa chính xác chưa được xác định. | Gương Hán-Việt | 贆 không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 贆 giúp nhận diện chữ hiếm trong từ điển chữ Hán và văn bản cổ.", "Tự nguyên_Xie": "Wiktionary chỉ ghi âm đọc biāo mà không giải thích nghĩa hay cấu trúc (rfdef). Bộ 貝 gợi liên quan đến tài vật. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "贆", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "貝 + 猋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰貝猋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "猋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "貝", "Unihan_Simplified (Chữ Giản thể)": "贆", "Unihan_Traditional (Chữ Phồn thể)": "贆", "Pinyin_Xie": "biāo", "Âm Hán Việt_Xie": "tiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này là một danh từ cổ rất hiếm gặp dùng để chỉ tiền tài hoặc của cải. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蹨', '{"9000": "6644.0", "Chữ Trung Quốc": "蹨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 19 | nét | 蹨 | niễm | tượng hình | nhảy lên/đứng trên ngón chân | 蹨 thuộc bộ 足 (chân). Wiktionary không cung cấp phân tích cấu trúc hình thanh/hội ý. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"niễm\": chân (足) nhón lên — 蹨 mô tả động tác đứng trên ngón chân hoặc nhảy lên. | Gương Hán-Việt | 蹨 không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 蹨 giúp đọc từ điển phương ngữ Quảng Đông và văn bản mô tả chuyển động.", "Tự nguyên_Xie": "Wiktionary ghi âm đọc niǎn và định nghĩa không rõ (rfdef). Trong tiếng Quảng Đông, mang nghĩa đứng trên ngón chân. Bộ 足 liên quan đến chân/di chuyển. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhảy", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 然", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊然", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "然", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "蹨", "Unihan_Traditional (Chữ Phồn thể)": "蹨", "Pinyin_Xie": "niǎn", "Âm Hán Việt_Xie": "niễm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động giẫm đạp hoặc di chuyển bằng chân. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鰜', '{"9000": "6645.0", "Chữ Trung Quốc": "鰜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 21 | nét | 鰜 | kiêm | tượng hình | loài cá bơn miệng to | 鰜 thuộc bộ 魚 (cá). Wiktionary không cung cấp phân tích cấu trúc hình thanh/hội ý. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiêm\": cá (魚) dẹt — 鰜 là cá bơn miệng rộng, bơi nghiêng mình dưới nước. | Gương Hán-Việt | 鰜 không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 鰜 giúp đọc tài liệu ngư nghiệp và động vật học cổ đại Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi âm đọc jiān/qiàn và nghĩa là loài cá bơn. Bộ 魚 biểu nghĩa loài cá. Tiểu triện đã có dạng chữ này. Chưa có nguồn học thuật về cấu trúc nội bộ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鳒", "Hạng Tần Suất (Jun Da)": "7522.0", "Tần Suất % (Jun Da)": "99.9985607534", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 兼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚兼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鳒", "Unihan_Traditional (Chữ Phồn thể)": "鰜", "Pinyin_Xie": "qiàn", "Âm Hán Việt_Xie": "kiêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài cá bơn mắt lệch về một bên. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('赕', '{"9000": "6646.0", "Chữ Trung Quốc": "赕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 12 | nét | 赕 | đảm | tượng hình | dâng cúng, tiến dâng | 赕 thuộc bộ 貝 (tiền, của cải). Wiktionary không cung cấp phân tích cấu trúc. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đảm\": của cải (貝) được dâng cúng — 赕 là hành động tiến dâng lễ vật, đặc biệt trong văn hóa dân tộc thiểu số vùng Vân Nam. | Gương Hán-Việt | 赕 không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 赕 giúp đọc văn bản văn hóa dân tộc Thái, Bạch và các dân tộc thiểu số miền Nam Trung Quốc.", "Tự nguyên_Xie": "赕 nghĩa là dâng cúng, tiến hiến (phổ biến trong cộng đồng dân tộc thiểu số miền Nam Trung Quốc). Bộ 貝 gợi liên quan đến tài vật được dâng tặng. Chưa có nguồn học thuật về cấu trúc nội bộ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dâng cúng; dâng; cúng", "Hạng Tần Suất (Jun Da)": "6646.0", "Tần Suất % (Jun Da)": "99.9946765963", "GavinGrover_Once (Chiết tự trực tiếp)": "贝 + 炎", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰贝炎", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "炎", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "贝", "Unihan_Simplified (Chữ Giản thể)": "赕", "Unihan_Traditional (Chữ Phồn thể)": "賧", "Pinyin_Xie": "dǎn", "Âm Hán Việt_Xie": "đàm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ việc dâng cúng lễ vật hoặc làm danh từ chỉ tiền chuộc tội theo tập tục xưa. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鯮', '{"9000": "6647.0", "Chữ Trung Quốc": "鯮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 19 | nét | 鯮 | tông | tượng hình | loài cá đầu nhọn miệng như mỏ vịt | 鯮 thuộc bộ 魚 (cá). Wiktionary không cung cấp phân tích cấu trúc. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tông\": cá (魚) đầu nhọn như tông (rồng) — 鯮 là loài cá miệng như mỏ vịt, phổ biến trong ẩm thực Triều Châu. | Gương Hán-Việt | 鯮 không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 鯮 giúp đọc thực đơn hải sản và tài liệu ngư nghiệp vùng Triều Châu, Quảng Đông.", "Tự nguyên_Xie": "Wiktionary mô tả 鯮 là loài cá có đầu nhọn và miệng giống mỏ vịt, phổ biến trong tiếng Triều Châu. Bộ 魚 biểu nghĩa. Chưa có nguồn học thuật về cấu trúc nội bộ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Liệu", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 宗", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚宗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鯮", "Unihan_Traditional (Chữ Phồn thể)": "鯮", "Pinyin_Xie": "zōng", "Âm Hán Việt_Xie": "tông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ để chỉ một loài cá nước ngọt cỡ lớn thuộc họ cá chép. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蔯', '{"9000": "6648.0", "Chữ Trung Quốc": "蔯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 13 | nét | 蔯 | trần | tượng hình | loài ngải cứu (nhân trần 茵蔯) | 蔯 thuộc bộ 艹 (cỏ/thực vật). Không có dữ liệu Wiktionary hay cấu trúc hình thanh/hội ý. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trần\": cỏ (艹) tên trần — 蔯 xuất hiện trong \"nhân trần\" (茵蔯), dược liệu Đông y thanh nhiệt giải độc. | Gương Hán-Việt | \"trần\" trong \"nhân trần\" (茵蔯) — dược liệu thanh nhiệt quen thuộc trong Đông y Việt Nam. | Mở khoá kiến thức | Biết 蔯 giúp nhận diện tên dược liệu Đông y trong đơn thuốc và sách y học cổ truyền.", "Tự nguyên_Xie": "蔯 là thành phần trong dược liệu 茵蔯 (nhân trần) — một loại ngải cứu dùng trong Đông y. Không có nguồn Wiktionary. Bộ 艹 biểu nghĩa thực vật. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: nhân trần 茵蔯)", "Hạng Tần Suất (Jun Da)": "6648.0", "Tần Suất % (Jun Da)": "99.9946977845", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 陳", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹陳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "陳", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蔯", "Unihan_Traditional (Chữ Phồn thể)": "蔯", "Pinyin_Xie": "chén", "Âm Hán Việt_Xie": "trần", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường kết hợp với chữ nhân để tạo thành danh từ chỉ vị thuốc nhân trần. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('貙', '{"9000": "6649.0", "Chữ Trung Quốc": "貙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 豸 | Số nét | 18 | nét | 貙 | xu | tượng hình | loài dã thú hung dữ giống hổ | 貙 thuộc bộ 豸 (thú hung dữ, không có chân). Wiktionary không cung cấp phân tích cấu trúc hội ý hay hình thanh. Kim văn và tiểu triện đã có.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xu\": thú (豸) hung dữ — 貙 là dã thú dữ dằn giống hổ, sức mạnh ghê gớm. | Gương Hán-Việt | 貙 không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 貙 giúp đọc văn học cổ Trung Hoa mô tả thú rừng và thiên nhiên hoang dã.", "Tự nguyên_Xie": "Kim văn | Đại triện | Tiểu triện | Wiktionary ghi 貙 là loài dã thú hung dữ giống hổ. Bộ 豸 biểu thị loài thú hung mạnh. Kim văn, đại triện và tiểu triện đã có dạng chữ này. Chưa có nguồn học thuật về cấu trúc nội bộ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "貙", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "豸 + 區", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰豸區", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "區", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "豸", "Unihan_Simplified (Chữ Giản thể)": "䝙", "Unihan_Traditional (Chữ Phồn thể)": "貙", "Pinyin_Xie": "chū", "Âm Hán Việt_Xie": "xu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này đóng vai trò là danh từ chỉ một loài thú dữ thời cổ đại gần giống như hổ hoặc báo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('躜', '{"9000": "6650.0", "Chữ Trung Quốc": "躜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 23 | nét | 躜 | toản | tượng hình | nhảy vụt lên, xông lên | 躜 thuộc bộ 足 (chân). Không có dữ liệu Wiktionary. Chưa có nguồn học thuật về cấu trúc nội bộ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"toản\": chân (足) xông lên như khoan (鑽) — 躜 là động tác nhảy vọt lên cao hoặc xông thẳng về phía trước. | Gương Hán-Việt | 躜 không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 躜 giúp đọc văn mô tả võ thuật, nhảy nhót và chuyển động mạnh bạo trong tiểu thuyết cổ.", "Tự nguyên_Xie": "躜 không có nguồn Wiktionary. Bộ 足 gợi liên quan đến chân/di chuyển. Nghĩa là nhảy vọt lên, xông lên mạnh mẽ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngoi lên, vụt lên, xông lên", "Hạng Tần Suất (Jun Da)": "6650.0", "Tần Suất % (Jun Da)": "99.9947179391", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 赞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊赞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "赞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "躜", "Unihan_Traditional (Chữ Phồn thể)": "躦", "Pinyin_Xie": "zuān", "Âm Hán Việt_Xie": "toàn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động cúi mình lấy đà rồi nhảy vọt hoặc xông mạnh về phía trước. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鳀', '{"9000": "6651.0", "Chữ Trung Quốc": "鳀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 17 | nét | 鳀 | đề | tượng hình | cá cơm (Engraulidae) | 鳀 thuộc bộ 魚 (cá). Wiktionary không cung cấp phân tích cấu trúc. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đề\": cá (魚) nhỏ — 鳀 là cá cơm, loài cá biển nhỏ được dùng làm mắm và thức ăn phổ biến. | Gương Hán-Việt | 鳀 không có từ Hán-Việt thông dụng; \"cá cơm\" trong tiếng Việt là tên phổ thông. | Mở khoá kiến thức | Biết 鳀 giúp đọc tài liệu ngư nghiệp và ẩm thực hải sản Trung Quốc.", "Tự nguyên_Xie": "Wiktionary (từ dạng phồn thể 鯷) ghi 鳀 ban đầu chỉ cá catfish lớn, sau mở rộng sang cá cơm (anchovy, họ Engraulidae). Bộ 魚 biểu nghĩa. Chưa có nguồn học thuật về cấu trúc nội bộ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá đề; đề; như \"đề (cá cơm)\" (gdhn)", "Hạng Tần Suất (Jun Da)": "6651.0", "Tần Suất % (Jun Da)": "99.9947246573", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 是", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼是", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "是", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鳀", "Unihan_Traditional (Chữ Phồn thể)": "鯷", "Pinyin_Xie": "tí", "Âm Hán Việt_Xie": "đề", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loài cá nhỏ thuộc họ cá cơm trong ngành ngư nghiệp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鹡', '{"9000": "6652.0", "Chữ Trung Quốc": "鹡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 15 | nét | 鹡 | tích | tượng hình | chim tích linh (wagtail) | 鹡 thuộc bộ 鳥 (chim). Wiktionary không cung cấp phân tích cấu trúc. Chỉ dùng trong từ ghép 鹡鸰 (tích linh — chim bẽn lẽn).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tích\": chim (鳥) tích linh — 鹡 chỉ dùng trong 鹡鸰, loài chim vẫy đuôi tích tích, biểu tượng tình huynh đệ trong thơ ca cổ. | Gương Hán-Việt | \"tích\" trong \"tích linh\" (鶺鴒, 鹡鸰) — loài chim nhỏ vẫy đuôi. | Mở khoá kiến thức | Biết 鹡 giúp hiểu điển cố 鶺鴒在原 (chim tích linh trên đồng — điển cố tình huynh đệ) trong thơ Kinh Thi.", "Tự nguyên_Xie": "Wiktionary (dạng phồn thể 鶺) ghi 鹡 chỉ dùng trong 鶺鴒 (鹡鸰) — loài chim wagtail, thường vẫy đuôi. Tên loài chim này xuất hiện trong Kinh Thi. Chưa có nguồn học thuật về cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: tích linh 鶺鴒,鹡鸰)", "Hạng Tần Suất (Jun Da)": "6652.0", "Tần Suất % (Jun Da)": "99.9947313756", "GavinGrover_Once (Chiết tự trực tiếp)": "脊 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰脊鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "脊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鹡", "Unihan_Traditional (Chữ Phồn thể)": "鶺", "Pinyin_Xie": "jí", "Âm Hán Việt_Xie": "tích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường đi liền với chữ linh để tạo thành danh từ chỉ loài chim chìa vôi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蠋', '{"9000": "6654.0", "Chữ Trung Quốc": "蠋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 19 | nét | 虫 | trùng | biểu nghĩa | sâu, côn trùng | 蜀 | thục | biểu âm | âm đọc gần zhú | 蠋 = 虫 (Trùng, biểu nghĩa: sâu/côn trùng) + 蜀 (Thục, biểu âm); chữ hình thanh. Bộ 虫 cho biết đây là loài sâu bướm, 蜀 cung cấp âm zhú.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không có âm chuẩn: sâu (虫) xứ Thục (蜀) — 蠋 là con sâu bướm ăn lá dâu, được Kinh Thi khắc họa. | Gương Hán-Việt | 蠋 không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 蠋 giúp hiểu điển cố trong Kinh Thi (蜎蜎者蠋) và văn học cổ điển Trung Hoa.", "Tự nguyên_Xie": "Chữ hình thanh: 虫 biểu nghĩa, 蜀 biểu âm. 蠋 chỉ loài sâu bướm ăn lá cây. Xuất hiện trong Kinh Thi: \"蜎蜎者蠋，烝在桑野\" (sâu bướm bò lổm ngổm trên ruộng dâu). Chưa có dạng giáp cốt văn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sâu róm ăn lá cây", "Hạng Tần Suất (Jun Da)": "6654.0", "Tần Suất % (Jun Da)": "99.994744812", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 蜀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫蜀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "蜀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蠋", "Unihan_Traditional (Chữ Phồn thể)": "蠋", "Pinyin_Xie": "zhú", "Âm Hán Việt_Xie": "trục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loại sâu bướm lớn ăn lá cây trong nông nghiệp cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钲', '{"9000": "6655.0", "Chữ Trung Quốc": "钲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 10 | nét | 钲 | tranh | tượng hình | nhạc cụ đồng thu quân cổ đại | 钲 thuộc bộ 金 (kim loại). Wiktionary (dạng phồn thể 鉦) không cung cấp phân tích cấu trúc hội ý hay hình thanh rõ ràng. Kim văn, tiểu triện đã có.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tranh\": kim loại (金) vang tiếng tranh — 钲 là cái chiêng đồng cổ đại, đánh lên để ra hiệu thu quân. | Gương Hán-Việt | \"tranh\" trong \"tranh cổ\" (鉦鼓, chiêng trống trong quân đội cổ). | Mở khoá kiến thức | Biết 钲 giúp đọc văn học sử học về quân đội và nhạc lễ cổ đại Trung Quốc.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | Wiktionary (dạng 鉦) mô tả 钲 là nhạc cụ đồng hình chuông hẹp gắn cán dài, đánh bằng dùi, dùng trong chiến trận để thu quân. Kim văn và tiểu triện đã có. Chưa có nguồn học thuật về cấu trúc nội bộ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái chiêng", "Hạng Tần Suất (Jun Da)": "6655.0", "Tần Suất % (Jun Da)": "99.9947515302", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 正", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅正", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "正", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钲", "Unihan_Traditional (Chữ Phồn thể)": "鉦", "Pinyin_Xie": "zhēng", "Âm Hán Việt_Xie": "chinh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại nhạc cụ gõ bằng đồng dùng trong quân đội thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蜁', '{"9000": "6656.0", "Chữ Trung Quốc": "蜁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 13 | nét | 蜁 | huyền | tượng hình | loài ốc sên (蜁蜗) | 蜁 thuộc bộ 虫 (côn trùng/sâu bọ). Wiktionary không cung cấp phân tích cấu trúc. Chỉ dùng trong từ ghép 蜁蜗.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huyền\": sâu (虫) xoáy tròn như huyền (玄 — huyền bí xoắn ốc) — 蜁 là loài ốc sên, vỏ xoắn bí ẩn. | Gương Hán-Việt | 蜁 không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 蜁 giúp nhận diện tên loài ốc sên trong từ điển cổ và văn học tự nhiên Trung Quốc.", "Tự nguyên_Xie": "Wiktionary ghi 蜁 chỉ dùng trong 蜁蜗 (một loại ốc sên). Bộ 虫 biểu nghĩa sinh vật nhỏ. Chưa có nguồn học thuật về cấu trúc nội bộ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "蜁", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "蜁", "Unihan_Traditional (Chữ Phồn thể)": "蜁", "Pinyin_Xie": "xuán", "Âm Hán Việt_Xie": "huyền", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài côn trùng nhỏ hoặc loài ốc sên theo sách cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('兕', '{"9000": "6657.0", "Chữ Trung Quốc": "兕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 儿 | Số nét | 7 | nét | 兕 | tị | tượng hình | trâu rừng/tê giác cái cổ đại | 兕 là chữ tượng hình — vẽ hình loài thú móng guốc lớn. Wiktionary xác nhận đây là chữ tượng hình (liushu: p). Nhiều giáp cốt văn đã ghi lại hình dạng chữ này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tị\": hình con thú lớn móng guốc — 兕 là trâu rừng hay tê giác cổ đại, xuất hiện trong giáp cốt văn nhà Thương. | Gương Hán-Việt | \"tị\" trong \"hổ tị\" (虎兕, hổ và tê giác) — hình ảnh mãnh thú trong Luận Ngữ. | Mở khoá kiến thức | Biết 兕 giúp đọc điển cố trong Luận Ngữ (虎兕出於柙 — hổ tê giác sổng chuồng), Kinh Thi.", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | Lục thư thông | Chữ tượng hình (象形). Giáp cốt văn ghi lại hình dáng con thú móng guốc lớn. Truyền thống coi 兕 là tê giác cái (Bencao Gangmu); nghiên cứu hiện đại cho rằng ban đầu chỉ trâu rừng (Schuessler, 2007). Nhiều giáp cốt và tiểu triện đã có dạng chữ này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con tê giác", "Hạng Tần Suất (Jun Da)": "6657.0", "Tần Suất % (Jun Da)": "99.9947649666", "GavinGrover_Once (Chiết tự trực tiếp)": "凹 + 儿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱凹儿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "凹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "儿", "Unihan_Simplified (Chữ Giản thể)": "兕", "Unihan_Traditional (Chữ Phồn thể)": "兕", "Pinyin_Xie": "sì", "Âm Hán Việt_Xie": "huỷ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ đứng độc lập hoặc làm thành phần trong các từ ghép cổ chỉ loài thú. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('阽', '{"9000": "6658.0", "Chữ Trung Quốc": "阽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 7 | nét | 阽 | điểm | tượng hình | ở bờ vực nguy hiểm | 阽 thuộc bộ 阜 (đồi, bờ đất). Wiktionary không cung cấp phân tích cấu trúc hội ý hay hình thanh. Tiểu triện đã có.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điểm\": đứng trên bờ đất (阜) trượt ngã — 阽 là ở bờ vực nguy hiểm, sắp rơi xuống vực. | Gương Hán-Việt | \"điểm\" trong \"nguy điểm\" (危阽, ở bờ vực nguy hiểm) — từ văn học cổ. | Mở khoá kiến thức | Biết 阽 giúp đọc văn xuôi văn học cổ Trung Hoa mô tả tình trạng nguy cấp.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 阽 có nghĩa văn chương là tiến gần đến nguy hiểm, ở bờ vực. Âm đọc: diàn hoặc yán. Tiểu triện đã có. Chưa có nguồn học thuật về cấu trúc nội bộ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguy khốn", "Hạng Tần Suất (Jun Da)": "6658.0", "Tần Suất % (Jun Da)": "99.9947716848", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + 占", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝占", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "占", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "阽", "Unihan_Traditional (Chữ Phồn thể)": "阽", "Pinyin_Xie": "diàn", "Âm Hán Việt_Xie": "diêm, điếm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ bổ nghĩa cho trạng thái nguy hiểm hoặc động từ chỉ sự kề cận hiểm nguy. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('绋', '{"9000": "6659.0", "Chữ Trung Quốc": "绋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 8 | nét | 绋 | phất | tượng hình | dây thừng lớn buộc quan tài | 绋 thuộc bộ 糸 (dây, sợi). Wiktionary (dạng phồn thể 紼) không cung cấp phân tích cấu trúc hình thanh/hội ý. Tiểu triện đã có.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phất\": dây (糸) to dùng trong tang lễ — 绋 là sợi dây thừng lớn buộc quan tài, tượng trưng lòng tiếc thương trong lễ nghi. | Gương Hán-Việt | \"phất\" trong \"chấp phất\" (執紼, cầm dây quan tài — nghi thức tiễn biệt). | Mở khoá kiến thức | Biết 绋 giúp đọc văn bản lễ nghi tang lễ và điển chế cổ đại Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary (dạng 紼) ghi 绋 là dây thừng lớn dùng để kéo quan tài. Bộ 糸 biểu nghĩa sợi/dây. Tiểu triện đã có. Trong nghi lễ tang lễ cổ đại, nhiều người cùng kéo dây 绋 để hạ quan tài. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dây tam cố (để buộc quan tài)", "Hạng Tần Suất (Jun Da)": "6659.0", "Tần Suất % (Jun Da)": "99.9947851212", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 弗", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟弗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "弗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "绋", "Unihan_Traditional (Chữ Phồn thể)": "紼", "Pinyin_Xie": "fú", "Âm Hán Việt_Xie": "phất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau động từ để chỉ hành động kéo dây quan tài trong tang lễ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铓', '{"9000": "6660.0", "Chữ Trung Quốc": "铓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 11 | nét | 铓 | mang | tượng hình | đầu mũi nhọn của vũ khí | 铓 thuộc bộ 金 (kim loại). Wiktionary (dạng phồn thể 鋩) không cung cấp phân tích cấu trúc hình thanh/hội ý rõ ràng. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mang\": kim loại (金) như mang (芒 — mũi nhọn của bông lúa) — 铓 là đầu nhọn của vũ khí, mũi kiếm sắc bén. | Gương Hán-Việt | \"mang\" trong \"châm mang\" (針鋩, đầu nhọn của kim) — dùng trong mô tả vũ khí và dụng cụ. | Mở khoá kiến thức | Biết 铓 giúp đọc văn miêu tả vũ khí, võ thuật và dụng cụ sắc bén trong văn học cổ.", "Tự nguyên_Xie": "Wiktionary (dạng 鋩) ghi 铓 có nghĩa là đầu nhọn, mũi sắc của lưỡi dao/kiếm. Trong tiếng Phúc Kiến (Chương Châu) còn nghĩa là sắc bén. Bộ 金 biểu nghĩa kim loại. Chưa có nguồn học thuật về cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đầu mũi nhọn", "Hạng Tần Suất (Jun Da)": "6660.0", "Tần Suất % (Jun Da)": "99.9947918394", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 芒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅芒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "芒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铓", "Unihan_Traditional (Chữ Phồn thể)": "鋩", "Pinyin_Xie": "máng", "Âm Hán Việt_Xie": "mang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng trong các từ ghép để chỉ phần sắc bén của vũ khí hoặc tài năng phát lộ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('爝', '{"9000": "6661.0", "Chữ Trung Quốc": "爝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 21 | nét | 爝 | tước | tượng hình | bó đuốc | 爝 thuộc bộ 火 (lửa). Wiktionary không cung cấp phân tích cấu trúc hội ý hay hình thanh. Tiểu triện và lục thư thông đã có.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tước\": lửa (火) bó đuốc nhỏ — 爝 là ngọn lửa đuốc nhỏ, tương phản với ánh sáng mặt trời trong điển cố Trang Tử. | Gương Hán-Việt | \"tước\" ít dùng trong tiếng Việt; 爝 xuất hiện trong điển cố 爝火 (lửa đuốc nhỏ) từ Trang Tử. | Mở khoá kiến thức | Biết 爝 giúp hiểu điển cố 日月出矣爝火不息 (Trang Tử) — ánh sáng nhỏ trước mặt trời lớn.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary ghi 爝 là bó đuốc. Bộ 火 biểu nghĩa lửa. Tiểu triện và lục thư thông đã có. Xuất hiện trong thành ngữ 日月出矣而爝火不息 (mặt trời đã mọc mà đuốc nhỏ chưa tắt — ví người không biết thời thế). | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bó đuốc", "Hạng Tần Suất (Jun Da)": "6661.0", "Tần Suất % (Jun Da)": "99.9947985576", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 爵", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火爵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "爵", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "爝", "Unihan_Traditional (Chữ Phồn thể)": "爝", "Pinyin_Xie": "jué", "Âm Hán Việt_Xie": "tước", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ thường kết hợp với các từ chỉ ánh sáng để ví với ánh sáng yếu ớt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('磾', '{"9000": "6662.0", "Chữ Trung Quốc": "磾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 17 | nét | 磾 | sạn | tượng hình | đá đen dùng nhuộm lụa thời cổ | 磾 là chữ độc thể, không phân tích được thành các thành phần rõ ràng qua cấu trúc hình thanh hay hội ý. Wiktionary chỉ ghi nhận cấu trúc Han etym mà không có compound rõ ràng; đây là chữ chuyên dùng trong danh từ riêng và từ cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sạn\": đá (石) đen cứng như sạn — ngày xưa dùng loại đá này để nhuộm tơ lụa thành màu tối. | Gương Hán-Việt | Không phổ biến trong từ Hán-Việt hiện đại; xuất hiện chủ yếu trong danh từ riêng cổ như \"Kim Nhật Sạn\". | Mở khoá kiến thức | Biết 磾 giúp nhận diện tên nhân vật lịch sử Hán-Hung trong văn bản Hán cổ.", "Tự nguyên_Xie": "磾 chỉ một loại đá đen dùng để nhuộm lụa ở Trung Hoa cổ đại. Chữ gắn liền với danh nhân 金日磾 (Kim Nhật Sạn), người Hung Nô được Hán Vũ Đế sủng ái. Nguồn Wiktionary không cung cấp phân tích cấu trúc; chưa có nguồn học thuật về cơ chế tạo chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "磾", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 單", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石單", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "單", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "磾", "Unihan_Traditional (Chữ Phồn thể)": "磾", "Pinyin_Xie": "dī", "Âm Hán Việt_Xie": "sạn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ trong tên người cổ hoặc tên loại đá nhuộm màu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('螘', '{"9000": "6663.0", "Chữ Trung Quốc": "螘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 16 | nét | 虫 | trùng | biểu nghĩa | sâu bọ, côn trùng | 豈 | biểu âm | cho âm | 螘 = 虫 (Trùng, biểu nghĩa: côn trùng) + 豈 (biểu âm); chữ hình thanh. 虫 xác định lớp nghĩa (loài sâu bọ), 豈 cung cấp âm đọc gốc. Đây là dạng biến thể cổ của 蟻.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nghĩ\" (dị thể của 蟻): con 虫 (trùng) mà biết \"豈\" — con kiến nhỏ bé nhưng siêng năng, biết lo xa. | Gương Hán-Việt | Không có âm Hán-Việt riêng được ghi nhận; đọc theo dạng chính 蟻 (nghĩ). Xuất hiện trong cụm 蟻螘 ở văn cổ. | Mở khoá kiến thức | Biết 螘 giúp nhận diện dị thể của 蟻 trong văn bản cổ điển Trung Hoa.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 螘 là dị thể cổ của 蟻 (kiến). Theo Wiktionary, chữ được cấu thành theo kiểu hình thanh: 虫 biểu nghĩa (côn trùng), 豈 biểu âm. Dạng 蟻 phổ biến hơn trong văn bản hiện đại; 螘 chủ yếu xuất hiện trong văn bản cổ và tự điển. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Kiến", "Hạng Tần Suất (Jun Da)": "6663.0", "Tần Suất % (Jun Da)": "99.9948187122", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 豈", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫豈", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "豈", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "螘", "Unihan_Traditional (Chữ Phồn thể)": "螘", "Pinyin_Xie": "yǐ", "Âm Hán Việt_Xie": "nghĩ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ đứng độc lập hoặc làm thành phần cấu tạo từ chỉ loài kiến trong văn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('仂', '{"9000": "6664.0", "Chữ Trung Quốc": "仂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 4 | nét | 人 | nhân | biểu nghĩa | người | 力 | lực | biểu âm | cho âm | 仂 = 亻/人 (Nhân, biểu nghĩa: người) + 力 (Lực, biểu âm); chữ hình thanh. Bộ nhân 亻 xác định liên quan đến con người hay hoạt động của người; 力 cung cấp âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lặc\": người (亻) dùng sức (力) làm thêm phần dư — 仂 là số dư, phần thặng ra sau khi chia. | Gương Hán-Việt | Không phổ biến trong từ Hán-Việt hiện đại; xuất hiện trong văn bản toán học cổ. | Mở khoá kiến thức | Biết 仂 giúp đọc văn bản toán học và lịch cổ Trung Hoa liên quan đến phép chia và số dư.", "Tự nguyên_Xie": "仂 theo Wiktionary là chữ hình thanh: 人 biểu nghĩa (người), 力 biểu âm. Nghĩa gốc là phần dư, số thừa — thường xuất hiện trong ngữ cảnh tính toán và số học cổ. Ít dùng trong văn bản hiện đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "số dư", "Hạng Tần Suất (Jun Da)": "6664.0", "Tần Suất % (Jun Da)": "99.9948254304", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 力", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻力", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "力", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "仂", "Unihan_Traditional (Chữ Phồn thể)": "仂", "Pinyin_Xie": "lè", "Âm Hán Việt_Xie": "lặc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Số từ | 数词 | Thường làm danh từ trong toán học cổ hoặc kết hợp với số từ để chỉ phần lẻ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Số từ | 数词 | Chỉ số lượng hoặc thứ tự. Hầu như không đứng thẳng trước danh từ mà phải chèn lượng từ ở giữa: 两个人.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('顗', '{"9000": "6665.0", "Chữ Trung Quốc": "顗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 頁 | Số nét | 19 | nét | 顗 | nghi | tượng hình | trầm tĩnh, nghiêm trang | 顗 không có phân tích cấu trúc rõ ràng từ Wiktionary; anchor không cung cấp Han compound. Chữ thuộc bộ 頁 (trang — đầu, trang giấy), gợi liên quan đến dáng vẻ đầu mặt hoặc tính cách của người.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nghi\": dáng vẻ (頁 — đầu) nghiêm nghị, điềm tĩnh — 顗 là người có tư thái đoan trang, không hấp tấp. | Gương Hán-Việt | Không phổ biến trong từ Hán-Việt hiện đại; thường thấy trong tên người hoặc thơ cổ. | Mở khoá kiến thức | Biết 顗 giúp đọc văn bản cổ tả tính cách hoặc nhận diện tên nhân vật lịch sử.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 顗 mang nghĩa trầm tĩnh, nghiêm trang, điềm đạm. Wiktionary không cung cấp phân tích cấu trúc chi tiết; chưa có nguồn học thuật về cơ chế tạo chữ. Chữ ít dùng, chủ yếu xuất hiện trong văn bản văn học và tên người cổ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "闗", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "豈 + 頁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰豈頁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "豈", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "頁", "Unihan_Simplified (Chữ Giản thể)": "𫖮", "Unihan_Traditional (Chữ Phồn thể)": "顗", "Pinyin_Xie": "yǐ", "Âm Hán Việt_Xie": "nghĩ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ miêu tả dáng vẻ cung kính hoặc dùng trong tên người. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蟫', '{"9000": "6666.0", "Chữ Trung Quốc": "蟫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 18 | nét | 蟫 | tầm | tượng hình | con bọc bạc (silverfish — côn trùng gặm giấy sách) | 蟫 không có phân tích Han compound từ Wiktionary. Chữ thuộc bộ 虫 (trùng — côn trùng), xác nhận đây là tên loài côn trùng. Cấu trúc nội bộ không được ghi nhận rõ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tầm\": bộ 虫 (trùng) + thân bạc ánh — 蟫 là con bọc bạc, kẻ thù của sách vở cổ. | Gương Hán-Việt | Không phổ biến trong từ Hán-Việt hiện đại. | Mở khoá kiến thức | Biết 蟫 giúp đọc văn bản cổ về côn trùng hoặc bảo tồn sách vở.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 蟫 chỉ con silverfish (bọc bạc), loài côn trùng nhỏ có màu bạc sống trong sách vở, giấy tờ. Wiktionary chỉ ghi nhận đây là danh từ chỉ loài này, không có phân tích cấu trúc; chưa có nguồn học thuật về cơ chế tạo chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con giòi cá", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 覃", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫覃", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "覃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蟫", "Unihan_Traditional (Chữ Phồn thể)": "蟫", "Pinyin_Xie": "yín", "Âm Hán Việt_Xie": "đàm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ để chỉ loài côn trùng nhỏ chuyên ăn giấy vở. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蕺', '{"9000": "6667.0", "Chữ Trung Quốc": "蕺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 15 | nét | 蕺 | tắc | tượng hình | rau diếp cá (Houttuynia cordata) | 蕺 không có phân tích Han compound từ Wiktionary. Chữ thuộc bộ 艸 (thảo — cỏ, cây), xác nhận đây là tên thực vật. Cấu trúc nội bộ không được ghi nhận rõ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tắc\": bộ 艸 (cỏ) + tên gọi loài cây — 蕺 là rau diếp cá, loài rau quen thuộc với người Việt. | Gương Hán-Việt | Không phổ biến trong từ Hán-Việt hiện đại; biết qua tên khoa học 蕺菜 (diếp cá). | Mở khoá kiến thức | Biết 蕺 giúp đọc văn bản y học cổ và tên thực vật Hán.", "Tự nguyên_Xie": "蕺 chỉ cây rau diếp cá (Houttuynia cordata), loài cây thuốc quen thuộc ở Đông Á và Đông Nam Á, có mùi đặc trưng. Wiktionary xếp vào nhóm tên taxon (sinh vật học). Không có phân tích cấu trúc cụ thể; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rau giấp cá", "Hạng Tần Suất (Jun Da)": "6667.0", "Tần Suất % (Jun Da)": "99.9948523033", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 戢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹戢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "戢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蕺", "Unihan_Traditional (Chữ Phồn thể)": "蕺", "Pinyin_Xie": "jí", "Âm Hán Việt_Xie": "trấp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong y học cổ truyền hoặc tên gọi các loại rau. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('骃', '{"9000": "6668.0", "Chữ Trung Quốc": "骃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 9 | nét | 骃 | nhân | tượng hình | ngựa màu xám đốm trắng | 骃 không có phân tích Han compound từ Wiktionary. Chữ thuộc bộ 馬 (mã — ngựa), xác nhận đây là tính từ chỉ màu sắc hoặc loại ngựa. Cấu trúc nội bộ không được ghi nhận rõ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhân\": bộ 馬 (mã — ngựa) + màu xám bạc — 骃 là ngựa hoa, màu xám có đốm trắng như mây. | Gương Hán-Việt | Không phổ biến trong từ Hán-Việt hiện đại; xuất hiện chủ yếu trong văn học cổ tả ngựa. | Mở khoá kiến thức | Biết 骃 giúp đọc thơ cổ và văn bản mô tả ngựa trong văn học cổ điển Trung Hoa.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 骃 chỉ con ngựa có màu xám đốm trắng. Wiktionary ghi nhận là danh từ/tính từ liên quan đến ngựa nhưng không cung cấp phân tích cấu trúc; chưa có nguồn học thuật về cơ chế tạo chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngựa màu trắng hơi đen", "Hạng Tần Suất (Jun Da)": "6668.0", "Tần Suất % (Jun Da)": "99.9948590215", "GavinGrover_Once (Chiết tự trực tiếp)": "马 + 因", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰马因", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "因", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "马", "Unihan_Simplified (Chữ Giản thể)": "骃", "Unihan_Traditional (Chữ Phồn thể)": "駰", "Pinyin_Xie": "yīn", "Âm Hán Việt_Xie": "nhân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Dùng làm danh từ chỉ loại ngựa có màu lông pha trộn hoặc làm tính từ mô tả màu sắc này. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蔀', '{"9000": "6669.0", "Chữ Trung Quốc": "蔀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 13 | nét | 蔀 | bộ | tượng hình | tấm che bằng cỏ rơm; cũng nghĩa là che khuất, phủ lên | 蔀 không có phân tích Han compound từ Wiktionary. Chữ thuộc bộ 艸 (thảo — cỏ), gợi liên quan đến vật liệu cỏ rơm. Cấu trúc nội bộ không được ghi nhận rõ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bộ\": bộ (艸) rơm rạ dùng làm tấm che — 蔀 là mành cỏ, che nắng che mưa thời xưa. | Gương Hán-Việt | Không phổ biến trong từ Hán-Việt hiện đại; xuất hiện trong văn bản cổ và Kinh Dịch. | Mở khoá kiến thức | Biết 蔀 giúp đọc Kinh Dịch (quẻ Bĩ: 蔀其屋) và văn bản cổ về kiến trúc.", "Tự nguyên_Xie": "蔀 nghĩa là tấm che bằng cỏ rơm dùng để che nắng hoặc che chắn. Nghĩa mở rộng: che khuất, phủ bóng tối. Wiktionary ghi nhận nhưng không cung cấp phân tích cấu trúc chi tiết; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "che lấp", "Hạng Tần Suất (Jun Da)": "6669.0", "Tần Suất % (Jun Da)": "99.9948657397", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 部", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹部", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "部", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蔀", "Unihan_Traditional (Chữ Phồn thể)": "蔀", "Pinyin_Xie": "bù", "Âm Hán Việt_Xie": "bộ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ tấm phên che hoặc động từ với nghĩa che phủ ánh sáng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('诪', '{"9000": "6670.0", "Chữ Trung Quốc": "诪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 9 | nét | 诪 | trù | tượng hình | lừa dối, đánh lừa; hấp tấp vội vàng | 诪 là chữ giản thể; dạng truyền thống là 譸. Wiktionary không cung cấp phân tích Han compound; chữ thuộc bộ 言 (ngôn — lời nói), gợi liên quan đến ngôn từ hoặc hành vi giao tiếp lừa dối.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trù\": bộ 言 (ngôn — lời nói) bên trong có ý gian — 诪 là lời gian dối, nói sai sự thật để đánh lừa. | Gương Hán-Việt | Không phổ biến trong từ Hán-Việt hiện đại; chủ yếu xuất hiện trong cụm 诪张 (phóng đại, lừa bịp). | Mở khoá kiến thức | Biết 诪 giúp đọc văn bản cổ về hành vi gian lận và những thành ngữ liên quan.", "Tự nguyên_Xie": "诪 (dạng truyền thống: 譸) có nghĩa là lừa dối, gian trá. Cũng dùng nghĩa hấp tấp, vội vàng. Wiktionary ghi nhận là biến thể của 侜 (cùng nghĩa lừa dối). Không có phân tích cấu trúc chi tiết; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đắn đo", "Hạng Tần Suất (Jun Da)": "6670.0", "Tần Suất % (Jun Da)": "99.9948724579", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 寿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠寿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "寿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "诪", "Unihan_Traditional (Chữ Phồn thể)": "譸", "Pinyin_Xie": "zhōu", "Âm Hán Việt_Xie": "trù", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ trong văn ngôn cổ để chỉ hành vi lừa gạt hoặc do dự. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('猹', '{"9000": "6671.0", "Chữ Trung Quốc": "猹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 12 | nét | 犭 | biểu nghĩa | chó, thú vật (biến thể của 犬) | 查 | tra | biểu âm | cho âm | 猹 = 犭 (biến thể của 犬 — biểu nghĩa: thú vật) + 查 (Tra, biểu âm); chữ hình thanh. Đây là chữ do nhà văn Lỗ Tấn sáng tạo hoặc ghi chép lại để chỉ một loài dã thú chưa xác định rõ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không có đọc chuẩn; chữ của Lỗ Tấn: thú (犭) mà âm như \"tra\" (查) — con猹 hay trộm dưa trong đêm tối của \"Cố Hương\". | Gương Hán-Việt | Không có đọc Hán-Việt chính thức; chữ văn học sáng tạo của Lỗ Tấn. | Mở khoá kiến thức | Biết 猹 giúp đọc hiểu \"Cố Hương\" của Lỗ Tấn — một trong những tác phẩm quan trọng nhất của văn học hiện đại Trung Quốc.", "Tự nguyên_Xie": "猹 là từ xuất hiện trong truyện ngắn \"Cố Hương\" (故乡) của Lỗ Tấn. Tác giả dùng từ phương ngữ này để chỉ một loài dã thú (được đoán là lửng hoặc cầy hương) thích ăn dưa hấu. Theo Wiktionary, chữ cấu tạo hình thanh: 犭 biểu nghĩa (thú vật), 查 biểu âm. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con tra (dã thú, loài động vật thích ăn dưa, được Lỗ Tấn miêu tả trong tiểu thuyết ''Cố Hương'')", "Hạng Tần Suất (Jun Da)": "6671.0", "Tần Suất % (Jun Da)": "99.9948791761", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 查", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭查", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "查", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "猹", "Unihan_Traditional (Chữ Phồn thể)": "猹", "Pinyin_Xie": "chá", "Âm Hán Việt_Xie": "tra", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loài động vật hoang dã chuyên ăn trộm dưa trong văn học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鋬', '{"9000": "6672.0", "Chữ Trung Quốc": "鋬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 15 | nét | 鋬 | bạn | tượng hình | núm cầm, tay cầm của đồ vật kim loại | 鋬 không có dữ liệu anchor Wiktionary. Chữ thuộc bộ 金 (kim — kim loại), gợi liên quan đến đồ vật bằng kim loại. Cấu trúc nội bộ không xác định được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bạn\": bộ 金 (kim — kim loại) + núm cầm — 鋬 là cái tay cầm kim loại, giúp nắm nồi chậu không bị bỏng. | Gương Hán-Việt | Không phổ biến trong từ Hán-Việt hiện đại. | Mở khoá kiến thức | Biết 鋬 giúp đọc văn bản kỹ thuật cổ về đồ dùng nhà bếp và đồ kim loại.", "Tự nguyên_Xie": "鋬 chỉ núm cầm, tay cầm của các đồ vật kim loại như nồi, chậu. Wiktionary không cung cấp dữ liệu etymology; chưa có nguồn học thuật về cơ chế tạo chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "núm", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "扳 + 金", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱扳金", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "扳", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鋬", "Unihan_Traditional (Chữ Phồn thể)": "鋬", "Pinyin_Xie": "pàn", "Âm Hán Việt_Xie": "phiến", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ bộ phận tay cầm hoặc quai của các dụng cụ chứa đựng bằng kim loại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('齾', '{"9000": "6673.0", "Chữ Trung Quốc": "齾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 齒 | Số nét | 35 | nét | 獻 | hiến | biểu âm | cho âm | 齒 | xỉ | biểu nghĩa | răng | 齾 = 獻 (Hiến, biểu âm) + 齒 (Xỉ, biểu nghĩa: răng); chữ hình thanh. 齒 xác định lớp nghĩa (liên quan đến răng), 獻 cung cấp âm. Chữ có tổng 35 nét — thuộc hàng phức tạp nhất trong bảng chữ Hán.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nha\" (biến âm): bộ 齒 (xỉ — răng) mà mẻ vỡ — 齾 là chiếc răng gãy, sứt hoặc kẽ hở khó coi. | Gương Hán-Việt | Không phổ biến trong từ Hán-Việt hiện đại. | Mở khoá kiến thức | Biết 齾 giúp đọc văn bản y học cổ về nha khoa và miêu tả khuyết tật.", "Tự nguyên_Xie": "齾 theo Wiktionary là chữ hình thanh: 齒 (Xỉ) biểu nghĩa, 獻 biểu âm. Nghĩa: răng bị sứt mẻ hoặc có kẽ hở; cũng dùng cho dụng cụ bị vỡ, mẻ. Chữ rất ít dùng trong văn bản hiện đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sứt mẻ; bị móp; có răng thưa; không có răng", "Hạng Tần Suất (Jun Da)": "6673.0", "Tần Suất % (Jun Da)": "99.9948993307", "GavinGrover_Once (Chiết tự trực tiếp)": "獻 + 齒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱獻齒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "獻", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "齒", "Unihan_Simplified (Chữ Giản thể)": "齾", "Unihan_Traditional (Chữ Phồn thể)": "齾", "Pinyin_Xie": "yà", "Âm Hán Việt_Xie": "ngạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Dùng làm tính từ miêu tả trạng thái sứt mẻ của đồ vật hoặc răng bị khuyết thiếu. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('埕', '{"9000": "6674.0", "Chữ Trung Quốc": "埕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 10 | nét | 土 | thổ | biểu nghĩa | đất, đồ đất nung | 呈 | trình | biểu âm | cho âm | 埕 = 土 (Thổ, biểu nghĩa: đất) + 呈 (Trình, biểu âm); chữ hình thanh. 土 xác định lớp nghĩa (đồ vật bằng đất nung), 呈 cung cấp âm. Âm Hán-Việt ghi lại là \"chĩnh\" — cũng là tên gọi quen thuộc của người Việt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chĩnh\": đất (土) nặn thành vật — 埕 là cái chĩnh, vại sành làm từ đất nung, dùng muối dưa hoặc ủ rượu. | Gương Hán-Việt | \"Chĩnh\" trong tiếng Việt (chum, vại đất nung) chính là âm Hán-Việt của 埕 được bảo tồn nguyên vẹn. | Mở khoá kiến thức | Biết 埕 giúp hiểu gốc Hán của từ \"chĩnh\" trong tiếng Việt — ví dụ điển hình về từ mượn từ tiếng Hán Trung Cổ.", "Tự nguyên_Xie": "埕 theo Wiktionary là chữ hình thanh: 土 (Thổ) biểu nghĩa, 呈 biểu âm. Nghĩa là vại sành, chum đất nung lớn dùng để chứa rượu, dưa muối, hoặc nước. Âm Hán-Việt \"chĩnh\" tương ứng trực tiếp với từ thuần Việt \"chĩnh\" (vại, chum). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái hũ", "Hạng Tần Suất (Jun Da)": "6674.0", "Tần Suất % (Jun Da)": "99.9949060489", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 呈", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土呈", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "呈", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "埕", "Unihan_Traditional (Chữ Phồn thể)": "埕", "Pinyin_Xie": "chéng", "Âm Hán Việt_Xie": "trình", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ loại bình, hũ đất nung cổ truyền dùng để đựng rượu hoặc nước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('虡', '{"9000": "6675.0", "Chữ Trung Quốc": "虡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虍 | Số nét | 13 | nét | 虡 | cự | tượng hình | giá gỗ treo chuông, trống trong nghi lễ cổ | 虡 không có phân tích Han compound từ Wiktionary. Chữ thuộc nhóm đồ vật nghi lễ cổ. Cấu trúc nội bộ không xác định được từ dữ liệu anchor.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cự\": trụ gỗ đứng thẳng (lớn, cứng như 巨) — 虡 là cái giá cao đứng trong miếu đường để treo nhạc cụ cổ. | Gương Hán-Việt | Không phổ biến trong từ Hán-Việt hiện đại; xuất hiện trong văn bản âm nhạc và lễ nghi cổ. | Mở khoá kiến thức | Biết 虡 giúp đọc văn bản về nhạc lễ và nghi lễ cung đình Trung Hoa cổ đại.", "Tự nguyên_Xie": "虡 chỉ giá trụ bằng gỗ dùng để treo chuông (chung) và trống (khánh) trong nghi lễ cung đình Trung Hoa cổ đại. Wiktionary ghi nhận là danh từ lịch sử nhưng không cung cấp phân tích cấu trúc; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái giá (treo chuông, khánh); ghế cao", "Hạng Tần Suất (Jun Da)": "6675.0", "Tần Suất % (Jun Da)": "99.9949262035", "GavinGrover_Once (Chiết tự trực tiếp)": "虚 + 八", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴虚八", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "虚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "八", "Unihan_Simplified (Chữ Giản thể)": "虡", "Unihan_Traditional (Chữ Phồn thể)": "虡", "Pinyin_Xie": "jù", "Âm Hán Việt_Xie": "cự", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ đồ vật cổ, thường đứng sau các từ chỉ chất liệu hoặc hành động chế tác. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('紬', '{"9000": "6676.0", "Chữ Trung Quốc": "紬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 11 | nét | 糸 | biểu nghĩa | tơ lụa (biến thể của 絲) | 由 | do | biểu âm | cho âm | 紬 = 糸 (biểu nghĩa: tơ lụa) + 由 (Do, biểu âm); chữ hình thanh. 糸 xác định lớp nghĩa (vải lụa, sợi tơ), 由 cung cấp âm. Chỉ một loại lụa mỏng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dò\": tơ (糸) từ nguyên nhân (由) — 紬 là lụa mỏng từ tơ tằm kéo ra; \"dò\" gần với \"dệt\" trong âm cổ. | Gương Hán-Việt | \"Dò\" ít xuất hiện trong từ Hán-Việt hiện đại; 紬 là dạng cổ của 綢 (cửu/dò — lụa). | Mở khoá kiến thức | Biết 紬 giúp đọc văn bản cổ về tơ lụa và nhận ra mối liên hệ với 綢 (lụa) trong tiếng Hán hiện đại.", "Tự nguyên_Xie": "Tiểu triện | 紬 theo Wiktionary là chữ hình thanh: 糸 (tơ lụa) biểu nghĩa, 由 biểu âm. Nghĩa là một loại lụa mỏng nhẹ. Âm Hán-Việt \"dò\" phản ánh âm đọc cổ. Chữ ít dùng trong văn bản hiện đại; được thay bởi 綢 (cùng nghĩa lụa). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lụa", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 由", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹由", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "由", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "䌷", "Unihan_Traditional (Chữ Phồn thể)": "紬", "Pinyin_Xie": "chóu", "Âm Hán Việt_Xie": "dò", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ chất liệu vải, thường đứng trước các danh từ chỉ trang phục hoặc làm định ngữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('訢', '{"9000": "6677.0", "Chữ Trung Quốc": "訢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 11 | nét | 言 | ngôn | biểu nghĩa | lời nói, cảm xúc bộc lộ qua lời | 斤 | cân | biểu âm | cho âm | 訢 = 言 (Ngôn, biểu nghĩa: lời nói) + 斤 (Cân, biểu âm); chữ hình thanh. 言 gợi cảm xúc bộc lộ qua lời nói, 斤 cung cấp âm. Nghĩa: vui sướng, hân hoan.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hân\": lời (言) vui mừng như tiếng búa rìu (斤) nặng nề mà nhẹ nhàng — 訢 là niềm vui hân hoan, cùng nghĩa với 欣. | Gương Hán-Việt | Không phổ biến trong từ Hán-Việt hiện đại; dạng thường gặp là 欣 (hân hoan, vui mừng). | Mở khoá kiến thức | Biết 訢 giúp nhận ra biến thể cổ của 欣 trong văn bản cổ điển.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | 訢 theo Wiktionary là chữ hình thanh: 言 (Ngôn) biểu nghĩa, 斤 biểu âm. Nghĩa là vui mừng, hân hoan, thỏa lòng. Có hình ảnh kim văn (bronze) — chữ khá cổ. Ít dùng trong văn bản hiện đại; được thay bởi 欣 (cùng âm, nghĩa tương tự). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sung sướng, mừng, vui vẻ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 斤", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言斤", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "斤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "䜣", "Unihan_Traditional (Chữ Phồn thể)": "訢", "Pinyin_Xie": "xīn", "Âm Hán Việt_Xie": "hân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ biểu thị trạng thái cảm xúc, xuất hiện nhiều trong tên người hoặc từ ghép cổ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蔎', '{"9000": "6678.0", "Chữ Trung Quốc": "蔎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 14 | nét | 蔎 | thiết | tượng hình | một loại cây chè hoặc cây có mùi thơm | 蔎 không có phân tích Han compound từ Wiktionary. Chữ thuộc bộ 艸 (thảo — cỏ cây), xác nhận là tên thực vật. Cấu trúc nội bộ không xác định được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiết\": bộ 艸 (cỏ thơm) — 蔎 là loài cây có mùi thơm nhẹ trong văn bản cổ; ít dùng ngày nay. | Gương Hán-Việt | Không phổ biến trong từ Hán-Việt hiện đại. | Mở khoá kiến thức | Biết 蔎 giúp đọc từ điển cổ về tên cây thảo dược Trung Hoa.", "Tự nguyên_Xie": "蔎 chỉ một loại cây có mùi thơm, có giả thuyết là liên quan đến cây chè hoặc cây thơm cổ. Wiktionary ghi nhận là từ cổ nhưng không cung cấp phân tích cấu trúc; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Thea sinensis", "Hạng Tần Suất (Jun Da)": "6678.0", "Tần Suất % (Jun Da)": "99.9949665128", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 設", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹設", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "設", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蔎", "Unihan_Traditional (Chữ Phồn thể)": "蔎", "Pinyin_Xie": "shè", "Âm Hán Việt_Xie": "thiết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ trong văn ngôn để chỉ các loại thực vật hoặc hương liệu cổ xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('繸', '{"9000": "6679.0", "Chữ Trung Quốc": "繸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 18 | nét | 繸 | choại | tượng hình | tua rua, tua viền của đồ trang trí hoặc tang phục | 繸 không có dữ liệu anchor Wiktionary. Chữ thuộc bộ 糸 (mịch — sợi tơ), xác nhận liên quan đến vải vóc. Cấu trúc nội bộ không xác định được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"choại\": bộ 糸 (sợi tơ) buông thõng xuống — 繸 là những tua rua tơ lụa buông rủ ở viền áo cổ. | Gương Hán-Việt | Không phổ biến trong từ Hán-Việt hiện đại. | Mở khoá kiến thức | Biết 繸 giúp đọc văn bản lễ nghi về y phục và tang lễ cổ Trung Hoa.", "Tự nguyên_Xie": "繸 chỉ tua rua, tua viền của y phục hoặc đồ tang. Wiktionary không cung cấp dữ liệu etymology; chưa có nguồn học thuật về cơ chế tạo chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "縸", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 遂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹遂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "遂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "䍁", "Unihan_Traditional (Chữ Phồn thể)": "繸", "Pinyin_Xie": "suì", "Âm Hán Việt_Xie": "choại", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ phụ kiện trang phục cổ, thường đi sau các động từ như đeo, thắt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('绖', '{"9000": "6680.0", "Chữ Trung Quốc": "绖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 9 | nét | 绖 | điệt | tượng hình | dây đai gai đeo trong tang lễ | 绖 không có phân tích Han compound từ Wiktionary. Chữ thuộc bộ 糸 (mịch — sợi), xác nhận liên quan đến vải vóc dùng trong tang lễ. Cấu trúc nội bộ không xác định được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điệt\": sợi (糸) gai thắt ngang — 绖 là dây đai tang, biểu tượng của nỗi đau mất người thân trong lễ tang cổ. | Gương Hán-Việt | Không phổ biến trong từ Hán-Việt hiện đại. | Mở khoá kiến thức | Biết 绖 giúp đọc văn bản về lễ nghi tang tế cổ điển Trung Hoa.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 绖 chỉ dây đai làm bằng cây gai (hemp) mà người để tang đeo quanh đầu hoặc thắt lưng theo lễ nghi cổ Trung Hoa. Wiktionary xác nhận nghĩa nhưng không phân tích cấu trúc; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vải gai (làm đồ tang)", "Hạng Tần Suất (Jun Da)": "6680.0", "Tần Suất % (Jun Da)": "99.9949789156", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 至", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟至", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "至", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "绖", "Unihan_Traditional (Chữ Phồn thể)": "絰", "Pinyin_Xie": "dié", "Âm Hán Việt_Xie": "điệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ đồ tang lễ ngày xưa, thường dùng trong các cụm từ mô tả nghi thức tang chế. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('埭', '{"9000": "6681.0", "Chữ Trung Quốc": "埭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 11 | nét | 埭 | đạo | tượng hình | đập đất, đê nhỏ ngăn nước | 埭 không có phân tích Han compound từ Wiktionary. Chữ thuộc bộ 土 (thổ — đất), xác nhận liên quan đến công trình đất đắp. Cấu trúc nội bộ không xác định được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đạo\": đất (土) đắp chắn ngang — 埭 là đập đất nhỏ, đê thấp chắn dòng chảy của nước. | Gương Hán-Việt | Không phổ biến trong từ Hán-Việt hiện đại; thường thấy trong địa danh hoặc văn bản nông nghiệp cổ. | Mở khoá kiến thức | Biết 埭 giúp đọc văn bản nông nghiệp cổ và nhận ra trong địa danh Trung Hoa.", "Tự nguyên_Xie": "埭 chỉ đập đất nhỏ hoặc đê chắn nước, dùng trong nông nghiệp và thủy lợi cổ. Wiktionary ghi nhận nhưng không phân tích cấu trúc; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đập ngăn nước", "Hạng Tần Suất (Jun Da)": "6681.0", "Tần Suất % (Jun Da)": "99.9949851171", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 隶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土隶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "隶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "埭", "Unihan_Traditional (Chữ Phồn thể)": "埭", "Pinyin_Xie": "dài", "Âm Hán Việt_Xie": "đại", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ công trình thủy lợi, thường kết hợp với tên địa danh để chỉ các con đập cụ thể. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('駮', '{"9000": "6682.0", "Chữ Trung Quốc": "駮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 16 | nét | 駮 | bác | tượng hình | ngựa hoa (lông đốm nhiều màu); bác bỏ, phản bác | 駮 không có phân tích Han compound từ Wiktionary. Chữ thuộc bộ 馬 (mã — ngựa), xác nhận liên quan đến ngựa. Cấu trúc nội bộ không xác định được từ anchor.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bác\": ngựa (馬) có màu lông lẫn lộn — 駮 là ngựa đốm; và vì \"lẫn lộn\" nên mở rộng thành \"bác bỏ\" lý lẽ rối mù. | Gương Hán-Việt | \"Bác\" trong \"phản bác\", \"bác bỏ\" — 駮 là dạng cổ, hiện đại dùng 驳. | Mở khoá kiến thức | Biết 駮 giúp đọc văn bản cổ về ngựa và nhận ra gốc của từ \"bác bỏ\" trong tiếng Hán.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 駮 có hai nghĩa: (1) ngựa có lông nhiều màu (ngựa hoa, ngựa đốm); (2) phản bác, bác bỏ (cùng nghĩa với 驳). Wiktionary chỉ ghi nhận {{Han etym}} mà không phân tích; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "loang lổ; lẫn lộn; phản bác, chống lại", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "馬 + 交", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰馬交", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "交", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "駮", "Unihan_Traditional (Chữ Phồn thể)": "駮", "Pinyin_Xie": "bó", "Âm Hán Việt_Xie": "bác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ mang tân ngữ để biểu thị sự phản đối hoặc làm tính từ chỉ màu sắc không đều. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鰡', '{"9000": "6683.0", "Chữ Trung Quốc": "鰡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 21 | nét | 鰡 | lưu | tượng hình | loài cá (chưa xác định rõ) | 鰡 không có phân tích Han compound từ Wiktionary. Chữ thuộc bộ 魚 (ngư — cá), xác nhận là tên một loài cá. Cấu trúc nội bộ không xác định được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lưu\": bộ 魚 (ngư — cá) lưu động — 鰡 là một loài cá ít được biết đến, bơi theo dòng chảy. | Gương Hán-Việt | Không phổ biến trong từ Hán-Việt hiện đại. | Mở khoá kiến thức | Biết 鰡 giúp đọc từ điển sinh vật học cổ và văn bản ngư nghiệp Trung Hoa.", "Tự nguyên_Xie": "鰡 chỉ một loài cá chưa được xác định rõ trong tài liệu. Wiktionary ghi nhận rfdef (cần định nghĩa) — nghĩa chưa đủ tư liệu; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "radon", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 留", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚留", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "留", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鰡", "Unihan_Traditional (Chữ Phồn thể)": "鰡", "Pinyin_Xie": "liú", "Âm Hán Việt_Xie": "lưu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ loài cá, thường dùng trong các văn bản chuyên ngành sinh học hoặc ẩm thực địa phương. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鵳', '{"9000": "6684.0", "Chữ Trung Quốc": "鵳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 19 | nét | 鵳 | kiên | tượng hình | tên chim, chỉ dùng trong từ ghép 鶗鵳 | 鵳 không có phân tích Han compound từ Wiktionary. Chữ thuộc bộ 鳥 (điểu — chim), xác nhận là tên loài chim. Chữ chỉ xuất hiện trong tổ hợp cố định 鶗鵳. Cấu trúc nội bộ không xác định được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiên\": bộ 鳥 (điểu — chim) + âm kiên — 鵳 chỉ sống trong từ kép 鶗鵳, tên một loài chim cổ bí ẩn. | Gương Hán-Việt | Không phổ biến trong từ Hán-Việt hiện đại. | Mở khoá kiến thức | Biết 鵳 giúp đọc thơ cổ và từ điển chim thú trong văn học cổ điển.", "Tự nguyên_Xie": "鵳 chỉ dùng trong tổ hợp 鶗鵳 — tên một loài chim trong văn học cổ Trung Hoa (có thể là loài cú hoặc chim không xác định). Wiktionary ghi nhận {{zh-only|鶗鵳}}, không có phân tích cấu trúc; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Kỷ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "肩 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰肩鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "肩", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鵳", "Unihan_Traditional (Chữ Phồn thể)": "鵳", "Pinyin_Xie": "jiān", "Âm Hán Việt_Xie": "kiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài chim săn mồi nhỏ thuộc họ ưng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('柁', '{"9000": "6685.0", "Chữ Trung Quốc": "柁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 9 | nét | 柁 | xà | tượng hình | xà nhà (dầm gỗ lớn) hoặc bánh lái thuyền | 柁 không có phân tích Han compound từ Wiktionary (chỉ ghi {{Han etym}}). Chữ thuộc bộ 木 (mộc — gỗ), xác nhận là vật dụng bằng gỗ. Có hai nghĩa: dầm gỗ lớn trong kiến trúc, hoặc bánh lái thuyền.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xà\": gỗ (木) nằm ngang nâng đỡ — 柁 là cái xà nhà, dầm gỗ lớn; \"xà\" trong \"xà nhà\" tiếng Việt chính là âm Hán-Việt của 柁. | Gương Hán-Việt | \"Xà\" trong tiếng Việt (xà nhà, cột xà) bảo tồn âm Hán-Việt cổ của 柁. | Mở khoá kiến thức | Biết 柁 giúp hiểu gốc Hán của từ \"xà nhà\" trong tiếng Việt và các thuật ngữ kiến trúc cổ.", "Tự nguyên_Xie": "柁 theo bộ 木 (Mộc — gỗ), chỉ dầm gỗ lớn nằm ngang (xà ngang) trong kiến trúc cổ, hoặc bánh lái thuyền. Wiktionary chỉ ghi {{Han etym}} không có phân tích; chưa có nguồn học thuật. Âm Hán-Việt \"xà\" còn được bảo tồn trong từ \"xà nhà\" (dầm ngang). | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bánh lái thuyền", "Hạng Tần Suất (Jun Da)": "6685.0", "Tần Suất % (Jun Da)": "99.9950099227", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 它", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木它", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "它", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "柁", "Unihan_Traditional (Chữ Phồn thể)": "柁", "Pinyin_Xie": "duò", "Âm Hán Việt_Xie": "đà", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ bánh lái của thuyền hoặc đòn tay trong kiến trúc gỗ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('筴', '{"9000": "6686.0", "Chữ Trung Quốc": "筴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 13 | nét | 筴 | sách | tượng hình | thẻ bói, thẻ tre dùng trong bói toán | 筴 không có phân tích Han compound từ Wiktionary. Chữ thuộc bộ 竹 (trúc — tre), xác nhận liên quan đến vật dụng bằng tre. Là dạng cổ của 策 (cũng viết 筴).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sách\": tre (竹) dùng để tính toán — 筴 là thẻ tre bói toán; cùng gốc với \"sách\" trong \"mưu sách\", \"kế sách\". | Gương Hán-Việt | Không phổ biến trong từ Hán-Việt hiện đại; dạng thường dùng là 策 (sách — kế sách). | Mở khoá kiến thức | Biết 筴 giúp đọc văn bản bói toán và nhận ra gốc cổ của 策 (sách lược, kế sách).", "Tự nguyên_Xie": "筴 là dạng cổ của 策 — thẻ tre dùng trong bói toán. Theo Wiktionary (đề mục 策), nghĩa là thẻ bói, dùng để tiên đoán, tính toán. Wiktionary cho thấy đây là dạng biến thể, với etymology của 策. Cấu trúc nội bộ không xác định qua anchor. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "䇲", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 夾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮夾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "筴", "Unihan_Traditional (Chữ Phồn thể)": "筴", "Pinyin_Xie": "cè", "Âm Hán Việt_Xie": "giáp, hiệp, kiệp, sách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ thẻ tre dùng để bói toán hoặc động từ chỉ việc quất roi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('珧', '{"9000": "6687.0", "Chữ Trung Quốc": "珧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 10 | nét | 玉 | ngọc | biểu nghĩa | ngọc, đồ quý | 兆 | triệu | biểu âm | cho âm | 珧 = 玉 (Ngọc, biểu nghĩa: ngọc, đồ quý) + 兆 (Triệu, biểu âm); chữ hình thanh. 玉 xác định lớp nghĩa (đồ vật quý như ngọc), 兆 cung cấp âm. Chỉ vỏ trai biển có thể dùng làm đồ trang sức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dao\": ngọc (玉) ánh lên từ vỏ trai — 珧 là xà cừ, vỏ trai óng ánh như ngọc dùng trang trí. | Gương Hán-Việt | Không phổ biến trong từ Hán-Việt hiện đại; xuất hiện trong tên món ăn hải sản như 江珧柱 (gan điệp). | Mở khoá kiến thức | Biết 珧 giúp đọc thực đơn hải sản cao cấp và văn bản cổ về đồ trang sức.", "Tự nguyên_Xie": "Tiểu triện | 珧 theo Wiktionary là chữ hình thanh: 玉 (Ngọc) biểu nghĩa, 兆 biểu âm. Nghĩa là vỏ của loài trai 蜃 — loại vỏ óng ánh như ngọc trai, dùng trang trí cung tên (弓珧). Cũng dùng trong 江珧 (sò điệp lớn). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con trai biển (làm ngọc trai); ngọc diêu; cung nạm ngọc trai", "Hạng Tần Suất (Jun Da)": "6687.0", "Tần Suất % (Jun Da)": "99.9950223256", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 兆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王兆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "珧", "Unihan_Traditional (Chữ Phồn thể)": "珧", "Pinyin_Xie": "yáo", "Âm Hán Việt_Xie": "diêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ loài trai sông hoặc phần vỏ sò dùng để trang trí đồ vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('贳', '{"9000": "6688.0", "Chữ Trung Quốc": "贳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 9 | nét | 贳 | thể | tượng hình | cho vay, cho mượn; tha thứ, xá tội | 贳 là chữ giản thể của 貰. Wiktionary xác nhận: 贳 = 貰 giản thể hóa bộ 貝 thành 贝. Cấu trúc đầy đủ của 貰 không được phân tích trong anchor; bộ 貝 (bối — tiền của, tài sản) cho thấy liên quan đến giao dịch kinh tế.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thể\": tiền (貝/贝) cho đi một phần — 贳 là cho mượn, cho nợ; cũng là tha nợ, xá tội. | Gương Hán-Việt | Không phổ biến trong từ Hán-Việt hiện đại. | Mở khoá kiến thức | Biết 贳 giúp đọc văn bản pháp lý cổ về vay mượn và tha thứ.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 贳 là chữ giản thể của 貰 — theo Wiktionary, 贝 là dạng giản thể của 貝. Nghĩa: cho vay (với lãi), cho thuê, tha thứ. Bộ 貝 (tiền bạc) xác nhận liên quan đến giao dịch tài chính. Chữ dùng nhiều hơn trong văn bản cổ và pháp lý. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cho vay, cho thuê; tha thứ, xá tội", "Hạng Tần Suất (Jun Da)": "6688.0", "Tần Suất % (Jun Da)": "99.995028527", "GavinGrover_Once (Chiết tự trực tiếp)": "世 + 贝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱世贝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "世", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "贝", "Unihan_Simplified (Chữ Giản thể)": "贳", "Unihan_Traditional (Chữ Phồn thể)": "貰", "Pinyin_Xie": "shì", "Âm Hán Việt_Xie": "thế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ chỉ tiền bạc, hàng hóa hoặc tội lỗi được tha thứ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('贶', '{"9000": "6689.0", "Chữ Trung Quốc": "贶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 9 | nét | 贶 | huống | tượng hình | ban cho, trao tặng; họ người | 贶 là chữ giản thể của 貺. Wiktionary ghi nhận là dạng 貺 không có phân tích Han compound rõ ràng; bộ 貝/贝 (bối — tiền của) xác nhận liên quan đến hành vi tặng quà có giá trị. Cấu trúc nội bộ không xác định được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huống\": tiền của (貝/贝) ban tặng từ trên xuống — 贶 là ân ban, quà tặng từ người có địa vị cao hơn. | Gương Hán-Việt | Không phổ biến trong từ Hán-Việt hiện đại; xuất hiện trong cụm 天貺節 (Thiên Huống Tiết — ngày lễ cổ). | Mở khoá kiến thức | Biết 贶 giúp đọc văn thư ngoại giao cổ và tên ngày lễ trong lịch cổ Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | 贶 (dạng cổ: 貺) theo Wiktionary là chữ mang nghĩa ban cho, trao tặng với ý kính trọng — thường dùng khi người trên ban ân cho kẻ dưới. Cũng là họ người trong tiếng Hán. Không có phân tích cấu trúc; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ban cho", "Hạng Tần Suất (Jun Da)": "6689.0", "Tần Suất % (Jun Da)": "99.9950347284", "GavinGrover_Once (Chiết tự trực tiếp)": "贝 + 兄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰贝兄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "贝", "Unihan_Simplified (Chữ Giản thể)": "贶", "Unihan_Traditional (Chữ Phồn thể)": "貺", "Pinyin_Xie": "kuàng", "Âm Hán Việt_Xie": "huống", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong văn phong cổ kính để chỉ việc bề trên ban tặng cho bề dưới. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('腩', '{"9000": "6690.0", "Chữ Trung Quốc": "腩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 13 | nét | 肉 | nhục | biểu nghĩa | thịt, thân thể | 南 | nam | biểu âm | cho âm | 腩 = 肉 (Nhục, biểu nghĩa: thịt) + 南 (Nam, biểu âm); chữ hình thanh. 肉 xác định lớp nghĩa (thịt, bộ phận cơ thể), 南 cung cấp âm. Chỉ phần thịt ức bò, sườn bò.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nem\": thịt (肉) phía nam (南 — bụng dưới) — 腩 là phần nạm, thịt bụng dưới bò; \"nem\" trong 牛腩 phát âm gần với \"nạm\" tiếng Việt. | Gương Hán-Việt | \"Nem\" trong tiếng Việt có thể liên quan đến âm Hán-Việt cổ của 腩 qua đường ẩm thực Quảng Đông. | Mở khoá kiến thức | Biết 腩 giúp đọc thực đơn ẩm thực Quảng Đông và Hồng Kông, đặc biệt các món 牛腩.", "Tự nguyên_Xie": "腩 theo Wiktionary là chữ hình thanh: 肉 (Nhục) biểu nghĩa, 南 biểu âm. Nghĩa là phần thịt ức bò (brisket) hoặc thịt nạm bò — phần mềm mỡ dưới bụng và sườn. Đặc biệt phổ biến trong ẩm thực Quảng Đông với từ 牛腩 (thịt nạm bò). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nem, thịt trâu ngon", "Hạng Tần Suất (Jun Da)": "6690.0", "Tần Suất % (Jun Da)": "99.9950409298", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 南", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月南", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "南", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "腩", "Unihan_Traditional (Chữ Phồn thể)": "腩", "Pinyin_Xie": "nǎn", "Âm Hán Việt_Xie": "nạm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ phần thịt ở bụng của bò, lợn trong ẩm thực. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('臌', '{"9000": "6691.0", "Chữ Trung Quốc": "臌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 17 | nét | 臌 | cổ | tượng hình | bụng trướng, bụng phình to do bệnh | 臌 không có dữ liệu anchor Wiktionary. Chữ thuộc bộ 肉/月 (nhục — thịt, cơ thể), xác nhận liên quan đến thân thể. Cấu trúc nội bộ không xác định được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cổ\": bụng (肉/月) phình như trống — 臌 là chứng bụng trướng; \"cổ\" gợi tiếng trống (鼓 — cùng âm), bụng căng như trống. | Gương Hán-Việt | Không phổ biến trong từ Hán-Việt hiện đại; xuất hiện trong văn bản y học Đông y. | Mở khoá kiến thức | Biết 臌 giúp đọc văn bản y học cổ truyền Trung Hoa về các chứng bệnh tiêu hóa.", "Tự nguyên_Xie": "臌 chỉ chứng bụng trướng, bụng phình to do bệnh (ascites hoặc các rối loạn tiêu hóa). Đây là thuật ngữ y học cổ truyền Trung Hoa. Wiktionary không cung cấp dữ liệu; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bệnh trướng", "Hạng Tần Suất (Jun Da)": "6691.0", "Tần Suất % (Jun Da)": "99.9950471313", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 鼓", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月鼓", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鼓", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "臌", "Unihan_Traditional (Chữ Phồn thể)": "臌", "Pinyin_Xie": "gǔ", "Âm Hán Việt_Xie": "cổ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ chứng bệnh cổ trướng hoặc tính từ mô tả trạng thái bụng bị phình to. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('礓', '{"9000": "6692.0", "Chữ Trung Quốc": "礓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 18 | nét | 礓 | cương | tượng hình | đường dốc sần sùi, bậc đá xây bằng viên sỏi | 礓 không có phân tích Han compound từ Wiktionary. Chữ thuộc bộ 石 (thạch — đá), xác nhận liên quan đến đá hoặc mặt đường. Cấu trúc nội bộ không xác định được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cương\": đá (石) cứng sần sùi — 礓 là mặt dốc đá sỏi, hoặc đường bậc thềm xây bằng sỏi chống trơn. | Gương Hán-Việt | Không phổ biến trong từ Hán-Việt hiện đại. | Mở khoá kiến thức | Biết 礓 giúp đọc văn bản kiến trúc và địa lý cổ Trung Hoa.", "Tự nguyên_Xie": "礓 chỉ một loại mặt đường dốc xây bằng viên sỏi nhỏ để chống trơn trượt, hoặc mặt đất sần sùi với đá lộ ra. Wiktionary ghi nhận nhưng không phân tích cấu trúc; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thềm", "Hạng Tần Suất (Jun Da)": "6692.0", "Tần Suất % (Jun Da)": "99.9950533327", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 畺", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石畺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "畺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "礓", "Unihan_Traditional (Chữ Phồn thể)": "礓", "Pinyin_Xie": "jiāng", "Âm Hán Việt_Xie": "cương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ các bậc thềm dốc lát bằng gạch đá chống trơn trượt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('袛', '{"9000": "6693.0", "Chữ Trung Quốc": "袛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 10 | nét | 袛 | đê | tượng hình | áo mỏng một lớp, y phục đơn giản | 袛 không có phân tích Han compound từ Wiktionary. Chữ thuộc bộ 衣 (y — áo, quần áo), xác nhận là tên loại y phục. Cấu trúc nội bộ không xác định được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đê\": áo (衣) mỏng nhẹ — 袛 là áo đơn mỏng, may bằng một lớp vải để mặc mùa nóng. | Gương Hán-Việt | Không phổ biến trong từ Hán-Việt hiện đại. | Mở khoá kiến thức | Biết 袛 giúp đọc văn bản cổ về y phục và trang phục truyền thống Trung Hoa.", "Tự nguyên_Xie": "袛 chỉ loại áo mỏng, chỉ một lớp vải, mặc khi trời nóng hoặc làm lót. Wiktionary ghi nhận nhưng không phân tích cấu trúc; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Chuyển", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 氐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤氐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "氐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "袛", "Unihan_Traditional (Chữ Phồn thể)": "袛", "Pinyin_Xie": "dī", "Âm Hán Việt_Xie": "đê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ một loại áo ngắn hoặc vạt áo trong trang phục cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('貐', '{"9000": "6694.0", "Chữ Trung Quốc": "貐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 豸 | Số nét | 16 | nét | 貐 | dũ | tượng hình | con quái thú đầu người mình hổ trong thần thoại Trung Hoa | 貐 là chữ tượng hình/độc thể, không có bộ phận hình thanh hay hội ý rõ ràng trong tự điển; thuộc bộ 豸 (trĩ — thú dữ không xương sống). Chữ chỉ con quái thú 猰貐 (yà yǔ) trong thần thoại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dũ\" (trong \"yết dũ\", \"khiết dũ\"): con quái thú đầu người mình hổ — bộ 豸 (thú dữ) gợi ngay bản chất hung hiểm của nó. | Gương Hán-Việt | 猰貐 (yết dũ) — tên quái thú thần thoại | Mở khoá kiến thức | Biết 貐 mở khoá tên quái vật trong Sơn Hải Kinh và các văn bản thần thoại cổ Trung Hoa.", "Tự nguyên_Xie": "Wiktionary ghi 貐 là dạng thay thế của 㺄, một con thú thần thoại trong cổ văn. Không có glyph giáp cốt hay kim văn được ghi nhận. Chữ thuộc nhóm tạo muộn, xuất hiện trong văn bản thời trung đại để chỉ con quái thú đầu người mình hổ trong 山海經 (Sơn Hải Kinh). Chưa có nguồn học thuật xác định cấu trúc hình-âm. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xem: khiết dũ, nghiệt dũ 猰貐", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "豸 + 俞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰豸俞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "俞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "豸", "Unihan_Simplified (Chữ Giản thể)": "貐", "Unihan_Traditional (Chữ Phồn thể)": "貐", "Pinyin_Xie": "yǔ", "Âm Hán Việt_Xie": "dũ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ trong danh từ ghép chỉ loài mãnh thú trong truyền thuyết Trung Hoa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蹐', '{"9000": "6695.0", "Chữ Trung Quốc": "蹐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 17 | nét | 足 | túc | biểu nghĩa | chân | 脊 | tích | biểu âm | xương sống — cho âm | 蹐 là chữ hình thanh: 足 (Túc, biểu nghĩa — chân) + 脊 (Tích, biểu âm — xương sống, cho âm gần jǐ/jí). Chữ chỉ hành động bước chân nhỏ, lê bước.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tích\" (bước nhỏ): bộ 足 (chân) + âm 脊 — hình ảnh người rón rén bước từng bước nhỏ xíu vì lo sợ. | Gương Hán-Việt | 跼蹐 (cúc tích) — bước chân nhỏ, khom người lo lắng | Mở khoá kiến thức | Biết 蹐 mở khoá thành ngữ cổ văn 跼蹐不安 và 蹐地跼天 trong văn học Hán.", "Tự nguyên_Xie": "Wiktionary ghi 蹐 là động từ văn ngôn chỉ \"bước chân nhỏ, lê bước\" (to walk with small steps). Xuất hiện trong thành ngữ cổ 跼蹐不安 (cúc tích bất an — khom người bước nhỏ, tỏ vẻ bất an) và 蹐地跼天 (trời thấp đất hẹp, mô tả cảnh khốn đốn). Cấu trúc hình thanh: bộ 足 cho nghĩa liên quan đến bước chân; 脊 cho âm. Chưa có nguồn học thuật chi tiết hơn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bước ngắn; lê chân đi", "Hạng Tần Suất (Jun Da)": "6695.0", "Tần Suất % (Jun Da)": "99.995071937", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 脊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊脊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "脊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "蹐", "Unihan_Traditional (Chữ Phồn thể)": "蹐", "Pinyin_Xie": "jí", "Âm Hán Việt_Xie": "tích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ mô tả dáng đi khép nép, rón rén hoặc bước đi ngắn do sợ hãi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('圬', '{"9000": "6696.0", "Chữ Trung Quốc": "圬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 6 | nét | 土 | thổ | biểu nghĩa | đất, đất sét | 亏 | khuy | biểu âm | cho âm (biến thể của 于) | 圬 là chữ hình thanh: 土 (Thổ, biểu nghĩa — đất, đất xây) + 亏/于 (Khuy, biểu âm). Wiktionary ghi rõ: {{Han compound|土|于|alt2=亏|ls=psc|c1=s|t1=earth|c2=p}}. Chữ chỉ việc trát vữa, xây tường.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hũ\" (thợ nề): 土 (đất sét) + 亏 (cho âm) — thợ xây dùng đất trát tường, đúng nghĩa chữ này. | Gương Hán-Việt | 圬者 (hũ giả) — thợ nề, thợ xây | Mở khoá kiến thức | Biết 圬 mở khoá từ 圬者 (hũ giả — thợ nề) trong cổ văn, đặc biệt văn Hàn Dũ.", "Tự nguyên_Xie": "Wiktionary ghi 圬 là chữ hình thanh, gồm 土 (đất, đất sét — biểu nghĩa) và 于/亏 (biểu âm). So sánh với 圩. Nghĩa gốc là \"trát vữa đất lên tường\" — công việc của thợ nề thời cổ. Hàn Dũ (韓愈) có bài 「圬者王承福傳」(Truyện thợ xây Vương Thừa Phúc) nhắc đến nghề này. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thợ nề, thợ xây", "Hạng Tần Suất (Jun Da)": "6696.0", "Tần Suất % (Jun Da)": "99.9950781384", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 亏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土亏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "圬", "Unihan_Traditional (Chữ Phồn thể)": "圬", "Pinyin_Xie": "wū", "Âm Hán Việt_Xie": "ô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này thường dùng làm danh từ chỉ người thợ nề hoặc làm động từ chỉ hành động trát tường. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('堠', '{"9000": "6697.0", "Chữ Trung Quốc": "堠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 12 | nét | 土 | thổ | biểu nghĩa | đất, đất đắp | 侯 | hầu | biểu âm | cho âm hòu/hầu | 堠 là chữ hình thanh: 土 (Thổ, biểu nghĩa — đất, đắp đất) + 侯 (Hầu, biểu âm). Wiktionary: {{Han compound|土|侯|c1=s|c2=p|t1=soil; earth|ls=psc}}. Chữ chỉ ụ đất quan sát quân sự, lô cốt đất.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hậu\" (lô cốt, ụ đất): 土 (đất đắp) + 侯 (âm hầu) — hình ảnh ụ đất cao đắp lên để lính canh quan sát địch. | Gương Hán-Việt | 斥堠 (xích hậu) — lính canh quan sát, trinh thám | Mở khoá kiến thức | Biết 堠 mở khoá từ 里堠 (ụ cột mốc dặm đường) và 斥堠 (lính trinh thám) trong cổ văn quân sự.", "Tự nguyên_Xie": "Wiktionary ghi 堠 là chữ hình thanh: bộ 土 (đất — biểu nghĩa) và 侯 (biểu âm). Nghĩa gốc là ''ụ đất quan sát'' (earthen watchtower) — một dạng công trình quân sự cổ đại đắp bằng đất để canh giữ đường đi. Cũng dùng chỉ cọc mốc đất đánh dấu khoảng cách (里堠 — cột mốc dặm đường). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ụ đất, lô cốt", "Hạng Tần Suất (Jun Da)": "6697.0", "Tần Suất % (Jun Da)": "99.9950843398", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 侯", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土侯", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "侯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "堠", "Unihan_Traditional (Chữ Phồn thể)": "堠", "Pinyin_Xie": "hòu", "Âm Hán Việt_Xie": "hậu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ các công trình canh gác hoặc mốc lộ giới thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('屦', '{"9000": "6698.0", "Chữ Trung Quốc": "屦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 尸 | Số nét | 15 | nét | 屦 | lũ | tượng hình | dép cỏ, giày rơm — chữ độc thể thuộc bộ 尸 | 屦 (dạng đơn giản hóa của 屨) là chữ thuộc bộ 尸 (thi — xác/thân thể). Wiktionary không ghi rõ cấu trúc hình thanh cho dạng này; chữ chỉ loại giày/dép đan bằng cỏ hay cói thời cổ. Chữ hội ý theo nghĩa: phần trên chỉ thân người, phần dưới chỉ loại vật dụng đi chân.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lũ\" (dép cỏ): hình ảnh đôi dép đan từ cỏ rơm mà người xưa đi hàng ngày — bộ 尸 nhắc thân thể người mang giày. | Gương Hán-Việt | 屨 (lũ) — dép cỏ, giày cói thời cổ | Mở khoá kiến thức | Biết 屦 mở khoá thành ngữ 屨賤踊貴 và các từ chỉ giày dép cổ trong văn học Hán.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 屦 là dạng rút gọn của 屨. Nghĩa: giày, dép (shoe, footwear); cũng dùng với nghĩa \"giẫm lên\" (to trample on). Xuất hiện trong nhiều thành ngữ liên quan đến sự mất cân xứng, như 屨賤踊貴 (dép rẻ, chân giả đắt — hình phạt tàn bạo khiến cụt chân nhiều). Hình thức cổ là 屨, ghi nhận trong giáp cốt văn. Chưa có nguồn học thuật mô tả cấu trúc hình-âm chi tiết. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dép gai", "Hạng Tần Suất (Jun Da)": "6698.0", "Tần Suất % (Jun Da)": "99.9950905412", "GavinGrover_Once (Chiết tự trực tiếp)": "尸 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴尸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "屦", "Unihan_Traditional (Chữ Phồn thể)": "屨", "Pinyin_Xie": "jù", "Âm Hán Việt_Xie": "lũ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ các loại giày dép thô sơ thời cổ hoặc động từ với nghĩa là xỏ giày. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('驵', '{"9000": "6699.0", "Chữ Trung Quốc": "驵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 8 | nét | 驵 | tổ | tượng hình | ngựa tốt, khỏe — chữ thuộc bộ 馬 | 驵 thuộc bộ 馬 (mã — ngựa). Wiktionary không ghi rõ cấu trúc hình thanh chi tiết. Nghĩa gốc là ngựa tốt, ngựa khỏe; sau mở rộng sang nghĩa \"người môi giới ngựa\" rồi \"kẻ đầu cơ, con buôn gian xảo\". Chưa xác định được thành phần biểu âm rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tổ\" (ngựa khoẻ, lái buôn ngựa): bộ 馬 (ngựa) — hình ảnh con ngựa cường tráng mà bọn con buôn hối lộ nhau để mua bán. | Gương Hán-Việt | 驵侩 (tổ khoái) — kẻ con buôn gian xảo, đầu cơ | Mở khoá kiến thức | Biết 驵 mở khoá từ 驵侩 (kẻ đầu cơ, con buôn gian) trong văn học Hán cổ.", "Tự nguyên_Xie": "Wiktionary ghi 驵 là chữ cổ, pinyin zǎng/zǔ/zù. Nghĩa 1: ngựa tốt, ngựa khỏe mạnh (fine horse, steed). Nghĩa 2 (sau): người môi giới mua bán ngựa, từ đó chỉ kẻ con buôn gian xảo (驵侩 — zǎng kuài). Bộ 馬 cho thấy liên quan đến ngựa. Chưa có nguồn học thuật xác định cấu trúc hình-âm. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngựa khoẻ", "Hạng Tần Suất (Jun Da)": "6699.0", "Tần Suất % (Jun Da)": "99.9950967426", "GavinGrover_Once (Chiết tự trực tiếp)": "马 + 且", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰马且", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "且", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "马", "Unihan_Simplified (Chữ Giản thể)": "驵", "Unihan_Traditional (Chữ Phồn thể)": "駔", "Pinyin_Xie": "zǎng", "Âm Hán Việt_Xie": "tảng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ ngựa tốt hoặc tính từ miêu tả sự khỏe mạnh của tuấn mã. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('桄', '{"9000": "6700.0", "Chữ Trung Quốc": "桄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 10 | nét | 桄 | quang | tượng hình | cây cọ, cây quang lang — chữ thuộc bộ 木 | 桄 thuộc bộ 木 (mộc — cây). Wiktionary không ghi rõ cấu trúc hình-âm chi tiết; chữ chỉ cây quang lang (桄榔 — cây cọ lá xòe lớn, tên khoa học Livistona). Chưa xác định được thành phần biểu âm rõ ràng từ anchor.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quang\" (cây quang lang): bộ 木 (cây) + âm quang — cây cọ lá tỏa ra rộng như ánh sáng (quang = sáng rực). | Gương Hán-Việt | 桄榔 (quang lang) — cây cọ nhiệt đới | Mở khoá kiến thức | Biết 桄 mở khoá tên thực vật học 桄榔 (quang lang) và các loài cọ nhiệt đới trong văn bản Hán.", "Tự nguyên_Xie": "Wiktionary ghi 桄 là tên một loại cây, chủ yếu xuất hiện trong từ 桄榔 (guāng láng — cây quang lang, loại cọ nhiệt đới Livistona). Pinyin guāng/guàng. Bộ 木 cho thấy liên quan đến cây cối. Không có glyph giáp cốt hay kim văn được ghi nhận. Chưa có nguồn học thuật xác định cấu trúc hình-âm. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: quang lang 桄榔)", "Hạng Tần Suất (Jun Da)": "6700.0", "Tần Suất % (Jun Da)": "99.9951091455", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 光", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木光", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "光", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "桄", "Unihan_Traditional (Chữ Phồn thể)": "桄", "Pinyin_Xie": "guāng", "Âm Hán Việt_Xie": "quang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong từ ghép để chỉ một loại cây họ dừa hoặc các bộ phận bằng gỗ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('憝', '{"9000": "6701.0", "Chữ Trung Quốc": "憝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 16 | nét | 憝 | đội | tượng hình | oán ghét, tàn ác — chữ thuộc bộ 心 | 憝 thuộc bộ 心 (tâm — tâm, lòng). Wiktionary không ghi cấu trúc hình-âm chi tiết; bộ 心 gợi trạng thái tâm lý. Nghĩa gốc: oán ghét sâu sắc, tàn ác, phần tử xấu xa nguy hiểm nhất. Chưa xác định thành phần biểu âm rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đội\" (oán thù, tàn ác): bộ 心 (tâm) — trái tim chứa đầy oán hận tàn ác, là kẻ xấu xa nhất trong thượng thư cổ. | Gương Hán-Việt | 元惡大憝 (nguyên ác đại đội) — kẻ đại ác, phần tử nguy hiểm nhất | Mở khoá kiến thức | Biết 憝 mở khoá thành ngữ 元惡大憝 (kẻ ác đầu sỏ) trong Thượng Thư và cổ văn Hán.", "Tự nguyên_Xie": "Wiktionary ghi 憝 là tính từ/danh từ văn ngôn: oán ghét, tàn ác (evil, to resent). Pinyin duì. Xuất hiện trong văn bản cổ như 《尚書》 để chỉ \"kẻ tàn ác xấu xa nhất\" (元惡大憝 — kẻ đại ác). Bộ 心 gợi trạng thái trong lòng — oán hận sâu sắc. Chưa có nguồn học thuật xác định cấu trúc đầy đủ. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "oan khuất; ghét", "Hạng Tần Suất (Jun Da)": "6701.0", "Tần Suất % (Jun Da)": "99.9951215483", "GavinGrover_Once (Chiết tự trực tiếp)": "敦 + 心", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱敦心", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "心", "Unihan_Simplified (Chữ Giản thể)": "憝", "Unihan_Traditional (Chữ Phồn thể)": "憝", "Pinyin_Xie": "duì", "Âm Hán Việt_Xie": "đỗi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ thể hiện thái độ căm ghét hoặc làm danh từ chỉ kẻ gian ác trong văn ngôn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瘳', '{"9000": "6702.0", "Chữ Trung Quốc": "瘳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 16 | nét | 瘳 | sưu | tượng hình | bệnh lành, hồi phục — chữ thuộc bộ 疒 | 瘳 thuộc bộ 疒 (nạch — bệnh tật). Wiktionary không ghi cấu trúc chi tiết. Bộ 疒 gợi nghĩa liên quan đến bệnh; 瘳 chỉ trạng thái bệnh đã lui, hồi phục. Chưa xác định thành phần biểu âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sưu\" (bệnh lành): bộ 疒 (bệnh) — bệnh đã rút lui, người bệnh được lành mạnh, nhẹ nhõm như thoát khỏi vòng vây của bệnh tật. | Gương Hán-Việt | 瘳癒 (sưu dũ) — lành bệnh, hồi phục | Mở khoá kiến thức | Biết 瘳 mở khoá các từ chỉ hồi phục bệnh trong cổ văn y học và thơ văn Hán.", "Tự nguyên_Xie": "Wiktionary ghi 瘳 là động từ văn ngôn: hồi phục từ bệnh tật (to recover from illness; to be healed). Pinyin chōu. Bộ 疒 (bệnh) gợi nghĩa liên quan đến trạng thái sức khỏe. Xuất hiện trong thành ngữ 萬民有瘳 (muôn dân được lành bệnh). Chưa có nguồn học thuật xác định cấu trúc hình-âm. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ốm khỏi", "Hạng Tần Suất (Jun Da)": "6702.0", "Tần Suất % (Jun Da)": "99.9951277498", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 翏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒翏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "翏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "瘳", "Unihan_Traditional (Chữ Phồn thể)": "瘳", "Pinyin_Xie": "chōu", "Âm Hán Việt_Xie": "sưu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ hoặc tính từ đứng sau chủ ngữ để chỉ trạng thái bệnh tình đã thuyên giảm hoặc khỏi hẳn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('騃', '{"9000": "6703.0", "Chữ Trung Quốc": "騃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 17 | nét | 騃 | ngai | tượng hình | ngu ngốc, đần độn — chữ thuộc bộ 馬 | 騃 thuộc bộ 馬 (mã — ngựa). Wiktionary không ghi cấu trúc chi tiết; anchor không có glyph origin. Bộ 馬 có thể gợi sự liên tưởng đến con ngựa bướng bỉnh, không nghe lời — hàm ý ngu ngốc. Chưa xác định thành phần biểu âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngai\" (ngu đần): bộ 馬 (ngựa) — con ngựa ương bướng không nghe lời chủ, hình ảnh của sự ngu ngốc không thể dạy được. | Gương Hán-Việt | 騃子 (ngai tử) — đứa ngu ngốc; 騃騃 (ngai ngai) — vẻ ngây thơ ngu dại | Mở khoá kiến thức | Biết 騃 mở khoá các từ chỉ sự ngu ngốc trong cổ văn Hán và các mô tả nhân vật phản diện.", "Tự nguyên_Xie": "Wiktionary không ghi cấu trúc hình-âm chi tiết cho 騃. Pinyin ái. Nghĩa: ngu ngốc, đần độn (stupid, foolish). Bộ 馬 gợi liên tưởng đến tính ngang bướng không nghe lời. Từ đồng nghĩa thường gặp: 愚 (ngu), 呆 (đần). Chưa có nguồn học thuật chi tiết. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngu; dốt; đần độn", "Hạng Tần Suất (Jun Da)": "6703.0", "Tần Suất % (Jun Da)": "99.9951339512", "GavinGrover_Once (Chiết tự trực tiếp)": "馬 + 矣", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰馬矣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "矣", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "騃", "Unihan_Traditional (Chữ Phồn thể)": "騃", "Pinyin_Xie": "ái", "Âm Hán Việt_Xie": "ngai", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ đứng trước danh từ để tu sức hoặc làm vị ngữ bổ nghĩa cho chủ ngữ chỉ người. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('茌', '{"9000": "6704.0", "Chữ Trung Quốc": "茌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 8 | nét | 茌 | sậy | tượng hình | tên địa danh — chữ thuộc bộ 艸 | 茌 thuộc bộ 艸 (thảo — cỏ). Wiktionary không ghi cấu trúc chi tiết; chủ yếu dùng trong địa danh 茌平 (Sậy Bình, huyện ở Sơn Đông, Trung Quốc). Bộ 艸 gợi vùng đất cỏ sậy. Chưa xác định thành phần biểu âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sậy\" (bãi sậy, tên đất): bộ 艸 (cỏ) — vùng đất cỏ sậy mọc dày, tên địa danh cổ ở Sơn Đông. | Gương Hán-Việt | 茌平 (Sậy Bình) — địa danh huyện ở Sơn Đông | Mở khoá kiến thức | Biết 茌 mở khoá địa danh 茌平 và các tên đất liên quan ở miền Bắc Trung Quốc.", "Tự nguyên_Xie": "Wiktionary ghi 茌 là chữ dùng chủ yếu trong địa danh, không có định nghĩa thông dụng độc lập. Pinyin chí. Bộ 艸 (cỏ) gợi vùng đất có cỏ sậy. Hán-Việt ''sậy'' phản ánh nghĩa gốc: vùng đất có sậy mọc. Địa danh 茌平 thuộc Liêu Thành, Sơn Đông. Chưa có nguồn học thuật xác định cấu trúc hình-âm. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên đất)", "Hạng Tần Suất (Jun Da)": "6704.0", "Tần Suất % (Jun Da)": "99.9951401526", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 仕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹仕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "仕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "茌", "Unihan_Traditional (Chữ Phồn thể)": "茌", "Pinyin_Xie": "chí", "Âm Hán Việt_Xie": "trì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ riêng trong các địa danh cổ như Trì Bình. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('辀', '{"9000": "6705.0", "Chữ Trung Quốc": "辀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 10 | nét | 辀 | trâu | tượng hình | đòn xe ngựa — chữ thuộc bộ 車 | 辀 thuộc bộ 車 (xa — xe). Anchor không ghi cấu trúc chi tiết; bộ 車 gợi liên quan đến xe. Nghĩa gốc: đòn xe (the pole/shaft of a carriage) — thanh gỗ nối xe với ngựa kéo. Chưa xác định thành phần biểu âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trâu\" (đòn xe): bộ 車 (xe ngựa) — thanh đòn dài phía trước xe ngựa, giống như con trâu kéo cày, nó là điểm nối giữa sức kéo và xe. | Gương Hán-Việt | 辀轅 (trâu viên) — đòn xe, càng xe | Mở khoá kiến thức | Biết 辀 mở khoá các từ chỉ bộ phận xe ngựa trong cổ văn Hán và kiến trúc xe.", "Tự nguyên_Xie": "Wiktionary không ghi cấu trúc hình-âm chi tiết cho 辀. Pinyin zhōu. Nghĩa: đòn xe ngựa (the shaft/pole of a carriage). Bộ 車 (xe) cho thấy đây là bộ phận của xe. Đòn xe là thanh gỗ dài nối thân xe với đôi ngựa kéo — bộ phận quan trọng trong xe ngựa cổ đại. Chưa có nguồn học thuật chi tiết. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái đòn xe", "Hạng Tần Suất (Jun Da)": "6705.0", "Tần Suất % (Jun Da)": "99.995146354", "GavinGrover_Once (Chiết tự trực tiếp)": "车 + 舟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰车舟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "舟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "车", "Unihan_Simplified (Chữ Giản thể)": "辀", "Unihan_Traditional (Chữ Phồn thể)": "輈", "Pinyin_Xie": "zhōu", "Âm Hán Việt_Xie": "chu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ bộ phận đòn gỗ cong nối từ trục xe đến ách cổ ngựa thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('胠', '{"9000": "6706.0", "Chữ Trung Quốc": "胠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 9 | nét | 胠 | khư | tượng hình | phần hông sườn, nách — chữ thuộc bộ 肉 | 胠 thuộc bộ 肉/月 (nhục — thịt, cơ thể). Wiktionary không ghi cấu trúc chi tiết; bộ 肉 gợi liên quan đến bộ phận cơ thể. Nghĩa gốc: phần giữa hông và nách (the area between the flank and armpit). Cũng dùng nghĩa \"mở ra\" (to open). Chưa xác định thành phần biểu âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khư\" (hông sườn): bộ 肉 (thịt, thân thể) — phần thịt ở hông sườn bên hữu, tên thiên Trang Tử 胠篋 nổi tiếng. | Gương Hán-Việt | 胠篋 (khư khiếp) — tên thiên Trang Tử, nghĩa là mở hộp/rương | Mở khoá kiến thức | Biết 胠 mở khoá tên thiên 胠篋 của Trang Tử và từ chỉ bộ phận cơ thể/quân đội trong cổ văn.", "Tự nguyên_Xie": "Wiktionary ghi 胠 là chữ chỉ phần cơ thể giữa hông và nách. Pinyin qū. Nghĩa mở rộng: cánh quân đi bên hữu (right flank of an army), và \"mở ra\" (to open). Xuất hiện trong văn bản Trang Tử 《胠篋》 (Khư Khiếp — Mở hộp, thiên nổi tiếng về trộm cắp tầm thường và trộm cắp lớn). Bộ 肉 gợi bộ phận cơ thể. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mở ra; sườn, nách; cánh quân đi bên hữu", "Hạng Tần Suất (Jun Da)": "6706.0", "Tần Suất % (Jun Da)": "99.9951525554", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 去", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月去", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "去", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "胠", "Unihan_Traditional (Chữ Phồn thể)": "胠", "Pinyin_Xie": "qū", "Âm Hán Việt_Xie": "khư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này thường dùng làm danh từ chỉ bộ phận cơ thể hoặc động từ chỉ hành động mở ra trong văn ngôn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('埏', '{"9000": "6707.0", "Chữ Trung Quốc": "埏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 9 | nét | 埏 | diên | tượng hình | biên giới đất, nhào đất — chữ thuộc bộ 土 | 埏 thuộc bộ 土 (thổ — đất). Anchor không ghi cấu trúc chi tiết. Bộ 土 gợi nghĩa liên quan đến đất. Nghĩa gốc: biên giới, ranh giới đất; cũng dùng nghĩa \"nhào nặn đất\" (to knead clay). Nổi tiếng qua Đạo Đức Kinh: 埏埴以為器 (nhào đất sét làm đồ gốm).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"diên\" (nhào đất, ranh giới): bộ 土 (đất) — hình ảnh Lão Tử nhào đất sét làm bình, chỗ trống bên trong mới tạo ra công dụng. | Gương Hán-Việt | 埏埴 (diên thực) — nhào đất sét (Đạo Đức Kinh) | Mở khoá kiến thức | Biết 埏 mở khoá câu Đạo Đức Kinh 埏埴以為器 và các từ chỉ nghề gốm, ranh giới trong cổ văn.", "Tự nguyên_Xie": "Wiktionary không ghi cấu trúc chi tiết. Pinyin shān/yán. Nghĩa: ranh giới đất (boundary), nhào đất (to knead clay). Xuất hiện trong Đạo Đức Kinh chương 11: 埏埴以為器，當其無，有器之用 (nhào đất sét làm đồ vật — chính chỗ trống rỗng tạo nên công dụng). 埏 trong nghĩa \"biên giới\" gợi nơi cuối cùng của đất. Chưa có nguồn học thuật xác định cấu trúc hình-âm. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "biên giới, ranh giới", "Hạng Tần Suất (Jun Da)": "6707.0", "Tần Suất % (Jun Da)": "99.9951587569", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 延", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土延", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "延", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "埏", "Unihan_Traditional (Chữ Phồn thể)": "埏", "Pinyin_Xie": "shān", "Âm Hán Việt_Xie": "duyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này chủ yếu dùng làm danh từ chỉ ranh giới hoặc động từ chỉ việc nhào đất sét trong văn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('腠', '{"9000": "6708.0", "Chữ Trung Quốc": "腠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 13 | nét | 腠 | tấu | tượng hình | thớ da, phần giữa da và thịt — chữ thuộc bộ 肉 | 腠 thuộc bộ 肉/月 (nhục — thịt, cơ thể). Anchor không ghi cấu trúc chi tiết. Bộ 肉 gợi liên quan đến mô cơ thể. Nghĩa gốc: lớp mô giữa da và thịt (tissue between skin and flesh) — thuật ngữ y học cổ Trung Hoa. Chưa xác định thành phần biểu âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tấu\" (thớ da, lỗ chân lông): bộ 肉 (thịt da) — lớp mô mỏng giữa da và thịt, nơi khí huyết ra vào theo quan niệm Đông y. | Gương Hán-Việt | 腠理 (tấu lý) — thớ da, lỗ chân lông (thuật ngữ Đông y) | Mở khoá kiến thức | Biết 腠 mở khoá thuật ngữ 腠理 trong y học cổ truyền Trung Hoa và các văn bản Đông y.", "Tự nguyên_Xie": "Wiktionary ghi 腠 là danh từ y học cổ: lớp mô giữa da và thịt (tissue between skin and flesh). Pinyin còu. Trong Đông y, 腠理 (tấu lý) là khái niệm chỉ các lỗ chân lông và kẽ hở trong mô da — nơi khí huyết lưu thông và tà khí có thể xâm nhập. Bộ 肉 gợi liên quan đến mô thân thể. Chưa có nguồn học thuật xác định cấu trúc hình-âm. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thớ da (phần giữa da và thịt)", "Hạng Tần Suất (Jun Da)": "6708.0", "Tần Suất % (Jun Da)": "99.9951649583", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "腠", "Unihan_Traditional (Chữ Phồn thể)": "腠", "Pinyin_Xie": "còu", "Âm Hán Việt_Xie": "thấu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong y học cổ truyền để chỉ phần cấu trúc dưới da. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('靰', '{"9000": "6709.0", "Chữ Trung Quốc": "靰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 革 | Số nét | 12 | nét | 革 | cách | biểu nghĩa | da thuộc, da thú | 靰 | ngột | tượng hình | bộ phận của 靰鞡 — giày da ủng Mãn Châu | 靰 thuộc bộ 革 (cách — da thuộc). Không có anchor Wiktionary. Chữ gần như chỉ xuất hiện trong từ 靰鞡 (ngột lạp — loại giày da ủng truyền thống của người Mãn Châu và vùng Đông Bắc Trung Quốc). Bộ 革 gợi chất liệu da. Chưa có nguồn học thuật chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngột\" (trong ngột lạp): bộ 革 (da thuộc) — chữ chỉ xuất hiện trong tên loại giày da ủng Mãn Châu 靰鞡, may từ da thú thô. | Gương Hán-Việt | 靰鞡 (ngột lạp) — giày da ủng Mãn Châu, Đông Bắc TQ | Mở khoá kiến thức | Biết 靰 mở khoá từ 靰鞡 — tên giày da ủng truyền thống trong văn hóa Mãn Châu và Đông Bắc Trung Quốc.", "Tự nguyên_Xie": "Không có anchor Wiktionary cho 靰. Chữ hầu như chỉ xuất hiện trong từ 靰鞡 (wùla / ngột lạp) — loại giày da ủng truyền thống của người Mãn Châu và vùng Đông Bắc Trung Quốc (满族传统鞋). Bộ 革 (da thuộc) gợi chất liệu làm giày. Nghĩa độc lập không được ghi nhận rõ ràng trong từ điển chuẩn. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: ngột lạp 靰鞡)", "Hạng Tần Suất (Jun Da)": "6709.0", "Tần Suất % (Jun Da)": "99.9951711597", "GavinGrover_Once (Chiết tự trực tiếp)": "革 + 兀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰革兀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "革", "Unihan_Simplified (Chữ Giản thể)": "靰", "Unihan_Traditional (Chữ Phồn thể)": "靰", "Pinyin_Xie": "wù", "Âm Hán Việt_Xie": "ngột", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này hầu như chỉ xuất hiện trong từ ghép ngột lạp để chỉ một loại giày da cổ truyền. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鞡', '{"9000": "6710.0", "Chữ Trung Quốc": "鞡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 革 | Số nét | 17 | nét | 革 | cách | biểu nghĩa | da thuộc, da thú | 鞡 | lạp | tượng hình | bộ phận của 靰鞡 — giày da ủng Mãn Châu | 鞡 thuộc bộ 革 (cách — da thuộc). Không có anchor Wiktionary. Chữ gần như chỉ xuất hiện trong từ 靰鞡 (ngột lạp). Bộ 革 gợi chất liệu da. Là tiền âm tiết thứ hai trong từ ghép chỉ giày da ủng. Chưa có nguồn học thuật chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lạp\" (trong ngột lạp): bộ 革 (da) — âm tiết thứ hai của tên giày ủng da Mãn Châu 靰鞡, đi kèm với 靰 (ngột). | Gương Hán-Việt | 靰鞡 (ngột lạp) — giày da ủng Mãn Châu truyền thống | Mở khoá kiến thức | Biết 鞡 mở khoá từ 靰鞡 — tên loại giày ủng da đặc trưng của người Mãn và vùng Đông Bắc Trung Quốc.", "Tự nguyên_Xie": "Không có anchor Wiktionary cho 鞡. Chữ hầu như chỉ xuất hiện trong từ 靰鞡 (wùla / ngột lạp) — loại giày ủng da truyền thống Mãn Châu. Bộ 革 (da thuộc) gợi chất liệu. Là âm tiết thứ hai (la/lạp) trong từ ghép. Nghĩa độc lập không được ghi nhận. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: ngột lạp 靰鞡)", "Hạng Tần Suất (Jun Da)": "6710.0", "Tần Suất % (Jun Da)": "99.9951773611", "GavinGrover_Once (Chiết tự trực tiếp)": "革 + 拉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰革拉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "拉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "革", "Unihan_Simplified (Chữ Giản thể)": "鞡", "Unihan_Traditional (Chữ Phồn thể)": "鞡", "Pinyin_Xie": "la", "Âm Hán Việt_Xie": "lạp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường đi kèm với chữ ngột để tạo thành danh từ chỉ loại giày da lót cỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缻', '{"9000": "6711.0", "Chữ Trung Quốc": "缻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 缶 | Số nét | 10 | nét | 缻 | phẫu | tượng hình | đồ gốm, vò đất — biến thể của 缶 | 缻 là biến thể của 缶 (phẫu — vò đất, đồ gốm). Không có anchor Wiktionary chi tiết. Chữ thuộc bộ 缶. Nghĩa tương đương 缶: đồ gốm, vò đất. Chữ này hiếm, thường dùng thay bằng 缶.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phẫu\" (vò gốm): chữ là dạng viết khác của 缶 — chiếc vò đất nung miệng hẹp đựng rượu hay nước của người xưa. | Gương Hán-Việt | 缶 (phẫu) — vò gốm; 缻 là dạng biến thể | Mở khoá kiến thức | Biết 缻 mở khoá hiểu bộ 缶 và các từ liên quan đến đồ gốm trong cổ văn Hán.", "Tự nguyên_Xie": "Không có anchor Wiktionary chi tiết cho 缻. Wiktionary ghi nghĩa là ''xem 缶''. Chữ là biến thể chính tả của 缶 (fǒu / phẫu) — vò gốm, đồ đất nung. 缶 là chữ tượng hình ghi nhận từ giáp cốt văn, chỉ loại vò miệng hẹp đựng rượu hoặc nước. Bộ chữ (radical) mang tên 缶 bộ. Chưa có nguồn học thuật chi tiết riêng cho 缻. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xem \"缶\"", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "缶 + 瓦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰缶瓦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "瓦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "缶", "Unihan_Simplified (Chữ Giản thể)": "缻", "Unihan_Traditional (Chữ Phồn thể)": "缻", "Pinyin_Xie": "fǒu", "Âm Hán Việt_Xie": "phẫu, phũ, phữu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ các loại bình vò bằng đất nung hoặc nhạc cụ gõ thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铼', '{"9000": "6712.0", "Chữ Trung Quốc": "铼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 12 | nét | 金 | kim | biểu nghĩa | kim loại | 來 | lai | biểu âm | cho âm lái/lai | 铼 là chữ hình thanh: 金 (Kim, biểu nghĩa — kim loại) + 來 (Lai, biểu âm). Wiktionary ghi: {{Han compound|金|來|c1=s|t1=metal|c2=p|ls=psc}}. Chữ tạo muộn để phiên âm nguyên tố hóa học Rhenium (Re, số nguyên tử 75).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lai\" (nguyên tố rhenium): 金 (kim loại) + 來 (âm lai) — kim loại quý hiếm \"đến từ xa\" (lai = đến), phiên âm nguyên tố Re trong bảng tuần hoàn. | Gương Hán-Việt | 铼 (lai) — nguyên tố rhenium (Re) trong hóa học | Mở khoá kiến thức | Biết 铼 mở khoá bộ chữ Hán phiên âm nguyên tố hóa học và tên nguyên tố Re trong bảng tuần hoàn tiếng Trung.", "Tự nguyên_Xie": "Wiktionary ghi 铼 là chữ hình thanh tạo để phiên âm tên nguyên tố Rhenium (Re). Cấu trúc: 金 (kim loại — biểu nghĩa) + 來 (biểu âm, âm lái). Rhenium được phát hiện năm 1925 bởi các nhà khoa học Đức; tên Latin từ tên sông Rhine (Rhein). Trung Quốc tạo chữ 铼 để ghi nguyên tố này trong hóa học. Giản thể dùng 铼, phồn thể dùng 錸. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố reni, Re", "Hạng Tần Suất (Jun Da)": "6712.0", "Tần Suất % (Jun Da)": "99.9952021668", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 来", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅来", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "来", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铼", "Unihan_Traditional (Chữ Phồn thể)": "錸", "Pinyin_Xie": "lái", "Âm Hán Việt_Xie": "lai", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong hóa học để chỉ nguyên tố kim loại chuyển tiếp Reni. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('紤', '{"9000": "6713.0", "Chữ Trung Quốc": "紤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 10 | nét | 糸 | mịch | biểu nghĩa | sợi tơ, vải | 紤 | cữu | tượng hình | thuộc bộ 糸, nghĩa không rõ | 紤 thuộc bộ 糸/纟 (mịch — sợi tơ, vải). Không có anchor Wiktionary chi tiết. Bộ 糸 gợi liên quan đến sợi vải. Nghĩa của 紤 (jiǔ) rất hạn chế trong từ điển chuẩn; dường như là chữ hiếm không có định nghĩa thông dụng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cữu\" (sợi chỉ hiếm): bộ 糸 (tơ, sợi) — chữ rất hiếm trong bộ sợi vải, nghĩa không còn dùng phổ biến. | Gương Hán-Việt | 紤 — chữ hiếm thuộc bộ 糸, ít dùng độc lập | Mở khoá kiến thức | Biết 紤 giúp nhận diện bộ 糸 và các chữ hiếm liên quan đến sợi vải trong cổ tự điển.", "Tự nguyên_Xie": "Không có anchor Wiktionary cho 紤. Pinyin jiǔ. Bộ 糸 (sợi tơ) gợi nghĩa liên quan đến dệt vải hoặc sợi chỉ. Nghĩa thực tế không được ghi rõ trong từ điển hiện đại; chữ hiếm và nghĩa bị mờ theo thời gian. Từ điển ghi nghĩa là 礤 (cái mài) — có thể là nhầm lẫn dữ liệu. Chữ tạo muộn, chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "礤", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 斤", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹斤", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "斤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "紤", "Unihan_Traditional (Chữ Phồn thể)": "紤", "Pinyin_Xie": "jiǔ", "Âm Hán Việt_Xie": "cữu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này là một danh từ hiếm gặp trong văn bản cổ dùng để chỉ các loại dây sợi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鐣', '{"9000": "6714.0", "Chữ Trung Quốc": "鐣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 20 | nét | 金 | kim | biểu nghĩa | kim loại | 撑 | chong | biểu âm | cho âm xanh/sanh | 鐣 là chữ Nôm hình thanh: 金 (Kim, biểu nghĩa — kim loại) + 撑 (Chong, biểu âm — âm sanh/xanh). Wiktionary ghi: {{Han compound|lang=vi|金|撑|ls=psc|tr={{vi-l|xanh}}|c1=s|t1=metal|c2=p|tr2={{vi-l|sanh}}}}. Đây là chữ Nôm đặc thù, ghi âm tiếng Việt \"xanh\" (màu xanh) hoặc \"cái xanh\" (chảo sâu đáy).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xanh\" (màu xanh, cái xanh): 金 (gang sắt) + 撑 (âm sanh) — chữ Nôm tạo để ghi âm \"xanh\", vừa chỉ màu sắc vừa chỉ cái chảo gang sâu đáy. | Gương Hán-Việt | 鐣 (xanh) — chữ Nôm chỉ màu xanh hoặc chảo gang | Mở khoá kiến thức | Biết 鐣 giúp hiểu hệ thống chữ Nôm — cách người Việt dùng bộ phận Hán để ghi âm tiếng Việt thuần túy.", "Tự nguyên_Xie": "Wiktionary ghi 鐣 là chữ Nôm: 金 (kim loại — biểu nghĩa) + 撑 (biểu âm, âm sanh). Được đọc \"xanh\" trong tiếng Việt, chỉ màu xanh (blue/green) hoặc \"cái xanh\" — chảo sâu đáy bằng gang. Chữ tạo để ghi âm tiếng Việt trong hệ thống chữ Nôm, không có trong Hán ngữ chuẩn. Đây là chữ tạo muộn dành riêng cho tiếng Việt. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xanh; như \"cái xanh (chảo sâu đáy)\" (gdhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 掌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金掌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "掌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鐣", "Unihan_Traditional (Chữ Phồn thể)": "鐣", "Pinyin_Xie": "zhang", "Âm Hán Việt_Xie": "đương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ một loại dụng cụ nấu ăn cổ của Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('莤', '{"9000": "6715.0", "Chữ Trung Quốc": "莤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 10 | nét | 莤 | giậu | tượng hình | hàng rào giậu, bờ rào — thuộc bộ 艸 | 莤 thuộc bộ 艸 (thảo — cỏ). Anchor không ghi cấu trúc chi tiết; bộ 艸 gợi liên quan đến thực vật. Hán-Việt \"giậu\" phản ánh nghĩa gốc: hàng rào giậu, bờ rào (cây được trồng làm hàng rào). Pinyin sù/yóu. Chưa xác định thành phần biểu âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giậu\" (hàng rào cây): bộ 艸 (cỏ, cây) — hàng rào trồng bằng cây cỏ ngăn ranh giới, gợi câu ca dao Việt \"nhà em có giậu mồng tơi\". | Gương Hán-Việt | 莤 (giậu) — hàng rào giậu bằng cây cỏ (chữ Hán Nôm) | Mở khoá kiến thức | Biết 莤 giúp hiểu từ \"giậu\" trong ca dao tục ngữ Việt Nam và nhận dạng chữ Nôm chỉ thực vật làm rào.", "Tự nguyên_Xie": "Wiktionary ghi 莤 là chữ ít gặp, pinyin sù/yóu. Trong từ điển Việt Hán Nôm (vhn), nghĩa là \"giậu\" — hàng rào làm bằng cây cỏ. Bộ 艸 gợi liên quan đến thực vật. Hán-Việt \"giậu\" gợi hình ảnh cây cỏ trồng làm hàng rào. Chưa có nguồn học thuật xác định cấu trúc hình-âm chi tiết. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giậu; như \"rào giậu\" (vhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 酉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹酉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "酉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "莤", "Unihan_Traditional (Chữ Phồn thể)": "莤", "Pinyin_Xie": "sù", "Âm Hán Việt_Xie": "súc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ một loại cỏ tranh dùng trong nghi lễ cúng tế thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鱯', '{"9000": "6716.0", "Chữ Trung Quốc": "鱯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 24 | nét | 鱯 | hộ | tượng hình | loài cá nheo, cá trê lớn — thuộc bộ 魚 | 鱯 thuộc bộ 魚 (ngư — cá). Wiktionary không ghi cấu trúc hình-âm chi tiết; bộ 魚 gợi liên quan đến cá. Nghĩa gốc: loài cá thuộc họ Mystus (cá nheo lớn nước ngọt). Chưa xác định thành phần biểu âm rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hộ\" (cá nheo lớn): bộ 魚 (cá) — con cá nheo to lớn sống dưới đáy sông, thuộc họ Mystus châu Á. | Gương Hán-Việt | 鱯 (hộ) — tên loài cá Mystus catfish trong phân loại học | Mở khoá kiến thức | Biết 鱯 giúp nhận dạng tên loài cá trong tài liệu phân loại học và ngư nghiệp châu Á.", "Tự nguyên_Xie": "Wiktionary ghi 鱯 là tên một loài cá: cá Mystus catfish (họ Bagridae — cá trê lớn nước ngọt châu Á). Pinyin hù. Bộ 魚 (cá) gợi liên quan đến cá. Chữ tạo để đặt tên loài cá trong phân loại học. Không có glyph cổ; chưa có nguồn học thuật xác định cấu trúc. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Tun", "Hạng Tần Suất (Jun Da)": "7802.0", "Tần Suất % (Jun Da)": "99.9990206922", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 蒦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚蒦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "蒦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鳠", "Unihan_Traditional (Chữ Phồn thể)": "鱯", "Pinyin_Xie": "hù", "Âm Hán Việt_Xie": "hộ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ một loài cá nước ngọt trong tiếng Trung cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('邲', '{"9000": "6717.0", "Chữ Trung Quốc": "邲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 7 | nét | 必 | tất | biểu âm | cho âm bì/tất | 邑 | ấp | biểu nghĩa | thành ấp, tên địa danh | 邲 là chữ hình thanh: 必 (Tất, biểu âm) + 邑/阝 (Ấp, biểu nghĩa — tên địa danh). Wiktionary ghi: {{Han compound|必|邑|c1=p|c2=s|t2=city; town|ls=psc}}. Chữ chỉ địa danh cổ 邲 — nơi xảy ra trận chiến nổi tiếng năm 597 TCN.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tất\" (địa danh cổ): 邑 (ấp, đất) + 必 (âm tất) — tên đất cổ ở Hà Nam, gắn với trận 邲之戰 lịch sử thời Xuân Thu. | Gương Hán-Việt | 邲之戰 (Tất chi chiến) — trận Bì, trận đánh Sở-Tấn năm 597 TCN | Mở khoá kiến thức | Biết 邲 mở khoá tên trận địa lịch sử 邲之戰 trong sử sách thời Xuân Thu Chiến Quốc.", "Tự nguyên_Xie": "Wiktionary ghi 邲 là chữ hình thanh chỉ địa danh: 必 (biểu âm) + 邑 (tên đất — biểu nghĩa). Tên địa danh cổ, nay ở phía Đông Trịnh Châu, tỉnh Hà Nam, Trung Quốc. Nổi tiếng qua trận Bì 邲之戰 (597 TCN) — trận chiến giữa Sở và Tấn. Tần vương đánh bại Tấn ở đây, là một trong những trận đánh lớn của thời Xuân Thu. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Tất; tên đất cổ, nay ở phía Đông Trịnh Châu, thuộc Hà Nam Trung quốc", "Hạng Tần Suất (Jun Da)": "6717.0", "Tần Suất % (Jun Da)": "99.9952941546", "GavinGrover_Once (Chiết tự trực tiếp)": "必 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰必阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "必", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "邲", "Unihan_Traditional (Chữ Phồn thể)": "邲", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "bật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ riêng chỉ địa danh cổ hoặc dùng làm tính từ mang nghĩa tốt lành. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('唼', '{"9000": "6718.0", "Chữ Trung Quốc": "唼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 11 | nét | 唼 | thép | tượng hình | đớp mồi, tiếng kêu đớp — thuộc bộ 口 | 唼 thuộc bộ 口 (khẩu — miệng). Anchor không ghi cấu trúc chi tiết; bộ 口 gợi liên quan đến âm thanh miệng. Nghĩa: đớp mồi (chim/vịt đớp mồi), tiếng kêu đớp; cũng dùng nghĩa nói điều ác, thóa mạ. Chưa xác định thành phần biểu âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thép\" (đớp mồi, nói xấu): bộ 口 (miệng) — con vịt đớp mồi tạo tiếng động, hoặc miệng kẻ thóa mạ người khác — đều gắn với cái miệng. | Gương Hán-Việt | 唼唼 (thép thép) — tiếng đớp mồi liên tục của vịt | Mở khoá kiến thức | Biết 唼 giúp nhận dạng từ tượng thanh chỉ tiếng đớp mồi và các động tác miệng trong cổ văn.", "Tự nguyên_Xie": "Không có anchor Wiktionary cho 唼. Pinyin shà. Hán-Việt \"thép\". Bộ 口 (miệng) gợi âm thanh hoặc hành động của miệng. Nghĩa 1: tiếng kêu đớp mồi của vịt/chim nước (gobbling sound made by ducks). Nghĩa 2: nói xấu, thóa mạ (speaking evil). Chưa có nguồn học thuật xác định cấu trúc hình-âm. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mổ, đớp mồi", "Hạng Tần Suất (Jun Da)": "6718.0", "Tần Suất % (Jun Da)": "99.9952998392", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 妾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口妾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "妾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "唼", "Unihan_Traditional (Chữ Phồn thể)": "唼", "Pinyin_Xie": "shà", "Âm Hán Việt_Xie": "xiệp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ mô tả động tác ăn hoặc mổ mồi của chim và cá. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鐻', '{"9000": "6719.0", "Chữ Trung Quốc": "鐻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 21 | nét | 鐻 | cự | tượng hình | nhạc cụ cổ, giá treo chuông/khánh — thuộc bộ 金 | 鐻 thuộc bộ 金 (kim — kim loại). Wiktionary không ghi cấu trúc chi tiết cho nhánh này; anchor ghi Hán-Việt ''cự'' với biến thể ''cứa''. Nghĩa gốc: nhạc cụ cổ giống chuông, hoặc giá treo chuông/khánh. Chưa xác định thành phần biểu âm rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cự\" (nhạc cụ cổ, giá treo chuông): bộ 金 (kim loại) — chiếc nhạc khí đồng thau thời cổ đại, hoặc giá đỡ chuông trong nhạc lễ cung đình. | Gương Hán-Việt | 鐻 (cự) — nhạc cụ cổ giống chuông, giá treo chuông khánh | Mở khoá kiến thức | Biết 鐻 mở khoá từ vựng nhạc cụ cổ và nghi lễ âm nhạc trong cổ văn Hán và văn liệu âm nhạc học.", "Tự nguyên_Xie": "Wiktionary không ghi cấu trúc hình-âm chi tiết cho 鐻. Pinyin jù. Hán-Việt ''cự'' (biến thể: cứa). Bộ 金 (kim loại) gợi đây là nhạc cụ hoặc vật dụng bằng kim loại. Nghĩa: cái cự — nhạc cụ thời cổ giống chuông nhỏ; cũng chỉ giá treo chuông hoặc giá treo khánh (bộ phận gỗ đỡ chuông đồng trong nhạc lễ). Chưa có nguồn học thuật chi tiết. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái cự (nhạc cụ thời xưa, giống như chuông); giá treo chuông; giá treo khánh (thời xưa)", "Hạng Tần Suất (Jun Da)": "6719.0", "Tần Suất % (Jun Da)": "99.9953055238", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 豦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金豦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "豦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鐻", "Unihan_Traditional (Chữ Phồn thể)": "鐻", "Pinyin_Xie": "jù", "Âm Hán Việt_Xie": "cự", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ một loại nhạc cụ gõ cổ hoặc giá dùng để treo chuông khánh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('閟', '{"9000": "6720.0", "Chữ Trung Quốc": "閟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 13 | nét | 閟 | bí | tượng hình | đóng cửa, giấu kín | 閟 là chữ cổ chưa xác định rõ cấu trúc thành phần. Dựa vào bộ 門 (cổng, cửa) và yếu tố bên trong, chữ gợi nghĩa đóng kín, giấu kín. Chưa có nguồn phân tích hình thanh/hội ý rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bí\": cổng cửa (門) khóa chặt, giấu kín bí mật bên trong — bí ẩn không ai biết. | Gương Hán-Việt | bí mật, bí ẩn | Mở khoá kiến thức | Biết 閟 (bí) giúp liên kết với các từ Hán-Việt chỉ sự kín đáo, che giấu như ''bí mật'', ''bí ẩn''.", "Tự nguyên_Xie": "閟 mang nghĩa văn ngôn ''đóng cửa, giấu kín, cẩn thận''. Wiktionary chỉ ghi nhận phát âm và định nghĩa, không cung cấp phân tích glyph cụ thể. Chưa có nguồn học thuật xác nhận cấu trúc chữ này. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giấu kín; đóng cửa", "Hạng Tần Suất (Jun Da)": "6720.0", "Tần Suất % (Jun Da)": "99.9953112085", "GavinGrover_Once (Chiết tự trực tiếp)": "門 + 必", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴門必", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "必", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "門", "Unihan_Simplified (Chữ Giản thể)": "閟", "Unihan_Traditional (Chữ Phồn thể)": "閟", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "bí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ chỉ hành động đóng kín hoặc tính từ miêu tả sự ẩn giấu, yên tĩnh. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('駚', '{"9000": "6721.0", "Chữ Trung Quốc": "駚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 15 | nét | 駚 | ngưỡng | tượng hình | tên riêng, dùng trong từ ghép 駚驡 | 駚 là chữ hiếm, chủ yếu dùng trong từ ghép 駚驡. Cấu trúc chứa bộ 馬 (ngựa), nhưng Wiktionary không cung cấp phân tích hình thanh hay hội ý cụ thể. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngưỡng\": chữ hiếm trong bộ 馬 (ngựa), chỉ thấy trong từ ghép 駚驡 — ngưỡng mộ con ngựa quý hiếm. | Gương Hán-Việt | ngưỡng mộ, ngưỡng vọng | Mở khoá kiến thức | Biết 駚 (ngưỡng) giúp nhận diện bộ 馬 trong các chữ liên quan đến ngựa và động vật.", "Tự nguyên_Xie": "駚 chỉ xuất hiện trong từ ghép 駚驡. Wiktionary ghi nhận phát âm yǎng nhưng không giải thích glyph. Chưa có nguồn học thuật xác nhận cấu trúc chữ này. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Yao", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "馬 + 央", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰馬央", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "央", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "駚", "Unihan_Traditional (Chữ Phồn thể)": "駚", "Pinyin_Xie": "yǎng", "Âm Hán Việt_Xie": "ngưỡng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ miêu tả tư thế chạy nhanh và khỏe mạnh của loài ngựa. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('篥', '{"9000": "6722.0", "Chữ Trung Quốc": "篥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 16 | nét | 篥 | sặt | tượng hình | loại nhạc cụ ống tre | 篥 là chữ chủ yếu dùng trong từ ghép 篳篥 (nhạc cụ thổi bằng sậy). Bộ 竹 (trúc) gợi chất liệu tre, nhưng Wiktionary không phân tích cấu trúc hình thanh hay hội ý. Chưa có nguồn học thuật chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sặt\": bộ 竹 (tre) + âm sặt — ống tre tạo tiếng sặc sặc như kèn sậy 篳篥. | Gương Hán-Việt | sặt — ít dùng độc lập trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 篥 (sặt) giúp nhận ra bộ 竹 trong các chữ liên quan đến nhạc cụ và đồ tre.", "Tự nguyên_Xie": "篥 thường dùng trong 篳篥, một loại nhạc cụ thổi làm từ sậy, có nguồn gốc từ vùng Tây Vực (Trung Á), du nhập vào Trung Quốc thời Hán-Đường. Wiktionary chỉ ghi nhận phát âm lì và dùng trong 篳篥, không giải thích glyph. Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái kèn để làm hiện trong quân đội", "Hạng Tần Suất (Jun Da)": "6722.0", "Tần Suất % (Jun Da)": "99.9953225777", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "篥", "Unihan_Traditional (Chữ Phồn thể)": "篥", "Pinyin_Xie": "lì", "Âm Hán Việt_Xie": "lật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong từ ghép để chỉ một loại nhạc cụ thổi bằng tre thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('茈', '{"9000": "6723.0", "Chữ Trung Quốc": "茈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 茈 | thử | tượng hình | cỏ tử thảo, cây nhuộm màu tím | 茈 chưa có phân tích hình thanh hay hội ý rõ ràng từ Wiktionary. Dựa vào bộ 艸 (cỏ), chữ chỉ một loại thực vật — cỏ tử thảo dùng nhuộm màu tím. Chưa có nguồn học thuật xác nhận cấu trúc cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thử\": cỏ (艸) màu tím — thứ cỏ nhuộm tím đặc biệt của người xưa. | Gương Hán-Việt | thử — ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 茈 (thử) giúp nhận ra bộ 艸 trong các chữ thực vật và thảo dược cổ.", "Tự nguyên_Xie": "Bạch thư | Tiểu triện | 茈 chỉ loại cỏ dùng để nhuộm màu tím (tử thảo). Wiktionary không cung cấp phân tích glyph chi tiết. Hình dạng chữ gợi bộ 艸 (cỏ) ở trên và yếu tố biểu âm bên dưới. Chưa có nguồn học thuật xác nhận. Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mã thầy; củ năn (nói trong sách cổ)", "Hạng Tần Suất (Jun Da)": "6723.0", "Tần Suất % (Jun Da)": "99.9953282624", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 此", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹此", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "此", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "茈", "Unihan_Traditional (Chữ Phồn thể)": "茈", "Pinyin_Xie": "cí", "Âm Hán Việt_Xie": "sài", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loại cây thảo dược hoặc củ mã thầy trong sách cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('肏', '{"9000": "6724.0", "Chữ Trung Quốc": "肏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 8 | nét | 入 | nhập | biểu nghĩa | đi vào, nhập vào | 肉 | nhục | biểu nghĩa | thịt, thân xác | 肏 = 入 (Nhập, biểu nghĩa: đi vào) + 肉 (Nhục, biểu nghĩa: thịt); chữ hội ý. Hai thành phần kết hợp theo nghĩa đen chỉ hành động tính giao — chữ thô tục trong tiếng Trung hiện đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhập nhục\": hội ý 入 (nhập, vào) + 肉 (nhục, thịt) — chữ thô tục, tránh dùng trong văn viết trang trọng. | Gương Hán-Việt | không có từ Hán-Việt thông dụng | Mở khoá kiến thức | Biết 肏 giúp nhận ra cấu trúc hội ý của các chữ Hán kết hợp ý nghĩa thành phần theo nghĩa đen.", "Tự nguyên_Xie": "Theo Wiktionary, 肏 là chữ hội ý (ls=ic): 入 (nhập, đi vào) + 肉 (nhục, thịt). Kết hợp ý nghĩa hai thành phần tạo ra nghĩa thô tục chỉ hành động tính giao. Đây là chữ tạo muộn, ít thấy trong giáp cốt hay kim văn cổ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "m; tiếng đan mạch (tiếng hạ lưu dùng để chửi bới, chỉ động tác giao hợp của nam giới)", "Hạng Tần Suất (Jun Da)": "6724.0", "Tần Suất % (Jun Da)": "99.995333947", "GavinGrover_Once (Chiết tự trực tiếp)": "入 + 肉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱入肉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "肉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "入", "Unihan_Simplified (Chữ Giản thể)": "肏", "Unihan_Traditional (Chữ Phồn thể)": "肏", "Pinyin_Xie": "cào", "Âm Hán Việt_Xie": "tháo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ trong khẩu ngữ thô tục để chửi bới hoặc chỉ hành vi tình dục. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('萩', '{"9000": "6725.0", "Chữ Trung Quốc": "萩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 萩 | tho | tượng hình | cây ngải, cây củi, cây điền ma | 萩 chứa bộ 艸 (cỏ, thực vật) nhưng Wiktionary không cung cấp phân tích hình thanh hay hội ý chi tiết. Chữ chỉ các loại thực vật: ngải cứu, cây catalpa, củi hoặc cây điền ma. Chưa có nguồn học thuật xác nhận cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tho\": cỏ cây (艸) thu hoạch làm củi — tho thẩn ngoài đồng nhặt ngải thu. | Gương Hán-Việt | tho — ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 萩 (tho) giúp nhận ra bộ 艸 trong các chữ thực vật và nhận biết tên cây cỏ trong cổ văn.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 萩 chỉ nhiều loại thực vật trong cổ thư: cây ngải (wormwood), đồng nghĩa với 梓 (cây catalpa), củi, và cây điền ma (Lespedeza bicolor). Wiktionary không giải thích glyph cụ thể. Chữ gồm bộ 艸 (cỏ) + yếu tố bên dưới. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một loài ngải", "Hạng Tần Suất (Jun Da)": "6725.0", "Tần Suất % (Jun Da)": "99.9953396317", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 秋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹秋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "秋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "萩", "Unihan_Traditional (Chữ Phồn thể)": "萩", "Pinyin_Xie": "qiū", "Âm Hán Việt_Xie": "thu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loài cây thuộc họ cúc hoặc ngải cứu trong thực vật học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('跐', '{"9000": "6726.0", "Chữ Trung Quốc": "跐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 13 | nét | 跐 | thứ | tượng hình | bước đạp lên, trượt ngã | 跐 chứa bộ 足 (chân), chỉ hành động bước, đạp hoặc trượt ngã. Wiktionary không cung cấp phân tích hình thanh hay hội ý chi tiết. Chữ có nhiều cách đọc với nghĩa khác nhau.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thứ\": bộ 足 (chân) — thứ bậc của bàn chân khi bước thứ bước trượt đất. | Gương Hán-Việt | thứ — ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 跐 (thứ) giúp nhận ra bộ 足 trong các chữ liên quan đến hành động đi, bước, dẫm.", "Tự nguyên_Xie": "跐 có nhiều phát âm: cǐ/zǐ (bước, đạp), cī (trượt ngã), caai2 (biến thể của 踩). Wiktionary ghi nhận các phát âm nhưng không giải thích glyph. Chữ thuộc bộ 足 (chân), gợi nghĩa hành động của bàn chân. Chưa có nguồn học thuật xác nhận cấu trúc cụ thể. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giẫm; đạp; chà đạp; giày xéo; nhón; kiễng (chân)", "Hạng Tần Suất (Jun Da)": "6726.0", "Tần Suất % (Jun Da)": "99.9953453163", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 此", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊此", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "此", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "跐", "Unihan_Traditional (Chữ Phồn thể)": "跐", "Pinyin_Xie": "cī", "Âm Hán Việt_Xie": "thử, thải", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ chỉ hành động giẫm lên vật gì đó hoặc bị trượt chân. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蹅', '{"9000": "6727.0", "Chữ Trung Quốc": "蹅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 16 | nét | 蹅 | tra | tượng hình | bước đi lộn xộn, giẫm đất bùn | 蹅 chứa bộ 足 (chân), gợi nghĩa hành động chân giẫm, bước. Wiktionary không cung cấp glyph origin hay phân tích cấu trúc. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tra\": bộ 足 (chân) — tra vào bùn khi bước chân giẫm lộn xộn. | Gương Hán-Việt | tra — ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 蹅 (tra) giúp nhận ra bộ 足 và các chữ chỉ động tác chân trong cổ văn.", "Tự nguyên_Xie": "蹅 không có phân tích glyph trên Wiktionary. Chữ thuộc bộ 足 (chân), có nghĩa bước đi lộn xộn hoặc giẫm vào chỗ bùn lầy. Chưa có nguồn học thuật xác nhận cấu trúc. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lội, dầm (mưa)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 查", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊查", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "查", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "蹅", "Unihan_Traditional (Chữ Phồn thể)": "蹅", "Pinyin_Xie": "chǎ", "Âm Hán Việt_Xie": "tra", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ chỉ hành động đi lội trong bùn đất hoặc nước mưa. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瞢', '{"9000": "6728.0", "Chữ Trung Quốc": "瞢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 15 | nét | 瞢 | mông | tượng hình | mắt mờ, không nhìn rõ, u mê | 瞢 chứa bộ 目 (mắt) ở dưới, gợi nghĩa liên quan đến thị giác — mắt mờ, nhìn không rõ. Wiktionary ghi nhận {{Han etym}} nhưng không phân tích cấu trúc chi tiết. Chưa có nguồn học thuật xác nhận hình thanh/hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mông\": bộ 目 (mắt) bị che phủ — mông lung, mắt mờ không thấy gì rõ ràng. | Gương Hán-Việt | mông lung, mông muội | Mở khoá kiến thức | Biết 瞢 (mông) liên kết với từ ''mông muội'', ''mông lung'' — những trạng thái tối tăm, không rõ ràng.", "Tự nguyên_Xie": "Tiểu triện | 瞢 mang nghĩa mắt mờ tối, không nhìn rõ, u mê. Wiktionary chỉ ghi nhận {{Han etym}} mà không cung cấp phân tích glyph. Chữ thuộc bộ 目 (mắt). Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mắt mờ; thẹn", "Hạng Tần Suất (Jun Da)": "6728.0", "Tần Suất % (Jun Da)": "99.9953566856", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "瞢", "Unihan_Traditional (Chữ Phồn thể)": "瞢", "Pinyin_Xie": "méng", "Âm Hán Việt_Xie": "măng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ miêu tả trạng thái thị lực suy giảm hoặc đầu óc mơ hồ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('罽', '{"9000": "6729.0", "Chữ Trung Quốc": "罽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 网 | Số nét | 17 | nét | 罒 | biểu nghĩa | lưới (biến thể của 网) | 㓹 | biểu âm | 罽 = 罒 (biến thể của 网, biểu nghĩa: lưới) + 㓹 (biểu âm); chữ hình thanh. Bộ lưới gợi liên hệ đến nghề dệt, vải thảm; âm phần 㓹 cho phát âm jì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kế\": lưới (罒) dệt thành tấm thảm kế tiếp nhau — kế hoạch dệt vải len từ sợi lưới. | Gương Hán-Việt | kế — ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 罽 (kế) giúp nhận ra bộ 罒 (lưới) trong các chữ liên quan đến dệt vải và đan lưới.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 罽 là chữ hình thanh (psc): 罒 (biến thể của 网, lưới, biểu nghĩa) + 㓹 (biểu âm). Chữ có nghĩa lưới cá (cổ), thảm/chiếu/vải lông cừu. Cũng dùng trong địa danh 罽賓 (Kābul, Afghanistan cổ đại). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "len, dạ", "Hạng Tần Suất (Jun Da)": "6729.0", "Tần Suất % (Jun Da)": "99.9953623702", "GavinGrover_Once (Chiết tự trực tiếp)": "罒 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱罒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "罽", "Unihan_Traditional (Chữ Phồn thể)": "罽", "Pinyin_Xie": "jì", "Âm Hán Việt_Xie": "kế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ các loại vải dệt bằng lông thú hoặc thảm len thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('聭', '{"9000": "6730.0", "Chữ Trung Quốc": "聭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 耳 | Số nét | 15 | nét | 聭 | quỹ | tượng hình | điếc, tai không nghe được | 聭 chứa bộ 耳 (tai), gợi nghĩa liên quan đến thính giác — điếc tai, nghe không rõ. Không có phân tích glyph từ Wiktionary. Chưa có nguồn học thuật xác nhận cấu trúc hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quỹ\": bộ 耳 (tai) bị tắc — quỹ đạo âm thanh bị chặn, tai điếc không nghe. | Gương Hán-Việt | quỹ — ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 聭 (quỹ) giúp nhận ra bộ 耳 trong các chữ liên quan đến thính giác và tai.", "Tự nguyên_Xie": "聭 mang nghĩa điếc, tai không nghe được. Wiktionary không cung cấp glyphOrigin chi tiết. Chữ thuộc bộ 耳 (tai). Chưa có nguồn học thuật xác nhận cấu trúc. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "聭", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "耳 + 鬼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰耳鬼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鬼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "耳", "Unihan_Simplified (Chữ Giản thể)": "聭", "Unihan_Traditional (Chữ Phồn thể)": "聭", "Pinyin_Xie": "kuì", "Âm Hán Việt_Xie": "quỹ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này thường dùng làm tính từ để miêu tả trạng thái xấu hổ hoặc e thẹn trong văn ngôn cổ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('辻', '{"9000": "6731.0", "Chữ Trung Quốc": "辻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 5 | nét | 辻 | thập | tượng hình | ngã tư đường (chữ Nhật tạo) | 辻 là chữ quốc tự Nhật Bản (kokuji), mượn vào tiếng Trung. Cấu trúc gồm 辶 (đi đường) + 十 (mười/chữ thập), biểu trưng ngã tư — nơi đường cắt nhau hình chữ thập. Không phải chữ Hán truyền thống.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thập\": bộ đường đi (辶) + chữ thập (十) — thập tự lộ, ngã tư đường hình chữ thập. | Gương Hán-Việt | thập tự lộ (ngã tư) | Mở khoá kiến thức | Biết 辻 (thập) giúp nhận ra cấu trúc chữ Nhật tạo dùng bộ thủ Hán kết hợp theo nghĩa hình ảnh.", "Tự nguyên_Xie": "辻 là chữ gốc Nhật (kokuji), theo Wiktionary là chữ mượn từ tiếng Nhật (辻, tsuji, ngã tư). Cấu trúc: 辶 (đi đường) + 十 (chữ thập) — đường cắt nhau hình dấu thập là ngã tư. Không có nguồn gốc Hán cổ. Chưa có nguồn học thuật Hán về chữ này. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Thập; ngã tư đường (chữ Hán của Nhật Bản có nghĩa là ngã tư, thường dùng làm tên người)", "Hạng Tần Suất (Jun Da)": "6731.0", "Tần Suất % (Jun Da)": "99.9953737395", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 十", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶十", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "十", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "辻", "Unihan_Traditional (Chữ Phồn thể)": "辻", "Pinyin_Xie": "shí", "Âm Hán Việt_Xie": "tật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ để chỉ ngã tư đường hoặc dùng trong tên riêng của người Nhật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铚', '{"9000": "6732.0", "Chữ Trung Quốc": "铚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 11 | nét | 铚 | chất | tượng hình | liềm nhỏ gặt lúa | 铚 chứa bộ 金 (kim loại), gợi nghĩa dụng cụ kim loại — liềm nhỏ dùng gặt lúa. Không có phân tích glyph chi tiết từ Wiktionary. Chưa có nguồn học thuật xác nhận cấu trúc hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chất\": bộ 金 (kim loại) — chất lượng lưỡi liềm kim loại để gặt lúa chín mùa thu. | Gương Hán-Việt | chất lượng, chất liệu | Mở khoá kiến thức | Biết 铚 (chất) giúp nhận ra bộ 金 trong các chữ chỉ công cụ nông nghiệp kim loại cổ đại.", "Tự nguyên_Xie": "Tiểu triện | 铚 là chữ chỉ một loại liềm nhỏ dùng để gặt lúa trong cổ thư. Wiktionary không cung cấp glyphOrigin chi tiết. Chữ thuộc bộ 金 (kim loại). Chưa có nguồn học thuật xác nhận cấu trúc. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "liềm ngắn; lưỡi hái; lưỡi liềm; gặt lúa; cắt lúa", "Hạng Tần Suất (Jun Da)": "6732.0", "Tần Suất % (Jun Da)": "99.9953794241", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 至", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅至", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "至", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铚", "Unihan_Traditional (Chữ Phồn thể)": "銍", "Pinyin_Xie": "zhì", "Âm Hán Việt_Xie": "trất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này thường làm danh từ chỉ cái liềm ngắn hoặc làm động từ chỉ hành động gặt lúa trong văn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('箦', '{"9000": "6733.0", "Chữ Trung Quốc": "箦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 14 | nét | 箦 | trách | tượng hình | chiếu tre, giường tre | 箦 chứa bộ 竹 (trúc), gợi nghĩa đồ vật làm từ tre — chiếu tre hoặc giường tre đan bện. Không có phân tích glyph chi tiết từ Wiktionary. Chưa có nguồn học thuật xác nhận cấu trúc hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trách\": bộ 竹 (tre) — trách nhiệm đan chiếu tre mát lành cho mùa hè. | Gương Hán-Việt | trách nhiệm, trách cứ | Mở khoá kiến thức | Biết 箦 (trách) giúp nhận ra bộ 竹 trong các chữ đồ dùng bằng tre và nhận liên kết Hán-Việt với ''trách''.", "Tự nguyên_Xie": "Tiểu triện | 箦 chỉ chiếu tre, giường tre đan bện. Wiktionary không cung cấp glyphOrigin chi tiết. Chữ thuộc bộ 竹 (trúc). Chưa có nguồn học thuật xác nhận cấu trúc. Chữ tạo muộn. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chiếu tre", "Hạng Tần Suất (Jun Da)": "6733.0", "Tần Suất % (Jun Da)": "99.9953851087", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 责", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮责", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "责", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "箦", "Unihan_Traditional (Chữ Phồn thể)": "簀", "Pinyin_Xie": "zé", "Âm Hán Việt_Xie": "trách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ tấm chiếu tre trải trên giường trong tiếng Hán cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('踣', '{"9000": "6734.0", "Chữ Trung Quốc": "踣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 15 | nét | 踣 | vội | tượng hình | ngã úp mặt, vấp ngã, thất bại | 踣 chứa bộ 足 (chân), gợi nghĩa hành động chân — ngã sấp mặt xuống đất. Wiktionary ghi nhận phát âm và định nghĩa nhưng không phân tích cấu trúc glyph. Chưa có nguồn học thuật xác nhận hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vội\": bộ 足 (chân) vội vàng vấp té — vội bước, chân ngã sấp mặt xuống đất. | Gương Hán-Việt | vội vàng, vội vã | Mở khoá kiến thức | Biết 踣 (vội) liên kết Hán-Việt với ''vội vàng'' — chân bước vội mà ngã sấp.", "Tự nguyên_Xie": "Tiểu triện | 踣 mang nghĩa văn ngôn: ngã sấp (fall forward/prone), phơi xác, lật đổ. Wiktionary ghi nhận phát âm bó/pòu nhưng không cung cấp phân tích glyph chi tiết. Chữ thuộc bộ 足 (chân). Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngã, té; ngã chết giữa đường", "Hạng Tần Suất (Jun Da)": "6734.0", "Tần Suất % (Jun Da)": "99.9953907934", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 咅", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊咅", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "咅", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "踣", "Unihan_Traditional (Chữ Phồn thể)": "踣", "Pinyin_Xie": "bó", "Âm Hán Việt_Xie": "bặc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động ngã nhào hoặc ngã chết giữa đường trong văn ngôn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('菑', '{"9000": "6735.0", "Chữ Trung Quốc": "菑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 艸 | tháu | biểu nghĩa | cỏ, thực vật | 甾 | biểu âm | 菑 = 艸 (Tháu, biểu nghĩa: cỏ/thực vật) + 甾 (biểu âm); chữ hình thanh. Bộ cỏ gợi nghĩa thực vật hoặc ruộng đất khai hoang; âm phần 甾 cho phát âm zāi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tai\": cỏ (艸) mọc trên đất tai hoang — mảnh ruộng mới khai hoang đầy cỏ dại. | Gương Hán-Việt | tai nạn, tai họa | Mở khoá kiến thức | Biết 菑 (tai) liên kết với ý nghĩa khai hoang đất đai và nhận ra bộ 艸 trong các chữ nông nghiệp.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 菑 là chữ hình thanh (psc): 艸 (cỏ, biểu nghĩa) + 甾 (biểu âm). Chữ có nghĩa đất mới khai hoang, ruộng năm đầu chưa canh tác, hoặc cây đổ. Liên quan đến nông nghiệp khai khẩn đất mới. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ruộng mới cày lần đầu; làm cỏ; nhổ cỏ; diệt cỏ", "Hạng Tần Suất (Jun Da)": "6735.0", "Tần Suất % (Jun Da)": "99.995396478", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 甾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹甾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "菑", "Unihan_Traditional (Chữ Phồn thể)": "菑", "Pinyin_Xie": "zāi", "Âm Hán Việt_Xie": "tai", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ ruộng mới khai khẩn hoặc làm động từ chỉ việc làm cỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('捃', '{"9000": "6736.0", "Chữ Trung Quốc": "捃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 10 | nét | 捃 | khuân | tượng hình | nhặt lên, thu lượm từng chút | 捃 chứa bộ 手 (tay), gợi nghĩa hành động tay — nhặt nhạnh, thu lượm từng chút. Không có phân tích glyph chi tiết từ Wiktionary. Chưa có nguồn học thuật xác nhận cấu trúc hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khuân\": bộ 手 (tay) khuân nhặt từng bông lúa rơi — khuân vác thu lượm từng chút sau mùa gặt. | Gương Hán-Việt | khuân vác, khuân chuyển | Mở khoá kiến thức | Biết 捃 (khuân) liên kết Hán-Việt với ''khuân vác'' — đôi tay nhặt nhạnh, khuân từng thứ nhỏ.", "Tự nguyên_Xie": "Lục thư thông | 捃 mang nghĩa nhặt lúa rơi sau gặt hái (gleaning), thu lượm từng chút một. Wiktionary không cung cấp glyphOrigin chi tiết. Chữ thuộc bộ 手 (tay). Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhặt nhạnh", "Hạng Tần Suất (Jun Da)": "6736.0", "Tần Suất % (Jun Da)": "99.9954078473", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 君", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌君", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "君", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "捃", "Unihan_Traditional (Chữ Phồn thể)": "捃", "Pinyin_Xie": "jùn", "Âm Hán Việt_Xie": "quấn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động nhặt nhạnh hoặc thu thập tài liệu, hiện vật. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瘕', '{"9000": "6737.0", "Chữ Trung Quốc": "瘕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 14 | nét | 疒 | biểu nghĩa | bệnh tật | 叚 | biểu âm | 瘕 = 疒 (biểu nghĩa: bệnh tật) + 叚 (biểu âm); chữ hình thanh. Bộ bệnh tật gợi nghĩa khối u/bướu trong bụng; âm phần 叚 cho phát âm jiǎ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giả\": bộ bệnh (疒) + âm giả — bướu giả trong bụng, loại bệnh đông y có thể di chuyển. | Gương Hán-Việt | giả — trong ''giả tạo'', ''giả mạo'' | Mở khoá kiến thức | Biết 瘕 (giả) giúp nhận ra bộ 疒 trong các thuật ngữ bệnh tật đông y và phân biệt với 癥 (trưng).", "Tự nguyên_Xie": "Theo Wiktionary, 瘕 là chữ hình thanh (psc): 疒 (bệnh tật, biểu nghĩa) + 叚 (biểu âm). Chữ y học chỉ khối u giả (giả tích), loại bướu bụng trong đông y có thể di chuyển vị trí — phân biệt với 癥 (bướu cố định). Thuật ngữ y học cổ truyền Trung Hoa. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bệnh hòn (tích hòn rắn chắc trong bụng)", "Hạng Tần Suất (Jun Da)": "6737.0", "Tần Suất % (Jun Da)": "99.9954135319", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 叚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒叚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "叚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "瘕", "Unihan_Traditional (Chữ Phồn thể)": "瘕", "Pinyin_Xie": "jiǎ", "Âm Hán Việt_Xie": "hà", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại bệnh kết hòn cục trong bụng theo y học cổ truyền. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('閒', '{"9000": "6738.0", "Chữ Trung Quốc": "閒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 12 | nét | 門 | môn | biểu nghĩa | cổng, cửa | 月 | nguyệt | biểu nghĩa | trăng, ánh trăng | 閒 = 門 (Môn, biểu nghĩa: cổng cửa) + 月 (Nguyệt, biểu nghĩa: trăng); chữ hội ý. Ánh trăng lọt qua khe cửa — gợi hình ảnh khoảng hở, khe hở, rồi mở rộng nghĩa thành nhàn rỗi, rảnh rang.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhàn\": cổng cửa (門) hé ra, ánh trăng (月) lọt qua — nhàn rỗi như đêm thanh bình ngắm trăng qua cửa. | Gương Hán-Việt | nhàn — trong ''nhàn rỗi'', ''nhàn nhã'', ''thư nhàn'' | Mở khoá kiến thức | Biết 閒 (nhàn) mở khoá: nhàn rỗi, nhàn nhã, thư nhàn, nhàn tản — trạng thái thảnh thơi trong văn hóa Hán.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Theo Wiktionary, 閒 là chữ hội ý (ic): 門 (cổng/cửa) + 月 (trăng) — ánh trăng lọt qua khe cửa, gợi nghĩa kẽ hở, khoảng trống, rảnh rang. Đây là chữ gốc của 間 (gian/nhàn). Kim văn và tiểu triện đã có dạng này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "202.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nguyệt (95) Môn (199)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Nguyệt (số 95) ở trong chữ Môn (số 199) . Buổi tối được rảnh rỗi ra ngắm mặt trăng (nguyệt) trước cửa (môn).", "Nghĩa Tiếng Việt_Xie": "thời gian rảnh rỗi", "Hạng Tần Suất (Jun Da)": "6738.0", "Tần Suất % (Jun Da)": "99.9954249012", "GavinGrover_Once (Chiết tự trực tiếp)": "門 + 月", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴門月", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "月", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "門", "Unihan_Simplified (Chữ Giản thể)": "閒", "Unihan_Traditional (Chữ Phồn thể)": "閒", "Pinyin_Xie": "xián", "Âm Hán Việt_Xie": "nhàn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ chỉ trạng thái rảnh rỗi hoặc làm danh từ chỉ khoảng trống, khe hở. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('顩', '{"9000": "6739.0", "Chữ Trung Quốc": "顩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 頁 | Số nét | 22 | nét | 顩 | yểm | tượng hình | răng nhô ra, hàm lồi | 顩 chứa bộ 頁 (trang/đầu), gợi nghĩa liên quan đến đầu mặt — răng nhô ra, hàm lồi. Wiktionary ghi nhận nghĩa và phát âm nhưng không phân tích cấu trúc glyph chi tiết. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"yểm\": bộ đầu/mặt (頁) với răng nhô — yểm mình lại vì hàm răng lồi xấu. | Gương Hán-Việt | yểm — trong ''yểm trợ'', ''yểm bùa'' | Mở khoá kiến thức | Biết 顩 (yểm) giúp nhận ra bộ 頁 trong các chữ liên quan đến khuôn mặt và đầu người.", "Tự nguyên_Xie": "顩 mang nghĩa răng nhô ra, hàm lồi (protruding teeth). Wiktionary ghi nhận các phát âm yǎn/qìn/hàn/qiǎn và nghĩa cụ thể, nhưng không giải thích glyph. Chữ thuộc bộ 頁. Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Chết tiệt", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "僉 + 頁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰僉頁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "僉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "頁", "Unihan_Simplified (Chữ Giản thể)": "顩", "Unihan_Traditional (Chữ Phồn thể)": "顩", "Pinyin_Xie": "yǎn", "Âm Hán Việt_Xie": "yểm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này thường dùng làm tính từ miêu tả khuôn mặt bị lệch hoặc hóp lại. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鳓', '{"9000": "6740.0", "Chữ Trung Quốc": "鳓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 19 | nét | 鳓 | lặc | tượng hình | cá lặc (Ilisha elongata), loại cá biển | 鳓 chứa bộ 魚 (cá), gợi nghĩa loài cá. Không có phân tích glyph chi tiết từ Wiktionary. Chữ chỉ loài cá lặc (Chinese herring). Chưa có nguồn học thuật xác nhận cấu trúc hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lặc\": bộ 魚 (cá) + âm lặc — cá lặc biển, tên dân gian vùng duyên hải. | Gương Hán-Việt | lặc — trong ''cá lặc'' | Mở khoá kiến thức | Biết 鳓 (lặc) giúp nhận ra bộ 魚 trong tên các loài cá Hán ngữ và tra cứu danh pháp ngư loại cổ.", "Tự nguyên_Xie": "鳓 chỉ loài cá lặc (Ilisha elongata), một loài cá biển thông dụng ở vùng duyên hải Trung Quốc. Wiktionary không cung cấp glyphOrigin chi tiết. Chữ thuộc bộ 魚 (cá). Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá lặc, cá bẹ dài", "Hạng Tần Suất (Jun Da)": "6740.0", "Tần Suất % (Jun Da)": "99.9954419551", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 勒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼勒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "勒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鳓", "Unihan_Traditional (Chữ Phồn thể)": "鰳", "Pinyin_Xie": "lè", "Âm Hán Việt_Xie": "lặc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài cá biển nhiều xương thường dùng làm thực phẩm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('聛', '{"9000": "6742.0", "Chữ Trung Quốc": "聛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 耳 | Số nét | 14 | nét | 聛 | bỉ | tượng hình | điếc một tai, nghe không rõ | 聛 chứa bộ 耳 (tai), gợi nghĩa liên quan đến thính giác — nghe không rõ, điếc. Không có phân tích glyph chi tiết từ Wiktionary. Chưa có nguồn học thuật xác nhận cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bỉ\": bộ 耳 (tai) + âm bỉ — bỉ tai, điếc một bên tai không nghe rõ. | Gương Hán-Việt | bỉ — trong ''bỉ ổi'', ''bỉ thử'' | Mở khoá kiến thức | Biết 聛 (bỉ) giúp nhận ra bộ 耳 và phân biệt các chữ chỉ trạng thái thính giác suy giảm.", "Tự nguyên_Xie": "聛 mang nghĩa điếc một bên tai hoặc nghe không rõ. Wiktionary không cung cấp glyphOrigin chi tiết. Chữ thuộc bộ 耳 (tai). Chưa có nguồn học thuật xác nhận cấu trúc. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Tạ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "耳 + 卑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰耳卑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "耳", "Unihan_Simplified (Chữ Giản thể)": "聛", "Unihan_Traditional (Chữ Phồn thể)": "聛", "Pinyin_Xie": "bǐ", "Âm Hán Việt_Xie": "bỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ trong văn ngôn để chỉ hành động liếc mắt nhìn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('脮', '{"9000": "6743.0", "Chữ Trung Quốc": "脮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 11 | nét | 脮 | nội | tượng hình | cá ươn thối; mệt mỏi, uể oải | 脮 chứa bộ 月/肉 (thịt), gợi nghĩa thịt cá bị ươn thối. Wiktionary ghi nhận phát âm và nghĩa nhưng không phân tích cấu trúc glyph chi tiết. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nội\": bộ thịt (肉) ươn — nội tạng cá bị thối, nặng mùi nội tạng ươn. | Gương Hán-Việt | nội — trong ''nội tạng'', ''nội địa'' | Mở khoá kiến thức | Biết 脮 (nội) giúp nhận ra bộ 月/肉 trong các chữ liên quan đến thịt và trạng thái thức ăn.", "Tự nguyên_Xie": "脮 có hai phát âm: něi (cá ươn thối, đồng nghĩa 鮾/餒) và tuǐ (dùng trong 腲脮, mệt mỏi uể oải). Wiktionary ghi nhận nghĩa cụ thể nhưng không giải thích glyph. Chữ thuộc bộ 月/肉 (thịt). Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "议", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 妥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月妥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "妥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "脮", "Unihan_Traditional (Chữ Phồn thể)": "脮", "Pinyin_Xie": "něi", "Âm Hán Việt_Xie": "nội", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ miêu tả trạng thái thịt bị bủng, sưng hoặc thối rữa. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('諹', '{"9000": "6744.0", "Chữ Trung Quốc": "諹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 16 | nét | 諹 | dương | tượng hình | (nghĩa không rõ, chữ hiếm) | 諹 chứa bộ 言 (lời nói), gợi nghĩa liên quan đến ngôn ngữ. Wiktionary ghi nhận phát âm yáng nhưng không cung cấp định nghĩa hay phân tích glyph. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dương\": bộ 言 (lời) dương lên — lời nói dương dương tự đắc, hào phóng. | Gương Hán-Việt | dương — trong ''dương dương'', ''dương liễu'' | Mở khoá kiến thức | Biết 諹 (dương) giúp nhận ra bộ 言 trong các chữ liên quan đến ngôn ngữ và lời nói.", "Tự nguyên_Xie": "諹 thuộc bộ 言 (lời nói). Wiktionary chỉ ghi nhận phát âm yáng và rfdef (cần định nghĩa) — nghĩa chưa được xác định rõ trong học giới. Chưa có nguồn học thuật xác nhận cấu trúc hay ý nghĩa. Chữ tạo muộn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đánh đòn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 昜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言昜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "諹", "Unihan_Traditional (Chữ Phồn thể)": "諹", "Pinyin_Xie": "yáng", "Âm Hán Việt_Xie": "dương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ cổ để chỉ việc ca ngợi hoặc tuyên truyền rộng rãi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('誖', '{"9000": "6745.0", "Chữ Trung Quốc": "誖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 14 | nét | 誖 | bội | tượng hình | ngang ngược, trái đạo lý; đồng nghĩa với 悖 | 誖 chứa bộ 言 (lời nói), gợi nghĩa lời nói ngang ngược, trái lý. Wiktionary ghi nhận đây là dị thể của 悖 (bội, ngang ngược). Chữ có giáp cốt văn và tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bội\": lời (言) bội phản — bội bạc, ngang ngược, phản lại đạo lý. | Gương Hán-Việt | bội — trong ''bội phản'', ''bội ơn'', ''bội nghĩa'' | Mở khoá kiến thức | Biết 誖 (bội) liên kết với ''bội phản'', ''bội ơn'' — lời nói và hành động trái đạo lý trong tiếng Việt gốc Hán.", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | Theo Wiktionary, 誖 là dị thể của 悖 (ngang ngược, lộn xộn, trái lý). Chữ thuộc bộ 言 (lời nói). Giáp cốt văn và tiểu triện đã có dạng này. Nghĩa: đi ngược, ngang ngược, lộn xộn — dùng trong 誖暴 (bạo ngược), 誖逆 (phản nghịch). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mâu thuẫn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 孛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言孛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "孛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "誖", "Unihan_Traditional (Chữ Phồn thể)": "誖", "Pinyin_Xie": "bèi", "Âm Hán Việt_Xie": "bội", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ bổ nghĩa cho hành vi hoặc động từ chỉ sự vi phạm đạo lý. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蕅', '{"9000": "6746.0", "Chữ Trung Quốc": "蕅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 15 | nét | 蕅 | ngẫu | tượng hình | ngó sen (藕), cây sen | 蕅 chứa bộ 艸 (cỏ/thực vật), gợi nghĩa thực vật — ngó sen. Wiktionary ghi nhận đây là dị thể của 藕 (ngẫu, ngó sen). Chưa có phân tích glyph chi tiết. Chưa có nguồn học thuật xác nhận cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngẫu\": bộ cỏ (艸) ngẫu nhiên — ngẫu nhiên như ngó sen mọc dưới bùn, trắng tinh khiết. | Gương Hán-Việt | ngẫu — trong ''ngẫu nhiên'', ''ngẫu hứng'' | Mở khoá kiến thức | Biết 蕅 (ngẫu) liên kết với 藕 (ngó sen) và từ ''ngẫu nhiên'', ''ngẫu hứng'' — xuất phát từ hình ảnh ngó sen bất ngờ mọc lên.", "Tự nguyên_Xie": "Theo Wiktionary, 蕅 là dị thể của 藕 (ngẫu, ngó sen — thân rễ của cây sen Nelumbo nucifera). Chữ thuộc bộ 艸 (thực vật). Chưa có nguồn học thuật xác nhận chi tiết cấu trúc. Chữ tạo muộn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Thịt lợn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 湡", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹湡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "湡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蕅", "Unihan_Traditional (Chữ Phồn thể)": "蕅", "Pinyin_Xie": "ǒu", "Âm Hán Việt_Xie": "ngẫu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ ngó sen trong văn bản. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('睒', '{"9000": "6747.0", "Chữ Trung Quốc": "睒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 13 | nét | 睒 | gườm | tượng hình | mắt nhìn liếc, nháy mắt | 睒 là chữ độc thể, bộ 目 (mắt). Chưa xác định rõ cấu trúc hình thành; có thể là chữ chỉ sự của 目. Chữ này ít tư liệu cổ văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"gườm\": mắt (目) nhìn gườm gườm — ánh mắt sắc bén liếc ngang, lấp lánh như tia chớp. | Gương Hán-Việt | \"gườm\" trong tiếng Việt: \"mắt gườm gườm\" — nhìn chằm chằm, nhìn đe doạ. | Mở khoá kiến thức | Biết 睒 mở khoá các từ miêu tả ánh mắt trong thơ văn cổ điển Trung Hoa.", "Tự nguyên_Xie": "Wiktionary không cung cấp phân tích cấu tạo chi tiết cho 睒. Bộ 目 (mắt) gợi liên quan đến thị giác. Chữ mang nghĩa nháy mắt, liếc mắt, lấp lánh — chưa có nguồn học thuật xác nhận glyph origin. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nháy mắt, chớp mắt; rình, dòm, nhòm; lấp lánh, nhấp nháy", "Hạng Tần Suất (Jun Da)": "6747.0", "Tần Suất % (Jun Da)": "99.9955437618", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 炎", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目炎", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "炎", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "睒", "Unihan_Traditional (Chữ Phồn thể)": "睒", "Pinyin_Xie": "shǎn", "Âm Hán Việt_Xie": "thiểm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường dùng làm động từ chỉ hành động liếc nhìn nhanh hoặc làm tính từ mô tả ánh sáng lấp lánh. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('笰', '{"9000": "6748.0", "Chữ Trung Quốc": "笰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 11 | nét | 笰 | phất | tượng hình | vật làm bằng tre, che chắn | 笰 thuộc bộ 竹 (trúc/tre). Wiktionary không cung cấp phân tích hình thành chi tiết. Chữ chỉ vật dụng làm bằng tre dùng che chắn (mui xe hoặc tên có buộc dây). Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phất\": tre (竹) uốn cong làm mui che — vật dụng tre phất phơ che nắng trên xe thời cổ. | Gương Hán-Việt | \"phất\" hiếm trong tiếng Việt hiện đại; gặp trong thuật ngữ cổ về xe ngựa và binh khí. | Mở khoá kiến thức | Biết 笰 giúp đọc hiểu các đoạn văn cổ Trung Hoa mô tả xe ngựa và trang bị quân sự.", "Tự nguyên_Xie": "Chưa có nguồn Wiktionary cung cấp glyph origin cho 笰. Bộ 竹 (tre) cho biết vật liệu chế tạo. Nghĩa cổ là mui xe hoặc tên cung có buộc dây. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tên có buộc dây; mui xe", "Hạng Tần Suất (Jun Da)": "6748.0", "Tần Suất % (Jun Da)": "99.9955489296", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 弗", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮弗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "弗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "笰", "Unihan_Traditional (Chữ Phồn thể)": "笰", "Pinyin_Xie": "fú", "Âm Hán Việt_Xie": "phất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn bản cổ để chỉ mui xe che mưa nắng hoặc loại tên đặc biệt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('籥', '{"9000": "6749.0", "Chữ Trung Quốc": "籥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 23 | nét | 竹 | trúc | biểu nghĩa | tre, vật liệu làm nhạc cụ | 龠 | thược | biểu âm | (nhạc cụ thổi cổ) | 籥 = 竹 (Trúc, biểu nghĩa: tre) + 龠 (Thược, biểu âm); chữ hình thanh. Bộ Trúc xác nhận nhạc cụ làm bằng tre, 龠 vừa gợi âm vừa là chữ gốc chỉ loại sáo cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thược\": tre (竹) thổi thành tiếng thược — cây sáo thược (籥) dùng trong lễ tế Khổng Tử, âm trong trẻo như tiếng suối. | Gương Hán-Việt | \"thược\" trong từ Hán-Việt: 籥管 (thược quản, loại sáo cổ), 橐籥 (thác thược, ống thổ lò rèn). | Mở khoá kiến thức | Biết 籥 mở khoá từ vựng âm nhạc và nghi lễ trong Kinh Thi, Chu Lễ và các văn bản Nho học.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 籥 là chữ hình thanh: 竹 (tre) biểu nghĩa, 龠 biểu âm. Đây là loại sáo tre cổ đại có 3 hoặc 6 lỗ, dùng trong nghi lễ Nho giáo và vũ đạo tế lễ. Kinh Thi nhắc tên: ''tay trái cầm 籥, tay phải cầm lông trĩ''. Ngoài ra còn có nghĩa then khoá và thanh tre tập viết thời thơ ấu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái thược (như sáo nhưng ngắn); then khoá", "Hạng Tần Suất (Jun Da)": "6749.0", "Tần Suất % (Jun Da)": "99.9955540975", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 龠", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮龠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "龠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "籥", "Unihan_Traditional (Chữ Phồn thể)": "籥", "Pinyin_Xie": "yuè", "Âm Hán Việt_Xie": "thược", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ nhạc cụ hơi cổ hoặc bộ phận khóa cửa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('翧', '{"9000": "6750.0", "Chữ Trung Quốc": "翧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羽 | Số nét | 15 | nét | 翧 | huyên | tượng hình | liên quan đến lông vũ, cánh chim | 翧 thuộc bộ 羽 (vũ/lông vũ). Wiktionary không cung cấp phân tích cấu tạo chi tiết. Chữ có thể liên quan đến cánh chim hay lông vũ, nhưng nghĩa cụ thể chưa rõ. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huyên\": lông vũ (羽) bay huyên náo — cánh chim vỗ ầm ào, huyên thiên. | Gương Hán-Việt | \"huyên\" hiếm trong tiếng Việt; có thể liên hệ với từ 喧 (huyên, ồn ào) qua âm đọc tương đồng. | Mở khoá kiến thức | Biết 翧 giúp nhận diện chữ hiếm trong thư tịch cổ về chim chóc và vũ đạo cung đình.", "Tự nguyên_Xie": "Wiktionary ghi nhận âm đọc Bắc Kinh là xuān nhưng không cung cấp glyph origin hay cấu tạo chi tiết. Bộ 羽 (lông vũ) gợi liên quan đến cánh chim hoặc lông vũ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "翧", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "宣 + 羽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰宣羽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宣", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羽", "Unihan_Simplified (Chữ Giản thể)": "翧", "Unihan_Traditional (Chữ Phồn thể)": "翧", "Pinyin_Xie": "xuān", "Âm Hán Việt_Xie": "huyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ cổ miêu tả động tác chim vỗ cánh bay lên. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镩', '{"9000": "6751.0", "Chữ Trung Quốc": "镩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 17 | nét | 镩 | toản | tượng hình | công cụ kim loại dùng đục, khoét | 镩 thuộc bộ 金 (kim loại). Wiktionary (dạng phồn thể 鑹) không cung cấp phân tích cấu tạo. Chữ chỉ loại dùi sắt dùng đục băng (ice pick) hoặc đục khoét. Chưa có nguồn học thuật chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"toản\": kim loại (金) nhọn toản thủng băng — cái dùi sắt đột thủng mặt băng cứng. | Gương Hán-Việt | \"toản\" ít gặp trong tiếng Việt hiện đại; liên hệ: 鑽 (toản, khoan, dùi). | Mở khoá kiến thức | Biết 镩 giúp đọc hiểu tên dụng cụ thủ công và từ vựng nghề rèn trong văn bản kỹ thuật cổ.", "Tự nguyên_Xie": "Wiktionary ghi nhận 镩 (phồn thể 鑹) là loại dùi sắt dùng đục băng. Không có glyph origin chi tiết. Bộ 金 (kim loại) cho biết vật liệu chế tạo. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đục thủng", "Hạng Tần Suất (Jun Da)": "6751.0", "Tần Suất % (Jun Da)": "99.9955644332", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 窜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅窜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "窜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镩", "Unihan_Traditional (Chữ Phồn thể)": "鑹", "Pinyin_Xie": "cuān", "Âm Hán Việt_Xie": "thoản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ dụng cụ đục lỗ hoặc động từ chỉ hành động đục, xuyên qua. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('耧', '{"9000": "6752.0", "Chữ Trung Quốc": "耧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 耒 | Số nét | 15 | nét | 耧 | lâu | tượng hình | nông cụ kéo gieo hạt | 耧 thuộc bộ 耒 (lỗi/cán cày). Wiktionary (dạng 耬) không cung cấp phân tích cấu tạo chi tiết. Bộ 耒 gắn với nông cụ cày bừa. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lâu\": cán cày (耒) kéo lâu ngày trên đồng — máy gieo hạt lâu đời của nông dân Trung Hoa. | Gương Hán-Việt | \"lâu\" trong từ Hán-Việt: 耧車 (lâu xa, máy gieo hạt kéo), 耧播 (lâu bá, gieo hạt bằng máy). | Mở khoá kiến thức | Biết 耧 mở khoá từ vựng nông nghiệp truyền thống trong văn học hiện thực và sử liệu canh tác.", "Tự nguyên_Xie": "Wiktionary ghi nhận 耧 (dị thể 耬) là máy gieo hạt kéo bằng người hoặc súc vật. Bộ 耒 (cán cày) xác nhận dụng cụ nông nghiệp. Tác phẩm văn học 1948 của Tôn Lê (孫犁) nhắc đến 耬 trong cảnh cày ruộng. Chưa có nguồn học thuật phân tích glyph. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nông cụ đánh luống gieo hạt", "Hạng Tần Suất (Jun Da)": "6752.0", "Tần Suất % (Jun Da)": "99.995569601", "GavinGrover_Once (Chiết tự trực tiếp)": "耒 + 娄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰耒娄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "娄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "耒", "Unihan_Simplified (Chữ Giản thể)": "耧", "Unihan_Traditional (Chữ Phồn thể)": "耬", "Pinyin_Xie": "lóu", "Âm Hán Việt_Xie": "lâu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ một loại nông cụ gieo hạt thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蜞', '{"9000": "6753.0", "Chữ Trung Quốc": "蜞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 14 | nét | 虫 | trùng | biểu nghĩa | côn trùng, sinh vật nhỏ | 其 | kỳ | biểu âm | 蜞 = 虫 (Trùng, biểu nghĩa: sinh vật nhỏ) + 其 (Kỳ, biểu âm); chữ hình thanh. Bộ Trùng xác nhận đây là loài sinh vật nhỏ, 其 gợi âm đọc qí.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kỳ\": trùng (虫) kỳ lạ bám vào da — con đỉa kỳ quặc hút máu, hay con cua 蟛蜞 kỳ nhỏ ven bờ. | Gương Hán-Việt | \"kỳ\" trong từ: 蟛蜞 (bằng kỳ, loài cua nhỏ) — thường dùng ghép với 蟛. | Mở khoá kiến thức | Biết 蜞 mở khoá tên sinh vật biển trong y học cổ truyền và văn học miêu tả cảnh quê.", "Tự nguyên_Xie": "Theo Wiktionary, 蜞 là chữ hình thanh: 虫 (sinh vật nhỏ) biểu nghĩa, 其 biểu âm. Chữ dùng chủ yếu trong tổ hợp 蟛蜞 (một loài cua nhỏ ven biển) và có nghĩa riêng là đỉa (leech). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con vắt, con đỉa", "Hạng Tần Suất (Jun Da)": "6753.0", "Tần Suất % (Jun Da)": "99.9955747689", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 其", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫其", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "其", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蜞", "Unihan_Traditional (Chữ Phồn thể)": "蜞", "Pinyin_Xie": "qí", "Âm Hán Việt_Xie": "kì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong các từ ghép chỉ các loài động vật nhỏ như cua sông hay đỉa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('舡', '{"9000": "6754.0", "Chữ Trung Quốc": "舡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 舟 | Số nét | 9 | nét | 舡 | cương | tượng hình | thuyền, tàu | 舡 thuộc bộ 舟 (thuyền). Wiktionary không cung cấp phân tích cấu tạo chi tiết. Bộ 舟 xác nhận liên quan đến thuyền bè. Chữ cổ chỉ thuyền hoặc tàu. Chưa có nguồn học thuật phân tích glyph.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cương\": thuyền (舟) căng buồm — con thuyền cương quyết vượt sóng gió. | Gương Hán-Việt | \"cương\" ít gặp trong từ Hán-Việt; liên hệ với 船 (thuyền) qua nghĩa tương đồng. | Mở khoá kiến thức | Biết 舡 giúp nhận diện chữ thuyền cổ trong thư tịch hàng hải và thơ ca sông nước.", "Tự nguyên_Xie": "Wiktionary ghi nhận âm đọc gāng (Bắc Kinh: gāng; Quảng Đông: gong1, syun4). Nghĩa cổ văn: thuyền, tàu. Bộ 舟 xác nhận phương tiện đường thủy. Chữ hiếm, âm đọc biến thể. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái thuyền", "Hạng Tần Suất (Jun Da)": "6754.0", "Tần Suất % (Jun Da)": "99.9955799367", "GavinGrover_Once (Chiết tự trực tiếp)": "舟 + 工", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舟工", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "工", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舟", "Unihan_Simplified (Chữ Giản thể)": "舡", "Unihan_Traditional (Chữ Phồn thể)": "舡", "Pinyin_Xie": "chuán", "Âm Hán Việt_Xie": "hang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn thơ cổ để chỉ thuyền bè. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鹀', '{"9000": "6755.0", "Chữ Trung Quốc": "鹀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 12 | nét | 鹀 | vô | tượng hình | loài chim nhỏ (sẻ đồng) | 鹀 thuộc bộ 鳥 (điểu/chim). Wiktionary (phồn thể 鵐) không cung cấp phân tích cấu tạo chi tiết. Bộ 鳥 xác nhận đây là tên chim. Chưa có nguồn học thuật phân tích glyph.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vô\": chim (鳥) vô danh nhỏ bé — sẻ đồng 鹀 không nổi tiếng, nhỏ nhắn như chim vô danh. | Gương Hán-Việt | \"vô\" trong từ Hán-Việt: 田鵐 (điền vô, sẻ đồng), 黃胸鵐 (hoàng hung vô, chim sẻ ngực vàng). | Mở khoá kiến thức | Biết 鹀 mở khoá tên các loài chim họ sẻ trong điểu học và thơ ca thiên nhiên Trung Hoa.", "Tự nguyên_Xie": "Wiktionary ghi nhận 鹀 (phồn thể 鵐) là tên chim sẻ đồng thuộc chi Emberiza (buntings). Không có glyph origin chi tiết. Bộ 鳥 xác nhận loài chim. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(một loại chim, giống chim sẻ)", "Hạng Tần Suất (Jun Da)": "6755.0", "Tần Suất % (Jun Da)": "99.9955902724", "GavinGrover_Once (Chiết tự trực tiếp)": "巫 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰巫鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鹀", "Unihan_Traditional (Chữ Phồn thể)": "鵐", "Pinyin_Xie": "wú", "Âm Hán Việt_Xie": "vũ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ các loài chim thuộc họ sẻ đồng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('罣', '{"9000": "6757.0", "Chữ Trung Quốc": "罣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 网 | Số nét | 11 | nét | 罣 | quái | tượng hình | cản trở, vướng mắc | 罣 thuộc bộ 网/罒 (võng/lưới). Wiktionary không cung cấp phân tích cấu tạo chi tiết. Bộ 网 gợi hình ảnh bị vướng lưới, bị cản. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quái\": lưới (网) quái dị vướng mắc — tâm bị vướng như cá mắc lưới, chướng ngại từ bên ngoài. | Gương Hán-Việt | \"quái\" trong từ Hán-Việt: 罣礙 (quái ngại, vướng mắc), 罣念 (quái niệm, lo âu vướng bận). | Mở khoá kiến thức | Biết 罣 mở khoá từ vựng Phật học và Hán văn cổ về sự vướng bận, lo âu tâm linh.", "Tự nguyên_Xie": "Wiktionary ghi nhận 罣 là dị thể của 絓 và 掛. Nghĩa: ngăn trở, vướng mắc, treo. Bộ 网 (lưới) gợi bị mắc kẹt, vướng víu. Gặp nhiều trong Phật học: 罣礙 (vô quái ngại). Chưa có nguồn glyph origin. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trở ngại, ngăn cản", "Hạng Tần Suất (Jun Da)": "6757.0", "Tần Suất % (Jun Da)": "99.9956006081", "GavinGrover_Once (Chiết tự trực tiếp)": "罒 + 圭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱罒圭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "圭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "罒", "Unihan_Simplified (Chữ Giản thể)": "罣", "Unihan_Traditional (Chữ Phồn thể)": "罣", "Pinyin_Xie": "guà", "Âm Hán Việt_Xie": "quái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ thể hiện sự vướng bận hoặc lo lắng trong lòng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('觍', '{"9000": "6758.0", "Chữ Trung Quốc": "觍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 見 | Số nét | 12 | nét | 觍 | điễn | tượng hình | xấu hổ, thẹn thùng | 觍 thuộc bộ 見 (kiến/thấy). Wiktionary không cung cấp glyph origin. Bộ 見 (nhìn, thấy) gợi cảm giác bị nhìn thấy — xấu hổ. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điễn\": nhìn thấy (見) mặt điễn đỏ — khi bị nhìn thẳng vào mặt thì xấu hổ, mặt đỏ bừng. | Gương Hán-Việt | \"điễn\" trong từ: 觍顏 (điễn nhan, mặt xấu hổ), 觍著臉 (điễn trước kiểm, mặt dày làm bừa). | Mở khoá kiến thức | Biết 觍 mở khoá từ vựng cảm xúc trong văn học cổ điển và Hán văn miêu tả tính cách.", "Tự nguyên_Xie": "Wiktionary không có tư liệu glyph origin cho 觍. Bộ 見 (nhìn) gợi hình ảnh bị người khác nhìn thẳng vào mặt — cảm giác xấu hổ, ngượng ngùng. Cũng dùng như 靦 (điễn: mặt dày, trơ tráo). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thẹn; e thẹn; trơ; mặt dày; điễn; như \"điễn nhan (xấu hổ); điễn trước kiểm (cứ làm bừa)\" \nTục dùng như điến 靦.", "Hạng Tần Suất (Jun Da)": "6758.0", "Tần Suất % (Jun Da)": "99.995605776", "GavinGrover_Once (Chiết tự trực tiếp)": "典 + 见", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰典见", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "典", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "见", "Unihan_Simplified (Chữ Giản thể)": "觍", "Unihan_Traditional (Chữ Phồn thể)": "覥", "Pinyin_Xie": "tiǎn", "Âm Hán Việt_Xie": "điễn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ bổ nghĩa cho khuôn mặt hoặc hành vi trơ trẽn, xấu hổ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('絽', '{"9000": "6759.0", "Chữ Trung Quốc": "絽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 12 | nét | 絽 | lữ | tượng hình | vải lụa mỏng thưa (sa) | 絽 thuộc bộ 糸 (mịch/tơ sợi). Wiktionary không cung cấp glyph origin. Bộ 糸 xác nhận chất liệu dệt. Chữ chỉ loại vải lụa mỏng, thưa lỗ (sa gauze). Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lữ\": tơ (糸) lữ hành qua lỗ thưa — vải lụa sa 絽 thưa như người lữ hành, gió lùa qua dễ dàng. | Gương Hán-Việt | \"lữ\" trong từ Hán-Việt: 絽紗 (lữ sa, vải lụa mỏng thưa). | Mở khoá kiến thức | Biết 絽 mở khoá tên vải và thuật ngữ dệt may trong văn bản thương mại và thơ ca trang phục cổ.", "Tự nguyên_Xie": "Wiktionary không có tư liệu glyph origin cho 絽. Bộ 糸 (tơ sợi) xác nhận chất liệu. Nghĩa: loại vải lụa sa mỏng thưa, dùng may trang phục mùa hè. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "絽", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 吕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹吕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "絽", "Unihan_Traditional (Chữ Phồn thể)": "絽", "Pinyin_Xie": "lǚ", "Âm Hán Việt_Xie": "lữ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ một loại vải dệt thưa hoặc sợi tơ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('羶', '{"9000": "6760.0", "Chữ Trung Quốc": "羶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羊 | Số nét | 19 | nét | 羊 | dương | biểu nghĩa | dê, cừu | 亶 | đản | biểu âm | 羶 = 羊 (Dương, biểu nghĩa: cừu/dê) + 亶 (Đản, biểu âm); chữ hình thanh. Bộ Dương cho biết mùi đặc trưng của cừu/dê, 亶 gợi âm shān.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chiên\": dê (羊) chiên bốc mùi — thịt dê/cừu 羶 có mùi hôi nồng đặc trưng, tiếng Việt gọi là \"mùi chiên\". | Gương Hán-Việt | \"chiên\" trong từ Hán-Việt: 羶肉 (chiên nhục, thịt dê/cừu hôi), 腥羶 (tinh chiên, mùi tanh hôi). | Mở khoá kiến thức | Biết 羶 mở khoá từ vựng ẩm thực và thành ngữ trong văn học về xu phụ quyền thế.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 羶 là chữ hình thanh: 羊 (cừu) biểu nghĩa, 亶 biểu âm. Nghĩa: mùi hôi đặc trưng của thịt cừu/dê (mùi chiên). Dùng trong thành ngữ mô tả sức hút của kẻ quyền thế: 如蟻附羶 (như kiến bu vào thịt dê hôi). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thịt cừu", "Hạng Tần Suất (Jun Da)": "6760.0", "Tần Suất % (Jun Da)": "99.9956161117", "GavinGrover_Once (Chiết tự trực tiếp)": "⺶ + 亶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⺶亶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺶", "Unihan_Simplified (Chữ Giản thể)": "羶", "Unihan_Traditional (Chữ Phồn thể)": "羶", "Pinyin_Xie": "shān", "Âm Hán Việt_Xie": "chiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ để miêu tả mùi hôi, gây đặc trưng của thịt dê hoặc cừu. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('臜', '{"9000": "6761.0", "Chữ Trung Quốc": "臜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 20 | nét | 臜 | táp | tượng hình | bẩn thỉu, nhơ nhuốc | 臜 thuộc bộ 肉/月 (nhục/thịt). Wiktionary (dạng 臢) không cung cấp glyph origin. Bộ 肉 gợi thịt, chất hữu cơ — bẩn thỉu hữu cơ. Chủ yếu dùng trong 腌臢 (nhơ bẩn). Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"táp\": thịt (肉) táp bẩn nhơ — 腌臢 gợi cảnh thứ hữu cơ thối rữa, bẩn thỉu không sạch sẽ. | Gương Hán-Việt | \"táp\" ít dùng độc lập; 腌臢 (yān zā) là tổ hợp thông dụng chỉ sự nhơ bẩn. | Mở khoá kiến thức | Biết 臜 giúp đọc hiểu từ 腌臢 trong văn xuôi miêu tả cảnh dơ bẩn, sống nghèo khó.", "Tự nguyên_Xie": "Wiktionary ghi nhận 臜 (dạng 臢) chủ yếu dùng trong tổ hợp 腌臢 (nhơ bẩn, dơ dáy). Không có glyph origin chi tiết. Bộ 肉 gợi sự nhơ bẩn hữu cơ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bẩn; nhớp nhúa; không sạch sẽ", "Hạng Tần Suất (Jun Da)": "6761.0", "Tần Suất % (Jun Da)": "99.9956212796", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 赞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月赞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "赞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "臜", "Unihan_Traditional (Chữ Phồn thể)": "臢", "Pinyin_Xie": "zā", "Âm Hán Việt_Xie": "trâm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường kết hợp với chữ khác tạo thành tính từ miêu tả sự bẩn thỉu, không sạch sẽ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('觔', '{"9000": "6762.0", "Chữ Trung Quốc": "觔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 角 | Số nét | 9 | nét | 觔 | cân | tượng hình | đơn vị đo cân (catty); rìu | 觔 thuộc bộ 角 (giác/sừng). Wiktionary không có tư liệu glyph origin. Bộ 角 gợi vật sắc, cứng. Chữ mang nghĩa cân (đơn vị trọng lượng) hoặc rìu. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cân\": sừng (角) nặng một cân — bộ góc sừng cứng chắc, nặng đúng một cân. | Gương Hán-Việt | \"cân\" trong từ Hán-Việt: 觔兩 (cân lượng, đơn vị đo khối lượng). | Mở khoá kiến thức | Biết 觔 giúp đọc hiểu các văn bản về đo lường và công cụ trong Hán văn thương mại cổ.", "Tự nguyên_Xie": "Wiktionary không có tư liệu glyph origin cho 觔. Bộ 角 (sừng) là bộ thủ. Nghĩa: cân (đơn vị khối lượng, catty ≈ 600g) hoặc cái rìu. Liên hệ với 斤 (cân/catty) qua nghĩa đồng nhất. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái rìu; cân (đơn vị khối lượng)", "Hạng Tần Suất (Jun Da)": "6762.0", "Tần Suất % (Jun Da)": "99.9956316153", "GavinGrover_Once (Chiết tự trực tiếp)": "角 + 力", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰角力", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "力", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "角", "Unihan_Simplified (Chữ Giản thể)": "觔", "Unihan_Traditional (Chữ Phồn thể)": "觔", "Pinyin_Xie": "jīn", "Âm Hán Việt_Xie": "cân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Lượng từ | 量词 | Danh từ | 名词 | Chữ này thường dùng làm lượng từ chỉ đơn vị đo khối lượng hoặc danh từ chỉ cái rìu. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('躼', '{"9000": "6763.0", "Chữ Trung Quốc": "躼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 身 | Số nét | 15 | nét | 身 | thân | biểu nghĩa | thân người | 長 | trường | biểu nghĩa | dài, cao | 躼 = 身 (Thân, thân người) + 長 (Trường, dài/cao); chữ hội ý. Hai thành phần kết hợp nghĩa: thân người cao lênh khênh, dáng người cao.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lão\": thân (身) dài lão khao — người lão khao cao lênh khênh, thân dài hơn người thường. | Gương Hán-Việt | \"lão\" trong từ: 躼佬 (lão lão, người cao lênh khênh); phương ngữ miêu tả vóc dáng. | Mở khoá kiến thức | Biết 躼 mở khoá từ vựng miêu tả ngoại hình trong phương ngữ và văn học dân gian Trung Hoa.", "Tự nguyên_Xie": "Theo Wiktionary, 躼 là chữ hội ý: 身 (thân người) + 長 (dài, cao). Nghĩa kết hợp: người có thân hình cao, lênh khênh. Không có glyph origin cổ đại. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "躼", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "身 + 長", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰身長", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "長", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "身", "Unihan_Simplified (Chữ Giản thể)": "躼", "Unihan_Traditional (Chữ Phồn thể)": "躼", "Pinyin_Xie": "lào", "Âm Hán Việt_Xie": "lão", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này chủ yếu dùng làm tính từ trong phương ngôn để miêu tả người có vóc dáng cao. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('岈', '{"9000": "6764.0", "Chữ Trung Quốc": "岈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 7 | nét | 山 | sơn | biểu nghĩa | núi | 牙 | nha | biểu âm | 岈 = 山 (Sơn, biểu nghĩa: núi) + 牙 (Nha, biểu âm); chữ hình thanh. Bộ Sơn xác nhận liên quan đến địa hình núi non, 牙 gợi âm yá.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nha\": núi (山) nha sâu thẳm — núi 嵖岈 với thung lũng sâu như răng nanh (nha) cắm vào đất. | Gương Hán-Việt | \"nha\" trong địa danh: 嵖岈山 (Tra Nha Sơn, núi ở tỉnh Hà Nam). | Mở khoá kiến thức | Biết 岈 mở khoá tên núi và từ miêu tả địa hình hiểm trở trong Hán văn địa lý cổ.", "Tự nguyên_Xie": "Theo Wiktionary, 岈 là chữ hình thanh: 山 (núi) biểu nghĩa, 牙 biểu âm. Nghĩa văn học: (thung lũng) sâu thẳm. Dùng trong địa danh 嵖岈 (tên núi ở Hà Nam, Trung Quốc). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Tra Nha (tên núi, ở tỉnh Hà Nam, Trung Quốc)", "Hạng Tần Suất (Jun Da)": "6764.0", "Tần Suất % (Jun Da)": "99.995641951", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 牙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰山牙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "牙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "岈", "Unihan_Traditional (Chữ Phồn thể)": "岈", "Pinyin_Xie": "yá", "Âm Hán Việt_Xie": "ha", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này thường dùng làm danh từ trong tên núi hoặc tính từ tả vẻ gồ ghề của núi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('潲', '{"9000": "6765.0", "Chữ Trung Quốc": "潲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 15 | nét | 水 | thủy | biểu nghĩa | nước | 稍 | sảo | biểu âm | 潲 = 水 (Thủy, biểu nghĩa: nước) + 稍 (Sảo, biểu âm); chữ hình thanh. Bộ Thủy xác nhận liên quan đến chất lỏng, 稍 gợi âm shào.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sảo\": nước (水) sảo tạt theo gió — mưa 潲 bị gió thổi xiên vào mặt, hắt thẳng vào người. | Gương Hán-Việt | \"sảo\" trong từ: 潲水 (sảo thủy, nước bẩn/cám lợn), 雨潲 (vũ sảo, mưa tạt). | Mở khoá kiến thức | Biết 潲 mở khoá từ vựng thời tiết và nông thôn trong văn học phương ngữ Trung Hoa.", "Tự nguyên_Xie": "Theo Wiktionary, 潲 là chữ hình thanh: 水 (nước) biểu nghĩa, 稍 biểu âm. Nghĩa: mưa bị gió thổi tạt nghiêng; vẩy nước; thức ăn lợn đã nấu. Hình ảnh mưa hắt vào theo gió. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giọt mưa bị gió thổi tạt rơi nghiêng xuống; rưới nước, vẩy nước; thức ăn nuôi lợn đã nấu chín", "Hạng Tần Suất (Jun Da)": "6765.0", "Tần Suất % (Jun Da)": "99.9956471188", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 稍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵稍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "稍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "潲", "Unihan_Traditional (Chữ Phồn thể)": "潲", "Pinyin_Xie": "shào", "Âm Hán Việt_Xie": "sảo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm động từ chỉ hành động nước mưa bị gió thổi tạt vào nhà. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('枧', '{"9000": "6766.0", "Chữ Trung Quốc": "枧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 8 | nét | 枧 | giản | tượng hình | máng tre dẫn nước; xà phòng | 枧 thuộc bộ 木 (mộc/gỗ). Wiktionary không có glyph origin. Bộ 木 xác nhận vật liệu gỗ hoặc tre. Chữ chỉ máng dẫn nước bằng tre/gỗ, cũng có nghĩa xà phòng (phương ngữ Quảng Đông). Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giản\": gỗ (木) giản dị dẫn nước — máng tre giản đơn dẫn nước từ nguồn về nhà. | Gương Hán-Việt | \"giản\" trong từ: 枧水 (giản thủy, nước tro kiềm/xà phòng tự nhiên). | Mở khoá kiến thức | Biết 枧 mở khoá từ vựng về công trình nước và hóa học dân gian trong phương ngữ Quảng Đông.", "Tự nguyên_Xie": "Wiktionary không có tư liệu glyph origin cho 枧. Bộ 木 (gỗ/tre) xác nhận vật liệu. Nghĩa gốc: máng dẫn nước bằng tre/gỗ; cọc gỗ. Trong phương ngữ Quảng Đông: xà phòng (枧水 = lye/nước tro). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "máng dẫn nước (bằng tre); xà phòng; xà bông", "Hạng Tần Suất (Jun Da)": "6766.0", "Tần Suất % (Jun Da)": "99.9956522867", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 见", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木见", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "见", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "枧", "Unihan_Traditional (Chữ Phồn thể)": "梘", "Pinyin_Xie": "jiǎn", "Âm Hán Việt_Xie": "kiển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ máng nước bằng tre hoặc dùng trong từ ghép chỉ xà phòng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('觌', '{"9000": "6767.0", "Chữ Trung Quốc": "觌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 見 | Số nét | 12 | nét | 觌 | địch | tượng hình | thăm viếng, diện kiến | 觌 thuộc bộ 見 (kiến/nhìn, gặp gỡ). Wiktionary (phồn thể 覿) không cung cấp glyph origin cấu tạo. Bộ 見 xác nhận hành động nhìn thấy, gặp gỡ. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"địch\": thấy (見) mặt địch thủ trong lễ diện kiến — 覿面 là gặp nhau trực tiếp, nhìn thẳng mặt. | Gương Hán-Việt | \"địch\" trong từ: 覿面 (địch diện, gặp mặt trực tiếp), 覿武 (địch vũ, phô diễn võ lực). | Mở khoá kiến thức | Biết 觌 mở khoá từ vựng ngoại giao và nghi lễ cung đình trong Hán văn kinh điển.", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | Wiktionary ghi nhận 觌 (phồn thể 覿) có âm dí và nghĩa văn học: nhìn thấy, gặp gỡ lễ nghi, thăm viếng, bày tỏ. Không có glyph origin cấu tạo chi tiết. Bộ 見 xác nhận hành vi thị giác và giao tiếp. Chưa có nguồn học thuật. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đi thăm", "Hạng Tần Suất (Jun Da)": "6767.0", "Tần Suất % (Jun Da)": "99.9956574545", "GavinGrover_Once (Chiết tự trực tiếp)": "卖 + 见", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰卖见", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "见", "Unihan_Simplified (Chữ Giản thể)": "觌", "Unihan_Traditional (Chữ Phồn thể)": "覿", "Pinyin_Xie": "dí", "Âm Hán Việt_Xie": "địch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường xuất hiện trong văn viết cổ chỉ việc gặp mặt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('膦', '{"9000": "6768.0", "Chữ Trung Quốc": "膦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 16 | nét | 膦 | lận | tượng hình | phosphine (PH₃), hợp chất phospho | 膦 thuộc bộ 肉/月 (nhục). Wiktionary không có glyph origin. Chữ là thuật ngữ hoá học hiện đại chỉ hợp chất phosphine (PH₃). Bộ 肉 được dùng để tạo ký tự hoá học. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lận\": chất lận độc hại — phosphine (膦, PH₃) là khí độc, mùi hôi như tỏi thối. | Gương Hán-Việt | \"lận\" trong hoá học: 膦化氫 (lận hoá khinh, phosphine PH₃), 磷化膦 (phosphine phái sinh). | Mở khoá kiến thức | Biết 膦 mở khoá thuật ngữ hoá học phosphine và các hợp chất lân trong giáo trình hoá học Trung văn.", "Tự nguyên_Xie": "膦 là chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Được tạo ra để phiên dịch thuật ngữ hoá học phosphine (PH₃) trong tiếng Trung hiện đại. Không có glyph origin học thuật. Bộ 肉/月 dùng cho nhóm hợp chất hữu cơ trong hoá học. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một hợp chất (công thức hoá học: PH3)", "Hạng Tần Suất (Jun Da)": "6768.0", "Tần Suất % (Jun Da)": "99.9956626224", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 粦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月粦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "粦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "膦", "Unihan_Traditional (Chữ Phồn thể)": "膦", "Pinyin_Xie": "lìn", "Âm Hán Việt_Xie": "lận", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chuyên ngành hóa học để chỉ hợp chất hữu cơ của phốt pho. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('礞', '{"9000": "6769.0", "Chữ Trung Quốc": "礞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 18 | nét | 礞 | mông | tượng hình | mông thạch, loại đá làm thuốc | 礞 thuộc bộ 石 (thạch/đá). Wiktionary không có glyph origin. Bộ 石 xác nhận đây là tên đá/khoáng vật. Chữ chỉ mông thạch (礞石), loại đá dùng trong đông y. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mông\": đá (石) mông lung kỳ bí — mông thạch 礞石 là viên đá mờ đục dùng trị bệnh. | Gương Hán-Việt | \"mông\" trong đông y: 礞石 (mông thạch, loại đá trị đờm). | Mở khoá kiến thức | Biết 礞 mở khoá tên dược liệu đông y và khoáng vật trong y thư cổ Trung Hoa.", "Tự nguyên_Xie": "Wiktionary không có tư liệu glyph origin cho 礞. Bộ 石 (đá) xác nhận khoáng vật. Nghĩa: mông thạch (礞石), loại đá khoáng dùng trong đông y để trị đờm. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đá mông thạch (dùng làm thuốc)", "Hạng Tần Suất (Jun Da)": "6769.0", "Tần Suất % (Jun Da)": "99.9956677902", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 蒙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石蒙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "蒙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "礞", "Unihan_Traditional (Chữ Phồn thể)": "礞", "Pinyin_Xie": "méng", "Âm Hán Việt_Xie": "mông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chủ yếu dùng trong y học cổ truyền để chỉ loại khoáng vật làm thuốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蝤', '{"9000": "6770.0", "Chữ Trung Quốc": "蝤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 15 | nét | 蝤 | tựu | tượng hình | ấu trùng, sâu; con cua 蝤蛑 | 蝤 thuộc bộ 虫 (trùng). Wiktionary chỉ cung cấp dữ liệu âm vị học. Bộ 虫 xác nhận sinh vật nhỏ. Chưa có nguồn học thuật chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tựu\": trùng (虫) tựu lại thành bầy — sâu ấu trùng 蝤 hay con cua 蝤蛑 lớn ở biển. | Gương Hán-Việt | \"tựu\" trong từ: 蝤蛑 (tựu mâu, loài cua biển lớn/swimming crab). | Mở khoá kiến thức | Biết 蝤 mở khoá tên sinh vật biển và côn trùng trong y học cổ truyền và thơ ca.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi nhận 蝤 chỉ có dữ liệu âm vị, không có glyph origin. Bộ 虫 xác nhận sinh vật nhỏ. Nghĩa: ấu trùng, sâu; dùng trong 蝤蛑 (tên loài cua biển lớn). Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: tưu mâu 蝤蛑)", "Hạng Tần Suất (Jun Da)": "6770.0", "Tần Suất % (Jun Da)": "99.9956729581", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 酋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫酋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "酋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蝤", "Unihan_Traditional (Chữ Phồn thể)": "蝤", "Pinyin_Xie": "qiú", "Âm Hán Việt_Xie": "du, tù", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường đi kèm với các chữ khác để chỉ tên một số loại cua biển. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('螗', '{"9000": "6771.0", "Chữ Trung Quốc": "螗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 16 | nét | 螗 | đường | tượng hình | loài ve sầu nhỏ | 螗 thuộc bộ 虫 (trùng). Wiktionary không cung cấp phân tích cấu tạo. Bộ 虫 xác nhận côn trùng. Nghĩa: một loài ve sầu nhỏ. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đường\": trùng (虫) kêu đường đường — ve sầu 螗蜩 kêu inh ỏi như vạc dầu đang sôi. | Gương Hán-Việt | \"đường\" trong từ: 螗蜩 (đường điêu, loại ve sầu nhỏ), 蜩螗 (điêu đường, ve sầu kêu ầm ĩ). | Mở khoá kiến thức | Biết 螗 mở khoá tên côn trùng và thành ngữ thiên nhiên trong Kinh Thi và thơ Hán cổ.", "Tự nguyên_Xie": "Wiktionary ghi nhận 螗 không có định nghĩa rõ ràng nhưng có từ ghép 螗蜩 (một loài ve sầu). Bộ 虫 xác nhận côn trùng. Thơ Kinh Thi nhắc 蜩螗沸羹 (tiếng ve rền như nước sôi). Chưa có nguồn học thuật phân tích glyph. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: đường điêu 螗蜩)", "Hạng Tần Suất (Jun Da)": "6771.0", "Tần Suất % (Jun Da)": "99.9956781259", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 唐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫唐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "唐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "螗", "Unihan_Traditional (Chữ Phồn thể)": "螗", "Pinyin_Xie": "táng", "Âm Hán Việt_Xie": "đường", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường kết hợp thành từ ghép để chỉ một loại ve sầu nhỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('酹', '{"9000": "6772.0", "Chữ Trung Quốc": "酹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 14 | nét | 酹 | lại | tượng hình | rót rượu xuống đất tế thần | 酹 thuộc bộ 酉 (dậu/rượu). Wiktionary chỉ cung cấp dữ liệu âm vị. Bộ 酉 xác nhận liên quan đến rượu. Chữ chỉ hành động rót rượu xuống đất để tế lễ. Chưa có nguồn học thuật phân tích glyph.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lại\": rượu (酉) lại rót xuống đất — hành động tưới rượu lại xuống đất để tưởng nhớ người đã khuất. | Gương Hán-Việt | \"lại\" trong từ: 酹酒 (lại tửu, rót rượu tế); thi từ Tô Đông Pha: 一尊還酹江月 (một chén rót xuống trăng sông). | Mở khoá kiến thức | Biết 酹 mở khoá từ vựng nghi lễ tế tự và thơ từ Tống đại trong Hán văn văn học.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary ghi nhận 酹 có âm lèi, nghĩa rót rượu tế và tưới rượu xuống đất. Không có glyph origin. Bộ 酉 xác nhận rượu. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lấy rượu rót xuống đất để tế", "Hạng Tần Suất (Jun Da)": "6772.0", "Tần Suất % (Jun Da)": "99.9956832938", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 寽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉寽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "寽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "酹", "Unihan_Traditional (Chữ Phồn thể)": "酹", "Pinyin_Xie": "lèi", "Âm Hán Việt_Xie": "lỗi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thể hiện nghi thức rưới rượu xuống đất khi cúng tế. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('醅', '{"9000": "6773.0", "Chữ Trung Quốc": "醅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 15 | nét | 酉 | dậu | biểu nghĩa | rượu, bình rượu | 咅 | phẫu | biểu âm | 醅 = 酉 (Dậu, biểu nghĩa: rượu) + 咅 (Phẫu, biểu âm); chữ hình thanh. Bộ Dậu xác nhận đây là loại rượu, 咅 gợi âm pēi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phôi\": rượu (酉) phôi thai chưa lọc — rượu 醅 còn nguyên cặn, mới ủ xong, chưa qua lọc. | Gương Hán-Việt | \"phôi\" trong từ: 醅酒 (phôi tửu, rượu chưa lọc), 玉醅 (ngọc phôi, rượu ngon còn cặn). | Mở khoá kiến thức | Biết 醅 mở khoá từ vựng rượu trong thơ Đường và văn hóa ẩm thực Trung Hoa cổ điển.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 醅 là chữ hình thanh: 酉 (rượu) biểu nghĩa, 咅 biểu âm. Nghĩa: rượu chưa lọc, hèm rượu tươi. Bạch Cư Dị (Đường) đã dùng trong thơ: ''綠蟻新醅酒，紅泥小火爐'' (Rượu mới còn cặn màu xanh rêu, bếp lửa nhỏ đất đỏ). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rượu chưa lọc", "Hạng Tần Suất (Jun Da)": "6773.0", "Tần Suất % (Jun Da)": "99.9956884616", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 咅", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉咅", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "咅", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "醅", "Unihan_Traditional (Chữ Phồn thể)": "醅", "Pinyin_Xie": "pēi", "Âm Hán Việt_Xie": "phôi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loại rượu mới cất chưa qua màng lọc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('絅', '{"9000": "6774.0", "Chữ Trung Quốc": "絅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 11 | nét | 絅 | quýnh | tượng hình | áo không lót, áo phủ ngoài đơn | 絅 thuộc bộ 糸 (mịch/tơ sợi). Wiktionary không cung cấp glyph origin cấu tạo chi tiết. Bộ 糸 xác nhận chất liệu dệt. Chữ chỉ loại áo đơn không lót, thường mặc phủ bên ngoài. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quýnh\": tơ (糸) quýnh quáng phủ ngoài — áo đơn 絅 phủ lên bộ lụa gấm, che giấu vẻ đẹp bên trong. | Gương Hán-Việt | \"quýnh\" trong từ: 衣錦尚絅 (y cẩm thượng quýnh, mặc gấm mà phủ áo đơn — ẩn dụ khiêm nhường). | Mở khoá kiến thức | Biết 絅 mở khoá thành ngữ Trung Dung và triết học Nho giáo về đức hạnh che giấu.", "Tự nguyên_Xie": "Kim văn | Wiktionary ghi nhận 絅 là áo không lót (unlined garment). Từ ghép 衣錦尚絅 (mặc lụa gấm mà phủ áo đơn lên trên) xuất phát từ Trung Dung — ẩn dụ đức hạnh che giấu bên trong, không phô trương. Không có glyph origin. Chữ tạo muộn. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "煅", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 冋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹冋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "䌹", "Unihan_Traditional (Chữ Phồn thể)": "絅", "Pinyin_Xie": "jiōng", "Âm Hán Việt_Xie": "quýnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này thường làm danh từ chỉ áo đơn khoác ngoài hoặc tính từ chỉ sự sáng tỏ trong văn ngôn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('纁', '{"9000": "6775.0", "Chữ Trung Quốc": "纁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 20 | nét | 纁 | huân | tượng hình | màu đỏ nhạt, màu hồng nhạt | 纁 thuộc bộ 糸 (mịch/tơ sợi). Wiktionary không cung cấp glyph origin cấu tạo. Bộ 糸 xác nhận liên quan đến vải dệt và màu sắc vải. Chữ chỉ màu đỏ nhạt hoặc hồng. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huân\": tơ (糸) huân huy đỏ nhạt — vải lụa 纁 màu đỏ nhạt hồng như ánh hoàng hôn huân vàng. | Gương Hán-Việt | \"huân\" trong từ: 纁色 (huân sắc, màu đỏ nhạt/hồng), 纁黃 (huân hoàng, màu vàng đỏ). | Mở khoá kiến thức | Biết 纁 mở khoá tên màu sắc vải trong Hán văn lễ phục và văn học thơ ca cổ điển.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | Wiktionary ghi nhận 纁 có nghĩa màu đỏ nhạt, hồng và là dạng khác của 曛 (ánh hoàng hôn). Không có glyph origin. Bộ 糸 liên hệ với màu sắc vải dệt. Chữ tạo muộn. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "màu đỏ thẫm", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 熏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹熏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "熏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "𫄸", "Unihan_Traditional (Chữ Phồn thể)": "纁", "Pinyin_Xie": "xūn", "Âm Hán Việt_Xie": "huân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ màu sắc hoặc tính từ bổ nghĩa cho trang phục thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('葰', '{"9000": "6776.0", "Chữ Trung Quốc": "葰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 艸 | tháu | biểu nghĩa | cỏ, cây | 俊 | tuấn | biểu âm | 葰 = 艸 (Tháu, biểu nghĩa: cây cỏ) + 俊 (Tuấn, biểu âm); chữ hình thanh. Bộ Tháu xác nhận thực vật, 俊 gợi âm suī (gần với âm tuấn).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuy\": cỏ (艹) tuy nhỏ vẫn có ích — loài thực vật 葰 tuy không nổi tiếng nhưng có tên trong thảo mộc học cổ. | Gương Hán-Việt | \"tuy\" ít gặp trong từ Hán-Việt; liên hệ bộ tháu 艹 trong nhiều tên cây thuốc. | Mở khoá kiến thức | Biết 葰 giúp đọc hiểu tên thực vật trong thảo dược học Hán văn cổ.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 葰 là chữ hình thanh: 艸 (cỏ/cây) biểu nghĩa, 俊 biểu âm. Nghĩa không rõ trong Wiktionary (cùng ký hiệu rfdef). Bộ 艹 xác nhận thực vật. Chưa có nguồn học thuật xác nhận nghĩa cụ thể. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "谰", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 俊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹俊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "俊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "葰", "Unihan_Traditional (Chữ Phồn thể)": "葰", "Pinyin_Xie": "suī", "Âm Hán Việt_Xie": "tuy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ miêu tả cây cối tốt tươi hoặc danh từ chỉ một loại rau thơm cổ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('郇', '{"9000": "6777.0", "Chữ Trung Quốc": "郇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 8 | nét | 旬 | tuần | biểu âm | 邑 | ấp | biểu nghĩa | thành ấp, nước chư hầu | 郇 = 旬 (Tuần, biểu âm) + 邑 (Ấp, biểu nghĩa: thành ấp/nước); chữ hình thanh. Bộ Ấp xác nhận địa danh, 旬 gợi âm huán/tuần.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuần\": ấp (邑) tuần thú — nước Tuần 郇 là chư hầu nhỏ thời Chu, người cai quản tuần tra lãnh thổ mỗi tuần. | Gương Hán-Việt | \"tuần\" trong địa danh: 郇國 (tuần quốc, nước Tuần thời Tây Chu). | Mở khoá kiến thức | Biết 郇 mở khoá địa danh lịch sử thời Tây Chu trong Hán văn lịch sử và địa lý.", "Tự nguyên_Xie": "Theo Wiktionary, 郇 là chữ hình thanh: 旬 biểu âm, 邑 (thành ấp) biểu nghĩa. Chữ là tên nước chư hầu Tuần thời Tây Chu (nay thuộc Thiểm Tây hoặc Sơn Tây), phong cho con cháu nhà Chu. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước Tuân", "Hạng Tần Suất (Jun Da)": "6777.0", "Tần Suất % (Jun Da)": "99.995709133", "GavinGrover_Once (Chiết tự trực tiếp)": "旬 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰旬阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "郇", "Unihan_Traditional (Chữ Phồn thể)": "郇", "Pinyin_Xie": "huán", "Âm Hán Việt_Xie": "tuân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ riêng chỉ tên nước cổ hoặc họ của người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('躄', '{"9000": "6778.0", "Chữ Trung Quốc": "躄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 20 | nét | 躄 | tịch | tượng hình | tàn tật hai chân, ngã sấp | 躄 thuộc bộ 足 (túc/chân). Wiktionary không cung cấp glyph origin cấu tạo. Bộ 足 xác nhận liên quan đến chân. Nghĩa: liệt hai chân, tàn tật; ngã úp mặt. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tịch\": chân (足) tịch lặng không cử động — người 躄 liệt cả hai chân, đi đứng tịch mịch. | Gương Hán-Việt | \"tịch\" trong từ Hán-Việt: 躄者 (tịch giả, người tàn tật hai chân). | Mở khoá kiến thức | Biết 躄 mở khoá từ vựng tàn tật và lòng trắc ẩn trong văn học Hán cổ và Phật học.", "Tự nguyên_Xie": "Wiktionary ghi nhận 躄 có nhiều nghĩa và phương ngữ: ngã sấp mặt, liệt hai chân; trong Mân Nam tục ngữ còn có nghĩa thô tục. Bộ 足 (chân) xác nhận liên quan chi dưới. Chưa có glyph origin học thuật. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khoèo cả hai chân", "Hạng Tần Suất (Jun Da)": "6778.0", "Tần Suất % (Jun Da)": "99.9957143009", "GavinGrover_Once (Chiết tự trực tiếp)": "辟 + 足", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱辟足", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "辟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "足", "Unihan_Simplified (Chữ Giản thể)": "躄", "Unihan_Traditional (Chữ Phồn thể)": "躄", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "tích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ miêu tả trạng thái chân bị què hoặc động từ chỉ việc bị liệt. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('茼', '{"9000": "6779.0", "Chữ Trung Quốc": "茼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 茼 | đòng | tượng hình | rau đồng hao (Chrysanthemum coronarium) | 茼 thuộc bộ 艸/艹 (thảo/cỏ). Wiktionary không có glyph origin. Bộ 艹 xác nhận thực vật. Chữ dùng trong 茼蒿 (đồng hao, rau cải cúc). Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đòng\": cỏ (艹) đòng đưa mềm mại — rau 茼蒿 (cải cúc) lá mềm đòng đưa trong gió, hương thơm đặc biệt. | Gương Hán-Việt | \"đòng\" trong từ: 茼蒿 (đòng hao, rau cải cúc), 蓬茼 (bồng đòng). | Mở khoá kiến thức | Biết 茼 mở khoá tên rau trong ẩm thực và thực vật học Trung-Việt.", "Tự nguyên_Xie": "Wiktionary không có tư liệu glyph origin cho 茼. Bộ 艹 (cỏ/cây) xác nhận thực vật. Chữ chủ yếu dùng trong 茼蒿 (cải cúc, Chrysanthemum coronarium). Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: đồng hao 茼蒿)", "Hạng Tần Suất (Jun Da)": "6779.0", "Tần Suất % (Jun Da)": "99.9957194687", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 同", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹同", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "同", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "茼", "Unihan_Traditional (Chữ Phồn thể)": "茼", "Pinyin_Xie": "tóng", "Âm Hán Việt_Xie": "đồng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với chữ Hào thành từ ghép để chỉ rau cải cúc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('洧', '{"9000": "6780.0", "Chữ Trung Quốc": "洧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 9 | nét | 洧 | vĩ | tượng hình | sông Vị (Hà Nam, Trung Quốc) | 洧 thuộc bộ 水/氵 (thủy/nước). Wiktionary không cung cấp cấu tạo chi tiết. Bộ 氵 xác nhận địa danh sông nước. Chữ dùng riêng cho tên sông Vị tại Hà Nam. Chưa có nguồn học thuật phân tích glyph.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vĩ\": nước (氵) vĩ đại chảy qua — sông Vĩ 洧 chảy qua Hà Nam từ thời xa xưa, được nhắc trong Kinh Thi. | Gương Hán-Việt | \"vĩ\" trong địa danh: 洧水 (vĩ thủy, sông Vị), 洧川 (vĩ xuyên, Vĩ Xuyên). | Mở khoá kiến thức | Biết 洧 mở khoá địa danh sông nước trong Kinh Thi và địa lý học Hán cổ.", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | Wiktionary ghi nhận 洧 là tên riêng của sông Vị (洧水) tại tỉnh Hà Nam. Kinh Thi nhắc 溱洧 (Trinh-Vị, hai con sông). Bộ 氵 xác nhận địa danh sông. Chữ tạo muộn. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Vị", "Hạng Tần Suất (Jun Da)": "6780.0", "Tần Suất % (Jun Da)": "99.9957246366", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 有", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵有", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "有", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "洧", "Unihan_Traditional (Chữ Phồn thể)": "洧", "Pinyin_Xie": "wěi", "Âm Hán Việt_Xie": "vị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ riêng để chỉ tên sông hoặc địa danh cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('滠', '{"9000": "6781.0", "Chữ Trung Quốc": "滠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 13 | nét | 滠 | nhiếp | tượng hình | sông Nhiếp (Hồ Bắc, Trung Quốc) | 滠 thuộc bộ 水/氵 (thủy/nước). Wiktionary (dạng 灄) không cung cấp glyph origin. Bộ 氵 xác nhận địa danh sông. Chữ dùng riêng cho tên sông ở tỉnh Hồ Bắc. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhiếp\": nước (氵) nhiếp thu vào lòng đất — sông Nhiếp 滠 ở Hồ Bắc chảy nhiếp vào đất ẩm. | Gương Hán-Việt | \"nhiếp\" trong địa danh: 滠口 (nhiếp khẩu, cửa sông Nhiếp/Nhiếp Khẩu). | Mở khoá kiến thức | Biết 滠 giúp đọc địa danh sông nước Hồ Bắc trong sử liệu địa lý Trung Hoa.", "Tự nguyên_Xie": "Wiktionary ghi nhận 滠 (dạng 灄) là tên sông ở tỉnh Hồ Bắc. Không có glyph origin. Bộ 氵 xác nhận địa danh thủy văn. Chữ tạo muộn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Nhiếp Khẩu (tên đất, ở tỉnh Hồ Bắc, Trung Quốc)", "Hạng Tần Suất (Jun Da)": "6781.0", "Tần Suất % (Jun Da)": "99.9957298044", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 聂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵聂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "聂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "滠", "Unihan_Traditional (Chữ Phồn thể)": "灄", "Pinyin_Xie": "shè", "Âm Hán Việt_Xie": "nhiếp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ riêng trong các địa danh như Nhiếp Khẩu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('澉', '{"9000": "6782.0", "Chữ Trung Quốc": "澉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 14 | nét | 澉 | cảm | tượng hình | gột rửa; tên địa danh | 澉 thuộc bộ 水/氵 (thủy/nước). Wiktionary không cung cấp glyph origin hay định nghĩa rõ. Bộ 氵 xác nhận liên quan đến nước. Nghĩa: gột rửa hoặc tên địa danh. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cảm\": nước (氵) cảm ứng gột rửa — dùng nước rửa sạch, gột trôi bụi bặm. | Gương Hán-Việt | \"cảm\" trong địa danh: 澉浦 (cảm phổ, tên làng ven biển ở Chiết Giang). | Mở khoá kiến thức | Biết 澉 giúp đọc địa danh và từ gột rửa trong Hán văn địa lý và thơ ca.", "Tự nguyên_Xie": "Wiktionary chỉ ghi nhận âm đọc gǎn, không có định nghĩa hay glyph origin (rfdef). Bộ 氵 (nước) xác nhận liên quan đến nước. Nghĩa truyền thống: gột rửa; cũng dùng làm tên địa danh 澉浦 (Cảm Phổ). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gột rửa", "Hạng Tần Suất (Jun Da)": "6782.0", "Tần Suất % (Jun Da)": "99.9957349723", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 敢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵敢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "澉", "Unihan_Traditional (Chữ Phồn thể)": "澉", "Pinyin_Xie": "gǎn", "Âm Hán Việt_Xie": "cảm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường dùng làm động từ chỉ hành động tẩy rửa hoặc tính từ chỉ tính chất nước lợ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鎭', '{"9000": "6783.0", "Chữ Trung Quốc": "鎭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 18 | nét | 鎭 | trấn | tượng hình | biến thể của 鎮 (trấn thủ, thị trấn) | 鎭 là biến thể của 鎮 (trấn), thuộc bộ 金 (kim loại). Wiktionary xác nhận 鎭 là dạng khác của 鎮. Bộ 金 xác nhận liên quan đến kim loại. Chưa có glyph origin riêng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trấn\": kim loại (金) trấn giữ vững chắc — quân đồn trú nặng như sắt thép, trấn thủ biên cương. | Gương Hán-Việt | \"trấn\" trong từ Hán-Việt: 鎭守 (trấn thủ, canh giữ), 鎭壓 (trấn áp), 鎭靜 (trấn tĩnh, bình tĩnh). | Mở khoá kiến thức | Biết 鎭 mở khoá từ vựng quân sự, hành chính và từ biểu đạt sự ổn định trong Hán văn.", "Tự nguyên_Xie": "Wiktionary ghi nhận 鎭 là dạng khác (variant) của 鎮. 鎮 có glyph origin: 金 (kim loại) + 真 (biểu âm) — hình thanh. Nghĩa: trấn áp, trấn thủ; thị trấn. Dùng rộng rãi trong địa danh và từ quân sự. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鎭", "Hạng Tần Suất (Jun Da)": "6783.0", "Tần Suất % (Jun Da)": "99.9957401401", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 眞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金眞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "眞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鎭", "Unihan_Traditional (Chữ Phồn thể)": "鎭", "Pinyin_Xie": "zhèn", "Âm Hán Việt_Xie": "trấn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ việc trấn giữ hoặc danh từ chỉ thị trấn, đơn vị hành chính. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铏', '{"9000": "6784.0", "Chữ Trung Quốc": "铏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 11 | nét | 铏 | hình | tượng hình | cái liễn, đồ đựng thức ăn dùng trong tế lễ (chữ tạo muộn, dạng giản hoá của 鉶) | 铏 là dạng giản thể của 鉶. Chữ tạo muộn, xuất hiện từ Lục thư thông (thời Minh trở đi), chưa có trong giáp cốt hay kim văn. Không rõ cấu trúc hình thanh/hội ý từ dạng giản này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hình\": nhớ bộ kim (金) chỉ đồ kim loại — cái liễn đồng dùng đựng canh cúng tế. | Gương Hán-Việt | 铏 ít dùng trong từ Hán-Việt hiện đại; gặp trong văn ngôn với nghĩa đồ tế khí. | Mở khoá kiến thức | Biết 铏 giúp đọc hiểu các văn bản nghi lễ cổ Trung Hoa đề cập đến đồ tế khí bằng đồng.", "Tự nguyên_Xie": "Lục thư thông | 铏 là chữ giản thể của 鉶. Wiktionary chỉ ghi nhận âm đọc và nghĩa: đồ đựng thức ăn dùng trong tế lễ (sacrificial cauldron). Chữ tạo muộn, không có nguồn giáp cốt hay kim văn. Chưa có nguồn học thuật xác nhận cấu trúc ngữ nguyên. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái liễn (đồ đựng thức ăn)", "Hạng Tần Suất (Jun Da)": "6784.0", "Tần Suất % (Jun Da)": "99.995745308", "GavinGrover_Once (Chiết tự trực tiếp)": "钘 + 刂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钘刂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "钘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "刂", "Unihan_Simplified (Chữ Giản thể)": "铏", "Unihan_Traditional (Chữ Phồn thể)": "鉶", "Pinyin_Xie": "xíng", "Âm Hán Việt_Xie": "hình", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loại dụng cụ đựng thức ăn thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('赆', '{"9000": "6785.0", "Chữ Trung Quốc": "赆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 10 | nét | 赆 | tẫn | tượng hình | đồ tặng kẻ ra đi, lễ tiễn hành; dạng giản hoá của 贐 | 赆 là dạng giản thể/biến thể của 贐. Chữ tạo muộn, xuất hiện trong Lục thư thông. Cấu trúc ngữ nguyên theo 贐 gốc. Chưa thể xác định hình thanh hay hội ý từ dạng này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tẫn\": nghĩ đến \"tẫn\" (hết, cạn) — người sắp ra đi tặng nhau vật phẩm cuối cùng trước khi chia tay. | Gương Hán-Việt | tẫn ít dùng trong từ Hán-Việt thông dụng; gặp trong văn cổ với nghĩa lễ tiễn hành. | Mở khoá kiến thức | Biết 赆 giúp đọc thơ văn tiễn biệt cổ điển Trung Hoa.", "Tự nguyên_Xie": "Lục thư thông | Wiktionary dẫn chiếu 贐 làm dạng chính. 赆/贐 nghĩa là đồ tặng phẩm trao cho người lên đường, lễ vật tiễn hành; hoặc cống vật dâng lên vua chúa. Chữ tạo muộn, chưa có nguồn học thuật rõ ràng về cấu trúc dạng giản thể này. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đồ cống", "Hạng Tần Suất (Jun Da)": "6785.0", "Tần Suất % (Jun Da)": "99.9957556437", "GavinGrover_Once (Chiết tự trực tiếp)": "贝 + 尽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰贝尽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "贝", "Unihan_Simplified (Chữ Giản thể)": "赆", "Unihan_Traditional (Chữ Phồn thể)": "贐", "Pinyin_Xie": "jìn", "Âm Hán Việt_Xie": "tẫn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ để chỉ tiền của hoặc lễ vật tặng cho người đi xa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('赇', '{"9000": "6786.0", "Chữ Trung Quốc": "赇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 11 | nét | 貝 | bối | biểu nghĩa | vỏ sò, tiền | 求 | cầu | biểu âm | cầu xin | 赇 = 貝 (Bối, biểu nghĩa: tiền) + 求 (Cầu, biểu âm); chữ hình thanh. Tiền (貝) là ý nghĩa, 求 cho âm đọc qiú.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cầu\": tiền (貝) + cầu xin (求) — kẻ cầu xin dùng tiền để hối lộ quan lại. | Gương Hán-Việt | cầu trong văn ngôn với nghĩa hối lộ, ăn của đút. | Mở khoá kiến thức | Biết 赇 giúp đọc các văn bản pháp lý và sử ký cổ đề cập đến tham nhũng, hối lộ.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 赇 là chữ hình thanh: 貝 (vỏ sò/tiền) biểu nghĩa, 求 biểu âm. Nghĩa gốc là nhận của đút lót, ăn hối lộ. Tiền (貝) đi cùng ý cầu xin/trao đổi ngầm. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ăn của đút", "Hạng Tần Suất (Jun Da)": "6786.0", "Tần Suất % (Jun Da)": "99.9957608115", "GavinGrover_Once (Chiết tự trực tiếp)": "贝 + 求", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰贝求", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "求", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "贝", "Unihan_Simplified (Chữ Giản thể)": "赇", "Unihan_Traditional (Chữ Phồn thể)": "賕", "Pinyin_Xie": "qiú", "Âm Hán Việt_Xie": "cầu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này thường làm danh từ chỉ của đút lót hoặc làm động từ chỉ hành vi nhận hối lộ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('顣', '{"9000": "6787.0", "Chữ Trung Quốc": "顣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 頁 | Số nét | 20 | nét | 顣 | túc | tượng hình | nhăn mặt, cau mày (biến thể/dị thể của 蹙) | 顣 là dị thể cổ của 蹙, dùng với nghĩa nhăn mặt, cau mày. Wiktionary dẫn chiếu 蹙 làm dạng chuẩn. Cấu trúc nội tại không rõ từ dạng này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"túc\": nhớ âm \"túc\" gần với \"trúc\" (nhíu lại) — khuôn mặt nhíu lại, cau mày khó chịu. | Gương Hán-Việt | túc trong \"cau túc\" (cau mày nhăn nhó), gặp trong văn ngôn. | Mở khoá kiến thức | Biết 顣 giúp nhận diện dị thể khi đọc sách cổ bản in thời Tống-Minh.", "Tự nguyên_Xie": "Wiktionary định nghĩa 顣 là dị thể của 蹙 với nghĩa knit one''s brows (cau mày). Không có phân tích ngữ nguyên độc lập cho dạng này. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhăn, cau mày", "Hạng Tần Suất (Jun Da)": "6787.0", "Tần Suất % (Jun Da)": "99.9957659794", "GavinGrover_Once (Chiết tự trực tiếp)": "戚 + 頁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰戚頁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "戚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "頁", "Unihan_Simplified (Chữ Giản thể)": "顣", "Unihan_Traditional (Chữ Phồn thể)": "顣", "Pinyin_Xie": "cù", "Âm Hán Việt_Xie": "xúc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này thường làm động từ thể hiện nét mặt nhăn nhó hoặc cau mày khi lo lắng, đau đớn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('骕', '{"9000": "6788.0", "Chữ Trung Quốc": "骕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 11 | nét | 骕 | túc | tượng hình | tên của một con ngựa quý trong sách cổ | 骕 là chữ dùng để đặt tên ngựa quý trong văn học cổ. Cấu trúc ngữ nguyên không được phân tích rõ trong Wiktionary. Chữ hiếm gặp, chủ yếu xuất hiện trong tên ghép 驌驦.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"túc\": ngựa (bộ 馬) chạy nhanh như gió — tên riêng của ngựa thần trong huyền thoại Trung Hoa. | Gương Hán-Việt | túc xuất hiện trong tên ghép 驌驦 (Túc Song) — tên ngựa quý trong Sở từ. | Mở khoá kiến thức | Biết 骕 giúp đọc Sở từ và thi ca cổ điển Trung Hoa đề cập đến ngựa thần.", "Tự nguyên_Xie": "Wiktionary ghi nhận 骕 là tên của một con ngựa nổi tiếng (name of a famous horse). Không có phân tích ngữ nguyên cụ thể. Chưa có nguồn học thuật xác nhận cấu trúc. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngựa túc sương (nói trong sách cổ)", "Hạng Tần Suất (Jun Da)": "6788.0", "Tần Suất % (Jun Da)": "99.9957711472", "GavinGrover_Once (Chiết tự trực tiếp)": "马 + 肃", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰马肃", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "肃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "马", "Unihan_Simplified (Chữ Giản thể)": "骕", "Unihan_Traditional (Chữ Phồn thể)": "驌", "Pinyin_Xie": "sù", "Âm Hán Việt_Xie": "túc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng trong danh từ riêng để chỉ giống ngựa quý thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('飑', '{"9000": "6789.0", "Chữ Trung Quốc": "飑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 風 | Số nét | 9 | nét | 飑 | tiêu | tượng hình | cơn trở gió đột ngột (dạng giản thể của 颮) | 飑 là dạng giản thể của 颮 (phong + biểu âm). Wiktionary ghi rõ: 飑 = Han simplification của 颮, đổi 風 thành 风. Chữ khí tượng học hiện đại, chưa có trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiêu\": bộ phong (风) + âm biêu — gió (风) nổi lên đột ngột dữ dội, trở gió thình lình. | Gương Hán-Việt | tiêu trong \"phi tiêu\" (gió mạnh); gặp trong khí tượng học và thơ văn miêu tả bão tố. | Mở khoá kiến thức | Biết 飑 giúp đọc tài liệu khí tượng học và văn miêu tả thiên nhiên khắc nghiệt.", "Tự nguyên_Xie": "飑 là dạng giản thể của 颮 theo Wiktionary. Nghĩa: hiện tượng khí tượng khi hướng gió đột ngột chuyển chiều, tốc độ gió tăng mạnh, nhiệt độ giảm, kèm mưa rào (squall). Chữ tạo muộn, không có nguồn học thuật về ngữ nguyên dạng giản. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trở gió; thình lình chuyển gió (về khí tượng học, là hiện tượng thời tiết hướng gió chuyển hướng đột ngột, tốc độ gió tăng nhanh mạnh. Khi trở gió, nhiệt độ giảm, đồng thời có mưa rào)", "Hạng Tần Suất (Jun Da)": "6789.0", "Tần Suất % (Jun Da)": "99.9957763151", "GavinGrover_Once (Chiết tự trực tiếp)": "风 + 包", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴风包", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "包", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "风", "Unihan_Simplified (Chữ Giản thể)": "飑", "Unihan_Traditional (Chữ Phồn thể)": "颮", "Pinyin_Xie": "biāo", "Âm Hán Việt_Xie": "bào, phác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ trong khí tượng học để chỉ hiện tượng gió tăng tốc đột ngột. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('訄', '{"9000": "6790.0", "Chữ Trung Quốc": "訄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 9 | nét | 訄 | cầu | tượng hình | cấp bách, bức bách (chữ cổ hiếm gặp) | 訄 là chữ hiếm trong bộ 言. Wiktionary không có phân tích cấu trúc. Âm đọc qiú, nghĩa cấp bách/bức bách; gặp trong tên sách cổ như 訄書 của Chương Thái Viêm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cầu\": bộ ngôn (訁/言) + nghĩa bức bách — lời nói (言) cấp bách thúc ép người khác. | Gương Hán-Việt | cầu gặp trong tên 訄書 (Cầu Thư) — tác phẩm nổi tiếng của Chương Thái Viêm. | Mở khoá kiến thức | Biết 訄 giúp nhận diện tên tác phẩm 訄書 trong nghiên cứu học thuật Trung Hoa cận đại.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi nhận 訄 âm qiú, nghĩa bức bách, cấp thiết (rfdef — chưa có định nghĩa đầy đủ chính thức). Xuất hiện trong tên tác phẩm 訄書 của học giả Chương Thái Viêm thời Thanh. Có hình trong tiểu triện. Chưa có nguồn học thuật rõ về ngữ nguyên. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cấp bách, bức bách", "Hạng Tần Suất (Jun Da)": "6790.0", "Tần Suất % (Jun Da)": "99.9957814829", "GavinGrover_Once (Chiết tự trực tiếp)": "九 + 言", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴九言", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "九", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "訄", "Unihan_Traditional (Chữ Phồn thể)": "訄", "Pinyin_Xie": "qiú", "Âm Hán Việt_Xie": "cầu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này thường làm động từ chỉ sự thúc ép hoặc làm tính từ chỉ trạng thái khẩn cấp. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('輓', '{"9000": "6791.0", "Chữ Trung Quốc": "輓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 14 | nét | 車 | xa | biểu nghĩa | xe | 免 | miễn | biểu âm | tránh, thoát | 輓 = 車 (Xa, biểu nghĩa: xe) + 免 (Miễn, biểu âm); chữ hình thanh. Bộ 車 chỉ xe kéo, 免 cho âm wǎn. Về sau mở rộng nghĩa sang khóc thương người mất.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vãn\": xe (車) kéo đi (免) — kéo xe tang tiễn đưa người mất, tiếng khóc thương vãn. | Gương Hán-Việt | vãn trong \"vãn ca\" (bài ca điếu tang), \"vãn liên\" (câu đối viếng). | Mở khoá kiến thức | Biết 輓 giúp đọc văn thơ điếu tang cổ điển và hiểu 輓歌 (vãn ca), 輓聯 (vãn liên).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 輓 là chữ hình thanh: 車 (xe) biểu nghĩa, 免 biểu âm. Nghĩa gốc là kéo xe. Nghĩa phái sinh: khóc thương, điếu tang — từ hình ảnh kéo xe tang đưa linh cữu. Chữ truyền thống, có hình tiểu triện và lục thư thông. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "kéo xe", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "車 + 免", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰車免", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "免", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "車", "Unihan_Simplified (Chữ Giản thể)": "輓", "Unihan_Traditional (Chữ Phồn thể)": "輓", "Pinyin_Xie": "wǎn", "Âm Hán Việt_Xie": "vãn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường làm động từ chỉ việc kéo xe tang hoặc dâng câu đối viếng người đã khuất. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鋹', '{"9000": "6792.0", "Chữ Trung Quốc": "鋹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 16 | nét | 金 | kim | biểu nghĩa | kim loại | 長 | trường | biểu âm | dài | 鋹 = 金 (Kim, biểu nghĩa: kim loại) + 長 (Trường, biểu âm); chữ hình thanh. Bộ 金 chỉ vật kim loại sắc nhọn, 長 cho âm chǎng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sướng\": kim loại (金) dài (長) mài thành lưỡi — vũ khí sắc nhọn bén ngọt. | Gương Hán-Việt | sướng ít gặp trong từ Hán-Việt thông dụng; gặp trong văn ngôn miêu tả vũ khí. | Mở khoá kiến thức | Biết 鋹 giúp đọc văn miêu tả binh khí cổ đại và đặc tính kim loại.", "Tự nguyên_Xie": "Theo Wiktionary, 鋹 là chữ hình thanh: 金 (kim loại) biểu nghĩa, 長 biểu âm. Nghĩa: sắc nhọn (sharp). Chữ ít gặp trong văn bản hiện đại, không có trong giáp cốt hay kim văn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sắc nhọn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 長", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金長", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "長", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "𬬮", "Unihan_Traditional (Chữ Phồn thể)": "鋹", "Pinyin_Xie": "chǎng", "Âm Hán Việt_Xie": "sưởng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường làm tính từ bổ nghĩa cho vũ khí sắc bén hoặc người có tài năng sắc sảo. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钘', '{"9000": "6793.0", "Chữ Trung Quốc": "钘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 9 | nét | 钘 | hình | tượng hình | vò rượu cổ dài (chữ cổ bộ 金) | 钘 là chữ cổ bộ Kim, chỉ vò rượu hình dài. Có hình trong kim văn (bronze) và tiểu triện. Wiktionary ghi là dị thể của 鉶. Cấu trúc hình thanh/hội ý không được phân tích rõ cho dạng này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hình\": bộ kim (金) — đồ đựng (vò rượu/bát canh) bằng đồng thời cổ đại. | Gương Hán-Việt | hình ít gặp trong từ Hán-Việt thông dụng; dùng trong khảo cổ học và nghiên cứu đồng khí. | Mở khoá kiến thức | Biết 钘 giúp nhận diện tên đồ vật trong danh mục đồng khí thời Tây Chu.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Wiktionary ghi nhận 钘 âm đọc xíng (hoặc jiān khi là tên riêng), nghĩa vò rượu hình tròn cổ dài thời cổ, hoặc là dị thể của 鉶 (bát canh). Có hình trong kim văn (bronze inscription) và tiểu triện cho thấy chữ đã dùng từ thời Tây Chu. Chưa có nguồn học thuật rõ về ngữ nguyên độc lập. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vò rượu (thời xưa); bát canh", "Hạng Tần Suất (Jun Da)": "6793.0", "Tần Suất % (Jun Da)": "99.9958021544", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 开", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅开", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "开", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钘", "Unihan_Traditional (Chữ Phồn thể)": "鈃", "Pinyin_Xie": "xíng", "Âm Hán Việt_Xie": "hình", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ chỉ một loại dụng cụ đựng rượu hoặc canh thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('陁', '{"9000": "6794.0", "Chữ Trung Quốc": "陁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 7 | nét | 阜 | phụ | biểu nghĩa | núi đất, gò cao | 㐌 | biểu âm | 陁 = 阜 (Phụ, biểu nghĩa: núi đất, gò cao) + 㐌 (biểu âm); chữ hình thanh. Bộ 阜 (阝bên trái) chỉ địa hình đất đá, 㐌 cho âm tuó. Theo Wiktionary, đây là dạng theo 陀.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đà\": gò đất (阜) lởm chởm quanh co — địa thế đồi núi gồ ghề, cũng dùng phiên âm \"đà\" trong Phật-đà. | Gương Hán-Việt | đà trong \"Phật-đà\" (Buddha), \"lạc-đà\" (lạc đà); gặp nhiều trong văn bản Phật giáo. | Mở khoá kiến thức | Biết 陁 giúp đọc văn bản Phật giáo và địa lý cổ đại.", "Tự nguyên_Xie": "Theo Wiktionary (theo dạng 陀), 陁 là chữ hình thanh: 阜 (gò đất) biểu nghĩa, 㐌 biểu âm. Nghĩa: địa hình lởm chởm đất đá, quanh co. Dùng trong phiên âm tiếng Phạn (ví dụ Phật-đà 佛陁/佛陀). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lởm chởm đất đá; quanh co", "Hạng Tần Suất (Jun Da)": "6794.0", "Tần Suất % (Jun Da)": "99.9958073222", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + 㐌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝㐌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㐌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "陁", "Unihan_Traditional (Chữ Phồn thể)": "陁", "Pinyin_Xie": "tuó", "Âm Hán Việt_Xie": "trĩ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này thường làm danh từ chỉ sườn núi dốc hoặc làm tính từ miêu tả địa hình gồ ghề. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('耱', '{"9000": "6795.0", "Chữ Trung Quốc": "耱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 耒 | Số nét | 22 | nét | 耱 | mạc | tượng hình | bừa gỗ, dụng cụ san phẳng đất sau khi cày (nông cụ phương Bắc Trung Quốc) | 耱 là chữ bộ Lỗi (耒, dụng cụ nông nghiệp). Không có phân tích ngữ nguyên trong Wiktionary. Chữ tạo muộn, chuyên chỉ dụng cụ nông nghiệp. Chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mạc\": bộ lỗi (耒, nông cụ) — cái bừa san đất (mạc) sau khi cày xong ruộng. | Gương Hán-Việt | mạc ít gặp trong từ Hán-Việt thông dụng; dùng trong nông học và từ điển chuyên ngành. | Mở khoá kiến thức | Biết 耱 giúp đọc văn bản nông học truyền thống Trung Hoa về kỹ thuật canh tác.", "Tự nguyên_Xie": "Không có nguồn ngữ nguyên từ Wiktionary. 耱 chuyên chỉ loại bừa gỗ dùng để san phẳng và vỡ đất sau khi cày, phổ biến ở nông nghiệp miền Bắc Trung Quốc. Bộ 耒 cho biết đây là nông cụ. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bừa; san đất", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "耒 + 磨", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰耒磨", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "磨", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "耒", "Unihan_Simplified (Chữ Giản thể)": "耱", "Unihan_Traditional (Chữ Phồn thể)": "耱", "Pinyin_Xie": "mò", "Âm Hán Việt_Xie": "mạ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm động từ chỉ hoạt động dùng bừa để san phẳng đất ruộng sau khi cày. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鋵', '{"9000": "6796.0", "Chữ Trung Quốc": "鋵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 15 | nét | 鋵 | đột | tượng hình | chữ cổ hiếm, bộ kim, nghĩa chưa rõ | 鋵 là chữ hiếm bộ Kim. Không có phân tích ngữ nguyên trong Wiktionary. Cấu trúc và nghĩa chưa được ghi chép đầy đủ. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đột\": bộ kim (金) — vật kim loại đột xuất, nổi lên (đột) như mũi nhọn. | Gương Hán-Việt | đột ít gặp trong từ Hán-Việt thông dụng với nghĩa này. | Mở khoá kiến thức | Biết 鋵 giúp nhận diện chữ hiếm trong từ điển chuyên ngành kim thuật cổ.", "Tự nguyên_Xie": "Không có nguồn ngữ nguyên từ Wiktionary. 鋵 là chữ hiếm bộ Kim, âm tū. Nghĩa và cấu trúc chưa được ghi chép đầy đủ trong các từ điển thông dụng. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鋵", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 秃", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金秃", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "秃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鋵", "Unihan_Traditional (Chữ Phồn thể)": "鋵", "Pinyin_Xie": "tū", "Âm Hán Việt_Xie": "đột", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này là danh từ cổ chỉ một loại hợp kim kim loại như đồng thau. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鱵', '{"9000": "6797.0", "Chữ Trung Quốc": "鱵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 26 | nét | 鱵 | châm | tượng hình | cá kim, cá thu đao (loài cá có mõm dài nhọn như kim) | 鱵 là chữ bộ Ngư (魚), chỉ loài cá kim/cá thu đao có mõm dài nhọn. Wiktionary không có phân tích cấu trúc hình thanh/hội ý cho chữ này. Chữ tạo muộn, chuyên dùng trong danh pháp động vật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"châm\": bộ ngư (魚) — con cá (魚) có mõm nhọn như cây châm/kim may, đó là cá kim. | Gương Hán-Việt | châm trong danh pháp sinh học; tiếng Việt gọi là \"cá kim\" hay \"cá thu đao\". | Mở khoá kiến thức | Biết 鱵 giúp đọc tài liệu ngư học và phân loại sinh học loài cá.", "Tự nguyên_Xie": "Wiktionary chỉ ghi nhận âm zhēn và loài cá này. 鱵 chỉ loài cá họ Hemiramphidae — cá có hàm dưới dài nhọn như cây kim hay lưỡi đao. Chữ tạo muộn, không có nguồn giáp cốt hay kim văn. Chưa có nguồn học thuật về cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá kim, cá thu đao", "Hạng Tần Suất (Jun Da)": "6797.0", "Tần Suất % (Jun Da)": "99.9958279936", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 箴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚箴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "箴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鱵", "Unihan_Traditional (Chữ Phồn thể)": "鱵", "Pinyin_Xie": "zhēn", "Âm Hán Việt_Xie": "châm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một họ cá có thân dài và nhọn như cây kim. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('榀', '{"9000": "6798.0", "Chữ Trung Quốc": "榀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 13 | nét | 榀 | phẩm | tượng hình | nếp nhà, bộ khung (đơn vị đếm cho kết cấu mái nhà bằng gỗ) | 榀 là chữ bộ Mộc (木), dùng như lượng từ chỉ một vì kèo hoặc một nếp nhà trong kiến trúc gỗ. Không có phân tích ngữ nguyên trong Wiktionary. Chữ tạo muộn, chuyên dùng trong xây dựng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phẩm\": bộ mộc (木) — một \"phẩm\" (bộ) khung gỗ hình thành nếp nhà. | Gương Hán-Việt | phẩm trong lĩnh vực xây dựng kiến trúc; ít gặp trong văn chương. | Mở khoá kiến thức | Biết 榀 giúp đọc tài liệu kiến trúc truyền thống Trung Hoa về kết cấu nhà gỗ.", "Tự nguyên_Xie": "Không có nguồn ngữ nguyên từ Wiktionary. 榀 là lượng từ chuyên dụng trong kiến trúc gỗ truyền thống Trung Hoa, chỉ một vì kèo hoặc một bộ khung nhà (frame/truss). Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nếp (nhà); bộ (khung nhà)", "Hạng Tần Suất (Jun Da)": "6798.0", "Tần Suất % (Jun Da)": "99.9958590007", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 品", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木品", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "品", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "榀", "Unihan_Traditional (Chữ Phồn thể)": "榀", "Pinyin_Xie": "pǐn", "Âm Hán Việt_Xie": "phẩm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Lượng từ | 量词 | Danh từ | 名词 | Thường dùng làm lượng từ cho cấu trúc vì kèo hoặc khung nhà gỗ. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('膶', '{"9000": "6799.0", "Chữ Trung Quốc": "膶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 月 | Số nét | 16 | nét | 膶 | nhuận | tượng hình | gan heo (từ tiếng Quảng Đông); bộ nhục (月/肉) | 膶 là chữ bộ Nhục (月/肉). Không có phân tích ngữ nguyên trong Wiktionary. Đây là chữ chủ yếu dùng trong tiếng Quảng Đông (Cantonese) để chỉ gan lợn, không phổ biến trong tiếng Quan Thoại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhuận\": bộ nhục (肉/月) — thịt (肉) nhuận mềm, ám chỉ gan heo mềm mọng trong ẩm thực Quảng Đông. | Gương Hán-Việt | nhuận ít gặp trong từ Hán-Việt thông dụng; gặp trong thực đơn ẩm thực Quảng Đông. | Mở khoá kiến thức | Biết 膶 giúp đọc thực đơn nhà hàng Quảng Đông và tên món ăn truyền thống.", "Tự nguyên_Xie": "Không có nguồn ngữ nguyên từ Wiktionary. 膶 âm rùn (hoặc jeun trong Quảng Đông), chỉ gan heo trong tiếng Quảng Đông. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chủ yếu dùng trong ẩm thực Quảng Đông (Canton/Guangdong). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Mẹ kiếp", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 閏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月閏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "閏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "膶", "Unihan_Traditional (Chữ Phồn thể)": "膶", "Pinyin_Xie": "rùn", "Âm Hán Việt_Xie": "nhuận", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong phương ngôn phương nam để chỉ gan của động vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('茐', '{"9000": "6800.0", "Chữ Trung Quốc": "茐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 8 | nét | 茐 | thông | tượng hình | hành lá (dạng giản hoá đặc biệt của 蔥/葱) | 茐 là dạng giản hoá đặc biệt (supersimplified) của 蔥/葱 (hành lá). Wiktionary ghi: 茐 = Han simp của 蔥, đổi 悤 thành 匆; cũng là Han simp của 葱, đổi 怱 thành 匆. Chữ tạo muộn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thông\": bộ thảo (艸) + 匆 — cây thảo (艸) mọc nhanh như thông (thông suốt), đó là cây hành lá. | Gương Hán-Việt | thông trong \"hành thông\" (hành hương/hành lá); ẩm thực Việt gọi là \"hành lá\". | Mở khoá kiến thức | Biết 茐 giúp nhận diện dạng biến thể của 葱 (hành lá) trong các văn bản đặc biệt.", "Tự nguyên_Xie": "Theo Wiktionary, 茐 là dạng siêu giản hoá của 蔥 (và 葱), chỉ cây hành lá. Dạng gốc 蔥 có bộ Thảo (艸) + 悤 (biểu âm, nghĩa vội vã). Dạng 茐 đơn giản hoá phần âm thành 匆. Chữ tạo muộn, không gặp trong văn bản chính thống hiện đại. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "茐", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 匆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹匆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "茐", "Unihan_Traditional (Chữ Phồn thể)": "茐", "Pinyin_Xie": "cong", "Âm Hán Việt_Xie": "thông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này là biến thể cổ của chữ thông, dùng làm danh từ chỉ cây hành. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('螝', '{"9000": "6801.0", "Chữ Trung Quốc": "螝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 15 | nét | 螝 | quỷ | tượng hình | nhộng, kén; cũng là dị thể của 虺 (rắn độc) trong văn cổ | 螝 là chữ cổ bộ Trùng (虫), chỉ nhộng/kén (chrysalis/pupa). Wiktionary ghi hai nghĩa: (1) nhộng/kén (obs-std), (2) dị thể của 虺 (rắn độc). Cấu trúc ngữ nguyên không được phân tích rõ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quỷ\": bộ trùng (虫) — con trùng (虫) đang trong giai đoạn biến hoá thành kén nhộng như hồn quỷ ẩn náu. | Gương Hán-Việt | quỷ ít gặp trong từ Hán-Việt thông dụng với nghĩa này; gặp trong côn trùng học cổ điển. | Mở khoá kiến thức | Biết 螝 giúp đọc văn bản côn trùng học và bản thảo y dược cổ Trung Hoa.", "Tự nguyên_Xie": "Wiktionary ghi nhận 螝 âm huì/guì/huǐ, nghĩa gốc là nhộng/kén (pupa/chrysalis, nghĩa lỗi thời). Cũng là dị thể cổ của 虺 (rắn độc). Hai nghĩa hoàn toàn khác nhau có lẽ do chữ dùng âm mượn. Chưa có nguồn học thuật về ngữ nguyên. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "蝞", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 鬼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫鬼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鬼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "螝", "Unihan_Traditional (Chữ Phồn thể)": "螝", "Pinyin_Xie": "guī", "Âm Hán Việt_Xie": "quỷ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại côn trùng hoặc nhộng tằm trong văn bản cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('訙', '{"9000": "6802.0", "Chữ Trung Quốc": "訙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 10 | nét | 訙 | tấn | tượng hình | dị thể cổ của 訊 (hỏi thẩm, tin tức) | 訙 là dị thể cổ của 訊. Wiktionary dẫn chiếu: 訙 = dị thể của 訊 (xùn). Cấu trúc và ngữ nguyên theo dạng chuẩn 訊.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tấn\": bộ ngôn (言) — lời nói (言) hỏi thăm, dị thể cổ của chữ tấn (訊). | Gương Hán-Việt | tấn trong \"thẩm tấn\" (hỏi thẩm), \"thông tấn\" (tin tức/thông tin); dạng chuẩn là 訊. | Mở khoá kiến thức | Biết 訙 giúp nhận diện dị thể khi đọc văn bản cổ bản in.", "Tự nguyên_Xie": "Wiktionary định nghĩa 訙 là dị thể của 訊 (hỏi thẩm, tin tức). Không có phân tích ngữ nguyên độc lập. Dạng chuẩn 訊 = 言 (lời nói) + 卂 (biểu âm xùn). Chữ không còn dùng độc lập trong văn bản hiện đại. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "訙", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 丸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言丸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "訙", "Unihan_Traditional (Chữ Phồn thể)": "訙", "Pinyin_Xie": "xùn", "Âm Hán Việt_Xie": "tấn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ biểu thị hành vi hỏi han hoặc truyền đạt thông tin. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鄬', '{"9000": "6803.0", "Chữ Trung Quốc": "鄬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 14 | nét | 鄬 | vi | tượng hình | địa danh cổ ở tỉnh Hà Nam, Trung Quốc | 鄬 là chữ bộ Ấp (邑/阝bên phải), chỉ địa danh. Không có phân tích ngữ nguyên. Chữ chuyên dùng làm địa danh, ít xuất hiện ngoài ngữ cảnh đó.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vi\": bộ ấp (邑/阝) chỉ địa danh — vùng đất (鄬) ở Hà Nam có tên Hán-Việt là Vi. | Gương Hán-Việt | vi ít gặp trong từ Hán-Việt thông dụng; dùng trong địa lý lịch sử Trung Hoa. | Mở khoá kiến thức | Biết 鄬 giúp nhận diện địa danh cổ vùng Hà Nam trong lịch sử và địa lý học Trung Hoa.", "Tự nguyên_Xie": "Không có nguồn ngữ nguyên từ Wiktionary. 鄬 là tên địa danh cổ ở tỉnh Hà Nam (Henan), Trung Quốc. Bộ 邑 (阝bên phải) là dấu hiệu đặc trưng của chữ địa danh trong tiếng Hán. Chữ tạo muộn, không gặp trong giáp cốt/kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "địa điểm ở tỉnh Hà Nam", "Hạng Tần Suất (Jun Da)": "6803.0", "Tần Suất % (Jun Da)": "99.9959055114", "GavinGrover_Once (Chiết tự trực tiếp)": "爲 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰爲阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "爲", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "鄬", "Unihan_Traditional (Chữ Phồn thể)": "鄬", "Pinyin_Xie": "wéi", "Âm Hán Việt_Xie": "vy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ riêng chỉ địa danh cổ ở vùng Hà Nam, Trung Quốc ngày nay. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('閮', '{"9000": "6804.0", "Chữ Trung Quốc": "閮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 14 | nét | 閮 | đình | tượng hình | chữ hiếm bộ Môn, nghĩa chưa rõ | 閮 là chữ hiếm bộ Môn (門). Không có phân tích ngữ nguyên trong Wiktionary. Nghĩa và cấu trúc chưa được ghi chép đầy đủ. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đình\": bộ môn (門) — cánh cửa (門) đình (đình) lớn, có thể là biến thể chữ trong kiến trúc cổ. | Gương Hán-Việt | đình ít gặp trong từ Hán-Việt thông dụng với nghĩa này. | Mở khoá kiến thức | Biết 閮 giúp nhận diện chữ hiếm trong từ điển chuyên ngành kiến trúc và văn bản cổ.", "Tự nguyên_Xie": "Không có nguồn ngữ nguyên từ Wiktionary. 閮 là chữ hiếm bộ Môn (門), âm tíng. Nghĩa và cấu trúc chưa được ghi chép đầy đủ trong các từ điển thông dụng. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鮮", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "門 + 廷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴門廷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "廷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "門", "Unihan_Simplified (Chữ Giản thể)": "閮", "Unihan_Traditional (Chữ Phồn thể)": "閮", "Pinyin_Xie": "tíng", "Âm Hán Việt_Xie": "đình", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Làm tính từ miêu tả trạng thái tươi đẹp hoặc không gian rộng rãi trong văn cổ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鯆', '{"9000": "6805.0", "Chữ Trung Quốc": "鯆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 18 | nét | 鯆 | phố | tượng hình | cá heo, cá đuối (bộ Ngư) | 鯆 là chữ bộ Ngư (魚). Wiktionary không phân tích cấu trúc hình thanh/hội ý. Âm đọc bū/pū, nghĩa con cá heo (porpoise) hoặc cá đuối (ray) tuỳ theo cách đọc. Chữ tạo muộn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phố\": bộ ngư (魚) — loài cá (魚) biển phổ biến vùng ven bờ, có thể là cá heo hay cá đuối. | Gương Hán-Việt | phố ít gặp trong từ Hán-Việt thông dụng; dùng trong ngư học và phân loại động vật biển. | Mở khoá kiến thức | Biết 鯆 giúp đọc tài liệu ngư học cổ điển và nhận biết tên loài trong danh mục động vật biển Trung Hoa.", "Tự nguyên_Xie": "Wiktionary ghi nhận 鯆 có hai âm đọc bū và pū với nghĩa có thể là porpoise (cá heo) hoặc ray (cá đuối). Không có phân tích ngữ nguyên chi tiết. Chữ tạo muộn, không có nguồn giáp cốt hay kim văn. Chưa có nguồn học thuật về cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá heo", "Hạng Tần Suất (Jun Da)": "6805.0", "Tần Suất % (Jun Da)": "99.9959416863", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 甫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚甫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鯆", "Unihan_Traditional (Chữ Phồn thể)": "鯆", "Pinyin_Xie": "pū", "Âm Hán Việt_Xie": "phô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong tên gọi các loài cá biển cổ hoặc cá đuối. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('逿', '{"9000": "6806.0", "Chữ Trung Quốc": "逿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 12 | nét | 逿 | đãng | tượng hình | vượt qua; ngã; lắc lư (bộ Sước 辶) | 逿 là chữ bộ Sước (辶, đi đường). Không có phân tích ngữ nguyên trong Wiktionary. Nghĩa: vượt qua, ngã, lắc lư. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đãng\": bộ sước (辶, đi đường) — đi đường (辶) mà lảo đảo lắc lư (đãng), dễ vấp ngã. | Gương Hán-Việt | đãng ít gặp trong từ Hán-Việt thông dụng với nghĩa này; gặp trong văn miêu tả chuyển động. | Mở khoá kiến thức | Biết 逿 giúp nhận diện chữ hiếm bộ Sước trong các văn bản cổ điển.", "Tự nguyên_Xie": "Không có nguồn ngữ nguyên từ Wiktionary. 逿 là chữ bộ Sước (辶), âm dàng, nghĩa vượt qua/ngã/lắc lư. Chữ tạo muộn, không gặp trong giáp cốt hay kim văn. Chưa có nguồn học thuật về cấu trúc và ngữ nguyên. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vượt qua; ngã; lắc lư", "Hạng Tần Suất (Jun Da)": "6806.0", "Tần Suất % (Jun Da)": "99.9959468542", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 昜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶昜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "逿", "Unihan_Traditional (Chữ Phồn thể)": "逿", "Pinyin_Xie": "dàng", "Âm Hán Việt_Xie": "đãng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong văn ngôn để biểu thị hành động ngã hoặc vượt qua. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鮀', '{"9000": "6807.0", "Chữ Trung Quốc": "鮀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 16 | nét | 魚 | ngư | biểu nghĩa | cá | 它 | tha | biểu âm | 鮀 = 魚 (Ngư, biểu nghĩa: cá) + 它 (Tha, biểu âm); chữ hình thanh — bộ Ngư chỉ loài cá, Tha cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đà\" (âm Hán): con cá (魚) mang cái gì đó (它) trên lưng như con rùa đà — hình ảnh cá trê bò dưới đáy sông. | Gương Hán-Việt | đà — ít dùng trong tiếng Việt hiện đại, xuất hiện trong địa danh 鮀江 (Đà Giang). | Mở khoá kiến thức | Biết 鮀 mở khoá các địa danh phương Nam Trung Quốc như 鮀島, 鮀城 (tên cũ của Shantou).", "Tự nguyên_Xie": "Chữ hình thanh: 魚 (ngư) biểu nghĩa chỉ loài cá, 它 (tha) biểu âm cho âm tuó. Nghĩa gốc là một loại cá nhỏ nước ngọt; cũng dùng để chỉ cá trê hoặc làm dị thể của 鼉 (cá sấu Trung Quốc). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá mẫn (con cá nhỏ hay chúm miệng thổi cát)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 它", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚它", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "它", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "𬶍", "Unihan_Traditional (Chữ Phồn thể)": "鮀", "Pinyin_Xie": "tuó", "Âm Hán Việt_Xie": "đà", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ một loài cá nhỏ sống ở cát hoặc loài cá sấu nước ngọt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鯝', '{"9000": "6808.0", "Chữ Trung Quốc": "鯝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 19 | nét | 鯝 | cổ | tượng hình | loài cá nước ngọt thân dài, dẹt | 鯝 là chữ độc thể — bộ 魚 (ngư) ẩn trong cấu trúc tổng thể; nguồn gốc cấu tạo chi tiết chưa được Wiktionary phân tích rõ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cổ\" (gù): con cá (鯝) có bụng tròn như cái cổ bình — loài cá bạc mập mình sông suối. | Gương Hán-Việt | cổ — ít xuất hiện trong từ vựng Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 鯝 giúp nhận ra các tên loài cá đặc hữu Đài Loan trong văn bản sinh học cổ điển.", "Tự nguyên_Xie": "Chữ chỉ loài cá Taiwan shovel-jaw carp (Onychostoma barbatulum), thân dài dẹt, màu bạc ánh vàng. Trong văn cổ cũng mang nghĩa lòng cá. Cấu tạo chưa có phân tích hình thanh/hội ý từ nguồn học thuật; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá chim", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 固", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚固", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "固", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鯝", "Unihan_Traditional (Chữ Phồn thể)": "鯝", "Pinyin_Xie": "gù", "Âm Hán Việt_Xie": "cổ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ một chi cá nước ngọt thuộc họ cá chép. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鰁', '{"9000": "6809.0", "Chữ Trung Quốc": "鰁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 20 | nét | 鰁 | quyền | tượng hình | loài cá nước ngọt | 鰁 là chữ ít tài liệu — cấu tạo nội bộ chưa được phân tích rõ trong nguồn học thuật hiện có. Bộ 魚 (ngư) hiện diện trong cấu trúc, chỉ liên quan đến loài cá.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quyền\" (quán): con cá (鰁) có vây cong như nắm đấm (quyền) dưới nước. | Gương Hán-Việt | quyền — hầu như không xuất hiện trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 鰁 giúp đọc tên loài trong các sách sinh học cổ điển Trung Quốc.", "Tự nguyên_Xie": "Chữ chỉ một loài cá nước ngọt, chưa có mục phân tích glyph-origin trên Wiktionary. Không rõ cấu tạo hình thanh hay hội ý; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "遁", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 泉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚泉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "泉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鰁", "Unihan_Traditional (Chữ Phồn thể)": "鰁", "Pinyin_Xie": "quán", "Âm Hán Việt_Xie": "quyền", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ một loài cá nhỏ thuộc họ cá chép. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鱤', '{"9000": "6810.0", "Chữ Trung Quốc": "鱤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 24 | nét | 鱤 | cảm | tượng hình | loài cá yellowcheek, cá vàng má | 鱤 là chữ ít tài liệu chi tiết về cấu tạo — bộ 魚 (ngư) chỉ liên quan cá. Cấu tạo đầy đủ chưa được Wiktionary phân tích hình thanh/hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cảm\" (gǎn): con cá (鱤) khổng lồ khiến người ta phải cảm (cảm) phục — cá yellowcheek dài tới cả mét trong sông Dương Tử. | Gương Hán-Việt | cảm — không xuất hiện trong từ Hán-Việt thông dụng; chủ yếu dùng trong danh pháp sinh học. | Mở khoá kiến thức | Biết 鱤 giúp nhận ra tên loài cá lớn trong sách ngư nghiệp cổ điển Trung Quốc.", "Tự nguyên_Xie": "Chữ chỉ loài cá yellowcheek (Elopichthys bambusa), loài cá nước ngọt lớn của Trung Quốc, đồng nghĩa với 鰥 trong một số văn bản. Không có phân tích glyph-origin; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "豤", "Hạng Tần Suất (Jun Da)": "6113.0", "Tần Suất % (Jun Da)": "99.9852783419", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 感", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚感", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "感", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鳡", "Unihan_Traditional (Chữ Phồn thể)": "鱤", "Pinyin_Xie": "gǎn", "Âm Hán Việt_Xie": "cảm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ loài cá măng lớn chuyên ăn thịt ở sông hồ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('郕', '{"9000": "6811.0", "Chữ Trung Quốc": "郕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 8 | nét | 郕 | thành | tượng hình | nước Thành thời cổ | 郕 là tên địa danh cổ — bộ 阝(ấp, phải) chỉ địa danh/thành quách. Cấu tạo chi tiết chưa được Wiktionary phân tích đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thành\" (chéng): đất (阝) của nước Thành — một chư hầu nhỏ thời Xuân Thu nay là Sơn Đông. | Gương Hán-Việt | thành — đồng âm với 城 (thành phố), 成 (thành công), nhưng 郕 chỉ riêng địa danh cổ này. | Mở khoá kiến thức | Biết 郕 giúp đọc sử liệu Xuân Thu liên quan đến các nước chư hầu nhỏ vùng Sơn Đông.", "Tự nguyên_Xie": "Chữ chỉ nước Thành (郕) thời Xuân Thu, nay thuộc phía bắc huyện Vấn Thượng, tỉnh Sơn Đông. Bộ 阝(phải) chỉ vùng đất/nước chư hầu. Không có phân tích glyph-origin chi tiết; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước Thành thời cổ (nay thuộc phía bắc huyện Vấn Thượng, tỉnh Sơn Đông của Trung Quốc)", "Hạng Tần Suất (Jun Da)": "6811.0", "Tần Suất % (Jun Da)": "99.9959721767", "GavinGrover_Once (Chiết tự trực tiếp)": "成 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰成阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "成", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "郕", "Unihan_Traditional (Chữ Phồn thể)": "郕", "Pinyin_Xie": "chéng", "Âm Hán Việt_Xie": "thành", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ riêng chỉ tên một nước chư hầu thời Chu hoặc họ người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镴', '{"9000": "6812.0", "Chữ Trung Quốc": "镴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 20 | nét | 镴 | lạp | tượng hình | hợp kim chì-thiếc dùng làm thuốc hàn | 镴 là chữ giản thể của 鑞 — bộ 钅(kim, giản) thay cho 釒(kim, phồn), phần còn lại giữ nguyên. Chữ hình thanh chỉ kim loại hàn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lạp\" (là): kim loại (钅) dùng để lạp (hàn) — chì-thiếc nóng chảy điền vào khe hở như sáp nến. | Gương Hán-Việt | lạp — đồng âm với 臘 (lạp, tháng chạp), 蜡 (lạp chúc, nến sáp); nhưng 镴 chỉ riêng kim loại hàn. | Mở khoá kiến thức | Biết 镴/鑞 giúp đọc các văn bản kỹ thuật kim loại và nghề thủ công truyền thống Trung Quốc.", "Tự nguyên_Xie": "镴 là dạng giản thể của 鑞, chỉ hợp kim chì và thiếc dùng làm chất hàn (solder). Bộ 钅(kim) biểu nghĩa chỉ kim loại; phần biểu âm cho âm là. Wiktionary ghi rõ đây là giản hóa từ 鑞 (f=釒→t=钅). | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hợp kim của chì và thiếc dùng làm thuốc hàn", "Hạng Tần Suất (Jun Da)": "6812.0", "Tần Suất % (Jun Da)": "99.9959768277", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 巤", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅巤", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镴", "Unihan_Traditional (Chữ Phồn thể)": "鑞", "Pinyin_Xie": "là", "Âm Hán Việt_Xie": "lạp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ kim loại hoặc hợp kim dễ nóng chảy dùng để hàn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鮄', '{"9000": "6813.0", "Chữ Trung Quốc": "鮄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 16 | nét | 魚 | ngư | biểu nghĩa | cá | 弗 | phất | biểu âm | 鮄 = 魚 (Ngư, biểu nghĩa: cá) + 弗 (Phất, biểu âm); chữ hình thanh — bộ 魚 chỉ loài cá, 弗 cho âm fú/phất.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phất\" (fú): con cá (魚) phất (弗) vây đỏ dưới đáy biển — cá phất (gurnard) có vây ngực sặc sỡ như lá cờ. | Gương Hán-Việt | phất — xuất hiện trong tên ghép 魴鮄 (phương phất: loài cá gurnard/sculpin). | Mở khoá kiến thức | Biết 鮄 giúp đọc tên loài cá biển cổ điển trong sách ngư nghiệp Trung Hoa.", "Tự nguyên_Xie": "Chữ hình thanh: 魚 (ngư) biểu nghĩa chỉ loài cá biển; 弗 (phất) biểu âm cho âm fú. Chữ xuất hiện trong các từ điển lịch sử để chỉ một loại cá biển cụ thể (魴鮄, loài cá scorpionfish hoặc gurnard). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: phường phất 魴鮄)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 弗", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚弗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "弗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鮄", "Unihan_Traditional (Chữ Phồn thể)": "鮄", "Pinyin_Xie": "fú", "Âm Hán Việt_Xie": "phất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong các từ ghép cổ để chỉ một loài cá biển. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲙', '{"9000": "6814.0", "Chữ Trung Quốc": "鲙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 14 | nét | 鲙 | khoái | tượng hình | cá thái mỏng, gỏi cá | 鲙 là giản thể của 鱠 (魚+會) — bộ 鱼(ngư, giản) biểu nghĩa chỉ cá; phần 会(hội, giản) vốn biểu âm trong dạng phồn thể. Chữ hình thanh chỉ cá thái lát mỏng ăn sống.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khoái\" (kuài): con cá (鱼) được thái thành miếng (會/会 nghĩa tụ hội từng lát) — khoái khẩu khi thưởng thức gỏi cá tươi. | Gương Hán-Việt | khoái — xuất hiện trong 膾炙人口 (khoái chích nhân khẩu: được mọi người yêu thích, nổi tiếng). | Mở khoá kiến thức | Biết 鲙/鱠 mở khoá thành ngữ 膾炙人口 — câu nói nổi tiếng truyền miệng từ đời này sang đời khác.", "Tự nguyên_Xie": "鲙 là giản thể của 鱠, ghép từ 魚 (ngư: cá) và 會 (hội: tụ hội). Nghĩa gốc là cá thái mỏng ăn sống (gỏi cá), tương tự sashimi Nhật Bản. Wiktionary ghi đây là giản hóa: f=魚→t=鱼, f2=會→t2=会. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thái thịt cá nhỏ ra; cá bẹ", "Hạng Tần Suất (Jun Da)": "6814.0", "Tần Suất % (Jun Da)": "99.9959907809", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 会", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼会", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "会", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲙", "Unihan_Traditional (Chữ Phồn thể)": "鱠", "Pinyin_Xie": "kuài", "Âm Hán Việt_Xie": "khoái, quái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ món gỏi cá hoặc động từ chỉ việc thái mỏng thịt cá. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鳁', '{"9000": "6815.0", "Chữ Trung Quốc": "鳁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 17 | nét | 鳁 | ôn | tượng hình | cá mòi, cá sardine | 鳁 là chữ ít tài liệu chi tiết — bộ 鱼(ngư) chỉ loài cá. Là biến thể của 鰮 (cá sardine). Cấu tạo đầy đủ chưa được phân tích.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ôn\" (wēn): cá (鱼) ôn hòa (ôn) — cá mòi nhỏ bé hiền lành bơi thành đàn ấm áp dưới biển. | Gương Hán-Việt | ôn — không xuất hiện phổ biến trong từ Hán-Việt; chủ yếu dùng trong danh pháp sinh học. | Mở khoá kiến thức | Biết 鳁 giúp nhận ra tên cá mòi/sardine trong văn bản ngư nghiệp Trung Quốc.", "Tự nguyên_Xie": "鳁 là biến thể giản hóa của 鰮, chỉ cá sardine hoặc cá cơm. Không có mục phân tích glyph-origin trên Wiktionary; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá voi; cá kình; biến thể của 鰮", "Hạng Tần Suất (Jun Da)": "6815.0", "Tần Suất % (Jun Da)": "99.995995432", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 昷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼昷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鳁", "Unihan_Traditional (Chữ Phồn thể)": "鰮", "Pinyin_Xie": "wēn", "Âm Hán Việt_Xie": "ôn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ loài cá mòi biển trong các từ ghép. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('齁', '{"9000": "6816.0", "Chữ Trung Quốc": "齁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鼻 | Số nét | 19 | nét | 齁 | hầu | tượng hình | tiếng ngáy; quá ngọt/mặn đến nghẹt mũi | 齁 thuộc bộ 鼻 (tị: mũi) — chỉ âm thanh hoặc cảm giác liên quan đến mũi/họng. Cấu tạo nội bộ chi tiết chưa được Wiktionary phân tích đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hầu\" (hōu): tiếng hầu hầu vọng ra từ mũi (鼻) khi ngủ sâu — đó là tiếng ngáy mà ai cũng nghe quen. | Gương Hán-Việt | hầu — không xuất hiện trong từ Hán-Việt thông dụng; chữ dùng chủ yếu trong văn nói và văn học Trung Quốc. | Mở khoá kiến thức | Biết 齁 giúp hiểu các mô tả về tiếng ngủ ngáy hoặc vị quá nồng trong văn học Trung Quốc hiện đại.", "Tự nguyên_Xie": "Chữ thuộc bộ 鼻 (tị: mũi), chỉ tiếng ngáy (âm thanh qua mũi khi ngủ) hoặc cảm giác ngộp khi ăn thứ gì quá ngọt/mặn/cay. Chưa có phân tích glyph-origin chi tiết; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng ngáy", "Hạng Tần Suất (Jun Da)": "6816.0", "Tần Suất % (Jun Da)": "99.9960000831", "GavinGrover_Once (Chiết tự trực tiếp)": "鼻 + 句", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鼻句", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "句", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鼻", "Unihan_Simplified (Chữ Giản thể)": "齁", "Unihan_Traditional (Chữ Phồn thể)": "齁", "Pinyin_Xie": "hōu", "Âm Hán Việt_Xie": "hầu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm phó từ đứng trước tính từ để biểu thị mức độ cực kỳ hoặc làm động từ chỉ tiếng ngáy. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('膹', '{"9000": "6817.0", "Chữ Trung Quốc": "膹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 16 | nét | 膹 | phận | tượng hình | canh thịt; thái thịt chín | 膹 thuộc bộ 月/肉 (nhục: thịt) — chỉ món ăn từ thịt. Cấu tạo nội bộ chi tiết chưa được Wiktionary phân tích đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phận\" (fèn): thịt (月/肉) được thái chia từng phận — tô canh thịt thơm dùng trong nghi lễ cổ đại. | Gương Hán-Việt | phận — hầu như không xuất hiện trong từ Hán-Việt thông dụng; chỉ gặp trong từ nguyên học. | Mở khoá kiến thức | Biết 膹 giúp đọc các mô tả bữa ăn trong văn học và lễ nghi Trung Hoa cổ đại.", "Tự nguyên_Xie": "Chữ thuộc bộ 月/肉 (nhục: thịt), chỉ canh thịt hoặc hành động thái thịt chín (《廣韻》: 膹，切熟肉也). Là chữ văn ngôn ít dùng hiện đại; chưa có nguồn học thuật glyph-origin. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "膹", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 賁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月賁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "賁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "膹", "Unihan_Traditional (Chữ Phồn thể)": "膹", "Pinyin_Xie": "fèn", "Âm Hán Việt_Xie": "phận", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn ngôn để chỉ món thịt nấu chín. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('袣', '{"9000": "6818.0", "Chữ Trung Quốc": "袣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 10 | nét | 袣 | dật | tượng hình | (nghĩa chưa xác định rõ) | 袣 thuộc bộ 衣 (y: áo) — chỉ liên quan đến trang phục. Cấu tạo nội bộ chi tiết chưa được Wiktionary định nghĩa; được ghi là rfdef (cần định nghĩa).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dật\" (yì): áo (衣/袣) dật dờ — chữ cổ về trang phục mà ngay cả học giả cũng chưa xác định rõ nghĩa. | Gương Hán-Việt | dật — không xuất hiện trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 袣 giúp nhận ra một trong những chữ Hán bí truyền liên quan đến trang phục cổ đại.", "Tự nguyên_Xie": "Chữ thuộc bộ 衣 (y: áo), nhưng Wiktionary chỉ ghi {{rfdef|zh}} — nghĩa chưa được xác định chính thức. Chữ văn ngôn cực hiếm; chưa có nguồn học thuật glyph-origin. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "袣", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 世", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤世", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "世", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "袣", "Unihan_Traditional (Chữ Phồn thể)": "袣", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "dật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong cổ văn để chỉ loại áo dài. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('謿', '{"9000": "6819.0", "Chữ Trung Quốc": "謿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 19 | nét | 言 | ngôn | biểu nghĩa | lời nói | 朝 | triều | biểu âm | 謿 = 言 (Ngôn, biểu nghĩa: lời nói) + 朝 (Triều, biểu âm); chữ hình thanh — 言 chỉ ý nghĩa dùng lời trào phúng, 朝 cho âm cháo/trào. Là dị thể của 嘲.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trào\" (cháo): lời (言) chế nhạo như triều thần (朝) chọc ghẹo kẻ ngốc — đó là nghệ thuật trào phúng bằng ngôn từ. | Gương Hán-Việt | trào — xuất hiện trong 嘲諷/謿諷 (trào phúng: chế giễu, châm biếm). | Mở khoá kiến thức | Biết 謿/嘲 mở khoá các từ về châm biếm: 嘲笑 (trào tiếu: chế nhạo), 嘲諷 (trào phúng: châm biếm).", "Tự nguyên_Xie": "Chữ hình thanh: 言 (ngôn) biểu nghĩa chỉ lời nói; 朝 (triều) biểu âm cho âm cháo. Wiktionary ghi 謿 là dị thể phồn thể của 嘲 (trào: trêu chọc, chế nhạo). Nghĩa gốc là dùng lời lẽ chế giễu, trào phúng. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trào; như \"trào phúng\" (gdhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 朝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言朝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "朝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "謿", "Unihan_Traditional (Chữ Phồn thể)": "謿", "Pinyin_Xie": "cháo", "Âm Hán Việt_Xie": "trào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ để biểu thị hành vi chế giễu hoặc đùa cợt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('陧', '{"9000": "6820.0", "Chữ Trung Quốc": "陧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 9 | nét | 陧 | niết | tượng hình | không ổn định, bất an (dùng trong 杌隉) | 陧 thuộc bộ 阜/阝 (phụ: gò đất) — chỉ địa hình hoặc trạng thái không ổn định. Cấu tạo nội bộ chi tiết chưa được Wiktionary phân tích đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"niết\" (niè): đất (阝) rung chuyển như bị niết chặt — 杌陧 (兀陧) diễn tả thế giới bất ổn, không chỗ bám víu. | Gương Hán-Việt | niết — xuất hiện trong cụm 杌陧/杌隉 (兀陧: bất ổn) trong văn ngôn. | Mở khoá kiến thức | Biết 陧 giúp đọc thành ngữ 杌陧 (niết: tình trạng bất ổn, xã hội loạn lạc) trong văn học cổ điển.", "Tự nguyên_Xie": "Chữ thuộc bộ 阜/阝 (phụ: gò đất cao), dùng chủ yếu trong thành ngữ 杌隉 (兀陧/阢隉: bất ổn, lung lay). Wiktionary ghi âm niè, dùng trong cụm 杌隉, 阢隉. Chưa có phân tích glyph-origin chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: ngột niết 杌隉,杌陧)", "Hạng Tần Suất (Jun Da)": "6820.0", "Tần Suất % (Jun Da)": "99.9960233384", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + 圼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝圼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "圼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "陧", "Unihan_Traditional (Chữ Phồn thể)": "隉", "Pinyin_Xie": "niè", "Âm Hán Việt_Xie": "niết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ trong từ ghép để miêu tả trạng thái lung lay, bất ổn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('坜', '{"9000": "6821.0", "Chữ Trung Quốc": "坜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 7 | nét | 坜 | lịch | tượng hình | hố đất, lỗ trũng | 坜 thuộc bộ 土 (thổ: đất) — chỉ đặc điểm địa hình đất. Cấu tạo nội bộ chi tiết chưa được Wiktionary phân tích; không có mục glyph-origin.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lịch\" (lì): đất (土) lõm xuống thành hố — 坜 là chỗ trũng, lỗ hổng trên mặt đất. | Gương Hán-Việt | lịch — xuất hiện trong địa danh 中壢 (Zhōnglì: Trung Lịch, thành phố Đài Loan). | Mở khoá kiến thức | Biết 坜 giúp đọc địa danh 中壢 (Trung Lịch) và các tên đất miền nông thôn Đài Loan.", "Tự nguyên_Xie": "Chữ thuộc bộ 土 (thổ: đất), chỉ hố đất, lỗ trũng. Không có mục phân tích glyph-origin; chưa có nguồn học thuật. Xuất hiện trong địa danh như 中壢 (Trung Lịch, Đài Loan). | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hố, lỗ", "Hạng Tần Suất (Jun Da)": "6821.0", "Tần Suất % (Jun Da)": "99.9960279895", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 历", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土历", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "历", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "坜", "Unihan_Traditional (Chữ Phồn thể)": "壢", "Pinyin_Xie": "lì", "Âm Hán Việt_Xie": "lịch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ các hố hoặc rãnh nước nhỏ trên mặt đất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('坫', '{"9000": "6822.0", "Chữ Trung Quốc": "坫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 8 | nét | 坫 | điếm | tượng hình | bệ để đặt chén sau khi uống rượu; góc nhà | 坫 thuộc bộ 土 (thổ: đất/vật liệu xây dựng) — chỉ đồ vật hoặc cấu trúc bằng đất nung. Cấu tạo nội bộ chưa được Wiktionary phân tích đầy đủ (có hai âm đọc: diàn và zhēn).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điếm\" (diàn): bệ đất (土) nơi đặt chén sau điếm (yến tiệc) — 坫 là vật không thể thiếu trong lễ uống rượu của quý tộc cổ đại. | Gương Hán-Việt | điếm — xuất hiện trong cụm 壇坫 (đàn điếm: bàn thờ và bệ lễ nghi), 反坫 (phản điếm: bệ để trả chén). | Mở khoá kiến thức | Biết 坫 giúp đọc các ghi chép lễ nghi trong Luận Ngữ và văn cổ Trung Hoa.", "Tự nguyên_Xie": "Chữ thuộc bộ 土 (thổ), chỉ bệ đất nung để đặt chén sau khi uống trong nghi lễ cổ đại Trung Quốc; cũng có nghĩa là góc nhà (corner of a room). Có hai âm đọc: diàn (bệ lễ nghi) và zhēn (nghĩa lễ nghi khác). Chưa có phân tích glyph-origin chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái bục, cái bệ; góc nhà", "Hạng Tần Suất (Jun Da)": "6822.0", "Tần Suất % (Jun Da)": "99.9960326405", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 占", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土占", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "占", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "坫", "Unihan_Traditional (Chữ Phồn thể)": "坫", "Pinyin_Xie": "diàn", "Âm Hán Việt_Xie": "điếm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ cái bệ để đồ vật thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('甍', '{"9000": "6823.0", "Chữ Trung Quốc": "甍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 瓦 | Số nét | 14 | nét | 夢 | mộng | biểu âm | 瓦 | ngoã | biểu nghĩa | ngói mái | 甍 = 夢 (Mộng, biểu âm, viết tắt) + 瓦 (Ngoã, biểu nghĩa: ngói); chữ hình thanh — 瓦 chỉ ngói mái nhà, 夢 (rút gọn) cho âm méng/mành.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mành\" (méng): ngói (瓦) trên mái nhà nằm mộng (夢) dưới ánh trăng — 甍 là thanh rui nơi hàng ngói tựa vào. | Gương Hán-Việt | mành — xuất hiện trong thơ cổ: 碧瓦朱甍 (ngói lam mái son), 層甍 (tầng mành: mái nhà tầng). | Mở khoá kiến thức | Biết 甍 mở khoá hình ảnh kiến trúc cổ điển trong thơ ca Đường-Tống: 碧瓦朱甍, 層甍, 飛甍.", "Tự nguyên_Xie": "Chữ hình thanh: 瓦 (ngoã) biểu nghĩa chỉ ngói mái nhà; 夢 (mộng, viết tắt) biểu âm cho âm méng. Wiktionary ghi: {{Han compound|夢|瓦|c1=p|c2=s|t2=roof tile|ls=psc|abb1=y}}. Nghĩa gốc là xà nóc, rui nhà nơi móc ngói. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái rui (đóng trên mái nhà để móc ngói vào)", "Hạng Tần Suất (Jun Da)": "6823.0", "Tần Suất % (Jun Da)": "99.9960372916", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "甍", "Unihan_Traditional (Chữ Phồn thể)": "甍", "Pinyin_Xie": "méng", "Âm Hán Việt_Xie": "manh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn học cổ để chỉ mái nhà ngói. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('绠', '{"9000": "6824.0", "Chữ Trung Quốc": "绠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 10 | nét | 绠 | ngạnh | tượng hình | dây kéo nước từ giếng | 绠 thuộc bộ 糸/纟 (mịch/tơ: sợi dây) — chỉ vật dụng làm từ sợi/dây thừng. Cấu tạo nội bộ chi tiết chưa được Wiktionary phân tích đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngạnh\" (gěng): sợi dây (糸) cứng ngạnh — dây gàu giếng phải đủ dài mới múc được nước sâu. | Gương Hán-Việt | ngạnh — hầu như không xuất hiện trong từ Hán-Việt thông dụng; chủ yếu trong câu trích dẫn Tuân Tử. | Mở khoá kiến thức | Biết 绠 giúp hiểu thành ngữ 短綆汲深 (ngạnh đoản cấp thâm: năng lực có hạn, không kham việc lớn).", "Tự nguyên_Xie": "Chữ thuộc bộ 糸 (mịch: sợi tơ), chỉ dây thừng dùng để thả gàu múc nước giếng. Câu thành ngữ nổi tiếng: 短綆不可以汲深井之泉 (dây ngắn không thể múc nước giếng sâu — người học hẹp không thể hiểu lời thánh hiền, Tuân Tử). Chưa có phân tích glyph-origin chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dây kéo nước, dây gầu múc nước", "Hạng Tần Suất (Jun Da)": "6824.0", "Tần Suất % (Jun Da)": "99.9960419427", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 更", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟更", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "更", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "绠", "Unihan_Traditional (Chữ Phồn thể)": "綆", "Pinyin_Xie": "gěng", "Âm Hán Việt_Xie": "cảnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ sợi dây thừng dùng để múc nước giếng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('恝', '{"9000": "6825.0", "Chữ Trung Quốc": "恝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 10 | nét | 恝 | giới | tượng hình | quên bẵng, không để tâm | 恝 thuộc bộ 心/忄 (tâm: lòng) — chỉ trạng thái tâm lý. Cấu tạo nội bộ chi tiết không có trong Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giới\" (jiá): tâm trí (心) không còn giới (coi trọng) — 恝 là thái độ hờ hững, quên đi như không có gì xảy ra. | Gương Hán-Việt | giới — hầu như không xuất hiện trong từ Hán-Việt thông dụng; chữ văn ngôn hiếm. | Mở khoá kiến thức | Biết 恝 giúp đọc văn cổ Trung Hoa về thái độ hờ hững, vô tâm trong mối quan hệ con người.", "Tự nguyên_Xie": "Chữ thuộc bộ 心 (tâm: lòng), chỉ trạng thái quên bẵng, không để tâm, hờ hững. Không có mục phân tích glyph-origin; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quên bẵng đi", "Hạng Tần Suất (Jun Da)": "6825.0", "Tần Suất % (Jun Da)": "99.9960465937", "GavinGrover_Once (Chiết tự trực tiếp)": "㓞 + 心", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱㓞心", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㓞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "心", "Unihan_Simplified (Chữ Giản thể)": "恝", "Unihan_Traditional (Chữ Phồn thể)": "恝", "Pinyin_Xie": "jiá", "Âm Hán Việt_Xie": "kiết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ để miêu tả thái độ hờ hững, không quan tâm. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('飗', '{"9000": "6826.0", "Chữ Trung Quốc": "飗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 風 | Số nét | 14 | nét | 飗 | lưu | tượng hình | gió thổi vi vu; biến thể giản của 飀 | 飗 là giản thể của 飀 — bộ 风(phong, giản) thay cho 風(phong, phồn). Chỉ âm thanh gió thổi. Cấu tạo chi tiết theo dạng phồn thể 飀 chưa được phân tích đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lưu\" (liú): gió (风) lưu (liú — chảy) — 飗 là tiếng gió lưu chuyển vi vu, thổi mãi không ngừng. | Gương Hán-Việt | lưu — xuất hiện trong cụm 颼飀/颼飗 (sưu lưu: tiếng gió thổi mạnh) trong thơ ca cổ điển. | Mở khoá kiến thức | Biết 飗/飀 giúp đọc các mô tả gió trong thơ Đường và văn xuôi cổ điển Trung Hoa.", "Tự nguyên_Xie": "飗 là giản thể của 飀, Wiktionary ghi: {{Han simp|飀|f=風|t=风}}. Chỉ tiếng gió thổi vi vu (颼飀: âm thanh gió). Dùng trong tổ hợp 颼飀 (sưu lưu) để mô tả gió mạnh thổi vù vù. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: sưu lưu 颼飀)", "Hạng Tần Suất (Jun Da)": "6826.0", "Tần Suất % (Jun Da)": "99.9960512448", "GavinGrover_Once (Chiết tự trực tiếp)": "风 + 留", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴风留", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "留", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "风", "Unihan_Simplified (Chữ Giản thể)": "飗", "Unihan_Traditional (Chữ Phồn thể)": "飀", "Pinyin_Xie": "liú", "Âm Hán Việt_Xie": "lưu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Danh từ | 名词 | Thường kết hợp thành từ láy để mô tả âm thanh gió thổi. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镙', '{"9000": "6827.0", "Chữ Trung Quốc": "镙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 16 | nét | 镙 | la | tượng hình | (nghĩa không rõ — bộ kim loại) | 镙 thuộc bộ 钅(kim, giản: kim loại) — chỉ liên quan đến kim loại. Cấu tạo nội bộ chi tiết không có trong Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"la\" (luó): kim loại (钅) hình xoắn ốc như con ốc (la) — 镙 có thể liên quan đến đồ vật kim loại dạng xoắn. | Gương Hán-Việt | la — không xuất hiện trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 镙 giúp nhận ra chữ bộ 钅 ít gặp trong danh mục công cụ kim loại cổ.", "Tự nguyên_Xie": "Chữ thuộc bộ 钅(kim: kim loại). Không có mục phân tích glyph-origin trên Wiktionary; nghĩa và nguồn gốc chưa được làm rõ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "镙", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 累", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅累", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "累", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镙", "Unihan_Traditional (Chữ Phồn thể)": "镙", "Pinyin_Xie": "luó", "Âm Hán Việt_Xie": "la", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ để chỉ các loại ốc vít hoặc ren vặn trong cơ khí. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镱', '{"9000": "6828.0", "Chữ Trung Quốc": "镱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 18 | nét | 金 | kim | biểu nghĩa | kim loại | 意 | ý | biểu âm | 镱 = 钅(Kim, biểu nghĩa: kim loại) + 意 (Ý, biểu âm); chữ hình thanh — bộ 钅chỉ nguyên tố kim loại, 意 cho âm yì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ý\" (yì): kim loại (钅) mang ý (意) nghĩa khoa học — 镱 là tên Hán hóa của nguyên tố Ytterbium, ký hiệu Yb. | Gương Hán-Việt | ý — đồng âm với 意 (ý nghĩa), nhưng 镱 chỉ riêng nguyên tố hóa học Yb. | Mở khoá kiến thức | Biết 镱 giúp đọc bảng tuần hoàn bằng chữ Hán và tài liệu hóa học Trung Quốc.", "Tự nguyên_Xie": "Chữ hình thanh: 钅(kim) biểu nghĩa chỉ nguyên tố kim loại; 意 (ý) biểu âm cho âm yì. Wiktionary ghi: {{Han compound|金|意|c1=s|t1=metal|c2=p|ls=psc}}. Chữ được tạo ra để phiên âm tên nguyên tố Ytterbium (Yb, số hiệu 70) sang chữ Hán. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố ytebi, Yb", "Hạng Tần Suất (Jun Da)": "6828.0", "Tần Suất % (Jun Da)": "99.9960605469", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 意", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅意", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "意", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镱", "Unihan_Traditional (Chữ Phồn thể)": "鐿", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "ý", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ nguyên tố hóa học kim loại chuyển tiếp Ytecbi trong bảng tuần hoàn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('魋', '{"9000": "6829.0", "Chữ Trung Quốc": "魋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鬼 | Số nét | 17 | nét | 鬼 | quỷ | biểu nghĩa | hồn ma, dáng đáng sợ | 隹 | chuy | biểu âm | 魋 = 鬼 (Quỷ, biểu nghĩa: hình dáng đáng sợ/siêu nhiên) + 隹 (Chuy, biểu âm); chữ hình thanh — bộ 鬼 chỉ loài thú hình dạng kỳ dị, 隹 cho âm tuí.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đồi\" (tuí): loài thú (鬼 — dáng đáng sợ) giống gấu nhỏ — 魋 là thú rừng bí ẩn trong sách cổ, lông đỏ như ma quỷ xuất hiện. | Gương Hán-Việt | đồi — xuất hiện trong cụm 魋結 (đồi kết: búi tóc hình dùi cui) và tên họ. | Mở khoá kiến thức | Biết 魋 giúp đọc mô tả loài thú huyền bí trong bách khoa thư cổ Trung Hoa và thành ngữ 魋結.", "Tự nguyên_Xie": "Chữ hình thanh: 鬼 (quỷ) biểu nghĩa chỉ dáng vẻ đáng sợ, kỳ dị; 隹 (chuy) biểu âm cho âm tuí. Wiktionary ghi: {{Han compound|鬼|隹|ls=psc|c1=s|c2=p|t1=ghost}}. Nghĩa gốc là loài thú giống gấu nâu nhỏ, lông ngắn màu đỏ vàng (văn cổ: 魋，如小熊而赤). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một giống thú ở rừng", "Hạng Tần Suất (Jun Da)": "6829.0", "Tần Suất % (Jun Da)": "99.9960698491", "GavinGrover_Once (Chiết tự trực tiếp)": "鬼 + 隹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴鬼隹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "隹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鬼", "Unihan_Simplified (Chữ Giản thể)": "魋", "Unihan_Traditional (Chữ Phồn thể)": "魋", "Pinyin_Xie": "tuí", "Âm Hán Việt_Xie": "đồi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài thú hoang dã thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('硱', '{"9000": "6830.0", "Chữ Trung Quốc": "硱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 12 | nét | 硱 | khổn | tượng hình | (nghĩa chưa xác định — bộ đá) | 硱 thuộc bộ 石 (thạch: đá) — chỉ liên quan đến đá hoặc vật liệu cứng. Wiktionary chỉ ghi {{rfdef|zh}} — nghĩa chưa được xác định chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khổn\" (kǔn): đá (石) vây bủa khổn (困) cứng ngắc — 硱 là chữ đá bí ẩn ngay cả học giả chưa xác định được nghĩa. | Gương Hán-Việt | khổn — không xuất hiện trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 硱 là ví dụ điển hình về các chữ Hán có bộ 石 chưa được định nghĩa đầy đủ trong từ điển hiện đại.", "Tự nguyên_Xie": "Chữ thuộc bộ 石 (thạch: đá), nhưng Wiktionary ghi {{rfdef|zh}} — nghĩa chưa được xác định. Chữ văn ngôn cực hiếm, chưa có phân tích glyph-origin; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "硱", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 困", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石困", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "困", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "硱", "Unihan_Traditional (Chữ Phồn thể)": "硱", "Pinyin_Xie": "kǔn", "Âm Hán Việt_Xie": "khổn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này chủ yếu dùng làm danh từ chỉ đá cứng hoặc tính từ miêu tả độ cứng của đá. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('祫', '{"9000": "6831.0", "Chữ Trung Quốc": "祫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 10 | nét | 祫 | hiệp | tượng hình | tế lễ chung hợp tổ tiên nhiều đời | 祫 thuộc bộ 示 (kỳ: thần linh, lễ nghi) — chỉ nghi lễ tế tự. Cấu tạo nội bộ chi tiết chưa được Wiktionary phân tích đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hiệp\" (xiá): thần (示) hợp hiệp — 祫 là lễ tế gộp tất cả tổ tiên lại một buổi, tưởng nhớ muôn đời. | Gương Hán-Việt | hiệp — xuất hiện trong 祫祭 (hiệp tế: đại lễ hợp tế tổ tiên). | Mở khoá kiến thức | Biết 祫 giúp đọc các ghi chép về nghi lễ tế tự trong Kinh Lễ và văn cổ Nho giáo.", "Tự nguyên_Xie": "Chữ thuộc bộ 示 (kỳ: thần linh, lễ tế), chỉ lễ hợp tế (祫祭) — tế lễ chung hợp tất cả bài vị tổ tiên từ xa xưa lại thờ cùng một lần. Là nghi lễ quan trọng trong Nho giáo cổ đại. Chưa có phân tích glyph-origin chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ông tổ đã chết lâu năm", "Hạng Tần Suất (Jun Da)": "6831.0", "Tần Suất % (Jun Da)": "99.9960791512", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 合", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻合", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "合", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "祫", "Unihan_Traditional (Chữ Phồn thể)": "祫", "Pinyin_Xie": "xiá", "Âm Hán Việt_Xie": "hợp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ nghi lễ cúng tế chung hoặc động từ thực hiện nghi lễ đó. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('箖', '{"9000": "6832.0", "Chữ Trung Quốc": "箖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 14 | nét | 箖 | lâm | tượng hình | loại tre/trúc cổ đại (đã lỗi thời) | 箖 thuộc bộ 竹 (trúc: tre) — chỉ loại cây họ tre. Cấu tạo nội bộ chi tiết chưa được Wiktionary phân tích đầy đủ; được ghi là lỗi thời (obsolete).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lâm\" (lín): rừng tre (竹+lâm) — 箖 là tên một loài tre cổ, nay không còn dùng trong văn nói. | Gương Hán-Việt | lâm — không xuất hiện trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 箖 giúp nhận ra các chữ bộ 竹 hiếm gặp trong danh mục thực vật học cổ điển Trung Hoa.", "Tự nguyên_Xie": "Chữ thuộc bộ 竹 (trúc: tre), chỉ một loại tre/trúc đã lỗi thời trong văn cổ. Wiktionary ghi {{lb|zh|obsolete}}. Không có phân tích glyph-origin; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rổ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 林", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮林", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "林", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "箖", "Unihan_Traditional (Chữ Phồn thể)": "箖", "Pinyin_Xie": "lín", "Âm Hán Việt_Xie": "lâm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại tre đặc biệt hoặc dụng cụ làm từ tre. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('袧', '{"9000": "6833.0", "Chữ Trung Quốc": "袧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 10 | nét | 衤 | y | biểu nghĩa | áo, trang phục | 句 | câu | biểu âm | 袧 = 衤(Y, biểu nghĩa: áo/quần áo) + 句 (Câu, biểu âm); chữ hình thanh — bộ 衤chỉ trang phục, 句 cho âm kōu/câu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"câu\" (kōu): áo (衤) với những câu (句) thêu — 袧 gợi lên hình ảnh trang phục trang trí câu chữ thời cổ. | Gương Hán-Việt | câu — không xuất hiện trong từ Hán-Việt thông dụng; chữ hiếm. | Mở khoá kiến thức | Biết 袧 giúp nhận ra cấu tạo hình thanh của các chữ trang phục bộ 衤 trong từ điển chữ Hán cổ.", "Tự nguyên_Xie": "Chữ hình thanh: 衤(y/y bàng: áo) biểu nghĩa chỉ trang phục; 句 (câu) biểu âm cho âm kōu. Wiktionary ghi: {{Han compound|衣|alt1=衤|句|ls=psc|c1=s|c2=p}}. Nghĩa cụ thể chưa được định nghĩa rõ (rfdef). | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "觧", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 句", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤句", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "句", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "袧", "Unihan_Traditional (Chữ Phồn thể)": "袧", "Pinyin_Xie": "gōu", "Âm Hán Việt_Xie": "câu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một bộ phận hoặc chi tiết trên trang phục cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('迯', '{"9000": "6834.0", "Chữ Trung Quốc": "迯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 8 | nét | 迯 | đào | tượng hình | chạy trốn, đào thoát (dị thể cổ của 逃) | 迯 là dị thể cổ của 逃 — bộ 辶(sước: đi đường) chỉ hành động di chuyển. Cấu tạo chi tiết không có trong Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đào\" (táo): chạy trốn (辶) — 迯 là dạng cổ của 逃, chữ đào tẩu, đào ngũ quen thuộc. | Gương Hán-Việt | đào — xuất hiện trong 逃跑 (đào bào: chạy trốn), 逃避 (đào tị: trốn tránh), 出逃 (xuất đào: bỏ trốn). | Mở khoá kiến thức | Biết 迯 là dạng cổ của 逃 giúp đọc văn bản cổ và hiểu nguồn gốc từ 逃/đào trong tiếng Việt gốc Hán.", "Tự nguyên_Xie": "迯 là dị thể cổ của 逃 (đào: chạy trốn). Không có phân tích glyph-origin trên Wiktionary; chưa có nguồn học thuật. Bộ 辶 (sước) biểu nghĩa chỉ hành động đi/chạy. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đào; như \"đào ngũ; đào tẩu\" (gdhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 外", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶外", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "外", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "迯", "Unihan_Traditional (Chữ Phồn thể)": "迯", "Pinyin_Xie": "táo", "Âm Hán Việt_Xie": "đào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành vi bỏ trốn, là dạng viết khác của chữ đào. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('郙', '{"9000": "6835.0", "Chữ Trung Quốc": "郙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 9 | nét | 郙 | phủ | tượng hình | địa danh cổ | 郙 thuộc bộ 阝(ấp, phải: địa danh/chư hầu) — chỉ vùng đất cổ. Cấu tạo nội bộ chi tiết chưa được Wiktionary phân tích; ghi rfdef.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phủ\" (fǔ): vùng đất (阝) của phủ (府: nơi cai quản) — 郙 là địa danh cổ mang dấu ấn hành chính thời xưa. | Gương Hán-Việt | phủ — đồng âm với 府 (phủ: dinh thự, địa phương), nhưng 郙 chỉ riêng địa danh cổ này. | Mở khoá kiến thức | Biết 郙 giúp đọc sử liệu địa lý cổ Trung Quốc; bộ 阝(phải) thường báo hiệu địa danh.", "Tự nguyên_Xie": "Chữ thuộc bộ 阝(phải: ấp/nước nhỏ), chỉ địa danh cổ. Wiktionary chỉ ghi {{rfdef|zh}} — nghĩa chưa xác định rõ ngoài việc là một địa danh. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "địa danh cổ", "Hạng Tần Suất (Jun Da)": "6835.0", "Tần Suất % (Jun Da)": "99.9961024065", "GavinGrover_Once (Chiết tự trực tiếp)": "甫 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰甫阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "郙", "Unihan_Traditional (Chữ Phồn thể)": "郙", "Pinyin_Xie": "fǔ", "Âm Hán Việt_Xie": "phủ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ riêng chỉ địa danh cổ, thường xuất hiện trong thư tịch cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('酖', '{"9000": "6836.0", "Chữ Trung Quốc": "酖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 11 | nét | 酖 | đam | tượng hình | mê đắm rượu; đắm chìm trong khoái lạc | 酖 thuộc bộ 酉 (dậu: rượu/bình rượu) — chỉ hành động liên quan đến rượu chè, sa đà. Cấu tạo nội bộ chi tiết chưa được Wiktionary phân tích đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đam\" (zhèn): bình rượu (酉) mà người ta đam mê — 酖 là trạng thái đắm chìm không thoát ra được. | Gương Hán-Việt | đam — xuất hiện trong 酖酒 (đam tửu: mê rượu), đồng nghĩa với 耽 trong nhiều văn bản. | Mở khoá kiến thức | Biết 酖 giúp hiểu các từ về sự sa đà, đam mê thái quá trong văn cổ Trung Hoa.", "Tự nguyên_Xie": "Chữ thuộc bộ 酉 (dậu: rượu), chỉ sự mê đắm rượu chè, sa đà vào khoái lạc. Wiktionary chỉ ghi nghĩa ngắn. Đồng âm và đồng nghĩa với 耽 (đam: mê đắm). Chưa có phân tích glyph-origin chi tiết; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mê rượu, ham rượu", "Hạng Tần Suất (Jun Da)": "6836.0", "Tần Suất % (Jun Da)": "99.9961070576", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 冘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉冘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "酖", "Unihan_Traditional (Chữ Phồn thể)": "酖", "Pinyin_Xie": "zhèn", "Âm Hán Việt_Xie": "đam, chậm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này làm động từ chỉ sự say mê quá độ hoặc tính từ miêu tả trạng thái nghiện ngập. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('遘', '{"9000": "6837.0", "Chữ Trung Quốc": "遘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 13 | nét | 辶 | sước | biểu nghĩa | đi đường | 冓 | cấu | biểu âm | 遘 = 辶(Sước, biểu nghĩa: đi đường) + 冓 (Cấu, biểu âm); chữ hình thanh — bộ 辶 chỉ hành động di chuyển/gặp gỡ trên đường, 冓 cho âm gòu/cấu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cấu\" (gòu): đang đi (辶) mà gặp cấu (冓 — xây gặp nhau) — 遘 là cuộc gặp gỡ bất ngờ không hẹn trước. | Gương Hán-Việt | cấu — xuất hiện trong 遘難 (cấu nạn: gặp tai nạn), 遘遇 (cấu ngộ: tình cờ gặp). | Mở khoá kiến thức | Biết 遘 giúp đọc các đoạn thơ văn cổ về những cuộc gặp gỡ định mệnh trong thơ Đường và văn Hán cổ.", "Tự nguyên_Xie": "Chữ hình thanh: 辵 (sước, viết tắt là 辶) biểu nghĩa chỉ việc đi đường; 冓 (cấu) biểu âm cho âm gòu. Wiktionary ghi: {{Han compound|辵|alt1=辶|冓|c1=s|c2=p|t1=walk|ls=psc}}. Nghĩa gốc là tình cờ gặp gỡ, không hẹn mà gặp. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "không hẹn mà gặp", "Hạng Tần Suất (Jun Da)": "6837.0", "Tần Suất % (Jun Da)": "99.9961117086", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 冓", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶冓", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冓", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "遘", "Unihan_Traditional (Chữ Phồn thể)": "遘", "Pinyin_Xie": "gòu", "Âm Hán Việt_Xie": "cấu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong văn ngôn để chỉ việc tình cờ gặp mặt hoặc gặp phải tai ương. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('阘', '{"9000": "6838.0", "Chữ Trung Quốc": "阘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 13 | nét | 阘 | tháp | tượng hình | cửa nhỏ trên gác; thấp kém, hèn hạ | 阘 thuộc bộ 門 (môn: cửa) — chỉ loại cửa hoặc tính chất hèn kém. Cấu tạo nội bộ chi tiết chưa được Wiktionary phân tích đầy đủ (đọc tà theo văn cổ).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tháp\" (tà): cửa (門) nhỏ trên gác tháp — 阘 gợi lên cửa hẹp dẫn vào không gian tối tăm, hay được dùng ám chỉ người hèn kém. | Gương Hán-Việt | tháp — xuất hiện trong 闒茸 (tháp nhung: kẻ hèn kém, tiểu nhân vô dụng). | Mở khoá kiến thức | Biết 阘 giúp đọc thành ngữ 闒茸 (tháp nhung) dùng trong văn cổ để chê bai kẻ bất tài.", "Tự nguyên_Xie": "Chữ thuộc bộ 門 (môn: cửa), chỉ cửa nhỏ ở tầng trên. Wiktionary ghi {{lb|zh|archaic}} small door located on an upper story. Cũng dùng trong cụm 闒茸 (tháp nhung: kẻ hèn kém, vô dụng). Chưa có phân tích glyph-origin chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cửa trên gác (tầng trên); tiếng chuông trống; thấp kém, hèn hạ", "Hạng Tần Suất (Jun Da)": "6838.0", "Tần Suất % (Jun Da)": "99.9961163597", "GavinGrover_Once (Chiết tự trực tiếp)": "门 + 𦐇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴门𦐇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𦐇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "门", "Unihan_Simplified (Chữ Giản thể)": "阘", "Unihan_Traditional (Chữ Phồn thể)": "闒", "Pinyin_Xie": "dá", "Âm Hán Việt_Xie": "tháp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ để mô tả tính cách hèn kém hoặc làm danh từ chỉ cửa nhỏ trên lầu. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('眭', '{"9000": "6839.0", "Chữ Trung Quốc": "眭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 11 | nét | 目 | mục | biểu nghĩa | mắt | 圭 | quê | biểu âm | 眭 = 目 (Mục, biểu nghĩa: mắt) + 圭 (Quê, biểu âm); chữ hình thanh — bộ 目 chỉ liên quan đến mắt/hốc mắt, 圭 cho âm suī/huy.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huy\" (suī): mắt (目) sâu như quê (圭: viên ngọc hình nhọn) — 眭 gợi lên đôi mắt sâu thẳm, hốc mắt lõm vào. | Gương Hán-Việt | huy — đồng âm với 輝 (huy: rực rỡ), 揮 (huy: vẫy tay); nhưng 眭 chỉ riêng hốc mắt sâu và họ người. | Mở khoá kiến thức | Biết 眭 giúp nhận ra tên họ và các từ mô tả mắt trong văn học Trung Hoa cổ điển.", "Tự nguyên_Xie": "Chữ hình thanh: 目 (mục) biểu nghĩa chỉ mắt; 圭 (quê) biểu âm cho âm suī. Wiktionary ghi: {{Han compound|目|圭|c1=s|c2=p|t1=eye|ls=psc}}. Nghĩa gốc là hốc mắt sâu; cũng là họ người (họ Tuy/Huy). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ổ mắt sâu; họ Tuy", "Hạng Tần Suất (Jun Da)": "6839.0", "Tần Suất % (Jun Da)": "99.9961210108", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 圭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目圭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "圭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "眭", "Unihan_Traditional (Chữ Phồn thể)": "眭", "Pinyin_Xie": "suī", "Âm Hán Việt_Xie": "tuy, khôi, huề", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ họ người hoặc làm động từ mô tả ánh mắt nhìn giận dữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('餗', '{"9000": "6840.0", "Chữ Trung Quốc": "餗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 15 | nét | 餗 | túc | tượng hình | thức ăn trong đỉnh (nồi lễ nghi); đồ ăn ngon | 餗 thuộc bộ 食/飠 (thực: ăn uống/đồ ăn) — chỉ thức ăn. Cấu tạo nội bộ chi tiết chưa được Wiktionary phân tích đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"túc\" (sù): thức ăn (食) trong đỉnh lễ nghi — 折鼎覆餗 là khi người bất tài đảm nhiệm trọng trách, làm đổ cả nồi. | Gương Hán-Việt | túc — xuất hiện trong thành ngữ 折鼎覆餗 (chiết đỉnh phúc túc: gãy đỉnh đổ thức ăn — bất tài làm hỏng việc). | Mở khoá kiến thức | Biết 餗 giúp hiểu thành ngữ 折鼎覆餗 — cảnh báo về việc giao trọng trách cho người không đủ sức.", "Tự nguyên_Xie": "Chữ thuộc bộ 食 (thực: ăn), chỉ đồ ăn nấu chín bên trong đỉnh — loại nồi đồng lễ nghi cổ đại. Nổi tiếng qua thành ngữ 折鼎覆餗 (gãy chân đỉnh đổ thức ăn — ám chỉ thất bại vì thiếu năng lực). Chưa có phân tích glyph-origin chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nồi cơm chín", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "飠 + 束", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰飠束", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "束", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "飠", "Unihan_Simplified (Chữ Giản thể)": "𫗧", "Unihan_Traditional (Chữ Phồn thể)": "餗", "Pinyin_Xie": "sù", "Âm Hán Việt_Xie": "tốc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau động từ để chỉ thức ăn nấu trong vạc thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('耖', '{"9000": "6841.0", "Chữ Trung Quốc": "耖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 耒 | Số nét | 10 | nét | 耖 | sào | tượng hình | cào bừa; dụng cụ làm đất sau khi bừa | 耖 thuộc bộ 耒 (lỗi: cày bừa) — chỉ nông cụ. Cấu tạo nội bộ chi tiết chưa được Wiktionary phân tích đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sào\" (chào): cây sào (耒: cày) kéo qua ruộng lần cuối — 耖 là bước bừa kỹ cuối cùng trước khi gieo mạ. | Gương Hán-Việt | sào — không xuất hiện trong từ Hán-Việt thông dụng; chữ nông nghiệp chuyên biệt. | Mở khoá kiến thức | Biết 耖 giúp đọc văn bản nông nghiệp cổ điển Trung Hoa về kỹ thuật làm đất lúa nước.", "Tự nguyên_Xie": "Chữ thuộc bộ 耒 (lỗi: cày bừa cổ), chỉ công cụ giống bừa dùng để vỡ thêm đất ruộng sau lần bừa đầu, hoặc hành động dùng dụng cụ này. Đây là chữ nông nghiệp đặc thù trong văn hóa lúa nước. Chưa có phân tích glyph-origin; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái bừa; bừa đất", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "耒 + 少", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰耒少", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "少", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "耒", "Unihan_Simplified (Chữ Giản thể)": "耖", "Unihan_Traditional (Chữ Phồn thể)": "耖", "Pinyin_Xie": "chào", "Âm Hán Việt_Xie": "sáo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ đứng sau danh từ chỉ công cụ để mô tả hoạt động làm đất. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鯒', '{"9000": "6842.0", "Chữ Trung Quốc": "鯒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 18 | nét | 鯒 | dũng | tượng hình | Palladium; loài cá dẹt đáy biển | 鯒 thuộc bộ 魚 (ngư: cá) — chỉ loài cá. Cấu tạo nội bộ chi tiết không có trong Wiktionary; không có mục glyph-origin.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dũng\" (yǒng): con cá (魚) nằm dũng (yǒng: nằm im) dưới đáy — 鯒 là loài cá đầu phẳng nằm bất động dưới cát biển. | Gương Hán-Việt | dũng — không xuất hiện trong từ Hán-Việt thông dụng; chủ yếu dùng trong danh pháp sinh học. | Mở khoá kiến thức | Biết 鯒 giúp nhận ra tên loài cá đáy biển trong sách sinh học và ẩm thực hải sản Nhật-Trung.", "Tự nguyên_Xie": "Chữ thuộc bộ 魚 (ngư: cá). Không có mục phân tích glyph-origin trên Wiktionary; chưa có nguồn học thuật. Có thể chỉ loài cá dẹt đáy biển họ Platycephalidae (cá đầu phẳng). Anchor ghi nghĩa là Palladium — có thể là mục nhầm; nghĩa cá đáy biển xác thực hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Palladium", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 甬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚甬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鯒", "Unihan_Traditional (Chữ Phồn thể)": "鯒", "Pinyin_Xie": "yǒng", "Âm Hán Việt_Xie": "dũng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ đứng sau lượng từ để chỉ một loài cá biển có đầu dẹt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('邶', '{"9000": "6843.0", "Chữ Trung Quốc": "邶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 7 | nét | 邶 | bội | tượng hình | tên nước chư hầu cổ đại ở vùng Hà Nam | 邶 là địa danh, không phân tích thành các bộ phận có nghĩa thông thường. Bộ 邑 (ấp) gợi ý tính chất địa phương/quốc gia; chữ này dùng như tên riêng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Bội\": tên nước cổ thời Tây Chu, xuất hiện trong Kinh Thi thiên Bội Phong (邶風) — nhớ như vùng đất gắn với thơ ca bi tráng thời Chu. | Gương Hán-Việt | Bội phong (邶風) — tên thiên thơ trong Kinh Thi | Mở khoá kiến thức | Biết 邶 giúp đọc hiểu các tên địa danh cổ trong kinh điển Nho học, đặc biệt Kinh Thi.", "Tự nguyên_Xie": "邶 là tên nước chư hầu cổ đại dưới triều Chu, nằm ở phía nam Thang Âm (Tangyin), tỉnh Hà Nam ngày nay. Wiktionary không ghi rõ cấu trúc hình-thanh; chữ có thể liên quan bộ 邑 (ấp, đất phong). Chưa có nguồn học thuật xác nhận cấu trúc nội tại. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước Bội", "Hạng Tần Suất (Jun Da)": "6843.0", "Tần Suất % (Jun Da)": "99.996139615", "GavinGrover_Once (Chiết tự trực tiếp)": "北 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰北阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "北", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "邶", "Unihan_Traditional (Chữ Phồn thể)": "邶", "Pinyin_Xie": "bèi", "Âm Hán Việt_Xie": "bắc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ riêng chỉ tên một nước chư hầu thời Chu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('絼', '{"9000": "6844.0", "Chữ Trung Quốc": "絼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 13 | nét | 絼 | chẩn | tượng hình | dây lụa dùng trong tang lễ | 絼 là chữ hiếm thuộc bộ 糸 (mịch — sợi tơ lụa). Không có dữ liệu phân tích cấu trúc nội tại từ Wiktionary; chỉ suy từ bộ thủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Chẩn\": bộ 糸 (tơ lụa) gợi vật dụng làm từ sợi — nhớ là loại dây lụa dùng trong nghi lễ cổ xưa. | Gương Hán-Việt | Ít dùng trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 絼 giúp đọc các văn bản lễ nghi cổ điển liên quan đến tang lễ.", "Tự nguyên_Xie": "絼 thuộc bộ 糸 (sợi tơ), âm đọc zhěn. Đây là chữ hiếm, chưa có nguồn học thuật Wiktionary xác nhận cấu trúc hình-thanh hay hội ý cụ thể. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "絼", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 豸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹豸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "豸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "絼", "Unihan_Traditional (Chữ Phồn thể)": "絼", "Pinyin_Xie": "zhěn", "Âm Hán Việt_Xie": "chẩn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ làm tân ngữ cho các động từ liên quan đến chăn dắt gia súc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('颥', '{"9000": "6845.0", "Chữ Trung Quốc": "颥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 頁 | Số nét | 20 | nét | 颥 | nhu | tượng hình | xương thái dương (phần hõm hai bên đầu) | 颥 chỉ dùng trong từ kép 顳顬 (thái dương, phần xương hai bên đầu). Bộ 頁 (hiệt — đầu) gợi liên quan đến vùng đầu. Không có dữ liệu cấu trúc hình-thanh chi tiết từ Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Nhu\": chữ dùng trong giải phẫu cổ điển để chỉ vùng thái dương — bộ 頁 (đầu) nhắc đây là chữ liên quan đến phần đầu người. | Gương Hán-Việt | Nhu trong 顳顬 (thái dương) | Mở khoá kiến thức | Biết 颥 giúp đọc các văn bản y học cổ điển Trung Hoa khi nhắc đến vùng đầu.", "Tự nguyên_Xie": "颥 là chữ chỉ xuất hiện trong từ kép 顳顬 (niè rú), chỉ vùng xương thái dương hai bên đầu người. Wiktionary ghi nhận âm Trung cổ và thượng cổ nhưng không phân tích cấu trúc nội tại. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: nhiếp nhu 顳顬,颞颥)", "Hạng Tần Suất (Jun Da)": "6845.0", "Tần Suất % (Jun Da)": "99.9961489172", "GavinGrover_Once (Chiết tự trực tiếp)": "需 + 页", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰需页", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "需", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "页", "Unihan_Simplified (Chữ Giản thể)": "颥", "Unihan_Traditional (Chữ Phồn thể)": "顬", "Pinyin_Xie": "rú", "Âm Hán Việt_Xie": "nhu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với chữ khác tạo thành danh từ ghép chỉ vùng thái dương trên đầu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('篚', '{"9000": "6846.0", "Chữ Trung Quốc": "篚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 16 | nét | 篚 | phỉ | tượng hình | giỏ tre tròn dùng trong tế lễ | 篚 thuộc bộ 竹 (trúc — tre), là chữ chỉ loại giỏ tre tròn dùng trong nghi lễ cúng tế thời cổ. Không có dữ liệu hình-thanh chi tiết; bộ 竹 xác nhận vật liệu làm từ tre.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Phỉ\": bộ 竹 (tre) + hình tròn → chiếc giỏ tre tròn đặt trên bàn thờ ngày cúng tế — nhớ qua hình ảnh lễ vật đựng trong giỏ tre. | Gương Hán-Việt | Phỉ — ít dùng trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 篚 giúp đọc các văn bản lễ nghi cổ điển như Nghi Lễ, Chu Lễ.", "Tự nguyên_Xie": "篚 (fěi) là loại giỏ tre hình tròn dùng để đựng lễ vật trong các nghi lễ tế tự thời cổ đại Trung Hoa. Chữ thuộc bộ 竹 (tre). Wiktionary ghi nhận âm Trung cổ và thượng cổ, dẫn chứng từ Nghi Lễ (儀禮). Chưa có nguồn học thuật phân tích cấu trúc nội tại chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái thúng tròn có nắp", "Hạng Tần Suất (Jun Da)": "6846.0", "Tần Suất % (Jun Da)": "99.9961535682", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 匪", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮匪", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匪", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "篚", "Unihan_Traditional (Chữ Phồn thể)": "篚", "Pinyin_Xie": "fěi", "Âm Hán Việt_Xie": "phỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ vật thể, thường đi kèm với lượng từ chỉ đồ vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鳘', '{"9000": "6847.0", "Chữ Trung Quốc": "鳘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 19 | nét | 鳘 | mẫn | tượng hình | cá mỉn (Miichthys miiuy), loài cá biển lớn | 鳘 thuộc bộ 鳥/魚, là tên loài cá. Bộ thủ gợi ý liên quan đến động vật thủy sinh. Không có dữ liệu hình-thanh chi tiết từ Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Mẫn\": tên loài cá biển quý ở vùng Đông Á — nhớ qua từ 鰵魚肝油 (dầu gan cá mỉn) tương tự dầu cá tuyết. | Gương Hán-Việt | Mẫn ngư — ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 鳘 giúp đọc văn bản về ngư nghiệp và ẩm thực biển Trung Hoa.", "Tự nguyên_Xie": "鳘 (mǐn) là tên loài cá mỉn (Miichthys miiuy), còn gọi là mi-iuy croaker, một loài cá biển lớn có giá trị kinh tế cao ở vùng biển Đông Á. Wiktionary ghi nhận cả nghĩa cá tuyết (codfish). Chưa có nguồn học thuật phân tích cấu trúc nội tại. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá sủ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "敏 + 鱼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱敏鱼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鳘", "Unihan_Traditional (Chữ Phồn thể)": "鳘", "Pinyin_Xie": "mǐn", "Âm Hán Việt_Xie": "mẫn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ đứng sau lượng từ để chỉ loài cá sủ trong thực tế. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('虒', '{"9000": "6849.0", "Chữ Trung Quốc": "虒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虍 | Số nét | 10 | nét | 虒 | tư | tượng hình | con thú huyền thoại giống hổ một sừng | 虒 là tên con thú huyền thoại (委虒) giống hổ có một sừng, sống được dưới nước. Bộ 虍 (hổ) xác nhận liên quan đến hổ. Chữ cũng là tên địa danh (虒亭) ở Sơn Tây.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Tư\": bộ 虍 (hổ) + một sừng → con thú thần kỳ nửa hổ nửa kỳ lân sống dưới nước trong thần thoại Trung Hoa. | Gương Hán-Việt | Tư — ít dùng trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 虒 giúp đọc các văn bản thần thoại và địa lý cổ đại Trung Hoa.", "Tự nguyên_Xie": "虒 (sī) dùng trong 委虒 — tên con thú huyền thoại lưỡng thê, thân hổ một sừng. Wiktionary ghi nhận âm Trung cổ và thượng cổ. Chữ cũng dùng trong địa danh 虒亭 ở huyện Tương Viên, tỉnh Sơn Tây. Chưa có nguồn học thuật phân tích cấu trúc nội tại. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Tư Đình (tên đất, ở tỉnh Sơn Tây, Trung Quốc)", "Hạng Tần Suất (Jun Da)": "6849.0", "Tần Suất % (Jun Da)": "99.9961675214", "GavinGrover_Once (Chiết tự trực tiếp)": "⺁ + 虎", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴⺁虎", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "虎", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺁", "Unihan_Simplified (Chữ Giản thể)": "虒", "Unihan_Traditional (Chữ Phồn thể)": "虒", "Pinyin_Xie": "sī", "Âm Hán Việt_Xie": "ty", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ riêng chỉ địa danh cổ hoặc tên loài thú huyền thoại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('裈', '{"9000": "6850.0", "Chữ Trung Quốc": "裈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 11 | nét | 衤 | y | biểu nghĩa | quần áo | 軍 | quân | biểu âm | 裈 = 衤 (Y, biểu nghĩa: quần áo) + 軍 (Quân, biểu âm); chữ hình thanh. Bộ 衤 xác nhận nghĩa liên quan đến trang phục; 軍 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Côn\": bộ 衤 (y phục) + 軍 (quân, cho âm) → loại quần ngắn/khố — bộ y phục đơn giản nhất của binh sĩ ngày xưa. | Gương Hán-Việt | Côn — ít dùng trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 裈 giúp đọc văn bản mô tả trang phục cổ đại và nghiên cứu phương ngữ Trung Hoa.", "Tự nguyên_Xie": "裈 (kūn) là chữ hình thanh: bộ 衤 (y phục) cho nghĩa, 軍 (quân) cho âm. Chỉ loại quần ngắn hoặc khố, dùng trong phương ngữ Quan Thoại và Ngô để chỉ quần. Wiktionary xác nhận cấu trúc Han compound với ls=psc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái quần đùi", "Hạng Tần Suất (Jun Da)": "6850.0", "Tần Suất % (Jun Da)": "99.9961721725", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 军", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤军", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "军", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "裈", "Unihan_Traditional (Chữ Phồn thể)": "褌", "Pinyin_Xie": "kūn", "Âm Hán Việt_Xie": "côn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ các loại quần ngắn hoặc quần mặc bên trong thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('遆', '{"9000": "6851.0", "Chữ Trung Quốc": "遆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 12 | nét | 遆 | đề | tượng hình | chữ hiếm, nghĩa không rõ | 遆 thuộc bộ 辵 (착— đi lại), gợi liên quan đến chuyển động. Không có dữ liệu cấu trúc hình-thanh từ Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Đề\": bộ 辵 (đi lại) gợi sự chuyển dịch — chữ hiếm chưa rõ nghĩa cụ thể. | Gương Hán-Việt | Đề — ít dùng trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 遆 giúp nhận diện chữ trong các cổ văn hiếm gặp.", "Tự nguyên_Xie": "遆 (tí) là chữ hiếm thuộc bộ 辵 (đi lại). Không có dữ liệu Wiktionary về cấu trúc nội tại. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "họ Đề", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 帝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶帝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "帝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "遆", "Unihan_Traditional (Chữ Phồn thể)": "遆", "Pinyin_Xie": "tí", "Âm Hán Việt_Xie": "đệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ riêng chỉ họ người hoặc động từ chỉ sự thay đổi, kế thừa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('麑', '{"9000": "6852.0", "Chữ Trung Quốc": "麑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鹿 | Số nét | 19 | nét | 麑 | nghê | tượng hình | hươu non, nai non | 麑 thuộc bộ 鹿 (lộc — hươu nai), là tên gọi hươu non hoặc nai con. Bộ 鹿 xác nhận đây là loài động vật họ hươu. Chưa có dữ liệu cấu trúc chi tiết từ Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Nghê\": bộ 鹿 (lộc/hươu) + non trẻ → con hươu non còn đang bú mẹ — nhớ qua hình ảnh nai con trong rừng. | Gương Hán-Việt | Nghê lộc (hươu non) — ít dùng trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 麑 giúp đọc thơ văn cổ điển và văn bản thú y, săn bắn thời cổ.", "Tự nguyên_Xie": "麑 (ní) là tên gọi hươu non, nai con trong tiếng Hán cổ. Thuộc bộ 鹿 (hươu). Wiktionary không cung cấp phân tích cấu trúc nội tại. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con hươu con", "Hạng Tần Suất (Jun Da)": "6852.0", "Tần Suất % (Jun Da)": "99.9961814746", "GavinGrover_Once (Chiết tự trực tiếp)": "鹿 + 兒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴鹿兒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鹿", "Unihan_Simplified (Chữ Giản thể)": "麑", "Unihan_Traditional (Chữ Phồn thể)": "麑", "Pinyin_Xie": "ní", "Âm Hán Việt_Xie": "nghê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ đứng độc lập hoặc kết hợp với các từ chỉ động vật để chỉ con non. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('粚', '{"9000": "6853.0", "Chữ Trung Quốc": "粚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 11 | nét | 粚 | lê | tượng hình | chữ hiếm thuộc bộ gạo | 粚 thuộc bộ 米 (mễ — gạo), gợi liên quan đến lương thực. Không có dữ liệu cấu trúc hình-thanh từ Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Lê\": bộ 米 (gạo) gợi lương thực — chữ hiếm ít được dùng trong văn bản hiện đại. | Gương Hán-Việt | Lê — ít dùng trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 粚 giúp nhận diện chữ trong các cổ văn về lương thực.", "Tự nguyên_Xie": "粚 (lí) là chữ hiếm thuộc bộ 米 (gạo). Không có nguồn Wiktionary phân tích cấu trúc nội tại. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rạ; như \"rơm rạ\" (vhn)", "Hạng Tần Suất (Jun Da)": "6853.0", "Tần Suất % (Jun Da)": "99.9961861257", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 㐌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米㐌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㐌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "粚", "Unihan_Traditional (Chữ Phồn thể)": "粚", "Pinyin_Xie": "lí", "Âm Hán Việt_Xie": "li", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ phần gốc cây lúa còn lại sau khi gặt hoặc một loại thức ăn dạng bột. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鄚', '{"9000": "6854.0", "Chữ Trung Quốc": "鄚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 12 | nét | 鄚 | mạo | tượng hình | địa danh cổ ở Hà Bắc | 鄚 là tên địa danh (鄚州), thuộc bộ 邑 (ấp — làng ấp, địa phương). Bộ 邑 xác nhận đây là chữ chỉ địa danh hành chính.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Mạo\": bộ 邑 (ấp/địa phương) → tên một vùng đất cổ ở Hà Bắc — nhớ là địa danh hành chính thời phong kiến. | Gương Hán-Việt | Mạo — ít dùng trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 鄚 giúp đọc sử liệu địa lý cổ đại vùng Hà Bắc, Trung Quốc.", "Tự nguyên_Xie": "鄚 (mào/mò) là tên địa danh cổ (鄚州, nay là thị trấn Maozhou, tỉnh Hà Bắc, Trung Quốc). Thuộc bộ 邑 (ấp). Wiktionary ghi nhận cả hai âm đọc mào và mò, không phân tích cấu trúc nội tại. Chưa có nguồn học thuật xác nhận chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: mạo châu 鄚州)", "Hạng Tần Suất (Jun Da)": "6854.0", "Tần Suất % (Jun Da)": "99.9961954278", "GavinGrover_Once (Chiết tự trực tiếp)": "莫 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰莫阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "莫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "鄚", "Unihan_Traditional (Chữ Phồn thể)": "鄚", "Pinyin_Xie": "mào", "Âm Hán Việt_Xie": "mạo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ riêng để chỉ địa danh cổ ở Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_