INSERT INTO characters (char, data) VALUES ('粌', '{"9000": "6855.0", "Chữ Trung Quốc": "粌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 10 | nét | 粌 | dẫn | tượng hình | chữ hiếm thuộc bộ gạo | 粌 thuộc bộ 米 (mễ — gạo). Không có dữ liệu cấu trúc hình-thanh từ Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Dẫn\": bộ 米 (gạo) gợi lương thực — chữ hiếm ít được dùng trong văn bản hiện đại. | Gương Hán-Việt | Dẫn — ít dùng trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 粌 giúp nhận diện chữ trong các cổ văn về lương thực.", "Tự nguyên_Xie": "粌 là chữ hiếm thuộc bộ 米 (gạo). Không có nguồn Wiktionary phân tích cấu trúc nội tại. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "粲", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 引", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米引", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "引", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "粌", "Unihan_Traditional (Chữ Phồn thể)": "粌", "Pinyin_Xie": "yin", "Âm Hán Việt_Xie": "dẫn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong văn bản cổ để chỉ một loại gạo hoặc hạt ngũ cốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('葌', '{"9000": "6856.0", "Chữ Trung Quốc": "葌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 葌 | gian | tượng hình | cỏ lan, cỏ tranh (cổ ngữ) | 葌 thuộc bộ 艹 (thảo — cỏ cây), là tên cổ của cỏ lan hoặc cỏ tranh. Bộ 艹 xác nhận đây là tên một loài thực vật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Gian\": bộ 艹 (cỏ cây) → tên cổ của cỏ lan hoặc cỏ tranh — chữ văn học dùng trong thơ ca cổ đại. | Gương Hán-Việt | Gian — ít dùng trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 葌 giúp đọc thơ văn cổ điển Trung Hoa khi nhắc đến tên cây cỏ.", "Tự nguyên_Xie": "葌 (jiān) là tên cổ của lan thảo (蘭草) hoặc cỏ tranh (cogon grass). Wiktionary ghi nhận là chữ cổ (obs-std) không còn dùng trong tiếng Trung chuẩn hiện đại. Thuộc bộ 艹. Không có phân tích hình-thanh chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "葌", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 姦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹姦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "姦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "葌", "Unihan_Traditional (Chữ Phồn thể)": "葌", "Pinyin_Xie": "jiān", "Âm Hán Việt_Xie": "gian", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ trong văn ngôn để chỉ một loại cỏ tranh hoặc cỏ tế lễ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('貏', '{"9000": "6857.0", "Chữ Trung Quốc": "貏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 豸 | Số nét | 15 | nét | 貏 | bĩ | tượng hình | chỉ dùng trong 貏豸 — tên một vùng đất | 貏 là chữ hiếm, chỉ dùng trong từ kép 貏豸. Thuộc bộ 豸 (trãi — loài thú). Không có dữ liệu cấu trúc chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Bĩ\": bộ 豸 (loài thú) → chữ dùng trong cụm từ 貏豸 chỉ một vùng địa lý hoặc tên loài thú cổ. | Gương Hán-Việt | Bĩ — ít dùng trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 貏 giúp nhận diện chữ trong các cổ văn địa lý.", "Tự nguyên_Xie": "貏 (bǐ) chỉ xuất hiện trong từ kép 貏豸. Wiktionary ghi nhận âm Trung cổ và thượng cổ nhưng không phân tích cấu trúc. Thuộc bộ 豸. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "菅", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "豸 + 卑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰豸卑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "豸", "Unihan_Simplified (Chữ Giản thể)": "貏", "Unihan_Traditional (Chữ Phồn thể)": "貏", "Pinyin_Xie": "bǐ", "Âm Hán Việt_Xie": "bĩ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong văn học cổ để chỉ một loài thú hoang dã. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('闅', '{"9000": "6858.0", "Chữ Trung Quốc": "闅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 17 | nét | 闅 | văn | tượng hình | chữ hiếm thuộc bộ cửa, nghĩa chưa rõ | 闅 thuộc bộ 門 (môn — cửa). Không có dữ liệu cấu trúc hình-thanh từ Wiktionary; Wiktionary chỉ ghi rfdef (cần định nghĩa).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Văn\": bộ 門 (cửa) → chữ hiếm gần với các chữ về cửa ngõ — nghĩa chưa được xác định chính thức. | Gương Hán-Việt | Văn — ít dùng trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 闅 giúp nhận diện chữ trong các cổ văn hiếm gặp.", "Tự nguyên_Xie": "闅 (wén) thuộc bộ 門 (cửa). Wiktionary ghi rfdef — tức là nghĩa chưa được xác định rõ. Âm Trung cổ và thượng cổ được ghi nhận. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "闅", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "𫕛 + 攴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴𫕛攴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𫕛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "攴", "Unihan_Simplified (Chữ Giản thể)": "闅", "Unihan_Traditional (Chữ Phồn thể)": "闅", "Pinyin_Xie": "wén", "Âm Hán Việt_Xie": "văn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ riêng chỉ địa danh cổ hoặc tên người trong thư tịch cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鳉', '{"9000": "6859.0", "Chữ Trung Quốc": "鳉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 17 | nét | 鳉 | giang | tượng hình | loài cá nhỏ (guppy hoặc cá killifish) | 鳉 thuộc bộ 鳥/魚, là tên loài cá nhỏ. Bộ thủ gợi liên quan đến động vật thủy sinh. Wiktionary không có định nghĩa cụ thể (rfdef).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Giang\": bộ cá + âm giang → loài cá nhỏ sống ở sông ngòi — nhớ qua \"giang\" (sông) nơi loài cá này sinh sống. | Gương Hán-Việt | Giang — ít dùng trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 鳉 giúp đọc văn bản về sinh vật học cá nước ngọt Trung Hoa.", "Tự nguyên_Xie": "鳉 (jiāng) là tên loài cá nhỏ, thường chỉ cá guppy hoặc killifish. Wiktionary ghi rfdef — chưa có định nghĩa chính thức. Âm Trung cổ và thượng cổ được ghi nhận. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá lành canh", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 将", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼将", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "将", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鳉", "Unihan_Traditional (Chữ Phồn thể)": "鳉", "Pinyin_Xie": "jiāng", "Âm Hán Việt_Xie": "tương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ một loài cá nhỏ, xuất hiện trong các danh từ ghép chỉ tên cá. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鴱', '{"9000": "6860.0", "Chữ Trung Quốc": "鴱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 16 | nét | 鴱 | ái | tượng hình | chim tiêu dao (wren) | 鴱 thuộc bộ 鳥 (điểu — chim), là tên loài chim tiêu dao (wren). Bộ 鳥 xác nhận đây là tên một loài chim. Không có dữ liệu cấu trúc chi tiết từ Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Ái\": bộ 鳥 (chim) → con chim tiêu dao nhỏ bé — nhớ qua hình ảnh con wren trong thơ ca cổ điển. | Gương Hán-Việt | Ái — ít dùng trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 鴱 giúp đọc thơ văn cổ điển nhắc đến các loài chim.", "Tự nguyên_Xie": "鴱 (ài) là tên loài chim tiêu dao (wren), đồng nghĩa với 鷦鷯. Wiktionary xác nhận nghĩa là wren và âm đọc. Thuộc bộ 鳥. Không có phân tích hình-thanh chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ờ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艾 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰艾鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "艾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鴱", "Unihan_Traditional (Chữ Phồn thể)": "鴱", "Pinyin_Xie": "ài", "Âm Hán Việt_Xie": "ái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thán từ | 叹词 | Thường dùng làm danh từ chỉ một loài chim nhạn hoặc làm thán từ biểu thị sự đồng ý. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Thán từ | 叹词 | Bộc lộ cảm xúc hoặc dùng để gọi đáp: 啊, 哦, 喂. Đứng tách riêng ở đầu câu, không làm thành phần câu.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鶎', '{"9000": "6861.0", "Chữ Trung Quốc": "鶎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 19 | nét | 宗 | tông | biểu âm | 鳥 | điểu | biểu nghĩa | chim | 鶎 = 宗 (Tông, biểu âm) + 鳥 (Điểu, biểu nghĩa: chim); chữ hình thanh theo Wiktionary (kokuji Nhật). Bộ 鳥 xác nhận đây là tên loài chim; 宗 cho âm. Đây là chữ Nhật tạo (kokuji), không phải chữ Hán thuần.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Tông\": chữ Nhật tạo (kokuji) = 鳥 (chim) + 宗 (âm) → tên loài chim Goldcrest trong tiếng Nhật — chữ không thuộc hệ thống Hán. | Gương Hán-Việt | Tông — không dùng trong từ Hán-Việt | Mở khoá kiến thức | Biết 鶎 giúp nhận ra kokuji — chữ do người Nhật tự tạo, không có trong tiếng Hán thuần.", "Tự nguyên_Xie": "鶎 là kokuji (chữ Nhật tạo ra), không phải chữ Hán gốc. Cấu trúc: 宗 (phonetic) + 鳥 (semantic: chim). Chữ đọc là きくいただき (kikuitadaki) trong tiếng Nhật, chỉ loài chim Goldcrest (菊戴). Wiktionary đặt câu hỏi tại sao 宗 là phonetic vì không rõ cách phát âm. Không dùng trong tiếng Hán. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鶎", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "宗 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰宗鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鶎", "Unihan_Traditional (Chữ Phồn thể)": "鶎", "Pinyin_Xie": "zun", "Âm Hán Việt_Xie": "tông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ một loài chim cổ trong thư tịch cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('祼', '{"9000": "6862.0", "Chữ Trung Quốc": "祼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 12 | nét | 示 | thị | biểu nghĩa | bàn thờ, thần linh, tế lễ | 果 | quả | biểu âm | 祼 = 示 (Thị, biểu nghĩa: bàn thờ, tế lễ) + 果 (Quả, biểu âm); chữ hình thanh, dù trong chữ viết sớm có thể phân tích như hội ý với hình bình rượu và bàn tay. Bộ 示 xác nhận ngữ cảnh tế lễ; 果 cho âm đọc gần guàn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Quán\": bộ 示 (tế lễ) + 果 (âm) → rưới rượu xuống đất để cúng thần — nghi lễ trang nghiêm trong tế tự Trung Hoa cổ đại. | Gương Hán-Việt | Quán trong \"quán lễ\" (祼禮 — lễ rưới rượu tế thần) | Mở khoá kiến thức | Biết 祼 giúp đọc các văn bản nghi lễ cổ đại như Chu Lễ, Nghi Lễ.", "Tự nguyên_Xie": "Giáp cốt văn | 祼 (guàn) là chữ hình thanh: bộ 示 (tế lễ, bàn thờ) cho nghĩa — nghi thức rưới rượu thơm xuống đất để tế thần hoặc dâng tổ tiên; 果 (quả) cho âm. Wiktionary ghi rằng trong chữ viết sớm, hình dạng gần hội ý hơn (hình bình rượu 酉/畐 kết hợp với tay). Có giáp cốt văn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tưới rượu xuống đất để tế", "Hạng Tần Suất (Jun Da)": "6862.0", "Tần Suất % (Jun Da)": "99.9963070534", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 果", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻果", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "果", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "祼", "Unihan_Traditional (Chữ Phồn thể)": "祼", "Pinyin_Xie": "guàn", "Âm Hán Việt_Xie": "quán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ chỉ nghi thức rưới rượu xuống đất trong các lễ tế cổ xưa. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鬛', '{"9000": "6863.0", "Chữ Trung Quốc": "鬛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 髟 | Số nét | 22 | nét | 鬛 | liệp | tượng hình | bờm ngựa, lông bờm | 鬛 thuộc bộ 髟 (tiêu — tóc, lông dài), chỉ bờm ngựa hoặc đám lông dài. Không có dữ liệu cấu trúc hình-thanh từ Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Liệp\": bộ 髟 (lông tóc dài) → bờm ngựa rậm rạp phất phơ — nhớ qua hình ảnh đám lông dài trên cổ ngựa hoặc sư tử. | Gương Hán-Việt | Liệp — ít dùng trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 鬛 giúp đọc văn bản về ngựa, thú vật trong văn học cổ điển.", "Tự nguyên_Xie": "鬛 (liè) chỉ bờm ngựa (lông dài trên cổ ngựa, sư tử). Thuộc bộ 髟 (tóc, lông dài). Không có nguồn Wiktionary phân tích cấu trúc nội tại. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鬛", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "髟 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱髟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "鬛", "Unihan_Traditional (Chữ Phồn thể)": "鬛", "Pinyin_Xie": "liè", "Âm Hán Việt_Xie": "liệp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ bờm của thú vật hoặc vây cá. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镈', '{"9000": "6864.0", "Chữ Trung Quốc": "镈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 15 | nét | 镈 | bác | tượng hình | nhạc khí đồng cổ (chuông lớn thời Chu) | 镈 là giản thể của 鎛, là tên loại nhạc khí đồng lớn (chuông treo) thời nhà Chu. Bộ 钅/金 (kim loại) xác nhận đây là nhạc khí bằng đồng. Wiktionary chỉ ghi là dạng giản thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Bác\": bộ 钅(kim loại) → chuông đồng lớn dùng trong lễ nhạc cung đình — nhớ qua âm thanh trầm vang của chuông đồng thời Chu. | Gương Hán-Việt | Bác trong nhạc khí cổ — ít dùng trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 镈 giúp đọc văn bản về nhạc khí và nghi lễ cổ đại Trung Hoa.", "Tự nguyên_Xie": "镈 là giản thể của 鎛 (bó), loại chuông đồng lớn dùng trong nghi lễ nhà Chu. Wiktionary ghi \"Han simp 鎛\" — đây là phiên bản giản thể. Thuộc bộ 钅(金). Chưa có phân tích cấu trúc nội tại riêng. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái chuông to; cái bướm (một loại cuốc)", "Hạng Tần Suất (Jun Da)": "6864.0", "Tần Suất % (Jun Da)": "99.9963163556", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 尃", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅尃", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镈", "Unihan_Traditional (Chữ Phồn thể)": "鎛", "Pinyin_Xie": "bó", "Âm Hán Việt_Xie": "bác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ một loại nhạc cụ gõ cổ hoặc công cụ làm ruộng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瞓', '{"9000": "6865.0", "Chữ Trung Quốc": "瞓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 15 | nét | 目 | mục | biểu nghĩa | mắt | 訓 | huấn | biểu âm | 瞓 = 目 (Mục, biểu nghĩa: mắt) + 訓 (Huấn, biểu âm); chữ hình thanh. Bộ 目 xác nhận nghĩa liên quan đến mắt — nhắm mắt ngủ; 訓 cho âm đọc gần shuì (phương ngữ Quảng Đông).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Huấn\": bộ 目 (mắt) + 訓 (huấn, âm) → nhắm mắt lại để ngủ — chữ Quảng Đông đặc thù, nghĩa là ngủ/ngủ thiếp đi. | Gương Hán-Việt | Huấn — ít dùng trong từ Hán-Việt; đây là chữ phương ngữ Quảng Đông | Mở khoá kiến thức | Biết 瞓 giúp đọc văn bản tiếng Quảng Đông (Cantonese) và hiểu hệ thống chữ phương ngữ.", "Tự nguyên_Xie": "瞓 (shuì) là chữ hình thanh Quảng Đông: bộ 目 (mắt) cho nghĩa — nhắm mắt ngủ; 訓 (huấn) cho âm theo phát âm Quảng Đông. Wiktionary xác nhận cấu trúc Han compound ls=psc với c1=s (eye), c2=p (phonetic 訓), ghi no_och2=1 (không có âm thượng cổ cho 訓 trong ngữ cảnh này). Đây là chữ tạo ra cho phương ngữ Quảng Đông. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Tương đương tiếng phổ thông: 睡 [Shui4]; đi ngủ (tiếng Quảng Đông)", "Hạng Tần Suất (Jun Da)": "6865.0", "Tần Suất % (Jun Da)": "99.9963210066", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 訓", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目訓", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "訓", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "瞓", "Unihan_Traditional (Chữ Phồn thể)": "瞓", "Pinyin_Xie": "shuì", "Âm Hán Việt_Xie": "thẩm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ biểu thị hành động ngủ trong phương ngôn Quảng Đông. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('罶', '{"9000": "6866.0", "Chữ Trung Quốc": "罶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 网 | Số nét | 15 | nét | 罶 | lưu | tượng hình | đăng tre bắt cá, chữ độc thể | 罶 là chữ độc thể, cấu tạo chưa được phân tích rõ trong CHISE. Bộ 网 (mạng lưới) gợi ý liên quan đến đồ dùng đánh bắt. Chữ tạo muộn, không thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lưu\": chữ mang bộ 网 (lưới) — gợi hình cái đăng tre giăng lưới dưới nước để \"lưu\" cá lại. | Gương Hán-Việt | lưu — ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 罶 giúp nhận diện các từ cổ về dụng cụ đánh bắt trong văn ngôn Hán.", "Tự nguyên_Xie": "Tiểu triện | 罶 chỉ cái đăng tre dùng để bắt cá trong văn cổ (bamboo fishing trap). Nguồn Wiktionary chỉ ghi phát âm và định nghĩa, không cung cấp phân tích tự hình. Chưa có nguồn học thuật về cấu tạo chữ này. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đăng bắt cá", "Hạng Tần Suất (Jun Da)": "6866.0", "Tần Suất % (Jun Da)": "99.9963251409", "GavinGrover_Once (Chiết tự trực tiếp)": "罒 + 留", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱罒留", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "留", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "罒", "Unihan_Simplified (Chữ Giản thể)": "罶", "Unihan_Traditional (Chữ Phồn thể)": "罶", "Pinyin_Xie": "liǔ", "Âm Hán Việt_Xie": "lữu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ dụng cụ đan bằng tre dùng để bắt cá. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('羑', '{"9000": "6867.0", "Chữ Trung Quốc": "羑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羊 | Số nét | 9 | nét | 羑 | dữu | tượng hình | hướng dẫn làm điều thiện, chữ độc thể | 羑 là chữ độc thể, bộ 羊 (dương, con dê/tốt lành). Wiktionary ghi nhận đây là dạng cổ của 誘 (dụ dỗ, hướng dẫn). Cấu tạo chi tiết chưa được phân tích chính thức. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dữu\": bộ 羊 (dương, tốt lành) — người dẫn dắt như mục đồng dẫn đàn cừu đi về phía \"thiện\". | Gương Hán-Việt | dữu — xuất hiện trong từ cổ, ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 羑 giúp hiểu từ cổ chỉ việc hướng dẫn về đạo đức trong văn ngôn.", "Tự nguyên_Xie": "Tiểu triện | 羑 trong văn cổ có nghĩa là dẫn dắt, hướng dẫn, tiến về phía thiện (《玉篇》: 羑，導也，進也，善也). Sau được thay bằng 誘. Wiktionary không phân tích tự hình chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gắng làm việc thiện", "Hạng Tần Suất (Jun Da)": "6867.0", "Tần Suất % (Jun Da)": "99.9963292752", "GavinGrover_Once (Chiết tự trực tiếp)": "羊 + 久", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱羊久", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "久", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羊", "Unihan_Simplified (Chữ Giản thể)": "羑", "Unihan_Traditional (Chữ Phồn thể)": "羑", "Pinyin_Xie": "yǒu", "Âm Hán Việt_Xie": "dũ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ chỉ việc dẫn dắt, khuyên bảo người khác hướng thiện. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('黉', '{"9000": "6868.0", "Chữ Trung Quốc": "黉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 黃 | Số nét | 16 | nét | 黉 | hoành | tượng hình | trường học thời cổ, chữ độc thể | 黉 (dị thể của 黌) là chữ chỉ trường học thời cổ. Cấu tạo chi tiết chưa được CHISE phân tích rõ. Bộ 黄 xuất hiện trong hình thể. Chữ chủ yếu dùng trong văn ngôn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoành\": ngôi trường \"hoành tráng\" thời xưa — 黌宮 là học cung, nơi học trò đến tu dưỡng. | Gương Hán-Việt | hoành — xuất hiện trong từ 黌門 (hoành môn), ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 黉 giúp đọc văn ngôn chỉ các thiết chế giáo dục cổ đại như 黌宇, 黌舍.", "Tự nguyên_Xie": "黉 là dị thể của 黌, chỉ ngôi trường học trong xã hội cổ đại Trung Hoa. Wiktionary ghi nhận các hợp từ như 黌宮 (hoàng cung, tức trường học lớn), 黌門 (hoàng môn, cổng trường). Không có phân tích tự hình chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trường học", "Hạng Tần Suất (Jun Da)": "6868.0", "Tần Suất % (Jun Da)": "99.9963334095", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 黄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱黄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "黉", "Unihan_Traditional (Chữ Phồn thể)": "黌", "Pinyin_Xie": "hóng", "Âm Hán Việt_Xie": "huỳnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ để chỉ trường học hoặc nơi dạy học thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('霚', '{"9000": "6869.0", "Chữ Trung Quốc": "霚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 雨 | Số nét | 17 | nét | 雨 | vũ | biểu nghĩa | mưa, thời tiết | 敄 | biểu âm | thành phần biểu âm | 霚 = 雨 (Vũ, biểu nghĩa: mưa/thời tiết) + 敄 (biểu âm). Chữ hình thanh. 霚 là dị thể cổ của 霧 (sương mù).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vụ\": bộ 雨 (vũ, mưa) trên đầu — cơn mưa nhẹ tan thành \"sương mù\" (霧/霚). | Gương Hán-Việt | vụ — 霧 (vụ) trong từ \"sương mù\", \"mù sương\" | Mở khoá kiến thức | Biết 霚 giúp nhận ra dạng cổ của 霧, xuất hiện trong văn bản cổ điển về thời tiết.", "Tự nguyên_Xie": "霚 là dạng cổ của 霧 (sương mù). Cấu tạo hình thanh: bộ 雨 biểu thị hiện tượng khí quyển, 敄 cho âm đọc. Wiktionary xác nhận 霚 là biến thể của 霧. Chữ này không còn dùng độc lập trong văn bản hiện đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "隚", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "雨 + 敄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱雨敄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "雨", "Unihan_Simplified (Chữ Giản thể)": "霚", "Unihan_Traditional (Chữ Phồn thể)": "霚", "Pinyin_Xie": "wù", "Âm Hán Việt_Xie": "vụ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ hiện tượng sương mù tích tụ trong tự nhiên. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('笹', '{"9000": "6870.0", "Chữ Trung Quốc": "笹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 11 | nét | 笹 | tể | tượng hình | cỏ tre nhỏ (Sasa), chữ mượn từ tiếng Nhật | 笹 là chữ mượn từ tiếng Nhật (sasa, 笹), chỉ loại tre thấp Sasa. Cấu tạo bộ 竹 (trúc, tre) + phần dưới. Không thuộc hệ thống hình thanh/hội ý truyền thống của chữ Hán.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tể\": bộ 竹 (trúc, tre) trên đầu — cây \"tể\" này là loài tre thấp của Nhật Bản (sasa), lá nhỏ mảnh. | Gương Hán-Việt | tể — ít xuất hiện trong tiếng Việt; chủ yếu dùng trong ngữ cảnh sinh học/thực vật | Mở khoá kiến thức | Biết 笹 giúp nhận diện loài thực vật Sasa trong văn bản tiếng Trung/Nhật về thực vật học.", "Tự nguyên_Xie": "笹 là chữ vay mượn từ tiếng Nhật (obor: sasa), chỉ loại tre thấp Sasa thuộc họ tre. Wiktionary xác nhận đây là \"outlier borrowing\" từ Nhật vào bộ chữ Hán mở rộng. Không có nguồn gốc tự hình Hán truyền thống. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Sasa", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 世", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮世", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "世", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "笹", "Unihan_Traditional (Chữ Phồn thể)": "笹", "Pinyin_Xie": "ti", "Âm Hán Việt_Xie": "tể", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một giống tre nhỏ có lá dùng làm thuốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('郐', '{"9000": "6871.0", "Chữ Trung Quốc": "郐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 8 | nét | 會 | hội | biểu âm | gặp gỡ, hội họp | 阝 | biểu nghĩa | bộ ấp, chỉ đất/nước chư hầu | 郐 = 會 (Hội, biểu âm) + 阝 (Ấp, biểu nghĩa: vùng đất, nước chư hầu). Chữ hình thanh chỉ tên một nước cổ ở vùng Hà Nam ngày nay.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khoái\": bộ 阝 (ấp, đất) + 會 (hội, gặp) — nước \"Khoái\" là nơi hội tụ, nhưng nổi tiếng qua câu 自鄶以下 (từ Khoái trở xuống, không đáng kể). | Gương Hán-Việt | khoái — ít dùng trong tiếng Việt; chủ yếu trong văn ngôn địa danh cổ | Mở khoá kiến thức | Biết 郐 giúp đọc văn bản lịch sử Trung Hoa về các nước chư hầu thời Xuân Thu.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | 郐 (dị thể phồn thể: 鄶) là tên một nước chư hầu cổ đại ở vùng Hà Nam, Trung Quốc. Cấu tạo hình thanh: bộ 邑 (阝, ấp, biểu thị địa danh) kết hợp 會 (hội) làm biểu âm. Hợp từ nổi bật: 自鄶以下 (từ nước Khoái trở xuống, ý coi thường). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước Cối thời xưa (nay thuộc tỉnh Hà Nam của Trung Quốc)", "Hạng Tần Suất (Jun Da)": "6871.0", "Tần Suất % (Jun Da)": "99.9963458123", "GavinGrover_Once (Chiết tự trực tiếp)": "会 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰会阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "会", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "郐", "Unihan_Traditional (Chữ Phồn thể)": "鄶", "Pinyin_Xie": "kuài", "Âm Hán Việt_Xie": "cối", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ riêng chỉ tên một nước chư hầu thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('溻', '{"9000": "6872.0", "Chữ Trung Quốc": "溻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 13 | nét | 溻 | thấp | tượng hình | ướt đẫm mồ hôi, chữ độc thể | 溻 có bộ 氵(thuỷ, nước) biểu thị liên quan đến chất lỏng. Cấu tạo chi tiết chưa được CHISE phân tích. Nghĩa: ướt đẫm, đặc biệt ướt đẫm mồ hôi. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thấp\": bộ 氵(thuỷ, nước) — mồ hôi \"thấm\" ướt đẫm toàn thân là 溻. | Gương Hán-Việt | thấp — liên quan âm với \"ẩm thấp\", \"thấp ướt\" trong tiếng Việt | Mở khoá kiến thức | Biết 溻 giúp hiểu mô tả trạng thái ướt đẫm mồ hôi trong văn học Trung Quốc hiện đại.", "Tự nguyên_Xie": "溻 chỉ trạng thái ướt đẫm, thường dùng để tả ướt đẫm mồ hôi (溻湿). Wiktionary không cung cấp phân tích tự hình (rfdef). Bộ 氵 biểu thị liên quan đến nước. Chưa có nguồn học thuật về cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ướt đẫm mồ hôi", "Hạng Tần Suất (Jun Da)": "6872.0", "Tần Suất % (Jun Da)": "99.9963499466", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 𦐇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵𦐇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𦐇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "溻", "Unihan_Traditional (Chữ Phồn thể)": "溻", "Pinyin_Xie": "tā", "Âm Hán Việt_Xie": "thạp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này làm động từ miêu tả trạng thái mồ hôi thấm ướt vào quần áo. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('袉', '{"9000": "6873.0", "Chữ Trung Quốc": "袉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 10 | nét | 袉 | đà | tượng hình | chữ liên quan đến y phục, nghĩa chưa xác định rõ | 袉 có bộ 衣 (y, áo), gợi ý liên quan đến y phục. Cấu tạo chi tiết chưa được CHISE phân tích đầy đủ. Nghĩa cụ thể chưa được Wiktionary định nghĩa (rfdef). Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đà\": bộ 衣 (y, áo quần) — 袉 là chữ về y phục, nghĩa cụ thể như cái gì đó \"đà\" (kéo lê, rủ xuống) của áo. | Gương Hán-Việt | đà — ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 袉 giúp nhận diện chữ trong văn bản cổ về trang phục và vải vóc.", "Tự nguyên_Xie": "Tiểu triện | 袉 có bộ 衣 (y, áo), gợi ý liên quan đến y phục hoặc vải. Wiktionary không cung cấp định nghĩa rõ ràng (rfdef). Tiểu triện còn lưu giữ. Chưa có nguồn học thuật về cấu tạo và nghĩa chính xác. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "袉", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 它", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤它", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "它", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "袉", "Unihan_Traditional (Chữ Phồn thể)": "袉", "Pinyin_Xie": "tuó", "Âm Hán Việt_Xie": "đà", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ phần vạt áo dài hoặc nếp gấp của trang phục. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('訚', '{"9000": "6874.0", "Chữ Trung Quốc": "訚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 10 | nét | 訚 | ngân | tượng hình | tranh biện ôn hòa, giản thể của 誾 | 訚 là giản hoá của 誾. 誾 = 門 (môn, cánh cửa, bao ngoài) + 言 (ngôn, lời nói) — hội ý: lời nói trong cánh cửa, tượng trưng cho cuộc tranh biện ôn hòa, khiêm tốn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngân\": 言 (ngôn, lời) bên trong 門 (môn, cửa) — \"ngân\" tiếng nói lịch thiệp đằng sau cánh cửa, tranh biện mà vẫn ôn hoà. | Gương Hán-Việt | ngân — trong 訚訚 (ngân ngân, ôn hoà trong tranh luận) | Mở khoá kiến thức | Biết 訚 giúp đọc các trích dẫn Luận Ngữ và văn chính thống mô tả phong cách giao tiếp quân tử.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 訚 là dạng giản hoá của 誾 (門→门, thu gọn). 誾 theo Wiktionary là 誾誾, chỉ thái độ tranh biện ôn hoà, nghiêm túc mà không cứng nhắc (《論語》: 訚訚如也). Cấu tạo: 言 (ngôn, lời nói) trong khung 門 (môn). Chữ này ghi lại phong cách giao tiếp lý tưởng của người quân tử. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tranh biện một cách ôn hoà", "Hạng Tần Suất (Jun Da)": "6874.0", "Tần Suất % (Jun Da)": "99.9963664837", "GavinGrover_Once (Chiết tự trực tiếp)": "门 + 言", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴门言", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "言", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "门", "Unihan_Simplified (Chữ Giản thể)": "訚", "Unihan_Traditional (Chữ Phồn thể)": "誾", "Pinyin_Xie": "yín", "Âm Hán Việt_Xie": "ngân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Phó từ | 副词 | Chữ này làm tính từ miêu tả thái độ nói năng ôn hòa và kính cẩn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谉', '{"9000": "6875.0", "Chữ Trung Quốc": "谉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 10 | nét | 谉 | thẩm | tượng hình | xét hỏi kỹ, thẩm tra, chữ độc thể | 谉 có bộ 讠(ngôn, lời nói), gợi ý liên quan đến quá trình ngôn ngữ/thẩm vấn. Cấu tạo đầy đủ chưa được CHISE và Wiktionary phân tích. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thẩm\": bộ 讠(ngôn, lời) — \"thẩm\" vấn là hỏi đi hỏi lại, xét tỉ mỉ từng lời khai. | Gương Hán-Việt | thẩm — trong 審問 (thẩm vấn), 審查 (thẩm tra) | Mở khoá kiến thức | Biết 谉 giúp nhận diện từ liên quan đến thẩm vấn, điều tra trong văn bản pháp lý cổ.", "Tự nguyên_Xie": "谉 chỉ việc thẩm tra, xét hỏi tỉ mỉ. Bộ 讠(ngôn) gợi ý quá trình hỏi đáp, thẩm vấn. Wiktionary không có entry cho chữ này. Chưa có nguồn học thuật về cấu tạo và lịch sử chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tỉ mỉ; thẩm tra, xét hỏi kỹ", "Hạng Tần Suất (Jun Da)": "6875.0", "Tần Suất % (Jun Da)": "99.996370618", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 审", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠审", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "审", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "谉", "Unihan_Traditional (Chữ Phồn thể)": "讅", "Pinyin_Xie": "shěn", "Âm Hán Việt_Xie": "thẩm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ đứng trước tân ngữ để chỉ việc thẩm tra, xét hỏi kỹ lưỡng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('莛', '{"9000": "6876.0", "Chữ Trung Quốc": "莛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 莛 | đình | tượng hình | thân cỏ thẳng đứng, chữ độc thể | 莛 có bộ 艹 (thảo, cây cỏ), gợi ý chỉ bộ phận của thực vật thân thảo. Cấu tạo chi tiết chưa được CHISE phân tích. Nghĩa: thân cây thảo mang hoa/quả (peduncle). Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đình\": bộ 艹 (thảo, cây cỏ) — cái thân cây \"đình\" thẳng, thẳng như đình làng, mang bông hoa trên đầu. | Gương Hán-Việt | đình — liên âm với \"đình\" (sân/đình), gợi hình thân cây thẳng đứng | Mở khoá kiến thức | Biết 莛 giúp đọc văn thơ, nông học cổ điển mô tả bộ phận cây trồng như lúa mì, tỏi.", "Tự nguyên_Xie": "Tiểu triện | 莛 chỉ thân thẳng đứng của cây thảo mang hoa hoặc quả (peduncle/scape). Ví dụ: 麥莛 (thân lúa mì), 花莛 (cuống hoa). Đồng nghĩa với 薹. Wiktionary cung cấp ví dụ dùng trong thực tiễn nhưng không phân tích tự hình. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sợi cỏ, thân cây cỏ", "Hạng Tần Suất (Jun Da)": "6876.0", "Tần Suất % (Jun Da)": "99.9963747523", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 廷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹廷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "廷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "莛", "Unihan_Traditional (Chữ Phồn thể)": "莛", "Pinyin_Xie": "tíng", "Âm Hán Việt_Xie": "đình", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ phần cọng hoặc thân của các loài cây thân thảo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('哕', '{"9000": "6877.0", "Chữ Trung Quốc": "哕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 9 | nét | 哕 | uế | tượng hình | nôn oẹ, ợ, giản thể của 噦 | 哕 là giản hoá của 噦. Bộ 口 (khẩu, miệng) biểu thị âm thanh phát ra từ miệng khi nôn hoặc ợ. Cấu tạo đầy đủ chưa được CHISE phân tích chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uế\": bộ 口 (khẩu, miệng) — tiếng \"uế\" phát ra khi buồn nôn, giống âm oẹ. | Gương Hán-Việt | uế — liên quan đến \"ô uế\", điều không sạch sẽ | Mở khoá kiến thức | Biết 哕 giúp đọc văn y học cổ truyền mô tả triệu chứng nôn oẹ, ợ hơi.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 哕 (phồn thể: 噦) chỉ âm thanh ợ, tiếng oẹ khi nôn. Wiktionary xác nhận đây là giản hoá của 噦. Bộ 口 (khẩu) chỉ hành động phát âm qua miệng. Tiểu triện và Lục thư thông đều ghi nhận. Chưa có phân tích tự hình chi tiết. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nôn, mửa, oẹ", "Hạng Tần Suất (Jun Da)": "6877.0", "Tần Suất % (Jun Da)": "99.9963788866", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 岁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口岁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "岁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "哕", "Unihan_Traditional (Chữ Phồn thể)": "噦", "Pinyin_Xie": "huì", "Âm Hán Việt_Xie": "uyết, hối", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Từ tượng thanh | 象声词 | Chữ này làm động từ chỉ hành động nôn oẹ hoặc làm từ tượng thanh mô tả âm thanh nôn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('滗', '{"9000": "6878.0", "Chữ Trung Quốc": "滗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 13 | nét | 滗 | tất | tượng hình | chắt lọc, gạn lấy phần trong, chữ độc thể | 滗 (phồn thể: 潷) có bộ 氵(thuỷ, nước), gợi ý hành động liên quan đến chất lỏng — cụ thể là chắt/gạn. Cấu tạo chi tiết chưa được CHISE phân tích.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tất\": bộ 氵(thuỷ, nước) — \"tất\" phải chắt gạn cho sạch, giống khi nấu cơm phải chắt nước cơm đi. | Gương Hán-Việt | tất — ít dùng độc lập trong tiếng Việt | Mở khoá kiến thức | Biết 滗 giúp đọc công thức nấu ăn Trung Hoa mô tả bước gạn/chắt nước.", "Tự nguyên_Xie": "滗 (phồn thể: 潷) nghĩa là chắt, gạn, lọc — lấy phần nước trong ra khỏi cặn hoặc hỗn hợp. Wiktionary xác nhận động từ decant/drain/strain. Bộ 氵biểu thị chất lỏng. Chưa có phân tích tự hình chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chắt lọc, chắt ra", "Hạng Tần Suất (Jun Da)": "6878.0", "Tần Suất % (Jun Da)": "99.9963830208", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 笔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵笔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "笔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "滗", "Unihan_Traditional (Chữ Phồn thể)": "潷", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "tiết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ đứng trước danh từ chỉ chất lỏng để biểu thị hành động gạn lọc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瀹', '{"9000": "6879.0", "Chữ Trung Quốc": "瀹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 20 | nét | 瀹 | nhược | tượng hình | nấu sôi, rửa sạch, chữ độc thể | 瀹 có bộ 氵(thuỷ, nước), gợi ý hành động liên quan đến nước sôi hoặc rửa. Nghĩa: đun sôi, ngâm nước, làm sạch. Cấu tạo chi tiết chưa được CHISE phân tích.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhược\": bộ 氵(thuỷ, nước) — nước sôi \"nhược\" (yếu ớt) trên lửa nhỏ, đủ để làm sạch và nấu chín. | Gương Hán-Việt | nhược — ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 瀹 giúp đọc văn ngôn và thơ văn mô tả cách nấu ăn, pha trà trong văn học cổ điển.", "Tự nguyên_Xie": "Tiểu triện | 瀹 nghĩa là đun sôi (to boil) hoặc rửa/ngâm/làm sạch (to wash, cleanse, soak). Wiktionary ghi nhận cả hai nghĩa này. Bộ 氵biểu thị nước/chất lỏng. Tiểu triện còn lưu giữ. Chưa có phân tích tự hình chi tiết. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nấu; làm sạch", "Hạng Tần Suất (Jun Da)": "6879.0", "Tần Suất % (Jun Da)": "99.9963871551", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 龠", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵龠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "龠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "瀹", "Unihan_Traditional (Chữ Phồn thể)": "瀹", "Pinyin_Xie": "yuè", "Âm Hán Việt_Xie": "thược", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ trong văn ngôn để chỉ việc nấu nướng hoặc tẩy rửa. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('稃', '{"9000": "6880.0", "Chữ Trung Quốc": "稃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 12 | nét | 禾 | hoà | biểu nghĩa | lúa, ngũ cốc | 孚 | phu | biểu âm | thành phần biểu âm | 稃 = 禾 (Hoà, biểu nghĩa: lúa/ngũ cốc) + 孚 (Phu, biểu âm). Chữ hình thanh chỉ phần trấu, vỏ ngoài của hạt ngũ cốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phu\": 禾 (hoà, lúa) + 孚 (phu, ấp trứng) — lớp vỏ trấu \"phu\" bao bọc bên ngoài hạt thóc như ôm ấp hạt gạo bên trong. | Gương Hán-Việt | phu — ít dùng trong tiếng Việt; liên âm với \"trấu, vỏ lúa\" | Mở khoá kiến thức | Biết 稃 giúp đọc tài liệu nông học và thực vật học Trung Quốc về cấu tạo hạt ngũ cốc.", "Tự nguyên_Xie": "稃 là chữ hình thanh: bộ 禾 (hoà, lúa) biểu thị nghĩa liên quan đến ngũ cốc, 孚 (phu) cho âm đọc. Wiktionary xác nhận nghĩa chaff/husk (trấu, vỏ hạt). Các hợp từ: 內稃 (vỏ trong), 外稃 (vỏ ngoài). Đây là thuật ngữ nông nghiệp/thực vật học. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trấu", "Hạng Tần Suất (Jun Da)": "6880.0", "Tần Suất % (Jun Da)": "99.9963954237", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 孚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾孚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "孚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "稃", "Unihan_Traditional (Chữ Phồn thể)": "稃", "Pinyin_Xie": "fū", "Âm Hán Việt_Xie": "phu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ lớp vỏ bao bọc bên ngoài của các loại hạt ngũ cốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('眰', '{"9000": "6881.0", "Chữ Trung Quốc": "眰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 11 | nét | 眰 | điệt | tượng hình | chữ bộ 目 (mắt), nghĩa chưa xác định | 眰 có bộ 目 (mục, mắt), gợi ý liên quan đến mắt hoặc thị giác. Cấu tạo chi tiết chưa được CHISE và Wiktionary phân tích. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điệt\": bộ 目 (mục, mắt) — chữ 眰 mang bộ mắt, gợi liên quan đến hành động hoặc trạng thái của mắt. | Gương Hán-Việt | điệt — ít dùng trong tiếng Việt | Mở khoá kiến thức | Biết 眰 giúp nhận diện chữ hiếm liên quan đến mắt trong văn bản cổ.", "Tự nguyên_Xie": "眰 có bộ 目 (mục, mắt). Wiktionary và CHISE không có phân tích cho chữ này. Nghĩa chính xác chưa được xác định trong nguồn học thuật. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "簰", "Hạng Tần Suất (Jun Da)": "6881.0", "Tần Suất % (Jun Da)": "99.996399558", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 至", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目至", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "至", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "眰", "Unihan_Traditional (Chữ Phồn thể)": "眰", "Pinyin_Xie": "diè", "Âm Hán Việt_Xie": "điệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ chỉ hành động nhìn hoặc liếc mắt trong văn bản cổ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('眳', '{"9000": "6882.0", "Chữ Trung Quốc": "眳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 11 | nét | 目 | mục | biểu nghĩa | mắt | 名 | danh | biểu âm | tên, danh tiếng | 眳 = 目 (Mục, biểu nghĩa: mắt) + 名 (Danh, biểu âm). Chữ hình thanh chỉ vùng da giữa lông mày và lông mi. Cũng có nghĩa: mắt mờ đục, không rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"minh\": 目 (mục, mắt) + 名 (danh, tên) — vùng \"minh\" trên mắt, nơi được \"đặt tên\" là khoảng giữa lông mày và mi. | Gương Hán-Việt | minh — liên âm với \"minh\" (sáng), nhưng nghĩa này chỉ vùng quanh mắt | Mở khoá kiến thức | Biết 眳 giúp đọc văn y học cổ truyền và thơ văn mô tả chi tiết về đôi mắt.", "Tự nguyên_Xie": "眳 là chữ hình thanh: 目 (mục, mắt) biểu nghĩa, 名 (danh) biểu âm. Nghĩa: vùng da giữa lông mày và lông mi; cũng chỉ trạng thái mắt mờ đục. Wiktionary xác nhận cấu tạo psc và các nghĩa này. Chữ cổ, ít dùng trong tiếng Trung hiện đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khoảng cách giữa lông mày và lông mi", "Hạng Tần Suất (Jun Da)": "6882.0", "Tần Suất % (Jun Da)": "99.9964036922", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 名", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目名", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "名", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "眳", "Unihan_Traditional (Chữ Phồn thể)": "眳", "Pinyin_Xie": "míng", "Âm Hán Việt_Xie": "danh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ bộ phận nhỏ trên khuôn mặt trong y học cổ truyền hoặc nhân tướng học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('矞', '{"9000": "6883.0", "Chữ Trung Quốc": "矞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 矛 | Số nét | 12 | nét | 矞 | duật | tượng hình | rực rỡ; sợ hãi; giả dối — chữ độc thể | 矞 là chữ phức hợp khó phân tích, bộ 矛 (mâu, giáo). Wiktionary chỉ ghi {{Han etym}} không chi tiết. Chữ đa nghĩa: rực rỡ, đẹp đẽ; sợ hãi; giả dối. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"duật\": chữ có hình dạng rực rỡ như bộ 矛 (mâu, giáo) — \"duật\" gợi sự lanh lợi, sắc bén nhưng cũng đáng sợ và đôi khi giả dối. | Gương Hán-Việt | duật — ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 矞 giúp đọc thơ văn cổ dùng chữ này để mô tả vẻ rực rỡ hoặc tính chất phức tạp.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 矞 mang nhiều nghĩa: rực rỡ, tốt đẹp; sợ hãi; giả dối. Có ở đại triện và tiểu triện. Wiktionary chỉ ghi {{Han etym}} mà không phân tích cấu tạo chi tiết. Chưa có nguồn học thuật về nguồn gốc chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1881.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mâu (080) Quýnh (023) Bát (010)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Phía trên là bộ Mâu (số 080 - cây giáo/ 矛), phía dưới là chữ Quýnh (số 023 - cửa sổ/sáng sủa/ 冏 - gồm bộ Quýnh 冂 và chữ Bát 八). Dùng mũi nhọn của cây mâu để đâm xuyên qua. Giải thích sự chuyển ý: Duật mang ý nghĩa là lấy cái mâu đâm xuyên qua. Nghĩa bóng của chữ Duật dùng để chỉ sự rực rỡ, tốt đẹp (tường duật - mây lành).", "Nghĩa Tiếng Việt_Xie": "rực rỡ, tốt đẹp; sợ hãi; giả dối", "Hạng Tần Suất (Jun Da)": "6883.0", "Tần Suất % (Jun Da)": "99.9964078265", "GavinGrover_Once (Chiết tự trực tiếp)": "矛 + 冏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱矛冏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "矛", "Unihan_Simplified (Chữ Giản thể)": "矞", "Unihan_Traditional (Chữ Phồn thể)": "矞", "Pinyin_Xie": "yù", "Âm Hán Việt_Xie": "duật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ bổ nghĩa cho danh từ để chỉ điềm lành hoặc vẻ rực rỡ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('硚', '{"9000": "6884.0", "Chữ Trung Quốc": "硚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 11 | nét | 硚 | kiều | tượng hình | giản thể của 礄, chỉ mố cầu/đầu cầu | 硚 là giản hoá của 礄 (喬→乔). Bộ 石 (thạch, đá), gợi ý liên quan đến đá/xây dựng. 礄頭/硚头 chỉ khu vực đầu cầu (kiều đầu) — tên địa danh nổi tiếng ở Hồng Kông.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiều\": bộ 石 (thạch, đá) — mố đá của \"kiều\" (cầu), nơi giao thông qua lại, như 硚头 ở Hồng Kông. | Gương Hán-Việt | kiều — trong 橋/硚 (kiều, cầu); 硚頭 (kiều đầu, đầu cầu/địa danh) | Mở khoá kiến thức | Biết 硚 giúp nhận diện địa danh 硚头 ở Hồng Kông và các chữ về xây dựng cầu.", "Tự nguyên_Xie": "硚 là dạng giản hoá của 礄 (喬→乔). Wiktionary xác nhận qua {{Han simp}}. 硚頭 (Kiều Đầu) là tên địa danh nổi tiếng ở Cửu Long, Hồng Kông. Bộ 石 (thạch, đá) chỉ vật liệu xây dựng cầu. Chữ chủ yếu dùng trong địa danh. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: kiều đầu 礄頭,硚头)", "Hạng Tần Suất (Jun Da)": "6884.0", "Tần Suất % (Jun Da)": "99.9964119608", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 乔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石乔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "硚", "Unihan_Traditional (Chữ Phồn thể)": "礄", "Pinyin_Xie": "qiáo", "Âm Hán Việt_Xie": "kiều", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong địa danh hoặc để chỉ loại cầu xây bằng đá. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('禋', '{"9000": "6885.0", "Chữ Trung Quốc": "禋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 13 | nét | 禋 | nhân | tượng hình | lễ tế trời thời cổ, chữ độc thể bộ 示 | 禋 có bộ 示 (thị, chỉ lễ nghi thần thánh). Nghĩa: lễ tế trời (sacrifice), nghi lễ cúng bái thời cổ. Cấu tạo chi tiết chưa được CHISE phân tích. Có giáp cốt văn, kim văn, tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhân\": bộ 示 (thị, lễ nghi) — lễ \"nhân\" là nghi thức thiêng liêng đốt hương tế trời, khói bay lên tận thiên đình. | Gương Hán-Việt | nhân — ít dùng trong tiếng Việt; liên quan đến lễ nghi cổ | Mở khoá kiến thức | Biết 禋 giúp đọc kinh thư, lễ ký mô tả các nghi lễ tế tự thời cổ đại.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Tiểu triện | Lục thư thông | 禋 là chữ chỉ nghi lễ tế trời trong thời cổ đại Trung Hoa. Bộ 示 (thị) biểu thị liên quan đến thần linh và lễ nghi. Wiktionary ghi nhận nghĩa sacrifice (nghi lễ cúng tế). Giáp cốt văn và kim văn còn ghi nhận — đây là chữ cổ xưa có lịch sử từ thời Ân Thương. Không cung cấp phân tích tự hình chi tiết. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lễ tế trời (thời xưa); cúng tế", "Hạng Tần Suất (Jun Da)": "6885.0", "Tần Suất % (Jun Da)": "99.9964160951", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "禋", "Unihan_Traditional (Chữ Phồn thể)": "禋", "Pinyin_Xie": "yīn", "Âm Hán Việt_Xie": "yên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ nghi thức cúng tế trời đất của hoàng đế thời xưa. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('翀', '{"9000": "6886.0", "Chữ Trung Quốc": "翀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羽 | Số nét | 10 | nét | 翀 | xung | tượng hình | bay vút thẳng lên, chữ độc thể bộ 羽 | 翀 có bộ 羽 (vũ, lông vũ/cánh chim), gợi ý chuyển động của chim. Nghĩa: bay thẳng lên cao (fly directly upward). Cấu tạo chi tiết chưa được CHISE phân tích.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xung\": bộ 羽 (vũ, cánh) — con chim \"xung\" thẳng lên như mũi tên, không chệch hướng, vút thẳng vào bầu trời cao. | Gương Hán-Việt | xung — trong \"xung thiên\" (bay lên tận trời), \"xung kích\" (tấn công thẳng) | Mở khoá kiến thức | Biết 翀 giúp hiểu thơ văn cổ điển mô tả hình ảnh chim bay cao hoặc khí phách anh hùng.", "Tự nguyên_Xie": "Lục thư thông | 翀 nghĩa là bay vút thẳng lên, chỉ chuyển động của chim hoặc tên lao vút lên cao. Wiktionary dẫn câu thơ: 鵠飛舉萬里，一飛翀昊蒼 (Thiên nga bay vạn dặm, vút thẳng lên bầu trời bao la). Bộ 羽 (vũ, cánh) biểu thị chuyển động bay. Chữ tạo muộn, chỉ còn ở Lục thư thông. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bay vút lên (chim)", "Hạng Tần Suất (Jun Da)": "6886.0", "Tần Suất % (Jun Da)": "99.9964202294", "GavinGrover_Once (Chiết tự trực tiếp)": "羽 + 中", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰羽中", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "中", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羽", "Unihan_Simplified (Chữ Giản thể)": "翀", "Unihan_Traditional (Chữ Phồn thể)": "翀", "Pinyin_Xie": "chōng", "Âm Hán Việt_Xie": "trưng, xung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ miêu tả tư thế bay thẳng lên cao của loài chim. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('苾', '{"9000": "6887.0", "Chữ Trung Quốc": "苾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 8 | nét | 苾 | bí | tượng hình | thơm tho, hương thơm, chữ độc thể bộ 艹 | 苾 có bộ 艹 (thảo, cỏ/thực vật), gợi ý mùi hương từ thực vật. Nghĩa: thơm tho, thơm ngát. Thường dùng trong 苾芻 (tên Phạn ngữ của nhà sư/tỳ kheo). Cấu tạo chi tiết chưa được CHISE phân tích.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bí\": bộ 艹 (thảo, cỏ) — bông hoa \"bí\" ẩn trong cỏ toả hương thơm ngát; 苾芻 là nhà sư mang hương đức hạnh. | Gương Hán-Việt | bí — trong 苾芻 (bí sô, tỳ kheo); liên quan đến 秘 (bí), 泌 (bí) | Mở khoá kiến thức | Biết 苾 giúp đọc kinh Phật và thơ văn cổ điển mô tả hương thơm và đức hạnh.", "Tự nguyên_Xie": "Tiểu triện | 苾 nghĩa là thơm tho, thường dùng trong văn học và Phật giáo. Hợp từ 苾芻/苾蒭 là phiên âm tiếng Phạn bhikṣu (tỳ kheo, tu sĩ Phật giáo nam). Bộ 艹 (thảo) gợi hương thơm từ cỏ cây. Wiktionary ghi nhận nghĩa fragrant/aromatic. Chưa có phân tích tự hình chi tiết. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thơm tho; thơm", "Hạng Tần Suất (Jun Da)": "6887.0", "Tần Suất % (Jun Da)": "99.9964243637", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 必", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹必", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "必", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "苾", "Unihan_Traditional (Chữ Phồn thể)": "苾", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "bật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ đứng trước danh từ để miêu tả mùi thơm của hoa cỏ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('襕', '{"9000": "6888.0", "Chữ Trung Quốc": "襕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 17 | nét | 襕 | lan | tượng hình | áo dài phủ kín, áo liền thân, chữ độc thể bộ 衣 | 襕 có bộ 衣 (y, áo), gợi ý loại y phục. Nghĩa: loại áo dài liền thân phủ kín từ vai đến chân, dùng trong trang phục lễ thời cổ đại Trung Hoa (thường dành cho học giả, quan lại). Cấu tạo chi tiết chưa được CHISE và Wiktionary phân tích.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lan\": bộ 衣 (y, áo) — áo \"lan\" phủ dài như lan can bao quanh, che kín từ vai xuống chân. | Gương Hán-Việt | lan — ít dùng trong tiếng Việt; xuất hiện trong văn bản về y phục cổ đại | Mở khoá kiến thức | Biết 襕 giúp đọc văn bản lịch sử về trang phục lễ của học giả, quan lại thời phong kiến.", "Tự nguyên_Xie": "襕 chỉ loại áo dài liền thân (full-length robe) thời cổ đại. Wiktionary không có entry. Bộ 衣 (y) biểu thị y phục. Áo 襕 thường được học giả và quan lại mặc trong các dịp lễ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "áo dài (thời xưa)", "Hạng Tần Suất (Jun Da)": "6888.0", "Tần Suất % (Jun Da)": "99.9964284979", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 阑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤阑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "阑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "襕", "Unihan_Traditional (Chữ Phồn thể)": "襴", "Pinyin_Xie": "lán", "Âm Hán Việt_Xie": "lan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ một loại trang phục truyền thống của nam giới thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('趥', '{"9000": "6889.0", "Chữ Trung Quốc": "趥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 走 | Số nét | 16 | nét | 趥 | thu | tượng hình | chữ bộ 走 (đi), nghĩa chưa xác định | 趥 có bộ 走 (tẩu, đi bộ, chạy), gợi ý liên quan đến chuyển động. Cấu tạo chi tiết chưa được CHISE phân tích. Wiktionary không cung cấp định nghĩa (rfdef). Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thu\": bộ 走 (tẩu, chạy) — chữ \"thu\" này mang dáng vẻ chuyển động, nghĩa cụ thể chưa được sách cổ ghi rõ. | Gương Hán-Việt | thu — ít dùng trong tiếng Việt | Mở khoá kiến thức | Biết 趥 giúp nhận diện chữ hiếm liên quan đến chuyển động trong văn bản cổ.", "Tự nguyên_Xie": "趥 có bộ 走 (tẩu, đi), gợi ý chuyển động. Wiktionary ghi nhận phát âm qiū/cù nhưng không có định nghĩa (rfdef). Chưa có nguồn học thuật về nghĩa và cấu tạo chính xác. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "襥", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "走 + 酋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴走酋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "酋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "走", "Unihan_Simplified (Chữ Giản thể)": "趥", "Unihan_Traditional (Chữ Phồn thể)": "趥", "Pinyin_Xie": "qiū", "Âm Hán Việt_Xie": "thu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường dùng làm động từ chỉ hành động đi nhanh hoặc thu dọn đồ đạc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('茺', '{"9000": "6890.0", "Chữ Trung Quốc": "茺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 茺 | súng | tượng hình | cây ích mẫu (Leonurus), bộ 艹 | 茺 có bộ 艹 (thảo, cỏ/thực vật), chỉ tên một loài thực vật. Xuất hiện trong 茺蔚/茺尉, tên cổ của cây ích mẫu (Leonurus japonicus), thảo dược quan trọng trong y học cổ truyền. Cấu tạo chi tiết chưa được CHISE phân tích.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"súng\": bộ 艹 (thảo, cây) — cây \"súng\" ích mẫu trong 茺蔚, loài thảo dược quý cho phụ nữ. | Gương Hán-Việt | súng — trong 茺蔚 (súng uý, cây ích mẫu) | Mở khoá kiến thức | Biết 茺 giúp đọc tài liệu y học cổ truyền về cây ích mẫu (益母草).", "Tự nguyên_Xie": "茺chủ yếu xuất hiện trong 茺蔚 (súng uý), tên cổ của cây ích mẫu (益母草, Leonurus japonicus). Wiktionary không có entry. Bộ 艹 chỉ đây là thực vật. Trong y học cổ truyền, cây này dùng chữa bệnh phụ khoa. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: sung uý 茺尉)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 充", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹充", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "充", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "茺", "Unihan_Traditional (Chữ Phồn thể)": "茺", "Pinyin_Xie": "chōng", "Âm Hán Việt_Xie": "sung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ trong tên gọi thảo dược như súng úy tức cây ích mẫu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('軿', '{"9000": "6891.0", "Chữ Trung Quốc": "軿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 13 | nét | 軿 | bánh | tượng hình | xe có mui che, xe bịt bạt, chữ độc thể bộ 車 | 軿 có bộ 車 (xa, xe), gợi ý loại phương tiện. Nghĩa: xe có mui hoặc màn che (curtained carriage), loại xe sang trọng thời cổ đại. Cấu tạo chi tiết chưa được CHISE phân tích.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bánh\": bộ 車 (xa, xe) — cái xe \"bánh\" (xe bình — bằng phẳng, có mui che), loại xe sang trọng của quý tộc thời xưa. | Gương Hán-Việt | bánh — trong 軿 (bánh, xe có mui); liên âm với 餅 (bánh, bánh bao) | Mở khoá kiến thức | Biết 軿 giúp đọc văn học cổ điển mô tả cảnh vật và phương tiện đi lại của quý tộc.", "Tự nguyên_Xie": "軿 chỉ loại xe có mui/màn che, thường dùng cho phụ nữ quý tộc thời cổ đại. Wiktionary ghi nhận phát âm nhưng không định nghĩa (rfdef). Bộ 車 (xa) biểu thị xe cộ. Chữ hiếm dùng trong văn bản hiện đại. Chưa có nguồn học thuật về cấu tạo chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xe có mui; xe có bạt che", "Hạng Tần Suất (Jun Da)": "6891.0", "Tần Suất % (Jun Da)": "99.9964409008", "GavinGrover_Once (Chiết tự trực tiếp)": "車 + 并", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰車并", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "并", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "車", "Unihan_Simplified (Chữ Giản thể)": "軿", "Unihan_Traditional (Chữ Phồn thể)": "軿", "Pinyin_Xie": "píng", "Âm Hán Việt_Xie": "bình", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này đóng vai trò danh từ chỉ loại xe cổ có mui che kín dành cho phụ nữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('逌', '{"9000": "6892.0", "Chữ Trung Quốc": "逌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 10 | nét | 逌 | du | tượng hình | có vẻ tự đắc, hài lòng, chữ độc thể bộ 辶 | 逌 có bộ 辶 (sước/chước, đi lại), gợi ý chuyển động hoặc thái độ. Nghĩa: có vẻ tự đắc, hài lòng với bản thân. Có nhiều dạng trong kim văn và giáp cốt. Cấu tạo chi tiết chưa được Wiktionary phân tích.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"du\": bộ 辶 (đi lại) — người \"du\" dạo bước với thái độ tự mãn, hài lòng với mình. | Gương Hán-Việt | du — liên âm với \"du\" (dạo chơi, nhàn du) | Mở khoá kiến thức | Biết 逌 giúp nhận diện chữ hiếm chỉ thái độ tự mãn trong văn bản cổ điển.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Lục thư thông | 逌 có rất nhiều dạng viết trong kim văn (14 dạng) và giáp cốt văn, cho thấy chữ này có lịch sử lâu đời. Wiktionary không có entry. Bộ 辶 gợi ý chuyển động tâm lý — thái độ tự đắc, hài lòng. Chưa có nguồn học thuật về cấu tạo và nghĩa chính xác. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "có vẻ tự đắc", "Hạng Tần Suất (Jun Da)": "6892.0", "Tần Suất % (Jun Da)": "99.9964450351", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 卣", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶卣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卣", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "逌", "Unihan_Traditional (Chữ Phồn thể)": "逌", "Pinyin_Xie": "yōu", "Âm Hán Việt_Xie": "do, du", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Phó từ | 副词 | Chữ này thường làm tính từ hoặc phó từ mô tả trạng thái ung dung tự tại hoặc tự mãn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('唪', '{"9000": "6893.0", "Chữ Trung Quốc": "唪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 11 | nét | 唪 | phụng | tượng hình | cười to, tiếng cười lớn, bộ 口 | 唪 có bộ 口 (khẩu, miệng), gợi ý âm thanh phát ra. Nghĩa: cười to, phát ra tiếng cười lớn. Cấu tạo chi tiết chưa được CHISE phân tích. Tiểu triện còn ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phụng\": bộ 口 (khẩu, miệng) — tiếng \"phụng\" cười vang lên, to và rõ như phụng hoàng hót. | Gương Hán-Việt | phụng — liên âm với 奉 (phụng, dâng), 鳳 (phụng, phụng hoàng) | Mở khoá kiến thức | Biết 唪 giúp đọc văn học cổ mô tả cảnh cười đùa, vui vẻ.", "Tự nguyên_Xie": "Tiểu triện | 唪 nghĩa là cười to, phát ra tiếng cười lớn. Bộ 口 (khẩu, miệng) biểu thị hành động phát âm qua miệng. Wiktionary chỉ ghi {{Han etym}} không phân tích. Tiểu triện còn ghi nhận dạng chữ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cười to", "Hạng Tần Suất (Jun Da)": "6893.0", "Tần Suất % (Jun Da)": "99.9964491693", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 奉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口奉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "唪", "Unihan_Traditional (Chữ Phồn thể)": "唪", "Pinyin_Xie": "fěng", "Âm Hán Việt_Xie": "phủng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường dùng làm động từ chỉ hành động tụng kinh niệm Phật hoặc cười lớn tiếng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('庳', '{"9000": "6894.0", "Chữ Trung Quốc": "庳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 广 | Số nét | 11 | nét | 庳 | tỳ | tượng hình | thấp lún, nơi thấp, chữ độc thể bộ 广 | 庳 có bộ 广 (nghiễm, mái nhà rộng/tòa nhà), gợi ý liên quan đến kiến trúc, địa hình. Nghĩa: thấp lún, nhà thấp lún ở giữa; cũng là tên nước cổ Hữu Tỳ (有庳) ở Hồ Nam. Cấu tạo chi tiết chưa được CHISE phân tích.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tỳ\": bộ 广 (nghiễm, nhà) — ngôi nhà \"tỳ\" (tì) thấp, lún xuống đất, địa thế trũng thấp. | Gương Hán-Việt | tỳ — ít dùng trong tiếng Việt hiện đại; liên âm với 脾 (tỳ vị), 婢 (tỳ nữ) | Mở khoá kiến thức | Biết 庳 giúp đọc văn bản địa lý và lịch sử mô tả địa hình trũng thấp hoặc nước Hữu Tỳ.", "Tự nguyên_Xie": "Tiểu triện | 庳 có ba âm đọc và nghĩa: (1) bì — thấp lún, nơi địa thế thấp; (2) bì — nước Hữu Tỳ (有庳) cổ đại ở Hồ Nam; (3) pí — chim cút cái; cũng là dị thể của 毗 (giúp đỡ). Wiktionary cung cấp đầy đủ nghĩa. Bộ 广 (nghiễm) chỉ kiến trúc/địa điểm. Có tiểu triện ghi nhận. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thấp hẹp; nước Bí", "Hạng Tần Suất (Jun Da)": "6894.0", "Tần Suất % (Jun Da)": "99.9964533036", "GavinGrover_Once (Chiết tự trực tiếp)": "广 + 卑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴广卑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "广", "Unihan_Simplified (Chữ Giản thể)": "庳", "Unihan_Traditional (Chữ Phồn thể)": "庳", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "bí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này thường dùng làm tính từ để miêu tả nhà cửa thấp bé hoặc địa thế hẹp. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('殪', '{"9000": "6895.0", "Chữ Trung Quốc": "殪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 歹 | Số nét | 16 | nét | 殪 | ế | tượng hình | giết chết; chết; diệt — chữ độc thể bộ 歹 | 殪 có bộ 歹 (đãi, xương chết, chỉ chết chóc). Nghĩa: giết chết, tiêu diệt, hoặc chết (trong văn cổ). Cấu tạo chi tiết chưa được CHISE phân tích.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ế\": bộ 歹 (đãi, xương tàn) — kẻ thù bị \"ế\" (hết, tắt) trong trận chiến, bị diệt một mũi tên. | Gương Hán-Việt | ế — trong \"ế ẩm\" (ế hàng, không bán được); nghĩa gốc: hết, tắt, chết | Mở khoá kiến thức | Biết 殪 giúp đọc sử ký, chiến ký Trung Hoa cổ đại mô tả cảnh chém giết.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 殪 nghĩa là giết chết, tiêu diệt (to kill, exterminate) hoặc chết trong văn ngôn cổ điển. Một nghĩa đặc biệt: bắn chết bằng một mũi tên. Bộ 歹 (đãi) biểu thị cái chết, xương tàn. Wiktionary ghi nhận đầy đủ. Có tiểu triện và Lục thư thông. Liên quan âm Hán-Việt với 噎 (nghẹn). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chết, giết", "Hạng Tần Suất (Jun Da)": "6895.0", "Tần Suất % (Jun Da)": "99.9964574379", "GavinGrover_Once (Chiết tự trực tiếp)": "歹 + 壹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰歹壹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "壹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "歹", "Unihan_Simplified (Chữ Giản thể)": "殪", "Unihan_Traditional (Chữ Phồn thể)": "殪", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "ế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thể hiện hành động tiêu diệt hoàn toàn hoặc bị làm cho chết. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('隃', '{"9000": "6896.0", "Chữ Trung Quốc": "隃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 11 | nét | 隃 | du | tượng hình | tên núi cổ; vượt qua; xa — bộ 阝 | 隃 có bộ 阝 (phụ, đất cao/đồi). Đa âm: shù (tên núi Tây Vu), yú (vượt qua, dị thể của 踰; tên nước 隃麋), yáo (dị thể của 遙, xa). Cấu tạo chi tiết chưa được CHISE phân tích.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"du\": bộ 阝 (phụ, đất cao) — núi 隃 cao vút, cần phải \"du\" (vượt qua) để đến đích xa xôi. | Gương Hán-Việt | du — trong \"du hành\", \"du ngoạn\"; nghĩa gốc liên quan đến vượt qua/xa xôi | Mở khoá kiến thức | Biết 隃 giúp đọc văn bản địa lý và sử ký cổ đại về các núi và địa danh Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | 隃 là chữ đa âm đa nghĩa: (1) shù — tên núi cổ Tây Vu (西隃); (2) yú — vượt qua (dị thể 踰), hoặc tên nước 隃麋; (3) yáo — xa xôi (dị thể 遙). Bộ 阝 (phụ) chỉ đất cao, địa danh. Wiktionary cung cấp đầy đủ. Có tiểu triện. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên đất)", "Hạng Tần Suất (Jun Da)": "6896.0", "Tần Suất % (Jun Da)": "99.9964615722", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + 俞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝俞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "俞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "隃", "Unihan_Traditional (Chữ Phồn thể)": "隃", "Pinyin_Xie": "shù", "Âm Hán Việt_Xie": "du", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này dùng làm động từ chỉ sự vượt qua hoặc làm danh từ riêng chỉ địa danh cổ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('糈', '{"9000": "6897.0", "Chữ Trung Quốc": "糈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 15 | nét | 糈 | tư | tượng hình | gạo ngon dùng cúng tế; tư lương — bộ 米 | 糈 có bộ 米 (mễ, gạo), gợi ý liên quan đến thóc gạo. Nghĩa: gạo ngon dùng trong lễ cúng tế, hoặc tư lương (lương thực dự trữ). Cấu tạo chi tiết chưa được CHISE phân tích.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tư\": bộ 米 (mễ, gạo) — gạo \"tư\" ngon nhất dùng để cúng tế, giống như \"tư lương\" dự trữ cho chuyến dài. | Gương Hán-Việt | tư — liên âm với \"tư lương\" (lương thực dự trữ), \"tư\" trong Sở từ cổ điển | Mở khoá kiến thức | Biết 糈 giúp đọc Sở từ và văn bản lễ nghi cổ đại đề cập đến gạo cúng tế.", "Tự nguyên_Xie": "Tiểu triện | 糈 chỉ loại gạo ngon dùng trong lễ cúng tế thần linh, hoặc gạo dự trữ làm tư lương. Wiktionary chỉ ghi {{Han etym}} không phân tích. Bộ 米 (mễ) biểu thị gạo. Có tiểu triện ghi nhận. Chữ thuộc ngữ cảnh lễ nghi và nông nghiệp cổ đại. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tư lương; gạo ngon", "Hạng Tần Suất (Jun Da)": "6897.0", "Tần Suất % (Jun Da)": "99.9964657065", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 胥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米胥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "胥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "糈", "Unihan_Traditional (Chữ Phồn thể)": "糈", "Pinyin_Xie": "xǔ", "Âm Hán Việt_Xie": "tư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ lương thực hoặc lễ vật bằng gạo trong văn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲄', '{"9000": "6898.0", "Chữ Trung Quốc": "鲄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 13 | nét | 鲄 | hà | tượng hình | tên loài cá, giản thể của 魺 | 鲄 là giản hoá của 魺 (魚→鱼). Bộ 鱼 (ngư, cá), gợi ý loài cá. Nghĩa: một loài cá nhỏ (theo 爾雅). Cấu tạo chi tiết chưa được CHISE phân tích.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hà\": bộ 鱼 (ngư, cá) — chữ 鲄 là \"hà\" (cá sông Hà?), loài cá nhỏ ghi trong sách Nhĩ Nhã cổ đại. | Gương Hán-Việt | hà — liên âm với 河 (hà, sông), 荷 (hà, hoa sen) | Mở khoá kiến thức | Biết 鲄 giúp nhận diện chữ cá cổ trong văn bản ngư nghiệp và sách Nhĩ Nhã.", "Tự nguyên_Xie": "鲄 là dạng giản hoá của 魺 (魚→鱼). Wiktionary xác nhận qua {{Han simp}}. 魺 theo 爾雅 chỉ một loại cá (nhỏ). Bộ 鱼 (ngư) biểu thị loài cá. Chưa có phân tích tự hình chi tiết về 魺. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鲲", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 可", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼可", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "可", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲄", "Unihan_Traditional (Chữ Phồn thể)": "鲄", "Pinyin_Xie": "hé", "Âm Hán Việt_Xie": "hà", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ để chỉ một loài cá nhỏ theo cách gọi cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('碕', '{"9000": "6899.0", "Chữ Trung Quốc": "碕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 13 | nét | 碕 | kỳ | tượng hình | bờ đá gồ ghề, mỏm đá, bộ 石 | 碕 có bộ 石 (thạch, đá), gợi ý địa hình đá. Nghĩa: mỏm đá bên bờ nước, bờ đá gồ ghề. Cấu tạo chi tiết chưa được CHISE phân tích. Wiktionary chỉ ghi {{Han etym}}.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kỳ\": bộ 石 (thạch, đá) — mỏm đá \"kỳ\" (kỳ lạ) nhô ra mặt nước, tạo nên cảnh quan \"kỳ\" vĩ bên bờ. | Gương Hán-Việt | kỳ — trong \"kỳ lạ\", \"kỳ quan\"; nghĩa gốc liên quan đến hình dạng đặc biệt | Mở khoá kiến thức | Biết 碕 giúp đọc văn thơ mô tả địa hình đá ven sông suối.", "Tự nguyên_Xie": "碕 chỉ mỏm đá hoặc bờ đá gồ ghề ven sông/biển. Bộ 石 (thạch) biểu thị đá. Wiktionary chỉ ghi {{Han etym}} không phân tích. Tiểu triện không có. Chưa có nguồn học thuật về cấu tạo chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "畕", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 奇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石奇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "碕", "Unihan_Traditional (Chữ Phồn thể)": "碕", "Pinyin_Xie": "qí", "Âm Hán Việt_Xie": "kỳ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này dùng làm danh từ chỉ bờ đá ven sông hoặc tính từ tả địa hình gồ ghề. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲣', '{"9000": "6900.0", "Chữ Trung Quốc": "鲣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 15 | nét | 魚 | ngư | biểu nghĩa | cá | 堅 | kiên | biểu âm | cứng rắn, kiên định | 鲣 = 魚 (Ngư, biểu nghĩa: cá) + 堅 (Kiên, biểu âm). Chữ hình thanh chỉ loài cá ngừ skipjack (Katsuwonus pelamis). Phồn thể: 鰹.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiên\": 魚 (ngư, cá) + 堅 (kiên, cứng) — cá 鲣 thịt \"kiên\" chắc, là loài cá ngừ vằn mạnh mẽ dưới biển. | Gương Hán-Việt | kiên — trong \"kiên cường\", \"kiên định\"; nghĩa cá chắc thịt liên quan đến 堅 | Mở khoá kiến thức | Biết 鲣 giúp nhận diện loài cá ngừ skipjack trong văn bản ẩm thực và ngư nghiệp.", "Tự nguyên_Xie": "鲣 (phồn thể: 鰹) là chữ hình thanh: 魚 (ngư, cá) biểu nghĩa, 堅 (kiên) biểu âm. Chỉ loài cá ngừ skipjack (cá ngừ vằn, Katsuwonus pelamis). Wiktionary xác nhận cấu tạo và nghĩa. Hợp từ: 鰹魚 (jiān yú, cá ngừ), 鰹鳥 (chim điên biển ăn cá ngừ). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá ngừ", "Hạng Tần Suất (Jun Da)": "6900.0", "Tần Suất % (Jun Da)": "99.9964822436", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 坚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼坚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "坚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲣", "Unihan_Traditional (Chữ Phồn thể)": "鰹", "Pinyin_Xie": "jiān", "Âm Hán Việt_Xie": "kiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài cá biển, thường dùng trong danh từ ghép chỉ tên cá. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('綎', '{"9000": "6901.0", "Chữ Trung Quốc": "綎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 12 | nét | 綎 | đình | tượng hình | dây bện lụa, dải lụa, bộ 糸 | 綎 có bộ 糸 (mịch, sợi tơ/lụa), gợi ý liên quan đến vải/tơ lụa. Nghĩa: dây bện bằng lụa, dải lụa trang trí. Cấu tạo chi tiết chưa được CHISE phân tích. Có tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đình\": bộ 糸 (mịch, tơ lụa) — sợi tơ \"đình\" (kéo dài, đình thẳng) bện thành dải lụa trang trí. | Gương Hán-Việt | đình — liên âm với 廷 (đình, triều đình), 庭 (đình, sân nhà) | Mở khoá kiến thức | Biết 綎 giúp đọc văn bản cổ về trang phục và dệt lụa Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | 綎 chỉ loại dây bện hoặc dải làm bằng tơ lụa, thường dùng trong trang phục và đồ trang trí. Wiktionary ghi nhận phát âm nhưng không định nghĩa (rfdef). Bộ 糸 (mịch, tơ) biểu thị vật liệu lụa. Có tiểu triện ghi nhận. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dây bện lụa", "Hạng Tần Suất (Jun Da)": "6901.0", "Tần Suất % (Jun Da)": "99.9964863779", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 廷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹廷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "廷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "綎", "Unihan_Traditional (Chữ Phồn thể)": "綎", "Pinyin_Xie": "tīng", "Âm Hán Việt_Xie": "đinh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ sợi dây lụa bện, thường xuất hiện trong văn bản cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('栝', '{"9000": "6902.0", "Chữ Trung Quốc": "栝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 10 | nét | 木 | mộc | biểu nghĩa | cây, gỗ | 𠯑 | quát | biểu âm | (phần biểu âm, nay viết gần với 括) | 栝 = 木 (Mộc, biểu nghĩa: cây gỗ) + 𠯑 (biểu âm); chữ hình thanh. Bộ 木 cho biết đây là loại cây; phần còn lại cung cấp âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quát\": 木 (cây) + âm quát → cây quát, loại gỗ dùng làm tên và dụng cụ nắn gỗ. | Gương Hán-Việt | quát trong \"cây quát\" — tên cổ cho cây bách Juniperus | Mở khoá kiến thức | Biết 栝 mở khoá từ 栝樓 (tên cây thuốc), 機栝 (bộ phận kích phát), 檃栝 (chỉnh nắn).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 栝 là chữ hình thanh: bộ 木 (mộc — cây gỗ) làm phần biểu nghĩa, 𠯑 làm phần biểu âm (tương đương 括). Chữ chỉ cây bách hương Juniperus chinensis (tức cây cối), phần đuôi mũi tên (nock), và dụng cụ nắn thẳng gỗ. Cũng dùng trong từ 栝樓 (tên một loài dây leo dược liệu). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây quát, cây cối", "Hạng Tần Suất (Jun Da)": "6902.0", "Tần Suất % (Jun Da)": "99.9964905122", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 舌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木舌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "舌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "栝", "Unihan_Traditional (Chữ Phồn thể)": "栝", "Pinyin_Xie": "guā", "Âm Hán Việt_Xie": "quát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại cây thuộc họ bách hoặc dùng làm dụng cụ đo thẳng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('轵', '{"9000": "6903.0", "Chữ Trung Quốc": "轵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 9 | nét | 車 | xa | biểu nghĩa | xe, cỗ xe | 只 | chỉ | biểu âm | (biểu âm) | 轵 = 車 (Xa, biểu nghĩa: xe) + 只 (Chỉ, biểu âm); chữ hình thanh. Bộ 車 cho biết liên quan đến xe; 只 cung cấp âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chỉ\": 車 (xe) + 只 (chỉ, âm) → đầu trục xe, phần chỉ ra ngoài bánh xe. | Gương Hán-Việt | chỉ trong \"trục chỉ\" — đầu mút trục xe cổ | Mở khoá kiến thức | Biết 轵 giúp đọc văn bản cổ về cấu tạo xe ngựa và địa danh lịch sử Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 轵 (dạng phồn thể 軹) là chữ hình thanh: bộ 車 (xa — xe) biểu nghĩa, 只 (chỉ) biểu âm. Chữ chỉ đầu mút của trục bánh xe — phần nhô ra ngoài bánh xe của cỗ xe cổ đại. Cũng xuất hiện trong địa danh 軹道 (Zhidao) và 軹城. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đầu trục xe; đường rẽ", "Hạng Tần Suất (Jun Da)": "6903.0", "Tần Suất % (Jun Da)": "99.9964946464", "GavinGrover_Once (Chiết tự trực tiếp)": "车 + 只", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰车只", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "只", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "车", "Unihan_Simplified (Chữ Giản thể)": "轵", "Unihan_Traditional (Chữ Phồn thể)": "軹", "Pinyin_Xie": "zhǐ", "Âm Hán Việt_Xie": "chỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bộ phận đầu trục bánh xe hoặc lối rẽ trên đường. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('雔', '{"9000": "6904.0", "Chữ Trung Quốc": "雔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 隹 | Số nét | 16 | nét | 隹 | chuy | tượng hình | chim đuôi ngắn | 隹 | chuy | tượng hình | chim đuôi ngắn (lặp đôi) | 雔 = 隹 + 隹 (hai con chim Chuy ghép đôi); chữ hội ý — hai con chim đứng cạnh nhau biểu thị ý nghĩa \"một đôi chim\". Đây là kiểu nhân đôi ký tự tạo nghĩa ghép đôi, tương tự 林 (hai cây = rừng).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thù\": hai chim 隹+隹 đứng sát nhau → một đôi chim, ý \"thù địch\" hay \"sánh đôi\" đều xuất phát từ hình ảnh hai cá thể đối diện. | Gương Hán-Việt | thù trong \"đối thù\" hay \"thù địch\" — gốc nghĩa là hai bên đối nhau | Mở khoá kiến thức | Biết 雔 giúp hiểu nguồn gốc của 讎 (thù — kẻ thù) và 酬 (thù — đáp lễ), đều chứa âm-nghĩa từ hai cá thể đối nhau.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 雔 là chữ nhân đôi từ 隹 (chuy — chim đuôi ngắn): hai chữ 隹 ghép lại biểu thị một đôi chim. Nghĩa gốc là \"một đôi chim\", mở rộng thành \"sánh đôi, phối hợp\". Kiểu cấu tạo này phổ biến trong chữ Hán cổ (林, 森, 磊...). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "锛", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "隹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴隹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "雔", "Unihan_Traditional (Chữ Phồn thể)": "雔", "Pinyin_Xie": "chóu", "Âm Hán Việt_Xie": "thù", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ cặp chim hoặc động từ chỉ sự so sánh, đối chiếu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('頠', '{"9000": "6905.0", "Chữ Trung Quốc": "頠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 頁 | Số nét | 15 | nét | 頠 | nguy | tượng hình | (độc thể, tự thân là bộ thủ) | 頠 là chữ độc thể có bộ 頁 (hiệt — đầu người). Wiktionary không ghi cấu trúc phân tích rõ ràng; chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Nghĩa: yên tĩnh, thành thạo — liên quan đến vẻ bình thản trên khuôn mặt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nguy\": bộ 頁 (đầu người) → khuôn mặt bình thản, nguy nga, yên tĩnh như người đang tĩnh tọa. | Gương Hán-Việt | nguy trong văn cổ — khuôn mặt yên tĩnh, bình thản | Mở khoá kiến thức | Biết 頠 giúp đọc văn bản Hán cổ miêu tả thái độ bình thản, điềm tĩnh.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 頠 thuộc bộ 頁 (hiệt — đầu), nhưng không cung cấp phân tích cấu tạo chi tiết. Chữ tạo muộn, chỉ xuất hiện trong văn bản cổ với nghĩa \"yên tĩnh, bình thản\". Chưa có nguồn học thuật giải thích cụ thể cấu trúc biểu âm hay biểu nghĩa. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "yên tĩnh; thành thạo", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "危 + 頁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰危頁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "危", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "頁", "Unihan_Simplified (Chữ Giản thể)": "𬱟", "Unihan_Traditional (Chữ Phồn thể)": "頠", "Pinyin_Xie": "wěi", "Âm Hán Việt_Xie": "ngỗi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ miêu tả dáng vẻ ung dung, nhàn nhã hoặc trạng thái yên tĩnh. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('穈', '{"9000": "6906.0", "Chữ Trung Quốc": "穈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 16 | nét | 穈 | muội | tượng hình | (độc thể, bộ 禾) | 穈 thuộc bộ 禾 (hoà — cây lúa), là chữ hiếm chỉ loại kê/lúa mầm đỏ. Không có phân tích cấu tạo từ Wiktionary; chữ tạo muộn, chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"muội\": bộ 禾 (lúa) → loại lúa mầm đỏ, muội lúa — cây ngũ cốc sắc hồng đỏ. | Gương Hán-Việt | muội trong \"lúa muội\" — giống lúa kê đỏ cổ đại | Mở khoá kiến thức | Biết 穈 giúp đọc văn bản nông nghiệp cổ Trung Hoa về các giống lúa kê.", "Tự nguyên_Xie": "Không tìm thấy phân tích nguồn gốc từ Wiktionary cho 穈. Bộ 禾 (hoà — cây lúa, kê) cho biết đây là loại ngũ cốc; nghĩa cụ thể là lúa mầm đỏ hoặc kê đỏ. Chưa có nguồn học thuật giải thích cụ thể. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lúa mầm đỏ", "Hạng Tần Suất (Jun Da)": "6906.0", "Tần Suất % (Jun Da)": "99.9965070493", "GavinGrover_Once (Chiết tự trực tiếp)": "麻 + 禾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴麻禾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "禾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "麻", "Unihan_Simplified (Chữ Giản thể)": "穈", "Unihan_Traditional (Chữ Phồn thể)": "穈", "Pinyin_Xie": "méi", "Âm Hán Việt_Xie": "my", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một giống lúa kê hạt màu đỏ thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('翃', '{"9000": "6907.0", "Chữ Trung Quốc": "翃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羽 | Số nét | 10 | nét | 翃 | hoằng | tượng hình | (độc thể, bộ 羽) | 翃 thuộc bộ 羽 (vũ — lông vũ, cánh), là chữ cổ chỉ động tác bay. Wiktionary không cung cấp phân tích cấu trúc; chữ tạo muộn. Bộ 羽 xác nhận liên hệ với cánh chim.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoằng\": bộ 羽 (cánh lông) → bay lượn hoằng hoặc — cánh rộng vươn lên trời. | Gương Hán-Việt | hoằng trong văn cổ — bay lượn, dùng rất hiếm | Mở khoá kiến thức | Biết 翃 giúp nhận diện chữ cổ chỉ động tác bay trong thơ phú Hán cổ.", "Tự nguyên_Xie": "Wiktionary ghi 翃 có nghĩa \"bay\" (obs-std — dạng cổ không còn dùng chuẩn), thuộc bộ 羽. Không có phân tích thêm về cấu trúc biểu âm hay biểu nghĩa. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bay", "Hạng Tần Suất (Jun Da)": "6907.0", "Tần Suất % (Jun Da)": "99.9965111836", "GavinGrover_Once (Chiết tự trực tiếp)": "厷 + 羽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰厷羽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "厷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羽", "Unihan_Simplified (Chữ Giản thể)": "翃", "Unihan_Traditional (Chữ Phồn thể)": "翃", "Pinyin_Xie": "hóng", "Âm Hán Việt_Xie": "hồng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ miêu tả động tác bay lượn của chim muông hoặc côn trùng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('膭', '{"9000": "6908.0", "Chữ Trung Quốc": "膭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 16 | nét | 膭 | quý | tượng hình | (độc thể, bộ 肉) | 膭 thuộc bộ 肉/月 (nhục — thịt, cơ thể). Wiktionary không có mục từ cho 膭; nghĩa chưa được xác định rõ. Chữ tạo muộn, chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quý\": bộ 肉 (thịt, cơ thể) → phần thịt gì đó quý hiếm, chưa rõ nghĩa cụ thể trong văn liệu hiện đại. | Gương Hán-Việt | quý trong văn cổ — chữ rất hiếm, chưa có từ ghép thông dụng | Mở khoá kiến thức | Biết 膭 giúp nhận diện chữ hiếm trong bộ 肉 khi đọc tự điển Hán cổ.", "Tự nguyên_Xie": "Không tìm thấy phân tích nguồn gốc từ Wiktionary cho 膭. Bộ 肉 (nhục — thịt) cho biết có liên quan đến cơ thể người hoặc động vật. Nghĩa cụ thể chưa rõ; chưa có nguồn học thuật. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "譭", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 貴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月貴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "貴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "膭", "Unihan_Traditional (Chữ Phồn thể)": "膭", "Pinyin_Xie": "guī", "Âm Hán Việt_Xie": "quý", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ miêu tả trạng thái béo phì hoặc phần bụng to ra. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('衒', '{"9000": "6909.0", "Chữ Trung Quốc": "衒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 行 | Số nét | 11 | nét | 行 | hàng | biểu nghĩa | đường đi, hành động | 玄 | huyền | biểu âm | (biểu âm) | 衒 = 行 (Hàng, biểu nghĩa: đường đi, hành động) + 玄 (Huyền, biểu âm); chữ hình thanh. Bộ 行 cho biết liên quan đến hành động, đi lại; 玄 cung cấp âm đọc. Hàm ý đi khoe — tự phô trương khi đi ra ngoài.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huyễn\": 行 (đi, hành động) + 玄 (huyền, âm) → đi khoe — huyễn hoặc, tự phô trương trên đường. | Gương Hán-Việt | huyễn trong \"huyễn hoặc\" — phô trương, khoe mẽ tạo ảo tưởng | Mở khoá kiến thức | Biết 衒 mở khoá 衒耀 (khoe khoang), 自衒 (tự phô trương), 衒材揚己 (khoe tài tự đề cao).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 衒 là chữ hình thanh: bộ 行 (hàng — đường đi, hành động) biểu nghĩa, 玄 (huyền) biểu âm. Nghĩa là tự khoe khoang, phô trương bản thân. Các từ phái sinh như 衒耀 (khoe khoang), 自衒 (tự phô trương) phản ánh nghĩa gốc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tự khoe mình", "Hạng Tần Suất (Jun Da)": "6909.0", "Tần Suất % (Jun Da)": "99.9965194521", "GavinGrover_Once (Chiết tự trực tiếp)": "行 + 玄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴行玄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "玄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "行", "Unihan_Simplified (Chữ Giản thể)": "衒", "Unihan_Traditional (Chữ Phồn thể)": "衒", "Pinyin_Xie": "xuàn", "Âm Hán Việt_Xie": "huyễn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành vi tự phô trương bản thân hoặc rao bán hàng hóa. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('盇', '{"9000": "6910.0", "Chữ Trung Quốc": "盇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 皿 | Số nét | 9 | nét | 盇 | hạp | tượng hình | (độc thể, bộ 皿) | 盇 thuộc bộ 皿 (mãnh — chén đĩa, đồ đựng). Không có phân tích cấu tạo từ Wiktionary. Có lẽ là chữ hội ý từ 大 (to) + 皿 (chén) hoặc dạng cổ của 蓋/盍 (nắp đậy, sao không). Chữ tạo muộn, chưa có nguồn học thuật chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hạp\": bộ 皿 (chén đĩa) → nắp hạp, đậy lại — hoặc câu hỏi cổ \"sao không đậy lại?\" | Gương Hán-Việt | hạp trong \"hạp lại\" — đậy nắp, đóng lại; hoặc hạp trong câu nghi vấn cổ | Mở khoá kiến thức | Biết 盇 giúp nhận biết biến thể cổ của 盍 khi đọc văn bản Hán cổ.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Không tìm thấy phân tích nguồn gốc rõ ràng từ Wiktionary cho 盇. Bộ 皿 (mãnh — chén, đồ đựng) gợi ý liên quan đến vật chứa. Chữ có thể là biến thể cổ của 盍 (hạp — sao không, tại sao không) hoặc 蓋 (cái — nắp đậy). Chưa có nguồn học thuật. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sao, sao chẳng (câu hỏi); cánh cửa", "Hạng Tần Suất (Jun Da)": "5560.0", "Tần Suất % (Jun Da)": "99.9633651018", "GavinGrover_Once (Chiết tự trực tiếp)": "太 + 皿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱太皿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "太", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "皿", "Unihan_Simplified (Chữ Giản thể)": "盍", "Unihan_Traditional (Chữ Phồn thể)": "盇", "Pinyin_Xie": "hé", "Âm Hán Việt_Xie": "hạp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Danh từ | 名词 | Chữ này làm phó từ nghi vấn dùng để hỏi nguyên nhân hoặc làm danh từ chỉ cái nắp đậy. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('譢', '{"9000": "6911.0", "Chữ Trung Quốc": "譢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 19 | nét | 譢 | tuệ | tượng hình | (độc thể, bộ 言) | 譢 thuộc bộ 言 (ngôn — lời nói, ngôn ngữ). Wiktionary ghi nhận nhưng không cung cấp định nghĩa rõ (rfdef). Chữ tạo muộn, chưa có nguồn học thuật về cấu trúc nội tại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuệ\": bộ 言 (ngôn — lời nói) → lời nói tuệ trí, chữ hiếm trong văn liệu cổ Hán. | Gương Hán-Việt | tuệ trong văn cổ — chữ rất hiếm, chưa có từ ghép thông dụng | Mở khoá kiến thức | Biết 譢 giúp nhận diện chữ hiếm bộ 言 khi tra tự điển Hán cổ.", "Tự nguyên_Xie": "Wiktionary ghi 譢 âm suì/zhān, thuộc bộ 言 (ngôn — lời nói), nhưng không có định nghĩa hay phân tích cấu trúc cụ thể. Chữ rất hiếm, chỉ xuất hiện trong tự điển cổ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "袢", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 遂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言遂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "遂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "譢", "Unihan_Traditional (Chữ Phồn thể)": "譢", "Pinyin_Xie": "suì", "Âm Hán Việt_Xie": "tuệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này dùng làm động từ trong văn ngôn để chỉ việc khuyên răn hoặc lừa dối. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鳰', '{"9000": "6912.0", "Chữ Trung Quốc": "鳰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 13 | nét | 鳰 | nhu | tượng hình | (độc thể, bộ 鳥 — chữ kokuji Nhật) | 鳰 là chữ kokuji (国字) — chữ Hán do người Nhật sáng tạo, không có gốc Hán cổ. Thuộc bộ 鳥 (điểu — chim). Chỉ loài chim lặn nhỏ (chim mòng két, grebe) trong tiếng Nhật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhu\": bộ 鳥 (chim) → chim nhu mì, chim lặn nhỏ của Nhật Bản — chữ do người Nhật đặt ra. | Gương Hán-Việt | nhu trong \"chim nhu\" — loài chim lặn nhỏ (grebe) theo cách đọc Hán-Việt | Mở khoá kiến thức | Biết 鳰 giúp nhận diện một trong số ít chữ kokuji Nhật khi gặp trong văn bản song ngữ Hán-Nhật.", "Tự nguyên_Xie": "Theo Wiktionary, 鳰 là chữ kokuji (chữ Hán Nhật tự tạo), không có nguồn gốc từ chữ Hán Trung Quốc. Âm Nhật: にお (nio) hoặc かいつぶり (kaitsuburi) — tên loài chim lặn nhỏ (little grebe). Không có tương đương trong Hán ngữ cổ điển. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá da trơn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "入 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰入鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鳥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "入", "Unihan_Simplified (Chữ Giản thể)": "鳰", "Unihan_Traditional (Chữ Phồn thể)": "鳰", "Pinyin_Xie": "ru", "Âm Hán Việt_Xie": "nhu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này đóng vai trò làm danh từ chỉ một loài chim nước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鴫', '{"9000": "6913.0", "Chữ Trung Quốc": "鴫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 16 | nét | 鴫 | điền | tượng hình | (độc thể, kokuji Nhật, bộ 鳥) | 鴫 là chữ kokuji (国字) — chữ do người Nhật sáng tạo, không có gốc Hán cổ. Thuộc bộ 鳥 (điểu — chim). Âm Nhật là しぎ (shigi), chỉ loài chim dẽ giun (sandpiper/snipe).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điền\": bộ 鳥 (chim) → chim điền dã, chim dẽ ở ruộng đồng — kokuji Nhật cho loài shigi. | Gương Hán-Việt | điền trong \"chim điền\" — chim đồng cỏ, theo âm đọc Hán-Việt | Mở khoá kiến thức | Biết 鴫 giúp nhận diện một trong các chữ kokuji Nhật Bản khi đọc tên động vật trong văn bản Nhật.", "Tự nguyên_Xie": "Theo Wiktionary, 鴫 là chữ kokuji Nhật, không có nguồn gốc từ chữ Hán Trung Quốc. Âm Nhật: しぎ (shigi) — tên loài chim dẽ giun (sandpiper). Chữ tạo muộn, không có trong giáp cốt/kim văn. Không dùng trong tiếng Trung. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鴴", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "田 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰田鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鳥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "田", "Unihan_Simplified (Chữ Giản thể)": "鴫", "Unihan_Traditional (Chữ Phồn thể)": "鴫", "Pinyin_Xie": "tian", "Âm Hán Việt_Xie": "điền", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài chim nước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('笟', '{"9000": "6914.0", "Chữ Trung Quốc": "笟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 11 | nét | 笟 | cô | tượng hình | (độc thể, bộ 竹) | 笟 thuộc bộ 竹 (trúc — tre, trúc). Wiktionary không có mục từ; nghĩa và cấu trúc chưa được xác định. Chữ tạo muộn, chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cô\": bộ 竹 (tre, trúc) → vật cô đơn làm từ tre — chữ hiếm, nghĩa chưa rõ. | Gương Hán-Việt | cô trong văn cổ — chữ hiếm bộ 竹 | Mở khoá kiến thức | Biết 笟 giúp nhận diện chữ hiếm bộ 竹 khi tra tự điển Hán cổ.", "Tự nguyên_Xie": "Không tìm thấy phân tích nguồn gốc từ Wiktionary cho 笟. Bộ 竹 (trúc — tre, trúc) cho biết liên quan đến vật liệu tre hoặc đồ vật làm từ tre. Nghĩa cụ thể chưa rõ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "笟", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 瓜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮瓜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "瓜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "笟", "Unihan_Traditional (Chữ Phồn thể)": "笟", "Pinyin_Xie": "gū", "Âm Hán Việt_Xie": "cô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ dụng cụ đan bằng tre nứa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('莾', '{"9000": "6915.0", "Chữ Trung Quốc": "莾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 莾 | mãng | tượng hình | (độc thể, bộ 艸) | 莾 thuộc bộ 艸/艹 (tháu — cỏ, thực vật). Không có phân tích Wiktionary; có thể là biến thể hoặc dạng khác của 莽 (mãng — cỏ rậm). Chữ tạo muộn, chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mãng\": bộ 艸 (cỏ) → cỏ mãng — vùng cỏ rậm rạp, hoang vu; biến thể của 莽. | Gương Hán-Việt | mãng trong \"mãng địa\" — vùng đất hoang cỏ rậm | Mở khoá kiến thức | Biết 莾 giúp nhận diện biến thể của 莽 trong văn bản cổ về thực vật.", "Tự nguyên_Xie": "Không tìm thấy phân tích nguồn gốc từ Wiktionary cho 莾. Bộ 艸 (tháu — cỏ) cho biết liên quan đến thực vật. Chữ có thể là biến thể của 莽 (mãng — rậm rạp, cỏ hoang). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "莾", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 奔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹奔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "莾", "Unihan_Traditional (Chữ Phồn thể)": "莾", "Pinyin_Xie": "mǎng", "Âm Hán Việt_Xie": "mãng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ bổ nghĩa cho danh từ để tả cảnh hoang vu. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('袑', '{"9000": "6916.0", "Chữ Trung Quốc": "袑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 10 | nét | 袑 | chéo | tượng hình | (độc thể, bộ 衣) | 袑 thuộc bộ 衣 (y — quần áo). Wiktionary ghi đây là chữ cổ chỉ phần chéo vạt áo hoặc bẹn quần. Không có phân tích cấu trúc rõ ràng; chữ tạo muộn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chéo\": bộ 衣 (áo) → phần chéo vạt áo — nơi hai tà giao nhau theo đường chéo. | Gương Hán-Việt | chéo trong \"chéo khăn\", \"chéo áo\" — phần vạt chéo của trang phục truyền thống | Mở khoá kiến thức | Biết 袑 giúp đọc văn bản cổ về trang phục, may mặc truyền thống Trung Hoa.", "Tự nguyên_Xie": "Theo Wiktionary, 袑 là chữ cổ (obs-std) chỉ phần bẹn/chéo của trang phục — cụ thể là crotch (chỗ giao nhau của hai ống quần) hoặc chéo vạt áo. Thuộc bộ 衣 (y — quần áo). Không có phân tích cấu trúc biểu âm hay biểu nghĩa phức hợp. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chéo; như \"chéo khăn; chéo áo; chéo góc\" (vhn) xéo; như \"cắt xéo; xếp xéo\" (gdhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 召", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤召", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "召", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "袑", "Unihan_Traditional (Chữ Phồn thể)": "袑", "Pinyin_Xie": "shào", "Âm Hán Việt_Xie": "thiệu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một bộ phận của trang phục cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('訒', '{"9000": "6917.0", "Chữ Trung Quốc": "訒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 10 | nét | 訒 | nhẫn | tượng hình | (độc thể, bộ 言) | 訒 thuộc bộ 言 (ngôn — lời nói). Wiktionary ghi nhận nhưng không phân tích cấu trúc. Có thể là hội ý từ 言 (ngôn — lời) + 刃 (nhẫn — dao, cắt giảm) → cân nhắc từng lời trước khi nói. Chữ cổ, ít dùng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhẫn\": bộ 言 (lời nói) → nhẫn nhịn khi nói — người có nhân đức thì chậm lời, không bộp chộp. | Gương Hán-Việt | nhẫn trong \"chậm nhẫn khi nói\" — người quân tử kiệm lời, cân nhắc trước khi phát ngôn | Mở khoá kiến thức | Biết 訒 giúp đọc Luận Ngữ và các văn bản Nho học bàn về đức hạnh ngôn ngữ.", "Tự nguyên_Xie": "Đại triện | Theo Wiktionary, 訒 có nghĩa \"chậm rãi và thận trọng trong lời nói\" — được trích dẫn trong Luận Ngữ khi Khổng Tử bàn về nhân đức. Thuộc bộ 言 (ngôn — lời nói). Không có phân tích cấu trúc rõ ràng, nhưng âm nhẫn và ý nghĩa thận trọng gợi ý liên quan đến 忍 (nhẫn — chịu đựng, kiên nhẫn). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chậm nói", "Hạng Tần Suất (Jun Da)": "7505.0", "Tần Suất % (Jun Da)": "99.9985297463", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 刃", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言刃", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "刃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "讱", "Unihan_Traditional (Chữ Phồn thể)": "訒", "Pinyin_Xie": "rèn", "Âm Hán Việt_Xie": "nhẫn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ miêu tả cách nói năng thận trọng, chậm rãi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('讝', '{"9000": "6918.0", "Chữ Trung Quốc": "讝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 26 | nét | 讝 | chiêm | tượng hình | (độc thể, bộ 言) | 讝 thuộc bộ 言 (ngôn — lời nói). Wiktionary ghi nhận âm zhān nhưng không có định nghĩa (rfdef). Chữ rất hiếm, tạo muộn, chưa có nguồn học thuật về cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chiêm\": bộ 言 (lời nói) → lời chiêm ngôn — nói mê sảng, lời trong cơn chiêm bao; gần nghĩa 譫 (chiêm — nói mê). | Gương Hán-Việt | chiêm trong \"chiêm ngôn\" — lời nói mê sảng | Mở khoá kiến thức | Biết 讝 giúp nhận diện biến thể cổ của 譫 trong văn bản y học cổ về mê sảng.", "Tự nguyên_Xie": "Wiktionary ghi 讝 âm zhān, thuộc bộ 言, nhưng không cung cấp định nghĩa hay phân tích cấu trúc. Chữ rất hiếm, chỉ xuất hiện trong tự điển cổ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "蝝", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 嚴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言嚴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "嚴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "讝", "Unihan_Traditional (Chữ Phồn thể)": "讝", "Pinyin_Xie": "zhán", "Âm Hán Việt_Xie": "chiêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ chỉ trạng thái nói sảng khi bị bệnh nặng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鈩', '{"9000": "6919.0", "Chữ Trung Quốc": "鈩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 12 | nét | 鈩 | lô | tượng hình | (độc thể, bộ 金) | 鈩 thuộc bộ 金 (kim — kim loại, đồ kim khí). Là dạng cổ hoặc biến thể của 爐 (lô — lò, bếp). Chữ tạo muộn, không có phân tích cấu trúc từ Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lô\": bộ 金 (kim loại) → lô lửa — cái lò kim loại đựng than, sưởi ấm trong mùa đông. | Gương Hán-Việt | lô trong \"lô hỏa\" (lò lửa), \"noãn lô\" (bếp sưởi) | Mở khoá kiến thức | Biết 鈩 giúp nhận biết biến thể cổ của 爐 trong văn bản cổ về đồ gia dụng kim loại.", "Tự nguyên_Xie": "Không tìm thấy phân tích nguồn gốc từ Wiktionary cho 鈩. Bộ 金 (kim — kim loại) kết hợp với nghĩa lò sưởi, bếp lửa cho thấy đây có thể là biến thể cổ của 爐 (lô). Nghĩa: lò sưởi, bếp lò, lò nung. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鈩", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 户", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金户", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "户", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鈩", "Unihan_Traditional (Chữ Phồn thể)": "鈩", "Pinyin_Xie": "lu", "Âm Hán Việt_Xie": "lô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ dùng trong hóa học để chỉ nguyên tố nhân tạo Rutherfordi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('閷', '{"9000": "6920.0", "Chữ Trung Quốc": "閷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 16 | nét | 閷 | sái | tượng hình | (độc thể, bộ 門) | 閷 thuộc bộ 門 (môn — cửa). Wiktionary ghi hai âm: shài (cắt giảm, điểm nối cung tên) và shā (dạng của 殺). Chữ cổ, hiếm dùng, chưa có phân tích cấu trúc rõ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sái\": bộ 門 (cửa) → sái lệch — cắt bớt qua cửa, làm giảm đi; cũng là điểm gút của cung tên. | Gương Hán-Việt | sái trong văn cổ — cắt giảm, điểm nối cung | Mở khoá kiến thức | Biết 閷 giúp đọc văn bản cổ về vũ khí và hình phạt.", "Tự nguyên_Xie": "Theo Wiktionary, 閷 có hai âm đọc: shài (nghĩa: cắt giảm, làm yếu; điểm nối của cung tên) và shā (biến thể của 殺 — giết). Thuộc bộ 門. Là chữ cổ, hầu như không dùng trong tiếng Trung hiện đại. Chưa có phân tích chi tiết về cấu trúc biểu âm/biểu nghĩa. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鷷", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "杀 + 閃", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰杀閃", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "閃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "杀", "Unihan_Simplified (Chữ Giản thể)": "閷", "Unihan_Traditional (Chữ Phồn thể)": "閷", "Pinyin_Xie": "shài", "Âm Hán Việt_Xie": "sái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng như động từ trong văn ngôn cổ với nghĩa giảm bớt hoặc sát hại. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('頉', '{"9000": "6921.0", "Chữ Trung Quốc": "頉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 頁 | Số nét | 13 | nét | 頉 | di | tượng hình | (độc thể, bộ 頁) | 頉 thuộc bộ 頁 (hiệt — đầu, khuôn mặt). Wiktionary không có mục từ; nghĩa theo anchor context là gò má, hàm, cằm. Chữ tạo muộn, chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"di\": bộ 頁 (đầu) → phần hàm di chuyển — cằm hàm, bộ phận mặt người. | Gương Hán-Việt | di trong \"hàm di\" — cằm hàm, bộ phận khuôn mặt | Mở khoá kiến thức | Biết 頉 giúp nhận diện biến thể cổ của 頤 (hàm) trong văn bản y học cổ.", "Tự nguyên_Xie": "Không tìm thấy phân tích nguồn gốc từ Wiktionary cho 頉. Bộ 頁 (hiệt — đầu, khuôn mặt) và nghĩa gợi ý liên quan đến phần mặt/hàm/cằm. Có thể liên quan đến 頤 (di — hàm, nuôi dưỡng). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鉉", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "止 + 頁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰止頁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "頁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "止", "Unihan_Simplified (Chữ Giản thể)": "頉", "Unihan_Traditional (Chữ Phồn thể)": "頉", "Pinyin_Xie": "yí", "Âm Hán Việt_Xie": "di", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Dùng như danh từ chỉ bộ phận cằm hoặc động từ chỉ việc nuôi dưỡng trong văn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('髤', '{"9000": "6922.0", "Chữ Trung Quốc": "髤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 髟 | Số nét | 14 | nét | 髤 | hưu | tượng hình | (độc thể, bộ 髟) | 髤 thuộc bộ 髟 (tiêu — tóc, lông dài). Wiktionary ghi nhận nhưng không có định nghĩa rõ (rfdef). Theo anchor context, nghĩa là sơn, quét sơn. Chữ tạo muộn, chưa có nguồn học thuật rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hưu\": bộ 髟 (tóc, lông) → sơn bóng như mái tóc — hưu sắc bóng loáng của sơn mài truyền thống. | Gương Hán-Việt | hưu trong \"hưu sơn\" — sơn mài, quét sơn bóng | Mở khoá kiến thức | Biết 髤 giúp đọc văn bản cổ về nghề thủ công sơn mài truyền thống Trung Hoa.", "Tự nguyên_Xie": "Wiktionary ghi 髤 âm xiū, thuộc bộ 髟, nhưng không có định nghĩa chi tiết. Theo các nguồn tham khảo khác, 髤 (hưu) có nghĩa là sơn (chất sơn mài) và hành động quét sơn — liên quan đến nghề sơn mài truyền thống. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sơn; quét sơn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "髟 + 木", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱髟木", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "木", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "髟", "Unihan_Simplified (Chữ Giản thể)": "髤", "Unihan_Traditional (Chữ Phồn thể)": "髤", "Pinyin_Xie": "xiū", "Âm Hán Việt_Xie": "hưu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Làm động từ chỉ hành động quét sơn lên đồ vật hoặc danh từ chỉ chất sơn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('龤', '{"9000": "6923.0", "Chữ Trung Quốc": "龤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 龠 | Số nét | 26 | nét | 龤 | hài | tượng hình | (độc thể, bộ 龠) | 龤 thuộc bộ 龠 (dược — sáo, nhạc cụ). Wiktionary ghi đây là dạng tương đương của 諧 (hài — hòa hợp). Chữ tạo muộn, không có trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hài\": bộ 龠 (nhạc cụ) → hài hòa — các âm thanh khác nhau từ sáo trúc hòa quyện thành điệu nhạc hài. | Gương Hán-Việt | hài trong \"hài hòa\" (調和), \"hài thanh\" (âm thanh hòa hợp) | Mở khoá kiến thức | Biết 龤 giúp hiểu nguồn gốc âm nhạc của 諧 (hài hòa) — gốc từ tiếng nhạc cụ sáo.", "Tự nguyên_Xie": "Theo Wiktionary, 龤 có âm xié, nghĩa là \"hòa hợp, phù hợp với\" — tương đương với 諧. Thuộc bộ 龠 (dược — nhạc cụ sáo). Chữ hiếm, không dùng trong văn xuôi hiện đại; chỉ gặp trong văn học cổ về âm nhạc và hòa hợp. Chữ tạo muộn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phù hợp với; đồng ý; hòa hợp", "Hạng Tần Suất (Jun Da)": "6923.0", "Tần Suất % (Jun Da)": "99.9966145406", "GavinGrover_Once (Chiết tự trực tiếp)": "龠 + 皆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰龠皆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "皆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "龠", "Unihan_Simplified (Chữ Giản thể)": "龤", "Unihan_Traditional (Chữ Phồn thể)": "龤", "Pinyin_Xie": "xié", "Âm Hán Việt_Xie": "hài", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ biểu thị sự hòa hợp về âm điệu hoặc ý kiến. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('薿', '{"9000": "6924.0", "Chữ Trung Quốc": "薿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 17 | nét | 薿 | nghĩ | tượng hình | (độc thể, bộ 艸) | 薿 thuộc bộ 艸/艹 (tháu — cỏ, thực vật). Wiktionary ghi chỉ dùng trong từ ghép 薿薿 (mô tả cây cỏ xanh tốt, rậm rạp). Chữ tạo muộn, chưa có nguồn học thuật rõ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nghĩ\": bộ 艸 (cỏ) → cây cỏ nghĩ ngợi xanh tươi — 薿薿, cỏ cây lên xanh mướt như suy nghĩ lan rộng. | Gương Hán-Việt | nghĩ trong \"thảo mộc nghĩ nghĩ\" — cây cỏ xanh tươi tốt lành | Mở khoá kiến thức | Biết 薿 giúp đọc thơ phú cổ miêu tả cảnh quan thiên nhiên xanh tươi.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 薿 (âm nǐ) chỉ dùng trong từ ghép 薿薿 — mô tả cây cỏ xanh tươi, sinh sôi rậm rạp. Thuộc bộ 艸. Chữ tạo muộn, chưa thấy trong giáp cốt. Chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tươi tốt; xanh tươi", "Hạng Tần Suất (Jun Da)": "6924.0", "Tần Suất % (Jun Da)": "99.9966186749", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 疑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹疑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "疑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "薿", "Unihan_Traditional (Chữ Phồn thể)": "薿", "Pinyin_Xie": "nǐ", "Âm Hán Việt_Xie": "nghĩ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Làm tính từ miêu tả trạng thái cây cối, lúa má mọc lên tươi tốt. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鱥', '{"9000": "6925.0", "Chữ Trung Quốc": "鱥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 24 | nét | 魚 | ngư | biểu nghĩa | cá | 歲 | tuế | biểu âm | (biểu âm) | 鱥 = 魚 (Ngư, biểu nghĩa: cá) + 歲 (Tuế, biểu âm); chữ hình thanh. Bộ 魚 cho biết đây là một loài cá; 歲 (tuế) cung cấp âm đọc guì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuế\": 魚 (cá) + 歲 (tuế, âm) → cá tuế — loài cá nhỏ sống theo năm tháng trong suối đồng. | Gương Hán-Việt | tuế trong \"ngư tuế\" — cá nhỏ, cá mương nước ngọt | Mở khoá kiến thức | Biết 鱥 giúp đọc văn bản cổ về phân loại cá nước ngọt và thủy sản học.", "Tự nguyên_Xie": "Theo Wiktionary, 鱥 là chữ hình thanh: bộ 魚 (ngư — cá) biểu nghĩa, 歲 (tuế) biểu âm. Chữ chỉ loài cá gudgeon nhỏ (minnow) hoặc cá mương — loài cá nước ngọt nhỏ. Chưa có phân tích thêm về nguồn gốc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tuế", "Hạng Tần Suất (Jun Da)": "6925.0", "Tần Suất % (Jun Da)": "99.9966228091", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 歲", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚歲", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "歲", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鱥", "Unihan_Traditional (Chữ Phồn thể)": "鱥", "Pinyin_Xie": "guì", "Âm Hán Việt_Xie": "quyết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ một loài cá nhỏ thuộc họ cá chép. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('觝', '{"9000": "6926.0", "Chữ Trung Quốc": "觝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 角 | Số nét | 12 | nét | 觝 | để | tượng hình | (độc thể, bộ 角) | 觝 thuộc bộ 角 (giác — sừng, góc). Wiktionary ghi đây là dạng khác của 牴 (để — húc đầu, va chạm, xung đột). Nghĩa: húc bằng sừng, va đập, đối địch.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"để\": bộ 角 (sừng) → dùng sừng để húc — đối để, kháng cự, không nhượng bộ. | Gương Hán-Việt | để trong \"đối để\" (đối kháng), \"để xúc\" (húc va chạm) | Mở khoá kiến thức | Biết 觝 giúp hiểu từ nguyên 牴觸 (để xúc — mâu thuẫn nhau) trong văn bản pháp luật và triết học.", "Tự nguyên_Xie": "Theo Wiktionary, 觝 là dạng thay thế (alt form) của 牴 (để — húc đầu vào, va chạm, xung đột). Thuộc bộ 角 (giác — sừng). Nghĩa gốc là húc bằng sừng, mở rộng thành va chạm, mâu thuẫn, kháng cự. Chưa có phân tích chi tiết thêm. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "húc nhau", "Hạng Tần Suất (Jun Da)": "6926.0", "Tần Suất % (Jun Da)": "99.9966269434", "GavinGrover_Once (Chiết tự trực tiếp)": "角 + 氐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰角氐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "氐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "角", "Unihan_Simplified (Chữ Giản thể)": "觝", "Unihan_Traditional (Chữ Phồn thể)": "觝", "Pinyin_Xie": "dǐ", "Âm Hán Việt_Xie": "để", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ chỉ hành động dùng sừng húc nhau hoặc chống cự, đụng chạm. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鮻', '{"9000": "6927.0", "Chữ Trung Quốc": "鮻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 18 | nét | 鮻 | sa | tượng hình | (độc thể, bộ 魚) | 鮻 thuộc bộ 魚 (ngư — cá). Wiktionary không có mục từ; nghĩa theo anchor context là một loài cá (Canton dace) hoặc nhân vật kỳ bí trong Sơn Hải Kinh. Chữ tạo muộn, chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sa\": bộ 魚 (cá) → cá sa — loài cá sa mạc cát bờ biển, hoặc nhân vật cá-người trong thần thoại. | Gương Hán-Việt | sa trong \"ngư sa\" — cá sa, sinh vật nửa người nửa cá | Mở khoá kiến thức | Biết 鮻 giúp nhận diện loài cá hiếm và sinh vật thần thoại trong văn bản Sơn Hải Kinh.", "Tự nguyên_Xie": "Không tìm thấy phân tích nguồn gốc từ Wiktionary cho 鮻. Bộ 魚 (ngư — cá) cho biết đây là loài cá. Một số nguồn ghi là cá mugil (đối vân) hoặc sinh vật huyền thoại trong Sơn Hải Kinh với đầu người thân cá. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "người cá (quái vật nói trong sách Sơn Hải Kinh, ở núi Cô Xạ, có đầu người, tay người, mình cá)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 夋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚夋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鮻", "Unihan_Traditional (Chữ Phồn thể)": "鮻", "Pinyin_Xie": "suō", "Âm Hán Việt_Xie": "toa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài sinh vật kỳ quái mình cá đầu người trong thư tịch cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鳤', '{"9000": "6928.0", "Chữ Trung Quốc": "鳤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 22 | nét | 鳤 | quản | tượng hình | (độc thể, bộ 魚) | 鳤 thuộc bộ 魚 (ngư — cá). Wiktionary không có mục từ; nghĩa là cá quản hoặc một loài cá nước ngọt đặc hữu. Chữ tạo muộn, chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quản\": bộ 魚 (cá) → cá quản — loài cá lớn được quản lý bảo tồn ở sông Trường Giang. | Gương Hán-Việt | quản trong \"ngư quản\" — loài cá lớn nước ngọt | Mở khoá kiến thức | Biết 鳤 giúp đọc tài liệu thủy sản học và sinh thái học sông Dương Tử.", "Tự nguyên_Xie": "Không tìm thấy phân tích nguồn gốc từ Wiktionary cho 鳤. Bộ 魚 (ngư — cá) xác nhận đây là loài cá. Theo một số nguồn Trung Quốc, 鳤 (guǎn) là một loài cá nước ngọt lớn đặc hữu ở lưu vực sông Dương Tử. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá quản", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 管", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼管", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "管", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鳤", "Unihan_Traditional (Chữ Phồn thể)": "鳤", "Pinyin_Xie": "guǎn", "Âm Hán Việt_Xie": "quản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ dùng để gọi một loài cá xương nước ngọt đặc hữu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('穉', '{"9000": "6929.0", "Chữ Trung Quốc": "穉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 17 | nét | 穉 | trĩ | tượng hình | (độc thể, bộ 禾) | 穉 thuộc bộ 禾 (hoà — lúa, cây ngũ cốc). Wiktionary không có mục từ; nghĩa là lúa non, trẻ con, non nớt. Chữ tạo muộn, chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trĩ\": bộ 禾 (lúa) → lúa trĩ non — mầm lúa còn non xanh, ý chỉ trẻ thơ non nớt. | Gương Hán-Việt | trĩ trong \"ấu trĩ\" (non nớt), \"trĩ tử\" (trẻ con) | Mở khoá kiến thức | Biết 穉 giúp nhận diện biến thể cổ của 稚 trong văn bản nông nghiệp và văn học cổ.", "Tự nguyên_Xie": "Không tìm thấy phân tích nguồn gốc từ Wiktionary cho 穉. Bộ 禾 (hoà — lúa) cho thấy liên quan đến nông nghiệp; nghĩa \"lúa non, non nớt, trẻ thơ\" gợi ý hình ảnh cây lúa còn non. Có thể là biến thể cổ của 稚 (trĩ — trẻ, non). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lúa non; trẻ con", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 犀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾犀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "犀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "穉", "Unihan_Traditional (Chữ Phồn thể)": "穉", "Pinyin_Xie": "zhì", "Âm Hán Việt_Xie": "trĩ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ thường đứng trước danh từ để biểu thị sự non nớt hoặc làm danh từ chỉ trẻ nhỏ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('觱', '{"9000": "6930.0", "Chữ Trung Quốc": "觱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 角 | Số nét | 16 | nét | 角 | giác | biểu nghĩa | sừng, nhạc cụ bằng sừng | 𢨋 | biểu âm | (biểu âm, theo Thuyết Văn) | 觱 = 角 (Giác, biểu nghĩa: sừng/nhạc cụ sừng) + 𢨋 (biểu âm, theo Thuyết Văn); chữ hình thanh. Bộ 角 xác nhận đây là nhạc cụ làm từ sừng; phần biểu âm cung cấp âm đọc bì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tất\": 角 (sừng, kèn) → tất lật — tiếng kèn sừng Tất Lật hú vang lạnh buốt như gió bắc. | Gương Hán-Việt | tất trong \"tất lật\" (觱篥) — loại nhạc cụ thổi bằng sừng | Mở khoá kiến thức | Biết 觱 mở khoá 觱篥 (tất lật — nhạc cụ sừng), 觱沸 (nước sôi ùng ục), 觱發 (gió lạnh).", "Tự nguyên_Xie": "Theo Wiktionary (dẫn Thuyết Văn), 觱 là chữ hình thanh: 角 (giác — sừng) biểu nghĩa, 𢨋 biểu âm. Chữ chỉ kèn sừng (觱篥 — tất lật, loại nhạc cụ thổi bằng sừng hoặc sậy có nguồn gốc Trung Á). Mở rộng: gió lạnh (觱發 — gió lạnh thổi). Cũng dùng trong 觱沸 (nước sôi ùng ục). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: tất lật 觱篥)", "Hạng Tần Suất (Jun Da)": "6930.0", "Tần Suất % (Jun Da)": "99.996642447", "GavinGrover_Once (Chiết tự trực tiếp)": "咸 + 角", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱咸角", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "咸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "角", "Unihan_Simplified (Chữ Giản thể)": "觱", "Unihan_Traditional (Chữ Phồn thể)": "觱", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "tất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này chủ yếu dùng trong từ ghép để chỉ một loại nhạc cụ thổi cổ xưa hoặc tả tiếng gió thổi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('轘', '{"9000": "6931.0", "Chữ Trung Quốc": "轘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 20 | nét | 車 | xa | biểu nghĩa | xe, cỗ xe | 睘 | hoàn | biểu âm | (biểu âm) | 轘 = 車 (Xa, biểu nghĩa: xe) + 睘 (Hoàn, biểu âm); chữ hình thanh. Bộ 車 cho biết liên quan đến xe; 睘 (hoàn) cung cấp âm đọc. Chữ chỉ hình phạt phanh thây bằng xe thời cổ đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoàn\": 車 (xe) + 睘 (hoàn, âm) → hoàn hình — hình phạt xe hoàn, phanh thây bằng nhiều cỗ xe kéo ngược chiều. | Gương Hán-Việt | hoàn trong \"hoàn hình\" (hình phạt xe phanh thây) — hình phạt cổ đại cực kỳ tàn khốc | Mở khoá kiến thức | Biết 轘 giúp đọc văn bản lịch sử về hình phạt cổ đại và địa danh 轘轅 ở Trung Nguyên.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 轘 là chữ hình thanh: bộ 車 (xa — xe) biểu nghĩa, 睘 (hoàn) biểu âm. Nghĩa là hình phạt tử hình man rợ thời cổ đại Trung Quốc: buộc tội nhân vào nhiều cỗ xe rồi cho ngựa chạy theo các hướng khác nhau để xé xác. Cũng dùng trong địa danh 轘轅 (Hoàn Viên — địa danh ở Hà Nam). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hình phạt phanh thây", "Hạng Tần Suất (Jun Da)": "6931.0", "Tần Suất % (Jun Da)": "99.9966460645", "GavinGrover_Once (Chiết tự trực tiếp)": "車 + 睘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰車睘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "睘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "車", "Unihan_Simplified (Chữ Giản thể)": "轘", "Unihan_Traditional (Chữ Phồn thể)": "轘", "Pinyin_Xie": "huán", "Âm Hán Việt_Xie": "hoàn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ việc thi hành hình phạt dùng xe kéo phân thây thời cổ đại. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('筘', '{"9000": "6932.0", "Chữ Trung Quốc": "筘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 12 | nét | 竹 | trúc | biểu nghĩa | tre, trúc | 扣 | khấu | biểu âm | khấu, móc | 筘 = 竹 (Trúc, biểu nghĩa: tre/trúc) + 扣 (Khấu, biểu âm); chữ hình thanh. Bộ 竹 chỉ chất liệu tre/trúc, phần 扣 cho âm đọc kòu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khấu\" (kòu): bộ 竹 (tre) ghép với âm 扣 — hình ảnh chiếc go cửi bằng tre, gõ nhịp theo tiếng khung dệt. | Gương Hán-Việt | Chữ 筘 ít dùng trong từ Hán-Việt thông dụng; gặp trong văn bản kỹ thuật dệt cổ. | Mở khoá kiến thức | Biết 筘 mở khoá từ vựng nghề dệt truyền thống: go cửi, khung dệt.", "Tự nguyên_Xie": "筘 là chữ hình thanh: bộ 竹 (trúc) chỉ vật liệu làm bằng tre, phần 扣 biểu âm. Dùng chỉ \"go cửi\" — bộ phận hình lược bằng tre trong khung dệt vải, để đưa sợi ngang vào đúng vị trí. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật rõ ràng hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khổ, khuôn, go", "Hạng Tần Suất (Jun Da)": "6932.0", "Tần Suất % (Jun Da)": "99.9966532995", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 扣", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮扣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "扣", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "筘", "Unihan_Traditional (Chữ Phồn thể)": "筘", "Pinyin_Xie": "kòu", "Âm Hán Việt_Xie": "khấu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bộ phận của máy dệt dùng để dồn sợi chỉ cho chặt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲝', '{"9000": "6933.0", "Chữ Trung Quốc": "鲝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 14 | nét | 鲝 | trả | tượng hình | cá ướp muối | 鲝 là chữ độc thể, không có cấu trúc hình thanh/hội ý rõ ràng; cấu tạo nội bộ chưa được Wiktionary phân tích. Chữ liên quan đến bộ 魚 (ngư, cá).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trá\" (鲝): bộ 魚 (cá) + âm trá — loài cá ướp muối, bảo quản qua tháng năm như cách người xưa trả nợ thiên nhiên. | Gương Hán-Việt | Chữ 鲝 ít dùng trong tiếng Hán-Việt hiện đại; có thể gặp trong từ cổ chỉ món ăn ướp muối. | Mở khoá kiến thức | Biết 鲝 mở khoá từ vựng ẩm thực cổ Trung Hoa: các loại mắm, cá ướp.", "Tự nguyên_Xie": "鲝 chỉ cá ướp muối hoặc các loại mắm cá, gần nghĩa \"chả cá\" trong tiếng Việt gốc Hán. Không có nguồn Wiktionary phân tích cấu tạo. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ướp; cá ướp; mắm; Trả (Trả Thảo Than, tên đất, ở tỉnh Tứ Xuyên, Trung Quốc); chả; như \"chả cá\" (gdhn)", "Hạng Tần Suất (Jun Da)": "6933.0", "Tần Suất % (Jun Da)": "99.996656917", "GavinGrover_Once (Chiết tự trực tiếp)": "⺶ + 鱼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺶鱼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鱼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺶", "Unihan_Simplified (Chữ Giản thể)": "鲝", "Unihan_Traditional (Chữ Phồn thể)": "鮺", "Pinyin_Xie": "zhǎ", "Âm Hán Việt_Xie": "tráp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ món cá muối hoặc làm động từ chỉ hành động ướp muối thức ăn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蔸', '{"9000": "6934.0", "Chữ Trung Quốc": "蔸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 14 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 兜 | đâu | biểu âm | túi, ôm | 蔸 = 艹 (Thảo, biểu nghĩa: cỏ/thực vật) + 兜 (Đâu, biểu âm); chữ hình thanh. Bộ 艹 chỉ loại thực vật, phần 兜 cho âm dōu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đâu\" (dōu): bộ 艹 (cỏ) ghép âm 兜 — hình ảnh khóm cây túm tụ lại như chiếc túi 兜. | Gương Hán-Việt | Chữ 蔸 ít dùng trong từ Hán-Việt tiêu chuẩn; dùng trong phương ngữ Nam chỉ gốc cây, khóm. | Mở khoá kiến thức | Biết 蔸 mở khoá từ vựng phương ngữ nông nghiệp: đơn vị đếm cây trồng theo khóm.", "Tự nguyên_Xie": "蔸 là chữ hình thanh: bộ 艹 (thảo — cỏ, thực vật) biểu nghĩa; phần 兜 (đâu) biểu âm cho âm dōu. Nghĩa gốc là gốc rễ và thân cây của một số loại thực vật; cũng dùng làm lượng từ đếm cây theo bụi/khóm trong phương ngữ miền Nam Trung Quốc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gốc; gốc; khóm; bụi (lượng từ)", "Hạng Tần Suất (Jun Da)": "6934.0", "Tần Suất % (Jun Da)": "99.996664152", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 兜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹兜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蔸", "Unihan_Traditional (Chữ Phồn thể)": "蔸", "Pinyin_Xie": "dōu", "Âm Hán Việt_Xie": "đâu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Chữ này làm danh từ chỉ phần gốc rễ thực vật hoặc làm lượng từ cho các loại cây trồng theo khóm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镚', '{"9000": "6935.0", "Chữ Trung Quốc": "镚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 16 | nét | 镚 | bằng | tượng hình | đồng tiền kim loại nhỏ | 镚 là chữ thuộc bộ 金 (kim — kim loại), cấu tạo nội bộ chưa được Wiktionary phân tích chi tiết. Chữ tạo muộn dùng trong văn bản thương mại cận đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"băng\" (bèng): bộ 金 (kim loại) — đồng xu bằng kim loại bé tí, văng ra tiếng \"beng\" khi rơi xuống đất. | Gương Hán-Việt | Chữ 镚 ít dùng trong từ Hán-Việt; gặp trong từ 镚子 (bèngzi) chỉ đồng xu lẻ. | Mở khoá kiến thức | Biết 镚 mở khoá từ vựng tiền tệ cận đại: 镚子 (đồng xu nhỏ).", "Tự nguyên_Xie": "镚 chỉ đồng tiền kim loại nhỏ, đặc biệt đồng tiền đúc cuối thời Thanh và đầu Trung Hoa Dân Quốc. Bộ 金 (kim) chỉ chất liệu kim loại. Không có phân tích cấu tạo từ Wiktionary. Chữ tạo muộn, chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiền đồng cuối đời Thanh; tiền đúc bằng kim loại", "Hạng Tần Suất (Jun Da)": "6935.0", "Tần Suất % (Jun Da)": "99.9966677695", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 崩", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅崩", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "崩", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镚", "Unihan_Traditional (Chữ Phồn thể)": "鏰", "Pinyin_Xie": "bèng", "Âm Hán Việt_Xie": "băng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường dùng trong khẩu ngữ để chỉ những đồng tiền xu có mệnh giá nhỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('痦', '{"9000": "6936.0", "Chữ Trung Quốc": "痦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 12 | nét | 疒 | nạch | biểu nghĩa | bệnh tật | 午 | ngọ | biểu âm | giờ ngọ | 痦 = 疒 (Nạch, biểu nghĩa: bệnh, triệu chứng da) + 午 (Ngọ, biểu âm); chữ hình thanh. Bộ 疒 chỉ các bệnh hoặc triệu chứng trên cơ thể, phần 午 cho âm wù.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngộ\" (wù): bộ bệnh 疒 — chiếc nốt ruồi nhỏ nằm im trên da, không đau không ngứa. | Gương Hán-Việt | Chữ 痦 ít dùng trong từ Hán-Việt; gặp trong từ 痦子 (wùzi) chỉ nốt ruồi. | Mở khoá kiến thức | Biết 痦 mở khoá từ vựng y học da liễu: 痦子 (nốt ruồi, mụt cóc).", "Tự nguyên_Xie": "痦 là chữ hình thanh: bộ 疒 (nạch — ký hiệu bệnh tật) biểu nghĩa chỉ dấu hiệu trên da; phần biểu âm gần âm wù. Nghĩa là nốt ruồi phẳng hoặc mụt trên da. Không có phân tích chi tiết từ Wiktionary. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mụt; nốt ruồi", "Hạng Tần Suất (Jun Da)": "6936.0", "Tần Suất % (Jun Da)": "99.9966713869", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 吾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒吾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "痦", "Unihan_Traditional (Chữ Phồn thể)": "痦", "Pinyin_Xie": "wù", "Âm Hán Việt_Xie": "ố", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường kết hợp với các từ khác để chỉ nốt ruồi hoặc mụn lồi trên cơ thể. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('秵', '{"9000": "6937.0", "Chữ Trung Quốc": "秵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 11 | nét | 秵 | yīn | tượng hình | lúa non mảnh | 秵 thuộc bộ 禾 (hòa — lúa), cấu tạo nội bộ chưa được Wiktionary phân tích. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"âm\" (yīn): bộ 禾 (lúa) — một loại lúa hoặc cây ngũ cốc đặc biệt trong nông nghiệp cổ. | Gương Hán-Việt | Chữ 秵 rất hiếm trong từ Hán-Việt; chưa có ghi chép dùng phổ biến. | Mở khoá kiến thức | Biết 秵 giúp nhận diện chữ nông nghiệp cổ trong văn bản cổ điển Trung Hoa.", "Tự nguyên_Xie": "秵 thuộc bộ 禾 (hòa — lúa gạo), nghĩa chưa rõ ràng trong từ điển hiện đại. Wiktionary không có phân tích cấu tạo. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "秵", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 因", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾因", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "因", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "秵", "Unihan_Traditional (Chữ Phồn thể)": "秵", "Pinyin_Xie": "yīn", "Âm Hán Việt_Xie": "âm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ để chỉ một loại lúa chín muộn hoặc tấm đệm bằng cỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('臎', '{"9000": "6938.0", "Chữ Trung Quốc": "臎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 18 | nét | 臎 | tụy | tượng hình | thịt đùi, phần thịt ngu ngốc | 臎 thuộc bộ 肉 (nhục — thịt), cấu tạo nội bộ chưa được Wiktionary phân tích chi tiết. Chữ tạo muộn, định nghĩa chưa rõ ràng (rfdef).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tụy\" (tụy): bộ 肉 (thịt) — một chữ cổ liên quan đến bộ phận cơ thể, nghĩa nay đã mờ phai. | Gương Hán-Việt | Chữ 臎 không dùng trong từ Hán-Việt hiện đại. | Mở khoá kiến thức | Biết 臎 giúp nhận diện chữ cổ về giải phẫu trong văn bản y học Hán cổ.", "Tự nguyên_Xie": "臎 thuộc bộ 肉 (nhục — thịt), nghĩa chưa được định nghĩa rõ trong Wiktionary (rfdef). Ký hiệu mc/oc cho thấy chữ có trong văn bản trung cổ/cổ đại nhưng nghĩa đã thất truyền. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Ngốc nghếch", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 翠", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月翠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "翠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "臎", "Unihan_Traditional (Chữ Phồn thể)": "臎", "Pinyin_Xie": "cuì", "Âm Hán Việt_Xie": "tụy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ để miêu tả trạng thái ngốc nghếch hoặc làm danh từ chỉ phao câu của loài chim. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('葴', '{"9000": "6939.0", "Chữ Trung Quốc": "葴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 冘 | du | biểu âm | chuyển dịch | 葴 thuộc bộ 艹 (thảo — thực vật), cấu tạo nội bộ chưa được Wiktionary phân tích chi tiết. Chữ chỉ loài cây Strobilanthes cusia (chàm mã lam) và cây tầm phỏng (Physalis alkekengi).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"châm\" (zhēn): bộ 艹 (cỏ) — cây chàm xanh mọc hoang, lá dùng làm thuốc nhuộm truyền thống. | Gương Hán-Việt | Chữ 葴 ít dùng trong từ Hán-Việt; gặp trong từ thực vật học cổ điển. | Mở khoá kiến thức | Biết 葴 mở khoá từ vựng thực vật học cổ: tên các loài cây dược liệu truyền thống.", "Tự nguyên_Xie": "Tiểu triện | 葴 thuộc bộ 艹 (thảo) chỉ loài thực vật. Wiktionary chỉ ghi {{Han etym}} mà không phân tích cấu tạo. Chữ dùng tên loài Strobilanthes cusia (đồng nghĩa 馬藍) và Alkekengi officinarum (tầm phỏng, đồng nghĩa 酸漿). Chữ có dạng tiểu triện. Chưa có nguồn học thuật phân tích cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Physalis alkekengi", "Hạng Tần Suất (Jun Da)": "6939.0", "Tần Suất % (Jun Da)": "99.9966822394", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 咸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹咸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "咸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "葴", "Unihan_Traditional (Chữ Phồn thể)": "葴", "Pinyin_Xie": "zhēn", "Âm Hán Việt_Xie": "châm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ một loại cây thân thảo dùng làm thuốc trong Đông y. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('泖', '{"9000": "6940.0", "Chữ Trung Quốc": "泖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 8 | nét | 氵 | thủy | biểu nghĩa | nước | 卯 | mão | biểu âm | giờ mão, mộng ghép | 泖 = 氵 (Thủy, biểu nghĩa: nước) + 卯 (Mão, biểu âm); chữ hình thanh. Bộ 氵 chỉ địa hình liên quan đến nước, phần 卯 cho âm mǎo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mão\" (mão): bộ 氵 (nước) ghép âm 卯 — vùng ao hồ nhỏ yên tĩnh như buổi giờ mão bình minh. | Gương Hán-Việt | Chữ 泖 ít dùng trong từ Hán-Việt thông dụng; gặp trong địa danh vùng Giang Nam. | Mở khoá kiến thức | Biết 泖 giúp đọc địa danh vùng đồng bằng Giang Nam Trung Quốc.", "Tự nguyên_Xie": "泖 là chữ hình thanh: bộ 氵 (thủy — nước) biểu nghĩa chỉ vùng nước; phần 卯 (mão) biểu âm cho âm mǎo. Nghĩa là vùng nước tĩnh lặng, ao hồ nhỏ ở đồng bằng miền Nam Trung Quốc; cũng dùng trong địa danh như Dã泖 (huyện Tùng Giang, Thượng Hải). Chưa có nguồn học thuật bổ sung. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước đọng; sông Mão", "Hạng Tần Suất (Jun Da)": "6940.0", "Tần Suất % (Jun Da)": "99.9966930919", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 卯", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵卯", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "泖", "Unihan_Traditional (Chữ Phồn thể)": "泖", "Pinyin_Xie": "mǎo", "Âm Hán Việt_Xie": "mão", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ riêng để chỉ địa danh hoặc vùng nước đọng ở vùng Giang Nam. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('骟', '{"9000": "6941.0", "Chữ Trung Quốc": "骟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 13 | nét | 马 | mã | biểu nghĩa | ngựa | 扇 | thiện | biểu âm | quạt, cánh cửa | 骟 thuộc bộ 马 (mã — ngựa), cấu tạo nội bộ chưa được Wiktionary phân tích. Dựa vào cấu trúc chữ, khả năng là hình thanh: bộ 马 biểu nghĩa, phần 扇 biểu âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiến\" (shàn): bộ 马 (ngựa) — thao tác thiến ngựa để ngựa ngoan ngoãn hơn. | Gương Hán-Việt | Chữ 骟 ít dùng trong từ Hán-Việt; dùng trong 骟马 (shàn mǎ — ngựa thiến). | Mở khoá kiến thức | Biết 骟 mở khoá từ vựng chăn nuôi ngựa: 骟马 (ngựa thiến), thuật ngữ chăn nuôi cổ.", "Tự nguyên_Xie": "骟 thuộc bộ 马 (mã — ngựa), nghĩa là thiến ngựa (cắt bỏ tinh hoàn của ngựa đực). Wiktionary không có phân tích cấu tạo. Chữ tạo muộn, chưa có nguồn học thuật. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngựa đã thiến; thiến (trâu, ngựa)", "Hạng Tần Suất (Jun Da)": "6941.0", "Tần Suất % (Jun Da)": "99.9966967094", "GavinGrover_Once (Chiết tự trực tiếp)": "马 + 扇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰马扇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "扇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "马", "Unihan_Simplified (Chữ Giản thể)": "骟", "Unihan_Traditional (Chữ Phồn thể)": "騸", "Pinyin_Xie": "shàn", "Âm Hán Việt_Xie": "phiến", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường dùng làm động từ chỉ việc thiến gia súc hoặc làm tính từ bổ nghĩa cho danh từ chỉ con vật đã thiến. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锽', '{"9000": "6942.0", "Chữ Trung Quốc": "锽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 14 | nét | 金 | kim | biểu nghĩa | kim loại | 黄 | hoàng | biểu âm | vàng, màu vàng | 锽 thuộc bộ 金 (kim — kim loại), cấu tạo nội bộ chưa được Wiktionary phân tích. Có thể là hình thanh: bộ 金 biểu nghĩa, 黄 biểu âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoàng\" (huáng): bộ 金 (kim loại) — tiếng chuông vàng vang vọng, âm hoàng. | Gương Hán-Việt | Chữ 锽 ít dùng trong từ Hán-Việt hiện đại; gặp trong văn bản tả âm thanh kim loại cổ. | Mở khoá kiến thức | Biết 锽 giúp nhận diện từ cổ tả âm thanh nhạc khí kim loại.", "Tự nguyên_Xie": "锽 thuộc bộ 金 (kim — kim loại), chỉ tiếng chuông vang hoặc dụng cụ kim loại phát âm thanh. Wiktionary không có phân tích cấu tạo. Chữ tạo muộn, chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng chuông trống kêu; cái đinh ba", "Hạng Tần Suất (Jun Da)": "6942.0", "Tần Suất % (Jun Da)": "99.9967003269", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 皇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅皇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "皇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锽", "Unihan_Traditional (Chữ Phồn thể)": "鍠", "Pinyin_Xie": "huáng", "Âm Hán Việt_Xie": "hoàng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Từ tượng thanh | 象声词 | Thường dùng làm danh từ chỉ một loại binh khí cổ hoặc làm từ tượng thanh mô tả tiếng chuông trống vang rền. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('犋', '{"9000": "6943.0", "Chữ Trung Quốc": "犋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 牛 | Số nét | 12 | nét | 牛 | ngưu | biểu nghĩa | trâu bò | 具 | cụ | biểu âm | công cụ, dụng cụ | 犋 = 牛 (Ngưu, biểu nghĩa: trâu bò) + 具 (Cụ, biểu âm); chữ hình thanh. Bộ 牛 chỉ gia súc kéo cày, phần 具 cho âm jù.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cụ\" (jù): bộ 牛 (trâu) + 具 (dụng cụ) — đôi trâu đầy đủ công cụ kéo cày, làm việc cùng nhau. | Gương Hán-Việt | Chữ 犋 ít dùng trong từ Hán-Việt tiêu chuẩn; gặp trong văn bản nông nghiệp cổ. | Mở khoá kiến thức | Biết 犋 mở khoá từ vựng nông nghiệp cổ: đơn vị đôi trâu bò kéo cày.", "Tự nguyên_Xie": "犋 là chữ hình thanh: bộ 牛 (ngưu — trâu bò) biểu nghĩa chỉ gia súc; phần 具 (cụ — dụng cụ) biểu âm cho âm jù. Nghĩa là một đôi bò/trâu kéo cày cùng nhau. Chữ cổ, nay ít dùng ngoài phương ngữ và văn bản nông nghiệp. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một cặp (trâu, bò, ngựa)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "牛 + 具", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰牛具", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "具", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "牛", "Unihan_Simplified (Chữ Giản thể)": "犋", "Unihan_Traditional (Chữ Phồn thể)": "犋", "Pinyin_Xie": "jù", "Âm Hán Việt_Xie": "cụ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Lượng từ | 量词 | Danh từ | 名词 | Thường dùng làm lượng từ đi sau số từ để đếm số lượng cặp gia súc kéo cày. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('眵', '{"9000": "6944.0", "Chữ Trung Quốc": "眵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 11 | nét | 目 | mục | biểu nghĩa | mắt | 多 | đa | biểu âm | nhiều | 眵 = 目 (Mục, biểu nghĩa: mắt) + 多 (Đa, biểu âm); chữ hình thanh. Bộ 目 chỉ mắt, phần 多 cho âm chī.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"si\" (chī): bộ 目 (mắt) + âm 多 — nhiều ghèn đọng ở khóe mắt sau giấc ngủ dài. | Gương Hán-Việt | Chữ 眵 ít dùng trong từ Hán-Việt tiêu chuẩn; dùng trong y học mắt cổ. | Mở khoá kiến thức | Biết 眵 mở khoá từ: 眵目糊 (ghèn mắt), từ vựng y học và sinh hoạt hàng ngày.", "Tự nguyên_Xie": "眵 là chữ hình thanh: bộ 目 (mục — mắt) biểu nghĩa chỉ trạng thái liên quan đến mắt; phần 多 (đa — nhiều) biểu âm cho âm chī. Nghĩa gốc là mắt bị thương hoặc đau ở góc mắt; nghĩa phái sinh là ghèn mắt (chất dịch đọng ở khóe mắt sau khi ngủ dậy). Từ 眵目糊 (chī mùhú) dùng phổ biến để chỉ ghèn mắt. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rỉ mắt, dử mắt", "Hạng Tần Suất (Jun Da)": "6944.0", "Tần Suất % (Jun Da)": "99.9967075619", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 多", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目多", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "多", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "眵", "Unihan_Traditional (Chữ Phồn thể)": "眵", "Pinyin_Xie": "chī", "Âm Hán Việt_Xie": "si", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ làm tân ngữ cho động từ hoặc kết hợp thành từ ghép chỉ dịch mắt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('耩', '{"9000": "6945.0", "Chữ Trung Quốc": "耩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 耒 | Số nét | 16 | nét | 耒 | lồi | biểu nghĩa | cày, nông cụ | 冓 | cấu | biểu âm | xây dựng, giao thoa | 耩 = 耒 (Lồi, biểu nghĩa: cày/nông cụ) + 冓 (Cấu, biểu âm); chữ hình thanh. Bộ 耒 chỉ nông cụ, phần 冓 cho âm jiǎng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giảng\" (jiǎng): bộ 耒 (cày) — dùng cày kéo thành hàng rồi thả hạt vào — kỹ thuật gieo hạt cổ truyền. | Gương Hán-Việt | Chữ 耩 ít dùng trong từ Hán-Việt tiêu chuẩn; gặp trong từ điển nông nghiệp cổ. | Mở khoá kiến thức | Biết 耩 mở khoá từ vựng kỹ thuật nông nghiệp cổ Bắc Trung Hoa: gieo hạt theo luống.", "Tự nguyên_Xie": "耩 là chữ hình thanh: bộ 耒 (lồi — cái cày) biểu nghĩa chỉ nông cụ; phần 冓 biểu âm cho âm jiǎng. Nghĩa là gieo hạt bằng cách dùng cày rạch luống, thuật ngữ nông nghiệp vùng miền Bắc Trung Quốc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gieo giống hoặc rải phân bằng nông cụ đánh luống gieo hạt; dụng cụ đánh luống gieo hạt; cày ruộng; giẫy cỏ, làm cỏ", "Hạng Tần Suất (Jun Da)": "6945.0", "Tần Suất % (Jun Da)": "99.9967111794", "GavinGrover_Once (Chiết tự trực tiếp)": "耒 + 冓", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰耒冓", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冓", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "耒", "Unihan_Simplified (Chữ Giản thể)": "耩", "Unihan_Traditional (Chữ Phồn thể)": "耩", "Pinyin_Xie": "jiǎng", "Âm Hán Việt_Xie": "giảng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ đứng trước danh từ chỉ hạt giống hoặc ruộng đất để mô tả việc gieo trồng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('筢', '{"9000": "6946.0", "Chữ Trung Quốc": "筢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 13 | nét | 竹 | trúc | biểu nghĩa | tre, trúc | 杷 | bả | biểu âm | cào, tay cầm | 筢 thuộc bộ 竹 (trúc — tre), cấu tạo nội bộ chưa được Wiktionary phân tích. Có thể là hình thanh: bộ 竹 biểu nghĩa (chất liệu tre), phần 杷 biểu âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bả\" (pá): bộ 竹 (tre) — chiếc cào làm từ tre, quét dọn ruộng vườn. | Gương Hán-Việt | Chữ 筢 ít dùng trong từ Hán-Việt; dùng trong từ 筢子 (pázi — cái cào). | Mở khoá kiến thức | Biết 筢 mở khoá từ vựng nông cụ: 筢子 (cái cào bằng tre).", "Tự nguyên_Xie": "筢 thuộc bộ 竹 (trúc — tre), nghĩa là chiếc cào bằng tre (dùng cào cỏ, cào lá). Wiktionary không có phân tích cấu tạo. Chữ tạo muộn, chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái bồ cào, cái cào cỏ", "Hạng Tần Suất (Jun Da)": "6946.0", "Tần Suất % (Jun Da)": "99.9967147969", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 把", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮把", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "把", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "筢", "Unihan_Traditional (Chữ Phồn thể)": "筢", "Pinyin_Xie": "pá", "Âm Hán Việt_Xie": "ba", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ nông cụ cầm tay dùng để cào cỏ hoặc rơm rạ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('躔', '{"9000": "6947.0", "Chữ Trung Quốc": "躔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 22 | nét | 躔 | triền | tượng hình | dấu vết đi lại, quỹ đạo thiên thể | 躔 thuộc bộ 足 (túc — chân), cấu tạo nội bộ chưa được Wiktionary phân tích chi tiết. Nghĩa cổ là dẫm theo dấu, bước đi; nghĩa thiên văn là quỹ đạo/hành trình của thiên thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"triền\" (躔): bộ 足 (chân) — bước chân của sao trên bầu trời, quỹ đạo triền miên không dứt. | Gương Hán-Việt | 躔 xuất hiện trong 日躔 (nhật triền — hành trình của mặt trời), 躔次 (triền thứ — cung bậc quỹ đạo). | Mở khoá kiến thức | Biết 躔 mở khoá từ vựng thiên văn cổ: 日躔 (quỹ đạo mặt trời), 廿八躔 (28 cung thiên văn).", "Tự nguyên_Xie": "躔 thuộc bộ 足 (túc — chân), nghĩa cổ là bước đi theo dấu vết, dẫm lên; nghĩa văn học là chuyển động quỹ đạo của thiên thể. Wiktionary ghi {{Han etym}} nhưng không phân tích cấu tạo. Chữ dùng trong thơ văn cổ và thiên văn học cổ điển Trung Hoa. Chưa có nguồn học thuật bổ sung. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xéo, giẫm lên; quỹ đạo của sao", "Hạng Tần Suất (Jun Da)": "6947.0", "Tần Suất % (Jun Da)": "99.9967184144", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 廛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊廛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "廛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "躔", "Unihan_Traditional (Chữ Phồn thể)": "躔", "Pinyin_Xie": "chán", "Âm Hán Việt_Xie": "triền", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ chỉ sự vận hành của các thiên thể hoặc danh từ chỉ quỹ đạo của chúng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鬏', '{"9000": "6948.0", "Chữ Trung Quốc": "鬏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 髟 | Số nét | 19 | nét | 髟 | tiêu | biểu nghĩa | tóc, mái tóc | 丩 | biểu âm | xoắn, cuộn | 鬏 thuộc bộ 髟 (tiêu — tóc mái dài), cấu tạo nội bộ chưa được Wiktionary phân tích chi tiết. Nghĩa là búi tóc/chóp tóc vấn gọn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cữu\" (jiū): bộ 髟 (tóc) — búi tóc vấn chặt gọn lên đỉnh đầu, xoắn tròn như con ốc. | Gương Hán-Việt | Chữ 鬏 ít dùng trong từ Hán-Việt; dùng trong 鬏子 (jiūzi — búi tóc nhỏ). | Mở khoá kiến thức | Biết 鬏 mở khoá từ vựng tóc tai truyền thống: búi tóc, chóp tóc cổ phong.", "Tự nguyên_Xie": "鬏 thuộc bộ 髟 (tiêu — tóc dài phủ xuống), nghĩa là búi tóc (chignon). Wiktionary ghi {{Han etym}} nhưng không phân tích cấu tạo. Chữ tạo muộn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "búi tóc", "Hạng Tần Suất (Jun Da)": "6948.0", "Tần Suất % (Jun Da)": "99.9967220319", "GavinGrover_Once (Chiết tự trực tiếp)": "髟 + 秋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱髟秋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "秋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "髟", "Unihan_Simplified (Chữ Giản thể)": "鬏", "Unihan_Traditional (Chữ Phồn thể)": "鬏", "Pinyin_Xie": "jiū", "Âm Hán Việt_Xie": "thu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ kiểu tóc búi của phụ nữ hoặc trẻ em. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('黪', '{"9000": "6949.0", "Chữ Trung Quốc": "黪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 黑 | Số nét | 20 | nét | 黑 | hắc | biểu nghĩa | đen | 参 | sâm | biểu âm | sâm, tham gia | 黪 thuộc bộ 黑 (hắc — đen), cấu tạo nội bộ chưa được Wiktionary phân tích chi tiết. Có thể là hình thanh: bộ 黑 biểu nghĩa (màu tối), phần 参 gần âm cǎn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thảm\" (cǎn): bộ 黑 (đen) — màu xám tối ảm đạm, như bầu trời u ám cǎn. | Gương Hán-Việt | Chữ 黪 ít dùng trong từ Hán-Việt; gặp trong thành ngữ văn học: 黲淡 (xám xịt), 黲白 (trắng ảm đạm). | Mở khoá kiến thức | Biết 黪 mở khoá từ vựng màu sắc văn học cổ: 黲淡, 黲黷.", "Tự nguyên_Xie": "黪 thuộc bộ 黑 (hắc — đen/tối), nghĩa văn học là màu xám tối, tối mờ, ảm đạm. Wiktionary ghi {{Han etym}} nhưng không phân tích cấu tạo. Chữ dùng trong thơ văn cổ tả màu sắc u tối. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xanh đen nhạt; đen; xanh; mờ tối; mờ mịt", "Hạng Tần Suất (Jun Da)": "6949.0", "Tần Suất % (Jun Da)": "99.9967256494", "GavinGrover_Once (Chiết tự trực tiếp)": "黑 + 参", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰黑参", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "参", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "黑", "Unihan_Simplified (Chữ Giản thể)": "黪", "Unihan_Traditional (Chữ Phồn thể)": "黲", "Pinyin_Xie": "cǎn", "Âm Hán Việt_Xie": "thảm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ đứng trước danh từ để miêu tả màu sắc u ám hoặc bầu trời tối tăm. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('祔', '{"9000": "6951.0", "Chữ Trung Quốc": "祔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 9 | nét | 示 | thị | biểu nghĩa | thần linh, tế lễ | 付 | phó | biểu âm | giao phó, trả | 祔 thuộc bộ 示 (thị — thần linh, tế lễ), cấu tạo nội bộ chưa được Wiktionary phân tích. Có thể là hình thanh: bộ 示 biểu nghĩa, 付 biểu âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phụ\" (fù): bộ 示 (lễ tế) — lễ nhập bài vị tổ tiên vào miếu thờ sau ba năm tang. | Gương Hán-Việt | Chữ 祔 ít dùng trong từ Hán-Việt thông dụng; gặp trong văn bản nghi lễ Nho giáo cổ. | Mở khoá kiến thức | Biết 祔 mở khoá từ vựng nghi lễ tang ma Nho giáo: hợp táng, tế phụ.", "Tự nguyên_Xie": "祔 thuộc bộ 示 (thị — tế lễ, thần linh), nghĩa là hợp táng hoặc tế lễ sau tang khi hết 3 năm để nhập bài vị vào miếu tổ tiên. Wiktionary không có phân tích cấu tạo. Chữ dùng trong nghi lễ tang ma Nho giáo. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tế phụ (hết tang 3 năm); chôn chung, hợp táng", "Hạng Tần Suất (Jun Da)": "6951.0", "Tần Suất % (Jun Da)": "99.9967328844", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 付", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻付", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "付", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "祔", "Unihan_Traditional (Chữ Phồn thể)": "祔", "Pinyin_Xie": "fù", "Âm Hán Việt_Xie": "phụ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ trong nghi lễ cúng bái tổ tiên hoặc mai táng thời xưa. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('箠', '{"9000": "6952.0", "Chữ Trung Quốc": "箠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 14 | nét | 竹 | trúc | biểu nghĩa | tre, trúc | 垂 | thùy | biểu âm | rủ xuống, buông | 箠 = 竹 (Trúc, biểu nghĩa: tre/trúc) + 垂 (Thùy, biểu âm); chữ hình thanh. Bộ 竹 chỉ vật liệu tre, phần 垂 cho âm chuí.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thùy\" (chuí): bộ 竹 (tre) + 垂 (rủ) — chiếc roi tre rủ xuống, tiếng vút nghe rõ. | Gương Hán-Việt | Chữ 箠 ít dùng trong từ Hán-Việt thông dụng; gặp trong từ 箠楚 (roi vọt hình phạt). | Mở khoá kiến thức | Biết 箠 mở khoá từ vựng hình phạt cổ đại: 箠楚 (roi tre), 鞭箠 (roi đánh).", "Tự nguyên_Xie": "箠 là chữ hình thanh: bộ 竹 (trúc — tre) biểu nghĩa chỉ chất liệu; phần 垂 (thùy — rủ xuống) biểu âm cho âm chuí. Nghĩa là roi tre, gậy tre để đánh phạt; cũng dùng chỉ đòn roi trong hình phạt cổ đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vụt", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 垂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮垂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "垂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "箠", "Unihan_Traditional (Chữ Phồn thể)": "箠", "Pinyin_Xie": "chuí", "Âm Hán Việt_Xie": "chủy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ cây roi hoặc động từ chỉ hành động đánh phạt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('舲', '{"9000": "6953.0", "Chữ Trung Quốc": "舲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 舟 | Số nét | 11 | nét | 舟 | chu | biểu nghĩa | thuyền | 令 | lệnh | biểu âm | lệnh, sai khiến | 舲 thuộc bộ 舟 (chu — thuyền), cấu tạo nội bộ chưa được Wiktionary phân tích chi tiết. Có thể là hình thanh: bộ 舟 biểu nghĩa, phần 令 biểu âm gần âm líng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"linh\" (líng): bộ 舟 (thuyền) — con thuyền nhỏ có ô cửa sổ nhìn ra sông, nhẹ nhàng như tiếng líng. | Gương Hán-Việt | Chữ 舲 ít dùng trong từ Hán-Việt; gặp trong thơ văn cổ tả sông nước. | Mở khoá kiến thức | Biết 舲 giúp đọc thơ văn cổ điển Trung Hoa về cảnh sông nước.", "Tự nguyên_Xie": "舲 thuộc bộ 舟 (chu — thuyền), nghĩa là chiếc thuyền nhỏ có cửa sổ nhìn ra hai bên (houseboat nhỏ). Wiktionary ghi {{Han etym}} nhưng không phân tích cấu tạo. Chữ dùng trong văn học cổ điển tả cảnh sông nước. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thuyền nhỏ có cửa sổ bên mui", "Hạng Tần Suất (Jun Da)": "6953.0", "Tần Suất % (Jun Da)": "99.9967401194", "GavinGrover_Once (Chiết tự trực tiếp)": "舟 + 令", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舟令", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "令", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舟", "Unihan_Simplified (Chữ Giản thể)": "舲", "Unihan_Traditional (Chữ Phồn thể)": "舲", "Pinyin_Xie": "líng", "Âm Hán Việt_Xie": "linh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn học cổ để chỉ loại thuyền nhỏ chở khách. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蒷', '{"9000": "6954.0", "Chữ Trung Quốc": "蒷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 13 | nét | 蒷 | vân | tượng hình | tên cây | 蒷 thuộc bộ 艹 (thảo — thực vật), cấu tạo nội bộ chưa được Wiktionary phân tích. Chữ tạo muộn, nghĩa không rõ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vân\" (yún): bộ 艹 (cỏ) — một loài thực vật không rõ tên, ít gặp trong văn bản hiện đại. | Gương Hán-Việt | Chữ 蒷 không dùng trong từ Hán-Việt hiện đại. | Mở khoá kiến thức | Biết 蒷 giúp nhận diện các chữ thực vật cổ hiếm trong văn bản cổ điển.", "Tự nguyên_Xie": "蒷 thuộc bộ 艹 (thảo), nghĩa không rõ (có thể là tên một loài cây/chí?). Wiktionary không có phân tích cấu tạo. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Chí", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 員", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹員", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "員", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蒷", "Unihan_Traditional (Chữ Phồn thể)": "蒷", "Pinyin_Xie": "yún", "Âm Hán Việt_Xie": "vân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong thư tịch cổ để chỉ một loài thảo mộc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蜺', '{"9000": "6955.0", "Chữ Trung Quốc": "蜺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 14 | nét | 虫 | trùng | biểu nghĩa | sâu, côn trùng, sinh vật nhỏ | 兒 | nhi | biểu âm | trẻ con | 蜺 thuộc bộ 虫 (trùng — sinh vật nhỏ/côn trùng), cấu tạo nội bộ chưa được Wiktionary phân tích. Có thể là hình thanh: bộ 虫 biểu nghĩa, phần biểu âm cho âm ní.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nghê\" (ní): bộ 虫 (sinh vật) — cầu vồng phụ mờ ảo như con sâu nước nhiều màu sắc. | Gương Hán-Việt | Chữ 蜺 ít dùng trong từ Hán-Việt; gặp trong thơ văn cổ tả cầu vồng. | Mở khoá kiến thức | Biết 蜺 mở khoá từ vựng cổ về hiện tượng thiên nhiên: cầu vồng phụ trong thơ văn.", "Tự nguyên_Xie": "蜺 thuộc bộ 虫 (trùng), nghĩa là cầu vồng hoặc chuồn chuồn — trong cổ văn dùng chỉ cầu vồng thứ hai/sắc mờ hơn. Wiktionary không có phân tích cấu tạo. Chữ tạo muộn, chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhiều màu; cầu vồng", "Hạng Tần Suất (Jun Da)": "3602.0", "Tần Suất % (Jun Da)": "99.5970672816", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 兒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫兒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "霓", "Unihan_Traditional (Chữ Phồn thể)": "蜺", "Pinyin_Xie": "ní", "Âm Hán Việt_Xie": "nghê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ đứng sau danh từ khác hoặc đi đôi với hồng để chỉ cầu vồng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('襢', '{"9000": "6956.0", "Chữ Trung Quốc": "襢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 18 | nét | 衤 | y | biểu nghĩa | quần áo | 亶 | đản | biểu âm | thực sự, thành thật | 襢 = 衤 (Y, biểu nghĩa: quần áo) + 亶 (Đản, biểu âm); chữ hình thanh. Bộ 衤 chỉ quần áo/trang phục, phần 亶 cho âm tǎn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đản\" (tǎn): bộ 衤 (áo) — áo được cởi ra, để lộ thân trần. | Gương Hán-Việt | Chữ 襢 ít dùng trong từ Hán-Việt thông dụng; gặp trong từ cổ chỉ trạng thái cởi trần. | Mở khoá kiến thức | Biết 襢 mở khoá từ vựng cổ về trang phục và nghi lễ: trạng thái cởi trần trong văn bản lễ nghi.", "Tự nguyên_Xie": "襢 là chữ hình thanh: bộ 衤 (y — quần áo) biểu nghĩa; phần 亶 biểu âm cho âm tǎn. Nghĩa là cởi trần, không mặc áo. Wiktionary ghi cấu tạo nhưng không có giải thích nghĩa chi tiết. Chữ dùng trong văn bản cổ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cởi trần", "Hạng Tần Suất (Jun Da)": "6956.0", "Tần Suất % (Jun Da)": "99.9967509719", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 亶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤亶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "襢", "Unihan_Traditional (Chữ Phồn thể)": "襢", "Pinyin_Xie": "tǎn", "Âm Hán Việt_Xie": "đản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ miêu tả hành động cởi bỏ y phục để lộ phần thân trên. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('謺', '{"9000": "6957.0", "Chữ Trung Quốc": "謺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 18 | nét | 言 | ngôn | biểu nghĩa | lời nói | 執 | chấp | biểu âm | nắm giữ, chấp hành | 謺 = 言 (Ngôn, biểu nghĩa: lời nói) + 執 (Chấp, biểu âm); chữ hình thanh. Bộ 言 chỉ hành động ngôn ngữ, phần 執 cho âm zhé.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"triếp\" (zhé): bộ 言 (lời) + 執 (nắm chặt) — nắm chặt từng lời nói, thận trọng trong ngôn từ. | Gương Hán-Việt | Chữ 謺 không dùng trong từ Hán-Việt hiện đại. | Mở khoá kiến thức | Biết 謺 giúp nhận diện chữ cổ liên quan đến lời nói trong văn bản cổ điển.", "Tự nguyên_Xie": "謺 là chữ hình thanh: bộ 言 (ngôn — lời nói) biểu nghĩa; phần 執 (chấp) biểu âm cho âm zhé. Wiktionary ghi rfdef — định nghĩa chưa rõ. Chữ cổ liên quan đến lời nói/văn tự. Chưa có nguồn học thuật. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Con tem", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "執 + 言", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱執言", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "執", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "謺", "Unihan_Traditional (Chữ Phồn thể)": "謺", "Pinyin_Xie": "zhé", "Âm Hán Việt_Xie": "triếp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ miêu tả trạng thái nói năng nhiều hoặc tính cách cứng rắn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('劐', '{"9000": "6958.0", "Chữ Trung Quốc": "劐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 刀 | Số nét | 15 | nét | 劐 | hoắc | tượng hình | rạch, xẻ | 劐 thuộc bộ 刀 (đao — dao), cấu tạo nội bộ chưa được Wiktionary phân tích chi tiết. Nghĩa là rạch, xẻ bằng dao.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoắc\" (hoắc): bộ đao (dao) — tiếng dao rạch nhanh một nhát, gọn và dứt khoát. | Gương Hán-Việt | Chữ 劐 ít dùng trong từ Hán-Việt; dùng trong phương ngữ chỉ hành động rạch nhanh. | Mở khoá kiến thức | Biết 劐 mở khoá từ vựng phương ngữ: rạch, xẻ bằng dao sắc trong nông thôn Trung Hoa.", "Tự nguyên_Xie": "劐 thuộc bộ 刀 (đao — dao), nghĩa là rạch hoặc xẻ bằng vật sắc bén. Wiktionary ghi {{Han etym}} nhưng không phân tích cấu tạo. Chữ tạo muộn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rạch, xẻ", "Hạng Tần Suất (Jun Da)": "6958.0", "Tần Suất % (Jun Da)": "99.9967582069", "GavinGrover_Once (Chiết tự trực tiếp)": "蒦 + 刂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰蒦刂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "蒦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "刂", "Unihan_Simplified (Chữ Giản thể)": "劐", "Unihan_Traditional (Chữ Phồn thể)": "劐", "Pinyin_Xie": "huō", "Âm Hán Việt_Xie": "hoát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ chỉ hành động dùng dao sắc rạch hoặc xẻ một vật. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('搋', '{"9000": "6959.0", "Chữ Trung Quốc": "搋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 13 | nét | 手 | thủ | biểu nghĩa | tay | 虒 | biểu âm | 搋 = 手 (Thủ, biểu nghĩa: tay) + 虒 (biểu âm); chữ hình thanh. Bộ 手 chỉ hành động bằng tay, phần 虒 cho âm chuāi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"si\" (chuāi): bộ 手 (tay) — đôi tay nhào bột mạnh mẽ, đẩy vào kéo ra. | Gương Hán-Việt | Chữ 搋 ít dùng trong từ Hán-Việt; dùng trong 搋子 (chuāizi — dụng cụ thông cống). | Mở khoá kiến thức | Biết 搋 mở khoá từ: 搋子 (dụng cụ thông cống), từ vựng làm bếp và gia dụng.", "Tự nguyên_Xie": "搋 là chữ hình thanh: bộ 手 (thủ — tay) biểu nghĩa chỉ hành động dùng tay; phần 虒 biểu âm cho âm chuāi. Nghĩa là nhào/nhồi bột bằng tay, hoặc thông cống bằng tay có bao cao su (搋子). Cũng dùng để tả việc vò bóp. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhào, nhồi, vò", "Hạng Tần Suất (Jun Da)": "6959.0", "Tần Suất % (Jun Da)": "99.9967654418", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 虒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌虒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "虒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "搋", "Unihan_Traditional (Chữ Phồn thể)": "搋", "Pinyin_Xie": "chuāi", "Âm Hán Việt_Xie": "trỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ biểu thị động tác nhào bột hoặc giặt vò quần áo. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('醊', '{"9000": "6960.0", "Chữ Trung Quốc": "醊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 15 | nét | 酉 | dậu | biểu nghĩa | rượu, bình rượu | 叕 | chuyết | biểu âm | nối liền | 醊 thuộc bộ 酉 (dậu — rượu, bình rượu), cấu tạo nội bộ chưa được Wiktionary phân tích chi tiết. Nghĩa là rót rượu xuống đất tế lễ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chuyết\" (zhuì): bộ 酉 (rượu) — rót rượu xuống đất khấn vái tổ tiên thần linh. | Gương Hán-Việt | Chữ 醊 ít dùng trong từ Hán-Việt; gặp trong từ nghi lễ cổ: 醊祭 (tế rượu). | Mở khoá kiến thức | Biết 醊 mở khoá từ vựng tế lễ cổ: nghi thức rót rượu xuống đất trong lễ cúng.", "Tự nguyên_Xie": "醊 thuộc bộ 酉 (dậu — rượu), nghĩa là rót rượu xuống đất trong nghi lễ cúng tế; cũng chỉ hành động liên tiếp dâng cúng. Wiktionary ghi {{Han etym}} nhưng không phân tích cấu tạo. Chữ dùng trong văn bản nghi lễ và văn học cổ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lấy rượu rót xuống đất để tế", "Hạng Tần Suất (Jun Da)": "6960.0", "Tần Suất % (Jun Da)": "99.9967690593", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 叕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉叕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "叕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "醊", "Unihan_Traditional (Chữ Phồn thể)": "醊", "Pinyin_Xie": "zhuì", "Âm Hán Việt_Xie": "chuyết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ trong văn cảnh tế lễ cổ đại để chỉ nghi thức rót rượu xuống đất. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('廒', '{"9000": "6961.0", "Chữ Trung Quốc": "廒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 广 | Số nét | 13 | nét | 广 | quảng | biểu nghĩa | nhà, công trình | 敖 | ngao | biểu âm | ngao du, tự do | 廒 thuộc bộ 广 (quảng — mái nhà, công trình), cấu tạo nội bộ chưa được Wiktionary phân tích. Có thể là hình thanh: bộ 广 biểu nghĩa, phần 敖 biểu âm cho âm áo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngao\" (áo): bộ 广 (nhà) — kho chứa thóc rộng lớn, đầy ắp lúa sau mùa gặt. | Gương Hán-Việt | Chữ 廒 ít dùng trong từ Hán-Việt; dùng trong từ 廒仓 (áo cāng — kho thóc). | Mở khoá kiến thức | Biết 廒 mở khoá từ vựng quản lý lương thực cổ: 廒仓 (kho thóc), từ vựng hành chính cổ đại.", "Tự nguyên_Xie": "廒 thuộc bộ 广 (quảng — công trình, mái nhà), nghĩa là kho vựa đựng thóc gạo. Wiktionary không có phân tích cấu tạo. Chữ tạo muộn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái vựa đựng thóc", "Hạng Tần Suất (Jun Da)": "6961.0", "Tần Suất % (Jun Da)": "99.9967726768", "GavinGrover_Once (Chiết tự trực tiếp)": "广 + 敖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴广敖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "广", "Unihan_Simplified (Chữ Giản thể)": "廒", "Unihan_Traditional (Chữ Phồn thể)": "廒", "Pinyin_Xie": "áo", "Âm Hán Việt_Xie": "ngao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ nhà kho chuyên dụng để tích trữ lương thực. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('洚', '{"9000": "6962.0", "Chữ Trung Quốc": "洚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 9 | nét | 氵 | thủy | biểu nghĩa | nước | 夅 | giáng | biểu âm | xuống | 洚 thuộc bộ 氵 (thủy — nước), cấu tạo nội bộ chưa được Wiktionary phân tích chi tiết. Nghĩa là lũ lụt, nước tràn ngập.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giáng\" (jiàng): bộ 氵 (nước) — nước từ trên trời ào xuống (jiàng = xuống), thành lũ lụt mênh mông. | Gương Hán-Việt | Chữ 洚 ít dùng trong từ Hán-Việt; gặp trong 洚水 (lũ lụt) trong văn bản cổ. | Mở khoá kiến thức | Biết 洚 mở khoá từ vựng thiên tai cổ: 洚水 (lũ lụt đại hồng thủy).", "Tự nguyên_Xie": "洚 thuộc bộ 氵 (thủy — nước), nghĩa là lũ lụt, nước tràn. Wiktionary ghi {{Han etym}} nhưng không phân tích cấu tạo. Dùng trong từ 洚水 (jiàng shuǐ — nước lũ) và 洚洞 (nước chảy mạnh). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước tràn, ngập", "Hạng Tần Suất (Jun Da)": "6962.0", "Tần Suất % (Jun Da)": "99.9967762943", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 夅", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵夅", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夅", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "洚", "Unihan_Traditional (Chữ Phồn thể)": "洚", "Pinyin_Xie": "jiàng", "Âm Hán Việt_Xie": "giáng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ bổ nghĩa cho danh từ chỉ nguồn nước hoặc lũ lụt trong văn ngôn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('胲', '{"9000": "6963.0", "Chữ Trung Quốc": "胲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 10 | nét | 月 | nguyệt | biểu nghĩa | thịt (biến thể bộ 肉) | 亥 | hợi | biểu âm | can chi thứ 12 | 胲 thuộc bộ 月 (nguyệt — biến thể bộ 肉, thịt/cơ thể), cấu tạo nội bộ chưa được Wiktionary phân tích chi tiết. Nghĩa liên quan đến hydroxylamine (hóa chất).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hợi\" (hǎi): bộ 月/肉 (cơ thể) — chữ Hán hóa học chỉ hydroxylamine, hợp chất cơ thể đặc biệt. | Gương Hán-Việt | Chữ 胲 ít dùng trong từ Hán-Việt; là thuật ngữ hóa học: 羟胺/胲 (hydroxylamine). | Mở khoá kiến thức | Biết 胲 mở khoá từ vựng hóa học Hán: hydroxylamine và các hợp chất nitrogen cơ thể.", "Tự nguyên_Xie": "胲 thuộc bộ 月 (biến thể bộ 肉 nhục — thịt/cơ thể), nghĩa là hydroxylamine (NH₂OH) trong hóa học hiện đại — một từ phiên âm/dịch nghĩa Hán hóa. Wiktionary ghi {{Han etym}} nhưng không phân tích cấu tạo. Chữ tạo cho từ vựng khoa học hiện đại. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hy-đrô xy-la-min", "Hạng Tần Suất (Jun Da)": "6963.0", "Tần Suất % (Jun Da)": "99.9967799118", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 亥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月亥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "胲", "Unihan_Traditional (Chữ Phồn thể)": "胲", "Pinyin_Xie": "hǎi", "Âm Hán Việt_Xie": "hợi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong thuật ngữ giải phẫu cơ thể người hoặc trong hóa học hiện đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('韥', '{"9000": "6964.0", "Chữ Trung Quốc": "韥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 韋 | Số nét | 24 | nét | 韥 | độc | tượng hình | bao đựng cung tên | 韥 thuộc bộ 韋 (vi — da thuộc), cấu tạo nội bộ chưa được Wiktionary phân tích. Chữ liên quan đến đồ dùng quân sự.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"độc\" (độc): bộ 韋 (da) — bao da đựng cung tên của người chiến binh. | Gương Hán-Việt | Chữ 韥 không dùng trong từ Hán-Việt hiện đại. | Mở khoá kiến thức | Biết 韥 giúp nhận diện chữ cổ liên quan đến đồ dùng quân sự bằng da.", "Tự nguyên_Xie": "韥 thuộc bộ 韋 (vi — da thuộc), nghĩa chưa rõ ràng trong từ điển hiện đại. Wiktionary không có phân tích cấu tạo. Chữ tạo muộn, chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "韥", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "韋 + 賣", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰韋賣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "賣", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "韋", "Unihan_Simplified (Chữ Giản thể)": "韥", "Unihan_Traditional (Chữ Phồn thể)": "韥", "Pinyin_Xie": "dú", "Âm Hán Việt_Xie": "độc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ loại bao da chuyên dụng thời cổ để bảo quản binh khí hoặc roi ngựa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('饘', '{"9000": "6965.0", "Chữ Trung Quốc": "饘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 21 | nét | 食 | thực | biểu nghĩa | thức ăn, ăn uống | 亶 | đản | biểu âm | thực sự | 饘 thuộc bộ 食 (thực — thức ăn/ăn uống), cấu tạo nội bộ chưa được Wiktionary phân tích chi tiết. Nghĩa là cháo đặc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chiêm\" (zhān): bộ 食 (thức ăn) — bát cháo đặc thơm lừng, nuôi dưỡng người bệnh và người già. | Gương Hán-Việt | Chữ 饘 ít dùng trong từ Hán-Việt; gặp trong từ 饘粥 (zhān zhōu — cháo đặc) và văn học cổ. | Mở khoá kiến thức | Biết 饘 mở khoá từ vựng ẩm thực cổ: 饘粥 (cháo đặc), từ thực phẩm trong y học cổ.", "Tự nguyên_Xie": "饘 thuộc bộ 食 (thực — thức ăn), nghĩa là cháo đặc (cháo nấu từ gạo hoặc ngũ cốc đặc sệt). Wiktionary ghi {{Han etym}} nhưng không phân tích cấu tạo. Chữ dùng trong văn học cổ điển và y học truyền thống Trung Hoa. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "阘", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "飠 + 亶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰飠亶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "飠", "Unihan_Simplified (Chữ Giản thể)": "𫗴", "Unihan_Traditional (Chữ Phồn thể)": "饘", "Pinyin_Xie": "zhān", "Âm Hán Việt_Xie": "chiêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ món cháo nấu đặc trong thư tịch cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('馂', '{"9000": "6966.0", "Chữ Trung Quốc": "馂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 10 | nét | 食 | thực | biểu nghĩa | thức ăn, ăn uống | 俊 | tuấn | biểu âm | tài giỏi, tuấn tú | 馂 thuộc bộ 食 (thực — thức ăn/ăn uống), cấu tạo nội bộ chưa được Wiktionary phân tích chi tiết. Nghĩa là đồ ăn thừa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuấn\" (jùn): bộ 食 (thức ăn) — phần đồ ăn còn lại sau tiệc, không nên lãng phí. | Gương Hán-Việt | Chữ 馂 ít dùng trong từ Hán-Việt; gặp trong từ 餕餘 (đồ ăn thừa). | Mở khoá kiến thức | Biết 馂 mở khoá từ: 餕餘 (đồ ăn thừa, thức ăn dư), từ vựng nghi lễ ẩm thực cổ.", "Tự nguyên_Xie": "馂 thuộc bộ 食 (thực — thức ăn), nghĩa là đồ ăn thừa, thức ăn còn lại sau bữa. Wiktionary ghi rfdef — nghĩa chưa được xác nhận chính thức. Dùng trong từ 餕餘 (jùnyú — đồ ăn thừa). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đồ ăn thừa", "Hạng Tần Suất (Jun Da)": "6966.0", "Tần Suất % (Jun Da)": "99.9967907643", "GavinGrover_Once (Chiết tự trực tiếp)": "饣 + 夋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰饣夋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "饣", "Unihan_Simplified (Chữ Giản thể)": "馂", "Unihan_Traditional (Chữ Phồn thể)": "餕", "Pinyin_Xie": "jùn", "Âm Hán Việt_Xie": "tuấn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ phần thức ăn còn lại sau bữa tiệc hoặc sau khi cúng tế. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('筅', '{"9000": "6967.0", "Chữ Trung Quốc": "筅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 12 | nét | 竹 | trúc | biểu nghĩa | tre, trúc | 先 | tiên | biểu âm | trước, tiên phong | 筅 thuộc bộ 竹 (trúc — tre), cấu tạo nội bộ chưa được Wiktionary phân tích chi tiết. Có thể là hình thanh: bộ 竹 biểu nghĩa, phần 先 biểu âm cho âm xiǎn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiên\" (xiǎn): bộ 竹 (tre) — chiếc bàn chải tre vệ sinh nồi niêu, tiện lợi và thân thiện môi trường. | Gương Hán-Việt | Chữ 筅 ít dùng trong từ Hán-Việt; dùng trong 锅筅 (guō xiǎn — cọ rửa nồi). | Mở khoá kiến thức | Biết 筅 mở khoá từ vựng dụng cụ nhà bếp: cái bàn chải tre rửa nồi truyền thống.", "Tự nguyên_Xie": "筅 thuộc bộ 竹 (trúc — tre), nghĩa là cái bàn chải làm bằng tre (dùng rửa nồi, vệ sinh đồ bếp). Wiktionary ghi {{Han etym}} nhưng không phân tích cấu tạo. Chữ tạo muộn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái bàn chải làm bằng tre", "Hạng Tần Suất (Jun Da)": "6967.0", "Tần Suất % (Jun Da)": "99.9967943818", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 先", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮先", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "先", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "筅", "Unihan_Traditional (Chữ Phồn thể)": "筅", "Pinyin_Xie": "xiǎn", "Âm Hán Việt_Xie": "tiển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ dụng cụ làm bằng tre dùng để cọ rửa xoong nồi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鳆', '{"9000": "6968.0", "Chữ Trung Quốc": "鳆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 17 | nét | 鳆 | phục | tượng hình | loài hải sản, bào ngư | 鳆 là chữ dạng rút gọn của 鰒 (bào ngư). Chưa có dữ liệu cây thành phần rõ ràng trong nguồn anchor; chữ tạo muộn hoặc biến thể giản hoá của 鰒. Chưa có nguồn học thuật xác nhận cấu trúc hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phục\": bộ 魚 (cá) chỉ loài hải sản — bào ngư bám đá kiên trì như chữ 鳆 bám vào bộ cá, sống ở biển sâu. | Gương Hán-Việt | phục trong \"bào phục\" (bào ngư) | Mở khoá kiến thức | Biết 鳆 (phục) giúp nhận ra các từ chỉ hải sản biển sâu trong văn bản Hán cổ.", "Tự nguyên_Xie": "Tiểu triện | 鳆 là dạng giản hoá của 鰒. Chữ gốc 鰒 từ bộ 魚 (cá) kết hợp thành phần biểu âm, chỉ loài bào ngư, con hàu nhỏ sống dưới đáy biển. Anchor Wiktionary chỉ ghi {{Han etym}} không có chi tiết; chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con hàu nhỏ", "Hạng Tần Suất (Jun Da)": "6968.0", "Tần Suất % (Jun Da)": "99.9967979993", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 复", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼复", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "复", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鳆", "Unihan_Traditional (Chữ Phồn thể)": "鰒", "Pinyin_Xie": "fù", "Âm Hán Việt_Xie": "phục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong tên gọi cổ của loài bào ngư. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲊', '{"9000": "6969.0", "Chữ Trung Quốc": "鲊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 13 | nét | 鲊 | trá | tượng hình | cá muối ướp, cá hộp | 鲊 là dạng giản hoá của 鮓. Anchor không có cây thành phần; chữ thuộc bộ 魚 (cá), chỉ món cá muối lên men. Chưa có nguồn học thuật xác nhận cấu trúc chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trá\": bộ 魚 (cá) + ý nghĩa bảo quản — \"trá\" như \"giả\" (đóng giả), cá được ướp muối để giả tươi lâu dài. | Gương Hán-Việt | trá trong \"trá hải\" (thực phẩm biển muối) | Mở khoá kiến thức | Biết 鲊 (trá) giúp đọc văn bản ẩm thực cổ và hiểu các từ chỉ phương pháp bảo quản thực phẩm.", "Tự nguyên_Xie": "鲊 là dạng giản hoá của 鮓. Chữ gốc 鮓 từ bộ 魚 (cá), chỉ cách chế biến cá bằng muối và lên men — kỹ thuật bảo quản thực phẩm truyền thống của người Hán. Wiktionary chỉ ghi {{Han etym}} không có chi tiết cấu trúc; chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá muối, cá ướp, cá hộp", "Hạng Tần Suất (Jun Da)": "6969.0", "Tần Suất % (Jun Da)": "99.9968016168", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 乍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼乍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲊", "Unihan_Traditional (Chữ Phồn thể)": "鮓", "Pinyin_Xie": "zhǎ", "Âm Hán Việt_Xie": "trả", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ các món cá hoặc thịt được muối chua để bảo quản lâu ngày. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('篸', '{"9000": "6970.0", "Chữ Trung Quốc": "篸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 17 | nét | 竹 | trúc | biểu nghĩa | tre, vật dụng làm từ tre | 參 | tham | biểu âm | tham gia — cho âm đọc | 篸 là chữ hình thanh: 竹 (Trúc, biểu nghĩa — vật liệu tre) + 參 (Tham, biểu âm). Wiktionary xác nhận: {{Han compound|竹|參|ls=psc|c1=s|t1=bamboo|c2=p}}. Đây là dụng cụ làm từ tre.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sâm\": 竹 (tre) + 參 (sâm) — chiếc trâm cài tóc bằng tre quý như sâm, đẹp như nhánh cây. | Gương Hán-Việt | sâm trong \"trúc sâm\" (vật dụng tre) | Mở khoá kiến thức | Biết 篸 (sâm) giúp nhận ra từ chỉ vật dụng tre trong văn bản cổ điển.", "Tự nguyên_Xie": "Tiểu triện | 篸 là chữ hình thanh gồm 竹 (tre, biểu nghĩa) và 參 (biểu âm). Theo Wiktionary, chữ chỉ các vật dụng đan bằng tre như giỏ, hộp đựng, cái trâm cài tóc làm bằng tre. Âm đọc cǎn/cān xuất phát từ thành phần 參 (tham/sâm). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "篸", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 參", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮參", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "參", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "篸", "Unihan_Traditional (Chữ Phồn thể)": "篸", "Pinyin_Xie": "cǎn", "Âm Hán Việt_Xie": "sâm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này đóng vai trò danh từ chỉ một loại dụng cụ đựng đồ làm bằng tre. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('腄', '{"9000": "6971.0", "Chữ Trung Quốc": "腄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 12 | nét | 腄 | thuỳ | tượng hình | chai, cục chai trên tay chân | 腄 không có cây thành phần rõ ràng trong anchor. Từ glyphOrigin, chữ thuộc bộ 肉 (nhục — thịt), nhiều khả năng là hình thanh với thành phần biểu âm không rõ. Chưa có nguồn học thuật xác nhận đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thuỳ\": bộ 肉 (da thịt) — \"thuỳ\" âm gần \"thụt xuống\", da thịt 肉 bị áp lực lâu ngày sẽ dầy lên thành cục chai cứng. | Gương Hán-Việt | thuỳ trong nghĩa y học cổ (cục chai, vết chai) | Mở khoá kiến thức | Biết 腄 (thuỳ) giúp đọc văn bản y học cổ Trung Hoa về bệnh ngoài da.", "Tự nguyên_Xie": "Tiểu triện | 腄 thuộc bộ 肉 (thịt, da thịt), chỉ cục chai hoặc vết cứng trên da. Wiktionary ghi nhiều âm đọc: chuí, hóu, chuái — cho thấy chữ có thể dùng trong nhiều ngữ cảnh khác nhau. Nguồn học thuật không đầy đủ; chưa có nguồn học thuật xác nhận cấu trúc chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vết sẹo, vết chai trên tay chân; phần xương nối ở chân ngựa hoặc chim; hông, mông; tên một huyện thời xưa", "Hạng Tần Suất (Jun Da)": "6971.0", "Tần Suất % (Jun Da)": "99.9968124693", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 垂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月垂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "垂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "腄", "Unihan_Traditional (Chữ Phồn thể)": "腄", "Pinyin_Xie": "chuí", "Âm Hán Việt_Xie": "chuỷ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu làm danh từ chỉ các bộ phận cơ thể hoặc vết chai sạn trên da. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('臑', '{"9000": "6972.0", "Chữ Trung Quốc": "臑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 18 | nét | 臑 | nhu | tượng hình | phần thịt mềm trên xương cánh tay | 臑 không có cây thành phần trong anchor. Từ bộ 肉 (nhục), chữ chỉ phần thịt mềm, non trên cánh tay hoặc vai. Wiktionary chỉ ghi {{Han etym}} mà không mô tả cấu trúc chi tiết. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhu\": 肉 (thịt) mềm — \"nhu\" như \"nhu mì, mềm mại\", phần thịt non nhất trên cánh tay, mềm như nhung. | Gương Hán-Việt | nhu trong \"nhu nhuyễn\" (mềm mại), phần thịt mềm | Mở khoá kiến thức | Biết 臑 (nhu) giúp đọc văn bản y học cổ và các văn bản lễ nghi ẩm thực Trung Hoa cổ đại.", "Tự nguyên_Xie": "Tiểu triện | 臑 thuộc bộ 肉 (thịt), chỉ phần thịt mềm, non trên cánh tay thú vật hoặc người. Trong y học cổ điển Trung Hoa và các văn bản lễ nghi, 臑 được dùng để chỉ phần thịt vai hoặc trên cánh tay. Wiktionary không cung cấp chi tiết cấu trúc; chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cánh tay (chỉ phần tay từ vai đến khuỷu); chân trước; chi trước (của thú vật nói trong sách cổ)", "Hạng Tần Suất (Jun Da)": "6972.0", "Tần Suất % (Jun Da)": "99.9968160868", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 需", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月需", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "需", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "臑", "Unihan_Traditional (Chữ Phồn thể)": "臑", "Pinyin_Xie": "nào", "Âm Hán Việt_Xie": "nhu, nao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ phần thịt ở vai hoặc chi trước của động vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('诐', '{"9000": "6973.0", "Chữ Trung Quốc": "诐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 7 | nét | 讠 | ngôn | biểu nghĩa | lời nói, ngôn từ | 皮 | bì | biểu âm | da, lớp ngoài — cho âm đọc | 诐 là dạng giản thể của 詖. Wiktionary ghi: {{Han simp|詖|f=言|t=讠}} — bộ 言 (ngôn) giản hoá thành 讠 (biểu nghĩa: lời nói), 皮 (bì, biểu âm). Chữ hình thanh: âm lấy từ 皮, nghĩa liên quan đến lời nói thiên vị, biện bác.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ba\": 讠 (lời nói) + 皮 (da bề ngoài) — \"ba\" như lời nói chỉ trơn tru bề ngoài (\"da\"), thiếu thực chất, một chiều, ngụy biện. | Gương Hán-Việt | ba trong \"thiên ba\" (lời nói thiên lệch, một chiều) | Mở khoá kiến thức | Biết 诐/詖 (ba) giúp đọc văn bản triết học Nho gia về các loại lời nói sai lầm.", "Tự nguyên_Xie": "Tiểu triện | 诐 là dạng giản thể của 詖. Chữ gốc 詖 gồm 言 (lời nói, biểu nghĩa) và thành phần biểu âm. Nghĩa gốc: lời nói thiên lệch, lý luận lệch lạc, biện bác một chiều. Trong kinh điển, 詖 (诐) chỉ những lời lẽ sai trái, ngụy biện. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vẹo, lệch2. biện luận; nịnh nọt", "Hạng Tần Suất (Jun Da)": "6973.0", "Tần Suất % (Jun Da)": "99.9968197043", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 皮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠皮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "皮", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "诐", "Unihan_Traditional (Chữ Phồn thể)": "詖", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "bí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này thường dùng làm tính từ để chỉ tính chất lệch lạc hoặc hành vi nịnh hót. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('仳', '{"9000": "6974.0", "Chữ Trung Quốc": "仳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 6 | nét | 亻 | nhân | biểu nghĩa | người | 比 | tỷ | biểu âm | so sánh, cạnh nhau — cho âm đọc | 仳 là chữ hình thanh: 亻 (Nhân, biểu nghĩa — người) + 比 (Tỷ, biểu âm). Anchor không nêu rõ cấu trúc nhưng từ glyphOrigin có thể suy ra. Nghĩa gốc: rời nhau, chia ly, đặc biệt dùng cho cặp vợ chồng ly dị.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tỷ\": 亻 (người) — \"tỷ\" như \"tỷ lệ so sánh\", hai người so sánh rồi chia lìa, mỗi người một hướng. | Gương Hán-Việt | tỷ trong \"tỷ ly\" (chia tay, ly biệt) | Mở khoá kiến thức | Biết 仳 (tỷ) giúp đọc thơ cổ và kinh điển Nho gia về chủ đề chia ly, ly hôn.", "Tự nguyên_Xie": "Tiểu triện | 仳 là chữ hình thanh gồm 亻 (người, biểu nghĩa) và thành phần biểu âm. Nghĩa gốc trong kinh điển: rời nhau, ly dị. Wiktionary ghi nhiều âm đọc cổ (pǐ), dùng trong ngữ cảnh \"仳离\" (pǐlí) — ly biệt, chia cắt người với người. Chưa có nguồn học thuật đầy đủ về cấu trúc chi tiết. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chia rẽ", "Hạng Tần Suất (Jun Da)": "6974.0", "Tần Suất % (Jun Da)": "99.9968233218", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 比", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻比", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "比", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "仳", "Unihan_Traditional (Chữ Phồn thể)": "仳", "Pinyin_Xie": "pǐ", "Âm Hán Việt_Xie": "tỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ biểu thị sự chia ly, thường xuất hiện trong văn bản cổ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('趩', '{"9000": "6975.0", "Chữ Trung Quốc": "趩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 走 | Số nét | 18 | nét | 走 | tẩu | biểu nghĩa | đi, chạy | 異 | dị | biểu âm | khác lạ — cho âm đọc | 趩 là chữ hình thanh: 走 (Tẩu, biểu nghĩa — đi, chạy) + 異 (Dị, biểu âm). Wiktionary xác nhận: {{Han compound|走|異|c1=s|c2=p|t1=walk|ls=psc}}. Nghĩa: đi lại lạ lùng, bước chân vội vã hoặc không đều.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sách\": 走 (đi) + 異 (dị thường) — bước đi \"sách\" (chật vật, vội vàng) theo cách dị thường, không bình thường. | Gương Hán-Việt | sách trong \"sách bộ\" (bước đi vội, bước chân to) | Mở khoá kiến thức | Biết 趩 (sách) giúp nhận ra chữ chỉ chuyển động trong văn bản cổ điển.", "Tự nguyên_Xie": "趩 là chữ hình thanh gồm 走 (đi, chạy — biểu nghĩa) và 異 (biểu âm). Nghĩa gốc chỉ cách đi lại không bình thường, bước đi vội vã hoặc bước chân to. Chữ hiếm gặp, chỉ xuất hiện trong từ điển cổ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "婩", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "走 + 異", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴走異", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "異", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "走", "Unihan_Simplified (Chữ Giản thể)": "趩", "Unihan_Traditional (Chữ Phồn thể)": "趩", "Pinyin_Xie": "chì", "Âm Hán Việt_Xie": "sách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Động từ | 动词 | Chữ này dùng làm từ tượng thanh mô tả tiếng bước chân hoặc động từ chỉ dáng đi nhanh. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('絪', '{"9000": "6976.0", "Chữ Trung Quốc": "絪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 12 | nét | 絪 | nhân | tượng hình | khí âm dương hoà hợp, hơi mây trên trời | 絪 không có cây thành phần trong anchor. Từ bộ 糸 (ti — sợi tơ), chữ chỉ hơi ẩm, khí mây, hoặc trạng thái mây mù bao phủ. Wiktionary ghi anchor nhưng không có cấu trúc chi tiết. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhân\": bộ 糸 (tơ) — \"nhân\" như sợi tơ âm dương 絪 quyện vào nhau, tạo nên khí trời, hơi mây mù bảng lảng. | Gương Hán-Việt | nhân trong \"nhân uẩn\" (絪縕, khí âm dương hoà hợp) | Mở khoá kiến thức | Biết 絪 (nhân) giúp đọc văn bản Chu Dịch và triết học cổ về âm dương.", "Tự nguyên_Xie": "Lục thư thông (chữ tạo muộn) | 絪 thuộc bộ 糸 (sợi, tơ), chỉ hơi ẩm bốc lên như sợi tơ, hoặc cảm giác khí âm dương hoà quyện. Trong văn triết học cổ (Chu Dịch), 絪縕 (yīnyūn) chỉ trạng thái khí âm dương đan xen, hoà hợp. Wiktionary không cung cấp cấu trúc chi tiết; chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên khí phát ra", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 因", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹因", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "因", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "𬘡", "Unihan_Traditional (Chữ Phồn thể)": "絪", "Pinyin_Xie": "yīn", "Âm Hán Việt_Xie": "nhân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường dùng trong triết học cổ đại hoặc chỉ đồ dùng để nằm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('绹', '{"9000": "6977.0", "Chữ Trung Quốc": "绹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 11 | nét | 绹 | đào | tượng hình | dây bện, dây thừng xoắn | 绹 không có cây thành phần rõ ràng trong anchor. Từ bộ 糸/纟 (ti — sợi tơ), chữ chỉ dây bện, dây thừng xoắn. Anchor chỉ ghi {{Han etym}} không có chi tiết cấu trúc. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đào\": bộ 纟 (sợi) xoắn lại — \"đào\" như đào bới, xoắn xít, sợi tơ 绹 xoắn vào nhau thành dây bền chắc. | Gương Hán-Việt | đào trong \"đào thừng\" (dây bện xoắn) | Mở khoá kiến thức | Biết 绹 (đào) giúp đọc văn bản kỹ thuật dệt và thủ công nghiệp Trung Hoa cổ.", "Tự nguyên_Xie": "Đại triện | 绹 thuộc bộ 糸/纟 (sợi tơ), chỉ dây bện hoặc cách bện dây thừng. Wiktionary ghi: to braid, twist; twisted or braided rope. Chữ dùng trong ngữ cảnh thủ công nghiệp dệt, bện lưới hoặc dây thừng. Chưa có nguồn học thuật đầy đủ về cấu trúc chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đánh dây, xe sợi", "Hạng Tần Suất (Jun Da)": "6977.0", "Tần Suất % (Jun Da)": "99.9968414093", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 匋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟匋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "绹", "Unihan_Traditional (Chữ Phồn thể)": "綯", "Pinyin_Xie": "táo", "Âm Hán Việt_Xie": "đào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ hành động bện dây hoặc làm danh từ chỉ sợi dây thừng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('膵', '{"9000": "6978.0", "Chữ Trung Quốc": "膵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 15 | nét | 膵 | tuỵ | tượng hình | tuyến tuỵ, pancreas | 膵 là chữ mượn từ tiếng Nhật (Wiktionary: {{obor|zh|ja|膵}}). Chữ không có cây thành phần rõ ràng trong nguồn anchor; đây là thuật ngữ y học hiện đại được Nhật Bản tạo ra và Trung Quốc mượn lại. Cấu trúc có thể gồm bộ 肉 (nhục — thịt, nội tạng).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuỵ\": chữ mượn từ Nhật, bộ 肉 (nội tạng) — \"tuỵ\" như \"tuỵ xuất\" (tiết ra), tuyến tuỵ 膵 tiết ra enzyme tiêu hoá và insulin. | Gương Hán-Việt | tuỵ trong \"tuỵ tạng\" (tuyến tuỵ), y học hiện đại | Mở khoá kiến thức | Biết 膵 (tuỵ) mở khoá: 膵腺 (tuỵ tuyến), 膵臟 (tuỵ tạng), 膵炎 (viêm tuỵ).", "Tự nguyên_Xie": "膵 là chữ mượn từ chữ Nhật (Japonic borrow, ký hiệu Wiktionary: {{obor|zh|ja|膵}}). Người Nhật tạo chữ này để phiên âm thuật ngữ y học phương Tây \"pancreas\". Trung Quốc sau đó dùng lại chữ này. Không có nguồn gốc Hán cổ truyền thống. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tuỵ (tiết dịch tiêu hoá)", "Hạng Tần Suất (Jun Da)": "6978.0", "Tần Suất % (Jun Da)": "99.9968450268", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 萃", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月萃", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "萃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "膵", "Unihan_Traditional (Chữ Phồn thể)": "膵", "Pinyin_Xie": "cuì", "Âm Hán Việt_Xie": "tụy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một cơ quan nội tạng trong cơ thể người và động vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蕗', '{"9000": "6979.0", "Chữ Trung Quốc": "蕗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 16 | nét | 蕗 | lộ | tượng hình | cây lộ, cây rau cải dại (Petasites japonicus) | 蕗 không có cây thành phần và không có glyphOrigin trong anchor. Chữ thuộc bộ 艹 (thảo — cỏ cây), chỉ một loài thực vật. Cấu trúc nội bộ có thể gồm 艹 (biểu nghĩa) và thành phần biểu âm chưa xác định. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lộ\": bộ 艹 (cây) — \"lộ\" như lộ thiên, lộ ra, cây 蕗 mọc lộ thiên ven suối, lá to xoè rộng phủ mặt đất. | Gương Hán-Việt | lộ trong \"lộ thảo\" (cây cỏ mọc ven đường) | Mở khoá kiến thức | Biết 蕗 (lộ) giúp nhận ra tên loài thực vật trong văn bản thực vật học và y học cổ Đông Á.", "Tự nguyên_Xie": "蕗 thuộc bộ 艹 (cỏ, cây), chỉ cây lộ (Petasites japonicus, fukinoto trong tiếng Nhật) — một loài thực vật ăn được mọc ở vùng đầm lầy và ven suối. Không có glyphOrigin trong anchor; chưa có nguồn học thuật xác nhận cấu trúc chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cam thảo", "Hạng Tần Suất (Jun Da)": "6979.0", "Tần Suất % (Jun Da)": "99.9968486442", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 路", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹路", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "路", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蕗", "Unihan_Traditional (Chữ Phồn thể)": "蕗", "Pinyin_Xie": "lù", "Âm Hán Việt_Xie": "lộc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ để chỉ một loại cây thân thảo hoặc dùng trong tên riêng của thực vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蝘', '{"9000": "6980.0", "Chữ Trung Quốc": "蝘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 15 | nét | 虫 | trùng | biểu nghĩa | sâu, côn trùng, bò sát nhỏ | 匽 | yển | biểu âm | nằm phục — cho âm đọc | 蝘 là chữ hình thanh: 虫 (Trùng, biểu nghĩa — bò sát nhỏ, côn trùng) + 匽 (Yển, biểu âm). Wiktionary xác nhận: {{Han compound|虫|匽|ls=psc|c1=s|t1=insect|c2=p}}. Chữ chỉ con tắc kè, thạch sùng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"yển\": 虫 (côn trùng/bò sát) + 匽 (nằm phục) — tắc kè 蝘 nằm phục 匽 trên tường, bất động chờ mồi. | Gương Hán-Việt | yển trong \"thạch yển\" (thạch sùng, tắc kè) | Mở khoá kiến thức | Biết 蝘 (yển) giúp nhận ra tên loài bò sát trong văn bản tự nhiên học và y học cổ Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | 蝘 là chữ hình thanh gồm 虫 (bò sát, côn trùng — biểu nghĩa) và 匽 (biểu âm). Theo Wiktionary, nghĩa: gecko — tắc kè hoặc thạch sùng. Loài bò sát leo tường phổ biến trong nhà ở. Âm yǎn xuất phát từ thành phần 匽 (yển). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: yển đình 蝘蜓)", "Hạng Tần Suất (Jun Da)": "6980.0", "Tần Suất % (Jun Da)": "99.9968522617", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 匽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫匽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蝘", "Unihan_Traditional (Chữ Phồn thể)": "蝘", "Pinyin_Xie": "yǎn", "Âm Hán Việt_Xie": "yển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu làm danh từ trong các từ ghép cổ để chỉ một số loài bò sát hoặc côn trùng nhỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('袠', '{"9000": "6981.0", "Chữ Trung Quốc": "袠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 11 | nét | 袠 | chất | tượng hình | túi đựng sách, bọc sách | 袠 không có cây thành phần và không có glyphOrigin trong anchor. Chữ thuộc bộ 衣 (y — quần áo, vải vóc), chỉ vật dùng bọc hoặc đựng sách. Cấu trúc chi tiết không rõ. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chất\": bộ 衣 (vải) bọc sách — \"chất\" như \"chất lượng\", cái túi vải 袠 bảo vệ sách, giữ gìn chất lượng tri thức. | Gương Hán-Việt | chất trong \"thư chất\" (túi đựng sách) | Mở khoá kiến thức | Biết 袠 (chất) giúp đọc văn bản cổ về đồ dùng học tập và thư tịch.", "Tự nguyên_Xie": "袠 thuộc bộ 衣 (vải, quần áo), chỉ túi đựng sách hoặc bao bọc sách, cũng có thể chỉ bìa sách vải. Chữ hiếm gặp trong văn bản cổ điển. Không có glyphOrigin; chưa có nguồn học thuật xác nhận cấu trúc chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái bao sách", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "衣 + 失", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴衣失", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "失", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衣", "Unihan_Simplified (Chữ Giản thể)": "袠", "Unihan_Traditional (Chữ Phồn thể)": "袠", "Pinyin_Xie": "zhì", "Âm Hán Việt_Xie": "dật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Chữ này làm danh từ chỉ bao sách hoặc làm lượng từ để đếm số tập sách, cuộn tranh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('賸', '{"9000": "6982.0", "Chữ Trung Quốc": "賸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 17 | nét | 朕 | trẫm | biểu âm | ta (xưng của vua) — cho âm đọc | 貝 | bối | biểu nghĩa | vỏ sò, tiền tệ, của cải | 賸 là chữ hình thanh: 貝 (Bối, biểu nghĩa — tiền của, của cải) + 朕 (Trẫm, biểu âm). Wiktionary xác nhận: {{Han compound|朕|貝|c1=p|c2=s|t2=shellfish|ls=psc}}. Nghĩa: thặng dư, còn lại sau khi dùng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thặng\": 貝 (tiền của) + 朕 (vua) — phần tài sản \"thặng\" lại sau khi vua 朕 dùng xong, của cải dư thừa còn lại. | Gương Hán-Việt | thặng trong \"dư thặng\" (dư thừa), \"thặng dư\" (phần còn lại) | Mở khoá kiến thức | Biết 賸 (thặng) mở khoá: 賸餘 (thặng dư, còn lại), 賸下 (còn lại), từ gốc của 剩 hiện đại.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | 賸 là chữ hình thanh gồm 貝 (vỏ sò, tiền của — biểu nghĩa) và 朕 (trẫm, biểu âm). Âm shèng xuất phát từ thành phần 朕. Nghĩa gốc: của cải thặng dư, phần còn lại sau khi phân chia. Chữ truyền thống của 剩 (thặng dư). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "có phần còn lại; giao dịch. biến thể của 剩", "Hạng Tần Suất (Jun Da)": "6982.0", "Tần Suất % (Jun Da)": "99.9968594967", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "賸", "Unihan_Traditional (Chữ Phồn thể)": "賸", "Pinyin_Xie": "shèng", "Âm Hán Việt_Xie": "thặng, thứng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này thường làm động từ chỉ sự dư thừa hoặc làm tính từ bổ nghĩa cho danh từ đứng sau. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('葙', '{"9000": "6983.0", "Chữ Trung Quốc": "葙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 葙 | tương | tượng hình | cây mào gà dại (Celosia argentea) | 葙 không có cây thành phần và không có glyphOrigin trong anchor. Chữ thuộc bộ 艹 (thảo — cỏ cây), chỉ cây mào gà dại hay còn gọi là qing xiang (Celosia argentea). Cấu trúc chi tiết không rõ. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tương\": bộ 艹 (cây) — \"tương\" như \"tương lai\" (tiến về phía trước), cây mào gà 葙 vươn thẳng, bông hoa nhọn tựa ngọn giáo tiến thẳng lên trời. | Gương Hán-Việt | tương trong \"thanh tương\" (tên khoa học cây mào gà dại) | Mở khoá kiến thức | Biết 葙 (tương) giúp đọc văn bản thực vật học và y học cổ Trung Hoa.", "Tự nguyên_Xie": "葙 thuộc bộ 艹 (cỏ, cây), chỉ cây Celosia argentea (mào gà trắng/bạc, feather cockscomb). Đây là loài cây thuốc trong y học cổ truyền Trung Hoa, hạt dùng chữa bệnh mắt. Không có glyphOrigin; chưa có nguồn học thuật xác nhận cấu trúc chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây thanh tương", "Hạng Tần Suất (Jun Da)": "6983.0", "Tần Suất % (Jun Da)": "99.9968631142", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 相", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹相", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "相", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "葙", "Unihan_Traditional (Chữ Phồn thể)": "葙", "Pinyin_Xie": "xiāng", "Âm Hán Việt_Xie": "tương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này đóng vai trò là danh từ, thường xuất hiện trong tên vị thuốc đông y thanh tương tử. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('祪', '{"9000": "6984.0", "Chữ Trung Quốc": "祪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 10 | nét | 祪 | quỷ | tượng hình | thần linh của tổ tiên nước Tề | 祪 không có cây thành phần rõ ràng trong anchor. Từ bộ 示 (thị — tế lễ, thần linh), chữ chỉ một vị thần cụ thể hoặc nghi lễ tế tổ tiên của nước Tề. Wiktionary chỉ ghi {{Han etym}} không có chi tiết cấu trúc. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quỷ\": bộ 示 (tế lễ) — \"quỷ\" như thần linh, vị thần tổ tiên 祪 được thờ phụng qua các nghi lễ 示 trang trọng của nước Tề. | Gương Hán-Việt | quỷ trong \"Tề quỷ\" (thần tổ tiên nước Tề) | Mở khoá kiến thức | Biết 祪 (quỷ) giúp đọc văn bản lễ nghi và sử học thời Xuân Thu Chiến Quốc.", "Tự nguyên_Xie": "祪 thuộc bộ 示 (tế lễ, thần linh), chỉ vị thần tổ tiên của nước Tề (một trong các nước chư hầu thời Xuân Thu Chiến Quốc). Chữ hiếm gặp, chỉ xuất hiện trong văn bản lễ nghi và sử học cổ điển. Wiktionary không cung cấp cấu trúc chi tiết; chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Tề", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 危", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻危", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "危", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "祪", "Unihan_Traditional (Chữ Phồn thể)": "祪", "Pinyin_Xie": "guǐ", "Âm Hán Việt_Xie": "quỷ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại bài vị thờ cúng trong các nghi lễ tông miếu thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('禘', '{"9000": "6985.0", "Chữ Trung Quốc": "禘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 13 | nét | 示 | thị | biểu nghĩa | bàn thờ, tế lễ | 帝 | đế | biểu âm | hoàng đế, thượng đế — cho âm đọc | 禘 là chữ hình thanh: 示 (Thị, biểu nghĩa — tế lễ, bàn thờ) + 帝 (Đế, biểu âm). Wiktionary xác nhận: {{Han compound|示|帝|c1=s|c2=p|t1=sacrifical altar|t2=|ls=psc}}. Đây là nghi lễ tế tổ tiên hoàng gia — lễ tế bậc cao nhất của thiên tử.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đế\": 示 (tế lễ) + 帝 (hoàng đế) — \"đế\" lễ 禘 là nghi lễ tối cao, chỉ thiên tử mới được tế 示 đấng thượng đế 帝 và tổ tiên hoàng gia. | Gương Hán-Việt | đế trong \"đế tế\" (lễ tế của thiên tử), \"tông miếu đế\" (tế ở tông miếu) | Mở khoá kiến thức | Biết 禘 (đế) giúp đọc văn bản lễ nhạc Nho giáo và các điển tích tế tự trong Kinh Lễ.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Tiểu triện | 禘 là chữ hình thanh gồm 示 (bàn thờ, tế lễ — biểu nghĩa) và 帝 (biểu âm, âm dì). Nghĩa gốc: lễ tế đặc biệt của thiên tử dành cho tổ tiên hoàng gia và thượng đế (Shang Di). Đây là nghi lễ trang trọng nhất trong hệ thống lễ nhạc Nho giáo. Wiktionary cũng ghi rằng có thể là hội ý. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tế đế (vua tế tổ tiên)", "Hạng Tần Suất (Jun Da)": "6985.0", "Tần Suất % (Jun Da)": "99.9968812017", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 帝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻帝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "帝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "禘", "Unihan_Traditional (Chữ Phồn thể)": "禘", "Pinyin_Xie": "dì", "Âm Hán Việt_Xie": "đế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ nghi lễ tế tự lớn thời cổ hoặc làm động từ thực hiện nghi lễ đó. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('菍', '{"9000": "6986.0", "Chữ Trung Quốc": "菍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 艸 | tháo | biểu nghĩa | cỏ, thực vật | 念 | niệm | biểu âm | nhớ, suy nghĩ — cho âm đọc | 菍 là chữ hình thanh: 艸 (Tháo/Thảo, biểu nghĩa — cỏ, thực vật) + 念 (Niệm, biểu âm). Wiktionary xác nhận: {{Han compound|艸|念|ls=psc|c1=s|c2=p|t1=grass; plant}}. Chữ chỉ loài thực vật cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nấm\": 艸 (cỏ cây) + 念 (niệm, nhớ) — \"nấm\" mọc lên từ đất ẩm, loài cây 艸 mà người ta cứ \"niệm\" 念 đến vì nó ngon hoặc độc lạ. | Gương Hán-Việt | nấm trong tiếng Việt gọi thẳng (dùng đây là HV reading theo anchor) | Mở khoá kiến thức | Biết 菍 (nấm) giúp nhận ra tên thực vật hiếm trong văn bản thực vật học cổ Trung Hoa.", "Tự nguyên_Xie": "菍 là chữ hình thanh gồm 艸 (cỏ, cây — biểu nghĩa) và 念 (biểu âm, âm niè). Nghĩa: loài thực vật thuộc họ rau dền (Amaranthus), hoặc một tên cổ của loài cây mọc dại. Chữ hiếm gặp trong văn bản thực vật học cổ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nấm; như \"cây nấm\" (vhn) nộm; như \"rau nộm\" (btcn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 念", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹念", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "念", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "菍", "Unihan_Traditional (Chữ Phồn thể)": "菍", "Pinyin_Xie": "niè", "Âm Hán Việt_Xie": "nhẫm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ dùng trong tên gọi của một số loài thực vật hoặc món ăn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('仉', '{"9000": "6987.0", "Chữ Trung Quốc": "仉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 4 | nét | 仉 | kẻ | tượng hình | họ Chưởng, biến thể cổ của 掌 | 仉 là chữ biến thể (corruption) của 𤓯, dạng cổ của 掌 (bàn tay/chưởng). Wiktionary ghi: \"Corruption of 𤓯, an ancient form of 掌. In its current form, the left part became 亻\". Bộ 亻 (nhân — người) xuất hiện do biến thể chữ viết, không phải thành phần gốc có nghĩa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kẻ\": bộ 亻 (người) — \"kẻ\" như người mang họ Chưởng 仉, chữ biến thể của 掌 (lòng bàn tay), một dòng họ tự đặt tên theo hình bàn tay. | Gương Hán-Việt | kẻ trong tên riêng, họ Chưởng (仉) | Mở khoá kiến thức | Biết 仉 (kẻ) giúp nhận ra họ Chưởng trong văn bản lịch sử Trung Hoa — đặc biệt mẹ của Mạnh Tử mang họ này.", "Tự nguyên_Xie": "仉 là chữ biến thể của 𤓯, dạng cổ của 掌 (bàn tay, chưởng). Theo Wiktionary: trong dạng hiện tại, phần bên trái trở thành 亻. Chữ chủ yếu được dùng như họ (姓) — họ Chưởng. Đây là trường hợp biến thể chữ viết lịch sử, không phải chữ được tạo theo quy tắc thông thường. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "họ Chưởng", "Hạng Tần Suất (Jun Da)": "6987.0", "Tần Suất % (Jun Da)": "99.9969065242", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 几", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻几", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "几", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "仉", "Unihan_Traditional (Chữ Phồn thể)": "仉", "Pinyin_Xie": "zhǎng", "Âm Hán Việt_Xie": "chưởng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ riêng đứng đầu trong tên họ của người Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('氕', '{"9000": "6988.0", "Chữ Trung Quốc": "氕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 气 | Số nét | 5 | nét | 气 | khí | biểu nghĩa | khí, hơi (nguyên tố khí) | 丿 | phết | hội ý / biểu âm | nét phảy; biểu thị \"một\" (protium có 1 proton) | 氕 là chữ hội ý kiêm hình thanh (Wiktionary: {{Han compound|气|t1=gas|丿|t2=one|ls=ic}}). 气 (khí, biểu nghĩa — nguyên tố khí) + 丿 (một nét, biểu thị \"một\" proton). Đây là chữ tạo hiện đại để chỉ hydro-1 (protium). Wiktionary cũng ghi rằng 丿 có thể đóng vai trò biểu âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phết\": 气 (khí nguyên tố) + 丿 (một nét duy nhất) — chỉ 1 proton, nhẹ như nét phảy 丿, hydro-1 là nguyên tử đơn giản nhất vũ trụ. | Gương Hán-Việt | phết trong \"phết hiđrô\" (protium, hydro-1) | Mở khoá kiến thức | Biết 氕 (phết) mở khoá hệ thống đồng vị hydro: 氕 (protium ¹H), 氘 (deuterium ²H), 氚 (tritium ³H).", "Tự nguyên_Xie": "氕 là chữ tạo hiện đại theo hệ thống chữ Hán khoa học của Trung Quốc. Cấu trúc: 气 (khí, nguyên tố khí — biểu nghĩa) + 丿 (một nét — đại diện cho số lượng proton = 1). Đây là ký hiệu cho protium (hydro-1, ¹H), đồng vị nhẹ nhất của hydro. Hệ thống này tạo 氕 (1H), 氘 (2H/D), 氚 (3H/T). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Proti, Pr", "Hạng Tần Suất (Jun Da)": "6988.0", "Tần Suất % (Jun Da)": "99.9969101417", "GavinGrover_Once (Chiết tự trực tiếp)": "气 + 丿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴气丿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "气", "Unihan_Simplified (Chữ Giản thể)": "氕", "Unihan_Traditional (Chữ Phồn thể)": "氕", "Pinyin_Xie": "piē", "Âm Hán Việt_Xie": "phân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong thuật ngữ hóa học để chỉ nguyên tố proti. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('矔', '{"9000": "6989.0", "Chữ Trung Quốc": "矔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 22 | nét | 矔 | quán | tượng hình | ánh mắt sáng rực, mắt nhìn rõ | 矔 không có cây thành phần rõ ràng trong anchor. Từ bộ 目 (mục — mắt), chữ chỉ ánh mắt sáng, chói lọi, nhìn rõ ràng. Wiktionary chỉ ghi {{Han etym}} không có chi tiết cấu trúc. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quán\": bộ 目 (mắt) — \"quán\" như ánh mắt \"quán xuyến\" (nhìn thấu suốt), đôi mắt 矔 sáng rực chiếu rọi tất cả. | Gương Hán-Việt | quán trong \"minh quán\" (mắt sáng, nhìn tinh) | Mở khoá kiến thức | Biết 矔 (quán) giúp đọc thơ văn cổ mô tả vẻ đẹp đôi mắt trong văn học Trung Hoa.", "Tự nguyên_Xie": "矔 thuộc bộ 目 (mắt), chỉ trạng thái ánh mắt rực sáng, chói lọi, hoặc đôi mắt nhìn tinh tường. Chữ hiếm gặp, chủ yếu dùng trong văn học cổ điển để mô tả vẻ đẹp của đôi mắt. Wiktionary không cung cấp cấu trúc chi tiết; chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rực rỡ (của đôi mắt)", "Hạng Tần Suất (Jun Da)": "6989.0", "Tần Suất % (Jun Da)": "99.9969137592", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 雚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目雚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "雚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "矔", "Unihan_Traditional (Chữ Phồn thể)": "矔", "Pinyin_Xie": "guàn", "Âm Hán Việt_Xie": "quán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ chỉ hành động nhìn chăm chú hoặc làm tính từ miêu tả thần thái của đôi mắt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('臒', '{"9000": "6990.0", "Chữ Trung Quốc": "臒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 17 | nét | 臒 | ác | tượng hình | gầy còm, ốm yếu | 臒 không có cây thành phần rõ ràng trong anchor. Từ bộ 肉 (nhục — thịt, cơ thể), chữ chỉ trạng thái gầy, thiếu thịt. Wiktionary ghi nhiều âm đọc: wò, yuè — cho thấy chữ có thể có nhiều nghĩa hoặc cách dùng. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ác\": bộ 肉 (thịt) thiếu hụt — \"ác\" như thiếu \"ác là\", cơ thể 肉 gầy còm trơ xương, mỏng như tờ giấy. | Gương Hán-Việt | ác trong \"tiêu ác\" (gầy mòn, hao mòn) | Mở khoá kiến thức | Biết 臒 (ác) giúp đọc văn bản y học cổ và văn học miêu tả thể trạng sức khoẻ.", "Tự nguyên_Xie": "臒 thuộc bộ 肉 (thịt), chỉ trạng thái gầy, cơ thể thiếu thịt, ốm yếu. Wiktionary ghi âm đọc cổ (MC) là wò và yuè. Chữ hiếm gặp trong văn bản y học và văn học cổ điển mô tả thể trạng con người. Chưa có nguồn học thuật xác nhận cấu trúc chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "臒", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 蒦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月蒦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "蒦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "臒", "Unihan_Traditional (Chữ Phồn thể)": "臒", "Pinyin_Xie": "wò", "Âm Hán Việt_Xie": "ác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu làm danh từ trong văn ngôn để chỉ các món ăn chế biến từ thịt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('苿', '{"9000": "6991.0", "Chữ Trung Quốc": "苿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 8 | nét | 苿 | mạt | tượng hình | cây linh lăng, cỏ mục túc (Medicago sativa) | 苿 không có cây thành phần và không có glyphOrigin trong anchor. Chữ thuộc bộ 艹 (thảo — cỏ cây), chỉ cây alfalfa hoặc cỏ linh lăng. Cấu trúc chi tiết không rõ. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mạt\": bộ 艹 (cỏ) — \"mạt\" như \"tận mạt\" (tận cùng), cỏ linh lăng 苿 mọc khắp nơi đến tận cùng đồng ruộng. | Gương Hán-Việt | mạt trong \"mạt thảo\" (cỏ cây tầm thường, cỏ dại) | Mở khoá kiến thức | Biết 苿 (mạt) giúp nhận ra tên thực vật trong văn bản thực vật học cổ Trung Hoa.", "Tự nguyên_Xie": "苿 thuộc bộ 艹 (cỏ, cây), chỉ cây alfalfa (linh lăng, Medicago sativa) hoặc một loài cỏ liên quan. Không có glyphOrigin; chưa có nguồn học thuật xác nhận cấu trúc chi tiết. Chữ hiếm gặp, có thể là biến thể của 苜 trong 苜蓿 (alfalfa). | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây hoa nhài", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 未", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹未", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "未", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "苿", "Unihan_Traditional (Chữ Phồn thể)": "苿", "Pinyin_Xie": "wèi", "Âm Hán Việt_Xie": "mạt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ một loại cây thân thảo hoặc dùng trong tên gọi cổ của hoa nhài. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('菢', '{"9000": "6992.0", "Chữ Trung Quốc": "菢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 菢 | bão | tượng hình | ấp trứng, ủ trứng (như gà mái ấp) | 菢 không có cây thành phần rõ ràng trong anchor. Wiktionary chỉ ghi {{Han etym}} không có chi tiết cấu trúc. Từ ngữ cảnh, chữ chỉ hành động ấp trứng. Bộ gốc có thể liên quan đến 包 (bao, ôm ấp) hoặc 艹. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bão\": nghĩa ủ ấp — \"bão\" như \"bão bọc\" (ôm ấp bảo vệ), gà mái 菢 ôm 包 trứng dưới cánh, ủ ấm để trứng nở. | Gương Hán-Việt | bão trong \"bão noãn\" (ủ ấp trứng) | Mở khoá kiến thức | Biết 菢 (bão) giúp đọc văn bản nông nghiệp và chăn nuôi cổ Trung Hoa.", "Tự nguyên_Xie": "菢 chỉ hành động ấp trứng, ủ trứng để nở. Wiktionary ghi: to incubate; to brood; to hatch. Chữ thường dùng cho gà mái hoặc chim ấp trứng. Không có glyphOrigin chi tiết; chưa có nguồn học thuật xác nhận cấu trúc. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ôm ấp, bế; ấp ủ; vừa khít, khớp", "Hạng Tần Suất (Jun Da)": "6992.0", "Tần Suất % (Jun Da)": "99.9969318467", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 抱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹抱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "抱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "菢", "Unihan_Traditional (Chữ Phồn thể)": "菢", "Pinyin_Xie": "bào", "Âm Hán Việt_Xie": "bão", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ chỉ hành động chim ấp trứng hoặc ôm giữ vật gì đó trong lòng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蔂', '{"9000": "6993.0", "Chữ Trung Quốc": "蔂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 14 | nét | 蔂 | luy | tượng hình | giỏ đựng đất, cái hốt, cái bồ | 蔂 là dị thể (variant) của 虆. Wiktionary ghi: {{zh-see|虆}} — xem chữ 虆. Chữ chỉ giỏ đựng đất hoặc các vật liệu nặng. Bộ chính có thể là 艹 hoặc 𠦜. Cấu trúc chi tiết không rõ. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"luy\": nghĩa giỏ đất — \"luy\" như \"luỹ\" (lũy đất, bờ đắp), cái giỏ 蔂 đựng đất đắp nên luỹ thành. | Gương Hán-Việt | luy trong \"luy thổ\" (giỏ đựng đất, hốt đất) | Mở khoá kiến thức | Biết 蔂/虆 (luy) giúp đọc văn bản nông nghiệp và xây dựng cổ Trung Hoa.", "Tự nguyên_Xie": "蔂 là dị thể (biến thể) của 虆, theo Wiktionary: {{zh-see|虆}}. Nghĩa gốc: cái giỏ đựng đất, hốt đựng cát đá dùng trong xây dựng hoặc nông nghiệp. Chữ hiếm gặp; dạng chính thức hơn là 虆. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bò dài, bò lan ra; cái sọt đựng đất", "Hạng Tần Suất (Jun Da)": "6993.0", "Tần Suất % (Jun Da)": "99.9969354642", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 累", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹累", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "累", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蔂", "Unihan_Traditional (Chữ Phồn thể)": "蔂", "Pinyin_Xie": "léi", "Âm Hán Việt_Xie": "luy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ cái sọt đựng đất đá hoặc động từ chỉ sự bò lan của cây cỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('藞', '{"9000": "6994.0", "Chữ Trung Quốc": "藞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 18 | nét | 藞 | lủi | tượng hình | cỏ mọc lộn xộn, rối rắm | 藞 không có cây thành phần rõ ràng trong anchor. Từ bộ 艹 (thảo — cỏ cây), chữ chỉ trạng thái cỏ mọc rối rắm, lộn xộn, hoặc bước đi lén lút. Wiktionary chỉ ghi {{Han etym}} không có chi tiết cấu trúc. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lủi\": bộ 艹 (cỏ) — \"lủi\" như \"lủi vào bụi rậm\", cỏ 藞 mọc rối rắm như mê cung, con vật lủi vào ẩn nấp trong đám cỏ um tùm đó. | Gương Hán-Việt | lủi trong \"lủi thủi\" (lén lút, cô đơn, âm thầm) | Mở khoá kiến thức | Biết 藞 (lủi) giúp đọc văn bản cổ mô tả cảnh vật rối rắm hoặc hành vi lén lút.", "Tự nguyên_Xie": "藞 thuộc bộ 艹 (cỏ), chỉ trạng thái cỏ mọc rối rắm hoặc sự lủi thủi, lén lút. Trong một số phương ngữ, 藞苴 (lǎ jū) chỉ trạng thái lộn xộn, cẩu thả. Wiktionary không cung cấp cấu trúc chi tiết; chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lủi; như \"lủi thủi\" (vhn) lủa; như \"rau lủa\" (btcn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 磊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹磊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "磊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "藞", "Unihan_Traditional (Chữ Phồn thể)": "藞", "Pinyin_Xie": "lǎ", "Âm Hán Việt_Xie": "lã", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường kết hợp với chữ khác tạo thành tính từ chỉ sự luộm thuộm hoặc danh từ chỉ một loại rau. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('袩', '{"9000": "6995.0", "Chữ Trung Quốc": "袩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 10 | nét | 袩 | xiêm | tượng hình | áo xiêm, y phục phụ nữ | 袩 thuộc bộ 衣 (y — vải vóc, y phục). Cấu trúc nội bộ chưa được phân tích hình thanh/hội ý trong nguồn học thuật hiện có.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xiêm\": bộ 衣 (y — áo) gợi đây là loại y phục — \"áo xiêm\" trang lễ của phụ nữ thời xưa. | Gương Hán-Việt | \"xiêm\" trong \"áo xiêm\" — y phục lễ nghi phụ nữ thời phong kiến | Mở khoá kiến thức | Biết 袩 (xiêm) giúp nhận ra từ cổ \"áo xiêm\" trong văn học Hán-Nôm chỉ trang phục lễ nghi phụ nữ.", "Tự nguyên_Xie": "袩 thuộc bộ 衣 (y — y phục). Không có dữ liệu glyphOrigin từ Wiktionary. Dựa vào bộ thủ, chữ liên quan đến áo xống. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xiêm; như \"áo xiêm\" (vhn) chêm; như \"chêm vào; chêm cho chặt\" (gdhn) xem; như \"xem tướng; xem thường\" (gdhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 占", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤占", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "占", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "袩", "Unihan_Traditional (Chữ Phồn thể)": "袩", "Pinyin_Xie": "zhé", "Âm Hán Việt_Xie": "triệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Dùng làm danh từ chỉ trang phục cổ hoặc động từ với nghĩa chêm, chèn cho chặt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('跍', '{"9000": "6996.0", "Chữ Trung Quốc": "跍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 12 | nét | 足 | túc | biểu nghĩa | chân, bàn chân | 古 | cổ | biểu âm | xưa cũ (cho âm) | 跍 là chữ hình thanh (ls=psc): 足 (túc — chân) là phần biểu nghĩa chỉ hành động liên quan đến chân; 古 (cổ) là phần biểu âm cho âm kū.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cổ\" (đọc theo 古, biểu âm): chân (足) gập xuống như người \"cổ\" đại ngồi xổm trước lửa. | Gương Hán-Việt | \"cổ\" — âm phụ, không phổ biến trong từ Hán-Việt thông dụng | Mở khoá kiến thức | 跍 là chữ hiếm; biết 足 (túc — chân) giúp nhận ra nhóm chữ về vận động chân như 跑, 跳, 踪.", "Tự nguyên_Xie": "Theo Wiktionary, 跍 gồm 足 (túc — chân, biểu nghĩa) + 古 (cổ, biểu âm) theo cấu trúc hình thanh. Nghĩa là ngồi xổm, chụm chân lại. Chưa có nguồn học thuật chuyên sâu về chữ này ngoài phân tích cấu trúc. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngồi xổm", "Hạng Tần Suất (Jun Da)": "6996.0", "Tần Suất % (Jun Da)": "99.9969535516", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 古", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊古", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "古", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "跍", "Unihan_Traditional (Chữ Phồn thể)": "跍", "Pinyin_Xie": "kū", "Âm Hán Việt_Xie": "khu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ chỉ tư thế ngồi xổm hoặc co chân lại, thường dùng trong văn bạch thoại hoặc phương ngôn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('跓', '{"9000": "6997.0", "Chữ Trung Quốc": "跓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 12 | nét | 跓 | chú | tượng hình | dừng bước chân | 跓 là chữ thuộc bộ 足 (túc — chân). Cấu trúc nội bộ không có phân tích hình thanh/hội ý rõ ràng trong nguồn Wiktionary; chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chú\": bộ 足 (túc — chân) — chân \"chú\" xuống đất, dừng bước hẳn lại. | Gương Hán-Việt | \"chú\" — âm Hán-Việt ít dùng trong từ thông dụng hiện đại | Mở khoá kiến thức | 跓 là chữ hiếm; bộ 足 (túc) kết nối nhóm từ vận động: 跑 (chạy), 跳 (nhảy), 踪 (dấu chân).", "Tự nguyên_Xie": "跓 thuộc bộ 足 (túc — chân). Nghĩa: dừng bước, ngừng di chuyển. Không có dữ liệu glyphOrigin có cấu trúc từ Wiktionary. Dựa vào bộ thủ 足, chữ liên quan đến vận động chân. Chưa có nguồn học thuật chuyên sâu. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Chí", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 主", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊主", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "主", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "跓", "Unihan_Traditional (Chữ Phồn thể)": "跓", "Pinyin_Xie": "zhù", "Âm Hán Việt_Xie": "trú", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ chỉ hành động đứng yên một chỗ để chờ đợi hoặc quan sát. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('邿', '{"9000": "6998.0", "Chữ Trung Quốc": "邿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 8 | nét | 邿 | thi | tượng hình | tên nước cổ thời Xuân Thu, tỉnh Sơn Đông | 邿 thuộc bộ 阝(邑) — địa danh, nước chư hầu. Cấu trúc nội bộ không có phân tích hình thanh/hội ý rõ ràng trong Wiktionary; chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thi\": bộ 邑 (ấp — nước/đất) + âm \"thi\" — nước \"Thi\" nhỏ bé thời Xuân Thu ở Sơn Đông. | Gương Hán-Việt | \"thi\" — âm Hán-Việt, dùng trong địa danh/lịch sử; không phổ biến trong từ thông dụng | Mở khoá kiến thức | 邿 là địa danh lịch sử; bộ 阝(邑) kết nối nhóm chữ địa danh: 那, 都, 郡, 鄰.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | 邿 là tên một nước chư hầu nhỏ thời Xuân Thu, nằm ở tỉnh Sơn Đông ngày nay. Cũng là tên một ngọn núi và họ người. Thuộc bộ 邑 (ấp — địa danh). Không có dữ liệu glyphOrigin có cấu trúc từ Wiktionary ngoài nhãn {{Han etym}}. Chưa có nguồn học thuật chuyên sâu. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên đất)", "Hạng Tần Suất (Jun Da)": "6998.0", "Tần Suất % (Jun Da)": "99.9969680216", "GavinGrover_Once (Chiết tự trực tiếp)": "寺 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰寺阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "寺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "邿", "Unihan_Traditional (Chữ Phồn thể)": "邿", "Pinyin_Xie": "shī", "Âm Hán Việt_Xie": "thi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ riêng chỉ một nước nhỏ hoặc địa danh thời cổ đại ở Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('醿', '{"9000": "6999.0", "Chữ Trung Quốc": "醿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 24 | nét | 醿 | mị | tượng hình | loại rượu ngon (cổ) | 醿 thuộc bộ 酉 (dậu — rượu, men rượu). Cấu trúc nội bộ không có phân tích hình thanh/hội ý rõ ràng trong Wiktionary; chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mị\": bộ 酉 (dậu — rượu) — loại rượu \"mị\" hồn người uống vào mê say. | Gương Hán-Việt | \"mị\" — âm Hán-Việt ít dùng trong từ thông dụng hiện đại | Mở khoá kiến thức | 醿 là chữ hiếm; bộ 酉 kết nối nhóm chữ về rượu: 酒, 醉, 醒, 醇, 酴.", "Tự nguyên_Xie": "醿 thuộc bộ 酉 (dậu — rượu). Không có dữ liệu glyphOrigin có cấu trúc từ Wiktionary (chỉ có {{Han etym}} và {{rfdef|zh}}). Dựa vào bộ thủ, chữ liên quan đến rượu hoặc men rượu. Chưa có nguồn học thuật chuyên sâu. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鿿", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 縻", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉縻", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "縻", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "醿", "Unihan_Traditional (Chữ Phồn thể)": "醿", "Pinyin_Xie": "mí", "Âm Hán Việt_Xie": "mị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong văn học cổ để chỉ một loại rượu ngon hoặc nước uống lên men. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鈨', '{"9000": "7000.0", "Chữ Trung Quốc": "鈨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 12 | nét | 鈨 | viên | tượng hình | nguyên tố hóa học uranium (U) | 鈨 thuộc bộ 金 (kim — kim loại). Là chữ hiện đại dùng để phiên âm nguyên tố hóa học uranium. Không có phân tích hình thanh/hội ý cổ điển.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"viên\": bộ 金 (kim — kim loại) — \"viên\" kim loại nặng, chính là uranium trong bảng tuần hoàn. | Gương Hán-Việt | \"viên\" — âm phiên dịch, ít dùng trong từ Hán-Việt thông thường | Mở khoá kiến thức | 鈨 là ký hiệu hóa học; bộ 金 kết nối nhóm nguyên tố: 鐵 (sắt), 銅 (đồng), 鋼 (thép), 鈾 (uranium dạng khác).", "Tự nguyên_Xie": "鈨 là chữ tạo muộn, dùng để phiên âm tên nguyên tố uranium (U) trong tiếng Trung. Thuộc bộ 金 (kim — kim loại), phù hợp với tính chất kim loại của nguyên tố. Không có dữ liệu glyphOrigin từ Wiktionary. Chưa có nguồn học thuật chuyên sâu. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鈨", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 元", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金元", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "元", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鈨", "Unihan_Traditional (Chữ Phồn thể)": "鈨", "Pinyin_Xie": "yuan", "Âm Hán Việt_Xie": "viên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ để chỉ tên một loại kim loại trong hóa học cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('駵', '{"9000": "7001.0", "Chữ Trung Quốc": "駵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 17 | nét | 駵 | lưu | tượng hình | ngựa lông đỏ hung (cổ) | 駵 thuộc bộ 馬 (mã — ngựa). Cấu trúc nội bộ không có phân tích hình thanh/hội ý rõ ràng trong nguồn hiện có; không có glyphOrigin. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lưu\": bộ 馬 (mã — ngựa) — con ngựa \"lưu\" lại trong ký ức vì bờm đỏ rực như lửa. | Gương Hán-Việt | \"lưu\" — âm Hán-Việt ít dùng trong từ thông dụng hiện đại | Mở khoá kiến thức | 駵 là chữ cổ hiếm; bộ 馬 kết nối nhóm chữ về ngựa: 馬, 駿, 騎, 驅, 驟.", "Tự nguyên_Xie": "駵 thuộc bộ 馬 (mã — ngựa). Không có dữ liệu glyphOrigin từ Wiktionary. Nghĩa: ngựa có bờm lông màu đỏ hung. Là biến thể/chữ cổ liên quan đến màu sắc ngựa. Chưa có nguồn học thuật chuyên sâu. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "biến thể cũ của 騮", "Hạng Tần Suất (Jun Da)": "7001.0", "Tần Suất % (Jun Da)": "99.9969861091", "GavinGrover_Once (Chiết tự trực tiếp)": "馬 + 丣", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰馬丣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丣", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "駵", "Unihan_Traditional (Chữ Phồn thể)": "駵", "Pinyin_Xie": "liú", "Âm Hán Việt_Xie": "lưu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Dùng làm danh từ chỉ giống ngựa lông đỏ bờm đen hoặc làm tính từ chỉ màu sắc ngựa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('駸', '{"9000": "7002.0", "Chữ Trung Quốc": "駸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 17 | nét | 駸 | xăm | tượng hình | ngựa chạy nhanh, tiến gấp | 駸 thuộc bộ 馬 (mã — ngựa). Cấu trúc nội bộ không có phân tích hình thanh/hội ý rõ ràng trong Wiktionary; chưa có nguồn học thuật chuyên sâu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xăm\": bộ 馬 (mã — ngựa) — ngựa \"xăm\" xăm tiến gấp, không dừng lại được. | Gương Hán-Việt | \"xăm\" — âm Hán-Việt ít dùng trong từ thông dụng hiện đại | Mở khoá kiến thức | 駸 thường gặp trong 駸駸; bộ 馬 kết nối: 馬 (mã), 駿 (tuấn mã), 驟 (đột ngột/nhanh).", "Tự nguyên_Xie": "Tiểu triện | 駸 thuộc bộ 馬 (mã — ngựa). Wiktionary chỉ ghi {{Han etym}} không có compound structure. Dùng chủ yếu trong từ láy 駸駸 chỉ ngựa chạy nhanh, tiến gấp, thường dùng theo nghĩa bóng: thời gian trôi nhanh, tiến triển mạnh. Chưa có nguồn học thuật chuyên sâu. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Kiều", "Hạng Tần Suất (Jun Da)": "6392.0", "Tần Suất % (Jun Da)": "99.9915133545", "GavinGrover_Once (Chiết tự trực tiếp)": "馬 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰馬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "骎", "Unihan_Traditional (Chữ Phồn thể)": "駸", "Pinyin_Xie": "qīn", "Âm Hán Việt_Xie": "xăm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Phó từ | 副词 | Thường xuất hiện trong từ láy để miêu tả trạng thái chạy nhanh hoặc sự tiến triển thần tốc. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鰪', '{"9000": "7003.0", "Chữ Trung Quốc": "鰪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 21 | nét | 鰪 | nga | tượng hình | tên cá (cổ) | 鰪 thuộc bộ 魚 (ngư — cá). Cấu trúc nội bộ không có phân tích hình thanh/hội ý rõ ràng trong Wiktionary (chỉ có {{rfdef|zh}}); chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nga\": bộ 魚 (ngư — cá) — loài cá \"nga\" ngã trong sách cổ, nay ít ai nhắc đến. | Gương Hán-Việt | \"nga\" — âm Hán-Việt, ít dùng trong từ thông dụng hiện đại | Mở khoá kiến thức | 鰪 là chữ hiếm; bộ 魚 (ngư) kết nối nhóm chữ về cá: 鯉 (lý), 鮭 (hồi), 鮑 (bào), 鱾.", "Tự nguyên_Xie": "鰪 thuộc bộ 魚 (ngư — cá). Không có dữ liệu glyphOrigin có cấu trúc từ Wiktionary. Nghĩa chưa xác định rõ (rfdef). Dựa vào bộ thủ, chữ chỉ một loài cá. Chưa có nguồn học thuật chuyên sâu. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "kẹp tóc", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 盍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚盍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "盍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鰪", "Unihan_Traditional (Chữ Phồn thể)": "鰪", "Pinyin_Xie": "é", "Âm Hán Việt_Xie": "nga", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Được dùng làm danh từ trong văn bản cổ để chỉ một loài cá cụ thể. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鱾', '{"9000": "7004.0", "Chữ Trung Quốc": "鱾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 11 | nét | 鱾 | kỷ | tượng hình | cá kỷ — tên loài cá | 鱾 là dạng giản thể hoặc dị thể của 魢 (cùng chỉ một loài cá). Thuộc bộ 魚 (ngư — cá). Wiktionary ghi: 鱾 = Han simp của 魢, thay 魚 bằng 鱼.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kỷ\": bộ 魚 (ngư — cá) + âm 己 (kỷ) — loài cá nhỏ mang tên \"kỷ\", như tự giới thiệu mình. | Gương Hán-Việt | \"kỷ\" — âm Hán-Việt ít dùng trong từ thông dụng hiện đại | Mở khoá kiến thức | 鱾 là chữ hiếm; bộ 魚 kết nối: 鰪, 鰉 (cá kaluga), 鮭 (cá hồi).", "Tự nguyên_Xie": "Theo Wiktionary, 鱾 là dạng giản hóa của 魢 (thay bộ 魚 bằng 鱼). 魢 chỉ một loài cá biển nhỏ. Thuộc bộ 魚 (ngư — cá). Chưa có nguồn học thuật chuyên sâu về nguồn gốc glyph. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một loại cá", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 己", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼己", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "己", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鱾", "Unihan_Traditional (Chữ Phồn thể)": "鱾", "Pinyin_Xie": "jǐ", "Âm Hán Việt_Xie": "kỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này đóng vai trò làm danh từ để gọi tên một loài cá trong sinh học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('賨', '{"9000": "7006.0", "Chữ Trung Quốc": "賨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 15 | nét | 賨 | tông | tượng hình | cống vật bằng vải của các tộc người miền tây nam Trung Quốc | 賨 thuộc bộ 貝 (bối — vỏ sò, tiền của). Cấu trúc nội bộ không có phân tích hình thanh/hội ý rõ ràng trong Wiktionary; chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tông\": bộ 貝 (bối — tiền của) — cống phẩm \"tông\" tộc miền sơn cước nộp bằng vải thay tiền. | Gương Hán-Việt | \"tông\" — âm Hán-Việt ít dùng trong từ thông dụng hiện đại | Mở khoá kiến thức | 賨 là thuật ngữ lịch sử; bộ 貝 kết nối: 賦 (phú — thuế), 貢 (cống), 費 (phí), 賣 (mại).", "Tự nguyên_Xie": "賨 thuộc bộ 貝 (bối — tiền của, cống phú). Theo Wiktionary, nghĩa: loại cống vật bằng vải do các tộc người ở Tứ Xuyên và Vân Nam nộp dưới thời Hán. Không có dữ liệu glyphOrigin có cấu trúc. Chưa có nguồn học thuật chuyên sâu. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rợ Ba (phía Nam Trung Quốc)", "Hạng Tần Suất (Jun Da)": "7006.0", "Tần Suất % (Jun Da)": "99.9970041966", "GavinGrover_Once (Chiết tự trực tiếp)": "宀 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱宀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "賨", "Unihan_Traditional (Chữ Phồn thể)": "賨", "Pinyin_Xie": "cóng", "Âm Hán Việt_Xie": "tung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Được dùng làm danh từ chỉ sắc thuế bằng vải hoặc chỉ tộc người nộp thuế đó. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('艞', '{"9000": "7007.0", "Chữ Trung Quốc": "艞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 舟 | Số nét | 18 | nét | 艞 | diệu | tượng hình | thuyền lớn; cầu ngang lên thuyền (cổ) | 艞 thuộc bộ 舟 (chu — thuyền bè). Cấu trúc nội bộ không có phân tích hình thanh/hội ý rõ ràng trong Wiktionary; chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"diệu\": bộ 舟 (chu — thuyền) — chiếc thuyền \"diệu\" kỳ lớn lao, có cầu gang riêng để lên xuống. | Gương Hán-Việt | \"diệu\" — âm Hán-Việt ít dùng trong từ thông dụng hiện đại | Mở khoá kiến thức | 艞 là chữ cổ hiếm; bộ 舟 kết nối: 舟 (chu — thuyền), 船 (thuyền), 艇 (đình — thuyền nhỏ).", "Tự nguyên_Xie": "艞 thuộc bộ 舟 (chu — thuyền). Theo Wiktionary (cổ ngữ): nghĩa là thuyền lớn, hoặc tấm ván/cầu ngang dùng để lên xuống thuyền từ bờ sông. Không có dữ liệu glyphOrigin có cấu trúc. Chưa có nguồn học thuật chuyên sâu. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "艞", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "舟 + 筄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舟筄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "筄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舟", "Unihan_Simplified (Chữ Giản thể)": "艞", "Unihan_Traditional (Chữ Phồn thể)": "艞", "Pinyin_Xie": "yào", "Âm Hán Việt_Xie": "diệu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Đóng vai trò danh từ chỉ vật dụng làm cầu nối từ bờ lên thuyền. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鹟', '{"9000": "7008.0", "Chữ Trung Quốc": "鹟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 15 | nét | 翁 | ông | biểu âm | ông lão (cho âm wēng) | 鳥 | điểu | biểu nghĩa | chim | 鹟 là chữ hình thanh (ls=psc): 鳥 (điểu — chim) là phần biểu nghĩa; 翁 (ông) là phần biểu âm cho âm wēng. Chỉ loài chim bắt ruồi (flycatcher).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ông\": chim (鳥) + âm ông (翁) — con chim \"ông ông\" bay quanh bắt ruồi, gọi là chim ông (鹟). | Gương Hán-Việt | \"ông\" trong tiếng Việt thường chỉ người; ở đây là âm phiên dịch tên loài chim | Mở khoá kiến thức | 鹟 là tên chim chuyên ngành; bộ 鳥 kết nối: 鷹 (ưng — đại bàng), 鴿 (cáp — bồ câu), 鸚 (anh — vẹt).", "Tự nguyên_Xie": "Theo Wiktionary, 鹟 gồm 翁 (ông, biểu âm cho wēng) + 鳥 (điểu — chim, biểu nghĩa) theo cấu trúc hình thanh. Chỉ loài chim flycatcher (chim bắt ruồi). Dạng giản thể thay 鳥 bằng 鸟. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chim ông (tên của một loài chim, tên khoa học là muscicapa sibirica)", "Hạng Tần Suất (Jun Da)": "7008.0", "Tần Suất % (Jun Da)": "99.9970114316", "GavinGrover_Once (Chiết tự trực tiếp)": "翁 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰翁鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "翁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鹟", "Unihan_Traditional (Chữ Phồn thể)": "鶲", "Pinyin_Xie": "wēng", "Âm Hán Việt_Xie": "ông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong ngành điểu học để chỉ họ chim đớp ruồi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
